export interface MCQItem {
  id: string;
  section: string;
  unit: string;
  chapter: string;
  questionNumber: string;
  question: string;
  options: {
    A: string;
    B: string;
    C: string;
    D: string;
  };
  correctOption: "A" | "B" | "C" | "D";
  correctAnswer: string;
  questionType: "MCQ";
  explanation: {
    correct_reason: string;
    distractor_reasons: {
      A: string;
      B: string;
      C: string;
      D: string;
    };
  };
}

export const MCQ_BANK_3: MCQItem[] = [{"id":"P1_U3_MCQ_001","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_001","question":"A newly opened urban bakery surveys local commuters about breakfast preferences before designing its morning pastry menu. Which core role of marketing is the bakery performing?","options":{"A":"Identifying and anticipating customer needs profitably","B":"Maximizing factory production output regardless of demand","C":"Reducing corporate income tax liabilities through bookkeeping","D":"Recruiting and training kitchen staff for shift work"},"correctOption":"A","correctAnswer":"Identifying and anticipating customer needs profitably","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because marketing's primary role is to identify, anticipate, and satisfy customer requirements profitably.","distractor_reasons":{"A":"Option A is correct because marketing's primary role is to identify, anticipate, and satisfy customer requirements profitably.","B":"Incorrect because maximizing output without checking demand describes a product-oriented operations focus.","C":"Incorrect because tax calculation and accounting belong to the Finance function.","D":"Incorrect because staffing and training belong to the Human Resources function."}}},{"id":"P1_U3_MCQ_002","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_002","question":"A mid-sized coffee chain notices regular customers switching to a new rival offering loyalty rewards and oat-milk drinks. Which marketing objective best helps the chain maintain customer loyalty?","options":{"A":"Eliminating all market research to cut administrative overheads","B":"Building strong brand relationships and adapting products to evolving customer tastes","C":"Raising coffee prices sharply without improving product quality","D":"Reducing store opening hours during busy morning commuter periods"},"correctOption":"B","correctAnswer":"Building strong brand relationships and adapting products to evolving customer tastes","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because retaining loyal customers requires understanding changing preferences and strengthening perceived brand value.","distractor_reasons":{"A":"Incorrect because cutting research leaves the firm blind to shifting consumer tastes.","B":"Option B is correct because retaining loyal customers requires understanding changing preferences and strengthening perceived brand value.","C":"Incorrect because unsubstantiated price hikes drive price-sensitive buyers toward competitors.","D":"Incorrect because restricting availability inconveniences regular commuters."}}},{"id":"P1_U3_MCQ_003","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_003","question":"In a regional bottled-water market worth $40 million annually, PureSpring Ltd generates $6 million in sales revenue. What is PureSpring Ltd's market share?","options":{"A":"6.7%","B":"24.0%","C":"15.0%","D":"60.0%"},"correctOption":"C","correctAnswer":"15.0%","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Market Share (%) = (Business Sales / Total Market Sales) × 100 = ($6m / $40m) × 100 = 15.0%.","distractor_reasons":{"A":"Incorrect because 6.7% divides $40m by $6m instead of $6m by $40m.","B":"Incorrect because 24.0% multiplies 6 by 4 rather than calculating a percentage share.","C":"Option C is correct because Market Share (%) = (Business Sales / Total Market Sales) × 100 = ($6m / $40m) × 100 = 15.0%.","D":"Incorrect because 60.0% misplaces the decimal point during percentage conversion."}}},{"id":"P1_U3_MCQ_004","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_004","question":"An electric bicycle manufacturer sees total industry sales rise from $200 million to $250 million in one year, while its own sales stay at $20 million. How has the manufacturer's market position changed?","options":{"A":"Its market share increased from 8% to 10%","B":"Its sales revenue fell by 20% over the year","C":"Its market share remained unchanged at 10%","D":"Its market share fell from 10% to 8% despite stable sales revenue"},"correctOption":"D","correctAnswer":"Its market share fell from 10% to 8% despite stable sales revenue","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because its share dropped from ($20m / $200m) = 10% to ($20m / $250m) = 8% as competitors captured the market growth.","distractor_reasons":{"A":"Incorrect because 8% to 10% reverses the before-and-after market share figures.","B":"Incorrect because the firm's absolute sales revenue stayed constant at $20 million.","C":"Incorrect because constant sales in a growing total market reduces relative market share.","D":"Option D is correct because its share dropped from ($20m / $200m) = 10% to ($20m / $250m) = 8% as competitors captured the market growth."}}},{"id":"P1_U3_MCQ_005","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_005","question":"As average household incomes rise in a developing economy, a supermarket chain notices shoppers buying fewer basic canned foods and more organic fresh meals. Which factor explains this shift in consumer spending patterns?","options":{"A":"Higher disposable income increasing demand for higher-quality, premium convenience foods","B":"An ageing population reducing total demand for all grocery products","C":"Government bans on selling canned vegetables in retail stores","D":"A decrease in the number of supermarkets operating in the country"},"correctOption":"A","correctAnswer":"Higher disposable income increasing demand for higher-quality, premium convenience foods","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rising consumer incomes shift spending away from basic staples toward higher-value, healthier, and convenient options.","distractor_reasons":{"A":"Option A is correct because rising consumer incomes shift spending away from basic staples toward higher-value, healthier, and convenient options.","B":"Incorrect because the scenario specifically highlights rising household incomes rather than demographic ageing.","C":"Incorrect because no regulatory ban was mentioned.","D":"Incorrect because fewer stores would not explain a shift from canned to organic products."}}},{"id":"P1_U3_MCQ_006","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_006","question":"High Street Travel has seen its booking numbers fall as more customers use smartphone apps to compare and book holidays independently. Which action would most effectively help the agency respond to this change in the market?","options":{"A":"Raise prices to pay for more window displays","B":"Add an online booking service and personal advice an app cannot match","C":"Stop advertising and rely only on walk-in customers","D":"Reduce the number of destinations it offers"},"correctOption":"B","correctAnswer":"Add an online booking service and personal advice an app cannot match","questionType":"MCQ","explanation":{"correct_reason":"The market has changed because customers now use technology; adapting by offering online booking plus personalized service meets customer needs and helps the agency compete with apps.","distractor_reasons":{"A":"Raising prices for window displays does not address why customers are leaving and would likely drive more away.","B":"Adapting with online booking and personal service meets customer needs and helps the agency compete with apps.","C":"Stopping advertising lowers awareness and ignores the shift in customer behaviour toward online booking.","D":"Offering fewer destinations narrows the range and makes the agency less competitive."}}},{"id":"P1_U3_MCQ_007","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_007","question":"A local electronics retailer faces fierce price competition from global e-commerce giants selling identical televisions. Which response is most effective for the local retailer to survive?","options":{"A":"Ignore competitor prices and stop training shop-floor sales staff","B":"Reduce product warranties while raising delivery charges","C":"Differentiate through expert in-store advice, same-day installation, and personalized after-sales service","D":"Attempt to outspend global giants on nationwide television advertising"},"correctOption":"C","correctAnswer":"Differentiate through expert in-store advice, same-day installation, and personalized after-sales service","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because smaller retailers rarely win pure price wars against giants, so adding tailored service differentiation creates a competitive advantage.","distractor_reasons":{"A":"Incorrect because neglecting pricing and staff knowledge accelerates customer loss.","B":"Incorrect because cutting service value while raising fees drives shoppers online.","C":"Option C is correct because smaller retailers rarely win pure price wars against giants, so adding tailored service differentiation creates a competitive advantage.","D":"Incorrect because a local retailer lacks the budget to outspend multinational corporations on national TV."}}},{"id":"P1_U3_MCQ_008","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_008","question":"An artisan chocolatier produces handmade, allergen-free vegan truffles sold exclusively to health-conscious luxury buyers. Which market approach is this business using?","options":{"A":"Mass marketing","B":"Cost-leadership marketing","C":"Undifferentiated marketing","D":"Niche marketing"},"correctOption":"D","correctAnswer":"Niche marketing","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because niche marketing tailors specialized products to a small, well-defined segment with specific preferences.","distractor_reasons":{"A":"Incorrect because mass marketing targets the broadest possible audience with standardized goods.","B":"Incorrect because handmade luxury truffles focus on specialization rather than lowest-cost volume.","C":"Incorrect because undifferentiated marketing ignores segment differences.","D":"Option D is correct because niche marketing tailors specialized products to a small, well-defined segment with specific preferences."}}},{"id":"P1_U3_MCQ_009","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_009","question":"What is a major financial advantage for a small startup operating in a 'niche market' rather than a 'mass market'?","options":{"A":"Less direct competition from large multinationals, allowing higher profit margins per unit sold","B":"Huge economies of scale from producing millions of identical units daily","C":"Guaranteed stable demand even if consumer tastes change suddenly","D":"Zero need to understand specific customer preferences"},"correctOption":"A","correctAnswer":"Less direct competition from large multinationals, allowing higher profit margins per unit sold","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because large corporations often overlook small niches, enabling specialists to charge premium prices for closely matched products.","distractor_reasons":{"A":"Option A is correct because large corporations often overlook small niches, enabling specialists to charge premium prices for closely matched products.","B":"Incorrect because large-scale economies of scale are an advantage of mass marketing.","C":"Incorrect because niche firms face high risk if demand in their single narrow segment shifts.","D":"Incorrect because niche success depends on deep knowledge of specialized buyer needs."}}},{"id":"P1_U3_MCQ_010","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_010","question":"A small firm specializing solely in left-handed mechanical watches experiences a sharp drop in profits when a rival enters the segment. What key risk of niche marketing does this illustrate?","options":{"A":"Excessive spending on nationwide mass-media advertising","B":"Small total market size limits growth, leaving profits vulnerable if a competitor takes market share","C":"Inability to charge prices above basic manufacturing cost","D":"Over-reliance on standardized mass-production assembly lines"},"correctOption":"B","correctAnswer":"Small total market size limits growth, leaving profits vulnerable if a competitor takes market share","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because niche markets have a limited pool of buyers, so even one new competitor can severely erode sales volume.","distractor_reasons":{"A":"Incorrect because niche firms use targeted promotion rather than expensive mass-media campaigns.","B":"Option B is correct because niche markets have a limited pool of buyers, so even one new competitor can severely erode sales volume.","C":"Incorrect because niche products usually command premium margins rather than bare-cost pricing.","D":"Incorrect because niche goods are typically produced in small batches or job production."}}},{"id":"P1_U3_MCQ_011","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_011","question":"A global soft-drinks company sells its flagship cola in identical cans across millions of supermarkets worldwide using standardized television campaigns. Which strategy does this represent?","options":{"A":"Niche marketing","B":"Bespoke job marketing","C":"Mass marketing","D":"Geographic micro-targeting"},"correctOption":"C","correctAnswer":"Mass marketing","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because mass marketing appeals to the entire market with one standardized product and unified promotional message.","distractor_reasons":{"A":"Incorrect because niche marketing targets a narrow, specialized consumer group.","B":"Incorrect because bespoke marketing customizes items for individual buyers.","C":"Option C is correct because mass marketing appeals to the entire market with one standardized product and unified promotional message.","D":"Incorrect because selling identical cans globally ignores narrow local variations."}}},{"id":"P1_U3_MCQ_012","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_012","question":"Why does a 'mass marketing' strategy allow a household detergent manufacturer to charge lower retail prices than a niche eco-detergent brand?","options":{"A":"Mass-market firms never pay for market research or distribution","B":"Mass-market firms are exempt from consumer protection laws","C":"Niche brands are legally forced to charge higher prices by regulators","D":"High sales volumes generate purchasing and technical economies of scale, lowering average unit production costs"},"correctOption":"D","correctAnswer":"High sales volumes generate purchasing and technical economies of scale, lowering average unit production costs","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because large-scale standardized production spreads fixed overheads and secures bulk ingredient discounts, reducing unit costs.","distractor_reasons":{"A":"Incorrect because mass-market brands invest heavily in research and wide distribution.","B":"Incorrect because all firms must obey consumer protection laws.","C":"Incorrect because niche pricing reflects higher unit costs and value positioning, not government mandates.","D":"Option D is correct because large-scale standardized production spreads fixed overheads and secures bulk ingredient discounts, reducing unit costs."}}},{"id":"P1_U3_MCQ_013","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_013","question":"What is a major disadvantage for a business competing in a 'mass market'?","options":{"A":"Products cannot be distributed through national supermarket chains","B":"Total potential customer demand is too small to justify automated machinery","C":"Intense price and promotional competition from large rivals can squeeze profit margins","D":"Brand awareness is impossible to build through mass media"},"correctOption":"C","correctAnswer":"Intense price and promotional competition from large rivals can squeeze profit margins","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because mass markets attract powerful competitors offering similar products, driving heavy advertising outlays and price pressure.","distractor_reasons":{"A":"Incorrect because mass-market goods rely heavily on national supermarket distribution.","B":"Incorrect because huge demand in mass markets directly supports automated flow production.","C":"Option C is correct because mass markets attract powerful competitors offering similar products, driving heavy advertising outlays and price pressure.","D":"Incorrect because mass media is ideal for reaching mass-market consumers."}}},{"id":"P1_U3_MCQ_014","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_014","question":"A clothing retailer divides its customer base into distinct groups—such as teenagers, working professionals, and retirees—and designs separate ranges for each. What is this practice called?","options":{"A":"Product orientation","B":"Market segmentation","C":"Price skimming","D":"Vertical integration"},"correctOption":"B","correctAnswer":"Market segmentation","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because market segmentation subdivides a heterogeneous market into smaller groups with shared characteristics and needs.","distractor_reasons":{"A":"Incorrect because product orientation focuses on engineering features without tailoring to customer groups.","B":"Option B is correct because market segmentation subdivides a heterogeneous market into smaller groups with shared characteristics and needs.","C":"Incorrect because price skimming is a launch pricing strategy.","D":"Incorrect because vertical integration involves merging with suppliers or distributors."}}},{"id":"P1_U3_MCQ_015","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_015","question":"A financial services firm promotes student bank accounts to 18-to-21-year-olds and retirement annuities to customers aged over 60. Which basis of market segmentation is it using?","options":{"A":"Geographic segmentation","B":"Climatic segmentation","C":"Demographic segmentation (age)","D":"Distribution-channel segmentation"},"correctOption":"C","correctAnswer":"Demographic segmentation (age)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because demographic segmentation divides consumers using population variables such as age, gender, family size, or occupation.","distractor_reasons":{"A":"Incorrect because geographic segmentation groups buyers by region, city, or country.","B":"Incorrect because climate is a geographic factor rather than age.","C":"Option C is correct because demographic segmentation divides consumers using population variables such as age, gender, family size, or occupation.","D":"Incorrect because distribution channels relate to Place in the marketing mix."}}},{"id":"P1_U3_MCQ_016","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_016","question":"An international fast-food chain sells spicy rice bowls in Southeast Asia, vegetarian paneer wraps in India, and beef burgers in North America. Which segmentation method is guiding its menus?","options":{"A":"Income segmentation","B":"Age segmentation","C":"Gender segmentation","D":"Geographic and cultural segmentation"},"correctOption":"D","correctAnswer":"Geographic and cultural segmentation","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because adapting menus by country and regional dietary traditions reflects geographic and cultural segmentation.","distractor_reasons":{"A":"Incorrect because menu items are tailored to regional tastes rather than wealth brackets.","B":"Incorrect because meals target all age groups within each region.","C":"Incorrect because menus are not split by male or female buyers.","D":"Option D is correct because adapting menus by country and regional dietary traditions reflects geographic and cultural segmentation."}}},{"id":"P1_U3_MCQ_017","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_017","question":"An airline offers ultra-low-fare basic economy tickets alongside $6,000 flat-bed first-class suites on the same long-haul flight. Which segmentation variable is the airline primarily targeting?","options":{"A":"Marital status","B":"Gender","C":"Residential postcode","D":"Income / socio-economic group"},"correctOption":"D","correctAnswer":"Income / socio-economic group","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because offering budget seats and luxury suites segments travellers by disposable income and willingness to pay.","distractor_reasons":{"A":"Incorrect because cabin selection does not depend on marital status.","B":"Incorrect because cabin classes are open to passengers of any gender.","C":"Incorrect because seating tiers are based on fare budget rather than home address.","D":"Option D is correct because offering budget seats and luxury suites segments travellers by disposable income and willingness to pay."}}},{"id":"P1_U3_MCQ_018","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_018","question":"A smartwatch brand markets a rugged GPS model to outdoor trail runners and a sleek leather-strap model to fashion-conscious city professionals. Which segmentation approach is being applied?","options":{"A":"Geographic segmentation","B":"Psychographic / lifestyle segmentation","C":"Age-only segmentation","D":"Mass undifferentiated segmentation"},"correctOption":"B","correctAnswer":"Psychographic / lifestyle segmentation","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because lifestyle segmentation groups consumers according to their hobbies, interests, values, and daily activities.","distractor_reasons":{"A":"Incorrect because buyers are grouped by athletic vs fashion interests rather than country or climate.","B":"Option B is correct because lifestyle segmentation groups consumers according to their hobbies, interests, values, and daily activities.","C":"Incorrect because trail runners and city professionals can belong to the same age bracket.","D":"Incorrect because the firm offers two distinct targeted designs rather than one uniform watch."}}},{"id":"P1_U3_MCQ_019","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_019","question":"How does effective 'market segmentation' help a medium-sized sportswear firm use its promotional budget more efficiently?","options":{"A":"It eliminates the need to conduct any primary or secondary market research","B":"It allows the firm to sell identical shoes at the exact same price in every country","C":"It directs adverts specifically to media channels read or watched by target buyer groups, avoiding wasted spending on uninterested audiences","D":"It legally prevents rival sportswear companies from entering the market"},"correctOption":"C","correctAnswer":"It directs adverts specifically to media channels read or watched by target buyer groups, avoiding wasted spending on uninterested audiences","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because targeting defined segments focuses advertising expenditure on high-potential buyers rather than broadcasting broadly.","distractor_reasons":{"A":"Incorrect because identifying segments actually relies on solid market research.","B":"Incorrect because segmentation encourages tailoring products and prices to different groups.","C":"Option C is correct because targeting defined segments focuses advertising expenditure on high-potential buyers rather than broadcasting broadly.","D":"Incorrect because segmentation does not create legal barriers against competitors."}}},{"id":"P1_U3_MCQ_020","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_020","question":"What is a potential disadvantage for a car manufacturer that creates too many narrow sub-models across dozens of tiny market segments?","options":{"A":"Higher design, tooling, and marketing costs per model, reducing economies of scale","B":"Customers complain that there is zero variety in vehicle features","C":"The manufacturer becomes completely immune to changes in fuel prices","D":"Retail dealerships no longer need trained salespeople"},"correctOption":"A","correctAnswer":"Higher design, tooling, and marketing costs per model, reducing economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because over-segmenting fragments production runs and requires separate promotional campaigns, driving up unit costs.","distractor_reasons":{"A":"Option A is correct because over-segmenting fragments production runs and requires separate promotional campaigns, driving up unit costs.","B":"Incorrect because offering dozens of sub-models provides extensive variety.","C":"Incorrect because macroeconomic factors like fuel prices still affect vehicle demand.","D":"Incorrect because multiple models actually require knowledgeable sales staff."}}},{"id":"P1_U3_MCQ_021","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_021","question":"A toy manufacturer notices birth rates falling steadily in its home country while the proportion of citizens aged over 65 is rising rapidly. Which strategic marketing response is most appropriate?","options":{"A":"Double factory capacity for infant baby rattles in the domestic market","B":"Expand exports to countries with growing young populations or diversify into adult board games and brain-training puzzles","C":"Eliminate all digital marketing and raise prices on children's toys by 50%","D":"Stop tracking demographic statistics because population trends never affect sales"},"correctOption":"B","correctAnswer":"Expand exports to countries with growing young populations or diversify into adult board games and brain-training puzzles","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because demographic shifts shrink the domestic child segment, requiring either new geographic markets or new products for older consumers.","distractor_reasons":{"A":"Incorrect because expanding baby-toy output in a shrinking birth-rate market causes unsold inventory.","B":"Option B is correct because demographic shifts shrink the domestic child segment, requiring either new geographic markets or new products for older consumers.","C":"Incorrect because steep price rises in a declining market accelerate revenue loss.","D":"Incorrect because demographic trends directly govern segment size."}}},{"id":"P1_U3_MCQ_022","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_022","question":"Which business is most likely to succeed using a 'mass marketing' strategy rather than a 'niche marketing' strategy?","options":{"A":"A bespoke wedding-dress tailor operating from a single boutique studio","B":"A manufacturer of specialized surgical instruments for brain surgeons","C":"A large consumer-goods corporation producing everyday toothpaste and bath soap","D":"An artisan restorer of antique 18th-century grandfather clocks"},"correctOption":"C","correctAnswer":"A large consumer-goods corporation producing everyday toothpaste and bath soap","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because toothpaste and soap are universal everyday necessities suited to high-volume standardized production and broad distribution.","distractor_reasons":{"A":"Incorrect because bespoke bridal wear is customized for individual buyers.","B":"Incorrect because specialized surgical tools serve a tiny, expert niche.","C":"Option C is correct because toothpaste and soap are universal everyday necessities suited to high-volume standardized production and broad distribution.","D":"Incorrect because antique clock restoration serves a very narrow collector niche."}}},{"id":"P1_U3_MCQ_023","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_023","question":"Why might a once-profitable 'niche market' suddenly attract intense competition from large corporations?","options":{"A":"Niche markets always have lower unit production costs than mass markets","B":"Governments force large corporations to enter every small niche market by law","C":"Rapid sales growth in the niche signals high profit potential, prompting large firms to launch competing lines","D":"Consumers in niche markets prefer unbranded generic goods"},"correctOption":"C","correctAnswer":"Rapid sales growth in the niche signals high profit potential, prompting large firms to launch competing lines","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because if a niche grows substantially (such as plant-based milks), big corporations enter to capture the expanding revenue.","distractor_reasons":{"A":"Incorrect because mass markets achieve lower unit costs through economies of scale.","B":"Incorrect because corporations enter markets voluntarily for profit, not by government order.","C":"Option C is correct because if a niche grows substantially (such as plant-based milks), big corporations enter to capture the expanding revenue.","D":"Incorrect because niche buyers often value strong specialist brands."}}},{"id":"P1_U3_MCQ_024","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_024","question":"A supermarket chain uses loyalty-card data to send coupons for baby diapers to new parents and pet-food discounts to dog owners. How does this benefit the supermarket?","options":{"A":"It eliminates the need to stock products for customers without children or pets","B":"Targeted promotions increase redemption rates and repeat store visits by matching offers to specific household segments","C":"It allows the supermarket to charge higher prices than competitors on every item","D":"It replaces the need for physical store locations or delivery vans"},"correctOption":"B","correctAnswer":"Targeted promotions increase redemption rates and repeat store visits by matching offers to specific household segments","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because personalized segmentation ensures promotions are relevant to each household, boosting customer retention and basket size.","distractor_reasons":{"A":"Incorrect because supermarkets still serve all household types.","B":"Option B is correct because personalized segmentation ensures promotions are relevant to each household, boosting customer retention and basket size.","C":"Incorrect because coupons offer targeted discounts rather than universal price hikes.","D":"Incorrect because retail stores or delivery networks remain essential."}}},{"id":"P1_U3_MCQ_025","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_025","question":"When is 'gender segmentation' becoming less effective for modern personal-care and clothing brands?","options":{"A":"When clothing sizes become identical across all adults worldwide","B":"When governments ban men and women from shopping in the same retail stores","C":"When companies stop using demographic data in all market research","D":"When younger consumers increasingly prefer gender-neutral styles and choose products based on lifestyle or skin type instead"},"correctOption":"D","correctAnswer":"When younger consumers increasingly prefer gender-neutral styles and choose products based on lifestyle or skin type instead","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because shifting social attitudes and unisex fashion trends mean lifestyle and functional needs often predict buying better than gender.","distractor_reasons":{"A":"Incorrect because sizing differences persist regardless of gender-neutral branding.","B":"Incorrect because no such retail segregation laws exist.","C":"Incorrect because firms still collect demographic data while broadening segmentation criteria.","D":"Option D is correct because shifting social attitudes and unisex fashion trends mean lifestyle and functional needs often predict buying better than gender."}}},{"id":"P1_U3_MCQ_026","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_026","question":"An engineering firm invents a complex new kitchen gadget based purely on its engineers' technical interests, without checking if consumers want it or what price they would pay. Which business approach does this illustrate?","options":{"A":"Market-oriented approach","B":"Product-oriented approach","C":"Niche-segmented approach","D":"Customer-led approach"},"correctOption":"B","correctAnswer":"Product-oriented approach","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a product-oriented business focuses first on developing technical features and then tries to persuade customers to buy.","distractor_reasons":{"A":"Incorrect because a market-oriented firm researches customer needs before designing the product.","B":"Option B is correct because a product-oriented business focuses first on developing technical features and then tries to persuade customers to buy.","C":"Incorrect because niche segmentation starts with identifying a specific customer group's needs.","D":"Incorrect because customer-led firms prioritize buyer preferences from the outset."}}},{"id":"P1_U3_MCQ_027","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_027","question":"Why does a 'market-oriented' business generally face lower risk of new-product failure than a 'product-oriented' business?","options":{"A":"It conducts market research first to ensure products match verified consumer needs and price expectations","B":"It never spends money on research and development or product testing","C":"It is legally guaranteed a monopoly patent on every product launched","D":"It sells products exclusively to government departments"},"correctOption":"A","correctAnswer":"It conducts market research first to ensure products match verified consumer needs and price expectations","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because basing design, pricing, and promotion on customer evidence reduces the chance of launching unwanted goods.","distractor_reasons":{"A":"Option A is correct because basing design, pricing, and promotion on customer evidence reduces the chance of launching unwanted goods.","B":"Incorrect because market-oriented firms invest heavily in research and prototype testing.","C":"Incorrect because market orientation provides commercial insight, not automatic patent monopolies.","D":"Incorrect because market-oriented firms operate across consumer and business markets."}}},{"id":"P1_U3_MCQ_028","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_028","question":"Which situation is an example of 'primary (field) market research'?","options":{"A":"Downloading national population census tables from a government statistics website","B":"Reading a competitor's published annual report and price list","C":"Distributing an original online questionnaire to 500 potential buyers about a proposed beverage flavour","D":"Purchasing a published industry trend report from a market research agency"},"correctOption":"C","correctAnswer":"Distributing an original online questionnaire to 500 potential buyers about a proposed beverage flavour","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because primary research collects brand-new, first-hand data directly from respondents for the business's specific purpose.","distractor_reasons":{"A":"Incorrect because census data was already collected by government (secondary research).","B":"Incorrect because existing competitor publications are external secondary data.","C":"Option C is correct because primary research collects brand-new, first-hand data directly from respondents for the business's specific purpose.","D":"Incorrect because pre-published commercial reports are secondary research."}}},{"id":"P1_U3_MCQ_029","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_029","question":"Why do market researchers usually gather 'secondary (desk) research' before commissioning expensive 'primary research'?","options":{"A":"Secondary research is always 100% tailored to the firm's brand-new product prototype","B":"Secondary research is faster and cheaper to obtain, helping clarify background market size and narrow down what primary questions are needed","C":"Secondary research is collected exclusively through face-to-face street interviews","D":"Secondary research is never accessible to rival businesses"},"correctOption":"B","correctAnswer":"Secondary research is faster and cheaper to obtain, helping clarify background market size and narrow down what primary questions are needed","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because reviewing existing internal records and published data saves time and money before designing targeted field surveys.","distractor_reasons":{"A":"Incorrect because secondary data was collected for other purposes and cannot test a brand-new prototype directly.","B":"Option B is correct because reviewing existing internal records and published data saves time and money before designing targeted field surveys.","C":"Incorrect because face-to-face interviews are a primary research method.","D":"Incorrect because external secondary sources (like newspapers or government stats) are publicly available to rivals."}}},{"id":"P1_U3_MCQ_030","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_030","question":"Which of the following is an 'internal source of secondary data' for a retail supermarket chain?","options":{"A":"A national newspaper article on food inflation","B":"Government retail trade census statistics","C":"Past sales records and loyalty-card purchase histories stored in the supermarket's own database","D":"A street survey conducted by the supermarket's marketing interns"},"correctOption":"C","correctAnswer":"Past sales records and loyalty-card purchase histories stored in the supermarket's own database","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because past sales and customer records already exist inside the organisation and can be re-analyzed cheaply.","distractor_reasons":{"A":"Incorrect because newspapers are an external secondary source.","B":"Incorrect because government statistics are an external secondary source.","C":"Option C is correct because past sales and customer records already exist inside the organisation and can be re-analyzed cheaply.","D":"Incorrect because a new street survey is primary research."}}},{"id":"P1_U3_MCQ_031","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_031","question":"What is a major limitation of relying solely on 'secondary market research' when launching an innovative product?","options":{"A":"Secondary data takes years to collect from individual households","B":"Secondary data may be outdated, collected for a different purpose, and publicly available to competitors","C":"Secondary data is always more expensive than hiring a team of field interviewers","D":"Secondary data provides qualitative emotional insights from focus groups"},"correctOption":"B","correctAnswer":"Secondary data may be outdated, collected for a different purpose, and publicly available to competitors","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because existing publications may not reflect current trends or specific product features, and offer no exclusive information advantage.","distractor_reasons":{"A":"Incorrect because secondary data is already compiled and quick to access.","B":"Option B is correct because existing publications may not reflect current trends or specific product features, and offer no exclusive information advantage.","C":"Incorrect because secondary research is typically far cheaper than primary research.","D":"Incorrect because focus groups are a primary qualitative method."}}},{"id":"P1_U3_MCQ_032","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_032","question":"A toy company invites 10 children and their parents to play with prototype board games in a room while a moderator observes and discusses their reactions. Which primary research method is this?","options":{"A":"Postal questionnaire","B":"Focus group","C":"Desk research","D":"Census enumeration"},"correctOption":"B","correctAnswer":"Focus group","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a focus group brings together a small group of target consumers for guided discussion and observation of attitudes and reactions.","distractor_reasons":{"A":"Incorrect because a postal questionnaire collects written answers remotely without group interaction.","B":"Option B is correct because a focus group brings together a small group of target consumers for guided discussion and observation of attitudes and reactions.","C":"Incorrect because desk research analyzes existing secondary sources.","D":"Incorrect because a census surveys an entire population."}}},{"id":"P1_U3_MCQ_033","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_033","question":"What is a key disadvantage of using 'focus groups' to gather qualitative market research?","options":{"A":"Participants cannot explain the reasons behind their opinions","B":"Focus groups take place entirely via automated telephone dialers","C":"Small sample sizes may not represent the whole population, and one dominant speaker can bias other participants' views","D":"Focus groups produce only raw numerical percentages without any verbal detail"},"correctOption":"C","correctAnswer":"Small sample sizes may not represent the whole population, and one dominant speaker can bias other participants' views","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because group dynamics ('groupthink' or dominant voices) and small participant numbers limit statistical generalizability.","distractor_reasons":{"A":"Incorrect because exploring deeper reasons ('why') is the main strength of focus groups.","B":"Incorrect because focus groups are moderated group discussions, in person or via video.","C":"Option C is correct because group dynamics ('groupthink' or dominant voices) and small participant numbers limit statistical generalizability.","D":"Incorrect because focus groups generate rich qualitative insights rather than large-scale statistics."}}},{"id":"P1_U3_MCQ_034","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_034","question":"A soft-drinks manufacturer launches a new mango-ginger soda in three mid-sized cities for two months to measure actual repeat purchases before rolling it out nationwide. Which research method is being used?","options":{"A":"Telephone polling","B":"Secondary desk research","C":"Test marketing","D":"Quota street interviewing"},"correctOption":"C","correctAnswer":"Test marketing","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because test marketing trials a new product in a limited geographical area under real market conditions to gauge demand and spot flaws before national launch.","distractor_reasons":{"A":"Incorrect because telephone polling asks hypothetical questions rather than tracking real store sales.","B":"Incorrect because test marketing generates new real-world sales data.","C":"Option C is correct because test marketing trials a new product in a limited geographical area under real market conditions to gauge demand and spot flaws before national launch.","D":"Incorrect because street interviews gather stated opinions rather than actual regional sales performance."}}},{"id":"P1_U3_MCQ_035","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_035","question":"What is a major risk for a consumer-electronics firm that conducts 'test marketing' in a limited region before a national launch?","options":{"A":"Rival firms can observe the test product, analyze customer reactions, and rush out a competing copy before the national rollout","B":"Test marketing provides zero information about real consumer purchasing behaviour","C":"Test marketing is always completely free of production or distribution costs","D":"Customers in test cities are legally forbidden from buying the product twice"},"correctOption":"A","correctAnswer":"Rival firms can observe the test product, analyze customer reactions, and rush out a competing copy before the national rollout","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because revealing a new product early in test cities alerts competitors and gives them time to imitate or disrupt the national launch.","distractor_reasons":{"A":"Option A is correct because revealing a new product early in test cities alerts competitors and gives them time to imitate or disrupt the national launch.","B":"Incorrect because measuring real purchase behaviour is test marketing's core advantage.","C":"Incorrect because producing and distributing a regional batch still incurs significant cost.","D":"Incorrect because tracking repeat purchases is central to test marketing."}}},{"id":"P1_U3_MCQ_036","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_036","question":"A supermarket researcher stands quietly near the cereal aisle recording which shelf height shoppers look at first and how long they examine nutrition labels. Which primary research method is this?","options":{"A":"Observation","B":"Postal survey","C":"Focus group","D":"Secondary trade report"},"correctOption":"A","correctAnswer":"Observation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because observation records actual consumer behaviour without asking questions, avoiding discrepancies between what people say and what they do.","distractor_reasons":{"A":"Option A is correct because observation records actual consumer behaviour without asking questions, avoiding discrepancies between what people say and what they do.","B":"Incorrect because postal surveys rely on self-reported written answers.","C":"Incorrect because focus groups involve moderated group conversation.","D":"Incorrect because watching live shoppers generates primary data."}}},{"id":"P1_U3_MCQ_037","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_037","question":"What is a key limitation of 'observation' as a primary market research method?","options":{"A":"It cannot be used inside physical retail stores or websites","B":"It relies on shoppers exaggerating their answers to please an interviewer","C":"It records what shoppers actually do, but cannot explain the underlying reasons why they behaved that way","D":"It requires sending printed forms to thousands of home addresses"},"correctOption":"C","correctAnswer":"It records what shoppers actually do, but cannot explain the underlying reasons why they behaved that way","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because seeing a customer put a product back on the shelf shows the action, but not whether the barrier was price, packaging, or ingredients.","distractor_reasons":{"A":"Incorrect because both store cameras/watchers and website click-tracking are forms of observation.","B":"Incorrect because avoiding interviewer-pleasing bias is actually an advantage of unobtrusive observation.","C":"Option C is correct because seeing a customer put a product back on the shelf shows the action, but not whether the barrier was price, packaging, or ingredients.","D":"Incorrect because mailing forms describes postal questionnaires."}}},{"id":"P1_U3_MCQ_038","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_038","question":"Why have 'online questionnaires' largely replaced traditional 'postal questionnaires' for many consumer brands?","options":{"A":"Online surveys guarantee a 100% response rate from every internet user","B":"Online surveys are much cheaper to distribute, gather responses rapidly, and automatically tabulate quantitative data","C":"Online surveys reach elderly consumers without internet access more easily than postal mail","D":"Online surveys prevent respondents from ever skipping questions"},"correctOption":"B","correctAnswer":"Online surveys are much cheaper to distribute, gather responses rapidly, and automatically tabulate quantitative data","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because digital survey tools eliminate printing and postage expenses while automating statistical chart generation.","distractor_reasons":{"A":"Incorrect because online surveys still experience non-response bias.","B":"Option B is correct because digital survey tools eliminate printing and postage expenses while automating statistical chart generation.","C":"Incorrect because digitally excluded groups are actually missed by online-only surveys.","D":"Incorrect because respondents can still abandon online forms mid-way."}}},{"id":"P1_U3_MCQ_039","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_039","question":"How does 'random sampling' differ from 'quota sampling' when selecting survey respondents?","options":{"A":"Random sampling gives every member of the target population an equal chance of selection, whereas quota sampling selects set numbers matching specific population characteristics (e.g., age or gender)","B":"Random sampling interviews only people passing a busy shopping mall, whereas quota sampling uses computer number generators","C":"Random sampling is used only for secondary data, whereas quota sampling is used only for primary data","D":"Random sampling is faster and cheaper than quota sampling when no population list exists"},"correctOption":"A","correctAnswer":"Random sampling gives every member of the target population an equal chance of selection, whereas quota sampling selects set numbers matching specific population characteristics (e.g., age or gender)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because true random sampling relies on chance across a sampling frame, while quota sampling mirrors key demographic proportions.","distractor_reasons":{"A":"Option A is correct because true random sampling relies on chance across a sampling frame, while quota sampling mirrors key demographic proportions.","B":"Incorrect because interviewing passers-by at will is convenience/quota selection, whereas computer generators support random sampling.","C":"Incorrect because both are sampling methods for primary research.","D":"Incorrect because quota sampling is generally quicker and cheaper when a complete population list is unavailable."}}},{"id":"P1_U3_MCQ_040","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_040","question":"A fitness club's membership is 60% female and 40% male. If the club uses 'quota sampling' to survey 150 members about new gym classes, how many female and male members should be interviewed?","options":{"A":"75 females and 75 males","B":"60 females and 40 males","C":"90 females and 60 males","D":"100 females and 50 males"},"correctOption":"C","correctAnswer":"90 females and 60 males","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because 60% of 150 = 90 females and 40% of 150 = 60 males, preserving the population's gender ratio.","distractor_reasons":{"A":"Incorrect because 75/75 splits the sample 50/50 rather than matching the 60/40 membership ratio.","B":"Incorrect because 60 + 40 totals only 100 respondents instead of 150.","C":"Option C is correct because 60% of 150 = 90 females and 40% of 150 = 60 males, preserving the population's gender ratio.","D":"Incorrect because 100/50 applies a 66.7%/33.3% split instead of 60%/40%."}}},{"id":"P1_U3_MCQ_041","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_041","question":"What is a potential source of bias when interviewers use 'quota sampling' on a high street?","options":{"A":"Interviewers may consciously choose friendly-looking passers-by who fit the age/gender quota rather than selecting objectively","B":"The sample will completely ignore the age and gender proportions of the target market","C":"Quota sampling requires obtaining a complete list of every citizen's name and address first","D":"Quota sampling cannot be used for face-to-face interviews"},"correctOption":"A","correctAnswer":"Interviewers may consciously choose friendly-looking passers-by who fit the age/gender quota rather than selecting objectively","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because quota sampling is non-random, so interviewer selection judgment can introduce subtle bias within each quota category.","distractor_reasons":{"A":"Option A is correct because quota sampling is non-random, so interviewer selection judgment can introduce subtle bias within each quota category.","B":"Incorrect because matching target demographic proportions is the exact purpose of quota sampling.","C":"Incorrect because needing a full sampling frame is a requirement of random sampling, not quota sampling.","D":"Incorrect because quota sampling is very commonly used in face-to-face street surveys."}}},{"id":"P1_U3_MCQ_042","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_042","question":"A luxury golf-club manufacturer conducts a street survey outside a university campus at 10:00 AM on a Tuesday to forecast demand for $2,500 golf clubs. Why will the resulting data likely be inaccurate?","options":{"A":"Sampling bias: the location and time over-represent full-time students rather than high-income golf buyers","B":"Primary research can never collect quantitative opinions on price","C":"University students always refuse to answer street questionnaires","D":"Market research is only accurate if 100% of the national population is interviewed"},"correctOption":"A","correctAnswer":"Sampling bias: the location and time over-represent full-time students rather than high-income golf buyers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because surveying outside a university captures a non-representative sample whose income and interests differ from luxury golf consumers.","distractor_reasons":{"A":"Option A is correct because surveying outside a university captures a non-representative sample whose income and interests differ from luxury golf consumers.","B":"Incorrect because surveys routinely test price willingness.","C":"Incorrect because even willing student respondents do not represent the target luxury segment.","D":"Incorrect because properly selected samples yield reliable results without surveying everyone."}}},{"id":"P1_U3_MCQ_043","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_043","question":"A survey asks respondents: 'Don't you agree that our eco-friendly bamboo toothbrush is far superior to wasteful plastic brushes?' Why does this question reduce data reliability?","options":{"A":"It is a leading (biased) question whose loaded wording pushes respondents toward a positive answer","B":"It is an open-ended question that takes two hours to answer","C":"It uses secondary census statistics instead of primary opinions","D":"It targets too large a sample size"},"correctOption":"A","correctAnswer":"It is a leading (biased) question whose loaded wording pushes respondents toward a positive answer","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because phrasing like 'Don't you agree' and 'wasteful' nudges respondents to agree rather than giving honest preferences.","distractor_reasons":{"A":"Option A is correct because phrasing like 'Don't you agree' and 'wasteful' nudges respondents to agree rather than giving honest preferences.","B":"Incorrect because it is a closed yes/no leading question.","C":"Incorrect because this is a poorly worded primary survey question.","D":"Incorrect because larger sample sizes generally improve rather than reduce accuracy."}}},{"id":"P1_U3_MCQ_044","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_044","question":"What is the main difference between 'quantitative' and 'qualitative' market research data?","options":{"A":"Quantitative data comes only from secondary sources, whereas qualitative data comes only from primary sources","B":"Quantitative data measures numerical quantities (such as '72% prefer blue'), whereas qualitative data explores opinions, attitudes, and reasons behind behaviour","C":"Quantitative data is collected only from focus groups, whereas qualitative data comes only from barcode scanners","D":"Quantitative data is always biased, whereas qualitative data is always 100% objective"},"correctOption":"B","correctAnswer":"Quantitative data measures numerical quantities (such as '72% prefer blue'), whereas qualitative data explores opinions, attitudes, and reasons behind behaviour","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because quantitative research answers 'how many/how much' statistically, while qualitative research answers 'why/how' consumers feel.","distractor_reasons":{"A":"Incorrect because both primary and secondary research can produce quantitative or qualitative data.","B":"Option B is correct because quantitative research answers 'how many/how much' statistically, while qualitative research answers 'why/how' consumers feel.","C":"Incorrect because this reverses the typical outputs of focus groups and barcode scanners.","D":"Incorrect because both data types can suffer bias if poorly designed."}}},{"id":"P1_U3_MCQ_045","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_045","question":"Why do market researchers include both 'closed questions' and 'open-ended questions' in a customer satisfaction questionnaire?","options":{"A":"Closed questions allow quick statistical analysis, while open-ended questions capture unexpected customer suggestions in their own words","B":"Closed questions prevent respondents from completing the form honestly","C":"Open-ended questions are required by law in every commercial questionnaire","D":"Open-ended questions are easier to summarize into pie charts than closed questions"},"correctOption":"A","correctAnswer":"Closed questions allow quick statistical analysis, while open-ended questions capture unexpected customer suggestions in their own words","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because combining structured ratings with free-text boxes balances quantitative measurement and qualitative insight.","distractor_reasons":{"A":"Option A is correct because combining structured ratings with free-text boxes balances quantitative measurement and qualitative insight.","B":"Incorrect because well-written closed questions yield clear, honest choices.","C":"Incorrect because questionnaire structure is a research design choice, not a legal mandate.","D":"Incorrect because closed questions are far easier to tabulate into charts."}}},{"id":"P1_U3_MCQ_046","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_046","question":"A restaurant chain relies on a 2019 industry report to plan its 2026 takeaway delivery strategy. Why is this decision risky?","options":{"A":"Secondary data from 2019 is outdated and fails to reflect major shifts in food-delivery apps and consumer ordering habits","B":"Industry reports never contain numerical market-size estimates","C":"Primary research is illegal in the restaurant and hospitality sector","D":"Older reports always overestimate demand for digital delivery apps"},"correctOption":"A","correctAnswer":"Secondary data from 2019 is outdated and fails to reflect major shifts in food-delivery apps and consumer ordering habits","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rapid changes in technology and consumer behaviour quickly make historical secondary data obsolete.","distractor_reasons":{"A":"Option A is correct because rapid changes in technology and consumer behaviour quickly make historical secondary data obsolete.","B":"Incorrect because industry reports frequently include market-size statistics.","C":"Incorrect because restaurants routinely run primary customer surveys.","D":"Incorrect because a 2019 report would actually understate post-2020 delivery app adoption."}}},{"id":"P1_U3_MCQ_047","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_047","question":"How does presenting market research findings using 'bar charts and pie charts' rather than raw spreadsheet tables assist marketing managers?","options":{"A":"Charts visually highlight key proportions, comparisons, and trends quickly for faster decision-making","B":"Charts automatically correct sampling errors and biased survey questions","C":"Charts eliminate the need to collect accurate numerical responses","D":"Charts prevent competitors from ever copying the business's products"},"correctOption":"A","correctAnswer":"Charts visually highlight key proportions, comparisons, and trends quickly for faster decision-making","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because visual data presentation makes complex patterns immediately clear to decision-makers.","distractor_reasons":{"A":"Option A is correct because visual data presentation makes complex patterns immediately clear to decision-makers.","B":"Incorrect because visual formatting cannot fix flawed underlying data collection.","C":"Incorrect because accurate figures are still needed to build valid charts.","D":"Incorrect because internal charts do not create legal product protection."}}},{"id":"P1_U3_MCQ_048","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_048","question":"When is a 'product-oriented' approach most likely to succeed in modern business?","options":{"A":"When consumer tastes change rapidly every fashion season","B":"When selling standard commodity clothing in a saturated high-street market","C":"When operating a local restaurant in a diverse multicultural neighbourhood","D":"When a firm develops breakthrough medical or technological innovations where consumers cannot yet imagine what is possible"},"correctOption":"D","correctAnswer":"When a firm develops breakthrough medical or technological innovations where consumers cannot yet imagine what is possible","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because in cutting-edge R&D fields (such as pharmaceuticals or novel hardware), technical breakthroughs often create entirely new customer demand.","distractor_reasons":{"A":"Incorrect because fast-changing fashion markets penalize firms that ignore customer trends.","B":"Incorrect because saturated clothing markets require close market orientation to match shopper styles.","C":"Incorrect because local restaurants succeed by tailoring menus to neighbourhood tastes.","D":"Option D is correct because in cutting-edge R&D fields (such as pharmaceuticals or novel hardware), technical breakthroughs often create entirely new customer demand."}}},{"id":"P1_U3_MCQ_049","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_049","question":"An online fashion retailer analyzes website 'abandoned shopping cart' analytics and customer return logs before redesigning its sizing guide. Which type of research is this?","options":{"A":"Quota street sampling","B":"External primary focus group","C":"Internal secondary research","D":"External government census research"},"correctOption":"C","correctAnswer":"Internal secondary research","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because website logs and return records are existing operational data held internally by the retailer.","distractor_reasons":{"A":"Incorrect because no street interviews were conducted.","B":"Incorrect because no external focus group discussion was held.","C":"Option C is correct because website logs and return records are existing operational data held internally by the retailer.","D":"Incorrect because the data came from the company's own platform rather than government files."}}},{"id":"P1_U3_MCQ_050","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_050","question":"Why does increasing a survey's 'sample size' from 20 respondents to 1,000 respondents improve market research reliability?","options":{"A":"It reduces random sampling error so results reflect the wider target population more accurately, though at higher cost and time","B":"It guarantees that poorly worded leading questions become unbiased","C":"It eliminates the need to define the target market segment","D":"It makes primary research cheaper than reading free government websites"},"correctOption":"A","correctAnswer":"It reduces random sampling error so results reflect the wider target population more accurately, though at higher cost and time","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because larger representative samples minimize the distortion caused by a few unusual responses.","distractor_reasons":{"A":"Option A is correct because larger representative samples minimize the distortion caused by a few unusual responses.","B":"Incorrect because a larger sample still produces biased answers if the questions themselves are leading.","C":"Incorrect because researchers must still target the relevant population group.","D":"Incorrect because surveying 1,000 people increases time and fieldwork costs."}}},{"id":"P1_U3_MCQ_051","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_051","question":"A smartphone maker builds a small working model of a new phone to test battery safety and gather user feedback on its shape before mass production. Which stage of new product development is this?","options":{"A":"The decline stage of the product life cycle","B":"Generating the initial idea","C":"Segmenting the market","D":"Developing and testing a prototype"},"correctOption":"D","correctAnswer":"Developing and testing a prototype","questionType":"MCQ","explanation":{"correct_reason":"Building a working sample to test safety and collect feedback is prototype development and testing, a key step before launching a new product.","distractor_reasons":{"B":"Idea generation is the earlier stage of thinking of possible products, not constructing and testing a physical model.","C":"Market segmentation divides customers into groups and does not involve making or testing a product sample.","D":"Building a working sample to test safety and collect feedback is prototype development and testing, a key step before launching a new product.","A":"The decline stage occurs late in a product's life when sales fall, not during development before launch."}}},{"id":"P1_U3_MCQ_052","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_052","question":"Stride Athletics sells running shoes and is investing heavily in a distinctive brand with a recognizable logo and design. What is the main benefit of strong branding for Stride?","options":{"A":"It guarantees lower manufacturing costs for every shoe","B":"It removes the need to design or develop new products","C":"It helps customers recognize and trust the shoes, encouraging repeat purchases","D":"It forces competitors to leave the market"},"correctOption":"C","correctAnswer":"It helps customers recognize and trust the shoes, encouraging repeat purchases","questionType":"MCQ","explanation":{"correct_reason":"A strong brand makes a product recognizable and builds customer loyalty and trust, encouraging repeat purchases and supporting a competitive position.","distractor_reasons":{"A":"Branding does not lower production costs; those depend on manufacturing efficiency.","B":"Branding does not remove the need for product design and development.","C":"Recognition and trust encourage repeat purchases, which is the main benefit of branding.","D":"A brand cannot force rivals out of the market; it only influences customer choice."}}},{"id":"P1_U3_MCQ_053","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_053","question":"A gourmet olive oil producer switches to dark UV-protective glass bottles featuring embossed gold labels and clear origin stories. Which two functions of 'packaging' are highlighted here?","options":{"A":"Lowering manufacturing unit costs to zero and replacing wholesale distributors","B":"Protecting product freshness from light damage and promoting a premium brand image on store shelves","C":"Eliminating the need for legal ingredient labelling and barcode scanning","D":"Making the bottle heavier to increase international air-freight charges"},"correctOption":"B","correctAnswer":"Protecting product freshness from light damage and promoting a premium brand image on store shelves","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because packaging physically protects contents during transport/storage while acting as a silent salesperson reinforcing brand positioning.","distractor_reasons":{"A":"Incorrect because glass and embossed labels increase packaging cost and still use distributors.","B":"Option B is correct because packaging physically protects contents during transport/storage while acting as a silent salesperson reinforcing brand positioning.","C":"Incorrect because legal nutritional/origin information is displayed on packaging.","D":"Incorrect because heavier freight weight is a logistical drawback rather than a marketing objective."}}},{"id":"P1_U3_MCQ_054","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_054","question":"Why are many supermarket snack brands redesigning their packaging using recyclable paper pouches instead of single-use plastics?","options":{"A":"Because consumers prefer products with no brand logos on the wrapper","B":"Because paper packaging is always stronger and more waterproof than heavy plastic","C":"To hide mandatory nutritional and allergy warnings from shoppers","D":"To appeal to environmentally conscious consumers and comply with stricter sustainability expectations"},"correctOption":"D","correctAnswer":"To appeal to environmentally conscious consumers and comply with stricter sustainability expectations","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because eco-friendly packaging strengthens brand image among sustainability-minded shoppers and reduces environmental waste.","distractor_reasons":{"A":"Incorrect because brands still print prominent logos on recyclable pouches.","B":"Incorrect because paper often requires careful barrier design to match plastic durability.","C":"Incorrect because legal nutritional and allergen info must remain clearly visible.","D":"Option D is correct because eco-friendly packaging strengthens brand image among sustainability-minded shoppers and reduces environmental waste."}}},{"id":"P1_U3_MCQ_055","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_055","question":"During which stage of the 'Product Life Cycle (PLC)' are sales rising slowly, unit costs high due to low output, and cash flow typically negative because of heavy launch promotion?","options":{"A":"Introduction stage","B":"Maturity stage","C":"Saturation stage","D":"Decline stage"},"correctOption":"A","correctAnswer":"Introduction stage","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because at introduction, low consumer awareness keeps sales modest while high R&D and launch advertising exceed early revenue.","distractor_reasons":{"A":"Option A is correct because at introduction, low consumer awareness keeps sales modest while high R&D and launch advertising exceed early revenue.","B":"Incorrect because maturity features peak sales, strong cash flow, and lower unit costs.","C":"Incorrect because saturation represents peak market penetration rather than slow initial uptake.","D":"Incorrect because decline occurs when sales fall due to changing tastes or superior substitutes."}}},{"id":"P1_U3_MCQ_056","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_056","question":"A wireless earbud brand experiences peak sales volume, intense competition from rival brands, and slowing sales growth as most target consumers already own a pair. Which PLC stage has it reached?","options":{"A":"Development","B":"Introduction","C":"Maturity","D":"Decline"},"correctOption":"C","correctAnswer":"Maturity","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because maturity is characterized by maximum sales plateauing, fierce competition, and heavy persuasive promotion to defend market share.","distractor_reasons":{"A":"Incorrect because development occurs before commercial launch with zero sales.","B":"Incorrect because introduction involves low initial sales and few direct competitors.","C":"Option C is correct because maturity is characterized by maximum sales plateauing, fierce competition, and heavy persuasive promotion to defend market share.","D":"Incorrect because decline involves falling sales rather than plateauing at peak levels."}}},{"id":"P1_U3_MCQ_057","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_057","question":"A classic breakfast cereal entering the 'maturity stage' of its Product Life Cycle launches new honey-almond and chocolate flavours alongside redesigned family-sized boxes. What is this strategy called?","options":{"A":"An extension strategy","B":"Price skimming","C":"Market withdrawal","D":"Product orientation"},"correctOption":"A","correctAnswer":"An extension strategy","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because extension strategies (new flavours, updated packaging, new markets) aim to prolong the profitable maturity phase and delay decline.","distractor_reasons":{"A":"Option A is correct because extension strategies (new flavours, updated packaging, new markets) aim to prolong the profitable maturity phase and delay decline.","B":"Incorrect because price skimming sets a high initial price at product introduction.","C":"Incorrect because market withdrawal discontinues a declining product.","D":"Incorrect because product orientation focuses on engineering without market feedback."}}},{"id":"P1_U3_MCQ_058","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_058","question":"Which of the following is an effective 'extension strategy' for a baking-soda brand whose traditional cooking sales have plateaued?","options":{"A":"Halting all advertising and reducing retail distribution to two stores","B":"Promoting new uses for the product, such as refrigerator deodorizing and household cleaning","C":"Raising the retail price by 80% without changing the product or packaging","D":"Immediately discontinuing the product line and scrapping factory machinery"},"correctOption":"B","correctAnswer":"Promoting new uses for the product, such as refrigerator deodorizing and household cleaning","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because finding new applications for an existing product attracts fresh demand and extends its life cycle.","distractor_reasons":{"A":"Incorrect because cutting promotion and distribution accelerates decline ('harvesting').","B":"Option B is correct because finding new applications for an existing product attracts fresh demand and extends its life cycle.","C":"Incorrect because an unjustified steep price rise drives buyers to generic substitutes.","D":"Incorrect because discontinuing the product ends its life cycle rather than extending it."}}},{"id":"P1_U3_MCQ_059","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_059","question":"A furniture workshop calculates that making one oak dining table costs $240 in materials, labour, and allocated overheads. If it applies a 40% cost-plus mark-up, what is the selling price?","options":{"A":"$280","B":"$336","C":"$96","D":"$400"},"correctOption":"B","correctAnswer":"$336","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Selling Price = Unit Cost + (Unit Cost × Mark-up %) = $240 + ($240 × 0.40) = $240 + $96 = $336.","distractor_reasons":{"A":"Incorrect because $280 adds $40 directly instead of 40% of $240.","B":"Option B is correct because Selling Price = Unit Cost + (Unit Cost × Mark-up %) = $240 + ($240 × 0.40) = $240 + $96 = $336.","C":"Incorrect because $96 is only the profit mark-up amount, not the total selling price.","D":"Incorrect because $400 divides $240 by 0.60 instead of adding a 40% mark-up."}}},{"id":"P1_U3_MCQ_060","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_060","question":"What is a major limitation of relying solely on 'cost-plus pricing' in a competitive retail market?","options":{"A":"It ignores competitor prices and how much customers are actually willing to pay, risking overpricing and lost sales","B":"It guarantees that the business will make a financial loss on every unit sold","C":"It is too complex for small businesses to calculate without specialist economists","D":"It forces businesses to sell products below variable manufacturing cost"},"correctOption":"A","correctAnswer":"It ignores competitor prices and how much customers are actually willing to pay, risking overpricing and lost sales","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cost-plus pricing is purely inward-looking; if the firm's unit costs exceed rivals', the resulting price may be uncompetitive.","distractor_reasons":{"A":"Option A is correct because cost-plus pricing is purely inward-looking; if the firm's unit costs exceed rivals', the resulting price may be uncompetitive.","B":"Incorrect because cost-plus ensures a profit margin per unit if forecasted sales volume is achieved.","C":"Incorrect because simplicity of calculation is actually cost-plus pricing's main advantage.","D":"Incorrect because adding a positive mark-up sets price above unit cost."}}},{"id":"P1_U3_MCQ_061","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_061","question":"A new video-streaming service enters a crowded market at $3.99 per month—well below established rivals charging $11.99—to attract millions of subscribers rapidly before raising prices later. Which pricing strategy is this?","options":{"A":"Price skimming","B":"Penetration pricing","C":"Cost-plus premium pricing","D":"Dynamic surge pricing"},"correctOption":"B","correctAnswer":"Penetration pricing","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because penetration pricing sets a low introductory price to break into a competitive market and build market share quickly.","distractor_reasons":{"A":"Incorrect because price skimming sets a high initial price for an innovative product.","B":"Option B is correct because penetration pricing sets a low introductory price to break into a competitive market and build market share quickly.","C":"Incorrect because charging far below rivals prioritizes rapid share over high initial unit margins.","D":"Incorrect because dynamic pricing adjusts prices continuously with real-time demand fluctuations."}}},{"id":"P1_U3_MCQ_062","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_062","question":"What is a key risk when a business uses 'penetration pricing' to launch a new product?","options":{"A":"Initial profit margins are very low, and customers may resist future price increases or perceive the brand as low quality","B":"High initial prices deter all price-sensitive buyers from trying the product","C":"Competitors never notice a low-priced rival entering their market","D":"Supermarkets refuse to stock affordable everyday products"},"correctOption":"A","correctAnswer":"Initial profit margins are very low, and customers may resist future price increases or perceive the brand as low quality","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because low launch prices require high sales volume to cover costs and can anchor consumer price expectations too low.","distractor_reasons":{"A":"Option A is correct because low launch prices require high sales volume to cover costs and can anchor consumer price expectations too low.","B":"Incorrect because high initial prices deterring buyers is a risk of price skimming.","C":"Incorrect because aggressive low pricing often triggers retaliatory price cuts from rivals.","D":"Incorrect because supermarkets welcome competitively priced high-turnover items."}}},{"id":"P1_U3_MCQ_063","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_063","question":"Why is 'price skimming' effective for a pharmaceutical or technology firm launching a patented, breakthrough innovation?","options":{"A":"There are dozens of identical low-cost substitutes already on supermarket shelves","B":"Early adopters are willing to pay a high price for exclusive cutting-edge features, helping the firm rapidly recover heavy R&D costs","C":"Low initial prices maximize immediate profit margins per unit","D":"Patent laws require firms to charge the highest legal price for ten years"},"correctOption":"B","correctAnswer":"Early adopters are willing to pay a high price for exclusive cutting-edge features, helping the firm rapidly recover heavy R&D costs","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because temporary protection from competition and strong early-adopter demand enable high unit margins before rivals catch up.","distractor_reasons":{"A":"Incorrect because abundant close substitutes make skimming unworkable.","B":"Option B is correct because temporary protection from competition and strong early-adopter demand enable high unit margins before rivals catch up.","C":"Incorrect because skimming relies on high initial prices, not low ones.","D":"Incorrect because patents grant exclusive production rights rather than mandating high prices."}}},{"id":"P1_U3_MCQ_064","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_064","question":"Three petrol stations located on the same highway interchange match each other's fuel prices within one cent every morning. Which pricing strategy are they following?","options":{"A":"Competitive pricing","B":"Price skimming","C":"Penetration pricing","D":"Psychological prestige pricing"},"correctOption":"A","correctAnswer":"Competitive pricing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because competitive pricing sets prices in line with rivals when products are very similar and buyers compare prices easily.","distractor_reasons":{"A":"Option A is correct because competitive pricing sets prices in line with rivals when products are very similar and buyers compare prices easily.","B":"Incorrect because price skimming applies to new, innovative launches.","C":"Incorrect because penetration pricing sets a deliberately low entry price for a new product.","D":"Incorrect because petrol is a homogenous commodity rather than a prestige luxury."}}},{"id":"P1_U3_MCQ_065","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_065","question":"A fashion retailer runs a '50% Off End-of-Season Clearance Sale' for two weeks to clear winter coats before spring stock arrives. Which pricing method is being used?","options":{"A":"Predatory monopoly pricing","B":"Price skimming","C":"Cost-plus mark-up pricing","D":"Promotional pricing"},"correctOption":"D","correctAnswer":"Promotional pricing","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because promotional pricing temporarily reduces prices to stimulate short-term demand, clear seasonal stock, or attract store traffic.","distractor_reasons":{"A":"Incorrect because seasonal clearance is standard inventory management rather than illegal anti-competitive predation.","B":"Incorrect because skimming charges a high launch price for new innovations.","C":"Incorrect because clearance discounts often cut prices near or below full cost rather than adding a mark-up.","D":"Option D is correct because promotional pricing temporarily reduces prices to stimulate short-term demand, clear seasonal stock, or attract store traffic."}}},{"id":"P1_U3_MCQ_066","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_066","question":"What is a potential negative consequence if a sofa retailer runs '50% Off' promotional pricing almost every month of the year?","options":{"A":"Profit margins per sofa increase automatically during every discount sale","B":"Customers refuse to ever buy sofas at full price and the brand's perceived quality is damaged","C":"Competitors are legally prohibited from offering competing discounts","D":"Factory production costs drop by 50% every time a sale is advertised"},"correctOption":"B","correctAnswer":"Customers refuse to ever buy sofas at full price and the brand's perceived quality is damaged","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because continuous discounting trains shoppers to wait for sales and erodes trust in regular prices.","distractor_reasons":{"A":"Incorrect because discounting lowers unit profit margins unless costs fall equally.","B":"Option B is correct because continuous discounting trains shoppers to wait for sales and erodes trust in regular prices.","C":"Incorrect because rivals can freely run their own promotions.","D":"Incorrect because retail price discounts do not reduce manufacturing costs."}}},{"id":"P1_U3_MCQ_067","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_067","question":"A supermarket prices a popular brand of coffee at $4.99 instead of $5.00, while a luxury watchmaker prices its gold timepiece at a round $12,000. Both firms are applying which pricing concept?","options":{"A":"Psychological pricing","B":"Penetration pricing","C":"Cost-plus pricing","D":"Competitive price matching"},"correctOption":"A","correctAnswer":"Psychological pricing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because psychological pricing uses specific price points ($4.99 to feel under $5; $12,000 round figure to signal prestige) to influence buyer perception.","distractor_reasons":{"A":"Option A is correct because psychological pricing uses specific price points ($4.99 to feel under $5; $12,000 round figure to signal prestige) to influence buyer perception.","B":"Incorrect because penetration pricing sets a low entry price to gain market share.","C":"Incorrect because cost-plus calculates price mechanically from unit cost plus a percentage.","D":"Incorrect because these figures target buyer psychology rather than matching a rival."}}},{"id":"P1_U3_MCQ_068","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_068","question":"An airline uses software that automatically raises ticket prices as seats fill up and departure dates approach, while lowering prices on quiet mid-week flights. Which pricing method is this?","options":{"A":"Penetration pricing","B":"Static cost-plus pricing","C":"Loss-leader pricing","D":"Dynamic pricing"},"correctOption":"D","correctAnswer":"Dynamic pricing","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because dynamic pricing adjusts prices flexibly in real time according to changing demand levels and remaining capacity.","distractor_reasons":{"A":"Incorrect because penetration pricing is a low introductory launch strategy.","B":"Incorrect because static cost-plus keeps prices fixed based on unit cost.","C":"Incorrect because loss-leader pricing sells an item below cost to attract buyers for other goods.","D":"Option D is correct because dynamic pricing adjusts prices flexibly in real time according to changing demand levels and remaining capacity."}}},{"id":"P1_U3_MCQ_069","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_069","question":"Bean & Brew wants to set the price of its new cakes. It adds up the cost of ingredients and labour for each cake, then adds a fixed percentage to cover overheads and profit. Which pricing method is Bean & Brew using?","options":{"A":"Competitive pricing","B":"Promotional pricing","C":"Cost-plus pricing","D":"Place-based pricing"},"correctOption":"C","correctAnswer":"Cost-plus pricing","questionType":"MCQ","explanation":{"correct_reason":"Cost-plus pricing calculates the total cost per unit and then adds a percentage margin to determine the selling price.","distractor_reasons":{"A":"Competitive pricing sets prices based on rivals' prices, not on internal costs.","B":"Promotional pricing uses temporary price offers to attract customers, not a cost calculation.","C":"Adding a percentage to unit cost is exactly what cost-plus pricing involves.","D":"Place-based pricing is not a cost-based method; distribution decisions concern place, not price."}}},{"id":"P1_U3_MCQ_070","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_070","question":"Metro Bikes makes bicycles in one factory and wants customers across the country to be able to buy them without travelling far. Which element of the marketing mix is Metro Bikes mainly addressing?","options":{"A":"Product — the features and design of the bicycle","B":"Price — the amount customers are charged","C":"Place — the distribution channels used to reach customers","D":"Promotion — the advertising used to raise awareness"},"correctOption":"C","correctAnswer":"Place — the distribution channels used to reach customers","questionType":"MCQ","explanation":{"correct_reason":"Ensuring customers can buy the product conveniently concerns place, which covers distribution channels and product availability.","distractor_reasons":{"A":"Product concerns the item's features and design, not how customers obtain it.","B":"Price concerns the amount charged, not where the product is sold.","C":"Distribution and availability are part of the place element of the mix.","D":"Promotion concerns communication and advertising, not distribution."}}},{"id":"P1_U3_MCQ_071","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_071","question":"Verde Snacks is redesigning the wrapper of its healthy snack bars to be bright and eye-catching, show clear nutritional information and be resealable. What is the main aim of these changes?","options":{"A":"To change the price charged to retailers","B":"To improve packaging so the product attracts and informs customers","C":"To change where the snack bars are manufactured","D":"To reduce the number of promotional methods used"},"correctOption":"B","correctAnswer":"To improve packaging so the product attracts and informs customers","questionType":"MCQ","explanation":{"correct_reason":"Packaging is part of the product element; attractive, informative and practical packaging helps differentiate the product and appeal to customers.","distractor_reasons":{"A":"Changing the wrapper does not set the price charged to retailers.","B":"Better packaging attracts and informs customers, supporting the product's appeal.","C":"Wrapper design does not affect where the bars are manufactured.","D":"Redesigning packaging is not about cutting the number of promotional methods."}}},{"id":"P1_U3_MCQ_072","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_072","question":"A furniture maker calculates the total cost of producing a wooden desk, then adds 30% to that cost to set the selling price. Which pricing method is the firm using?","options":{"A":"Cost-plus pricing","B":"Competitive pricing","C":"Promotional pricing","D":"Loss leader pricing"},"correctOption":"A","correctAnswer":"Cost-plus pricing","questionType":"MCQ","explanation":{"correct_reason":"Cost-plus pricing sets the selling price by adding a percentage profit margin to the total cost of making the product, exactly as the furniture maker does.","distractor_reasons":{"A":"This is correct: adding a percentage to production cost is cost-plus pricing.","B":"Competitive pricing sets the price by reference to what rivals charge, not by adding a margin to cost.","C":"Promotional pricing temporarily cuts price to attract customers, rather than building it up from cost.","D":"Loss leader pricing sells below cost to draw customers in, the opposite of adding a profit margin."}}},{"id":"P1_U3_MCQ_073","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_073","question":"A supermarket sells cartons of fresh milk at slightly below cost price to draw families into the store, knowing they will also buy profitable groceries during the same visit. What is this pricing tactic called?","options":{"A":"Loss-leader pricing","B":"Price skimming","C":"Cost-plus pricing","D":"Prestige pricing"},"correctOption":"A","correctAnswer":"Loss-leader pricing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because loss-leader pricing prices a frequently bought staple very low to generate store footfall and higher-margin basket sales.","distractor_reasons":{"A":"Option A is correct because loss-leader pricing prices a frequently bought staple very low to generate store footfall and higher-margin basket sales.","B":"Incorrect because price skimming sets a high initial price for new innovations.","C":"Incorrect because cost-plus adds a positive profit margin above unit cost.","D":"Incorrect because prestige pricing uses high prices to signal luxury status."}}},{"id":"P1_U3_MCQ_074","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_074","question":"Why do electronics manufacturers often update their smartphone models every 12 months even when current versions still sell well?","options":{"A":"To increase unit manufacturing costs while lowering product functionality","B":"Because laws require all smartphones to be destroyed after twelve months","C":"To act as a continuous extension/innovation strategy that stimulates upgrade demand and prevents rivals from overtaking them in maturity","D":"Because product life cycles never have a decline stage in technology markets"},"correctOption":"C","correctAnswer":"To act as a continuous extension/innovation strategy that stimulates upgrade demand and prevents rivals from overtaking them in maturity","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because rapid technological innovation shortens life cycles, so regular feature upgrades keep customers upgrading within the brand.","distractor_reasons":{"A":"Incorrect because upgrades aim to add customer value and sustain revenue.","B":"Incorrect because no law mandates annual device replacement.","C":"Option C is correct because rapid technological innovation shortens life cycles, so regular feature upgrades keep customers upgrading within the brand.","D":"Incorrect because tech products actually decline very rapidly if not updated."}}},{"id":"P1_U3_MCQ_075","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_075","question":"How does a product's 'Unique Selling Point (USP)' support its pricing strategy?","options":{"A":"A clear USP differentiates the product from rivals, reducing price sensitivity and allowing the business to charge a higher price","B":"A USP forces the business to match the lowest discount supermarket price","C":"A USP eliminates the need for packaging or brand promotion","D":"A USP guarantees that fixed production costs fall to zero"},"correctOption":"A","correctAnswer":"A clear USP differentiates the product from rivals, reducing price sensitivity and allowing the business to charge a higher price","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a distinctive, valued feature (USP) makes substitutes less comparable, supporting stronger profit margins.","distractor_reasons":{"A":"Option A is correct because a distinctive, valued feature (USP) makes substitutes less comparable, supporting stronger profit margins.","B":"Incorrect because undifferentiated commodities—not USP products—are forced into pure price matching.","C":"Incorrect because packaging and promotion are needed to communicate the USP to buyers.","D":"Incorrect because a USP affects perceived value rather than eliminating fixed costs."}}},{"id":"P1_U3_MCQ_076","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_076","question":"A custom wedding-cake baker takes orders directly from brides and delivers cakes straight to wedding venues without using any retail shops or wholesalers. Which distribution channel is this?","options":{"A":"Agent-intermediated export channel","B":"Traditional wholesale channel","C":"Direct channel (Producer to Consumer)","D":"Multi-tier retail chain channel"},"correctOption":"C","correctAnswer":"Direct channel (Producer to Consumer)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a zero-intermediary direct channel moves perishable, bespoke goods straight from producer to final consumer.","distractor_reasons":{"A":"Incorrect because no overseas sales agent is involved.","B":"Incorrect because no wholesaler buys and resells the cakes.","C":"Option C is correct because a zero-intermediary direct channel moves perishable, bespoke goods straight from producer to final consumer.","D":"Incorrect because no third-party retail stores stock the cakes."}}},{"id":"P1_U3_MCQ_077","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_077","question":"What is a major advantage for a manufacturer selling directly to consumers via its own e-commerce website rather than through supermarkets?","options":{"A":"The manufacturer keeps the full retail profit margin and controls brand presentation and customer data directly","B":"Supermarkets pay all of the manufacturer's individual parcel delivery charges","C":"Consumers can physically inspect and try on products in thousands of local stores immediately","D":"The manufacturer avoids managing individual customer orders or returns"},"correctOption":"A","correctAnswer":"The manufacturer keeps the full retail profit margin and controls brand presentation and customer data directly","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cutting out retail intermediaries avoids sharing profit margins and builds direct customer relationships.","distractor_reasons":{"A":"Option A is correct because cutting out retail intermediaries avoids sharing profit margins and builds direct customer relationships.","B":"Incorrect because in direct e-commerce the manufacturer handles and funds parcel shipping.","C":"Incorrect because physical store browsing is an advantage of retail channels, not online-only direct sales.","D":"Incorrect because direct selling requires handling individual orders, customer service, and returns."}}},{"id":"P1_U3_MCQ_078","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_078","question":"How does a 'wholesaler' add value in the distribution channel between a large canned-food factory and thousands of small independent corner shops?","options":{"A":"By 'breaking bulk'—buying huge lorry-loads from the factory, storing stock, and selling smaller assorted quantities to local shops","B":"By manufacturing the canned food on behalf of the factory","C":"By guaranteeing that independent shops never pay for the stock they order","D":"By eliminating all transport between factories and retail stores"},"correctOption":"A","correctAnswer":"By 'breaking bulk'—buying huge lorry-loads from the factory, storing stock, and selling smaller assorted quantities to local shops","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because wholesalers bridge the gap between high-volume producers and small retailers that lack warehouse space for full truckloads.","distractor_reasons":{"A":"Option A is correct because wholesalers bridge the gap between high-volume producers and small retailers that lack warehouse space for full truckloads.","B":"Incorrect because wholesalers distribute finished goods rather than manufacturing them.","C":"Incorrect because retailers must pay wholesalers for purchased inventory.","D":"Incorrect because wholesalers organize transport and regional warehousing."}}},{"id":"P1_U3_MCQ_079","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_079","question":"Why do large national supermarket chains usually buy groceries directly from food manufacturers instead of using a 'wholesaler'?","options":{"A":"Supermarkets buy in huge bulk quantities for their own regional warehouses, saving the wholesaler's profit margin","B":"Wholesalers are legally forbidden from selling food products to large companies","C":"Supermarkets sell only bespoke handmade goods","D":"Manufacturers refuse to sell large pallet loads to major retail chains"},"correctOption":"A","correctAnswer":"Supermarkets buy in huge bulk quantities for their own regional warehouses, saving the wholesaler's profit margin","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because large retail chains have the scale and logistics hubs to perform the wholesaling function themselves at lower unit cost.","distractor_reasons":{"A":"Option A is correct because large retail chains have the scale and logistics hubs to perform the wholesaling function themselves at lower unit cost.","B":"Incorrect because no law bars wholesalers from serving large firms.","C":"Incorrect because supermarkets sell mass-produced everyday goods.","D":"Incorrect because manufacturers eagerly supply large retail chains."}}},{"id":"P1_U3_MCQ_080","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_080","question":"How does an 'agent' differ from a 'wholesaler' in international distribution?","options":{"A":"An agent manufactures products locally, whereas a wholesaler designs television commercials","B":"An agent operates physical supermarket stores, whereas a wholesaler sells only online","C":"An agent negotiates sales on behalf of a producer for a commission without taking ownership of the goods, whereas a wholesaler buys and owns the stock to resell","D":"An agent is employed exclusively in domestic retail shops, whereas a wholesaler works only in banks"},"correctOption":"C","correctAnswer":"An agent negotiates sales on behalf of a producer for a commission without taking ownership of the goods, whereas a wholesaler buys and owns the stock to resell","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because agents use local market contacts to connect exporters with foreign buyers on commission without taking inventory risk.","distractor_reasons":{"A":"Incorrect because agents arrange sales rather than manufacturing or advertising.","B":"Incorrect because retail chains operate physical stores, not agents.","C":"Option C is correct because agents use local market contacts to connect exporters with foreign buyers on commission without taking inventory risk.","D":"Incorrect because both operate across commercial supply chains."}}},{"id":"P1_U3_MCQ_081","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_081","question":"Which distribution channel is most appropriate for a producer of fresh strawberries that spoil within 48 hours?","options":{"A":"Short channel: direct to consumers at farm shops or directly to local supermarkets with refrigerated transport","B":"Long four-tier channel passing through national exporters, regional wholesalers, and small corner kiosks","C":"Slow international sea freight via overseas commission agents","D":"Warehousing stock for six months before releasing it to retailers"},"correctOption":"A","correctAnswer":"Short channel: direct to consumers at farm shops or directly to local supermarkets with refrigerated transport","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because perishable produce requires fast, short distribution channels to reach consumers while still fresh.","distractor_reasons":{"A":"Option A is correct because perishable produce requires fast, short distribution channels to reach consumers while still fresh.","B":"Incorrect because multi-tier intermediaries add handling delays that cause fresh fruit to rot.","C":"Incorrect because slow sea freight destroys short-shelf-life berries.","D":"Incorrect because fresh strawberries cannot be stored for months."}}},{"id":"P1_U3_MCQ_082","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_082","question":"How has the growth of 'e-commerce' benefited a small regional craft-tea business?","options":{"A":"It can reach customers nationwide and internationally 24/7 without paying expensive high-street store rents","B":"It eliminates all costs of packaging, parcel shipping, and website cybersecurity","C":"It guarantees that no rival tea brands can advertise online","D":"Customers no longer care about tea flavour or delivery speed"},"correctOption":"A","correctAnswer":"It can reach customers nationwide and internationally 24/7 without paying expensive high-street store rents","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because an online storefront removes geographical limits and high-street property overheads for niche and small businesses.","distractor_reasons":{"A":"Option A is correct because an online storefront removes geographical limits and high-street property overheads for niche and small businesses.","B":"Incorrect because e-commerce still incurs shipping, packaging, and web maintenance costs.","C":"Incorrect because online markets feature intense global competition.","D":"Incorrect because quality and fast delivery remain critical for online reviews and repeat orders."}}},{"id":"P1_U3_MCQ_083","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_083","question":"What is a major challenge for a traditional clothing retailer expanding into 'e-commerce'?","options":{"A":"Online stores require paying rent on physical shopping-mall units","B":"Customers are legally prohibited from buying clothes online using debit cards","C":"E-commerce websites can only be viewed during normal daytime shop hours","D":"High rates of customer garment returns due to sizing uncertainty and increased parcel logistics costs"},"correctOption":"D","correctAnswer":"High rates of customer garment returns due to sizing uncertainty and increased parcel logistics costs","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because shoppers cannot try clothes on before buying online, leading to costly reverse logistics and return processing.","distractor_reasons":{"A":"Incorrect because online operations reduce reliance on physical mall space.","B":"Incorrect because online card and digital payments are standard.","C":"Incorrect because websites operate 24 hours a day.","D":"Option D is correct because shoppers cannot try clothes on before buying online, leading to costly reverse logistics and return processing."}}},{"id":"P1_U3_MCQ_084","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_084","question":"What is the key difference between 'informative advertising' and 'persuasive advertising'?","options":{"A":"Informative advertising is used only in the decline stage, whereas persuasive advertising is used only before product launch","B":"Informative advertising is free, whereas persuasive advertising is paid media","C":"Informative advertising gives factual details about a new product's features or uses, whereas persuasive advertising appeals to emotions and brand image to convince buyers it is superior to rivals","D":"Informative advertising is illegal for consumer goods, whereas persuasive advertising is mandatory"},"correctOption":"C","correctAnswer":"Informative advertising gives factual details about a new product's features or uses, whereas persuasive advertising appeals to emotions and brand image to convince buyers it is superior to rivals","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because informative ads educate consumers (vital at launch or for public health notices), while persuasive ads build brand preference in competitive markets.","distractor_reasons":{"A":"Incorrect because informative ads are heavily used at introduction, while persuasive ads dominate growth and maturity.","B":"Incorrect because both are paid forms of above-the-line advertising.","C":"Option C is correct because informative ads educate consumers (vital at launch or for public health notices), while persuasive ads build brand preference in competitive markets.","D":"Incorrect because both are lawful when truthful and non-misleading."}}},{"id":"P1_U3_MCQ_085","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_085","question":"A breakfast-cereal brand includes free collectible sports cards inside cereal boxes and offers 'Buy Two, Get One Free' coupons in supermarkets. Which promotional category is this?","options":{"A":"Sales promotion","B":"Public relations (PR)","C":"Personal selling","D":"Television informative advertising"},"correctOption":"A","correctAnswer":"Sales promotion","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sales promotions use short-term incentives (free gifts, coupons, BOGOF, loyalty points) to stimulate immediate purchases.","distractor_reasons":{"A":"Option A is correct because sales promotions use short-term incentives (free gifts, coupons, BOGOF, loyalty points) to stimulate immediate purchases.","B":"Incorrect because PR manages unpaid media coverage and public goodwill rather than point-of-sale coupons.","C":"Incorrect because personal selling involves face-to-face sales conversations.","D":"Incorrect because free gifts and coupons are below-the-line incentives rather than TV commercials."}}},{"id":"P1_U3_MCQ_086","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_086","question":"How does 'sales promotion' differ from 'advertising' in its typical impact on sales?","options":{"A":"Sales promotion triggers a rapid short-term spike in purchases, whereas advertising builds long-term brand awareness and loyalty","B":"Sales promotion is always more expensive than national television advertising","C":"Sales promotion is targeted only at factory suppliers, whereas advertising targets only employees","D":"Sales promotion never uses discounts, samples, or competitions"},"correctOption":"A","correctAnswer":"Sales promotion triggers a rapid short-term spike in purchases, whereas advertising builds long-term brand awareness and loyalty","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because coupons and multi-buys encourage immediate action ('buy now'), while advertising shapes lasting brand perception.","distractor_reasons":{"A":"Option A is correct because coupons and multi-buys encourage immediate action ('buy now'), while advertising shapes lasting brand perception.","B":"Incorrect because national TV advertising is usually far costlier than point-of-sale promotions.","C":"Incorrect because both target end consumers (and trade promotions can also target retailers).","D":"Incorrect because discounts, free samples, and competitions are classic sales promotion tools."}}},{"id":"P1_U3_MCQ_087","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_087","question":"A sports-drink company sponsors a city charity marathon and donates clean water stations, earning positive stories on local TV news and newspapers without buying ad space. Which promotional method is this?","options":{"A":"Loss-leader pricing","B":"Direct mail leaflets","C":"Personal door-to-door selling","D":"Public relations (PR) and sponsorship"},"correctOption":"D","correctAnswer":"Public relations (PR) and sponsorship","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because PR and community sponsorship generate credible earned media coverage and strengthen public goodwill.","distractor_reasons":{"A":"Incorrect because loss-leader pricing is a retail pricing tactic.","B":"Incorrect because direct mail sends paid promotional letters to households.","C":"Incorrect because personal selling involves individual sales pitches.","D":"Option D is correct because PR and community sponsorship generate credible earned media coverage and strengthen public goodwill."}}},{"id":"P1_U3_MCQ_088","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_088","question":"Why is 'personal selling' essential for an industrial machinery manufacturer selling $500,000 custom factory presses to corporate buyers?","options":{"A":"Personal selling requires zero product knowledge from sales representatives","B":"Personal selling is the cheapest way to reach 10 million individual supermarket shoppers","C":"Industrial buyers are legally forbidden from reading technical brochures or websites","D":"Complex, high-value B2B equipment requires tailored technical demonstrations, specification negotiation, and relationship trust"},"correctOption":"D","correctAnswer":"Complex, high-value B2B equipment requires tailored technical demonstrations, specification negotiation, and relationship trust","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because high-ticket customized B2B orders involve detailed technical questions and contract terms best handled one-to-one.","distractor_reasons":{"A":"Incorrect because B2B sales engineers need deep technical expertise.","B":"Incorrect because personal selling has a very high cost per contact and is unsuitable for mass consumer staples.","C":"Incorrect because brochures and websites support the sales process.","D":"Option D is correct because high-ticket customized B2B orders involve detailed technical questions and contract terms best handled one-to-one."}}},{"id":"P1_U3_MCQ_089","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_089","question":"A local independent plumber has a monthly marketing budget of $300. Which promotional combination is most cost-effective?","options":{"A":"A 30-second commercial during an international football final","B":"Targeted local social media ads, a free online business directory listing, and magnetic signs on the work van","C":"Full-page colour advertisements in national glossy fashion magazines","D":"Sponsoring an international Formula 1 racing team"},"correctOption":"B","correctAnswer":"Targeted local social media ads, a free online business directory listing, and magnetic signs on the work van","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because geo-targeted social ads, local listings, and vehicle signage reach nearby homeowners at very low cost.","distractor_reasons":{"A":"Incorrect because global sports broadcasts cost hundreds of thousands of dollars and waste reach outside the plumber's town.","B":"Option B is correct because geo-targeted social ads, local listings, and vehicle signage reach nearby homeowners at very low cost.","C":"Incorrect because national fashion magazines are expensive and poorly targeted for local plumbing.","D":"Incorrect because global motorsport sponsorship far exceeds a small local budget."}}},{"id":"P1_U3_MCQ_090","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_090","question":"How does 'social media influencer marketing' help a new skincare brand reach teenage and young-adult buyers?","options":{"A":"Influencers guarantee that products never need safety testing","B":"Trusted content creators demonstrate the products authentically to engaged niche followers at lower cost than traditional TV","C":"Social media posts reach retired citizens without smartphones more effectively than newspapers","D":"Influencer campaigns eliminate the need for an online checkout or retail stock"},"correctOption":"B","correctAnswer":"Trusted content creators demonstrate the products authentically to engaged niche followers at lower cost than traditional TV","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because younger consumers follow digital creators closely and respond strongly to peer-style recommendations.","distractor_reasons":{"A":"Incorrect because cosmetic safety laws remain strictly enforceable.","B":"Option B is correct because younger consumers follow digital creators closely and respond strongly to peer-style recommendations.","C":"Incorrect because print media and TV reach older demographics more broadly than youth social apps.","D":"Incorrect because e-commerce checkout and inventory remain essential to fulfil orders."}}},{"id":"P1_U3_MCQ_091","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_091","question":"What is a major risk when a sportswear brand relies heavily on a celebrity endorsement for its promotional campaigns?","options":{"A":"If the celebrity becomes involved in a public scandal, negative publicity can immediately damage the brand's reputation","B":"Celebrity endorsements are completely free for the sportswear company","C":"Consumers never recognize famous athletes in advertisements","D":"Celebrity endorsements prevent the brand from selling shoes in retail stores"},"correctOption":"A","correctAnswer":"If the celebrity becomes involved in a public scandal, negative publicity can immediately damage the brand's reputation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because linking brand identity closely to an individual exposes the company to reputational fallout from that person's private actions.","distractor_reasons":{"A":"Option A is correct because linking brand identity closely to an individual exposes the company to reputational fallout from that person's private actions.","B":"Incorrect because celebrity contracts are very expensive.","C":"Incorrect because high recognition is the exact reason brands hire celebrities.","D":"Incorrect because endorsements aim to boost retail and online store sales."}}},{"id":"P1_U3_MCQ_092","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_092","question":"A home-furnishings company generates $2,400,000 in annual sales and allocates 6% of sales revenue to its annual marketing budget. If $54,000 is spent on digital ads, how much remains for other promotional activities?","options":{"A":"$54,000","B":"$144,000","C":"$346,000","D":"$90,000"},"correctOption":"D","correctAnswer":"$90,000","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Total Budget = 6% of $2,400,000 = $144,000; Remaining Budget = $144,000 − $54,000 = $90,000.","distractor_reasons":{"A":"Incorrect because $54,000 is the amount already spent on digital ads.","B":"Incorrect because $144,000 is the total marketing budget before subtracting the $54,000 digital ad spend.","C":"Incorrect because $346,000 uses 16.7% instead of 6%.","D":"Option D is correct because Total Budget = 6% of $2,400,000 = $144,000; Remaining Budget = $144,000 − $54,000 = $90,000."}}},{"id":"P1_U3_MCQ_093","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_093","question":"How can a marketing director best evaluate whether a $30,000 online promotional campaign was financially worthwhile?","options":{"A":"Verify that the campaign used every single dollar of the budget regardless of sales","B":"Count only how many employees inside the company liked the advert's colours","C":"Check whether the company's factory rent decreased during the campaign","D":"Compare the extra gross profit generated from tracked campaign sales and promo codes against the $30,000 campaign cost"},"correctOption":"D","correctAnswer":"Compare the extra gross profit generated from tracked campaign sales and promo codes against the $30,000 campaign cost","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because promotional effectiveness is measured by comparing incremental sales/profit return against campaign expenditure.","distractor_reasons":{"A":"Incorrect because spending a full budget without generating profitable sales is ineffective.","B":"Incorrect because internal staff opinions do not measure customer buying response.","C":"Incorrect because fixed factory rent is unrelated to promotional return.","D":"Option D is correct because promotional effectiveness is measured by comparing incremental sales/profit return against campaign expenditure."}}},{"id":"P1_U3_MCQ_094","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_094","question":"Why does an 'omnichannel' retail strategy—combining physical stores, a mobile app, and click-and-collect website ordering—give a clothing brand a competitive advantage?","options":{"A":"It forces every customer to visit a physical store before viewing prices","B":"It eliminates the need to maintain any inventory tracking software","C":"It allows the retailer to close all warehouses and delivery networks","D":"Customers can browse, buy, collect, or return items conveniently across whichever channel suits them best at any moment"},"correctOption":"D","correctAnswer":"Customers can browse, buy, collect, or return items conveniently across whichever channel suits them best at any moment","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because integrating online convenience with physical store immediacy maximizes customer reach and convenience.","distractor_reasons":{"A":"Incorrect because online channels display prices transparently anytime.","B":"Incorrect because omnichannel retailing requires sophisticated real-time stock integration.","C":"Incorrect because fulfilling click-and-collect and home deliveries relies on strong warehousing.","D":"Option D is correct because integrating online convenience with physical store immediacy maximizes customer reach and convenience."}}},{"id":"P1_U3_MCQ_095","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_095","question":"Which factor is most decisive when a luxury perfume house chooses which retail outlets ('Place') should stock its fragrance?","options":{"A":"Selecting prestigious department stores and exclusive boutiques whose upscale environment reinforces the brand's luxury image","B":"Placing bottles next to motor oil in discount roadside petrol stations for maximum volume","C":"Choosing only wholesale cash-and-carry warehouses with bare concrete floors","D":"Distributing exclusively through unbranded vending machines in train stations"},"correctOption":"A","correctAnswer":"Selecting prestigious department stores and exclusive boutiques whose upscale environment reinforces the brand's luxury image","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because selective distribution in high-end stores aligns Place with the brand's premium Product and Price positioning.","distractor_reasons":{"A":"Option A is correct because selective distribution in high-end stores aligns Place with the brand's premium Product and Price positioning.","B":"Incorrect because discount petrol stations would destroy a luxury perfume's exclusive image.","C":"Incorrect because bare warehouses clash with prestige brand expectations.","D":"Incorrect because station vending machines cheapen luxury positioning."}}},{"id":"P1_U3_MCQ_096","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_096","question":"Why do manufacturers of mass-market chewing gum and batteries use 'intensive distribution' across supermarkets, convenience stores, cinemas, and vending machines?","options":{"A":"Because these low-cost impulse items rely on maximum convenience and immediate availability wherever shoppers happen to be","B":"Because chewing gum requires personalized technical consultation before purchase","C":"Because batteries are luxury status symbols bought once every ten years","D":"Because intensive distribution avoids using any wholesalers or retailers"},"correctOption":"A","correctAnswer":"Because these low-cost impulse items rely on maximum convenience and immediate availability wherever shoppers happen to be","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because buyers rarely travel far for routine convenience items; if one brand is unavailable, they immediately buy a rival.","distractor_reasons":{"A":"Option A is correct because buyers rarely travel far for routine convenience items; if one brand is unavailable, they immediately buy a rival.","B":"Incorrect because chewing gum is a simple everyday purchase requiring zero technical advice.","C":"Incorrect because batteries are routine utilitarian goods.","D":"Incorrect because intensive distribution relies heavily on wholesalers and multiple retail tiers."}}},{"id":"P1_U3_MCQ_097","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_097","question":"How does 'direct email marketing' using personalized customer purchase histories outperform untargeted printed flyers dropped through random letterboxes?","options":{"A":"It has virtually zero printing/postage cost, tailors offers to proven buyer interests, and allows instant click-through tracking","B":"It reaches households that have no internet access or email accounts","C":"Consumers never delete marketing emails without reading every word","D":"Direct email marketing is exempt from data privacy and consent regulations"},"correctOption":"A","correctAnswer":"It has virtually zero printing/postage cost, tailors offers to proven buyer interests, and allows instant click-through tracking","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because targeted email segments buyers by past behaviour, dramatically lowering cost per conversion and enabling precise analytics.","distractor_reasons":{"A":"Option A is correct because targeted email segments buyers by past behaviour, dramatically lowering cost per conversion and enabling precise analytics.","B":"Incorrect because offline households are reached by printed mail rather than email.","C":"Incorrect because spam filters and inbox clutter remain challenges if emails are irrelevant.","D":"Incorrect because businesses must comply with data protection and opt-in consent laws."}}},{"id":"P1_U3_MCQ_098","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_098","question":"A B2B cybersecurity software firm exhibits at an international banking technology trade fair. Which promotional strengths does a trade fair offer?","options":{"A":"Complete secrecy from competitors attending the same industry","B":"Reaching millions of children watching Saturday morning cartoons","C":"Zero exhibition booth rental or staff travel expenses","D":"Concentrated face-to-face access to pre-qualified corporate decision-makers and live software demonstrations"},"correctOption":"D","correctAnswer":"Concentrated face-to-face access to pre-qualified corporate decision-makers and live software demonstrations","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because trade fairs gather serious industry buyers in one venue, supporting high-value personal selling and product demos.","distractor_reasons":{"A":"Incorrect because rivals also attend trade fairs and observe industry launches.","B":"Incorrect because banking trade fairs target corporate executives, not general child consumers.","C":"Incorrect because trade fair stands and travel carry substantial costs.","D":"Option D is correct because trade fairs gather serious industry buyers in one venue, supporting high-value personal selling and product demos."}}},{"id":"P1_U3_MCQ_099","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_099","question":"Why do loyalty card schemes (such as earning points per dollar spent for future store vouchers) serve as both a 'sales promotion' and a 'market research' tool?","options":{"A":"Loyalty cards legally prevent customers from ever visiting a competing supermarket","B":"Points incentivize repeat customer visits while checkout scans automatically record detailed buying patterns for segmentation","C":"Loyalty cards eliminate the need to price products competitively","D":"Loyalty schemes cost the retailer nothing to administer or redeem"},"correctOption":"B","correctAnswer":"Points incentivize repeat customer visits while checkout scans automatically record detailed buying patterns for segmentation","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because reward points encourage retention while basket data generates continuous internal secondary research.","distractor_reasons":{"A":"Incorrect because shoppers remain free to shop at multiple retailers.","B":"Option B is correct because reward points encourage retention while basket data generates continuous internal secondary research.","C":"Incorrect because core shelf prices must still remain competitive.","D":"Incorrect because IT systems and voucher redemptions represent real promotional costs."}}},{"id":"P1_U3_MCQ_100","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_100","question":"When choosing promotional media for a complex pension and life-insurance plan aimed at middle-aged professionals, why are detailed financial newspaper articles and advisor consultations more effective than 6-second social media clips?","options":{"A":"Middle-aged professionals are legally banned from using smartphones","B":"High-involvement financial services require detailed explanation, credibility, and personal reassurance rather than brief impulse entertainment","C":"Newspaper advertisements are always cheaper than short social media posts","D":"Financial services never require regulatory risk disclosures"},"correctOption":"B","correctAnswer":"High-involvement financial services require detailed explanation, credibility, and personal reassurance rather than brief impulse entertainment","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because complex, long-term financial commitments demand trust and thorough information that ultra-short clips cannot convey.","distractor_reasons":{"A":"Incorrect because professionals use smartphones, though they rely on credible sources for major financial choices.","B":"Option B is correct because complex, long-term financial commitments demand trust and thorough information that ultra-short clips cannot convey.","C":"Incorrect because print ads in major newspapers are typically costlier than social posts.","D":"Incorrect because financial promotions require clear regulatory disclosures."}}},{"id":"P1_U3_MCQ_101","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_101","question":"A luxury Swiss watchmaker sells watches at $15,000 through exclusive boutiques, yet promotes them with 'Buy One, Get One Free' flyers distributed outside subway stations. Why is this marketing strategy ineffective?","options":{"A":"Flyers are illegal to distribute in major cities","B":"Luxury watches are always bought as impulse purchases by subway commuters","C":"Exclusive boutiques require heavy discount coupons to attract wealthy buyers","D":"The four elements of the marketing mix conflict: discount subway flyers undermine the luxury Product, high Price, and exclusive Place positioning"},"correctOption":"D","correctAnswer":"The four elements of the marketing mix conflict: discount subway flyers undermine the luxury Product, high Price, and exclusive Place positioning","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because an effective marketing strategy requires all elements of the 4Ps to align consistently around the target segment's expectations.","distractor_reasons":{"A":"Incorrect because the flaw is strategic inconsistency rather than illegality.","B":"Incorrect because $15,000 watches are high-involvement luxury purchases.","C":"Incorrect because BOGOF promotions cheapen luxury prestige.","D":"Option D is correct because an effective marketing strategy requires all elements of the 4Ps to align consistently around the target segment's expectations."}}},{"id":"P1_U3_MCQ_102","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_102","question":"A budget gym chain targets price-conscious students and young workers with no-frills 24-hour facilities. Which integrated marketing mix best supports its strategy?","options":{"A":"Penetration pricing followed by an immediate 400% price hike in month two","B":"High $300 monthly fees, personal butler service, and print adverts in private-jet magazines","C":"Low monthly membership fees, digital self-service sign-ups, and targeted social media referral promotions","D":"Exclusive invitation-only memberships sold through luxury hotel concierges"},"correctOption":"C","correctAnswer":"Low monthly membership fees, digital self-service sign-ups, and targeted social media referral promotions","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because affordable pricing, automated low-overhead operations, and digital youth marketing reinforce a coherent cost-focused strategy.","distractor_reasons":{"A":"Incorrect because extreme sudden price hikes cause immediate membership cancellations.","B":"Incorrect because luxury pricing and butler service target wealthy segments rather than budget students.","C":"Option C is correct because affordable pricing, automated low-overhead operations, and digital youth marketing reinforce a coherent cost-focused strategy.","D":"Incorrect because exclusive hotel concierges misalign with a mass-budget gym."}}},{"id":"P1_U3_MCQ_103","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_103","question":"As household budgets tighten, a mid-priced family restaurant changes its menu and decor to be seen as an affordable treat for families. Which element of marketing strategy is this?","options":{"A":"Market segmentation","B":"Market positioning","C":"Product lifecycle","D":"Target marketing"},"correctOption":"B","correctAnswer":"Market positioning","questionType":"MCQ","explanation":{"correct_reason":"Repositioning means changing how a product is perceived in customers' minds relative to rivals; presenting the restaurant as an affordable family treat is a change of market position.","distractor_reasons":{"A":"Segmentation divides customers into distinct groups; the question is about changing perception, not dividing the market.","B":"This is correct: the restaurant is deliberately changing its market positioning.","C":"The product lifecycle describes stages from launch to decline, not a deliberate change of image.","D":"Target marketing means choosing which group to serve; here the change concerns the image presented."}}},{"id":"P1_U3_MCQ_104","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_104","question":"Why might a consumer-goods manufacturer expand into 'foreign markets' even when its domestic market is still profitable?","options":{"A":"To achieve faster sales growth, spread risk across multiple economies, and gain further economies of scale","B":"Because foreign markets never have local competitors or cultural differences","C":"Because exporting eliminates all shipping, insurance, and currency-exchange risks","D":"Because domestic consumer protection laws stop applying once a firm exports"},"correctOption":"A","correctAnswer":"To achieve faster sales growth, spread risk across multiple economies, and gain further economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because international expansion opens larger customer bases, reduces reliance on one home economy, and extends product life cycles.","distractor_reasons":{"A":"Option A is correct because international expansion opens larger customer bases, reduces reliance on one home economy, and extends product life cycles.","B":"Incorrect because foreign markets feature strong local rivals and distinct cultural preferences.","C":"Incorrect because international trade adds freight, tariff, and exchange-rate complexities.","D":"Incorrect because firms must obey both domestic and foreign market regulations."}}},{"id":"P1_U3_MCQ_105","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_105","question":"What is a major challenge for a Western food manufacturer entering an East Asian retail market for the first time?","options":{"A":"International shipping containers are legally banned from carrying processed foods","B":"Consumers in East Asia never buy packaged supermarket foods","C":"Adapting recipes, packaging colours, and brand names to local cultural tastes, languages, and food-safety regulations","D":"Foreign companies are forbidden from conducting market research abroad"},"correctOption":"C","correctAnswer":"Adapting recipes, packaging colours, and brand names to local cultural tastes, languages, and food-safety regulations","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because cultural differences in flavour preferences, symbolism, and labelling laws require careful product and promotional localization.","distractor_reasons":{"A":"Incorrect because containerized food trade is standard globally.","B":"Incorrect because East Asia has massive, modern retail grocery markets.","C":"Option C is correct because cultural differences in flavour preferences, symbolism, and labelling laws require careful product and promotional localization.","D":"Incorrect because cross-cultural market research is essential and widely practiced."}}},{"id":"P1_U3_MCQ_106","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_106","question":"How does forming a 'joint venture' with a local partner help a European supermarket chain enter a complex foreign market?","options":{"A":"The local partner contributes established supply chains, regulatory knowledge, and cultural insight while sharing capital costs and risks","B":"The European chain keeps 100% of all profits without sharing any decision-making","C":"A joint venture guarantees that cultural disagreements between partners never arise","D":"The European chain avoids investing any capital or management expertise"},"correctOption":"A","correctAnswer":"The local partner contributes established supply chains, regulatory knowledge, and cultural insight while sharing capital costs and risks","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because pooling resources with a domestic company overcomes local regulatory and cultural barriers faster than going alone.","distractor_reasons":{"A":"Option A is correct because pooling resources with a domestic company overcomes local regulatory and cultural barriers faster than going alone.","B":"Incorrect because profits and control are shared between the joint-venture partners.","C":"Incorrect because differing management cultures and profit priorities are key risks of joint ventures.","D":"Incorrect because both partners contribute capital and capabilities."}}},{"id":"P1_U3_MCQ_107","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_107","question":"What is a primary disadvantage of entering a foreign market through a 'joint venture'?","options":{"A":"Joint ventures are illegal in all emerging economies","B":"The foreign entrant must bear 100% of the financial startup risk alone","C":"The business gains zero access to the local partner's distribution network","D":"Disagreements over strategy, profit reinvestment, or quality standards between the two partner companies can slow decisions"},"correctOption":"D","correctAnswer":"Disagreements over strategy, profit reinvestment, or quality standards between the two partner companies can slow decisions","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because shared ownership requires consensus, and clashes in corporate culture or strategic goals can undermine performance.","distractor_reasons":{"A":"Incorrect because many countries actively encourage foreign-local joint ventures.","B":"Incorrect because risk sharing is an advantage of joint ventures.","C":"Incorrect because accessing local networks is a primary benefit.","D":"Option D is correct because shared ownership requires consensus, and clashes in corporate culture or strategic goals can undermine performance."}}},{"id":"P1_U3_MCQ_108","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_108","question":"A popular animated-film studio grants a foreign toy manufacturer legal permission to produce and sell branded action figures in exchange for a royalty fee on sales. Which international entry method is this?","options":{"A":"Licensing","B":"Wholly owned foreign subsidiary","C":"Direct mail exporting","D":"Horizontal merger"},"correctOption":"A","correctAnswer":"Licensing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because licensing allows a foreign licensee to use intellectual property (characters, patents, trademarks) locally for royalty payments without the licensor building factories.","distractor_reasons":{"A":"Option A is correct because licensing allows a foreign licensee to use intellectual property (characters, patents, trademarks) locally for royalty payments without the licensor building factories.","B":"Incorrect because a wholly owned subsidiary requires building or buying foreign operations directly.","C":"Incorrect because direct exporting ships home-made goods abroad rather than licensing local production.","D":"Incorrect because a merger combines two firms into one corporate entity."}}},{"id":"P1_U3_MCQ_109","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_109","question":"What is a key risk for a brand owner using 'licensing' to expand into overseas markets?","options":{"A":"If the foreign licensee produces poor-quality goods, the original brand's global reputation can suffer damage","B":"The brand owner must fund 100% of the foreign factory construction costs","C":"The brand owner receives no royalty income when foreign sales grow","D":"Licensing exposes the brand owner to high international shipping tariffs on finished goods"},"correctOption":"A","correctAnswer":"If the foreign licensee produces poor-quality goods, the original brand's global reputation can suffer damage","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because delegating production to an independent licensee reduces direct quality control and risks creating a future competitor.","distractor_reasons":{"A":"Option A is correct because delegating production to an independent licensee reduces direct quality control and risks creating a future competitor.","B":"Incorrect because the local licensee funds its own production facilities.","C":"Incorrect because royalties are typically calculated as a percentage of licensee sales.","D":"Incorrect because local production under license avoids finished-good import tariffs."}}},{"id":"P1_U3_MCQ_110","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_110","question":"A US coffee-house brand expands into 25 countries by selling local entrepreneurs the right to operate stores under its brand name, store layout, and training manual. Which expansion strategy is this?","options":{"A":"International franchising","B":"Commission-agent exporting","C":"Unbranded wholesale distribution","D":"Product orientation"},"correctOption":"A","correctAnswer":"International franchising","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because franchising replicates a complete business format rapidly abroad using franchisee capital and local management.","distractor_reasons":{"A":"Option A is correct because franchising replicates a complete business format rapidly abroad using franchisee capital and local management.","B":"Incorrect because agents negotiate product orders rather than operating branded retail cafés.","C":"Incorrect because franchises rely heavily on uniform brand identity.","D":"Incorrect because product orientation describes engineering focus rather than an entry method."}}},{"id":"P1_U3_MCQ_111","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_111","question":"An exporter ships bicycles valued at $200 each to a foreign country that imposes a 15% import tariff on bicycles. What is the landed cost per bicycle after the tariff is added?","options":{"A":"$170","B":"$215","C":"$230","D":"$300"},"correctOption":"C","correctAnswer":"$230","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Tariff = 15% of $200 = $30; Landed Cost = $200 + $30 = $230, making the imported bicycle less price-competitive.","distractor_reasons":{"A":"Incorrect because $170 subtracts $30 instead of adding the import tax.","B":"Incorrect because $215 adds $15 flat rather than 15% of $200.","C":"Option C is correct because Tariff = 15% of $200 = $30; Landed Cost = $200 + $30 = $230, making the imported bicycle less price-competitive.","D":"Incorrect because $300 adds a 50% tariff instead of 15%."}}},{"id":"P1_U3_MCQ_112","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_112","question":"How does a 'trade bloc' (such as a customs union or free-trade area) benefit a manufacturer exporting to member countries within that bloc?","options":{"A":"Competitors inside the trade bloc are forbidden from advertising","B":"All member countries automatically speak the exact same language and share identical consumer tastes","C":"Transport distances between member countries are reduced to zero","D":"Tariffs and import quotas between member states are eliminated, keeping export prices competitive"},"correctOption":"D","correctAnswer":"Tariffs and import quotas between member states are eliminated, keeping export prices competitive","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because free-trade agreements remove tariff barriers among members, lowering cross-border trading costs.","distractor_reasons":{"A":"Incorrect because trade blocs actually intensify competition among member firms.","B":"Incorrect because cultural and linguistic differences still exist across member states.","C":"Incorrect because physical geography and freight costs remain.","D":"Option D is correct because free-trade agreements remove tariff barriers among members, lowering cross-border trading costs."}}},{"id":"P1_U3_MCQ_113","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_113","question":"A cosmetics company advertises a face cream claiming it 'permanently erases all wrinkles in 24 hours,' despite zero clinical evidence. Which legal control over marketing is being breached?","options":{"A":"Import quota tariff regulations","B":"Minimum wage employment legislation","C":"Trade union collective bargaining rules","D":"Misleading advertising and false product description laws"},"correctOption":"D","correctAnswer":"Misleading advertising and false product description laws","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because consumer protection and advertising standards laws prohibit false, unsubstantiated performance claims.","distractor_reasons":{"A":"Incorrect because import tariffs govern cross-border trade taxes.","B":"Incorrect because minimum wage laws govern employee pay rather than advert claims.","C":"Incorrect because union rules govern industrial relations.","D":"Option D is correct because consumer protection and advertising standards laws prohibit false, unsubstantiated performance claims."}}},{"id":"P1_U3_MCQ_114","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_114","question":"A customer buys a brand-new washing machine that stops spinning after two weeks due to a factory wiring fault, and the retailer refuses to repair, replace, or refund it. Which consumer protection principle is violated?","options":{"A":"Goods sold must be of satisfactory quality and fit for their intended purpose","B":"Retailers must guarantee that every customer enjoys the colour of the appliance","C":"Manufacturers must sell all appliances at zero profit margin","D":"Customers are entitled to unlimited free electricity for five years"},"correctOption":"A","correctAnswer":"Goods sold must be of satisfactory quality and fit for their intended purpose","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because consumer protection laws grant buyers statutory remedies when faulty goods fail to perform their normal function.","distractor_reasons":{"A":"Option A is correct because consumer protection laws grant buyers statutory remedies when faulty goods fail to perform their normal function.","B":"Incorrect because subjective colour preference is not a statutory defect.","C":"Incorrect because businesses may earn normal profits.","D":"Incorrect because utility bills are unrelated to appliance quality laws."}}},{"id":"P1_U3_MCQ_115","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_115","question":"Why do consumer protection laws require packaged foods to display accurate net weights, ingredient lists, and allergen warnings?","options":{"A":"To eliminate the need for supermarket barcode scanners","B":"To make food packaging more expensive for small bakeries","C":"To prevent deceptive short-weighing and protect consumers with severe food allergies from dangerous health risks","D":"To allow manufacturers to substitute cheaper ingredients secretly"},"correctOption":"C","correctAnswer":"To prevent deceptive short-weighing and protect consumers with severe food allergies from dangerous health risks","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because weights-and-measures and labelling laws ensure fair value for money and vital consumer safety transparency.","distractor_reasons":{"A":"Incorrect because barcodes remain standard for retail checkout.","B":"Incorrect because cost increases are a compliance side-effect, not the purpose of the law.","C":"Option C is correct because weights-and-measures and labelling laws ensure fair value for money and vital consumer safety transparency.","D":"Incorrect because accurate labelling specifically prevents hidden ingredient substitution."}}},{"id":"P1_U3_MCQ_116","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_116","question":"How do 'legal controls over marketing' affect a business's costs and marketing decisions?","options":{"A":"Legal controls apply only to online retailers and exempt physical high-street shops","B":"Legal controls reduce compliance costs to zero and allow unrestricted promotional claims","C":"Compliance raises packaging, testing, and legal review costs, yet protects the brand from heavy fines, product recalls, and lost customer trust","D":"Legal controls eliminate all competition within the industry"},"correctOption":"C","correctAnswer":"Compliance raises packaging, testing, and legal review costs, yet protects the brand from heavy fines, product recalls, and lost customer trust","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because adhering to safety and advertising rules requires upfront expenditure, while preventing far costlier legal penalties and reputational collapse.","distractor_reasons":{"A":"Incorrect because consumer protection applies across both online and physical channels.","B":"Incorrect because compliance involves real testing and legal review costs.","C":"Option C is correct because adhering to safety and advertising rules requires upfront expenditure, while preventing far costlier legal penalties and reputational collapse.","D":"Incorrect because regulation sets fair standards rather than eliminating rivals."}}},{"id":"P1_U3_MCQ_117","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_117","question":"A supermarket advertises a 'Was $100, Now $60' blender discount, even though the blender was never sold at $100 in any of its stores. Why is this practice unlawful in many countries?","options":{"A":"Supermarkets are legally forbidden from ever discounting kitchen appliances","B":"Deceptive price-comparison claims mislead consumers about genuine savings and breach fair-trading regulations","C":"All blenders must be sold using cost-plus pricing by law","D":"Consumers are prohibited from comparing prices across different stores"},"correctOption":"B","correctAnswer":"Deceptive price-comparison claims mislead consumers about genuine savings and breach fair-trading regulations","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because fictitious 'was/now' reference prices deceive shoppers and violate consumer protection rules against misleading pricing.","distractor_reasons":{"A":"Incorrect because genuine discounts are completely lawful.","B":"Option B is correct because fictitious 'was/now' reference prices deceive shoppers and violate consumer protection rules against misleading pricing.","C":"Incorrect because firms choose their own pricing methods within fair-trading rules.","D":"Incorrect because price comparison is encouraged."}}},{"id":"P1_U3_MCQ_118","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_118","question":"An online retailer automatically ticks a hidden checkout box adding a $15 monthly subscription fee to customers' baskets unless they spot and untick it. Which legal issue does this violate?","options":{"A":"Consumer contract laws requiring clear, explicit opt-in consent before charging for additional items","B":"Workplace health and safety machinery rules","C":"International patent licensing treaties","D":"Quota sampling guidelines for street surveys"},"correctOption":"A","correctAnswer":"Consumer contract laws requiring clear, explicit opt-in consent before charging for additional items","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because modern e-commerce consumer laws ban pre-ticked hidden charges and require transparent pricing upfront.","distractor_reasons":{"A":"Option A is correct because modern e-commerce consumer laws ban pre-ticked hidden charges and require transparent pricing upfront.","B":"Incorrect because workplace safety rules govern employee physical safety.","C":"Incorrect because patent treaties protect inventions.","D":"Incorrect because quota sampling relates to market research."}}},{"id":"P1_U3_MCQ_119","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_119","question":"Why do consumer laws in many jurisdictions give online shoppers a 'cooling-off period' (e.g., 14 days) to return goods bought at a distance?","options":{"A":"To force all online businesses to close their websites and open physical shops","B":"Because online retailers never display product photos or descriptions","C":"Because online buyers cannot physically inspect or test products before purchase, reducing perceived buying risk and encouraging e-commerce trust","D":"Because postal delivery companies lose 50% of all parcels"},"correctOption":"C","correctAnswer":"Because online buyers cannot physically inspect or test products before purchase, reducing perceived buying risk and encouraging e-commerce trust","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because statutory return rights compensate for the inability to examine goods in person prior to ordering.","distractor_reasons":{"A":"Incorrect because cooling-off rules actually boost consumer confidence to shop online.","B":"Incorrect because online stores provide photos and specs, yet physical inspection remains impossible.","C":"Option C is correct because statutory return rights compensate for the inability to examine goods in person prior to ordering.","D":"Incorrect because parcel loss is handled separately from cooling-off return rights."}}},{"id":"P1_U3_MCQ_120","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_120","question":"A toy manufacturer discovers that a small detachable wheel on its new toddler truck poses a choking hazard. Rather than waiting for regulators to act, it immediately announces a voluntary public recall and full refund. How does this protect long-term marketing strategy?","options":{"A":"Issuing a recall exempts the company from future safety testing","B":"Voluntary recalls eliminate all short-term refund and logistics costs","C":"Proactive accountability demonstrates ethical responsibility, prevents injuries, and preserves long-term parent trust in the brand","D":"Product recalls immediately double current-month sales revenue"},"correctOption":"C","correctAnswer":"Proactive accountability demonstrates ethical responsibility, prevents injuries, and preserves long-term parent trust in the brand","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because transparent, swift action protects child safety and prevents far worse reputational ruin from a cover-up.","distractor_reasons":{"A":"Incorrect because safety standards remain strictly enforced.","B":"Incorrect because recalls incur substantial short-term refund and collection expenses.","C":"Option C is correct because transparent, swift action protects child safety and prevents far worse reputational ruin from a cover-up.","D":"Incorrect because recalls temporarily reduce sales while protecting long-term brand survival."}}},{"id":"P1_U3_MCQ_121","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_121","question":"A domestic electric-scooter startup wants to enter a neighbouring country quickly with limited capital, but faces unfamiliar local traffic laws and retail networks. Which entry strategy is most suitable?","options":{"A":"Forming a joint venture or appointing a local distributor/agent with established regulatory and retail connections","B":"Building a wholly owned gigafactory abroad before conducting any market research","C":"Using mass-market TV adverts in its home language without local translation","D":"Ignoring foreign scooter safety regulations to save testing costs"},"correctOption":"A","correctAnswer":"Forming a joint venture or appointing a local distributor/agent with established regulatory and retail connections","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because partnering with a local firm or distributor provides immediate market knowledge and shared investment when capital is constrained.","distractor_reasons":{"A":"Option A is correct because partnering with a local firm or distributor provides immediate market knowledge and shared investment when capital is constrained.","B":"Incorrect because building a wholly owned foreign factory requires huge capital and carries high risk without local insight.","C":"Incorrect because untranslated home-market TV ads fail to connect with foreign buyers.","D":"Incorrect because breaching local safety rules leads to import bans and fines."}}},{"id":"P1_U3_MCQ_122","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_122","question":"When developing a 'marketing strategy' to enter a mature, highly competitive domestic market with a new brand of mineral water, which factor is most critical to evaluate?","options":{"A":"Whether competitors use random or quota sampling in their internal HR surveys","B":"Whether the factory uses time-rate or piece-rate wages for warehouse cleaners","C":"Whether the company's head office has a flat or tall span of control","D":"Whether the product has a clear USP (such as eco-packaging or added electrolytes) and sufficient promotional budget to win shelf space from entrenched rivals"},"correctOption":"D","correctAnswer":"Whether the product has a clear USP (such as eco-packaging or added electrolytes) and sufficient promotional budget to win shelf space from entrenched rivals","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because breaking into a saturated market requires meaningful differentiation and strong promotional/distribution backing.","distractor_reasons":{"A":"Incorrect because HR survey sampling is unrelated to winning retail shelf space.","B":"Incorrect because internal cleaner wage systems do not determine external market entry success.","C":"Incorrect because internal span of control is an HR/organisational factor rather than a market-entry determinant.","D":"Option D is correct because breaking into a saturated market requires meaningful differentiation and strong promotional/distribution backing."}}},{"id":"P1_U3_MCQ_123","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_123","question":"How does a strong 'social media customer-support and community strategy' reinforce the other elements of a brand's marketing mix?","options":{"A":"It provides real-time customer feedback to improve Product features, communicates Promotional offers, and drives traffic to e-commerce Place channels","B":"It eliminates the need to manufacture reliable products or price them fairly","C":"It replaces all physical delivery logistics for tangible goods","D":"It exempts the business from consumer refund and advertising laws"},"correctOption":"A","correctAnswer":"It provides real-time customer feedback to improve Product features, communicates Promotional offers, and drives traffic to e-commerce Place channels","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because digital engagement connects ongoing market research, promotion, and online distribution into a cohesive customer experience.","distractor_reasons":{"A":"Option A is correct because digital engagement connects ongoing market research, promotion, and online distribution into a cohesive customer experience.","B":"Incorrect because product quality and fair pricing remain foundational.","C":"Incorrect because physical goods still require freight and parcel delivery.","D":"Incorrect because online channels remain fully subject to consumer protection laws."}}},{"id":"P1_U3_MCQ_124","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_124","question":"A solar-lantern manufacturer targets off-grid rural households in developing regions. Which coordinated 4Ps marketing strategy best fits this target segment?","options":{"A":"Durable weatherproof lantern design, affordable micro-instalment pricing, distribution via local rural cooperatives, and live village demonstrations","B":"Fragile glass designer lamps priced at $800, sold exclusively in luxury airport duty-free shops","C":"Subscription-only smartphone app controls requiring high-speed fiber broadband","D":"High-price skimming aimed at urban luxury penthouse owners"},"correctOption":"A","correctAnswer":"Durable weatherproof lantern design, affordable micro-instalment pricing, distribution via local rural cooperatives, and live village demonstrations","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rugged product design, accessible payment terms, local rural distribution, and hands-on demos directly address rural off-grid customer needs.","distractor_reasons":{"A":"Option A is correct because rugged product design, accessible payment terms, local rural distribution, and hands-on demos directly address rural off-grid customer needs.","B":"Incorrect because luxury airport retail and $800 pricing do not reach rural off-grid households.","C":"Incorrect because off-grid rural communities lack fiber internet infrastructure.","D":"Incorrect because urban penthouse owners are a completely different target segment."}}},{"id":"P1_U3_MCQ_125","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_125","question":"Why must a business continuously review and adapt its 'marketing strategy' even after achieving market leadership?","options":{"A":"Because consumer tastes, competitor actions, technology, and economic or legal conditions constantly evolve, making static strategies obsolete","B":"Because government regulations force market leaders to change their brand logos every six months","C":"Because products in the maturity stage never experience competition or decline","D":"Because market research becomes illegal once a firm reaches a 30% market share"},"correctOption":"A","correctAnswer":"Because consumer tastes, competitor actions, technology, and economic or legal conditions constantly evolve, making static strategies obsolete","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because dynamic external markets require ongoing research, product renewal, and agile marketing mix adjustments to sustain competitive advantage.","distractor_reasons":{"A":"Option A is correct because dynamic external markets require ongoing research, product renewal, and agile marketing mix adjustments to sustain competitive advantage.","B":"Incorrect because governments do not mandate periodic logo redesigns.","C":"Incorrect because mature markets face intense competition and eventual decline without extension strategies.","D":"Incorrect because market research remains lawful and essential at every market share level."}}},{"id":"P1_U3_MCQ_126","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_126","question":"A subscription meal-kit company finds that spending $15 on loyalty perks for existing subscribers retains far more revenue than spending $60 per advert to attract first-time buyers. Which core marketing principle does this demonstrate?","options":{"A":"Acquiring brand-new customers is always cheaper than keeping existing buyers","B":"Maintaining customer loyalty is more cost-effective and profitable over time than constantly replacing lost customers","C":"Existing subscribers never care about meal quality or delivery punctuality","D":"Marketing departments should stop advertising completely once they reach 1,000 subscribers"},"correctOption":"B","correctAnswer":"Maintaining customer loyalty is more cost-effective and profitable over time than constantly replacing lost customers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because retaining satisfied repeat buyers lowers promotional acquisition costs and generates steady long-term revenue.","distractor_reasons":{"A":"Incorrect because attracting new buyers usually costs significantly more than retaining current customers.","B":"Option B is correct because retaining satisfied repeat buyers lowers promotional acquisition costs and generates steady long-term revenue.","C":"Incorrect because customer retention depends directly on consistent product quality and reliable service.","D":"Incorrect because businesses still need ongoing promotion to remind customers and replace natural churn."}}},{"id":"P1_U3_MCQ_127","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_127","question":"In a national organic-juice market worth $150 million annually, GreenSip Ltd records annual sales revenue of $18 million. What is GreenSip Ltd's market share?","options":{"A":"8.3%","B":"18.0%","C":"12.0%","D":"27.0%"},"correctOption":"C","correctAnswer":"12.0%","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Market Share (%) = ($18m / $150m) × 100 = 12.0%.","distractor_reasons":{"A":"Incorrect because 8.3% divides $150m by $18m instead of $18m by $150m.","B":"Incorrect because 18.0% confuses dollar sales ($18m) with percentage share.","C":"Option C is correct because Market Share (%) = ($18m / $150m) × 100 = 12.0%.","D":"Incorrect because 27.0% multiplies 18 by 1.5 instead of dividing."}}},{"id":"P1_U3_MCQ_128","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_128","question":"During an economic downturn, total national sales in the printed-newspaper market fall by 12%, while DailyChronicle Ltd's sales revenue falls by only 4%. How has DailyChronicle Ltd's market share changed?","options":{"A":"Its market share fell by 8% because its sales dropped","B":"Its market share remained completely unchanged","C":"Its market share fell to zero due to industry contraction","D":"Its market share increased because its sales declined more slowly than the overall market"},"correctOption":"D","correctAnswer":"Its market share increased because its sales declined more slowly than the overall market","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because outperforming the industry average—even during a market contraction—gives the firm a larger proportion of total remaining market sales.","distractor_reasons":{"A":"Incorrect because its competitors lost sales at a faster rate than DailyChronicle Ltd.","B":"Incorrect because different percentage changes between firm sales and total market sales alter market share.","C":"Incorrect because the firm retained 96% of its previous sales.","D":"Option D is correct because outperforming the industry average—even during a market contraction—gives the firm a larger proportion of total remaining market sales."}}},{"id":"P1_U3_MCQ_129","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_129","question":"A household cleaning-products firm observes consumers increasingly rejecting single-use plastic spray bottles in favour of concentrated refill tablets. Which driver of changing consumer spending patterns is influencing this market?","options":{"A":"An increase in the average age of retirement","B":"A sudden collapse in average household disposable incomes","C":"Government bans on cleaning domestic kitchens and bathrooms","D":"Growing environmental awareness and ethical concern over plastic waste"},"correctOption":"D","correctAnswer":"Growing environmental awareness and ethical concern over plastic waste","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because heightened ecological concern changes buyer preferences toward sustainable, low-waste alternatives.","distractor_reasons":{"A":"Incorrect because retirement age changes do not explain anti-plastic packaging trends.","B":"Incorrect because switching from plastic bottles to eco-refills reflects sustainability preferences rather than falling incomes.","C":"Incorrect because no such ban exists.","D":"Option D is correct because heightened ecological concern changes buyer preferences toward sustainable, low-waste alternatives."}}},{"id":"P1_U3_MCQ_130","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_130","question":"In several developed countries, healthcare providers, hearing-aid makers, and luxury river-cruise operators experience rapid long-term demand growth. Which demographic shift best explains this trend?","options":{"A":"Rising birth rates increasing the proportion of infants in the population","B":"An ageing population with higher life expectancy and greater numbers of retired consumers","C":"Rapid migration of teenagers into primary schools","D":"Declining average life expectancy across all income groups"},"correctOption":"B","correctAnswer":"An ageing population with higher life expectancy and greater numbers of retired consumers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because an expanding over-65 demographic boosts spending on medical care, mobility aids, and leisure travel.","distractor_reasons":{"A":"Incorrect because higher birth rates raise demand for baby products rather than hearing aids and cruises.","B":"Option B is correct because an expanding over-65 demographic boosts spending on medical care, mobility aids, and leisure travel.","C":"Incorrect because school-age demographics drive demand for education and youth goods.","D":"Incorrect because declining life expectancy would shrink the senior consumer segment."}}},{"id":"P1_U3_MCQ_131","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_131","question":"A domestic furniture maker that once dominated its local city now faces intense pressure from overseas flat-pack brands and online comparison sites. Why have many markets become significantly more competitive?","options":{"A":"Governments have banned businesses from using internet websites to sell goods","B":"Transport costs have risen so high that international trade has stopped","C":"Globalization, lower trade barriers, and e-commerce price transparency have exposed local firms to global rivals","D":"Consumers no longer compare product prices or quality before purchasing"},"correctOption":"C","correctAnswer":"Globalization, lower trade barriers, and e-commerce price transparency have exposed local firms to global rivals","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because international trade agreements, cheaper logistics, and digital platforms allow foreign and online competitors to enter local markets easily.","distractor_reasons":{"A":"Incorrect because e-commerce is actively used worldwide.","B":"Incorrect because modern shipping and digital platforms facilitate global trade.","C":"Option C is correct because international trade agreements, cheaper logistics, and digital platforms allow foreign and online competitors to enter local markets easily.","D":"Incorrect because digital tools make price and review comparisons easier than ever."}}},{"id":"P1_U3_MCQ_132","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_132","question":"When rival streaming platforms enter its market with lower monthly fees, an established entertainment company invests heavily in exclusive original dramas and ultra-HD streaming quality. How is it responding to competition?","options":{"A":"By abandoning product development to focus solely on cost cutting","B":"By reducing content variety while doubling subscription prices","C":"By switching from mass marketing to a tiny local geographic niche","D":"By differentiating its product quality and exclusive features so subscribers stay loyal despite cheaper rivals"},"correctOption":"D","correctAnswer":"By differentiating its product quality and exclusive features so subscribers stay loyal despite cheaper rivals","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because exclusive content creates a strong Unique Selling Point (USP) that reduces price sensitivity against low-cost competitors.","distractor_reasons":{"A":"Incorrect because funding original dramas represents major product investment.","B":"Incorrect because the firm expanded exclusive content rather than cutting variety.","C":"Incorrect because global streaming platforms operate across broad mass audiences.","D":"Option D is correct because exclusive content creates a strong Unique Selling Point (USP) that reduces price sensitivity against low-cost competitors."}}},{"id":"P1_U3_MCQ_133","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_133","question":"A small independent bakery specializes exclusively in certified gluten-free, nut-free birthday cakes for children with severe food allergies. Why does this 'niche marketing' approach suit a small business?","options":{"A":"It guarantees that no other bakery will ever learn how to bake gluten-free cakes","B":"It allows the bakery to produce millions of identical plain loaves using automated flow lines","C":"It avoids head-on price battles with giant supermarket bakeries and meets an urgent, specific need that parents gladly pay a premium for","D":"It eliminates the need to follow food hygiene and allergen labelling laws"},"correctOption":"C","correctAnswer":"It avoids head-on price battles with giant supermarket bakeries and meets an urgent, specific need that parents gladly pay a premium for","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because specialized niches shelter small firms from mass-market giants while supporting strong profit margins through tailored value.","distractor_reasons":{"A":"Incorrect because niche markets carry no permanent legal protection against future entrants.","B":"Incorrect because automated mass production describes mass marketing.","C":"Option C is correct because specialized niches shelter small firms from mass-market giants while supporting strong profit margins through tailored value.","D":"Incorrect because allergen safety laws are especially strict for allergy-free foods."}}},{"id":"P1_U3_MCQ_134","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_134","question":"A boutique manufacturer of custom carbon-fibre racing bicycles produces only 300 frames per year. What cost disadvantage does this 'niche market' strategy typically create?","options":{"A":"Excessive spending on nationwide television commercials during prime-time broadcasts","B":"Higher average unit production costs due to small batch sizes and inability to gain mass purchasing economies of scale","C":"Over-reliance on selling cheap unbranded bicycles through discount supermarkets","D":"Inability to communicate directly with cycling enthusiasts"},"correctOption":"B","correctAnswer":"Higher average unit production costs due to small batch sizes and inability to gain mass purchasing economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because low output volumes prevent bulk raw-material discounts and spread fixed tooling costs over fewer units.","distractor_reasons":{"A":"Incorrect because niche firms use targeted cycling magazines and clubs rather than mass TV ads.","B":"Option B is correct because low output volumes prevent bulk raw-material discounts and spread fixed tooling costs over fewer units.","C":"Incorrect because niche firms sell specialized high-value items rather than supermarket generics.","D":"Incorrect because niche businesses usually maintain close, direct ties with their specialist buyers."}}},{"id":"P1_U3_MCQ_135","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_135","question":"A global battery maker sells standard AA alkaline batteries to households, offices, and schools worldwide. What is a major advantage of this 'mass marketing' strategy?","options":{"A":"Zero competition from any rival battery brands","B":"Complete customization of battery chemical formulas for every individual buyer","C":"A huge customer base that spreads risk and supports large-scale, low-unit-cost automated manufacturing","D":"Ability to charge luxury boutique prices ten times higher than rivals"},"correctOption":"C","correctAnswer":"A huge customer base that spreads risk and supports large-scale, low-unit-cost automated manufacturing","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because broad universal demand reduces dependence on any single tiny segment and maximizes economies of scale.","distractor_reasons":{"A":"Incorrect because mass markets typically feature intense competition.","B":"Incorrect because mass marketing relies on standardized products.","C":"Option C is correct because broad universal demand reduces dependence on any single tiny segment and maximizes economies of scale.","D":"Incorrect because standardized mass-market commodities face strong price competition."}}},{"id":"P1_U3_MCQ_136","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_136","question":"A shampoo brand sells a single 'one-size-fits-all' formula across the entire country, but loses sales to rivals offering specialized shampoos for curly, dyed, and sensitive scalps. Which weakness of 'mass marketing' does this reveal?","options":{"A":"Unit manufacturing costs are always higher than in niche markets","B":"Standardized products cannot be advertised on national television","C":"Mass-market retailers refuse to stock single-formula products","D":"A standardized product fails to satisfy consumers who want solutions tailored to their specific individual needs"},"correctOption":"D","correctAnswer":"A standardized product fails to satisfy consumers who want solutions tailored to their specific individual needs","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because undifferentiated mass products leave gaps that segmented or niche competitors can exploit.","distractor_reasons":{"A":"Incorrect because mass production yields lower unit costs.","B":"Incorrect because mass-market brands use national TV extensively.","C":"Incorrect because supermarkets routinely stock mainstream single-formula staples.","D":"Option D is correct because undifferentiated mass products leave gaps that segmented or niche competitors can exploit."}}},{"id":"P1_U3_MCQ_137","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_137","question":"An oat-milk startup originally sold only through small health-food shops expands into major national supermarket chains to capture mainstream demand. What trade-off will it likely face as it moves toward the mass market?","options":{"A":"Higher unit manufacturing costs, balanced against exemption from food safety regulations","B":"Lower sales volume, balanced against zero competition from dairy or beverage corporations","C":"Higher total sales volume and lower unit production costs, balanced against lower profit margins per carton and tougher competition from food giants","D":"Complete elimination of all marketing and promotional expenses"},"correctOption":"C","correctAnswer":"Higher total sales volume and lower unit production costs, balanced against lower profit margins per carton and tougher competition from food giants","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because entering mainstream supermarkets boosts scale and revenue while triggering supermarket price pressure and multinational competition.","distractor_reasons":{"A":"Incorrect because higher output lowers unit costs and safety laws always apply.","B":"Incorrect because mainstream supermarket distribution increases sales volume and attracts fierce corporate rivals.","C":"Option C is correct because entering mainstream supermarkets boosts scale and revenue while triggering supermarket price pressure and multinational competition.","D":"Incorrect because competing in mass retail requires heavier promotional spending."}}},{"id":"P1_U3_MCQ_138","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_138","question":"A soft-drinks company analyzes consumer data and discovers that fitness enthusiasts want zero-sugar electrolyte drinks while office workers want lightly caffeinated herbal teas. How does 'market segmentation' help the company grow?","options":{"A":"It forces both groups to drink the exact same sugary cola","B":"It uncovers distinct unserved customer needs, enabling targeted product launches that expand total market share","C":"It eliminates the need to conduct product testing or packaging design","D":"It reduces the number of retail outlets willing to stock the company's drinks"},"correctOption":"B","correctAnswer":"It uncovers distinct unserved customer needs, enabling targeted product launches that expand total market share","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because segmentation identifies profitable sub-groups whose specific preferences can be satisfied with dedicated product lines.","distractor_reasons":{"A":"Incorrect because forcing one uniform product describes undifferentiated mass marketing.","B":"Option B is correct because segmentation identifies profitable sub-groups whose specific preferences can be satisfied with dedicated product lines.","C":"Incorrect because each targeted drink requires tailored testing and packaging.","D":"Incorrect because offering distinct products for different buyer groups typically increases shelf space."}}},{"id":"P1_U3_MCQ_139","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_139","question":"A frozen-food producer sells single-portion microwave meals in city-centre convenience stores and 2-kilogram family value packs in suburban supermarkets. Which demographic variable is driving this strategy?","options":{"A":"Gender","B":"Religious affiliation","C":"Household and family size","D":"Political party membership"},"correctOption":"C","correctAnswer":"Household and family size","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because household composition (single-person households vs multi-person families) directly determines ideal package sizes.","distractor_reasons":{"A":"Incorrect because portion sizes are based on household size rather than male or female buyers.","B":"Incorrect because pack size does not reflect religious dietary rules.","C":"Option C is correct because household composition (single-person households vs multi-person families) directly determines ideal package sizes.","D":"Incorrect because political affiliation is irrelevant to frozen meal pack sizes."}}},{"id":"P1_U3_MCQ_140","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_140","question":"A footwear manufacturer designs steel-toe waterproof boots for construction engineers and lightweight slip-resistant clogs for hospital nurses. Which demographic segmentation factor is being used?","options":{"A":"Age group","B":"Climatic zone","C":"Marital status","D":"Occupation / job role"},"correctOption":"D","correctAnswer":"Occupation / job role","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because different professions require specific functional product attributes tailored to daily working conditions.","distractor_reasons":{"A":"Incorrect because engineers and nurses span all working ages.","B":"Incorrect because both products are differentiated by workplace hazards rather than weather climate.","C":"Incorrect because marital status has no bearing on occupational footwear.","D":"Option D is correct because different professions require specific functional product attributes tailored to daily working conditions."}}},{"id":"P1_U3_MCQ_141","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_141","question":"An automotive tyre manufacturer promotes studded winter snow tyres in northern Scandinavia while marketing high-drainage monsoon tyres in Southeast Asia. Which segmentation basis is applied?","options":{"A":"Socio-economic income segmentation","B":"Geographic and climatic segmentation","C":"Gender segmentation","D":"Age segmentation"},"correctOption":"B","correctAnswer":"Geographic and climatic segmentation","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because regional climate and weather conditions dictate distinct functional product requirements.","distractor_reasons":{"A":"Incorrect because the distinction is based on snow vs tropical rain rather than buyer wealth.","B":"Option B is correct because regional climate and weather conditions dictate distinct functional product requirements.","C":"Incorrect because tyre tread design is unrelated to driver gender.","D":"Incorrect because all drivers in each climate zone need suitable seasonal tyres."}}},{"id":"P1_U3_MCQ_142","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_142","question":"A vehicle manufacturer markets compact electric city cars to apartment residents in congested metropolises and heavy-duty 4x4 pickup trucks to agricultural communities. Which segmentation dimension is this?","options":{"A":"Age segmentation","B":"Geographic (urban vs rural) segmentation","C":"Gender segmentation","D":"Undifferentiated mass marketing"},"correctOption":"B","correctAnswer":"Geographic (urban vs rural) segmentation","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because population density, road infrastructure, and urban vs rural locations create markedly different transport needs.","distractor_reasons":{"A":"Incorrect because drivers of any age live in cities or rural areas.","B":"Option B is correct because population density, road infrastructure, and urban vs rural locations create markedly different transport needs.","C":"Incorrect because vehicle choice here reflects terrain and parking conditions rather than gender.","D":"Incorrect because two distinct vehicle types are targeted at different geographic environments."}}},{"id":"P1_U3_MCQ_143","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_143","question":"A commercial bank offers free basic digital current accounts to low-wage workers alongside dedicated wealth-management advisors for clients holding over $1 million in savings. How is the bank segmenting its market?","options":{"A":"By geographic postcode","B":"By gender and age","C":"By income and socio-economic wealth bracket","D":"By climate and seasonal weather"},"correctOption":"C","correctAnswer":"By income and socio-economic wealth bracket","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because matching financial services to clients' income and asset levels aligns service complexity and fees with ability to pay.","distractor_reasons":{"A":"Incorrect because account tiers depend on financial assets rather than street address.","B":"Incorrect because wealth brackets cut across all genders and adult age groups.","C":"Option C is correct because matching financial services to clients' income and asset levels aligns service complexity and fees with ability to pay.","D":"Incorrect because banking tiers are unrelated to weather conditions."}}},{"id":"P1_U3_MCQ_144","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_144","question":"A travel company sells silent meditation retreats to stressed corporate executives and extreme bungee-jumping tours to thrill-seeking backpackers. Which segmentation criterion is it using?","options":{"A":"Gender","B":"Marital status","C":"Home postal code","D":"Lifestyle and psychographic attitudes"},"correctOption":"D","correctAnswer":"Lifestyle and psychographic attitudes","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because personal values, leisure interests, and attitudes toward relaxation vs adventure define lifestyle segmentation.","distractor_reasons":{"A":"Incorrect because both retreats and adventure tours attract male and female travellers.","B":"Incorrect because marital status does not determine preference for meditation vs bungee jumping.","C":"Incorrect because buyer hobbies and values drive these choices rather than residential address.","D":"Option D is correct because personal values, leisure interests, and attitudes toward relaxation vs adventure define lifestyle segmentation."}}},{"id":"P1_U3_MCQ_145","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_145","question":"A tour operator designs escorted cultural wildlife safaris priced at $8,000 specifically for active, high-income retirees aged 60–75. Which approach is the operator using?","options":{"A":"Product-oriented cost-plus discounting","B":"Undifferentiated mass marketing","C":"Multi-variable segmentation combining age, income, and lifestyle","D":"Geographic-only segmentation"},"correctOption":"C","correctAnswer":"Multi-variable segmentation combining age, income, and lifestyle","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because real-world businesses frequently combine demographic (age), socio-economic (income), and psychographic (active cultural travel) variables to pinpoint a profitable niche.","distractor_reasons":{"A":"Incorrect because the safari is designed around specific customer traits rather than unresearched production.","B":"Incorrect because the package is highly tailored rather than aimed at the entire public.","C":"Option C is correct because real-world businesses frequently combine demographic (age), socio-economic (income), and psychographic (active cultural travel) variables to pinpoint a profitable niche.","D":"Incorrect because the target group is defined by age, wealth, and interests rather than where they live."}}},{"id":"P1_U3_MCQ_146","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_146","question":"A cloud-accounting software firm offers a $15/month self-service plan for sole traders and a $1,200/month multi-currency enterprise package for multinational corporations. How is this B2B market segmented?","options":{"A":"By customer gender and leisure hobbies","B":"By client business size and operational complexity","C":"By individual employee shoe size","D":"By residential neighbourhood"},"correctOption":"B","correctAnswer":"By client business size and operational complexity","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because business-to-business (B2B) segmentation groups organizational buyers by company scale, industry sector, and transaction volume.","distractor_reasons":{"A":"Incorrect because personal hobbies apply to consumer (B2C) lifestyle segmentation.","B":"Option B is correct because business-to-business (B2B) segmentation groups organizational buyers by company scale, industry sector, and transaction volume.","C":"Incorrect because personal physical traits are irrelevant to accounting software.","D":"Incorrect because business scale determines software tier rather than residential address."}}},{"id":"P1_U3_MCQ_147","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_147","question":"Why do mobile-phone network providers offer discounted phone upgrades and priority customer support to subscribers who renew two-year contracts?","options":{"A":"Because regulators forbid mobile networks from signing up new customers","B":"Because loyal subscribers generate zero revenue during their contract term","C":"Because retaining loyal customers secures predictable recurring revenue and prevents rivals from stealing market share","D":"Because offering upgrades eliminates all network maintenance expenses"},"correctOption":"C","correctAnswer":"Because retaining loyal customers secures predictable recurring revenue and prevents rivals from stealing market share","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because customer loyalty stabilizes cash flows and reduces costly customer churn in saturated telecom markets.","distractor_reasons":{"A":"Incorrect because mobile operators actively recruit new subscribers alongside retention deals.","B":"Incorrect because subscribers pay regular monthly fees throughout their contract.","C":"Option C is correct because customer loyalty stabilizes cash flows and reduces costly customer churn in saturated telecom markets.","D":"Incorrect because network infrastructure still requires ongoing investment."}}},{"id":"P1_U3_MCQ_148","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_148","question":"A specialty coffee roaster sells 25,000 bags of coffee beans at $20 per bag ($500,000 annual revenue) and holds a 20% share of its regional market. What is the total value of the regional market?","options":{"A":"$100,000","B":"$1,000,000","C":"$2,000,000","D":"$2,500,000"},"correctOption":"D","correctAnswer":"$2,500,000","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because if $500,000 represents 20% (0.20) of the market, Total Market Size = $500,000 / 0.20 = $2,500,000.","distractor_reasons":{"A":"Incorrect because $100,000 multiplies $500,000 by 0.20 instead of dividing.","B":"Incorrect because $1,000,000 assumes a 50% market share rather than 20%.","C":"Incorrect because $2,000,000 assumes a 25% market share rather than 20%.","D":"Option D is correct because if $500,000 represents 20% (0.20) of the market, Total Market Size = $500,000 / 0.20 = $2,500,000."}}},{"id":"P1_U3_MCQ_149","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_149","question":"A fast-fashion retailer notices viral social media trends shifting teen clothing styles every few weeks. How must its marketing and operations respond to survive?","options":{"A":"Use continuous digital trend monitoring and flexible short-run production to launch matching styles rapidly before trends fade","B":"Order a five-year supply of a single jacket style to maximize bulk discounts","C":"Stop conducting market research because teen fashions remain identical every decade","D":"Sell exclusively through printed mail-order catalogues published once a year"},"correctOption":"A","correctAnswer":"Use continuous digital trend monitoring and flexible short-run production to launch matching styles rapidly before trends fade","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rapid changes in consumer tastes and fashions shorten product life cycles, demanding agile research and fast supply chains.","distractor_reasons":{"A":"Option A is correct because rapid changes in consumer tastes and fashions shorten product life cycles, demanding agile research and fast supply chains.","B":"Incorrect because holding five years of inventory in fast fashion guarantees massive unsold stock when styles change.","C":"Incorrect because fast-changing markets require more frequent research, not less.","D":"Incorrect because annual print catalogues are far too slow for fast-moving trends."}}},{"id":"P1_U3_MCQ_150","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_150","question":"A newly founded startup with $25,000 in capital wants to enter the crowded athletic-socks market. Why is targeting a specific niche—such as blister-proof compression socks for marathon runners—better than undifferentiated mass marketing?","options":{"A":"Mass marketing requires zero promotional expenditure or retail distribution","B":"Limited capital cannot fund nationwide mass-market battles against giants, whereas focusing on marathon runners builds strong brand loyalty and higher margins","C":"Marathon runners are legally prohibited from buying standard supermarket socks","D":"Niche socks require no product design or quality testing"},"correctOption":"B","correctAnswer":"Limited capital cannot fund nationwide mass-market battles against giants, whereas focusing on marathon runners builds strong brand loyalty and higher margins","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because concentrating limited resources on a high-involvement niche avoids direct price wars with huge multinationals.","distractor_reasons":{"A":"Incorrect because mass marketing demands huge advertising and distribution budgets.","B":"Option B is correct because concentrating limited resources on a high-involvement niche avoids direct price wars with huge multinationals.","C":"Incorrect because marathon runners choose specialist socks voluntarily for performance, not by law.","D":"Incorrect because technical niche products require careful design and testing."}}},{"id":"P1_U3_MCQ_151","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_151","question":"A traditional wristwatch manufacturer spends millions perfecting mechanical gears without researching buyer trends, and is shocked when consumers switch to fitness-tracking smartwatches. What caused this failure?","options":{"A":"Excessive reliance on consumer focus groups and test marketing","B":"Over-segmenting the market into too many digital watch categories","C":"A product-oriented mindset that prioritized engineering tradition over evolving customer needs","D":"Setting launch prices too low through penetration pricing"},"correctOption":"C","correctAnswer":"A product-oriented mindset that prioritized engineering tradition over evolving customer needs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because product-oriented firms assume technical craftsmanship guarantees sales, leaving them vulnerable to shifts in customer preferences.","distractor_reasons":{"A":"Incorrect because the firm conducted no consumer research before investing.","B":"Incorrect because the firm ignored the emerging smartwatch segment altogether.","C":"Option C is correct because product-oriented firms assume technical craftsmanship guarantees sales, leaving them vulnerable to shifts in customer preferences.","D":"Incorrect because the core issue was failing to adapt product functionality to customer demand."}}},{"id":"P1_U3_MCQ_152","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_152","question":"How does adopting a 'market-oriented' culture help a consumer-electronics brand respond faster when competitors launch rival gadgets?","options":{"A":"It eliminates the need for engineers to test product safety","B":"It guarantees that competitors will never copy the brand's designs","C":"It allows the firm to ignore customer complaints and warranty returns","D":"Ongoing customer feedback alerts the firm early to shifting user priorities so it can adapt features quickly"},"correctOption":"D","correctAnswer":"Ongoing customer feedback alerts the firm early to shifting user priorities so it can adapt features quickly","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because continuous market intelligence keeps product development aligned with real buyer expectations.","distractor_reasons":{"A":"Incorrect because safety testing remains essential in electronics.","B":"Incorrect because market orientation improves responsiveness rather than preventing imitation.","C":"Incorrect because market-oriented firms analyze complaints closely to improve products.","D":"Option D is correct because continuous market intelligence keeps product development aligned with real buyer expectations."}}},{"id":"P1_U3_MCQ_153","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_153","question":"Before investing $15 million in new factory tooling for a folding electric scooter, a mobility firm conducts surveys, focus groups, and price-willingness tests. What is the main purpose of this market research?","options":{"A":"To replace the need for quality inspection on the factory assembly line","B":"To calculate exact corporate income tax rates owed to the government","C":"To reduce the financial risk of launching a product that fails to attract enough buyers at a profitable price","D":"To eliminate all fixed overhead costs during manufacturing"},"correctOption":"C","correctAnswer":"To reduce the financial risk of launching a product that fails to attract enough buyers at a profitable price","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because market research provides objective evidence on demand, design, and pricing before committing irreversible capital.","distractor_reasons":{"A":"Incorrect because operational quality control remains necessary during production.","B":"Incorrect because tax calculations belong to Finance.","C":"Option C is correct because market research provides objective evidence on demand, design, and pricing before committing irreversible capital.","D":"Incorrect because market research informs commercial decisions rather than eliminating factory overheads."}}},{"id":"P1_U3_MCQ_154","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_154","question":"A café owner designs a short questionnaire asking local office workers which sandwich fillings and lunch prices would make them visit daily. What is the key advantage of this 'primary research'?","options":{"A":"It is completely free of time or effort compared with reading online news","B":"The data is up-to-date, confidential to the café, and directly answers the owner's specific menu and pricing questions","C":"It automatically interviews every resident in the entire country","D":"It requires zero planning of question wording"},"correctOption":"B","correctAnswer":"The data is up-to-date, confidential to the café, and directly answers the owner's specific menu and pricing questions","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because primary research is gathered first-hand for the exact decision at hand and is not shared with rivals.","distractor_reasons":{"A":"Incorrect because primary research requires time and effort to design, collect, and analyze.","B":"Option B is correct because primary research is gathered first-hand for the exact decision at hand and is not shared with rivals.","C":"Incorrect because surveys use a sample rather than a full national census.","D":"Incorrect because careful question design is vital to avoid bias."}}},{"id":"P1_U3_MCQ_155","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_155","question":"Why might a luxury carmaker use 'face-to-face personal interviews' with existing owners rather than an automated multiple-choice web form when designing its next flagship sedan?","options":{"A":"Face-to-face interviews are much cheaper and faster per respondent than online forms","B":"Face-to-face interviews completely eliminate any possibility of interviewer bias","C":"Trained interviewers can ask follow-up questions, clarify complex reactions, and capture nuanced qualitative insights","D":"Luxury car owners are legally forbidden from completing online surveys"},"correctOption":"C","correctAnswer":"Trained interviewers can ask follow-up questions, clarify complex reactions, and capture nuanced qualitative insights","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because personal interviews allow probing into detailed opinions and clarifying misunderstandings, though at higher cost per interview.","distractor_reasons":{"A":"Incorrect because personal interviews are far costlier and slower than online forms.","B":"Incorrect because interviewer tone or body language can introduce bias if not carefully trained.","C":"Option C is correct because personal interviews allow probing into detailed opinions and clarifying misunderstandings, though at higher cost per interview.","D":"Incorrect because online surveys are completely lawful."}}},{"id":"P1_U3_MCQ_156","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_156","question":"A cereal manufacturer brings together eight parents of school-age children to taste three prototype oat bars and discuss packaging slogans for 90 minutes. What key advantage does this 'focus group' provide?","options":{"A":"Statistically representative numerical forecasts across millions of households","B":"Zero moderation cost because participants manage the session themselves","C":"Complete elimination of dominant speakers influencing quieter members","D":"Rich qualitative feedback and spontaneous group discussion revealing emotional reactions to taste and branding"},"correctOption":"D","correctAnswer":"Rich qualitative feedback and spontaneous group discussion revealing emotional reactions to taste and branding","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because group interaction sparks deeper explanation of why consumers prefer certain flavours or messages.","distractor_reasons":{"A":"Incorrect because small 8-person groups are qualitative and not statistically generalizable.","B":"Incorrect because skilled moderators are required to guide discussion objectively.","C":"Incorrect because dominant speakers are actually a well-known risk in focus groups.","D":"Option D is correct because group interaction sparks deeper explanation of why consumers prefer certain flavours or messages."}}},{"id":"P1_U3_MCQ_157","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_157","question":"A department store uses overhead heat-mapping cameras to track which store aisles shoppers walk down most frequently and where congestion slows foot traffic. Which primary research method is being used?","options":{"A":"Telephone interview","B":"Postal questionnaire","C":"Observation","D":"External government census"},"correctOption":"C","correctAnswer":"Observation","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because observing natural shopper movement captures genuine behaviour without relying on self-reported memory.","distractor_reasons":{"A":"Incorrect because telephone interviews ask verbal questions.","B":"Incorrect because postal questionnaires collect written self-reports.","C":"Option C is correct because observing natural shopper movement captures genuine behaviour without relying on self-reported memory.","D":"Incorrect because store camera analytics generate internal primary data."}}},{"id":"P1_U3_MCQ_158","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_158","question":"A market research agency recruits 2,000 households to scan every grocery item they buy each week over a full year using a home barcode reader. Which research method is this?","options":{"A":"One-off street quota survey","B":"Consumer panel (longitudinal primary research)","C":"Internal accounting audit","D":"Newspaper article desk review"},"correctOption":"B","correctAnswer":"Consumer panel (longitudinal primary research)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a consumer panel tracks the same sample of households repeatedly over time to measure brand switching and repeat buying.","distractor_reasons":{"A":"Incorrect because street surveys capture a single moment rather than continuous weekly tracking.","B":"Option B is correct because a consumer panel tracks the same sample of households repeatedly over time to measure brand switching and repeat buying.","C":"Incorrect because an accounting audit verifies financial records.","D":"Incorrect because reading newspapers is secondary desk research."}}},{"id":"P1_U3_MCQ_159","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_159","question":"Before designing a new vacuum cleaner model, an appliance manufacturer reviews five years of its own customer-helpline call logs and warranty repair records. Why is this a smart first step?","options":{"A":"It is expensive primary research that interviews rival companies' customers","B":"It automatically guarantees 100% sales growth in foreign markets","C":"These internal secondary records already exist at minimal cost and pinpoint real product weaknesses experienced by buyers","D":"It replaces the need to test prototypes with new target consumers"},"correctOption":"C","correctAnswer":"These internal secondary records already exist at minimal cost and pinpoint real product weaknesses experienced by buyers","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because internal secondary data is immediately accessible, cheap, and highlights recurring functional faults to fix.","distractor_reasons":{"A":"Incorrect because internal company logs are secondary data rather than external primary interviews.","B":"Incorrect because fixing past defects aids quality but does not guarantee foreign expansion.","C":"Option C is correct because internal secondary data is immediately accessible, cheap, and highlights recurring functional faults to fix.","D":"Incorrect because new prototypes still require primary user testing."}}},{"id":"P1_U3_MCQ_160","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_160","question":"A private nursery chain uses free national census tables showing birth rates and average household incomes by city district to select where to open three new nurseries. Which type of research is this?","options":{"A":"Primary focus-group research","B":"Primary test marketing","C":"Internal company secondary data","D":"External secondary (desk) research"},"correctOption":"D","correctAnswer":"External secondary (desk) research","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because government census statistics were published by an external body for general public use and provide reliable demographic insights.","distractor_reasons":{"A":"Incorrect because no parent focus group discussions were conducted.","B":"Incorrect because no trial nursery was opened yet.","C":"Incorrect because census data comes from the government rather than the nursery's own records.","D":"Option D is correct because government census statistics were published by an external body for general public use and provide reliable demographic insights."}}},{"id":"P1_U3_MCQ_161","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_161","question":"A boutique hotel manager checks competitors' public websites, online travel-agency reviews, and national tourism board reports before setting summer room rates. Which research approach is being used?","options":{"A":"External secondary research","B":"Random primary sampling","C":"Quota street interviewing","D":"Controlled laboratory experimentation"},"correctOption":"A","correctAnswer":"External secondary research","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because competitor price listings, existing reviews, and tourism board publications are pre-existing external sources.","distractor_reasons":{"A":"Option A is correct because competitor price listings, existing reviews, and tourism board publications are pre-existing external sources.","B":"Incorrect because no new survey sample was drawn.","C":"Incorrect because no street interviews took place.","D":"Incorrect because reviewing published websites is desk research."}}},{"id":"P1_U3_MCQ_162","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_162","question":"A small startup developing a pet-grooming app has a limited research budget of $500. Why should it start with secondary desk research before running primary surveys?","options":{"A":"Secondary research always reveals exact customer reactions to the startup's unreleased app prototype","B":"Secondary research uses free or low-cost existing pet-ownership statistics to estimate market size quickly, preserving the $500 budget for targeted user testing","C":"Primary surveys are illegal for startups with fewer than ten employees","D":"Secondary research is never available on the internet"},"correctOption":"B","correctAnswer":"Secondary research uses free or low-cost existing pet-ownership statistics to estimate market size quickly, preserving the $500 budget for targeted user testing","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because starting with inexpensive secondary data avoids wasting scarce funds gathering basic industry facts that already exist.","distractor_reasons":{"A":"Incorrect because existing publications cannot test an unreleased custom prototype.","B":"Option B is correct because starting with inexpensive secondary data avoids wasting scarce funds gathering basic industry facts that already exist.","C":"Incorrect because startups can lawfully run primary surveys.","D":"Incorrect because vast amounts of secondary data are accessible online."}}},{"id":"P1_U3_MCQ_163","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_163","question":"What is a major drawback of commissioning a large-scale primary field survey before launching a trendy tech accessory?","options":{"A":"Primary data is always outdated by at least five years","B":"Competitors automatically receive free copies of the survey results","C":"High fieldwork costs and lengthy data-collection times may delay launch, allowing agile rivals to reach the market first","D":"Primary surveys cannot include questions about desired product features"},"correctOption":"C","correctAnswer":"High fieldwork costs and lengthy data-collection times may delay launch, allowing agile rivals to reach the market first","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because designing, conducting, and analyzing primary research is costly and time-consuming in fast-moving markets.","distractor_reasons":{"A":"Incorrect because primary research collects fresh, current data.","B":"Incorrect because primary data belongs exclusively to the commissioning firm.","C":"Option C is correct because designing, conducting, and analyzing primary research is costly and time-consuming in fast-moving markets.","D":"Incorrect because testing desired features is a primary purpose of product surveys."}}},{"id":"P1_U3_MCQ_164","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_164","question":"A college canteen wants to survey 200 of its 6,000 students. It assigns each student a number and uses a computer to pick numbers so every student has an equal chance. Which sampling method is used?","options":{"A":"Random sampling","B":"Quota sampling","C":"A focus group","D":"Analysing internal sales records"},"correctOption":"A","correctAnswer":"Random sampling","questionType":"MCQ","explanation":{"correct_reason":"Giving every member of the population an equal chance of selection through a computer-generated draw is random sampling.","distractor_reasons":{"B":"Quota sampling selects set numbers from categories rather than giving each individual an equal chance of being picked.","C":"A focus group is a small guided discussion, not a method of selecting a representative set of respondents.","D":"Sales records are existing secondary data, not a way of choosing people to take part in a survey.","A":"Giving every member of the population an equal chance of selection through a computer-generated draw is random sampling."}}},{"id":"P1_U3_MCQ_165","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_165","question":"Why is 'random sampling' often impractical for a soft-drinks brand wanting to survey casual supermarket shoppers nationwide?","options":{"A":"Random sampling forces interviewers to interview only elderly retired citizens","B":"The brand lacks a complete, up-to-date list (sampling frame) of every individual shopper in the country, making true random selection costly and difficult","C":"Random sampling is mathematically biased toward wealthy respondents","D":"Random sampling can only be used with secondary census tables"},"correctOption":"B","correctAnswer":"The brand lacks a complete, up-to-date list (sampling frame) of every individual shopper in the country, making true random selection costly and difficult","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because true random sampling requires an accurate population list, and selected individuals may be scattered geographically and hard to contact.","distractor_reasons":{"A":"Incorrect because random sampling gives all population members equal probability.","B":"Option B is correct because true random sampling requires an accurate population list, and selected individuals may be scattered geographically and hard to contact.","C":"Incorrect because unbiased random selection avoids systematic wealth skew.","D":"Incorrect because sampling applies to primary research."}}},{"id":"P1_U3_MCQ_166","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_166","question":"A commuter rail operator knows its passengers are 30% aged 18–30, 50% aged 31–55, and 20% aged 56+. If it uses 'quota sampling' to interview 200 passengers, how many aged 18–30 should be interviewed?","options":{"A":"30 passengers","B":"60 passengers","C":"100 passengers","D":"140 passengers"},"correctOption":"B","correctAnswer":"60 passengers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because 30% of a 200-person sample = 0.30 × 200 = 60 passengers aged 18–30.","distractor_reasons":{"A":"Incorrect because 30 would apply to a 100-person sample rather than 200.","B":"Option B is correct because 30% of a 200-person sample = 0.30 × 200 = 60 passengers aged 18–30.","C":"Incorrect because 100 represents the 50% bracket (31–55).","D":"Incorrect because 140 represents the combined 31–55 and 56+ brackets."}}},{"id":"P1_U3_MCQ_167","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_167","question":"A shopping-mall researcher needs 100 opinions and makes sure the sample reflects the mall's customers by interviewing fixed numbers from each age group. Which sampling method is this?","options":{"A":"Quota sampling","B":"Random sampling","C":"A census of all shoppers","D":"Analysing till receipts"},"correctOption":"A","correctAnswer":"Quota sampling","questionType":"MCQ","explanation":{"correct_reason":"Selecting set numbers from defined groups so the sample mirrors the population's composition is quota sampling.","distractor_reasons":{"B":"Random sampling relies on equal chance selection rather than deliberately filling age-group quotas.","C":"A census surveys every shopper, whereas this researcher interviews only 100 people.","D":"Till receipts are existing records and do not involve choosing participants by age group.","A":"Selecting set numbers from defined groups so the sample mirrors the population's composition is quota sampling."}}},{"id":"P1_U3_MCQ_168","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_168","question":"An umbrella manufacturer conducts street interviews during a rare three-week summer heatwave and concludes that umbrella demand has permanently collapsed. Which factor has distorted its market research accuracy?","options":{"A":"Excessive sample size reducing statistical reliability","B":"Over-reliance on government census records","C":"Using random number tables to select respondents","D":"Seasonal and temporary weather timing biasing respondents' immediate purchasing perceptions"},"correctOption":"D","correctAnswer":"Seasonal and temporary weather timing biasing respondents' immediate purchasing perceptions","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because temporary seasonal conditions strongly influence short-term consumer opinions and distort long-term demand forecasts.","distractor_reasons":{"A":"Incorrect because larger sample sizes improve accuracy.","B":"Incorrect because the firm used street interviews rather than census data.","C":"Incorrect because random selection reduces bias rather than causing weather distortion.","D":"Option D is correct because temporary seasonal conditions strongly influence short-term consumer opinions and distort long-term demand forecasts."}}},{"id":"P1_U3_MCQ_169","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_169","question":"In a face-to-face street survey, 85% of respondents claim they gladly pay extra for biodegradable packaging, yet actual supermarket sales show 80% buy the cheapest plastic-wrapped brand. What explains this discrepancy?","options":{"A":"Social desirability bias: respondents give answers that make them appear ethical to the interviewer rather than reflecting actual shopping habits","B":"Supermarkets illegally hide biodegradable products in locked back rooms","C":"Secondary data always contradicts primary observation","D":"Shoppers do not understand how to read price tags in supermarkets"},"correctOption":"A","correctAnswer":"Social desirability bias: respondents give answers that make them appear ethical to the interviewer rather than reflecting actual shopping habits","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because people often overstate socially admirable intentions in interviews compared with their real price-driven behaviour at the checkout.","distractor_reasons":{"A":"Option A is correct because people often overstate socially admirable intentions in interviews compared with their real price-driven behaviour at the checkout.","B":"Incorrect because supermarkets display eco-lines prominently when stocked.","C":"Incorrect because valid secondary and primary data often complement each other.","D":"Incorrect because shoppers actively respond to lower shelf prices."}}},{"id":"P1_U3_MCQ_170","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_170","question":"A cinema survey asks: 'Do you go to the movies frequently? Yes / No.' Why will the responses provide unreliable data for marketing decisions?","options":{"A":"The question uses too many complex technical film-industry acronyms","B":"The word 'frequently' is vague and subjective—one person may mean once a week while another means twice a year","C":"Yes/No questions cannot be counted into percentages","D":"Cinema customers are legally barred from answering frequency questions"},"correctOption":"B","correctAnswer":"The word 'frequently' is vague and subjective—one person may mean once a week while another means twice a year","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because imprecise terms lead different respondents to interpret the question differently; specific ranges (e.g., 'once a month') are needed.","distractor_reasons":{"A":"Incorrect because 'frequently' is an everyday vague word rather than technical jargon.","B":"Option B is correct because imprecise terms lead different respondents to interpret the question differently; specific ranges (e.g., 'once a month') are needed.","C":"Incorrect because closed Yes/No questions are easily tabulated, though ambiguous wording ruins validity.","D":"Incorrect because no such legal restriction exists."}}},{"id":"P1_U3_MCQ_171","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_171","question":"An airline emails passengers a post-flight survey asking them to rate seat comfort from 1 to 5 and also provides a comment box asking 'How could we improve your flight?' Why is this combination effective?","options":{"A":"It eliminates the need to analyze survey results before changing seat designs","B":"It guarantees that every passenger will give a 5-star rating","C":"The numerical rating quantifies overall satisfaction trends, while the open comment box reveals specific actionable causes behind low scores","D":"It converts primary customer feedback into external government census data"},"correctOption":"C","correctAnswer":"The numerical rating quantifies overall satisfaction trends, while the open comment box reveals specific actionable causes behind low scores","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because combining quantitative scores with qualitative explanations tells managers both how well they are performing and what to fix.","distractor_reasons":{"A":"Incorrect because managers must still analyze both numbers and comments carefully.","B":"Incorrect because honest feedback includes critical scores when service falls short.","C":"Option C is correct because combining quantitative scores with qualitative explanations tells managers both how well they are performing and what to fix.","D":"Incorrect because post-flight surveys remain internal primary research."}}},{"id":"P1_U3_MCQ_172","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_172","question":"A marketing analyst wants to show the Board of Directors how monthly online sales revenue grew steadily over the past 24 months. Which visual chart is clearest for displaying continuous change over time?","options":{"A":"A single pie chart showing only total annual sales","B":"A random scatter plot of employee birthdays","C":"A 10-page unformatted list of raw daily transaction receipts","D":"A line graph plotting monthly sales revenue along the timeline"},"correctOption":"D","correctAnswer":"A line graph plotting monthly sales revenue along the timeline","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because line graphs clearly illustrate trends, seasonal peaks, and growth rates across consecutive time periods.","distractor_reasons":{"A":"Incorrect because pie charts show parts of a whole at one point rather than a 24-month trend.","B":"Incorrect because employee birthdays are unrelated to sales trends.","C":"Incorrect because raw receipt lists obscure overall patterns.","D":"Option D is correct because line graphs clearly illustrate trends, seasonal peaks, and growth rates across consecutive time periods."}}},{"id":"P1_U3_MCQ_173","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_173","question":"A brand manager presents a bar chart where Brand A scored 81% satisfaction and Brand B scored 80%, but starts the vertical axis at 79.5% so Brand A's bar looks four times taller. What risk does this create?","options":{"A":"Starting the axis at 79.5% makes the survey sample size automatically larger","B":"Misleading visual presentation exaggerates a tiny 1% difference, risking flawed strategic decisions","C":"Bar charts are illegal to use in internal company board meetings","D":"Truncated axes convert qualitative opinions into secondary data"},"correctOption":"B","correctAnswer":"Misleading visual presentation exaggerates a tiny 1% difference, risking flawed strategic decisions","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because manipulating chart scales distorts visual proportions and can mislead executives into overreacting to negligible differences.","distractor_reasons":{"A":"Incorrect because chart formatting does not alter underlying sample size.","B":"Option B is correct because manipulating chart scales distorts visual proportions and can mislead executives into overreacting to negligible differences.","C":"Incorrect because bar charts are standard business tools when scaled honestly.","D":"Incorrect because axis scale does not change data origin."}}},{"id":"P1_U3_MCQ_174","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_174","question":"A hardware firm wants to learn how gamers actually handle a new wireless mouse during play, so it watches and records their actions in a test room. Which research method is this?","options":{"A":"Observation","B":"Questionnaire","C":"Secondary research","D":"Interview"},"correctOption":"A","correctAnswer":"Observation","questionType":"MCQ","explanation":{"correct_reason":"Observation is a primary research method that involves watching and recording customers' behaviour directly as they use a product.","distractor_reasons":{"A":"This is correct: watching and recording behaviour is observation.","B":"A questionnaire uses set written questions, not watching what people actually do.","C":"Secondary research uses existing data collected by others, not first-hand watching.","D":"An interview asks questions directly; here the firm records behaviour without questioning the gamers."}}},{"id":"P1_U3_MCQ_175","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_175","question":"Even after conducting thorough primary and secondary market research, a smartphone startup experiences weaker-than-forecast sales because a rival unexpectedly slashes prices by 40% on launch week. What limitation of market research does this show?","options":{"A":"Market research is only useful for sole traders selling agricultural produce","B":"Surveys always fail when sample sizes exceed 500 respondents","C":"Market research reduces uncertainty, but cannot predict sudden external shocks or aggressive competitor retaliation","D":"Businesses should never conduct market research before launching technology products"},"correctOption":"C","correctAnswer":"Market research reduces uncertainty, but cannot predict sudden external shocks or aggressive competitor retaliation","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because market research captures conditions at the time of study, whereas dynamic markets remain exposed to unexpected rival moves and economic shifts.","distractor_reasons":{"A":"Incorrect because market research benefits businesses of all sizes and sectors.","B":"Incorrect because larger samples increase statistical accuracy.","C":"Option C is correct because market research captures conditions at the time of study, whereas dynamic markets remain exposed to unexpected rival moves and economic shifts.","D":"Incorrect because skipping research would leave the startup even more vulnerable."}}},{"id":"P1_U3_MCQ_176","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_176","question":"A kitchen-appliance maker designs a sleek, award-winning toaster that burns bread unevenly and breaks after three months, leading to poor online reviews and falling repeat sales. Which aspect of 'Product' was neglected?","options":{"A":"Attractive exterior styling and colour variety","B":"Using a high psychological launch price","C":"Distributing through national department stores","D":"Core functional performance, reliability, and build quality"},"correctOption":"D","correctAnswer":"Core functional performance, reliability, and build quality","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because appealing aesthetics cannot compensate for poor core functionality and durability; successful products must perform reliably.","distractor_reasons":{"A":"Incorrect because the scenario notes the toaster already had sleek, award-winning styling.","B":"Incorrect because pricing strategy does not fix mechanical defects.","C":"Incorrect because distribution channels cannot rescue an unreliable product.","D":"Option D is correct because appealing aesthetics cannot compensate for poor core functionality and durability; successful products must perform reliably."}}},{"id":"P1_U3_MCQ_177","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_177","question":"During new product development, a beverage company's brainstorming team proposes 40 new drink concepts, then evaluates production feasibility, ingredient costs, and target-market fit to eliminate 35 weak ideas early. Which stage is this?","options":{"A":"Decline harvesting","B":"Full commercial launch","C":"Maturity extension","D":"Idea screening"},"correctOption":"D","correctAnswer":"Idea screening","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because screening filters out unviable or unprofitable concepts before spending heavy funds on prototypes and test marketing.","distractor_reasons":{"A":"Incorrect because decline harvesting manages aging products at the end of their life cycle.","B":"Incorrect because full launch occurs at the end of development for the winning product.","C":"Incorrect because extension strategies apply to existing mature products.","D":"Option D is correct because screening filters out unviable or unprofitable concepts before spending heavy funds on prototypes and test marketing."}}},{"id":"P1_U3_MCQ_178","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_178","question":"Why does an athletic clothing company legally register its distinctive swoosh-style logo and brand name as a 'trademark'?","options":{"A":"To eliminate all fabric and sewing labour costs in its factories","B":"To prevent competitors from copying its brand identity and confusing customers with counterfeit lookalikes","C":"To exempt its clothing from displaying washing-instruction labels","D":"To force supermarkets to stock its hoodies free of charge"},"correctOption":"B","correctAnswer":"To prevent competitors from copying its brand identity and confusing customers with counterfeit lookalikes","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because trademark protection safeguards brand equity, ensuring consumers can identify genuine quality reliably.","distractor_reasons":{"A":"Incorrect because trademarks protect intellectual property rather than lowering production costs.","B":"Option B is correct because trademark protection safeguards brand equity, ensuring consumers can identify genuine quality reliably.","C":"Incorrect because statutory garment care labelling laws still apply.","D":"Incorrect because retail listing terms are negotiated commercially."}}},{"id":"P1_U3_MCQ_179","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_179","question":"Many shoppers recognize a budget airline's logo immediately, yet still switch to whichever airline is $5 cheaper on booking websites. By contrast, Apple or Nike buyers repeatedly choose those brands even when cheaper alternatives exist. What does this contrast illustrate?","options":{"A":"The difference between mass distribution and direct wholesale exporting","B":"The difference between primary quota sampling and secondary desk research","C":"The difference between simple brand awareness and strong brand loyalty","D":"The difference between product orientation and cost-plus accounting"},"correctOption":"C","correctAnswer":"The difference between simple brand awareness and strong brand loyalty","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because brand awareness merely means consumers recognize a name, whereas brand loyalty drives repeat purchase and lower price sensitivity.","distractor_reasons":{"A":"Incorrect because the scenario compares customer attachment rather than distribution channels.","B":"Incorrect because market research sampling is not being compared.","C":"Option C is correct because brand awareness merely means consumers recognize a name, whereas brand loyalty drives repeat purchase and lower price sensitivity.","D":"Incorrect because product orientation and accounting methods are unrelated to brand attachment."}}},{"id":"P1_U3_MCQ_180","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_180","question":"Major supermarket chains sell their own 'store-brand (own-label)' breakfast cereals alongside famous manufacturer brands at 25% lower retail prices. Why are own-label products profitable for supermarkets?","options":{"A":"Supermarkets pay zero manufacturing or ingredient costs for own-label cereals","B":"Manufacturer brands are legally banned from advertising on television","C":"Own-label cereals never require nutritional or allergy packaging labels","D":"Supermarkets avoid heavy national brand-advertising costs and control supplier margins directly while building store loyalty"},"correctOption":"D","correctAnswer":"Supermarkets avoid heavy national brand-advertising costs and control supplier margins directly while building store loyalty","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because own-label ranges leverage the supermarket's existing store footfall without massive brand ad budgets, yielding attractive retail margins.","distractor_reasons":{"A":"Incorrect because supermarkets still pay contract manufacturers to produce own-label goods.","B":"Incorrect because manufacturer brands advertise heavily.","C":"Incorrect because all packaged foods must carry statutory labels.","D":"Option D is correct because own-label ranges leverage the supermarket's existing store footfall without massive brand ad budgets, yielding attractive retail margins."}}},{"id":"P1_U3_MCQ_181","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_181","question":"A children's toy box displays a clear 'Not suitable for children under 36 months—small parts choking hazard' symbol, assembly steps, and a retail barcode. Which role of 'packaging' is being fulfilled?","options":{"A":"Extending the Product Life Cycle during the decline stage","B":"Using psychological prestige pricing to target wealthy luxury collectors","C":"Replacing the need for wholesale distributors or retail toy stores","D":"Providing essential consumer safety information, usage instructions, and retail stock-tracking data"},"correctOption":"D","correctAnswer":"Providing essential consumer safety information, usage instructions, and retail stock-tracking data","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because beyond physical protection and shelf promotion, packaging communicates mandatory safety warnings, instructions, and barcodes.","distractor_reasons":{"A":"Incorrect because safety warnings are required from launch rather than being an extension strategy.","B":"Incorrect because safety warnings and barcodes are functional/legal information rather than prestige pricing.","C":"Incorrect because barcodes actually facilitate retail store checkout and inventory tracking.","D":"Option D is correct because beyond physical protection and shelf promotion, packaging communicates mandatory safety warnings, instructions, and barcodes."}}},{"id":"P1_U3_MCQ_182","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_182","question":"An e-commerce homeware brand replaces oversized, air-filled decorative cardboard boxes with snug, stackable moulded-pulp packaging. What dual benefit does this packaging redesign achieve?","options":{"A":"It eliminates all product manufacturing costs and removes the need for online marketing","B":"It reduces breakage damage during courier transit while cutting shipping volume and warehousing costs","C":"It prevents customers from identifying the brand logo upon delivery","D":"It allows the brand to ignore consumer refund laws"},"correctOption":"B","correctAnswer":"It reduces breakage damage during courier transit while cutting shipping volume and warehousing costs","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because smart packaging protects fragile items efficiently while maximizing container/van space and lowering freight costs.","distractor_reasons":{"A":"Incorrect because core manufacturing and marketing costs still apply.","B":"Option B is correct because smart packaging protects fragile items efficiently while maximizing container/van space and lowering freight costs.","C":"Incorrect because moulded pulp can still be printed or sleeved with clear branding.","D":"Incorrect because consumer laws remain fully binding."}}},{"id":"P1_U3_MCQ_183","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_183","question":"A pharmaceutical firm spends $40 million over four years testing a new allergy medication in clinical trials before receiving regulatory approval to sell a single dose. Which stage of the 'Product Life Cycle' is this?","options":{"A":"Growth stage","B":"Maturity stage","C":"Research and development (R&D) stage","D":"Decline stage"},"correctOption":"C","correctAnswer":"Research and development (R&D) stage","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because during R&D, the firm incurs heavy investment outlays with zero sales revenue and negative cash flow prior to commercial launch.","distractor_reasons":{"A":"Incorrect because growth features rapidly rising commercial sales.","B":"Incorrect because maturity represents peak sales and strong positive cash flow.","C":"Option C is correct because during R&D, the firm incurs heavy investment outlays with zero sales revenue and negative cash flow prior to commercial launch.","D":"Incorrect because decline occurs after peak sales when demand falls."}}},{"id":"P1_U3_MCQ_184","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_184","question":"Sales of a new portable solar power bank surge by 60% per quarter, unit production costs fall as factory output scales up, and the product turns profitable for the first time while rivals rush to launch copies. Which PLC stage is this?","options":{"A":"Development","B":"Introduction","C":"Decline","D":"Growth"},"correctOption":"D","correctAnswer":"Growth","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the growth stage combines rapid sales acceleration, economies of scale, rising profitability, and emerging competitor entry.","distractor_reasons":{"A":"Incorrect because development has zero sales.","B":"Incorrect because introduction features slow initial sales and typically net losses.","C":"Incorrect because decline features falling sales and shrinking margins.","D":"Option D is correct because the growth stage combines rapid sales acceleration, economies of scale, rising profitability, and emerging competitor entry."}}},{"id":"P1_U3_MCQ_185","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_185","question":"Sales of a traditional corded landline telephone fall steadily every year as households switch exclusively to mobile smartphones. What action should the manufacturer take in this 'decline stage'?","options":{"A":"Launch an expensive nationwide youth social-media influencer campaign","B":"Invest $50 million in building three brand-new corded-telephone factories","C":"Apply high price skimming as if the corded phone were a brand-new innovation","D":"Gradually reduce promotional spending to harvest remaining cash flow, and prepare to discontinue the line once it becomes unprofitable"},"correctOption":"D","correctAnswer":"Gradually reduce promotional spending to harvest remaining cash flow, and prepare to discontinue the line once it becomes unprofitable","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because when technological obsolescence drives permanent decline, cutting marketing overheads ('harvesting') and phasing out the product protects capital for newer lines.","distractor_reasons":{"A":"Incorrect because youth audiences have permanently moved to smartphones.","B":"Incorrect because expanding factory capacity in a dying market wastes capital.","C":"Incorrect because price skimming works only at initial launch for innovative goods.","D":"Option D is correct because when technological obsolescence drives permanent decline, cutting marketing overheads ('harvesting') and phasing out the product protects capital for newer lines."}}},{"id":"P1_U3_MCQ_186","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_186","question":"When domestic sales of its classic carbonated lemonade plateau in its mature home market, a beverage firm launches the drink in fast-growing emerging markets abroad. Which strategy is this?","options":{"A":"Product withdrawal","B":"Product Life Cycle extension strategy (entering new geographic markets)","C":"Cost-plus price skimming","D":"Primary quota sampling"},"correctOption":"B","correctAnswer":"Product Life Cycle extension strategy (entering new geographic markets)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because finding new geographic markets gives a domestically mature product a fresh growth curve abroad.","distractor_reasons":{"A":"Incorrect because withdrawal removes the product from sale.","B":"Option B is correct because finding new geographic markets gives a domestically mature product a fresh growth curve abroad.","C":"Incorrect because expanding into new markets is a Product/Place extension move rather than launch skimming.","D":"Incorrect because quota sampling is a research technique."}}},{"id":"P1_U3_MCQ_187","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_187","question":"A chocolate-bar brand whose sales have leveled off in maturity introduces a 'mint-crunch limited edition' and a resealable share-pouch format. What is the objective of these changes?","options":{"A":"To move the chocolate bar immediately into the decline stage","B":"To eliminate all supermarket distribution channels","C":"To stimulate fresh consumer interest and extend the profitable maturity stage of the Product Life Cycle","D":"To reduce product variety to a single basic wrapper"},"correctOption":"C","correctAnswer":"To stimulate fresh consumer interest and extend the profitable maturity stage of the Product Life Cycle","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because product variations and new packaging formats are classic extension strategies that revive mature sales.","distractor_reasons":{"A":"Incorrect because extension strategies aim to delay decline rather than accelerate it.","B":"Incorrect because new variants rely on strong supermarket distribution.","C":"Option C is correct because product variations and new packaging formats are classic extension strategies that revive mature sales.","D":"Incorrect because adding limited editions and share-pouches increases variety."}}},{"id":"P1_U3_MCQ_188","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_188","question":"What is a major risk when a company spends heavily on advertising and packaging redesigns to extend the life of a product in the 'decline stage'?","options":{"A":"Extension strategies always reduce unit production costs to zero","B":"Regulators fine businesses that update packaging on mature products","C":"Customers become confused and buy twice as much as expected","D":"If consumer tastes or technology have permanently shifted away, the extra promotional spending will fail to revive sales and reduce overall profit"},"correctOption":"D","correctAnswer":"If consumer tastes or technology have permanently shifted away, the extra promotional spending will fail to revive sales and reduce overall profit","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because extension strategies cannot rescue a product made permanently obsolete by superior technology (such as film cameras vs smartphones).","distractor_reasons":{"A":"Incorrect because redesigning packaging and advertising increases marketing expenses.","B":"Incorrect because updating packaging is completely lawful.","C":"Incorrect because the risk is wasted expenditure with weak sales response, not excess demand.","D":"Option D is correct because extension strategies cannot rescue a product made permanently obsolete by superior technology (such as film cameras vs smartphones)."}}},{"id":"P1_U3_MCQ_189","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_189","question":"A designer handbag maker uses hand-stitched Italian leather and exclusive boutique displays, yet prices its bags at $25—the same as mass-market canvas totes. Why is this pricing decision flawed?","options":{"A":"The low price conflicts with the luxury Product image, causing wealthy buyers to doubt its authenticity and failing to cover high craft costs","B":"Luxury handbags must always use penetration pricing to maximize supermarket volume","C":"Wealthy consumers only buy designer accessories priced under $30","D":"Italian leather handbags have zero variable material costs"},"correctOption":"A","correctAnswer":"The low price conflicts with the luxury Product image, causing wealthy buyers to doubt its authenticity and failing to cover high craft costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because price acts as a powerful quality signal and must align with product positioning and unit costs.","distractor_reasons":{"A":"Option A is correct because price acts as a powerful quality signal and must align with product positioning and unit costs.","B":"Incorrect because luxury goods rely on prestige pricing rather than mass supermarket penetration.","C":"Incorrect because luxury shoppers associate high prices with exclusivity and status.","D":"Incorrect because fine leather and hand-stitching carry high unit costs."}}},{"id":"P1_U3_MCQ_190","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_190","question":"A ceramic-mug manufacturer incurs total production costs of $12,000 to produce a batch of 1,500 mugs. If it applies a 25% cost-plus mark-up, what is the selling price per mug?","options":{"A":"$8.00","B":"$10.00","C":"$10.67","D":"$12.50"},"correctOption":"B","correctAnswer":"$10.00","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Unit Cost = $12,000 / 1,500 = $8.00; Selling Price = $8.00 + (25% of $8.00) = $8.00 + $2.00 = $10.00.","distractor_reasons":{"A":"Incorrect because $8.00 is the unit production cost before adding the 25% profit mark-up.","B":"Option B is correct because Unit Cost = $12,000 / 1,500 = $8.00; Selling Price = $8.00 + (25% of $8.00) = $8.00 + $2.00 = $10.00.","C":"Incorrect because $10.67 divides $8.00 by 0.75 instead of adding a 25% mark-up.","D":"Incorrect because $12.50 adds $4.50 rather than 25% of $8.00."}}},{"id":"P1_U3_MCQ_191","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_191","question":"Why might a cloud-storage startup choose 'penetration pricing' (free basic tier + $2/month upgrade) rather than 'price skimming' when launching its app?","options":{"A":"Because cloud storage has very high physical shipping costs per gigabyte","B":"Because early adopters never try new software apps","C":"Because low initial prices rapidly build a huge user base and customer lock-in in a competitive market with low marginal serving costs","D":"Because price skimming is legally forbidden for digital software companies"},"correctOption":"C","correctAnswer":"Because low initial prices rapidly build a huge user base and customer lock-in in a competitive market with low marginal serving costs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because digital platforms benefit from rapid scale and switching costs once users store files on the platform.","distractor_reasons":{"A":"Incorrect because digital cloud storage has zero physical parcel shipping costs.","B":"Incorrect because tech users readily adopt new apps.","C":"Option C is correct because digital platforms benefit from rapid scale and switching costs once users store files on the platform.","D":"Incorrect because software firms can lawfully choose any non-predatory pricing model."}}},{"id":"P1_U3_MCQ_192","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_192","question":"A new regional airline enters a route where two rivals sell tickets for $140. It sets its own fare at $132, just below the rivals, to win passengers. Which pricing method is this?","options":{"A":"Cost-plus pricing","B":"Competitive pricing","C":"Promotional pricing","D":"Premium pricing"},"correctOption":"B","correctAnswer":"Competitive pricing","questionType":"MCQ","explanation":{"correct_reason":"Competitive pricing sets a price by referring to what competitors charge; the airline priced just below its rivals' $140 fare.","distractor_reasons":{"A":"Cost-plus pricing builds the price from production cost plus a margin, not from rivals' prices.","B":"This is correct: the airline based its fare on competitors' prices.","C":"Promotional pricing is a temporary price cut to boost sales, not a price matched to rivals.","D":"Premium pricing sets a price above competitors to signal high quality, the opposite of undercutting them."}}},{"id":"P1_U3_MCQ_193","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_193","question":"Every evening at 7:30 PM, a supermarket bakery reduces the price of fresh bread loaves by 60% so they sell before closing time rather than being thrown away. Which pricing tactic is this?","options":{"A":"Promotional clearance pricing","B":"Price skimming","C":"Cost-plus mark-up pricing","D":"Psychological prestige pricing"},"correctOption":"A","correctAnswer":"Promotional clearance pricing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because temporary end-of-day markdowns clear perishable inventory quickly and recover cash.","distractor_reasons":{"A":"Option A is correct because temporary end-of-day markdowns clear perishable inventory quickly and recover cash.","B":"Incorrect because skimming charges a high launch price for innovative products.","C":"Incorrect because end-of-day markdowns often sell below full cost to avoid total spoilage loss.","D":"Incorrect because clearance discounts signal bargain value rather than luxury prestige."}}},{"id":"P1_U3_MCQ_194","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_194","question":"An electronics retailer prices a mid-range tablet computer at $299 rather than $300 so shoppers mentally categorize it as 'under $300'. Which pricing technique is being used?","options":{"A":"Penetration pricing","B":"Psychological (charm) pricing","C":"Dynamic surge pricing","D":"Loss-leader pricing"},"correctOption":"B","correctAnswer":"Psychological (charm) pricing","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because charm pricing ($299 vs $300) exploits left-digit perception to make a price feel noticeably lower.","distractor_reasons":{"A":"Incorrect because penetration pricing sets a substantially lower entry price to win market share.","B":"Option B is correct because charm pricing ($299 vs $300) exploits left-digit perception to make a price feel noticeably lower.","C":"Incorrect because dynamic pricing fluctuates automatically with live demand.","D":"Incorrect because loss-leader pricing sells an item below cost to attract store traffic."}}},{"id":"P1_U3_MCQ_195","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_195","question":"During a sudden evening thunderstorm, a ride-hailing app automatically increases trip fares by 1.5×, encouraging more drivers to log on while rationing rides to urgent passengers. Which pricing strategy is operating?","options":{"A":"Fixed cost-plus pricing","B":"Static penetration pricing","C":"Dynamic pricing","D":"Promotional clearance pricing"},"correctOption":"C","correctAnswer":"Dynamic pricing","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because dynamic pricing uses real-time algorithms to adjust prices instantaneously to shifts in supply and demand.","distractor_reasons":{"A":"Incorrect because cost-plus remains fixed regardless of weather or demand spikes.","B":"Incorrect because penetration pricing is a low introductory launch price.","C":"Option C is correct because dynamic pricing uses real-time algorithms to adjust prices instantaneously to shifts in supply and demand.","D":"Incorrect because surge fares raise prices during peak demand rather than discounting surplus stock."}}},{"id":"P1_U3_MCQ_196","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_196","question":"A regional bus operator wants to fill empty seats on quiet weekday routes, so it offers 'buy one ticket, get one free' for a limited period. Which pricing method is this?","options":{"A":"Competitive pricing","B":"Cost-plus pricing","C":"Promotional pricing","D":"Premium pricing"},"correctOption":"C","correctAnswer":"Promotional pricing","questionType":"MCQ","explanation":{"correct_reason":"Promotional pricing uses temporary price reductions or special offers to stimulate sales, such as a limited-time 'buy one, get one free' deal.","distractor_reasons":{"A":"Competitive pricing sets the price relative to rivals, not through a temporary special offer.","B":"Cost-plus pricing adds a margin to cost, rather than running a short-term deal.","C":"This is correct: a limited-time offer to boost sales is promotional pricing.","D":"Premium pricing charges above the market to signal quality, unlike a discount offer."}}},{"id":"P1_U3_MCQ_197","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_197","question":"A restaurant chain sets the price of its lunchtime pasta bowls by working out the cost of ingredients and kitchen labour, then adding a fixed percentage to cover overheads and profit. Which pricing method is the chain using?","options":{"A":"Cost-plus pricing","B":"Competitive pricing","C":"Promotional pricing","D":"Psychological pricing"},"correctOption":"A","correctAnswer":"Cost-plus pricing","questionType":"MCQ","explanation":{"correct_reason":"Cost-plus pricing works out the cost of making each unit and adds a percentage mark-up to cover overheads and generate profit.","distractor_reasons":{"A":"Cost-plus pricing builds the price up from unit costs and a mark-up, which is exactly what the chain does.","B":"Competitive pricing sets a price by comparing with rivals' prices, not by adding a mark-up to costs.","C":"Promotional pricing temporarily lowers a price to boost sales; it is not a cost-based calculation.","D":"Psychological pricing uses prices just below round figures to influence buyers, not a calculation of costs."}}},{"id":"P1_U3_MCQ_198","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_198","question":"A manufacturer of specialised replacement water-pump seals for commercial ships supplies its products directly to shipyards instead of using wholesalers or retailers. Which element of the marketing mix does this describe?","options":{"A":"Product — the design and features of the seal","B":"Price — the amount charged to the shipyard","C":"Place — the channel used to reach the customer","D":"Promotion — how the product is advertised"},"correctOption":"C","correctAnswer":"Place — the channel used to reach the customer","questionType":"MCQ","explanation":{"correct_reason":"Place refers to distribution: how a product reaches the customer. Selling straight to shipyards is a choice of distribution channel.","distractor_reasons":{"A":"Product concerns the seal's design, quality and features, not the route by which it reaches buyers.","B":"Price is the amount charged, not the channel used to deliver the product to the customer.","C":"Place covers the distribution channel used to get the product to the customer, here selling directly to shipyards.","D":"Promotion covers advertising and sales messages, not the route to market."}}},{"id":"P1_U3_MCQ_199","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_199","question":"A coffee shop chain runs a long-term campaign built around a distinctive name, logo and packaging so customers recognise it instantly and choose it over rivals. What is the main aim of this brand-building activity?","options":{"A":"To build customer loyalty and differentiate its drinks","B":"To reduce the cost of its raw materials","C":"To increase the number of its suppliers","D":"To remove all competitors from the market"},"correctOption":"A","correctAnswer":"To build customer loyalty and differentiate its drinks","questionType":"MCQ","explanation":{"correct_reason":"Branding creates recognition and loyalty, helping a business differentiate its products and charge a premium.","distractor_reasons":{"A":"A strong brand builds recognition and loyalty, setting the product apart from competitors' offerings.","B":"Branding affects customer perception, not the price paid to suppliers for raw materials.","C":"Brand-building focuses on customers, not on expanding the supplier base.","D":"A strong brand helps a firm compete but cannot remove rival businesses from the market."}}},{"id":"P1_U3_MCQ_200","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_200","question":"How does a typical technology hardware company adjust its pricing strategy as a flagship product moves from 'Introduction' to 'Maturity'?","options":{"A":"It starts with clearance discounts at introduction and raises prices by 100% during decline","B":"It keeps the exact same launch price for ten years regardless of competitor models","C":"It uses loss-leader pricing at launch and switches to price skimming when the product becomes obsolete","D":"It often starts with high price skimming for early adopters, then shifts toward competitive and promotional pricing as rivals enter during maturity"},"correctOption":"D","correctAnswer":"It often starts with high price skimming for early adopters, then shifts toward competitive and promotional pricing as rivals enter during maturity","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because evolving competition and buyer segments across the Product Life Cycle require adapting prices from early-adopter margins to mainstream competitiveness.","distractor_reasons":{"A":"Incorrect because clearance discounts belong at the end of the life cycle rather than introduction.","B":"Incorrect because rigid pricing loses share once competitors launch cheaper alternatives.","C":"Incorrect because skimming works only when a product is new and innovative.","D":"Option D is correct because evolving competition and buyer segments across the Product Life Cycle require adapting prices from early-adopter margins to mainstream competitiveness."}}},{"id":"P1_U3_MCQ_201","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_201","question":"An umbrella brand launches a great waterproof design at a fair price with catchy TV ads, yet sales disappoint because customers cannot find the umbrellas in local stores when it rains. Which element of the marketing mix failed?","options":{"A":"Promotional awareness","B":"Product design","C":"Price competitiveness","D":"Place (distribution availability)"},"correctOption":"D","correctAnswer":"Place (distribution availability)","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because even the best product, price, and promotion fail if distribution channels do not place stock conveniently where and when buyers want it.","distractor_reasons":{"A":"Incorrect because TV ads generated awareness, but buyers could not locate stock.","B":"Incorrect because the scenario states the waterproof design was strong.","C":"Incorrect because the price was already competitive.","D":"Option D is correct because even the best product, price, and promotion fail if distribution channels do not place stock conveniently where and when buyers want it."}}},{"id":"P1_U3_MCQ_202","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_202","question":"An organic vegetable farm sells weekly seasonal produce boxes directly to local households via its own website and delivery van. Why is this 'direct distribution channel' ideal?","options":{"A":"It allows vegetables to sit in wholesale warehouses for three months","B":"It keeps perishable produce fresh, avoids intermediary profit margins, and builds direct relationships with local subscribers","C":"It eliminates the need to harvest vegetables or maintain a delivery van","D":"It guarantees nationwide supermarket shelf space across 1,000 stores"},"correctOption":"B","correctAnswer":"It keeps perishable produce fresh, avoids intermediary profit margins, and builds direct relationships with local subscribers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because perishable farm produce benefits from zero-intermediary speed and full margin retention.","distractor_reasons":{"A":"Incorrect because storing fresh vegetables for months would cause spoilage.","B":"Option B is correct because perishable farm produce benefits from zero-intermediary speed and full margin retention.","C":"Incorrect because direct delivery still requires harvesting and transport logistics.","D":"Incorrect because selling direct via own vans bypasses national supermarkets."}}},{"id":"P1_U3_MCQ_203","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_203","question":"A major washing-machine manufacturer sells its appliances through large national electronics retail chains rather than operating hundreds of its own brand showrooms. Why is using 'retailers' advantageous here?","options":{"A":"Retailers never charge any profit margin on appliances sold","B":"Retailers manufacture the washing-machine motors on behalf of the brand","C":"Retail chains provide widespread physical store locations where shoppers can compare models and arrange home delivery without the manufacturer funding retail premises","D":"Using retailers prevents shoppers from comparing rival washing-machine brands"},"correctOption":"C","correctAnswer":"Retail chains provide widespread physical store locations where shoppers can compare models and arrange home delivery without the manufacturer funding retail premises","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because established retailers offer immediate nationwide store networks, customer footfall, and local delivery infrastructure.","distractor_reasons":{"A":"Incorrect because retailers earn a retail margin between wholesale purchase price and consumer price.","B":"Incorrect because retailers distribute finished appliances rather than manufacturing components.","C":"Option C is correct because established retailers offer immediate nationwide store networks, customer footfall, and local delivery infrastructure.","D":"Incorrect because retail stores display competing brands side-by-side."}}},{"id":"P1_U3_MCQ_204","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_204","question":"A confectionery manufacturer sells chocolates through regional 'wholesalers', who then supply thousands of small convenience shops. What is a major disadvantage of this channel for the manufacturer?","options":{"A":"The manufacturer must deliver tiny ten-bar boxes individually to every corner shop","B":"Wholesalers refuse to buy bulk pallet loads from factories","C":"Independent corner shops cannot purchase small assorted quantities","D":"Each intermediary takes a profit margin, raising final retail prices or lowering factory margins, while the manufacturer loses direct control over store presentation"},"correctOption":"D","correctAnswer":"Each intermediary takes a profit margin, raising final retail prices or lowering factory margins, while the manufacturer loses direct control over store presentation","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because adding both a wholesaler and a retailer lengthens the chain, sharing profit margins and distancing the producer from end consumers.","distractor_reasons":{"A":"Incorrect because wholesalers handle small-lot distribution to corner shops, saving the factory from doing so.","B":"Incorrect because buying in bulk is the wholesaler's core function.","C":"Incorrect because breaking bulk into small assortments is how wholesalers help corner shops.","D":"Option D is correct because adding both a wholesaler and a retailer lengthens the chain, sharing profit margins and distancing the producer from end consumers."}}},{"id":"P1_U3_MCQ_205","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_205","question":"A boutique Chilean vineyard wants to sell its wines to upscale restaurants in Japan, where it has no local contacts or staff. Why does it appoint an 'overseas sales agent' in Tokyo?","options":{"A":"The agent buys the entire vineyard and pays all grape-harvesting wages","B":"The agent possesses established local hospitality contacts, language fluency, and import knowledge, earning commission only when orders are secured","C":"Agents are legally required to sell products at zero profit margin","D":"Using an agent eliminates all international shipping and customs documentation"},"correctOption":"B","correctAnswer":"The agent possesses established local hospitality contacts, language fluency, and import knowledge, earning commission only when orders are secured","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because local agents overcome cultural and network barriers in unfamiliar export markets without fixed overseas branch overheads.","distractor_reasons":{"A":"Incorrect because agents represent producers on commission rather than buying the business.","B":"Option B is correct because local agents overcome cultural and network barriers in unfamiliar export markets without fixed overseas branch overheads.","C":"Incorrect because agents earn a negotiated sales commission.","D":"Incorrect because international freight and customs clearance still take place."}}},{"id":"P1_U3_MCQ_206","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_206","question":"Why do manufacturers of complex medical imaging equipment (such as hospital MRI scanners) use a 'direct sales channel' rather than selling through general wholesalers?","options":{"A":"MRI scanners are low-value impulse items bought in corner shops","B":"High technical complexity requires direct engineer consultation, custom hospital installation, staff training, and ongoing maintenance contracts","C":"Wholesalers are legally banned from storing electronic equipment","D":"Direct selling requires zero technical knowledge from the manufacturer's team"},"correctOption":"B","correctAnswer":"High technical complexity requires direct engineer consultation, custom hospital installation, staff training, and ongoing maintenance contracts","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because technically sophisticated, high-value capital goods need direct producer-to-buyer support before and after installation.","distractor_reasons":{"A":"Incorrect because MRI scanners are multi-million-dollar specialist capital equipment.","B":"Option B is correct because technically sophisticated, high-value capital goods need direct producer-to-buyer support before and after installation.","C":"Incorrect because wholesalers handle standard electronics, just not custom hospital scanners.","D":"Incorrect because direct B2B sales engineers must possess deep technical expertise."}}},{"id":"P1_U3_MCQ_207","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_207","question":"A quarry produces heavy crushed stone and concrete blocks that have high transport weight relative to their unit selling price. How does this product characteristic shape its 'Place' strategy?","options":{"A":"The quarry exports heavy stone blocks via individual air-freight parcels worldwide","B":"The quarry sells individual concrete blocks through luxury shopping-mall boutiques","C":"Distribution focuses on regional bulk truck deliveries directly to construction sites within a short radius to keep freight costs economical","D":"The quarry stores blocks in three layers of national wholesalers before selling"},"correctOption":"C","correctAnswer":"Distribution focuses on regional bulk truck deliveries directly to construction sites within a short radius to keep freight costs economical","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because bulky, low-value-to-weight materials become uncompetitive if shipped long distances or handled repeatedly.","distractor_reasons":{"A":"Incorrect because air freighting heavy stone would cost far more than the product's value.","B":"Incorrect because heavy construction materials are sold to builders rather than mall shoppers.","C":"Option C is correct because bulky, low-value-to-weight materials become uncompetitive if shipped long distances or handled repeatedly.","D":"Incorrect because multiple handling stages add prohibitive transport expenses."}}},{"id":"P1_U3_MCQ_208","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_208","question":"Many traditional book publishers and music labels now sell digital e-books and streaming downloads straight to consumers online, bypassing physical wholesalers and high-street shops. What is this trend called?","options":{"A":"Vertical backward integration","B":"Price skimming","C":"Quota market sampling","D":"Disintermediation (cutting out traditional intermediaries via e-commerce)"},"correctOption":"D","correctAnswer":"Disintermediation (cutting out traditional intermediaries via e-commerce)","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because digital e-commerce allows producers to deliver directly to end users without middlemen.","distractor_reasons":{"A":"Incorrect because backward integration means buying a raw-material supplier.","B":"Incorrect because price skimming is a launch pricing method.","C":"Incorrect because quota sampling is a survey technique.","D":"Option D is correct because digital e-commerce allows producers to deliver directly to end users without middlemen."}}},{"id":"P1_U3_MCQ_209","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_209","question":"A medium-sized retailer launches an online store to complement its physical shops, but sees high cart-abandonment rates at checkout. Which 'e-commerce' barrier commonly causes shoppers to abandon online purchases?","options":{"A":"Shoppers are legally forbidden from buying goods online after 6:00 PM","B":"Unexpected high shipping fees, slow delivery estimates, or concerns over website payment security","C":"Online stores cannot display product prices in local currency","D":"E-commerce websites force buyers to visit a wholesale warehouse in person"},"correctOption":"B","correctAnswer":"Unexpected high shipping fees, slow delivery estimates, or concerns over website payment security","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because hidden delivery charges, long wait times, and trust/security doubts frequently deter online checkout completion.","distractor_reasons":{"A":"Incorrect because online shopping operates 24/7.","B":"Option B is correct because hidden delivery charges, long wait times, and trust/security doubts frequently deter online checkout completion.","C":"Incorrect because e-commerce platforms routinely display local currencies.","D":"Incorrect because online purchases deliver directly to the buyer's address."}}},{"id":"P1_U3_MCQ_210","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_210","question":"A well-established toothpaste brand runs regular reminder advertisements even though most consumers already know the brand well. What is a primary aim of 'reminder promotion' for mature products?","options":{"A":"To explain for the very first time what toothpaste is used for","B":"To keep the brand top-of-mind in supermarkets so loyal buyers do not switch to aggressive rivals","C":"To eliminate the need to distribute toothpaste to retail stores","D":"To reduce factory production capacity to zero"},"correctOption":"B","correctAnswer":"To keep the brand top-of-mind in supermarkets so loyal buyers do not switch to aggressive rivals","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because in mature, competitive markets, ongoing promotion reinforces brand habit and defends shelf share.","distractor_reasons":{"A":"Incorrect because basic product education occurs during the introduction stage.","B":"Option B is correct because in mature, competitive markets, ongoing promotion reinforces brand habit and defends shelf share.","C":"Incorrect because retail distribution remains essential.","D":"Incorrect because reminder ads aim to sustain steady production and sales."}}},{"id":"P1_U3_MCQ_211","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_211","question":"A public health agency launches a campaign explaining the exact symptoms of heatstroke and step-by-step hydration advice during summer. Which type of advertising is this?","options":{"A":"Persuasive luxury brand advertising","B":"Point-of-sale clearance promotion","C":"Informative advertising","D":"Personal B2B door-to-door selling"},"correctOption":"C","correctAnswer":"Informative advertising","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because informative advertising focuses on communicating clear, factual knowledge and instructions to the audience.","distractor_reasons":{"A":"Incorrect because luxury ads use emotional status appeal rather than public safety facts.","B":"Incorrect because point-of-sale clearance discounts retail stock.","C":"Option C is correct because informative advertising focuses on communicating clear, factual knowledge and instructions to the audience.","D":"Incorrect because personal selling involves individual commercial sales pitches."}}},{"id":"P1_U3_MCQ_212","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_212","question":"A fragrance brand's television commercial shows glamorous actors attending a Paris gala without mentioning bottle size, ingredients, or price. Which advertising approach is being used?","options":{"A":"Informative technical advertising","B":"Trade-fair wholesale cataloguing","C":"Loss-leader price promotion","D":"Persuasive (image-based) advertising"},"correctOption":"D","correctAnswer":"Persuasive (image-based) advertising","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because persuasive advertising builds emotional desire and aspirational brand associations to differentiate a product.","distractor_reasons":{"A":"Incorrect because no factual product specifications are given.","B":"Incorrect because trade catalogues target business buyers with technical details.","C":"Incorrect because luxury perfumes avoid discount loss-leader tactics.","D":"Option D is correct because persuasive advertising builds emotional desire and aspirational brand associations to differentiate a product."}}},{"id":"P1_U3_MCQ_213","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_213","question":"Why does a multinational snack-food corporation still allocate millions of dollars to 'television and streaming video advertising' despite high airtime costs?","options":{"A":"Audiovisual storytelling demonstrates product enjoyment vividly and reaches millions of mass-market households simultaneously, building strong brand awareness","B":"Television commercials are cheaper per campaign than printing local flyers","C":"Viewers are legally forced to buy every product advertised on television","D":"Television advertising targets only a tiny niche of 50 industrial buyers"},"correctOption":"A","correctAnswer":"Audiovisual storytelling demonstrates product enjoyment vividly and reaches millions of mass-market households simultaneously, building strong brand awareness","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sight, sound, and motion create memorable brand impact across massive consumer audiences.","distractor_reasons":{"A":"Option A is correct because sight, sound, and motion create memorable brand impact across massive consumer audiences.","B":"Incorrect because national TV production and airtime are very expensive.","C":"Incorrect because consumers choose purchases freely.","D":"Incorrect because TV is a mass-market medium rather than a tiny B2B niche tool."}}},{"id":"P1_U3_MCQ_214","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_214","question":"A regional car dealership wants to promote its weekend trade-in event to drivers living within 30 kilometres of its showroom on a modest budget. Which advertising media are most suitable?","options":{"A":"Global airline in-flight magazines","B":"Local radio stations and local city newspapers","C":"International scientific academic journals","D":"Nationwide cinema trailers across all 50 states"},"correctOption":"B","correctAnswer":"Local radio stations and local city newspapers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because local radio (heard by commuters driving in their cars) and local newspapers reach the exact geographic catchment area affordably.","distractor_reasons":{"A":"Incorrect because in-flight magazines reach international travellers rather than local drivers.","B":"Option B is correct because local radio (heard by commuters driving in their cars) and local newspapers reach the exact geographic catchment area affordably.","C":"Incorrect because academic journals are untargeted for local car sales.","D":"Incorrect because nationwide cinema campaigns waste budget outside the dealership's 30 km radius."}}},{"id":"P1_U3_MCQ_215","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_215","question":"An urban food-delivery app places large illuminated billboards at busy commuter train stations. What design rule is most important for 'outdoor billboard advertising'?","options":{"A":"Include 500 words of detailed small-print terms and conditions","B":"Omit the brand name and app logo so commuters must guess the company","C":"Use bold visuals and a short, memorable 5-to-7-word headline because commuters pass by in just a few seconds","D":"Avoid placing billboards in high-footfall city centres"},"correctOption":"C","correctAnswer":"Use bold visuals and a short, memorable 5-to-7-word headline because commuters pass by in just a few seconds","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because outdoor posters have brief viewing windows, requiring instant visual clarity and concise messaging.","distractor_reasons":{"A":"Incorrect because passing commuters cannot read long paragraphs.","B":"Incorrect because clear brand identification is essential.","C":"Option C is correct because outdoor posters have brief viewing windows, requiring instant visual clarity and concise messaging.","D":"Incorrect because high-traffic commuter hubs maximize billboard exposure."}}},{"id":"P1_U3_MCQ_216","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_216","question":"A new plant-based burger brand sets up cooking booths inside 50 supermarkets to hand out free hot bite-sized samples to weekend shoppers. Why is 'free sampling' an effective sales promotion for food launches?","options":{"A":"Free samples are completely free for the company to produce and staff","B":"Supermarkets legally require every new food product to give away free samples","C":"Free sampling eliminates the need to put nutritional labels on retail packs","D":"Tasting the product removes shopper scepticism about unfamiliar flavours and triggers immediate impulse purchases"},"correctOption":"D","correctAnswer":"Tasting the product removes shopper scepticism about unfamiliar flavours and triggers immediate impulse purchases","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because consumers hesitate to spend money on unfamiliar foods; tasting proves quality firsthand and converts trial into sales.","distractor_reasons":{"A":"Incorrect because producing sample stock and hiring demonstrators incurs significant cost.","B":"Incorrect because sampling is a voluntary promotional choice.","C":"Incorrect because full retail packs still require statutory labels.","D":"Option D is correct because consumers hesitate to spend money on unfamiliar foods; tasting proves quality firsthand and converts trial into sales."}}},{"id":"P1_U3_MCQ_217","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_217","question":"A confectionery company pays supermarkets to place brightly coloured cardboard display stands of its chocolate bars right next to the checkout queues. What is this promotional technique called?","options":{"A":"Point-of-sale (POS) merchandising display","B":"Public relations press conference","C":"Personal B2B consultative selling","D":"External secondary desk research"},"correctOption":"A","correctAnswer":"Point-of-sale (POS) merchandising display","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because point-of-sale displays catch shoppers' eyes at the exact moment of payment, driving high-margin impulse buys.","distractor_reasons":{"A":"Option A is correct because point-of-sale displays catch shoppers' eyes at the exact moment of payment, driving high-margin impulse buys.","B":"Incorrect because PR press conferences target journalists rather than checkout queues.","C":"Incorrect because personal selling involves one-to-one sales staff.","D":"Incorrect because POS displays are an in-store sales promotion tool."}}},{"id":"P1_U3_MCQ_218","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_218","question":"A soft-drinks brand runs an on-pack competition offering a chance to win concert tickets by entering a code printed inside bottle caps. What is a common limitation of such 'sales promotions'?","options":{"A":"Competitions are illegal in all consumer retail markets","B":"Sales often jump temporarily while the prize draw runs, but may drop back once the promotion ends if underlying brand loyalty is weak","C":"Every single customer must be awarded a concert ticket by law","D":"Competitions reduce product visibility on supermarket shelves"},"correctOption":"B","correctAnswer":"Sales often jump temporarily while the prize draw runs, but may drop back once the promotion ends if underlying brand loyalty is weak","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because sales promotions create short-term spikes rather than permanent shifts in consumer preference unless paired with strong product value.","distractor_reasons":{"A":"Incorrect because promotional prize draws are lawful when run under fair rules.","B":"Option B is correct because sales promotions create short-term spikes rather than permanent shifts in consumer preference unless paired with strong product value.","C":"Incorrect because prize draws award prizes to randomly drawn winners.","D":"Incorrect because promotional packaging typically boosts shelf attention."}}},{"id":"P1_U3_MCQ_219","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_219","question":"An outdoor-apparel company donates waterproof jackets to mountain-rescue volunteers and sends a press release to national newspapers, resulting in favourable news articles. What is a key advantage and disadvantage of 'Public Relations (PR)'?","options":{"A":"News coverage is very expensive to buy, but the company controls every word printed by journalists","B":"PR is completely illegal for profit-making limited companies","C":"Editorial news coverage carries high public credibility at low media cost, but the business cannot control whether or how journalists report the story","D":"PR guarantees immediate 50% sales increases within twenty-four hours"},"correctOption":"C","correctAnswer":"Editorial news coverage carries high public credibility at low media cost, but the business cannot control whether or how journalists report the story","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because consumers trust independent news stories more than paid ads, though editors retain total control over publication.","distractor_reasons":{"A":"Incorrect because earned PR media space is unpaid and editors—not the firm—control the wording.","B":"Incorrect because PR is a standard, lawful marketing function.","C":"Option C is correct because consumers trust independent news stories more than paid ads, though editors retain total control over publication.","D":"Incorrect because PR builds long-term goodwill rather than guaranteeing instant sales spikes."}}},{"id":"P1_U3_MCQ_220","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_220","question":"A telecommunications company pays to become the official shirt sponsor of a popular national football club. How does 'sponsorship' benefit the sponsor's marketing mix?","options":{"A":"It eliminates the need to maintain mobile phone towers or customer service","B":"It legally prevents rival telecom companies from advertising anywhere in the country","C":"It lowers the company's annual corporate tax rate to 0%","D":"It exposes the brand logo repeatedly to millions of passionate fans and associates the company with positive sporting excitement"},"correctOption":"D","correctAnswer":"It exposes the brand logo repeatedly to millions of passionate fans and associates the company with positive sporting excitement","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because sports sponsorship builds massive repeated brand visibility and transfers fan goodwill to the sponsor.","distractor_reasons":{"A":"Incorrect because network quality remains vital to retain subscribers.","B":"Incorrect because sponsorship grants exclusive club rights rather than banning rivals from general advertising.","C":"Incorrect because sponsorship does not eliminate corporate tax.","D":"Option D is correct because sports sponsorship builds massive repeated brand visibility and transfers fan goodwill to the sponsor."}}},{"id":"P1_U3_MCQ_221","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_221","question":"A commercial real-estate agency assigns dedicated property advisors to tour office buildings with corporate clients and negotiate custom lease terms. Why is 'personal selling' justified despite its high cost per client?","options":{"A":"Corporate clients are legally forbidden from viewing property photos online","B":"Personal selling is cheaper per contact than posting a single social media update","C":"Each commercial property lease is high-value and complex, requiring tailored negotiation and trust that mass advertising cannot close alone","D":"Personal selling requires zero commission or salary payments to advisors"},"correctOption":"C","correctAnswer":"Each commercial property lease is high-value and complex, requiring tailored negotiation and trust that mass advertising cannot close alone","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because high-ticket transactions justify high personal-selling expenses when bespoke answers close lucrative contracts.","distractor_reasons":{"A":"Incorrect because online listings introduce properties before personal tours occur.","B":"Incorrect because personal selling has a very high cost per contact.","C":"Option C is correct because high-ticket transactions justify high personal-selling expenses when bespoke answers close lucrative contracts.","D":"Incorrect because skilled advisors earn substantial salaries and commissions."}}},{"id":"P1_U3_MCQ_222","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_222","question":"When a shopper places running shoes into an online cart on a sportswear website but leaves without paying, the site sends an automated email two hours later offering free express shipping to complete the order. Which promotional tool is this?","options":{"A":"National television broadcast advertising","B":"Targeted digital direct marketing / email remarketing","C":"Outdoor highway billboard advertising","D":"In-store supermarket shelf wobbler"},"correctOption":"B","correctAnswer":"Targeted digital direct marketing / email remarketing","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because personalized triggered emails follow up directly with warm prospects to convert abandoned carts into completed sales.","distractor_reasons":{"A":"Incorrect because TV broadcasts to mass audiences rather than individual website visitors.","B":"Option B is correct because personalized triggered emails follow up directly with warm prospects to convert abandoned carts into completed sales.","C":"Incorrect because billboards are physical outdoor media.","D":"Incorrect because shelf wobblers are physical retail displays."}}},{"id":"P1_U3_MCQ_223","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_223","question":"How does 'social media marketing' differ fundamentally from traditional one-way newspaper or television advertising?","options":{"A":"Social media marketing is always completely free even when running paid targeted ad campaigns","B":"Social media platforms prohibit customers from posting comments or reviews","C":"Social media enables instant two-way dialogue, viral user sharing, and precise demographic/interest targeting","D":"Social media marketing can only be viewed on desktop computers in offices"},"correctOption":"C","correctAnswer":"Social media enables instant two-way dialogue, viral user sharing, and precise demographic/interest targeting","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because social platforms turn passive audiences into interactive participants who comment, share, and provide immediate engagement analytics.","distractor_reasons":{"A":"Incorrect because paid social ads and content creation incur real budgets.","B":"Incorrect because public comments and reviews are defining features of social platforms.","C":"Option C is correct because social platforms turn passive audiences into interactive participants who comment, share, and provide immediate engagement analytics.","D":"Incorrect because social media is accessed predominantly via mobile smartphones."}}},{"id":"P1_U3_MCQ_224","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_224","question":"A startup launching a brand-new food-delivery app allocates 35% of its first-year budget to promotion, whereas a long-established regional water utility spends less than 1%. Which factor explains this difference in 'marketing budgets'?","options":{"A":"Water utilities are legally forbidden from communicating with households","B":"Food-delivery apps have zero variable delivery costs","C":"Startups always earn higher first-year net profits than established utilities","D":"A new brand in a competitive market must build awareness from zero, whereas an established monopoly utility already has captive customers"},"correctOption":"D","correctAnswer":"A new brand in a competitive market must build awareness from zero, whereas an established monopoly utility already has captive customers","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Product Life Cycle stage (introduction vs maturity) and competitive intensity strongly govern required promotional spending.","distractor_reasons":{"A":"Incorrect because utilities send bills and service notices regularly.","B":"Incorrect because delivery apps incur significant courier and app-operating costs.","C":"Incorrect because startups typically incur launch losses while building scale.","D":"Option D is correct because Product Life Cycle stage (introduction vs maturity) and competitive intensity strongly govern required promotional spending."}}},{"id":"P1_U3_MCQ_225","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_225","question":"To launch a new smart fitness ring, a tech company combines tech-journalist preview reviews (PR), short-form workout influencer videos (social media), and a 15% pre-order launch code (sales promotion). Why is using a 'cohesive promotional mix' superior to relying on one single method?","options":{"A":"Different promotional tools reinforce each other—PR builds credibility, social media drives awareness, and launch codes trigger immediate purchases","B":"Combining three methods eliminates all promotional expenses","C":"Using multiple methods guarantees that the product never needs customer support","D":"Regulators require every product launch to use at least three advertising channels"},"correctOption":"A","correctAnswer":"Different promotional tools reinforce each other—PR builds credibility, social media drives awareness, and launch codes trigger immediate purchases","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because each promotional tool has distinct strengths; integrating them moves buyers smoothly from awareness to trust and action.","distractor_reasons":{"A":"Option A is correct because each promotional tool has distinct strengths; integrating them moves buyers smoothly from awareness to trust and action.","B":"Incorrect because running multiple coordinated activities requires careful budget allocation.","C":"Incorrect because post-purchase customer support remains vital for tech hardware.","D":"Incorrect because promotional mix choices are strategic rather than legally mandated."}}},{"id":"P1_U3_MCQ_226","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_226","question":"A skincare brand conducts customer research, selects environmentally conscious millennials as its target segment, and aligns refillable glass packaging, mid-premium pricing, e-commerce delivery, and influencer education campaigns. What has the brand created?","options":{"A":"An internal human resource redundancy plan","B":"A coherent, integrated marketing strategy built around a clear target market","C":"A product-oriented cost-plus accounting ledger","D":"An undifferentiated mass-market clearance policy"},"correctOption":"B","correctAnswer":"A coherent, integrated marketing strategy built around a clear target market","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a marketing strategy links market research and segmentation to a consistent, mutually reinforcing 4Ps marketing mix.","distractor_reasons":{"A":"Incorrect because redundancy planning belongs to Unit 2 Human Resources.","B":"Option B is correct because a marketing strategy links market research and segmentation to a consistent, mutually reinforcing 4Ps marketing mix.","C":"Incorrect because the brand started with customer research rather than unresearched production.","D":"Incorrect because the brand specifically targeted eco-conscious millennials."}}},{"id":"P1_U3_MCQ_227","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_227","question":"An organic baby-food startup targets high-income, health-conscious parents. Which marketing mix combination best supports this 'marketing strategy'?","options":{"A":"Bulk 5-kilogram plastic tubs priced at $2, sold via roadside discount warehouses","B":"Unlabelled generic jars sold exclusively through late-night vending machines","C":"Certified organic BPA-free glass pouches, premium pricing, selective distribution in upscale grocers and online subscriptions, and paediatrician-endorsed parenting blogs","D":"High-sugar formula promoted via extreme-sports television commercials"},"correctOption":"C","correctAnswer":"Certified organic BPA-free glass pouches, premium pricing, selective distribution in upscale grocers and online subscriptions, and paediatrician-endorsed parenting blogs","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because safe organic packaging, premium value pricing, trusted retail channels, and credible expert promotion align seamlessly with anxious, affluent parents' priorities.","distractor_reasons":{"A":"Incorrect because bulk plastic tubs and discount warehouses clash with affluent organic parent expectations.","B":"Incorrect because unlabelled jars violate food laws and fail to build parental trust.","C":"Option C is correct because safe organic packaging, premium value pricing, trusted retail channels, and credible expert promotion align seamlessly with anxious, affluent parents' priorities.","D":"Incorrect because high sugar and extreme sports misalign completely with infant nutrition."}}},{"id":"P1_U3_MCQ_228","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_228","question":"A consumer-goods company launches a new everyday household laundry detergent aimed at budget-conscious mass-market families. Which marketing mix is most appropriate?","options":{"A":"Hand-numbered crystal bottles priced at $95, sold only in one boutique","B":"Personal door-to-door sales engineers visiting every household individually","C":"Price skimming at $60 per box with zero supermarket distribution","D":"Large economy family packs, competitive supermarket pricing, intensive grocery distribution, and TV/digital ads paired with money-off coupons"},"correctOption":"D","correctAnswer":"Large economy family packs, competitive supermarket pricing, intensive grocery distribution, and TV/digital ads paired with money-off coupons","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because everyday mass-market staples require affordable value packs, wide retail convenience, and broad promotional reach.","distractor_reasons":{"A":"Incorrect because crystal bottles and $95 pricing target ultra-luxury niches.","B":"Incorrect because personal selling is far too expensive for low-priced household staples.","C":"Incorrect because skipping supermarkets blocks access to everyday grocery shoppers.","D":"Option D is correct because everyday mass-market staples require affordable value packs, wide retail convenience, and broad promotional reach."}}},{"id":"P1_U3_MCQ_229","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_229","question":"A smart-thermostat brand moves from the 'Introduction stage' into the 'Maturity stage' as six rivals launch similar devices. How should its marketing strategy evolve?","options":{"A":"Discontinue the thermostat immediately while sales are at their peak","B":"Cut retail distribution to one store and raise prices by 50%","C":"Stop all product updates and rely solely on early-adopter word-of-mouth","D":"Shift from informative launch ads and high skimming prices toward persuasive brand differentiation, competitive bundle pricing, and wider retail distribution"},"correctOption":"D","correctAnswer":"Shift from informative launch ads and high skimming prices toward persuasive brand differentiation, competitive bundle pricing, and wider retail distribution","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because maturity brings intense competition, requiring broader availability, sharper value pricing, and persuasive differentiation.","distractor_reasons":{"A":"Incorrect because maturity is the highest-volume profit phase and should be defended or extended.","B":"Incorrect because restricting distribution and hiking prices when rivals enter causes rapid share loss.","C":"Incorrect because mainstream buyers need persuasive promotion and ongoing software/feature upgrades.","D":"Option D is correct because maturity brings intense competition, requiring broader availability, sharper value pricing, and persuasive differentiation."}}},{"id":"P1_U3_MCQ_230","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_230","question":"A major rival cuts prices on its cordless vacuum cleaners by 15%. Rather than matching the price cut and destroying profit margins, how can an established vacuum brand respond strategically?","options":{"A":"Ignore the competitor completely and reduce product warranty coverage","B":"Differentiate through value-added promotion—offering a free extra battery pack, a 5-year warranty, and persuasive ads highlighting superior suction power","C":"Close its online store and rely solely on wholesale cash-and-carry depots","D":"Raise its vacuum prices by 40% without adding any features"},"correctOption":"B","correctAnswer":"Differentiate through value-added promotion—offering a free extra battery pack, a 5-year warranty, and persuasive ads highlighting superior suction power","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because non-price competition (added accessories, extended warranties, quality positioning) protects brand equity and avoids destructive price wars.","distractor_reasons":{"A":"Incorrect because cutting warranties weakens perceived value against a cheaper rival.","B":"Option B is correct because non-price competition (added accessories, extended warranties, quality positioning) protects brand equity and avoids destructive price wars.","C":"Incorrect because closing direct online sales restricts customer convenience.","D":"Incorrect because steep unsubstantiated price hikes widen the price gap further."}}},{"id":"P1_U3_MCQ_231","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_231","question":"During a strong economic boom with rising employment and consumer confidence, how should a home-renovation and furniture retailer adapt its marketing strategy?","options":{"A":"Discontinue all stylish higher-margin furniture ranges and sell only basic plastic chairs","B":"Cut promotional budgets to zero because consumers never shop during economic booms","C":"Promote higher-margin premium room collections, bespoke design consultations, and flexible upgrade packages to capture rising disposable income","D":"Switch exclusively to distress clearance pricing across all showrooms"},"correctOption":"C","correctAnswer":"Promote higher-margin premium room collections, bespoke design consultations, and flexible upgrade packages to capture rising disposable income","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because rising household incomes increase demand for big-ticket discretionary home upgrades and premium designs.","distractor_reasons":{"A":"Incorrect because booms shift spending toward higher-value goods rather than bare basics.","B":"Incorrect because active promotion helps capture growing consumer spending ahead of rivals.","C":"Option C is correct because rising household incomes increase demand for big-ticket discretionary home upgrades and premium designs.","D":"Incorrect because heavy discounting sacrifices margins unnecessarily when demand is strong."}}},{"id":"P1_U3_MCQ_232","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_232","question":"A European household-appliance maker faces a saturated domestic market where almost every household already owns a refrigerator. Why is expanding into fast-growing emerging foreign markets an attractive strategic opportunity?","options":{"A":"Emerging foreign markets never have any local competitors or import rules","B":"Shipping heavy refrigerators overseas costs zero freight or insurance","C":"Consumers in emerging markets prefer broken appliances without warranties","D":"Rising middle-class incomes abroad create millions of first-time buyers, enabling rapid sales growth and economies of scale"},"correctOption":"D","correctAnswer":"Rising middle-class incomes abroad create millions of first-time buyers, enabling rapid sales growth and economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because entering expanding overseas markets overcomes domestic saturation and extends product life cycles.","distractor_reasons":{"A":"Incorrect because emerging markets feature local rivals and regulatory requirements.","B":"Incorrect because international freight and insurance are real expenses.","C":"Incorrect because reliable quality and warranties remain vital to build trust abroad.","D":"Option D is correct because entering expanding overseas markets overcomes domestic saturation and extends product life cycles."}}},{"id":"P1_U3_MCQ_233","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_233","question":"A North American beverage company translates its catchy English slogan word-for-word into a foreign language, accidentally creating an offensive slang phrase that triggers a consumer boycott. Which foreign market entry risk does this illustrate?","options":{"A":"Currency exchange-rate appreciation making exports expensive","B":"High import tariffs imposed by customs authorities","C":"Linguistic and cultural translation errors resulting from insufficient local market research","D":"Lack of factory production capacity in the home country"},"correctOption":"C","correctAnswer":"Linguistic and cultural translation errors resulting from insufficient local market research","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because idioms and brand names rarely translate literally; local cultural consultation is essential before launching campaigns abroad.","distractor_reasons":{"A":"Incorrect because exchange rates affect pricing rather than linguistic meaning.","B":"Incorrect because tariffs are trade taxes rather than slogan translation mistakes.","C":"Option C is correct because idioms and brand names rarely translate literally; local cultural consultation is essential before launching campaigns abroad.","D":"Incorrect because the boycott was triggered by offensive messaging rather than stock shortages."}}},{"id":"P1_U3_MCQ_234","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_234","question":"A British textile manufacturer exports wool coats priced in British pounds (£) to retail buyers in the United States. If the British pound appreciates (strengthens) sharply against the US dollar ($), how does this affect the exporter's foreign marketing competitiveness?","options":{"A":"British coats become much cheaper in US dollars, boosting US orders automatically","B":"British coats become more expensive in US dollars, reducing price competitiveness against US and rival foreign brands","C":"Exchange-rate movements have zero effect on export prices paid by foreign importers","D":"The British manufacturer is exempted from paying UK wages and raw-material bills"},"correctOption":"B","correctAnswer":"British coats become more expensive in US dollars, reducing price competitiveness against US and rival foreign brands","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a stronger home currency requires foreign buyers to spend more of their own currency per pound, raising export prices.","distractor_reasons":{"A":"Incorrect because a stronger pound makes UK exports dearer in dollars (currency depreciation makes exports cheaper).","B":"Option B is correct because a stronger home currency requires foreign buyers to spend more of their own currency per pound, raising export prices.","C":"Incorrect because currency conversion directly alters foreign-currency retail prices or exporter margins.","D":"Incorrect because domestic operating costs remain unchanged."}}},{"id":"P1_U3_MCQ_235","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_235","question":"Before exporting electric hairdryers from Europe to North America and Japan, a manufacturer must redesign the electrical plugs, voltage ratings, and safety certification labels. Which challenge of entering foreign markets does this represent?","options":{"A":"Adapting products to comply with differing national technical standards and legal regulations","B":"Overcoming seasonal weather differences between cities","C":"Using quota sampling to choose factory assembly workers","D":"Eliminating all wholesale and retail intermediaries"},"correctOption":"A","correctAnswer":"Adapting products to comply with differing national technical standards and legal regulations","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because foreign markets enforce distinct electrical, safety, and labelling laws that require product adaptation before sale.","distractor_reasons":{"A":"Option A is correct because foreign markets enforce distinct electrical, safety, and labelling laws that require product adaptation before sale.","B":"Incorrect because voltage and plug differences are technical/regulatory rather than weather-related.","C":"Incorrect because quota sampling is a survey research method.","D":"Incorrect because exporters still use local distributors or retailers."}}},{"id":"P1_U3_MCQ_236","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_236","question":"A medium-sized footwear brand wants to enter three foreign countries quickly without investing millions in building overseas company-owned stores. Why might it export through established foreign retail distributors rather than opening wholly owned subsidiaries?","options":{"A":"Foreign distributors never earn any profit margin on shoes sold","B":"Wholly owned subsidiaries are illegal in every foreign country","C":"Exporting via distributors eliminates all shipping and customs tariffs","D":"It requires far lower upfront capital investment and leverages existing local store networks, even though profit margins are shared"},"correctOption":"D","correctAnswer":"It requires far lower upfront capital investment and leverages existing local store networks, even though profit margins are shared","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because using local distributors lowers financial risk and speeds market entry when capital and local knowledge are limited.","distractor_reasons":{"A":"Incorrect because distributors take a wholesale/retail margin for their services.","B":"Incorrect because wholly owned subsidiaries are lawful in most countries, just very expensive.","C":"Incorrect because exported goods still cross borders subject to freight and applicable tariffs.","D":"Option D is correct because using local distributors lowers financial risk and speeds market entry when capital and local knowledge are limited."}}},{"id":"P1_U3_MCQ_237","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_237","question":"In a foreign country where laws forbid 100% foreign ownership of telecommunications networks, a European mobile operator partners 50/50 with a local company to build a new 5G network. Why is a 'joint venture' ideal here?","options":{"A":"It eliminates all competition from rival mobile networks","B":"It allows the European operator to keep 100% of all profits without consulting the local partner","C":"It guarantees that zero capital investment is needed to build 5G towers","D":"It satisfies local ownership regulations while combining the European firm's 5G technology with the local partner's regulatory access and customer base"},"correctOption":"D","correctAnswer":"It satisfies local ownership regulations while combining the European firm's 5G technology with the local partner's regulatory access and customer base","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because joint ventures unlock restricted foreign markets and share massive infrastructure costs and risks.","distractor_reasons":{"A":"Incorrect because rival telecom firms still compete in the market.","B":"Incorrect because profits and strategic control are shared between both partners.","C":"Incorrect because both partners contribute capital to build the network.","D":"Option D is correct because joint ventures unlock restricted foreign markets and share massive infrastructure costs and risks."}}},{"id":"P1_U3_MCQ_238","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_238","question":"Shipping heavy glass bottles of soft drinks across oceans is prohibitively expensive relative to their retail price. How does 'licensing' local overseas bottling companies solve this problem?","options":{"A":"The brand owner gives away its secret recipe for free without earning royalties","B":"The foreign licensee produces and bottles the drink locally using the brand's formula and trademark in return for royalty fees, avoiding heavy liquid shipping costs and import tariffs","C":"The brand owner builds and staffs 50 wholly owned overseas bottling plants itself","D":"Licensing prevents foreign consumers from ever tasting the beverage"},"correctOption":"B","correctAnswer":"The foreign licensee produces and bottles the drink locally using the brand's formula and trademark in return for royalty fees, avoiding heavy liquid shipping costs and import tariffs","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because local production under license eliminates bulky cross-border freight while generating low-risk royalty revenue.","distractor_reasons":{"A":"Incorrect because licensors earn contracted royalty fees on licensee production/sales.","B":"Option B is correct because local production under license eliminates bulky cross-border freight while generating low-risk royalty revenue.","C":"Incorrect because the local licensee funds its own bottling facilities.","D":"Incorrect because local bottling increases availability and freshness for foreign buyers."}}},{"id":"P1_U3_MCQ_239","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_239","question":"A global burger chain expands abroad through 'franchising' and conducts strict unannounced hygiene, recipe, and service inspections at overseas outlets. Why are these inspections essential?","options":{"A":"Because the franchisor pays 100% of every franchisee's daily restaurant electricity and wage bills","B":"Because franchisees are forbidden from earning any profit from their restaurants","C":"Because poor food hygiene or inconsistent quality at one overseas franchise damages the entire brand's global reputation","D":"Because franchising is illegal without government food tasters present every day"},"correctOption":"C","correctAnswer":"Because poor food hygiene or inconsistent quality at one overseas franchise damages the entire brand's global reputation","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because customers view all outlets under the same brand logo as one company, so quality failures anywhere harm global trust.","distractor_reasons":{"A":"Incorrect because franchisees fund their own local operating expenses.","B":"Incorrect because franchisees keep remaining profits after paying royalties.","C":"Option C is correct because customers view all outlets under the same brand logo as one company, so quality failures anywhere harm global trust.","D":"Incorrect because quality audits are enforced contractually by the franchisor."}}},{"id":"P1_U3_MCQ_240","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_240","question":"What is a major strategic advantage for a successful domestic bakery-café brand expanding internationally via 'franchising' rather than opening company-owned branches?","options":{"A":"The franchisor retains 100% of every café's net profit","B":"The franchisor avoids giving franchisees any training or operating manuals","C":"Franchisees have no motivation to work hard because they earn fixed hourly wages","D":"Rapid international expansion is funded largely by franchisees' initial fees and capital, while local owners bring strong entrepreneurial motivation"},"correctOption":"D","correctAnswer":"Rapid international expansion is funded largely by franchisees' initial fees and capital, while local owners bring strong entrepreneurial motivation","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because franchising scales a proven business model quickly with lower capital outlay and motivated local owner-operators.","distractor_reasons":{"A":"Incorrect because the franchisor earns upfront fees and percentage royalties rather than 100% of store profits.","B":"Incorrect because comprehensive training and brand manuals are vital to franchise success.","C":"Incorrect because franchisees invest their own capital and profit directly from store success.","D":"Option D is correct because franchising scales a proven business model quickly with lower capital outlay and motivated local owner-operators."}}},{"id":"P1_U3_MCQ_241","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_241","question":"A global streaming platform keeps its core brand logo and app interface identical worldwide, but produces local-language dramas and accepts local mobile-wallet payments in each country. Which international marketing approach is this?","options":{"A":"Domestic-only niche withdrawal","B":"Pure undifferentiated mass standardization","C":"Product-oriented cost-plus exporting","D":"Glocalization ('think global, act local'—balancing global brand consistency with local adaptation)"},"correctOption":"D","correctAnswer":"Glocalization ('think global, act local'—balancing global brand consistency with local adaptation)","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because glocalization captures global brand recognition and technical scale while tailoring content and payment convenience to local cultures.","distractor_reasons":{"A":"Incorrect because the platform is expanding globally rather than withdrawing domestically.","B":"Incorrect because pure standardization ignores local languages and payment methods.","C":"Incorrect because tailoring shows to local audiences is strongly market-oriented.","D":"Option D is correct because glocalization captures global brand recognition and technical scale while tailoring content and payment convenience to local cultures."}}},{"id":"P1_U3_MCQ_242","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_242","question":"A concert-ticketing website advertises tickets at '$40', but only reveals unavoidable '$18 booking and facility fees' on the final payment screen. Why do consumer protection authorities penalize this 'drip pricing'?","options":{"A":"Concert tickets are legally required to be sold free of charge","B":"Hiding mandatory fees until checkout deceives consumers about the true total price and prevents fair price comparison","C":"Online ticket sites are forbidden from charging any service fees","D":"Drip pricing reduces consumer demand to zero across all industries"},"correctOption":"B","correctAnswer":"Hiding mandatory fees until checkout deceives consumers about the true total price and prevents fair price comparison","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because fair-trading regulations require upfront display of the full unavoidable price so buyers are not misled.","distractor_reasons":{"A":"Incorrect because tickets are commercial products.","B":"Option B is correct because fair-trading regulations require upfront display of the full unavoidable price so buyers are not misled.","C":"Incorrect because booking fees are lawful if included transparently in the upfront headline price.","D":"Incorrect because drip pricing exploits shoppers until checkout rather than eliminating demand."}}},{"id":"P1_U3_MCQ_243","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_243","question":"A clothing brand prints '100% Eco-Sustainable Carbon-Zero T-Shirt' on its labels without any verified environmental data or offset evidence. Which legal marketing violation is occurring?","options":{"A":"Predatory monopoly price-fixing","B":"Failure to pay statutory employee overtime wages","C":"Misleading environmental advertising ('greenwashing') that makes unsubstantiated claims to deceive eco-conscious buyers","D":"Violation of international patent licensing quotas"},"correctOption":"C","correctAnswer":"Misleading environmental advertising ('greenwashing') that makes unsubstantiated claims to deceive eco-conscious buyers","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because advertising standards and consumer laws require all environmental and performance claims to be truthful and backed by objective proof.","distractor_reasons":{"A":"Incorrect because price-fixing involves collusion among rivals over prices.","B":"Incorrect because employee wages belong to employment law rather than marketing claims.","C":"Option C is correct because advertising standards and consumer laws require all environmental and performance claims to be truthful and backed by objective proof.","D":"Incorrect because patent licensing protects technical inventions."}}},{"id":"P1_U3_MCQ_244","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_244","question":"Before selling children's pyjamas or electric heaters, a manufacturer must pass mandatory flammability and electrical-insulation tests enforced by consumer safety legislation. How does this law impact the business?","options":{"A":"It lowers product design and testing expenses to zero","B":"It allows the manufacturer to sell untested imports at double profit margins","C":"It applies only to small sole traders and exempts multinational corporations","D":"It increases R&D and quality-testing costs, but prevents dangerous injuries, product recalls, and severe legal fines"},"correctOption":"D","correctAnswer":"It increases R&D and quality-testing costs, but prevents dangerous injuries, product recalls, and severe legal fines","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because product safety laws impose compliance costs while safeguarding consumers and protecting reputable firms from unsafe low-cost rivals.","distractor_reasons":{"A":"Incorrect because safety testing adds real R&D and compliance costs.","B":"Incorrect because all products sold must meet safety standards regardless of origin.","C":"Incorrect because safety regulations bind all businesses equally.","D":"Option D is correct because product safety laws impose compliance costs while safeguarding consumers and protecting reputable firms from unsafe low-cost rivals."}}},{"id":"P1_U3_MCQ_245","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_245","question":"A coffee roaster sells bags printed with 'Net Weight 500g', but government inspectors discover bags routinely contain only 440g due to uncalibrated filling machines. Which consumer law is breached?","options":{"A":"Weights and measures legislation requiring goods sold by weight or volume to match their stated quantity accurately","B":"Trade union recognition and collective bargaining legislation","C":"Copyright protection over original musical compositions","D":"Dynamic surge pricing regulations"},"correctOption":"A","correctAnswer":"Weights and measures legislation requiring goods sold by weight or volume to match their stated quantity accurately","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because weights-and-measures laws protect consumers from being short-changed on packaged quantities.","distractor_reasons":{"A":"Option A is correct because weights-and-measures laws protect consumers from being short-changed on packaged quantities.","B":"Incorrect because union laws govern employer-employee relations.","C":"Incorrect because copyright protects creative works.","D":"Incorrect because dynamic pricing adjusts prices with demand rather than package weight."}}},{"id":"P1_U3_MCQ_246","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_246","question":"An online retailer collects customers' email addresses during checkout and automatically sells the email list to third-party telemarketers without customer consent. Which legal control is being violated?","options":{"A":"Weights and measures packaging rules","B":"Data protection and consumer privacy legislation governing how personal customer data is stored, used, and shared","C":"Factory health and safety machinery rules","D":"Import tariff customs valuation rules"},"correctOption":"B","correctAnswer":"Data protection and consumer privacy legislation governing how personal customer data is stored, used, and shared","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because data protection laws prohibit sharing or using personal consumer data for direct marketing without explicit permission.","distractor_reasons":{"A":"Incorrect because weights and measures govern physical product quantities.","B":"Option B is correct because data protection laws prohibit sharing or using personal consumer data for direct marketing without explicit permission.","C":"Incorrect because factory safety laws govern physical workplace hazards.","D":"Incorrect because customs rules govern cross-border goods taxes."}}},{"id":"P1_U3_MCQ_247","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_247","question":"In many countries, governments ban television commercials for high-sugar junk food during children's programming hours and prohibit tobacco advertising altogether. How must affected businesses adapt their marketing?","options":{"A":"Ignore the advertising bans and pay daily criminal fines indefinitely","B":"Continue airing children's TV ads using cartoon mascots","C":"Reformulate healthier low-sugar product lines or shift promotional budgets toward compliant adult channels, packaging, and in-store displays","D":"Stop maintaining product quality or financial accounts"},"correctOption":"C","correctAnswer":"Reformulate healthier low-sugar product lines or shift promotional budgets toward compliant adult channels, packaging, and in-store displays","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because legal advertising restrictions force firms either to innovate compliant healthier products or adjust their promotional mix within the law.","distractor_reasons":{"A":"Incorrect because persistent non-compliance leads to severe penalties and broadcast bans.","B":"Incorrect because cartoon mascots on restricted ads directly breach child-marketing rules.","C":"Option C is correct because legal advertising restrictions force firms either to innovate compliant healthier products or adjust their promotional mix within the law.","D":"Incorrect because operational quality and accounting remain essential."}}},{"id":"P1_U3_MCQ_248","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_248","question":"A customer orders a dining table online advertised as '100% Solid Walnut Wood', but receives a table made of cheap chipboard covered in thin plastic wood-grain sticker. Which statutory consumer right applies?","options":{"A":"The buyer must keep the table because online descriptions are never legally binding","B":"The seller only has to offer a 5% discount coupon toward a future purchase","C":"Consumer protection laws apply only to food and medicine, not furniture","D":"Goods must match their description ('as described'), entitling the customer to reject the table and receive a full refund"},"correctOption":"D","correctAnswer":"Goods must match their description ('as described'), entitling the customer to reject the table and receive a full refund","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because consumer protection statutes require products to correspond accurately with seller descriptions and samples.","distractor_reasons":{"A":"Incorrect because product descriptions form a legally binding part of the sales contract.","B":"Incorrect because a misdescribed item entitles the buyer to a full refund rather than a tiny voucher.","C":"Incorrect because consumer goods laws cover all consumer products including furniture.","D":"Option D is correct because consumer protection statutes require products to correspond accurately with seller descriptions and samples."}}},{"id":"P1_U3_MCQ_249","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_249","question":"How do strict, well-enforced 'consumer protection laws' ultimately benefit honest, quality-focused businesses?","options":{"A":"They guarantee that every new product launched will achieve 50% market share","B":"They allow honest businesses to charge unlimited monopoly prices without competition","C":"They eliminate all compliance, testing, and customer-service costs","D":"They build consumer confidence to buy—especially online—and prevent dishonest competitors from undercutting reputable firms with unsafe or misdescribed goods"},"correctOption":"D","correctAnswer":"They build consumer confidence to buy—especially online—and prevent dishonest competitors from undercutting reputable firms with unsafe or misdescribed goods","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because strong legal standards create a fair competitive playing field and increase shopper willingness to purchase.","distractor_reasons":{"A":"Incorrect because market share still depends on customer preference and competitive execution.","B":"Incorrect because competition laws prevent anti-competitive monopoly abuse.","C":"Incorrect because compliance and after-sales service still carry costs.","D":"Option D is correct because strong legal standards create a fair competitive playing field and increase shopper willingness to purchase."}}},{"id":"P1_U3_MCQ_250","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_250","question":"A mid-sized sportswear brand faces slowing domestic sales in a mature market and intense price competition from online fast-fashion rivals. Which integrated long-term 'marketing strategy' is most likely to restore profitable growth?","options":{"A":"Cut product fabric quality while raising domestic prices by 30% and stopping all digital marketing","B":"Develop differentiated performance-engineered activewear using recycled fabrics (Product/USP), expand direct-to-consumer e-commerce alongside selective foreign entry via local distributors (Place), and build community loyalty via fitness influencers (Promotion)","C":"Abandon market research completely and sell identical unbranded grey tracksuits solely through one local wholesale warehouse","D":"Use deceptive 'Was $200, Now $40' fake discount pricing on low-quality garments"},"correctOption":"B","correctAnswer":"Develop differentiated performance-engineered activewear using recycled fabrics (Product/USP), expand direct-to-consumer e-commerce alongside selective foreign entry via local distributors (Place), and build community loyalty via fitness influencers (Promotion)","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because combining product differentiation (sustainability/performance), omnichannel & international expansion, and targeted digital community building addresses both domestic maturity and online competition coherently.","distractor_reasons":{"A":"Incorrect because lowering quality while hiking prices accelerates customer defection.","B":"Option B is correct because combining product differentiation (sustainability/performance), omnichannel & international expansion, and targeted digital community building addresses both domestic maturity and online competition coherently.","C":"Incorrect because removing differentiation and restricting distribution weakens brand competitiveness.","D":"Incorrect because fictitious reference pricing violates consumer law and destroys brand trust."}}},{"id":"P1_U3_MCQ_251","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_251","question":"Before launching a range of ergonomic home-office chairs, a furniture manufacturer interviews remote workers about back-pain issues and desk space constraints. Which core function of marketing does this illustrate?","options":{"A":"Negotiating collective wage agreements with factory trade unions","B":"Maximizing factory machine utilization without checking buyer preferences","C":"Preparing statutory end-of-year profit and loss accounts for shareholders","D":"Identifying and anticipating customer needs so products can be designed and sold profitably"},"correctOption":"D","correctAnswer":"Identifying and anticipating customer needs so products can be designed and sold profitably","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because marketing begins with researching and anticipating consumer requirements in order to satisfy them profitably.","distractor_reasons":{"A":"Incorrect because industrial relations and wage negotiations belong to Human Resources.","B":"Incorrect because maximizing machine output regardless of buyer demand describes a product-oriented operations focus.","C":"Incorrect because preparing financial statements is the role of the Finance department.","D":"Option D is correct because marketing begins with researching and anticipating consumer requirements in order to satisfy them profitably."}}},{"id":"P1_U3_MCQ_252","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_252","question":"A boutique pet-supplies store tracks customers' dog birthdays and sends personalized grooming vouchers each year, resulting in 78% of buyers returning every month. Which marketing goal is the store achieving?","options":{"A":"Eliminating all variable inventory costs","B":"Building strong customer relationships and long-term brand loyalty","C":"Converting the business into a pure public-sector monopoly","D":"Operating a product-oriented mass-production assembly line"},"correctOption":"B","correctAnswer":"Building strong customer relationships and long-term brand loyalty","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because personalized engagement strengthens emotional trust and encourages repeat purchases over time.","distractor_reasons":{"A":"Incorrect because retail stores still incur stock and grooming supply costs.","B":"Option B is correct because personalized engagement strengthens emotional trust and encourages repeat purchases over time.","C":"Incorrect because private retail stores operate in competitive markets.","D":"Incorrect because tailoring vouchers to individual pets is customer-focused rather than product-oriented."}}},{"id":"P1_U3_MCQ_253","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_253","question":"Total annual sales in a national plant-based milk market equal $320 million, of which OatPure Ltd generates $48 million. What is OatPure Ltd's market share?","options":{"A":"6.7%","B":"48.0%","C":"15.0%","D":"18.0%"},"correctOption":"C","correctAnswer":"15.0%","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Market Share (%) = ($48m / $320m) × 100 = 15.0%.","distractor_reasons":{"A":"Incorrect because 6.7% divides $320m by $48m instead of $48m by $320m.","B":"Incorrect because 48.0% confuses dollar sales ($48m) with percentage market share.","C":"Option C is correct because Market Share (%) = ($48m / $320m) × 100 = 15.0%.","D":"Incorrect because 18.0% miscalculates the ratio between $48m and $320m."}}},{"id":"P1_U3_MCQ_254","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_254","question":"Over two years, total industry sales in the electric-scooter market expand by 30%, while VoltRide Ltd's sales revenue grows by 10%. How has VoltRide Ltd's competitive position changed?","options":{"A":"Its market share increased by 20%","B":"Its absolute sales revenue declined by 20%","C":"Its market share stayed exactly the same because sales rose","D":"Its market share fell because its sales grew more slowly than the overall market"},"correctOption":"D","correctAnswer":"Its market share fell because its sales grew more slowly than the overall market","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because when total market sales expand faster (+30%) than a firm's own sales (+10%), rivals capture a larger share of the market.","distractor_reasons":{"A":"Incorrect because growing slower than the market reduces rather than increases market share.","B":"Incorrect because VoltRide's sales rose by 10% in absolute terms.","C":"Incorrect because market share depends on relative growth compared with total industry sales.","D":"Option D is correct because when total market sales expand faster (+30%) than a firm's own sales (+10%), rivals capture a larger share of the market."}}},{"id":"P1_U3_MCQ_255","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_255","question":"A traditional confectionery company observes consumers increasingly checking nutrition labels and cutting back on high-sugar sodas and sweets. Which driver of changing consumer spending patterns is affecting this industry?","options":{"A":"A sudden decline in national literacy rates","B":"Growing health and wellness awareness shifting demand toward low-sugar, healthier alternatives","C":"Government bans on supermarkets selling any packaged beverages","D":"Falling average life expectancy reducing total grocery demand"},"correctOption":"B","correctAnswer":"Growing health and wellness awareness shifting demand toward low-sugar, healthier alternatives","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because heightened health consciousness changes consumer tastes away from sugary items toward functional or low-calorie products.","distractor_reasons":{"A":"Incorrect because consumers are actively reading nutrition labels.","B":"Option B is correct because heightened health consciousness changes consumer tastes away from sugary items toward functional or low-calorie products.","C":"Incorrect because supermarkets continue selling packaged beverages.","D":"Incorrect because health awareness—not falling life expectancy—drives low-sugar preferences."}}},{"id":"P1_U3_MCQ_256","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_256","question":"As dual-income households work longer hours and have less spare time for cooking from scratch, supermarkets report surging sales of pre-chopped vegetables and 15-minute meal kits. Which factor explains this spending shift?","options":{"A":"A massive drop in average household disposable income","B":"Changing lifestyles and higher demand for time-saving convenience products","C":"A legal ban on selling raw potatoes and fresh ingredients","D":"Decreasing availability of domestic kitchen refrigerators"},"correctOption":"B","correctAnswer":"Changing lifestyles and higher demand for time-saving convenience products","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because time-poor lifestyles increase willingness to pay for convenient, ready-to-cook food solutions.","distractor_reasons":{"A":"Incorrect because prepared meal kits cost more than raw ingredients, reflecting higher income and time scarcity.","B":"Option B is correct because time-poor lifestyles increase willingness to pay for convenient, ready-to-cook food solutions.","C":"Incorrect because raw ingredients remain widely sold.","D":"Incorrect because chilled meal kits actually rely on household refrigeration."}}},{"id":"P1_U3_MCQ_257","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_257","question":"A DVD rental chain is closing its high-street stores as households switch to monthly online streaming subscriptions. Which response best shows the business adapting to this change in customer needs?","options":{"A":"Reduce the number of staff in its existing stores","B":"Launch its own online streaming subscription service","C":"Lower the price of renting DVDs in store","D":"Open more high-street rental stores"},"correctOption":"B","correctAnswer":"Launch its own online streaming subscription service","questionType":"MCQ","explanation":{"correct_reason":"Moving into online streaming responds directly to customers' changed preference for convenient digital access to films.","distractor_reasons":{"A":"Cutting staff reduces costs but does not address the underlying change in what customers want.","B":"Offering streaming meets the new customer need for convenient, on-demand film access.","C":"Cheaper DVD rentals do not meet the wish to stream films, so the market change remains unaddressed.","D":"Opening more stores moves against the trend and ignores customers moving away from physical rentals."}}},{"id":"P1_U3_MCQ_258","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_258","question":"After a government removes import tariffs and licensing restrictions in the domestic airline sector, three low-cost foreign carriers launch routes into the country. Why has competition intensified for the existing national airline?","options":{"A":"Consumer demand for air travel fell to zero","B":"Fuel costs disappeared for all newly licensed airlines","C":"Foreign airlines are legally forbidden from advertising ticket prices","D":"Deregulation and lower entry barriers allowed new rival suppliers to enter the market"},"correctOption":"D","correctAnswer":"Deregulation and lower entry barriers allowed new rival suppliers to enter the market","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because removing regulatory and trade barriers enables new competitors to challenge established incumbents.","distractor_reasons":{"A":"Incorrect because lower fares from new airlines typically expand passenger demand.","B":"Incorrect because all airlines still pay fuel and operating expenses.","C":"Incorrect because new entrants actively promote low fares.","D":"Option D is correct because removing regulatory and trade barriers enables new competitors to challenge established incumbents."}}},{"id":"P1_U3_MCQ_259","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_259","question":"Facing aggressive price-cutting from rival online pharmacies, an established pharmacy chain automates its prescription-sorting warehouses to cut unit handling costs by 25%. How does this operational change help its marketing response?","options":{"A":"Lower handling costs allow the chain to stop distributing medicines to local branches","B":"Automation eliminates the need to employ qualified pharmacists in stores","C":"Warehouse automation guarantees that customers never compare medicine prices online","D":"Lower unit costs enable the chain to offer competitive prices without sacrificing profit margins"},"correctOption":"D","correctAnswer":"Lower unit costs enable the chain to offer competitive prices without sacrificing profit margins","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because improving operational efficiency supports sustainable competitive pricing when rivals slash prices.","distractor_reasons":{"A":"Incorrect because warehouse sorting supplies local branches faster.","B":"Incorrect because licensed pharmacists remain legally required in retail pharmacies.","C":"Incorrect because online price comparison persists, making cost efficiency vital.","D":"Option D is correct because improving operational efficiency supports sustainable competitive pricing when rivals slash prices."}}},{"id":"P1_U3_MCQ_260","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_260","question":"When two giant supermarket chains open branches near a family-owned greengrocer, the greengrocer begins offering same-day local recipe boxes, locally grown heritage produce, and free home delivery for elderly residents. How is it responding to competition?","options":{"A":"By attempting to outspend national supermarkets on television advertising","B":"By differentiating through specialized local product quality and personalized community service","C":"By switching to undifferentiated mass-market canned goods","D":"By reducing store opening hours and raising prices on basic apples"},"correctOption":"B","correctAnswer":"By differentiating through specialized local product quality and personalized community service","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because small independent retailers compete effectively against supermarket scale by offering niche freshness and tailored personal care.","distractor_reasons":{"A":"Incorrect because a single greengrocer lacks the budget for national TV campaigns.","B":"Option B is correct because small independent retailers compete effectively against supermarket scale by offering niche freshness and tailored personal care.","C":"Incorrect because selling standard canned goods puts the shop in direct price competition with supermarkets.","D":"Incorrect because cutting hours and raising prices on staples drives buyers away."}}},{"id":"P1_U3_MCQ_261","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_261","question":"A shoemaker crafts custom orthopaedic running shoes solely for athletes recovering from Achilles tendon injuries. Which market strategy is this business pursuing?","options":{"A":"Mass marketing","B":"Undifferentiated commodity marketing","C":"Niche marketing","D":"Cost-leadership supermarket marketing"},"correctOption":"C","correctAnswer":"Niche marketing","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because niche marketing targets a small, specialized segment with very specific functional needs.","distractor_reasons":{"A":"Incorrect because mass marketing produces standardized shoes for the general public.","B":"Incorrect because undifferentiated marketing ignores specialized medical needs.","C":"Option C is correct because niche marketing targets a small, specialized segment with very specific functional needs.","D":"Incorrect because custom orthopaedic shoes are specialist items rather than mass supermarket goods."}}},{"id":"P1_U3_MCQ_262","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_262","question":"How does a 'niche marketing' strategy help a specialist manufacturer of saltwater fly-fishing rods keep promotional costs low?","options":{"A":"Fly-fishing rods never require any product testing or quality control","B":"Governments pay 100% of advertising bills for specialist sports brands","C":"Mass-market supermarkets distribute fly-fishing rods free of charge","D":"The firm can advertise directly in dedicated fishing magazines and clubs where almost every reader is a potential buyer, avoiding wasted mass-media spend"},"correctOption":"D","correctAnswer":"The firm can advertise directly in dedicated fishing magazines and clubs where almost every reader is a potential buyer, avoiding wasted mass-media spend","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because well-defined niche audiences congregate in specialist media, maximizing promotional efficiency.","distractor_reasons":{"A":"Incorrect because technical gear requires rigorous testing.","B":"Incorrect because private firms fund their own marketing.","C":"Incorrect because specialist gear is sold via specialist tackle shops and direct online stores.","D":"Option D is correct because well-defined niche audiences congregate in specialist media, maximizing promotional efficiency."}}},{"id":"P1_U3_MCQ_263","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_263","question":"A small company produces exclusively custom leather covers for one specific model of e-reader. When the e-reader manufacturer discontinues that device, the cover company's sales collapse overnight. What key risk of 'niche marketing' does this demonstrate?","options":{"A":"Lack of product diversification leaves a niche business highly vulnerable if demand in its narrow segment disappears","B":"Unit production costs are always lower in niche markets than in mass markets","C":"Niche businesses spend too much on global television sponsorships","D":"Niche markets always have too many millions of customers to manage"},"correctOption":"A","correctAnswer":"Lack of product diversification leaves a niche business highly vulnerable if demand in its narrow segment disappears","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because relying on a single small segment exposes a firm to severe revenue shock if tastes or technology change.","distractor_reasons":{"A":"Option A is correct because relying on a single small segment exposes a firm to severe revenue shock if tastes or technology change.","B":"Incorrect because unit costs are generally higher in small-batch niche production.","C":"Incorrect because niche firms rarely use global TV sponsorships.","D":"Incorrect because small total customer numbers define niche markets."}}},{"id":"P1_U3_MCQ_264","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_264","question":"A paper mill produces standard white A4 printer paper sold in identical 500-sheet reams to offices, schools, and households nationwide. Which approach is the mill using?","options":{"A":"Bespoke luxury marketing","B":"Mass marketing","C":"Micro-niche targeting","D":"Psychographic lifestyle segmentation"},"correctOption":"B","correctAnswer":"Mass marketing","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because standard A4 copy paper is a uniform product aimed at the widest possible market with standardized production.","distractor_reasons":{"A":"Incorrect because bespoke marketing customizes products for individual buyers.","B":"Option B is correct because standard A4 copy paper is a uniform product aimed at the widest possible market with standardized production.","C":"Incorrect because standard office paper serves universal mainstream demand.","D":"Incorrect because A4 paper is bought across all lifestyles without personal value tailoring."}}},{"id":"P1_U3_MCQ_265","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_265","question":"Why can a large 'mass-market' biscuit manufacturer afford to spend $10 million on a nationwide television campaign while keeping retail packet prices at $1.50?","options":{"A":"Television networks air commercials free of charge for food companies","B":"Biscuit factories pay zero wages or ingredient expenses","C":"Selling tens of millions of packets spreads fixed advertising and factory overheads across huge unit volumes","D":"Mass-market biscuits are exempt from retail sales taxes"},"correctOption":"C","correctAnswer":"Selling tens of millions of packets spreads fixed advertising and factory overheads across huge unit volumes","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because marketing and technical economies of scale reduce the advertising and production cost per unit sold.","distractor_reasons":{"A":"Incorrect because TV networks charge high commercial rates.","B":"Incorrect because factories incur major raw-material and labour costs.","C":"Option C is correct because marketing and technical economies of scale reduce the advertising and production cost per unit sold.","D":"Incorrect because standard taxes apply equally."}}},{"id":"P1_U3_MCQ_266","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_266","question":"In a saturated mass market for bottled still water, four major brands offer nearly identical products, leading to frequent supermarket price discounts and squeezed profit margins. Which disadvantage of 'mass marketing' is occurring?","options":{"A":"Inability to use automated bottling machinery","B":"Total customer demand is too small to supply supermarkets","C":"High customer loyalty prevents shoppers from ever switching brands","D":"Low product differentiation intensifies price competition and erodes unit profit margins"},"correctOption":"D","correctAnswer":"Low product differentiation intensifies price competition and erodes unit profit margins","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because when mass-market goods appear standardized, buyers easily switch on price, forcing firms into margin-eroding competition.","distractor_reasons":{"A":"Incorrect because high-volume bottling uses rapid automated machinery.","B":"Incorrect because bottled water has massive mainstream demand.","C":"Incorrect because undifferentiated commodities suffer high brand switching.","D":"Option D is correct because when mass-market goods appear standardized, buyers easily switch on price, forcing firms into margin-eroding competition."}}},{"id":"P1_U3_MCQ_267","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_267","question":"A global trainer brand manufactures standard running shoes in bulk, but lets online buyers pick custom sole colours, lace styles, and embroidered initials for an extra $25. How does this strategy combine mass and niche benefits?","options":{"A":"It captures core mass-production economies of scale while satisfying individual consumer desire for personalized differentiation","B":"It eliminates all online delivery and manufacturing costs","C":"It prevents customers from buying standard shoes in retail stores","D":"It forces every customer to accept the exact same shoe colour"},"correctOption":"A","correctAnswer":"It captures core mass-production economies of scale while satisfying individual consumer desire for personalized differentiation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because mass customization uses standardized base components to keep unit costs reasonable while charging a premium for tailored finishing.","distractor_reasons":{"A":"Option A is correct because mass customization uses standardized base components to keep unit costs reasonable while charging a premium for tailored finishing.","B":"Incorrect because custom orders still incur production and shipping costs.","C":"Incorrect because retail stores continue selling standard models alongside online customization.","D":"Incorrect because buyers actively select their own colour combinations."}}},{"id":"P1_U3_MCQ_268","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_268","question":"What is the fundamental purpose of 'market segmentation' for a medium-sized consumer-electronics company?","options":{"A":"To charge every customer the exact same price regardless of product features","B":"To divide a broad, diverse market into distinct buyer groups with shared needs so tailored products and promotions can be designed for each","C":"To reduce the number of customers buying from the company","D":"To avoid conducting any market research before designing products"},"correctOption":"B","correctAnswer":"To divide a broad, diverse market into distinct buyer groups with shared needs so tailored products and promotions can be designed for each","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because consumers differ in tastes, budgets, and uses; segmentation aligns the 4Ps closely with each target group.","distractor_reasons":{"A":"Incorrect because segmentation supports tiered pricing across different product versions.","B":"Option B is correct because consumers differ in tastes, budgets, and uses; segmentation aligns the 4Ps closely with each target group.","C":"Incorrect because segmentation aims to grow sales by appealing more accurately to chosen groups.","D":"Incorrect because segmentation depends on thorough research data."}}},{"id":"P1_U3_MCQ_269","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_269","question":"A real-estate developer builds trendy studio apartments near nightlife districts for single young professionals, four-bedroom suburban houses near schools for families with children, and single-level bungalows for retirees. Which segmentation variable is applied?","options":{"A":"Gender","B":"Climatic zone","C":"Demographic segmentation (age and family life-cycle stage)","D":"Undifferentiated mass marketing"},"correctOption":"C","correctAnswer":"Demographic segmentation (age and family life-cycle stage)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because household composition and life stage (single youth, parents with children, retirees) shape housing requirements.","distractor_reasons":{"A":"Incorrect because housing designs reflect household stage rather than male/female differences.","B":"Incorrect because all three housing types can exist within the same city climate.","C":"Option C is correct because household composition and life stage (single youth, parents with children, retirees) shape housing requirements.","D":"Incorrect because three distinct property types are built for three distinct groups."}}},{"id":"P1_U3_MCQ_270","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_270","question":"A textbook publisher produces illustrated phonics workbooks for primary-school pupils, exam revision guides for secondary students, and peer-reviewed journals for university researchers. How is the publisher segmenting its market?","options":{"A":"By geographic postcode","B":"By residential climate","C":"By customer gender","D":"By demographic variables (age and educational stage)"},"correctOption":"D","correctAnswer":"By demographic variables (age and educational stage)","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because age and academic/educational level define the distinct learning needs of each reader group.","distractor_reasons":{"A":"Incorrect because students across all postcodes use the same curriculum books.","B":"Incorrect because weather climate does not determine academic reading level.","C":"Incorrect because educational texts serve all genders equally.","D":"Option D is correct because age and academic/educational level define the distinct learning needs of each reader group."}}},{"id":"P1_U3_MCQ_271","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_271","question":"A garden-equipment manufacturer sells compact cordless balcony-plant trimmers in high-rise cities like Singapore and Tokyo, while marketing ride-on lawn tractors in suburban North America. Which segmentation approach is guiding product design?","options":{"A":"Age-only segmentation","B":"Gender segmentation","C":"Geographic segmentation (region and housing environment)","D":"Mass undifferentiated standardization"},"correctOption":"C","correctAnswer":"Geographic segmentation (region and housing environment)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because regional geography and local living spaces dictate whether buyers have small balconies or large lawns.","distractor_reasons":{"A":"Incorrect because adults of any age in Singapore vs suburban America face different yard sizes.","B":"Incorrect because garden size is determined by location rather than buyer gender.","C":"Option C is correct because regional geography and local living spaces dictate whether buyers have small balconies or large lawns.","D":"Incorrect because the firm sells two contrasting products adapted to local geography."}}},{"id":"P1_U3_MCQ_272","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_272","question":"A hotel group operates 'SleepEasy' budget motels at $55 per night alongside 'Grandeur Palace' five-star resorts at $750 per night. Which segmentation dimension separates these two brands?","options":{"A":"Gender","B":"Income and socio-economic group","C":"Age bracket","D":"Climatic zone"},"correctOption":"B","correctAnswer":"Income and socio-economic group","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because offering budget and luxury tiers allows the company to capture travellers across different disposable income levels.","distractor_reasons":{"A":"Incorrect because both hotel brands welcome all genders.","B":"Option B is correct because offering budget and luxury tiers allows the company to capture travellers across different disposable income levels.","C":"Incorrect because budget and luxury travellers span all adult ages.","D":"Incorrect because both hotel tiers can operate in the same tourist destination."}}},{"id":"P1_U3_MCQ_273","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_273","question":"A carmaker launches a zero-emission compact EV promoted around carbon-footprint reduction for environmentally committed buyers, while marketing a twin-turbo V8 coupe to motorsport enthusiasts. Which segmentation basis is being used?","options":{"A":"Geographic postcode","B":"Marital status","C":"Lifestyle, attitudes, and personal values (psychographic segmentation)","D":"Family size"},"correctOption":"C","correctAnswer":"Lifestyle, attitudes, and personal values (psychographic segmentation)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because personal values (environmental activism vs motorsport thrill) distinguish buyer motivations beyond simple age or income.","distractor_reasons":{"A":"Incorrect because both buyer types can live in the same city.","B":"Incorrect because marital status does not determine EV vs V8 preference.","C":"Option C is correct because personal values (environmental activism vs motorsport thrill) distinguish buyer motivations beyond simple age or income.","D":"Incorrect because both vehicles are compact/two-door models rather than large family vans."}}},{"id":"P1_U3_MCQ_274","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_274","question":"While analyzing consumer demographics, a cosmetics firm notices that men aged 25–40 increasingly buy skincare moisturizers, yet almost all rival creams are packaged in floral pink jars marketed to women. How does segmentation benefit the firm here?","options":{"A":"It proves that men never buy personal-care products","B":"It allows the firm to stop advertising altogether","C":"It lowers factory ingredient costs to zero","D":"It reveals an unserved gap in the market, allowing the firm to launch a dedicated men's skincare range ahead of competitors"},"correctOption":"D","correctAnswer":"It reveals an unserved gap in the market, allowing the firm to launch a dedicated men's skincare range ahead of competitors","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because systematic segmentation uncovers neglected consumer groups where competition is still weak.","distractor_reasons":{"A":"Incorrect because the data explicitly shows rising male demand.","B":"Incorrect because entering a new segment requires targeted promotion.","C":"Incorrect because launching a new line involves R&D and packaging costs.","D":"Option D is correct because systematic segmentation uncovers neglected consumer groups where competition is still weak."}}},{"id":"P1_U3_MCQ_275","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_275","question":"A tea company divides its customers into 18 separate segments, producing distinct blends, boxes, and adverts for each tiny group, causing warehouse storage and packaging costs to soar. What lesson does this illustrate?","options":{"A":"Each market segment must be large and profitable enough to justify the extra production, inventory, and promotional costs of serving it separately","B":"Market segmentation is always less profitable than selling one unbranded product","C":"Businesses should never segment consumers by age or income","D":"Producing 18 different box designs reduces printing and warehousing costs"},"correctOption":"A","correctAnswer":"Each market segment must be large and profitable enough to justify the extra production, inventory, and promotional costs of serving it separately","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because effective segments must be substantial and accessible enough that incremental revenue exceeds added customization costs.","distractor_reasons":{"A":"Option A is correct because effective segments must be substantial and accessible enough that incremental revenue exceeds added customization costs.","B":"Incorrect because well-chosen segmentation increases profitability when segments are viable.","C":"Incorrect because age and income are valuable segmentation tools when not fragmented excessively.","D":"Incorrect because multiple variants increase setup, printing, and inventory holding costs."}}},{"id":"P1_U3_MCQ_276","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_276","question":"A software startup builds a complex project-management app packed with 90 technical buttons that its programmers thought were clever, without asking office managers what they needed. Users find it confusing and cancel subscriptions. What caused this failure?","options":{"A":"Excessive reliance on customer focus groups","B":"A product-oriented approach that ignored actual user needs and usability","C":"Over-spending on primary test marketing","D":"Pricing the software too low via penetration pricing"},"correctOption":"B","correctAnswer":"A product-oriented approach that ignored actual user needs and usability","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because product-oriented businesses prioritize internal technical preferences over verified customer problems.","distractor_reasons":{"A":"Incorrect because no customer focus groups were consulted.","B":"Option B is correct because product-oriented businesses prioritize internal technical preferences over verified customer problems.","C":"Incorrect because no user trials were run prior to launch.","D":"Incorrect because product usability—not low price—caused cancellations."}}},{"id":"P1_U3_MCQ_277","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_277","question":"Before designing a new mobile banking app for teenagers, a bank interviews 200 teens and their parents to discover which spending-limit controls and savings goals they want most. Which business orientation is demonstrated?","options":{"A":"Product orientation","B":"Production-led orientation","C":"Market orientation","D":"Asset-stripping orientation"},"correctOption":"C","correctAnswer":"Market orientation","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a market-oriented organization researches customer desires first and shapes its product around those findings.","distractor_reasons":{"A":"Incorrect because product orientation builds features first without user research.","B":"Incorrect because production orientation focuses purely on high-volume low-cost output.","C":"Option C is correct because a market-oriented organization researches customer desires first and shapes its product around those findings.","D":"Incorrect because asset-stripping refers to selling off parts of an acquired company."}}},{"id":"P1_U3_MCQ_278","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_278","question":"How does accurate 'market research' assist a food manufacturer when deciding how much factory capacity and raw ingredients to order for a new cereal launch?","options":{"A":"It eliminates the need to pay suppliers for oats and packaging","B":"It legally guarantees that supermarkets will sell 100% of stock delivered","C":"It replaces the need for quality assurance inspectors on the production line","D":"It provides realistic sales-volume forecasts, preventing costly overproduction of unsold stock or underproduction shortages"},"correctOption":"D","correctAnswer":"It provides realistic sales-volume forecasts, preventing costly overproduction of unsold stock or underproduction shortages","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because estimating likely demand aligns production scheduling and inventory purchasing with expected orders.","distractor_reasons":{"A":"Incorrect because raw materials still must be purchased.","B":"Incorrect because market research estimates demand rather than guaranteeing legal sales.","C":"Incorrect because factory quality control remains necessary.","D":"Option D is correct because estimating likely demand aligns production scheduling and inventory purchasing with expected orders."}}},{"id":"P1_U3_MCQ_279","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_279","question":"An entrepreneur planning to open an indoor climbing gym stands outside local sports centres interviewing climbers about membership fees and wall difficulty preferences. Which type of research is being conducted?","options":{"A":"External government census desk research","B":"Internal secondary accounting research","C":"Primary (field) research","D":"Competitor annual-report desk analysis"},"correctOption":"C","correctAnswer":"Primary (field) research","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because collecting new responses first-hand directly from target customers for a specific business decision is primary research.","distractor_reasons":{"A":"Incorrect because no government census tables are being read.","B":"Incorrect because a startup entrepreneur has no internal past sales records.","C":"Option C is correct because collecting new responses first-hand directly from target customers for a specific business decision is primary research.","D":"Incorrect because live interviews generate fresh primary data rather than reading published reports."}}},{"id":"P1_U3_MCQ_280","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_280","question":"Why does a pharmaceutical or consumer-tech firm value 'primary market research' over publicly published industry reports when testing a confidential new product concept?","options":{"A":"Primary research is always faster and cheaper than downloading a free report","B":"The findings are proprietary and confidential to the firm, giving a competitive insight advantage that rivals cannot access","C":"Primary research requires zero effort to design questions or recruit participants","D":"Primary research automatically eliminates all sampling errors"},"correctOption":"B","correctAnswer":"The findings are proprietary and confidential to the firm, giving a competitive insight advantage that rivals cannot access","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because original data collected privately belongs exclusively to the commissioning business.","distractor_reasons":{"A":"Incorrect because primary research is slower and costlier than reading existing reports.","B":"Option B is correct because original data collected privately belongs exclusively to the commissioning business.","C":"Incorrect because questionnaire design and recruitment require substantial effort.","D":"Incorrect because primary surveys can still suffer sampling bias if poorly executed."}}},{"id":"P1_U3_MCQ_281","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_281","question":"A small independent bookshop wants to understand national reading trends across the entire country, but decides against commissioning a nationwide face-to-face primary survey. Why is primary research unsuitable here?","options":{"A":"National reading statistics are illegal to collect via surveys","B":"Primary research never produces numerical percentages","C":"Hiring interviewers across the whole country would be far too expensive and time-consuming when national book-trade secondary reports already exist","D":"Bookshop customers refuse to answer questions about genres they read"},"correctOption":"C","correctAnswer":"Hiring interviewers across the whole country would be far too expensive and time-consuming when national book-trade secondary reports already exist","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because broad macro-level industry trends are already published cheaply in trade association and government secondary sources.","distractor_reasons":{"A":"Incorrect because reading surveys are completely lawful.","B":"Incorrect because structured primary surveys readily generate quantitative percentages.","C":"Option C is correct because broad macro-level industry trends are already published cheaply in trade association and government secondary sources.","D":"Incorrect because the barrier is cost and scale rather than reader refusal."}}},{"id":"P1_U3_MCQ_282","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_282","question":"A questionnaire asks: 'Do you think our new laptop is lightweight and reasonably priced? Yes / No.' Why is this a poorly designed survey question?","options":{"A":"It uses secondary census data instead of primary customer opinions","B":"It is an open-ended essay question that cannot be coded","C":"It uses overly complex computer engineering jargon","D":"It is a double-barrelled question combining two separate issues (weight and price), making a single Yes/No answer ambiguous"},"correctOption":"D","correctAnswer":"It is a double-barrelled question combining two separate issues (weight and price), making a single Yes/No answer ambiguous","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a respondent might think the laptop is lightweight (Yes) but overpriced (No); each attribute must be asked separately.","distractor_reasons":{"A":"Incorrect because this is a primary questionnaire item.","B":"Incorrect because Yes/No is a closed format.","C":"Incorrect because 'lightweight' and 'reasonably priced' are everyday words.","D":"Option D is correct because a respondent might think the laptop is lightweight (Yes) but overpriced (No); each attribute must be asked separately."}}},{"id":"P1_U3_MCQ_283","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_283","question":"When designing a customer feedback survey for 2,000 hotel guests, why are 'closed questions' (such as 1-to-5 satisfaction scales) preferred for the majority of the questionnaire?","options":{"A":"Closed questions allow guests to write two-page essays about every detail of their stay","B":"Responses can be quickly counted, compared statistically, and turned into graphs without subjective interpretation","C":"Closed questions guarantee a 100% response rate from all hotel guests","D":"Closed questions eliminate the need to select a representative sample"},"correctOption":"B","correctAnswer":"Responses can be quickly counted, compared statistically, and turned into graphs without subjective interpretation","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because standardized numerical choices make large-scale quantitative tabulation fast and objective.","distractor_reasons":{"A":"Incorrect because long free-text responses describe open-ended questions.","B":"Option B is correct because standardized numerical choices make large-scale quantitative tabulation fast and objective.","C":"Incorrect because non-response still occurs in any survey.","D":"Incorrect because representative sampling remains essential."}}},{"id":"P1_U3_MCQ_284","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_284","question":"Why do 'postal questionnaires' often suffer from lower data accuracy than 'face-to-face interviews'?","options":{"A":"Postal questionnaires are much more expensive per contact than hiring personal interviewers","B":"Very low response rates mean only people with unusually strong opinions reply (non-response bias), and nobody is present to clarify confusing questions","C":"Postal questionnaires force interviewers to read answers aloud to respondents","D":"Postal questionnaires can only be sent to businesses rather than households"},"correctOption":"B","correctAnswer":"Very low response rates mean only people with unusually strong opinions reply (non-response bias), and nobody is present to clarify confusing questions","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because most mailed questionnaires are discarded, skewing the small returning sample toward unrepresentative extremes.","distractor_reasons":{"A":"Incorrect because postal mail is cheaper per contact than face-to-face interviewers.","B":"Option B is correct because most mailed questionnaires are discarded, skewing the small returning sample toward unrepresentative extremes.","C":"Incorrect because postal forms are self-completed by respondents.","D":"Incorrect because households frequently receive mailed surveys."}}},{"id":"P1_U3_MCQ_285","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_285","question":"Before finalizing the brand name, bottle shape, and TV advert storyboard for a new iced tea, a beverage firm invites target young-adult drinkers to discuss mock-ups in a moderated session. Which method is being used?","options":{"A":"Focus group","B":"Automated barcode observation","C":"National population census","D":"Internal accounting audit"},"correctOption":"A","correctAnswer":"Focus group","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because focus groups excel at pre-testing creative branding, packaging designs, and advert concepts qualitatively.","distractor_reasons":{"A":"Option A is correct because focus groups excel at pre-testing creative branding, packaging designs, and advert concepts qualitatively.","B":"Incorrect because barcode scanning tracks actual store sales rather than discussing mock-ups.","C":"Incorrect because a census counts the entire population.","D":"Incorrect because financial audits verify accounting records."}}},{"id":"P1_U3_MCQ_286","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_286","question":"During a focus group testing a new smoothie flavour, the moderator repeatedly praises the recipe, leading hesitant participants to say they love it even though they found it too sour. Which research flaw occurred?","options":{"A":"Secondary desk-research obsolescence","B":"Interviewer / moderator bias distorting participants' genuine reactions","C":"Excessive sample size reducing statistical clarity","D":"Random sampling frame inaccuracy"},"correctOption":"B","correctAnswer":"Interviewer / moderator bias distorting participants' genuine reactions","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because an unskilled or biased moderator can subtly cue participants toward desired answers, invalidating qualitative feedback.","distractor_reasons":{"A":"Incorrect because a focus group is primary research.","B":"Option B is correct because an unskilled or biased moderator can subtly cue participants toward desired answers, invalidating qualitative feedback.","C":"Incorrect because focus groups involve small panels of 6–12 people.","D":"Incorrect because focus groups use purposive selection rather than random sampling frames."}}},{"id":"P1_U3_MCQ_287","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_287","question":"An e-commerce website uses screen-tracking software to observe where visitors move their cursors and which checkout buttons cause users to hesitate or exit. Which research method is this?","options":{"A":"Digital observation","B":"Postal survey","C":"Telephone interview","D":"External government trade report"},"correctOption":"A","correctAnswer":"Digital observation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because recording actual user navigation and clicks captures real behaviour objectively without interrupting shoppers.","distractor_reasons":{"A":"Option A is correct because recording actual user navigation and clicks captures real behaviour objectively without interrupting shoppers.","B":"Incorrect because no mailed forms are involved.","C":"Incorrect because no phone calls are made.","D":"Incorrect because website analytics generate first-hand primary behavioural data."}}},{"id":"P1_U3_MCQ_288","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_288","question":"Why do retail researchers often pair in-store 'observation' with short exit 'questionnaires'?","options":{"A":"Observation is illegal unless paired with a written questionnaire","B":"Questionnaires are needed to calculate exact shelf heights","C":"Observation reveals what shoppers actually did in the aisle, while exit questions uncover the reasons why they made those choices","D":"Pairing them converts primary research into secondary census data"},"correctOption":"C","correctAnswer":"Observation reveals what shoppers actually did in the aisle, while exit questions uncover the reasons why they made those choices","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because observation measures objective action while brief follow-up questions explain underlying motivations.","distractor_reasons":{"A":"Incorrect because unobtrusive store observation is standard commercial practice.","B":"Incorrect because shelf dimensions are already known by store managers.","C":"Option C is correct because observation measures objective action while brief follow-up questions explain underlying motivations.","D":"Incorrect because both methods collect primary data."}}},{"id":"P1_U3_MCQ_289","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_289","question":"A frozen-pizza company launches a new spicy-jackfruit pizza in just 20 supermarkets in one region for eight weeks to evaluate repeat sales and adjust packaging before committing to national TV ads. What is the main benefit of this 'test marketing'?","options":{"A":"It guarantees that competitors will never find out the new pizza exists","B":"It avoids the huge financial loss of a full national launch if the product underperforms, allowing fixes first","C":"It costs zero money to produce and distribute the regional trial batch","D":"It eliminates the need to analyze supermarket scanner data"},"correctOption":"B","correctAnswer":"It avoids the huge financial loss of a full national launch if the product underperforms, allowing fixes first","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because trialling on a small scale tests real purchasing under authentic store conditions while limiting downside risk.","distractor_reasons":{"A":"Incorrect because exposing the product in regional stores alerts rivals—a known risk of test marketing.","B":"Option B is correct because trialling on a small scale tests real purchasing under authentic store conditions while limiting downside risk.","C":"Incorrect because regional production and retail listing incur real costs.","D":"Incorrect because analyzing trial store sales is the exact goal of test marketing."}}},{"id":"P1_U3_MCQ_290","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_290","question":"Which of the following is an 'internal source of secondary data' that a hotel chain can analyze to improve guest satisfaction?","options":{"A":"National tourism ministry arrival statistics","B":"Past room-occupancy records, repeat-booking histories, and guest complaint logs stored in the hotel's own system","C":"A commercial hospitality industry report purchased from a consultancy","D":"A new telephone survey of rival hotels' customers"},"correctOption":"B","correctAnswer":"Past room-occupancy records, repeat-booking histories, and guest complaint logs stored in the hotel's own system","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because existing operational records inside the business provide fast, low-cost insight into guest patterns.","distractor_reasons":{"A":"Incorrect because government tourism statistics are external secondary data.","B":"Option B is correct because existing operational records inside the business provide fast, low-cost insight into guest patterns.","C":"Incorrect because commercial consultancy reports are external secondary data.","D":"Incorrect because a new phone survey is primary research."}}},{"id":"P1_U3_MCQ_291","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_291","question":"A solar-panel installer consults national energy-ministry household statistics, local newspaper articles on electricity tariffs, and competitors' published brochures before entering a new city. Which research type is this?","options":{"A":"Primary focus-group research","B":"Primary quota street sampling","C":"External secondary (desk) research","D":"Internal company sales-ledger analysis"},"correctOption":"C","correctAnswer":"External secondary (desk) research","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because government statistics, press articles, and competitor brochures are pre-existing information published outside the business.","distractor_reasons":{"A":"Incorrect because no group discussions were conducted.","B":"Incorrect because no street interviews took place.","C":"Option C is correct because government statistics, press articles, and competitor brochures are pre-existing information published outside the business.","D":"Incorrect because the sources came from external organizations rather than internal files."}}},{"id":"P1_U3_MCQ_292","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_292","question":"Why do multinational corporations regularly purchase 'external secondary reports' from specialist market-research agencies?","options":{"A":"Because primary research is illegal for multinational corporations","B":"Because secondary reports are always free of charge","C":"Because secondary reports test confidential prototypes before anyone else sees them","D":"Because specialist agencies compile nationwide market-size and competitor-share data that would be too vast for one firm to gather alone"},"correctOption":"D","correctAnswer":"Because specialist agencies compile nationwide market-size and competitor-share data that would be too vast for one firm to gather alone","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because syndicated industry reports aggregate macro-market intelligence rapidly, though at a purchase fee.","distractor_reasons":{"A":"Incorrect because multinationals use both primary and secondary research.","B":"Incorrect because commercial research agency reports are often expensive to buy.","C":"Incorrect because testing unreleased prototypes requires private primary research.","D":"Option D is correct because syndicated industry reports aggregate macro-market intelligence rapidly, though at a purchase fee."}}},{"id":"P1_U3_MCQ_293","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_293","question":"A gourmet dog-bakery reads a free government report on 'Total National Pet Care Spending' (which combines veterinary bills, dog food, birdseed, and aquarium fish). Why is this secondary data insufficient on its own?","options":{"A":"Government statistics are always mathematically fabricated","B":"The broad category combines unrelated pet expenses and fails to show specific demand or price willingness for gourmet dog treats","C":"Secondary data can never be viewed by small businesses","D":"Primary research is always cheaper than reading a free government report"},"correctOption":"B","correctAnswer":"The broad category combines unrelated pet expenses and fails to show specific demand or price willingness for gourmet dog treats","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because secondary data was compiled for wider policy purposes and lacks the granular product-specific detail needed for niche decisions.","distractor_reasons":{"A":"Incorrect because government stats are reliable at macro level, just too broad here.","B":"Option B is correct because secondary data was compiled for wider policy purposes and lacks the granular product-specific detail needed for niche decisions.","C":"Incorrect because public reports are accessible to all businesses.","D":"Incorrect because primary research costs more than reading free public reports."}}},{"id":"P1_U3_MCQ_294","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_294","question":"A survey finds that '64% of respondents buy takeaway coffee at least three times a week' (quantitative data), while follow-up interviews reveal 'commuters feel rushed in the morning and view barista coffee as an affordable daily treat' (qualitative data). How do both data types help a café chain?","options":{"A":"Qualitative data always proves that 100% of consumers will buy the product","B":"Quantitative data is collected only from focus groups, while qualitative data comes only from cash registers","C":"Quantitative data eliminates the need for qualitative insights in branding","D":"Quantitative data measures the numerical scale of demand, while qualitative data explains the emotional motivations needed to craft persuasive adverts"},"correctOption":"D","correctAnswer":"Quantitative data measures the numerical scale of demand, while qualitative data explains the emotional motivations needed to craft persuasive adverts","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because numerical demand sizing and psychological insight complement each other in marketing planning.","distractor_reasons":{"A":"Incorrect because qualitative data explores feelings rather than guaranteeing universal sales.","B":"Incorrect because this reverses their typical sources.","C":"Incorrect because numbers alone do not explain why buyers behave as they do.","D":"Option D is correct because numerical demand sizing and psychological insight complement each other in marketing planning."}}},{"id":"P1_U3_MCQ_295","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_295","question":"An electricity utility wants an unbiased survey of its 250,000 account holders. It numbers every account, draws 500 numbers with a random number generator and contacts only those. What method is this?","options":{"A":"Random sampling","B":"Quota sampling","C":"Testing a product prototype","D":"Analysing competitors' prices"},"correctOption":"A","correctAnswer":"Random sampling","questionType":"MCQ","explanation":{"correct_reason":"Selecting accounts by random number so that each has an equal chance of inclusion is random sampling, which helps avoid bias.","distractor_reasons":{"B":"Quota sampling would set numbers for categories of account holder instead of drawing names at random.","C":"Prototype testing concerns developing a physical product, not choosing survey respondents.","D":"Competitors' prices are secondary market data, not a sampling method for selecting customers.","A":"Selecting accounts by random number so that each has an equal chance of inclusion is random sampling, which helps avoid bias."}}},{"id":"P1_U3_MCQ_296","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_296","question":"A city's commuter population is 45% aged under 35 and 55% aged 35 or older. If a transport planner uses 'quota sampling' to interview 200 commuters, how many respondents are needed in each age group?","options":{"A":"100 under 35 and 100 aged 35+","B":"45 under 35 and 55 aged 35+","C":"90 under 35 and 110 aged 35+","D":"110 under 35 and 90 aged 35+"},"correctOption":"C","correctAnswer":"90 under 35 and 110 aged 35+","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because 45% of 200 = 90 respondents under 35, and 55% of 200 = 110 respondents aged 35+.","distractor_reasons":{"A":"Incorrect because 100/100 splits 50/50 instead of matching the 45/55 population ratio.","B":"Incorrect because 45 + 55 equals only 100 respondents rather than 200.","C":"Option C is correct because 45% of 200 = 90 respondents under 35, and 55% of 200 = 110 respondents aged 35+.","D":"Incorrect because 110/90 reverses the two age percentages."}}},{"id":"P1_U3_MCQ_297","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_297","question":"Why do commercial market-research agencies frequently use 'quota sampling' rather than 'random sampling' for high-street consumer surveys?","options":{"A":"Quota sampling requires obtaining a complete register of every citizen's home address first","B":"Quota sampling guarantees zero interviewer bias in every single interview","C":"Random sampling cannot be used with questionnaires","D":"Quota sampling is faster and cheaper when no complete population list exists, while still reflecting key demographic proportions"},"correctOption":"D","correctAnswer":"Quota sampling is faster and cheaper when no complete population list exists, while still reflecting key demographic proportions","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because quota sampling avoids the time and cost of tracking down scattered individuals from a master list while preserving demographic balance.","distractor_reasons":{"A":"Incorrect because needing a full register is a requirement of random sampling.","B":"Incorrect because interviewer judgment in picking respondents can still introduce subtle bias in quota sampling.","C":"Incorrect because random sampling is widely used with questionnaires.","D":"Option D is correct because quota sampling avoids the time and cost of tracking down scattered individuals from a master list while preserving demographic balance."}}},{"id":"P1_U3_MCQ_298","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_298","question":"A snack company surveys 40 people at $5 per interview ($200 total) and gets rough results, whereas surveying 1,200 people across the country costs $6,000. What trade-off must the marketing manager balance when choosing 'sample size'?","options":{"A":"Larger samples produce more statistically reliable results with lower sampling error, but increase fieldwork costs and delay decision-making","B":"Smaller samples are always more accurate than larger samples","C":"Larger samples eliminate the need to write unbiased survey questions","D":"Increasing sample size reduces total survey expenditure"},"correctOption":"A","correctAnswer":"Larger samples produce more statistically reliable results with lower sampling error, but increase fieldwork costs and delay decision-making","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because managers must weigh the value of higher statistical confidence against budget limits and launch deadlines.","distractor_reasons":{"A":"Option A is correct because managers must weigh the value of higher statistical confidence against budget limits and launch deadlines.","B":"Incorrect because small samples are easily distorted by outlier views.","C":"Incorrect because biased questions ruin accuracy regardless of sample size.","D":"Incorrect because larger samples increase total collection and processing costs."}}},{"id":"P1_U3_MCQ_299","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_299","question":"An airline emails a satisfaction survey to 5,000 passengers, but only 120 passengers reply—mostly travellers whose luggage was delayed. Why would relying on these 120 replies distort management decisions?","options":{"A":"Secondary data always contradicts email surveys","B":"Non-response bias: the tiny 2.4% response rate over-represents dissatisfied passengers rather than the typical flyer experience","C":"120 respondents is larger than the airline's entire annual passenger count","D":"Email surveys are illegal in the aviation industry"},"correctOption":"B","correctAnswer":"Non-response bias: the tiny 2.4% response rate over-represents dissatisfied passengers rather than the typical flyer experience","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because when very few invited people respond, self-selection skews findings toward extreme experiences.","distractor_reasons":{"A":"Incorrect because the distortion comes from low response rate rather than secondary data.","B":"Option B is correct because when very few invited people respond, self-selection skews findings toward extreme experiences.","C":"Incorrect because 120 is a tiny fraction of 5,000 invited passengers.","D":"Incorrect because post-flight email surveys are standard practice."}}},{"id":"P1_U3_MCQ_300","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_300","question":"A marketing manager wants to show how total industry sales of $100 million are divided among four competing smartphone brands (40%, 30%, 20%, and 10%). Which visual presentation format is most effective?","options":{"A":"An unsorted list of 500 raw customer interview transcripts","B":"A continuous scatter diagram of factory temperatures","C":"A pie chart clearly displaying each brand's percentage slice of the total market","D":"A paragraph of text omitting all numerical percentages"},"correctOption":"C","correctAnswer":"A pie chart clearly displaying each brand's percentage slice of the total market","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because pie charts visually highlight each component's proportional share of a 100% total.","distractor_reasons":{"A":"Incorrect because raw transcripts obscure market share proportions.","B":"Incorrect because factory temperatures are unrelated to market share.","C":"Option C is correct because pie charts visually highlight each component's proportional share of a 100% total.","D":"Incorrect because omitting figures reduces clarity for decision-makers."}}},{"id":"P1_U3_MCQ_301","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_301","question":"After generating and screening ideas for a foldable electric bicycle, an engineering team builds a working model and tests its frame strength and battery range before regional trials. Which stage of 'new product development' is this?","options":{"A":"Maturity extension","B":"Decline harvesting","C":"Mass commercial saturation","D":"Prototype development and testing"},"correctOption":"D","correctAnswer":"Prototype development and testing","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because building and testing a working prototype verifies technical safety and performance prior to test marketing or mass production.","distractor_reasons":{"A":"Incorrect because extension strategies apply to mature existing products.","B":"Incorrect because harvesting manages aging products in decline.","C":"Incorrect because saturation occurs after full market rollout.","D":"Option D is correct because building and testing a working prototype verifies technical safety and performance prior to test marketing or mass production."}}},{"id":"P1_U3_MCQ_302","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_302","question":"Why do leading consumer-electronics companies invest billions in 'new product development (NPD)' despite the high risk that many prototypes never reach store shelves?","options":{"A":"New products never require any advertising or distribution support","B":"Governments fine technology firms if they sell the same product for more than six months","C":"Prototype development reduces factory fixed costs to zero","D":"Continuous innovation creates new revenue streams, replaces aging declining products, and maintains a competitive edge over rivals"},"correctOption":"D","correctAnswer":"Continuous innovation creates new revenue streams, replaces aging declining products, and maintains a competitive edge over rivals","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because existing products eventually mature and decline, so a pipeline of new products sustains long-term business growth.","distractor_reasons":{"A":"Incorrect because new launches require heavy informative promotion.","B":"Incorrect because market competition—not government fines—drives continuous innovation.","C":"Incorrect because R&D adds substantial fixed development outlays.","D":"Option D is correct because existing products eventually mature and decline, so a pipeline of new products sustains long-term business growth."}}},{"id":"P1_U3_MCQ_303","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_303","question":"Chemically, bottled mineral waters from different springs taste very similar, yet one brand charges twice as much as supermarket own-label water and outsells rivals. What enables this pricing power?","options":{"A":"Supermarkets are legally forbidden from selling cheap bottled water","B":"A strong, aspirational brand image built through distinctive packaging and lifestyle promotion that differentiates the product in consumers' minds","C":"The brand pays zero bottling or transport costs","D":"Consumers cannot see price tags in grocery stores"},"correctOption":"B","correctAnswer":"A strong, aspirational brand image built through distinctive packaging and lifestyle promotion that differentiates the product in consumers' minds","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because branding creates perceived uniqueness and emotional value even when physical product differences are subtle.","distractor_reasons":{"A":"Incorrect because own-label water is widely sold alongside premium brands.","B":"Option B is correct because branding creates perceived uniqueness and emotional value even when physical product differences are subtle.","C":"Incorrect because bottling and shipping carry real costs.","D":"Incorrect because shoppers see prices clearly and willingly pay more for the trusted brand."}}},{"id":"P1_U3_MCQ_304","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_304","question":"A well-known kitchenware brand known for durable cast-iron pans successfully launches a new line of stainless-steel knives under the same brand name. Why does an established 'brand image' make launching new products easier?","options":{"A":"Established brands are exempt from product safety and labelling regulations","B":"Existing customer trust transfers to the new product line, reducing perceived buyer risk and winning faster retail shelf space","C":"Existing brands never need to pay for manufacturing materials","D":"Retailers must stock every new product from an established brand free of charge"},"correctOption":"B","correctAnswer":"Existing customer trust transfers to the new product line, reducing perceived buyer risk and winning faster retail shelf space","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because brand extension leverages existing reputation, lowering launch promotion barriers and encouraging trial.","distractor_reasons":{"A":"Incorrect because all products remain subject to consumer safety laws.","B":"Option B is correct because brand extension leverages existing reputation, lowering launch promotion barriers and encouraging trial.","C":"Incorrect because raw materials still incur full production costs.","D":"Incorrect because retailers evaluate commercial demand before allocating shelf space."}}},{"id":"P1_U3_MCQ_305","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_305","question":"A dairy company packages fresh yogurt in sealed foil-lidded tubs packed inside rigid corrugated trays for refrigerated lorry transport. Which essential role of 'packaging' is illustrated?","options":{"A":"Preventing bacterial contamination, leaks, and crushing damage during transit and retail storage","B":"Increasing unit freight weight to raise distribution charges","C":"Hiding the expiry date from supermarket shoppers","D":"Eliminating the need for refrigerated delivery vehicles"},"correctOption":"A","correctAnswer":"Preventing bacterial contamination, leaks, and crushing damage during transit and retail storage","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because physical protection and hygiene preservation are primary functional duties of food packaging.","distractor_reasons":{"A":"Option A is correct because physical protection and hygiene preservation are primary functional duties of food packaging.","B":"Incorrect because businesses aim to minimize rather than inflate freight costs.","C":"Incorrect because use-by dates must be printed clearly on packaging by law.","D":"Incorrect because fresh dairy still requires cold-chain transport."}}},{"id":"P1_U3_MCQ_306","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_306","question":"A dish-soap manufacturer introduces an upside-down squeeze bottle with a non-drip valve so cooks can dispense soap with one wet hand. How does this 'packaging' innovation add customer value?","options":{"A":"It eliminates the need for brand logos or usage instructions","B":"It reduces the chemical cleaning strength of the soap","C":"It forces supermarkets to store the bottles in locked cabinets","D":"It improves everyday functional convenience and usability, creating a practical Unique Selling Point over standard bottles"},"correctOption":"D","correctAnswer":"It improves everyday functional convenience and usability, creating a practical Unique Selling Point over standard bottles","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because user-friendly packaging design enhances product utility and differentiates a staple item on crowded shelves.","distractor_reasons":{"A":"Incorrect because branding and instructions remain on the bottle label.","B":"Incorrect because bottle design improves dispensing without weakening the soap.","C":"Incorrect because innovative packaging attracts prominent open-shelf display.","D":"Option D is correct because user-friendly packaging design enhances product utility and differentiates a staple item on crowded shelves."}}},{"id":"P1_U3_MCQ_307","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_307","question":"Why do cereal brands use bright colours, recognizable mascots, and bold typography on the front of boxes in supermarkets?","options":{"A":"To replace all television and digital advertising permanently","B":"To make the cardboard box heavier for warehouse forklifts","C":"To avoid displaying mandatory ingredient and weight information","D":"To act as a 'silent salesperson' on crowded supermarket shelves, grabbing shopper attention and reinforcing instant brand recognition"},"correctOption":"D","correctAnswer":"To act as a 'silent salesperson' on crowded supermarket shelves, grabbing shopper attention and reinforcing instant brand recognition","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because point-of-sale shelf impact is critical when shoppers scan dozens of competing brands in seconds.","distractor_reasons":{"A":"Incorrect because packaging works alongside media promotion rather than replacing it.","B":"Incorrect because graphics do not affect freight weight.","C":"Incorrect because ingredient and weight tables are displayed on side/back panels.","D":"Option D is correct because point-of-sale shelf impact is critical when shoppers scan dozens of competing brands in seconds."}}},{"id":"P1_U3_MCQ_308","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_308","question":"An automotive engineering firm spends $120 million designing and crash-testing a hydrogen-powered delivery van, generating zero sales revenue during the two-year engineering phase. Which Product Life Cycle stage is this?","options":{"A":"Saturation stage","B":"Growth stage","C":"Maturity stage","D":"Research and development (Development stage)"},"correctOption":"D","correctAnswer":"Research and development (Development stage)","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the development stage involves heavy capital outflow for design and testing before any commercial units are sold.","distractor_reasons":{"A":"Incorrect because saturation occurs when market ownership reaches maximum levels.","B":"Incorrect because growth features rapidly rising commercial sales.","C":"Incorrect because maturity represents peak sales and strong cash inflows.","D":"Option D is correct because the development stage involves heavy capital outflow for design and testing before any commercial units are sold."}}},{"id":"P1_U3_MCQ_309","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_309","question":"A new smart-garden indoor herb planter has just launched; consumer awareness is low, sales volume is modest, unit production costs are high, and heavy informative ads keep cash flow negative. Which PLC stage is it in?","options":{"A":"Growth stage","B":"Introduction stage","C":"Maturity stage","D":"Decline stage"},"correctOption":"B","correctAnswer":"Introduction stage","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because introduction combines slow initial sales, high unit costs due to low output, and substantial launch marketing expenses.","distractor_reasons":{"A":"Incorrect because growth brings rapid sales acceleration and emerging profitability.","B":"Option B is correct because introduction combines slow initial sales, high unit costs due to low output, and substantial launch marketing expenses.","C":"Incorrect because maturity features peak sales and positive cash flow.","D":"Incorrect because decline involves falling demand for an established product."}}},{"id":"P1_U3_MCQ_310","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_310","question":"As a portable espresso maker moves from 'Introduction' into the 'Growth stage' of its Product Life Cycle, what typically happens to unit production costs and competitor activity?","options":{"A":"Advertising stops completely because every household already owns two units","B":"Unit costs triple and all competitors withdraw from the market","C":"Sales volume drops to zero and the product is discontinued","D":"Unit costs fall as higher output unlocks economies of scale, while rival firms notice rising profits and launch competing models"},"correctOption":"D","correctAnswer":"Unit costs fall as higher output unlocks economies of scale, while rival firms notice rising profits and launch competing models","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because surging sales volume improves production efficiency and profitability, attracting imitators into the market.","distractor_reasons":{"A":"Incorrect because persuasive promotion intensifies during growth to build brand preference.","B":"Incorrect because higher volume lowers unit costs and attracts—rather than deters—rivals.","C":"Incorrect because falling sales and withdrawal describe the decline stage.","D":"Option D is correct because surging sales volume improves production efficiency and profitability, attracting imitators into the market."}}},{"id":"P1_U3_MCQ_311","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_311","question":"A well-established brand of washing powder has high sales but fierce competition and little growth. The firm launches a concentrated version in updated packaging. What is this an example of?","options":{"A":"Product deletion in the decline stage","B":"A brand-new product in the introduction stage","C":"An extension strategy during the maturity stage","D":"Price skimming at the point of launch"},"correctOption":"C","correctAnswer":"An extension strategy during the maturity stage","questionType":"MCQ","explanation":{"correct_reason":"Adding a new variant and refreshing packaging to revive sales of a mature brand is an extension strategy used in the maturity stage.","distractor_reasons":{"B":"The product is already well established, so it is not a completely new item entering the introduction stage.","C":"Adding a new variant and refreshing packaging to revive sales of a mature brand is an extension strategy used in the maturity stage.","D":"Price skimming is a high initial launch price for a new product, not a way of prolonging a mature brand.","A":"Deletion means withdrawing a product from the market, whereas the firm is investing to keep this brand going."}}},{"id":"P1_U3_MCQ_312","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_312","question":"Sales of a traditional standalone portable MP3 music player fall by 35% per year as consumers listen to music exclusively on smartphones. Which PLC stage has the MP3 player reached?","options":{"A":"Development","B":"Introduction","C":"Growth","D":"Decline"},"correctOption":"D","correctAnswer":"Decline","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because technological substitution has caused sustained falling sales and shrinking profitability.","distractor_reasons":{"A":"Incorrect because development occurs before launch.","B":"Incorrect because introduction involves slowly rising initial sales.","C":"Incorrect because growth features rapidly increasing sales.","D":"Option D is correct because technological substitution has caused sustained falling sales and shrinking profitability."}}},{"id":"P1_U3_MCQ_313","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_313","question":"A classic laundry-soap brand whose sales have plateaued in maturity replaces its dated cardboard carton with a sleek, modern resealable pouch and refreshed logo. Which strategy is being applied?","options":{"A":"An extension strategy through packaging redesign and brand modernization","B":"Product withdrawal and liquidation","C":"Launch price skimming","D":"Product-oriented cost cutting"},"correctOption":"A","correctAnswer":"An extension strategy through packaging redesign and brand modernization","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because refreshing packaging revives shelf appeal and reminds shoppers of the brand, extending its mature life.","distractor_reasons":{"A":"Option A is correct because refreshing packaging revives shelf appeal and reminds shoppers of the brand, extending its mature life.","B":"Incorrect because the brand is investing to stay on shelves rather than withdrawing.","C":"Incorrect because price skimming applies to new product introductions.","D":"Incorrect because upgrading packaging responds to modern shopper tastes."}}},{"id":"P1_U3_MCQ_314","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_314","question":"A popular potato-chip brand entering maturity introduces 'Spicy Truffle' and 'Sea Salt & Rosemary' flavours alongside single-serve multipacks. How does this 'extension strategy' boost sales?","options":{"A":"By eliminating all supermarket distribution channels","B":"By offering new variety and pack formats that re-engage existing buyers and attract new snack occasions","C":"By raising the price of plain chips by 200%","D":"By reducing factory production output to zero"},"correctOption":"B","correctAnswer":"By offering new variety and pack formats that re-engage existing buyers and attract new snack occasions","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because product variations and multipack sizes stimulate fresh trials and higher purchase frequency.","distractor_reasons":{"A":"Incorrect because new flavours rely on wide supermarket distribution.","B":"Option B is correct because product variations and multipack sizes stimulate fresh trials and higher purchase frequency.","C":"Incorrect because core prices remain competitive.","D":"Incorrect because new variants aim to expand total sales volume."}}},{"id":"P1_U3_MCQ_315","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_315","question":"An oat-porridge brand traditionally eaten only as a hot winter breakfast launches adverts promoting 'overnight cold summer oats' with berries. Which 'extension strategy' is this?","options":{"A":"Withdrawing the product during summer months","B":"Switching from market orientation to product orientation","C":"Promoting a new seasonal usage occasion to expand year-round demand","D":"Using loss-leader pricing below raw oat cost"},"correctOption":"C","correctAnswer":"Promoting a new seasonal usage occasion to expand year-round demand","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because educating consumers on new ways or times to consume an existing product unlocks fresh demand.","distractor_reasons":{"A":"Incorrect because the brand is boosting summer sales rather than withdrawing.","B":"Incorrect because adapting to summer refreshment preferences is market-oriented.","C":"Option C is correct because educating consumers on new ways or times to consume an existing product unlocks fresh demand.","D":"Incorrect because the campaign changes product usage rather than cutting price below cost."}}},{"id":"P1_U3_MCQ_316","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_316","question":"A backpack manufacturer incurs variable costs of $18 per backpack and allocated fixed overheads of $7 per backpack. If it applies a 60% cost-plus mark-up, what is the selling price per backpack?","options":{"A":"$25.00","B":"$35.80","C":"$15.00","D":"$40.00"},"correctOption":"D","correctAnswer":"$40.00","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Total Unit Cost = $18 + $7 = $25.00; Selling Price = $25.00 + (60% of $25.00) = $25.00 + $15.00 = $40.00.","distractor_reasons":{"A":"Incorrect because $25.00 is the total unit cost before adding the 60% profit mark-up.","B":"Incorrect because $35.80 adds 60% only to the $18 variable cost ($18 + $10.80 + $7 = $35.80) rather than full unit cost.","C":"Incorrect because $15.00 is only the profit mark-up amount, not the selling price.","D":"Option D is correct because Total Unit Cost = $18 + $7 = $25.00; Selling Price = $25.00 + (60% of $25.00) = $25.00 + $15.00 = $40.00."}}},{"id":"P1_U3_MCQ_317","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_317","question":"A bespoke metal-fabrication workshop quotes prices for custom staircases using 'cost-plus pricing'. Why is cost-plus pricing particularly suited to custom job production?","options":{"A":"Custom staircases have zero material or labour costs","B":"Every custom order has unique material and labour costs, so calculating full job cost plus an agreed percentage guarantees a profit margin on each contract","C":"Cost-plus pricing guarantees that the workshop always offers the cheapest price in the country","D":"Customers are legally forbidden from asking for quotes before ordering"},"correctOption":"B","correctAnswer":"Every custom order has unique material and labour costs, so calculating full job cost plus an agreed percentage guarantees a profit margin on each contract","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because bespoke jobs lack standard retail market prices, making transparent cost-plus estimation practical and safe.","distractor_reasons":{"A":"Incorrect because custom steel and craftsmanship carry high direct costs.","B":"Option B is correct because bespoke jobs lack standard retail market prices, making transparent cost-plus estimation practical and safe.","C":"Incorrect because if workshop costs are high, cost-plus may produce a higher price than rivals.","D":"Incorrect because written quotes are standard before job production begins."}}},{"id":"P1_U3_MCQ_318","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_318","question":"Two rival supermarket chains sell identical branded cans of soup within one cent of each other in every town. Which pricing strategy are they using?","options":{"A":"Price skimming","B":"Competitive pricing","C":"Penetration launch pricing","D":"Prestige luxury pricing"},"correctOption":"B","correctAnswer":"Competitive pricing","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because when products are identical and shoppers compare prices easily, firms set prices closely aligned with competitors.","distractor_reasons":{"A":"Incorrect because price skimming applies to innovative new launches.","B":"Option B is correct because when products are identical and shoppers compare prices easily, firms set prices closely aligned with competitors.","C":"Incorrect because penetration pricing sets a low introductory price for a new market entrant.","D":"Incorrect because canned soup is an everyday staple rather than a prestige luxury."}}},{"id":"P1_U3_MCQ_319","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_319","question":"A new sports-drink brand enters a market dominated by two global giants by pricing its bottles at $0.99—half the rivals' $1.99 price—for its first six months to persuade shoppers to switch. Which strategy is this?","options":{"A":"Price skimming","B":"Cost-plus luxury pricing","C":"Penetration pricing","D":"Dynamic surge pricing"},"correctOption":"C","correctAnswer":"Penetration pricing","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because penetration pricing sets a low initial price to overcome brand loyalty to incumbents and capture rapid market share.","distractor_reasons":{"A":"Incorrect because price skimming sets a high initial price.","B":"Incorrect because $0.99 is an aggressive low-margin entry price.","C":"Option C is correct because penetration pricing sets a low initial price to overcome brand loyalty to incumbents and capture rapid market share.","D":"Incorrect because dynamic pricing adjusts prices automatically in real time with demand."}}},{"id":"P1_U3_MCQ_320","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_320","question":"A technology firm launches the first lightweight augmented-reality smart glasses, a product no rival currently offers. Which pricing method is hardest for the firm to apply at launch?","options":{"A":"Cost-plus pricing","B":"Competitive pricing","C":"Promotional pricing","D":"Psychological pricing"},"correctOption":"B","correctAnswer":"Competitive pricing","questionType":"MCQ","explanation":{"correct_reason":"Competitive pricing means comparing your price with rivals' prices; with no comparable product on the market, this method is hard to use.","distractor_reasons":{"A":"Cost-plus pricing can still be used because the firm knows its own production costs and desired mark-up.","B":"With no rival selling a similar product, there is no benchmark price to compare against, so this method is hardest to apply.","C":"Promotional pricing can be used at launch whatever rivals do, for example by offering a temporary introductory price.","D":"Psychological pricing depends on how the price is presented, not on whether competitors exist."}}},{"id":"P1_U3_MCQ_321","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_321","question":"A garden centre offers 'Buy One Bag of Potting Soil, Get One Free' during a quiet rainy weekend in autumn to clear warehouse space. Which pricing method is being used?","options":{"A":"Penetration launch pricing","B":"Price skimming","C":"Promotional pricing","D":"Prestige psychological pricing"},"correctOption":"C","correctAnswer":"Promotional pricing","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because temporary multi-buy discounts stimulate immediate off-peak sales and clear excess inventory.","distractor_reasons":{"A":"Incorrect because penetration pricing introduces a brand-new product to the market.","B":"Incorrect because skimming sets high launch prices for innovations.","C":"Option C is correct because temporary multi-buy discounts stimulate immediate off-peak sales and clear excess inventory.","D":"Incorrect because BOGOF signals bargain clearance rather than prestige."}}},{"id":"P1_U3_MCQ_322","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_322","question":"How does 'dynamic pricing' used by online hotels and airlines differ from 'psychological pricing' used by retail stores?","options":{"A":"Dynamic pricing is illegal in e-commerce, whereas psychological pricing is mandatory","B":"Dynamic pricing keeps prices fixed for ten years, whereas psychological pricing changes every five seconds","C":"Dynamic pricing adjusts prices continuously in real time based on live demand and remaining capacity, whereas psychological pricing sets specific price numbers (like $19.99) to influence buyer perception","D":"Dynamic pricing is used only for agricultural commodities, whereas psychological pricing is used only for airline tickets"},"correctOption":"C","correctAnswer":"Dynamic pricing adjusts prices continuously in real time based on live demand and remaining capacity, whereas psychological pricing sets specific price numbers (like $19.99) to influence buyer perception","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because dynamic pricing responds algorithmically to supply-demand fluctuations, while psychological pricing targets consumer mental framing.","distractor_reasons":{"A":"Incorrect because both pricing strategies are lawful when transparent.","B":"Incorrect because this reverses the two concepts.","C":"Option C is correct because dynamic pricing responds algorithmically to supply-demand fluctuations, while psychological pricing targets consumer mental framing.","D":"Incorrect because airlines use dynamic pricing extensively while retailers use charm pricing."}}},{"id":"P1_U3_MCQ_323","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_323","question":"Starlight Cinemas wants to set its weekday ticket prices by working out the cost of each screening and then adding a fixed percentage to earn a profit. Which pricing method is the cinema using?","options":{"A":"Competitive pricing - matching rivals' ticket prices","B":"Cost-plus pricing - adding a percentage markup to costs","C":"Promotional pricing - temporary price cuts to fill seats","D":"Loss leader pricing - selling tickets below cost"},"correctOption":"B","correctAnswer":"Cost-plus pricing - adding a percentage markup to costs","questionType":"MCQ","explanation":{"correct_reason":"Cost-plus pricing means calculating the cost of providing a product or service and adding a percentage markup to set the selling price, exactly what Starlight Cinemas is doing.","distractor_reasons":{"A":"Competitive pricing sets prices based on what rivals charge, not by adding a markup to the cinema's own costs.","B":"Cost-plus pricing adds a percentage markup to the cost of each screening, which matches the cinema's approach.","C":"Promotional pricing uses temporary price reductions to attract customers, not a fixed markup on costs.","D":"Loss leader pricing sells below cost to draw customers in, which is not the method described."}}},{"id":"P1_U3_MCQ_324","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_324","question":"MediPump Ltd is the only business producing a patented insulin pump with a pain-free needle. What is the main product-related advantage this gives the firm?","options":{"A":"It can charge the lowest price in the market","B":"It can offer a unique feature that competitors cannot copy","C":"It can avoid all of its production costs","D":"It can distribute through every retailer automatically"},"correctOption":"B","correctAnswer":"It can offer a unique feature that competitors cannot copy","questionType":"MCQ","explanation":{"correct_reason":"A patent protects the design so rivals cannot copy it, giving MediPump a unique product feature that helps differentiate its offering from competitors.","distractor_reasons":{"A":"Having a unique patented product does not mean charging the lowest price; a patent often supports a higher price.","B":"The patent gives a unique feature competitors cannot legally copy, which is the product advantage.","C":"Production costs still exist; a patent does not remove the costs of making the pump.","D":"Distribution through retailers is a place decision, not a benefit that comes from the patent itself."}}},{"id":"P1_U3_MCQ_325","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_325","question":"OceanEscape Cruises wants to build brand awareness by paying popular travel vloggers to show its ships in their videos. Which element of the marketing mix does this activity belong to?","options":{"A":"Product","B":"Price","C":"Place","D":"Promotion"},"correctOption":"D","correctAnswer":"Promotion","questionType":"MCQ","explanation":{"correct_reason":"Paying vloggers to feature the cruises is advertising and sponsorship, which form part of the promotion element of the marketing mix used to communicate with customers.","distractor_reasons":{"A":"Product covers the design, branding and packaging of the cruise, not paid publicity.","B":"Price concerns how much customers are charged, not advertising through vloggers.","C":"Place concerns distribution channels, not activities that promote the product.","D":"Promotion includes advertising and sponsorship, so paying vloggers fits here."}}},{"id":"P1_U3_MCQ_326","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_326","question":"What is the primary objective of the 'Place' element within a business's marketing mix?","options":{"A":"Ensuring products are available to target customers at convenient locations, in the right quantities, and at the right time","B":"Designing the chemical formula and packaging colours of the product","C":"Calculating cost-plus mark-up percentages for the finance team","D":"Writing humorous scripts for television commercials"},"correctOption":"A","correctAnswer":"Ensuring products are available to target customers at convenient locations, in the right quantities, and at the right time","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Place governs distribution channels, logistics, and retail availability so buyers can actually purchase the product.","distractor_reasons":{"A":"Option A is correct because Place governs distribution channels, logistics, and retail availability so buyers can actually purchase the product.","B":"Incorrect because product design and packaging belong to Product.","C":"Incorrect because mark-up calculation belongs to Price.","D":"Incorrect because advert scripts belong to Promotion."}}},{"id":"P1_U3_MCQ_327","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_327","question":"A mattress startup sells mattresses exclusively via its own website and ships boxed mattresses directly from its factory to customers' homes. What is a disadvantage of this 'direct distribution channel' compared with selling through furniture stores?","options":{"A":"The startup must share 50% of its retail margin with wholesale middlemen","B":"Shoppers cannot physically lie down and test mattress firmness in local stores before buying, and the startup bears all individual delivery and return logistics","C":"The startup has zero access to customer email addresses or feedback","D":"Selling direct online is legally prohibited for bulky household furniture"},"correctOption":"B","correctAnswer":"Shoppers cannot physically lie down and test mattress firmness in local stores before buying, and the startup bears all individual delivery and return logistics","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because cutting out retail showrooms removes physical product inspection and shifts storage, single-item shipping, and return handling onto the producer.","distractor_reasons":{"A":"Incorrect because direct selling avoids sharing margins with wholesalers.","B":"Option B is correct because cutting out retail showrooms removes physical product inspection and shifts storage, single-item shipping, and return handling onto the producer.","C":"Incorrect because direct e-commerce gives the brand full ownership of customer data.","D":"Incorrect because direct-to-consumer online mattress sales are completely lawful."}}},{"id":"P1_U3_MCQ_328","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_328","question":"A consumer-electronics brand sells its laptops directly to major national retail chains (Producer -> Retailer -> Consumer) without using a wholesaler. Why does this two-tier channel work well?","options":{"A":"Retailers pay zero money for the laptops until five years after selling them","B":"National retail chains manufacture the laptops inside their shops","C":"Large retail chains buy in full truckloads for their own distribution centres, saving the wholesaler's margin while giving the brand nationwide store displays","D":"Using retailers eliminates all competition from rival laptop brands"},"correctOption":"C","correctAnswer":"Large retail chains buy in full truckloads for their own distribution centres, saving the wholesaler's margin while giving the brand nationwide store displays","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because large retailers have sufficient scale to buy directly in bulk from manufacturers while providing wide consumer reach.","distractor_reasons":{"A":"Incorrect because standard trade credit terms apply (e.g., 30–60 days).","B":"Incorrect because retailers distribute finished goods rather than manufacturing them.","C":"Option C is correct because large retailers have sufficient scale to buy directly in bulk from manufacturers while providing wide consumer reach.","D":"Incorrect because retail stores display multiple rival laptop brands side-by-side."}}},{"id":"P1_U3_MCQ_329","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_329","question":"A small family-owned convenience store needs 20 different brands of snacks, drinks, and cleaning supplies each week, but only has storage space for two cases of each item. Which intermediary is essential to supply this store efficiently?","options":{"A":"An overseas export sales agent","B":"A national television advertising agency","C":"A consumer focus group moderator","D":"A wholesaler who buys bulk pallets from dozens of manufacturers and 'breaks bulk' into small mixed orders for independent shops"},"correctOption":"D","correctAnswer":"A wholesaler who buys bulk pallets from dozens of manufacturers and 'breaks bulk' into small mixed orders for independent shops","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because wholesalers aggregate products from many producers and supply small retailers in manageable quantities.","distractor_reasons":{"A":"Incorrect because export agents arrange international sales rather than domestic grocery wholesaling.","B":"Incorrect because ad agencies create promotional campaigns rather than distributing stock.","C":"Incorrect because focus groups conduct market research.","D":"Option D is correct because wholesalers aggregate products from many producers and supply small retailers in manageable quantities."}}},{"id":"P1_U3_MCQ_330","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_330","question":"An Italian luxury olive-oil producer appoints an 'agent' in South Korea to pitch its oils to Seoul department stores and restaurants. What distinguishes this 'agent' from a 'wholesaler'?","options":{"A":"The agent never takes legal ownership of the olive oil and earns a commission on orders arranged, whereas a wholesaler buys stock outright to resell","B":"The agent owns all the olive groves in Italy and bottles the oil","C":"The agent sells exclusively to individual walk-in shoppers from a market stall","D":"The agent pays the producer a fixed salary regardless of whether any orders are won"},"correctOption":"A","correctAnswer":"The agent never takes legal ownership of the olive oil and earns a commission on orders arranged, whereas a wholesaler buys stock outright to resell","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because agents act as commissioned commercial intermediaries connecting exporters with foreign buyers without holding inventory ownership.","distractor_reasons":{"A":"Option A is correct because agents act as commissioned commercial intermediaries connecting exporters with foreign buyers without holding inventory ownership.","B":"Incorrect because the Italian producer owns the production assets.","C":"Incorrect because agents negotiate B2B trade orders with department stores and restaurants.","D":"Incorrect because independent agents work on commission rather than salaried employment."}}},{"id":"P1_U3_MCQ_331","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_331","question":"A bakery produces fresh artisan sourdough bread daily that tastes best within 24 hours. Why must it avoid a long distribution channel involving regional wholesalers?","options":{"A":"Wholesalers are legally banned from handling bread products","B":"Bread is a luxury prestige item sold only in airport boutiques","C":"Multi-stage wholesale storage adds transit delays that would leave bread stale before reaching consumers","D":"Wholesalers always sell bread below raw flour cost"},"correctOption":"C","correctAnswer":"Multi-stage wholesale storage adds transit delays that would leave bread stale before reaching consumers","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because highly perishable foods require short, rapid distribution channels (direct to consumer or direct to local retailers).","distractor_reasons":{"A":"Incorrect because wholesalers handle packaged long-life baked goods, just not 24-hour fresh artisan loaves.","B":"Incorrect because bread is an everyday staple.","C":"Option C is correct because highly perishable foods require short, rapid distribution channels (direct to consumer or direct to local retailers).","D":"Incorrect because wholesalers add a profit mark-up."}}},{"id":"P1_U3_MCQ_332","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_332","question":"Why does a Swiss luxury fountain-pen maker distribute its $900 pens exclusively through 40 prestigious flagship boutiques worldwide rather than thousands of supermarket stationery aisles?","options":{"A":"Supermarkets refuse to sell any writing instruments","B":"Exclusive distribution protects prestige brand image, ensures knowledgeable personal service, and aligns Place with luxury Product and Price","C":"Fountain pens are perishable items that spoil within 48 hours","D":"Exclusive distribution eliminates all manufacturing costs"},"correctOption":"B","correctAnswer":"Exclusive distribution protects prestige brand image, ensures knowledgeable personal service, and aligns Place with luxury Product and Price","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because high-involvement luxury goods require upscale retail settings that reinforce exclusivity and offer expert consultation.","distractor_reasons":{"A":"Incorrect because supermarkets sell everyday ballpoint pens.","B":"Option B is correct because high-involvement luxury goods require upscale retail settings that reinforce exclusivity and offer expert consultation.","C":"Incorrect because fountain pens are durable goods.","D":"Incorrect because precision craftsmanship still incurs high production costs."}}},{"id":"P1_U3_MCQ_333","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_333","question":"A small pottery studio in rural Wales launches an 'e-commerce' online shop. What is a major commercial benefit of e-commerce for this small business?","options":{"A":"It can sell handmade ceramics to customers across the world 24 hours a day without renting expensive city-centre retail shops","B":"It eliminates all parcel postage, packaging, and payment-processing fees","C":"It guarantees that no other pottery studio can sell online","D":"Customers never return fragile ceramic items shipped by courier"},"correctOption":"A","correctAnswer":"It can sell handmade ceramics to customers across the world 24 hours a day without renting expensive city-centre retail shops","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because e-commerce removes geographic location barriers and lowers fixed retail property overheads.","distractor_reasons":{"A":"Option A is correct because e-commerce removes geographic location barriers and lowers fixed retail property overheads.","B":"Incorrect because shipping, protective packaging, and card fees remain real expenses.","C":"Incorrect because online marketplaces are open to global rivals.","D":"Incorrect because fragile transit breakages and returns remain operational risks."}}},{"id":"P1_U3_MCQ_334","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_334","question":"VoltZone Electronics sells mainly through its own website rather than physical shops. Which of these is a likely disadvantage of this distribution channel?","options":{"A":"Customers can compare rivals' prices easily online","B":"The firm must pay high rent for a high-street shop","C":"It can only make sales during set opening hours","D":"It must use wholesalers to reach its customers"},"correctOption":"A","correctAnswer":"Customers can compare rivals' prices easily online","questionType":"MCQ","explanation":{"correct_reason":"Selling online exposes the retailer to easy comparison shopping, so customers can quickly find cheaper rivals and the firm may have to keep prices competitive.","distractor_reasons":{"A":"Easy online price comparison is a genuine drawback of e-commerce because customers can find cheaper alternatives instantly.","B":"An online-only retailer does not pay high-street shop rent, so this is not a disadvantage here.","C":"A website can take orders at any time, so limited opening hours is not a drawback of online selling.","D":"Selling directly online can bypass wholesalers, so this is not a necessary disadvantage."}}},{"id":"P1_U3_MCQ_335","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_335","question":"How has the rise of 'e-commerce' changed consumer purchasing behaviour for everyday household goods?","options":{"A":"Physical supermarkets have completely disappeared from every city","B":"Consumers are forced to pay higher prices online than in physical shops for every item","C":"Consumers can no longer return faulty goods bought over the internet","D":"Consumers can order anytime from mobile phones with home delivery or click-and-collect, though they must wait for delivery and cannot physically inspect items beforehand"},"correctOption":"D","correctAnswer":"Consumers can order anytime from mobile phones with home delivery or click-and-collect, though they must wait for delivery and cannot physically inspect items beforehand","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because e-commerce trades immediate physical possession and tactile inspection for 24/7 convenience and broad choice.","distractor_reasons":{"A":"Incorrect because physical stores continue to thrive alongside online channels.","B":"Incorrect because online prices are often lower due to lower store overheads.","C":"Incorrect because consumer protection laws grant strong distance-selling return rights.","D":"Option D is correct because e-commerce trades immediate physical possession and tactile inspection for 24/7 convenience and broad choice."}}},{"id":"P1_U3_MCQ_336","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_336","question":"A newly opened dental clinic distributes leaflets explaining its modern painless laser treatments and weekend opening hours to local residents. Which primary aim of 'promotion' is being pursued?","options":{"A":"Raising local awareness and informing potential patients about new services available","B":"Reducing fixed clinic rent and dental equipment depreciation","C":"Harvesting cash flow from a dying product in the decline stage","D":"Conducting random census sampling of national tooth-brushing habits"},"correctOption":"A","correctAnswer":"Raising local awareness and informing potential patients about new services available","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because new businesses must first make target local consumers aware of their existence and service benefits.","distractor_reasons":{"A":"Option A is correct because new businesses must first make target local consumers aware of their existence and service benefits.","B":"Incorrect because promotion incurs marketing spend rather than cutting fixed property rent.","C":"Incorrect because the clinic is newly launched rather than declining.","D":"Incorrect because promotional leaflets communicate information rather than collecting survey data."}}},{"id":"P1_U3_MCQ_337","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_337","question":"How does 'above-the-line promotion' differ from 'below-the-line promotion'?","options":{"A":"Above-the-line uses paid mass-media advertising (TV, radio, press, online display ads) where the firm pays media owners for space, whereas below-the-line uses direct non-mass-media incentives (coupons, PR, personal selling, POS displays) controlled directly by the business","B":"Above-the-line promotion is always completely free, whereas below-the-line costs millions","C":"Above-the-line targets only factory workers, whereas below-the-line targets only foreign governments","D":"Above-the-line is illegal for consumer brands, whereas below-the-line is mandatory"},"correctOption":"A","correctAnswer":"Above-the-line uses paid mass-media advertising (TV, radio, press, online display ads) where the firm pays media owners for space, whereas below-the-line uses direct non-mass-media incentives (coupons, PR, personal selling, POS displays) controlled directly by the business","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the distinction separates paid third-party media advertising from direct promotional tactics like sales promotions and PR.","distractor_reasons":{"A":"Option A is correct because the distinction separates paid third-party media advertising from direct promotional tactics like sales promotions and PR.","B":"Incorrect because paid mass-media advertising is typically very expensive.","C":"Incorrect because both target external buyers and stakeholders.","D":"Incorrect because both are standard, lawful components of the promotional mix."}}},{"id":"P1_U3_MCQ_338","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_338","question":"A city council launches a new high-speed tram line and publishes posters showing exact station maps, ticket fares, and departure frequencies. Why is 'informative advertising' more suitable than 'persuasive image advertising' here?","options":{"A":"Persuasive advertising is banned in all transport industries","B":"Informative posters are legally required to omit ticket prices","C":"Commuters need clear practical facts to understand how to use a brand-new transport service","D":"Commuters never look at station maps before boarding trains"},"correctOption":"C","correctAnswer":"Commuters need clear practical facts to understand how to use a brand-new transport service","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because unfamiliar services and public utilities succeed when potential users receive clear factual guidance.","distractor_reasons":{"A":"Incorrect because airlines and rail firms regularly use persuasive travel adverts.","B":"Incorrect because transparent fare details are helpful and lawful.","C":"Option C is correct because unfamiliar services and public utilities succeed when potential users receive clear factual guidance.","D":"Incorrect because route maps directly assist passenger adoption."}}},{"id":"P1_U3_MCQ_339","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_339","question":"A manufacturer of specialized laboratory microscopes wants to promote its latest model to university biology professors and hospital lab directors. Which advertising medium is most cost-effective?","options":{"A":"Commercials during prime-time pop-music talent shows","B":"Billboards outside children's amusement parks","C":"Specialist scientific and medical trade journals read directly by laboratory decision-makers","D":"Flyers handed out at suburban shopping malls"},"correctOption":"C","correctAnswer":"Specialist scientific and medical trade journals read directly by laboratory decision-makers","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because specialist trade publications reach a concentrated niche of professional buyers with minimal wasted ad spend.","distractor_reasons":{"A":"Incorrect because mass TV entertainment wastes huge budget on non-buyers.","B":"Incorrect because amusement-park visitors are not laboratory equipment buyers.","C":"Option C is correct because specialist trade publications reach a concentrated niche of professional buyers with minimal wasted ad spend.","D":"Incorrect because general mall shoppers do not purchase hospital microscopes."}}},{"id":"P1_U3_MCQ_340","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_340","question":"Why do small online retailers favour 'pay-per-click (PPC) search engine and social media advertising' over traditional print newspaper adverts?","options":{"A":"Print newspapers have zero readers anywhere in the world","B":"Search engine ads are always 100% free regardless of how many clicks occur","C":"Advertisers pay only when interested users actually click the ad, can target exact keywords or demographics, and can track exact return on investment","D":"Digital ads guarantee that every click converts into a $1,000 purchase"},"correctOption":"C","correctAnswer":"Advertisers pay only when interested users actually click the ad, can target exact keywords or demographics, and can track exact return on investment","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because digital performance advertising offers precise intent targeting, flexible small budgets, and real-time conversion analytics.","distractor_reasons":{"A":"Incorrect because newspapers still serve specific older or local audiences.","B":"Incorrect because PPC advertisers pay per click according to auction bids.","C":"Option C is correct because digital performance advertising offers precise intent targeting, flexible small budgets, and real-time conversion analytics.","D":"Incorrect because clicks bring website traffic, though conversion still depends on product and price."}}},{"id":"P1_U3_MCQ_341","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_341","question":"A coffee-shop chain issues stamped 'Buy 9 Coffees, Get the 10th Free' cards to commuters. Which type of promotional tool is this?","options":{"A":"Sales promotion (customer loyalty incentive)","B":"Public relations press release","C":"Above-the-line television advertising","D":"Personal B2B consultative selling"},"correctOption":"A","correctAnswer":"Sales promotion (customer loyalty incentive)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because loyalty stamp cards reward repeat purchases with a tangible short-term product incentive.","distractor_reasons":{"A":"Option A is correct because loyalty stamp cards reward repeat purchases with a tangible short-term product incentive.","B":"Incorrect because PR seeks unpaid media coverage rather than issuing customer reward cards.","C":"Incorrect because stamp cards are a below-the-line point-of-sale promotion.","D":"Incorrect because personal selling involves one-to-one sales pitches."}}},{"id":"P1_U3_MCQ_342","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_342","question":"A shampoo brand offers '25% Extra Free' bonus bottles in supermarkets for one month. What is a likely financial drawback if the brand runs bonus-pack promotions continuously?","options":{"A":"Higher packaging and ingredient costs per unit reduce profit margins, and shoppers refuse to buy standard-sized bottles at regular prices","B":"Supermarkets refuse to display bonus packs on shelves","C":"Giving extra shampoo for free lowers factory raw-material consumption","D":"Competitors are legally prohibited from offering competing promotions"},"correctOption":"A","correctAnswer":"Higher packaging and ingredient costs per unit reduce profit margins, and shoppers refuse to buy standard-sized bottles at regular prices","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because giving away 25% more product at the same price compresses unit profit margin unless it builds lasting brand loyalty.","distractor_reasons":{"A":"Option A is correct because giving away 25% more product at the same price compresses unit profit margin unless it builds lasting brand loyalty.","B":"Incorrect because supermarkets welcome popular promotional packs.","C":"Incorrect because larger fill volumes increase raw-material usage.","D":"Incorrect because rivals frequently match promotions."}}},{"id":"P1_U3_MCQ_343","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_343","question":"A technology company hosts an environmental summit showcasing how its factories run on 100% solar power, attracting positive articles from national business journalists. Why do consumers often trust this 'Public Relations (PR)' coverage more than paid adverts?","options":{"A":"Paid advertisements are illegal in business newspapers","B":"Companies pay journalists directly to print word-for-word advertising scripts disguised as news","C":"PR articles are legally forbidden from mentioning the company's name","D":"Independent journalists write editorial news stories rather than the company buying ad space to praise itself"},"correctOption":"D","correctAnswer":"Independent journalists write editorial news stories rather than the company buying ad space to praise itself","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because third-party editorial endorsement carries higher perceived objectivity and credibility than self-funded commercials.","distractor_reasons":{"A":"Incorrect because paid display ads are completely lawful.","B":"Incorrect because genuine PR earns unpaid editorial coverage rather than bribing journalists.","C":"Incorrect because positive brand mention is the goal of PR.","D":"Option D is correct because third-party editorial endorsement carries higher perceived objectivity and credibility than self-funded commercials."}}},{"id":"P1_U3_MCQ_344","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_344","question":"A custom yacht builder employs experienced marine sales consultants to meet wealthy clients at boat shows, configure interior layouts, and negotiate $2 million build contracts. Why is 'personal selling' vital here?","options":{"A":"Personal selling eliminates the need to build seaworthy yachts","B":"Personal selling is the lowest-cost way to reach 50 million everyday shoppers","C":"Yachts are impulse purchases bought at supermarket checkouts","D":"High-value, bespoke purchases require one-to-one trust, tailored technical advice, and flexible contract negotiation"},"correctOption":"D","correctAnswer":"High-value, bespoke purchases require one-to-one trust, tailored technical advice, and flexible contract negotiation","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because complex, high-ticket items involve detailed buyer questions and customized terms that only human interaction can resolve.","distractor_reasons":{"A":"Incorrect because product engineering excellence remains paramount.","B":"Incorrect because personal selling has a very high cost per contact.","C":"Incorrect because luxury yachts are major capital purchases.","D":"Option D is correct because complex, high-ticket items involve detailed buyer questions and customized terms that only human interaction can resolve."}}},{"id":"P1_U3_MCQ_345","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_345","question":"An airline sends tailored SMS and email alerts offering discounted business-class seat upgrades to frequent flyers 24 hours before departure. What is a potential drawback of 'direct marketing' if overused?","options":{"A":"Direct marketing cannot be personalized with the customer's name or flight details","B":"Direct emails cost $50 per message to send","C":"Sending too many messages annoys customers as 'spam', causing them to unsubscribe or view the brand negatively","D":"Airlines are legally forbidden from emailing loyalty-club members"},"correctOption":"C","correctAnswer":"Sending too many messages annoys customers as 'spam', causing them to unsubscribe or view the brand negatively","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because excessive direct messaging creates inbox fatigue and opt-outs if frequency is not managed carefully.","distractor_reasons":{"A":"Incorrect because personalization is direct marketing's core strength.","B":"Incorrect because digital messaging has a tiny marginal cost per send.","C":"Option C is correct because excessive direct messaging creates inbox fatigue and opt-outs if frequency is not managed carefully.","D":"Incorrect because opted-in loyalty members can lawfully receive offers."}}},{"id":"P1_U3_MCQ_346","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_346","question":"A toy manufacturer forecasts annual revenue of $1,800,000 and sets its marketing budget at 5% of forecasted sales. If 40% of the marketing budget is allocated to digital video ads, how much is spent on digital video ads?","options":{"A":"$90,000","B":"$36,000","C":"$72,000","D":"$54,000"},"correctOption":"B","correctAnswer":"$36,000","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Total Marketing Budget = 5% of $1,800,000 = $90,000; Digital Video Spend = 40% of $90,000 = $36,000.","distractor_reasons":{"A":"Incorrect because $90,000 is the entire annual marketing budget before taking 40% for digital video.","B":"Option B is correct because Total Marketing Budget = 5% of $1,800,000 = $90,000; Digital Video Spend = 40% of $90,000 = $36,000.","C":"Incorrect because $72,000 is 4% of $1,800,000 (or 80% of the budget).","D":"Incorrect because $54,000 is the remaining 60% of the budget."}}},{"id":"P1_U3_MCQ_347","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_347","question":"What is a major weakness of setting a company's annual 'marketing budget' strictly as a fixed percentage (e.g., 5%) of last year's actual sales revenue?","options":{"A":"Accounting laws forbid businesses from linking marketing budgets to sales figures","B":"It is mathematically impossible to calculate 5% of annual sales revenue","C":"If sales fell last year, the budget automatically shrinks when the business actually needs more promotion to revive demand","D":"A percentage-of-sales budget guarantees that every advert produces a 500% profit"},"correctOption":"C","correctAnswer":"If sales fell last year, the budget automatically shrinks when the business actually needs more promotion to revive demand","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because tying budgets mechanically to past sales treats promotion as a result of sales rather than a driver of future sales.","distractor_reasons":{"A":"Incorrect because internal budgeting methods are management decisions.","B":"Incorrect because percentage-of-sales is simple to compute, which is why firms often use it despite its strategic flaw.","C":"Option C is correct because tying budgets mechanically to past sales treats promotion as a result of sales rather than a driver of future sales.","D":"Incorrect because budget size alone does not guarantee creative effectiveness."}}},{"id":"P1_U3_MCQ_348","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_348","question":"A restaurant chain spends $20,000 on local social media ads featuring a unique promo code 'DINE20', which generates $85,000 in tracked food orders with a 50% gross profit margin ($42,500 gross profit). How does tracking promo codes improve marketing decisions?","options":{"A":"It proves precisely that the campaign generated $22,500 net contribution above ad spend, justifying future digital investment","B":"It eliminates the need to pay chefs or buy food ingredients","C":"It prevents customers from visiting the restaurant without a smartphone","D":"It converts promotional expenses into fixed factory assets"},"correctOption":"A","correctAnswer":"It proves precisely that the campaign generated $22,500 net contribution above ad spend, justifying future digital investment","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because traceable codes measure exact return on marketing investment ($42,500 gross profit minus $20,000 ad cost = +$22,500) rather than guessing.","distractor_reasons":{"A":"Option A is correct because traceable codes measure exact return on marketing investment ($42,500 gross profit minus $20,000 ad cost = +$22,500) rather than guessing.","B":"Incorrect because food and kitchen labour costs still apply.","C":"Incorrect because walk-in diners are still welcome.","D":"Incorrect because advertising remains an operating expense."}}},{"id":"P1_U3_MCQ_349","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_349","question":"A supermarket introduces 'click-and-collect' lockers in its car parks and QR codes on shelf labels that unlock recipe videos and instant digital coupons on shoppers' phones. How does this technology integrate 'Place' and 'Promotion'?","options":{"A":"It blends digital convenience and interactive point-of-sale offers directly into the physical shopping experience","B":"It eliminates the need to keep food shelves stocked","C":"It forces shoppers to pay twice for every grocery item scanned","D":"It prevents customers from comparing unit prices per kilogram"},"correctOption":"A","correctAnswer":"It blends digital convenience and interactive point-of-sale offers directly into the physical shopping experience","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because mobile-enabled retail connects physical fulfilment convenience with real-time digital engagement.","distractor_reasons":{"A":"Option A is correct because mobile-enabled retail connects physical fulfilment convenience with real-time digital engagement.","B":"Incorrect because stocked inventory remains essential for both store and click-and-collect orders.","C":"Incorrect because QR coupons provide discounts rather than double-charging.","D":"Incorrect because unit pricing remains clearly displayed."}}},{"id":"P1_U3_MCQ_350","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_350","question":"An indie video-game studio launches a multiplayer PC game priced at $19.99, distributing it digitally via Steam and promoting it through live gaming streamers on Twitch and YouTube. Why are 'Place' and 'Promotion' well aligned here?","options":{"A":"Both digital distribution and gaming-stream promotion meet PC gamers directly on the online platforms where they already watch, socialize, and download games","B":"Printed newspaper adverts and physical DVD boxes are the only ways PC gamers buy games","C":"Digital downloads incur high international shipping container tariffs","D":"Twitch streamers are legally required to promote every new game for free"},"correctOption":"A","correctAnswer":"Both digital distribution and gaming-stream promotion meet PC gamers directly on the online platforms where they already watch, socialize, and download games","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because matching digital delivery channels with interactive creator streams removes friction between seeing gameplay and instant purchase.","distractor_reasons":{"A":"Option A is correct because matching digital delivery channels with interactive creator streams removes friction between seeing gameplay and instant purchase.","B":"Incorrect because PC gaming has shifted overwhelmingly to digital downloads.","C":"Incorrect because digital software distribution has zero physical shipping containers.","D":"Incorrect because sponsored streams are commercial promotional agreements."}}},{"id":"P1_U3_MCQ_351","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_351","question":"What best defines a business's 'marketing strategy'?","options":{"A":"A long-term plan that uses market research to select target segments and coordinates Product, Price, Place, and Promotion to achieve marketing objectives","B":"A daily timetable showing when factory cleaners mop the warehouse floor","C":"A single one-day price discount offered without checking costs or competitors","D":"A legal contract hiring a new human resources manager"},"correctOption":"A","correctAnswer":"A long-term plan that uses market research to select target segments and coordinates Product, Price, Place, and Promotion to achieve marketing objectives","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a marketing strategy integrates customer targeting with a consistent, goal-driven 4Ps marketing mix.","distractor_reasons":{"A":"Option A is correct because a marketing strategy integrates customer targeting with a consistent, goal-driven 4Ps marketing mix.","B":"Incorrect because cleaning schedules are routine operational housekeeping.","C":"Incorrect because an isolated ad-hoc discount is a short-term tactic rather than a strategy.","D":"Incorrect because recruitment contracts belong to Human Resources."}}},{"id":"P1_U3_MCQ_352","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_352","question":"An artisan cashmere-coat brand targets affluent fashion buyers. Which coordinated marketing mix justifies a $1,800 retail price?","options":{"A":"100% pure Scottish cashmere with hand-finished tailoring (Product), prestige pricing (Price), flagship city boutiques and white-glove online delivery (Place), and glossy fashion-magazine editorials (Promotion)","B":"Synthetic polyester blends (Product), prestige pricing (Price), discount warehouse bins (Place), and local bus-stop flyers (Promotion)","C":"100% pure cashmere (Product), $15 clearance pricing (Price), supermarket checkout racks (Place), and coupon leaflets (Promotion)","D":"Unlabelled coats (Product), cost-plus pricing (Price), wholesale cash-and-carry depots (Place), and zero promotion"},"correctOption":"A","correctAnswer":"100% pure Scottish cashmere with hand-finished tailoring (Product), prestige pricing (Price), flagship city boutiques and white-glove online delivery (Place), and glossy fashion-magazine editorials (Promotion)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because superior craftsmanship, exclusive retail settings, and prestigious editorial promotion reinforce the $1,800 price positioning.","distractor_reasons":{"A":"Option A is correct because superior craftsmanship, exclusive retail settings, and prestigious editorial promotion reinforce the $1,800 price positioning.","B":"Incorrect because synthetic fabric and discount bins destroy credibility for an $1,800 coat.","C":"Incorrect because $15 pricing and supermarket racks lose money and ruin luxury image.","D":"Incorrect because unlabelled wholesale coats fail to build luxury brand equity."}}},{"id":"P1_U3_MCQ_353","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_353","question":"A new bottled-water brand targets everyday commuters seeking affordable hydration. Which marketing mix is most coherent and commercially viable?","options":{"A":"Recyclable ergonomic 500ml bottles (Product), competitive $1.00 pricing (Price), intensive distribution across supermarkets, train kiosks, and vending machines (Place), and commuter billboard/social ads (Promotion)","B":"Heavy crystal decanters (Product), $95 price skimming (Price), appointment-only jewellery stores (Place), and personal door-to-door sales advisors (Promotion)","C":"Unlabelled plastic jugs (Product), $25 pricing (Price), sold solely from one rural farm gate (Place), and scientific journal ads (Promotion)","D":"500ml bottles (Product), $0.05 loss-leader pricing permanently (Price), sold only via postal mail order (Place), and zero promotion"},"correctOption":"A","correctAnswer":"Recyclable ergonomic 500ml bottles (Product), competitive $1.00 pricing (Price), intensive distribution across supermarkets, train kiosks, and vending machines (Place), and commuter billboard/social ads (Promotion)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because everyday convenience products require competitive pricing, maximum retail accessibility, and high-visibility commuter promotion.","distractor_reasons":{"A":"Option A is correct because everyday convenience products require competitive pricing, maximum retail accessibility, and high-visibility commuter promotion.","B":"Incorrect because $95 crystal decanters in jewellery shops do not serve everyday commuters.","C":"Incorrect because $25 unlabelled jugs at a single rural farm gate cannot reach urban commuters.","D":"Incorrect because permanent $0.05 pricing causes massive losses and postal delivery is impractical for single bottles."}}},{"id":"P1_U3_MCQ_354","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_354","question":"When a cordless drill brand moves from 'Introduction' into 'Growth' and 'Maturity', why must it widen its 'Place' strategy from specialist tool shops to major hardware superstores and online marketplaces?","options":{"A":"Because hardware superstores charge zero retail margin on power tools","B":"Because specialist tool shops are legally required to close after six months","C":"To reach mainstream DIY buyers nationwide and achieve the high sales volumes needed for manufacturing economies of scale","D":"To reduce consumer awareness of the drill brand"},"correctOption":"C","correctAnswer":"To reach mainstream DIY buyers nationwide and achieve the high sales volumes needed for manufacturing economies of scale","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because early adopters visit specialist outlets at introduction, whereas mainstream growth and maturity require broad retail availability.","distractor_reasons":{"A":"Incorrect because superstores negotiate wholesale discounts for their retail margin.","B":"Incorrect because specialist tool shops remain open, just serving a smaller segment.","C":"Option C is correct because early adopters visit specialist outlets at introduction, whereas mainstream growth and maturity require broad retail availability.","D":"Incorrect because wider shelf presence increases brand visibility."}}},{"id":"P1_U3_MCQ_355","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_355","question":"A rival smartwatch brand launches a model with 10-day battery life, causing an established smartwatch company's sales to dip. Which strategic marketing response addresses the root competitive threat?","options":{"A":"Invest in R&D to upgrade battery efficiency while running persuasive campaigns highlighting superior health sensors and app ecosystem integration","B":"Pretend the rival watch does not exist and cut R&D spending to zero","C":"Raise watch prices by 50% without improving battery life","D":"Switch from online and retail sales to postal mail-order catalogues only"},"correctOption":"A","correctAnswer":"Invest in R&D to upgrade battery efficiency while running persuasive campaigns highlighting superior health sensors and app ecosystem integration","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because matching or leapfrogging rival product performance while emphasizing existing strengths defends market share effectively.","distractor_reasons":{"A":"Option A is correct because matching or leapfrogging rival product performance while emphasizing existing strengths defends market share effectively.","B":"Incorrect because ignoring superior competitor features accelerates share loss.","C":"Incorrect because raising prices on an inferior battery model drives buyers away.","D":"Incorrect because restricting distribution does not solve the product feature gap."}}},{"id":"P1_U3_MCQ_356","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_356","question":"How does rapid growth in smartphone mobile commerce ('m-commerce') require a clothing retailer to adapt its marketing strategy?","options":{"A":"Stop accepting digital payments and accept only paper cheques by post","B":"Remove all product photos from its website to save mobile data","C":"Disable smartphone access to its online store so shoppers must use desktop computers","D":"Optimize mobile-friendly checkout apps, offer one-tap digital wallet payments, and run short vertical video ads with direct shoppable links"},"correctOption":"D","correctAnswer":"Optimize mobile-friendly checkout apps, offer one-tap digital wallet payments, and run short vertical video ads with direct shoppable links","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because aligning digital promotion and seamless mobile checkout with how consumers browse on phones boosts conversion rates.","distractor_reasons":{"A":"Incorrect because paper cheques create massive checkout friction.","B":"Incorrect because clear visual photos and videos are vital for mobile apparel shoppers.","C":"Incorrect because blocking mobile users cuts off the largest e-commerce traffic source.","D":"Option D is correct because aligning digital promotion and seamless mobile checkout with how consumers browse on phones boosts conversion rates."}}},{"id":"P1_U3_MCQ_357","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_357","question":"Why does expanding into 'foreign markets' help a domestic manufacturer reduce overall business risk?","options":{"A":"Exporting eliminates all foreign exchange-rate fluctuations","B":"Foreign countries never experience economic downturns or competition","C":"If the home country enters an economic recession, strong sales in growing foreign economies can offset domestic revenue declines","D":"Foreign governments guarantee 100% profit margins to all imported brands"},"correctOption":"C","correctAnswer":"If the home country enters an economic recession, strong sales in growing foreign economies can offset domestic revenue declines","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because geographic diversification prevents over-dependence on a single national economy's business cycle.","distractor_reasons":{"A":"Incorrect because international trade introduces currency conversion risk.","B":"Incorrect because foreign markets have their own business cycles and rivals.","C":"Option C is correct because geographic diversification prevents over-dependence on a single national economy's business cycle.","D":"Incorrect because exporters compete on commercial merit without profit guarantees."}}},{"id":"P1_U3_MCQ_358","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_358","question":"A European snack company exports beef-flavoured crisps and pork-gelatin sweets into a predominantly Muslim country without changing ingredients or Halal certification, resulting in zero supermarket orders. Which barrier to foreign market entry was overlooked?","options":{"A":"Cultural and religious dietary laws governing acceptable food ingredients","B":"High shipping container weight limits","C":"Lack of internet broadband speed in supermarkets","D":"Excessive use of random survey sampling"},"correctOption":"A","correctAnswer":"Cultural and religious dietary laws governing acceptable food ingredients","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because religious and cultural dietary rules strictly govern consumer food acceptance and import approval.","distractor_reasons":{"A":"Option A is correct because religious and cultural dietary rules strictly govern consumer food acceptance and import approval.","B":"Incorrect because snack crisps and sweets are lightweight.","C":"Incorrect because supermarket orders were rejected due to non-Halal ingredients, not internet speed.","D":"Incorrect because the failure resulted from ignoring local cultural research."}}},{"id":"P1_U3_MCQ_359","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_359","question":"A luxury handbag maker from Europe enters a developing economy where average household incomes are one-fifth of European levels, yet tries to sell identical $2,000 bags without introducing smaller, lower-priced accessories. Why will sales likely struggle?","options":{"A":"Failure to adapt product sizing and pricing tiers to local purchasing power and income distribution","B":"Consumers in developing economies never buy branded fashion accessories","C":"European handbags are legally banned from being exported","D":"Lower-priced leather wallets have higher manufacturing costs than $2,000 coats"},"correctOption":"A","correctAnswer":"Failure to adapt product sizing and pricing tiers to local purchasing power and income distribution","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because lower average disposable incomes restrict the size of the ultra-luxury segment, making accessible entry-level luxury items (like wallets or fragrances) strategic.","distractor_reasons":{"A":"Option A is correct because lower average disposable incomes restrict the size of the ultra-luxury segment, making accessible entry-level luxury items (like wallets or fragrances) strategic.","B":"Incorrect because aspirational brand demand is strong when priced within local reach.","C":"Incorrect because luxury goods are major European exports.","D":"Incorrect because smaller accessories use less material and cost less to produce."}}},{"id":"P1_U3_MCQ_360","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_360","question":"A domestic appliance maker produces blenders at a landed export cost (including shipping) of $40 per unit. If the importing country charges a 25% import tariff on blenders, what is the minimum price per blender needed just to break even on landed tariff-paid cost?","options":{"A":"$45.00","B":"$50.00","C":"$65.00","D":"$30.00"},"correctOption":"B","correctAnswer":"$50.00","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Import Tariff = 25% of $40 = $10.00; Total Tariff-Paid Cost = $40.00 + $10.00 = $50.00.","distractor_reasons":{"A":"Incorrect because $45.00 adds only 12.5% ($5) instead of 25%.","B":"Option B is correct because Import Tariff = 25% of $40 = $10.00; Total Tariff-Paid Cost = $40.00 + $10.00 = $50.00.","C":"Incorrect because $65.00 adds $25 flat rather than 25% of $40.","D":"Incorrect because $30.00 subtracts $10 instead of adding the import tariff."}}},{"id":"P1_U3_MCQ_361","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_361","question":"A Japanese electronics company forms a 50/50 'joint venture' with a Brazilian manufacturer to assemble and market air conditioners in South America. What is a key strategic advantage of this entry method?","options":{"A":"Local assembly avoids high finished-product import tariffs while combining Japanese engineering with the Brazilian partner's local distribution network and market insight","B":"The Japanese firm keeps 100% of all profits without sharing control","C":"Joint ventures guarantee zero cultural or management disagreements","D":"Neither partner has to invest any money or technical staff"},"correctOption":"A","correctAnswer":"Local assembly avoids high finished-product import tariffs while combining Japanese engineering with the Brazilian partner's local distribution network and market insight","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because local joint-venture production bypasses import barriers and leverages complementary strengths while sharing capital risk.","distractor_reasons":{"A":"Option A is correct because local joint-venture production bypasses import barriers and leverages complementary strengths while sharing capital risk.","B":"Incorrect because profits and governance are shared 50/50.","C":"Incorrect because differing corporate cultures remain a key risk.","D":"Incorrect because both partners contribute capital, technology, or facilities."}}},{"id":"P1_U3_MCQ_362","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_362","question":"A British sportswear brand grants a local textile company in India the legal right to manufacture and sell its branded gymwear for five years in return for an 8% royalty on wholesale revenue. What is a major risk of this 'licensing' agreement?","options":{"A":"Once the five-year license expires, the local manufacturer may use the production expertise and market contacts gained to launch its own rival brand","B":"The British brand must pay 100% of the Indian factory's electricity and wage bills","C":"Licensing prevents the British brand from earning any royalty income","D":"Licensing exposes the British brand to high import tariffs on finished gymwear"},"correctOption":"A","correctAnswer":"Once the five-year license expires, the local manufacturer may use the production expertise and market contacts gained to launch its own rival brand","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because transferring technical know-how and local market access to an independent licensee risks nurturing a future competitor.","distractor_reasons":{"A":"Option A is correct because transferring technical know-how and local market access to an independent licensee risks nurturing a future competitor.","B":"Incorrect because the licensee funds its own factory operations.","C":"Incorrect because the licensor earns the contracted 8% royalty.","D":"Incorrect because local production avoids finished-good import tariffs."}}},{"id":"P1_U3_MCQ_363","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_363","question":"A Canadian fast-casual sandwich chain enters 15 European countries by selling master 'franchise' rights to local operators who invest their own capital to open branded stores. Why is franchising faster than opening wholly owned branches?","options":{"A":"Franchisees provide the startup capital and local store management, allowing simultaneous multi-country expansion without exhausting the franchisor's balance sheet","B":"Franchisees require zero training, brand manuals, or quality audits","C":"The franchisor receives 100% of every store's net profit","D":"Franchising eliminates the need to adapt menus to local dietary preferences"},"correctOption":"A","correctAnswer":"Franchisees provide the startup capital and local store management, allowing simultaneous multi-country expansion without exhausting the franchisor's balance sheet","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because leveraging franchisee capital and local entrepreneurial drive overcomes financial and managerial bottlenecks.","distractor_reasons":{"A":"Option A is correct because leveraging franchisee capital and local entrepreneurial drive overcomes financial and managerial bottlenecks.","B":"Incorrect because franchisors must invest heavily in training and quality monitoring.","C":"Incorrect because the franchisor earns upfront fees and ongoing royalty percentages.","D":"Incorrect because successful global franchises still adapt menus to local tastes."}}},{"id":"P1_U3_MCQ_364","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_364","question":"When is setting up a 'wholly owned foreign manufacturing subsidiary' preferable to 'direct exporting' from the home country?","options":{"A":"When foreign sales volume is large and stable, transport costs or import tariffs are very high, and the firm wants 100% control over quality and profits","B":"When the business has almost zero capital and wants to test a tiny foreign market for two months","C":"When the foreign country is politically unstable and confiscates foreign factories","D":"When the product is digital software downloadable over the internet at zero shipping cost"},"correctOption":"A","correctAnswer":"When foreign sales volume is large and stable, transport costs or import tariffs are very high, and the firm wants 100% control over quality and profits","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because high committed capital is justified when scale, tariff savings, and full operational control outweigh startup risk.","distractor_reasons":{"A":"Option A is correct because high committed capital is justified when scale, tariff savings, and full operational control outweigh startup risk.","B":"Incorrect because low-capital market testing suits direct exporting or local distributors.","C":"Incorrect because political instability makes fixed foreign asset ownership high-risk.","D":"Incorrect because digital software needs no overseas factories."}}},{"id":"P1_U3_MCQ_365","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_365","question":"Why does a global smartphone brand keep its hardware specifications and operating system standardized worldwide while translating user manuals, app stores, and advertising campaigns for each country?","options":{"A":"Consumers prefer phones with operating systems written in foreign languages they cannot read","B":"Governments ban companies from selling identical phone hardware in two different countries","C":"Translating user manuals increases factory chip-fabrication costs by 500%","D":"Standardized hardware captures massive global manufacturing economies of scale, while localized promotion and language support ensure cultural relevance"},"correctOption":"D","correctAnswer":"Standardized hardware captures massive global manufacturing economies of scale, while localized promotion and language support ensure cultural relevance","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because balancing global production scale with local communication adaptation maximizes both cost efficiency and customer appeal.","distractor_reasons":{"A":"Incorrect because local language interfaces are vital for usability.","B":"Incorrect because global tech firms sell uniform core devices worldwide.","C":"Incorrect because software/manual localization is inexpensive relative to hardware tooling.","D":"Option D is correct because balancing global production scale with local communication adaptation maximizes both cost efficiency and customer appeal."}}},{"id":"P1_U3_MCQ_366","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_366","question":"Why do governments enact 'consumer protection legislation' regulating how businesses advertise, price, and sell goods?","options":{"A":"To prevent consumers from ever returning broken or misdescribed items","B":"To guarantee that every private business makes at least a 40% net profit margin","C":"To protect individual buyers—who have less technical information and bargaining power than large corporations—from unsafe, faulty, or deceptive products","D":"To eliminate all price competition between rival supermarkets"},"correctOption":"C","correctAnswer":"To protect individual buyers—who have less technical information and bargaining power than large corporations—from unsafe, faulty, or deceptive products","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because consumer protection laws correct information asymmetry and enforce minimum standards of honesty, safety, and quality.","distractor_reasons":{"A":"Incorrect because consumer laws grant statutory return and refund rights.","B":"Incorrect because laws protect buyers rather than guaranteeing business profits.","C":"Option C is correct because consumer protection laws correct information asymmetry and enforce minimum standards of honesty, safety, and quality.","D":"Incorrect because competition laws actively encourage fair rivalry."}}},{"id":"P1_U3_MCQ_367","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_367","question":"A travel website advertises a '5-Star Beachfront Resort' with photos of white sand, but arriving guests discover the hotel is a 2-star building three miles inland next to a highway. Which legal control has been violated?","options":{"A":"Patent royalty licensing rules","B":"Factory minimum-wage legislation","C":"Weights and measures liquid-volume rules","D":"Trade descriptions and misleading advertising laws prohibiting false statements about product or service features"},"correctOption":"D","correctAnswer":"Trade descriptions and misleading advertising laws prohibiting false statements about product or service features","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because misrepresenting location, star rating, and amenities deceives consumers and breaches fair-trading descriptions laws.","distractor_reasons":{"A":"Incorrect because patent rules govern inventions.","B":"Incorrect because minimum-wage laws govern employee pay.","C":"Incorrect because weights and measures govern physical quantity labelling.","D":"Option D is correct because misrepresenting location, star rating, and amenities deceives consumers and breaches fair-trading descriptions laws."}}},{"id":"P1_U3_MCQ_368","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_368","question":"A shopper buys a waterproof hiking jacket, and during its first light rain shower water leaks straight through the seams. The store displays a sign saying 'No Refunds Under Any Circumstances'. Why is the store's policy unlawful?","options":{"A":"Statutory consumer rights require goods to be 'fit for their intended purpose' and of satisfactory quality, overriding shop signs that try to waive legal remedies","B":"Retailers are legally required to refund jackets simply because a shopper dislikes the colour six months later","C":"Hiking jackets are exempt from all sales taxes","D":"Stores are forbidden from displaying any signs near cash registers"},"correctOption":"A","correctAnswer":"Statutory consumer rights require goods to be 'fit for their intended purpose' and of satisfactory quality, overriding shop signs that try to waive legal remedies","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a waterproof jacket that leaks is not fit for purpose, and retailers cannot contract out of statutory consumer protections.","distractor_reasons":{"A":"Option A is correct because a waterproof jacket that leaks is not fit for purpose, and retailers cannot contract out of statutory consumer protections.","B":"Incorrect because statutory remedies apply to faulty/unfit goods rather than change-of-mind months later.","C":"Incorrect because sales taxes apply normally.","D":"Incorrect because signs are lawful unless they misrepresent statutory rights."}}},{"id":"P1_U3_MCQ_369","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_369","question":"A petrol station's fuel pumps are found by trading-standards inspectors to dispense only 0.92 litres of petrol for every 1.00 litre charged on the digital display. Which consumer law is being breached?","options":{"A":"Employment redundancy notice legislation","B":"Weights and measures legislation requiring accurate measurement of goods sold by volume or weight","C":"Copyright protection over television jingles","D":"Franchise territory exclusivity agreements"},"correctOption":"B","correctAnswer":"Weights and measures legislation requiring accurate measurement of goods sold by volume or weight","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because weights-and-measures statutes require calibrated equipment so buyers receive the exact quantity paid for.","distractor_reasons":{"A":"Incorrect because redundancy laws belong to Human Resources.","B":"Option B is correct because weights-and-measures statutes require calibrated equipment so buyers receive the exact quantity paid for.","C":"Incorrect because copyright protects artistic works.","D":"Incorrect because franchise agreements are private commercial contracts."}}},{"id":"P1_U3_MCQ_370","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_370","question":"A sofa store advertises '70% Off — Ends Sunday!' continuously for 52 weeks in a row, never actually selling sofas at the higher reference price. Why do consumer regulators fine this tactic?","options":{"A":"Advertising furniture discounts is banned in all newspapers","B":"Sofa stores are legally required to raise prices every Monday morning","C":"Fictitious urgency and misleading reference pricing deceive shoppers into believing a permanent price is a temporary bargain","D":"Consumers are prohibited from buying sofas on weekends"},"correctOption":"C","correctAnswer":"Fictitious urgency and misleading reference pricing deceive shoppers into believing a permanent price is a temporary bargain","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because fake countdown deadlines and inflated reference prices manipulate buyer urgency unfairly.","distractor_reasons":{"A":"Incorrect because genuine sales promotions are lawful.","B":"Incorrect because firms set prices freely provided promotional claims are genuine.","C":"Option C is correct because fake countdown deadlines and inflated reference prices manipulate buyer urgency unfairly.","D":"Incorrect because weekend retail trading is standard."}}},{"id":"P1_U3_MCQ_371","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_371","question":"A bakery switches to a cheaper supplier of almond flour for its chocolate brownies, but forgets to update the ingredient list or add a 'Contains Tree Nuts' allergen warning on the wrapper. What severe legal and commercial consequence could follow?","options":{"A":"Exemption from paying business income taxes for five years","B":"Automatic 50% increase in repeat orders from nut-allergic shoppers","C":"Life-threatening allergic reactions in customers, mandatory product recalls, heavy criminal fines, and catastrophic brand trust collapse","D":"Reduced packaging printing costs with zero legal liability"},"correctOption":"C","correctAnswer":"Life-threatening allergic reactions in customers, mandatory product recalls, heavy criminal fines, and catastrophic brand trust collapse","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because food allergen labelling laws are strictly enforced to protect consumer lives; omissions trigger immediate recalls and prosecution.","distractor_reasons":{"A":"Incorrect because safety breaches incur fines rather than tax breaks.","B":"Incorrect because unlisted allergens endanger customers and destroy trust.","C":"Option C is correct because food allergen labelling laws are strictly enforced to protect consumer lives; omissions trigger immediate recalls and prosecution.","D":"Incorrect because businesses bear strict legal liability for accurate allergen declarations."}}},{"id":"P1_U3_MCQ_372","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_372","question":"Under modern data-protection and digital-marketing laws, what must an e-commerce retailer do before adding a new website visitor's email address to its promotional newsletter list?","options":{"A":"Publish the customer's home address and phone number publicly on social media","B":"Automatically subscribe every visitor using hidden pre-ticked boxes","C":"Obtain clear, affirmative opt-in consent from the customer and provide an easy one-click unsubscribe option in every marketing email","D":"Charge the customer $10 to remove their email from the mailing list"},"correctOption":"C","correctAnswer":"Obtain clear, affirmative opt-in consent from the customer and provide an easy one-click unsubscribe option in every marketing email","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because privacy regulations require explicit permission for direct marketing and transparent opt-out rights.","distractor_reasons":{"A":"Incorrect because sharing personal data publicly breaches privacy laws.","B":"Incorrect because pre-ticked boxes do not constitute valid consent under data protection laws.","C":"Option C is correct because privacy regulations require explicit permission for direct marketing and transparent opt-out rights.","D":"Incorrect because unsubscribing must be free and straightforward."}}},{"id":"P1_U3_MCQ_373","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_373","question":"Why do broadcasting regulators enforce strict rules prohibiting television adverts from pressuring children directly to beg parents to buy expensive toys ('pester power')?","options":{"A":"Because young children lack the critical maturity to distinguish persuasive commercial intent from factual reality, requiring ethical and legal protection","B":"Because toy companies are legally forbidden from manufacturing plastic toys","C":"Because parents never buy birthday or holiday presents for their children","D":"Because television channels only broadcast educational documentaries"},"correctOption":"A","correctAnswer":"Because young children lack the critical maturity to distinguish persuasive commercial intent from factual reality, requiring ethical and legal protection","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because advertising standards codes protect vulnerable audiences such as children from exploitative psychological pressure.","distractor_reasons":{"A":"Option A is correct because advertising standards codes protect vulnerable audiences such as children from exploitative psychological pressure.","B":"Incorrect because manufacturing toys is lawful when safety standards are met.","C":"Incorrect because parents remain the primary purchasers of toys.","D":"Incorrect because commercial channels air diverse programming under advertising rules."}}},{"id":"P1_U3_MCQ_374","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_374","question":"A household-appliance manufacturer spends $400,000 extra each year on independent electrical safety certifications and clear multilingual warning manuals. How can its marketing team turn this legal compliance cost into a competitive advantage?","options":{"A":"Highlight certified safety testing and 5-year reliability guarantees in promotions to justify premium pricing over uncertified budget imports","B":"Hide all safety certificates so customers assume the appliances are untested","C":"Stop inspecting factory output because certificates last forever without quality checks","D":"Cut warranty coverage to zero days to recover the $400,000 fee"},"correctOption":"A","correctAnswer":"Highlight certified safety testing and 5-year reliability guarantees in promotions to justify premium pricing over uncertified budget imports","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because visible safety assurance reduces perceived buyer risk, strengthening brand trust and supporting higher profit margins.","distractor_reasons":{"A":"Option A is correct because visible safety assurance reduces perceived buyer risk, strengthening brand trust and supporting higher profit margins.","B":"Incorrect because showcasing safety credentials builds buyer confidence.","C":"Incorrect because ongoing quality control is required to maintain certification.","D":"Incorrect because strong safety testing allows the firm to offer generous warranties confidently."}}},{"id":"P1_U3_MCQ_375","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_375","question":"A mid-sized European baby-stroller manufacturer faces falling domestic birth rates and strict European safety standards. Which integrated 'marketing strategy' is most likely to achieve sustainable long-term growth?","options":{"A":"Leverage its strict European safety certification as a premium trust USP to enter fast-growing Asian middle-class markets via local joint-venture distributors while expanding domestic accessories for existing parents","B":"Cut stroller frame quality to lower costs, ignore safety testing laws, and rely solely on domestic high-street shops","C":"Double domestic stroller prices while stopping all digital marketing and product R&D","D":"Sell unbranded strollers at below variable cost using misleading '90% Off' fake discounts"},"correctOption":"A","correctAnswer":"Leverage its strict European safety certification as a premium trust USP to enter fast-growing Asian middle-class markets via local joint-venture distributors while expanding domestic accessories for existing parents","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because turning regulatory safety excellence into an international trust advantage opens growing foreign demographics while extending domestic customer value.","distractor_reasons":{"A":"Option A is correct because turning regulatory safety excellence into an international trust advantage opens growing foreign demographics while extending domestic customer value.","B":"Incorrect because compromising child safety violates laws and destroys brand reputation.","C":"Incorrect because doubling prices in a shrinking domestic market collapses sales.","D":"Incorrect because selling below variable cost causes losses and fake discounts breach consumer law."}}},{"id":"P1_U3_MCQ_376","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_376","question":"A desk-accessory startup discovers through home-office visits that remote workers struggle with tangled charger cables, and designs a magnetic modular cable organizer priced to yield a 35% profit margin. Which core principle of marketing is shown?","options":{"A":"Focusing purely on maximizing factory machine running hours","B":"Producing the cheapest possible item regardless of buyer usefulness","C":"Identifying customer pain points and satisfying them profitably","D":"Eliminating all promotional spending to cut fixed overheads"},"correctOption":"C","correctAnswer":"Identifying customer pain points and satisfying them profitably","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because effective marketing connects a genuine consumer need with a commercial solution that generates sustainable profit.","distractor_reasons":{"A":"Incorrect because maximizing machine hours without demand focus reflects production orientation.","B":"Incorrect because ignoring buyer utility undermines product demand.","C":"Option C is correct because effective marketing connects a genuine consumer need with a commercial solution that generates sustainable profit.","D":"Incorrect because new products still require promotion to build awareness."}}},{"id":"P1_U3_MCQ_377","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_377","question":"Noticing a steady rise in single-person pet ownership, a home-security firm develops an indoor camera with built-in treat dispensing and barking alerts two years before major rivals enter the space. Which marketing role does this demonstrate?","options":{"A":"Managing statutory corporate tax filings","B":"Anticipating future customer needs ahead of competitors","C":"Negotiating raw-material bulk discounts with steel mills","D":"Operating a pure price-skimming monopoly on basic cameras"},"correctOption":"B","correctAnswer":"Anticipating future customer needs ahead of competitors","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because spotting emerging demographic lifestyle trends allows marketing teams to anticipate future demand early.","distractor_reasons":{"A":"Incorrect because tax compliance is handled by Finance.","B":"Option B is correct because spotting emerging demographic lifestyle trends allows marketing teams to anticipate future demand early.","C":"Incorrect because supplier procurement belongs to Operations.","D":"Incorrect because standard security cameras already face wide competition."}}},{"id":"P1_U3_MCQ_378","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_378","question":"A specialty coffee roaster calculates that acquiring a first-time online buyer costs $28 in adverts, whereas retaining an existing subscriber costs $4 per year in loyalty perks. Why is maintaining customer loyalty vital for profitability?","options":{"A":"Loyal customers never expect consistent coffee bean quality","B":"Repeat buyers generate recurring revenue at much lower marketing cost per order than constantly replacing lost customers","C":"High customer loyalty eliminates all coffee roasting and shipping expenses","D":"Retained subscribers are legally forbidden from buying rival brands"},"correctOption":"B","correctAnswer":"Repeat buyers generate recurring revenue at much lower marketing cost per order than constantly replacing lost customers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because repeat purchases amortize initial customer acquisition costs and produce reliable long-term cash flow.","distractor_reasons":{"A":"Incorrect because quality consistency is what sustains loyalty.","B":"Option B is correct because repeat purchases amortize initial customer acquisition costs and produce reliable long-term cash flow.","C":"Incorrect because production and delivery costs still apply to every order.","D":"Incorrect because consumers always remain free to switch brands."}}},{"id":"P1_U3_MCQ_379","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_379","question":"Total annual sales in a regional organic baby-food market equal $425 million, and PureSpoon Ltd achieves annual sales of $85 million. What is PureSpoon Ltd's market share?","options":{"A":"5.0%","B":"20.0%","C":"25.0%","D":"85.0%"},"correctOption":"B","correctAnswer":"20.0%","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Market Share (%) = ($85m / $425m) × 100 = 20.0%.","distractor_reasons":{"A":"Incorrect because 5.0 divides $425m by $85m instead of $85m by $425m.","B":"Option B is correct because Market Share (%) = ($85m / $425m) × 100 = 20.0%.","C":"Incorrect because 25.0% divides $85m by $340m ($425m - $85m).","D":"Incorrect because 85.0% confuses dollar sales with percentage share."}}},{"id":"P1_U3_MCQ_380","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_380","question":"During an economic slowdown, total industry sales of home-renovation tiles fall by 12%, while AquaTile Ltd's sales revenue declines by only 3%. What happened to AquaTile Ltd's market share?","options":{"A":"Its market share increased because its sales fell far less sharply than the overall market","B":"Its market share fell by 9%","C":"Its market share dropped to zero","D":"Its market share remained completely unchanged"},"correctOption":"A","correctAnswer":"Its market share increased because its sales fell far less sharply than the overall market","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because outperforming the industry average—even in a shrinking market—means capturing a larger slice of remaining sales.","distractor_reasons":{"A":"Option A is correct because outperforming the industry average—even in a shrinking market—means capturing a larger slice of remaining sales.","B":"Incorrect because losing fewer sales than rivals raises relative share.","C":"Incorrect because AquaTile retained 97% of its previous sales.","D":"Incorrect because relative share changes whenever firm growth differs from total market growth."}}},{"id":"P1_U3_MCQ_381","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_381","question":"In a country where the proportion of citizens aged over 65 has doubled in twenty years, pharmacies report booming sales of joint-support supplements, hearing aids, and step-free holiday packages. Which factor is driving these spending changes?","options":{"A":"Falling average life expectancy across all cities","B":"A sudden collapse in national internet access","C":"Government bans on youth clothing stores","D":"Demographic changes in the population age structure"},"correctOption":"D","correctAnswer":"Demographic changes in the population age structure","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because an aging population shifts aggregate consumer demand toward healthcare, accessibility, and senior leisure.","distractor_reasons":{"A":"Incorrect because longer life expectancy is what drives an aging demographic.","B":"Incorrect because internet access has expanded rather than collapsed.","C":"Incorrect because demand shifts reflect population demographics rather than bans.","D":"Option D is correct because an aging population shifts aggregate consumer demand toward healthcare, accessibility, and senior leisure."}}},{"id":"P1_U3_MCQ_382","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_382","question":"Eco-conscious shoppers increasingly reject single-use plastic detergent bottles in favour of concentrated soluble cleaning tablets shipped in compostable cardboard pouches. Which trend explains this shift?","options":{"A":"Consumers stopping washing their clothes altogether","B":"Growing environmental awareness influencing ethical purchasing choices","C":"A shortage of cardboard boxes worldwide","D":"Detergent tablets being legally required to cost five times more than liquid soap"},"correctOption":"B","correctAnswer":"Growing environmental awareness influencing ethical purchasing choices","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because sustainability values alter consumer preferences toward low-waste, recyclable packaging.","distractor_reasons":{"A":"Incorrect because laundry demand continues via more sustainable formats.","B":"Option B is correct because sustainability values alter consumer preferences toward low-waste, recyclable packaging.","C":"Incorrect because cardboard pouches are widely available.","D":"Incorrect because refill tablets are often competitively priced."}}},{"id":"P1_U3_MCQ_383","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_383","question":"With hybrid remote working becoming permanent in major cities, downtown sandwich shops see Monday and Friday footfall drop by 35%, while suburban cafés experience record weekday queues. What caused this spending shift?","options":{"A":"Changing work patterns altering where consumers spend money during the week","B":"City-centre restaurants banning office workers from entering","C":"Suburban cafés giving away all meals for free","D":"A total disappearance of commuter trains"},"correctOption":"A","correctAnswer":"Changing work patterns altering where consumers spend money during the week","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because working from home relocates daily lunch and coffee spending from business districts to residential suburbs.","distractor_reasons":{"A":"Option A is correct because working from home relocates daily lunch and coffee spending from business districts to residential suburbs.","B":"Incorrect because city cafés actively want weekday diners.","C":"Incorrect because suburban cafés charge commercial prices.","D":"Incorrect because trains still operate, just with fewer Friday/Monday commuters."}}},{"id":"P1_U3_MCQ_384","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_384","question":"A local stationery store in Malaysia used to compete only with shops on the same street, but now loses sales to overseas sellers offering free cross-border shipping on online marketplaces. Why has competition increased?","options":{"A":"International air freight has become completely free for all factories","B":"Local consumers stopped using pens and notebooks completely","C":"High-street stationery shops are legally barred from selling online","D":"Globalization and e-commerce platforms allow foreign sellers to reach domestic buyers directly"},"correctOption":"D","correctAnswer":"Globalization and e-commerce platforms allow foreign sellers to reach domestic buyers directly","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because digital marketplaces dismantle geographic barriers, exposing local retailers to global price and variety rivalry.","distractor_reasons":{"A":"Incorrect because sellers subsidize shipping within their pricing.","B":"Incorrect because stationery demand still exists, just captured by online rivals.","C":"Incorrect because local shops can also launch online stores.","D":"Option D is correct because digital marketplaces dismantle geographic barriers, exposing local retailers to global price and variety rivalry."}}},{"id":"P1_U3_MCQ_385","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_385","question":"In the smartphone accessories industry, rival factories copy newly released phone-case designs within three weeks and sell lookalikes online. Why does rapid technological imitation intensify competition?","options":{"A":"Consumers prefer phone cases that do not fit their phones","B":"Imitators always charge ten times more than original designers","C":"Product differentiation advantages are short-lived, forcing firms to innovate continuously or compete heavily on price","D":"Rapid imitation reduces the total number of sellers in the market"},"correctOption":"C","correctAnswer":"Product differentiation advantages are short-lived, forcing firms to innovate continuously or compete heavily on price","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because fast copying erodes first-mover uniqueness and increases the number of close substitutes.","distractor_reasons":{"A":"Incorrect because lookalikes match phone dimensions closely.","B":"Incorrect because copycat sellers typically undercut the original brand's price.","C":"Option C is correct because fast copying erodes first-mover uniqueness and increases the number of close substitutes.","D":"Incorrect because rapid entry increases seller numbers."}}},{"id":"P1_U3_MCQ_386","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_386","question":"To defend market share against cheaper imported washing machines, a domestic appliance manufacturer introduces a 7-year parts-and-labour warranty and next-day engineer home visits. How is it responding to competition?","options":{"A":"By lowering product build quality to match cheap imports","B":"By differentiating through superior after-sales service and reliability assurance rather than engaging in a destructive price war","C":"By reducing customer service phone hours to one hour per week","D":"By stopping all deliveries to appliance retailers"},"correctOption":"B","correctAnswer":"By differentiating through superior after-sales service and reliability assurance rather than engaging in a destructive price war","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because non-price differentiation reduces perceived buyer risk on major household appliances.","distractor_reasons":{"A":"Incorrect because a 7-year warranty requires high build quality.","B":"Option B is correct because non-price differentiation reduces perceived buyer risk on major household appliances.","C":"Incorrect because next-day support expands service availability.","D":"Incorrect because distribution continues normally."}}},{"id":"P1_U3_MCQ_387","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_387","question":"A craft kombucha brewery faces dozens of rival tea drinks in supermarkets, so it brews exclusively with wild-harvested botanical herbs in returnable apothecary glass bottles. What is the brewery creating?","options":{"A":"A clear Unique Selling Point (USP) that sets its brand apart on crowded shelves","B":"An undifferentiated mass-market commodity","C":"A product-oriented assembly line ignoring flavour trends","D":"A legal monopoly banning all other soft drinks"},"correctOption":"A","correctAnswer":"A clear Unique Selling Point (USP) that sets its brand apart on crowded shelves","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because distinctive ingredients and sustainable reusable bottles give buyers a compelling reason to choose the brand.","distractor_reasons":{"A":"Option A is correct because distinctive ingredients and sustainable reusable bottles give buyers a compelling reason to choose the brand.","B":"Incorrect because wild botanicals and returnable bottles strongly differentiate the product.","C":"Incorrect because eco-bottles and botanical flavours align with modern wellness trends.","D":"Incorrect because supermarkets continue stocking rival beverages."}}},{"id":"P1_U3_MCQ_388","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_388","question":"When saturation and fierce price discounting squeeze profits in its home market, a regional gym chain expands into smaller provincial towns that currently have no modern fitness clubs. Which competitive response is this?","options":{"A":"Closing all gyms and selling exercise equipment for scrap","B":"Doubling membership fees in its saturated home-city clubs","C":"Entering new, less-saturated geographic markets to capture untapped demand","D":"Switching from gyms to manufacturing agricultural tractors"},"correctOption":"C","correctAnswer":"Entering new, less-saturated geographic markets to capture untapped demand","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because geographic market development relieves competitive pressure by finding underserved locations.","distractor_reasons":{"A":"Incorrect because the chain is expanding rather than liquidating.","B":"Incorrect because raising fees in a saturated market would drive members to rivals.","C":"Option C is correct because geographic market development relieves competitive pressure by finding underserved locations.","D":"Incorrect because the firm remains in fitness services."}}},{"id":"P1_U3_MCQ_389","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_389","question":"A cutlery workshop designs ergonomically angled chef knives exclusively for left-handed professional cooks. Which market strategy is this?","options":{"A":"Niche marketing","B":"Mass marketing","C":"Undifferentiated commodity marketing","D":"Loss-leader supermarket marketing"},"correctOption":"A","correctAnswer":"Niche marketing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because left-handed chefs represent a small, specialized segment overlooked by mass-market knife producers.","distractor_reasons":{"A":"Option A is correct because left-handed chefs represent a small, specialized segment overlooked by mass-market knife producers.","B":"Incorrect because mass marketing produces standard right-handed knives for the majority.","C":"Incorrect because the knives are specifically engineered for left-handed ergonomics.","D":"Incorrect because specialist chef knives are premium tools rather than supermarket loss leaders."}}},{"id":"P1_U3_MCQ_390","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_390","question":"Why can a specialist maker of gluten-free, nut-free wedding cakes charge higher profit margins than a standard high-street bakery?","options":{"A":"Customers with severe food allergies face few safe alternatives and willingly pay a premium for trusted specialist expertise","B":"Allergen-free ingredients cost zero money to purchase","C":"High-street bakeries are legally banned from baking wedding cakes","D":"Specialist bakeries never pay kitchen electricity or staff wages"},"correctOption":"A","correctAnswer":"Customers with severe food allergies face few safe alternatives and willingly pay a premium for trusted specialist expertise","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because niche specialization solves a critical high-stakes need with minimal direct competition, supporting premium pricing.","distractor_reasons":{"A":"Option A is correct because niche specialization solves a critical high-stakes need with minimal direct competition, supporting premium pricing.","B":"Incorrect because certified allergen-free ingredients are actually costlier.","C":"Incorrect because standard bakeries make regular wedding cakes.","D":"Incorrect because normal overhead and labour costs still apply."}}},{"id":"P1_U3_MCQ_391","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_391","question":"A boutique watchmaker produces only 400 mechanical diving watches per year for deep-sea saturation divers. What cost disadvantage does this 'niche market' scale create compared with mass-market watch brands?","options":{"A":"Inability to achieve large technical and purchasing economies of scale, resulting in much higher unit production costs","B":"Excessive spending on global prime-time television commercials","C":"Too many millions of customers ordering watches every week","D":"Being forced to sell watches below raw steel cost"},"correctOption":"A","correctAnswer":"Inability to achieve large technical and purchasing economies of scale, resulting in much higher unit production costs","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because small batch sizes mean fixed tooling and engineering expenses are spread over very few units.","distractor_reasons":{"A":"Option A is correct because small batch sizes mean fixed tooling and engineering expenses are spread over very few units.","B":"Incorrect because niche firms rarely buy mass prime-time TV ads.","C":"Incorrect because total demand in a niche is small.","D":"Incorrect because niche watches are priced at a high premium."}}},{"id":"P1_U3_MCQ_392","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_392","question":"A battery manufacturer produces standardized AA alkaline batteries sold in identical packs across supermarkets, petrol stations, and hardware stores nationwide. Which approach is this?","options":{"A":"Mass marketing","B":"Bespoke niche marketing","C":"Psychographic luxury targeting","D":"Geographic micro-segmentation"},"correctOption":"A","correctAnswer":"Mass marketing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because standard AA batteries appeal to the broadest possible consumer base with one uniform product.","distractor_reasons":{"A":"Option A is correct because standard AA batteries appeal to the broadest possible consumer base with one uniform product.","B":"Incorrect because AA batteries serve universal everyday household demand.","C":"Incorrect because batteries are functional staples rather than luxury lifestyle goods.","D":"Incorrect because identical packs are sold everywhere."}}},{"id":"P1_U3_MCQ_393","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_393","question":"What is a major financial advantage for a household-soap company operating successfully in a large 'mass market'?","options":{"A":"Every consumer pays a custom negotiated luxury price","B":"Zero rival soap brands are allowed to enter supermarkets","C":"Mass-market soap requires no brand advertising or packaging","D":"High total sales volumes enable automated flow production, bulk raw-material discounts, and huge total revenue potential"},"correctOption":"D","correctAnswer":"High total sales volumes enable automated flow production, bulk raw-material discounts, and huge total revenue potential","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because serving the whole market maximizes output volume, driving down average unit costs while generating massive revenue.","distractor_reasons":{"A":"Incorrect because mass-market goods carry standardized retail prices.","B":"Incorrect because mass markets are fiercely competitive.","C":"Incorrect because mass brands invest heavily in packaging and advertising.","D":"Option D is correct because serving the whole market maximizes output volume, driving down average unit costs while generating massive revenue."}}},{"id":"P1_U3_MCQ_394","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_394","question":"A mass-market manufacturer of sugary carbonated colas invests $500 million in single-purpose bottling plants, only for mainstream consumer tastes to shift rapidly toward sparkling mineral water. What vulnerability of 'mass marketing' is exposed?","options":{"A":"Mass-market firms never face changes in consumer preferences","B":"Mass-market bottling machines can switch recipes at zero cost overnight","C":"Sparkling water is a tiny niche bought by fewer than 100 people","D":"Heavy fixed capital investment in standardized mass production makes it costly and slow to adapt when mainstream consumer fashions shift"},"correctOption":"D","correctAnswer":"Heavy fixed capital investment in standardized mass production makes it costly and slow to adapt when mainstream consumer fashions shift","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because specialized high-volume facilities create rigidity when broad market tastes evolve.","distractor_reasons":{"A":"Incorrect because health and lifestyle trends frequently reshape mass markets.","B":"Incorrect because retooling high-speed lines and rebranding involves major cost.","C":"Incorrect because bottled sparkling water is itself a huge mainstream category.","D":"Option D is correct because specialized high-volume facilities create rigidity when broad market tastes evolve."}}},{"id":"P1_U3_MCQ_395","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_395","question":"On the exact same flight, an airline sells 'Basic Economy' seats with no checked bag for $90, 'Flexible Economy' seats for $160, and 'Lie-Flat Business Class' pods for $950. Why does the airline segment passengers this way?","options":{"A":"Segmentation reduces the total number of passengers flying each year","B":"Airlines are legally forbidden from selling identical seats at different prices","C":"Lie-flat pods cost less to install than standard economy seats","D":"Different passengers value flexibility and comfort differently; segmentation captures maximum revenue from each willingness-to-pay group"},"correctOption":"D","correctAnswer":"Different passengers value flexibility and comfort differently; segmentation captures maximum revenue from each willingness-to-pay group","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because matching service tiers to distinct traveller budgets fills the aircraft while maximizing total flight yield.","distractor_reasons":{"A":"Incorrect because budget fares attract price-sensitive flyers who otherwise wouldn't travel.","B":"Incorrect because tiered fare classes are standard airline practice.","C":"Incorrect because business pods occupy much more cabin floor space.","D":"Option D is correct because matching service tiers to distinct traveller budgets fills the aircraft while maximizing total flight yield."}}},{"id":"P1_U3_MCQ_396","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_396","question":"A fashion retailer launches a tailored wool suit collection for female corporate executives alongside an affordable unisex fleece loungewear line for university students. Which segmentation variables are combined?","options":{"A":"Gender, occupation/life stage, and income","B":"Climatic zone and postal code only","C":"Undifferentiated mass standardization","D":"Industrial B2B factory capacity"},"correctOption":"A","correctAnswer":"Gender, occupation/life stage, and income","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because buyer gender, professional vs student lifestyle, and disposable income define the two distinct collections.","distractor_reasons":{"A":"Option A is correct because buyer gender, professional vs student lifestyle, and disposable income define the two distinct collections.","B":"Incorrect because both collections sell across the same cities.","C":"Incorrect because two distinct lines serve two separate buyer groups.","D":"Incorrect because both lines target individual retail consumers."}}},{"id":"P1_U3_MCQ_397","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_397","question":"An automotive brand promotes heavy-duty four-wheel-drive pickup trucks in rural farming provinces with unpaved roads, while advertising ultra-compact electric city cars in congested megacities. Which segmentation basis is applied?","options":{"A":"Age-only segmentation","B":"Gender segmentation","C":"Geographic segmentation (urban vs rural environment and infrastructure)","D":"Religious dietary segmentation"},"correctOption":"C","correctAnswer":"Geographic segmentation (urban vs rural environment and infrastructure)","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because road conditions, parking density, and local geography determine vehicle suitability.","distractor_reasons":{"A":"Incorrect because location rather than driver age explains the vehicle split.","B":"Incorrect because both men and women drive pickups in rural areas and city cars in megacities.","C":"Option C is correct because road conditions, parking density, and local geography determine vehicle suitability.","D":"Incorrect because religion does not dictate road infrastructure."}}},{"id":"P1_U3_MCQ_398","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_398","question":"A commercial bank offers zero-fee mobile checking accounts with small overdrafts for college students, while providing dedicated private wealth advisors and airport lounge passes for clients holding over $500,000 in savings. Which segmentation variable separates these products?","options":{"A":"Product-oriented mass production","B":"Customer gender","C":"Climatic weather zone","D":"Income and wealth (socio-economic status)"},"correctOption":"D","correctAnswer":"Income and wealth (socio-economic status)","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because financial asset levels and earning power dictate banking needs and fee structures.","distractor_reasons":{"A":"Incorrect because services are tailored to client wealth brackets.","B":"Incorrect because both accounts serve all genders.","C":"Incorrect because weather climate has no bearing on bank account tiers.","D":"Option D is correct because financial asset levels and earning power dictate banking needs and fee structures."}}},{"id":"P1_U3_MCQ_399","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_399","question":"An outdoor brand sells ultralight titanium stoves and minimalist bivouac tents marketed around 'leave-no-trace wilderness self-reliance' for solo mountain trekkers. Which segmentation approach is used?","options":{"A":"Psychographic segmentation (lifestyle, hobbies, and personal values)","B":"Postal code segmentation","C":"Gender-only segmentation","D":"Undifferentiated commodity marketing"},"correctOption":"A","correctAnswer":"Psychographic segmentation (lifestyle, hobbies, and personal values)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because shared outdoor passion and minimalist environmental values unite trekkers across different ages and regions.","distractor_reasons":{"A":"Option A is correct because shared outdoor passion and minimalist environmental values unite trekkers across different ages and regions.","B":"Incorrect because trekkers live in many postcodes and travel to mountains.","C":"Incorrect because solo trekkers include all genders.","D":"Incorrect because ultralight titanium gear is highly specialized."}}},{"id":"P1_U3_MCQ_400","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_400","question":"A smartphone maker launches a $699 'Lite' phone with nearly identical camera and screen specs to its $999 'Pro' model, causing existing 'Pro' buyers to downgrade to the cheaper model. What segmentation pitfall occurred?","options":{"A":"The firm spent too much on primary random sampling","B":"Poorly differentiated segments led to 'cannibalization', eroding revenue from higher-margin customers","C":"Consumers refused to buy any smartphones at all","D":"Unit manufacturing costs dropped to zero"},"correctOption":"B","correctAnswer":"Poorly differentiated segments led to 'cannibalization', eroding revenue from higher-margin customers","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because when tiered products lack clear separation, high-income buyers trade down, reducing overall profit margins.","distractor_reasons":{"A":"Incorrect because the issue was overlapping product positioning rather than survey sampling.","B":"Option B is correct because when tiered products lack clear separation, high-income buyers trade down, reducing overall profit margins.","C":"Incorrect because customers still bought the 'Lite' phone.","D":"Incorrect because hardware manufacturing costs remained substantial."}}},{"id":"P1_U3_MCQ_401","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_401","question":"An artisanal glassblowing studio spends months crafting heavy, ornate crystal fruit bowls because the founder admires classical sculpture, without checking whether modern apartment dwellers want delicate hand-wash-only bowls. Sales are dismal. Why?","options":{"A":"Crystal bowls are legally prohibited from being sold in retail shops","B":"The studio conducted too many customer focus groups","C":"The studio is product-oriented, prioritizing the maker's artistic tastes over researched buyer preferences","D":"The studio used dynamic online surge pricing"},"correctOption":"C","correctAnswer":"The studio is product-oriented, prioritizing the maker's artistic tastes over researched buyer preferences","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because product-oriented firms build what they enjoy making rather than researching practical consumer demand.","distractor_reasons":{"A":"Incorrect because glassware is completely legal to sell.","B":"Incorrect because no customer research was performed.","C":"Option C is correct because product-oriented firms build what they enjoy making rather than researching practical consumer demand.","D":"Incorrect because lack of market fit—not dynamic pricing—caused low sales."}}},{"id":"P1_U3_MCQ_402","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_402","question":"After tracking rising customer requests for dairy-free lunches, a meal-kit company tests six plant-based recipes with subscribers and adds the top three to its weekly menu, boosting retention by 18%. Which orientation does this reflect?","options":{"A":"Market orientation","B":"Product orientation","C":"Production-led orientation","D":"Asset-stripping orientation"},"correctOption":"A","correctAnswer":"Market orientation","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because listening to customer feedback and testing solutions before rollout exemplifies market orientation.","distractor_reasons":{"A":"Option A is correct because listening to customer feedback and testing solutions before rollout exemplifies market orientation.","B":"Incorrect because recipes were driven by subscriber demand rather than chef ego.","C":"Incorrect because the focus was recipe relevance rather than sheer factory volume.","D":"Incorrect because asset-stripping refers to corporate restructuring."}}},{"id":"P1_U3_MCQ_403","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_403","question":"Before signing a five-year lease on a retail unit in a new city, a bubble-tea chain researches local footfall, competitor store density, and student spending power. How does this research help management?","options":{"A":"It legally prevents rival bubble-tea shops from opening nearby","B":"It eliminates the need to pay rent or staff wages once the shop opens","C":"It reduces the financial risk of committing to a costly long-term lease in an unprofitable location","D":"It guarantees that 100% of passers-by will buy two drinks daily"},"correctOption":"C","correctAnswer":"It reduces the financial risk of committing to a costly long-term lease in an unprofitable location","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because evaluating demand and competition beforehand prevents expensive sunk-cost location mistakes.","distractor_reasons":{"A":"Incorrect because competitors can still enter open retail areas.","B":"Incorrect because rent and wages remain ongoing operating expenses.","C":"Option C is correct because evaluating demand and competition beforehand prevents expensive sunk-cost location mistakes.","D":"Incorrect because research estimates likely conversion rather than guaranteeing 100% sales."}}},{"id":"P1_U3_MCQ_404","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_404","question":"Six months after launching an updated mobile banking app, a bank surveys users to measure satisfaction with the new bill-splitting feature and identify bugs. Why is ongoing post-launch market research important?","options":{"A":"It tracks whether the product is meeting customer expectations in real use and highlights improvements needed to prevent customer churn","B":"Market research is only allowed before a product is launched","C":"Post-launch surveys automatically double customer bank balances","D":"Ongoing research replaces the need for software engineers"},"correctOption":"A","correctAnswer":"It tracks whether the product is meeting customer expectations in real use and highlights improvements needed to prevent customer churn","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because continuous feedback helps businesses refine existing offerings and sustain competitiveness.","distractor_reasons":{"A":"Option A is correct because continuous feedback helps businesses refine existing offerings and sustain competitiveness.","B":"Incorrect because research is valuable throughout the entire Product Life Cycle.","C":"Incorrect because surveys collect feedback rather than altering account balances.","D":"Incorrect because engineers are still required to fix issues uncovered."}}},{"id":"P1_U3_MCQ_405","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_405","question":"A health-club chain distributes a questionnaire to 800 members asking whether they would pay $10 extra per month for an infrared sauna or a dedicated indoor cycling studio. Why is 'primary research' needed here?","options":{"A":"No published external report can reveal what this specific club's own members prefer and are willing to pay","B":"Primary research is always cheaper than reading free online statistics","C":"Primary research requires zero questionnaire design effort","D":"Secondary data is illegal to use in the fitness industry"},"correctOption":"A","correctAnswer":"No published external report can reveal what this specific club's own members prefer and are willing to pay","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because bespoke pricing and facility trade-offs for a specific customer base require fresh, tailored primary data.","distractor_reasons":{"A":"Option A is correct because bespoke pricing and facility trade-offs for a specific customer base require fresh, tailored primary data.","B":"Incorrect because primary research is more expensive than free secondary sources.","C":"Incorrect because designing clear questions requires careful planning.","D":"Incorrect because secondary fitness reports are widely used alongside primary surveys."}}},{"id":"P1_U3_MCQ_406","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_406","question":"A fashion startup spends five months commissioning bespoke primary interviews and street surveys before launching a summer sandal collection, by which time summer has ended and rivals have already captured the market. Which drawback of primary research occurred?","options":{"A":"Primary research data is always outdated before it is collected","B":"Time-consuming data collection delayed product launch, causing the firm to miss a seasonal window","C":"Street surveys cannot be used for clothing or footwear","D":"Primary research costs zero money to conduct"},"correctOption":"B","correctAnswer":"Time-consuming data collection delayed product launch, causing the firm to miss a seasonal window","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because designing, fielding, and analyzing primary research takes time that can erode speed-to-market in fast-moving trends.","distractor_reasons":{"A":"Incorrect because primary data is up-to-date when collected, though slow collection can miss deadlines.","B":"Option B is correct because designing, fielding, and analyzing primary research takes time that can erode speed-to-market in fast-moving trends.","C":"Incorrect because apparel firms frequently survey shoppers.","D":"Incorrect because primary research is relatively costly."}}},{"id":"P1_U3_MCQ_407","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_407","question":"A juice company includes this in a customer survey: 'Don't you agree that our refreshing mango juice tastes better than any rival's?' What is the main problem with this question?","options":{"A":"It is a leading question that biases respondents","B":"It relies on secondary research data","C":"It is a closed question with fixed answer choices","D":"It uses a random sample of customers"},"correctOption":"A","correctAnswer":"It is a leading question that biases respondents","questionType":"MCQ","explanation":{"correct_reason":"The wording pushes respondents to agree with the company, making it a leading question that produces biased results rather than honest opinions.","distractor_reasons":{"A":"The phrasing leads respondents to agree, so it is a leading, biased question.","B":"The flaw is the wording of the question, not whether the data is primary or secondary.","C":"A closed question offers fixed answers, which is not the problem here; the bias comes from the wording.","D":"Using a random sample is good practice and is not the issue with this question."}}},{"id":"P1_U3_MCQ_408","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_408","question":"During a pilot study of 30 commuters, a bicycle manufacturer includes the open-ended question: 'What frustrates you most about folding your bike on crowded trains?' Why is an open question useful at this exploratory stage?","options":{"A":"It lets commuters describe unexpected practical issues in their own words rather than restricting them to pre-guessed tick boxes","B":"Open-ended essays can be turned into pie charts instantaneously without reading them","C":"Open questions guarantee a 100% completion rate on long surveys","D":"Open questions eliminate all interviewer bias"},"correctOption":"A","correctAnswer":"It lets commuters describe unexpected practical issues in their own words rather than restricting them to pre-guessed tick boxes","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because open questions uncover rich, unanticipated insights during early exploratory research.","distractor_reasons":{"A":"Option A is correct because open questions uncover rich, unanticipated insights during early exploratory research.","B":"Incorrect because open responses take substantial time to read and categorize.","C":"Incorrect because typing long answers often lowers completion rates.","D":"Incorrect because interpreting free-text answers can still involve researcher subjectivity."}}},{"id":"P1_U3_MCQ_409","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_409","question":"A broadband provider conducts 'telephone interviews' to ask households about internet speeds. What is a common disadvantage of telephone surveys compared with face-to-face interviews?","options":{"A":"Many people hang up immediately suspecting a sales call, and interviewers cannot show visual product prototypes or packaging","B":"Telephone calls are slower and more expensive than flying interviewers to every town","C":"Interviewers cannot clarify confusing questions during a live phone call","D":"Telephone interviews are illegal in telecommunications markets"},"correctOption":"A","correctAnswer":"Many people hang up immediately suspecting a sales call, and interviewers cannot show visual product prototypes or packaging","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cold-call skepticism causes high refusal rates and prevents showing physical mock-ups.","distractor_reasons":{"A":"Option A is correct because cold-call skepticism causes high refusal rates and prevents showing physical mock-ups.","B":"Incorrect because phone interviews are faster and cheaper than travel-heavy face-to-face interviews.","C":"Incorrect because live interviewers can explain questions over the phone.","D":"Incorrect because compliant phone research is lawful."}}},{"id":"P1_U3_MCQ_410","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_410","question":"A retirement-village developer distributes its housing preference survey exclusively via a QR code posted on a social-media gaming forum. Why is this 'online survey' sample flawed?","options":{"A":"QR codes cannot be scanned by modern smartphones","B":"Online surveys are always the most expensive research method","C":"Online surveys take six months to tabulate numerical results","D":"Sampling bias: elderly retirees are heavily under-represented on gaming forums, making the findings unrepresentative of the target market"},"correctOption":"D","correctAnswer":"Sampling bias: elderly retirees are heavily under-represented on gaming forums, making the findings unrepresentative of the target market","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because an online channel must reach the actual target demographic; gaming forums skew young.","distractor_reasons":{"A":"Incorrect because smartphones scan QR codes easily; the flaw is the audience channel.","B":"Incorrect because online surveys are fast and low-cost.","C":"Incorrect because digital forms tabulate data automatically in real time.","D":"Option D is correct because an online channel must reach the actual target demographic; gaming forums skew young."}}},{"id":"P1_U3_MCQ_411","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_411","question":"A cereal company runs two 'focus groups' of 8 parents each, and 12 of the 16 parents say they love a broccoli-flavoured breakfast cereal. Why would launching nationally based solely on this result be risky?","options":{"A":"Broccoli cereal is illegal to sell in supermarkets","B":"Focus groups are secondary research collected from government census books","C":"Focus groups never allow participants to taste sample products","D":"A tiny qualitative sample of 16 people is not statistically representative of millions of national households"},"correctOption":"D","correctAnswer":"A tiny qualitative sample of 16 people is not statistically representative of millions of national households","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because focus groups provide deep qualitative reactions but lack the sample size needed for reliable demand forecasting.","distractor_reasons":{"A":"Incorrect because the risk is commercial demand uncertainty, not legality.","B":"Incorrect because focus groups are primary qualitative research.","C":"Incorrect because product tasting is common in focus groups.","D":"Option D is correct because focus groups provide deep qualitative reactions but lack the sample size needed for reliable demand forecasting."}}},{"id":"P1_U3_MCQ_412","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_412","question":"In a focus group testing a new sports-car advert, one loud participant mocks the advert's music, causing quieter group members to stay silent or agree despite liking it. What limitation of focus groups occurred?","options":{"A":"Excessively large sample size causing computer crashes","B":"Secondary data obsolescence","C":"Peer pressure and dominant individuals distorting genuine individual opinions ('groupthink')","D":"Postal mail delivery delays"},"correctOption":"C","correctAnswer":"Peer pressure and dominant individuals distorting genuine individual opinions ('groupthink')","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because social conformity in group settings can suppress minority viewpoints unless skillfully moderated.","distractor_reasons":{"A":"Incorrect because focus groups involve small groups of 6–12 people.","B":"Incorrect because focus groups generate live primary insights.","C":"Option C is correct because social conformity in group settings can suppress minority viewpoints unless skillfully moderated.","D":"Incorrect because focus groups take place live rather than by mail."}}},{"id":"P1_U3_MCQ_413","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_413","question":"A supermarket records which organic products shoppers pick by watching them in-store. The manager worries that shoppers may behave differently because they know they are being observed. What is this problem an example of?","options":{"A":"People altering their behaviour because they are aware of being studied","B":"Sampling error caused by using too small a group of shoppers","C":"A correctly designed random sample of customers","D":"Using secondary data instead of first-hand research"},"correctOption":"A","correctAnswer":"People altering their behaviour because they are aware of being studied","questionType":"MCQ","explanation":{"correct_reason":"When being watched changes what people do, the observed behaviour is distorted, undermining the validity of the research findings.","distractor_reasons":{"B":"Sampling error concerns how many people are observed, not the way awareness of observation changes their conduct.","C":"A random sample concerns selection chances and does not address the distortion caused by shoppers knowing they are watched.","D":"Watching shoppers first-hand is primary research, so the problem is not the use of secondary data.","A":"When being watched changes what people do, the observed behaviour is distorted, undermining the validity of the research findings."}}},{"id":"P1_U3_MCQ_414","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_414","question":"While a beverage company runs a six-week regional 'test market' for a new energy drink in one city, its biggest rival secretly floods that same city with 'Half-Price' coupons to ruin the trial sales figures. What risk of test marketing does this show?","options":{"A":"Test marketing is illegal in grocery retail chains","B":"Test marketing costs more than launching immediately across 50 countries","C":"Test marketing alerts competitors to the new product early, allowing rivals to imitate it or distort trial results","D":"Test marketing never uses real paying customers"},"correctOption":"C","correctAnswer":"Test marketing alerts competitors to the new product early, allowing rivals to imitate it or distort trial results","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because regional trials expose commercial plans publicly before national rollout.","distractor_reasons":{"A":"Incorrect because test marketing is lawful.","B":"Incorrect because regional testing costs far less than a full-scale launch.","C":"Option C is correct because regional trials expose commercial plans publicly before national rollout.","D":"Incorrect because test marketing measures actual purchases by real shoppers."}}},{"id":"P1_U3_MCQ_415","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_415","question":"Before developing a new loyalty tier, a supermarket analyzes two years of its own till-receipt scanner records and customer loyalty-card purchase histories. Which type of data is being used?","options":{"A":"Primary focus-group data","B":"External government census data","C":"Internal secondary data","D":"External competitor press releases"},"correctOption":"C","correctAnswer":"Internal secondary data","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because historical transaction data already stored inside the firm's own systems is internal secondary data.","distractor_reasons":{"A":"Incorrect because no new group discussions were held.","B":"Incorrect because the data came from the supermarket's own tills rather than a government agency.","C":"Option C is correct because historical transaction data already stored inside the firm's own systems is internal secondary data.","D":"Incorrect because the records are internal company files."}}},{"id":"P1_U3_MCQ_416","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_416","question":"A baby-stroller manufacturer downloads free official national birth-rate projections and household income tables from the government statistics office. Which research source is this?","options":{"A":"Internal company accounting records","B":"External secondary research","C":"Primary quota street interviews","D":"Primary test marketing"},"correctOption":"B","correctAnswer":"External secondary research","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because publicly available demographic data compiled by government bodies is external secondary research.","distractor_reasons":{"A":"Incorrect because the data was published by the government rather than internal sales ledgers.","B":"Option B is correct because publicly available demographic data compiled by government bodies is external secondary research.","C":"Incorrect because no new interviews were conducted.","D":"Incorrect because no trial product launch occurred."}}},{"id":"P1_U3_MCQ_417","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_417","question":"An automotive components supplier reads quarterly reports published by the National Motor Manufacturers' Trade Association to estimate annual electric-vehicle production growth. Why is this external secondary source helpful?","options":{"A":"Trade association reports contain confidential prototypes of rival suppliers","B":"Trade associations aggregate sector-wide production forecasts quickly and affordably for member businesses","C":"Trade association reports eliminate the need to negotiate contracts with carmakers","D":"Primary research is illegal in automotive manufacturing"},"correctOption":"B","correctAnswer":"Trade associations aggregate sector-wide production forecasts quickly and affordably for member businesses","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because industry bodies compile reliable macro-level sector data that individual SMEs could not gather independently.","distractor_reasons":{"A":"Incorrect because trade reports publish aggregate industry trends rather than rival trade secrets.","B":"Option B is correct because industry bodies compile reliable macro-level sector data that individual SMEs could not gather independently.","C":"Incorrect because B2B sales negotiations remain essential.","D":"Incorrect because primary customer research is lawful and common."}}},{"id":"P1_U3_MCQ_418","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_418","question":"An entrepreneur uses a free 2019 commercial real-estate report to pick a city-centre café site in 2026, ignoring how hybrid remote work reshaped office occupancy since then. Which weakness of 'secondary research' caused this mistake?","options":{"A":"Government and industry reports are legally forbidden from being read by startups","B":"Secondary data is always more expensive than hiring 50 street interviewers","C":"Secondary reports never include numerical statistics","D":"Secondary data can become outdated quickly in fast-changing markets, leading to flawed decisions"},"correctOption":"D","correctAnswer":"Secondary data can become outdated quickly in fast-changing markets, leading to flawed decisions","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because historical secondary reports may no longer reflect current consumer habits or market conditions.","distractor_reasons":{"A":"Incorrect because published reports are openly accessible.","B":"Incorrect because free secondary reports are far cheaper than primary fieldwork.","C":"Incorrect because secondary reports contain extensive quantitative tables.","D":"Option D is correct because historical secondary reports may no longer reflect current consumer habits or market conditions."}}},{"id":"P1_U3_MCQ_419","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_419","question":"Which of the following findings from a hotel guest study represents 'qualitative data' rather than 'quantitative data'?","options":{"A":"Guests explained in interviews that dim hallway lighting made the corridor feel unsafe at night","B":"78% of surveyed guests rated room cleanliness 5 out of 5","C":"Average guest length of stay increased from 2.1 nights to 2.6 nights","D":"Room-service revenue rose by $14,500 in the third quarter"},"correctOption":"A","correctAnswer":"Guests explained in interviews that dim hallway lighting made the corridor feel unsafe at night","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because descriptive emotional feelings and perceptions about lighting safety represent non-numerical qualitative insight.","distractor_reasons":{"A":"Option A is correct because descriptive emotional feelings and perceptions about lighting safety represent non-numerical qualitative insight.","B":"Incorrect because 78% and 5-point scores are numerical quantitative metrics.","C":"Incorrect because night counts are quantitative figures.","D":"Incorrect because dollar revenue is quantitative data."}}},{"id":"P1_U3_MCQ_420","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_420","question":"A national telecom company has 8 million mobile subscribers and wants to test reactions to a new family data plan. Why does it survey a sample of 1,500 subscribers rather than all 8 million?","options":{"A":"Smaller samples are always 100% free of any statistical margin of error","B":"It is illegal to contact more than 2,000 customers in a survey","C":"Surveying 8 million people would be prohibitively expensive and take too long, whereas a well-chosen sample gives accurate results quickly","D":"Telecom companies do not have phone numbers for their own subscribers"},"correctOption":"C","correctAnswer":"Surveying 8 million people would be prohibitively expensive and take too long, whereas a well-chosen sample gives accurate results quickly","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because sampling balances statistical reliability against practical time and budget constraints.","distractor_reasons":{"A":"Incorrect because every sample carries some margin of sampling error.","B":"Incorrect because no legal cap restricts survey size.","C":"Option C is correct because sampling balances statistical reliability against practical time and budget constraints.","D":"Incorrect because telecom firms hold subscriber billing records."}}},{"id":"P1_U3_MCQ_421","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_421","question":"A street-food vendor wants to use 'random sampling' to survey everyone who eats lunch in a busy public square, but has no list of visitors and passers-by hurry past refusing to stop. Why is pure random sampling impractical here?","options":{"A":"True random sampling requires a complete sampling frame (list of the entire population) and high cooperation from selected individuals","B":"Random sampling can only be used with open-ended essay questions","C":"Random sampling is forbidden in food and hospitality businesses","D":"Random sampling requires interviewing every person in the country"},"correctOption":"A","correctAnswer":"True random sampling requires a complete sampling frame (list of the entire population) and high cooperation from selected individuals","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because without a master list of anonymous square visitors, every individual cannot be assigned an equal selection probability.","distractor_reasons":{"A":"Option A is correct because without a master list of anonymous square visitors, every individual cannot be assigned an equal selection probability.","B":"Incorrect because random sampling works with closed and open questionnaires.","C":"Incorrect because food businesses can use random sampling when customer lists exist.","D":"Incorrect because interviewing everyone is a census rather than a sample."}}},{"id":"P1_U3_MCQ_422","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_422","question":"A shopping mall's visitor profile is 60% female and 40% male. If a market-research team uses 'quota sampling' to interview 300 shoppers, how many female and male shoppers must they interview?","options":{"A":"150 female and 150 male","B":"180 female and 120 male","C":"120 female and 180 male","D":"60 female and 40 male"},"correctOption":"B","correctAnswer":"180 female and 120 male","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because 60% of 300 = 180 female respondents, and 40% of 300 = 120 male respondents.","distractor_reasons":{"A":"Incorrect because 150/150 splits 50/50 instead of matching the 60/40 mall gender ratio.","B":"Option B is correct because 60% of 300 = 180 female respondents, and 40% of 300 = 120 male respondents.","C":"Incorrect because 120/180 reverses the female and male quotas.","D":"Incorrect because 60 + 40 equals only 100 respondents rather than 300."}}},{"id":"P1_U3_MCQ_423","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_423","question":"To estimate national demand for a $40 budget toaster, a researcher interviews 400 shoppers outside an ultra-luxury designer boutique district on a Tuesday morning. Why will the data be inaccurate?","options":{"A":"Location and time sampling bias: wealthy weekday boutique shoppers do not reflect the income or habits of average national toaster buyers","B":"400 interviews is too large a sample for a household appliance","C":"Budget toasters are secondary research products","D":"Shoppers outside luxury boutiques never own kitchen appliances"},"correctOption":"A","correctAnswer":"Location and time sampling bias: wealthy weekday boutique shoppers do not reflect the income or habits of average national toaster buyers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because surveying in an unrepresentative affluent district on a workday skews results away from mainstream buyers.","distractor_reasons":{"A":"Option A is correct because surveying in an unrepresentative affluent district on a workday skews results away from mainstream buyers.","B":"Incorrect because 400 is a reasonable sample size if properly representative.","C":"Incorrect because toasters are physical consumer goods.","D":"Incorrect because the issue is unrepresentative income/lifestyle bias rather than zero ownership."}}},{"id":"P1_U3_MCQ_424","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_424","question":"In face-to-face street interviews, respondents claim they eat fast food 'less than once a month' and read 'four books a month', contradicting actual local fast-food sales and library records. What caused this research inaccuracy?","options":{"A":"Social-desirability bias: respondents give answers that make them look healthier or more cultured rather than admitting actual habits","B":"Secondary census calculation error","C":"Excessive use of random number generators","D":"High postal stamp prices"},"correctOption":"A","correctAnswer":"Social-desirability bias: respondents give answers that make them look healthier or more cultured rather than admitting actual habits","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because people often under-report stigmatized habits and over-report virtuous ones in front of an interviewer.","distractor_reasons":{"A":"Option A is correct because people often under-report stigmatized habits and over-report virtuous ones in front of an interviewer.","B":"Incorrect because the distortion arose from live interview answers.","C":"Incorrect because random selection does not cause dishonest self-reporting.","D":"Incorrect because the interviews were face-to-face."}}},{"id":"P1_U3_MCQ_425","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_425","question":"A marketing analyst wants to present how monthly online ice-cream orders rose and fell across all 36 months over the past three years to highlight seasonal peaks. Which chart format is clearest?","options":{"A":"A line graph plotting monthly sales over time","B":"A single pie chart showing 36 tiny slices","C":"An unformatted text paragraph listing 36 numbers","D":"A Venn diagram of factory staff"},"correctOption":"A","correctAnswer":"A line graph plotting monthly sales over time","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because line graphs clearly reveal continuous trends, growth rates, and seasonal fluctuations across time.","distractor_reasons":{"A":"Option A is correct because line graphs clearly reveal continuous trends, growth rates, and seasonal fluctuations across time.","B":"Incorrect because a 36-slice pie chart is unreadable and hides chronological sequence.","C":"Incorrect because raw text numbers obscure visual seasonal waves.","D":"Incorrect because Venn diagrams show set overlaps rather than time series."}}},{"id":"P1_U3_MCQ_426","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_426","question":"An espresso-machine manufacturer sells compact pod coffee makers to households and heavy-duty three-group steam machines to commercial cafés. How are these two product lines classified?","options":{"A":"Both machines are intangible consumer services","B":"Household pod machines are consumer goods, whereas commercial café machines are producer (capital) goods","C":"Household pod machines are producer goods, whereas café machines are consumer goods","D":"Both machines are raw agricultural commodities"},"correctOption":"B","correctAnswer":"Household pod machines are consumer goods, whereas commercial café machines are producer (capital) goods","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because goods bought for personal household enjoyment are consumer goods, while equipment bought by businesses to produce services are producer goods.","distractor_reasons":{"A":"Incorrect because physical machines are tangible goods rather than services.","B":"Option B is correct because goods bought for personal household enjoyment are consumer goods, while equipment bought by businesses to produce services are producer goods.","C":"Incorrect because this reverses consumer and producer classifications.","D":"Incorrect because assembled appliances are manufactured goods."}}},{"id":"P1_U3_MCQ_427","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_427","question":"A cybersecurity consultancy provides 24/7 network-threat monitoring for hospitals and banks, while a mobile pet groomer washes dogs at families' homes. How do these offerings compare?","options":{"A":"Dog grooming is a producer service, whereas hospital cybersecurity is a consumer service","B":"Both businesses sell tangible durable goods","C":"Cybersecurity monitoring is a producer (B2B) service, whereas mobile dog grooming is a consumer service","D":"Neither business operates in the tertiary sector"},"correctOption":"C","correctAnswer":"Cybersecurity monitoring is a producer (B2B) service, whereas mobile dog grooming is a consumer service","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because services sold to organizations are producer services, while services sold to private households are consumer services.","distractor_reasons":{"A":"Incorrect because this reverses the business and household buyers.","B":"Incorrect because both deliver intangible service activities.","C":"Option C is correct because services sold to organizations are producer services, while services sold to private households are consumer services.","D":"Incorrect because both operate in the tertiary service sector."}}},{"id":"P1_U3_MCQ_428","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_428","question":"A toy company generates 40 new board-game concepts, then eliminates 32 ideas after estimating production costs, safety rules, and likely retail demand before building any prototypes. Which NPD stage is this?","options":{"A":"Full commercial national rollout","B":"Idea screening and business analysis","C":"Decline-stage product withdrawal","D":"Mature extension packaging redesign"},"correctOption":"B","correctAnswer":"Idea screening and business analysis","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because screening filters out unfeasible or unprofitable ideas early before expensive prototype engineering begins.","distractor_reasons":{"A":"Incorrect because commercial launch is the final stage after testing.","B":"Option B is correct because screening filters out unfeasible or unprofitable ideas early before expensive prototype engineering begins.","C":"Incorrect because decline applies to aging existing products.","D":"Incorrect because extension strategies revive mature products."}}},{"id":"P1_U3_MCQ_429","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_429","question":"What is the main financial risk for a medical-device firm investing heavily in 'new product development (NPD)'?","options":{"A":"New medical devices require no regulatory safety approval","B":"Successful new products are legally banned from earning a profit","C":"R&D spending reduces factory fixed overheads to zero","D":"Substantial R&D and clinical testing costs are incurred upfront with no guarantee the product will pass trials or achieve commercial sales"},"correctOption":"D","correctAnswer":"Substantial R&D and clinical testing costs are incurred upfront with no guarantee the product will pass trials or achieve commercial sales","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because R&D outlays represent sunk costs that may never be recovered if technical or market failure occurs.","distractor_reasons":{"A":"Incorrect because medical devices face strict regulatory approval.","B":"Incorrect because successful innovations earn strong patent-protected profits.","C":"Incorrect because R&D adds significant development costs.","D":"Option D is correct because R&D outlays represent sunk costs that may never be recovered if technical or market failure occurs."}}},{"id":"P1_U3_MCQ_430","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_430","question":"A sportswear company launches a new running shoe by placing adverts featuring famous athletes and giving away free samples at athletics events. Which element of the marketing mix is the company mainly using here?","options":{"A":"Product","B":"Promotion","C":"Place","D":"Price"},"correctOption":"B","correctAnswer":"Promotion","questionType":"MCQ","explanation":{"correct_reason":"Advertising and free samples are activities used to communicate with and persuade customers, which is the promotion element of the marketing mix.","distractor_reasons":{"A":"Product refers to the design, features and quality of the shoe itself, not the adverts used to publicise it.","B":"Advertising and free samples are promotional activities, so promotion is the correct element.","C":"Place concerns how the shoe is distributed and made available to customers, not how it is advertised.","D":"Price is the amount customers pay, which is not what the advertising and sampling describe."}}},{"id":"P1_U3_MCQ_431","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_431","question":"Why do major supermarket chains willingly allocate prime eye-level shelf space to a leading global tomato-ketchup brand even though the brand offers lower wholesale discounts than unknown rivals?","options":{"A":"Strong consumer brand loyalty pulls shoppers into the store, and shoppers might switch supermarkets if the flagship ketchup is missing","B":"Ketchup manufacturers own all supermarket buildings","C":"Unknown ketchup brands taste identical and cost zero to stock","D":"Supermarkets are legally forced to put famous brands at eye level"},"correctOption":"A","correctAnswer":"Strong consumer brand loyalty pulls shoppers into the store, and shoppers might switch supermarkets if the flagship ketchup is missing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because 'must-stock' brand equity gives manufacturers stronger bargaining power with retailers.","distractor_reasons":{"A":"Option A is correct because 'must-stock' brand equity gives manufacturers stronger bargaining power with retailers.","B":"Incorrect because supermarkets are independent retail businesses.","C":"Incorrect because supermarkets maximize profit per metre of shelf space.","D":"Incorrect because shelf placement is a commercial negotiation."}}},{"id":"P1_U3_MCQ_432","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_432","question":"A frozen-meal box displays cooking microwave wattage times, calorie tables, allergy warnings, a recycling symbol, and a scannable barcode. Which function of 'packaging' does this fulfill?","options":{"A":"Preventing shoppers from knowing how to heat the meal","B":"Communicating essential consumer usage, nutritional, legal, and retail inventory information","C":"Increasing shipping container fuel consumption","D":"Eliminating the need for frozen delivery trucks"},"correctOption":"B","correctAnswer":"Communicating essential consumer usage, nutritional, legal, and retail inventory information","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because packaging informs consumers safely while providing barcodes for retail checkout and stock control.","distractor_reasons":{"A":"Incorrect because heating instructions guide safe preparation.","B":"Option B is correct because packaging informs consumers safely while providing barcodes for retail checkout and stock control.","C":"Incorrect because printed labels do not inflate freight fuel.","D":"Incorrect because frozen foods still require cold-chain transport."}}},{"id":"P1_U3_MCQ_433","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_433","question":"A headphone manufacturer replaces non-recyclable foam-and-plastic blister packaging with sleek, 100% recycled molded-pulp boxes printed with soy ink. How does this packaging change benefit the brand?","options":{"A":"It guarantees that headphones will never break if dropped in water","B":"It appeals to environmentally conscious buyers, improves brand reputation, and prepares the firm for stricter single-use plastic laws","C":"It eliminates all factory assembly wages","D":"It prevents online stores from shipping headphones by courier"},"correctOption":"B","correctAnswer":"It appeals to environmentally conscious buyers, improves brand reputation, and prepares the firm for stricter single-use plastic laws","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because sustainable packaging strengthens ethical brand positioning and reduces regulatory compliance risk.","distractor_reasons":{"A":"Incorrect because outer retail packaging does not waterproof the headphones during use.","B":"Option B is correct because sustainable packaging strengthens ethical brand positioning and reduces regulatory compliance risk.","C":"Incorrect because assembly wages remain unchanged.","D":"Incorrect because molded pulp protects products well during courier transit."}}},{"id":"P1_U3_MCQ_434","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_434","question":"On a Product Life Cycle cash-flow chart, why does the cash-flow line dip deepest below zero just before the 'Introduction' stage begins?","options":{"A":"Heavy cumulative spending on R&D, prototype testing, factory tooling, and launch promotion occurs before any sales revenue is earned","B":"Customers are paid cash bonuses to return the product","C":"Sales volume reaches its all-time peak during R&D","D":"Competitors steal all factory machinery before launch"},"correctOption":"A","correctAnswer":"Heavy cumulative spending on R&D, prototype testing, factory tooling, and launch promotion occurs before any sales revenue is earned","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because upfront capital and development outflows peak right as commercial launch starts.","distractor_reasons":{"A":"Option A is correct because upfront capital and development outflows peak right as commercial launch starts.","B":"Incorrect because negative cash flow reflects R&D and launch expenses.","C":"Incorrect because sales revenue is zero during R&D.","D":"Incorrect because the cash outflow is planned investment."}}},{"id":"P1_U3_MCQ_435","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_435","question":"During the 'Introduction' stage of a new plant-based protein snack bar, why does the brand hand out free sample bars at commuter train stations alongside informative posters?","options":{"A":"Informative promotion is only used when 90% of households already buy the product","B":"The snack bar is already in the decline stage and being discontinued","C":"Free samples eliminate the need for supermarket distribution","D":"Consumers are unfamiliar with the new product's taste, so free trials overcome hesitation and build initial awareness"},"correctOption":"D","correctAnswer":"Consumers are unfamiliar with the new product's taste, so free trials overcome hesitation and build initial awareness","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because trial sampling and informative promotion educate early adopters and spark initial word-of-mouth.","distractor_reasons":{"A":"Incorrect because reminder ads—not launch education—suit saturated mature products.","B":"Incorrect because sampling launches a new product rather than closing an old one.","C":"Incorrect because sampling drives shoppers into supermarkets to buy full boxes.","D":"Option D is correct because trial sampling and informative promotion educate early adopters and spark initial word-of-mouth."}}},{"id":"P1_U3_MCQ_436","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_436","question":"As a robotic window-cleaner enters the 'Growth' stage of its Product Life Cycle, sales surge and three rival brands launch competing models. How should the firm adapt its promotion?","options":{"A":"Shift from purely explaining what the product does toward persuasive brand-preference advertising highlighting why its model is superior to rivals","B":"Stop all advertising completely because competitors have arrived","C":"Withdraw the robotic cleaner immediately before reaching maturity","D":"Cut distribution back to a single local hardware shop"},"correctOption":"A","correctAnswer":"Shift from purely explaining what the product does toward persuasive brand-preference advertising highlighting why its model is superior to rivals","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because once consumers understand the product category, persuasive promotion defends brand share against imitators.","distractor_reasons":{"A":"Option A is correct because once consumers understand the product category, persuasive promotion defends brand share against imitators.","B":"Incorrect because stopping promotion lets rivals capture the expanding market.","C":"Incorrect because growth is a profitable expansion phase.","D":"Incorrect because distribution should widen during growth."}}},{"id":"P1_U3_MCQ_437","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_437","question":"A leading brand of household dishwashing tablets is in the 'Maturity' stage, where almost every dishwasher owner already buys tablets and four strong rivals compete on supermarket shelves. Which pricing and promotion mix is typical?","options":{"A":"Competitive pricing paired with reminder advertising and occasional multi-buy promotions to retain loyal buyers","B":"Extreme price skimming at triple rival prices with zero advertising","C":"Introductory penetration pricing below raw chemical cost for ten years","D":"Purely technical B2B trade-journal adverts explaining how dishwashers work"},"correctOption":"A","correctAnswer":"Competitive pricing paired with reminder advertising and occasional multi-buy promotions to retain loyal buyers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because mature markets require competitive pricing and continuous brand reminders to prevent switching.","distractor_reasons":{"A":"Option A is correct because mature markets require competitive pricing and continuous brand reminders to prevent switching.","B":"Incorrect because skimming works only at initial innovative launch.","C":"Incorrect because selling below cost for years is financially unsustainable.","D":"Incorrect because households already know how dishwashing tablets work."}}},{"id":"P1_U3_MCQ_438","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_438","question":"A consumer-electronics firm still sells a legacy standalone GPS car-navigation unit whose sales fall 40% annually as drivers use free smartphone maps. Rather than spending on R&D or ads, the firm cuts marketing spend to zero and sells remaining stock at modest margins until demand vanishes. Which strategy is this?","options":{"A":"Introductory price skimming","B":"Launching a bold extension strategy","C":"Harvesting a declining product to extract remaining cash before final withdrawal","D":"Aggressive penetration pricing to capture 80% market share"},"correctOption":"C","correctAnswer":"Harvesting a declining product to extract remaining cash before final withdrawal","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because harvesting minimizes support costs on an irreversibly declining product to maximize short-term cash extraction.","distractor_reasons":{"A":"Incorrect because skimming applies to new launches.","B":"Incorrect because no product updates or promotional investments are being made.","C":"Option C is correct because harvesting minimizes support costs on an irreversibly declining product to maximize short-term cash extraction.","D":"Incorrect because investing to capture share in a dying category wastes capital."}}},{"id":"P1_U3_MCQ_439","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_439","question":"Sales of a traditional British malted hot drink have plateaued in the UK, so the manufacturer exports the drink to West African and Southeast Asian markets where rising middle-class demand creates rapid growth. Which 'extension strategy' is this?","options":{"A":"Entering new geographic markets to extend the product's overall life cycle","B":"Withdrawing the brand worldwide","C":"Switching to product-oriented factory closures","D":"Using predatory loss-leader pricing in UK supermarkets"},"correctOption":"A","correctAnswer":"Entering new geographic markets to extend the product's overall life cycle","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a product mature or declining in one country may be at the introduction/growth stage in overseas markets.","distractor_reasons":{"A":"Option A is correct because a product mature or declining in one country may be at the introduction/growth stage in overseas markets.","B":"Incorrect because the firm is expanding internationally rather than withdrawing.","C":"Incorrect because export growth increases factory utilization.","D":"Incorrect because the strategy focuses on overseas market development."}}},{"id":"P1_U3_MCQ_440","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_440","question":"A games console maker sells its console bundled with two popular games at one combined price lower than buying the items separately, to encourage sales. Which pricing method is being used?","options":{"A":"Cost-plus pricing","B":"Competitive pricing","C":"Promotional pricing","D":"Premium pricing"},"correctOption":"C","correctAnswer":"Promotional pricing","questionType":"MCQ","explanation":{"correct_reason":"Offering a special combined deal to stimulate sales is a short-term promotional pricing technique.","distractor_reasons":{"A":"Cost-plus pricing sets the price by adding a margin to production costs, not by bundling a special offer.","B":"Competitive pricing means matching or beating rivals' prices, which is not what a bundle offer does.","C":"Promotional pricing uses temporary offers such as bundles to attract buyers, so this is correct.","D":"Premium pricing sets a high price to suggest high quality, the opposite of a discounted bundle."}}},{"id":"P1_U3_MCQ_441","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_441","question":"A lamp factory has fixed costs of $40,000 per month, produces 10,000 lamps per month, and incurs variable costs of $6 per lamp. If it uses cost-plus pricing with a 25% mark-up, what is the selling price per lamp?","options":{"A":"$10.00","B":"$12.50","C":"$7.50","D":"$14.00"},"correctOption":"B","correctAnswer":"$12.50","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because Average Fixed Cost = $40,000 / 10,000 = $4.00; Total Unit Cost = $4.00 + $6.00 = $10.00; Selling Price = $10.00 × 1.25 = $12.50.","distractor_reasons":{"A":"Incorrect because $10.00 is the total unit cost before adding the 25% profit mark-up.","B":"Option B is correct because Average Fixed Cost = $40,000 / 10,000 = $4.00; Total Unit Cost = $4.00 + $6.00 = $10.00; Selling Price = $10.00 × 1.25 = $12.50.","C":"Incorrect because $7.50 adds 25% only to the $6.00 variable cost and omits fixed costs.","D":"Incorrect because $14.00 adds a 40% mark-up instead of 25%."}}},{"id":"P1_U3_MCQ_442","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_442","question":"A furniture maker calculates its unit cost at $180 and adds a rigid 50% cost-plus mark-up to price its dining chairs at $270, even though rival stores sell nearly identical chairs for $195. What is the main flaw of 'cost-plus pricing' shown here?","options":{"A":"Cost-plus pricing is mathematically impossible when fixed costs exist","B":"It ignores competitor prices and consumer willingness to pay, risking uncompetitive pricing if internal production costs are high","C":"Cost-plus pricing guarantees zero profit even when every chair sells","D":"Furniture retailers are legally banned from using cost-plus formulas"},"correctOption":"B","correctAnswer":"It ignores competitor prices and consumer willingness to pay, risking uncompetitive pricing if internal production costs are high","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because cost-plus pricing looks solely at internal expenses rather than external market demand and rivalry.","distractor_reasons":{"A":"Incorrect because fixed costs are allocated per unit to compute total unit cost.","B":"Option B is correct because cost-plus pricing looks solely at internal expenses rather than external market demand and rivalry.","C":"Incorrect because it guarantees a profit margin if units actually sell—the problem is low sales at an uncompetitive price.","D":"Incorrect because cost-plus is lawful and widely used."}}},{"id":"P1_U3_MCQ_443","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_443","question":"When three rival budget airlines match every $5 ticket cut on the same route using 'competitive pricing', fares fall below operating costs for all three carriers. What risk does strict competitive price-matching create?","options":{"A":"It can trigger a destructive price war that erodes industry-wide profit margins without increasing any single airline's market share","B":"Passengers stop flying when airfares become cheaper","C":"Jet fuel becomes completely free during airline price wars","D":"Competitive pricing guarantees a 50% net profit margin"},"correctOption":"A","correctAnswer":"It can trigger a destructive price war that erodes industry-wide profit margins without increasing any single airline's market share","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because when rivals match cuts immediately, no firm gains relative share while all firms earn less per ticket.","distractor_reasons":{"A":"Option A is correct because when rivals match cuts immediately, no firm gains relative share while all firms earn less per ticket.","B":"Incorrect because lower fares stimulate passenger volume, though at unprofitable margins.","C":"Incorrect because operating costs remain unchanged.","D":"Incorrect because price wars compress margins."}}},{"id":"P1_U3_MCQ_444","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_444","question":"A streaming-music startup launches at $2.99 per month using 'penetration pricing' to attract 500,000 subscribers, but when it raises the fee to $9.99 a year later, 60% of users cancel immediately. Which risk of penetration pricing occurred?","options":{"A":"Low launch prices attract bargain-hunters with weak brand loyalty who abandon the product once prices rise to profitable levels","B":"Penetration pricing sets launch prices too high for early adopters","C":"Streaming platforms pay zero music licensing royalties","D":"Penetration pricing is illegal in digital subscription businesses"},"correctOption":"A","correctAnswer":"Low launch prices attract bargain-hunters with weak brand loyalty who abandon the product once prices rise to profitable levels","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because buyers acquired purely on rock-bottom price often churn when normal pricing is introduced.","distractor_reasons":{"A":"Option A is correct because buyers acquired purely on rock-bottom price often churn when normal pricing is introduced.","B":"Incorrect because setting high initial prices describes price skimming.","C":"Incorrect because streaming firms pay significant royalties.","D":"Incorrect because introductory promotional pricing is lawful."}}},{"id":"P1_U3_MCQ_445","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_445","question":"A kitchen-gadget firm launches an unpatented electric avocado slicer at $89 using 'price skimming'. Within two months, six competitors launch identical slicers at $24, collapsing the pioneer's sales. Why did price skimming fail here?","options":{"A":"Lack of patent protection and low barriers to entry meant high initial profit margins rapidly attracted low-cost imitators","B":"Price skimming works best for basic unpatented commodities","C":"Consumers prefer paying $89 even when identical $24 alternatives exist","D":"Price skimming sets the initial price below variable manufacturing cost"},"correctOption":"A","correctAnswer":"Lack of patent protection and low barriers to entry meant high initial profit margins rapidly attracted low-cost imitators","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sustainable skimming requires strong intellectual property or technical barriers to delay copycats.","distractor_reasons":{"A":"Option A is correct because sustainable skimming requires strong intellectual property or technical barriers to delay copycats.","B":"Incorrect because commodities cannot sustain high skimming premiums.","C":"Incorrect because price-conscious buyers quickly switch to identical cheaper versions.","D":"Incorrect because skimming sets high prices well above unit cost."}}},{"id":"P1_U3_MCQ_446","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_446","question":"A supermarket sells fresh rotisserie chickens and cartons of milk below wholesale cost ('loss leaders') near the back of the store. How does this 'promotional pricing' tactic increase overall supermarket profit?","options":{"A":"Bargain staples draw shoppers into the store, where they walk past high-margin aisles and fill trolleys with profitable items","B":"Selling milk below cost generates a direct profit on every milk carton sold","C":"Suppliers pay supermarkets to throw away unsold chickens","D":"Shoppers are legally forced to spend at least $100 before leaving"},"correctOption":"A","correctAnswer":"Bargain staples draw shoppers into the store, where they walk past high-margin aisles and fill trolleys with profitable items","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because loss leaders drive store footfall so total basket margin outweighs the small loss on the promotional staple.","distractor_reasons":{"A":"Option A is correct because loss leaders drive store footfall so total basket margin outweighs the small loss on the promotional staple.","B":"Incorrect because a loss leader loses money on the individual item itself.","C":"Incorrect because the retailer absorbs the promotional discount.","D":"Incorrect because shoppers buy other items voluntarily out of convenience."}}},{"id":"P1_U3_MCQ_447","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_447","question":"A Swiss watchmaker prices its mechanical chronographs at $6,500 rather than $1,500 because affluent buyers associate the higher price with rarity, precision craftsmanship, and social prestige. Which pricing strategy is this?","options":{"A":"Predatory price cutting","B":"Penetration launch pricing","C":"Loss-leader clearance pricing","D":"Prestige / psychological pricing"},"correctOption":"D","correctAnswer":"Prestige / psychological pricing","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because psychological pricing uses price cues—either charm endings ($9.99) or luxury prestige figures ($6,500)—to shape perceived value.","distractor_reasons":{"A":"Incorrect because predatory pricing slashes prices below cost to bankrupt rivals.","B":"Incorrect because penetration pricing sets low entry prices.","C":"Incorrect because $6,500 is a high luxury price rather than a clearance discount.","D":"Option D is correct because psychological pricing uses price cues—either charm endings ($9.99) or luxury prestige figures ($6,500)—to shape perceived value."}}},{"id":"P1_U3_MCQ_448","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_448","question":"During a sudden torrential rainstorm, a ride-hailing app's algorithm automatically doubles trip fares ('dynamic pricing') to attract more drivers onto the roads, sparking angry social-media posts from stranded riders. What trade-off of dynamic pricing does this show?","options":{"A":"While dynamic pricing balances real-time supply and demand and maximizes peak revenue, sharp price spikes risk customer resentment and brand backlash","B":"Dynamic pricing keeps fares identical 24 hours a day regardless of weather","C":"Dynamic pricing eliminates the need for drivers or vehicles","D":"Surge fares always lose money for ride-hailing platforms"},"correctOption":"A","correctAnswer":"While dynamic pricing balances real-time supply and demand and maximizes peak revenue, sharp price spikes risk customer resentment and brand backlash","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because algorithmic surge pricing optimizes short-term market clearing but can feel exploitative during emergencies.","distractor_reasons":{"A":"Option A is correct because algorithmic surge pricing optimizes short-term market clearing but can feel exploitative during emergencies.","B":"Incorrect because dynamic pricing changes prices continuously with demand.","C":"Incorrect because higher fares incentivize human drivers to log on.","D":"Incorrect because higher fares boost per-trip commission revenue."}}},{"id":"P1_U3_MCQ_449","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_449","question":"A rail operator works out the average cost of providing a season-ticket journey and then adds a fixed percentage to decide the fare. Which pricing method is this?","options":{"A":"Competitive pricing","B":"Cost-plus pricing","C":"Promotional pricing","D":"Loss-leader pricing"},"correctOption":"B","correctAnswer":"Cost-plus pricing","questionType":"MCQ","explanation":{"correct_reason":"Adding a percentage mark-up to the cost of providing a service is the definition of cost-plus pricing.","distractor_reasons":{"A":"Competitive pricing sets fares relative to other rail firms, not by adding a margin to costs.","B":"Cost-plus pricing means adding a mark-up to costs, so this is the correct method.","C":"Promotional pricing involves temporary offers or discounts, not a cost-based mark-up.","D":"Loss-leader pricing sells below cost to attract customers, not adding a percentage to costs."}}},{"id":"P1_U3_MCQ_450","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_450","question":"A bottled-water producer wants its drinks stocked in supermarkets, petrol stations and vending machines nationwide so customers can buy them wherever they are. Which element of the marketing mix does this focus on?","options":{"A":"Product","B":"Price","C":"Promotion","D":"Place"},"correctOption":"D","correctAnswer":"Place","questionType":"MCQ","explanation":{"correct_reason":"Deciding where and how a product reaches customers is the place, or distribution, element of the marketing mix.","distractor_reasons":{"A":"Product concerns the drink's design, branding and packaging, not where it is sold.","B":"Price is the amount charged, not the outlets through which the drink is sold.","C":"Promotion is about communicating and advertising, not the distribution channels used.","D":"Place covers distribution and availability, so this is the correct element."}}},{"id":"P1_U3_MCQ_451","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_451","question":"A manufacturer of custom-engineered hydroelectric power turbines sells directly to national electricity utilities without using wholesalers or retail shops. Why is this 'zero-intermediary direct channel' essential?","options":{"A":"Supermarkets refuse to stock hydroelectric turbines due to shelf weight","B":"High-value B2B industrial equipment is built to bespoke engineering specifications and requires direct technical collaboration between producer and buyer","C":"Electricity utilities buy turbines on impulse every weekend","D":"Wholesalers are legally barred from buying industrial machinery"},"correctOption":"B","correctAnswer":"High-value B2B industrial equipment is built to bespoke engineering specifications and requires direct technical collaboration between producer and buyer","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because complex capital projects involve direct tendering, engineering customization, and installation support.","distractor_reasons":{"A":"Incorrect because consumer retail stores are irrelevant to power-station infrastructure.","B":"Option B is correct because complex capital projects involve direct tendering, engineering customization, and installation support.","C":"Incorrect because turbines are multi-million-dollar capital investments.","D":"Incorrect because the channel choice reflects technical complexity rather than legal bans."}}},{"id":"P1_U3_MCQ_452","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_452","question":"A producer of chilled fresh sushi boxes supplies refrigerated distribution depots of major supermarket chains directly (Producer -> Retailer -> Consumer). Why is a wholesaler omitted here?","options":{"A":"Sushi boxes can be stored unrefrigerated for six months","B":"Wholesalers charge zero profit margin on fresh seafood","C":"Supermarkets prepare all sushi inside their parking lots","D":"Chilled sushi has a 48-hour shelf life, so skipping wholesalers preserves freshness while supermarkets buy in large enough volumes to deal direct"},"correctOption":"D","correctAnswer":"Chilled sushi has a 48-hour shelf life, so skipping wholesalers preserves freshness while supermarkets buy in large enough volumes to deal direct","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because short shelf-life perishables need fast cold-chain delivery and large retail chains possess centralized logistics.","distractor_reasons":{"A":"Incorrect because raw fish products are highly perishable.","B":"Incorrect because wholesalers charge a margin for storage and breaking bulk.","C":"Incorrect because central kitchens supply supermarket depots.","D":"Option D is correct because short shelf-life perishables need fast cold-chain delivery and large retail chains possess centralized logistics."}}},{"id":"P1_U3_MCQ_453","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_453","question":"A confectionery giant sells chocolate bars to regional wholesalers, who then supply 45,000 small rural newsagents and village kiosks (Producer -> Wholesaler -> Retailer -> Consumer). Why is this three-tier channel efficient?","options":{"A":"Rural kiosks buy full 40-foot shipping containers of chocolate every week","B":"Chocolate bars spoil within four hours of leaving the factory","C":"Delivery vans from the factory would lose money making thousands of tiny drop-offs to remote kiosks, whereas wholesalers consolidate mixed deliveries locally","D":"Manufacturers are legally prohibited from selling directly to small shops"},"correctOption":"C","correctAnswer":"Delivery vans from the factory would lose money making thousands of tiny drop-offs to remote kiosks, whereas wholesalers consolidate mixed deliveries locally","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because wholesalers achieve transport economies by bundling many brands into single deliveries for fragmented small retailers.","distractor_reasons":{"A":"Incorrect because small kiosks lack space and cash for full containers.","B":"Incorrect because packaged chocolate has a long shelf life.","C":"Option C is correct because wholesalers achieve transport economies by bundling many brands into single deliveries for fragmented small retailers.","D":"Incorrect because direct delivery is legal, simply uneconomical for tiny orders."}}},{"id":"P1_U3_MCQ_454","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_454","question":"Besides 'breaking bulk', how does a 'wholesaler' assist small independent clothing boutiques financially and operationally?","options":{"A":"By guaranteeing that every dress will sell at full price","B":"By designing and sewing all garments inside the boutique's fitting rooms","C":"By paying the boutique owner's personal home mortgage","D":"By storing seasonal inventory in regional warehouses and offering 30-day trade credit so boutiques can sell stock before paying"},"correctOption":"D","correctAnswer":"By storing seasonal inventory in regional warehouses and offering 30-day trade credit so boutiques can sell stock before paying","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because wholesalers absorb inventory holding risk and ease retailer working-capital pressure via trade credit.","distractor_reasons":{"A":"Incorrect because retailers still bear fashion-markdown risk.","B":"Incorrect because garment manufacturing happens in factories.","C":"Incorrect because trade credit supports business inventory rather than personal bills.","D":"Option D is correct because wholesalers absorb inventory holding risk and ease retailer working-capital pressure via trade credit."}}},{"id":"P1_U3_MCQ_455","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_455","question":"How do 'retailers' add value for both manufacturers and everyday shoppers in the distribution chain?","options":{"A":"They gather thousands of complementary products in convenient local stores, display them attractively, and assist shoppers at the point of purchase","B":"They manufacture raw steel and plastic polymers for factories","C":"They act solely as commission agents who never hold physical stock","D":"They prevent consumers from comparing rival brands in one place"},"correctOption":"A","correctAnswer":"They gather thousands of complementary products in convenient local stores, display them attractively, and assist shoppers at the point of purchase","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because retail assortment, convenient hours, and local accessibility bridge factory output with household shopping habits.","distractor_reasons":{"A":"Option A is correct because retail assortment, convenient hours, and local accessibility bridge factory output with household shopping habits.","B":"Incorrect because raw-material extraction belongs to primary/secondary sectors.","C":"Incorrect because retailers purchase and hold physical store inventory.","D":"Incorrect because multi-brand stores enable convenient comparison."}}},{"id":"P1_U3_MCQ_456","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_456","question":"A New Zealand organic honey exporter hires a Tokyo-based 'agent' to negotiate listings with Japanese gourmet department stores. Why is an agent useful when entering an unfamiliar overseas market?","options":{"A":"The agent possesses established local retail relationships, language fluency, and customs knowledge, earning commission only when orders are secured","B":"The agent buys the entire New Zealand bee farm outright","C":"The agent eliminates all Japanese food import safety inspections","D":"Agents work completely free of charge without commission or fees"},"correctOption":"A","correctAnswer":"The agent possesses established local retail relationships, language fluency, and customs knowledge, earning commission only when orders are secured","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because commission-based local agents lower fixed market-entry overhead while bridging cultural and B2B network barriers.","distractor_reasons":{"A":"Option A is correct because commission-based local agents lower fixed market-entry overhead while bridging cultural and B2B network barriers.","B":"Incorrect because agents act as commercial intermediaries rather than acquirers.","C":"Incorrect because imported foods must still pass Japanese customs and health checks.","D":"Incorrect because agents earn a percentage commission on sales arranged."}}},{"id":"P1_U3_MCQ_457","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_457","question":"A manufacturer of medical ultrasound scanners distributes its machines through specialist regional medical-equipment dealers with trained clinical demonstrators rather than general online marketplaces. Which factor determined this 'Place' choice?","options":{"A":"General online marketplaces are illegal for medical devices","B":"Ultrasound scanners are cheap impulse buys for teenagers","C":"Technical product complexity requiring hands-on demonstration, staff training, and certified maintenance support","D":"Specialist dealers charge zero wholesale margin"},"correctOption":"C","correctAnswer":"Technical product complexity requiring hands-on demonstration, staff training, and certified maintenance support","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because complex diagnostic equipment requires expert pre-sale demonstration and reliable after-sale calibration.","distractor_reasons":{"A":"Incorrect because the choice is driven by clinical training needs rather than legality.","B":"Incorrect because scanners are expensive clinical capital assets.","C":"Option C is correct because complex diagnostic equipment requires expert pre-sale demonstration and reliable after-sale calibration.","D":"Incorrect because specialist dealers earn margins/fees for technical support."}}},{"id":"P1_U3_MCQ_458","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_458","question":"Why is mint chewing gum sold across hundreds of thousands of checkout counters, vending machines, and kiosks ('intensive distribution'), whereas grand pianos are sold in only a handful of city showrooms?","options":{"A":"Supermarkets refuse to sell chewing gum due to high weight","B":"Chewing gum spoils within two hours unless kept in vending machines","C":"Grand pianos are cheap everyday items bought at petrol stations","D":"Chewing gum is a low-cost frequent impulse purchase where immediate convenience drives sales, whereas grand pianos are rare, high-involvement purchases buyers travel to inspect"},"correctOption":"D","correctAnswer":"Chewing gum is a low-cost frequent impulse purchase where immediate convenience drives sales, whereas grand pianos are rare, high-involvement purchases buyers travel to inspect","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because shopping frequency and buyer effort determine whether a product needs maximum convenience outlets or selective/exclusive showrooms.","distractor_reasons":{"A":"Incorrect because gum is lightweight and profitable at checkouts.","B":"Incorrect because gum has a long shelf life.","C":"Incorrect because grand pianos are major luxury investments.","D":"Option D is correct because shopping frequency and buyer effort determine whether a product needs maximum convenience outlets or selective/exclusive showrooms."}}},{"id":"P1_U3_MCQ_459","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_459","question":"A clothing retailer lets shoppers order jackets on its smartphone app, pick them up two hours later at a local store, and exchange sizes free of charge at any branch. How does this 'omnichannel' strategy benefit the retailer?","options":{"A":"It combines online browsing convenience with instant store collection and drives extra footfall into physical shops where buyers often purchase additional items","B":"It eliminates the need to maintain accurate inventory tracking across warehouses and shops","C":"It forces online buyers to pay double shipping charges","D":"It closes all physical branches permanently"},"correctOption":"A","correctAnswer":"It combines online browsing convenience with instant store collection and drives extra footfall into physical shops where buyers often purchase additional items","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because integrating digital and physical channels reduces return friction and boosts cross-selling inside stores.","distractor_reasons":{"A":"Option A is correct because integrating digital and physical channels reduces return friction and boosts cross-selling inside stores.","B":"Incorrect because omnichannel retail requires tightly integrated real-time stock systems.","C":"Incorrect because click-and-collect saves delivery fees.","D":"Incorrect because physical branches serve as collection and exchange hubs."}}},{"id":"P1_U3_MCQ_460","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_460","question":"How has rapid 'e-commerce' growth pressured traditional high-street book and electronics stores?","options":{"A":"Physical stores carry heavy fixed property rents and local business rates while online rivals operate from lower-cost out-of-town fulfilment warehouses","B":"High-street stores are legally banned from displaying prices in shop windows","C":"Online retailers pay 90% higher corporate income tax than high-street shops","D":"Consumers are prohibited from walking into city-centre shops"},"correctOption":"A","correctAnswer":"Physical stores carry heavy fixed property rents and local business rates while online rivals operate from lower-cost out-of-town fulfilment warehouses","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because high-street fixed occupancy overheads make matching pure-play online prices difficult unless stores offer experiential value.","distractor_reasons":{"A":"Option A is correct because high-street fixed occupancy overheads make matching pure-play online prices difficult unless stores offer experiential value.","B":"Incorrect because displaying prices is standard and often legally required.","C":"Incorrect because online warehouses typically incur lower property taxes per dollar of sales.","D":"Incorrect because footfall shifted voluntarily toward online convenience."}}},{"id":"P1_U3_MCQ_461","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_461","question":"An online fashion retailer offers free return shipping and sees 38% of dresses sent back after customers wear them once for weekend parties ('wardrobing'). Which operational challenge of 'e-commerce' does this highlight?","options":{"A":"High reverse-logistics costs, damaged/worn returned stock, and potential payment fraud erode online profit margins","B":"Online fashion stores never have to pay for website hosting or cybersecurity","C":"E-commerce laws forbid customers from returning clothes that do not fit","D":"Returned dresses automatically double in resale value"},"correctOption":"A","correctAnswer":"High reverse-logistics costs, damaged/worn returned stock, and potential payment fraud erode online profit margins","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because high apparel return rates create expensive inspection, repackaging, and markdown losses.","distractor_reasons":{"A":"Option A is correct because high apparel return rates create expensive inspection, repackaging, and markdown losses.","B":"Incorrect because cybersecurity and platform maintenance are major ongoing costs.","C":"Incorrect because distance-selling rules protect genuine sizing returns.","D":"Incorrect because returned items often require heavy discounting or disposal."}}},{"id":"P1_U3_MCQ_462","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_462","question":"After false rumours circulate online that a bottled-juice brand uses banned artificial dyes, the company publishes independent lab certificates and factory transparency videos across major news sites. Which aim of 'promotion' is this?","options":{"A":"Conducting random quota sampling of fruit farmers","B":"Calculating unit variable manufacturing costs","C":"Harvesting a declining product prior to liquidation","D":"Defending and restoring brand reputation by correcting public misinformation"},"correctOption":"D","correctAnswer":"Defending and restoring brand reputation by correcting public misinformation","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because crisis communication and transparent evidence protect consumer trust and prevent sudden sales collapse.","distractor_reasons":{"A":"Incorrect because the campaign communicates outward to consumers.","B":"Incorrect because cost calculation belongs to Finance/Operations.","C":"Incorrect because the brand is actively investing to protect ongoing sales.","D":"Option D is correct because crisis communication and transparent evidence protect consumer trust and prevent sudden sales collapse."}}},{"id":"P1_U3_MCQ_463","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_463","question":"A luxury fragrance house airs cinematic adverts showing glamorous Parisian evening galas without mentioning perfume ingredients or bottle prices. Which promotional goal is being pursued?","options":{"A":"Building an aspirational brand image and emotional desirability through persuasive advertising","B":"Providing factual technical assembly instructions","C":"Clearing damaged warehouse stock via loss-leader discounts","D":"Explaining how a brand-new invention functions for the first time"},"correctOption":"A","correctAnswer":"Building an aspirational brand image and emotional desirability through persuasive advertising","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because lifestyle imagery creates symbolic status value that differentiates luxury fragrances.","distractor_reasons":{"A":"Option A is correct because lifestyle imagery creates symbolic status value that differentiates luxury fragrances.","B":"Incorrect because perfumes need no technical assembly.","C":"Incorrect because luxury prestige campaigns avoid bargain clearance messaging.","D":"Incorrect because consumers already understand how perfume is used."}}},{"id":"P1_U3_MCQ_464","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_464","question":"Why do pharmaceutical companies rely on 'informative advertising' listing active ingredients, dosage guidelines, and clinical trial efficacy when promoting allergy medicines to pharmacists?","options":{"A":"Healthcare professionals make purchasing recommendations based on verified clinical facts rather than emotional lifestyle slogans","B":"Informative adverts are always free to publish in medical journals","C":"Pharmacists are legally forbidden from reading clinical trial results","D":"Allergy medicines have zero competition from rival brands"},"correctOption":"A","correctAnswer":"Healthcare professionals make purchasing recommendations based on verified clinical facts rather than emotional lifestyle slogans","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because technical and medical audiences require objective evidence to evaluate safety and effectiveness.","distractor_reasons":{"A":"Option A is correct because technical and medical audiences require objective evidence to evaluate safety and effectiveness.","B":"Incorrect because medical journal ad space is paid.","C":"Incorrect because clinical data is essential to pharmacy practice.","D":"Incorrect because multiple rival antihistamine brands compete."}}},{"id":"P1_U3_MCQ_465","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_465","question":"A national supermarket chain spends $2 million on a festive 'television advertising' campaign. What is a key advantage of TV over local flyers, alongside its main drawback?","options":{"A":"TV combines sight, sound, and emotion to reach millions of households simultaneously, but requires very high production and airtime budgets","B":"TV adverts cost almost nothing to produce, but can only be seen by 50 people","C":"TV adverts allow viewers to click directly on bananas inside the screen to buy them instantly without internet","D":"TV advertising is legal only for B2B industrial steel manufacturers"},"correctOption":"A","correctAnswer":"TV combines sight, sound, and emotion to reach millions of households simultaneously, but requires very high production and airtime budgets","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because broadcast television delivers unmatched mass reach and storytelling impact at a high absolute cost.","distractor_reasons":{"A":"Option A is correct because broadcast television delivers unmatched mass reach and storytelling impact at a high absolute cost.","B":"Incorrect because this reverses TV's high cost and massive reach.","C":"Incorrect because traditional broadcast TV lacks direct click-to-cart interactivity.","D":"Incorrect because consumer supermarkets are among the biggest TV advertisers."}}},{"id":"P1_U3_MCQ_466","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_466","question":"A family-owned emergency plumbing business operating within one town advertises on 'local commercial radio' during morning commuter drive-time. Why is local radio well suited to this business?","options":{"A":"It reaches local residents across the exact service area repeatedly at a fraction of national TV costs, building memorable phone-number recall","B":"Local radio broadcasts worldwide to every continent","C":"Radio adverts allow plumbers to show 20-page technical blueprints","D":"Local radio stations air business adverts completely free"},"correctOption":"A","correctAnswer":"It reaches local residents across the exact service area repeatedly at a fraction of national TV costs, building memorable phone-number recall","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because regional radio avoids wasted geographic coverage while audio jingles reinforce emergency recall.","distractor_reasons":{"A":"Option A is correct because regional radio avoids wasted geographic coverage while audio jingles reinforce emergency recall.","B":"Incorrect because regional radio targets the local broadcast area.","C":"Incorrect because radio is purely audio without visual diagrams.","D":"Incorrect because commercial radio charges airtime rates."}}},{"id":"P1_U3_MCQ_467","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_467","question":"A fast-food chain places large billboards along major commuter highways. Why must billboard adverts use only a bold product photo, brand logo, and five or fewer words?","options":{"A":"Billboards are placed exclusively inside quiet university libraries","B":"Printing more than five words on a billboard is a criminal offence","C":"Passing drivers and commuters only glance at roadside billboards for 2–3 seconds, so lengthy text goes unread","D":"Highway billboards cost more per word printed"},"correctOption":"C","correctAnswer":"Passing drivers and commuters only glance at roadside billboards for 2–3 seconds, so lengthy text goes unread","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because brief visual exposure requires instant, uncluttered message comprehension.","distractor_reasons":{"A":"Incorrect because billboards sit outdoors along roads and stations.","B":"Incorrect because brevity is a practical communication rule rather than a criminal law.","C":"Option C is correct because brief visual exposure requires instant, uncluttered message comprehension.","D":"Incorrect because billboard rates are priced by site location and size rather than word count."}}},{"id":"P1_U3_MCQ_468","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_468","question":"A skincare startup pays a popular fitness influencer $15,000 to review its sunscreen on social media, but a week later the influencer becomes involved in a major public scandal. Which risk of 'influencer marketing' is demonstrated?","options":{"A":"The brand's reputation becomes closely tied to an external individual whose personal controversies can damage consumer trust","B":"Social media influencers have zero followers under age 60","C":"Influencer posts are legally required to be broadcast on national radio","D":"Influencer marketing eliminates all sunscreen manufacturing costs"},"correctOption":"A","correctAnswer":"The brand's reputation becomes closely tied to an external individual whose personal controversies can damage consumer trust","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because partnering with human creators introduces reputational spillover risk outside the firm's direct control.","distractor_reasons":{"A":"Option A is correct because partnering with human creators introduces reputational spillover risk outside the firm's direct control.","B":"Incorrect because influencers have large, highly engaged audiences.","C":"Incorrect because influencer content runs on social platforms.","D":"Incorrect because production costs remain unchanged."}}},{"id":"P1_U3_MCQ_469","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_469","question":"A gourmet cheese producer sets up a tasting counter at the end of a supermarket aisle offering warm brie on crackers alongside a bright 'Point-of-Sale (POS)' display stand. How does this sales promotion boost sales?","options":{"A":"Sensory sampling reduces perceived taste risk and triggers immediate impulse purchases right where shoppers make buying decisions","B":"It forces shoppers to order cheese by postal mail six weeks later","C":"It replaces the need to pay supermarket listing fees","D":"It prevents shoppers from seeing rival cheeses in the dairy fridge"},"correctOption":"A","correctAnswer":"Sensory sampling reduces perceived taste risk and triggers immediate impulse purchases right where shoppers make buying decisions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because in-store sampling and prominent end-of-aisle POS stands convert hesitation into instant basket additions.","distractor_reasons":{"A":"Option A is correct because in-store sampling and prominent end-of-aisle POS stands convert hesitation into instant basket additions.","B":"Incorrect because shoppers pick up packs immediately at the display.","C":"Incorrect because supermarkets charge fees for prime end-cap promotional spaces.","D":"Incorrect because rival cheeses remain stocked in the dairy aisle."}}},{"id":"P1_U3_MCQ_470","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_470","question":"A breakfast-cereal brand prints '$1.50 Off Your Next Box' coupons inside its cereal cartons. How does this 'sales promotion' encourage repeat buying without permanently cutting shelf prices?","options":{"A":"Competitors are legally forbidden from selling cereal during coupon promotions","B":"Supermarkets must lower shelf prices for every shopper worldwide forever","C":"Coupons eliminate all cardboard printing and oat costs","D":"Only price-sensitive shoppers who buy the first box and redeem the coupon receive the discount, encouraging a second purchase while regular buyers still pay full price"},"correctOption":"D","correctAnswer":"Only price-sensitive shoppers who buy the first box and redeem the coupon receive the discount, encouraging a second purchase while regular buyers still pay full price","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because targeted coupons reward repeat purchase behavior selectively without eroding margins across all customers.","distractor_reasons":{"A":"Incorrect because rivals continue competing normally.","B":"Incorrect because coupons apply only when redeemed at checkout.","C":"Incorrect because printing and coupon redemption incur promotional costs.","D":"Option D is correct because targeted coupons reward repeat purchase behavior selectively without eroding margins across all customers."}}},{"id":"P1_U3_MCQ_471","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_471","question":"A regional construction firm sponsors local youth football jerseys and funds a community riverside park cleanup, earning positive coverage in local newspapers. How does this 'Public Relations (PR)' activity benefit the business?","options":{"A":"It builds community goodwill, enhances corporate reputation, and keeps the brand visible to local homeowners and council planners","B":"It guarantees that the firm wins every government building contract without submitting bids","C":"It eliminates all cement and worker safety equipment costs","D":"PR sponsorship is legally tax-free up to 100% of company revenue"},"correctOption":"A","correctAnswer":"It builds community goodwill, enhances corporate reputation, and keeps the brand visible to local homeowners and council planners","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because community sponsorship fosters positive stakeholder sentiment and earned local media coverage.","distractor_reasons":{"A":"Option A is correct because community sponsorship fosters positive stakeholder sentiment and earned local media coverage.","B":"Incorrect because public contracts still require competitive tendering.","C":"Incorrect because construction materials and safety costs remain.","D":"Incorrect because sponsorship is a normal business expense rather than a 100% revenue tax exemption."}}},{"id":"P1_U3_MCQ_472","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_472","question":"A dental-implant manufacturer employs qualified dental-hygienist sales representatives to visit private dental clinics and demonstrate surgical implant kits. Why is high-cost 'personal selling' justified here?","options":{"A":"Dental implants are low-priced impulse snacks bought by children","B":"Each clinic that adopts the system generates tens of thousands of dollars in recurring annual implant orders, easily covering the rep's salary","C":"Personal selling is cheaper per contact than posting a free social-media photo","D":"Dental clinics are legally forbidden from reading product brochures"},"correctOption":"B","correctAnswer":"Each clinic that adopts the system generates tens of thousands of dollars in recurring annual implant orders, easily covering the rep's salary","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because high customer lifetime value and technical training needs make face-to-face B2B consultative selling highly profitable.","distractor_reasons":{"A":"Incorrect because surgical implants are specialized clinical products.","B":"Option B is correct because high customer lifetime value and technical training needs make face-to-face B2B consultative selling highly profitable.","C":"Incorrect because field sales reps have a high cost per visit.","D":"Incorrect because brochures support—rather than replace—clinical demonstrations."}}},{"id":"P1_U3_MCQ_473","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_473","question":"An online furniture retailer sends an automated email two hours after a logged-in shopper leaves a sofa in their digital shopping basket, offering free fabric swatches and a 5% completion code. Which promotional tool is this?","options":{"A":"Targeted direct marketing","B":"Above-the-line broadcast television advertising","C":"Public relations press conference","D":"Wholesale trade-fair exhibition"},"correctOption":"A","correctAnswer":"Targeted direct marketing","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sending a personalized, action-triggered offer directly to an identified prospect exemplifies modern direct marketing.","distractor_reasons":{"A":"Option A is correct because sending a personalized, action-triggered offer directly to an identified prospect exemplifies modern direct marketing.","B":"Incorrect because TV ads broadcast identical messages to mass audiences.","C":"Incorrect because PR targets media journalists and the public.","D":"Incorrect because trade fairs target B2B retail buyers."}}},{"id":"P1_U3_MCQ_474","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_474","question":"A sportswear brand allocates a quarterly promotional budget of $45,000: 50% to digital ads, 30% to PR and sporting events, and 20% to in-store displays. How much does the brand spend on PR and sporting events?","options":{"A":"$9,000","B":"$13,500","C":"$22,500","D":"$15,000"},"correctOption":"B","correctAnswer":"$13,500","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because 30% of $45,000 = 0.30 × $45,000 = $13,500.","distractor_reasons":{"A":"Incorrect because $9,000 is 20% (in-store displays).","B":"Option B is correct because 30% of $45,000 = 0.30 × $45,000 = $13,500.","C":"Incorrect because $22,500 is 50% (digital ads).","D":"Incorrect because $15,000 is one-third (33.3%) rather than 30%."}}},{"id":"P1_U3_MCQ_475","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_475","question":"A budget cosmetics brand launches a viral short-video makeup challenge encouraging customers to post before-and-after clips using its $6 lip tint. How does 'user-generated content (UGC)' reduce promotional costs?","options":{"A":"Short-video platforms pay companies $100 every time a user uploads a video","B":"Enthusiastic customers create and share authentic product demonstrations voluntarily, amplifying organic reach without paying for every view","C":"UGC eliminates all cosmetics manufacturing and packaging expenses","D":"UGC guarantees that zero negative reviews will ever appear online"},"correctOption":"B","correctAnswer":"Enthusiastic customers create and share authentic product demonstrations voluntarily, amplifying organic reach without paying for every view","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because peer-created social videos act as low-cost, credible word-of-mouth endorsements.","distractor_reasons":{"A":"Incorrect because platforms do not pay brands per user upload.","B":"Option B is correct because peer-created social videos act as low-cost, credible word-of-mouth endorsements.","C":"Incorrect because physical production costs still apply.","D":"Incorrect because open social campaigns can also attract critical comments."}}},{"id":"P1_U3_MCQ_476","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_476","question":"A newly launched cloud-accounting software firm sets 'rapid market-share acquisition' as its top objective for Year 1. Which marketing strategy best aligns with this objective?","options":{"A":"Penetration subscription pricing with a free 60-day trial, self-serve online onboarding, and targeted small-business search/social ads","B":"High price skimming at triple rival fees, sold only via printed postal brochures with zero free trial","C":"Harvesting cash by cutting product support and stopping all advertising","D":"Selling exclusively to 10 multinational banks via five-year custom tenders"},"correctOption":"A","correctAnswer":"Penetration subscription pricing with a free 60-day trial, self-serve online onboarding, and targeted small-business search/social ads","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because low entry pricing, friction-free online signup, and broad SME digital promotion maximize fast user adoption.","distractor_reasons":{"A":"Option A is correct because low entry pricing, friction-free online signup, and broad SME digital promotion maximize fast user adoption.","B":"Incorrect because high prices and slow postal brochures restrict rapid adoption.","C":"Incorrect because harvesting applies to dying products rather than Year 1 growth.","D":"Incorrect because slow enterprise tenders yield few accounts in Year 1."}}},{"id":"P1_U3_MCQ_477","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_477","question":"A luggage manufacturer designs a durable, water-resistant carry-on backpack for budget university backpackers. Which 4Ps marketing mix is most consistent with this target segment?","options":{"A":"Practical multi-pocket nylon backpack (Product), affordable $49 pricing (Price), direct online store and campus pop-ups (Place), and student social-media/referral discounts (Promotion)","B":"Hand-stitched alligator-leather trunk (Product), $4,500 prestige pricing (Price), five-star hotel boutiques (Place), and private-jet magazine ads (Promotion)","C":"Nylon backpack (Product), $49 pricing (Price), sold solely at airport first-class lounges (Place), and medical trade-journal ads (Promotion)","D":"Unlabelled cardboard boxes (Product), $500 cost-plus pricing (Price), wholesale steel depots (Place), and zero promotion"},"correctOption":"A","correctAnswer":"Practical multi-pocket nylon backpack (Product), affordable $49 pricing (Price), direct online store and campus pop-ups (Place), and student social-media/referral discounts (Promotion)","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because functional durability, student-friendly price, digital/campus access, and peer referral promotion fit student travellers.","distractor_reasons":{"A":"Option A is correct because functional durability, student-friendly price, digital/campus access, and peer referral promotion fit student travellers.","B":"Incorrect because $4,500 luxury trunks target ultra-wealthy travellers.","C":"Incorrect because first-class lounges and medical journals do not reach university backpackers.","D":"Incorrect because $500 cardboard boxes fail to meet student travel needs."}}},{"id":"P1_U3_MCQ_478","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_478","question":"An organic cold-pressed face serum made with rare botanical oils is priced at $140 per bottle, but distributed in plastic bargain bins next to $2 paper towels in discount supermarkets with photocopied black-and-white flyers. Why is this marketing strategy failing?","options":{"A":"The 4Ps are inconsistent: discount Place and cheap Promotion destroy the luxury credibility needed to justify a $140 Product and Price","B":"Organic face serums are legally banned from costing over $5","C":"Discount supermarket shoppers prefer buying $140 serums out of bargain bins","D":"Photocopied flyers are too expensive for skincare brands"},"correctOption":"A","correctAnswer":"The 4Ps are inconsistent: discount Place and cheap Promotion destroy the luxury credibility needed to justify a $140 Product and Price","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because all four elements of the marketing mix must send a unified positioning message to target buyers.","distractor_reasons":{"A":"Option A is correct because all four elements of the marketing mix must send a unified positioning message to target buyers.","B":"Incorrect because luxury skincare regularly sells above $100 in upscale boutiques.","C":"Incorrect because luxury buyers expect upscale retail environments and polished branding.","D":"Incorrect because flyers are cheap; the problem is cheap brand positioning."}}},{"id":"P1_U3_MCQ_479","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_479","question":"How should a cordless robotic lawnmower manufacturer adapt its marketing strategy as the product transitions from 'Introduction' into 'Maturity'?","options":{"A":"Broaden Place from specialist garden centres to mass DIY superstores, shift Price from skimming to competitive tiers, and introduce trade-in upgrade promotions","B":"Narrow distribution back to a single showroom and double the original launch price","C":"Stop all customer support and withdraw the product while sales are at their peak","D":"Run purely educational adverts explaining that grass grows in summer"},"correctOption":"A","correctAnswer":"Broaden Place from specialist garden centres to mass DIY superstores, shift Price from skimming to competitive tiers, and introduce trade-in upgrade promotions","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because mature mass adoption requires wider retail reach, competitive pricing, and replacement incentives.","distractor_reasons":{"A":"Option A is correct because mature mass adoption requires wider retail reach, competitive pricing, and replacement incentives.","B":"Incorrect because narrowing distribution and doubling prices shrinks mature market share.","C":"Incorrect because peak maturity is the most profitable phase to defend.","D":"Incorrect because mature buyers already understand basic product function."}}},{"id":"P1_U3_MCQ_480","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_480","question":"During a severe economic recession when household disposable incomes fall, a mid-market pasta-sauce brand sees shoppers switching to cheap supermarket own-label jars. Which strategic adjustment protects volume and brand loyalty?","options":{"A":"Cut sauce quality secretly while keeping high luxury prices","B":"Raise jar prices by 45% without changing ingredients or pack size","C":"Stop supplying supermarkets and sell jars only at luxury airport boutiques","D":"Introduce larger 'Family Value' jars with lower cost per gram and run recipe promotions showing how to cook nutritious $2 family meals at home"},"correctOption":"D","correctAnswer":"Introduce larger 'Family Value' jars with lower cost per gram and run recipe promotions showing how to cook nutritious $2 family meals at home","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because emphasizing value-for-money and affordable home-cooking aligns with recession-hit household budgets.","distractor_reasons":{"A":"Incorrect because degrading quality permanently alienates loyal buyers.","B":"Incorrect because steep price hikes accelerate switching to own-label rivals.","C":"Incorrect because luxury airport boutiques do not serve everyday grocery shoppers.","D":"Option D is correct because emphasizing value-for-money and affordable home-cooking aligns with recession-hit household budgets."}}},{"id":"P1_U3_MCQ_481","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_481","question":"When cocoa bean prices surge by 60%, a chocolate-bar maker quietly shrinks bar weight from 100g to 85g while keeping the $2.00 price ('shrinkflation'), sparking consumer anger online. What alternative marketing response maintains stronger trust?","options":{"A":"Communicate transparently or introduce a clearly labelled 'Sharing Duo' pack and new crunchy wafer variants that justify value openly","B":"Hide ingredient weight labels completely in violation of food laws","C":"Stop selling chocolate bars until cocoa prices fall back to 1990 levels","D":"Replace cocoa entirely with sawdust without telling buyers"},"correctOption":"A","correctAnswer":"Communicate transparently or introduce a clearly labelled 'Sharing Duo' pack and new crunchy wafer variants that justify value openly","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because honest pack-tier innovation preserves brand trust better than stealth weight cuts.","distractor_reasons":{"A":"Option A is correct because honest pack-tier innovation preserves brand trust better than stealth weight cuts.","B":"Incorrect because net weight declarations are legally mandatory.","C":"Incorrect because halting sales surrenders shelf space to rivals.","D":"Incorrect because adulterating food is illegal and unethical."}}},{"id":"P1_U3_MCQ_482","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_482","question":"An eyewear retailer adds an Augmented Reality (AR) 'Virtual Try-On' camera feature to its mobile app so online shoppers can see how glasses frames fit their face shape in real time. How does this technology strengthen its marketing strategy?","options":{"A":"It overcomes the biggest barrier to buying glasses online—uncertainty over fit and appearance—boosting online conversion and lowering returns","B":"It eliminates the need to manufacture physical eyeglass frames","C":"It forces optometrists to close all eye-testing clinics","D":"It doubles the shipping weight of eyeglass parcels"},"correctOption":"A","correctAnswer":"It overcomes the biggest barrier to buying glasses online—uncertainty over fit and appearance—boosting online conversion and lowering returns","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because interactive AR visualization bridges the sensory gap between physical showrooms and e-commerce.","distractor_reasons":{"A":"Option A is correct because interactive AR visualization bridges the sensory gap between physical showrooms and e-commerce.","B":"Incorrect because physical glasses are still produced and shipped.","C":"Incorrect because clinical eye exams remain essential.","D":"Incorrect because digital app features do not affect parcel weight."}}},{"id":"P1_U3_MCQ_483","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_483","question":"With single-person households rising sharply in major cities, a frozen-food company launches single-serve 'Solo Gourmet' trays with zero food waste alongside its traditional 4-person family packs. Which market change is driving this product adaptation?","options":{"A":"A total disappearance of household microwave ovens","B":"A government ban on family-sized dining tables","C":"Falling national electricity generation","D":"Demographic shifts in household size and living arrangements"},"correctOption":"D","correctAnswer":"Demographic shifts in household size and living arrangements","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because more solo dwellers create strong demand for convenient single-portion packaging.","distractor_reasons":{"A":"Incorrect because frozen trays rely on widespread microwave ownership.","B":"Incorrect because portion sizes reflect household demographics rather than furniture bans.","C":"Incorrect because electricity supply is unrelated.","D":"Option D is correct because more solo dwellers create strong demand for convenient single-portion packaging."}}},{"id":"P1_U3_MCQ_484","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_484","question":"Why do consumer-appliance manufacturers frequently enter emerging foreign markets when domestic sales of a product reach saturation?","options":{"A":"Rising disposable incomes and first-time household ownership in emerging economies offer high-growth demand for products already proven at home","B":"Emerging markets have zero local or international competitors","C":"Exporting overseas requires zero adaptation of electrical plugs or manuals","D":"Foreign currencies never fluctuate against the home currency"},"correctOption":"A","correctAnswer":"Rising disposable incomes and first-time household ownership in emerging economies offer high-growth demand for products already proven at home","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because expanding middle classes in developing economies create fresh growth waves for established appliance categories.","distractor_reasons":{"A":"Option A is correct because expanding middle classes in developing economies create fresh growth waves for established appliance categories.","B":"Incorrect because emerging markets feature intense domestic and global rivalry.","C":"Incorrect because voltage, plugs, and languages require localization.","D":"Incorrect because exchange-rate volatility is a core international trade risk."}}},{"id":"P1_U3_MCQ_485","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_485","question":"A soft-drink company translates its humorous English slogan word-for-word into Spanish without consulting native copywriters, accidentally creating an embarrassing slang phrase that triggers ridicule. Which international marketing barrier occurred?","options":{"A":"Language and cultural localization failure in promotional communication","B":"High ocean-freight container tariffs","C":"Excessive use of random statistical sampling","D":"Domestic minimum-wage legislation"},"correctOption":"A","correctAnswer":"Language and cultural localization failure in promotional communication","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because idioms and humour rarely translate literally across cultures, requiring native cultural adaptation.","distractor_reasons":{"A":"Option A is correct because idioms and humour rarely translate literally across cultures, requiring native cultural adaptation.","B":"Incorrect because the blunder occurred in slogan translation rather than shipping tariffs.","C":"Incorrect because proper local focus testing would have caught the error.","D":"Incorrect because wage laws are unrelated to slogan translation."}}},{"id":"P1_U3_MCQ_486","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_486","question":"A Malaysian furniture exporter prices its dining sets in Malaysian Ringgit (MYR). If the Ringgit appreciates sharply by 15% against the US Dollar, what happens to the competitiveness of its furniture in the United States?","options":{"A":"US import tariffs automatically drop to zero when the Ringgit rises","B":"Its furniture becomes 15% cheaper in US Dollars automatically","C":"Exchange-rate changes have zero effect on export prices","D":"Its furniture becomes more expensive in US Dollars for American buyers, reducing price competitiveness unless the exporter absorbs lower profit margins"},"correctOption":"D","correctAnswer":"Its furniture becomes more expensive in US Dollars for American buyers, reducing price competitiveness unless the exporter absorbs lower profit margins","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because currency appreciation raises the foreign-currency price of exports, squeezing either demand or exporter margins.","distractor_reasons":{"A":"Incorrect because tariff rates are set by trade policy rather than exchange rates.","B":"Incorrect because depreciation—not appreciation—makes exports cheaper abroad.","C":"Incorrect because currency conversion directly alters foreign retail prices.","D":"Option D is correct because currency appreciation raises the foreign-currency price of exports, squeezing either demand or exporter margins."}}},{"id":"P1_U3_MCQ_487","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_487","question":"A European biscuit maker exports chocolate-coated biscuits to tropical Southeast Asia without upgrading the chocolate tempering or moisture-barrier foil, resulting in melted, soggy biscuits on store shelves. Which foreign-market factor was neglected?","options":{"A":"Hiring a B2B aircraft leasing agent","B":"Translating television jingles into French","C":"Using price skimming on everyday biscuits","D":"Adapting product formulation and protective packaging to local climate and storage conditions"},"correctOption":"D","correctAnswer":"Adapting product formulation and protective packaging to local climate and storage conditions","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because high heat and humidity require heat-stable formulations and superior moisture-seal packaging.","distractor_reasons":{"A":"Incorrect because aircraft leasing is unrelated.","B":"Incorrect because French translation does not prevent tropical heat melting.","C":"Incorrect because the failure was physical product spoilage rather than pricing.","D":"Option D is correct because high heat and humidity require heat-stable formulations and superior moisture-seal packaging."}}},{"id":"P1_U3_MCQ_488","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_488","question":"A specialty olive-oil producer wants to enter the German market quickly with low upfront investment by selling wholesale pallets to an established German specialty-food distributor. What is a drawback of using a 'foreign distributor' instead of opening a wholly owned sales subsidiary?","options":{"A":"The producer gives up part of its profit margin to the distributor and has less direct control over how retailers price and promote the brand","B":"The producer must spend $50 million building a bottling factory in Berlin","C":"Foreign distributors are legally forbidden from selling imported foods","D":"The producer must personally deliver single bottles to every German household"},"correctOption":"A","correctAnswer":"The producer gives up part of its profit margin to the distributor and has less direct control over how retailers price and promote the brand","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because outsourcing local distribution trades away margin and brand-execution control in exchange for speed and low capital risk.","distractor_reasons":{"A":"Option A is correct because outsourcing local distribution trades away margin and brand-execution control in exchange for speed and low capital risk.","B":"Incorrect because building a foreign factory describes wholly owned direct investment.","C":"Incorrect because import distributors are lawful and common.","D":"Incorrect because the distributor handles local B2B logistics."}}},{"id":"P1_U3_MCQ_489","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_489","question":"An American battery company and a South Korean chemical firm form an international 'joint venture' to build an EV battery plant, but clash over whether to reinvest profits into R&D or pay immediate cash dividends. Which risk of joint ventures is shown?","options":{"A":"Joint ventures are illegal in international manufacturing","B":"Strategic and cultural disagreements between partner management teams over profit allocation and operational control","C":"Neither partner contributes any capital or technology","D":"Joint ventures eliminate all raw-material lithium costs"},"correctOption":"B","correctAnswer":"Strategic and cultural disagreements between partner management teams over profit allocation and operational control","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because shared ownership requires continuous alignment on reinvestment, governance, and corporate priorities.","distractor_reasons":{"A":"Incorrect because joint ventures are widely used globally.","B":"Option B is correct because shared ownership requires continuous alignment on reinvestment, governance, and corporate priorities.","C":"Incorrect because both partners pool resources.","D":"Incorrect because raw-material expenses still apply."}}},{"id":"P1_U3_MCQ_490","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_490","question":"A global fried-chicken restaurant chain expands via international 'franchising', and one overseas franchisee triggers a food-poisoning outbreak by ignoring kitchen refrigeration rules, hurting the brand's image worldwide. Which drawback of franchising is this?","options":{"A":"Franchisees never pay upfront fees or ongoing royalties","B":"Franchisors must fund 100% of every franchisee's store construction costs","C":"Franchising prevents rapid multi-country store openings","D":"Poor quality or hygiene standards at one independent franchisee outlet can damage the global brand reputation of the entire chain"},"correctOption":"D","correctAnswer":"Poor quality or hygiene standards at one independent franchisee outlet can damage the global brand reputation of the entire chain","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because consumers view all stores under the same logo as one unified brand, creating reputational contagion risk.","distractor_reasons":{"A":"Incorrect because franchisees pay initial fees and percentage royalties.","B":"Incorrect because franchisees invest their own capital.","C":"Incorrect because speed is franchising's biggest strength.","D":"Option D is correct because consumers view all stores under the same logo as one unified brand, creating reputational contagion risk."}}},{"id":"P1_U3_MCQ_491","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_491","question":"A popular animated children's TV studio grants 'licensing' rights to toy, backpack, and bedding manufacturers across 30 countries in exchange for a 10% royalty on wholesale sales. Why is licensing attractive here?","options":{"A":"The studio earns global royalty revenue from its intellectual property without investing capital in toy or textile factories","B":"The studio must operate 30 plastic-moulding factories worldwide","C":"Licensing guarantees that unlicensed counterfeit toys never appear","D":"Toy manufacturers receive the studio's characters for free"},"correctOption":"A","correctAnswer":"The studio earns global royalty revenue from its intellectual property without investing capital in toy or textile factories","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because licensing monetizes brand/character IP rapidly while licensees bear manufacturing and inventory risks.","distractor_reasons":{"A":"Option A is correct because licensing monetizes brand/character IP rapidly while licensees bear manufacturing and inventory risks.","B":"Incorrect because the licensees own and run the factories.","C":"Incorrect because IP enforcement against counterfeits remains necessary.","D":"Incorrect because licensees pay contracted royalties."}}},{"id":"P1_U3_MCQ_492","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_492","question":"A high-pressure doorstep salesperson convinces an elderly homeowner to sign a $9,000 double-glazing window contract, and the next morning the homeowner changes their mind. How do consumer protection laws protect the buyer?","options":{"A":"Homeowners are legally forbidden from buying windows from salespeople","B":"Doorstep contracts can never be cancelled once signed","C":"Statutory 'cooling-off period' rules grant distance and doorstep buyers a legal window (e.g., 14 days) to cancel contracts for a full refund without penalty","D":"Salespeople must install the windows for free if the buyer complains"},"correctOption":"C","correctAnswer":"Statutory 'cooling-off period' rules grant distance and doorstep buyers a legal window (e.g., 14 days) to cancel contracts for a full refund without penalty","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because cooling-off rights protect consumers from impulsive pressure sales and online purchases where items could not be inspected beforehand.","distractor_reasons":{"A":"Incorrect because doorstep selling is lawful when cooling-off rights are honoured.","B":"Incorrect because consumer laws override non-cancellation clauses during the cooling-off period.","C":"Option C is correct because cooling-off rights protect consumers from impulsive pressure sales and online purchases where items could not be inspected beforehand.","D":"Incorrect because cancellation voids the contract and refunds deposits."}}},{"id":"P1_U3_MCQ_493","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_493","question":"A clothing brand prints '100% Eco-Friendly & Biodegradable' on polyester jackets that are actually made from standard petroleum plastics, resulting in heavy regulatory fines for 'greenwashing'. Why do advertising laws penalize false environmental claims?","options":{"A":"Clothing brands are legally prohibited from using recycled fabrics","B":"Unsubstantiated green claims deceive eco-conscious shoppers and unfairly disadvantage rivals who genuinely invest in sustainable materials","C":"Polyester jackets are exempt from all consumer description laws","D":"Regulators fine all companies that sell winter coats"},"correctOption":"B","correctAnswer":"Unsubstantiated green claims deceive eco-conscious shoppers and unfairly disadvantage rivals who genuinely invest in sustainable materials","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because environmental marketing claims must be backed by verifiable scientific evidence to prevent consumer deception.","distractor_reasons":{"A":"Incorrect because genuine sustainable fabrics are encouraged.","B":"Option B is correct because environmental marketing claims must be backed by verifiable scientific evidence to prevent consumer deception.","C":"Incorrect because apparel labels are strictly covered by misleading-claims laws.","D":"Incorrect because the fine targeted false environmental claims rather than coats themselves."}}},{"id":"P1_U3_MCQ_494","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_494","question":"Why do governments enforce strict legal restrictions banning tobacco and vaping companies from sponsoring youth music festivals or placing adverts on social-media platforms used heavily by teenagers?","options":{"A":"To force tobacco companies to switch to manufacturing bicycles","B":"Because music festivals refuse to accept sponsorship money from any industry","C":"Because social-media platforms have zero adult users","D":"To protect public health and prevent addictive, age-restricted products from being promoted to minors"},"correctOption":"D","correctAnswer":"To protect public health and prevent addictive, age-restricted products from being promoted to minors","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because public-health legislation restricts marketing channels for harmful or age-controlled goods to shield young people.","distractor_reasons":{"A":"Incorrect because the law regulates marketing practices rather than mandating unrelated products.","B":"Incorrect because festivals accept sponsorships from non-restricted sectors.","C":"Incorrect because youth-heavy platforms require age-gating and ad bans for restricted goods.","D":"Option D is correct because public-health legislation restricts marketing channels for harmful or age-controlled goods to shield young people."}}},{"id":"P1_U3_MCQ_495","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_495","question":"Three competing domestic airlines secretly agree to set identical minimum fuel surcharges on all flights so none of them loses passengers to cheaper fares. Which legal control is violated?","options":{"A":"Employee maternity-leave statutes","B":"Weights and measures liquid calibration rules","C":"Product allergen labelling regulations","D":"Competition and anti-trust laws prohibiting price-fixing cartels that harm consumers"},"correctOption":"D","correctAnswer":"Competition and anti-trust laws prohibiting price-fixing cartels that harm consumers","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because collusive price-fixing eliminates genuine rivalry and forces consumers to pay artificially inflated prices.","distractor_reasons":{"A":"Incorrect because maternity leave is an employment law.","B":"Incorrect because weights and measures govern physical quantity labels.","C":"Incorrect because allergen rules apply to food packaging.","D":"Option D is correct because collusive price-fixing eliminates genuine rivalry and forces consumers to pay artificially inflated prices."}}},{"id":"P1_U3_MCQ_496","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_496","question":"An electric-kettle manufacturer discovers a faulty thermostat switch that can overheat and cause kitchen fires in 50,000 sold units. Under product-safety legislation, what must the company do immediately?","options":{"A":"Issue an urgent public product recall, halt further store sales, and offer free repairs, safe replacements, or full refunds to buyers","B":"Ignore the fault and quietly sell the remaining defective kettles at a 50% discount","C":"Blame customers for plugging the kettles into electrical sockets","D":"Change the kettle box colour without fixing the faulty switch"},"correctOption":"A","correctAnswer":"Issue an urgent public product recall, halt further store sales, and offer free repairs, safe replacements, or full refunds to buyers","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because product-safety laws impose strict liability on producers to remove hazardous goods from homes and prevent injury.","distractor_reasons":{"A":"Option A is correct because product-safety laws impose strict liability on producers to remove hazardous goods from homes and prevent injury.","B":"Incorrect because knowingly selling unsafe goods incurs severe criminal penalties and lawsuits.","C":"Incorrect because normal household use must be completely safe.","D":"Incorrect because cosmetic packaging changes do not resolve the safety hazard."}}},{"id":"P1_U3_MCQ_497","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_497","question":"Even though local law permits sugary soda billboards near schools, a beverage corporation voluntarily removes all adverts within 500 metres of primary schools and shifts ad spend to low-sugar sparkling water. What motivates this 'ethical marketing' decision?","options":{"A":"Strengthening long-term brand trust with parents and preempting stricter government sugar-advertising bans","B":"Increasing short-term sugar sales to six-year-old children","C":"Eliminating all bottling factory electricity expenses","D":"Violating consumer protection laws intentionally"},"correctOption":"A","correctAnswer":"Strengthening long-term brand trust with parents and preempting stricter government sugar-advertising bans","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because ethical self-regulation protects corporate reputation among parents and reduces future regulatory backlash.","distractor_reasons":{"A":"Option A is correct because ethical self-regulation protects corporate reputation among parents and reduces future regulatory backlash.","B":"Incorrect because the firm is reducing sugary drink promotion to children.","C":"Incorrect because bottling costs remain unchanged.","D":"Incorrect because ethical behaviour goes beyond minimum legal compliance."}}},{"id":"P1_U3_MCQ_498","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_498","question":"How do strict consumer-protection and advertising regulations affect a business's marketing operations and costs?","options":{"A":"Firms must spend more on legal copy reviews, accurate packaging labels, safety testing, and customer return handling, though compliance builds long-term buyer confidence","B":"Consumer laws reduce all marketing and packaging costs to zero","C":"Regulations allow businesses to make any exaggerated health claim without proof","D":"Consumer laws ban businesses from offering warranties or refunds"},"correctOption":"A","correctAnswer":"Firms must spend more on legal copy reviews, accurate packaging labels, safety testing, and customer return handling, though compliance builds long-term buyer confidence","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because regulatory compliance raises administrative and testing overheads while creating a trustworthy marketplace.","distractor_reasons":{"A":"Option A is correct because regulatory compliance raises administrative and testing overheads while creating a trustworthy marketplace.","B":"Incorrect because compliance adds testing and legal verification expenses.","C":"Incorrect because claims must be substantiated.","D":"Incorrect because laws guarantee minimum refund and repair rights."}}},{"id":"P1_U3_MCQ_499","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_499","question":"Before launching an electric-scooter sharing service in Kuala Lumpur, a startup surveys 600 train commuters on first-mile gaps, sets dynamic per-minute app pricing with student passes, places docks at LRT stations, and runs referral codes. Why is this strategy likely to succeed?","options":{"A":"It ignores commuter travel habits and sells scooters solely via printed postal catalogues","B":"It is market-oriented, targets clear commuter segments, and aligns convenient station Place, flexible Price, and digital Promotion around real user needs","C":"It relies purely on product-oriented engineering without checking station footfall","D":"It uses permanent loss-leader pricing at zero cents per ride forever"},"correctOption":"B","correctAnswer":"It is market-oriented, targets clear commuter segments, and aligns convenient station Place, flexible Price, and digital Promotion around real user needs","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because primary commuter research directly informs accessible station placement, tiered pricing, and viral referral promotion.","distractor_reasons":{"A":"Incorrect because the startup surveyed commuters and used mobile app access.","B":"Option B is correct because primary commuter research directly informs accessible station placement, tiered pricing, and viral referral promotion.","C":"Incorrect because station placement was driven by commuter survey data.","D":"Incorrect because dynamic per-minute pricing and student passes generate recurring revenue."}}},{"id":"P1_U3_MCQ_500","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_500","question":"Facing declining sales of traditional loose-leaf black tea, a heritage tea company segments busy young professionals, launches biodegradable pyramid herbal-infusion tea bags, sells subscriptions online plus via trendy cafés, and backs relaxation claims with certified nutritional data. How does this turn the business around?","options":{"A":"It combines targeted market segmentation, an extension strategy into convenient modern formats, omnichannel Place, and legally compliant promotion","B":"It cuts tea quality, raises prices by 300%, and removes all ingredient labels","C":"It relies solely on outdated 1995 secondary reports and stops all online sales","D":"It uses misleading 'Cures All Diseases' health claims to boost short-term orders"},"correctOption":"A","correctAnswer":"It combines targeted market segmentation, an extension strategy into convenient modern formats, omnichannel Place, and legally compliant promotion","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because revitalizing a mature/declining brand requires aligning product innovation, modern distribution, and credible, lawful promotion with a growing demographic segment.","distractor_reasons":{"A":"Option A is correct because revitalizing a mature/declining brand requires aligning product innovation, modern distribution, and credible, lawful promotion with a growing demographic segment.","B":"Incorrect because cutting quality and removing mandatory labels would destroy trust and breach food laws.","C":"Incorrect because e-commerce subscriptions and modern formats actively capture younger buyers.","D":"Incorrect because unverified medical claims violate consumer protection and advertising regulations."}}},{"id":"P1_U3_MCQ_501","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_501","question":"What is meant by the term 'marketing'?","options":{"A":"Producing goods at the lowest possible unit cost regardless of demand.","B":"Identifying customer wants and satisfying them profitably.","C":"Advertising and selling existing inventory to the general public.","D":"Distributing finished goods from factories to retail outlets."},"correctOption":"B","correctAnswer":"Identifying customer wants and satisfying them profitably.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because marketing is the management process responsible for identifying customer needs and wants and satisfying them profitably.","distractor_reasons":{"A":"Incorrect because focusing solely on production efficiency without considering customer demand describes a product-oriented approach.","B":"Option B is correct because marketing is the management process responsible for identifying customer needs and wants and satisfying them profitably.","C":"Incorrect because advertising and selling are only individual elements of promotion and sales, not the whole marketing function.","D":"Incorrect because transporting goods to retail outlets describes distribution ('place'), which is just one part of the marketing mix."}}},{"id":"P1_U3_MCQ_502","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_502","question":"What is the key difference between a 'customer' and a 'consumer'?","options":{"A":"A customer only buys services, whereas a consumer only buys tangible goods.","B":"A customer buys goods or services from a business, whereas a consumer uses them for personal use.","C":"A customer buys products in bulk for resale, whereas a consumer is always another business.","D":"A customer buys from niche markets, whereas a consumer only buys from mass markets."},"correctOption":"B","correctAnswer":"A customer buys goods or services from a business, whereas a consumer uses them for personal use.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a customer is a person or business that purchases goods or services, whereas a consumer is the final user who buys or uses goods or services for personal use and not for resale.","distractor_reasons":{"A":"Incorrect because both customers and consumers can purchase or use both tangible goods and intangible services.","B":"Option B is correct because a customer is a person or business that purchases goods or services, whereas a consumer is the final user who buys or uses goods or services for personal use and not for resale.","C":"Incorrect because a consumer buys for personal use rather than for resale, and is an individual rather than a business.","D":"Incorrect because both customers and consumers exist in both niche and mass markets."}}},{"id":"P1_U3_MCQ_503","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_503","question":"How is 'market share' defined?","options":{"A":"The total profit earned by a business divided by the total profit of the industry.","B":"The number of retail outlets selling a business's brand compared to rivals.","C":"The percentage of total sales revenue for the whole market held by one brand or business.","D":"The total value of all goods and services sold within a country in one year."},"correctOption":"C","correctAnswer":"The percentage of total sales revenue for the whole market held by one brand or business.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because market share measures the proportion (percentage) of total market sales revenue held by a single brand or business.","distractor_reasons":{"A":"Incorrect because market share is based on sales revenue (or sales volume), not profit.","B":"Incorrect because the number of retail outlets measures distribution coverage rather than market share.","C":"Option C is correct because market share measures the proportion (percentage) of total market sales revenue held by a single brand or business.","D":"Incorrect because the total value of all goods and services sold in an economy measures national output (GDP), not a firm's market share."}}},{"id":"P1_U3_MCQ_504","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_504","question":"Which statement best defines 'customer loyalty'?","options":{"A":"When customers purchase a product once because of a temporary price discount.","B":"When suppliers agree to sell raw materials exclusively to one manufacturer.","C":"When employees remain working for the same business for many years.","D":"When existing customers continually buy products from the same business rather than competitors."},"correctOption":"D","correctAnswer":"When existing customers continually buy products from the same business rather than competitors.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because customer loyalty occurs when existing customers repeatedly purchase from the same business instead of switching to rival brands.","distractor_reasons":{"A":"Incorrect because a one-off purchase driven by a discount does not represent ongoing repeat purchasing or loyalty.","B":"Incorrect because exclusive supply agreements relate to supplier relationships, not customer behaviour.","C":"Incorrect because employees staying with a business describes low labour turnover, not customer loyalty.","D":"Option D is correct because customer loyalty occurs when existing customers repeatedly purchase from the same business instead of switching to rival brands."}}},{"id":"P1_U3_MCQ_505","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_505","question":"Why is maintaining customer loyalty an important role of marketing?","options":{"A":"It eliminates all fixed costs associated with operating a marketing department.","B":"It removes the need to ever update or improve existing products.","C":"It guarantees that competitors will exit the industry completely.","D":"It is usually much cheaper to keep existing customers than to attract new ones."},"correctOption":"D","correctAnswer":"It is usually much cheaper to keep existing customers than to attract new ones.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because retaining existing customers costs significantly less in promotion and acquisition expenses than attracting brand-new customers.","distractor_reasons":{"A":"Incorrect because marketing departments still incur fixed salaries and administrative expenses.","B":"Incorrect because businesses must still adapt and improve products as customer expectations evolve over time.","C":"Incorrect because high customer loyalty strengthens a firm's position but does not force all rivals out of the market.","D":"Option D is correct because retaining existing customers costs significantly less in promotion and acquisition expenses than attracting brand-new customers."}}},{"id":"P1_U3_MCQ_506","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_506","question":"What is the primary purpose of 'building customer relationships' in marketing?","options":{"A":"To force customers into signing long-term legal purchasing contracts.","B":"To communicate with customers to encourage repeat purchases and understand their changing needs.","C":"To replace primary market research with government census statistics.","D":"To reduce product quality once customers have become regular buyers."},"correctOption":"B","correctAnswer":"To communicate with customers to encourage repeat purchases and understand their changing needs.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because building customer relationships involves ongoing communication with customers to encourage repeat business and gather insight into their changing buying habits and needs.","distractor_reasons":{"A":"Incorrect because customer relationships rely on trust and engagement rather than binding legal contracts.","B":"Option B is correct because building customer relationships involves ongoing communication with customers to encourage repeat business and gather insight into their changing buying habits and needs.","C":"Incorrect because customer relationships actually provide direct primary feedback rather than relying on secondary government data.","D":"Incorrect because lowering quality would destroy trust and drive loyal customers away."}}},{"id":"P1_U3_MCQ_507","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_507","question":"How does a business gain a competitive advantage by 'anticipating changes in customer needs'?","options":{"A":"By waiting for competitors to launch new products before copying them.","B":"By keeping prices fixed regardless of changes in consumer incomes.","C":"By identifying new trends or market gaps early and developing products ahead of rivals.","D":"By reducing expenditure on research and development to maximize short-term cash."},"correctOption":"C","correctAnswer":"By identifying new trends or market gaps early and developing products ahead of rivals.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because anticipating changes in customer needs allows a business to spot emerging trends or gaps in the market early and launch products before competitors do.","distractor_reasons":{"A":"Incorrect because waiting to copy rivals is reactive rather than anticipating future customer needs.","B":"Incorrect because rigid pricing ignores changing economic conditions and consumer spending power.","C":"Option C is correct because anticipating changes in customer needs allows a business to spot emerging trends or gaps in the market early and launch products before competitors do.","D":"Incorrect because cutting R&D prevents a business from innovating to meet future customer demands."}}},{"id":"P1_U3_MCQ_508","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_508","question":"Which factor is a direct cause of changes in consumer spending patterns?","options":{"A":"A change in the legal form of ownership of a supplier.","B":"An increase in the span of control within a factory.","C":"A reduction in the number of shares traded on a stock exchange.","D":"Changes in consumer tastes, fashions, and levels of disposable income."},"correctOption":"D","correctAnswer":"Changes in consumer tastes, fashions, and levels of disposable income.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because consumer spending patterns change due to shifts in tastes and fashions, technological advances, changes in income, and ageing populations.","distractor_reasons":{"A":"Incorrect because a supplier's legal ownership structure does not directly alter what consumers choose to buy.","B":"Incorrect because internal organizational hierarchy does not dictate consumer purchasing habits.","C":"Incorrect because stock exchange trading volume does not directly cause shifts in consumer product preferences.","D":"Option D is correct because consumer spending patterns change due to shifts in tastes and fashions, technological advances, changes in income, and ageing populations."}}},{"id":"P1_U3_MCQ_509","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_509","question":"How does an ageing population affect consumer spending patterns in a country?","options":{"A":"Total demand for all luxury goods disappears completely.","B":"Demand increases rapidly for baby clothing and primary school textbooks.","C":"Consumers stop purchasing services and spend exclusively on raw materials.","D":"Demand increases for products and services aimed at older people, such as healthcare and retirement homes."},"correctOption":"D","correctAnswer":"Demand increases for products and services aimed at older people, such as healthcare and retirement homes.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because an ageing population increases the proportion of older consumers, raising demand for age-related goods and services such as anti-ageing products, healthcare, and care homes.","distractor_reasons":{"A":"Incorrect because many older consumers have significant savings and pensions to spend on leisure and luxury items.","B":"Incorrect because demand for baby and children's items rises with a higher birth rate, not an ageing population.","C":"Incorrect because older consumers purchase a wide variety of consumer goods and services, not industrial raw materials.","D":"Option D is correct because an ageing population increases the proportion of older consumers, raising demand for age-related goods and services such as anti-ageing products, healthcare, and care homes."}}},{"id":"P1_U3_MCQ_510","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_510","question":"How do advances in technology change consumer spending patterns?","options":{"A":"They prevent consumers from comparing prices across different retailers.","B":"New technological products replace older versions, causing sales of outdated products to fall.","C":"They force all consumers to shop exclusively at local physical stores.","D":"They make consumer tastes permanently fixed over several decades."},"correctOption":"B","correctAnswer":"New technological products replace older versions, causing sales of outdated products to fall.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because new technological innovations (such as smartphones and tablets) attract consumer spending away from older alternatives (such as traditional desktop computers).","distractor_reasons":{"A":"Incorrect because technology, especially the internet, makes price comparison much easier for consumers.","B":"Option B is correct because new technological innovations (such as smartphones and tablets) attract consumer spending away from older alternatives (such as traditional desktop computers).","C":"Incorrect because technological advances in ecommerce encourage online shopping rather than restricting buyers to physical shops.","D":"Incorrect because rapid technological innovation accelerates changes in consumer tastes."}}},{"id":"P1_U3_MCQ_511","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_511","question":"Which factor explains why many markets have become more competitive in recent years?","options":{"A":"Higher international transport costs preventing imports from entering domestic markets.","B":"Government bans on businesses creating websites or using social media.","C":"Globalisation, improved transport links, and the growth of ecommerce.","D":"A decrease in the amount of product information available to consumers."},"correctOption":"C","correctAnswer":"Globalisation, improved transport links, and the growth of ecommerce.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because globalisation, lower international transport costs, ecommerce, and greater consumer access to product information have increased competition worldwide.","distractor_reasons":{"A":"Incorrect because transport improvements have lowered shipping costs, making imports more competitive rather than blocking them.","B":"Incorrect because online platforms and social media are widely used and have intensified competition.","C":"Option C is correct because globalisation, lower international transport costs, ecommerce, and greater consumer access to product information have increased competition worldwide.","D":"Incorrect because consumers now have far more product and price information via the internet, which increases competition."}}},{"id":"P1_U3_MCQ_512","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_512","question":"How can a business best respond to increased competition in its market?","options":{"A":"Stop conducting market research so competitors cannot copy its ideas.","B":"Raise prices above competitors' levels without improving product quality.","C":"Reduce product features while keeping prices unchanged.","D":"Improve existing products to differentiate them and keep costs low to remain price competitive."},"correctOption":"D","correctAnswer":"Improve existing products to differentiate them and keep costs low to remain price competitive.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because businesses respond to stronger competition by differentiating and improving products, developing new products, maintaining strong customer relationships, and lowering costs to offer competitive prices.","distractor_reasons":{"A":"Incorrect because stopping market research leaves the business blind to changing customer needs and rival strategies.","B":"Incorrect because raising prices without adding value will cause customers to switch to cheaper competitors.","C":"Incorrect because reducing quality or features for the same price makes the product less attractive than rival offerings.","D":"Option D is correct because businesses respond to stronger competition by differentiating and improving products, developing new products, maintaining strong customer relationships, and lowering costs to offer competitive prices."}}},{"id":"P1_U3_MCQ_513","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_513","question":"What is meant by a 'mass market'?","options":{"A":"Where a business sells standardised products to a very large number of customers.","B":"A small, specialised segment of a larger market with unique customer needs.","C":"A market where only luxury, custom-made goods are sold at premium prices.","D":"A market restricted solely to business-to-business industrial buyers."},"correctOption":"A","correctAnswer":"Where a business sells standardised products to a very large number of customers.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a mass market exists where a business sells standardised products to a very large number of consumers across the whole market.","distractor_reasons":{"A":"Option A is correct because a mass market exists where a business sells standardised products to a very large number of consumers across the whole market.","B":"Incorrect because a small, specialised segment of a larger market defines a niche market.","C":"Incorrect because luxury, custom-made products target a niche market rather than a mass market.","D":"Incorrect because mass markets typically consist of millions of everyday individual consumers."}}},{"id":"P1_U3_MCQ_514","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_514","question":"Which of the following is a key advantage of operating in a mass market?","options":{"A":"There are very few competitors selling similar products.","B":"High sales volumes can lead to high revenue and economies of scale.","C":"Products are custom-made to satisfy the exact individual preferences of every buyer.","D":"Consumers are always willing to pay exceptionally high luxury prices."},"correctOption":"B","correctAnswer":"High sales volumes can lead to high revenue and economies of scale.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because selling to a mass market generates high total sales volumes, leading to high revenue and lower average costs through economies of scale.","distractor_reasons":{"A":"Incorrect because competition in mass markets is usually intense with many rival businesses.","B":"Option B is correct because selling to a mass market generates high total sales volumes, leading to high revenue and lower average costs through economies of scale.","C":"Incorrect because mass market products are standardised rather than custom-made for individual buyers.","D":"Incorrect because mass market products must be priced affordably for the majority of consumers."}}},{"id":"P1_U3_MCQ_515","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_515","question":"What is a major disadvantage of selling in a mass market?","options":{"A":"Total sales potential is too small to allow business growth.","B":"Businesses must design completely different products for every single customer.","C":"Competition is high and it is difficult to differentiate standardised products from rivals.","D":"Brand names rarely become widely known among the general public."},"correctOption":"C","correctAnswer":"Competition is high and it is difficult to differentiate standardised products from rivals.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because mass markets attract intense competition, making it difficult to differentiate standardised products from those of competitors.","distractor_reasons":{"A":"Incorrect because limited sales potential is a disadvantage of niche markets, not mass markets.","B":"Incorrect because mass marketing avoids the cost of producing different versions for every customer.","C":"Option C is correct because mass markets attract intense competition, making it difficult to differentiate standardised products from those of competitors.","D":"Incorrect because wide promotion in mass markets usually makes brand names very well known."}}},{"id":"P1_U3_MCQ_516","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_516","question":"What is meant by a 'niche market'?","options":{"A":"The total number of consumers who buy everyday necessities in a country.","B":"A market where standardised goods are sold at the lowest possible price.","C":"A market dominated exclusively by large multinational corporations.","D":"A small, usually specialised, segment of a much larger market."},"correctOption":"D","correctAnswer":"A small, usually specialised, segment of a much larger market.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a niche market is a small, specialised sub-group or segment of a much larger market.","distractor_reasons":{"A":"Incorrect because the total number of buyers for everyday goods describes a mass market.","B":"Incorrect because standardised, low-priced goods are typical of mass markets, whereas niche products are specialised.","C":"Incorrect because large multinationals often focus on mass markets, leaving niche markets to smaller specialist firms.","D":"Option D is correct because a niche market is a small, specialised sub-group or segment of a much larger market."}}},{"id":"P1_U3_MCQ_517","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_517","question":"Which of the following is an advantage to a small business of targeting a niche market?","options":{"A":"It can avoid direct competition from large businesses that focus on mass markets.","B":"It guarantees unlimited sales volume and massive economies of scale.","C":"It completely eliminates the risk of business failure if demand falls.","D":"It requires no understanding of specific customer needs or preferences."},"correctOption":"A","correctAnswer":"It can avoid direct competition from large businesses that focus on mass markets.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because large firms often overlook small niche segments to focus on mass markets, allowing small businesses to operate with less competition and charge higher prices for specialised products.","distractor_reasons":{"A":"Option A is correct because large firms often overlook small niche segments to focus on mass markets, allowing small businesses to operate with less competition and charge higher prices for specialised products.","B":"Incorrect because niche markets have small customer numbers, limiting sales volume and economies of scale.","C":"Incorrect because niche businesses often rely on a single specialised product, increasing risk if demand drops.","D":"Incorrect because succeeding in a niche market requires a very close focus on specific consumer needs."}}},{"id":"P1_U3_MCQ_518","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_518","question":"What is a key disadvantage of operating in a niche market?","options":{"A":"Consumers refuse to pay higher prices for specialised products.","B":"Sales potential is limited due to the small number of customers, restricting growth.","C":"It is impossible to build close relationships with customers.","D":"Promotion must be broadcast to the entire population at huge expense."},"correctOption":"B","correctAnswer":"Sales potential is limited due to the small number of customers, restricting growth.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because niche markets consist of a small number of buyers, meaning total sales potential is limited and a firm must expand outside the niche to achieve major growth.","distractor_reasons":{"A":"Incorrect because niche consumers are often willing to pay higher prices for products tailored to their specific needs.","B":"Option B is correct because niche markets consist of a small number of buyers, meaning total sales potential is limited and a firm must expand outside the niche to achieve major growth.","C":"Incorrect because focusing on a small group of buyers actually makes it easier to build strong customer relationships.","D":"Incorrect because niche promotion can be narrowly targeted rather than broadcast to the mass public."}}},{"id":"P1_U3_MCQ_519","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_519","question":"What is meant by 'market segmentation'?","options":{"A":"Dividing a company's workforce into separate functional departments.","B":"Selling one identical product to every consumer in the entire economy.","C":"Breaking down a whole market into identifiable sub-groups of consumers with similar characteristics and marketing different products to each.","D":"Calculating the percentage of total industry sales earned by each competitor."},"correctOption":"C","correctAnswer":"Breaking down a whole market into identifiable sub-groups of consumers with similar characteristics and marketing different products to each.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because market segmentation involves dividing a market into distinct sub-groups (segments) of consumers who share similar characteristics or preferences and tailoring products and marketing to each group.","distractor_reasons":{"A":"Incorrect because dividing workers into departments describes organizational structure, not market segmentation.","B":"Incorrect because selling one identical product to everyone describes undifferentiated mass marketing.","C":"Option C is correct because market segmentation involves dividing a market into distinct sub-groups (segments) of consumers who share similar characteristics or preferences and tailoring products and marketing to each group.","D":"Incorrect because calculating percentages of total sales describes measuring market share."}}},{"id":"P1_U3_MCQ_520","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_520","question":"What is a 'market segment'?","options":{"A":"A geographic region where a business is legally banned from trading.","B":"The distribution channel used to transport raw materials to a factory.","C":"A specific stage in the life cycle of a consumer product.","D":"An identifiable sub-group of a whole market in which consumers share similar characteristics or preferences."},"correctOption":"D","correctAnswer":"An identifiable sub-group of a whole market in which consumers share similar characteristics or preferences.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a market segment is a distinct sub-group within a larger market whose members share similar characteristics, needs, or preferences.","distractor_reasons":{"A":"Incorrect because a market segment is a group of consumers, not a restricted trading zone.","B":"Incorrect because transporting materials relates to supply chains and distribution, not consumer grouping.","C":"Incorrect because stages such as growth and maturity belong to the product life cycle.","D":"Option D is correct because a market segment is a distinct sub-group within a larger market whose members share similar characteristics, needs, or preferences."}}},{"id":"P1_U3_MCQ_521","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_521","question":"Which of the following lists five common ways businesses segment a market?","options":{"A":"Product, price, place, promotion, and packaging.","B":"Land, labour, capital, enterprise, and profit.","C":"Age, income, location, gender, and lifestyle.","D":"Introduction, growth, maturity, saturation, and decline."},"correctOption":"C","correctAnswer":"Age, income, location, gender, and lifestyle.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because markets are commonly segmented by demographic and behavioural factors: age, income, location, gender, and lifestyle.","distractor_reasons":{"A":"Incorrect because product, price, place, and promotion are the elements of the marketing mix.","B":"Incorrect because land, labour, capital, and enterprise are the four factors of production.","C":"Option C is correct because markets are commonly segmented by demographic and behavioural factors: age, income, location, gender, and lifestyle.","D":"Incorrect because introduction, growth, maturity, and decline are stages of the product life cycle."}}},{"id":"P1_U3_MCQ_522","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_522","question":"How does segmenting a market by 'lifestyle' work?","options":{"A":"By pricing products according to the average monthly salary of consumers.","B":"By developing and marketing different products based on consumers' hobbies, interests, and ways of living.","C":"By selling waterproof clothing only in regions with high annual rainfall.","D":"By designing toys specifically for infants versus older teenagers."},"correctOption":"B","correctAnswer":"By developing and marketing different products based on consumers' hobbies, interests, and ways of living.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because lifestyle segmentation divides consumers according to how they spend their free time, their hobbies, and their daily way of living (e.g., sports enthusiasts versus indoor craft hobbyists).","distractor_reasons":{"A":"Incorrect because pricing according to earnings is segmentation by income.","B":"Option B is correct because lifestyle segmentation divides consumers according to how they spend their free time, their hobbies, and their daily way of living (e.g., sports enthusiasts versus indoor craft hobbyists).","C":"Incorrect because tailoring products to regional climate is segmentation by location.","D":"Incorrect because targeting infants versus teenagers is segmentation by age."}}},{"id":"P1_U3_MCQ_523","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_523","question":"What is a key advantage to a business of using market segmentation?","options":{"A":"It reduces production and storage costs by making only one standardised product.","B":"It eliminates the need to carry out any market research before launching products.","C":"Promotion can be directed accurately at specific consumer groups, making better use of the marketing budget.","D":"It ensures that every single market segment is large enough to be profitable."},"correctOption":"C","correctAnswer":"Promotion can be directed accurately at specific consumer groups, making better use of the marketing budget.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because market segmentation allows a business to tailor both products and promotions to each consumer group, avoiding wasted advertising spend on uninterested audiences.","distractor_reasons":{"A":"Incorrect because producing multiple product variations for different segments increases production and inventory storage costs.","B":"Incorrect because market segmentation requires extensive market research to understand each segment's characteristics.","C":"Option C is correct because market segmentation allows a business to tailor both products and promotions to each consumer group, avoiding wasted advertising spend on uninterested audiences.","D":"Incorrect because some market segments may be too small to generate enough sales to be profitable."}}},{"id":"P1_U3_MCQ_524","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_524","question":"Which of the following is a disadvantage of market segmentation?","options":{"A":"Customer needs are ignored because only one generic product is offered.","B":"Businesses cannot charge higher prices for products designed for specific segments.","C":"Promotional messages must be identical across all media platforms.","D":"Research, development, production, and storage costs increase when creating different products for multiple segments."},"correctOption":"D","correctAnswer":"Research, development, production, and storage costs increase when creating different products for multiple segments.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because developing, researching, producing, storing, and promoting different product versions for separate market segments raises business costs.","distractor_reasons":{"A":"Incorrect because market segmentation specifically aims to meet the distinct needs of different customer groups.","B":"Incorrect because tailored products often allow a business to charge higher prices, which is an advantage.","C":"Incorrect because segmentation involves adapting promotions to appeal to each target group.","D":"Option D is correct because developing, researching, producing, storing, and promoting different product versions for separate market segments raises business costs."}}},{"id":"P1_U3_MCQ_525","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_525","question":"Why might a business choose NOT to target a particular market segment?","options":{"A":"Market segmentation prevents a business from selling in mass markets.","B":"Consumers in a single segment never share any similar preferences.","C":"Legal controls prohibit businesses from advertising to specific age groups.","D":"The segment may have too few consumers to generate enough sales to be profitable."},"correctOption":"D","correctAnswer":"The segment may have too few consumers to generate enough sales to be profitable.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because if a market segment contains only a small number of potential buyers, the revenue earned may not cover the extra costs of developing and marketing a specialised product.","distractor_reasons":{"A":"Incorrect because large businesses often target multiple segments simultaneously across a mass market.","B":"Incorrect because by definition, consumers in a market segment share similar characteristics or preferences.","C":"Incorrect because segmenting by age is standard business practice, provided promotions follow consumer protection rules.","D":"Option D is correct because if a market segment contains only a small number of potential buyers, the revenue earned may not cover the extra costs of developing and marketing a specialised product."}}},{"id":"P1_U3_MCQ_526","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_526","question":"What is meant by 'market research'?","options":{"A":"The process of manufacturing new prototypes in a factory laboratory.","B":"The process of gathering, analysing, and interpreting information about a market.","C":"The legal registration of a brand name and logo with the government.","D":"The physical distribution of finished goods to wholesale warehouses."},"correctOption":"B","correctAnswer":"The process of gathering, analysing, and interpreting information about a market.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because market research is the systematic process of gathering, analysing, and interpreting information about a market, consumers, and competitors.","distractor_reasons":{"A":"Incorrect because building prototypes is part of product research and development (R&D), not market research.","B":"Option B is correct because market research is the systematic process of gathering, analysing, and interpreting information about a market, consumers, and competitors.","C":"Incorrect because registering a brand name or trademark is legal intellectual property protection.","D":"Incorrect because moving goods to warehouses is logistics and distribution ('place')."}}},{"id":"P1_U3_MCQ_527","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_527","question":"What distinguishes a 'product-oriented' business from a 'market-oriented' business?","options":{"A":"A product-oriented business conducts extensive customer surveys before designing any product.","B":"A product-oriented business sells only intangible services rather than physical goods.","C":"A product-oriented business focuses on the product and production process first, hoping customers will buy it afterward.","D":"A product-oriented business operates exclusively in niche markets."},"correctOption":"C","correctAnswer":"A product-oriented business focuses on the product and production process first, hoping customers will buy it afterward.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a product-oriented business concentrates on designing and manufacturing a product based on its own technical expertise first, and then tries to persuade customers to buy it.","distractor_reasons":{"A":"Incorrect because researching customer needs before developing a product defines a market-oriented business.","B":"Incorrect because product-oriented firms commonly produce physical, technical, or traditional goods.","C":"Option C is correct because a product-oriented business concentrates on designing and manufacturing a product based on its own technical expertise first, and then tries to persuade customers to buy it.","D":"Incorrect because either orientation can exist in different market structures, though market orientation is safer in competitive markets."}}},{"id":"P1_U3_MCQ_528","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_528","question":"Why is it important for a business to carry out market research before launching a new product?","options":{"A":"It guarantees that competitors will not lower their prices.","B":"It eliminates all variable costs of manufacturing the new product.","C":"It allows the business to avoid paying government taxes on sales revenue.","D":"It reduces the risk of new product failure by identifying whether consumers will buy it and at what price."},"correctOption":"D","correctAnswer":"It reduces the risk of new product failure by identifying whether consumers will buy it and at what price.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because market research reduces the risk and uncertainty of launching a new product by identifying consumer needs, willingness to buy, acceptable price levels, and competitor strength.","distractor_reasons":{"A":"Incorrect because market research gathers information about competitors but cannot control their pricing decisions.","B":"Incorrect because variable production costs (such as raw materials) still occur regardless of research.","C":"Incorrect because taxes apply to business profits and sales irrespective of market research.","D":"Option D is correct because market research reduces the risk and uncertainty of launching a new product by identifying consumer needs, willingness to buy, acceptable price levels, and competitor strength."}}},{"id":"P1_U3_MCQ_529","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_529","question":"What is 'primary market research' (field research)?","options":{"A":"Research carried out solely by businesses operating in the primary sector of industry.","B":"The use of statistics already published by government departments and trade journals.","C":"The collection and collation of original data via direct contact with potential or existing consumers.","D":"Analysing historical sales records held inside the company's finance department."},"correctOption":"C","correctAnswer":"The collection and collation of original data via direct contact with potential or existing consumers.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because primary (field) research involves collecting brand-new, original data directly from potential or existing customers for a specific business purpose.","distractor_reasons":{"A":"Incorrect because 'primary' in market research means first-hand original data, not farming or mining.","B":"Incorrect because using already published information describes secondary (desk) research.","C":"Option C is correct because primary (field) research involves collecting brand-new, original data directly from potential or existing customers for a specific business purpose.","D":"Incorrect because internal historical sales records are an internal source of secondary data."}}},{"id":"P1_U3_MCQ_530","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_530","question":"Which of the following is a key advantage of primary market research over secondary market research?","options":{"A":"It is always cheaper and faster to collect than existing data.","B":"The data is up to date, tailored to the specific needs of the business, and unavailable to competitors.","C":"It provides complete nationwide population census figures free of charge.","D":"It requires no planning or sample selection before collecting data."},"correctOption":"B","correctAnswer":"The data is up to date, tailored to the specific needs of the business, and unavailable to competitors.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because primary research is collected first-hand for the business's specific problem, is completely up to date, and remains exclusive to the business that conducted it.","distractor_reasons":{"A":"Incorrect because primary research is usually more expensive and time-consuming than secondary research.","B":"Option B is correct because primary research is collected first-hand for the business's specific problem, is completely up to date, and remains exclusive to the business that conducted it.","C":"Incorrect because nationwide census figures are secondary data collected by governments.","D":"Incorrect because primary research requires careful planning, questionnaire design, and sampling."}}},{"id":"P1_U3_MCQ_531","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_531","question":"What is a major disadvantage of primary market research?","options":{"A":"The information is automatically available to all rival businesses.","B":"The data is always several years out of date before it is analysed.","C":"It can be expensive and time-consuming to collect and collate.","D":"It cannot be used to find out consumers' opinions about a new product."},"correctOption":"C","correctAnswer":"It can be expensive and time-consuming to collect and collate.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because designing surveys, interviewing respondents, and analysing original data requires significant time and financial expenditure.","distractor_reasons":{"A":"Incorrect because exclusive ownership of the findings is an advantage of primary research, not a disadvantage.","B":"Incorrect because being out of date is a common disadvantage of secondary data, whereas primary data is current.","C":"Option C is correct because designing surveys, interviewing respondents, and analysing original data requires significant time and financial expenditure.","D":"Incorrect because discovering consumer opinions and preferences is one of the main strengths of primary research."}}},{"id":"P1_U3_MCQ_532","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_532","question":"Which of the following are all methods of primary market research?","options":{"A":"Government census reports, trade magazines, and competitor websites.","B":"Market research agency reports, newspaper articles, and internal sales records.","C":"Focus groups, trade journals, and national income statistics.","D":"Questionnaires, interviews, focus groups, and observation."},"correctOption":"D","correctAnswer":"Questionnaires, interviews, focus groups, and observation.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because questionnaires (surveys), interviews, focus groups, and observation all involve collecting original, first-hand data directly from consumers.","distractor_reasons":{"A":"Incorrect because census reports, trade magazines, and competitor websites are all secondary research sources.","B":"Incorrect because published market reports, newspapers, and internal records are secondary data.","C":"Incorrect because trade journals and national income statistics are secondary sources.","D":"Option D is correct because questionnaires (surveys), interviews, focus groups, and observation all involve collecting original, first-hand data directly from consumers."}}},{"id":"P1_U3_MCQ_533","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_533","question":"What is an advantage of using 'online questionnaires' compared to postal questionnaires?","options":{"A":"They are faster and cheaper to distribute and analyse, and can reach respondents worldwide.","B":"They guarantee a 100% response rate from every person who receives a link.","C":"They allow an interviewer to explain ambiguous questions face-to-face.","D":"They effectively reach consumers who have no access to the internet."},"correctOption":"A","correctAnswer":"They are faster and cheaper to distribute and analyse, and can reach respondents worldwide.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because online questionnaires eliminate printing and postage costs, reach a wide geographic audience quickly, and allow automated data collation.","distractor_reasons":{"A":"Option A is correct because online questionnaires eliminate printing and postage costs, reach a wide geographic audience quickly, and allow automated data collation.","B":"Incorrect because online surveys still suffer from non-response as many people ignore survey links.","C":"Incorrect because questionnaires are self-completed without an interviewer present to clarify questions.","D":"Incorrect because lack of internet access among some groups is actually a disadvantage of online questionnaires."}}},{"id":"P1_U3_MCQ_534","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_534","question":"What is a disadvantage of using 'questionnaires' as a primary research method?","options":{"A":"It is impossible to ask closed 'Yes/No' questions on a questionnaire.","B":"Respondents cannot ask for clarification if a question is ambiguous, and response rates can be low.","C":"Questionnaires can only ever be conducted with one person per week.","D":"They always suffer from direct interviewer body-language bias."},"correctOption":"B","correctAnswer":"Respondents cannot ask for clarification if a question is ambiguous, and response rates can be low.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because self-completed questionnaires offer no opportunity to explain unclear questions or probe deeper, and postal or online surveys often suffer from low response rates.","distractor_reasons":{"A":"Incorrect because closed questions are very commonly used in questionnaires.","B":"Option B is correct because self-completed questionnaires offer no opportunity to explain unclear questions or probe deeper, and postal or online surveys often suffer from low response rates.","C":"Incorrect because questionnaires can be distributed to thousands of people simultaneously.","D":"Incorrect because interviewer bias occurs during face-to-face or phone interviews rather than self-completed questionnaires."}}},{"id":"P1_U3_MCQ_535","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_535","question":"What is a key advantage of using 'interviews' rather than self-completed questionnaires?","options":{"A":"Interviews are much cheaper and faster to conduct across large samples.","B":"Interviews completely eliminate any possibility of interviewer bias.","C":"The interviewer can explain misunderstood questions and ask follow-up questions for detailed answers.","D":"Interviews require no trained staff to ask questions or record answers."},"correctOption":"C","correctAnswer":"The interviewer can explain misunderstood questions and ask follow-up questions for detailed answers.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because interviews allow two-way interaction, enabling the interviewer to clarify confusing questions, build rapport, and ask follow-up questions.","distractor_reasons":{"A":"Incorrect because interviews are time-consuming and expensive, leading to smaller sample sizes.","B":"Incorrect because interviewer bias (leading the interviewee) is a major disadvantage of interviews.","C":"Option C is correct because interviews allow two-way interaction, enabling the interviewer to clarify confusing questions, build rapport, and ask follow-up questions.","D":"Incorrect because effective interviews require skilled interviewers to avoid bias and build trust."}}},{"id":"P1_U3_MCQ_536","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_536","question":"What is meant by 'interviewer bias' in primary market research?","options":{"A":"When a respondent refuses to answer any open-ended questions.","B":"When government statistics contain outdated population figures.","C":"When a sample is too large to be analysed on a computer.","D":"When the interviewer consciously or subconsciously leads the interviewee into answering in a certain way."},"correctOption":"D","correctAnswer":"When the interviewer consciously or subconsciously leads the interviewee into answering in a certain way.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because interviewer bias happens when the interviewer's tone, wording, or reaction influences the respondent's answers, distorting the research results.","distractor_reasons":{"A":"Incorrect because refusal to answer is non-response rather than interviewer bias.","B":"Incorrect because outdated government statistics relate to secondary data accuracy.","C":"Incorrect because a large sample improves accuracy rather than causing interviewer bias.","D":"Option D is correct because interviewer bias happens when the interviewer's tone, wording, or reaction influences the respondent's answers, distorting the research results."}}},{"id":"P1_U3_MCQ_537","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_537","question":"What is a 'focus group' in market research?","options":{"A":"A group of people representative of the target market brought together to discuss opinions about products and promotions.","B":"A team of company directors who set the annual marketing budget.","C":"A random crowd of passers-by counted silently by a researcher in a shopping mall.","D":"A panel of government officials who approve product safety labels."},"correctOption":"A","correctAnswer":"A group of people representative of the target market brought together to discuss opinions about products and promotions.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a focus group consists of selected members of the target market who participate in a guided group discussion to share detailed views on products, packaging, or adverts.","distractor_reasons":{"A":"Option A is correct because a focus group consists of selected members of the target market who participate in a guided group discussion to share detailed views on products, packaging, or adverts.","B":"Incorrect because directors setting budgets are internal decision-makers, not a market research sample.","C":"Incorrect because silently watching and counting shoppers describes observation, not a focus group.","D":"Incorrect because government safety regulators are external authorities, not consumer focus groups."}}},{"id":"P1_U3_MCQ_538","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_538","question":"What is a key disadvantage of using focus groups for primary market research?","options":{"A":"Participants are forbidden from interacting with one another during the session.","B":"Discussion can be biased if dominant or argumentative individuals influence other members' opinions.","C":"They provide zero qualitative insight into why consumers prefer certain features.","D":"They always cost more per person than conducting individual one-to-one interviews."},"correctOption":"B","correctAnswer":"Discussion can be biased if dominant or argumentative individuals influence other members' opinions.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because outspoken or dominant individuals in a focus group can sway the discussion and pressure quieter participants, causing biased results.","distractor_reasons":{"A":"Incorrect because interaction among participants is a core feature and advantage of focus groups.","B":"Option B is correct because outspoken or dominant individuals in a focus group can sway the discussion and pressure quieter participants, causing biased results.","C":"Incorrect because gaining detailed qualitative opinions is the main strength of focus groups.","D":"Incorrect because focus groups are usually quicker and cheaper than interviewing each person individually."}}},{"id":"P1_U3_MCQ_539","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_539","question":"What is 'observation' as a method of primary market research?","options":{"A":"Reading competitor websites to record their current selling prices.","B":"Sending postal surveys to households asking about their weekly spending.","C":"Watching and recording consumer behaviour and actions when buying or choosing between products.","D":"Interviewing customers in depth about their emotional feelings toward a brand."},"correctOption":"C","correctAnswer":"Watching and recording consumer behaviour and actions when buying or choosing between products.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because observation collects primary data by watching and recording actual consumer behaviour (such as footfall or shelf selection) without questioning them.","distractor_reasons":{"A":"Incorrect because checking competitor websites is secondary desk research.","B":"Incorrect because sending surveys uses questionnaires rather than observation.","C":"Option C is correct because observation collects primary data by watching and recording actual consumer behaviour (such as footfall or shelf selection) without questioning them.","D":"Incorrect because observation records actions but cannot uncover underlying motives or feelings without questioning."}}},{"id":"P1_U3_MCQ_540","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_540","question":"What is the main limitation of observation as a market research method?","options":{"A":"Consumers frequently lie to researchers during observation.","B":"It is illegal to watch shoppers in public retail stores.","C":"It cannot record how many customers enter a store or look at a display.","D":"Because consumers are not questioned, the underlying reasons for their actions cannot be identified."},"correctOption":"D","correctAnswer":"Because consumers are not questioned, the underlying reasons for their actions cannot be identified.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because observation only reveals what consumers do (their actions), not why they behaved that way, since no questions are asked.","distractor_reasons":{"A":"Incorrect because an advantage of observation is that shoppers act naturally rather than trying to please or mislead an interviewer.","B":"Incorrect because observing customer traffic and behaviour in stores is standard, legal market research practice.","C":"Incorrect because counting shoppers and tracking display views is exactly what observation does well.","D":"Option D is correct because observation only reveals what consumers do (their actions), not why they behaved that way, since no questions are asked."}}},{"id":"P1_U3_MCQ_541","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_541","question":"What is meant by a 'sample' in market research?","options":{"A":"Every single consumer who lives within a country's borders.","B":"The group of people selected to respond to a market research exercise, representing the target population.","C":"A free miniature product given away as part of a sales promotion.","D":"A secondary report published by a government statistical office."},"correctOption":"B","correctAnswer":"The group of people selected to respond to a market research exercise, representing the target population.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a sample is a smaller group of people selected from the target market population to participate in market research so their views represent the whole group.","distractor_reasons":{"A":"Incorrect because surveying every person in a country is a full population census, not a sample.","B":"Option B is correct because a sample is a smaller group of people selected from the target market population to participate in market research so their views represent the whole group.","C":"Incorrect because a promotional giveaway is a free sample product, not a research sample.","D":"Incorrect because a government report is a secondary data source."}}},{"id":"P1_U3_MCQ_542","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_542","question":"How does 'quota sampling' differ from 'random sampling'?","options":{"A":"Quota sampling selects people entirely by chance, whereas random sampling selects by age or gender.","B":"Quota sampling selects people based on specific characteristics (such as age or income), whereas random sampling selects people entirely by chance.","C":"Quota sampling surveys the entire population, whereas random sampling surveys only business owners.","D":"Quota sampling uses only secondary data, whereas random sampling uses only primary data."},"correctOption":"B","correctAnswer":"Quota sampling selects people based on specific characteristics (such as age or income), whereas random sampling selects people entirely by chance.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because random sampling gives every member of the population an equal chance of selection purely by chance, whereas quota sampling selects specific proportions of people based on characteristics like age, gender, or income.","distractor_reasons":{"A":"Incorrect because this reverses the definitions of random sampling and quota sampling.","B":"Option B is correct because random sampling gives every member of the population an equal chance of selection purely by chance, whereas quota sampling selects specific proportions of people based on characteristics like age, gender, or income.","C":"Incorrect because both are sampling methods that survey a subset of the target population rather than everyone.","D":"Incorrect because both random and quota sampling are used to select respondents for primary research."}}},{"id":"P1_U3_MCQ_543","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_543","question":"Why is sampling useful to businesses conducting market research?","options":{"A":"It guarantees that market research results will always be 100% accurate.","B":"It removes the need to design clear, unbiased questionnaire questions.","C":"It saves time and money compared to surveying the entire target population while still providing representative results.","D":"It allows a business to avoid analysing the data after collection."},"correctOption":"C","correctAnswer":"It saves time and money compared to surveying the entire target population while still providing representative results.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because surveying every consumer in a market is impractical and costly; a well-chosen sample saves time and money while representing the target population.","distractor_reasons":{"A":"Incorrect because sampling always carries a margin of error and never guarantees 100% accuracy.","B":"Incorrect because poorly worded questions will still distort results regardless of how the sample is chosen.","C":"Option C is correct because surveying every consumer in a market is impractical and costly; a well-chosen sample saves time and money while representing the target population.","D":"Incorrect because collected sample data must still be collated, presented, and analysed."}}},{"id":"P1_U3_MCQ_544","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_544","question":"What is 'secondary market research' (desk research)?","options":{"A":"Collecting brand-new data by interviewing customers outside a retail shop.","B":"Research conducted only after a product has reached the decline stage.","C":"Research carried out exclusively by manufacturing firms in the secondary sector.","D":"Using information that has already been collected and is available for use by others."},"correctOption":"D","correctAnswer":"Using information that has already been collected and is available for use by others.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because secondary (desk) research uses existing data that was previously collected for another purpose, either internally or by external organisations.","distractor_reasons":{"A":"Incorrect because interviewing customers directly collects original data, which is primary research.","B":"Incorrect because secondary research is typically the first step before primary research at any product stage.","C":"Incorrect because 'secondary' refers to second-hand data, not the secondary manufacturing sector.","D":"Option D is correct because secondary (desk) research uses existing data that was previously collected for another purpose, either internally or by external organisations."}}},{"id":"P1_U3_MCQ_545","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_545","question":"What is a major advantage of secondary market research?","options":{"A":"The statistics are always guaranteed to reflect yesterday's consumer preferences.","B":"The data is always collected exclusively for the business's specific new product.","C":"Competitors are legally prevented from accessing the same published reports.","D":"It is usually quicker and cheaper to obtain than conducting primary research."},"correctOption":"D","correctAnswer":"It is usually quicker and cheaper to obtain than conducting primary research.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because secondary data already exists (often free or low-cost online or in government publications), making it much faster and cheaper to gather than primary research.","distractor_reasons":{"A":"Incorrect because secondary data can be several years out of date.","B":"Incorrect because secondary data was collected for other purposes and may not be specific to the business's needs.","C":"Incorrect because external secondary data is generally available to all competing businesses.","D":"Option D is correct because secondary data already exists (often free or low-cost online or in government publications), making it much faster and cheaper to gather than primary research."}}},{"id":"P1_U3_MCQ_546","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_546","question":"What is a common disadvantage of using government sources (such as a national census) for secondary market research?","options":{"A":"They are extremely expensive for a small business to access.","B":"They may be out of date (e.g., collected every 10 years) and are not specific to an individual product or brand.","C":"They provide information only about a single town rather than national regions.","D":"They rely entirely on biased opinions from focus groups."},"correctOption":"B","correctAnswer":"They may be out of date (e.g., collected every 10 years) and are not specific to an individual product or brand.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because government censuses are infrequent (often every 10 years) so data can be outdated, and they provide broad demographic data rather than product-specific market insights.","distractor_reasons":{"A":"Incorrect because government statistics are usually free and widely accessible online or in libraries.","B":"Option B is correct because government censuses are infrequent (often every 10 years) so data can be outdated, and they provide broad demographic data rather than product-specific market insights.","C":"Incorrect because government sources cover both national and regional levels.","D":"Incorrect because government statistics are based on official demographic and economic records, not focus groups."}}},{"id":"P1_U3_MCQ_547","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_547","question":"Which statement describes a disadvantage of using 'market reports' produced by specialist agencies?","options":{"A":"They never contain any data about industry trends or competitors.","B":"They are written purely for entertainment rather than business analysis.","C":"They can be expensive to purchase and may become out of date quickly in fast-changing markets.","D":"They are illegal for businesses to use when planning a marketing strategy."},"correctOption":"C","correctAnswer":"They can be expensive to purchase and may become out of date quickly in fast-changing markets.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because specialist market research agencies charge high fees for detailed market reports, and reports not updated annually can quickly become outdated.","distractor_reasons":{"A":"Incorrect because detailed industry and competitor data is precisely what market reports provide.","B":"Incorrect because market reports are professional analytical documents created for businesses.","C":"Option C is correct because specialist market research agencies charge high fees for detailed market reports, and reports not updated annually can quickly become outdated.","D":"Incorrect because purchasing commercial market reports is a standard, legal research practice."}}},{"id":"P1_U3_MCQ_548","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_548","question":"What is a limitation of using 'trade magazines' as a source of secondary market research?","options":{"A":"They contain zero information about the industry in which the business operates.","B":"They are strictly confidential and cannot be read by small business owners.","C":"They are always published once every ten years like a national census.","D":"Articles and opinions may be influenced by major advertisers and lack verified research methods."},"correctOption":"D","correctAnswer":"Articles and opinions may be influenced by major advertisers and lack verified research methods.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because trade magazines do not use rigorous research agency methodologies and their editorial opinions may be biased toward major industry advertisers.","distractor_reasons":{"A":"Incorrect because trade magazines focus specifically on news and trends within a particular industry.","B":"Incorrect because trade magazines are publicly available to managers and businesses in that sector.","C":"Incorrect because trade magazines are typically published weekly or monthly, not every ten years.","D":"Option D is correct because trade magazines do not use rigorous research agency methodologies and their editorial opinions may be biased toward major industry advertisers."}}},{"id":"P1_U3_MCQ_549","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_549","question":"How does 'sample size' influence the accuracy of primary market research data?","options":{"A":"A larger sample generally produces more accurate and reliable results, though at a higher cost.","B":"A smaller sample always produces more accurate results because fewer opinions conflict.","C":"Sample size has no effect on accuracy as long as secondary data is ignored.","D":"A sample size of fewer than five people is ideal for nationwide mass markets."},"correctOption":"A","correctAnswer":"A larger sample generally produces more accurate and reliable results, though at a higher cost.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because surveying a larger number of representative respondents reduces sampling error and increases reliability, though it increases research costs.","distractor_reasons":{"A":"Option A is correct because surveying a larger number of representative respondents reduces sampling error and increases reliability, though it increases research costs.","B":"Incorrect because a very small sample is unlikely to reflect the diverse views of the whole target market.","C":"Incorrect because sample size is one of the primary determinants of survey reliability.","D":"Incorrect because a sample of fewer than five people is far too small to represent a nationwide mass market."}}},{"id":"P1_U3_MCQ_550","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_550","question":"Which set of factors directly affects the accuracy and reliability of market research data?","options":{"A":"Span of control, chain of command, and leadership style.","B":"Sample selection, sample size, question wording, bias, and age of the information.","C":"Channel of distribution, packaging colour, and brand logo.","D":"Import tariffs, exchange rates, and factory location."},"correctOption":"B","correctAnswer":"Sample selection, sample size, question wording, bias, and age of the information.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because data accuracy depends on how representative the sample is, sample size, clear unbiased question wording, absence of researcher/source bias, and how current the data is.","distractor_reasons":{"A":"Incorrect because these are organizational management concepts rather than market research factors.","B":"Option B is correct because data accuracy depends on how representative the sample is, sample size, clear unbiased question wording, absence of researcher/source bias, and how current the data is.","C":"Incorrect because these are elements of the marketing mix rather than research reliability factors.","D":"Incorrect because these are external economic and operational factors."}}},{"id":"P1_U3_MCQ_551","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_551","question":"What is meant by the term 'brand image'?","options":{"A":"The legal contract signed between a manufacturer and a wholesaler.","B":"The physical cardboard box used to protect a product during transport.","C":"An image or identity given to a product which distinguishes it from competitors' brands.","D":"The percentage of total market sales held by a single business."},"correctOption":"C","correctAnswer":"An image or identity given to a product which distinguishes it from competitors' brands.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because brand image is the unique identity and perception created for a product in the minds of consumers that differentiates it from rival products.","distractor_reasons":{"A":"Incorrect because a contract between channel members is a distribution agreement, not brand image.","B":"Incorrect because the physical container is packaging, which supports brand image rather than defining it.","C":"Option C is correct because brand image is the unique identity and perception created for a product in the minds of consumers that differentiates it from rival products.","D":"Incorrect because percentage of total sales defines market share."}}},{"id":"P1_U3_MCQ_552","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_552","question":"What is 'brand loyalty'?","options":{"A":"When a business refuses to change its product design for fifty years.","B":"When retailers agree to stock only one manufacturer's products.","C":"When a government protects a company's logo from being copied.","D":"When consumers keep buying the same brand instead of choosing a competitor's product."},"correctOption":"D","correctAnswer":"When consumers keep buying the same brand instead of choosing a competitor's product.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because brand loyalty occurs when consumers repeatedly choose and purchase the same brand over rival brands.","distractor_reasons":{"A":"Incorrect because failing to update products usually causes declining sales rather than loyalty.","B":"Incorrect because retailer stocking decisions relate to distribution channels, not consumer brand loyalty.","C":"Incorrect because legal protection of a logo is trademark law, not brand loyalty.","D":"Option D is correct because brand loyalty occurs when consumers repeatedly choose and purchase the same brand over rival brands."}}},{"id":"P1_U3_MCQ_553","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_553","question":"How does a strong brand image benefit a business?","options":{"A":"It prevents any new competitors from ever entering the industry.","B":"The business no longer needs to maintain consistent product quality.","C":"It eliminates all costs of advertising and promotion permanently.","D":"Consumers become less price sensitive and are often willing to pay higher prices than for unbranded goods."},"correctOption":"D","correctAnswer":"Consumers become less price sensitive and are often willing to pay higher prices than for unbranded goods.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a strong brand image builds trust and desirability, making consumers less price sensitive and willing to pay higher prices than for unbranded equivalents.","distractor_reasons":{"A":"Incorrect because strong brand loyalty makes entry harder for rivals but does not legally block them.","B":"Incorrect because poor quality quickly destroys a brand's reputation and image.","C":"Incorrect because strong brands require ongoing advertising to maintain and reinforce their image.","D":"Option D is correct because a strong brand image builds trust and desirability, making consumers less price sensitive and willing to pay higher prices than for unbranded equivalents."}}},{"id":"P1_U3_MCQ_554","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_554","question":"Which of the following correctly describes the main roles of 'packaging'?","options":{"A":"To increase shipping weight, hide product ingredients, and raise manufacturing costs.","B":"To protect the product, promote it, support the brand image, and provide required product information.","C":"To replace the need for distribution channels and retail stores.","D":"To prevent consumers from comparing the product with competing brands."},"correctOption":"B","correctAnswer":"To protect the product, promote it, support the brand image, and provide required product information.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because packaging performs four key roles: protecting the product during transport/use, attracting customers (promotion), reinforcing brand image, and displaying legal/usage information.","distractor_reasons":{"A":"Incorrect because packaging must legally show ingredients/allergens on food items and should minimise unnecessary weight and cost.","B":"Option B is correct because packaging performs four key roles: protecting the product during transport/use, attracting customers (promotion), reinforcing brand image, and displaying legal/usage information.","C":"Incorrect because packaging facilitates transport through distribution channels rather than replacing them.","D":"Incorrect because packaging displays product details that help consumers compare items."}}},{"id":"P1_U3_MCQ_555","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_555","question":"What is meant by a 'Unique Selling Point (USP)'?","options":{"A":"The single retail shop where a product is exclusively sold.","B":"The lowest possible price at which a product can break even.","C":"The special feature of a product that differentiates it from the products of competitors.","D":"A one-day sales promotion offering free samples to passers-by."},"correctOption":"C","correctAnswer":"The special feature of a product that differentiates it from the products of competitors.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a Unique Selling Point (USP) is a distinctive feature, design, or benefit of a product that sets it apart from competing products.","distractor_reasons":{"A":"Incorrect because where a product is sold relates to 'place' (distribution), not its USP.","B":"Incorrect because break-even price is a financial/pricing calculation, not a product feature.","C":"Option C is correct because a Unique Selling Point (USP) is a distinctive feature, design, or benefit of a product that sets it apart from competing products.","D":"Incorrect because free samples are a short-term sales promotion method."}}},{"id":"P1_U3_MCQ_556","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_556","question":"Which statement describes an advantage of developing new products?","options":{"A":"It requires zero market research or technical development expenditure.","B":"It guarantees that every new launch will immediately earn a high profit.","C":"It prevents competitors from ever developing similar technology.","D":"It creates diversification, reducing the business's reliance on existing products and markets."},"correctOption":"D","correctAnswer":"It creates diversification, reducing the business's reliance on existing products and markets.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because developing new products broadens a firm's product range (diversification), reducing dependence on existing products whose sales may eventually decline.","distractor_reasons":{"A":"Incorrect because high research and development costs are a major disadvantage of new product development.","B":"Incorrect because new products carry a high risk of low sales and financial failure.","C":"Incorrect because successful new products are often quickly copied by competitors.","D":"Option D is correct because developing new products broadens a firm's product range (diversification), reducing dependence on existing products whose sales may eventually decline."}}},{"id":"P1_U3_MCQ_557","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_557","question":"What is a major disadvantage of developing new products?","options":{"A":"It prevents the business from entering export markets in other countries.","B":"It damages the business's reputation for being innovative and creative.","C":"High research and development costs and the risk that consumer demand may be too low to make a profit.","D":"It forces the business to withdraw all its profitable existing products."},"correctOption":"C","correctAnswer":"High research and development costs and the risk that consumer demand may be too low to make a profit.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because developing new products involves expensive market research and technical R&D, with no guarantee that enough consumers will buy the product to cover those costs.","distractor_reasons":{"A":"Incorrect because developing products tailored to foreign tastes helps firms enter export markets.","B":"Incorrect because successful new products actually enhance a brand's reputation for innovation.","C":"Option C is correct because developing new products involves expensive market research and technical R&D, with no guarantee that enough consumers will buy the product to cover those costs.","D":"Incorrect because businesses routinely sell new products alongside existing profitable lines."}}},{"id":"P1_U3_MCQ_558","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_558","question":"What are the four main stages of the 'product life cycle' in chronological order?","options":{"A":"Research, testing, pricing, and advertising.","B":"Introduction, growth, maturity, and decline.","C":"Primary, secondary, tertiary, and quaternary.","D":"Planning, organising, commanding, and controlling."},"correctOption":"B","correctAnswer":"Introduction, growth, maturity, and decline.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the standard product life cycle traces a product's sales from Introduction, through Growth and Maturity, to Decline.","distractor_reasons":{"A":"Incorrect because these are pre-launch marketing activities rather than life cycle stages.","B":"Option B is correct because the standard product life cycle traces a product's sales from Introduction, through Growth and Maturity, to Decline.","C":"Incorrect because these are economic sectors of industry.","D":"Incorrect because these are the functions of management."}}},{"id":"P1_U3_MCQ_559","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_559","question":"Which characteristics best describe the 'introduction' stage of the product life cycle?","options":{"A":"Sales reach their peak, competition is intense, and prices are heavily discounted.","B":"Sales fall rapidly as the product becomes technologically obsolete.","C":"Sales grow slowly because few consumers are aware of the product, and profit is often low or negative due to high development and launch costs.","D":"Sales grow at their fastest rate and brand loyalty is already firmly established."},"correctOption":"C","correctAnswer":"Sales grow slowly because few consumers are aware of the product, and profit is often low or negative due to high development and launch costs.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because at the introduction stage consumer awareness is low so sales grow slowly, while heavy launch advertising and unrecovered R&D costs keep profit low or negative.","distractor_reasons":{"A":"Incorrect because peak sales and intense competition characterize the maturity stage.","B":"Incorrect because rapidly falling sales due to obsolescence describe the decline stage.","C":"Option C is correct because at the introduction stage consumer awareness is low so sales grow slowly, while heavy launch advertising and unrecovered R&D costs keep profit low or negative.","D":"Incorrect because rapid sales acceleration describes the growth stage."}}},{"id":"P1_U3_MCQ_560","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_560","question":"What happens during the 'maturity' stage of the product life cycle?","options":{"A":"The product is launched for the first time and consumers have never heard of it.","B":"Sales fall sharply and the product is immediately withdrawn from sale.","C":"There are zero competitors in the market and development costs have not yet been recovered.","D":"Sales growth slows down and reaches a peak, competition becomes intense, and extension strategies may be considered."},"correctOption":"D","correctAnswer":"Sales growth slows down and reaches a peak, competition becomes intense, and extension strategies may be considered.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because in the maturity stage sales level off at their peak, competition is fierce, and businesses use heavy promotion or extension strategies to maintain sales.","distractor_reasons":{"A":"Incorrect because initial launch with low awareness describes the introduction stage.","B":"Incorrect because sharp falls and withdrawal occur in the decline stage.","C":"Incorrect because absence of rivals and unrecovered R&D occur in the introduction stage.","D":"Option D is correct because in the maturity stage sales level off at their peak, competition is fierce, and businesses use heavy promotion or extension strategies to maintain sales."}}},{"id":"P1_U3_MCQ_561","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_561","question":"What is the purpose of an 'extension strategy' in the product life cycle?","options":{"A":"To keep a product at the maturity stage of its life cycle and prolong its profitable sales before decline sets in.","B":"To speed up the decline stage so a product can be withdrawn earlier.","C":"To increase the length of the chain of command in the marketing department.","D":"To delay launching a newly developed product until competitors leave the market."},"correctOption":"A","correctAnswer":"To keep a product at the maturity stage of its life cycle and prolong its profitable sales before decline sets in.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because extension strategies aim to boost demand and keep a product in the maturity stage for longer, postponing decline and avoiding immediate R&D costs for a replacement.","distractor_reasons":{"A":"Option A is correct because extension strategies aim to boost demand and keep a product in the maturity stage for longer, postponing decline and avoiding immediate R&D costs for a replacement.","B":"Incorrect because extension strategies aim to prevent or delay decline, not accelerate it.","C":"Incorrect because chain of command relates to organizational structure, not the product life cycle.","D":"Incorrect because extension strategies apply to existing mature products rather than delaying new launches."}}},{"id":"P1_U3_MCQ_562","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_562","question":"Which of the following are recognised product life cycle extension strategies?","options":{"A":"Increasing unit production costs, reducing product quality, and stopping all advertising.","B":"Entering new markets, finding new uses for the product, adapting the product or packaging, and increasing advertising/sales promotion.","C":"Conducting random sampling, using trade magazines, and hiring external auditors.","D":"Downsizing the workforce, delayering management, and selling off factories."},"correctOption":"B","correctAnswer":"Entering new markets, finding new uses for the product, adapting the product or packaging, and increasing advertising/sales promotion.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because the five core extension strategies are selling into new markets, finding new uses, adapting the product, adapting the packaging, and increasing advertising or sales promotion.","distractor_reasons":{"A":"Incorrect because raising costs, cutting quality, and halting promotion would accelerate product decline.","B":"Option B is correct because the five core extension strategies are selling into new markets, finding new uses, adapting the product, adapting the packaging, and increasing advertising or sales promotion.","C":"Incorrect because these are market research and accounting activities, not product extension strategies.","D":"Incorrect because these are organizational restructuring actions rather than marketing extension strategies."}}},{"id":"P1_U3_MCQ_563","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_563","question":"What is a key advantage of finding 'new uses' for an existing product as an extension strategy?","options":{"A":"No advertising or promotion is needed to inform consumers about the new use.","B":"Competitors are legally barred from copying the new use.","C":"No physical changes to the product are required, which helps keep production costs down.","D":"It guarantees that existing customers will double their weekly purchases immediately."},"correctOption":"C","correctAnswer":"No physical changes to the product are required, which helps keep production costs down.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because promoting a new use for an already well-known product requires no costly redesign or manufacturing changes.","distractor_reasons":{"A":"Incorrect because new advertising and promotion are essential to inform consumers about the alternative use.","B":"Incorrect because rival firms can also promote the same alternative use for their versions.","C":"Option C is correct because promoting a new use for an already well-known product requires no costly redesign or manufacturing changes.","D":"Incorrect because consumers may be reluctant to change how they use a familiar product, so sales increases are not guaranteed."}}},{"id":"P1_U3_MCQ_564","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_564","question":"How is 'cost-plus pricing' determined?","options":{"A":"Setting the price lower than competitors' prices to enter a new market quickly.","B":"Varying prices continuously online according to real-time changes in customer demand.","C":"Setting the price at the exact same level as the market leader.","D":"Calculating the unit cost of manufacturing or supplying the product and adding a percentage mark-up for profit."},"correctOption":"D","correctAnswer":"Calculating the unit cost of manufacturing or supplying the product and adding a percentage mark-up for profit.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because cost-plus pricing calculates the average cost per unit and adds a predetermined percentage mark-up to ensure a profit margin on each unit sold.","distractor_reasons":{"A":"Incorrect because setting a price below competitors to gain market share is penetration pricing.","B":"Incorrect because changing prices in response to real-time demand is dynamic pricing.","C":"Incorrect because matching rivals' prices is competitive pricing.","D":"Option D is correct because cost-plus pricing calculates the average cost per unit and adds a predetermined percentage mark-up to ensure a profit margin on each unit sold."}}},{"id":"P1_U3_MCQ_565","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_565","question":"What is a major disadvantage of 'cost-plus pricing'?","options":{"A":"It ignores competitors' prices and whether consumers are actually willing to pay the calculated price.","B":"It is extremely complex and impossible to calculate once unit costs are known.","C":"It forces a business to sell every unit below its average cost of production.","D":"It cannot be adjusted to use different profit mark-ups in different markets."},"correctOption":"A","correctAnswer":"It ignores competitors' prices and whether consumers are actually willing to pay the calculated price.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cost-plus pricing focuses purely on internal costs plus a mark-up, ignoring market demand and competitors' prices—which can result in low sales if the price is too high.","distractor_reasons":{"A":"Option A is correct because cost-plus pricing focuses purely on internal costs plus a mark-up, ignoring market demand and competitors' prices—which can result in low sales if the price is too high.","B":"Incorrect because ease of calculation is actually one of the main advantages of cost-plus pricing.","C":"Incorrect because adding a positive mark-up sets the price above average unit cost (provided expected output is sold).","D":"Incorrect because businesses can apply different percentage mark-ups in different market segments."}}},{"id":"P1_U3_MCQ_566","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_566","question":"What is meant by 'competitive pricing'?","options":{"A":"Setting a very high initial price for a newly invented luxury product.","B":"Setting the price of a product in line with competitors' prices to maintain sales and market share.","C":"Setting a price significantly below rivals' prices to penetrate a new market.","D":"Charging different customers different prices based on their online browsing history."},"correctOption":"B","correctAnswer":"Setting the price of a product in line with competitors' prices to maintain sales and market share.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because competitive pricing sets prices at a similar level to competitors' prices for comparable products in order to protect sales and market share.","distractor_reasons":{"A":"Incorrect because setting a high initial price for a new product is price skimming.","B":"Option B is correct because competitive pricing sets prices at a similar level to competitors' prices for comparable products in order to protect sales and market share.","C":"Incorrect because pricing below competitors to enter a market is penetration pricing.","D":"Incorrect because varying prices based on demand or customer data is dynamic pricing."}}},{"id":"P1_U3_MCQ_567","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_567","question":"What is a possible disadvantage to a business of setting its prices mainly by competitive pricing?","options":{"A":"It removes the need to watch what rival businesses charge","B":"It can start a price war that lowers profit margins for everyone","C":"It guarantees the business the highest profit per item sold","D":"It always makes customers more loyal to the brand"},"correctOption":"B","correctAnswer":"It can start a price war that lowers profit margins for everyone","questionType":"MCQ","explanation":{"correct_reason":"When firms keep cutting prices to undercut rivals, a price war can reduce profit margins across the market.","distractor_reasons":{"A":"Competitive pricing actually requires closely watching rivals, so this statement is false.","B":"Price wars that squeeze profit margins are a recognised drawback of matching rivals' prices, so this is correct.","C":"Competitive pricing does not guarantee high profits, so this is not a genuine drawback.","D":"Lower prices do not automatically create brand loyalty, so this is not a valid disadvantage."}}},{"id":"P1_U3_MCQ_568","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_568","question":"What is 'penetration pricing'?","options":{"A":"Setting a high price when launching a unique, technologically advanced product.","B":"Adding a fixed 50% mark-up onto the total production cost of each unit.","C":"Raising prices sharply during peak holiday travel seasons.","D":"Setting a price lower than competitors' prices when entering a new market in order to gain market share quickly."},"correctOption":"D","correctAnswer":"Setting a price lower than competitors' prices when entering a new market in order to gain market share quickly.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because penetration pricing involves launching a product at a lower price than competitors to attract buyers quickly and build market share.","distractor_reasons":{"A":"Incorrect because setting a high launch price is price skimming.","B":"Incorrect because adding a percentage profit mark-up to cost is cost-plus pricing.","C":"Incorrect because varying prices with seasonal demand is dynamic pricing.","D":"Option D is correct because penetration pricing involves launching a product at a lower price than competitors to attract buyers quickly and build market share."}}},{"id":"P1_U3_MCQ_569","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_569","question":"Which of the following is a disadvantage of 'penetration pricing'?","options":{"A":"It immediately recovers high research and development costs within the first week.","B":"It is completely ineffective at attracting price-sensitive consumers to try a new product.","C":"It creates an overly luxurious brand image that intimidates everyday shoppers.","D":"Profit per unit is low in the short term, and customers may stop buying if the business later tries to raise the price."},"correctOption":"D","correctAnswer":"Profit per unit is low in the short term, and customers may stop buying if the business later tries to raise the price.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because low penetration prices yield low unit profit margins (or short-term losses) and condition consumers to expect a low price, making future price increases risky.","distractor_reasons":{"A":"Incorrect because quickly recovering high R&D costs is an advantage of price skimming, not penetration pricing.","B":"Incorrect because attracting price-sensitive buyers to try a new product is the main advantage of penetration pricing.","C":"Incorrect because a low price can actually undermine a high-quality or luxury brand image.","D":"Option D is correct because low penetration prices yield low unit profit margins (or short-term losses) and condition consumers to expect a low price, making future price increases risky."}}},{"id":"P1_U3_MCQ_570","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_570","question":"What is 'price skimming'?","options":{"A":"Setting a price below average cost to drive all existing competitors out of business.","B":"Setting a high initial price for a newly developed or innovative product on the market.","C":"Matching the lowest price offered by any supermarket in the local area.","D":"Reducing prices automatically whenever online website traffic drops."},"correctOption":"B","correctAnswer":"Setting a high initial price for a newly developed or innovative product on the market.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because price skimming sets a high initial price for a new or uniquely differentiated product to earn high unit profits and reinforce a high-quality image before competitors enter.","distractor_reasons":{"A":"Incorrect because pricing below competitors to gain market share is penetration pricing.","B":"Option B is correct because price skimming sets a high initial price for a new or uniquely differentiated product to earn high unit profits and reinforce a high-quality image before competitors enter.","C":"Incorrect because matching rivals' prices is competitive pricing.","D":"Incorrect because adjusting prices in response to online demand is dynamic pricing."}}},{"id":"P1_U3_MCQ_571","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_571","question":"Why might a business choose to use 'price skimming' when launching a new product?","options":{"A":"To appeal to low-income consumers who only buy discounted goods.","B":"To avoid having to differentiate the product from older competing models.","C":"To earn high profit per unit and quickly recover high research and development costs.","D":"To discourage any competitors from ever noticing the profitability of the market."},"correctOption":"C","correctAnswer":"To earn high profit per unit and quickly recover high research and development costs.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because high skimming prices generate high profit margins per unit sold, helping the business quickly recoup expensive research and development costs while reinforcing a prestige image.","distractor_reasons":{"A":"Incorrect because high skimming prices exclude low-income buyers and target early adopters willing to pay a premium.","B":"Incorrect because price skimming only works if the product is clearly differentiated and superior to existing products.","C":"Option C is correct because high skimming prices generate high profit margins per unit sold, helping the business quickly recoup expensive research and development costs while reinforcing a prestige image.","D":"Incorrect because high profits from price skimming actually attract competitors into the market—a key disadvantage."}}},{"id":"P1_U3_MCQ_572","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_572","question":"What is meant by 'dynamic pricing'?","options":{"A":"Keeping the exact same fixed price printed in a catalogue for an entire year.","B":"Calculating price strictly by adding a fixed percentage mark-up to variable cost.","C":"Setting a permanent low price to enter a foreign export market.","D":"Changing the price of a product, usually when selling online, depending on the changing level of demand."},"correctOption":"D","correctAnswer":"Changing the price of a product, usually when selling online, depending on the changing level of demand.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because dynamic pricing flexibly adjusts prices—commonly via online platforms—rising when demand is high and falling when demand is low to maximise revenue.","distractor_reasons":{"A":"Incorrect because dynamic pricing is the opposite of fixed pricing.","B":"Incorrect because adding a mark-up to cost is cost-plus pricing.","C":"Incorrect because a low entry price is penetration pricing.","D":"Option D is correct because dynamic pricing flexibly adjusts prices—commonly via online platforms—rising when demand is high and falling when demand is low to maximise revenue."}}},{"id":"P1_U3_MCQ_573","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_573","question":"What is a major advantage of 'dynamic pricing' for businesses such as airlines and hotels?","options":{"A":"It helps sell all available capacity at varying prices, maximising total revenue and reducing unsold waste.","B":"It guarantees that every customer pays the exact same price regardless of booking time.","C":"It completely eliminates customer confusion and dissatisfaction over price changes.","D":"It removes the need for any online booking or IT systems."},"correctOption":"A","correctAnswer":"It helps sell all available capacity at varying prices, maximising total revenue and reducing unsold waste.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because dynamic pricing raises prices during peak demand and lowers them when spare capacity remains, maximising total revenue and ensuring seats or rooms do not go unsold.","distractor_reasons":{"A":"Option A is correct because dynamic pricing raises prices during peak demand and lowers them when spare capacity remains, maximising total revenue and ensuring seats or rooms do not go unsold.","B":"Incorrect because customers pay different prices depending on when they purchase and current demand levels.","C":"Incorrect because customer confusion and dissatisfaction when seeing different prices is a disadvantage of dynamic pricing.","D":"Incorrect because dynamic pricing relies heavily on real-time IT and online sales systems."}}},{"id":"P1_U3_MCQ_574","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_574","question":"Havenwood Furniture makes wooden desks at a production cost of $80 each and adds a 25% mark-up to decide its selling price. Which pricing method is Havenwood using?","options":{"A":"Cost-plus pricing - adding a percentage mark-up to the cost of production","B":"Competitive pricing - matching the prices charged by rival firms","C":"Promotional pricing - temporarily cutting price to attract buyers","D":"Premium pricing - setting a high price to suggest high quality"},"correctOption":"A","correctAnswer":"Cost-plus pricing - adding a percentage mark-up to the cost of production","questionType":"MCQ","explanation":{"correct_reason":"Cost-plus pricing sets the selling price by adding a mark-up to the cost of making the product, exactly as Havenwood does with its desks.","distractor_reasons":{"A":"Correct: the price is based on the firm's production cost plus a percentage mark-up.","B":"Wrong: competitive pricing is based on rivals' prices, not on the business's own costs.","C":"Wrong: promotional pricing is a temporary reduction to stimulate sales, not a cost-based price.","D":"Wrong: premium pricing sets a high price to signal quality rather than covering cost plus a mark-up."}}},{"id":"P1_U3_MCQ_575","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_575","question":"Bluewave Electronics sells smart speakers alongside several similar brands. It checks what rival firms charge and sets its own price close to theirs. Which pricing method is Bluewave using?","options":{"A":"Cost-plus pricing - adding a percentage mark-up to production cost","B":"Competitive pricing - setting price relative to competitors' prices","C":"Promotional pricing - briefly lowering price to increase sales","D":"Skimming pricing - starting with a high price and reducing it later"},"correctOption":"B","correctAnswer":"Competitive pricing - setting price relative to competitors' prices","questionType":"MCQ","explanation":{"correct_reason":"Competitive pricing means setting a price by reference to what competitors charge, which is what Bluewave does.","distractor_reasons":{"A":"Wrong: cost-plus pricing uses the firm's own costs plus a mark-up, not rivals' prices.","B":"Correct: the business bases its price on the prices charged by competing firms.","C":"Wrong: promotional pricing is a short-lived reduction, whereas Bluewave matches normal market prices.","D":"Wrong: skimming starts high and falls over time, not tracking competitors' current prices."}}},{"id":"P1_U3_MCQ_576","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_576","question":"What is meant by a 'distribution channel'?","options":{"A":"The paid television and social media advertisements used to promote a brand.","B":"The internal chain of command through which managers pass instructions to workers.","C":"The production line inside a factory that assembles raw materials into finished goods.","D":"The means by which a product is passed from the producer to the customer."},"correctOption":"D","correctAnswer":"The means by which a product is passed from the producer to the customer.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a distribution channel ('place') is the route or means by which goods and services move from the manufacturer/producer to the final customer.","distractor_reasons":{"A":"Incorrect because paid media messages belong to 'promotion', not 'place'.","B":"Incorrect because internal authority lines describe the chain of command in HRM/management.","C":"Incorrect because factory assembly is part of operations management, not distribution.","D":"Option D is correct because a distribution channel ('place') is the route or means by which goods and services move from the manufacturer/producer to the final customer."}}},{"id":"P1_U3_MCQ_577","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_577","question":"Which statement describes a 'direct channel of distribution' (producer direct to customer)?","options":{"A":"The producer appoints an overseas agent to manage all sales and marketing in another country.","B":"The producer sells in bulk to a wholesaler, who then supplies small independent retailers.","C":"The producer sells directly to the final customer without using any intermediaries such as wholesalers or retailers.","D":"The producer sells exclusively through large national supermarket chains."},"correctOption":"C","correctAnswer":"The producer sells directly to the final customer without using any intermediaries such as wholesalers or retailers.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because direct distribution involves zero intermediaries—the producer sells straight to the customer via factory shops, mail order, or its own website.","distractor_reasons":{"A":"Incorrect because appointing an agent introduces an intermediary into the channel.","B":"Incorrect because using wholesalers and retailers is a traditional multi-intermediary channel.","C":"Option C is correct because direct distribution involves zero intermediaries—the producer sells straight to the customer via factory shops, mail order, or its own website.","D":"Incorrect because selling through supermarkets uses retailers as intermediaries."}}},{"id":"P1_U3_MCQ_578","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_578","question":"What is a key advantage to a manufacturer of selling directly to customers?","options":{"A":"Wholesalers hold all the inventory, reducing the manufacturer's storage costs.","B":"The manufacturer keeps all the profit and maintains complete control over how the product is marketed and priced.","C":"The manufacturer receives fewer individual orders and makes fewer delivery journeys.","D":"Customers can browse competing brands from many different manufacturers in one store."},"correctOption":"B","correctAnswer":"The manufacturer keeps all the profit and maintains complete control over how the product is marketed and priced.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because direct selling eliminates intermediary profit margins, allowing the producer to earn all the profit and control pricing, display, and promotion.","distractor_reasons":{"A":"Incorrect because holding inventory for many small orders is a disadvantage of direct selling; wholesalers reduce producer storage costs.","B":"Option B is correct because direct selling eliminates intermediary profit margins, allowing the producer to earn all the profit and control pricing, display, and promotion.","C":"Incorrect because selling directly to individual consumers increases the number of orders and deliveries.","D":"Incorrect because offering products from multiple producers is an advantage of retailers, not direct manufacturer outlets."}}},{"id":"P1_U3_MCQ_579","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_579","question":"What is the role of a 'retailer' in a distribution channel?","options":{"A":"To extract raw materials from the Earth for manufacturing businesses.","B":"To buy raw components in bulk and manufacture finished consumer goods.","C":"To buy products from producers or wholesalers and sell them to final customers in relatively small quantities.","D":"To pass laws protecting consumers from faulty goods and misleading advertisements."},"correctOption":"C","correctAnswer":"To buy products from producers or wholesalers and sell them to final customers in relatively small quantities.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a retailer is an intermediary business that purchases goods from producers or wholesalers and sells them in smaller quantities to final consumers.","distractor_reasons":{"A":"Incorrect because extracting natural resources is the role of primary sector businesses.","B":"Incorrect because manufacturing finished goods is the role of secondary sector producers.","C":"Option C is correct because a retailer is an intermediary business that purchases goods from producers or wholesalers and sells them in smaller quantities to final consumers.","D":"Incorrect because passing consumer protection laws is the role of the government."}}},{"id":"P1_U3_MCQ_580","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_580","question":"What is a disadvantage to a manufacturer of distributing products through retailers rather than directly to consumers?","options":{"A":"The manufacturer must process thousands of tiny individual customer deliveries.","B":"Customers have less choice because retailers only sell one brand.","C":"The manufacturer cannot focus on manufacturing because it must run retail shops.","D":"The manufacturer earns a lower profit per unit and loses direct contact with final customers."},"correctOption":"D","correctAnswer":"The manufacturer earns a lower profit per unit and loses direct contact with final customers.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because retailers buy at a lower wholesale/trade price to earn their own profit margin, and the manufacturer loses direct customer contact and feedback.","distractor_reasons":{"A":"Incorrect because selling large quantities to retailers actually reduces the manufacturer's delivery and administration costs.","B":"Incorrect because retailers typically stock rival brands, giving customers more choice.","C":"Incorrect because using retailers frees the manufacturer to focus on production.","D":"Option D is correct because retailers buy at a lower wholesale/trade price to earn their own profit margin, and the manufacturer loses direct customer contact and feedback."}}},{"id":"P1_U3_MCQ_581","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_581","question":"What is the main function of a 'wholesaler' in a distribution channel?","options":{"A":"Breaking bulk by buying in large quantities from manufacturers and selling in smaller quantities to retailers.","B":"Designing advertisements and television commercials for consumer brands.","C":"Selling single items directly to individual household consumers in high-street shops.","D":"Providing bank loans and overdrafts to start-up entrepreneurs."},"correctOption":"A","correctAnswer":"Breaking bulk by buying in large quantities from manufacturers and selling in smaller quantities to retailers.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a wholesaler buys large bulk quantities from manufacturers, stores the inventory, and breaks bulk into smaller quantities for retailers to buy.","distractor_reasons":{"A":"Option A is correct because a wholesaler buys large bulk quantities from manufacturers, stores the inventory, and breaks bulk into smaller quantities for retailers to buy.","B":"Incorrect because creating advertisements is the role of an advertising agency or marketing department.","C":"Incorrect because selling single items to final consumers is the role of a retailer.","D":"Incorrect because providing loans is the role of commercial banks, though wholesalers may offer trade credit on goods."}}},{"id":"P1_U3_MCQ_582","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_582","question":"How does using a wholesaler benefit a manufacturer?","options":{"A":"The final price paid by consumers is lower than in direct selling.","B":"The wholesaler holds most of the inventory, reducing the manufacturer's storage costs and number of delivery journeys.","C":"The manufacturer retains full control over which shops sell the product and at what retail price.","D":"The manufacturer receives immediate face-to-face feedback from every individual consumer."},"correctOption":"B","correctAnswer":"The wholesaler holds most of the inventory, reducing the manufacturer's storage costs and number of delivery journeys.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because wholesalers store large amounts of inventory and distribute to numerous small retailers, reducing the manufacturer's warehouse space, storage costs, and order processing.","distractor_reasons":{"A":"Incorrect because adding both a wholesaler and a retailer increases intermediary mark-ups and raises the final consumer price.","B":"Option B is correct because wholesalers store large amounts of inventory and distribute to numerous small retailers, reducing the manufacturer's warehouse space, storage costs, and order processing.","C":"Incorrect because manufacturers lose control over the selling process once goods are sold to wholesalers.","D":"Incorrect because two intermediaries separate the manufacturer from final consumers, preventing direct feedback."}}},{"id":"P1_U3_MCQ_583","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_583","question":"What is the role of an 'agent' in a distribution channel?","options":{"A":"A government inspector who tests whether imported goods meet safety regulations.","B":"A factory employee responsible for checking product quality on the assembly line.","C":"An independent person or business appointed to deal with the sales and distribution of a product, often in another country.","D":"A bank manager who approves mortgages for retail property owners."},"correctOption":"C","correctAnswer":"An independent person or business appointed to deal with the sales and distribution of a product, often in another country.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because an agent is an independent intermediary appointed by a producer—frequently when entering foreign export markets—to handle local sales and distribution.","distractor_reasons":{"A":"Incorrect because government safety inspectors enforce legal compliance rather than distributing products.","B":"Incorrect because quality inspectors work within operations management inside a factory.","C":"Option C is correct because an agent is an independent intermediary appointed by a producer—frequently when entering foreign export markets—to handle local sales and distribution.","D":"Incorrect because bank managers provide financial services rather than product distribution."}}},{"id":"P1_U3_MCQ_584","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_584","question":"What is a key advantage of using an agent when selling products in another country?","options":{"A":"The producer retains 100% direct control over every marketing decision.","B":"Agents never charge any fees or commission for their distribution services.","C":"Agents always possess deeper technical knowledge of the product than the manufacturer.","D":"The agent has specialist local market knowledge of consumer tastes and distribution networks."},"correctOption":"D","correctAnswer":"The agent has specialist local market knowledge of consumer tastes and distribution networks.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because local agents understand the foreign market's culture, regulations, and distribution channels, increasing the likelihood of successful export sales.","distractor_reasons":{"A":"Incorrect because loss of control over how the product is marketed is a disadvantage of using an agent.","B":"Incorrect because agents charge fees or commission, which raises costs or final consumer prices.","C":"Incorrect because agents typically have less detailed product knowledge than the producer itself.","D":"Option D is correct because local agents understand the foreign market's culture, regulations, and distribution channels, increasing the likelihood of successful export sales."}}},{"id":"P1_U3_MCQ_585","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_585","question":"What is meant by 'ecommerce' (electronic commerce)?","options":{"A":"Selling goods exclusively through printed mail-order catalogues sent by post.","B":"The online buying and selling of goods and services using internet-linked devices such as laptops and smartphones.","C":"Using automated robots to assemble cars inside a manufacturing plant.","D":"Distributing leaflets by hand to shoppers in a local town centre."},"correctOption":"B","correctAnswer":"The online buying and selling of goods and services using internet-linked devices such as laptops and smartphones.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because ecommerce refers to buying and selling goods and services over the internet via connected devices such as computers, tablets, and smartphones.","distractor_reasons":{"A":"Incorrect because printed mail-order catalogues do not use internet-linked electronic transactions.","B":"Option B is correct because ecommerce refers to buying and selling goods and services over the internet via connected devices such as computers, tablets, and smartphones.","C":"Incorrect because factory robotics relates to production technology (CAM), not ecommerce.","D":"Incorrect because handing out paper leaflets is traditional offline advertising."}}},{"id":"P1_U3_MCQ_586","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_586","question":"Which of the following are three common examples of ecommerce?","options":{"A":"Door-to-door selling, newspaper classified adverts, and cash-only market stalls.","B":"Mobile/internet banking, online shopping, and online ticketing.","C":"Wholesale cash-and-carry warehouses, postal questionnaires, and billboard posters.","D":"Job production, batch production, and flow production."},"correctOption":"B","correctAnswer":"Mobile/internet banking, online shopping, and online ticketing.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because mobile/internet banking, online shopping, and online ticketing (e-tickets) are key real-world applications of ecommerce.","distractor_reasons":{"A":"Incorrect because these are traditional offline trading and promotional methods.","B":"Option B is correct because mobile/internet banking, online shopping, and online ticketing (e-tickets) are key real-world applications of ecommerce.","C":"Incorrect because physical warehouses, postal mail, and roadside billboards are offline operations.","D":"Incorrect because these are the three main methods of manufacturing production."}}},{"id":"P1_U3_MCQ_587","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_587","question":"What is a major advantage of ecommerce for a retail business?","options":{"A":"Product return rates from customers fall to zero because buyers can try items on before ordering.","B":"There is zero competition from overseas producers when selling online.","C":"Websites allow the business to reach global markets 24/7 while reducing physical shop and sales staff costs.","D":"IT systems and websites never require updating or cybersecurity protection."},"correctOption":"C","correctAnswer":"Websites allow the business to reach global markets 24/7 while reducing physical shop and sales staff costs.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because ecommerce enables 24/7 global sales through a website while lowering fixed overhead costs associated with operating high-street retail stores.","distractor_reasons":{"A":"Incorrect because higher product return rates (since buyers cannot touch or try items beforehand) are a disadvantage of online shopping.","B":"Incorrect because operating online increases global competition from low-cost international sellers.","C":"Option C is correct because ecommerce enables 24/7 global sales through a website while lowering fixed overhead costs associated with operating high-street retail stores.","D":"Incorrect because websites require frequent updates and face risks from hackers and IT failures."}}},{"id":"P1_U3_MCQ_588","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_588","question":"What is a key disadvantage of ecommerce for customers?","options":{"A":"Online stores are only open for four hours a day.","B":"Customers can never compare prices between different online sellers.","C":"Online prices are always higher than prices in physical high-street shops.","D":"Customers cannot physically touch, inspect, or try on products before buying, and face security/fraud risks."},"correctOption":"D","correctAnswer":"Customers cannot physically touch, inspect, or try on products before buying, and face security/fraud risks.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because online shoppers cannot physically inspect or try on goods prior to delivery, lose personal face-to-face advice, and risk payment fraud or identity theft.","distractor_reasons":{"A":"Incorrect because 24/7 convenience at any time of day is a major advantage for customers.","B":"Incorrect because easy price comparison across websites is a benefit to online shoppers.","C":"Incorrect because lower overhead costs often allow online retailers to offer lower prices than physical shops.","D":"Option D is correct because online shoppers cannot physically inspect or try on goods prior to delivery, lose personal face-to-face advice, and risk payment fraud or identity theft."}}},{"id":"P1_U3_MCQ_589","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_589","question":"What is the overall aim of 'promotion' in the marketing mix?","options":{"A":"To calculate the exact break-even level of output for a factory.","B":"To raise customer awareness of a product or brand, generate sales, and help create brand loyalty.","C":"To transport raw materials from primary sector suppliers to manufacturers.","D":"To recruit and train new employees for the human resources department."},"correctOption":"B","correctAnswer":"To raise customer awareness of a product or brand, generate sales, and help create brand loyalty.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because promotion encompasses advertising and sales promotion activities designed to inform/persuade customers, raise awareness, boost sales, and build brand loyalty.","distractor_reasons":{"A":"Incorrect because break-even calculation is an operations/finance tool.","B":"Option B is correct because promotion encompasses advertising and sales promotion activities designed to inform/persuade customers, raise awareness, boost sales, and build brand loyalty.","C":"Incorrect because moving materials is logistics and supply chain management.","D":"Incorrect because recruiting and training staff is the role of human resource management."}}},{"id":"P1_U3_MCQ_590","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_590","question":"How does 'informative advertising' differ from 'persuasive advertising'?","options":{"A":"Informative advertising is free of charge, whereas persuasive advertising is paid for.","B":"Informative advertising provides factual details about features, price, and uses, whereas persuasive advertising focuses on creating a desirable image to convince consumers to buy.","C":"Informative advertising is used only in the decline stage, whereas persuasive advertising is used only before a product is invented.","D":"Informative advertising uses only social media, whereas persuasive advertising uses only roadside billboards."},"correctOption":"B","correctAnswer":"Informative advertising provides factual details about features, price, and uses, whereas persuasive advertising focuses on creating a desirable image to convince consumers to buy.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because informative advertising gives consumers factual information (such as specifications, price, and benefits), while persuasive advertising appeals to emotions and lifestyle to create brand desirability.","distractor_reasons":{"A":"Incorrect because all advertising is paid-for communication.","B":"Option B is correct because informative advertising gives consumers factual information (such as specifications, price, and benefits), while persuasive advertising appeals to emotions and lifestyle to create brand desirability.","C":"Incorrect because informative advertising is heavily used at the introduction stage when launching a new product.","D":"Incorrect because both informative and persuasive messages can be delivered across various media."}}},{"id":"P1_U3_MCQ_591","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_591","question":"What is meant by 'sales promotion'?","options":{"A":"Long-term television campaigns designed solely to build corporate public relations.","B":"Promoting an existing employee to a senior management position.","C":"Short-term incentives such as vouchers, reward schemes, competitions, or special offers aimed at boosting sales.","D":"Selecting the most efficient wholesaler to distribute perishable food products."},"correctOption":"C","correctAnswer":"Short-term incentives such as vouchers, reward schemes, competitions, or special offers aimed at boosting sales.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because sales promotions are short-term incentives (like discounts, BOGOF offers, vouchers, competitions, and loyalty reward schemes) used to stimulate immediate purchases.","distractor_reasons":{"A":"Incorrect because long-term TV campaigns are advertising rather than short-term sales promotion.","B":"Incorrect because internal staff promotion is an HRM concept, not marketing sales promotion.","C":"Option C is correct because sales promotions are short-term incentives (like discounts, BOGOF offers, vouchers, competitions, and loyalty reward schemes) used to stimulate immediate purchases.","D":"Incorrect because selecting a wholesaler relates to 'place' (distribution)."}}},{"id":"P1_U3_MCQ_592","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_592","question":"How do 'reward schemes' (such as customer loyalty cards) benefit a business?","options":{"A":"They require zero IT systems or administrative costs to operate.","B":"They guarantee that customers will never shop at any competing store.","C":"They allow the business to avoid paying value-added tax on discounted goods.","D":"They encourage repeat purchases and provide valuable customer data for market research when shoppers register."},"correctOption":"D","correctAnswer":"They encourage repeat purchases and provide valuable customer data for market research when shoppers register.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because reward schemes incentivize customers to keep returning to collect points/rewards while capturing registration and purchasing data for market research.","distractor_reasons":{"A":"Incorrect because managing loyalty schemes requires costly IT databases and ongoing rewards.","B":"Incorrect because shoppers often hold loyalty cards for several competing supermarkets at once.","C":"Incorrect because loyalty cards do not exempt a business from taxes.","D":"Option D is correct because reward schemes incentivize customers to keep returning to collect points/rewards while capturing registration and purchasing data for market research."}}},{"id":"P1_U3_MCQ_593","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_593","question":"What is a potential disadvantage of using 'special offers' (such as price discounts or 'buy-one-get-one-free')?","options":{"A":"Consumers are never motivated to try a new product by a temporary price discount.","B":"They are completely ineffective at clearing excess inventory nearing its sell-by date.","C":"Profit margin per unit is reduced, and frequent discounts may damage an exclusive or luxury brand image.","D":"They permanently increase the cost of raw materials used in manufacturing."},"correctOption":"C","correctAnswer":"Profit margin per unit is reduced, and frequent discounts may damage an exclusive or luxury brand image.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because price reductions cut unit profit margins, may cause buyers to stockpile and buy less later at full price, and can cheapen a luxury brand's image.","distractor_reasons":{"A":"Incorrect because encouraging first-time trial is a primary purpose of special offers.","B":"Incorrect because clearing seasonal or short-dated inventory is actually a common advantage of special offers.","C":"Option C is correct because price reductions cut unit profit margins, may cause buyers to stockpile and buy less later at full price, and can cheapen a luxury brand's image.","D":"Incorrect because promotional discounts affect selling revenue rather than supplier raw material costs."}}},{"id":"P1_U3_MCQ_594","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_594","question":"What is a key advantage of advertising on 'social media'?","options":{"A":"It guarantees that negative customer comments can never be posted publicly.","B":"It reaches a large, often younger audience, allows two-way communication, and adverts can be shared virally at low cost.","C":"It effectively reaches elderly consumers who do not own smartphones or computers.","D":"It requires zero staff time to monitor messages or update online content."},"correctOption":"B","correctAnswer":"It reaches a large, often younger audience, allows two-way communication, and adverts can be shared virally at low cost.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because social media advertising can target specific demographics cost-effectively, encourages two-way engagement, drives website traffic, and can go viral.","distractor_reasons":{"A":"Incorrect because viral negative feedback is a major risk and disadvantage of social media marketing.","B":"Option B is correct because social media advertising can target specific demographics cost-effectively, encourages two-way engagement, drives website traffic, and can go viral.","C":"Incorrect because consumers who do not use social media cannot be reached through this medium.","D":"Incorrect because managing social media accounts requires ongoing time and resources."}}},{"id":"P1_U3_MCQ_595","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_595","question":"What is a common disadvantage of using 'direct/targeted emails' for advertising?","options":{"A":"They incur high paper printing and postal stamp expenses for every message sent.","B":"They cannot be sent to customers who have previously subscribed to a mailing list.","C":"Recipients may view them as irritating spam, delete them unread, or unsubscribe from the mailing list.","D":"They cause severe environmental damage due to large amounts of discarded paper waste."},"correctOption":"C","correctAnswer":"Recipients may view them as irritating spam, delete them unread, or unsubscribe from the mailing list.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because commercial emails are often filtered into spam/junk folders or deleted unread by irritated consumers, requiring continuous database maintenance.","distractor_reasons":{"A":"Incorrect because zero printing or postage cost is an advantage of email over physical mail.","B":"Incorrect because targeted emails are specifically sent to existing subscribers and past customers.","C":"Option C is correct because commercial emails are often filtered into spam/junk folders or deleted unread by irritated consumers, requiring continuous database maintenance.","D":"Incorrect because low environmental impact compared to printed leaflets is an advantage of email."}}},{"id":"P1_U3_MCQ_596","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_596","question":"What is a disadvantage of using 'billboards' as an advertising medium?","options":{"A":"They can only be displayed for a maximum of twenty-four hours.","B":"They cannot display large, colourful visual images.","C":"They are always more expensive than a nationwide prime-time television campaign.","D":"Detailed product information cannot be included because passers-by and drivers only see them briefly."},"correctOption":"D","correctAnswer":"Detailed product information cannot be included because passers-by and drivers only see them briefly.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because billboards are passed quickly by pedestrians and motorists, meaning adverts must rely on brief slogans and visuals rather than detailed technical text.","distractor_reasons":{"A":"Incorrect because billboards remain displayed for long periods, which is an advantage.","B":"Incorrect because large, eye-catching visuals are a core strength of billboards.","C":"Incorrect because billboards are relatively low cost compared to national TV advertising.","D":"Option D is correct because billboards are passed quickly by pedestrians and motorists, meaning adverts must rely on brief slogans and visuals rather than detailed technical text."}}},{"id":"P1_U3_MCQ_597","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_597","question":"What is an advantage of using 'leaflets' for local advertising?","options":{"A":"They are a low-cost printed method that can be handed out locally and kept by consumers for future reference.","B":"Every recipient is guaranteed to read the leaflet carefully and make a purchase.","C":"They are widely praised by environmental groups for eliminating paper waste.","D":"They allow live two-way video interaction between the business and the customer."},"correctOption":"A","correctAnswer":"They are a low-cost printed method that can be handed out locally and kept by consumers for future reference.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because leaflets are inexpensive to print, can be distributed door-to-door or in busy streets, may include money-off vouchers, and can be kept by consumers.","distractor_reasons":{"A":"Option A is correct because leaflets are inexpensive to print, can be distributed door-to-door or in busy streets, may include money-off vouchers, and can be kept by consumers.","B":"Incorrect because many leaflets are thrown away unread as 'junk mail'.","C":"Incorrect because discarded paper leaflets are often criticised for creating litter and environmental waste.","D":"Incorrect because two-way digital interaction is a feature of social media, not printed leaflets."}}},{"id":"P1_U3_MCQ_598","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_598","question":"What is the primary role of 'Public Relations (PR)' in promotion?","options":{"A":"Paying for short-term price discounts on supermarket shelves.","B":"Maintaining a positive public image for the business through unpaid media coverage, press releases, and sponsorships.","C":"Calculating the percentage mark-up on manufactured goods.","D":"Distributing bulk shipments from factories to regional wholesalers."},"correctOption":"B","correctAnswer":"Maintaining a positive public image for the business through unpaid media coverage, press releases, and sponsorships.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because public relations aims to create and maintain a favourable public image and goodwill for the business using press releases, charity events, and media coverage.","distractor_reasons":{"A":"Incorrect because short-term price discounts are a method of sales promotion.","B":"Option B is correct because public relations aims to create and maintain a favourable public image and goodwill for the business using press releases, charity events, and media coverage.","C":"Incorrect because calculating mark-up relates to cost-plus pricing.","D":"Incorrect because bulk shipment relates to distribution ('place')."}}},{"id":"P1_U3_MCQ_599","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_599","question":"When is 'personal selling' (using sales representatives to meet buyers face-to-face) most appropriate?","options":{"A":"When selling low-priced everyday items like loaves of bread to millions of shoppers.","B":"When a business has almost no promotion budget and sells to a mass market.","C":"When selling expensive, complex, or technical producer goods that require detailed demonstration and explanation.","D":"When the product is sold exclusively through automated self-service vending machines."},"correctOption":"C","correctAnswer":"When selling expensive, complex, or technical producer goods that require detailed demonstration and explanation.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because personal selling is costly per contact and is best suited to high-value, complex, or technical products (such as industrial machinery) where tailored advice is needed.","distractor_reasons":{"A":"Incorrect because mass-market convenience goods rely on mass advertising and retail display rather than individual sales reps.","B":"Incorrect because employing trained sales representatives is expensive per customer reached.","C":"Option C is correct because personal selling is costly per contact and is best suited to high-value, complex, or technical products (such as industrial machinery) where tailored advice is needed.","D":"Incorrect because vending machines involve automated self-service with zero human sales interaction."}}},{"id":"P1_U3_MCQ_600","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_600","question":"Which factor is most important when deciding which method of promotion to use?","options":{"A":"The number of shareholders who attend the company's Annual General Meeting.","B":"The span of control of supervisors on the factory assembly line.","C":"The depreciation method used for non-current factory machinery.","D":"The size of the promotion budget, the stage of the product life cycle, the nature of the product, and the target market."},"correctOption":"D","correctAnswer":"The size of the promotion budget, the stage of the product life cycle, the nature of the product, and the target market.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because marketing managers select promotional methods based on available budget, expected revenue gain, product life cycle stage, product type (consumer vs producer), target audience, and brand image.","distractor_reasons":{"A":"Incorrect because AGM attendance relates to corporate governance rather than promotional media choice.","B":"Incorrect because factory supervision structure does not determine how products are advertised.","C":"Incorrect because accounting depreciation methods do not guide promotional strategy.","D":"Option D is correct because marketing managers select promotional methods based on available budget, expected revenue gain, product life cycle stage, product type (consumer vs producer), target audience, and brand image."}}},{"id":"P1_U3_MCQ_601","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_601","question":"What is meant by a 'marketing strategy'?","options":{"A":"A legal contract between an employer and an employee outlining working hours and pay.","B":"A financial statement showing a business's assets, liabilities, and capital at a specific date.","C":"A plan to combine the right combination of the four elements of the marketing mix for a product or service to achieve a particular marketing objective.","D":"A government policy restricting the quantity of foreign goods imported into a country."},"correctOption":"C","correctAnswer":"A plan to combine the right combination of the four elements of the marketing mix for a product or service to achieve a particular marketing objective.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a marketing strategy sets out a clear marketing objective and details the integrated marketing mix (product, price, place, promotion) designed to achieve that goal.","distractor_reasons":{"A":"Incorrect because an employer-employee agreement is a contract of employment.","B":"Incorrect because a record of assets and liabilities is a statement of financial position.","C":"Option C is correct because a marketing strategy sets out a clear marketing objective and details the integrated marketing mix (product, price, place, promotion) designed to achieve that goal.","D":"Incorrect because a restriction on import quantities is an import quota."}}},{"id":"P1_U3_MCQ_602","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_602","question":"Why is consistency between all four elements of the marketing mix essential for a successful marketing strategy?","options":{"A":"Because the law requires all businesses to spend the exact same amount on each of the four Ps.","B":"Because if one element clashes with the others (such as a luxury product sold in a cheap discount store), consumers receive mixed messages and the strategy will fail.","C":"Because a business is legally forbidden from ever changing its marketing mix once launched.","D":"Because consistency eliminates the need to identify a target market segment."},"correctOption":"B","correctAnswer":"Because if one element clashes with the others (such as a luxury product sold in a cheap discount store), consumers receive mixed messages and the strategy will fail.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because all four Ps must reinforce the same brand image and target market positioning; any inconsistency undermines consumer trust and causes the strategy to fail.","distractor_reasons":{"A":"Incorrect because there is no legal requirement to spend equal budgets across product, price, place, and promotion.","B":"Option B is correct because all four Ps must reinforce the same brand image and target market positioning; any inconsistency undermines consumer trust and causes the strategy to fail.","C":"Incorrect because businesses must regularly adapt their marketing mix across the product life cycle and as market conditions change.","D":"Incorrect because a consistent marketing mix is built specifically around the needs of a clearly defined target market."}}},{"id":"P1_U3_MCQ_603","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_603","question":"Which of the following is an example of a clear 'marketing objective'?","options":{"A":"Reducing factory absenteeism by introducing flexitime for assembly workers.","B":"Increasing the span of control of warehouse supervisors from four to eight subordinates.","C":"Increasing market share of an existing product or achieving a target sales level in a new market.","D":"Issuing new shares on a stock exchange to repay long-term bank loans."},"correctOption":"C","correctAnswer":"Increasing market share of an existing product or achieving a target sales level in a new market.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because marketing objectives focus on market performance targets such as increasing sales, gaining market share, entering new markets, or improving customer loyalty.","distractor_reasons":{"A":"Incorrect because reducing worker absenteeism is a human resource management objective.","B":"Incorrect because changing spans of control is an organizational structure decision.","C":"Option C is correct because marketing objectives focus on market performance targets such as increasing sales, gaining market share, entering new markets, or improving customer loyalty.","D":"Incorrect because issuing shares to repay debt is a corporate finance decision."}}},{"id":"P1_U3_MCQ_604","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_604","question":"Which four factors must a Marketing Manager consider when developing or adapting a marketing mix?","options":{"A":"Land, labour, capital, and enterprise.","B":"Cash inflows, cash outflows, opening balance, and closing balance.","C":"Job description, person specification, shortlist, and induction.","D":"Marketing objective, finance available, target market, and level of competition."},"correctOption":"D","correctAnswer":"Marketing objective, finance available, target market, and level of competition.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the choice of product, price, place, and promotion depends on the marketing objective, the available marketing budget, the target market's characteristics, and competitors' actions.","distractor_reasons":{"A":"Incorrect because these are the four factors of production.","B":"Incorrect because these are the components of a cash flow forecast.","C":"Incorrect because these are stages in employee recruitment and selection.","D":"Option D is correct because the choice of product, price, place, and promotion depends on the marketing objective, the available marketing budget, the target market's characteristics, and competitors' actions."}}},{"id":"P1_U3_MCQ_605","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_605","question":"Why must a business adapt its marketing strategy over time?","options":{"A":"Because consumer tastes change, new competitors enter, and the product moves through different stages of its life cycle.","B":"Because consumer protection laws expire every twelve months.","C":"Because products can never remain in the maturity stage for more than one month.","D":"Because market research becomes illegal after a product's initial launch."},"correctOption":"A","correctAnswer":"Because consumer tastes change, new competitors enter, and the product moves through different stages of its life cycle.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because market conditions are dynamic—consumer preferences evolve, competitors launch new rivals, and a product requires different pricing and promotion as it moves from introduction to maturity.","distractor_reasons":{"A":"Option A is correct because market conditions are dynamic—consumer preferences evolve, competitors launch new rivals, and a product requires different pricing and promotion as it moves from introduction to maturity.","B":"Incorrect because consumer protection laws remain permanently in force unless amended by parliament.","C":"Incorrect because well-managed brands can remain in the maturity stage for many years.","D":"Incorrect because ongoing market research is essential throughout a product's entire life."}}},{"id":"P1_U3_MCQ_606","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_606","question":"What is a major advantage to a business of entering new markets in other countries?","options":{"A":"The business can use the exact same language and packaging in every country without any changes.","B":"It increases total potential sales and spreads business risk across different economies.","C":"There are never any import tariffs, transport costs, or legal controls in foreign markets.","D":"Consumers in all countries have identical incomes, religions, and cultural tastes."},"correctOption":"B","correctAnswer":"It increases total potential sales and spreads business risk across different economies.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because expanding into foreign markets enlarges the customer base to boost sales and spreads risk so a downturn in the home economy can be offset by growth abroad.","distractor_reasons":{"A":"Incorrect because language and legal labelling requirements frequently require packaging adaptations.","B":"Option B is correct because expanding into foreign markets enlarges the customer base to boost sales and spreads risk so a downturn in the home economy can be offset by growth abroad.","C":"Incorrect because foreign markets often impose tariffs, transport expenses, and different legal rules.","D":"Incorrect because differences in income, religion, and culture are major challenges in international marketing."}}},{"id":"P1_U3_MCQ_607","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_607","question":"How does entering foreign markets help a business 'spread risk'?","options":{"A":"It guarantees that exchange rates will never fluctuate.","B":"It eliminates all fixed costs of operating factories in the home country.","C":"If demand falls due to a recession or new rival in the home country, strong sales in booming foreign markets can offset the loss.","D":"It prevents foreign governments from passing any consumer protection laws."},"correctOption":"C","correctAnswer":"If demand falls due to a recession or new rival in the home country, strong sales in booming foreign markets can offset the loss.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because operating across multiple national markets reduces reliance on a single domestic economy; weak demand at home can be balanced by growth elsewhere.","distractor_reasons":{"A":"Incorrect because international trade exposes businesses to exchange rate fluctuations.","B":"Incorrect because domestic factory fixed costs remain until assets are sold or closed.","C":"Option C is correct because operating across multiple national markets reduces reliance on a single domestic economy; weak demand at home can be balanced by growth elsewhere.","D":"Incorrect because businesses must comply with the laws of every country in which they sell."}}},{"id":"P1_U3_MCQ_608","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_608","question":"Which of the following are three key barriers or disadvantages of entering new markets in other countries?","options":{"A":"Lower total sales potential, complete absence of competitors, and lower consumer choice.","B":"Automatic economies of scale, zero marketing costs, and guaranteed brand loyalty.","C":"Short chains of command, wide spans of control, and democratic leadership.","D":"Cultural differences, lack of local market knowledge, and different legal requirements."},"correctOption":"D","correctAnswer":"Cultural differences, lack of local market knowledge, and different legal requirements.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because businesses entering foreign markets often face cultural/religious differences, lack of knowledge about local tastes and competitors, and unfamiliar legal regulations.","distractor_reasons":{"A":"Incorrect because entering foreign markets increases total sales potential rather than reducing it.","B":"Incorrect because entering new countries increases marketing and research costs and does not guarantee loyalty.","C":"Incorrect because these are internal organizational management concepts.","D":"Option D is correct because businesses entering foreign markets often face cultural/religious differences, lack of knowledge about local tastes and competitors, and unfamiliar legal regulations."}}},{"id":"P1_U3_MCQ_609","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_609","question":"How might 'cultural differences' affect a business's marketing mix when entering a foreign market?","options":{"A":"Product ingredients, recipes, and advertising images may have to be adapted to respect local religious beliefs and social norms.","B":"The business must always charge a higher price than in its home market regardless of local incomes.","C":"The business is forbidden from using local agents or wholesalers to distribute its goods.","D":"Consumers in foreign countries ignore product quality and buy purely based on packaging size."},"correctOption":"A","correctAnswer":"Product ingredients, recipes, and advertising images may have to be adapted to respect local religious beliefs and social norms.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cultural and religious norms (such as dietary restrictions or social customs) require adapting products and promotional imagery so they are acceptable and appealing.","distractor_reasons":{"A":"Option A is correct because cultural and religious norms (such as dietary restrictions or social customs) require adapting products and promotional imagery so they are acceptable and appealing.","B":"Incorrect because prices must be adjusted to match local income levels and competition, which may be lower.","C":"Incorrect because employing local agents is a common, effective way to overcome cultural barriers.","D":"Incorrect because consumers worldwide value product quality and suitability."}}},{"id":"P1_U3_MCQ_610","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_610","question":"Why is 'lack of knowledge' a serious disadvantage when entering a new market in another country?","options":{"A":"It prevents the business from calculating its own domestic factory costs.","B":"Without understanding local consumer incomes, age structures, and competitors, the business may choose an unsuitable marketing mix and make a loss.","C":"It forces the business to sell its products below cost in its home market.","D":"It makes it illegal to conduct primary or secondary market research abroad."},"correctOption":"B","correctAnswer":"Without understanding local consumer incomes, age structures, and competitors, the business may choose an unsuitable marketing mix and make a loss.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because unfamiliarity with foreign consumer incomes, demographics, and rival pricing can lead to costly marketing errors, though conducting research or hiring local agents adds expense.","distractor_reasons":{"A":"Incorrect because a firm knows its own internal production costs from its accounting records.","B":"Option B is correct because unfamiliarity with foreign consumer incomes, demographics, and rival pricing can lead to costly marketing errors, though conducting research or hiring local agents adds expense.","C":"Incorrect because lack of foreign market knowledge does not force domestic below-cost pricing.","D":"Incorrect because conducting market research in foreign markets is legal and strongly recommended."}}},{"id":"P1_U3_MCQ_611","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_611","question":"What is meant by 'legal controls on marketing'?","options":{"A":"Internal company rules setting annual sales targets for the marketing department.","B":"Agreements between competing businesses to fix prices at a high level.","C":"Laws passed by government to protect consumers from faulty goods, unsafe goods, and misleading promotion.","D":"Voluntary ethical guidelines written by advertising agencies."},"correctOption":"C","correctAnswer":"Laws passed by government to protect consumers from faulty goods, unsafe goods, and misleading promotion.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because legal controls on marketing are government laws designed to protect consumers against unfair practices such as faulty products, unsafe goods, and false promotional claims.","distractor_reasons":{"A":"Incorrect because internal sales targets are management objectives, not legal controls.","B":"Incorrect because price-fixing agreements between rivals are illegal anti-competitive cartels.","C":"Option C is correct because legal controls on marketing are government laws designed to protect consumers against unfair practices such as faulty products, unsafe goods, and false promotional claims.","D":"Incorrect because legal controls are mandatory laws enforced by government, not voluntary guidelines."}}},{"id":"P1_U3_MCQ_612","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_612","question":"Why do governments introduce legal controls to protect consumers?","options":{"A":"To ensure that all private sector businesses earn the exact same annual profit.","B":"To prevent consumers from buying imported goods from foreign businesses.","C":"To eliminate competition between businesses in mass markets.","D":"Because modern products are complex and persuasive promotions could otherwise mislead consumers into buying unsafe, faulty, or unsuitable goods."},"correctOption":"D","correctAnswer":"Because modern products are complex and persuasive promotions could otherwise mislead consumers into buying unsafe, faulty, or unsuitable goods.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because technical product complexity and sophisticated marketing make it difficult for consumers to judge product quality beforehand, requiring legal protection against exploitation.","distractor_reasons":{"A":"Incorrect because profits in a market economy vary based on business efficiency and demand.","B":"Incorrect because consumer protection laws apply equally to domestic and imported goods.","C":"Incorrect because governments aim to encourage fair competition rather than eliminate it.","D":"Option D is correct because technical product complexity and sophisticated marketing make it difficult for consumers to judge product quality beforehand, requiring legal protection against exploitation."}}},{"id":"P1_U3_MCQ_613","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_613","question":"What do consumer protection laws regarding 'misleading promotion' prohibit?","options":{"A":"Making false or deliberately misleading claims about a product's materials, performance, or price reductions in advertisements.","B":"Using social media or billboards to inform consumers about a newly launched product.","C":"Offering genuine temporary price discounts during a seasonal clearance sale.","D":"Stating the true country of origin and ingredients on food packaging."},"correctOption":"A","correctAnswer":"Making false or deliberately misleading claims about a product's materials, performance, or price reductions in advertisements.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because laws against misleading promotion require advertisements and price-reduction claims to be truthful and accurate (e.g., not claiming cotton is wool, or advertising fake 'discounts').","distractor_reasons":{"A":"Option A is correct because laws against misleading promotion require advertisements and price-reduction claims to be truthful and accurate (e.g., not claiming cotton is wool, or advertising fake 'discounts').","B":"Incorrect because truthful advertising on social media or billboards is completely legal.","C":"Incorrect because genuine price reductions are legal; only false claims of a discount are prohibited.","D":"Incorrect because displaying accurate ingredients and origin is a legal requirement, not a violation."}}},{"id":"P1_U3_MCQ_614","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_614","question":"Which requirement is covered by legal controls over 'product quality and faulty goods'?","options":{"A":"Goods must always be sold at the lowest price in the industry.","B":"Goods must be of satisfactory quality, fit for their intended purpose, and perform as described.","C":"Goods must be packaged in single-use plastic containers.","D":"Goods must be sold exclusively through wholesalers rather than online."},"correctOption":"B","correctAnswer":"Goods must be of satisfactory quality, fit for their intended purpose, and perform as described.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because consumer protection laws make it illegal to sell goods that are faulty/unsatisfactory in quality, unfit for the purpose requested by the buyer, or fail to match their description.","distractor_reasons":{"A":"Incorrect because businesses are free to set high prices for high-quality goods.","B":"Option B is correct because consumer protection laws make it illegal to sell goods that are faulty/unsatisfactory in quality, unfit for the purpose requested by the buyer, or fail to match their description.","C":"Incorrect because many governments actually ban or restrict single-use plastics to protect the environment.","D":"Incorrect because businesses may choose any legal distribution channel."}}},{"id":"P1_U3_MCQ_615","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_615","question":"What is the purpose of 'Weights and Measures' legal controls?","options":{"A":"To limit the maximum physical size of retail supermarkets.","B":"To control the number of employees a factory can hire.","C":"To prevent businesses from selling underweight goods or using inaccurate weighing equipment.","D":"To ensure that all competitors charge identical prices per kilogram."},"correctOption":"C","correctAnswer":"To prevent businesses from selling underweight goods or using inaccurate weighing equipment.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Weights and Measures legislation protects consumers by ensuring goods contain the stated weight or volume and that scales/measuring equipment are accurate.","distractor_reasons":{"A":"Incorrect because retail store size is governed by local planning laws, not Weights and Measures.","B":"Incorrect because workforce size is not regulated by Weights and Measures laws.","C":"Option C is correct because Weights and Measures legislation protects consumers by ensuring goods contain the stated weight or volume and that scales/measuring equipment are accurate.","D":"Incorrect because businesses set their own prices per unit weight."}}},{"id":"P1_U3_MCQ_616","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_616","question":"What makes a 'misleading price reduction' claim illegal under consumer protection laws?","options":{"A":"Reducing a product's price by 20% after it has been sold at the higher price for several months.","B":"Charging a higher price in an airport shop than in a suburban supermarket.","C":"Offering a 'buy-one-get-one-free' promotion on perishable groceries.","D":"Advertising a 'special discount' (such as '$40 off') when the product was actually sold at the exact same price previously."},"correctOption":"D","correctAnswer":"Advertising a 'special discount' (such as '$40 off') when the product was actually sold at the exact same price previously.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because claiming a fake price reduction when the item was never genuinely sold at the higher 'original' price deceives consumers about the value of the offer.","distractor_reasons":{"A":"Incorrect because discounting a genuine previous selling price is a legal sales promotion.","B":"Incorrect because charging different prices in different locations is legal.","C":"Incorrect because genuine BOGOF offers are legal sales promotions.","D":"Option D is correct because claiming a fake price reduction when the item was never genuinely sold at the higher 'original' price deceives consumers about the value of the offer."}}},{"id":"P1_U3_MCQ_617","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_617","question":"What is a positive effect on a business of complying with consumer protection laws?","options":{"A":"It builds consumer confidence and a strong reputation for safe, reliable products, leading to repeat sales and avoiding fines.","B":"It reduces product design, quality testing, and manufacturing costs to zero.","C":"It allows the business to ignore customer complaints about faulty products.","D":"It exempts the business from having to advertise its products."},"correctOption":"A","correctAnswer":"It builds consumer confidence and a strong reputation for safe, reliable products, leading to repeat sales and avoiding fines.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because observing legal controls enhances brand reputation, increases buyer confidence, encourages repeat purchases, and protects the firm from legal fines and bad publicity.","distractor_reasons":{"A":"Option A is correct because observing legal controls enhances brand reputation, increases buyer confidence, encourages repeat purchases, and protects the firm from legal fines and bad publicity.","B":"Incorrect because meeting strict safety and quality standards increases design and testing costs.","C":"Incorrect because legal controls require businesses to refund, replace, or compensate consumers for faulty goods.","D":"Incorrect because legal compliance does not replace the need for promotion."}}},{"id":"P1_U3_MCQ_618","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_618","question":"What is a negative effect on a business of strict legal controls protecting consumers?","options":{"A":"Consumers lose trust in the safety of products sold in shops.","B":"Costs increase due to safer product designs, improved quality control, and potential compensation claims, which may force higher prices.","C":"Businesses are legally prevented from exporting products to other countries.","D":"Brand loyalty decreases because products last longer and work properly."},"correctOption":"B","correctAnswer":"Costs increase due to safer product designs, improved quality control, and potential compensation claims, which may force higher prices.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because complying with safety regulations, accurate labelling, and quality standards raises production and compliance costs, which may reduce profit margins or require higher selling prices.","distractor_reasons":{"A":"Incorrect because legal controls actually increase consumer trust in product safety.","B":"Option B is correct because complying with safety regulations, accurate labelling, and quality standards raises production and compliance costs, which may reduce profit margins or require higher selling prices.","C":"Incorrect because meeting high domestic quality standards often makes it easier to meet export standards.","D":"Incorrect because reliable, durable products strengthen rather than weaken brand loyalty."}}},{"id":"P1_U3_MCQ_619","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_619","question":"What happens if a business is found guilty of selling unsafe goods that injure a consumer?","options":{"A":"The business receives a government grant to expand its factory.","B":"The consumer is fined for failing to inspect the product before purchase.","C":"The business is legally liable to pay compensation to the injured consumer and suffers severe reputational damage.","D":"The business is allowed to continue selling the unsafe item if it lowers the price."},"correctOption":"C","correctAnswer":"The business is legally liable to pay compensation to the injured consumer and suffers severe reputational damage.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because manufacturers and retailers are legally liable to compensate consumers injured by unsafe or defective goods, alongside facing fines and damaging publicity.","distractor_reasons":{"A":"Incorrect because law-breaking businesses face penalties rather than government grants.","B":"Incorrect because consumer protection laws place legal responsibility on the seller/manufacturer, not the consumer.","C":"Option C is correct because manufacturers and retailers are legally liable to compensate consumers injured by unsafe or defective goods, alongside facing fines and damaging publicity.","D":"Incorrect because unsafe products must be recalled and withdrawn from sale regardless of price."}}},{"id":"P1_U3_MCQ_620","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_620","question":"Why might a law-abiding business suffer unfair competition when consumer protection laws are poorly enforced?","options":{"A":"Because law-abiding businesses are forbidden from lowering their prices.","B":"Because consumers always prefer buying dangerous, faulty goods.","C":"Because government inspectors close down law-abiding businesses first.","D":"Because unscrupulous traders can ignore safety and quality laws to sell cheap, substandard goods and undercut compliant firms."},"correctOption":"D","correctAnswer":"Because unscrupulous traders can ignore safety and quality laws to sell cheap, substandard goods and undercut compliant firms.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because if authorities fail to stop rogue traders who ignore safety and quality rules, those traders save compliance costs and undercut responsible businesses on price.","distractor_reasons":{"A":"Incorrect because compliant businesses can reduce prices if they lower costs efficiently, though compliance costs are higher.","B":"Incorrect because consumers want safe products, but may be misled by cheap prices from dishonest sellers.","C":"Incorrect because enforcement targets businesses that breach regulations.","D":"Option D is correct because if authorities fail to stop rogue traders who ignore safety and quality rules, those traders save compliance costs and undercut responsible businesses on price."}}},{"id":"P1_U3_MCQ_621","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_621","question":"How do legal controls over marketing affect a business's promotional activities?","options":{"A":"All advertisements and packaging labels must be truthful, accurate, and avoid exaggerated or false claims.","B":"Businesses are banned from using persuasive advertising on television or social media.","C":"Businesses are prohibited from offering loyalty cards or competitions.","D":"All promotional campaigns must be approved by competitors before launch."},"correctOption":"A","correctAnswer":"All advertisements and packaging labels must be truthful, accurate, and avoid exaggerated or false claims.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because marketing laws require all promotional claims, descriptions, and price comparisons to be honest and verifiable so consumers are not deceived.","distractor_reasons":{"A":"Option A is correct because marketing laws require all promotional claims, descriptions, and price comparisons to be honest and verifiable so consumers are not deceived.","B":"Incorrect because persuasive advertising is legal as long as it does not make false or misleading factual claims.","C":"Incorrect because loyalty schemes and competitions are legal sales promotions when run fairly.","D":"Incorrect because competitors have no authority to approve a rival's advertising."}}},{"id":"P1_U3_MCQ_622","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_622","question":"When planning to enter a foreign market, why must managers research the target country's 'legal requirements'?","options":{"A":"Because every country in the world uses the exact same product safety and advertising laws.","B":"Because certain products, ingredients, advertising images, or pricing practices legal at home may be restricted or illegal abroad.","C":"Because foreign governments require all importers to operate as sole traders.","D":"Because legal requirements determine how many levels of hierarchy a company must have."},"correctOption":"B","correctAnswer":"Because certain products, ingredients, advertising images, or pricing practices legal at home may be restricted or illegal abroad.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because safety standards, banned ingredients, advertising censorship rules, and price controls vary widely between countries, requiring compliance to avoid fines or product bans.","distractor_reasons":{"A":"Incorrect because national laws differ significantly from country to country.","B":"Option B is correct because safety standards, banned ingredients, advertising censorship rules, and price controls vary widely between countries, requiring compliance to avoid fines or product bans.","C":"Incorrect because foreign entrants typically operate as limited companies, joint ventures, or via local agents.","D":"Incorrect because internal management hierarchy is not dictated by foreign marketing laws."}}},{"id":"P1_U3_MCQ_623","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_623","question":"Which element of the marketing mix is directly affected when a business must change a product's electrical plug or safety features to meet foreign legal standards?","options":{"A":"Place (channel of distribution).","B":"Promotion (sales promotion).","C":"Product (design and specification).","D":"People (employee recruitment)."},"correctOption":"C","correctAnswer":"Product (design and specification).","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because modifying physical design, technical specifications, or safety components to meet legal regulations directly alters the 'product' element of the marketing mix.","distractor_reasons":{"A":"Incorrect because 'place' concerns distribution channels and retail outlets rather than physical product design.","B":"Incorrect because 'promotion' concerns advertising and sales incentives.","C":"Option C is correct because modifying physical design, technical specifications, or safety components to meet legal regulations directly alters the 'product' element of the marketing mix.","D":"Incorrect because employee recruitment is an HRM function rather than one of the four Ps."}}},{"id":"P1_U3_MCQ_624","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_624","question":"How can a business overcome the barrier of 'lack of local knowledge' when entering a new market in another country?","options":{"A":"By ignoring local consumer preferences and selling only unsold domestic inventory.","B":"By refusing to conduct any primary or secondary market research.","C":"By eliminating all customer service and after-sales support.","D":"By conducting detailed market research, appointing a local agent, or forming a joint venture with a local business."},"correctOption":"D","correctAnswer":"By conducting detailed market research, appointing a local agent, or forming a joint venture with a local business.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because local market research, experienced local agents, or joint ventures with domestic partners provide crucial insight into local culture, tastes, laws, and distribution.","distractor_reasons":{"A":"Incorrect because ignoring local tastes typically results in rejected products and financial losses.","B":"Incorrect because market research is essential to understand a new foreign market.","C":"Incorrect because poor customer service alienates new international buyers.","D":"Option D is correct because local market research, experienced local agents, or joint ventures with domestic partners provide crucial insight into local culture, tastes, laws, and distribution."}}},{"id":"P1_U3_MCQ_625","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_625","question":"What is the relationship between a 'marketing objective' and the 'marketing mix' within a marketing strategy?","options":{"A":"The marketing objective defines what the business wants to achieve, and the marketing mix provides the coordinated four Ps used to achieve it.","B":"The marketing mix is chosen first at random, and the marketing objective is invented afterward.","C":"The marketing objective applies only to finance, whereas the marketing mix applies only to production.","D":"They are unrelated concepts used by separate competing companies."},"correctOption":"A","correctAnswer":"The marketing objective defines what the business wants to achieve, and the marketing mix provides the coordinated four Ps used to achieve it.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a marketing strategy begins with a clear marketing objective (the target) and selects a consistent combination of product, price, place, and promotion (the tools) to achieve that target.","distractor_reasons":{"A":"Option A is correct because a marketing strategy begins with a clear marketing objective (the target) and selects a consistent combination of product, price, place, and promotion (the tools) to achieve that target.","B":"Incorrect because the objective must be set first so that the four Ps can be designed to achieve it.","C":"Incorrect because both the marketing objective and the four Ps belong to the marketing function.","D":"Incorrect because both are core components of a single business's marketing strategy."}}},{"id":"P1_U3_MCQ_626","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_626","question":"What is the primary role of marketing within a business?","options":{"A":"Identifying and satisfying customer needs and wants profitably.","B":"Maximising factory output regardless of current consumer demand.","C":"Setting the lowest possible price for every item produced.","D":"Managing internal employee recruitment and payroll administration."},"correctOption":"A","correctAnswer":"Identifying and satisfying customer needs and wants profitably.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because marketing is the management process responsible for identifying, anticipating, and satisfying customer requirements profitably.","distractor_reasons":{"A":"Option A is correct because marketing is the management process responsible for identifying, anticipating, and satisfying customer requirements profitably.","B":"Incorrect because maximising output without checking demand describes a product-oriented approach rather than marketing.","C":"Incorrect because pricing depends on the marketing mix and brand positioning, not always charging the lowest price.","D":"Incorrect because recruitment and payroll are functions of the Human Resource Management department."}}},{"id":"P1_U3_MCQ_627","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_627","question":"Why is anticipating changes in customer needs an important role of marketing?","options":{"A":"It eliminates the need to conduct any future market research.","B":"It enables a business to adapt products early before sales decline.","C":"It guarantees that competitors cannot enter the same industry.","D":"It ensures fixed production costs remain unchanged over time."},"correctOption":"B","correctAnswer":"It enables a business to adapt products early before sales decline.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because predicting shifts in consumer tastes allows a business to innovate and update its offerings ahead of falling demand.","distractor_reasons":{"A":"Incorrect because ongoing market research is still essential to track changing consumer trends.","B":"Option B is correct because predicting shifts in consumer tastes allows a business to innovate and update its offerings ahead of falling demand.","C":"Incorrect because anticipating customer needs helps a business compete, but does not legally block new rivals from entering.","D":"Incorrect because fixed costs are determined by scale and overheads, not by anticipating demand."}}},{"id":"P1_U3_MCQ_628","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_628","question":"What is meant by maintaining customer loyalty as an objective of marketing?","options":{"A":"Forcing customers to sign long-term contracts before purchasing.","B":"Selling products exclusively through wholesale intermediaries.","C":"Encouraging existing customers to make repeat purchases from the business.","D":"Preventing customers from comparing prices on the internet."},"correctOption":"C","correctAnswer":"Encouraging existing customers to make repeat purchases from the business.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because customer loyalty means building strong relationships so customers repeatedly choose the business's brand over competitors.","distractor_reasons":{"A":"Incorrect because loyalty relies on customer satisfaction and relationship building rather than legal compulsion.","B":"Incorrect because distribution choices relate to Place, not customer loyalty.","C":"Option C is correct because customer loyalty means building strong relationships so customers repeatedly choose the business's brand over competitors.","D":"Incorrect because businesses cannot stop consumers from comparing prices online."}}},{"id":"P1_U3_MCQ_629","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_629","question":"What is meant by the term 'market share'?","options":{"A":"The total value of all goods and services sold across an entire economy.","B":"The proportion of a company's shares owned by institutional investors.","C":"The difference between a product's selling price and its variable cost.","D":"The percentage of total market sales held by one brand or business."},"correctOption":"D","correctAnswer":"The percentage of total market sales held by one brand or business.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because market share measures a single business's or brand's sales revenue as a percentage of total sales revenue in that market.","distractor_reasons":{"A":"Incorrect because total economic output refers to Gross Domestic Product, not market share.","B":"Incorrect because this confuses market share with share capital ownership in a limited company.","C":"Incorrect because selling price minus variable cost is unit contribution.","D":"Option D is correct because market share measures a single business's or brand's sales revenue as a percentage of total sales revenue in that market."}}},{"id":"P1_U3_MCQ_630","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_630","question":"Which of the following is a direct benefit to a business of gaining a high market share?","options":{"A":"Zero need to spend money on product quality control or promotion.","B":"Complete exemption from government consumer protection regulations.","C":"Greater influence over suppliers and retailers due to high order volumes.","D":"Automatic elimination of all variable production costs."},"correctOption":"C","correctAnswer":"Greater influence over suppliers and retailers due to high order volumes.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because market leaders buy in large quantities and attract strong customer demand, giving them bargaining power over suppliers and distributors.","distractor_reasons":{"A":"Incorrect because market leaders must still maintain quality and promote products to defend their position.","B":"Incorrect because all businesses must obey consumer protection laws regardless of size.","C":"Option C is correct because market leaders buy in large quantities and attract strong customer demand, giving them bargaining power over suppliers and distributors.","D":"Incorrect because variable costs still rise with output."}}},{"id":"P1_U3_MCQ_631","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_631","question":"How do changes in consumer tastes and fashions affect markets?","options":{"A":"They keep demand for traditional products permanently constant.","B":"They cause spending patterns to shift rapidly toward newer trends.","C":"They eliminate the need for businesses to update product designs.","D":"They reduce competition in clothing and technology industries."},"correctOption":"B","correctAnswer":"They cause spending patterns to shift rapidly toward newer trends.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because evolving tastes and fashions lead consumers to abandon outdated styles and spend more on trending products.","distractor_reasons":{"A":"Incorrect because changing tastes cause demand for older products to fall rather than stay constant.","B":"Option B is correct because evolving tastes and fashions lead consumers to abandon outdated styles and spend more on trending products.","C":"Incorrect because shifting fashions force businesses to regularly update designs.","D":"Incorrect because fast-changing trends typically intensify competition among rivals."}}},{"id":"P1_U3_MCQ_632","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_632","question":"Why do changes in technology frequently alter consumer spending patterns?","options":{"A":"Technological progress forces governments to ban all imported goods.","B":"New technology always increases the average cost of manufacturing.","C":"Innovative products make older versions obsolete and shift consumer demand.","D":"Consumers prefer buying products that lack modern digital features."},"correctOption":"C","correctAnswer":"Innovative products make older versions obsolete and shift consumer demand.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because technological advancements introduce improved features and new products, causing demand for outdated alternatives to fall.","distractor_reasons":{"A":"Incorrect because technological change encourages international trade rather than import bans.","B":"Incorrect because new technology usually lowers average production costs through efficiency.","C":"Option C is correct because technological advancements introduce improved features and new products, causing demand for outdated alternatives to fall.","D":"Incorrect because most consumers shift spending toward newer, more capable technologies."}}},{"id":"P1_U3_MCQ_633","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_633","question":"How does a rise in average household income typically change consumer spending patterns?","options":{"A":"Consumers spend all of their extra income solely on basic necessities.","B":"Demand for luxury and non-essential goods and services tends to fall.","C":"Businesses are forced to switch from mass markets to niche markets.","D":"Consumers spend a higher proportion of income on luxury and leisure items."},"correctOption":"D","correctAnswer":"Consumers spend a higher proportion of income on luxury and leisure items.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because higher disposable incomes enable consumers to buy more luxury goods, holidays, and branded products after covering basic needs.","distractor_reasons":{"A":"Incorrect because spending on basic necessities rises very little once essential needs are met.","B":"Incorrect because rising incomes increase, rather than decrease, demand for luxury items.","C":"Incorrect because higher incomes expand overall demand in both mass and niche markets.","D":"Option D is correct because higher disposable incomes enable consumers to buy more luxury goods, holidays, and branded products after covering basic needs."}}},{"id":"P1_U3_MCQ_634","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_634","question":"A country's proportion of retired citizens is rising steadily. Which change in consumer spending patterns is most likely to follow?","options":{"A":"Greater demand for healthcare and leisure services for older people","B":"Higher demand for children's toys and nursery schools","C":"A fall in demand for all services regardless of age","D":"Increased spending on baby food and nappies"},"correctOption":"A","correctAnswer":"Greater demand for healthcare and leisure services for older people","questionType":"MCQ","explanation":{"correct_reason":"An ageing population increases the number of consumers needing healthcare, retirement housing and leisure activities suited to older people.","distractor_reasons":{"B":"Demand for children's goods rises with a younger population, not when the share of retired people is growing.","C":"An ageing population shifts the pattern of spending rather than reducing demand for every kind of service.","D":"Baby products are demanded by younger families, so their spending does not rise as the population ages.","A":"An ageing population increases the number of consumers needing healthcare, retirement housing and leisure activities suited to older people."}}},{"id":"P1_U3_MCQ_635","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_635","question":"Which development has made many national markets significantly more competitive in recent decades?","options":{"A":"Higher transport costs that prevent goods from crossing national borders.","B":"Globalisation and the expansion of multinational companies into domestic markets.","C":"Government laws prohibiting businesses from advertising on social media.","D":"A worldwide decline in consumer access to smartphones and the internet."},"correctOption":"B","correctAnswer":"Globalisation and the expansion of multinational companies into domestic markets.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because globalisation and multinational companies expose domestic firms to rivalry from large foreign producers.","distractor_reasons":{"A":"Incorrect because transport costs have generally fallen, increasing international competition.","B":"Option B is correct because globalisation and multinational companies expose domestic firms to rivalry from large foreign producers.","C":"Incorrect because social media advertising is widely permitted and used globally.","D":"Incorrect because smartphone and internet usage has expanded rapidly worldwide."}}},{"id":"P1_U3_MCQ_636","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_636","question":"How has the growth of e-commerce increased competition in retail markets?","options":{"A":"It restricts consumers to buying only from shops within walking distance.","B":"It prevents small businesses from selling goods outside their home town.","C":"It allows consumers to easily compare prices and buy from sellers worldwide.","D":"It forces all online sellers to charge identical prices for products."},"correctOption":"C","correctAnswer":"It allows consumers to easily compare prices and buy from sellers worldwide.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because online shopping enables consumers to compare prices instantly and order from domestic or overseas competitors.","distractor_reasons":{"A":"Incorrect because e-commerce removes geographic distance barriers for shoppers.","B":"Incorrect because websites allow even small firms to reach national and global buyers.","C":"Option C is correct because online shopping enables consumers to compare prices instantly and order from domestic or overseas competitors.","D":"Incorrect because online businesses set their own competitive prices."}}},{"id":"P1_U3_MCQ_637","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_637","question":"Which of the following is an effective way for a business to respond to increased market competition?","options":{"A":"Reducing product quality while raising selling prices.","B":"Stopping all communication with existing customers.","C":"Ignoring changes in competitor pricing and product features.","D":"Maintaining strong customer relationships and improving product quality."},"correctOption":"D","correctAnswer":"Maintaining strong customer relationships and improving product quality.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because superior quality and strong customer relationships build loyalty and differentiate the business from rivals.","distractor_reasons":{"A":"Incorrect because lowering quality while raising prices drives customers to competitors.","B":"Incorrect because weak communication alienates customers in a competitive market.","C":"Incorrect because ignoring rivals causes a business to lose market share.","D":"Option D is correct because superior quality and strong customer relationships build loyalty and differentiate the business from rivals."}}},{"id":"P1_U3_MCQ_638","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_638","question":"How can a business respond effectively when consumer spending patterns shift away from its existing products?","options":{"A":"Increase fixed overhead costs to raise the break-even output level.","B":"Continue producing the exact same range without conducting research.","C":"Develop new products that match current customer needs and keep costs low.","D":"Eliminate all promotional activities to avoid informing consumers."},"correctOption":"C","correctAnswer":"Develop new products that match current customer needs and keep costs low.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because innovating new products aligned with changing demand and controlling costs keeps the business competitive and profitable.","distractor_reasons":{"A":"Incorrect because higher fixed costs raise break-even output and reduce profitability.","B":"Incorrect because continuing to sell unwanted products leads to falling sales and failure.","C":"Option C is correct because innovating new products aligned with changing demand and controlling costs keeps the business competitive and profitable.","D":"Incorrect because promotion is necessary to make buyers aware of updated products."}}},{"id":"P1_U3_MCQ_639","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_639","question":"A supermarket chain stocks one standard range of breakfast cereal aimed at almost all households rather than targeting any particular group. What kind of market is it serving?","options":{"A":"A mass market, where products appeal to a broad range of customers","B":"A niche market","C":"A single-customer market","D":"An industrial market"},"correctOption":"A","correctAnswer":"A mass market, where products appeal to a broad range of customers","questionType":"MCQ","explanation":{"correct_reason":"A product designed for the vast majority of consumers with similar needs is aimed at a mass market.","distractor_reasons":{"B":"A niche market serves a narrow, specialised group, the opposite of a cereal for nearly all households.","C":"A market of one customer would be an extreme bespoke case, not a standard range for many households.","D":"An industrial market involves goods bought by businesses for production, not cereals sold to households.","A":"A product designed for the vast majority of consumers with similar needs is aimed at a mass market."}}},{"id":"P1_U3_MCQ_640","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_640","question":"What is a major advantage to a business of operating in a mass market?","options":{"A":"There are no rival businesses competing for the same customers.","B":"Products can be custom-made individually without using machinery.","C":"High sales volumes enable economies of scale and lower average costs.","D":"Customers are always willing to pay luxury prices for basic items."},"correctOption":"C","correctAnswer":"High sales volumes enable economies of scale and lower average costs.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because large-scale production and sales in a mass market allow firms to benefit from purchasing, technical, and marketing economies of scale.","distractor_reasons":{"A":"Incorrect because mass markets attract intense competition from many rivals.","B":"Incorrect because mass markets rely on flow/mass production of standardised goods rather than one-off job production.","C":"Option C is correct because large-scale production and sales in a mass market allow firms to benefit from purchasing, technical, and marketing economies of scale.","D":"Incorrect because standardised mass-market goods are usually sold at competitive, lower prices."}}},{"id":"P1_U3_MCQ_641","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_641","question":"Which of the following is a disadvantage of operating in a mass market?","options":{"A":"Total potential sales volume is strictly limited to a few buyers.","B":"Average production costs are higher than in bespoke job production.","C":"Businesses cannot use national television or social media advertising.","D":"High competition forces heavy spending on advertising and keeps prices low."},"correctOption":"D","correctAnswer":"High competition forces heavy spending on advertising and keeps prices low.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because fierce rivalry in mass markets drives down prices and requires large promotional budgets to stand out.","distractor_reasons":{"A":"Incorrect because limited sales volume is a disadvantage of a niche market, not a mass market.","B":"Incorrect because mass production achieves lower average unit costs than job production.","C":"Incorrect because mass-market firms frequently use national advertising media.","D":"Option D is correct because fierce rivalry in mass markets drives down prices and requires large promotional budgets to stand out."}}},{"id":"P1_U3_MCQ_642","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_642","question":"A firm produces expensive, specialised hiking boots only for serious mountaineers and charges premium prices. Which market approach is this?","options":{"A":"A niche market, focusing on a narrow, specific group of customers","B":"A mass market","C":"An undifferentiated market","D":"A whole-population market"},"correctOption":"A","correctAnswer":"A niche market, focusing on a narrow, specific group of customers","questionType":"MCQ","explanation":{"correct_reason":"Targeting a small, well-defined group with specialist, premium products is a niche market approach.","distractor_reasons":{"B":"A mass market aims at a large, broad audience rather than serious mountaineers alone.","C":"An undifferentiated market offers the same product to everyone, which is not the case for specialist boots.","D":"Serving the whole population is the opposite of concentrating on a narrow group of enthusiasts.","A":"Targeting a small, well-defined group with specialist, premium products is a niche market approach."}}},{"id":"P1_U3_MCQ_643","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_643","question":"What is a key advantage to a small business of targeting a niche market?","options":{"A":"It guarantees millions of unit sales every year.","B":"It avoids direct competition from large mass-market businesses.","C":"It achieves maximum purchasing economies of scale.","D":"It eliminates the need to understand specific customer needs."},"correctOption":"B","correctAnswer":"It avoids direct competition from large mass-market businesses.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because large corporations often overlook small niche segments, allowing smaller firms to serve specialised needs with less rivalry and higher profit margins.","distractor_reasons":{"A":"Incorrect because niche markets have small total customer numbers.","B":"Option B is correct because large corporations often overlook small niche segments, allowing smaller firms to serve specialised needs with less rivalry and higher profit margins.","C":"Incorrect because low output volumes prevent niche firms from gaining large bulk-buying discounts.","D":"Incorrect because serving a niche requires deep understanding of customers' specialised requirements."}}},{"id":"P1_U3_MCQ_644","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_644","question":"Which of the following is a major disadvantage of operating in a niche market?","options":{"A":"Products cannot be tailored to specific customer preferences.","B":"Prices must always be set lower than mass-market alternatives.","C":"Limited market size restricts growth and leaves the firm vulnerable if demand falls.","D":"Large multinational firms dominate every small niche segment."},"correctOption":"C","correctAnswer":"Limited market size restricts growth and leaves the firm vulnerable if demand falls.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because niche markets have few customers, limiting economies of scale and creating high risk if consumer tastes change.","distractor_reasons":{"A":"Incorrect because tailoring products to specialised needs is a primary strength of niche marketing.","B":"Incorrect because niche products often command premium prices due to specialisation.","C":"Option C is correct because niche markets have few customers, limiting economies of scale and creating high risk if consumer tastes change.","D":"Incorrect because large multinationals usually focus on high-volume mass markets."}}},{"id":"P1_U3_MCQ_645","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_645","question":"A cosmetics firm divides customers by age, income and lifestyle and designs a different product range for each group. What is this process called?","options":{"A":"Market research sampling","B":"Mass marketing","C":"Product deletion","D":"Market segmentation"},"correctOption":"D","correctAnswer":"Market segmentation","questionType":"MCQ","explanation":{"correct_reason":"Dividing a broad market into distinct groups with common characteristics and targeting each separately is market segmentation.","distractor_reasons":{"B":"Mass marketing treats the whole market as one group, whereas this firm separates customers into categories.","C":"Product deletion means removing items from the range, not grouping customers by their characteristics.","D":"Dividing a broad market into distinct groups with common characteristics and targeting each separately is market segmentation.","A":"Sampling selects survey respondents; segmentation classifies customers for marketing purposes."}}},{"id":"P1_U3_MCQ_646","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_646","question":"Which basis of market segmentation groups consumers into categories such as children, teenagers, adults, and senior citizens?","options":{"A":"Lifestyle segmentation.","B":"Location segmentation.","C":"Income segmentation.","D":"Age segmentation."},"correctOption":"D","correctAnswer":"Age segmentation.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because segmenting by age divides consumers according to their stage of life, as different age groups demand different products.","distractor_reasons":{"A":"Incorrect because lifestyle segmentation groups consumers by hobbies, interests, and attitudes.","B":"Incorrect because location segmentation divides buyers by geographic region or climate.","C":"Incorrect because income segmentation groups buyers by earnings and spending power.","D":"Option D is correct because segmenting by age divides consumers according to their stage of life, as different age groups demand different products."}}},{"id":"P1_U3_MCQ_647","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_647","question":"Why do businesses segment markets according to consumer income?","options":{"A":"Because all income groups buy identical luxury goods.","B":"Because consumers with different earnings can afford different price levels and quality.","C":"Because income segmentation eliminates the need for advertising.","D":"Because consumer income never changes during an economic cycle."},"correctOption":"B","correctAnswer":"Because consumers with different earnings can afford different price levels and quality.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because grouping buyers by income allows businesses to offer budget ranges to lower-income groups and premium goods to higher-income groups.","distractor_reasons":{"A":"Incorrect because lower-income consumers cannot afford luxury items.","B":"Option B is correct because grouping buyers by income allows businesses to offer budget ranges to lower-income groups and premium goods to higher-income groups.","C":"Incorrect because businesses must still promote products to each targeted income segment.","D":"Incorrect because incomes fluctuate with employment levels and economic growth."}}},{"id":"P1_U3_MCQ_648","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_648","question":"Which factor is being used when a business adapts its clothing range according to regional climate and urban versus rural areas?","options":{"A":"Gender segmentation.","B":"Age segmentation.","C":"Location segmentation.","D":"Income segmentation."},"correctOption":"C","correctAnswer":"Location segmentation.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because location segmentation divides consumers based on where they live, including climate, country, or urban/rural differences.","distractor_reasons":{"A":"Incorrect because gender segmentation divides markets between male and female consumers.","B":"Incorrect because age segmentation divides consumers by age brackets.","C":"Option C is correct because location segmentation divides consumers based on where they live, including climate, country, or urban/rural differences.","D":"Incorrect because income segmentation divides buyers by earnings."}}},{"id":"P1_U3_MCQ_649","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_649","question":"What does segmenting a market by 'lifestyle' involve?","options":{"A":"Grouping consumers strictly by their annual salary.","B":"Grouping consumers solely by the postal code of their home.","C":"Grouping consumers only by whether they are male or female.","D":"Grouping consumers according to their hobbies, interests, and attitudes."},"correctOption":"D","correctAnswer":"Grouping consumers according to their hobbies, interests, and attitudes.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because lifestyle segmentation classifies consumers based on their activities, interests, values, and how they choose to live.","distractor_reasons":{"A":"Incorrect because annual salary is the basis of income segmentation.","B":"Incorrect because postal codes relate to location segmentation.","C":"Incorrect because male and female categories represent gender segmentation.","D":"Option D is correct because lifestyle segmentation classifies consumers based on their activities, interests, values, and how they choose to live."}}},{"id":"P1_U3_MCQ_650","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_650","question":"What is a major advantage to a business of using market segmentation?","options":{"A":"It enables the marketing mix to be tailored closely to specific customer needs, boosting sales.","B":"It lowers production costs by ensuring only one identical product is ever made.","C":"It completely removes the cost of conducting market research.","D":"It prevents competitors from targeting the same consumer groups."},"correctOption":"A","correctAnswer":"It enables the marketing mix to be tailored closely to specific customer needs, boosting sales.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because understanding each segment's exact needs allows a firm to design targeted products, prices, and promotions, increasing sales and reducing wasted advertising.","distractor_reasons":{"A":"Option A is correct because understanding each segment's exact needs allows a firm to design targeted products, prices, and promotions, increasing sales and reducing wasted advertising.","B":"Incorrect because segmentation often requires producing different product variations, which can raise production costs.","C":"Incorrect because market research is needed to identify and understand market segments.","D":"Incorrect because competitors are free to target the same profitable segments."}}},{"id":"P1_U3_MCQ_651","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_651","question":"Which statement accurately describes a market-oriented business?","options":{"A":"It develops a product first based on engineering skill and then searches for buyers.","B":"It carries out market research to identify customer needs before developing a product.","C":"It ignores customer feedback and focuses solely on lowering factory costs.","D":"It refuses to change its product design even when consumer tastes shift."},"correctOption":"B","correctAnswer":"It carries out market research to identify customer needs before developing a product.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a market-oriented business puts the customer first by researching wants and needs prior to designing and producing goods.","distractor_reasons":{"A":"Incorrect because designing a product before researching demand describes a product-oriented business.","B":"Option B is correct because a market-oriented business puts the customer first by researching wants and needs prior to designing and producing goods.","C":"Incorrect because market-oriented firms actively collect and act upon customer feedback.","D":"Incorrect because market-oriented businesses adapt their offerings to match evolving consumer preferences."}}},{"id":"P1_U3_MCQ_652","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_652","question":"What is a key characteristic of a product-oriented business?","options":{"A":"It conducts extensive consumer surveys before designing any prototype.","B":"It relies exclusively on secondary government data to set prices.","C":"It focuses primarily on the product itself and production quality before finding a market.","D":"It only operates in the tertiary service sector of the economy."},"correctOption":"C","correctAnswer":"It focuses primarily on the product itself and production quality before finding a market.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because product-oriented businesses concentrate on manufacturing a high-quality or innovative product first, then try to persuade consumers to buy it.","distractor_reasons":{"A":"Incorrect because researching customer wants before design is the hallmark of a market-oriented business.","B":"Incorrect because pricing and research methods do not define product orientation.","C":"Option C is correct because product-oriented businesses concentrate on manufacturing a high-quality or innovative product first, then try to persuade consumers to buy it.","D":"Incorrect because product-oriented businesses are frequently found in manufacturing and technology sectors."}}},{"id":"P1_U3_MCQ_653","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_653","question":"What is the main reason why businesses carry out market research?","options":{"A":"To guarantee that every new product will earn a monopoly profit.","B":"To avoid paying legal minimum wages to sales employees.","C":"To replace the need for quality control in the factory.","D":"To reduce the risk of product failure by understanding customer needs and competition."},"correctOption":"D","correctAnswer":"To reduce the risk of product failure by understanding customer needs and competition.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because market research provides information about consumer preferences, market size, and competitors, lowering the risk of launching unsuitable products.","distractor_reasons":{"A":"Incorrect because market research reduces risk, but cannot guarantee success or monopoly status.","B":"Incorrect because legal minimum wage laws apply regardless of market research.","C":"Incorrect because quality control ensures production standards, whereas market research gathers market data.","D":"Option D is correct because market research provides information about consumer preferences, market size, and competitors, lowering the risk of launching unsuitable products."}}},{"id":"P1_U3_MCQ_654","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_654","question":"What is meant by 'primary market research' (field research)?","options":{"A":"The extraction of raw materials such as oil and timber from the Earth.","B":"The analysis of historical sales statistics already published by government departments.","C":"The reading of competitor websites and trade magazines to gather industry news.","D":"The collection and collation of original, first-hand data directly from potential or existing customers."},"correctOption":"D","correctAnswer":"The collection and collation of original, first-hand data directly from potential or existing customers.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because primary research involves gathering brand-new, original data directly from the field for a specific business purpose.","distractor_reasons":{"A":"Incorrect because extracting natural resources defines the primary sector of industry, not primary research.","B":"Incorrect because using existing government statistics is secondary (desk) research.","C":"Incorrect because reviewing published websites and trade magazines is secondary research.","D":"Option D is correct because primary research involves gathering brand-new, original data directly from the field for a specific business purpose."}}},{"id":"P1_U3_MCQ_655","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_655","question":"What is meant by 'secondary market research' (desk research)?","options":{"A":"Conducting face-to-face interviews with shoppers in a town centre.","B":"Using information that has already been collected and published by other organisations.","C":"Observing customers as they select items from supermarket shelves.","D":"Organising a focus group to test a newly invented product prototype."},"correctOption":"B","correctAnswer":"Using information that has already been collected and published by other organisations.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because secondary research uses existing data previously gathered for another purpose, such as market reports, government data, or company records.","distractor_reasons":{"A":"Incorrect because interviewing shoppers collects new first-hand data (primary research).","B":"Option B is correct because secondary research uses existing data previously gathered for another purpose, such as market reports, government data, or company records.","C":"Incorrect because observing shoppers is a primary research method.","D":"Incorrect because running a focus group generates original primary data."}}},{"id":"P1_U3_MCQ_656","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_656","question":"What is a major advantage of primary research compared to secondary research?","options":{"A":"It is always completely free of charge to collect.","B":"It requires no planning or questionnaire design.","C":"The data is up to date and collected specifically for the business's exact needs.","D":"It can be completed in seconds without contacting any consumers."},"correctOption":"C","correctAnswer":"The data is up to date and collected specifically for the business's exact needs.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because primary research is tailored to the business's specific questions and reflects current market conditions, unlike older secondary sources.","distractor_reasons":{"A":"Incorrect because primary research is usually expensive to conduct.","B":"Incorrect because primary research requires careful design of surveys, samples, or interviews.","C":"Option C is correct because primary research is tailored to the business's specific questions and reflects current market conditions, unlike older secondary sources.","D":"Incorrect because collecting original data from consumers is time-consuming."}}},{"id":"P1_U3_MCQ_657","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_657","question":"Which of the following is a disadvantage of primary market research?","options":{"A":"The information is freely available to all rival competitors.","B":"The data is always several years out of date before collection.","C":"It cannot be used to ask consumers about new product ideas.","D":"It is often expensive and time-consuming to collect and analyse."},"correctOption":"D","correctAnswer":"It is often expensive and time-consuming to collect and analyse.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because designing surveys, paying interviewers, and analysing original responses requires substantial time and money.","distractor_reasons":{"A":"Incorrect because primary data belongs to the business that collected it, whereas secondary data is publicly available.","B":"Incorrect because out-of-date data is a limitation of secondary research, not primary research.","C":"Incorrect because primary research is ideal for testing new product concepts.","D":"Option D is correct because designing surveys, paying interviewers, and analysing original responses requires substantial time and money."}}},{"id":"P1_U3_MCQ_658","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_658","question":"What is a key advantage of secondary market research?","options":{"A":"It is guaranteed to answer the business's exact product-specific questions.","B":"It is relatively cheap and quick to obtain compared to primary research.","C":"It prevents competitors from accessing the same published statistics.","D":"It eliminates any risk of bias in the original data collection."},"correctOption":"B","correctAnswer":"It is relatively cheap and quick to obtain compared to primary research.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because secondary sources like government websites and trade reports already exist, saving time and money.","distractor_reasons":{"A":"Incorrect because secondary data was collected for another purpose and may not fit specific business needs.","B":"Option B is correct because secondary sources like government websites and trade reports already exist, saving time and money.","C":"Incorrect because published secondary sources are accessible to competitors too.","D":"Incorrect because secondary data may still contain bias or errors from whoever originally collected it."}}},{"id":"P1_U3_MCQ_659","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_659","question":"What is a major limitation of relying solely on secondary market research?","options":{"A":"It takes longer to access than conducting nationwide face-to-face interviews.","B":"The data may be out of date or collected for a different purpose.","C":"It can only provide qualitative opinions rather than numerical figures.","D":"It is illegal to use government statistics for commercial planning."},"correctOption":"B","correctAnswer":"The data may be out of date or collected for a different purpose.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because published data may reflect past market conditions or be too broad for a specific product decision.","distractor_reasons":{"A":"Incorrect because secondary research is much faster to gather than field interviews.","B":"Option B is correct because published data may reflect past market conditions or be too broad for a specific product decision.","C":"Incorrect because secondary sources often provide quantitative statistics such as population and sales data.","D":"Incorrect because government statistics are publicly provided for business and research use."}}},{"id":"P1_U3_MCQ_660","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_660","question":"Which primary research method involves asking a sample of consumers a set of structured questions online, by post, or in person?","options":{"A":"Observation.","B":"Trade magazine review.","C":"Questionnaire or survey.","D":"Competitor website analysis."},"correctOption":"C","correctAnswer":"Questionnaire or survey.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because questionnaires or surveys use a planned list of questions to gather structured responses from a sample of people.","distractor_reasons":{"A":"Incorrect because observation watches behaviour without asking questions.","B":"Incorrect because reading trade magazines is secondary research.","C":"Option C is correct because questionnaires or surveys use a planned list of questions to gather structured responses from a sample of people.","D":"Incorrect because reviewing competitor websites is secondary research."}}},{"id":"P1_U3_MCQ_661","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_661","question":"Which problem can reduce the reliability of data collected through online or postal questionnaires?","options":{"A":"Interviewer facial expressions influencing every respondent.","B":"Inability to ask any quantitative multiple-choice questions.","C":"Excessive cost of hiring physical meeting rooms for respondents.","D":"Low response rates and poorly worded questions that bias answers."},"correctOption":"D","correctAnswer":"Low response rates and poorly worded questions that bias answers.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because many people ignore online or postal surveys, and unclear or leading questions can distort the results.","distractor_reasons":{"A":"Incorrect because there is no interviewer present during self-completed online or postal questionnaires.","B":"Incorrect because questionnaires are ideal for collecting quantitative multiple-choice data.","C":"Incorrect because hiring meeting rooms is a cost associated with focus groups, not postal/online surveys.","D":"Option D is correct because many people ignore online or postal surveys, and unclear or leading questions can distort the results."}}},{"id":"P1_U3_MCQ_662","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_662","question":"What is a key advantage of using face-to-face interviews as a primary research method?","options":{"A":"The interviewer can explain unclear questions and gather detailed responses.","B":"It is the cheapest method for reaching millions of global consumers overnight.","C":"It completely eliminates any possibility of interviewer bias.","D":"Respondents always give honest answers even on sensitive personal topics."},"correctOption":"A","correctAnswer":"The interviewer can explain unclear questions and gather detailed responses.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because direct interaction allows the interviewer to clarify misunderstandings and probe deeper into customer opinions.","distractor_reasons":{"A":"Option A is correct because direct interaction allows the interviewer to clarify misunderstandings and probe deeper into customer opinions.","B":"Incorrect because interviewing people individually is expensive and slow compared to online surveys.","C":"Incorrect because interviewers can unintentionally influence respondents through tone or wording.","D":"Incorrect because respondents may give socially desirable rather than completely honest answers in person."}}},{"id":"P1_U3_MCQ_663","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_663","question":"What is a disadvantage of using interviews to gather primary market research?","options":{"A":"Questions cannot be explained if a respondent is confused.","B":"Trained interviewers are expensive to employ and interviewer bias may occur.","C":"It only provides secondary historical data from past years.","D":"It cannot be used to gather qualitative consumer opinions."},"correctOption":"B","correctAnswer":"Trained interviewers are expensive to employ and interviewer bias may occur.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because conducting individual interviews requires paying skilled staff and risks the interviewer leading the respondent's answers.","distractor_reasons":{"A":"Incorrect because clarifying questions is an advantage of interviews, not a disadvantage.","B":"Option B is correct because conducting individual interviews requires paying skilled staff and risks the interviewer leading the respondent's answers.","C":"Incorrect because interviews collect original primary data.","D":"Incorrect because interviews are well suited to collecting detailed qualitative insights."}}},{"id":"P1_U3_MCQ_664","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_664","question":"A snack-food company invites eight teenagers to a guided discussion about packaging designs and records their reactions. Which research method is being used?","options":{"A":"A focus group","B":"A questionnaire survey","C":"Random sampling of households","D":"Analysis of government statistics"},"correctOption":"A","correctAnswer":"A focus group","questionType":"MCQ","explanation":{"correct_reason":"A small group led through a discussion to reveal opinions and reactions is a focus group, a qualitative research method.","distractor_reasons":{"B":"A questionnaire uses written questions given to many respondents, not a guided group discussion.","C":"Random sampling is a selection method for surveys, not a discussion with a handful of participants.","D":"Government statistics are secondary data, whereas this company is gathering fresh opinions from consumers.","A":"A small group led through a discussion to reveal opinions and reactions is a focus group, a qualitative research method."}}},{"id":"P1_U3_MCQ_665","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_665","question":"Which of the following is a disadvantage of using focus groups for market research?","options":{"A":"Participants are not allowed to express detailed opinions.","B":"It relies purely on outdated government census publications.","C":"It cannot be used to test packaging designs or advertisements.","D":"Dominant group members may influence the opinions expressed by quieter participants."},"correctOption":"D","correctAnswer":"Dominant group members may influence the opinions expressed by quieter participants.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because outspoken individuals in a group discussion can sway others, biasing the qualitative feedback collected.","distractor_reasons":{"A":"Incorrect because encouraging detailed opinions is the main purpose of a focus group.","B":"Incorrect because focus groups generate new primary data.","C":"Incorrect because focus groups are frequently used to test packaging and adverts.","D":"Option D is correct because outspoken individuals in a group discussion can sway others, biasing the qualitative feedback collected."}}},{"id":"P1_U3_MCQ_666","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_666","question":"How does the 'observation' method of primary market research work?","options":{"A":"Watching and recording consumer behaviour, such as store traffic or product selection.","B":"Mailing paper questionnaires to thousands of households across the country.","C":"Reading published market reports written by independent research agencies.","D":"Interviewing a panel of consumers about why they prefer a rival brand."},"correctOption":"A","correctAnswer":"Watching and recording consumer behaviour, such as store traffic or product selection.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because observation involves recording actual consumer actions (such as counting shoppers or watching shelf choices) without direct questioning.","distractor_reasons":{"A":"Option A is correct because observation involves recording actual consumer actions (such as counting shoppers or watching shelf choices) without direct questioning.","B":"Incorrect because mailing surveys is the questionnaire method.","C":"Incorrect because reading published reports is secondary research.","D":"Incorrect because questioning a panel is an interview or focus group method."}}},{"id":"P1_U3_MCQ_667","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_667","question":"What is the main limitation of observation as a method of market research?","options":{"A":"It is illegal to record customer footfall inside retail stores.","B":"It shows how consumers behave, but does not explain the reasons behind their choices.","C":"It requires consumers to fill out lengthy written forms.","D":"It can only be used for secondary desk research."},"correctOption":"B","correctAnswer":"It shows how consumers behave, but does not explain the reasons behind their choices.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because observation records visible actions (what people buy or where they walk) without revealing their underlying motives.","distractor_reasons":{"A":"Incorrect because observing public shopper behaviour is a standard legal research practice.","B":"Option B is correct because observation records visible actions (what people buy or where they walk) without revealing their underlying motives.","C":"Incorrect because observation does not require respondents to complete forms.","D":"Incorrect because observation collects new primary data."}}},{"id":"P1_U3_MCQ_668","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_668","question":"Which of the following is an example of an external secondary research source?","options":{"A":"A questionnaire designed and distributed by the business's own marketing team.","B":"A focus group hosted at the company's headquarters.","C":"Government census statistics and published market research reports.","D":"Live observation of shoppers entering the business's retail branch."},"correctOption":"C","correctAnswer":"Government census statistics and published market research reports.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because government statistics and commercial market reports are published by external organisations and already exist.","distractor_reasons":{"A":"Incorrect because an original questionnaire is primary research.","B":"Incorrect because a focus group generates original primary research.","C":"Option C is correct because government statistics and commercial market reports are published by external organisations and already exist.","D":"Incorrect because observing shoppers collects primary data."}}},{"id":"P1_U3_MCQ_669","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_669","question":"Why do businesses examine competitor websites and trade magazines during market research?","options":{"A":"To collect first-hand primary feedback from their own loyal customers.","B":"To conduct random sampling of local household incomes.","C":"To avoid having to pay any taxes on online sales.","D":"To gather secondary data on rival prices, product ranges, and industry trends."},"correctOption":"D","correctAnswer":"To gather secondary data on rival prices, product ranges, and industry trends.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because competitor websites and trade publications provide readily available secondary information about rivals and market developments.","distractor_reasons":{"A":"Incorrect because reviewing websites and magazines is secondary desk research, not primary customer feedback.","B":"Incorrect because random sampling is a primary survey technique.","C":"Incorrect because market research does not affect tax obligations.","D":"Option D is correct because competitor websites and trade publications provide readily available secondary information about rivals and market developments."}}},{"id":"P1_U3_MCQ_670","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_670","question":"A phone company wants to gauge satisfaction among its one million users, so it questions 1,000 of them and uses their answers to infer the views of all users. What are the 1,000 users called?","options":{"A":"The population","B":"A sample","C":"A focus group","D":"A census"},"correctOption":"B","correctAnswer":"A sample","questionType":"MCQ","explanation":{"correct_reason":"The subgroup actually surveyed in order to draw conclusions about the whole group is the sample.","distractor_reasons":{"B":"The subgroup actually surveyed in order to draw conclusions about the whole group is the sample.","C":"A focus group is a small guided discussion, not the statistical term for a surveyed subgroup.","D":"A census would question every user, whereas here only 1,000 were asked.","A":"The population is all one million users, not the 1,000 who were questioned."}}},{"id":"P1_U3_MCQ_671","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_671","question":"Why is sampling useful to businesses conducting primary market research?","options":{"A":"It guarantees 100% accuracy without any margin of error.","B":"It is much cheaper and faster than surveying every individual in the target market.","C":"It eliminates the need to write clear survey questions.","D":"It allows businesses to ignore the target market's demographic profile."},"correctOption":"B","correctAnswer":"It is much cheaper and faster than surveying every individual in the target market.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because surveying an entire population is usually impractical and costly, whereas a well-chosen sample provides reliable insights quickly and affordably.","distractor_reasons":{"A":"Incorrect because sampling always carries some degree of sampling error.","B":"Option B is correct because surveying an entire population is usually impractical and costly, whereas a well-chosen sample provides reliable insights quickly and affordably.","C":"Incorrect because clear, unbiased questions are still essential for accurate results.","D":"Incorrect because understanding the target market's profile is vital for selecting a representative sample."}}},{"id":"P1_U3_MCQ_672","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_672","question":"How are respondents chosen in a 'random sample'?","options":{"A":"Only the business's existing loyal customers are invited to reply.","B":"Interviewers select people strictly based on specific age and income quotas.","C":"Every member of the target population has an equal chance of being selected.","D":"Only respondents who volunteer on social media are included."},"correctOption":"C","correctAnswer":"Every member of the target population has an equal chance of being selected.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because random sampling selects individuals purely by chance so every member of the population has an equal probability of inclusion.","distractor_reasons":{"A":"Incorrect because restricting to existing customers creates bias and is not random across the population.","B":"Incorrect because selecting by specific characteristics in set proportions defines quota sampling.","C":"Option C is correct because random sampling selects individuals purely by chance so every member of the population has an equal probability of inclusion.","D":"Incorrect because self-selected social media volunteers do not form a random sample."}}},{"id":"P1_U3_MCQ_673","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_673","question":"What is meant by 'quota sampling'?","options":{"A":"Selecting every tenth name from an alphabetical telephone directory.","B":"Surveying every single person living within a country.","C":"Choosing respondents completely by luck using a computer generator.","D":"Selecting respondents based on specific characteristics such as age or gender in set proportions."},"correctOption":"D","correctAnswer":"Selecting respondents based on specific characteristics such as age or gender in set proportions.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because quota sampling divides the population into specific groups (e.g. age or gender) and requires researchers to interview a fixed number from each group.","distractor_reasons":{"A":"Incorrect because picking every nth name is systematic/random sampling.","B":"Incorrect because surveying everyone is a census, not sampling.","C":"Incorrect because pure chance selection defines random sampling.","D":"Option D is correct because quota sampling divides the population into specific groups (e.g. age or gender) and requires researchers to interview a fixed number from each group."}}},{"id":"P1_U3_MCQ_674","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_674","question":"Which factor is most likely to reduce the accuracy of primary market research data?","options":{"A":"Combining primary survey findings with up-to-date secondary statistics.","B":"Testing the questionnaire on a small pilot group before the main survey.","C":"Using clear, neutral wording that avoids leading respondents.","D":"Using a sample size that is too small or unrepresentative of the target market."},"correctOption":"D","correctAnswer":"Using a sample size that is too small or unrepresentative of the target market.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because if a sample is too small or does not reflect the target market's characteristics, the findings will be biased and unreliable.","distractor_reasons":{"A":"Incorrect because cross-checking primary and secondary data improves reliability.","B":"Incorrect because pilot testing improves accuracy by identifying confusing questions early.","C":"Incorrect because neutral wording prevents bias and increases accuracy.","D":"Option D is correct because if a sample is too small or does not reflect the target market's characteristics, the findings will be biased and unreliable."}}},{"id":"P1_U3_MCQ_675","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_675","question":"Which factor most strongly affects the accuracy of secondary market research data?","options":{"A":"The physical weather conditions on the day a manager reads the report.","B":"How recently the data was published and the reliability of its original source.","C":"Whether the business uses flow production or batch production.","D":"The number of subordinates reporting to the Operations Manager."},"correctOption":"B","correctAnswer":"How recently the data was published and the reliability of its original source.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because outdated statistics or biased original publishers can make secondary data inaccurate for current business decisions.","distractor_reasons":{"A":"Incorrect because reading conditions do not change the accuracy of published data.","B":"Option B is correct because outdated statistics or biased original publishers can make secondary data inaccurate for current business decisions.","C":"Incorrect because production methods do not determine the accuracy of external research sources.","D":"Incorrect because span of control is an organisational structure concept unrelated to research accuracy."}}},{"id":"P1_U3_MCQ_676","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_676","question":"What is meant by 'brand image'?","options":{"A":"The legal patent protecting an invention from being copied.","B":"The total cost of manufacturing one unit of a product.","C":"The unique identity and perception of a product that distinguishes it from competitors.","D":"The physical warehouse where finished goods are stored before delivery."},"correctOption":"C","correctAnswer":"The unique identity and perception of a product that distinguishes it from competitors.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because brand image is the distinct identity, name, and reputation that sets a product apart from rivals in consumers' minds.","distractor_reasons":{"A":"Incorrect because legal protection of inventions is a patent, not brand image.","B":"Incorrect because cost per unit is average production cost.","C":"Option C is correct because brand image is the distinct identity, name, and reputation that sets a product apart from rivals in consumers' minds.","D":"Incorrect because storage facilities relate to inventory and distribution."}}},{"id":"P1_U3_MCQ_677","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_677","question":"Why is building a strong brand image important for a business?","options":{"A":"It eliminates all variable costs of raw materials.","B":"It removes the need to comply with consumer safety laws.","C":"It guarantees that a product will never enter the decline stage.","D":"It enables higher prices to be charged and encourages customer loyalty."},"correctOption":"D","correctAnswer":"It enables higher prices to be charged and encourages customer loyalty.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because consumers trust strong brands, allowing the business to charge premium prices, increase added value, and retain loyal buyers.","distractor_reasons":{"A":"Incorrect because raw material costs still vary with output.","B":"Incorrect because all businesses must meet safety standards regardless of brand strength.","C":"Incorrect because even strong brands can decline if not updated over time.","D":"Option D is correct because consumers trust strong brands, allowing the business to charge premium prices, increase added value, and retain loyal buyers."}}},{"id":"P1_U3_MCQ_678","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_678","question":"What is meant by 'brand loyalty'?","options":{"A":"When suppliers offer bulk-buying discounts to large manufacturers.","B":"When employees refuse to leave a company for higher-paying jobs.","C":"When consumers repeatedly purchase the same brand rather than switching to rivals.","D":"When a wholesaler agrees to stock only one category of goods."},"correctOption":"C","correctAnswer":"When consumers repeatedly purchase the same brand rather than switching to rivals.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because brand loyalty occurs when satisfied customers consistently buy the same brand again and again.","distractor_reasons":{"A":"Incorrect because bulk discounts are purchasing economies of scale.","B":"Incorrect because employee retention relates to HRM motivation, not brand loyalty.","C":"Option C is correct because brand loyalty occurs when satisfied customers consistently buy the same brand again and again.","D":"Incorrect because wholesaler stocking relates to distribution channels."}}},{"id":"P1_U3_MCQ_679","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_679","question":"Which of the following is a key role of packaging in the marketing mix?","options":{"A":"Increasing the weight of the product to raise transport expenses.","B":"Protecting the product, displaying required information, and reinforcing brand image.","C":"Replacing the need for any advertising or sales promotion.","D":"Ensuring the product is sold solely through online websites."},"correctOption":"B","correctAnswer":"Protecting the product, displaying required information, and reinforcing brand image.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because packaging physically protects goods during transport/storage, carries legal/usage labels, and attracts buyers through visual branding.","distractor_reasons":{"A":"Incorrect because businesses design packaging to minimise unnecessary weight and transport costs.","B":"Option B is correct because packaging physically protects goods during transport/storage, carries legal/usage labels, and attracts buyers through visual branding.","C":"Incorrect because packaging supports promotion rather than replacing advertising altogether.","D":"Incorrect because attractive packaging is especially vital on physical retail shelves as well as online."}}},{"id":"P1_U3_MCQ_680","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_680","question":"What is an advantage to a business of developing new products?","options":{"A":"It requires zero spending on research and development.","B":"It guarantees immediate high profits from the very first day of launch.","C":"It diversifies the product range, spreads risk, and can create a Unique Selling Point.","D":"It eliminates the need to train production workers."},"correctOption":"C","correctAnswer":"It diversifies the product range, spreads risk, and can create a Unique Selling Point.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because new products expand a firm's portfolio, reduce reliance on older products, and offer unique features that attract buyers.","distractor_reasons":{"A":"Incorrect because developing new products usually involves substantial research and development costs.","B":"Incorrect because new products often make losses during the introduction stage due to high launch costs.","C":"Option C is correct because new products expand a firm's portfolio, reduce reliance on older products, and offer unique features that attract buyers.","D":"Incorrect because new products frequently require employee training on new production processes."}}},{"id":"P1_U3_MCQ_681","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_681","question":"What is a major risk or disadvantage of developing new products?","options":{"A":"It prevents the business from entering new international markets.","B":"It reduces the business's brand image among existing customers.","C":"It makes existing machinery run faster than its maximum capacity.","D":"High research and development costs may not be recovered if sales are low."},"correctOption":"D","correctAnswer":"High research and development costs may not be recovered if sales are low.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because developing and testing new products is expensive, and if consumer demand is weak, the business suffers a financial loss.","distractor_reasons":{"A":"Incorrect because new products often help businesses enter new markets.","B":"Incorrect because successful innovation typically strengthens brand image.","C":"Incorrect because product development does not alter machine speed limits.","D":"Option D is correct because developing and testing new products is expensive, and if consumer demand is weak, the business suffers a financial loss."}}},{"id":"P1_U3_MCQ_682","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_682","question":"What does the 'Product Life Cycle' illustrate?","options":{"A":"The sequence of stages in recruiting and selecting a new manager.","B":"The physical journey of raw materials from a mine to a retail shop.","C":"The daily working hours of employees on a flow production line.","D":"The stages a product passes through from introduction to decline in sales over time."},"correctOption":"D","correctAnswer":"The stages a product passes through from introduction to decline in sales over time.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because the Product Life Cycle tracks how a product's sales evolve through introduction, growth, maturity, and decline.","distractor_reasons":{"A":"Incorrect because hiring steps represent the recruitment and selection process.","B":"Incorrect because moving goods from raw material to retailer describes economic sectors and channels of distribution.","C":"Incorrect because employee hours relate to employment contracts and shift patterns.","D":"Option D is correct because the Product Life Cycle tracks how a product's sales evolve through introduction, growth, maturity, and decline."}}},{"id":"P1_U3_MCQ_683","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_683","question":"Which set of characteristics best describes the 'introduction' stage of the Product Life Cycle?","options":{"A":"Peak sales volume, intense competition, and falling promotional spending.","B":"Slow sales growth, high promotional costs, and negative cash flow or losses.","C":"Rapidly falling sales as consumers switch to newer substitute products.","D":"Maximum economies of scale and lowest possible unit production costs."},"correctOption":"B","correctAnswer":"Slow sales growth, high promotional costs, and negative cash flow or losses.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because during introduction, consumer awareness is low so sales grow slowly while high launch advertising and development costs cause losses.","distractor_reasons":{"A":"Incorrect because peak sales and intense competition describe the maturity stage.","B":"Option B is correct because during introduction, consumer awareness is low so sales grow slowly while high launch advertising and development costs cause losses.","C":"Incorrect because rapidly falling sales describe the decline stage.","D":"Incorrect because low output volumes during introduction prevent maximum economies of scale."}}},{"id":"P1_U3_MCQ_684","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_684","question":"What happens during the 'growth' stage of the Product Life Cycle?","options":{"A":"Sales fall sharply and the product is withdrawn from the market.","B":"Sales remain completely flat at zero while prototypes are tested.","C":"Sales rise rapidly, unit costs fall, and the product begins to earn profits.","D":"No competitors ever enter the market because demand is shrinking."},"correctOption":"C","correctAnswer":"Sales rise rapidly, unit costs fall, and the product begins to earn profits.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because as consumers become aware of the product, sales accelerate, economies of scale lower unit costs, and profitability improves.","distractor_reasons":{"A":"Incorrect because falling sales and withdrawal happen in the decline stage.","B":"Incorrect because prototype testing occurs during development before introduction.","C":"Option C is correct because as consumers become aware of the product, sales accelerate, economies of scale lower unit costs, and profitability improves.","D":"Incorrect because rising sales during growth attract new competitors into the market."}}},{"id":"P1_U3_MCQ_685","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_685","question":"Which feature characterizes the 'maturity' stage of the Product Life Cycle?","options":{"A":"The product is brand new and unknown to almost all consumers.","B":"Losses are at their highest because no units have been sold yet.","C":"Production is halted permanently due to obsolete technology.","D":"Sales growth slows and reaches its peak amid intense competition."},"correctOption":"D","correctAnswer":"Sales growth slows and reaches its peak amid intense competition.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because in the maturity stage, most potential buyers have adopted the product, sales level off at their peak, and competition is fierce.","distractor_reasons":{"A":"Incorrect because low awareness defines the introduction stage.","B":"Incorrect because early losses occur in development and introduction, whereas maturity is usually highly profitable.","C":"Incorrect because withdrawal occurs at the end of the decline stage.","D":"Option D is correct because in the maturity stage, most potential buyers have adopted the product, sales level off at their peak, and competition is fierce."}}},{"id":"P1_U3_MCQ_686","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_686","question":"Why do sales fall during the 'decline' stage of the Product Life Cycle?","options":{"A":"Economies of scale reach their highest possible level.","B":"The business has just launched its first informative advertising campaign.","C":"Consumer tastes change or newer, improved products replace the existing one.","D":"Consumer incomes rise rapidly across all segments."},"correctOption":"C","correctAnswer":"Consumer tastes change or newer, improved products replace the existing one.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because products enter decline when shifting fashions or superior technological alternatives make them obsolete.","distractor_reasons":{"A":"Incorrect because falling output in decline raises average fixed costs rather than maximising economies of scale.","B":"Incorrect because initial informative advertising happens in the introduction stage.","C":"Option C is correct because products enter decline when shifting fashions or superior technological alternatives make them obsolete.","D":"Incorrect because rising consumer incomes generally boost demand rather than cause product decline."}}},{"id":"P1_U3_MCQ_687","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_687","question":"Sales of a once-popular instant coffee have stopped growing. The firm adds a new flavour and launches a celebrity campaign to boost sales. What is the firm trying to achieve?","options":{"A":"To withdraw the product from the market at once","B":"To move the product back into the introduction stage","C":"To reduce the price to the lowest possible level","D":"To extend the product's life cycle by stimulating demand"},"correctOption":"D","correctAnswer":"To extend the product's life cycle by stimulating demand","questionType":"MCQ","explanation":{"correct_reason":"Adding a flavour and advertising to revive sales of a mature product is an extension strategy intended to prolong its life cycle.","distractor_reasons":{"B":"A product cannot return to the introduction stage once launched; the campaign is an extension strategy, not a new launch.","C":"Cutting price to the minimum is not what is described, and would not necessarily rebuild brand interest.","D":"Adding a flavour and advertising to revive sales of a mature product is an extension strategy intended to prolong its life cycle.","A":"Withdrawing the product would end sales rather than boost them, which is the opposite of the firm's aim."}}},{"id":"P1_U3_MCQ_688","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_688","question":"Which of the following is an example of an extension strategy involving the product itself?","options":{"A":"Stopping all advertising and closing retail distribution outlets.","B":"Raising the selling price without making any improvements to the item.","C":"Redesigning the packaging or adding new features and flavours to the product.","D":"Reducing the quality of raw materials to cut production expenses."},"correctOption":"C","correctAnswer":"Redesigning the packaging or adding new features and flavours to the product.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because updating packaging or introducing minor product modifications refreshes consumer interest and extends sales.","distractor_reasons":{"A":"Incorrect because cutting promotion and distribution accelerates decline.","B":"Incorrect because raising prices without adding value reduces demand.","C":"Option C is correct because updating packaging or introducing minor product modifications refreshes consumer interest and extends sales.","D":"Incorrect because lowering quality damages brand reputation and speeds up decline."}}},{"id":"P1_U3_MCQ_689","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_689","question":"How can a business use market expansion as an extension strategy for a mature product?","options":{"A":"By limiting sales exclusively to a single local neighbourhood.","B":"By refusing to sell the product through e-commerce platforms.","C":"By reducing the number of retail shops stocking the item.","D":"By entering new overseas markets or promoting new uses for the product."},"correctOption":"D","correctAnswer":"By entering new overseas markets or promoting new uses for the product.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because launching a mature product in new geographic markets or encouraging new ways to use it generates fresh demand.","distractor_reasons":{"A":"Incorrect because restricting sales to one area shrinks demand.","B":"Incorrect because avoiding e-commerce limits access to new buyers.","C":"Incorrect because reducing distribution outlets lowers sales volume.","D":"Option D is correct because launching a mature product in new geographic markets or encouraging new ways to use it generates fresh demand."}}},{"id":"P1_U3_MCQ_690","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_690","question":"What is meant by 'cost-plus pricing'?","options":{"A":"Calculating the unit cost of producing a product and adding a percentage mark-up for profit.","B":"Setting a low initial price to attract customers quickly to a new product.","C":"Changing prices continuously in real time based on online customer demand.","D":"Matching the exact price charged by the largest competitor in the market."},"correctOption":"A","correctAnswer":"Calculating the unit cost of producing a product and adding a percentage mark-up for profit.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cost-plus pricing determines average unit cost and adds a fixed percentage or amount to ensure a profit margin.","distractor_reasons":{"A":"Option A is correct because cost-plus pricing determines average unit cost and adds a fixed percentage or amount to ensure a profit margin.","B":"Incorrect because a low launch price defines penetration pricing.","C":"Incorrect because real-time price adjustments define dynamic pricing.","D":"Incorrect because matching rivals' prices defines competitive pricing."}}},{"id":"P1_U3_MCQ_691","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_691","question":"What is an advantage of using cost-plus pricing?","options":{"A":"It guarantees that the business's price is always lower than every rival's price.","B":"It is simple to calculate and ensures production costs are covered if target sales are achieved.","C":"It automatically maximises sales during off-peak seasons.","D":"It adjusts prices instantly whenever competitor stock runs out."},"correctOption":"B","correctAnswer":"It is simple to calculate and ensures production costs are covered if target sales are achieved.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because cost-plus pricing is straightforward to apply and ensures each unit sold contributes a planned profit margin over cost.","distractor_reasons":{"A":"Incorrect because cost-plus pricing may result in a price higher than competitors' prices.","B":"Option B is correct because cost-plus pricing is straightforward to apply and ensures each unit sold contributes a planned profit margin over cost.","C":"Incorrect because adjusting prices for off-peak demand describes dynamic pricing.","D":"Incorrect because cost-plus pricing does not automatically track competitor inventory."}}},{"id":"P1_U3_MCQ_692","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_692","question":"What is a major disadvantage of cost-plus pricing?","options":{"A":"It fails to include fixed costs when calculating total unit costs.","B":"It is illegal under consumer protection laws in most countries.","C":"It ignores competitors' prices and customer willingness to pay, risking lost sales.","D":"It requires expensive real-time computer algorithms to operate."},"correctOption":"C","correctAnswer":"It ignores competitors' prices and customer willingness to pay, risking lost sales.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because if a business's costs are higher than rivals', adding a standard mark-up can make the price uncompetitive.","distractor_reasons":{"A":"Incorrect because average unit cost includes both fixed and variable costs.","B":"Incorrect because cost-plus pricing is a completely legal pricing method.","C":"Option C is correct because if a business's costs are higher than rivals', adding a standard mark-up can make the price uncompetitive.","D":"Incorrect because algorithms are associated with dynamic pricing, whereas cost-plus is simple arithmetic."}}},{"id":"P1_U3_MCQ_693","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_693","question":"A petrol station sets its price per litre just below the price charged by the other three stations in the same town. Which pricing method is this?","options":{"A":"Competitive pricing","B":"Cost-plus pricing","C":"Penetration pricing","D":"Price skimming"},"correctOption":"A","correctAnswer":"Competitive pricing","questionType":"MCQ","explanation":{"correct_reason":"Setting a price by reference to what rivals charge, here slightly undercutting them, is competitive pricing.","distractor_reasons":{"B":"Cost-plus pricing adds a markup to the cost of supply, which is not how this station chose its price.","C":"Penetration pricing sets a low price to gain share at launch, not simply to match nearby rivals.","D":"Price skimming charges a high initial price, the reverse of undercutting competitors.","A":"Setting a price by reference to what rivals charge, here slightly undercutting them, is competitive pricing."}}},{"id":"P1_U3_MCQ_694","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_694","question":"Why might a business choose to use competitive pricing?","options":{"A":"To avoid destructive price wars while keeping sales steady in a crowded market.","B":"To recover high research and development costs immediately at launch.","C":"To ensure prices change every minute according to website traffic.","D":"To create an ultra-exclusive luxury image above all rival brands."},"correctOption":"A","correctAnswer":"To avoid destructive price wars while keeping sales steady in a crowded market.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because pricing close to competitors prevents aggressive price-cutting wars and keeps the product attractive when goods are similar.","distractor_reasons":{"A":"Option A is correct because pricing close to competitors prevents aggressive price-cutting wars and keeps the product attractive when goods are similar.","B":"Incorrect because recovering high R&D costs quickly is the goal of price skimming.","C":"Incorrect because minute-by-minute price changes describe dynamic pricing.","D":"Incorrect because an exclusive luxury image usually requires premium or skimming prices above rivals."}}},{"id":"P1_U3_MCQ_695","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_695","question":"What is meant by 'penetration pricing'?","options":{"A":"Charging the highest price wealthy buyers will pay when a product is first launched.","B":"Setting a low initial price when launching a new product to gain market share quickly.","C":"Raising prices sharply during peak holiday travel periods.","D":"Selling products below cost permanently to force rivals out of business."},"correctOption":"B","correctAnswer":"Setting a low initial price when launching a new product to gain market share quickly.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because penetration pricing uses an introductory low price to encourage consumers to try a new product and rapidly build sales volume.","distractor_reasons":{"A":"Incorrect because charging a high initial price defines price skimming.","B":"Option B is correct because penetration pricing uses an introductory low price to encourage consumers to try a new product and rapidly build sales volume.","C":"Incorrect because peak-period price increases describe dynamic pricing.","D":"Incorrect because penetration pricing is a temporary launch strategy, after which prices are usually raised."}}},{"id":"P1_U3_MCQ_696","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_696","question":"What is a disadvantage of using penetration pricing?","options":{"A":"It prevents consumers from noticing the new product at launch.","B":"It creates an overly expensive image that deters budget shoppers.","C":"Initial profit margins are low and customers may resist when prices are later raised.","D":"It can only be used for luxury goods with zero competitors."},"correctOption":"C","correctAnswer":"Initial profit margins are low and customers may resist when prices are later raised.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because low launch prices yield small profits per unit, and buyers attracted by cheap prices may switch away once the price increases.","distractor_reasons":{"A":"Incorrect because low prices attract high initial attention and trial.","B":"Incorrect because penetration pricing sets a low, affordable price rather than an expensive one.","C":"Option C is correct because low launch prices yield small profits per unit, and buyers attracted by cheap prices may switch away once the price increases.","D":"Incorrect because penetration pricing is typically used in competitive mass markets, not luxury niches."}}},{"id":"P1_U3_MCQ_697","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_697","question":"What is meant by 'price skimming'?","options":{"A":"Setting a low launch price to enter a highly competitive mass market.","B":"Reducing prices every week until all unsold inventory is cleared.","C":"Charging identical prices to every competitor in a local town.","D":"Setting a high initial price for a new, unique, or innovative product."},"correctOption":"D","correctAnswer":"Setting a high initial price for a new, unique, or innovative product.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because price skimming sets a high price at launch for an innovative product with little competition before lowering it later.","distractor_reasons":{"A":"Incorrect because a low launch price defines penetration pricing.","B":"Incorrect because weekly clearance discounts are promotional markdowns, not skimming.","C":"Incorrect because matching rivals' prices defines competitive pricing.","D":"Option D is correct because price skimming sets a high price at launch for an innovative product with little competition before lowering it later."}}},{"id":"P1_U3_MCQ_698","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_698","question":"What is a major advantage of price skimming for a business launching an innovative product?","options":{"A":"It helps recover high research and development costs quickly and creates a quality image.","B":"It guarantees that low-income consumers can afford the product immediately.","C":"It discourages any competitors from ever developing similar technology.","D":"It eliminates the need to advertise the product's new features."},"correctOption":"A","correctAnswer":"It helps recover high research and development costs quickly and creates a quality image.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because high profit margins from early adopters allow the business to recoup R&D expenses rapidly and establish prestige.","distractor_reasons":{"A":"Option A is correct because high profit margins from early adopters allow the business to recoup R&D expenses rapidly and establish prestige.","B":"Incorrect because high initial prices exclude low-income buyers until prices are lowered later.","C":"Incorrect because high profits from skimming often attract competitors to develop rival versions.","D":"Incorrect because promotion is still required to justify the high price and explain innovations."}}},{"id":"P1_U3_MCQ_699","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_699","question":"An airline changes seat prices continuously, raising them as departure approaches and lowering them when bookings are slow. Which pricing approach does this illustrate?","options":{"A":"Promotional pricing","B":"Cost-plus pricing","C":"Penetration pricing","D":"Dynamic pricing"},"correctOption":"D","correctAnswer":"Dynamic pricing","questionType":"MCQ","explanation":{"correct_reason":"Changing prices in real time according to demand and timing is dynamic pricing.","distractor_reasons":{"B":"Cost-plus pricing sets a markup on costs and would not vary continuously with booking conditions.","C":"Penetration pricing is a low launch price to win customers, not ongoing adjustments as a departure nears.","D":"Changing prices in real time according to demand and timing is dynamic pricing.","A":"Promotional pricing is a temporary discount campaign, not a policy of frequent price changes."}}},{"id":"P1_U3_MCQ_700","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_700","question":"How does dynamic pricing benefit businesses such as airlines and hotels?","options":{"A":"It ensures every customer pays the exact same fare regardless of booking date.","B":"It eliminates the need to use computers or online booking systems.","C":"It maximises revenue during peak demand and fills spare capacity during quiet periods.","D":"It guarantees that competitors cannot lower their ticket prices."},"correctOption":"C","correctAnswer":"It maximises revenue during peak demand and fills spare capacity during quiet periods.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because raising prices when seats or rooms are scarce boosts profit margins, while lowering prices in off-peak times attracts extra bookings.","distractor_reasons":{"A":"Incorrect because dynamic pricing results in different customers paying different prices depending on timing and demand.","B":"Incorrect because dynamic pricing relies heavily on IT and online booking platforms.","C":"Option C is correct because raising prices when seats or rooms are scarce boosts profit margins, while lowering prices in off-peak times attracts extra bookings.","D":"Incorrect because competitors also use dynamic pricing to adjust their own fares."}}},{"id":"P1_U3_MCQ_701","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_701","question":"What is meant by a 'channel of distribution'?","options":{"A":"The television station chosen to broadcast a commercial.","B":"The sequence of stages used to manufacture a product on a factory line.","C":"The internal chain of command between senior directors and factory workers.","D":"The means by which a product is passed from the place of production to the customer."},"correctOption":"D","correctAnswer":"The means by which a product is passed from the place of production to the customer.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a channel of distribution describes the route and intermediaries (such as wholesalers and retailers) used to get goods from producer to consumer.","distractor_reasons":{"A":"Incorrect because selecting media stations relates to Promotion, not Place.","B":"Incorrect because factory stages relate to operations management.","C":"Incorrect because authority levels in a business refer to organisational hierarchy.","D":"Option D is correct because a channel of distribution describes the route and intermediaries (such as wholesalers and retailers) used to get goods from producer to consumer."}}},{"id":"P1_U3_MCQ_702","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_702","question":"Which distribution channel involves a producer selling straight to the final buyer without using any intermediaries?","options":{"A":"Direct to customers.","B":"Producer to wholesaler to retailer to consumer.","C":"Producer to agent to wholesaler to consumer.","D":"Producer to retailer to consumer."},"correctOption":"A","correctAnswer":"Direct to customers.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a direct channel connects the manufacturer directly with the end consumer (e.g. via factory outlets or the producer's own website).","distractor_reasons":{"A":"Option A is correct because a direct channel connects the manufacturer directly with the end consumer (e.g. via factory outlets or the producer's own website).","B":"Incorrect because this traditional channel uses two intermediaries (wholesaler and retailer).","C":"Incorrect because this channel uses both an agent and a wholesaler.","D":"Incorrect because this channel uses retailers as intermediaries."}}},{"id":"P1_U3_MCQ_703","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_703","question":"What is a major advantage to a producer of selling directly to consumers?","options":{"A":"Wholesalers handle all storage and delivery costs free of charge.","B":"The producer keeps the full profit margin and controls how the product is marketed.","C":"Retailers take full responsibility for resolving all customer complaints.","D":"The producer never needs to advertise or promote its brand."},"correctOption":"B","correctAnswer":"The producer keeps the full profit margin and controls how the product is marketed.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because avoiding intermediaries means no profit margin is shared with retailers or wholesalers, and the producer controls pricing and presentation.","distractor_reasons":{"A":"Incorrect because wholesalers are not used in a direct channel.","B":"Option B is correct because avoiding intermediaries means no profit margin is shared with retailers or wholesalers, and the producer controls pricing and presentation.","C":"Incorrect because retailers are bypassed in direct selling, so the producer handles customers directly.","D":"Incorrect because direct sellers must promote their products so consumers know where to buy."}}},{"id":"P1_U3_MCQ_704","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_704","question":"What is a disadvantage of direct distribution for a manufacturer of everyday consumer goods?","options":{"A":"The producer loses all contact with final customers.","B":"Intermediaries charge high retail mark-ups that double the selling price.","C":"High storage, administration, and delivery costs of dispatching many small orders.","D":"It is illegal to sell manufactured goods directly to the public."},"correctOption":"C","correctAnswer":"High storage, administration, and delivery costs of dispatching many small orders.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because storing finished inventory and shipping thousands of small individual parcels directly to households is costly and time-consuming.","distractor_reasons":{"A":"Incorrect because direct distribution increases, rather than reduces, direct contact with customers.","B":"Incorrect because there are no intermediaries taking mark-ups in a direct channel.","C":"Option C is correct because storing finished inventory and shipping thousands of small individual parcels directly to households is costly and time-consuming.","D":"Incorrect because direct-to-consumer selling is completely legal."}}},{"id":"P1_U3_MCQ_705","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_705","question":"What is the primary role of a 'retailer' in a channel of distribution?","options":{"A":"Manufacturing raw materials into finished consumer goods.","B":"Acting solely as an overseas legal adviser for exporting firms.","C":"Buying in bulk from factories and selling exclusively to other factories.","D":"Buying goods from producers or wholesalers and selling them in small quantities to consumers."},"correctOption":"D","correctAnswer":"Buying goods from producers or wholesalers and selling them in small quantities to consumers.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because retailers (such as supermarkets and high-street shops) buy stock in larger quantities and sell single items conveniently to final consumers.","distractor_reasons":{"A":"Incorrect because manufacturing goods is the role of secondary-sector producers.","B":"Incorrect because overseas sales representatives are agents, not retailers.","C":"Incorrect because retailers sell to final consumers rather than manufacturing factories.","D":"Option D is correct because retailers (such as supermarkets and high-street shops) buy stock in larger quantities and sell single items conveniently to final consumers."}}},{"id":"P1_U3_MCQ_706","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_706","question":"What is an advantage to a manufacturer of distributing products through retailers?","options":{"A":"The manufacturer avoids paying any retailer profit margin.","B":"Retailers provide wide geographic coverage and convenient access for shoppers.","C":"Retailers never stock competing brands alongside the manufacturer's product.","D":"The manufacturer keeps total control over the final price charged in every shop."},"correctOption":"B","correctAnswer":"Retailers provide wide geographic coverage and convenient access for shoppers.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because established retail chains place products in numerous towns and cities where consumers regularly shop.","distractor_reasons":{"A":"Incorrect because retailers add a profit mark-up when selling to consumers.","B":"Option B is correct because established retail chains place products in numerous towns and cities where consumers regularly shop.","C":"Incorrect because most retailers stock multiple competing brands side by side.","D":"Incorrect because retailers normally set their own final retail selling prices."}}},{"id":"P1_U3_MCQ_707","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_707","question":"What is the primary function of a 'wholesaler' in a distribution channel?","options":{"A":"Designing television advertisements for global brands.","B":"Buying in bulk from producers, storing inventory, and selling smaller batches to retailers.","C":"Selling individual items directly to household consumers through high-street shops.","D":"Inspecting factory machinery to ensure compliance with health and safety laws."},"correctOption":"B","correctAnswer":"Buying in bulk from producers, storing inventory, and selling smaller batches to retailers.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because wholesalers act as middlemen who 'break bulk'—buying huge quantities from manufacturers and reselling smaller cases to independent retailers.","distractor_reasons":{"A":"Incorrect because designing adverts is the role of advertising agencies or marketing departments.","B":"Option B is correct because wholesalers act as middlemen who 'break bulk'—buying huge quantities from manufacturers and reselling smaller cases to independent retailers.","C":"Incorrect because selling individual items to consumers is the role of retailers.","D":"Incorrect because safety inspections are carried out by operations staff or government inspectors."}}},{"id":"P1_U3_MCQ_708","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_708","question":"How does selling through a wholesaler benefit a manufacturer?","options":{"A":"It guarantees that the manufacturer receives the full retail price for every unit.","B":"It gives the manufacturer direct face-to-face contact with every individual shopper.","C":"It reduces the manufacturer's storage and transport costs through large bulk orders.","D":"It eliminates the need to maintain product quality standards."},"correctOption":"C","correctAnswer":"It reduces the manufacturer's storage and transport costs through large bulk orders.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because wholesalers buy in large bulk quantities and store the goods themselves, saving the producer warehousing and small-delivery expenses.","distractor_reasons":{"A":"Incorrect because both the wholesaler and retailer add profit margins.","B":"Incorrect because adding a wholesaler places two intermediaries between the producer and consumer.","C":"Option C is correct because wholesalers buy in large bulk quantities and store the goods themselves, saving the producer warehousing and small-delivery expenses.","D":"Incorrect because manufacturers must still maintain quality to keep wholesalers and consumers buying."}}},{"id":"P1_U3_MCQ_709","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_709","question":"What is a disadvantage to a producer of using a wholesaler in its distribution channel?","options":{"A":"The producer must build large warehouses to store stock for small shops.","B":"Small independent retailers are unable to buy stock in affordable quantities.","C":"The producer has to deliver single items directly to thousands of households.","D":"The wholesaler takes a profit margin, reducing the producer's share or raising final prices."},"correctOption":"D","correctAnswer":"The wholesaler takes a profit margin, reducing the producer's share or raising final prices.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because adding a wholesaler creates an extra intermediary who takes a cut of the profit, either lowering producer revenue or making the retail price less competitive.","distractor_reasons":{"A":"Incorrect because wholesalers take over the storage function from the producer.","B":"Incorrect because enabling small shops to buy small quantities is an advantage of wholesalers.","C":"Incorrect because wholesalers handle distribution to retailers rather than the producer shipping to households.","D":"Option D is correct because adding a wholesaler creates an extra intermediary who takes a cut of the profit, either lowering producer revenue or making the retail price less competitive."}}},{"id":"P1_U3_MCQ_710","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_710","question":"What is the role of an 'agent' in a channel of distribution?","options":{"A":"An independent specialist hired to find buyers and arrange sales in a foreign market.","B":"A factory employee responsible for operating automated welding robots.","C":"A supermarket checkout operator scanning customer barcodes.","D":"A government official who collects import tariffs at national borders."},"correctOption":"A","correctAnswer":"An independent specialist hired to find buyers and arrange sales in a foreign market.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because agents are appointed to represent a business in overseas markets, using local contacts and knowledge to secure sales for a commission.","distractor_reasons":{"A":"Option A is correct because agents are appointed to represent a business in overseas markets, using local contacts and knowledge to secure sales for a commission.","B":"Incorrect because operating factory machines is a production role.","C":"Incorrect because checkout staff work for retailers.","D":"Incorrect because customs officers work for the government, not as distribution agents."}}},{"id":"P1_U3_MCQ_711","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_711","question":"What is a disadvantage of using an agent to sell products in another country?","options":{"A":"The agent has no knowledge of local language or customs.","B":"The business has less control over how the product is marketed and must pay commission.","C":"The business must build its own expensive retail stores in the foreign country.","D":"Agents are legally prohibited from selling to foreign wholesalers."},"correctOption":"B","correctAnswer":"The business has less control over how the product is marketed and must pay commission.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because agents act independently on commission, meaning the producer sacrifices direct control over day-to-day selling and promotion.","distractor_reasons":{"A":"Incorrect because local market knowledge is the main advantage of hiring an agent.","B":"Option B is correct because agents act independently on commission, meaning the producer sacrifices direct control over day-to-day selling and promotion.","C":"Incorrect because using an agent avoids the capital cost of opening overseas branches.","D":"Incorrect because agents regularly arrange deals with overseas wholesalers and retailers."}}},{"id":"P1_U3_MCQ_712","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_712","question":"What is meant by 'e-commerce' (electronic commerce)?","options":{"A":"Advertising products solely through printed posters and street leaflets.","B":"Manufacturing electronic components on an automated assembly line.","C":"The online buying and selling of goods and services using internet-linked devices.","D":"Using internal email to send shift schedules to factory employees."},"correctOption":"C","correctAnswer":"The online buying and selling of goods and services using internet-linked devices.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because e-commerce refers to conducting commercial transactions—buying and selling goods or services—over the internet.","distractor_reasons":{"A":"Incorrect because posters and leaflets are traditional offline advertising methods.","B":"Incorrect because manufacturing electronics is secondary-sector production, not e-commerce.","C":"Option C is correct because e-commerce refers to conducting commercial transactions—buying and selling goods or services—over the internet.","D":"Incorrect because emailing staff schedules is internal workplace communication."}}},{"id":"P1_U3_MCQ_713","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_713","question":"Which of the following is a major advantage of e-commerce to a business?","options":{"A":"It guarantees zero competition from overseas producers.","B":"It eliminates all costs of shipping and delivering physical parcels.","C":"It increases face-to-face personal interaction with every shopper.","D":"It allows the business to reach global customers 24/7 without physical shop rents."},"correctOption":"D","correctAnswer":"It allows the business to reach global customers 24/7 without physical shop rents.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because an e-commerce website operates continuously worldwide, expanding potential sales while reducing high-street retail overhead costs.","distractor_reasons":{"A":"Incorrect because e-commerce increases global competition rather than removing it.","B":"Incorrect because delivering individual online orders often increases transport costs.","C":"Incorrect because e-commerce lacks direct face-to-face personal contact.","D":"Option D is correct because an e-commerce website operates continuously worldwide, expanding potential sales while reducing high-street retail overhead costs."}}},{"id":"P1_U3_MCQ_714","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_714","question":"Which of the following is a disadvantage of e-commerce for a retail business?","options":{"A":"High costs of processing returned goods because customers cannot try items before buying.","B":"Customers can only place orders during standard daytime shop opening hours.","C":"It is impossible to display photographs or product descriptions on a website.","D":"Banks refuse to process debit or credit card payments made online."},"correctOption":"A","correctAnswer":"High costs of processing returned goods because customers cannot try items before buying.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because online shoppers cannot touch or try on products beforehand, leading to higher return rates and added administration/logistics expenses.","distractor_reasons":{"A":"Option A is correct because online shoppers cannot touch or try on products beforehand, leading to higher return rates and added administration/logistics expenses.","B":"Incorrect because e-commerce allows customers to order 24 hours a day, 7 days a week.","C":"Incorrect because websites routinely display rich images, videos, and detailed descriptions.","D":"Incorrect because electronic card payments are a standard feature of e-commerce."}}},{"id":"P1_U3_MCQ_715","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_715","question":"What is a key advantage of e-commerce to customers?","options":{"A":"Products can always be touched, worn, and tested physically before paying.","B":"It is convenient to shop 24/7 from home and easily compare prices across websites.","C":"Delivery of physical goods is always instantaneous with zero waiting time.","D":"There is zero risk of online fraud or fake websites."},"correctOption":"B","correctAnswer":"It is convenient to shop 24/7 from home and easily compare prices across websites.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because online shopping saves travel time, operates around the clock, and lets buyers compare prices and choices quickly.","distractor_reasons":{"A":"Incorrect because inability to inspect physical items before purchase is a disadvantage of e-commerce.","B":"Option B is correct because online shopping saves travel time, operates around the clock, and lets buyers compare prices and choices quickly.","C":"Incorrect because physical goods take time to be delivered after ordering.","D":"Incorrect because security concerns, hacking, and bogus websites remain risks for online shoppers."}}},{"id":"P1_U3_MCQ_716","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_716","question":"Which of the following is a disadvantage of online shopping for customers?","options":{"A":"Limited choice compared to a small local corner shop.","B":"Inability to pay using debit or credit cards.","C":"Inability to see, touch, or try on products before purchase, plus potential delivery fees.","D":"Websites close every evening and on weekends."},"correctOption":"C","correctAnswer":"Inability to see, touch, or try on products before purchase, plus potential delivery fees.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because online buyers cannot physically inspect goods beforehand, often pay extra shipping charges, and face inconvenience when returning unsuitable items.","distractor_reasons":{"A":"Incorrect because online shopping offers far wider choice than physical stores.","B":"Incorrect because card payments are quick and standard online.","C":"Option C is correct because online buyers cannot physically inspect goods beforehand, often pay extra shipping charges, and face inconvenience when returning unsuitable items.","D":"Incorrect because online stores remain open 24/7."}}},{"id":"P1_U3_MCQ_717","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_717","question":"What is the primary purpose of 'promotion' in the marketing mix?","options":{"A":"To calculate the break-even level of output for a factory.","B":"To transport raw materials from suppliers to manufacturing plants.","C":"To recruit and train new managers for the Human Resources department.","D":"To inform consumers about products, persuade them to buy, and build brand image."},"correctOption":"D","correctAnswer":"To inform consumers about products, persuade them to buy, and build brand image.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because promotion communicates with target customers to raise awareness, encourage purchases, and strengthen brand identity.","distractor_reasons":{"A":"Incorrect because break-even calculation is a financial/operations management tool.","B":"Incorrect because transporting materials is part of operations and logistics.","C":"Incorrect because staff recruitment is an HRM function.","D":"Option D is correct because promotion communicates with target customers to raise awareness, encourage purchases, and strengthen brand identity."}}},{"id":"P1_U3_MCQ_718","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_718","question":"How does 'sales promotion' differ from 'advertising'?","options":{"A":"Sales promotion offers short-term incentives to boost immediate sales, whereas advertising communicates through paid media.","B":"Sales promotion is only used by public sector charities, whereas advertising is for profit-making firms.","C":"Sales promotion is legally banned in retail stores, whereas advertising is unrestricted.","D":"Sales promotion never costs the business any money, whereas advertising is always expensive."},"correctOption":"A","correctAnswer":"Sales promotion offers short-term incentives to boost immediate sales, whereas advertising communicates through paid media.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because sales promotion uses short-term deals (like vouchers, discounts, and competitions) to trigger immediate buying, while advertising uses media (like TV, social media, and billboards) to inform and persuade.","distractor_reasons":{"A":"Option A is correct because sales promotion uses short-term deals (like vouchers, discounts, and competitions) to trigger immediate buying, while advertising uses media (like TV, social media, and billboards) to inform and persuade.","B":"Incorrect because private-sector businesses widely use both advertising and sales promotion.","C":"Incorrect because sales promotions are legal provided they are not misleading.","D":"Incorrect because sales promotions (such as price discounts, free gifts, and loyalty points) also incur costs."}}},{"id":"P1_U3_MCQ_719","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_719","question":"Why do businesses use money-off vouchers as a method of sales promotion?","options":{"A":"To permanently increase the standard retail price of the product.","B":"To encourage consumers to try a new product or make a repeat purchase.","C":"To replace the need for product packaging.","D":"To prevent wholesalers from stocking competing brands."},"correctOption":"B","correctAnswer":"To encourage consumers to try a new product or make a repeat purchase.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because money-off coupons reduce the purchase price temporarily, motivating hesitant buyers to trial a new item or buy again.","distractor_reasons":{"A":"Incorrect because vouchers offer a temporary price reduction rather than a permanent price increase.","B":"Option B is correct because money-off coupons reduce the purchase price temporarily, motivating hesitant buyers to trial a new item or buy again.","C":"Incorrect because vouchers are often printed on or inside packaging rather than replacing it.","D":"Incorrect because vouchers target final consumers, not wholesaler stocking decisions."}}},{"id":"P1_U3_MCQ_720","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_720","question":"How do customer reward schemes (loyalty cards) help a business achieve its marketing aims?","options":{"A":"They eliminate the need to maintain satisfactory product quality.","B":"They ensure the business never has to pay for advertising.","C":"They encourage repeat purchases by awarding points or discounts to regular shoppers.","D":"They prevent customers from ever visiting rival stores by law."},"correctOption":"C","correctAnswer":"They encourage repeat purchases by awarding points or discounts to regular shoppers.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because reward schemes give customers financial incentives to keep returning to the same business, strengthening customer loyalty.","distractor_reasons":{"A":"Incorrect because customers will stop returning if product quality is poor.","B":"Incorrect because businesses still advertise alongside running loyalty programmes.","C":"Option C is correct because reward schemes give customers financial incentives to keep returning to the same business, strengthening customer loyalty.","D":"Incorrect because loyalty cards encourage repeat visits through rewards, not legal bans."}}},{"id":"P1_U3_MCQ_721","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_721","question":"What is an advantage of using competitions or special offers as a sales promotion method?","options":{"A":"They guarantee zero production costs for the promoted item.","B":"They permanently establish a luxury price image for budget goods.","C":"They eliminate all shipping expenses for e-commerce orders.","D":"They attract consumer attention and boost short-term sales volume."},"correctOption":"D","correctAnswer":"They attract consumer attention and boost short-term sales volume.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because competitions and special offers create excitement and urgency, stimulating immediate customer purchases.","distractor_reasons":{"A":"Incorrect because production costs are unaffected by sales promotions.","B":"Incorrect because frequent discounts can actually cheapen a brand's luxury image.","C":"Incorrect because shipping costs still apply unless absorbed by the seller.","D":"Option D is correct because competitions and special offers create excitement and urgency, stimulating immediate customer purchases."}}},{"id":"P1_U3_MCQ_722","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_722","question":"What is a key advantage of advertising on social media platforms?","options":{"A":"It is relatively low cost and allows precise targeting of specific consumer groups.","B":"Consumers never ignore online adverts or scroll past sponsored posts.","C":"It guarantees that older consumers without internet access will see the advert.","D":"It requires no creative design or ongoing content updates."},"correctOption":"A","correctAnswer":"It is relatively low cost and allows precise targeting of specific consumer groups.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because social media advertising reaches large audiences affordably and uses user data to target specific ages, locations, and interests.","distractor_reasons":{"A":"Option A is correct because social media advertising reaches large audiences affordably and uses user data to target specific ages, locations, and interests.","B":"Incorrect because many users ignore or block constant social media advertisements.","C":"Incorrect because people without internet or social media accounts cannot view online ads.","D":"Incorrect because effective social media campaigns require engaging visuals and regular updates."}}},{"id":"P1_U3_MCQ_723","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_723","question":"What is an advantage of using direct or targeted emails as an advertising method?","options":{"A":"Every recipient is legally required to open and read marketing emails.","B":"It is a cheap way to send personalised offers directly to interested or existing customers.","C":"It requires no customer email addresses or database management.","D":"It reaches people who do not own computers or smartphones."},"correctOption":"B","correctAnswer":"It is a cheap way to send personalised offers directly to interested or existing customers.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because targeted emails cost very little to send and can be tailored to customers who have already shown interest in the business.","distractor_reasons":{"A":"Incorrect because many recipients delete promotional emails as spam without reading them.","B":"Option B is correct because targeted emails cost very little to send and can be tailored to customers who have already shown interest in the business.","C":"Incorrect because businesses must collect and maintain a list of valid customer email addresses.","D":"Incorrect because recipients need internet-connected devices to read emails."}}},{"id":"P1_U3_MCQ_724","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_724","question":"What is a major disadvantage of using printed leaflets as an advertising method?","options":{"A":"They are much more expensive to produce than nationwide television commercials.","B":"Consumers cannot keep them for future reference or attach money-off vouchers.","C":"They are often thrown away unread as junk mail and may be seen as wasteful.","D":"They cannot be distributed in a specific local area."},"correctOption":"C","correctAnswer":"They are often thrown away unread as junk mail and may be seen as wasteful.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because many people discard unsolicited leaflets immediately without reading them, and paper waste can harm a firm's environmental image.","distractor_reasons":{"A":"Incorrect because leaflets are one of the cheapest advertising methods compared to TV.","B":"Incorrect because keeping printed leaflets and including vouchers are advantages of leaflets.","C":"Option C is correct because many people discard unsolicited leaflets immediately without reading them, and paper waste can harm a firm's environmental image.","D":"Incorrect because leaflets are easily targeted to specific local neighbourhoods."}}},{"id":"P1_U3_MCQ_725","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_725","question":"What is a key limitation of advertising on roadside billboards?","options":{"A":"They are removed after only five minutes of display.","B":"They cannot display large, colourful images.","C":"They can only be viewed by people who own a smartphone.","D":"Very little detailed product information can be included because passers-by have little time to read."},"correctOption":"D","correctAnswer":"Very little detailed product information can be included because passers-by have little time to read.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because drivers and pedestrians pass billboards quickly, so adverts must rely on short slogans and bold visuals rather than detailed text.","distractor_reasons":{"A":"Incorrect because billboards remain displayed for weeks or months.","B":"Incorrect because large, eye-catching visuals are the main strength of billboards.","C":"Incorrect because billboards are visible to anyone passing by physically.","D":"Option D is correct because drivers and pedestrians pass billboards quickly, so adverts must rely on short slogans and bold visuals rather than detailed text."}}},{"id":"P1_U3_MCQ_726","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_726","question":"A firm decides to focus on young adults, offer a premium product and promote it mainly through social media in order to gain market share. What has the firm developed?","options":{"A":"A cash-flow forecast","B":"A production plan","C":"A marketing strategy","D":"A recruitment policy"},"correctOption":"C","correctAnswer":"A marketing strategy","questionType":"MCQ","explanation":{"correct_reason":"Choosing a target market and decisions about product and promotion to reach a goal is a marketing strategy.","distractor_reasons":{"B":"A production plan concerns how goods will be made and in what quantities, not target customers and promotion.","C":"Choosing a target market and decisions about product and promotion to reach a goal is a marketing strategy.","D":"A recruitment policy covers hiring staff and is unrelated to targeting customers.","A":"A cash-flow forecast predicts money inflows and outflows, which is a financial rather than marketing plan."}}},{"id":"P1_U3_MCQ_727","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_727","question":"Why is it essential for all four elements of the marketing mix to be consistent with one another?","options":{"A":"Because laws require every business to spend equal money on each of the four Ps.","B":"Because a unified marketing mix sends a clear, believable image to the target market.","C":"Because consistency eliminates the need to conduct any market research.","D":"Because consistent products never enter the decline stage of the life cycle."},"correctOption":"B","correctAnswer":"Because a unified marketing mix sends a clear, believable image to the target market.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because if one element contradicts the others (e.g. a luxury product sold in discount stores), consumers become confused and the strategy fails.","distractor_reasons":{"A":"Incorrect because there is no legal rule requiring equal spending across the four Ps.","B":"Option B is correct because if one element contradicts the others (e.g. a luxury product sold in discount stores), consumers become confused and the strategy fails.","C":"Incorrect because market research is still needed to design a suitable marketing mix.","D":"Incorrect because all products eventually face life-cycle changes regardless of mix consistency."}}},{"id":"P1_U3_MCQ_728","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_728","question":"Which of the following illustrates an inconsistent marketing mix?","options":{"A":"Selling an everyday household soap at a competitive price in supermarkets.","B":"Advertising a new youth smartphone app on popular social media platforms.","C":"Promoting an exclusive, high-priced luxury watch using cheap street leaflets.","D":"Using price skimming for a newly invented, high-tech electronic device."},"correctOption":"C","correctAnswer":"Promoting an exclusive, high-priced luxury watch using cheap street leaflets.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because cheap street flyers clash with a high price and luxury brand image, undermining consumer perception of exclusivity.","distractor_reasons":{"A":"Incorrect because competitive pricing and supermarket distribution fit an everyday consumer good.","B":"Incorrect because social media matches a youth-targeted digital app.","C":"Option C is correct because cheap street flyers clash with a high price and luxury brand image, undermining consumer perception of exclusivity.","D":"Incorrect because price skimming is well suited to innovative high-tech products."}}},{"id":"P1_U3_MCQ_729","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_729","question":"Why must a business regularly review and adapt its marketing strategy over time?","options":{"A":"Because consumer tastes, competitor actions, and Product Life Cycle stages constantly evolve.","B":"Because fixed costs never change once a business has been established.","C":"Because consumer protection laws forbid using the same brand name for more than two years.","D":"Because market segmentation only works during the introduction stage."},"correctOption":"A","correctAnswer":"Because consumer tastes, competitor actions, and Product Life Cycle stages constantly evolve.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because dynamic market conditions—such as new competitors, shifting customer preferences, and product maturity—require ongoing updates to the four Ps.","distractor_reasons":{"A":"Option A is correct because dynamic market conditions—such as new competitors, shifting customer preferences, and product maturity—require ongoing updates to the four Ps.","B":"Incorrect because fixed costs can change over time as a business expands or relocates.","C":"Incorrect because businesses can keep brand names permanently.","D":"Incorrect because market segmentation remains useful across all stages of the Product Life Cycle."}}},{"id":"P1_U3_MCQ_730","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_730","question":"How does the amount of finance available to a business influence its marketing mix?","options":{"A":"It determines whether the business must operate in the public sector.","B":"It limits which promotional methods and distribution channels the business can afford.","C":"It forces every small business to use price skimming.","D":"It eliminates the need to calculate unit production costs."},"correctOption":"B","correctAnswer":"It limits which promotional methods and distribution channels the business can afford.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a small marketing budget prevents a business from affording costly national TV campaigns or opening its own retail store network.","distractor_reasons":{"A":"Incorrect because public-sector status depends on government ownership, not budget size.","B":"Option B is correct because a small marketing budget prevents a business from affording costly national TV campaigns or opening its own retail store network.","C":"Incorrect because small businesses choose pricing methods based on product and competition, not automatically skimming.","D":"Incorrect because knowing unit costs is always essential for setting profitable prices."}}},{"id":"P1_U3_MCQ_731","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_731","question":"How does the nature of the target market influence a business's marketing mix?","options":{"A":"Target market income, age, and lifestyle dictate suitable pricing, promotion media, and outlets.","B":"Target markets have no effect on product packaging or design.","C":"Every target market prefers buying goods exclusively through wholesalers.","D":"All target markets respond identically to price increases."},"correctOption":"A","correctAnswer":"Target market income, age, and lifestyle dictate suitable pricing, promotion media, and outlets.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the four Ps must match the buying habits, spending power, and media preferences of the chosen customer segment.","distractor_reasons":{"A":"Option A is correct because the four Ps must match the buying habits, spending power, and media preferences of the chosen customer segment.","B":"Incorrect because packaging and design must appeal directly to the target demographic.","C":"Incorrect because consumers buy from retailers or directly online, not usually from wholesalers.","D":"Incorrect because price sensitivity varies widely across different income and lifestyle groups."}}},{"id":"P1_U3_MCQ_732","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_732","question":"How does a high level of competition in an industry affect a business's marketing strategy?","options":{"A":"The business can safely charge very high prices without promoting its product.","B":"The business has no need to differentiate its product from rivals.","C":"The business must focus on competitive pricing, product differentiation, and effective promotion.","D":"The business should stop conducting market research to save money."},"correctOption":"C","correctAnswer":"The business must focus on competitive pricing, product differentiation, and effective promotion.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because intense competition requires businesses to offer attractive prices, distinct features, and persuasive promotion to win customers.","distractor_reasons":{"A":"Incorrect because charging high prices without promotion in a competitive market will cause customers to switch to rivals.","B":"Incorrect because differentiation is vital when many competitors offer similar products.","C":"Option C is correct because intense competition requires businesses to offer attractive prices, distinct features, and persuasive promotion to win customers.","D":"Incorrect because market research is crucial to track competitor moves and customer preferences."}}},{"id":"P1_U3_MCQ_733","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_733","question":"What is the main purpose of government legal controls related to marketing?","options":{"A":"To guarantee that every private business makes a high annual profit.","B":"To prevent small businesses from advertising on the internet.","C":"To force all retailers to charge the exact same price for food items.","D":"To protect consumers from faulty goods, unsafe products, and misleading promotion."},"correctOption":"D","correctAnswer":"To protect consumers from faulty goods, unsafe products, and misleading promotion.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because consumer protection laws prevent businesses from deceiving buyers with false claims or selling dangerous, defective products.","distractor_reasons":{"A":"Incorrect because governments do not guarantee profits for private businesses.","B":"Incorrect because online advertising is permitted for businesses of all sizes.","C":"Incorrect because businesses are free to set competitive prices unless price controls apply to specific essentials.","D":"Option D is correct because consumer protection laws prevent businesses from deceiving buyers with false claims or selling dangerous, defective products."}}},{"id":"P1_U3_MCQ_734","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_734","question":"Which marketing practice is prohibited by legal controls against misleading promotion?","options":{"A":"Advertising a jacket as genuine leather when it is actually made of synthetic plastic.","B":"Using colourful photographs on social media to show a product's real features.","C":"Offering a genuine 20% discount on last season's stock.","D":"Stating the accurate country of origin and ingredients on food packaging."},"correctOption":"A","correctAnswer":"Advertising a jacket as genuine leather when it is actually made of synthetic plastic.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because consumer protection laws make it illegal to give false or deceptive descriptions of a product's materials or capabilities.","distractor_reasons":{"A":"Option A is correct because consumer protection laws make it illegal to give false or deceptive descriptions of a product's materials or capabilities.","B":"Incorrect because truthfully displaying real product features is completely legal.","C":"Incorrect because genuine price reductions are permitted.","D":"Incorrect because accurate labelling complies with consumer protection regulations."}}},{"id":"P1_U3_MCQ_735","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_735","question":"What do consumer protection laws regarding product quality require from businesses?","options":{"A":"Every product sold must be the most expensive brand on the market.","B":"Goods must be safe, free from faults, and fit for the purpose intended by the buyer.","C":"Customers are never entitled to a refund even if an appliance breaks on first use.","D":"Businesses only have to check quality if they export goods overseas."},"correctOption":"B","correctAnswer":"Goods must be safe, free from faults, and fit for the purpose intended by the buyer.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because legal controls require goods to be of satisfactory quality, safe to use, and suitable for their stated purpose.","distractor_reasons":{"A":"Incorrect because low-priced goods are legal as long as they are safe and fit for purpose.","B":"Option B is correct because legal controls require goods to be of satisfactory quality, safe to use, and suitable for their stated purpose.","C":"Incorrect because consumers have legal rights to refunds, repairs, or replacements for faulty goods.","D":"Incorrect because domestic consumer protection laws apply to all sales within a country."}}},{"id":"P1_U3_MCQ_736","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_736","question":"What is the purpose of 'weights and measures' legal controls in marketing?","options":{"A":"To restrict the physical size of retail supermarkets in city centres.","B":"To force manufacturers to use only biodegradable glass packaging.","C":"To prevent businesses from selling underweight goods or using inaccurate weighing scales.","D":"To limit the number of adverts a business can broadcast per hour."},"correctOption":"C","correctAnswer":"To prevent businesses from selling underweight goods or using inaccurate weighing scales.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because weights and measures laws ensure consumers receive the exact weight or volume of product stated on the label.","distractor_reasons":{"A":"Incorrect because store size falls under planning regulations, not weights and measures.","B":"Incorrect because packaging material rules relate to environmental regulations.","C":"Option C is correct because weights and measures laws ensure consumers receive the exact weight or volume of product stated on the label.","D":"Incorrect because broadcast limits relate to media advertising standards."}}},{"id":"P1_U3_MCQ_737","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_737","question":"Which pricing practice is illegal under legal controls against misleading price reductions?","options":{"A":"Lowering prices during an annual end-of-year clearance sale.","B":"Using competitive pricing to match a rival supermarket's price.","C":"Offering a bulk-buying discount to wholesale customers.","D":"Claiming a product is reduced by '$50 off' when it was never sold at the higher price."},"correctOption":"D","correctAnswer":"Claiming a product is reduced by '$50 off' when it was never sold at the higher price.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because advertising fake discounts based on an inflated, fictitious previous price deceives consumers about true value.","distractor_reasons":{"A":"Incorrect because genuine seasonal clearance reductions are legal.","B":"Incorrect because matching competitor prices is a standard legal pricing method.","C":"Incorrect because offering volume discounts to trade buyers is legal.","D":"Option D is correct because advertising fake discounts based on an inflated, fictitious previous price deceives consumers about true value."}}},{"id":"P1_U3_MCQ_738","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_738","question":"What is a positive effect on a business of complying fully with consumer protection laws?","options":{"A":"It guarantees that no competitor will ever enter the market.","B":"It completely eliminates all production and quality-testing costs.","C":"It builds customer trust and a strong reputation while avoiding fines and bad publicity.","D":"It allows the business to ignore changing consumer preferences."},"correctOption":"C","correctAnswer":"It builds customer trust and a strong reputation while avoiding fines and bad publicity.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because reliable, safe products and honest promotion create consumer confidence, repeat sales, and protection from legal penalties.","distractor_reasons":{"A":"Incorrect because legal compliance does not prevent rivals from competing.","B":"Incorrect because meeting legal safety and quality rules usually increases testing and compliance costs.","C":"Option C is correct because reliable, safe products and honest promotion create consumer confidence, repeat sales, and protection from legal penalties.","D":"Incorrect because businesses must still adapt to consumer trends to survive."}}},{"id":"P1_U3_MCQ_739","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_739","question":"What is a negative effect on businesses of strict legal controls related to marketing?","options":{"A":"Consumers lose all confidence in buying manufactured goods.","B":"Higher costs of product safety testing, quality control, and redesigns may reduce profits.","C":"Businesses are prevented from exporting goods to high-income countries.","D":"Employees become less motivated to work safely."},"correctOption":"B","correctAnswer":"Higher costs of product safety testing, quality control, and redesigns may reduce profits.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because complying with safety, labelling, and quality regulations raises business expenses, forcing higher prices or lower profit margins.","distractor_reasons":{"A":"Incorrect because legal protection increases, rather than decreases, consumer confidence.","B":"Option B is correct because complying with safety, labelling, and quality regulations raises business expenses, forcing higher prices or lower profit margins.","C":"Incorrect because meeting strict quality standards often helps businesses qualify to export to high-income markets.","D":"Incorrect because safer products and processes generally improve workplace morale."}}},{"id":"P1_U3_MCQ_740","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_740","question":"A cosmetics brand sells in a small home market where sales have stalled and begins exporting to countries with growing demand. What is the main benefit it seeks?","options":{"A":"The elimination of all production costs","B":"Access to new customers and increased sales opportunities","C":"A guaranteed escape from every tariff","D":"An immediate monopoly in every country"},"correctOption":"B","correctAnswer":"Access to new customers and increased sales opportunities","questionType":"MCQ","explanation":{"correct_reason":"Entering overseas markets opens up additional customers, allowing the firm to grow sales beyond a stagnant home market.","distractor_reasons":{"B":"Entering overseas markets opens up additional customers, allowing the firm to grow sales beyond a stagnant home market.","C":"Tariffs are set by foreign governments and cannot be guaranteed away simply by entering a market.","D":"Competition exists in most countries, so a monopoly cannot be assumed from exporting.","A":"Production costs still arise when serving foreign markets; exporting does not make them disappear."}}},{"id":"P1_U3_MCQ_741","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_741","question":"How does entering markets in other countries help a business 'spread risk'?","options":{"A":"By ensuring that exchange rates never fluctuate between currencies.","B":"By selling only one identical product in a single town.","C":"By eliminating all legal regulations in every country entered.","D":"By offsetting falling sales during a home-country recession with strong sales in booming foreign economies."},"correctOption":"D","correctAnswer":"By offsetting falling sales during a home-country recession with strong sales in booming foreign economies.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because operating in multiple countries reduces dependence on one domestic economy; if one market slows down, growth elsewhere can compensate.","distractor_reasons":{"A":"Incorrect because international trade exposes a business to exchange rate fluctuations.","B":"Incorrect because relying on one product in one town concentrates risk rather than spreading it.","C":"Incorrect because businesses must obey the local laws of every country they enter.","D":"Option D is correct because operating in multiple countries reduces dependence on one domestic economy; if one market slows down, growth elsewhere can compensate."}}},{"id":"P1_U3_MCQ_742","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_742","question":"Why might a business enter a new foreign market with a product that has reached the maturity stage at home?","options":{"A":"To avoid paying any wages to foreign distribution workers.","B":"To act as an extension strategy by launching the product where it is still new to consumers.","C":"Because mature products never require any adaptation for foreign cultures.","D":"Because domestic consumers are legally barred from buying mature goods."},"correctOption":"B","correctAnswer":"To act as an extension strategy by launching the product where it is still new to consumers.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a product that is mature in the domestic market may be completely new in an overseas market, extending its profitable Product Life Cycle.","distractor_reasons":{"A":"Incorrect because workers involved in foreign distribution must still be paid.","B":"Option B is correct because a product that is mature in the domestic market may be completely new in an overseas market, extending its profitable Product Life Cycle.","C":"Incorrect because products often need adaptation to suit local tastes and laws abroad.","D":"Incorrect because mature products remain legal to sell domestically."}}},{"id":"P1_U3_MCQ_743","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_743","question":"Why are 'cultural differences' a disadvantage or barrier when entering new markets in other countries?","options":{"A":"Foreign consumers never buy any imported products regardless of price.","B":"Differences in religion, diet, language, and social norms may cause unadapted products or adverts to fail.","C":"Cultural differences prevent businesses from using the internet for market research.","D":"All countries share identical religious holidays and dress codes."},"correctOption":"B","correctAnswer":"Differences in religion, diet, language, and social norms may cause unadapted products or adverts to fail.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because failing to respect local beliefs, languages, or dietary customs can offend consumers and lead to product rejection.","distractor_reasons":{"A":"Incorrect because foreign consumers regularly purchase imported goods that fit their needs.","B":"Option B is correct because failing to respect local beliefs, languages, or dietary customs can offend consumers and lead to product rejection.","C":"Incorrect because online market research can still be conducted across countries.","D":"Incorrect because cultural traditions, religions, and social norms vary widely around the world."}}},{"id":"P1_U3_MCQ_744","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_744","question":"How can a business overcome cultural differences when entering a foreign market?","options":{"A":"By forcing foreign consumers to adopt the home country's traditional diet.","B":"By refusing to translate product labels or advertisements into the local language.","C":"By adapting product ingredients, packaging, and promotional images to match local customs.","D":"By setting prices much higher than local consumers can afford."},"correctOption":"C","correctAnswer":"By adapting product ingredients, packaging, and promotional images to match local customs.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because tailoring the marketing mix—such as modifying food recipes or advertising imagery—ensures cultural acceptability.","distractor_reasons":{"A":"Incorrect because businesses must adapt to consumer preferences rather than forcing change.","B":"Incorrect because untranslated labels hinder sales and may break local laws.","C":"Option C is correct because tailoring the marketing mix—such as modifying food recipes or advertising imagery—ensures cultural acceptability.","D":"Incorrect because unaffordable pricing leads to failure in the new market."}}},{"id":"P1_U3_MCQ_745","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_745","question":"How does 'lack of knowledge' create a barrier when entering a market in another country?","options":{"A":"Managers may not know how to operate their own domestic factory machines.","B":"It prevents the business from calculating its domestic fixed costs.","C":"It guarantees that competitors in the foreign country will go bankrupt.","D":"Unfamiliarity with local incomes, consumer tastes, and competitors can lead to an unsuitable marketing mix."},"correctOption":"D","correctAnswer":"Unfamiliarity with local incomes, consumer tastes, and competitors can lead to an unsuitable marketing mix.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because without understanding local spending power, demographics, and rivals, a business may set the wrong price or choose ineffective promotion.","distractor_reasons":{"A":"Incorrect because lack of knowledge in international expansion refers to unfamiliarity with the foreign market.","B":"Incorrect because domestic fixed costs are known internally.","C":"Incorrect because lack of local knowledge weakens the entering firm rather than local rivals.","D":"Option D is correct because without understanding local spending power, demographics, and rivals, a business may set the wrong price or choose ineffective promotion."}}},{"id":"P1_U3_MCQ_746","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_746","question":"Which action helps a business overcome a lack of local knowledge when entering a foreign market?","options":{"A":"Stopping all communication with distributors in the target country.","B":"Launching the exact domestic marketing mix immediately without any research.","C":"Conducting detailed local market research or hiring a local agent or joint venture partner.","D":"Assuming that average consumer incomes are identical in every country."},"correctOption":"C","correctAnswer":"Conducting detailed local market research or hiring a local agent or joint venture partner.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because local research, agents, or joint venture partners provide vital insights into consumer behaviour, regulations, and distribution channels.","distractor_reasons":{"A":"Incorrect because strong communication with local distributors is essential.","B":"Incorrect because launching blindly without research risks costly marketing errors.","C":"Option C is correct because local research, agents, or joint venture partners provide vital insights into consumer behaviour, regulations, and distribution channels.","D":"Incorrect because income levels vary significantly between countries."}}},{"id":"P1_U3_MCQ_747","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_747","question":"How can differing 'legal requirements' act as a disadvantage when entering new markets in other countries?","options":{"A":"Foreign laws always allow businesses to sell dangerous products without testing.","B":"Different safety standards, labelling rules, or advertising restrictions require costly product changes.","C":"Legal requirements eliminate the need to pay import tariffs.","D":"Foreign governments ban all businesses from using quality assurance."},"correctOption":"B","correctAnswer":"Different safety standards, labelling rules, or advertising restrictions require costly product changes.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because foreign markets may enforce stricter electrical safety laws, packaging rules, or content bans, raising compliance and adaptation costs.","distractor_reasons":{"A":"Incorrect because many foreign countries enforce strict consumer safety regulations.","B":"Option B is correct because foreign markets may enforce stricter electrical safety laws, packaging rules, or content bans, raising compliance and adaptation costs.","C":"Incorrect because tariffs are trade taxes separate from product and marketing regulations.","D":"Incorrect because governments encourage quality assurance to protect consumers."}}},{"id":"P1_U3_MCQ_748","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_748","question":"Why can entering new markets in other countries reduce a business's short-term profitability?","options":{"A":"Total potential market size shrinks whenever a business exports.","B":"Economies of scale are impossible to achieve when output rises.","C":"High upfront costs of foreign market research, product adaptation, transport, and promotion.","D":"Foreign consumers refuse to pay for any goods using electronic banking."},"correctOption":"C","correctAnswer":"High upfront costs of foreign market research, product adaptation, transport, and promotion.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because researching unfamiliar markets, modifying products for local laws/cultures, and establishing overseas distribution require heavy initial investment.","distractor_reasons":{"A":"Incorrect because entering foreign markets expands total market size.","B":"Incorrect because higher international sales volume usually increases economies of scale.","C":"Option C is correct because researching unfamiliar markets, modifying products for local laws/cultures, and establishing overseas distribution require heavy initial investment.","D":"Incorrect because electronic payments are widely used globally."}}},{"id":"P1_U3_MCQ_749","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_749","question":"Why is selling solely through an e-commerce website sometimes insufficient when entering a foreign market?","options":{"A":"Websites cannot be accessed by internet users outside the home country.","B":"Online shopping is illegal in all developing economies.","C":"E-commerce websites cannot display prices in foreign currencies.","D":"Perishable foods, bulky items, and personal services still require physical local distribution or outlets."},"correctOption":"D","correctAnswer":"Perishable foods, bulky items, and personal services still require physical local distribution or outlets.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because products that spoil quickly, are heavy to ship long distances, or require face-to-face delivery cannot rely purely on cross-border parcel shipping.","distractor_reasons":{"A":"Incorrect because websites are globally accessible over the internet.","B":"Incorrect because e-commerce operates legally in both developing and developed economies.","C":"Incorrect because websites easily display multiple currencies.","D":"Option D is correct because products that spoil quickly, are heavy to ship long distances, or require face-to-face delivery cannot rely purely on cross-border parcel shipping."}}},{"id":"P1_U3_MCQ_750","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_750","question":"What determines whether a business's chosen marketing mix will be successful?","options":{"A":"Whether the business uses cost-plus pricing for every single item it sells.","B":"Whether the business spends the maximum possible amount on billboard advertising.","C":"How well Product, Price, Place, and Promotion align with the marketing objective and target market.","D":"Whether the business avoids all forms of secondary market research."},"correctOption":"C","correctAnswer":"How well Product, Price, Place, and Promotion align with the marketing objective and target market.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because an effective marketing strategy requires all four Ps to work harmoniously together to satisfy the target segment and achieve the stated objective.","distractor_reasons":{"A":"Incorrect because the best pricing method depends on the product, competition, and market conditions.","B":"Incorrect because billboards may be unsuitable or unaffordable depending on the target market and budget.","C":"Option C is correct because an effective marketing strategy requires all four Ps to work harmoniously together to satisfy the target segment and achieve the stated objective.","D":"Incorrect because secondary research is a valuable, cost-effective input into marketing decisions."}}},{"id":"P1_U3_MCQ_751","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_751","question":"What is meant by 'building customer relationships' as a role of marketing?","options":{"A":"Forcing retail shops to sign exclusive supply agreements with the manufacturer.","B":"Communicating regularly with buyers to understand feedback and encourage long-term loyalty.","C":"Reducing after-sales customer service staff to lower fixed administrative overheads.","D":"Setting identical prices for every product sold across all international markets."},"correctOption":"B","correctAnswer":"Communicating regularly with buyers to understand feedback and encourage long-term loyalty.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because building customer relationships involves ongoing two-way communication and good service so customers feel valued and return repeatedly.","distractor_reasons":{"A":"Incorrect because exclusive supply deals relate to distribution agreements rather than customer relationships.","B":"Option B is correct because building customer relationships involves ongoing two-way communication and good service so customers feel valued and return repeatedly.","C":"Incorrect because cutting customer support weakens relationships and damages loyalty.","D":"Incorrect because uniform global pricing ignores local market needs and does not build relationships."}}},{"id":"P1_U3_MCQ_752","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_752","question":"Why is it more cost-effective for a business to retain existing loyal customers than to constantly attract new ones?","options":{"A":"Existing loyal customers never complain even if product quality falls.","B":"Marketing and promotional costs per sale are lower for repeat buyers than for acquiring new buyers.","C":"Loyal customers are legally required to pay higher prices than first-time shoppers.","D":"Retaining existing customers eliminates all variable manufacturing expenses."},"correctOption":"B","correctAnswer":"Marketing and promotional costs per sale are lower for repeat buyers than for acquiring new buyers.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because repeat buyers already trust the brand, meaning less advertising expenditure is needed to persuade them to purchase again.","distractor_reasons":{"A":"Incorrect because loyal customers still expect consistent quality and will leave if standards drop.","B":"Option B is correct because repeat buyers already trust the brand, meaning less advertising expenditure is needed to persuade them to purchase again.","C":"Incorrect because loyal buyers often receive loyalty rewards rather than higher prices.","D":"Incorrect because variable production costs still occur for every unit sold."}}},{"id":"P1_U3_MCQ_753","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_753","question":"Which situation best demonstrates a business failing to respond to the power of changing customer needs?","options":{"A":"A smartphone maker launching a model with an improved camera and longer battery life.","B":"A supermarket adding a range of plant-based ready meals after noticing rising vegan demand.","C":"A DVD rental store refusing to offer online streaming despite widespread broadband adoption.","D":"A sportswear brand using recycled ocean plastics to appeal to eco-conscious buyers."},"correctOption":"C","correctAnswer":"A DVD rental store refusing to offer online streaming despite widespread broadband adoption.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because clinging to physical DVD rentals while consumers shift to digital streaming ignores technological and taste changes, leading to business failure.","distractor_reasons":{"A":"Incorrect because upgrading phone features responds directly to consumer expectations.","B":"Incorrect because introducing plant-based meals adapts to changing dietary trends.","C":"Option C is correct because clinging to physical DVD rentals while consumers shift to digital streaming ignores technological and taste changes, leading to business failure.","D":"Incorrect because using recycled materials responds to growing environmental awareness."}}},{"id":"P1_U3_MCQ_754","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_754","question":"How have improvements in international transport contributed to increased competition in many markets?","options":{"A":"They have prevented domestic firms from exporting goods to neighbouring countries.","B":"They have increased import tariffs charged by governments at seaports.","C":"They have forced consumers to buy only perishable local produce.","D":"They have lowered the cost and time of shipping goods globally, allowing foreign rivals to enter domestic markets."},"correctOption":"D","correctAnswer":"They have lowered the cost and time of shipping goods globally, allowing foreign rivals to enter domestic markets.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because faster, cheaper container shipping and air freight enable overseas manufacturers to sell competitively in domestic markets.","distractor_reasons":{"A":"Incorrect because better transport makes exporting easier for domestic firms too.","B":"Incorrect because transport efficiency is separate from government tariff rates.","C":"Incorrect because refrigerated transport actually allows perishable goods to be traded internationally.","D":"Option D is correct because faster, cheaper container shipping and air freight enable overseas manufacturers to sell competitively in domestic markets."}}},{"id":"P1_U3_MCQ_755","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_755","question":"Why does keeping production costs low help a business respond to increased competition?","options":{"A":"It allows the business to offer competitive prices while still maintaining healthy profit margins.","B":"It guarantees that consumer tastes will never change in the future.","C":"It eliminates the need to conduct any primary or secondary market research.","D":"It ensures that the business becomes a legal monopoly in its industry."},"correctOption":"A","correctAnswer":"It allows the business to offer competitive prices while still maintaining healthy profit margins.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because lower unit costs enable a firm to match or undercut rivals' prices without sacrificing profitability.","distractor_reasons":{"A":"Option A is correct because lower unit costs enable a firm to match or undercut rivals' prices without sacrificing profitability.","B":"Incorrect because internal cost control does not stop external consumer preferences from evolving.","C":"Incorrect because market research is still needed to monitor rivals and customers.","D":"Incorrect because low costs help a firm compete, rather than granting a legal monopoly."}}},{"id":"P1_U3_MCQ_756","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_756","question":"A local bakery faces falling bread sales because a large supermarket opened nearby selling cheaper loaves. Which response best uses product improvement to stay competitive?","options":{"A":"Closing the bakery early every afternoon to save on electricity bills.","B":"Introducing freshly baked artisan sourdough and gluten-free specialty breads.","C":"Stopping all social media posts and removing the shop sign outside.","D":"Buying cheaper, lower-quality flour while keeping bread prices unchanged."},"correctOption":"B","correctAnswer":"Introducing freshly baked artisan sourdough and gluten-free specialty breads.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because upgrading the product range with unique, high-quality specialty loaves differentiates the bakery from standard supermarket bread.","distractor_reasons":{"A":"Incorrect because shorter opening hours reduce convenience and sales further.","B":"Option B is correct because upgrading the product range with unique, high-quality specialty loaves differentiates the bakery from standard supermarket bread.","C":"Incorrect because reducing visibility and promotion will lose more customers.","D":"Incorrect because lowering quality for the same price drives customers away."}}},{"id":"P1_U3_MCQ_757","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_757","question":"Which product is most likely to be sold in a mass market?","options":{"A":"Hand-built luxury sports cars costing $400,000 each.","B":"Custom-made orthodontic braces fitted for individual patients.","C":"Standardised everyday toothpaste sold in supermarkets nationwide.","D":"Left-handed professional concert harps crafted to order."},"correctOption":"C","correctAnswer":"Standardised everyday toothpaste sold in supermarkets nationwide.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because everyday toothpaste is a standardised product with huge, broad appeal across almost the entire population.","distractor_reasons":{"A":"Incorrect because ultra-expensive luxury sports cars serve a small high-income niche.","B":"Incorrect because custom medical items are tailored to individual needs rather than mass-produced.","C":"Option C is correct because everyday toothpaste is a standardised product with huge, broad appeal across almost the entire population.","D":"Incorrect because specialised instruments for left-handed musicians represent a tiny niche market."}}},{"id":"P1_U3_MCQ_758","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_758","question":"Which business is operating in a niche market?","options":{"A":"A global soft drinks manufacturer selling cola in 150 countries.","B":"A national supermarket chain selling everyday groceries to millions of households.","C":"A mass-market clothing retailer selling basic white cotton T-shirts.","D":"A specialist tailor making waterproof hiking coats exclusively for mountain rescue teams."},"correctOption":"D","correctAnswer":"A specialist tailor making waterproof hiking coats exclusively for mountain rescue teams.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because mountain rescue gear serves a very small, specialised segment of the outdoor clothing market with specific technical requirements.","distractor_reasons":{"A":"Incorrect because global cola sales represent a classic mass market.","B":"Incorrect because nationwide grocery retailing serves a broad mass market.","C":"Incorrect because basic cotton T-shirts appeal to the general mass market.","D":"Option D is correct because mountain rescue gear serves a very small, specialised segment of the outdoor clothing market with specific technical requirements."}}},{"id":"P1_U3_MCQ_759","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_759","question":"Why can businesses operating in a niche market often charge higher profit margins per unit than mass-market firms?","options":{"A":"Customers have specific needs that few rivals satisfy and are willing to pay more for specialised products.","B":"Niche businesses achieve the highest possible purchasing economies of scale.","C":"Government laws prevent niche businesses from offering any price discounts.","D":"Niche businesses never have to pay for raw materials or skilled labour."},"correctOption":"A","correctAnswer":"Customers have specific needs that few rivals satisfy and are willing to pay more for specialised products.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because specialised products tailored to distinct needs face less direct competition, allowing higher prices and profit margins per unit.","distractor_reasons":{"A":"Option A is correct because specialised products tailored to distinct needs face less direct competition, allowing higher prices and profit margins per unit.","B":"Incorrect because low sales volumes in niche markets limit economies of scale.","C":"Incorrect because niche firms are free to set their own prices and discounts.","D":"Incorrect because niche producers often use expensive specialist materials and skilled labour."}}},{"id":"P1_U3_MCQ_760","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_760","question":"What happens if a niche market grows rapidly and becomes highly profitable?","options":{"A":"The original niche firm is guaranteed a permanent legal monopoly.","B":"Larger mass-market businesses may enter the segment and threaten the small niche firm.","C":"Unit production costs automatically rise to infinity.","D":"Consumers stop buying the product because it is too popular."},"correctOption":"B","correctAnswer":"Larger mass-market businesses may enter the segment and threaten the small niche firm.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because if a niche grows large enough to offer high sales volumes, big corporations with economies of scale may enter and outcompete the small pioneer.","distractor_reasons":{"A":"Incorrect because unless protected by patents, profitable niches attract new entrants.","B":"Option B is correct because if a niche grows large enough to offer high sales volumes, big corporations with economies of scale may enter and outcompete the small pioneer.","C":"Incorrect because higher output usually lowers average unit costs through economies of scale.","D":"Incorrect because market growth reflects rising consumer demand."}}},{"id":"P1_U3_MCQ_761","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_761","question":"Why is operating in a mass market often less risky for product diversification than relying on a single niche market?","options":{"A":"Mass-market businesses never face any competition from rival brands.","B":"Mass markets require zero spending on national advertising.","C":"Large customer numbers and multiple product variations spread risk across wider demand.","D":"Mass-market consumers always buy products regardless of price or quality."},"correctOption":"C","correctAnswer":"Large customer numbers and multiple product variations spread risk across wider demand.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because mass-market firms serve huge customer bases and can sell several product lines, whereas a niche firm depends heavily on one small segment.","distractor_reasons":{"A":"Incorrect because mass markets typically involve intense competition.","B":"Incorrect because mass-market firms usually spend heavily on advertising.","C":"Option C is correct because mass-market firms serve huge customer bases and can sell several product lines, whereas a niche firm depends heavily on one small segment.","D":"Incorrect because mass-market buyers are very sensitive to price and quality."}}},{"id":"P1_U3_MCQ_762","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_762","question":"What does segmenting a market by 'socio-economic group' involve?","options":{"A":"Dividing consumers solely by whether they live in coastal or inland towns.","B":"Grouping buyers strictly according to their favourite sports teams.","C":"Classifying customers based only on their biological age.","D":"Grouping consumers according to their occupation, education, and social status."},"correctOption":"D","correctAnswer":"Grouping consumers according to their occupation, education, and social status.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because socio-economic segmentation categorises people by job type, qualifications, and income/social class, which strongly influence buying patterns.","distractor_reasons":{"A":"Incorrect because coastal versus inland living is geographic/location segmentation.","B":"Incorrect because hobbies and interests relate to lifestyle segmentation.","C":"Incorrect because age brackets represent age segmentation.","D":"Option D is correct because socio-economic segmentation categorises people by job type, qualifications, and income/social class, which strongly influence buying patterns."}}},{"id":"P1_U3_MCQ_763","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_763","question":"A computer manufacturer sells basic laptops for home students and high-specification workstations for professional video editors. Which segmentation method is being used?","options":{"A":"Use of the product.","B":"Gender segmentation.","C":"Climate segmentation.","D":"Age segmentation."},"correctOption":"A","correctAnswer":"Use of the product.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the manufacturer divides buyers based on how they intend to use the computer (everyday study versus heavy professional editing).","distractor_reasons":{"A":"Option A is correct because the manufacturer divides buyers based on how they intend to use the computer (everyday study versus heavy professional editing).","B":"Incorrect because laptops are not divided into male and female versions here.","C":"Incorrect because climate does not determine student versus video-editing specifications.","D":"Incorrect because the distinction is based on task/usage rather than age."}}},{"id":"P1_U3_MCQ_764","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_764","question":"Which segmentation method is most appropriate for a company selling luxury winter ski holidays?","options":{"A":"Gender and household size.","B":"Income and lifestyle.","C":"Gender and occupation only.","D":"Local postal code only."},"correctOption":"B","correctAnswer":"Income and lifestyle.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because luxury ski trips require high disposable income and appeal to consumers with an active, winter-sports lifestyle.","distractor_reasons":{"A":"Incorrect because ski holidays are enjoyed by all genders regardless of family size.","B":"Option B is correct because luxury ski trips require high disposable income and appeal to consumers with an active, winter-sports lifestyle.","C":"Incorrect because occupation and gender alone do not capture interest in skiing or ability to pay.","D":"Incorrect because postal code alone ignores whether residents can afford or enjoy skiing."}}},{"id":"P1_U3_MCQ_765","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_765","question":"How does market segmentation help a business identify new market opportunities?","options":{"A":"By reducing the total number of employees required in the finance department.","B":"By forcing all consumers in the country to buy the exact same product design.","C":"By eliminating the need to calculate profit margins on new product launches.","D":"By highlighting specific consumer sub-groups whose needs are not currently met by competitors."},"correctOption":"D","correctAnswer":"By highlighting specific consumer sub-groups whose needs are not currently met by competitors.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because analysing individual segments often reveals underserved gaps in the market where new products can be profitably launched.","distractor_reasons":{"A":"Incorrect because segmentation is a marketing tool unrelated to finance staffing levels.","B":"Incorrect because segmentation involves tailoring products to distinct groups rather than selling one uniform item.","C":"Incorrect because financial profitability analysis is always required before launching products.","D":"Option D is correct because analysing individual segments often reveals underserved gaps in the market where new products can be profitably launched."}}},{"id":"P1_U3_MCQ_766","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_766","question":"How does market segmentation make promotional spending more cost-effective?","options":{"A":"It ensures every person in the country buys the advertised product.","B":"It requires television stations to broadcast adverts free of charge.","C":"It eliminates the need to design attractive promotional messages.","D":"It allows a business to target adverts specifically at media channels used by its chosen segment."},"correctOption":"D","correctAnswer":"It allows a business to target adverts specifically at media channels used by its chosen segment.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because knowing who the target buyers are avoids wasting money advertising to people unlikely to purchase the product.","distractor_reasons":{"A":"Incorrect because segmented promotion aims at a specific target group rather than the entire population.","B":"Incorrect because media channels still charge standard advertising rates.","C":"Incorrect because tailored, persuasive messaging is still vital.","D":"Option D is correct because knowing who the target buyers are avoids wasting money advertising to people unlikely to purchase the product."}}},{"id":"P1_U3_MCQ_767","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_767","question":"What is a potential disadvantage to a business of dividing its market into too many small segments?","options":{"A":"Customers receive products that match their exact needs too closely.","B":"Higher production and marketing costs from creating separate product ranges and adverts for each segment.","C":"Total sales revenue falls to zero because segments cannot buy online.","D":"Competitors are legally prevented from entering any of the segments."},"correctOption":"B","correctAnswer":"Higher production and marketing costs from creating separate product ranges and adverts for each segment.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because producing multiple tailored versions and running separate promotional campaigns reduces economies of scale and increases costs.","distractor_reasons":{"A":"Incorrect because meeting customer needs closely is a benefit, not a disadvantage.","B":"Option B is correct because producing multiple tailored versions and running separate promotional campaigns reduces economies of scale and increases costs.","C":"Incorrect because segmented products can still be sold online and in stores.","D":"Incorrect because rivals can compete in any segment."}}},{"id":"P1_U3_MCQ_768","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_768","question":"A toy manufacturer wants to launch a new educational board game. Which primary segmentation basis should it use first?","options":{"A":"Location (urban vs rural).","B":"Occupation of the child.","C":"Age of the children.","D":"Car ownership."},"correctOption":"C","correctAnswer":"Age of the children.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because children's reading ability, interests, and safety requirements vary sharply by age bracket.","distractor_reasons":{"A":"Incorrect because children in both urban and rural areas play board games.","B":"Incorrect because children do not have occupations.","C":"Option C is correct because children's reading ability, interests, and safety requirements vary sharply by age bracket.","D":"Incorrect because car ownership is irrelevant to educational board games."}}},{"id":"P1_U3_MCQ_769","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_769","question":"A sportswear company sells affordable running shoes under one brand and high-end carbon-plated marathon shoes under another. What is the main benefit of targeting both income segments?","options":{"A":"It eliminates all competition in the athletic footwear industry.","B":"It guarantees identical profit margins on every pair of shoes sold.","C":"It prevents the company from ever needing to advertise.","D":"It maximises total market coverage and sales across both budget and premium buyers."},"correctOption":"D","correctAnswer":"It maximises total market coverage and sales across both budget and premium buyers.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because offering distinct tiers captures sales from price-sensitive runners as well as high-income enthusiasts.","distractor_reasons":{"A":"Incorrect because rival sportswear brands still compete in both tiers.","B":"Incorrect because premium shoes typically earn higher profit margins than budget shoes.","C":"Incorrect because both brands still require promotion.","D":"Option D is correct because offering distinct tiers captures sales from price-sensitive runners as well as high-income enthusiasts."}}},{"id":"P1_U3_MCQ_770","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_770","question":"Which formula correctly calculates a business's market share?","options":{"A":"(Business sales / Total market sales) x 100","B":"(Total market sales / Business sales) x 100","C":"(Gross profit / Sales revenue) x 100","D":"(Fixed costs / Contribution per unit)"},"correctOption":"A","correctAnswer":"(Business sales / Total market sales) x 100","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because market share expresses one firm's sales as a percentage of total sales in the entire market.","distractor_reasons":{"A":"Option A is correct because market share expresses one firm's sales as a percentage of total sales in the entire market.","B":"Incorrect because dividing total market sales by business sales inverts the fraction.","C":"Incorrect because this formula calculates gross profit margin.","D":"Incorrect because this formula calculates break-even output."}}},{"id":"P1_U3_MCQ_771","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_771","question":"Total annual sales in the national bottled water market are $50 million. Company X achieves annual sales of $10 million. What is Company X's market share?","options":{"A":"5%","B":"20%","C":"40%","D":"50%"},"correctOption":"B","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because ($10 million / $50 million) x 100 = 20%.","distractor_reasons":{"A":"Incorrect because $50m / $10m = 5, not 5%.","B":"Option B is correct because ($10 million / $50 million) x 100 = 20%.","C":"Incorrect because 40% would require $20 million in sales.","D":"Incorrect because 50% would require $25 million in sales."}}},{"id":"P1_U3_MCQ_772","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_772","question":"Why can a business's sales revenue increase while its market share decreases at the same time?","options":{"A":"Because the business lowered its selling prices to zero.","B":"Because total market sales fell faster than the business's sales.","C":"Because total market sales grew at a faster percentage rate than the business's own sales.","D":"Because the business stopped recording cash transactions."},"correctOption":"C","correctAnswer":"Because total market sales grew at a faster percentage rate than the business's own sales.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because if the overall market expands by 30% while the business's sales only grow by 10%, its percentage slice of the market shrinks.","distractor_reasons":{"A":"Incorrect because zero prices would reduce sales revenue to zero.","B":"Incorrect because if total market sales fell while the business's sales rose, market share would increase.","C":"Option C is correct because if the overall market expands by 30% while the business's sales only grow by 10%, its percentage slice of the market shrinks.","D":"Incorrect because accounting omissions do not explain real market growth dynamics."}}},{"id":"P1_U3_MCQ_773","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_773","question":"How does a fall in average consumer incomes during an economic recession affect spending patterns?","options":{"A":"Demand rises sharply for luxury yachts and designer jewellery.","B":"Consumers stop buying basic food and household utilities.","C":"Businesses switch from discount pricing to high price skimming.","D":"Consumers switch from expensive branded goods to cheaper own-label or value alternatives."},"correctOption":"D","correctAnswer":"Consumers switch from expensive branded goods to cheaper own-label or value alternatives.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because lower disposable incomes make shoppers more price-sensitive, increasing demand for budget and supermarket own-brand items.","distractor_reasons":{"A":"Incorrect because demand for luxury items falls when incomes decline.","B":"Incorrect because basic necessities remain essential even during a recession.","C":"Incorrect because businesses usually lower prices or offer promotions during recessions.","D":"Option D is correct because lower disposable incomes make shoppers more price-sensitive, increasing demand for budget and supermarket own-brand items."}}},{"id":"P1_U3_MCQ_774","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_774","question":"Which demographic trend in many developed countries has created growing markets for retirement villages, hearing aids, and cruise holidays?","options":{"A":"An ageing population with a larger proportion of retired consumers.","B":"A rapid increase in the birth rate of newborn babies.","C":"A sharp decline in life expectancy across all regions.","D":"A decrease in the number of people aged over 65."},"correctOption":"A","correctAnswer":"An ageing population with a larger proportion of retired consumers.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because longer life expectancy and lower birth rates expand the older age segment, raising demand for retirement-related goods and services.","distractor_reasons":{"A":"Option A is correct because longer life expectancy and lower birth rates expand the older age segment, raising demand for retirement-related goods and services.","B":"Incorrect because higher birth rates boost demand for baby products rather than retirement villages.","C":"Incorrect because falling life expectancy would shrink the elderly population.","D":"Incorrect because fewer over-65s would reduce demand for retirement services."}}},{"id":"P1_U3_MCQ_775","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_775","question":"What is the main danger for a business that relies purely on a product-oriented approach in a fast-changing consumer market?","options":{"A":"It will spend too much money listening to customer focus groups.","B":"It risks producing high-quality goods that consumers no longer want to buy.","C":"It will achieve too many economies of scale too quickly.","D":"It will be forced to lower its prices every single day."},"correctOption":"B","correctAnswer":"It risks producing high-quality goods that consumers no longer want to buy.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because focusing solely on the product without researching changing customer preferences can result in unsold stock when tastes shift.","distractor_reasons":{"A":"Incorrect because product-oriented firms do very little customer research.","B":"Option B is correct because focusing solely on the product without researching changing customer preferences can result in unsold stock when tastes shift.","C":"Incorrect because low demand prevents a firm from achieving high-volume economies of scale.","D":"Incorrect because daily price changes relate to dynamic pricing, not product orientation."}}},{"id":"P1_U3_MCQ_776","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_776","question":"Which information can a market-oriented business obtain by conducting market research before launching a new snack bar?","options":{"A":"The exact future interest rate set by the central bank in five years.","B":"A legal guarantee that no rival company will ever copy the recipe.","C":"Preferred flavours, suitable packaging sizes, and the price consumers are willing to pay.","D":"The personal bank account balances of individual factory workers."},"correctOption":"C","correctAnswer":"Preferred flavours, suitable packaging sizes, and the price consumers are willing to pay.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because market research investigates customer preferences regarding product features, pricing, and packaging prior to launch.","distractor_reasons":{"A":"Incorrect because central bank interest rates are macroeconomic policies, not market research data.","B":"Incorrect because market research cannot legally block competitors.","C":"Option C is correct because market research investigates customer preferences regarding product features, pricing, and packaging prior to launch.","D":"Incorrect because employee personal finances are private and irrelevant to product demand."}}},{"id":"P1_U3_MCQ_777","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_777","question":"What is the difference between quantitative and qualitative market research data?","options":{"A":"Quantitative data is collected only from secondary sources, whereas qualitative data is always primary.","B":"Quantitative data is gathered by the government, whereas qualitative data is gathered by private firms.","C":"Quantitative data is always unbiased, whereas qualitative data is always inaccurate.","D":"Quantitative data consists of numerical statistics, whereas qualitative data explores opinions and reasons."},"correctOption":"D","correctAnswer":"Quantitative data consists of numerical statistics, whereas qualitative data explores opinions and reasons.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because quantitative research answers 'how many' or 'what percentage' in numbers, while qualitative research explains 'why' consumers feel a certain way.","distractor_reasons":{"A":"Incorrect because both primary and secondary research can produce quantitative and qualitative data.","B":"Incorrect because private businesses collect both types of data.","C":"Incorrect because quantitative surveys can also be biased if poorly designed.","D":"Option D is correct because quantitative research answers 'how many' or 'what percentage' in numbers, while qualitative research explains 'why' consumers feel a certain way."}}},{"id":"P1_U3_MCQ_778","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_778","question":"Which of the following is an example of an internal secondary research source?","options":{"A":"An online survey sent out to 500 potential new customers yesterday.","B":"A national population census published by the government statistics office.","C":"The business's own past sales records and customer loyalty card purchase data.","D":"A trade association report sold to all companies in the industry."},"correctOption":"C","correctAnswer":"The business's own past sales records and customer loyalty card purchase data.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the company's own historical sales figures and customer records already exist inside the business.","distractor_reasons":{"A":"Incorrect because a newly sent online survey collects original primary data.","B":"Incorrect because government census data is an external secondary source.","C":"Option C is correct because the company's own historical sales figures and customer records already exist inside the business.","D":"Incorrect because a trade association report is an external secondary source."}}},{"id":"P1_U3_MCQ_779","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_779","question":"Why do businesses often carry out secondary market research before conducting primary research?","options":{"A":"Because primary research is illegal unless secondary research is completed first.","B":"Because secondary data is quick and cheap to gather, helping narrow down what primary research is still needed.","C":"Because secondary data is always more accurate and up to date than primary data.","D":"Because secondary research requires interviewing thousands of shoppers in person."},"correctOption":"B","correctAnswer":"Because secondary data is quick and cheap to gather, helping narrow down what primary research is still needed.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because checking existing secondary data first avoids wasting money collecting information that has already been published.","distractor_reasons":{"A":"Incorrect because there is no legal requirement to do secondary research first.","B":"Option B is correct because checking existing secondary data first avoids wasting money collecting information that has already been published.","C":"Incorrect because secondary data is often older and less specific than primary research.","D":"Incorrect because interviewing shoppers is primary field research."}}},{"id":"P1_U3_MCQ_780","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_780","question":"What is a major advantage of online surveys compared to postal questionnaires?","options":{"A":"Online surveys reach people who have no access to the internet.","B":"Online surveys guarantee a 100% response rate from every recipient.","C":"Responses are collected quickly at very low cost and analysed automatically by software.","D":"An interviewer sits beside every respondent to clarify confusing questions."},"correctOption":"C","correctAnswer":"Responses are collected quickly at very low cost and analysed automatically by software.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because online surveys avoid printing and postage expenses and instantly tabulate results into charts and tables.","distractor_reasons":{"A":"Incorrect because offline populations cannot complete online surveys.","B":"Incorrect because many people ignore online survey links.","C":"Option C is correct because online surveys avoid printing and postage expenses and instantly tabulate results into charts and tables.","D":"Incorrect because online surveys are self-completed without a live interviewer."}}},{"id":"P1_U3_MCQ_781","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_781","question":"Why might a postal questionnaire produce a biased sample of opinions?","options":{"A":"Because postal questionnaires can only be answered by teenagers.","B":"Because postal mail is delivered instantaneously within two seconds.","C":"Because interviewers force respondents to choose Option A.","D":"Because low response rates mean only people with very strong views or spare time reply."},"correctOption":"D","correctAnswer":"Because low response rates mean only people with very strong views or spare time reply.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because busy people often throw away postal surveys, leaving a self-selected group of respondents that may not reflect the whole market.","distractor_reasons":{"A":"Incorrect because postal questionnaires are usually sent to adult households.","B":"Incorrect because postal surveys are slow to send and receive back.","C":"Incorrect because there is no interviewer present with postal surveys.","D":"Option D is correct because busy people often throw away postal surveys, leaving a self-selected group of respondents that may not reflect the whole market."}}},{"id":"P1_U3_MCQ_782","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_782","question":"Which primary research method is best suited for obtaining deep, qualitative insights into how target customers react to three new TV advert concepts?","options":{"A":"A focus group.","B":"Counting store footfall by observation.","C":"Reading government census tables.","D":"A 2-question postal postcard."},"correctOption":"A","correctAnswer":"A focus group.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a focus group allows participants to watch the adverts and discuss their emotional reactions and suggestions in detail.","distractor_reasons":{"A":"Option A is correct because a focus group allows participants to watch the adverts and discuss their emotional reactions and suggestions in detail.","B":"Incorrect because observation only counts people and cannot measure reactions to draft adverts.","C":"Incorrect because government census data is secondary demographic data.","D":"Incorrect because a short postal card cannot show video adverts or capture rich discussion."}}},{"id":"P1_U3_MCQ_783","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_783","question":"A supermarket manager uses CCTV footage to track which aisles shoppers visit most frequently and where they pause. Which research method is this?","options":{"A":"Quota sampling.","B":"Observation.","C":"Secondary desk research.","D":"Postal survey."},"correctOption":"B","correctAnswer":"Observation.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because watching and recording shoppers' actual movements without questioning them is primary observation.","distractor_reasons":{"A":"Incorrect because quota sampling is a method of choosing people to question.","B":"Option B is correct because watching and recording shoppers' actual movements without questioning them is primary observation.","C":"Incorrect because recording live shopper movement generates new primary data.","D":"Incorrect because no written questionnaire is mailed to shoppers."}}},{"id":"P1_U3_MCQ_784","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_784","question":"What is a major advantage of observation over questionnaires in market research?","options":{"A":"It reveals the exact household income of every shopper.","B":"It explains why a customer prefers one brand over another.","C":"It records what consumers actually do rather than what they claim they do.","D":"It is the best method for testing ideas for products that do not exist yet."},"correctOption":"C","correctAnswer":"It records what consumers actually do rather than what they claim they do.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because respondents in surveys sometimes give inaccurate or socially desirable answers, whereas observation captures real behaviour.","distractor_reasons":{"A":"Incorrect because watching shoppers does not reveal their private income.","B":"Incorrect because observation cannot uncover underlying motives without asking questions.","C":"Option C is correct because respondents in surveys sometimes give inaccurate or socially desirable answers, whereas observation captures real behaviour.","D":"Incorrect because consumers cannot be observed interacting with a product that has not been made yet."}}},{"id":"P1_U3_MCQ_785","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_785","question":"Why do market researchers use sampling instead of interviewing the entire population (a census)?","options":{"A":"Because interviewing everyone in a target market is usually too expensive and time-consuming.","B":"Because random samples always give more accurate results than surveying 100% of the population.","C":"Because data protection laws forbid businesses from interviewing more than 50 people.","D":"Because sampling eliminates the need to analyse survey answers."},"correctOption":"A","correctAnswer":"Because interviewing everyone in a target market is usually too expensive and time-consuming.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because surveying millions of potential buyers is impractical and costly, so a representative sample provides timely insights at manageable cost.","distractor_reasons":{"A":"Option A is correct because surveying millions of potential buyers is impractical and costly, so a representative sample provides timely insights at manageable cost.","B":"Incorrect because a full census is more accurate than a sample, though far costlier.","C":"Incorrect because there is no 50-person legal limit on market research.","D":"Incorrect because sample data still requires careful statistical analysis."}}},{"id":"P1_U3_MCQ_786","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_786","question":"A researcher selects 300 names from an alphabetical list using a computer that gives every name an equal chance of being chosen. What is the main advantage of this approach?","options":{"A":"Every member of the population has an equal chance, which reduces selection bias","B":"It deliberately over-represents the largest age groups","C":"It removes the need to define the target population first","D":"It guarantees a perfectly representative result every time"},"correctOption":"A","correctAnswer":"Every member of the population has an equal chance, which reduces selection bias","questionType":"MCQ","explanation":{"correct_reason":"Equal chances of selection mean no section of the population is favoured, reducing bias in the sample chosen.","distractor_reasons":{"B":"Over-representing groups is a feature of quota selection, not of a method based on equal chances.","C":"The population must still be identified and listed before any names can be drawn for the sample.","D":"Equal chances reduce bias but cannot guarantee a perfectly representative result on every occasion.","A":"Equal chances of selection mean no section of the population is favoured, reducing bias in the sample chosen."}}},{"id":"P1_U3_MCQ_787","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_787","question":"What is a potential limitation of random sampling?","options":{"A":"Interviewers always pick only wealthy consumers.","B":"It can only be used for secondary desk research.","C":"By pure chance, a small random sample might over-represent one demographic group.","D":"It is impossible to conduct using computer software."},"correctOption":"C","correctAnswer":"By pure chance, a small random sample might over-represent one demographic group.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because pure chance selection does not guarantee demographic balance, especially if the sample size is small.","distractor_reasons":{"A":"Incorrect because every individual has an equal chance in random sampling.","B":"Incorrect because random sampling is a primary research sampling method.","C":"Option C is correct because pure chance selection does not guarantee demographic balance, especially if the sample size is small.","D":"Incorrect because computers are widely used to generate random samples."}}},{"id":"P1_U3_MCQ_788","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_788","question":"A cosmetics company instructs interviewers in a shopping mall to survey 100 women aged 18–25, 100 women aged 26–40, and 100 women aged over 40. Which sampling method is being used?","options":{"A":"Random sampling.","B":"Census sampling.","C":"Secondary sampling.","D":"Quota sampling."},"correctOption":"D","correctAnswer":"Quota sampling.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because interviewers are given fixed targets (quotas) of respondents sharing specific gender and age characteristics.","distractor_reasons":{"A":"Incorrect because respondents are not chosen purely at random from a full population list.","B":"Incorrect because a census surveys the entire population rather than 300 shoppers.","C":"Incorrect because this is original primary research.","D":"Option D is correct because interviewers are given fixed targets (quotas) of respondents sharing specific gender and age characteristics."}}},{"id":"P1_U3_MCQ_789","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_789","question":"What is a weakness of quota sampling compared to random sampling?","options":{"A":"Interviewers choose who to approach within each quota, which can introduce human selection bias.","B":"It prevents researchers from collecting data from different age groups.","C":"It requires a complete list of every citizen in the country.","D":"It takes much longer to complete than surveying an entire country."},"correctOption":"A","correctAnswer":"Interviewers choose who to approach within each quota, which can introduce human selection bias.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because interviewers may approach friendly-looking or easily accessible people to fill their quotas, creating selection bias.","distractor_reasons":{"A":"Option A is correct because interviewers may approach friendly-looking or easily accessible people to fill their quotas, creating selection bias.","B":"Incorrect because quota sampling specifically ensures multiple age groups are included.","C":"Incorrect because not needing a full population list is actually an advantage of quota sampling.","D":"Incorrect because quota sampling is much faster than a full census."}}},{"id":"P1_U3_MCQ_790","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_790","question":"Why is the following questionnaire question poorly written: 'Don't you agree that our delicious new fruit juice is better than sugary sodas?'","options":{"A":"It is too short for respondents to read.","B":"It is a leading question that pushes respondents toward a positive answer, biasing the results.","C":"It asks for too much confidential financial information.","D":"It can only be answered using secondary government data."},"correctOption":"B","correctAnswer":"It is a leading question that pushes respondents toward a positive answer, biasing the results.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because words like 'Don't you agree' and 'delicious' steer respondents to agree, making the survey data unreliable.","distractor_reasons":{"A":"Incorrect because question length is not the flaw here.","B":"Option B is correct because words like 'Don't you agree' and 'delicious' steer respondents to agree, making the survey data unreliable.","C":"Incorrect because the question asks about drink preference, not personal finances.","D":"Incorrect because this is a primary consumer survey question."}}},{"id":"P1_U3_MCQ_791","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_791","question":"A business surveys 20 people outside a luxury golf club to estimate national demand for a new budget commuter bicycle. Why will the research results likely be inaccurate?","options":{"A":"Budget bicycles can only be researched using secondary sources.","B":"Golfers are legally prohibited from answering market research questions.","C":"The sample size is too small and unrepresentative of typical budget bicycle commuters.","D":"The questionnaire contained too many open-ended questions."},"correctOption":"C","correctAnswer":"The sample size is too small and unrepresentative of typical budget bicycle commuters.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because 20 wealthy golf club visitors do not represent the wider commuter population, leading to severe sampling error and bias.","distractor_reasons":{"A":"Incorrect because primary research is useful for bicycles if conducted with a representative sample.","B":"Incorrect because anyone may legally participate in market research.","C":"Option C is correct because 20 wealthy golf club visitors do not represent the wider commuter population, leading to severe sampling error and bias.","D":"Incorrect because the core error here is the unrepresentative location and tiny sample size."}}},{"id":"P1_U3_MCQ_792","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_792","question":"Why might secondary market research data published by a rival company's trade group be unreliable?","options":{"A":"Because trade groups never publish numerical statistics.","B":"Because the organisation may have presented data selectively to promote its own industry interests.","C":"Because secondary data can only be read once before expiring.","D":"Because trade reports are always written in dead languages."},"correctOption":"B","correctAnswer":"Because the organisation may have presented data selectively to promote its own industry interests.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because industry lobbies or commercial publishers may emphasise favourable figures and omit weaknesses, introducing source bias.","distractor_reasons":{"A":"Incorrect because trade groups frequently publish industry sales and growth statistics.","B":"Option B is correct because industry lobbies or commercial publishers may emphasise favourable figures and omit weaknesses, introducing source bias.","C":"Incorrect because published reports can be reviewed repeatedly.","D":"Incorrect because trade reports are written in standard business languages."}}},{"id":"P1_U3_MCQ_793","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_793","question":"Which visual presentation method is best for showing how a total market of 100% is divided among four competing brands?","options":{"A":"A factory floor layout map.","B":"A pie chart.","C":"An organisation hierarchy chart.","D":"A job description."},"correctOption":"B","correctAnswer":"A pie chart.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a pie chart visually displays proportions or percentage shares making up a whole (100%).","distractor_reasons":{"A":"Incorrect because a factory map shows physical machine placement.","B":"Option B is correct because a pie chart visually displays proportions or percentage shares making up a whole (100%).","C":"Incorrect because an organisation chart shows management roles and chain of command.","D":"Incorrect because a job description outlines an employee's duties."}}},{"id":"P1_U3_MCQ_794","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_794","question":"Which chart is most effective for illustrating changes in a product's monthly sales revenue over a 12-month period?","options":{"A":"A pie chart.","B":"A line graph.","C":"A person specification.","D":"A balance sheet."},"correctOption":"B","correctAnswer":"A line graph.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because line graphs clearly show continuous trends and fluctuations over time.","distractor_reasons":{"A":"Incorrect because pie charts show parts of a whole at a single point in time rather than trends over 12 months.","B":"Option B is correct because line graphs clearly show continuous trends and fluctuations over time.","C":"Incorrect because a person specification lists candidate skills for recruitment.","D":"Incorrect because a balance sheet is a financial statement of assets and liabilities."}}},{"id":"P1_U3_MCQ_795","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_795","question":"A survey of 400 consumers asks which smartphone feature matters most: 180 choose Battery Life, 120 choose Camera Quality, 60 choose Screen Size, and 40 choose Price. What percentage chose Camera Quality?","options":{"A":"15%","B":"25%","C":"30%","D":"45%"},"correctOption":"C","correctAnswer":"30%","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because (120 / 400) x 100 = 30%.","distractor_reasons":{"A":"Incorrect because 60 / 400 = 15% (Screen Size).","B":"Incorrect because 25% would be 100 respondents.","C":"Option C is correct because (120 / 400) x 100 = 30%.","D":"Incorrect because 180 / 400 = 45% (Battery Life)."}}},{"id":"P1_U3_MCQ_796","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_796","question":"In the same survey of 400 consumers (180 Battery Life, 120 Camera Quality, 60 Screen Size, 40 Price), what conclusion should the smartphone manufacturer draw?","options":{"A":"Consumers care only about low prices and ignore technical performance.","B":"Screen size is the single highest priority for target customers.","C":"The company should remove cameras from its next smartphone model.","D":"Product development and advertising should emphasise long battery life and strong camera quality."},"correctOption":"D","correctAnswer":"Product development and advertising should emphasise long battery life and strong camera quality.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because 75% of respondents (300 out of 400) prioritised either battery life (45%) or camera quality (30%).","distractor_reasons":{"A":"Incorrect because only 10% (40 out of 400) ranked price as their top feature.","B":"Incorrect because screen size was chosen by only 15% of respondents.","C":"Incorrect because 30% ranked camera quality as their number one priority.","D":"Option D is correct because 75% of respondents (300 out of 400) prioritised either battery life (45%) or camera quality (30%)."}}},{"id":"P1_U3_MCQ_797","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_797","question":"A bar chart shows a cafe's quarterly sales: Q1 = $20,000, Q2 = $25,000, Q3 = $40,000, Q4 = $15,000. Which marketing action is best supported by this data?","options":{"A":"Stopping all advertising during Q1, Q2, and Q4.","B":"Closing the cafe permanently during Q3 when sales are highest.","C":"Raising prices by 100% in Q4 to recover lost revenue.","D":"Introducing special promotions or seasonal menu items in Q4 to boost off-peak sales."},"correctOption":"D","correctAnswer":"Introducing special promotions or seasonal menu items in Q4 to boost off-peak sales.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because sales drop sharply to $15,000 in Q4, so targeted promotions or seasonal products can stimulate demand during the quiet quarter.","distractor_reasons":{"A":"Incorrect because cutting promotion in quiet quarters would worsen low sales.","B":"Incorrect because Q3 is the peak revenue quarter ($40,000).","C":"Incorrect because doubling prices during weak Q4 demand would drive away remaining customers.","D":"Option D is correct because sales drop sharply to $15,000 in Q4, so targeted promotions or seasonal products can stimulate demand during the quiet quarter."}}},{"id":"P1_U3_MCQ_798","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_798","question":"Why should a business combine both primary and secondary market research when planning a major product launch?","options":{"A":"Because combining them makes the research completely free of cost.","B":"Because secondary research provides broad market context cheaply while primary research answers specific current questions.","C":"Because primary research can only collect quantitative data and secondary research only qualitative data.","D":"Because government regulators reject business plans unless both methods are used."},"correctOption":"B","correctAnswer":"Because secondary research provides broad market context cheaply while primary research answers specific current questions.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because using both sources balances cost-effective industry background with tailored, up-to-date customer insights.","distractor_reasons":{"A":"Incorrect because primary research still incurs collection costs.","B":"Option B is correct because using both sources balances cost-effective industry background with tailored, up-to-date customer insights.","C":"Incorrect because both primary and secondary sources can provide quantitative and qualitative data.","D":"Incorrect because regulators do not mandate specific research methods for product launches."}}},{"id":"P1_U3_MCQ_799","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_799","question":"How can a business reduce interviewer bias during face-to-face market research?","options":{"A":"By allowing interviewers to reword questions however they like during each interview.","B":"By instructing interviewers to smile only when respondents praise the company.","C":"By training interviewers to read standardised, neutral questions in a consistent tone.","D":"By interviewing only employees who work in the company's marketing department."},"correctOption":"C","correctAnswer":"By training interviewers to read standardised, neutral questions in a consistent tone.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because standardised wording and neutral delivery prevent interviewers from steering respondents' answers.","distractor_reasons":{"A":"Incorrect because changing wording inconsistently introduces interviewer bias.","B":"Incorrect because reacting positively to praise encourages biased answers.","C":"Option C is correct because standardised wording and neutral delivery prevent interviewers from steering respondents' answers.","D":"Incorrect because internal marketing staff do not represent external consumers."}}},{"id":"P1_U3_MCQ_800","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_800","question":"What is a 'pilot survey' in primary market research?","options":{"A":"A survey conducted exclusively with airline pilots.","B":"The final nationwide census distributed to every household.","C":"A secondary report published by an aviation trade journal.","D":"A small-scale trial run of a questionnaire to test for unclear or biased questions before the full survey."},"correctOption":"D","correctAnswer":"A small-scale trial run of a questionnaire to test for unclear or biased questions before the full survey.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because testing a draft questionnaire on a small group identifies confusing wording or layout errors before spending money on a large survey.","distractor_reasons":{"A":"Incorrect because 'pilot' here means a preliminary trial, not aviation staff.","B":"Incorrect because a pilot survey occurs before the main survey.","C":"Incorrect because a pilot survey is a primary research preparation step.","D":"Option D is correct because testing a draft questionnaire on a small group identifies confusing wording or layout errors before spending money on a large survey."}}},{"id":"P1_U3_MCQ_801","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_801","question":"What is meant by a product's 'Unique Selling Point' (USP)?","options":{"A":"A special feature of a product that differentiates it from competitors and attracts buyers.","B":"The single retail shop where the product is legally allowed to be sold.","C":"The lowest possible price charged during a clearance sale.","D":"The total fixed cost required to set up a production line."},"correctOption":"A","correctAnswer":"A special feature of a product that differentiates it from competitors and attracts buyers.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because a USP is a distinct benefit, design, or innovation that makes a product stand out from rival offerings.","distractor_reasons":{"A":"Option A is correct because a USP is a distinct benefit, design, or innovation that makes a product stand out from rival offerings.","B":"Incorrect because distribution locations relate to Place, not USP.","C":"Incorrect because clearance discounts are temporary pricing tactics.","D":"Incorrect because set-up costs are financial/operations figures."}}},{"id":"P1_U3_MCQ_802","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_802","question":"How does a strong brand image increase a business's 'added value'?","options":{"A":"By automatically reducing the cost of raw materials to zero.","B":"By allowing the business to charge a higher selling price than unbranded equivalents with similar production costs.","C":"By eliminating the need to pay wages to production employees.","D":"By reducing the physical weight of the finished product."},"correctOption":"B","correctAnswer":"By allowing the business to charge a higher selling price than unbranded equivalents with similar production costs.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because added value is the difference between selling price and bought-in material costs; strong branding raises the price consumers are willing to pay.","distractor_reasons":{"A":"Incorrect because raw materials still cost money.","B":"Option B is correct because added value is the difference between selling price and bought-in material costs; strong branding raises the price consumers are willing to pay.","C":"Incorrect because production workers must still be paid.","D":"Incorrect because brand perception adds psychological/status value rather than changing weight."}}},{"id":"P1_U3_MCQ_803","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_803","question":"Why is eye-catching packaging particularly important for fast-moving consumer goods (FMCG) sold in supermarkets?","options":{"A":"Because supermarkets forbid brands from using any media advertising.","B":"Because packaging eliminates the need for barcode scanners at checkouts.","C":"Because shoppers make quick decisions on crowded shelves where attractive packaging helps the product stand out.","D":"Because packaging prevents products from ever reaching the decline stage."},"correctOption":"C","correctAnswer":"Because shoppers make quick decisions on crowded shelves where attractive packaging helps the product stand out.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because in self-service supermarkets, distinctive colours, shapes, and labels act as a 'silent salesman' among competing brands.","distractor_reasons":{"A":"Incorrect because FMCG brands advertise heavily on TV and social media.","B":"Incorrect because packaging actually carries the printed barcode for scanning.","C":"Option C is correct because in self-service supermarkets, distinctive colours, shapes, and labels act as a 'silent salesman' among competing brands.","D":"Incorrect because good packaging supports sales but cannot permanently prevent product decline."}}},{"id":"P1_U3_MCQ_804","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_804","question":"How are environmental concerns influencing modern product packaging decisions?","options":{"A":"Businesses are using thicker layers of single-use non-recyclable plastic.","B":"Consumers prefer products packaged in toxic materials that cannot be reused.","C":"Governments have banned all cardboard and glass containers.","D":"Businesses are switching to recyclable, biodegradable, and minimal packaging to satisfy eco-conscious buyers and laws."},"correctOption":"D","correctAnswer":"Businesses are switching to recyclable, biodegradable, and minimal packaging to satisfy eco-conscious buyers and laws.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because rising consumer awareness and environmental regulations push firms to reduce plastic waste and use sustainable packaging.","distractor_reasons":{"A":"Incorrect because excessive single-use plastic harms brand image and faces legal restrictions.","B":"Incorrect because modern consumers increasingly penalise wasteful or toxic packaging.","C":"Incorrect because cardboard and glass are widely encouraged as recyclable materials.","D":"Option D is correct because rising consumer awareness and environmental regulations push firms to reduce plastic waste and use sustainable packaging."}}},{"id":"P1_U3_MCQ_805","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_805","question":"What happens during the 'development' stage before a product is introduced to the market?","options":{"A":"Prototypes are designed and tested, incurring high R&D costs with zero sales revenue.","B":"Sales reach their maximum peak and competition is at its fiercest.","C":"The product is withdrawn from retail stores due to falling demand.","D":"The business earns its highest net profit margin of the entire life cycle."},"correctOption":"A","correctAnswer":"Prototypes are designed and tested, incurring high R&D costs with zero sales revenue.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because during research and development, money is spent building and testing prototypes before any units are sold.","distractor_reasons":{"A":"Option A is correct because during research and development, money is spent building and testing prototypes before any units are sold.","B":"Incorrect because peak sales occur during the maturity stage.","C":"Incorrect because withdrawal occurs at the end of the decline stage.","D":"Incorrect because development generates cash outflows and losses rather than profits."}}},{"id":"P1_U3_MCQ_806","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_806","question":"How do pricing decisions typically change as a product moves from the introduction stage to the maturity stage?","options":{"A":"Prices always start at zero in introduction and rise by 500% in maturity.","B":"Initial skimming or penetration prices often shift toward competitive pricing as rivals enter the market.","C":"Businesses stop charging prices in maturity and rely solely on government subsidies.","D":"Pricing never changes across any stage of the Product Life Cycle."},"correctOption":"B","correctAnswer":"Initial skimming or penetration prices often shift toward competitive pricing as rivals enter the market.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because early launch pricing (skimming high or penetrating low) usually evolves into competitive pricing once rivals launch similar products in maturity.","distractor_reasons":{"A":"Incorrect because products are not launched for free nor raised fivefold in maturity.","B":"Option B is correct because early launch pricing (skimming high or penetrating low) usually evolves into competitive pricing once rivals launch similar products in maturity.","C":"Incorrect because private businesses rely on sales revenue rather than government subsidies.","D":"Incorrect because pricing must adapt to changing competition and demand across the life cycle."}}},{"id":"P1_U3_MCQ_807","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_807","question":"How do promotional aims change between the introduction stage and the maturity stage of the Product Life Cycle?","options":{"A":"Introduction uses persuasive promotion to defend market share, while maturity uses informative promotion.","B":"No promotion is used during introduction, whereas massive launch advertising begins in decline.","C":"Introduction focuses on informative promotion to build awareness, while maturity uses persuasive promotion to maintain brand loyalty.","D":"Both stages use identical promotional budgets and messages."},"correctOption":"C","correctAnswer":"Introduction focuses on informative promotion to build awareness, while maturity uses persuasive promotion to maintain brand loyalty.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because buyers first need information about what a new product does, whereas in maturity promotion must persuade buyers to choose the brand over rivals.","distractor_reasons":{"A":"Incorrect because this reverses the roles of informative and persuasive promotion.","B":"Incorrect because heavy promotion is vital at introduction and usually reduced in decline.","C":"Option C is correct because buyers first need information about what a new product does, whereas in maturity promotion must persuade buyers to choose the brand over rivals.","D":"Incorrect because promotional objectives and spending change across life-cycle stages."}}},{"id":"P1_U3_MCQ_808","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_808","question":"Which marketing decision is most appropriate when a product reaches the 'decline' stage and extension strategies are no longer cost-effective?","options":{"A":"Invest millions of dollars in building a brand-new factory for the product.","B":"Double the selling price while launching an expensive global TV campaign.","C":"Hire hundreds of extra full-time production workers.","D":"Reduce promotional spending, lower prices to clear remaining stock, and plan to withdraw the product."},"correctOption":"D","correctAnswer":"Reduce promotional spending, lower prices to clear remaining stock, and plan to withdraw the product.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because once a product is permanently declining, cutting advertising expenses and discounting remaining inventory avoids further losses before discontinuation.","distractor_reasons":{"A":"Incorrect because investing in new factories for a dying product wastes capital.","B":"Incorrect because raising prices and spending heavily on TV ads will generate large losses in decline.","C":"Incorrect because falling output requires fewer workers, not more.","D":"Option D is correct because once a product is permanently declining, cutting advertising expenses and discounting remaining inventory avoids further losses before discontinuation."}}},{"id":"P1_U3_MCQ_809","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_809","question":"Which of the following is an example of an extension strategy?","options":{"A":"Finding new uses for an existing product, such as promoting baking soda as a fridge deodoriser.","B":"Halting production immediately as soon as sales growth begins to slow.","C":"Increasing unit production costs by using slower machinery.","D":"Removing the product from all online stores."},"correctOption":"A","correctAnswer":"Finding new uses for an existing product, such as promoting baking soda as a fridge deodoriser.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because encouraging consumers to use a mature product in new ways creates fresh demand and extends its life cycle.","distractor_reasons":{"A":"Option A is correct because encouraging consumers to use a mature product in new ways creates fresh demand and extends its life cycle.","B":"Incorrect because slowing growth signals maturity, which is typically the most profitable stage.","C":"Incorrect because raising production costs reduces profitability rather than extending sales.","D":"Incorrect because restricting distribution reduces sales volume."}}},{"id":"P1_U3_MCQ_810","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_810","question":"A shoe manufacturer produces 10,000 pairs of trainers at a total cost of $200,000. It applies a 40% cost-plus mark-up. What is the selling price per pair?","options":{"A":"$20","B":"$28","C":"$32","D":"$40"},"correctOption":"B","correctAnswer":"$28","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because unit cost is $200,000 / 10,000 = $20, and adding a 40% mark-up ($20 x 0.40 = $8) gives a selling price of $28.","distractor_reasons":{"A":"Incorrect because $20 is the unit cost before adding the 40% mark-up.","B":"Option B is correct because unit cost is $200,000 / 10,000 = $20, and adding a 40% mark-up ($20 x 0.40 = $8) gives a selling price of $28.","C":"Incorrect because $32 represents a 60% mark-up rather than 40%.","D":"Incorrect because $40 represents a 100% mark-up."}}},{"id":"P1_U3_MCQ_811","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_811","question":"What is meant by 'promotional pricing'?","options":{"A":"Setting a permanent high price to reflect superior luxury quality.","B":"Adjusting prices every hour using real-time demand software.","C":"Temporarily lowering the price of a product for a short period to boost sales or clear excess stock.","D":"Calculating average unit cost and adding a fixed 25% profit margin."},"correctOption":"C","correctAnswer":"Temporarily lowering the price of a product for a short period to boost sales or clear excess stock.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because promotional pricing reduces prices for a limited time (such as seasonal sales or 'buy one get one free' deals) to attract shoppers.","distractor_reasons":{"A":"Incorrect because a high prestige price describes price skimming or premium pricing.","B":"Incorrect because hourly algorithm adjustments define dynamic pricing.","C":"Option C is correct because promotional pricing reduces prices for a limited time (such as seasonal sales or 'buy one get one free' deals) to attract shoppers.","D":"Incorrect because adding a fixed percentage to unit cost defines cost-plus pricing."}}},{"id":"P1_U3_MCQ_812","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_812","question":"What is a potential disadvantage of using promotional pricing too frequently?","options":{"A":"It guarantees that competitors will raise their prices.","B":"It eliminates all variable costs of manufacturing.","C":"It prevents customers from noticing the product in retail stores.","D":"It lowers profit per unit and can damage the brand's quality image if buyers expect constant discounts."},"correctOption":"D","correctAnswer":"It lowers profit per unit and can damage the brand's quality image if buyers expect constant discounts.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because frequent price cuts shrink profit margins and train customers to delay buying until the next sale.","distractor_reasons":{"A":"Incorrect because frequent discounts often trigger competitors to cut prices too.","B":"Incorrect because variable production costs remain unchanged.","C":"Incorrect because price promotions usually increase shopper attention.","D":"Option D is correct because frequent price cuts shrink profit margins and train customers to delay buying until the next sale."}}},{"id":"P1_U3_MCQ_813","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_813","question":"A technology company has spent $15 million developing a revolutionary foldable tablet with no direct competitors yet. Which pricing method should it choose at launch?","options":{"A":"Price skimming.","B":"Penetration pricing.","C":"Promotional clearance pricing.","D":"Below-cost pricing."},"correctOption":"A","correctAnswer":"Price skimming.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because price skimming sets a high initial price for an innovative, unique product to quickly recover high R&D costs from early adopters.","distractor_reasons":{"A":"Option A is correct because price skimming sets a high initial price for an innovative, unique product to quickly recover high R&D costs from early adopters.","B":"Incorrect because penetration pricing sets a low price, which would take far too long to recover $15 million in R&D.","C":"Incorrect because clearance pricing is used to get rid of old, unwanted stock.","D":"Incorrect because selling below cost would generate immediate losses."}}},{"id":"P1_U3_MCQ_814","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_814","question":"A new soft drinks brand is entering a crowded market dominated by established rivals selling similar cans at $1.00. Which pricing method is most suitable to gain rapid market share?","options":{"A":"Price skimming at $3.50 per can.","B":"Penetration pricing at $0.75 per can.","C":"Cost-plus pricing with a 200% mark-up.","D":"Dynamic surge pricing every ten minutes."},"correctOption":"B","correctAnswer":"Penetration pricing at $0.75 per can.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because penetration pricing sets an attractive introductory price below the $1.00 market norm to persuade consumers to switch and try the new drink.","distractor_reasons":{"A":"Incorrect because charging $3.50 for a standard soft drink in a crowded market will result in almost zero sales.","B":"Option B is correct because penetration pricing sets an attractive introductory price below the $1.00 market norm to persuade consumers to switch and try the new drink.","C":"Incorrect because a 200% mark-up would make the price uncompetitive against established rivals.","D":"Incorrect because frequent price surges are unsuitable for everyday supermarket cans."}}},{"id":"P1_U3_MCQ_815","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_815","question":"What is a potential disadvantage of dynamic pricing for a business?","options":{"A":"Prices can never be increased during busy peak periods.","B":"It requires no computers or internet connectivity.","C":"Customers may feel treated unfairly if they discover they paid much more than another buyer for the same seat or item.","D":"It forces the business to keep prices fixed for an entire year."},"correctOption":"C","correctAnswer":"Customers may feel treated unfairly if they discover they paid much more than another buyer for the same seat or item.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because sharp price spikes during high demand can irritate customers and damage brand trust.","distractor_reasons":{"A":"Incorrect because raising prices during peak demand is a primary feature of dynamic pricing.","B":"Incorrect because dynamic pricing relies on computer algorithms and real-time data.","C":"Option C is correct because sharp price spikes during high demand can irritate customers and damage brand trust.","D":"Incorrect because dynamic prices change continuously rather than staying fixed."}}},{"id":"P1_U3_MCQ_816","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_816","question":"To clear older stock before a new collection arrives, Willow's Clothing advertises '30% off everything this week only'. Which pricing strategy is Willow's using?","options":{"A":"Cost-plus pricing - setting price from cost plus a mark-up","B":"Promotional pricing - a temporary price cut to stimulate sales","C":"Competitive pricing - matching competitors' current prices","D":"Premium pricing - charging a high price to signal quality"},"correctOption":"B","correctAnswer":"Promotional pricing - a temporary price cut to stimulate sales","questionType":"MCQ","explanation":{"correct_reason":"Promotional pricing involves a temporary reduction in price to encourage purchases, here used to clear old stock quickly.","distractor_reasons":{"A":"Wrong: cost-plus pricing builds the price from costs and a mark-up, not from a short-term discount.","B":"Correct: the 'this week only' discount is a temporary price promotion.","C":"Wrong: competitive pricing matches what other firms charge rather than running a limited-time sale.","D":"Wrong: premium pricing charges high prices to suggest quality, the opposite of a discount."}}},{"id":"P1_U3_MCQ_817","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_817","question":"Sunrise Drinks gives its lemonade a new name, a distinctive logo and a specially shaped bottle so shoppers recognise it on the shelf. Which element of the marketing mix does this mainly strengthen?","options":{"A":"Product - branding and packaging give the drink a distinct identity","B":"Price - the amount customers pay for the lemonade","C":"Place - the shops and channels where the drink is sold","D":"Promotion - the advertising used to publicise the drink"},"correctOption":"A","correctAnswer":"Product - branding and packaging give the drink a distinct identity","questionType":"MCQ","explanation":{"correct_reason":"Brand names, logos and packaging are part of the product element of the marketing mix, helping differentiate it from rivals.","distractor_reasons":{"A":"Correct: the name, logo and bottle are branding and packaging decisions within the product.","B":"Wrong: no decision about the amount charged to customers is being described.","C":"Wrong: place concerns distribution channels and where the product is available, not its design.","D":"Wrong: promotion is communication such as advertising, not the product's name or bottle."}}},{"id":"P1_U3_MCQ_818","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_818","question":"A bakery wants to reach customers across the country, so it contracts to supply its bread to a national chain of supermarkets instead of selling only from its own shop. Which part of the marketing mix has changed?","options":{"A":"Product - the recipe and packaging of the bread","B":"Price - the amount charged to customers","C":"Place - the channels used to distribute the bread","D":"Promotion - the way the bakery advertises its bread"},"correctOption":"C","correctAnswer":"Place - the channels used to distribute the bread","questionType":"MCQ","explanation":{"correct_reason":"Place covers how a product reaches customers, and the bakery has changed its distribution channel by using supermarkets.","distractor_reasons":{"A":"Wrong: the bread's recipe and packaging have not changed, only how it is sold.","B":"Wrong: there is no mention of altering the price charged to customers.","C":"Correct: supplying through supermarkets is a change to the distribution channels used.","D":"Wrong: advertising methods are promotion, not the route to market described here."}}},{"id":"P1_U3_MCQ_819","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_819","question":"Harrow Bikes works out the total cost of producing a bicycle and then adds a fixed percentage to cover profit. Which pricing method is the business using?","options":{"A":"Competitive pricing","B":"Cost-plus pricing","C":"Promotional pricing","D":"Loss leader pricing"},"correctOption":"B","correctAnswer":"Cost-plus pricing","questionType":"MCQ","explanation":{"correct_reason":"Cost-plus pricing sets the selling price by adding a percentage profit margin to the cost of producing the product, which is exactly what Harrow Bikes does.","distractor_reasons":{"A":"Competitive pricing sets a price by referring to what rivals charge, not by adding a margin to production costs.","B":"Correct - Harrow Bikes adds a fixed percentage to its costs, which is cost-plus pricing.","C":"Promotional pricing is a temporary price cut to stimulate sales, not building a margin onto costs.","D":"Loss leader pricing sells a product below cost to attract customers, not adding a profit margin to costs."}}},{"id":"P1_U3_MCQ_820","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_820","question":"To clear old stock before a new model arrives, Vale Electronics cuts the price of its televisions for a two-week flash sale. Which pricing method is this?","options":{"A":"Cost-plus pricing","B":"Competitive pricing","C":"Promotional pricing","D":"Price skimming"},"correctOption":"C","correctAnswer":"Promotional pricing","questionType":"MCQ","explanation":{"correct_reason":"Promotional pricing involves temporarily lowering a price to encourage sales, here to clear old stock before the new model arrives.","distractor_reasons":{"A":"Cost-plus pricing builds a price from production costs plus a margin; it is not a temporary sale.","B":"Competitive pricing matches or undercuts rivals' regular prices rather than running a short-term sale.","C":"Correct - a short, temporary price cut to clear stock is promotional pricing.","D":"Price skimming sets a high initial price for a new product before lowering it over time, not a two-week sale."}}},{"id":"P1_U3_MCQ_821","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_821","question":"Ridgeway Coffee describes its beans as single-origin and small-batch roasted to stand out from supermarket brands. What is the main purpose of such a Unique Selling Point (USP)?","options":{"A":"To differentiate the product from competitors","B":"To make the product the cheapest available","C":"To lower the business's production costs","D":"To remove the need for any advertising"},"correctOption":"A","correctAnswer":"To differentiate the product from competitors","questionType":"MCQ","explanation":{"correct_reason":"A USP highlights a feature that makes a product distinct from rivals, helping to attract customers and build brand loyalty.","distractor_reasons":{"A":"Correct - a USP sets the product apart from competitors, which is its main purpose.","B":"A USP is about distinctiveness, not necessarily being the cheapest; many USPs support higher prices.","C":"A USP is a marketing claim and does not by itself reduce production costs.","D":"A USP supports promotion rather than removing the need for it; customers must still be told about it."}}},{"id":"P1_U3_MCQ_822","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_822","question":"Greenline Coaches operates on a route with three rival bus firms. It checks their fares each week and sets its own ticket price at a similar level. Which pricing method is Greenline using?","options":{"A":"Cost-plus pricing","B":"Competitive pricing","C":"Promotional pricing","D":"Loss leader pricing"},"correctOption":"B","correctAnswer":"Competitive pricing","questionType":"MCQ","explanation":{"correct_reason":"Competitive pricing means setting a price by referring to what rival businesses charge, as Greenline does by matching competitors' fares.","distractor_reasons":{"A":"Cost-plus pricing uses the firm's own costs plus a margin, not competitors' fares.","B":"Correct - Greenline bases its fare on the prices charged by rival firms.","C":"Promotional pricing is a temporary cut to boost sales, not regularly matching rivals' fares.","D":"Loss leader pricing means selling below cost to attract customers, not matching competitors' prices."}}},{"id":"P1_U3_MCQ_823","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_823","question":"What is 'loss-leader pricing' in retail?","options":{"A":"Pricing every item in a store below manufacturing cost permanently.","B":"Setting a high price for a brand-new gadget at launch.","C":"Selling a popular product at or below cost to attract shoppers into the store to buy other profitable items.","D":"Adding a 10% mark-up onto the wholesale cost of every product."},"correctOption":"C","correctAnswer":"Selling a popular product at or below cost to attract shoppers into the store to buy other profitable items.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because supermarkets often discount staple items (like milk or bread) heavily to draw footfall, earning overall profit from the rest of the shopper's trolley.","distractor_reasons":{"A":"Incorrect because discounting every item below cost would bankrupt the retailer.","B":"Incorrect because a high launch price defines price skimming.","C":"Option C is correct because supermarkets often discount staple items (like milk or bread) heavily to draw footfall, earning overall profit from the rest of the shopper's trolley.","D":"Incorrect because adding a fixed mark-up defines cost-plus pricing."}}},{"id":"P1_U3_MCQ_824","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_824","question":"A breakfast cereal brand is in the maturity stage with steady but slow-growing sales. What is the most likely reason its maker invests in new product development?","options":{"A":"Because the brand now has no competitors","B":"Because maturity guarantees ever-increasing revenue","C":"To remove the need for any advertising","D":"To replace slowing sales and sustain long-term growth"},"correctOption":"D","correctAnswer":"To replace slowing sales and sustain long-term growth","questionType":"MCQ","explanation":{"correct_reason":"With sales growth slowing at maturity, developing new products helps the business replace stagnant lines and maintain growth.","distractor_reasons":{"B":"Maturity brings slow growth and strong competition, not guaranteed ever-increasing revenue.","C":"New product development does not remove the need to advertise; the brand still competes for customers.","D":"With sales growth slowing at maturity, developing new products helps the business replace stagnant lines and maintain growth.","A":"A mature brand usually faces many competitors, which is why growth has slowed in the first place."}}},{"id":"P1_U3_MCQ_825","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_825","question":"Why might a small business struggle to develop innovative new products compared to a large multinational corporation?","options":{"A":"Consumers refuse to buy new products from small local firms.","B":"Small businesses are legally prohibited from inventing new products.","C":"Small businesses have too many employees in their R&D departments.","D":"Limited financial capital to pay for expensive research, prototype testing, and patent protection."},"correctOption":"D","correctAnswer":"Limited financial capital to pay for expensive research, prototype testing, and patent protection.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because R&D is costly and risky, and small firms often lack the retained profits or borrowing power to fund lengthy development.","distractor_reasons":{"A":"Incorrect because consumers regularly buy innovative products from small enterprises.","B":"Incorrect because small businesses are free to innovate and frequently create niche inventions.","C":"Incorrect because small businesses usually have very few or no dedicated R&D staff.","D":"Option D is correct because R&D is costly and risky, and small firms often lack the retained profits or borrowing power to fund lengthy development."}}},{"id":"P1_U3_MCQ_826","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_826","question":"Which distribution channel is most appropriate for a baker making fresh wedding cakes to order?","options":{"A":"Producer -> Wholesaler -> Retailer -> Consumer.","B":"Producer -> Direct to Consumer.","C":"Producer -> Overseas Agent -> Wholesaler -> Consumer.","D":"Producer -> National Supermarket Warehouse -> Consumer."},"correctOption":"B","correctAnswer":"Producer -> Direct to Consumer.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because custom wedding cakes are perishable, bespoke items made to individual customer specifications, requiring direct contact and fast delivery.","distractor_reasons":{"A":"Incorrect because passing through wholesalers and retailers takes too long for fresh bespoke cakes.","B":"Option B is correct because custom wedding cakes are perishable, bespoke items made to individual customer specifications, requiring direct contact and fast delivery.","C":"Incorrect because overseas agents are for exporting mass goods, not local custom cakes.","D":"Incorrect because supermarket warehouses handle standardised packaged goods rather than bespoke wedding cakes."}}},{"id":"P1_U3_MCQ_827","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_827","question":"Which distribution channel is typically best for a manufacturer of canned soup selling to thousands of small corner shops across a country?","options":{"A":"Producer -> Direct door-to-door delivery to every individual shopper.","B":"Producer -> Overseas export agent -> Consumer.","C":"Producer -> Wholesaler -> Retailer -> Consumer.","D":"Producer -> Custom job-order showroom -> Consumer."},"correctOption":"C","correctAnswer":"Producer -> Wholesaler -> Retailer -> Consumer.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because canned soup has a long shelf life and is bought in small cases by thousands of independent shops, making wholesalers ideal for breaking bulk.","distractor_reasons":{"A":"Incorrect because delivering single cans of soup directly to millions of homes is far too expensive.","B":"Incorrect because export agents are used for foreign markets rather than domestic corner shops.","C":"Option C is correct because canned soup has a long shelf life and is bought in small cases by thousands of independent shops, making wholesalers ideal for breaking bulk.","D":"Incorrect because canned soup is a mass-market FMCG item rather than a bespoke showroom product."}}},{"id":"P1_U3_MCQ_828","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_828","question":"Why do large supermarket chains usually buy groceries directly from food manufacturers rather than through wholesalers?","options":{"A":"Wholesalers are legally banned from selling food products.","B":"Supermarkets only sell one brand of each grocery item.","C":"Food manufacturers refuse to offer discounts on large bulk orders.","D":"Supermarkets buy in huge bulk quantities themselves and avoid paying a wholesaler's profit margin."},"correctOption":"D","correctAnswer":"Supermarkets buy in huge bulk quantities themselves and avoid paying a wholesaler's profit margin.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because major supermarket chains have their own regional distribution warehouses and purchase in massive volumes directly from producers.","distractor_reasons":{"A":"Incorrect because wholesalers regularly supply smaller independent grocers.","B":"Incorrect because supermarkets stock wide ranges of competing brands.","C":"Incorrect because manufacturers offer substantial bulk discounts to major supermarket chains.","D":"Option D is correct because major supermarket chains have their own regional distribution warehouses and purchase in massive volumes directly from producers."}}},{"id":"P1_U3_MCQ_829","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_829","question":"Which factor is most important when choosing a distribution channel for fresh fish or cut flowers?","options":{"A":"Using as many wholesalers and storage warehouses as possible.","B":"Speed and shortness of the channel so the perishable product reaches buyers before spoiling.","C":"Selling exclusively through mail-order catalogues taking three weeks to deliver.","D":"Choosing the slowest sea-freight route to minimise fuel usage."},"correctOption":"B","correctAnswer":"Speed and shortness of the channel so the perishable product reaches buyers before spoiling.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because perishable goods deteriorate quickly, requiring direct or short channels with rapid refrigerated transport.","distractor_reasons":{"A":"Incorrect because multiple intermediaries delay delivery and increase spoilage.","B":"Option B is correct because perishable goods deteriorate quickly, requiring direct or short channels with rapid refrigerated transport.","C":"Incorrect because three-week mail delivery would ruin fresh fish or flowers.","D":"Incorrect because slow transport is unsuitable for perishable items."}}},{"id":"P1_U3_MCQ_830","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_830","question":"Why are complex technical products (such as industrial turbines or medical scanners) normally sold directly from the producer to the business customer?","options":{"A":"Because supermarkets refuse to stock medical scanners on their shelves.","B":"Because specialist technical advice, custom installation, and after-sales maintenance are required.","C":"Because wholesalers buy industrial turbines in packs of 10,000 units.","D":"Because technical products never require any customer support."},"correctOption":"B","correctAnswer":"Because specialist technical advice, custom installation, and after-sales maintenance are required.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because high-value technical equipment requires direct engineering consultation, tailored specifications, and ongoing servicing from the manufacturer.","distractor_reasons":{"A":"Incorrect because supermarkets are consumer retailers, not B2B engineering suppliers.","B":"Option B is correct because high-value technical equipment requires direct engineering consultation, tailored specifications, and ongoing servicing from the manufacturer.","C":"Incorrect because heavy industrial machinery is ordered individually or in small numbers, not bulk-broken by wholesalers.","D":"Incorrect because complex equipment requires extensive training and after-sales support."}}},{"id":"P1_U3_MCQ_831","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_831","question":"A new phone is launched with adverts that explain its battery life and screen size in detail and make no emotional claims. Which type of advertising is this?","options":{"A":"Sponsorship of a sports event","B":"Persuasive advertising, which builds an emotional appeal","C":"Informative advertising, which gives factual product details","D":"Sales promotion using money-off coupons"},"correctOption":"C","correctAnswer":"Informative advertising, which gives factual product details","questionType":"MCQ","explanation":{"correct_reason":"Advertising that presents factual information such as specifications to help customers decide is informative advertising.","distractor_reasons":{"B":"Persuasive advertising tries to create desire or emotional attachment rather than simply stating verifiable facts.","C":"Advertising that presents factual information such as specifications to help customers decide is informative advertising.","D":"Sales promotion with coupons is a short-term incentive to buy, not an informational advert about specifications.","A":"Sponsorship involves funding an event or organisation in return for publicity, not describing product features."}}},{"id":"P1_U3_MCQ_832","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_832","question":"When is 'informative advertising' most useful for a business?","options":{"A":"When withdrawing an obsolete product from the market.","B":"When cutting production staff during a factory closure.","C":"When selling an identical commodity that every consumer already understands completely.","D":"When launching a brand-new invention whose features and uses consumers do not yet know."},"correctOption":"D","correctAnswer":"When launching a brand-new invention whose features and uses consumers do not yet know.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because consumers will not buy an unfamiliar new product unless advertising clearly explains what it does and how it benefits them.","distractor_reasons":{"A":"Incorrect because promotional spending is cut when withdrawing a declining product.","B":"Incorrect because internal staffing reductions are not promoted via consumer advertising.","C":"Incorrect because familiar everyday goods rely more on persuasive branding than basic explanation.","D":"Option D is correct because consumers will not buy an unfamiliar new product unless advertising clearly explains what it does and how it benefits them."}}},{"id":"P1_U3_MCQ_833","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_833","question":"What is a major advantage of television advertising for a large national brand?","options":{"A":"It targets only one specific street within a small village.","B":"It is the cheapest advertising medium available for small local corner shops.","C":"Viewers are legally prevented from changing channels during commercial breaks.","D":"It reaches millions of viewers simultaneously and combines sight, sound, and movement to create strong brand impact."},"correctOption":"D","correctAnswer":"It reaches millions of viewers simultaneously and combines sight, sound, and movement to create strong brand impact.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because TV reaches huge mass-market audiences and uses audio-visual storytelling to build high brand awareness.","distractor_reasons":{"A":"Incorrect because TV broadcasts regionally or nationally rather than to a single street.","B":"Incorrect because TV production and airtime are extremely expensive, making it unsuitable for small local shops.","C":"Incorrect because viewers frequently skip ads, switch channels, or use ad-free streaming.","D":"Option D is correct because TV reaches huge mass-market audiences and uses audio-visual storytelling to build high brand awareness."}}},{"id":"P1_U3_MCQ_834","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_834","question":"What is a key disadvantage of advertising in national newspapers or magazines?","options":{"A":"Readers cannot view the advert for more than three seconds.","B":"Print readership has declined as consumers shift online, and static pages lack sound or video.","C":"It is impossible to include detailed product specifications or coupons.","D":"Specialist magazines cannot target specific hobbyist audiences."},"correctOption":"B","correctAnswer":"Print readership has declined as consumers shift online, and static pages lack sound or video.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because falling print circulation reduces reach among younger audiences, and static print is less dynamic than video.","distractor_reasons":{"A":"Incorrect because readers can study a print advert for as long as they wish.","B":"Option B is correct because falling print circulation reduces reach among younger audiences, and static print is less dynamic than video.","C":"Incorrect because print ads are very good for detailed text and cut-out vouchers.","D":"Incorrect because specialist magazines actually target hobbyists very effectively."}}},{"id":"P1_U3_MCQ_835","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_835","question":"What is meant by 'point-of-sale displays' as a method of sales promotion?","options":{"A":"Television commercials aired late at night after shops close.","B":"Emails sent to customers six months after they bought an item.","C":"Eye-catching stands, signs, or product arrangements placed near supermarket checkouts or aisle ends to trigger impulse buys.","D":"Posters displayed inside a factory warehouse for delivery truck drivers."},"correctOption":"C","correctAnswer":"Eye-catching stands, signs, or product arrangements placed near supermarket checkouts or aisle ends to trigger impulse buys.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because point-of-sale (POS) displays catch shoppers' attention at the exact moment and place where purchasing decisions happen.","distractor_reasons":{"A":"Incorrect because TV commercials are media advertising, not in-store displays.","B":"Incorrect because follow-up emails are direct digital marketing.","C":"Option C is correct because point-of-sale (POS) displays catch shoppers' attention at the exact moment and place where purchasing decisions happen.","D":"Incorrect because warehouse signs for staff are internal operational notices."}}},{"id":"P1_U3_MCQ_836","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_836","question":"Why do food and cosmetics companies distribute 'free samples' as a sales promotion technique?","options":{"A":"Because the products failed safety inspections and cannot be sold.","B":"To eliminate the need to pay any retail distribution margins.","C":"To reduce the total weight of inventory stored in warehouses.","D":"To remove consumer risk by letting shoppers try the product first, encouraging future full-size purchases."},"correctOption":"D","correctAnswer":"To remove consumer risk by letting shoppers try the product first, encouraging future full-size purchases.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because consumers often hesitate to buy an unfamiliar food or skincare item; trying a free sample builds confidence and stimulates repeat sales.","distractor_reasons":{"A":"Incorrect because free samples must meet all legal health and safety standards.","B":"Incorrect because samples are often distributed through retailers.","C":"Incorrect because sample sizes are produced specifically for promotion, adding packaging costs.","D":"Option D is correct because consumers often hesitate to buy an unfamiliar food or skincare item; trying a free sample builds confidence and stimulates repeat sales."}}},{"id":"P1_U3_MCQ_837","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_837","question":"How does a 'Buy One, Get One Free' (BOGOF) promotion benefit a business?","options":{"A":"It quickly increases sales volume and clears excess stock while maintaining the product's standard unit price perception.","B":"It doubles the profit margin earned on every single unit given away.","C":"It guarantees that competitors will stop advertising their products.","D":"It eliminates all manufacturing costs for the second free item."},"correctOption":"A","correctAnswer":"It quickly increases sales volume and clears excess stock while maintaining the product's standard unit price perception.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because BOGOF encourages shoppers to buy larger quantities immediately without formally cutting the item's shelf price.","distractor_reasons":{"A":"Option A is correct because BOGOF encourages shoppers to buy larger quantities immediately without formally cutting the item's shelf price.","B":"Incorrect because giving away a second item halves the average revenue per unit.","C":"Incorrect because rivals often respond with their own promotions.","D":"Incorrect because the business still pays the variable cost of producing both units."}}},{"id":"P1_U3_MCQ_838","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_838","question":"What is the role of 'sponsorship' in a business's promotional mix?","options":{"A":"Paying factory workers overtime to increase weekend output.","B":"Paying to have the company's name or logo associated with a sports team, event, or television programme to boost brand awareness.","C":"Buying shares in a rival company to take over its board of directors.","D":"Offering a 50% cash discount to customers who pay invoices early."},"correctOption":"B","correctAnswer":"Paying to have the company's name or logo associated with a sports team, event, or television programme to boost brand awareness.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because sponsorship links the brand with popular events or teams watched by the target audience, generating wide publicity.","distractor_reasons":{"A":"Incorrect because overtime pay is an operations/HRM wage cost.","B":"Option B is correct because sponsorship links the brand with popular events or teams watched by the target audience, generating wide publicity.","C":"Incorrect because buying shares in a rival is a takeover/investment action.","D":"Incorrect because early-payment discounts are trade credit terms."}}},{"id":"P1_U3_MCQ_839","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_839","question":"What is a risk of using sports or celebrity sponsorship as a promotional tool?","options":{"A":"Sponsorship is completely free and therefore ignored by media outlets.","B":"It is illegal for private companies to sponsor sporting events.","C":"If the sponsored athlete or event suffers a scandal, negative publicity can damage the sponsor's brand image.","D":"Logos cannot be displayed on sportswear or stadium banners."},"correctOption":"C","correctAnswer":"If the sponsored athlete or event suffers a scandal, negative publicity can damage the sponsor's brand image.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because associating a brand closely with an individual or team exposes the business to reputational harm if misconduct occurs.","distractor_reasons":{"A":"Incorrect because major sponsorships are very expensive.","B":"Incorrect because commercial sponsorship is widespread and legal (aside from restricted products like tobacco).","C":"Option C is correct because associating a brand closely with an individual or team exposes the business to reputational harm if misconduct occurs.","D":"Incorrect because displaying logos on kits and banners is standard in sponsorship."}}},{"id":"P1_U3_MCQ_840","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_840","question":"What is meant by 'Public Relations' (PR) in promotion?","options":{"A":"Buying paid 30-second commercial slots during prime-time television.","B":"Distributing discount coupons at supermarket entrances.","C":"Conducting door-to-door market research interviews.","D":"Activities aimed at gaining favourable media coverage and building a positive public image, such as press releases and charity work."},"correctOption":"D","correctAnswer":"Activities aimed at gaining favourable media coverage and building a positive public image, such as press releases and charity work.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because PR focuses on maintaining good public goodwill and earning unpaid news coverage rather than buying direct advertising space.","distractor_reasons":{"A":"Incorrect because buying TV slots is paid advertising.","B":"Incorrect because coupons are sales promotions.","C":"Incorrect because door-to-door interviews are market research.","D":"Option D is correct because PR focuses on maintaining good public goodwill and earning unpaid news coverage rather than buying direct advertising space."}}},{"id":"P1_U3_MCQ_841","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_841","question":"Why is 'cost-effectiveness' important when a business decides how to spend its marketing budget on promotion?","options":{"A":"Because cheap promotion always produces higher sales than expensive promotion.","B":"Because businesses should always choose the most expensive advertising medium regardless of audience.","C":"Because laws cap promotional spending at 1% of annual revenue.","D":"Because promotion should generate extra sales revenue and profit that exceed the cost of the campaign."},"correctOption":"D","correctAnswer":"Because promotion should generate extra sales revenue and profit that exceed the cost of the campaign.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because marketing budgets are limited, so managers must evaluate the return on investment (extra sales per dollar spent) of each promotional method.","distractor_reasons":{"A":"Incorrect because very cheap methods (like flyers) may yield low response rates compared to better-targeted options.","B":"Incorrect because expensive media waste money if the target segment does not watch or read them.","C":"Incorrect because there is no universal legal cap of 1% on promotion.","D":"Option D is correct because marketing budgets are limited, so managers must evaluate the return on investment (extra sales per dollar spent) of each promotional method."}}},{"id":"P1_U3_MCQ_842","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_842","question":"How has the use of social media networks changed promotion for small businesses?","options":{"A":"Small businesses are now banned from promoting locally without a national TV budget.","B":"Small businesses can interact directly with customers, share viral content, and target ads on a modest budget.","C":"Social media eliminates the need to respond to negative customer reviews.","D":"Social media promotion guarantees that every post reaches 100% of the world's population."},"correctOption":"B","correctAnswer":"Small businesses can interact directly with customers, share viral content, and target ads on a modest budget.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because social media lowers barriers to promotion, allowing smaller firms to build communities and run targeted ads affordably.","distractor_reasons":{"A":"Incorrect because small businesses can advertise on social media without a TV budget.","B":"Option B is correct because social media lowers barriers to promotion, allowing smaller firms to build communities and run targeted ads affordably.","C":"Incorrect because public negative comments on social media require prompt management to protect reputation.","D":"Incorrect because algorithms limit organic reach to a fraction of users."}}},{"id":"P1_U3_MCQ_843","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_843","question":"What is a potential threat to a business from using social media for promotion?","options":{"A":"Customers are unable to share product links with their friends.","B":"Posts can only contain plain black-and-white text without images.","C":"Public customer complaints or product failures can spread virally within hours, damaging reputation.","D":"Social media platforms charge millions of dollars just to create a business profile."},"correctOption":"C","correctAnswer":"Public customer complaints or product failures can spread virally within hours, damaging reputation.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because social media gives consumers a public voice, meaning poor service or bad reviews can rapidly harm brand image.","distractor_reasons":{"A":"Incorrect because easy sharing is a major benefit of social media.","B":"Incorrect because social media supports photos, videos, and interactive content.","C":"Option C is correct because social media gives consumers a public voice, meaning poor service or bad reviews can rapidly harm brand image.","D":"Incorrect because setting up a business social media page is normally free."}}},{"id":"P1_U3_MCQ_844","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_844","question":"What is an opportunity created by e-commerce for a business's 'Place' strategy?","options":{"A":"It forces the business to open expensive physical stores in every city.","B":"It prevents customers in rural areas from ordering the business's products.","C":"It eliminates the need to package physical goods safely for transport.","D":"It enables direct-to-consumer selling worldwide without needing retail intermediaries."},"correctOption":"D","correctAnswer":"It enables direct-to-consumer selling worldwide without needing retail intermediaries.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because an e-commerce store acts as a global direct distribution channel, letting producers retain full retail margins.","distractor_reasons":{"A":"Incorrect because e-commerce reduces the need for physical retail branches.","B":"Incorrect because rural customers with internet access can order online easily.","C":"Incorrect because parcel delivery actually requires sturdy protective packaging.","D":"Option D is correct because an e-commerce store acts as a global direct distribution channel, letting producers retain full retail margins."}}},{"id":"P1_U3_MCQ_845","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_845","question":"What is a threat of e-commerce to traditional high-street retail shops?","options":{"A":"Shoppers prefer waiting in long checkout queues rather than ordering from home.","B":"Online websites are legally forbidden from selling clothing or electronics.","C":"Lower-cost online competitors can undercut high-street prices because they do not pay expensive shop rents.","D":"High-street shops are prohibited from creating their own websites."},"correctOption":"C","correctAnswer":"Lower-cost online competitors can undercut high-street prices because they do not pay expensive shop rents.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because online-only retailers avoid high-street property rents and store staffing costs, enabling lower prices that draw shoppers away from physical stores.","distractor_reasons":{"A":"Incorrect because convenience and avoiding queues attract shoppers online.","B":"Incorrect because clothing and electronics are among the largest e-commerce categories.","C":"Option C is correct because online-only retailers avoid high-street property rents and store staffing costs, enabling lower prices that draw shoppers away from physical stores.","D":"Incorrect because many high-street chains successfully operate 'click-and-collect' or online stores alongside physical shops."}}},{"id":"P1_U3_MCQ_846","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_846","question":"How does e-commerce affect 'Price' decisions for businesses selling online?","options":{"A":"Businesses can charge double the market price because shoppers cannot check rival prices.","B":"Price comparison websites make prices transparent, forcing online sellers to stay highly competitive or use dynamic pricing.","C":"Online businesses are legally required to charge identical prices across all websites.","D":"Delivery fees are banned by international law."},"correctOption":"B","correctAnswer":"Price comparison websites make prices transparent, forcing online sellers to stay highly competitive or use dynamic pricing.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because consumers can compare rival prices in seconds online, increasing price transparency and competitive pressure.","distractor_reasons":{"A":"Incorrect because online buyers can check rival prices effortlessly.","B":"Option B is correct because consumers can compare rival prices in seconds online, increasing price transparency and competitive pressure.","C":"Incorrect because online retailers set their own independent prices.","D":"Incorrect because businesses may charge delivery fees provided they are clearly disclosed."}}},{"id":"P1_U3_MCQ_847","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_847","question":"What is a cybersecurity threat that businesses operating e-commerce websites must manage?","options":{"A":"Shoplifters physically stealing items from website web pages.","B":"Customers paying with physical coins through their computer screens.","C":"Hacking, data breaches of customer payment details, and website downtime.","D":"Excessive rent increases charged by high-street landlords."},"correctOption":"C","correctAnswer":"Hacking, data breaches of customer payment details, and website downtime.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because online retailers must invest in secure payment encryption and IT reliability to prevent cyberattacks and lost sales.","distractor_reasons":{"A":"Incorrect because physical shoplifting occurs in brick-and-mortar shops, not online.","B":"Incorrect because online payments are digital.","C":"Option C is correct because online retailers must invest in secure payment encryption and IT reliability to prevent cyberattacks and lost sales.","D":"Incorrect because high-street shop rents affect physical stores rather than websites."}}},{"id":"P1_U3_MCQ_848","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_848","question":"How can a traditional brick-and-mortar retailer combine physical stores with e-commerce to gain an advantage?","options":{"A":"By closing its website every weekend and refusing card payments.","B":"By charging online customers triple the in-store price.","C":"By refusing to accept returns of online orders in its physical branches.","D":"By offering 'click and collect' where buyers order online and pick up in-store for free."},"correctOption":"D","correctAnswer":"By offering 'click and collect' where buyers order online and pick up in-store for free.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because 'click and collect' saves delivery charges for customers and brings them into physical stores where they may buy extra items.","distractor_reasons":{"A":"Incorrect because closing a website reduces convenience and sales.","B":"Incorrect because overcharging online shoppers drives them to competitors.","C":"Incorrect because easy in-store returns build confidence in ordering online.","D":"Option D is correct because 'click and collect' saves delivery charges for customers and brings them into physical stores where they may buy extra items."}}},{"id":"P1_U3_MCQ_849","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_849","question":"Why might a luxury designer handbag brand choose NOT to sell its bags on third-party mass-market discount websites?","options":{"A":"Selling alongside cheap discount goods would weaken its exclusive brand image and prestige.","B":"Third-party websites cannot process high-value credit card payments.","C":"Luxury handbags are too heavy to be transported by courier vans.","D":"Laws prohibit luxury brands from selling handbags over the internet."},"correctOption":"A","correctAnswer":"Selling alongside cheap discount goods would weaken its exclusive brand image and prestige.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Place must match brand positioning; selective distribution in flagship boutiques and official brand sites preserves exclusivity.","distractor_reasons":{"A":"Option A is correct because Place must match brand positioning; selective distribution in flagship boutiques and official brand sites preserves exclusivity.","B":"Incorrect because online payment gateways easily process high-value transactions.","C":"Incorrect because handbags are lightweight and easy to ship.","D":"Incorrect because luxury brands legally sell online through their own controlled platforms."}}},{"id":"P1_U3_MCQ_850","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_850","question":"Which promotional method is most appropriate for a small local plumber with a very limited marketing budget?","options":{"A":"A nationwide television commercial during the World Cup final.","B":"Local directory listings, targeted social media posts in the town, and printed flyers.","C":"Sponsoring an international Formula 1 racing team.","D":"Full-page adverts in national daily financial newspapers."},"correctOption":"B","correctAnswer":"Local directory listings, targeted social media posts in the town, and printed flyers.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a local plumber serves nearby households and has a small budget, making low-cost local search/social ads and neighbourhood flyers cost-effective.","distractor_reasons":{"A":"Incorrect because national TV ads are unaffordable and waste money reaching viewers outside the plumber's local area.","B":"Option B is correct because a local plumber serves nearby households and has a small budget, making low-cost local search/social ads and neighbourhood flyers cost-effective.","C":"Incorrect because Formula 1 sponsorship costs millions of dollars.","D":"Incorrect because national newspapers are costly and poorly targeted for a local tradesperson."}}},{"id":"P1_U3_MCQ_851","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_851","question":"A company wants to achieve the marketing objective of 'increasing market share by 5% over the next year' in a competitive snack market. Which marketing strategy is most suitable?","options":{"A":"Raise prices by 30%, cut advertising completely, and reduce the number of shops stocking the snacks.","B":"Stop all product innovation and rely solely on outdated packaging from ten years ago.","C":"Launch a new trending flavour, use competitive pricing with multi-buy offers, and promote heavily on social media and in supermarkets.","D":"Switch from mass-market distribution to selling exclusively by appointment from the factory gate."},"correctOption":"C","correctAnswer":"Launch a new trending flavour, use competitive pricing with multi-buy offers, and promote heavily on social media and in supermarkets.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because combining an appealing new product flavour, competitive/promotional pricing, wide retail availability, and strong promotion aligns all four Ps to win buyers from rivals.","distractor_reasons":{"A":"Incorrect because higher prices, less promotion, and fewer outlets will shrink market share.","B":"Incorrect because ignoring trends and packaging loses market share in snack markets.","C":"Option C is correct because combining an appealing new product flavour, competitive/promotional pricing, wide retail availability, and strong promotion aligns all four Ps to win buyers from rivals.","D":"Incorrect because restricting sales to the factory gate destroys convenience for everyday snack buyers."}}},{"id":"P1_U3_MCQ_852","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_852","question":"Why is 'Product' often considered the central element of the marketing mix when developing a marketing strategy?","options":{"A":"Because Place and Promotion have zero influence on consumer buying decisions.","B":"Because laws forbid businesses from changing their prices or promotional methods.","C":"Because products never require any packaging or branding.","D":"Because if the product fails to satisfy customer needs or is poor quality, low prices and heavy promotion will not sustain repeat sales."},"correctOption":"D","correctAnswer":"Because if the product fails to satisfy customer needs or is poor quality, low prices and heavy promotion will not sustain repeat sales.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a poorly designed or faulty product leads to dissatisfied customers and negative reviews regardless of how well it is advertised or priced.","distractor_reasons":{"A":"Incorrect because Place and Promotion are also essential to make buyers aware and able to purchase.","B":"Incorrect because businesses freely adjust prices and promotions.","C":"Incorrect because packaging and branding are integral parts of the Product element.","D":"Option D is correct because a poorly designed or faulty product leads to dissatisfied customers and negative reviews regardless of how well it is advertised or priced."}}},{"id":"P1_U3_MCQ_853","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_853","question":"Sprint Activewear finds its trainers are bought mostly by 16-25-year-olds who follow fitness trends online. Which marketing strategy activity has Sprint carried out?","options":{"A":"Market segmentation to identify a target market","B":"Cost-plus pricing of its products","C":"Mass production to lower unit costs","D":"Improving its distribution channels"},"correctOption":"A","correctAnswer":"Market segmentation to identify a target market","questionType":"MCQ","explanation":{"correct_reason":"Segmentation divides the market into distinct customer groups; identifying young fitness enthusiasts as its buyers is defining a target market, a key marketing strategy decision.","distractor_reasons":{"A":"Correct - grouping customers by age and interests to focus marketing is segmentation and target marketing.","B":"Cost-plus pricing is a pricing method, not the identification of a customer group.","C":"Mass production is an operations decision to lower unit costs, not identifying customers.","D":"Distribution channels concern where the product is sold, not identifying a target market."}}},{"id":"P1_U3_MCQ_854","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_854","question":"When is 'Place' (convenient availability) likely to be the most critical element of the marketing mix?","options":{"A":"For rare antique paintings sold at international auctions.","B":"For custom-built commercial passenger aircraft.","C":"For bespoke architectural home designs.","D":"For impulse convenience items such as bottled water, umbrellas on a rainy day, or snack bars."},"correctOption":"D","correctAnswer":"For impulse convenience items such as bottled water, umbrellas on a rainy day, or snack bars.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because consumers buying convenience or impulse items will simply buy whichever brand is immediately available in the nearest shop or vending machine.","distractor_reasons":{"A":"Incorrect because collectors travel or bid online for rare antiques regardless of convenience.","B":"Incorrect because airlines negotiate directly with manufacturers over technical specifications and price.","C":"Incorrect because architectural services are commissioned directly rather than bought on impulse.","D":"Option D is correct because consumers buying convenience or impulse items will simply buy whichever brand is immediately available in the nearest shop or vending machine."}}},{"id":"P1_U3_MCQ_855","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_855","question":"In which market is 'Promotion' especially influential in differentiating similar products and driving consumer choice?","options":{"A":"Markets for raw industrial iron ore sold to steel mills.","B":"Markets for perfumes, soft drinks, and fashion trainers where brand image heavily shapes consumer preference.","C":"Government monopoly water utility supply.","D":"Wholesale bulk grain trading between farms and flour mills."},"correctOption":"B","correctAnswer":"Markets for perfumes, soft drinks, and fashion trainers where brand image heavily shapes consumer preference.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because in lifestyle and personal-image markets like perfumes and trainers, persuasive advertising and celebrity endorsement build emotional brand appeal.","distractor_reasons":{"A":"Incorrect because industrial buyers judge iron ore by chemical grade and price rather than lifestyle ads.","B":"Option B is correct because in lifestyle and personal-image markets like perfumes and trainers, persuasive advertising and celebrity endorsement build emotional brand appeal.","C":"Incorrect because a monopoly utility has no competitors to persuade buyers against.","D":"Incorrect because B2B agricultural buyers focus on commodity grade and price."}}},{"id":"P1_U3_MCQ_856","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_856","question":"A toy company advertises a plastic action figure on TV showing it flying across a room on its own, even though the toy cannot fly. Which legal control does this breach?","options":{"A":"Weights and measures regulations.","B":"Minimum wage employment legislation.","C":"Laws against misleading promotion and false trade descriptions.","D":"Health and safety factory noise limits."},"correctOption":"C","correctAnswer":"Laws against misleading promotion and false trade descriptions.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because consumer protection and advertising laws prohibit exaggerated or false claims about what a product can actually do.","distractor_reasons":{"A":"Incorrect because weights and measures govern quantity/weight labels, not exaggerated performance claims.","B":"Incorrect because minimum wage laws govern worker pay.","C":"Option C is correct because consumer protection and advertising laws prohibit exaggerated or false claims about what a product can actually do.","D":"Incorrect because factory noise limits relate to workplace operations."}}},{"id":"P1_U3_MCQ_857","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_857","question":"A cereal box states 'Net Weight: 500g', but spot checks reveal boxes consistently contain only 440g. Which area of marketing legislation has been violated?","options":{"A":"Patent infringement law.","B":"Trade union collective bargaining law.","C":"Environmental zoning regulations.","D":"Weights and measures legislation."},"correctOption":"D","correctAnswer":"Weights and measures legislation.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because weights and measures laws make it an offence to sell short-weight goods or misstate package quantities.","distractor_reasons":{"A":"Incorrect because patents protect inventions from being copied.","B":"Incorrect because trade union laws govern employee representation.","C":"Incorrect because zoning laws regulate where factories or shops may be built.","D":"Option D is correct because weights and measures laws make it an offence to sell short-weight goods or misstate package quantities."}}},{"id":"P1_U3_MCQ_858","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_858","question":"What happens if a business sells an electric kettle that overheats and causes burns during normal household use?","options":{"A":"The business is rewarded with lower corporation tax rates.","B":"The customer has no legal rights once they leave the shop.","C":"It breaches consumer safety laws, forcing product recalls, legal fines, compensation claims, and severe brand damage.","D":"Only the factory worker who assembled the kettle can be prosecuted, while the company faces no consequences."},"correctOption":"C","correctAnswer":"It breaches consumer safety laws, forcing product recalls, legal fines, compensation claims, and severe brand damage.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because consumer protection laws require goods to be safe and fit for purpose; dangerous products trigger costly recalls, penalties, and loss of trust.","distractor_reasons":{"A":"Incorrect because selling unsafe goods brings legal penalties rather than tax rewards.","B":"Incorrect because statutory consumer rights protect buyers after purchase.","C":"Option C is correct because consumer protection laws require goods to be safe and fit for purpose; dangerous products trigger costly recalls, penalties, and loss of trust.","D":"Incorrect because the business itself is legally liable for selling unsafe products."}}},{"id":"P1_U3_MCQ_859","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_859","question":"Why do many governments restrict or ban the advertising of cigarettes and alcohol to young people?","options":{"A":"To increase government spending on tobacco subsidies.","B":"To protect public health and prevent persuasive promotion from encouraging harmful consumption among minors.","C":"To help cigarette companies reduce their marketing expenses and increase profits.","D":"Because print newspapers refuse to accept money from any advertisers."},"correctOption":"B","correctAnswer":"To protect public health and prevent persuasive promotion from encouraging harmful consumption among minors.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because legal controls over promotion also aim to protect vulnerable groups and public health from harmful products.","distractor_reasons":{"A":"Incorrect because advertising bans discourage smoking rather than subsidising it.","B":"Option B is correct because legal controls over promotion also aim to protect vulnerable groups and public health from harmful products.","C":"Incorrect because advertising restrictions limit tobacco companies' ability to attract new customers.","D":"Incorrect because newspapers depend heavily on advertising revenue."}}},{"id":"P1_U3_MCQ_860","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_860","question":"How can strict consumer protection laws create a competitive advantage for an ethical, high-quality business?","options":{"A":"They allow the ethical business to sell faulty items without giving refunds.","B":"They eliminate all costs of quality assurance testing.","C":"They force dishonest rivals out of the market or penalise them, rewarding firms that already maintain high safety and honesty standards.","D":"They permit the business to make exaggerated claims in online adverts."},"correctOption":"C","correctAnswer":"They force dishonest rivals out of the market or penalise them, rewarding firms that already maintain high safety and honesty standards.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because strong legal enforcement prevents unscrupulous competitors from undercutting responsible firms by selling unsafe or falsely described goods.","distractor_reasons":{"A":"Incorrect because all businesses must refund or replace faulty goods.","B":"Incorrect because quality assurance testing is still required.","C":"Option C is correct because strong legal enforcement prevents unscrupulous competitors from undercutting responsible firms by selling unsafe or falsely described goods.","D":"Incorrect because consumer laws prohibit exaggerated or misleading claims."}}},{"id":"P1_U3_MCQ_861","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_861","question":"Why do businesses often seek to enter new markets in other countries when their home market becomes 'saturated'?","options":{"A":"Because saturated domestic markets offer little room for further sales growth, whereas fast-growing foreign economies offer new demand.","B":"Because exporting goods to other countries eliminates all transport and packaging costs.","C":"Because foreign consumers never care about price or product quality.","D":"Because domestic governments ban businesses from selling to local citizens once they reach 20% market share."},"correctOption":"A","correctAnswer":"Because saturated domestic markets offer little room for further sales growth, whereas fast-growing foreign economies offer new demand.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because when almost everyone in the domestic market already owns the product, expanding abroad unlocks new customers and revenue growth.","distractor_reasons":{"A":"Option A is correct because when almost everyone in the domestic market already owns the product, expanding abroad unlocks new customers and revenue growth.","B":"Incorrect because international shipping increases transport and packaging expenses.","C":"Incorrect because foreign consumers are just as discerning about price and quality.","D":"Incorrect because no such 20% domestic sales ban exists."}}},{"id":"P1_U3_MCQ_862","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_862","question":"How does entering foreign markets help a business achieve greater 'economies of scale'?","options":{"A":"By reducing total factory output so fewer raw materials are needed.","B":"By increasing total global sales volume, allowing fixed R&D and machinery costs to be spread over more units.","C":"By forcing the business to build small, inefficient workshops in every town.","D":"By eliminating all import tariffs worldwide."},"correctOption":"B","correctAnswer":"By increasing total global sales volume, allowing fixed R&D and machinery costs to be spread over more units.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because higher combined domestic and export production lowers average unit costs through bulk purchasing and fuller capacity utilisation.","distractor_reasons":{"A":"Incorrect because entering new markets increases output rather than reducing it.","B":"Option B is correct because higher combined domestic and export production lowers average unit costs through bulk purchasing and fuller capacity utilisation.","C":"Incorrect because small workshops cause diseconomies rather than economies of scale.","D":"Incorrect because tariffs are set by governments, not eliminated by a firm's expansion."}}},{"id":"P1_U3_MCQ_863","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_863","question":"How can 'language differences' create problems when a business enters a new foreign market?","options":{"A":"Foreign consumers can always understand English slogans without translation.","B":"Language differences eliminate the need to print instruction manuals.","C":"Direct translation of brand names or advertising slogans may accidentally carry offensive or nonsensical meanings in the local language.","D":"Language differences prevent businesses from using dynamic pricing."},"correctOption":"C","correctAnswer":"Direct translation of brand names or advertising slogans may accidentally carry offensive or nonsensical meanings in the local language.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because poorly translated slogans, labels, or product names can confuse or offend local buyers, requiring professional localisation.","distractor_reasons":{"A":"Incorrect because many consumers prefer or require labels and ads in their native language.","B":"Incorrect because instruction manuals and safety warnings must be accurately translated.","C":"Option C is correct because poorly translated slogans, labels, or product names can confuse or offend local buyers, requiring professional localisation.","D":"Incorrect because pricing algorithms are unaffected by spoken languages."}}},{"id":"P1_U3_MCQ_864","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_864","question":"How can 'exchange rate changes' create a problem for an exporter selling products in a foreign country?","options":{"A":"Exchange rates never change between any two currencies.","B":"If the exporter's home currency appreciates (rises in value), its products become more expensive for foreign buyers, reducing sales.","C":"Exchange rate fluctuations automatically cancel all shipping insurance.","D":"Foreign retailers refuse to accept electronic bank transfers."},"correctOption":"B","correctAnswer":"If the exporter's home currency appreciates (rises in value), its products become more expensive for foreign buyers, reducing sales.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a stronger domestic currency makes exports pricier in foreign currency terms (or reduces profit margins if local prices are held steady).","distractor_reasons":{"A":"Incorrect because exchange rates fluctuate daily on foreign exchange markets.","B":"Option B is correct because a stronger domestic currency makes exports pricier in foreign currency terms (or reduces profit margins if local prices are held steady).","C":"Incorrect because insurance contracts remain valid regardless of exchange rate shifts.","D":"Incorrect because international bank transfers are standard in global trade."}}},{"id":"P1_U3_MCQ_865","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_865","question":"How do 'import tariffs and quotas' imposed by a foreign government act as a barrier to entering that market?","options":{"A":"They lower the selling price of imported goods below local competitors.","B":"They provide free warehouse storage for foreign exporters.","C":"Tariffs tax imported goods (making them more expensive) while quotas restrict the maximum quantity allowed into the country.","D":"They force domestic consumers to buy only imported products."},"correctOption":"C","correctAnswer":"Tariffs tax imported goods (making them more expensive) while quotas restrict the maximum quantity allowed into the country.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because protectionist trade barriers raise the price or limit the volume of foreign products to protect local producers.","distractor_reasons":{"A":"Incorrect because tariffs increase, rather than lower, the price of imports.","B":"Incorrect because tariffs are taxes paid by importers, not free storage.","C":"Option C is correct because protectionist trade barriers raise the price or limit the volume of foreign products to protect local producers.","D":"Incorrect because tariffs and quotas aim to protect domestic producers, not force import purchases."}}},{"id":"P1_U3_MCQ_866","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_866","question":"Why are 'higher transport costs' a problem when exporting bulky or heavy goods to distant countries?","options":{"A":"Long-distance freight adds substantially to unit costs, forcing higher selling prices that may make the product uncompetitive against local rivals.","B":"Cargo ships and aircraft refuse to carry manufactured goods across oceans.","C":"Transport costs are always paid by the exporting country's government.","D":"Bulky goods become lighter the further they travel."},"correctOption":"A","correctAnswer":"Long-distance freight adds substantially to unit costs, forcing higher selling prices that may make the product uncompetitive against local rivals.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because shipping heavy or low-value-to-weight items over long distances erodes profit margins or prices the exporter out of the foreign market.","distractor_reasons":{"A":"Option A is correct because shipping heavy or low-value-to-weight items over long distances erodes profit margins or prices the exporter out of the foreign market.","B":"Incorrect because international shipping lines regularly transport manufactured goods.","C":"Incorrect because businesses pay their own commercial freight expenses.","D":"Incorrect because physical weight does not decrease during transit."}}},{"id":"P1_U3_MCQ_867","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_867","question":"How does forming a 'joint venture' with a local company help a business overcome the problems of entering a new foreign market?","options":{"A":"The foreign entrant gains immediate access to local market knowledge, established distribution networks, and shared capital costs.","B":"The foreign entrant keeps 100% of all profits without sharing any decision-making.","C":"It eliminates all cultural and language differences between the two countries automatically.","D":"It exempts the business from obeying the host country's tax and safety laws."},"correctOption":"A","correctAnswer":"The foreign entrant gains immediate access to local market knowledge, established distribution networks, and shared capital costs.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because partnering with an existing local firm combines the entrant's product expertise with the local partner's contacts, cultural insight, and outlets.","distractor_reasons":{"A":"Option A is correct because partnering with an existing local firm combines the entrant's product expertise with the local partner's contacts, cultural insight, and outlets.","B":"Incorrect because profits and control must be shared with the joint venture partner.","C":"Incorrect because cultural differences still exist and must even be managed between the two partners.","D":"Incorrect because joint ventures must comply fully with host-country laws."}}},{"id":"P1_U3_MCQ_868","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_868","question":"What is a potential disadvantage of entering a foreign market through a 'joint venture'?","options":{"A":"The business has to bear 100% of the financial risk alone.","B":"Disagreements may arise between the partners over strategy, quality standards, and profit sharing.","C":"The local partner has zero knowledge of domestic consumers.","D":"Joint ventures are illegal in all international markets."},"correctOption":"B","correctAnswer":"Disagreements may arise between the partners over strategy, quality standards, and profit sharing.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because differences in management styles, business culture, and objectives can create conflict between joint venture partners.","distractor_reasons":{"A":"Incorrect because sharing capital and risk is an advantage of a joint venture.","B":"Option B is correct because differences in management styles, business culture, and objectives can create conflict between joint venture partners.","C":"Incorrect because local market knowledge is the main reason for choosing a local partner.","D":"Incorrect because joint ventures are a common, legal method of international expansion."}}},{"id":"P1_U3_MCQ_869","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_869","question":"How does 'licensing' help a business enter a foreign market while avoiding high transport costs and import tariffs?","options":{"A":"The business ships every finished item individually by air freight from its home factory.","B":"The business sells its entire company permanently to a foreign government.","C":"The business grants a foreign firm permission to manufacture and sell its patented product locally in return for royalty fees.","D":"The business smuggles goods across borders without paying customs duties."},"correctOption":"C","correctAnswer":"The business grants a foreign firm permission to manufacture and sell its patented product locally in return for royalty fees.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because local production by a licensee eliminates cross-border shipping and import tariffs while generating royalty income with low capital risk.","distractor_reasons":{"A":"Incorrect because air freight incurs high transport costs and tariffs.","B":"Incorrect because licensing retains ownership of the brand/patent rather than selling the whole company.","C":"Option C is correct because local production by a licensee eliminates cross-border shipping and import tariffs while generating royalty income with low capital risk.","D":"Incorrect because smuggling is illegal."}}},{"id":"P1_U3_MCQ_870","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_870","question":"What is a risk of using 'licensing' to expand into a foreign market?","options":{"A":"The business must invest huge sums building its own overseas factories.","B":"The foreign licensee may produce poor-quality goods that harm the brand's reputation or become a future competitor.","C":"The business receives zero royalty payments even if sales are high.","D":"Licensing requires hiring thousands of domestic retail staff."},"correctOption":"B","correctAnswer":"The foreign licensee may produce poor-quality goods that harm the brand's reputation or become a future competitor.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because giving a foreign firm access to designs/technology reduces direct quality control and risks creating a future rival once the licence ends.","distractor_reasons":{"A":"Incorrect because the licensee provides the local factory capital.","B":"Option B is correct because giving a foreign firm access to designs/technology reduces direct quality control and risks creating a future rival once the licence ends.","C":"Incorrect because licensees pay agreed royalties based on sales or output.","D":"Incorrect because the licensee hires its own local workforce."}}},{"id":"P1_U3_MCQ_871","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_871","question":"How does 'international franchising' help a fast-food or retail brand expand rapidly into foreign countries?","options":{"A":"International franchising eliminates the need for any training or quality checks.","B":"The franchisor pays every franchisee's rent and staff wages out of its own pocket.","C":"Franchisees are free to change the brand name, menu, and logo however they wish.","D":"Local franchisees invest their own capital to open outlets and bring local cultural knowledge while following the franchisor's proven business model."},"correctOption":"D","correctAnswer":"Local franchisees invest their own capital to open outlets and bring local cultural knowledge while following the franchisor's proven business model.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because franchisees fund local store openings and understand local consumers while paying fees and royalties to use an established brand.","distractor_reasons":{"A":"Incorrect because franchisors must train franchisees and monitor quality to protect the global brand.","B":"Incorrect because franchisees fund their own local operating expenses.","C":"Incorrect because franchisees must follow the franchisor's brand standards, though minor local menu adaptations may be approved.","D":"Option D is correct because franchisees fund local store openings and understand local consumers while paying fees and royalties to use an established brand."}}},{"id":"P1_U3_MCQ_872","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_872","question":"What does 'localising existing brands' (glocalisation) involve when entering foreign markets?","options":{"A":"Selling the exact same product, recipe, and advertisement in every country without any modification.","B":"Abandoning the global brand name completely in every foreign city.","C":"Keeping the core global brand identity while adapting product flavours, packaging, or promotions to suit local cultural preferences.","D":"Refusing to sell products in any country outside the company's home continent."},"correctOption":"C","correctAnswer":"Keeping the core global brand identity while adapting product flavours, packaging, or promotions to suit local cultural preferences.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because localising a global brand (such as offering vegetarian or spicy regional menu options at global fast-food chains) respects local tastes while leveraging global brand recognition.","distractor_reasons":{"A":"Incorrect because an unadapted global approach ignores local cultural and dietary differences.","B":"Incorrect because localisation preserves the core brand identity rather than abandoning it.","C":"Option C is correct because localising a global brand (such as offering vegetarian or spicy regional menu options at global fast-food chains) respects local tastes while leveraging global brand recognition.","D":"Incorrect because localisation is a strategy specifically used for international expansion."}}},{"id":"P1_U3_MCQ_873","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_873","question":"A global fast-food chain enters a country where most consumers do not eat beef for religious reasons. Which marketing strategy adjustment is essential?","options":{"A":"Keep beef burgers as the sole menu item and run ads telling locals to change their diet.","B":"Double the price of all meals to offset expected low customer numbers.","C":"Close all restaurants during lunchtime and dinner hours.","D":"Replace beef items with chicken, fish, and vegetarian burgers while ensuring local cultural compliance."},"correctOption":"D","correctAnswer":"Replace beef items with chicken, fish, and vegetarian burgers while ensuring local cultural compliance.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because adapting the Product element to respect religious and dietary norms is vital for acceptance and sales in the new market.","distractor_reasons":{"A":"Incorrect because ignoring religious dietary restrictions will cause the business to fail.","B":"Incorrect because high prices will further deter local customers.","C":"Incorrect because closing at peak meal times destroys restaurant revenue.","D":"Option D is correct because adapting the Product element to respect religious and dietary norms is vital for acceptance and sales in the new market."}}},{"id":"P1_U3_MCQ_874","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_874","question":"A high-end smartphone maker wants to enter a developing country where average household incomes are significantly lower than in its home market. Which strategy adjustment is most appropriate?","options":{"A":"Introduce a more affordable, slightly simplified model or offer monthly instalment plans while highlighting durability.","B":"Raise the phone's price by 40% above its home-country luxury price.","C":"Sell the phone exclusively in five-star airport lounges.","D":"Advertise only in print magazines written in a foreign language."},"correctOption":"A","correctAnswer":"Introduce a more affordable, slightly simplified model or offer monthly instalment plans while highlighting durability.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because adjusting Product specifications and Price/payment terms to match lower disposable incomes makes the brand accessible to the new market.","distractor_reasons":{"A":"Option A is correct because adjusting Product specifications and Price/payment terms to match lower disposable incomes makes the brand accessible to the new market.","B":"Incorrect because raising prices where incomes are lower will prevent almost all sales.","C":"Incorrect because restricting Place to airport lounges misses the wider domestic market.","D":"Incorrect because foreign-language print ads will not reach local consumers effectively."}}},{"id":"P1_U3_MCQ_875","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_875","question":"Before finalising a marketing strategy to launch a new product in a foreign country, why must managers review all four elements of the marketing mix together?","options":{"A":"To guarantee that exchange rates and competitor prices remain frozen for ten years.","B":"Because international law requires every exporter to use price skimming and wholesalers.","C":"To ensure that Product, Price, Place, and Promotion support each other, fit the local target segment, comply with local laws, and stay within budget.","D":"Because once a marketing strategy is chosen, it can never be changed again."},"correctOption":"C","correctAnswer":"To ensure that Product, Price, Place, and Promotion support each other, fit the local target segment, comply with local laws, and stay within budget.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because an effective international marketing strategy integrates all four Ps harmoniously while respecting budget limits, local culture, and legal controls.","distractor_reasons":{"A":"Incorrect because exchange rates and competitors constantly change.","B":"Incorrect because businesses choose pricing and distribution methods suited to their specific product and market.","C":"Option C is correct because an effective international marketing strategy integrates all four Ps harmoniously while respecting budget limits, local culture, and legal controls.","D":"Incorrect because marketing strategies must be reviewed and adapted continuously as market conditions evolve."}}},{"id":"P1_U3_MCQ_876","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_876","question":"Why is identifying customer needs before designing a product essential for business survival?","options":{"A":"It guarantees that government taxes on sales are reduced.","B":"It eliminates all fixed overhead expenses in the factory.","C":"It prevents competitors from lowering their prices.","D":"It ensures the business produces goods that consumers actually want and are willing to buy."},"correctOption":"D","correctAnswer":"It ensures the business produces goods that consumers actually want and are willing to buy.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because aligning products with genuine customer needs reduces the risk of unsold stock and business failure.","distractor_reasons":{"A":"Incorrect because sales tax rates are set by governments, not marketing.","B":"Incorrect because fixed overheads still exist regardless of customer research.","C":"Incorrect because identifying customer needs does not stop rivals from changing prices.","D":"Option D is correct because aligning products with genuine customer needs reduces the risk of unsold stock and business failure."}}},{"id":"P1_U3_MCQ_877","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_877","question":"Total sales in the electric scooter market are $80 million. Brand Z generates annual sales of $24 million. What is Brand Z's market share?","options":{"A":"20%","B":"30%","C":"33%","D":"40%"},"correctOption":"B","correctAnswer":"30%","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because ($24 million / $80 million) x 100 = 30%.","distractor_reasons":{"A":"Incorrect because 20% of $80 million is $16 million.","B":"Option B is correct because ($24 million / $80 million) x 100 = 30%.","C":"Incorrect because 33% of $80 million is approximately $26.4 million.","D":"Incorrect because 40% of $80 million is $32 million."}}},{"id":"P1_U3_MCQ_878","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_878","question":"How does rapid innovation in mobile apps and streaming platforms change consumer spending patterns?","options":{"A":"Consumers spend more money on physical newspapers and printed maps.","B":"Consumers stop purchasing smartphones and internet subscriptions.","C":"Consumers shift spending toward digital subscriptions and on-demand services.","D":"Consumers buy identical technology products for twenty years without upgrading."},"correctOption":"C","correctAnswer":"Consumers shift spending toward digital subscriptions and on-demand services.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because technological convenience shifts consumer expenditure from physical media toward digital platforms.","distractor_reasons":{"A":"Incorrect because digital apps have reduced demand for printed maps and newspapers.","B":"Incorrect because demand for smartphones and broadband has grown alongside streaming.","C":"Option C is correct because technological convenience shifts consumer expenditure from physical media toward digital platforms.","D":"Incorrect because rapid tech advances shorten replacement cycles."}}},{"id":"P1_U3_MCQ_879","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_879","question":"Which factor best explains why a niche manufacturer of vegan leather handbags can survive alongside huge global fashion brands?","options":{"A":"It achieves greater purchasing economies of scale than global corporations.","B":"It sells identical bags to every consumer segment at discount prices.","C":"It has no variable costs when sourcing plant-based materials.","D":"It caters closely to the ethical values of a specific consumer group overlooked by mass-market rivals."},"correctOption":"D","correctAnswer":"It caters closely to the ethical values of a specific consumer group overlooked by mass-market rivals.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because niche businesses succeed by meeting specialised needs and values that standardised mass-market brands miss.","distractor_reasons":{"A":"Incorrect because small niche firms have lower output and fewer economies of scale than global brands.","B":"Incorrect because niche firms focus on specialised segments rather than mass discounting.","C":"Incorrect because vegan leather materials still incur variable costs.","D":"Option D is correct because niche businesses succeed by meeting specialised needs and values that standardised mass-market brands miss."}}},{"id":"P1_U3_MCQ_880","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_880","question":"What happens to a niche business if consumer preferences suddenly shift away from its single specialised product?","options":{"A":"The business faces a high risk of failure because its small customer base offers no alternative demand.","B":"The business automatically transforms into a mass-market monopoly.","C":"Its fixed costs immediately fall to zero.","D":"Its market share increases to 100%."},"correctOption":"A","correctAnswer":"The business faces a high risk of failure because its small customer base offers no alternative demand.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because relying on one small, specialised segment leaves a niche firm highly vulnerable when tastes change.","distractor_reasons":{"A":"Option A is correct because relying on one small, specialised segment leaves a niche firm highly vulnerable when tastes change.","B":"Incorrect because falling demand shrinks the business rather than making it a mass-market leader.","C":"Incorrect because fixed overheads such as rent remain even when sales drop.","D":"Incorrect because market share does not protect a firm when total segment demand disappears."}}},{"id":"P1_U3_MCQ_881","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_881","question":"Which characteristic defines a product sold in a mass market?","options":{"A":"Custom-engineered to one individual buyer's blueprints.","B":"Standardised design aimed at appealing to the largest possible number of consumers.","C":"Sold exclusively in a single luxury boutique.","D":"Priced above the reach of 99% of households."},"correctOption":"B","correctAnswer":"Standardised design aimed at appealing to the largest possible number of consumers.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because mass-market goods are standardised to satisfy broad, common consumer needs at high sales volumes.","distractor_reasons":{"A":"Incorrect because one-off custom items represent bespoke job production rather than mass markets.","B":"Option B is correct because mass-market goods are standardised to satisfy broad, common consumer needs at high sales volumes.","C":"Incorrect because mass-market products require wide distribution across many outlets.","D":"Incorrect because mass-market goods are priced affordably for wide appeal."}}},{"id":"P1_U3_MCQ_882","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_882","question":"A travel agency offers budget coach tours for retired seniors, adventure backpacking trips for students, and luxury beach resorts for high-income families. Which marketing concept is this?","options":{"A":"Undifferentiated mass marketing.","B":"Product orientation.","C":"Market segmentation.","D":"Price skimming."},"correctOption":"C","correctAnswer":"Market segmentation.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the agency divides the travel market by age, income, and lifestyle to tailor distinct holiday packages to each group.","distractor_reasons":{"A":"Incorrect because undifferentiated marketing offers one identical product to everyone.","B":"Incorrect because tailoring packages to distinct customer groups is market-oriented segmentation.","C":"Option C is correct because the agency divides the travel market by age, income, and lifestyle to tailor distinct holiday packages to each group.","D":"Incorrect because price skimming is launching a single innovative product at a high initial price."}}},{"id":"P1_U3_MCQ_883","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_883","question":"Which segmentation factor is being applied when a skincare brand develops separate product lines for men and women?","options":{"A":"Location segmentation.","B":"Income segmentation.","C":"Use of product segmentation.","D":"Gender segmentation."},"correctOption":"D","correctAnswer":"Gender segmentation.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because dividing consumers into male and female target groups is gender segmentation.","distractor_reasons":{"A":"Incorrect because location segmentation groups buyers by geographic region.","B":"Incorrect because income segmentation divides buyers by earnings.","C":"Incorrect because product usage divides buyers by how or how often they use an item.","D":"Option D is correct because dividing consumers into male and female target groups is gender segmentation."}}},{"id":"P1_U3_MCQ_884","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_884","question":"How does rising competition from low-cost overseas imports affect domestic manufacturers?","options":{"A":"It forces domestic firms to improve efficiency, differentiate products, or risk losing market share.","B":"It allows domestic firms to raise prices without improving product quality.","C":"It removes the need for domestic firms to advertise their brands.","D":"It guarantees higher profit margins for all local producers."},"correctOption":"A","correctAnswer":"It forces domestic firms to improve efficiency, differentiate products, or risk losing market share.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because cheaper foreign rivals put downward pressure on prices and force domestic producers to cut costs or innovate.","distractor_reasons":{"A":"Option A is correct because cheaper foreign rivals put downward pressure on prices and force domestic producers to cut costs or innovate.","B":"Incorrect because raising prices without adding value drives buyers toward cheaper imports.","C":"Incorrect because stronger competition makes brand promotion even more important.","D":"Incorrect because intense competition typically squeezes profit margins."}}},{"id":"P1_U3_MCQ_885","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_885","question":"Why do multinational businesses often adjust their product designs when segmenting markets by geographic location?","options":{"A":"Because transport laws ban identical goods from crossing national borders.","B":"Because climate, cultural traditions, and local infrastructure differ across regions.","C":"Because geographic segmentation eliminates all marketing research costs.","D":"Because consumers in every country have identical income levels."},"correctOption":"B","correctAnswer":"Because climate, cultural traditions, and local infrastructure differ across regions.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because regional climate (e.g. cold vs tropical) and cultural norms directly affect what products consumers need.","distractor_reasons":{"A":"Incorrect because identical goods can legally cross borders unless they breach local standards.","B":"Option B is correct because regional climate (e.g. cold vs tropical) and cultural norms directly affect what products consumers need.","C":"Incorrect because researching regional differences still requires market research.","D":"Incorrect because incomes vary substantially across regions and countries."}}},{"id":"P1_U3_MCQ_886","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_886","question":"What is a key difference between a customer and a consumer?","options":{"A":"A customer always operates in the public sector, whereas a consumer is in the private sector.","B":"A customer manufactures the product, whereas a consumer delivers it to shops.","C":"A customer buys the product, whereas a consumer is the end user who actually uses or consumes it.","D":"A customer buys only online, whereas a consumer buys only in physical stores."},"correctOption":"C","correctAnswer":"A customer buys the product, whereas a consumer is the end user who actually uses or consumes it.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because the buyer (e.g. a parent buying baby food or toys) is the customer, while the person using the item (the child) is the consumer.","distractor_reasons":{"A":"Incorrect because both customers and consumers exist in private and public markets.","B":"Incorrect because manufacturers and distributors are producers/intermediaries, not customers or consumers.","C":"Option C is correct because the buyer (e.g. a parent buying baby food or toys) is the customer, while the person using the item (the child) is the consumer.","D":"Incorrect because shopping channel does not define customer versus consumer."}}},{"id":"P1_U3_MCQ_887","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_887","question":"Why should a children's breakfast cereal brand consider both the consumer and the customer in its marketing?","options":{"A":"Because children earn high salaries and pay for groceries themselves.","B":"Because parents never check nutritional labels before buying food.","C":"Because laws require children to approve all supermarket price tags.","D":"Because children influence what cereal they want to eat, while parents make the final purchasing decision."},"correctOption":"D","correctAnswer":"Because children influence what cereal they want to eat, while parents make the final purchasing decision.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because appealing packaging attracts the child (consumer) while health/value messages reassure the parent (customer).","distractor_reasons":{"A":"Incorrect because children do not earn salaries to pay for household groceries.","B":"Incorrect because parents frequently evaluate nutrition and price as customers.","C":"Incorrect because no such law exists.","D":"Option D is correct because appealing packaging attracts the child (consumer) while health/value messages reassure the parent (customer)."}}},{"id":"P1_U3_MCQ_888","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_888","question":"Why is a market-oriented approach generally less risky than a product-oriented approach when launching consumer goods?","options":{"A":"It guarantees that competitors cannot launch rival products.","B":"It avoids spending any money on prototypes or product testing.","C":"It bases product design on proven customer demand identified through research before committing production funds.","D":"It eliminates all variable costs of raw materials."},"correctOption":"C","correctAnswer":"It bases product design on proven customer demand identified through research before committing production funds.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because researching buyer preferences beforehand reduces the likelihood of producing goods that fail to sell.","distractor_reasons":{"A":"Incorrect because rivals can still launch competing products.","B":"Incorrect because market-oriented firms still build and test prototypes with target consumers.","C":"Option C is correct because researching buyer preferences beforehand reduces the likelihood of producing goods that fail to sell.","D":"Incorrect because raw materials still carry variable costs."}}},{"id":"P1_U3_MCQ_889","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_889","question":"In which industry is a product-oriented approach still commonly found?","options":{"A":"Fast-fashion clothing retailing.","B":"Pharmaceutical research and specialised scientific or engineering equipment.","C":"Supermarket breakfast cereal production.","D":"High-street coffee shop chains."},"correctOption":"B","correctAnswer":"Pharmaceutical research and specialised scientific or engineering equipment.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because medical drugs and advanced engineering rely heavily on scientific breakthroughs and technical performance before markets are developed.","distractor_reasons":{"A":"Incorrect because fast fashion is strongly market-oriented, tracking rapid consumer trends.","B":"Option B is correct because medical drugs and advanced engineering rely heavily on scientific breakthroughs and technical performance before markets are developed.","C":"Incorrect because packaged foods rely heavily on consumer taste and market research.","D":"Incorrect because coffee chains adapt menus closely to customer preferences."}}},{"id":"P1_U3_MCQ_890","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_890","question":"Which of the following questions in a questionnaire collects 'qualitative' data?","options":{"A":"How many times did you visit our cinema last month? (0 / 1-2 / 3+)","B":"What is your annual household income bracket?","C":"Please explain in your own words what you disliked about our online ticket booking process.","D":"On a scale of 1 to 5, how satisfied were you with the seat comfort?"},"correctOption":"C","correctAnswer":"Please explain in your own words what you disliked about our online ticket booking process.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because open-ended descriptive opinions about reasons and experiences constitute qualitative data.","distractor_reasons":{"A":"Incorrect because visit frequency produces numerical quantitative data.","B":"Incorrect because income brackets produce numerical quantitative data.","C":"Option C is correct because open-ended descriptive opinions about reasons and experiences constitute qualitative data.","D":"Incorrect because numerical rating scales generate quantitative scores."}}},{"id":"P1_U3_MCQ_891","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_891","question":"Why is 'quantitative' market research data useful for business decision-making?","options":{"A":"It always reveals the deep psychological motives behind every consumer choice.","B":"It is easy to analyse statistically and present in charts to measure market size and percentage preferences.","C":"It requires no sample selection or questionnaire planning.","D":"It is always free from any wording bias."},"correctOption":"B","correctAnswer":"It is easy to analyse statistically and present in charts to measure market size and percentage preferences.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because numerical data from large samples can be quickly counted, compared, and turned into percentages and graphs.","distractor_reasons":{"A":"Incorrect because uncovering deep motives is the strength of qualitative research.","B":"Option B is correct because numerical data from large samples can be quickly counted, compared, and turned into percentages and graphs.","C":"Incorrect because quantitative surveys still require careful sampling and question design.","D":"Incorrect because poorly worded quantitative questions can still produce biased figures."}}},{"id":"P1_U3_MCQ_892","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_892","question":"A toy manufacturer reviews national birth rate statistics from the government's official website before planning next year's production. What type of research is this?","options":{"A":"Primary field observation.","B":"External secondary desk research.","C":"Focus group qualitative research.","D":"Internal primary survey research."},"correctOption":"B","correctAnswer":"External secondary desk research.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because government statistics are already published by an external organisation, making them external secondary data.","distractor_reasons":{"A":"Incorrect because no live consumer behaviour is being watched first-hand.","B":"Option B is correct because government statistics are already published by an external organisation, making them external secondary data.","C":"Incorrect because no group discussion is taking place.","D":"Incorrect because the data comes from an external government source rather than internal records."}}},{"id":"P1_U3_MCQ_893","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_893","question":"Why might a business look at its own customer complaints log as part of market research?","options":{"A":"It shows the exact market share of every foreign competitor.","B":"It provides primary data on what non-customers think of rival brands.","C":"It is an inexpensive internal secondary source that highlights recurring product or service faults.","D":"It replaces the need for quality assurance in the factory."},"correctOption":"C","correctAnswer":"It is an inexpensive internal secondary source that highlights recurring product or service faults.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because existing company records of complaints provide ready-made internal secondary insights into areas needing improvement.","distractor_reasons":{"A":"Incorrect because internal logs do not measure competitors' sales.","B":"Incorrect because company complaint logs reflect existing customers rather than non-customers.","C":"Option C is correct because existing company records of complaints provide ready-made internal secondary insights into areas needing improvement.","D":"Incorrect because complaint logs identify problems after they occur rather than preventing defects."}}},{"id":"P1_U3_MCQ_894","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_894","question":"What is a major advantage of conducting interviews by telephone rather than face-to-face on the street?","options":{"A":"Interviewers can show physical product prototypes and packaging designs.","B":"Respondents never hang up before finishing a long questionnaire.","C":"It covers a wide geographic area quickly at lower travel cost than in-person interviews.","D":"It completely eliminates interviewer tone bias."},"correctOption":"C","correctAnswer":"It covers a wide geographic area quickly at lower travel cost than in-person interviews.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because telephone interviewers can contact respondents nationwide from one office without travel expenses.","distractor_reasons":{"A":"Incorrect because visual prototypes cannot be shown over a standard voice call.","B":"Incorrect because telephone respondents frequently hang up early.","C":"Option C is correct because telephone interviewers can contact respondents nationwide from one office without travel expenses.","D":"Incorrect because an interviewer's voice and phrasing can still influence replies."}}},{"id":"P1_U3_MCQ_895","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_895","question":"Why are focus groups expensive per participant compared to online questionnaires?","options":{"A":"Each participant must be flown to a foreign country.","B":"They require hiring a trained moderator, renting a venue, and often paying incentives to participants.","C":"Focus groups must include at least 10,000 participants per session.","D":"Government taxes are charged on every question asked in a group."},"correctOption":"B","correctAnswer":"They require hiring a trained moderator, renting a venue, and often paying incentives to participants.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because facilitating a small group discussion requires a skilled moderator, facility costs, and participant rewards for their time.","distractor_reasons":{"A":"Incorrect because focus groups are usually recruited locally or hosted online.","B":"Option B is correct because facilitating a small group discussion requires a skilled moderator, facility costs, and participant rewards for their time.","C":"Incorrect because focus groups typically involve only 6 to 10 people.","D":"Incorrect because no government tax applies to asking research questions."}}},{"id":"P1_U3_MCQ_896","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_896","question":"A soft drinks company places 10,000 names of registered loyalty app users into a computer program that randomly selects 500 people to receive a survey. Which sampling method is used?","options":{"A":"Quota sampling.","B":"Random sampling.","C":"Observation sampling.","D":"Secondary sampling."},"correctOption":"B","correctAnswer":"Random sampling.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because every person on the list has an equal chance of being chosen purely by chance.","distractor_reasons":{"A":"Incorrect because respondents were not selected to fill specific demographic quotas.","B":"Option B is correct because every person on the list has an equal chance of being chosen purely by chance.","C":"Incorrect because observation watches behaviour rather than sending surveys.","D":"Incorrect because this is primary survey research."}}},{"id":"P1_U3_MCQ_897","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_897","question":"Why might a business choose 'quota sampling' over 'random sampling' when conducting street interviews?","options":{"A":"Because quota sampling requires no complete list of the entire population and ensures key demographic groups are represented.","B":"Because quota sampling completely removes all human interviewer bias.","C":"Because random sampling is illegal in public shopping centres.","D":"Because quota sampling requires surveying 100% of the country's residents."},"correctOption":"A","correctAnswer":"Because quota sampling requires no complete list of the entire population and ensures key demographic groups are represented.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because researchers rarely have a full directory of every shopper, so setting age/gender quotas ensures balanced representation quickly.","distractor_reasons":{"A":"Option A is correct because researchers rarely have a full directory of every shopper, so setting age/gender quotas ensures balanced representation quickly.","B":"Incorrect because interviewers still choose whom to approach within each quota, creating potential bias.","C":"Incorrect because random sampling is legal.","D":"Incorrect because surveying 100% of residents is a census, not sampling."}}},{"id":"P1_U3_MCQ_898","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_898","question":"A survey asks respondents: 'How much money do you spend on clothes? [ ] $10-$50 [ ] $50-$100'. Why is this question flawed?","options":{"A":"The answer categories overlap at $50, causing confusion over which box to tick.","B":"It uses too many technical engineering terms.","C":"Respondents cannot answer questions about clothing purchases.","D":"It forces respondents to write a 500-word essay."},"correctOption":"A","correctAnswer":"The answer categories overlap at $50, causing confusion over which box to tick.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because overlapping numerical ranges ($10–$50 and $50–$100) create ambiguity and reduce data accuracy.","distractor_reasons":{"A":"Option A is correct because overlapping numerical ranges ($10–$50 and $50–$100) create ambiguity and reduce data accuracy.","B":"Incorrect because the wording is simple and non-technical.","C":"Incorrect because clothing expenditure is a standard consumer survey topic.","D":"Incorrect because it is a closed tick-box question."}}},{"id":"P1_U3_MCQ_899","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_899","question":"Why should a business treat 6-year-old market research data on smartphone usage with caution?","options":{"A":"Because smartphone prices never change over six years.","B":"Because consumer technology habits and competitor offerings change rapidly, making older data out of date.","C":"Because secondary data older than five years cannot be read.","D":"Because 6-year-old data is always forged by competitors."},"correctOption":"B","correctAnswer":"Because consumer technology habits and competitor offerings change rapidly, making older data out of date.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because fast-moving industries evolve quickly, so outdated secondary statistics no longer reflect current market conditions.","distractor_reasons":{"A":"Incorrect because prices and features shift constantly in electronics.","B":"Option B is correct because fast-moving industries evolve quickly, so outdated secondary statistics no longer reflect current market conditions.","C":"Incorrect because older data can still be read, though its relevance is limited.","D":"Incorrect because the limitation is obsolescence rather than deliberate forgery."}}},{"id":"P1_U3_MCQ_900","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_900","question":"Which type of product is a custom-built accounting software system sold to medium-sized businesses?","options":{"A":"Consumer convenience good.","B":"Producer service / business-to-business (B2B) product.","C":"Fast-moving consumer good (FMCG).","D":"Primary raw material."},"correctOption":"B","correctAnswer":"Producer service / business-to-business (B2B) product.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because accounting software is purchased by other businesses to support their operations rather than by household consumers.","distractor_reasons":{"A":"Incorrect because convenience goods are everyday household items like bread or soap.","B":"Option B is correct because accounting software is purchased by other businesses to support their operations rather than by household consumers.","C":"Incorrect because FMCGs are low-cost, frequently bought consumer items.","D":"Incorrect because software is a tertiary/quaternary digital product, not a raw material."}}},{"id":"P1_U3_MCQ_901","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_901","question":"How does a strong brand name help a business launch new products in the future?","options":{"A":"Consumers who already trust the brand are more willing to try new items released under the same brand name.","B":"It eliminates all research and development expenses for future products.","C":"It prevents retailers from charging any profit margin on new items.","D":"It legally stops rivals from inventing similar products."},"correctOption":"A","correctAnswer":"Consumers who already trust the brand are more willing to try new items released under the same brand name.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because positive brand reputation transfers trust to brand extensions, lowering launch resistance.","distractor_reasons":{"A":"Option A is correct because positive brand reputation transfers trust to brand extensions, lowering launch resistance.","B":"Incorrect because new products still require R&D investment.","C":"Incorrect because retailers still take margins on branded goods.","D":"Incorrect because brand names are protected by trademarks, whereas inventions require patents."}}},{"id":"P1_U3_MCQ_902","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_902","question":"Besides protecting a product from damage, how does packaging help a business comply with marketing laws?","options":{"A":"By hiding the product's weight and ingredients from shoppers.","B":"By displaying required safety warnings, ingredients, and net weight information clearly.","C":"By increasing the retail price above competitors.","D":"By preventing consumers from returning faulty goods."},"correctOption":"B","correctAnswer":"By displaying required safety warnings, ingredients, and net weight information clearly.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because consumer protection regulations require accurate labelling of contents, allergens, weights, and safety instructions on packaging.","distractor_reasons":{"A":"Incorrect because hiding weights or ingredients violates consumer laws.","B":"Option B is correct because consumer protection regulations require accurate labelling of contents, allergens, weights, and safety instructions on packaging.","C":"Incorrect because legal compliance does not mandate charging higher prices than rivals.","D":"Incorrect because packaging cannot override statutory consumer refund rights."}}},{"id":"P1_U3_MCQ_903","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_903","question":"Why do many products fail shortly after the 'introduction' stage of the Product Life Cycle?","options":{"A":"Sales growth is too fast for factories to keep up with demand.","B":"Fixed costs are zero during the launch phase.","C":"High launch promotion and R&D costs are not recovered due to weak consumer awareness or poor product-market fit.","D":"Consumers are already bored with the product after ten years on sale."},"correctOption":"C","correctAnswer":"High launch promotion and R&D costs are not recovered due to weak consumer awareness or poor product-market fit.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because cash outflows are heavy at introduction, and if buyers reject the product, losses force early withdrawal.","distractor_reasons":{"A":"Incorrect because slow initial sales, not excessive demand, cause launch failure.","B":"Incorrect because R&D and launch marketing represent heavy upfront costs.","C":"Option C is correct because cash outflows are heavy at introduction, and if buyers reject the product, losses force early withdrawal.","D":"Incorrect because long-term market saturation describes maturity or decline, not introduction."}}},{"id":"P1_U3_MCQ_904","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_904","question":"Which Product Life Cycle stage is typically associated with the highest positive cash flow and profits for a business?","options":{"A":"Development.","B":"Introduction.","C":"Maturity.","D":"Decline."},"correctOption":"C","correctAnswer":"Maturity.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because in maturity, initial R&D costs have been recovered, sales volume is at its peak, and economies of scale keep unit costs low.","distractor_reasons":{"A":"Incorrect because development has zero revenue and heavy R&D outflows.","B":"Incorrect because introduction usually makes losses due to low sales and high launch advertising.","C":"Option C is correct because in maturity, initial R&D costs have been recovered, sales volume is at its peak, and economies of scale keep unit costs low.","D":"Incorrect because falling sales and price discounts reduce profitability in decline."}}},{"id":"P1_U3_MCQ_905","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_905","question":"A chocolate bar brand has been in the maturity stage for five years and sales are starting to flatten. Which action is an effective extension strategy?","options":{"A":"Launching a limited-edition salted caramel flavour and updating the wrapper design.","B":"Removing the chocolate bar from all supermarkets.","C":"Stopping all advertising and raising the price by 50%.","D":"Reducing the cocoa quality while keeping the price unchanged."},"correctOption":"A","correctAnswer":"Launching a limited-edition salted caramel flavour and updating the wrapper design.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because introducing new flavour variations and refreshed packaging stimulates renewed consumer interest and delays decline.","distractor_reasons":{"A":"Option A is correct because introducing new flavour variations and refreshed packaging stimulates renewed consumer interest and delays decline.","B":"Incorrect because cutting distribution reduces sales immediately.","C":"Incorrect because cutting promotion while raising price accelerates decline.","D":"Incorrect because lowering quality alienates loyal customers."}}},{"id":"P1_U3_MCQ_906","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_906","question":"A bakery makes 500 loaves of artisan bread at a total cost of $1,000. If it uses cost-plus pricing with a 50% mark-up, what is the price of one loaf?","options":{"A":"$2.00","B":"$2.50","C":"$3.00","D":"$3.50"},"correctOption":"C","correctAnswer":"$3.00","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because unit cost is $1,000 / 500 = $2.00, and adding a 50% mark-up ($1.00) gives $3.00 per loaf.","distractor_reasons":{"A":"Incorrect because $2.00 is the average unit cost before adding the mark-up.","B":"Incorrect because $2.50 is only a 25% mark-up.","C":"Option C is correct because unit cost is $1,000 / 500 = $2.00, and adding a 50% mark-up ($1.00) gives $3.00 per loaf.","D":"Incorrect because $3.50 is a 75% mark-up."}}},{"id":"P1_U3_MCQ_907","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_907","question":"Why might a business using cost-plus pricing fail to make a profit even if it adds a 30% mark-up to its estimated unit cost?","options":{"A":"If actual sales volume is much lower than forecast, fixed costs per unit will be higher than expected and unsold stock may not cover overheads.","B":"Because cost-plus pricing forbids businesses from selling to retailers.","C":"Because variable costs disappear once a mark-up is added.","D":"Because 30% mark-ups are illegal in competitive markets."},"correctOption":"A","correctAnswer":"If actual sales volume is much lower than forecast, fixed costs per unit will be higher than expected and unsold stock may not cover overheads.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because average unit cost depends on assumed output; if high prices deter buyers and sales fall short, fixed costs are not fully recovered.","distractor_reasons":{"A":"Option A is correct because average unit cost depends on assumed output; if high prices deter buyers and sales fall short, fixed costs are not fully recovered.","B":"Incorrect because cost-plus pricing can be used when selling to retailers or consumers.","C":"Incorrect because variable costs still exist for every unit made.","D":"Incorrect because businesses can set any legal mark-up percentage."}}},{"id":"P1_U3_MCQ_908","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_908","question":"When is 'price skimming' most likely to succeed?","options":{"A":"When launching an identical bottle of tap water in a crowded supermarket.","B":"When launching a breakthrough medical device or gaming console with strong patent protection and eager early adopters.","C":"When clearing outdated winter coats at the end of spring.","D":"When targeting low-income shoppers in a highly price-sensitive commodity market."},"correctOption":"B","correctAnswer":"When launching a breakthrough medical device or gaming console with strong patent protection and eager early adopters.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because unique, innovative products with little immediate competition can command high prices from buyers willing to pay for the latest technology.","distractor_reasons":{"A":"Incorrect because identical commodities require competitive pricing.","B":"Option B is correct because unique, innovative products with little immediate competition can command high prices from buyers willing to pay for the latest technology.","C":"Incorrect because end-of-season clearance requires promotional markdown pricing.","D":"Incorrect because price-sensitive low-income markets require penetration or value pricing."}}},{"id":"P1_U3_MCQ_909","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_909","question":"Why do businesses using 'price skimming' usually lower their prices several months or a year after launch?","options":{"A":"To attract more price-sensitive customer segments once early adopters have bought the product and competitors enter the market.","B":"Because unit production costs always double after the first year.","C":"Because consumer protection laws force all prices down after six months.","D":"To destroy their own brand reputation for quality."},"correctOption":"A","correctAnswer":"To attract more price-sensitive customer segments once early adopters have bought the product and competitors enter the market.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because once the initial wave of high-paying early adopters is satisfied and rivals emerge, lowering the price expands sales into the wider market.","distractor_reasons":{"A":"Option A is correct because once the initial wave of high-paying early adopters is satisfied and rivals emerge, lowering the price expands sales into the wider market.","B":"Incorrect because unit costs generally fall over time due to economies of scale and experience.","C":"Incorrect because laws do not force businesses to lower prices after six months.","D":"Incorrect because gradual price reductions are planned to reach broader market segments."}}},{"id":"P1_U3_MCQ_910","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_910","question":"How does 'penetration pricing' help a new entrant overcome strong brand loyalty toward existing competitors?","options":{"A":"By charging a much higher price than established brands to look superior.","B":"By offering a noticeably lower introductory price that tempts buyers to switch and try the new brand.","C":"By refusing to advertise the product until prices are raised.","D":"By selling the product exclusively through overseas agents."},"correctOption":"B","correctAnswer":"By offering a noticeably lower introductory price that tempts buyers to switch and try the new brand.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a low launch price reduces the financial risk for consumers trying an unfamiliar brand, helping build rapid market share.","distractor_reasons":{"A":"Incorrect because charging more for an unknown brand in a crowded market deters buyers.","B":"Option B is correct because a low launch price reduces the financial risk for consumers trying an unfamiliar brand, helping build rapid market share.","C":"Incorrect because heavy promotion is needed alongside penetration pricing so buyers know about the low price.","D":"Incorrect because penetration pricing usually targets broad domestic mass distribution."}}},{"id":"P1_U3_MCQ_911","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_911","question":"Which of the following is an example of 'psychological pricing'?","options":{"A":"Raising airline ticket prices automatically when only three seats remain.","B":"Adding a 20% profit mark-up onto total factory cost.","C":"Pricing a jacket at $99.99 instead of $100.00 so consumers perceive it as significantly cheaper.","D":"Charging every customer the exact average cost of production."},"correctOption":"C","correctAnswer":"Pricing a jacket at $99.99 instead of $100.00 so consumers perceive it as significantly cheaper.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because pricing just below a round number ($99.99 vs $100) or setting high prestige prices appeals to consumer psychology rather than pure cost.","distractor_reasons":{"A":"Incorrect because real-time capacity pricing is dynamic pricing.","B":"Incorrect because adding a fixed percentage to cost is cost-plus pricing.","C":"Option C is correct because pricing just below a round number ($99.99 vs $100) or setting high prestige prices appeals to consumer psychology rather than pure cost.","D":"Incorrect because pricing at average cost leaves zero profit."}}},{"id":"P1_U3_MCQ_912","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_912","question":"A bakery calculates the total cost of producing one cake and then adds a fixed percentage to that cost to set the selling price. Which pricing method is the bakery using?","options":{"A":"Cost-plus pricing","B":"Competitive pricing","C":"Promotional pricing","D":"Loss-leader pricing"},"correctOption":"A","correctAnswer":"Cost-plus pricing","questionType":"MCQ","explanation":{"correct_reason":"Cost-plus pricing sets the price by adding a chosen percentage margin to the cost of making the product, which is exactly what the bakery does.","distractor_reasons":{"A":"Cost-plus pricing is correct because the price is based on production cost plus a fixed percentage margin.","B":"Competitive pricing sets the price by matching rivals, not by adding a margin to production cost.","C":"Promotional pricing temporarily cuts prices to attract customers, rather than building price from cost.","D":"Loss-leader pricing sells below cost to draw customers in, which is not what the bakery does."}}},{"id":"P1_U3_MCQ_913","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_913","question":"Which distribution channel is used when an airline sells flight tickets directly to passengers through its own mobile app?","options":{"A":"Producer -> Wholesaler -> Retailer -> Consumer.","B":"Producer -> Agent -> Retailer -> Consumer.","C":"Producer -> Direct to Consumer.","D":"Producer -> Wholesaler -> Consumer."},"correctOption":"C","correctAnswer":"Producer -> Direct to Consumer.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because selling via the company's own app bypasses travel agents and third-party intermediaries.","distractor_reasons":{"A":"Incorrect because no wholesalers or retailers are involved.","B":"Incorrect because travel agents are bypassed when passengers book on the airline's app.","C":"Option C is correct because selling via the company's own app bypasses travel agents and third-party intermediaries.","D":"Incorrect because no wholesaler is used."}}},{"id":"P1_U3_MCQ_914","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_914","question":"Why do small independent grocery stores rely heavily on wholesalers?","options":{"A":"Because wholesalers manufacture all food items inside their warehouses.","B":"Because manufacturers often refuse to deliver very small quantities to thousands of individual corner shops.","C":"Because laws ban small shops from buying directly from any supplier.","D":"Because wholesalers sell goods to shops completely free of charge."},"correctOption":"B","correctAnswer":"Because manufacturers often refuse to deliver very small quantities to thousands of individual corner shops.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because wholesalers break bulk, allowing small retailers to buy mixed cases of many brands in small, affordable quantities.","distractor_reasons":{"A":"Incorrect because wholesalers distribute goods made by manufacturers rather than producing them.","B":"Option B is correct because wholesalers break bulk, allowing small retailers to buy mixed cases of many brands in small, affordable quantities.","C":"Incorrect because small shops can buy directly if a producer accepts small orders, though it is rarely economical.","D":"Incorrect because wholesalers charge retailers a price that includes their wholesale profit margin."}}},{"id":"P1_U3_MCQ_915","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_915","question":"What is a disadvantage to a manufacturer of selling through large national retail chains?","options":{"A":"The product is hidden from mass-market shoppers.","B":"Large retailers have strong buying power and may demand heavy discounts, squeezing the manufacturer's profit margin.","C":"The manufacturer must deliver single items directly to every consumer's house.","D":"Retailers refuse to use barcode scanners."},"correctOption":"B","correctAnswer":"Large retailers have strong buying power and may demand heavy discounts, squeezing the manufacturer's profit margin.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because major supermarket and retail chains account for huge sales volumes, giving them bargaining power to negotiate low wholesale prices and promotional fees.","distractor_reasons":{"A":"Incorrect because national retail chains provide wide visibility to shoppers.","B":"Option B is correct because major supermarket and retail chains account for huge sales volumes, giving them bargaining power to negotiate low wholesale prices and promotional fees.","C":"Incorrect because manufacturers deliver in bulk to the retailer's distribution depots.","D":"Incorrect because large retailers use advanced EPOS barcode technology."}}},{"id":"P1_U3_MCQ_916","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_916","question":"How does using an 'agent' benefit a medium-sized manufacturer entering an unfamiliar overseas market for the first time?","options":{"A":"The agent works without receiving any commission or payment.","B":"The agent buys the manufacturer's domestic factories.","C":"The agent guarantees that foreign exchange rates will never change.","D":"The agent provides local market expertise, language fluency, and buyer contacts without requiring the manufacturer to open foreign offices."},"correctOption":"D","correctAnswer":"The agent provides local market expertise, language fluency, and buyer contacts without requiring the manufacturer to open foreign offices.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because local agents already know the foreign market's regulations, culture, and buyers, reducing entry risk and fixed overhead.","distractor_reasons":{"A":"Incorrect because agents earn a commission percentage on sales arranged.","B":"Incorrect because agents arrange sales rather than purchasing factories.","C":"Incorrect because agents have no control over currency exchange rates.","D":"Option D is correct because local agents already know the foreign market's regulations, culture, and buyers, reducing entry risk and fixed overhead."}}},{"id":"P1_U3_MCQ_917","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_917","question":"Which product is least suitable for selling solely through an e-commerce website?","options":{"A":"E-books and downloadable music tracks.","B":"Hotel room bookings and airline tickets.","C":"Freshly poured hot restaurant meals delivered 500 miles away.","D":"Standardised paperback books and computer accessories."},"correctOption":"C","correctAnswer":"Freshly poured hot restaurant meals delivered 500 miles away.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because hot prepared food spoils and cools rapidly, making long-distance parcel shipping impractical.","distractor_reasons":{"A":"Incorrect because digital downloads are ideal for e-commerce.","B":"Incorrect because travel and accommodation bookings are among the most successful e-commerce sectors.","C":"Option C is correct because hot prepared food spoils and cools rapidly, making long-distance parcel shipping impractical.","D":"Incorrect because durable packaged items ship easily via e-commerce."}}},{"id":"P1_U3_MCQ_918","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_918","question":"How can a business use its e-commerce website to improve its 'Promotion' as well as its 'Place'?","options":{"A":"By hiding all product prices until after the customer pays.","B":"By showcasing product videos, customer reviews, special online discount codes, and newsletter sign-ups.","C":"By preventing search engines from listing the website.","D":"By removing all brand logos from the homepage."},"correctOption":"B","correctAnswer":"By showcasing product videos, customer reviews, special online discount codes, and newsletter sign-ups.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a website acts simultaneously as a direct sales outlet (Place) and an interactive promotional showcase (Promotion).","distractor_reasons":{"A":"Incorrect because hiding prices is deceptive and drives visitors away.","B":"Option B is correct because a website acts simultaneously as a direct sales outlet (Place) and an interactive promotional showcase (Promotion).","C":"Incorrect because businesses use search engine optimisation to attract visitors.","D":"Incorrect because strong branding on a website reinforces brand image."}}},{"id":"P1_U3_MCQ_919","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_919","question":"What is a major advantage of radio advertising for a regional retail business?","options":{"A":"Viewers can watch high-definition video demonstrations of the product.","B":"It is much cheaper than television advertising and reaches local commuters effectively.","C":"Listeners can click directly on a radio broadcast to buy items.","D":"The advert remains visible in listeners' homes for several weeks like a magazine."},"correctOption":"B","correctAnswer":"It is much cheaper than television advertising and reaches local commuters effectively.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because local radio stations charge far less than TV while reaching regional audiences during daily drives and work hours.","distractor_reasons":{"A":"Incorrect because radio is audio-only without visual imagery.","B":"Option B is correct because local radio stations charge far less than TV while reaching regional audiences during daily drives and work hours.","C":"Incorrect because traditional radio lacks clickable links.","D":"Incorrect because radio messages are brief and transient rather than permanent like print."}}},{"id":"P1_U3_MCQ_920","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_920","question":"Why do businesses advertise in specialist trade or hobby magazines (such as cycling or photography journals)?","options":{"A":"Because specialist magazines have larger audiences than national television.","B":"Because specialist magazines are distributed free to every household in the country.","C":"Because readers already have a strong interest in that niche activity, reducing wasted advertising spend.","D":"Because specialist magazines forbid competitors from advertising."},"correctOption":"C","correctAnswer":"Because readers already have a strong interest in that niche activity, reducing wasted advertising spend.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because niche magazines reach a pre-segmented audience of enthusiasts who are much more likely to buy related products.","distractor_reasons":{"A":"Incorrect because niche magazines have much smaller circulations than national TV.","B":"Incorrect because enthusiasts typically pay to subscribe or buy specialist journals.","C":"Option C is correct because niche magazines reach a pre-segmented audience of enthusiasts who are much more likely to buy related products.","D":"Incorrect because rival brands also advertise in the same specialist publications."}}},{"id":"P1_U3_MCQ_921","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_921","question":"Which promotional method involves offering a free gift inside a cereal box or giving away a branded mug with a coffee purchase?","options":{"A":"Informative billboard advertising.","B":"Sales promotion (free gifts / premiums).","C":"Secondary market research.","D":"Price skimming."},"correctOption":"B","correctAnswer":"Sales promotion (free gifts / premiums).","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because free gifts provide an immediate short-term incentive for consumers to choose that product over rivals.","distractor_reasons":{"A":"Incorrect because billboards are outdoor media advertising.","B":"Option B is correct because free gifts provide an immediate short-term incentive for consumers to choose that product over rivals.","C":"Incorrect because giving away gifts is promotion, not data collection.","D":"Incorrect because price skimming is setting a high launch price."}}},{"id":"P1_U3_MCQ_922","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_922","question":"What is a disadvantage of using 'Buy One, Get One Free' (BOGOF) promotions for perishable food items?","options":{"A":"Customers may not be able to consume the second item before it expires, or it may simply delay their next purchase rather than increasing long-term demand.","B":"Supermarkets are legally barred from running BOGOF deals.","C":"It increases the selling price per unit for consumers.","D":"It eliminates all storage costs in the factory."},"correctOption":"A","correctAnswer":"Customers may not be able to consume the second item before it expires, or it may simply delay their next purchase rather than increasing long-term demand.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because short-term sales promotions often bring forward future purchases or lead to food waste rather than creating permanent new demand.","distractor_reasons":{"A":"Option A is correct because short-term sales promotions often bring forward future purchases or lead to food waste rather than creating permanent new demand.","B":"Incorrect because BOGOF promotions are legal.","C":"Incorrect because BOGOF halves the average price paid per item.","D":"Incorrect because factory storage costs still apply prior to delivery."}}},{"id":"P1_U3_MCQ_923","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_923","question":"Why do businesses often prefer 'Public Relations' (PR) stories in newspapers over paid advertisements?","options":{"A":"Because PR editorial coverage appears more credible to readers as independent news and avoids paying for media space.","B":"Because PR guarantees that journalists will never write anything critical.","C":"Because PR eliminates the need to have a quality product.","D":"Because paid advertisements are illegal for limited companies."},"correctOption":"A","correctAnswer":"Because PR editorial coverage appears more credible to readers as independent news and avoids paying for media space.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because consumers tend to trust news articles more than paid ads, and favourable press coverage costs far less than buying ad space.","distractor_reasons":{"A":"Option A is correct because consumers tend to trust news articles more than paid ads, and favourable press coverage costs far less than buying ad space.","B":"Incorrect because businesses cannot control exactly how independent journalists write a story.","C":"Incorrect because poor product quality will generate negative publicity.","D":"Incorrect because paid advertising is legal for all companies."}}},{"id":"P1_U3_MCQ_924","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_924","question":"How does influencer marketing on social media help a fashion or cosmetics brand?","options":{"A":"It guarantees zero returns of online clothing orders.","B":"It reaches engaged niche followers who trust the influencer's recommendations, boosting brand awareness and credibility.","C":"It eliminates all costs of manufacturing garments.","D":"It prevents competitors from creating social media accounts."},"correctOption":"B","correctAnswer":"It reaches engaged niche followers who trust the influencer's recommendations, boosting brand awareness and credibility.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because popular content creators already have the attention and trust of specific target demographics.","distractor_reasons":{"A":"Incorrect because online clothing orders still experience returns.","B":"Option B is correct because popular content creators already have the attention and trust of specific target demographics.","C":"Incorrect because manufacturing costs are unrelated to social media promotion.","D":"Incorrect because rivals can also use social media and influencers."}}},{"id":"P1_U3_MCQ_925","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_925","question":"Which factor is most important when selecting an advertising medium for a new luxury yacht?","options":{"A":"Reaching the largest possible number of school students.","B":"Choosing the cheapest possible street flyer printer.","C":"Targeting high-net-worth individuals through exclusive wealth magazines, private jet lounges, and international boat shows.","D":"Advertising on discount supermarket shopping trolleys."},"correctOption":"C","correctAnswer":"Targeting high-net-worth individuals through exclusive wealth magazines, private jet lounges, and international boat shows.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because promotional media must match the target segment's lifestyle and income while reinforcing the brand's luxury image.","distractor_reasons":{"A":"Incorrect because school students cannot afford luxury yachts.","B":"Incorrect because cheap street flyers clash with a luxury brand and miss wealthy buyers.","C":"Option C is correct because promotional media must match the target segment's lifestyle and income while reinforcing the brand's luxury image.","D":"Incorrect because supermarket trolleys target mass grocery shoppers rather than yacht buyers."}}},{"id":"P1_U3_MCQ_926","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_926","question":"A company wants to enter a new market segment of eco-conscious young professionals with a reusable insulated coffee cup. Which marketing mix is most consistent?","options":{"A":"Heavy glass mug, high skimming price, sold only by postal mail order, zero social media presence.","B":"Single-use thin plastic cup, ultra-cheap price, sold in wholesale hardware warehouses, promoted in farming newspapers.","C":"Recycled stainless-steel design, mid-to-premium price, sold via specialty coffee shops and online, promoted on Instagram.","D":"Unbranded plain cup, price doubled every week, sold exclusively in retirement homes."},"correctOption":"C","correctAnswer":"Recycled stainless-steel design, mid-to-premium price, sold via specialty coffee shops and online, promoted on Instagram.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because sustainable materials, appropriate pricing, convenient coffee-shop/online availability, and Instagram promotion all align with eco-conscious young professionals.","distractor_reasons":{"A":"Incorrect because postal mail order and lack of social media fail to reach young professionals.","B":"Incorrect because single-use plastic and farming newspapers completely miss eco-conscious young professionals.","C":"Option C is correct because sustainable materials, appropriate pricing, convenient coffee-shop/online availability, and Instagram promotion all align with eco-conscious young professionals.","D":"Incorrect because retirement homes and erratic pricing do not match the target segment."}}},{"id":"P1_U3_MCQ_927","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_927","question":"Why might a business change its marketing strategy when one of its key products enters the 'maturity' stage?","options":{"A":"To reduce distribution outlets so fewer shoppers can find the item.","B":"To stop selling the product immediately while profits are at their highest.","C":"To eliminate all quality control checks in the factory.","D":"To shift from informative launch ads to persuasive brand-loyalty promotion, competitive pricing, and extension strategies."},"correctOption":"D","correctAnswer":"To shift from informative launch ads to persuasive brand-loyalty promotion, competitive pricing, and extension strategies.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because intense competition in maturity requires defending market share through brand differentiation, competitive prices, and product extensions.","distractor_reasons":{"A":"Incorrect because wide availability is important in maturity.","B":"Incorrect because maturity is the most profitable stage and should be maintained or extended.","C":"Incorrect because maintaining quality is essential to keep loyal customers in maturity.","D":"Option D is correct because intense competition in maturity requires defending market share through brand differentiation, competitive prices, and product extensions."}}},{"id":"P1_U3_MCQ_928","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_928","question":"Which marketing objective is most appropriate for a newly established start-up business in its first year of trading?","options":{"A":"Achieving global market dominance across fifty countries immediately.","B":"Building initial brand awareness and achieving break-even sales volume.","C":"Maximising dividend payouts to international institutional shareholders.","D":"Withdrawing all products from the market."},"correctOption":"B","correctAnswer":"Building initial brand awareness and achieving break-even sales volume.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because new businesses must first make consumers aware of their existence and reach enough sales to cover costs and survive.","distractor_reasons":{"A":"Incorrect because a start-up lacks the resources for immediate global dominance.","B":"Option B is correct because new businesses must first make consumers aware of their existence and reach enough sales to cover costs and survive.","C":"Incorrect because start-ups rarely have institutional shareholders or surplus profits in year one.","D":"Incorrect because withdrawing products would end the business immediately."}}},{"id":"P1_U3_MCQ_929","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_929","question":"An electronics retailer advertises a laptop as 'Waterproof up to 10 metres', but the laptop breaks when splashed with rain. Which consumer protection principle has been breached?","options":{"A":"All electronics must be manufactured domestically.","B":"Retailers must charge the lowest price in the city.","C":"Goods must match their description and be fit for the stated purpose.","D":"Businesses must use wholesalers for all computer sales."},"correctOption":"C","correctAnswer":"Goods must match their description and be fit for the stated purpose.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because consumer laws require products to perform as advertised and match trade descriptions.","distractor_reasons":{"A":"Incorrect because imported electronics are legal.","B":"Incorrect because pricing levels are not fixed by consumer description laws.","C":"Option C is correct because consumer laws require products to perform as advertised and match trade descriptions.","D":"Incorrect because distribution channels are chosen by the business."}}},{"id":"P1_U3_MCQ_930","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_930","question":"What legal right does a consumer normally have when they purchase a brand-new washing machine that fails to work on the day it is delivered?","options":{"A":"The right to take ownership of the retailer's delivery van.","B":"The right to a full refund, repair, or replacement because the item is faulty and not of satisfactory quality.","C":"No rights at all once the receipt has been printed.","D":"The right to force the shop manager to resign."},"correctOption":"B","correctAnswer":"The right to a full refund, repair, or replacement because the item is faulty and not of satisfactory quality.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because consumer protection statutes guarantee remedies (refund, repair, or replacement) for defective goods.","distractor_reasons":{"A":"Incorrect because consumers cannot seize business assets.","B":"Option B is correct because consumer protection statutes guarantee remedies (refund, repair, or replacement) for defective goods.","C":"Incorrect because consumer rights apply after purchase when goods are faulty.","D":"Incorrect because staffing decisions belong to the employer, not shoppers."}}},{"id":"P1_U3_MCQ_931","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_931","question":"Why do governments enforce strict labelling laws on packaged food products regarding allergens and expiry dates?","options":{"A":"To protect consumer health and safety and ensure buyers have accurate information before purchasing.","B":"To make food packaging heavier and more expensive to transport.","C":"To prevent supermarkets from offering price discounts.","D":"To eliminate all competition among food manufacturers."},"correctOption":"A","correctAnswer":"To protect consumer health and safety and ensure buyers have accurate information before purchasing.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because accurate allergen and use-by labels prevent illness and help consumers make safe, informed choices.","distractor_reasons":{"A":"Option A is correct because accurate allergen and use-by labels prevent illness and help consumers make safe, informed choices.","B":"Incorrect because printing accurate labels is for safety, not adding weight.","C":"Incorrect because supermarkets can still discount food items safely within expiry dates.","D":"Incorrect because labelling rules apply equally to all competing food firms."}}},{"id":"P1_U3_MCQ_932","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_932","question":"How does entering foreign markets help extend the life of a product that is declining in its domestic market?","options":{"A":"Consumers in countries where the product has not been sold before may treat it as an exciting new innovation.","B":"Foreign governments guarantee to buy all unsold domestic inventory at double price.","C":"Exporting eliminates all production and shipping costs.","D":"Foreign consumers never switch to newer technologies."},"correctOption":"A","correctAnswer":"Consumers in countries where the product has not been sold before may treat it as an exciting new innovation.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because Product Life Cycles differ across countries; a mature or declining product at home may be in the introduction or growth stage abroad.","distractor_reasons":{"A":"Option A is correct because Product Life Cycles differ across countries; a mature or declining product at home may be in the introduction or growth stage abroad.","B":"Incorrect because foreign governments do not buy up private firms' unsold stock.","C":"Incorrect because exporting adds international shipping costs.","D":"Incorrect because foreign consumers also adopt new technologies over time."}}},{"id":"P1_U3_MCQ_933","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_933","question":"Which barrier is most likely to affect a domestic clothing retailer expanding into a country with a much hotter climate and different religious dress customs?","options":{"A":"Excessive demand for heavy woollen winter coats.","B":"Need to redesign the product range to match local climate and cultural modesty standards.","C":"Total absence of any retail shopping centres.","D":"Inability to hire local sales staff."},"correctOption":"B","correctAnswer":"Need to redesign the product range to match local climate and cultural modesty standards.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because both geographic climate and cultural norms dictate clothing fabrics, styles, and designs.","distractor_reasons":{"A":"Incorrect because hot climates reduce demand for heavy winter coats.","B":"Option B is correct because both geographic climate and cultural norms dictate clothing fabrics, styles, and designs.","C":"Incorrect because modern shopping centres exist worldwide.","D":"Incorrect because local retail staff can be recruited and trained."}}},{"id":"P1_U3_MCQ_934","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_934","question":"Why might a foreign company choose to set up a 'joint venture' with a local partner rather than opening a wholly owned branch on its own?","options":{"A":"To ensure that no local employees are ever hired.","B":"To avoid sharing any profits or control with anyone else.","C":"To avoid paying any local taxes or obeying safety regulations.","D":"To benefit from the local partner's existing distribution channels, regulatory knowledge, and brand trust while sharing set-up costs."},"correctOption":"D","correctAnswer":"To benefit from the local partner's existing distribution channels, regulatory knowledge, and brand trust while sharing set-up costs.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a local partner lowers entry barriers, speeds up market access, and shares financial risk.","distractor_reasons":{"A":"Incorrect because local partners typically employ local staff.","B":"Incorrect because joint ventures require sharing both profits and control.","C":"Incorrect because joint ventures must pay local taxes and obey all local laws.","D":"Option D is correct because a local partner lowers entry barriers, speeds up market access, and shares financial risk."}}},{"id":"P1_U3_MCQ_935","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_935","question":"How can 'licensing' overcome high import tariffs imposed by a foreign country?","options":{"A":"Because the product is manufactured locally inside the foreign country by the licensee rather than being imported across the border.","B":"Because licensed goods are exempt from all local sales taxes.","C":"Because the licensor ships goods secretly without customs declarations.","D":"Because tariffs only apply to agricultural products."},"correctOption":"A","correctAnswer":"Because the product is manufactured locally inside the foreign country by the licensee rather than being imported across the border.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because import tariffs apply to goods crossing national borders; local production by a licensee avoids import duties.","distractor_reasons":{"A":"Option A is correct because import tariffs apply to goods crossing national borders; local production by a licensee avoids import duties.","B":"Incorrect because local sales taxes (like VAT) still apply to locally produced goods.","C":"Incorrect because smuggling is illegal.","D":"Incorrect because import tariffs frequently apply to manufactured goods as well."}}},{"id":"P1_U3_MCQ_936","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_936","question":"What is a major risk for a franchisor expanding internationally through local franchisees?","options":{"A":"The franchisor must provide 100% of the capital for every overseas outlet.","B":"If one foreign franchisee delivers poor hygiene or bad customer service, it can damage the global brand's reputation.","C":"Franchisees are prohibited from adapting any menu items even with franchisor approval.","D":"The franchisor receives no initial fee or ongoing royalty payments."},"correctOption":"B","correctAnswer":"If one foreign franchisee delivers poor hygiene or bad customer service, it can damage the global brand's reputation.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because consumers view all outlets under the same brand name as one company, so misconduct at one branch harms the entire chain.","distractor_reasons":{"A":"Incorrect because franchisees invest their own capital to open outlets.","B":"Option B is correct because consumers view all outlets under the same brand name as one company, so misconduct at one branch harms the entire chain.","C":"Incorrect because franchisors often approve local menu adaptations to suit regional tastes.","D":"Incorrect because franchisees pay initial licence fees and ongoing royalties."}}},{"id":"P1_U3_MCQ_937","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_937","question":"When evaluating a proposed marketing strategy, why is checking the 'marketing budget' essential?","options":{"A":"Because a large budget guarantees that consumers will love a faulty product.","B":"Because laws require every business to spend at least half its revenue on TV ads.","C":"To ensure that the chosen promotional campaigns, research, and distribution channels are financially affordable and generate a positive return.","D":"Because marketing budgets eliminate all fixed factory overheads."},"correctOption":"C","correctAnswer":"To ensure that the chosen promotional campaigns, research, and distribution channels are financially affordable and generate a positive return.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because an effective marketing strategy must be realistic within the firm's financial resources and earn more profit than it costs.","distractor_reasons":{"A":"Incorrect because heavy spending cannot save a defective product.","B":"Incorrect because no law mandates spending 50% of revenue on advertising.","C":"Option C is correct because an effective marketing strategy must be realistic within the firm's financial resources and earn more profit than it costs.","D":"Incorrect because marketing budgets allocate promotional funds rather than removing factory overheads."}}},{"id":"P1_U3_MCQ_938","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_938","question":"How does the marketing department help a food manufacturer respond to growing consumer concern about plastic waste?","options":{"A":"By increasing factory production of single-use plastic wrappers to lower unit costs.","B":"By anticipating the shift in customer preferences and recommending biodegradable packaging before sales decline.","C":"By hiding ingredient and packaging material details from supermarket labels.","D":"By stopping all market research until sales fall by 50%."},"correctOption":"B","correctAnswer":"By anticipating the shift in customer preferences and recommending biodegradable packaging before sales decline.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because a core role of marketing is identifying and anticipating evolving customer needs so the business can adapt its products proactively.","distractor_reasons":{"A":"Incorrect because producing more unwanted single-use plastic ignores changing consumer values.","B":"Option B is correct because a core role of marketing is identifying and anticipating evolving customer needs so the business can adapt its products proactively.","C":"Incorrect because hiding material information alienates eco-conscious buyers and risks breaching labelling rules.","D":"Incorrect because waiting until sales collapse delays necessary product adaptation."}}},{"id":"P1_U3_MCQ_939","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_939","question":"Why is maintaining customer loyalty often more profitable for a business than constantly searching for brand-new customers?","options":{"A":"Loyal customers never compare prices or product quality.","B":"Existing satisfied customers make repeat purchases and require lower advertising expenditure per sale than attracting new buyers.","C":"Customer loyalty eliminates all fixed overhead expenses.","D":"Businesses are legally prohibited from advertising to existing customers."},"correctOption":"B","correctAnswer":"Existing satisfied customers make repeat purchases and require lower advertising expenditure per sale than attracting new buyers.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because retaining current customers generates steady repeat revenue and positive word-of-mouth at a much lower marketing cost than acquiring first-time buyers.","distractor_reasons":{"A":"Incorrect because loyal customers still expect good value and quality.","B":"Option B is correct because retaining current customers generates steady repeat revenue and positive word-of-mouth at a much lower marketing cost than acquiring first-time buyers.","C":"Incorrect because fixed overheads remain regardless of repeat purchases.","D":"Incorrect because businesses regularly market new offers to existing customers."}}},{"id":"P1_U3_MCQ_940","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_940","question":"Total annual sales in the domestic bottled water market are $60 million. Company A records annual sales of $15 million. What is Company A's market share?","options":{"A":"15%","B":"20%","C":"25%","D":"40%"},"correctOption":"C","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Market Share = ($15 million / $60 million) x 100 = 25%.","distractor_reasons":{"A":"Incorrect because 15% of $60 million is $9 million.","B":"Incorrect because 20% of $60 million is $12 million.","C":"Option C is correct because Market Share = ($15 million / $60 million) x 100 = 25%.","D":"Incorrect because 40% of $60 million is $24 million."}}},{"id":"P1_U3_MCQ_941","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_941","question":"What is a key commercial advantage of being the market leader with the highest market share in an industry?","options":{"A":"Retailers are eager to stock the leading brand, and high sales volumes enable purchasing and marketing economies of scale.","B":"The business no longer needs to develop new products or maintain quality.","C":"The market leader is exempt from paying corporation tax.","D":"Competitors are legally banned from lowering their prices."},"correctOption":"A","correctAnswer":"Retailers are eager to stock the leading brand, and high sales volumes enable purchasing and marketing economies of scale.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because dominant market share gives strong negotiating power with retailers, high brand visibility, and lower unit costs from large-scale output.","distractor_reasons":{"A":"Option A is correct because dominant market share gives strong negotiating power with retailers, high brand visibility, and lower unit costs from large-scale output.","B":"Incorrect because market leaders must keep innovating to defend their position.","C":"Incorrect because market leaders pay taxes like all other profitable businesses.","D":"Incorrect because rivals can still compete aggressively on price."}}},{"id":"P1_U3_MCQ_942","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_942","question":"How does an ageing population in a developed country affect consumer spending patterns?","options":{"A":"All businesses switch to producing only children's toys.","B":"Consumers spend all their income exclusively on high-school textbooks.","C":"Demand for mobility aids and pharmaceutical products drops to zero.","D":"Demand increases for healthcare services, retirement holidays, and accessible housing, while demand for baby products may fall."},"correctOption":"D","correctAnswer":"Demand increases for healthcare services, retirement holidays, and accessible housing, while demand for baby products may fall.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because demographic changes shift market demand toward goods and services tailored to older age groups.","distractor_reasons":{"A":"Incorrect because businesses adapt toward growing senior segments rather than shrinking child segments.","B":"Incorrect because an ageing population reduces, rather than increases, the proportion of school-age students.","C":"Incorrect because an older population increases demand for healthcare and mobility products.","D":"Option D is correct because demographic changes shift market demand toward goods and services tailored to older age groups."}}},{"id":"P1_U3_MCQ_943","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_943","question":"Which development has made many consumer markets significantly more competitive in recent years?","options":{"A":"Consumers refusing to compare prices before buying expensive items.","B":"The complete removal of internet access in major cities.","C":"Government bans on international trade across all countries.","D":"The growth of e-commerce and globalisation, allowing overseas and online rivals to reach local shoppers easily."},"correctOption":"D","correctAnswer":"The growth of e-commerce and globalisation, allowing overseas and online rivals to reach local shoppers easily.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because online selling lowers entry barriers and international trade exposes local firms to global competitors.","distractor_reasons":{"A":"Incorrect because comparison websites make it easier for shoppers to compare prices.","B":"Incorrect because internet access has expanded rapidly.","C":"Incorrect because international trade has grown rather than been banned.","D":"Option D is correct because online selling lowers entry barriers and international trade exposes local firms to global competitors."}}},{"id":"P1_U3_MCQ_944","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_944","question":"How can an established high-street bookstore best respond to intense price competition from large online retailers?","options":{"A":"By offering signed author events, a cosy in-store café, and expert staff recommendations that online sites cannot replicate.","B":"By closing the shop every Saturday when shoppers are free to visit.","C":"By raising book prices 40% above the cover price without offering any extra service.","D":"By removing all signs and window displays outside the store."},"correctOption":"A","correctAnswer":"By offering signed author events, a cosy in-store café, and expert staff recommendations that online sites cannot replicate.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because differentiating through customer experience and community events adds value where small retailers cannot win a pure price war.","distractor_reasons":{"A":"Option A is correct because differentiating through customer experience and community events adds value where small retailers cannot win a pure price war.","B":"Incorrect because closing on peak shopping days reduces sales further.","C":"Incorrect because raising prices without added value drives customers away.","D":"Incorrect because poor visibility reduces walk-in customer footfall."}}},{"id":"P1_U3_MCQ_945","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_945","question":"Why are businesses operating in a niche market often able to charge higher profit margins than mass-market firms?","options":{"A":"Specialised products meet exact buyer requirements with fewer direct competitors, making customers less price-sensitive.","B":"Niche businesses always produce millions of standardised units per day.","C":"Suppliers charge niche firms zero money for raw materials.","D":"Niche businesses never pay rent or wages."},"correctOption":"A","correctAnswer":"Specialised products meet exact buyer requirements with fewer direct competitors, making customers less price-sensitive.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because customers with specific needs value tailored solutions and face limited alternatives, supporting premium pricing.","distractor_reasons":{"A":"Option A is correct because customers with specific needs value tailored solutions and face limited alternatives, supporting premium pricing.","B":"Incorrect because high-volume standardised output describes mass markets.","C":"Incorrect because niche firms still pay for specialised materials.","D":"Incorrect because niche businesses still incur normal operating overheads."}}},{"id":"P1_U3_MCQ_946","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_946","question":"What is a major limitation of operating exclusively in a small niche market?","options":{"A":"Customers are forced to buy identical standardised products.","B":"The business must advertise on every national television channel simultaneously.","C":"Low sales volumes limit opportunities to achieve economies of scale, keeping average unit costs relatively high.","D":"The business faces hundreds of giant multinational rivals in that tiny segment."},"correctOption":"C","correctAnswer":"Low sales volumes limit opportunities to achieve economies of scale, keeping average unit costs relatively high.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because a small customer base restricts total output, preventing bulk-buying and mass-production cost savings.","distractor_reasons":{"A":"Incorrect because niche products are tailored rather than standardised.","B":"Incorrect because niche firms use targeted, low-cost specialist media rather than national TV.","C":"Option C is correct because a small customer base restricts total output, preventing bulk-buying and mass-production cost savings.","D":"Incorrect because large multinationals usually avoid small niches due to limited revenue potential."}}},{"id":"P1_U3_MCQ_947","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_947","question":"What is a primary advantage for a business targeting a mass market?","options":{"A":"High sales volumes allow the business to benefit from economies of scale, lowering average cost per unit.","B":"There is zero competition from other brands.","C":"Every customer receives a custom-made, one-of-a-kind product.","D":"No advertising or promotion is ever required."},"correctOption":"A","correctAnswer":"High sales volumes allow the business to benefit from economies of scale, lowering average cost per unit.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because selling standardised goods to a huge customer base generates high output and lowers unit costs.","distractor_reasons":{"A":"Option A is correct because selling standardised goods to a huge customer base generates high output and lowers unit costs.","B":"Incorrect because mass markets typically attract intense competition.","C":"Incorrect because mass-market products are standardised rather than bespoke.","D":"Incorrect because mass-market brands invest heavily in promotion to stand out."}}},{"id":"P1_U3_MCQ_948","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_948","question":"What is a major disadvantage of selling a single standardised product in a mass market?","options":{"A":"Supermarkets refuse to stock well-known mass-market brands.","B":"The business cannot use automated flow production.","C":"Unit production costs are always higher than bespoke job production.","D":"Fierce competition often forces lower prices and smaller profit margins, while specific consumer tastes may go unsatisfied."},"correctOption":"D","correctAnswer":"Fierce competition often forces lower prices and smaller profit margins, while specific consumer tastes may go unsatisfied.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because rival firms target the same large audience with similar goods, driving price competition and leaving specialised preferences unmet.","distractor_reasons":{"A":"Incorrect because supermarkets rely heavily on fast-selling mass-market goods.","B":"Incorrect because standardised mass-market goods are ideal for flow production.","C":"Incorrect because mass production achieves much lower unit costs than job production.","D":"Option D is correct because rival firms target the same large audience with similar goods, driving price competition and leaving specialised preferences unmet."}}},{"id":"P1_U3_MCQ_949","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_949","question":"An airline divides passengers into Economy Class, Business Class, and First Class cabins on the same flight. Which type of segmentation is this?","options":{"A":"Age segmentation.","B":"Gender segmentation.","C":"Income / socio-economic segmentation.","D":"Climate segmentation."},"correctOption":"C","correctAnswer":"Income / socio-economic segmentation.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because cabin classes separate travellers according to their income levels and willingness to pay for comfort and extra services.","distractor_reasons":{"A":"Incorrect because cabin classes are based on ticket price and income rather than passenger age.","B":"Incorrect because cabin classes are open to all genders.","C":"Option C is correct because cabin classes separate travellers according to their income levels and willingness to pay for comfort and extra services.","D":"Incorrect because all passengers on the same flight travel to the same destination."}}},{"id":"P1_U3_MCQ_950","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_950","question":"Why do businesses carry out market research before investing heavily in launching a new product?","options":{"A":"To guarantee with 100% certainty that competitors will go bankrupt.","B":"To reduce the risk of product failure by checking customer demand, preferred features, and acceptable price levels.","C":"To eliminate all fixed factory costs.","D":"To avoid having to pay for product packaging."},"correctOption":"B","correctAnswer":"To reduce the risk of product failure by checking customer demand, preferred features, and acceptable price levels.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because gathering evidence on buyer preferences and market size prevents wasting capital on unwanted products.","distractor_reasons":{"A":"Incorrect because market research reduces risk but cannot guarantee rival bankruptcy.","B":"Option B is correct because gathering evidence on buyer preferences and market size prevents wasting capital on unwanted products.","C":"Incorrect because fixed costs still exist when producing goods.","D":"Incorrect because packaging is still required for distribution and protection."}}},{"id":"P1_U3_MCQ_951","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_951","question":"What happens to a strictly 'product-oriented' business if consumer tastes suddenly shift toward a new style of product?","options":{"A":"It risks losing significant sales because it focuses on what its engineers can make rather than researching what customers want.","B":"It automatically spots the trend first through daily customer focus groups.","C":"Its profit margins double even when nobody buys its products.","D":"It immediately switches its entire product range every morning."},"correctOption":"A","correctAnswer":"It risks losing significant sales because it focuses on what its engineers can make rather than researching what customers want.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because product-oriented firms concentrate on technical product features first and neglect ongoing consumer research.","distractor_reasons":{"A":"Option A is correct because product-oriented firms concentrate on technical product features first and neglect ongoing consumer research.","B":"Incorrect because continuous customer focus groups describe a market-oriented business.","C":"Incorrect because unsold goods generate losses rather than profits.","D":"Incorrect because product-oriented businesses are slow to adapt to shifting consumer trends."}}},{"id":"P1_U3_MCQ_952","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_952","question":"A supermarket manager watches how shoppers move through aisles and which shelves they pause at without asking them any questions. What is a limitation of this 'observation' method?","options":{"A":"It shows what shoppers actually do, but cannot explain the reasons behind their choices.","B":"Shoppers lie about their answers during silent observation.","C":"It requires printing 50,000 paper questionnaires.","D":"It can only be used for online digital software."},"correctOption":"A","correctAnswer":"It shows what shoppers actually do, but cannot explain the reasons behind their choices.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because observation records real behaviour accurately, but without questioning shoppers, researchers do not know *why* they ignored or picked an item.","distractor_reasons":{"A":"Option A is correct because observation records real behaviour accurately, but without questioning shoppers, researchers do not know *why* they ignored or picked an item.","B":"Incorrect because no questions are asked in pure observation.","C":"Incorrect because observation does not use questionnaires.","D":"Incorrect because observation works both in physical stores and via website analytics."}}},{"id":"P1_U3_MCQ_953","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_953","question":"What is a major advantage of using 'online surveys' for primary market research?","options":{"A":"Interviewers can physically hand product samples to respondents through the screen.","B":"Every elderly resident without internet access is guaranteed to respond.","C":"Large numbers of responses can be collected quickly at very low cost, and results are automatically tabulated by software.","D":"Respondents spend two hours writing detailed essays on every question."},"correctOption":"C","correctAnswer":"Large numbers of responses can be collected quickly at very low cost, and results are automatically tabulated by software.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because online questionnaires eliminate printing, postage, and interviewer travel expenses while speeding up data analysis.","distractor_reasons":{"A":"Incorrect because physical samples cannot be handed over via an online link.","B":"Incorrect because people without internet access are excluded from online surveys.","C":"Option C is correct because online questionnaires eliminate printing, postage, and interviewer travel expenses while speeding up data analysis.","D":"Incorrect because online respondents usually prefer short, quick surveys."}}},{"id":"P1_U3_MCQ_954","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_954","question":"Why might a snack company launch a new crisp flavour in just two cities ('test marketing') before rolling it out nationwide?","options":{"A":"To ensure competitors have plenty of time to copy the flavour nationwide first.","B":"Because laws ban selling snacks in more than two cities during the first five years.","C":"To measure real customer repeat purchases and fix any taste or packaging flaws before spending millions on national production and TV ads.","D":"To avoid paying any taxes on snack sales."},"correctOption":"C","correctAnswer":"To measure real customer repeat purchases and fix any taste or packaging flaws before spending millions on national production and TV ads.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because test marketing trials the full marketing mix in a small representative area, reducing the financial cost of a nationwide failure.","distractor_reasons":{"A":"Incorrect because giving rivals time to copy is actually a disadvantage of test marketing.","B":"Incorrect because no law restricts nationwide launches.","C":"Option C is correct because test marketing trials the full marketing mix in a small representative area, reducing the financial cost of a nationwide failure.","D":"Incorrect because taxes still apply to test-market sales."}}},{"id":"P1_U3_MCQ_955","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_955","question":"Which of the following is an 'internal' source of secondary market research data?","options":{"A":"The business's own past sales records and customer loyalty card purchase histories.","B":"A national population census published by the government.","C":"An industry trend report sold by a private market research agency.","D":"Articles published in a national financial newspaper."},"correctOption":"A","correctAnswer":"The business's own past sales records and customer loyalty card purchase histories.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because internal secondary data already exists inside the business's own files and databases.","distractor_reasons":{"A":"Option A is correct because internal secondary data already exists inside the business's own files and databases.","B":"Incorrect because government census data is an external secondary source.","C":"Incorrect because research agency reports are external secondary sources.","D":"Incorrect because newspapers are external secondary sources."}}},{"id":"P1_U3_MCQ_956","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_956","question":"Which of the following is an 'external' source of secondary market research data?","options":{"A":"Street interviews conducted this morning by the firm's marketing team.","B":"The company's own accounting ledger of last month's sales.","C":"Feedback collected yesterday from a focus group hired by the business.","D":"Industry reports published by trade associations and market research agencies."},"correctOption":"D","correctAnswer":"Industry reports published by trade associations and market research agencies.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because trade association publications and research agency reports are compiled by outside organisations and already exist.","distractor_reasons":{"A":"Incorrect because new street interviews are primary research.","B":"Incorrect because internal sales ledgers are internal secondary data.","C":"Incorrect because a newly run focus group is primary research.","D":"Option D is correct because trade association publications and research agency reports are compiled by outside organisations and already exist."}}},{"id":"P1_U3_MCQ_957","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_957","question":"What is a major disadvantage of relying solely on external secondary data when designing a brand-new product?","options":{"A":"Secondary data is always more expensive than hiring an agency to conduct nationwide face-to-face interviews.","B":"The data was collected for another purpose, may not answer specific questions about the new product, and is also available to competitors.","C":"Secondary data never contains any numerical statistics.","D":"It takes ten years to download a government report from the internet."},"correctOption":"B","correctAnswer":"The data was collected for another purpose, may not answer specific questions about the new product, and is also available to competitors.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because existing external data is general rather than tailored to a firm's specific product idea, and rivals can access the exact same information.","distractor_reasons":{"A":"Incorrect because secondary data is usually much cheaper than primary research.","B":"Option B is correct because existing external data is general rather than tailored to a firm's specific product idea, and rivals can access the exact same information.","C":"Incorrect because secondary sources frequently provide rich quantitative statistics.","D":"Incorrect because secondary desk research is quick to access."}}},{"id":"P1_U3_MCQ_958","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_958","question":"Why do many businesses combine 'quantitative' and 'qualitative' research methods?","options":{"A":"Laws prohibit using only one type of research data.","B":"Quantitative data provides emotional stories, while qualitative data provides only financial balance sheets.","C":"Combining both methods eliminates the need to choose a sample.","D":"Quantitative data measures how many customers hold a view, while qualitative data explains why they feel that way."},"correctOption":"D","correctAnswer":"Quantitative data measures how many customers hold a view, while qualitative data explains why they feel that way.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because using both gives statistical breadth (numbers/percentages) alongside psychological depth (reasons/opinions).","distractor_reasons":{"A":"Incorrect because businesses freely choose whichever research methods suit their budget.","B":"Incorrect because this reverses the meanings of quantitative and qualitative data.","C":"Incorrect because both surveys and focus groups still require selecting samples.","D":"Option D is correct because using both gives statistical breadth (numbers/percentages) alongside psychological depth (reasons/opinions)."}}},{"id":"P1_U3_MCQ_959","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_959","question":"Why do businesses survey a 'sample' of consumers rather than asking every single potential buyer in the country?","options":{"A":"It is illegal to ask more than 1,000 consumers for their opinion.","B":"A sample of 5 people is always more accurate than asking 50,000 people.","C":"Computers cannot process more than 100 survey responses.","D":"Surveying the entire population would be far too expensive and time-consuming, delaying product launch decisions."},"correctOption":"D","correctAnswer":"Surveying the entire population would be far too expensive and time-consuming, delaying product launch decisions.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because a well-chosen representative sample provides reliable estimates quickly and at a fraction of the cost of a full census.","distractor_reasons":{"A":"Incorrect because no law caps survey sample sizes.","B":"Incorrect because tiny samples have high sampling error and poor accuracy.","C":"Incorrect because modern software easily analyses millions of responses.","D":"Option D is correct because a well-chosen representative sample provides reliable estimates quickly and at a fraction of the cost of a full census."}}},{"id":"P1_U3_MCQ_960","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_960","question":"A firm wants random sampling to survey buyers of a new snack nationwide but has no complete list of all customers. What practical problem does this create?","options":{"A":"Questionnaires cannot be used alongside random samples","B":"Random sampling can only be carried out online","C":"Quota sampling can never produce useful information","D":"Without a full list, not every customer can have an equal chance of selection"},"correctOption":"D","correctAnswer":"Without a full list, not every customer can have an equal chance of selection","questionType":"MCQ","explanation":{"correct_reason":"Random sampling needs a complete sampling frame so that each member of the population has a known, equal chance of being selected.","distractor_reasons":{"B":"Random sampling is a selection method and can be applied offline or online, so the channel is not the obstacle.","C":"The question concerns the requirement of a list for random selection, not the usefulness of quota sampling.","D":"Random sampling needs a complete sampling frame so that each member of the population has a known, equal chance of being selected.","A":"Questionnaires are frequently used with random samples; the missing list, not the questionnaire, is the difficulty."}}},{"id":"P1_U3_MCQ_961","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_961","question":"An interviewer in a shopping mall is instructed to survey 40 men and 40 women, with half aged under 35 and half aged 35 or over. Which sampling method is being used?","options":{"A":"Quota sampling.","B":"Random sampling.","C":"Test marketing.","D":"Secondary desk sampling."},"correctOption":"A","correctAnswer":"Quota sampling.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the target population is segmented by characteristics (gender and age) and specific numerical quotas are filled for each group.","distractor_reasons":{"A":"Option A is correct because the target population is segmented by characteristics (gender and age) and specific numerical quotas are filled for each group.","B":"Incorrect because respondents are chosen to fill demographic quotas rather than purely by chance from a full list.","C":"Incorrect because test marketing trials selling a product in a region.","D":"Incorrect because this is primary field research."}}},{"id":"P1_U3_MCQ_962","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_962","question":"Why might the results of a street questionnaire about healthy eating habits be inaccurate even with a large sample size?","options":{"A":"Respondents may give socially desirable answers (claiming they eat more vegetables than they really do) or questions may be worded in a leading way.","B":"Large sample sizes always produce less accurate data than tiny samples.","C":"Street questionnaires cannot ask any closed-ended questions.","D":"Healthy food manufacturers are banned from conducting surveys."},"correctOption":"A","correctAnswer":"Respondents may give socially desirable answers (claiming they eat more vegetables than they really do) or questions may be worded in a leading way.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because respondent dishonesty/embarrassment and biased question phrasing distort primary data accuracy.","distractor_reasons":{"A":"Option A is correct because respondent dishonesty/embarrassment and biased question phrasing distort primary data accuracy.","B":"Incorrect because larger representative samples generally improve statistical reliability.","C":"Incorrect because street questionnaires routinely use closed questions.","D":"Incorrect because food businesses regularly run consumer surveys."}}},{"id":"P1_U3_MCQ_963","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_963","question":"What is a major benefit to a business of regularly developing new products?","options":{"A":"It guarantees that every new product will become an instant bestseller.","B":"It requires zero spending on research, prototypes, or market testing.","C":"It creates a Unique Selling Point (USP), diversifies risk across multiple products, and attracts new customers.","D":"It eliminates all competition in the industry."},"correctOption":"C","correctAnswer":"It creates a Unique Selling Point (USP), diversifies risk across multiple products, and attracts new customers.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because continuous product innovation keeps the brand competitive, reduces reliance on one ageing product, and opens new revenue streams.","distractor_reasons":{"A":"Incorrect because many new products fail after launch.","B":"Incorrect because R&D and testing are costly and time-consuming.","C":"Option C is correct because continuous product innovation keeps the brand competitive, reduces reliance on one ageing product, and opens new revenue streams.","D":"Incorrect because rivals also innovate."}}},{"id":"P1_U3_MCQ_964","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_964","question":"A sportswear company uses a distinctive logo, consistent quality and stylish packaging so that customers recognise and trust its products. What is the company building?","options":{"A":"A strong brand","B":"A lower unit cost","C":"A wider distribution network","D":"A competitive price"},"correctOption":"A","correctAnswer":"A strong brand","questionType":"MCQ","explanation":{"correct_reason":"A brand is built through identifiable features such as a logo, consistent quality and packaging that create customer recognition and trust.","distractor_reasons":{"A":"This is correct: a logo, consistent quality and packaging are used to build a strong, recognisable brand.","B":"Lower unit costs come from production efficiency, not from logos or packaging.","C":"A distribution network concerns where products are sold, not how they are presented.","D":"Setting a competitive price is a pricing decision, not the result of building recognition and trust."}}},{"id":"P1_U3_MCQ_965","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_965","question":"How can innovative packaging directly increase sales of a liquid laundry detergent?","options":{"A":"Using fragile glass bottles increases excitement during delivery.","B":"Making the bottle heavy and impossible to open discourages rival brands.","C":"Removing the brand logo and usage instructions saves ink costs.","D":"An easy-pour, non-drip spout with a measuring cap makes the product more convenient to use and stands out on supermarket shelves."},"correctOption":"D","correctAnswer":"An easy-pour, non-drip spout with a measuring cap makes the product more convenient to use and stands out on supermarket shelves.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because functional, convenient, and eye-catching packaging adds practical value for shoppers and attracts attention at the point of sale.","distractor_reasons":{"A":"Incorrect because fragile packaging increases breakage and transport waste.","B":"Incorrect because inconvenient packaging frustrates customers and hurts repeat sales.","C":"Incorrect because brand recognition and clear instructions are essential functions of packaging.","D":"Option D is correct because functional, convenient, and eye-catching packaging adds practical value for shoppers and attracts attention at the point of sale."}}},{"id":"P1_U3_MCQ_966","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_966","question":"What happens to cash flow during the 'development' stage of the Product Life Cycle?","options":{"A":"Cash flow is heavily negative because the business spends money on R&D and prototypes while earning zero sales revenue.","B":"Cash flow reaches its highest positive peak.","C":"Sales revenue grows rapidly while R&D spending stops.","D":"The business clears leftover inventory at discounted prices."},"correctOption":"A","correctAnswer":"Cash flow is heavily negative because the business spends money on R&D and prototypes while earning zero sales revenue.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because the product has not yet been launched to buyers, so outflows occur with no offsetting sales inflows.","distractor_reasons":{"A":"Option A is correct because the product has not yet been launched to buyers, so outflows occur with no offsetting sales inflows.","B":"Incorrect because peak positive cash flow occurs in the maturity stage.","C":"Incorrect because rapid sales growth describes the growth stage.","D":"Incorrect because clearance discounting happens in the decline stage."}}},{"id":"P1_U3_MCQ_967","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_967","question":"Which feature is characteristic of the 'growth' stage of the Product Life Cycle?","options":{"A":"Sales rise rapidly as awareness spreads, profits start to appear, and competitors begin launching rival versions.","B":"Sales fall steadily toward zero as the product becomes obsolete.","C":"The product is still being tested secretly inside a laboratory.","D":"No retail shops agree to stock the product."},"correctOption":"A","correctAnswer":"Sales rise rapidly as awareness spreads, profits start to appear, and competitors begin launching rival versions.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because rapid adoption drives fast revenue growth and unit cost reductions, attracting imitators into the market.","distractor_reasons":{"A":"Option A is correct because rapid adoption drives fast revenue growth and unit cost reductions, attracting imitators into the market.","B":"Incorrect because falling sales toward obsolescence describe the decline stage.","C":"Incorrect because laboratory testing describes the development stage.","D":"Incorrect because distribution expands rapidly during the growth stage."}}},{"id":"P1_U3_MCQ_968","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_968","question":"Sales of a DVD rental service have fallen steadily as streaming becomes popular. Which factor best explains this decline?","options":{"A":"Changing customer preferences and new technology make the product outdated","B":"The product has just entered its introduction stage","C":"The company has sharply increased its advertising","D":"The rental price has been falling steadily"},"correctOption":"A","correctAnswer":"Changing customer preferences and new technology make the product outdated","questionType":"MCQ","explanation":{"correct_reason":"When customers switch to a newer technology and tastes change, demand for the old product falls, producing the decline stage.","distractor_reasons":{"B":"Falling sales indicate the end of the life cycle, not the introduction stage where sales begin to grow.","C":"More advertising would normally aim to support sales rather than explain a sustained fall in demand.","D":"A steady price fall alone does not account for declining sales caused by a superior alternative.","A":"When customers switch to a newer technology and tastes change, demand for the old product falls, producing the decline stage."}}},{"id":"P1_U3_MCQ_969","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_969","question":"A manufacturer of baking soda promotes new uses for its product—such as deodorising refrigerators and cleaning carpets—to boost flattening sales. Which strategy is this?","options":{"A":"Quota sampling.","B":"Price skimming.","C":"Product withdrawal.","D":"An extension strategy."},"correctOption":"D","correctAnswer":"An extension strategy.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because finding new uses or new market segments for an existing mature product revitalises demand and extends its life cycle.","distractor_reasons":{"A":"Incorrect because quota sampling is a market research technique.","B":"Incorrect because price skimming sets a high launch price for a new innovation.","C":"Incorrect because product withdrawal removes an item from sale.","D":"Option D is correct because finding new uses or new market segments for an existing mature product revitalises demand and extends its life cycle."}}},{"id":"P1_U3_MCQ_970","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_970","question":"A firm produces 1,000 units of a toy with monthly fixed costs of $4,000 and variable costs of $3 per unit. If it applies a 40% cost-plus mark-up, what is the selling price per toy?","options":{"A":"$7.00","B":"$8.40","C":"$9.80","D":"$10.50"},"correctOption":"C","correctAnswer":"$9.80","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because Total Cost = $4,000 + (1,000 x $3) = $7,000; Unit Cost = $7,000 / 1,000 = $7.00; adding a 40% mark-up ($2.80) gives $9.80.","distractor_reasons":{"A":"Incorrect because $7.00 is the average unit cost before adding the 40% profit mark-up.","B":"Incorrect because $8.40 represents a 20% mark-up ($7.00 + $1.40).","C":"Option C is correct because Total Cost = $4,000 + (1,000 x $3) = $7,000; Unit Cost = $7,000 / 1,000 = $7.00; adding a 40% mark-up ($2.80) gives $9.80.","D":"Incorrect because $10.50 represents a 50% mark-up ($7.00 + $3.50)."}}},{"id":"P1_U3_MCQ_971","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_971","question":"What is a major weakness of 'cost-plus pricing' in a competitive consumer market?","options":{"A":"It is illegal for retail businesses to use cost-plus pricing.","B":"It is too complicated to calculate even when unit costs are known.","C":"It guarantees that the business makes zero profit on every item sold.","D":"It ignores competitors' prices and what customers are actually willing to pay, risking an uncompetitive price if costs are high."},"correctOption":"D","correctAnswer":"It ignores competitors' prices and what customers are actually willing to pay, risking an uncompetitive price if costs are high.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because cost-plus pricing looks only at internal costs rather than market demand or rival prices.","distractor_reasons":{"A":"Incorrect because cost-plus pricing is legal and widely used.","B":"Incorrect because simplicity of calculation is actually the main advantage of cost-plus pricing.","C":"Incorrect because adding a mark-up aims to build a profit margin above unit cost.","D":"Option D is correct because cost-plus pricing looks only at internal costs rather than market demand or rival prices."}}},{"id":"P1_U3_MCQ_972","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_972","question":"When is 'competitive pricing' most appropriate for a business?","options":{"A":"When selling a product in a market with many close substitutes where consumers can easily compare prices.","B":"When the business holds a global patent on a life-saving medicine with zero competitors.","C":"When selling a one-of-a-kind historical painting at an auction.","D":"When production costs are higher than every competitor's selling price."},"correctOption":"A","correctAnswer":"When selling a product in a market with many close substitutes where consumers can easily compare prices.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because in markets with similar competing products, charging noticeably more than rivals causes customers to switch immediately.","distractor_reasons":{"A":"Option A is correct because in markets with similar competing products, charging noticeably more than rivals causes customers to switch immediately.","B":"Incorrect because a patented breakthrough with no rivals allows price skimming.","C":"Incorrect because unique items have no direct substitutes.","D":"Incorrect because matching low rival prices when unit costs are higher would result in losses."}}},{"id":"P1_U3_MCQ_973","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_973","question":"What is a potential risk of using 'penetration pricing' when launching a new product?","options":{"A":"Profit margins are very low initially, and price-sensitive customers may stop buying once the introductory price is raised.","B":"Customers refuse to try the product because the price is too low.","C":"Fixed factory overheads disappear completely.","D":"The business gains too much market share too quickly."},"correctOption":"A","correctAnswer":"Profit margins are very low initially, and price-sensitive customers may stop buying once the introductory price is raised.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because low launch prices delay cost recovery and attract bargain hunters who may switch away when prices rise later.","distractor_reasons":{"A":"Option A is correct because low launch prices delay cost recovery and attract bargain hunters who may switch away when prices rise later.","B":"Incorrect because low introductory prices generally encourage trial, except for luxury prestige goods.","C":"Incorrect because fixed overheads remain unchanged.","D":"Incorrect because gaining market share quickly is the intended goal of penetration pricing."}}},{"id":"P1_U3_MCQ_974","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_974","question":"Why should a premium clothing brand avoid running 'promotional pricing' (50% off sales) every single month?","options":{"A":"Customers dislike buying clothes at discounted prices.","B":"Supermarkets are legally barred from reducing prices more than once a year.","C":"Promotional pricing increases variable manufacturing costs per garment.","D":"Frequent discounting can cheapen the brand's luxury image and train customers to wait for sales instead of paying full price."},"correctOption":"D","correctAnswer":"Frequent discounting can cheapen the brand's luxury image and train customers to wait for sales instead of paying full price.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because constant price cuts erode brand prestige and reduce long-term full-price revenue.","distractor_reasons":{"A":"Incorrect because shoppers welcome discounts, which is why they wait for them.","B":"Incorrect because businesses can legally run sales throughout the year.","C":"Incorrect because retail discounts do not alter factory manufacturing costs.","D":"Option D is correct because constant price cuts erode brand prestige and reduce long-term full-price revenue."}}},{"id":"P1_U3_MCQ_975","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_975","question":"A ride-hailing app automatically increases fares during heavy rainstorms and Saturday night peak hours, then lowers fares on quiet Tuesday afternoons. Which pricing method is this?","options":{"A":"Penetration pricing.","B":"Cost-plus pricing.","C":"Dynamic pricing.","D":"Loss-leader pricing."},"correctOption":"C","correctAnswer":"Dynamic pricing.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because dynamic pricing uses algorithms to adjust prices continuously in response to real-time changes in demand and supply.","distractor_reasons":{"A":"Incorrect because penetration pricing sets a low initial launch price for a new product.","B":"Incorrect because cost-plus pricing adds a fixed percentage onto average cost.","C":"Option C is correct because dynamic pricing uses algorithms to adjust prices continuously in response to real-time changes in demand and supply.","D":"Incorrect because loss-leader pricing sells an item below cost to attract shoppers to buy other profitable goods."}}},{"id":"P1_U3_MCQ_976","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_976","question":"What is the main objective of the 'Place' element in the marketing mix?","options":{"A":"Negotiating annual wage increases with trade unions.","B":"Designing the company's television commercials and social media slogans.","C":"Calculating the break-even level of output for a factory.","D":"Ensuring products are available in the right locations, at the right time, and in convenient ways for target customers to purchase."},"correctOption":"D","correctAnswer":"Ensuring products are available in the right locations, at the right time, and in convenient ways for target customers to purchase.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because Place covers distribution channels and retail/online outlets that connect producers with consumers.","distractor_reasons":{"A":"Incorrect because wage negotiations belong to Human Resources.","B":"Incorrect because advertising and slogans belong to Promotion.","C":"Incorrect because break-even analysis belongs to Operations/Finance.","D":"Option D is correct because Place covers distribution channels and retail/online outlets that connect producers with consumers."}}},{"id":"P1_U3_MCQ_977","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_977","question":"Which type of product is most suited to the traditional distribution channel 'Producer -> Wholesaler -> Retailer -> Consumer'?","options":{"A":"Everyday convenience items like canned drinks and confectionery sold through thousands of small independent corner shops.","B":"Custom-built commercial passenger aircraft ordered directly by airlines.","C":"Downloadable smartphone video games.","D":"One-off tailored wedding gowns."},"correctOption":"A","correctAnswer":"Everyday convenience items like canned drinks and confectionery sold through thousands of small independent corner shops.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because wholesalers break bulk and distribute widely to numerous small retailers that manufacturers cannot economically supply directly.","distractor_reasons":{"A":"Option A is correct because wholesalers break bulk and distribute widely to numerous small retailers that manufacturers cannot economically supply directly.","B":"Incorrect because aircraft are sold directly from manufacturer to airline.","C":"Incorrect because digital apps are distributed directly online.","D":"Incorrect because bespoke dresses are sold directly from designer to bride."}}},{"id":"P1_U3_MCQ_978","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_978","question":"Why do large national supermarket chains usually buy groceries directly from manufacturers ('Producer -> Retailer -> Consumer') rather than using wholesalers?","options":{"A":"Manufacturers deliver single tins of soup directly to each supermarket cashier.","B":"Wholesalers are legally banned from selling food to supermarkets.","C":"Supermarkets only sell one brand of each grocery item.","D":"Supermarkets buy in huge bulk quantities, operate their own regional distribution warehouses, and save money by cutting out the wholesaler's margin."},"correctOption":"D","correctAnswer":"Supermarkets buy in huge bulk quantities, operate their own regional distribution warehouses, and save money by cutting out the wholesaler's margin.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because major retailers possess the scale and logistics infrastructure to perform the wholesaling function themselves at lower cost.","distractor_reasons":{"A":"Incorrect because manufacturers deliver full truckloads to supermarket distribution centres.","B":"Incorrect because no law prevents supermarkets from using wholesalers.","C":"Incorrect because supermarkets stock wide product ranges.","D":"Option D is correct because major retailers possess the scale and logistics infrastructure to perform the wholesaling function themselves at lower cost."}}},{"id":"P1_U3_MCQ_979","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_979","question":"What is a major advantage for a manufacturer of selling directly to consumers ('Producer -> Consumer')?","options":{"A":"The producer keeps the entire retail profit margin and maintains complete control over pricing, brand image, and customer relationships.","B":"The producer incurs zero delivery, storage, or customer service costs.","C":"The product automatically appears on the shelves of every supermarket chain.","D":"Wholesalers pay for all of the manufacturer's advertising."},"correctOption":"A","correctAnswer":"The producer keeps the entire retail profit margin and maintains complete control over pricing, brand image, and customer relationships.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because removing intermediaries avoids sharing profit margins and allows direct communication with buyers.","distractor_reasons":{"A":"Option A is correct because removing intermediaries avoids sharing profit margins and allows direct communication with buyers.","B":"Incorrect because the producer must handle individual order fulfilment, storage, and customer queries itself.","C":"Incorrect because direct selling bypasses supermarkets.","D":"Incorrect because no wholesalers are involved in direct distribution."}}},{"id":"P1_U3_MCQ_980","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_980","question":"What is a disadvantage for a manufacturer of distributing products exclusively through its own direct-to-consumer channel?","options":{"A":"Retail chains demand huge bulk discounts from the manufacturer.","B":"The manufacturer bears high warehousing, individual parcel shipping, and customer service administration costs, and may reach fewer casual shoppers.","C":"Wholesalers take 40% of the selling price as profit.","D":"The manufacturer is banned from collecting customer email addresses."},"correctOption":"B","correctAnswer":"The manufacturer bears high warehousing, individual parcel shipping, and customer service administration costs, and may reach fewer casual shoppers.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because handling thousands of small individual deliveries is logistically expensive and misses consumers who prefer browsing multi-brand stores.","distractor_reasons":{"A":"Incorrect because retail chains are not used in a direct channel.","B":"Option B is correct because handling thousands of small individual deliveries is logistically expensive and misses consumers who prefer browsing multi-brand stores.","C":"Incorrect because wholesalers are bypassed in a direct channel.","D":"Incorrect because direct sellers can collect customer data (subject to privacy laws)."}}},{"id":"P1_U3_MCQ_981","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_981","question":"How does operating an e-commerce store benefit a small specialist retailer?","options":{"A":"It removes the need to hold any inventory or manage suppliers.","B":"It eliminates all parcel postage and packaging expenses.","C":"It guarantees that competitors cannot lower their online prices.","D":"It allows customers worldwide to browse and buy 24 hours a day without the high rent of multiple physical high-street shops."},"correctOption":"D","correctAnswer":"It allows customers worldwide to browse and buy 24 hours a day without the high rent of multiple physical high-street shops.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because e-commerce expands geographic reach around the clock at much lower property overhead than opening physical branches.","distractor_reasons":{"A":"Incorrect because e-commerce retailers still must source and manage inventory.","B":"Incorrect because shipping and packaging costs are significant in e-commerce.","C":"Incorrect because online price competition is intense.","D":"Option D is correct because e-commerce expands geographic reach around the clock at much lower property overhead than opening physical branches."}}},{"id":"P1_U3_MCQ_982","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_982","question":"What is a common challenge faced by clothing retailers selling through e-commerce?","options":{"A":"Shoppers can only place orders between 9:00 AM and 5:00 PM.","B":"High rates of returned items because shoppers cannot try clothes on for size and fabric feel before ordering.","C":"Online stores are legally prohibited from offering home delivery.","D":"Customers are unable to compare prices with rival websites."},"correctOption":"B","correctAnswer":"High rates of returned items because shoppers cannot try clothes on for size and fabric feel before ordering.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because uncertainty over fit and appearance leads to frequent returns, adding reverse-logistics and repackaging costs.","distractor_reasons":{"A":"Incorrect because e-commerce stores operate 24/7.","B":"Option B is correct because uncertainty over fit and appearance leads to frequent returns, adding reverse-logistics and repackaging costs.","C":"Incorrect because home delivery is standard in e-commerce.","D":"Incorrect because online shoppers compare prices very easily."}}},{"id":"P1_U3_MCQ_983","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_983","question":"Which of the following is a primary aim of 'Promotion' in the marketing mix?","options":{"A":"To inform potential buyers about product features, persuade them to purchase, and build a positive brand image.","B":"To calculate the factory's average fixed cost per unit.","C":"To inspect finished products for manufacturing defects.","D":"To recruit production workers for night shifts."},"correctOption":"A","correctAnswer":"To inform potential buyers about product features, persuade them to purchase, and build a positive brand image.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because promotion communicates value to target customers to stimulate awareness, brand loyalty, and sales.","distractor_reasons":{"A":"Option A is correct because promotion communicates value to target customers to stimulate awareness, brand loyalty, and sales.","B":"Incorrect because unit cost calculation belongs to Operations/Finance.","C":"Incorrect because defect inspection is quality control in Operations.","D":"Incorrect because recruitment is a Human Resources function."}}},{"id":"P1_U3_MCQ_984","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_984","question":"When is 'informative advertising' most appropriate?","options":{"A":"When launching a brand-new or technically complex product where consumers need clear facts on how it works and what it does.","B":"When selling bottled water that is identical to twenty competing brands.","C":"When trying to hide product specifications from buyers.","D":"When withdrawing an obsolete product from the market."},"correctOption":"A","correctAnswer":"When launching a brand-new or technically complex product where consumers need clear facts on how it works and what it does.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because unfamiliar innovations require educating consumers about functions, benefits, and availability before they will buy.","distractor_reasons":{"A":"Option A is correct because unfamiliar innovations require educating consumers about functions, benefits, and availability before they will buy.","B":"Incorrect because identical everyday goods rely mainly on persuasive emotional branding.","C":"Incorrect because informative ads provide factual details rather than hiding them.","D":"Incorrect because withdrawn products are no longer promoted."}}},{"id":"P1_U3_MCQ_985","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_985","question":"Why do small local businesses rarely advertise on national television?","options":{"A":"Production and airtime costs are extremely expensive, and most national viewers live too far away to visit a single local shop.","B":"Television commercials cannot display moving images or sound.","C":"Small businesses are legally banned from buying TV airtime.","D":"Nobody watches television anymore."},"correctOption":"A","correctAnswer":"Production and airtime costs are extremely expensive, and most national viewers live too far away to visit a single local shop.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because high cost and huge geographic wastage make national TV unsuitable for a single local outlet.","distractor_reasons":{"A":"Option A is correct because high cost and huge geographic wastage make national TV unsuitable for a single local outlet.","B":"Incorrect because combining sight, sound, and motion is TV's main strength.","C":"Incorrect because any business with sufficient budget can buy TV ads.","D":"Incorrect because TV still reaches large mass audiences."}}},{"id":"P1_U3_MCQ_986","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_986","question":"What is a key advantage of targeted social media advertising compared to traditional print newspaper ads?","options":{"A":"Businesses can aim adverts specifically at users matching exact age, location, and interest profiles and measure clicks in real time.","B":"Social media users never scroll past adverts without buying.","C":"It guarantees that competitors cannot see the business's adverts.","D":"Social media platforms forbid any negative user comments."},"correctOption":"A","correctAnswer":"Businesses can aim adverts specifically at users matching exact age, location, and interest profiles and measure clicks in real time.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because digital platforms use user data to target relevant segments accurately and provide instant performance analytics.","distractor_reasons":{"A":"Option A is correct because digital platforms use user data to target relevant segments accurately and provide instant performance analytics.","B":"Incorrect because many users ignore or block online ads.","C":"Incorrect because public social media ads are visible to rivals.","D":"Incorrect because public comment sections can attract criticism if customers are unhappy."}}},{"id":"P1_U3_MCQ_987","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_987","question":"How does a supermarket 'loyalty card' scheme increase long-term revenue?","options":{"A":"By eliminating the need to stock fresh fruit and vegetables.","B":"By forcing shoppers to pay an extra 20% fee at the checkout.","C":"By rewarding repeat shoppers with points and personalised vouchers, encouraging them to do all their weekly shopping at that chain instead of rivals.","D":"By preventing shoppers from using cash or debit cards."},"correctOption":"C","correctAnswer":"By rewarding repeat shoppers with points and personalised vouchers, encouraging them to do all their weekly shopping at that chain instead of rivals.","questionType":"MCQ","explanation":{"correct_reason":"Option C is correct because loyalty rewards incentivize repeat visits while giving the supermarket valuable data on individual buying habits.","distractor_reasons":{"A":"Incorrect because fresh produce remains essential for supermarkets.","B":"Incorrect because loyalty cards offer discounts/points rather than extra checkout fees.","C":"Option C is correct because loyalty rewards incentivize repeat visits while giving the supermarket valuable data on individual buying habits.","D":"Incorrect because loyalty cards work alongside all normal payment methods."}}},{"id":"P1_U3_MCQ_988","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_988","question":"What is a potential risk for a sportswear company that spends millions sponsoring a famous football team?","options":{"A":"If the team performs poorly or players are involved in a public scandal, negative publicity can damage the sponsor's brand image.","B":"The company's logo is hidden from television cameras during matches.","C":"Sponsorship eliminates all manufacturing costs of sports shoes.","D":"Fans are legally banned from buying the sponsor's shirts."},"correctOption":"A","correctAnswer":"If the team performs poorly or players are involved in a public scandal, negative publicity can damage the sponsor's brand image.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because brand reputation becomes closely linked to the sponsored team or athlete, creating reputational risk if controversies arise.","distractor_reasons":{"A":"Option A is correct because brand reputation becomes closely linked to the sponsored team or athlete, creating reputational risk if controversies arise.","B":"Incorrect because high TV visibility is the main benefit of sports sponsorship.","C":"Incorrect because sponsorship is a promotional expense, not a manufacturing saving.","D":"Incorrect because sponsorship aims to boost merchandise sales."}}},{"id":"P1_U3_MCQ_989","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_989","question":"A clothing retailer plans to target environmentally conscious shoppers, use organic fabrics and sell only through its own website. Which part of marketing planning does this describe?","options":{"A":"A marketing strategy combining target market, product and place decisions","B":"A cash-flow forecast","C":"A production schedule","D":"A legal compliance report"},"correctOption":"A","correctAnswer":"A marketing strategy combining target market, product and place decisions","questionType":"MCQ","explanation":{"correct_reason":"Deciding whom to serve and how to use the product and place elements to satisfy them is the essence of a marketing strategy.","distractor_reasons":{"B":"A cash-flow forecast records expected money movements and does not choose target customers or channels.","C":"A production schedule plans output quantities and timing, not customer targeting or distribution choice.","D":"A compliance report checks adherence to rules rather than setting out how the firm will attract customers.","A":"Deciding whom to serve and how to use the product and place elements to satisfy them is the essence of a marketing strategy."}}},{"id":"P1_U3_MCQ_990","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_990","question":"Which marketing mix best fits a discount supermarket chain aiming to grow market share among budget-conscious families?","options":{"A":"Core everyday groceries with own-label basics, competitive low prices, accessible suburban stores, and price-comparison leaflets/TV ads.","B":"Imported luxury caviar, high skimming prices, single boutique in an exclusive financial district, and invitations to private art galleries.","C":"Unlabelled bulk sacks, prices raised every week, sold only by postal catalogue, and zero local advertising.","D":"Single-serving gourmet meals, luxury gift wrapping, sold only in airport departure lounges."},"correctOption":"A","correctAnswer":"Core everyday groceries with own-label basics, competitive low prices, accessible suburban stores, and price-comparison leaflets/TV ads.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because everyday product essentials, low prices, convenient locations, and value-focused promotion work together to attract budget-conscious families.","distractor_reasons":{"A":"Option A is correct because everyday product essentials, low prices, convenient locations, and value-focused promotion work together to attract budget-conscious families.","B":"Incorrect because luxury caviar and boutiques target wealthy niche buyers.","C":"Incorrect because postal catalogues and rising prices fail to serve weekly family grocery shoppers.","D":"Incorrect because airport departure lounges serve travellers rather than weekly family shoppers."}}},{"id":"P1_U3_MCQ_991","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_991","question":"Primary market research reveals that busy office workers care far more about 30-minute lunch delivery than saving $1 on meal price. How should a salad restaurant adjust its marketing strategy?","options":{"A":"Stop accepting online or app orders.","B":"Cut delivery drivers to save money and reduce salad prices by $1.","C":"Close at lunchtime and open only at midnight.","D":"Invest in fast local delivery riders and app ordering (Place), maintaining a mid-range price that covers delivery costs."},"correctOption":"D","correctAnswer":"Invest in fast local delivery riders and app ordering (Place), maintaining a mid-range price that covers delivery costs.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because aligning Place (rapid delivery) with researched customer priorities creates higher value than unnecessary price cuts.","distractor_reasons":{"A":"Incorrect because app ordering supports fast lunchtime convenience.","B":"Incorrect because cutting delivery speed contradicts the main customer priority identified in research.","C":"Incorrect because office workers buy lunch during midday hours.","D":"Option D is correct because aligning Place (rapid delivery) with researched customer priorities creates higher value than unnecessary price cuts."}}},{"id":"P1_U3_MCQ_992","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_992","question":"A cosmetics company claims in an advert that its face cream 'permanently erases all wrinkles in 24 hours', despite having no scientific evidence. Which legal control does this violate?","options":{"A":"Laws banning television commercials for cosmetics.","B":"Laws requiring every company to use wholesalers.","C":"Laws fixing maximum retail prices on skincare products.","D":"Laws prohibiting false and misleading descriptions in advertising."},"correctOption":"D","correctAnswer":"Laws prohibiting false and misleading descriptions in advertising.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because consumer protection legislation makes it illegal to deceive shoppers with unsubstantiated or false performance claims.","distractor_reasons":{"A":"Incorrect because truthful cosmetic ads are legal on TV.","B":"Incorrect because distribution channels are not mandated by law.","C":"Incorrect because skincare prices are set by businesses.","D":"Option D is correct because consumer protection legislation makes it illegal to deceive shoppers with unsubstantiated or false performance claims."}}},{"id":"P1_U3_MCQ_993","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_993","question":"Why do many countries enforce 'cooling-off' or mandatory return periods for goods purchased online or by mail order?","options":{"A":"To eliminate all shipping costs for online retailers.","B":"To prevent e-commerce websites from accepting credit cards.","C":"To force consumers to keep faulty items delivered by courier.","D":"To protect consumers who cannot physically inspect or test items before buying at a distance."},"correctOption":"D","correctAnswer":"To protect consumers who cannot physically inspect or test items before buying at a distance.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because distance-selling laws give online buyers time to inspect delivered goods and cancel/return them if unsuitable.","distractor_reasons":{"A":"Incorrect because retailers still incur shipping costs.","B":"Incorrect because online retailers freely accept card payments.","C":"Incorrect because consumer laws protect the right to return faulty or unsuitable distance purchases.","D":"Option D is correct because distance-selling laws give online buyers time to inspect delivered goods and cancel/return them if unsuitable."}}},{"id":"P1_U3_MCQ_994","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_994","question":"How do 'weights and measures' consumer protection laws affect a business's packaging and pricing?","options":{"A":"Businesses must sell every product in 1-kilogram bags.","B":"Businesses must state accurate net weights or volumes on packages and must not sell underweight goods.","C":"Businesses are forbidden from printing prices on supermarket shelves.","D":"Businesses can advertise 500g boxes while secretly putting only 300g inside."},"correctOption":"B","correctAnswer":"Businesses must state accurate net weights or volumes on packages and must not sell underweight goods.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because weights and measures regulations ensure consumers receive the exact quantity stated on the label.","distractor_reasons":{"A":"Incorrect because any pack size is legal provided its stated weight/volume is accurate.","B":"Option B is correct because weights and measures regulations ensure consumers receive the exact quantity stated on the label.","C":"Incorrect because clear price display is actually required by consumer laws.","D":"Incorrect because short-weighting customers is illegal."}}},{"id":"P1_U3_MCQ_995","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_995","question":"Why might a successful domestic soft-drinks manufacturer decide to enter foreign markets?","options":{"A":"Exporting overseas eliminates all transport and customs paperwork.","B":"Its home market is saturated with slow growth, whereas overseas markets offer new sales expansion and spread business risk across economies.","C":"Foreign consumers have identical tastes and languages in every country.","D":"Domestic laws force profitable firms to stop selling in their home country."},"correctOption":"B","correctAnswer":"Its home market is saturated with slow growth, whereas overseas markets offer new sales expansion and spread business risk across economies.","questionType":"MCQ","explanation":{"correct_reason":"Option B is correct because expanding internationally overcomes domestic market saturation, increases output for economies of scale, and reduces reliance on one economy.","distractor_reasons":{"A":"Incorrect because international trade increases shipping and customs documentation.","B":"Option B is correct because expanding internationally overcomes domestic market saturation, increases output for economies of scale, and reduces reliance on one economy.","C":"Incorrect because tastes and languages differ widely across countries.","D":"Incorrect because firms continue selling domestically alongside exports."}}},{"id":"P1_U3_MCQ_996","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_996","question":"What problem can arise if a company translates its domestic advertising slogan word-for-word into a foreign language without local research?","options":{"A":"The translated phrase may lose its intended meaning, sound nonsensical, or accidentally offend local cultural values.","B":"Foreign printing presses refuse to print translated words.","C":"Import tariffs automatically triple whenever a slogan is translated.","D":"Local consumers immediately buy twice as much of the product."},"correctOption":"A","correctAnswer":"The translated phrase may lose its intended meaning, sound nonsensical, or accidentally offend local cultural values.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because idioms and brand names frequently carry unintended or offensive meanings across languages and cultures.","distractor_reasons":{"A":"Option A is correct because idioms and brand names frequently carry unintended or offensive meanings across languages and cultures.","B":"Incorrect because local media print translated copy routinely.","C":"Incorrect because import tariffs are based on product classification and value, not ad wording.","D":"Incorrect because poor translation typically damages brand credibility and reduces sales."}}},{"id":"P1_U3_MCQ_997","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_997","question":"Besides cultural and language differences, which financial factor creates risk when a business sells products in foreign markets?","options":{"A":"Exchange rate fluctuations, which can unexpectedly make exported goods more expensive for foreign buyers or reduce converted profits.","B":"Foreign banks refuse to accept electronic money transfers.","C":"Fixed factory rent in the home country doubles every time a container is exported.","D":"All foreign currencies have the exact same value forever."},"correctOption":"A","correctAnswer":"Exchange rate fluctuations, which can unexpectedly make exported goods more expensive for foreign buyers or reduce converted profits.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because appreciation of the exporter's home currency raises foreign selling prices or squeezes profit margins when foreign revenue is converted back.","distractor_reasons":{"A":"Option A is correct because appreciation of the exporter's home currency raises foreign selling prices or squeezes profit margins when foreign revenue is converted back.","B":"Incorrect because international bank transfers operate globally.","C":"Incorrect because domestic rent does not automatically double with exports.","D":"Incorrect because exchange rates fluctuate continuously."}}},{"id":"P1_U3_MCQ_998","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_998","question":"A global fast-food chain keeps its core restaurant branding worldwide but introduces spicy paneer burgers in India and teriyaki burgers in Japan. How does this overcome foreign market barriers?","options":{"A":"By banning local ingredients from all overseas kitchens.","B":"By eliminating all local market research before opening new branches.","C":"By charging 500% more than every local restaurant competitor.","D":"By adapting the Product element of the marketing mix to respect local religious dietary rules and regional taste preferences."},"correctOption":"D","correctAnswer":"By adapting the Product element of the marketing mix to respect local religious dietary rules and regional taste preferences.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because localising menu items aligns the global brand with local cultural norms and culinary tastes, boosting customer acceptance.","distractor_reasons":{"A":"Incorrect because sourcing local ingredients helps adapt menus and control costs.","B":"Incorrect because successful menu adaptation relies on thorough local market research.","C":"Incorrect because fast-food chains use competitive local pricing.","D":"Option D is correct because localising menu items aligns the global brand with local cultural norms and culinary tastes, boosting customer acceptance."}}},{"id":"P1_U3_MCQ_999","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_999","question":"Why might a small manufacturer choose to sell through an established overseas distributor or agent rather than setting up its own foreign sales subsidiary?","options":{"A":"It avoids high upfront capital costs and uses the local distributor's existing retail contacts and regulatory knowledge.","B":"It guarantees 100% control over how the product is displayed in every foreign shop.","C":"Distributors never charge any commission or wholesale margin.","D":"Setting up a wholly owned foreign subsidiary is completely free."},"correctOption":"A","correctAnswer":"It avoids high upfront capital costs and uses the local distributor's existing retail contacts and regulatory knowledge.","questionType":"MCQ","explanation":{"correct_reason":"Option A is correct because working with local intermediaries lowers financial risk and speeds up market entry when a firm lacks capital and local expertise.","distractor_reasons":{"A":"Option A is correct because working with local intermediaries lowers financial risk and speeds up market entry when a firm lacks capital and local expertise.","B":"Incorrect because using third-party distributors actually reduces direct control over retail presentation.","C":"Incorrect because distributors take a margin or commission for their services.","D":"Incorrect because opening foreign offices and warehouses requires heavy capital investment."}}},{"id":"P1_U3_MCQ_1000","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1000","question":"When recommending a new marketing strategy to a business, why must managers consider the firm's current production capacity alongside its promotional plans?","options":{"A":"Laws forbid businesses from promoting products unless their factories are 100% empty.","B":"Production capacity has zero connection to how many units can be sold.","C":"Advertising campaigns automatically double factory floor space overnight.","D":"If heavy promotion generates orders that exceed factory capacity, unfulfilled orders and long delays will disappoint customers and harm the brand."},"correctOption":"D","correctAnswer":"If heavy promotion generates orders that exceed factory capacity, unfulfilled orders and long delays will disappoint customers and harm the brand.","questionType":"MCQ","explanation":{"correct_reason":"Option D is correct because an effective marketing strategy must align demand creation (Promotion/Price) with operational ability to supply (Product/Place).","distractor_reasons":{"A":"Incorrect because no such law exists.","B":"Incorrect because sales volume is constrained by how much output the business can produce or source.","C":"Incorrect because expanding physical capacity requires capital investment and time.","D":"Option D is correct because an effective marketing strategy must align demand creation (Promotion/Price) with operational ability to supply (Product/Place)."}}},{"id":"P1_U3_MCQ_1001","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1001","question":"Brindale Cycles Ltd sold 4,800 bicycles in 2025. The total number of bicycles sold in its national market that year was 60,000. What was Brindale Cycles' market share of this market?","options":{"A":"0.8%","B":"12.5%","C":"80%","D":"8%"},"correctOption":"D","correctAnswer":"8%","questionType":"MCQ","explanation":{"correct_reason":"Market share is the firm's sales divided by total market sales, so 4,800 divided by 60,000 multiplied by 100 gives exactly 8%.","distractor_reasons":{"A":"0.8% comes from moving the decimal point one place too far when dividing 4,800 by 60,000, which understates the real share.","B":"12.5% would only be correct if Brindale had sold 7,500 bicycles out of the 60,000 total, not 4,800.","C":"80% confuses the calculation with a simple percentage of the firm's own output rather than a share of the whole market.","D":"Market share is the firm's sales divided by total market sales, so 4,800 divided by 60,000 multiplied by 100 gives exactly 8%."}}},{"id":"P1_U3_MCQ_1002","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1002","question":"Kelvory Foods plans to launch a new breakfast cereal. Before printing 50,000 questionnaires, managers test the draft on 60 shoppers to check that the wording is clear. What is the main purpose of this pilot test?","options":{"A":"To guarantee that every respondent will give truthful answers in the main survey.","B":"To calculate the exact market share the cereal will achieve after launch.","C":"To replace the need for any sampling of the target population.","D":"To identify confusing questions and remove errors before the full survey is carried out."},"correctOption":"D","correctAnswer":"To identify confusing questions and remove errors before the full survey is carried out.","questionType":"MCQ","explanation":{"correct_reason":"A pilot test exposes ambiguous wording, leading questions and layout faults on a small group so the costly main survey with 50,000 forms is not wasted.","distractor_reasons":{"A":"Testing wording improves clarity but cannot force respondents to be honest or to answer every item truthfully.","B":"A trial of 60 shoppers cannot forecast market share, which depends on sales achieved against total market sales after launch.","C":"The pilot still uses a small sample, so sampling of the target population is still required for the full survey.","D":"A pilot test exposes ambiguous wording, leading questions and layout faults on a small group so the costly main survey with 50,000 forms is not wasted."}}},{"id":"P1_U3_MCQ_1003","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1003","question":"Tarnwell Interiors makes a desk lamp at a unit cost of $24. The business uses cost-plus pricing and adds a mark-up of 25% to that unit cost. What selling price should Tarnwell charge for each lamp?","options":{"A":"$6","B":"$30","C":"$49","D":"$25.20"},"correctOption":"B","correctAnswer":"$30","questionType":"MCQ","explanation":{"correct_reason":"A 25% mark-up on the $24 unit cost adds $6, so the cost-plus selling price is $24 plus $6, which equals $30 per lamp.","distractor_reasons":{"A":"$6 is only the value of the 25% mark-up itself, not the full selling price that must also cover the unit cost.","B":"A 25% mark-up on the $24 unit cost adds $6, so the cost-plus selling price is $24 plus $6, which equals $30 per lamp.","C":"$49 doubles the unit cost and adds a dollar, which does not match any 25% mark-up calculation.","D":"$25.20 wrongly applies a 5% addition to $24 rather than the stated 25% mark-up."}}},{"id":"P1_U3_MCQ_1004","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1004","question":"Vellick Print sells handmade wedding stationery to a small number of couples who want unique designs and are willing to pay high prices. Which marketing strategy is Vellick Print following?","options":{"A":"Mass marketing aimed at the widest possible range of customers.","B":"Niche marketing aimed at a small, clearly defined segment of customers.","C":"Selling only through large national supermarket chains.","D":"Cutting prices below competitors to win the whole market."},"correctOption":"B","correctAnswer":"Niche marketing aimed at a small, clearly defined segment of customers.","questionType":"MCQ","explanation":{"correct_reason":"Vellick targets a small group of couples wanting unique designs at high prices, which is the defining feature of niche marketing rather than mass marketing.","distractor_reasons":{"A":"Mass marketing would mean standardised stationery sold to a very wide audience at lower prices, not bespoke designs for a few couples.","B":"Vellick targets a small group of couples wanting unique designs at high prices, which is the defining feature of niche marketing rather than mass marketing.","C":"The scenario describes direct sales of unique designs, not distribution through national supermarket chains.","D":"Low-price penetration would conflict with the high prices that Vellick's customers are described as willing to pay."}}},{"id":"P1_U3_MCQ_1005","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1005","question":"Quenby Toys sold 3,200 board games in 2025 at an average selling price of $18 each. What was the total sales revenue Quenby Toys earned from board games that year?","options":{"A":"$178","B":"$5,760","C":"$576,000","D":"$57,600"},"correctOption":"D","correctAnswer":"$57,600","questionType":"MCQ","explanation":{"correct_reason":"Sales revenue equals price multiplied by quantity, so 3,200 games at $18 each produces 3,200 times 18, which is $57,600.","distractor_reasons":{"A":"$178 is simply the two figures added together rather than multiplied to find total revenue.","B":"$5,760 results from multiplying 3,200 by $1.80, using a price ten times too small.","C":"$576,000 multiplies by ten too much, as if Quenby had sold 32,000 games at $18 each.","D":"Sales revenue equals price multiplied by quantity, so 3,200 games at $18 each produces 3,200 times 18, which is $57,600."}}},{"id":"P1_U3_MCQ_1006","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1006","question":"Penhale Optics wants to survey 200 of its 4,000 past customers. It uses a computer to select 200 customers at random from the full list. What does this random sampling method mean?","options":{"A":"Each selected customer is asked to recommend another customer to interview.","B":"Only customers who live nearest to the shop are included in the survey.","C":"Researchers choose customers who look most likely to give helpful answers.","D":"Every customer on the list has an equal chance of being chosen for the survey."},"correctOption":"D","correctAnswer":"Every customer on the list has an equal chance of being chosen for the survey.","questionType":"MCQ","explanation":{"correct_reason":"Random sampling gives each of the 4,000 customers the same probability of selection, which helps Penhale obtain a representative sample of 200.","distractor_reasons":{"A":"Asking one customer to name another is referral-based recruitment, which does not give everyone an equal chance.","B":"Limiting the survey to nearby customers is a geographic restriction, not a random selection from the full list.","C":"Hand-picking helpful respondents introduces researcher bias and is not random sampling.","D":"Random sampling gives each of the 4,000 customers the same probability of selection, which helps Penhale obtain a representative sample of 200."}}},{"id":"P1_U3_MCQ_1007","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1007","question":"Ashcombe Dairy has a promotional budget of $84,000 for its new yoghurt. It expects to sell 12,000 tubs during the campaign. What is the promotional spending per tub?","options":{"A":"$0.70","B":"$1.40","C":"$8.40","D":"$7"},"correctOption":"D","correctAnswer":"$7","questionType":"MCQ","explanation":{"correct_reason":"The promotional budget per unit is $84,000 divided by 12,000 tubs, which works out at exactly $7 of promotion cost for each tub sold.","distractor_reasons":{"A":"$0.70 places the decimal point one place too far left, understating the promotion cost per tub by a factor of ten.","B":"$1.40 does not come from dividing $84,000 by 12,000 and seems to use an incorrect quantity figure.","C":"$8.40 treats the budget as $100,800, which is not the $84,000 that Ashcombe allocated.","D":"The promotional budget per unit is $84,000 divided by 12,000 tubs, which works out at exactly $7 of promotion cost for each tub sold."}}},{"id":"P1_U3_MCQ_1008","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1008","question":"Wrenfold Sports currently sells running shoes only through its single town-centre shop. It is considering an online store that ships across the country. Which is the main marketing benefit of this move?","options":{"A":"It removes the need to carry out any market research in future.","B":"It widens the geographic market the business can reach beyond its local customers.","C":"It guarantees that delivery costs will fall to zero for every order.","D":"It automatically lowers the price competitors charge for similar shoes."},"correctOption":"B","correctAnswer":"It widens the geographic market the business can reach beyond its local customers.","questionType":"MCQ","explanation":{"correct_reason":"Selling online lets Wrenfold serve shoppers nationwide rather than only those who visit one town-centre shop, which increases the size of its accessible market.","distractor_reasons":{"A":"Online selling creates new data needs and does not remove the need for market research about customers and rivals.","B":"Selling online lets Wrenfold serve shoppers nationwide rather than only those who visit one town-centre shop, which increases the size of its accessible market.","C":"Delivery to distant customers usually adds shipping and packaging costs rather than eliminating them.","D":"A firm's own distribution choice cannot set the prices that rival shoe sellers decide to charge."}}},{"id":"P1_U3_MCQ_1009","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1009","question":"In 2024 the total market for garden tools was worth 250,000 units. In 2025 the same market was worth 275,000 units. By what percentage did the size of the market grow?","options":{"A":"25%","B":"9.1%","C":"10%","D":"1.1%"},"correctOption":"C","correctAnswer":"10%","questionType":"MCQ","explanation":{"correct_reason":"The market grew by 25,000 units, and 25,000 divided by the original 250,000 multiplied by 100 gives a growth rate of 10%.","distractor_reasons":{"A":"25% mistakes the 25,000 unit increase for a percentage instead of dividing it by the 250,000 starting size.","B":"9.1% divides the 25,000 increase by the new 275,000 figure rather than by the original 250,000 base.","C":"The market grew by 25,000 units, and 25,000 divided by the original 250,000 multiplied by 100 gives a growth rate of 10%.","D":"1.1% comes from dividing 25,000 by 275,000 and then misplacing the decimal point, so it is far too small."}}},{"id":"P1_U3_MCQ_1010","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1010","question":"Coldstream Bakery is deciding whether to open a new branch. It buys published government reports on local population and household spending instead of interviewing residents itself. What is an advantage of this secondary data?","options":{"A":"It is certain to be more up to date than data the bakery could gather itself.","B":"It is always collected for the exact purpose the bakery has in mind.","C":"It reflects only the opinions of customers who visited Coldstream's shops.","D":"It is already collected, so it is usually cheaper and faster to obtain than new primary data."},"correctOption":"D","correctAnswer":"It is already collected, so it is usually cheaper and faster to obtain than new primary data.","questionType":"MCQ","explanation":{"correct_reason":"Published government reports already exist, so Coldstream avoids the time and cost of designing surveys and interviewing residents, although the data may be general rather than specific.","distractor_reasons":{"A":"Official reports are often published months after collection, so freshness cannot be guaranteed.","B":"Secondary data is normally gathered for another organisation's purpose, so it rarely matches the bakery's exact needs.","C":"Government population and spending reports cover whole areas, not just people who have shopped at Coldstream.","D":"Published government reports already exist, so Coldstream avoids the time and cost of designing surveys and interviewing residents, although the data may be general rather than specific."}}},{"id":"P1_U3_MCQ_1011","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1011","question":"Marlowe Ceramics produces mugs at a unit cost of $8.50. The owner applies cost-plus pricing with a 40% mark-up on unit cost. What selling price does this give for one mug?","options":{"A":"$13.60","B":"$3.40","C":"$12.00","D":"$11.90"},"correctOption":"D","correctAnswer":"$11.90","questionType":"MCQ","explanation":{"correct_reason":"A 40% mark-up on the $8.50 unit cost adds $3.40, so the cost-plus price is $8.50 plus $3.40, which equals $11.90.","distractor_reasons":{"A":"$13.60 wrongly applies a 60% mark-up instead of the 40% that Marlowe's owner specified.","B":"$3.40 is just the mark-up amount and leaves out the $8.50 unit cost that the price must also recover.","C":"$12.00 rounds the answer up and is not the exact result of a 40% mark-up on $8.50.","D":"A 40% mark-up on the $8.50 unit cost adds $3.40, so the cost-plus price is $8.50 plus $3.40, which equals $11.90."}}},{"id":"P1_U3_MCQ_1012","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1012","question":"Ostrey Media runs a paid subscription service for local news. It plans to reduce the monthly fee for the first three months to attract new readers. Which marketing aim does this price reduction mainly support?","options":{"A":"Increasing the number of subscribers by lowering the barrier to trial.","B":"Reducing the quality of journalism to cut production costs.","C":"Removing the need to promote the service at all.","D":"Guaranteeing that subscribers will never cancel their contracts."},"correctOption":"A","correctAnswer":"Increasing the number of subscribers by lowering the barrier to trial.","questionType":"MCQ","explanation":{"correct_reason":"A discounted introductory fee makes trying the service less risky for readers, which Ostrey hopes will convert triallists into a larger paying subscriber base.","distractor_reasons":{"A":"A discounted introductory fee makes trying the service less risky for readers, which Ostrey hopes will convert triallists into a larger paying subscriber base.","B":"Cutting editorial quality would damage the product itself and is not the purpose of an introductory price offer.","C":"A lower price still needs promotion so that potential readers actually learn about the offer.","D":"No price offer can prevent subscribers from cancelling once the trial period ends."}}},{"id":"P1_U3_MCQ_1013","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1013","question":"Dunmore Poultry Supplies, which sells feed to local egg farms, lost several customers in 2025 after a rival began offering free next-day delivery to the same farms. Which response best shows Dunmore reacting to competitive pressure?","options":{"A":"Ignoring the rival and assuming customers will return eventually.","B":"Raising its delivery charges to cover the cost of faster vans.","C":"Adding a similar free delivery service for orders above a set value.","D":"Stopping production until the rival leaves the market."},"correctOption":"C","correctAnswer":"Adding a similar free delivery service for orders above a set value.","questionType":"MCQ","explanation":{"correct_reason":"Matching the rival's delivery advantage protects Dunmore's farm customers, while the minimum order value keeps the free delivery affordable for the business.","distractor_reasons":{"A":"Doing nothing leaves the rival's offer as the better deal, so more farm customers are likely to switch away.","B":"Charging more for delivery widens the gap with the rival's free service and accelerates customer loss.","C":"Matching the rival's delivery advantage protects Dunmore's farm customers, while the minimum order value keeps the free delivery affordable for the business.","D":"Halting production would break supply contracts and hand the whole farm market to the competitor."}}},{"id":"P1_U3_MCQ_1014","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1014","question":"Harrowgate Leisure wants feedback on a new climbing wall. It places staff at the exit to ask every twentieth visitor a set of fixed questions. Which two features of this research are shown?","options":{"A":"Primary data collected by a questionnaire using quota sampling.","B":"Secondary data collected by observation using random sampling.","C":"Primary data collected by interview using a focus group.","D":"Secondary data collected by a questionnaire using a panel of experts."},"correctOption":"A","correctAnswer":"Primary data collected by a questionnaire using quota sampling.","questionType":"MCQ","explanation":{"correct_reason":"The fixed questions are gathered first-hand from visitors by questionnaire, and staff select a set number of respondents in groups, which is quota sampling.","distractor_reasons":{"A":"The fixed questions are gathered first-hand from visitors by questionnaire, and staff select a set number of respondents in groups, which is quota sampling.","B":"The data is collected directly from visitors rather than from existing records, and no observation of behaviour is described.","C":"There is no group discussion; staff ask each visitor a fixed set of questions individually.","D":"The responses come first-hand from visitors, not from published reports or a panel of specialists."}}},{"id":"P1_U3_MCQ_1015","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1015","question":"Selborne Kitchens sells its ovens through independent kitchen showrooms rather than directly to homeowners. Which element of the marketing mix does this decision mainly concern?","options":{"A":"Product, because it changes the oven's warranty length.","B":"Place, because it determines the distribution channel used.","C":"Price, because showrooms set the final retail price alone.","D":"Promotion, because showrooms refuse to display any branding."},"correctOption":"B","correctAnswer":"Place, because it determines the distribution channel used.","questionType":"MCQ","explanation":{"correct_reason":"Choosing independent showrooms instead of direct selling is a distribution decision, so it belongs to Place within the marketing mix.","distractor_reasons":{"A":"The warranty is a product feature, and nothing in the scenario says the channel choice alters it.","B":"Choosing independent showrooms instead of direct selling is a distribution decision, so it belongs to Place within the marketing mix.","C":"Channel choice affects who sells the ovens, but it does not by itself set the retail price.","D":"Showrooms typically display manufacturer branding, and the scenario gives no evidence of a promotion ban."}}},{"id":"P1_U3_MCQ_1016","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1016","question":"Barrowden Cosmetics sells the same basic moisturiser in two versions: a plain 200ml tub for $6 and a gift-boxed 200ml tub for $14. Why might this strategy increase total revenue?","options":{"A":"It forces every customer to buy both versions at the same time.","B":"It reduces the cost of producing each tub to zero.","C":"It allows the firm to charge a higher price to customers who value attractive packaging.","D":"It makes the product identical in every way, so customers cannot compare."},"correctOption":"C","correctAnswer":"It allows the firm to charge a higher price to customers who value attractive packaging.","questionType":"MCQ","explanation":{"correct_reason":"Gift buyers will pay $14 for presentation, while price-sensitive shoppers still buy at $6, so Barrowden captures revenue from both groups with one basic product.","distractor_reasons":{"A":"Customers choose one version, and nothing in the scenario compels them to buy both tubs together.","B":"The gift box adds packaging cost, so the $14 version certainly does not cost nothing to produce.","C":"Gift buyers will pay $14 for presentation, while price-sensitive shoppers still buy at $6, so Barrowden captures revenue from both groups with one basic product.","D":"The two versions are deliberately differentiated by packaging, which is what allows the price gap."}}},{"id":"P1_U3_MCQ_1017","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1017","question":"Thornbury Heating sold 9,000 boilers last year. Total boiler sales in its region were 120,000 units. A rival, Caxley Heating, sold 15,000 units. What was Thornbury's market share?","options":{"A":"7.5%","B":"12.5%","C":"6%","D":"75%"},"correctOption":"A","correctAnswer":"7.5%","questionType":"MCQ","explanation":{"correct_reason":"Thornbury's 9,000 boilers divided by the region's 120,000 total gives 0.075, which converts to a market share of 7.5%.","distractor_reasons":{"A":"Thornbury's 9,000 boilers divided by the region's 120,000 total gives 0.075, which converts to a market share of 7.5%.","B":"12.5% is Caxley's share from 15,000 units, not Thornbury's share from 9,000 units.","C":"6% would require Thornbury to have sold 7,200 boilers, which is below its actual 9,000.","D":"75% comes from dividing 9,000 by 12,000 instead of by the full regional market of 120,000."}}},{"id":"P1_U3_MCQ_1018","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1018","question":"Rendlesham Furniture asks 500 shoppers to rate six statements from 'strongly agree' to 'strongly disagree'. Which method of primary research is being used and what is its main limitation?","options":{"A":"Observation, which cannot record what customers say.","B":"A questionnaire, where respondents may misunderstand or answer carelessly.","C":"A focus group, which is limited to six participants only.","D":"Secondary research, which is out of date by definition."},"correctOption":"B","correctAnswer":"A questionnaire, where respondents may misunderstand or answer carelessly.","questionType":"MCQ","explanation":{"correct_reason":"A fixed rating scale given to 500 shoppers is a questionnaire, and the main weakness is that respondents may misread items or give rushed, unreliable answers.","distractor_reasons":{"A":"Shoppers are stating opinions on a rating scale, so the method records what they say rather than observed behaviour.","B":"A fixed rating scale given to 500 shoppers is a questionnaire, and the main weakness is that respondents may misread items or give rushed, unreliable answers.","C":"500 respondents answering individually is not a small group discussion of six people.","D":"The ratings are collected first-hand from shoppers, so the research is primary rather than secondary."}}},{"id":"P1_U3_MCQ_1019","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1019","question":"Fenwick Audio sells its Bluetooth speaker for $95 in its own town-centre shop. A rival's comparable speaker costs $76 in a nearby store. By what percentage is Fenwick's price higher than the rival's price?","options":{"A":"19%","B":"20%","C":"25%","D":"125%"},"correctOption":"C","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"The $19 gap divided by the rival's $76 base price gives 0.25, so Fenwick's speaker is priced 25% above the competitor.","distractor_reasons":{"A":"19% confuses the $19 cash difference with a percentage and never divides it by the $76 rival price.","B":"20% divides the $19 gap by Fenwick's own $95 price rather than by the rival's $76 price.","C":"The $19 gap divided by the rival's $76 base price gives 0.25, so Fenwick's speaker is priced 25% above the competitor.","D":"125% is the ratio of Fenwick's price to the rival price, not the percentage by which it is higher."}}},{"id":"P1_U3_MCQ_1020","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1020","question":"Gisleham Holidays wants to sell adventure trips to young professionals. It has a limited budget and cannot advertise on national television. Which promotional choice is most suitable?","options":{"A":"Sponsoring a costly national football league for ten years.","B":"Placing full-page adverts in every regional newspaper daily.","C":"Paid social media adverts targeted at users aged 25 to 34 with travel interests.","D":"Handing leaflets to shoppers outside a retirement village."},"correctOption":"C","correctAnswer":"Paid social media adverts targeted at users aged 25 to 34 with travel interests.","questionType":"MCQ","explanation":{"correct_reason":"Targeted social media advertising reaches the specific age and interest group Gisleham wants at a cost that fits a limited budget.","distractor_reasons":{"A":"A decade-long national league sponsorship is far beyond the budget and reaches mostly irrelevant audiences.","B":"Daily full-page regional adverts waste money on readers outside the young professional segment.","C":"Targeted social media advertising reaches the specific age and interest group Gisleham wants at a cost that fits a limited budget.","D":"Leaflets at a retirement village reach older people rather than the young professionals being targeted."}}},{"id":"P1_U3_MCQ_1021","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1021","question":"Larkhill Garden Centres sold 15,600 plants across its three outlets in 2024 and 17,160 plants in 2025. What was the percentage increase in the number of plants sold over the year?","options":{"A":"1.56%","B":"10%","C":"9.1%","D":"156%"},"correctOption":"B","correctAnswer":"10%","questionType":"MCQ","explanation":{"correct_reason":"Sales rose by 1,560 plants, and 1,560 divided by the original 15,600 multiplied by 100 gives an increase of exactly 10%.","distractor_reasons":{"A":"1.56% misplaces the decimal point when dividing 1,560 by the 15,600 base figure.","B":"Sales rose by 1,560 plants, and 1,560 divided by the original 15,600 multiplied by 100 gives an increase of exactly 10%.","C":"9.1% divides the 1,560 increase by the higher 2025 figure instead of the 2024 starting figure.","D":"156% treats the 1,560 extra plants as a percentage without dividing by the original sales at all."}}},{"id":"P1_U3_MCQ_1022","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1022","question":"Ingleby Rail wants 300 completed surveys split evenly between commuters, leisure travellers and students, because each group is a set proportion of its passengers. Which sampling method fits this requirement?","options":{"A":"Random sampling, because every passenger has an equal chance of selection.","B":"Quota sampling, because the researcher fills a fixed number of places in each group.","C":"Selecting only passengers who travel first class.","D":"Interviewing whoever happens to walk past the ticket office."},"correctOption":"B","correctAnswer":"Quota sampling, because the researcher fills a fixed number of places in each group.","questionType":"MCQ","explanation":{"correct_reason":"Quota sampling lets Ingleby specify how many respondents come from each of the three passenger groups, so the sample matches the known proportions of its customers.","distractor_reasons":{"A":"Random sampling gives equal chances but does not guarantee 100 commuters, 100 leisure travellers and 100 students.","B":"Quota sampling lets Ingleby specify how many respondents come from each of the three passenger groups, so the sample matches the known proportions of its customers.","C":"Restricting to first-class passengers would bias the results and miss the other two required groups.","D":"Approaching passers-by without any group targets cannot deliver the fixed 300 split Ingleby needs."}}},{"id":"P1_U3_MCQ_1023","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1023","question":"Cobworth Optics makes reading glasses at a unit cost of $32. It uses cost-plus pricing and adds a mark-up of 15% on unit cost. What selling price results?","options":{"A":"$4.80","B":"$36.80","C":"$47.00","D":"$32.15"},"correctOption":"B","correctAnswer":"$36.80","questionType":"MCQ","explanation":{"correct_reason":"A 15% mark-up on the $32 unit cost adds $4.80, so the cost-plus selling price is $32 plus $4.80, which equals $36.80.","distractor_reasons":{"A":"$4.80 is only the mark-up amount and omits the $32 unit cost that the price must recover.","B":"A 15% mark-up on the $32 unit cost adds $4.80, so the cost-plus selling price is $32 plus $4.80, which equals $36.80.","C":"$47.00 applies a mark-up of about 47% rather than the stated 15% to the unit cost.","D":"$32.15 treats the 15% as 15 cents added to the cost instead of 15% of $32."}}},{"id":"P1_U3_MCQ_1024","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1024","question":"Aldworth Bikes sells a basic children's bicycle at a low price to attract first-time buyers, expecting to earn more later from servicing and accessories. Why is this a sensible marketing strategy?","options":{"A":"It builds a customer relationship that can generate repeat purchases and after-sales income.","B":"It ensures the bicycle is never copied by any competitor.","C":"It removes all future costs of manufacturing and distribution.","D":"It makes market research unnecessary because the price is low."},"correctOption":"A","correctAnswer":"It builds a customer relationship that can generate repeat purchases and after-sales income.","questionType":"MCQ","explanation":{"correct_reason":"A low entry price brings families into Aldworth's brand, and servicing plus accessories sold later can produce more profit than the first bicycle sale alone.","distractor_reasons":{"A":"A low entry price brings families into Aldworth's brand, and servicing plus accessories sold later can produce more profit than the first bicycle sale alone.","B":"A pricing strategy cannot stop rivals from launching similar children's bicycles.","C":"Servicing and distribution still involve costs, so no strategy eliminates them entirely.","D":"Even low-priced products need research to confirm that the target families will buy them."}}},{"id":"P1_U3_MCQ_1025","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1025","question":"Whitcombe Coffee Roasters notices that most of its sales come from 200 loyal cafes that reorder every month. Why does this customer loyalty matter to the business?","options":{"A":"Loyal customers usually require heavier discounting than new ones.","B":"It gives predictable repeat revenue and lowers the cost of finding new buyers.","C":"It proves that the business no longer faces any competition.","D":"It means the firm can stop maintaining product quality."},"correctOption":"B","correctAnswer":"It gives predictable repeat revenue and lowers the cost of finding new buyers.","questionType":"MCQ","explanation":{"correct_reason":"Two hundred cafes reordering monthly create a stable sales base, and retaining them is cheaper than continually recruiting fresh customers through advertising.","distractor_reasons":{"A":"Loyal trade customers often need less discounting because switching costs and trust keep them buying.","B":"Two hundred cafes reordering monthly create a stable sales base, and retaining them is cheaper than continually recruiting fresh customers through advertising.","C":"Loyalty reflects past success but does not remove the threat of rival roasters winning those cafes.","D":"Consistent quality is the very reason those cafes keep reordering, so it cannot be abandoned."}}},{"id":"P1_U3_MCQ_1026","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1026","question":"Horbury Snacks budgets $9,600 for a consumer taste test of a new crisp flavour in four shopping centres. Outside researchers charge $24 for each completed interview. How many completed interviews can Horbury afford?","options":{"A":"230","B":"400","C":"960","D":"240"},"correctOption":"B","correctAnswer":"400","questionType":"MCQ","explanation":{"correct_reason":"Dividing the $9,600 research budget by the $24 cost of each interview gives exactly 400 completed interviews.","distractor_reasons":{"A":"230 does not follow from dividing $9,600 by $24 and uses figures that are not in the scenario.","B":"Dividing the $9,600 research budget by the $24 cost of each interview gives exactly 400 completed interviews.","C":"960 treats the $9,600 figure as $9.60 per interview instead of $24 per interview.","D":"240 divides the budget by $40 rather than by the stated $24 fee per interview."}}},{"id":"P1_U3_MCQ_1027","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1027","question":"Beckridge Furnishings sells sofas in three sizes and twelve fabric options, and offers a five-year frame guarantee. Which element of the marketing mix do these choices mainly represent?","options":{"A":"Price and place, because the fabrics change the retail price and the showroom location.","B":"Promotion and price, because guarantees are advertising and fabrics affect discounts.","C":"Product and place, because the guarantee is a distribution agreement with retailers.","D":"Product, because variety and guarantee are features of the sofa itself, and product also covers range and quality."},"correctOption":"D","correctAnswer":"Product, because variety and guarantee are features of the sofa itself, and product also covers range and quality.","questionType":"MCQ","explanation":{"correct_reason":"Range width, fabric choice and a five-year guarantee all shape what the customer receives, which are design, variety and quality aspects of Product.","distractor_reasons":{"A":"No prices or showroom locations are given; the described features concern the sofas themselves.","B":"A guarantee is part of the product offer and is not primarily a promotional message or a discount.","C":"The guarantee is a promise to the buyer rather than an arrangement about distribution channels.","D":"Range width, fabric choice and a five-year guarantee all shape what the customer receives, which are design, variety and quality aspects of Product."}}},{"id":"P1_U3_MCQ_1028","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1028","question":"Norbury Software finds that downloads of its app rise sharply, then level off, then fall as rival apps appear. What does this pattern show about the product?","options":{"A":"It has reached the decline stage, so the firm should consider updating or replacing it.","B":"It is still in the introduction stage and needs no changes.","C":"Sales will rise indefinitely once the app matures.","D":"Competitors have no influence on app sales at any stage."},"correctOption":"A","correctAnswer":"It has reached the decline stage, so the firm should consider updating or replacing it.","questionType":"MCQ","explanation":{"correct_reason":"Sales rose, plateaued and are now falling as rival apps enter, which is the decline stage, so Norbury needs a relaunch or a replacement product.","distractor_reasons":{"A":"Sales rose, plateaued and are now falling as rival apps enter, which is the decline stage, so Norbury needs a relaunch or a replacement product.","B":"The introduction stage would show low but rising sales, not a peak followed by a fall.","C":"The scenario states downloads are already falling, so indefinite growth is contradicted by the data.","D":"The fall is explicitly linked to rival apps appearing, so competition clearly affects sales."}}},{"id":"P1_U3_MCQ_1029","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1029","question":"A regional market for running shoes is worth $2.4 million a year. Stridewell Shoes sells $360,000 worth of shoes in that market. What is Stridewell's market share by value?","options":{"A":"6.7%","B":"15%","C":"1.5%","D":"66.7%"},"correctOption":"B","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Stridewell's $360,000 of sales divided by the $2.4 million market value gives 0.15, which is a 15% share by value.","distractor_reasons":{"A":"6.7% reverses the division, treating the whole $2.4 million market as a fraction of Stridewell's sales.","B":"Stridewell's $360,000 of sales divided by the $2.4 million market value gives 0.15, which is a 15% share by value.","C":"1.5% misplaces the decimal point after dividing $360,000 by $2,400,000.","D":"66.7% comes from dividing $1.6 million by $2.4 million, using a sales figure Stridewell does not have."}}},{"id":"P1_U3_MCQ_1030","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1030","question":"Nayland Pet Foods reads that national spending on premium pet food grew 12% last year. It wants to know whether local owners would pay $9 for a new grain-free recipe. Which combination of research would best answer this?","options":{"A":"Primary research with local owners, supported by the secondary national spending report.","B":"Secondary data alone, because national trends always apply locally.","C":"Primary research with supermarket managers instead of pet owners.","D":"No research, because the national report already proves local demand."},"correctOption":"A","correctAnswer":"Primary research with local owners, supported by the secondary national spending report.","questionType":"MCQ","explanation":{"correct_reason":"The report shows a national trend but not local willingness to pay $9, so Nayland should ask local owners directly while using the report as background evidence.","distractor_reasons":{"A":"The report shows a national trend but not local willingness to pay $9, so Nayland should ask local owners directly while using the report as background evidence.","B":"National averages can hide local differences, so secondary data alone cannot establish local willingness to pay.","C":"Supermarket managers do not represent the pet owners whose spending decision is being tested.","D":"The national report says nothing about local demand or the specific $9 price being considered."}}},{"id":"P1_U3_MCQ_1031","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1031","question":"Peverell Sports sells gym bags through its own town-centre shop. It plans a 'buy one, get one half price' offer for one month only. Why might the business limit this sales promotion to a short period?","options":{"A":"Because sales promotions lasting longer than one month are illegal in the UK.","B":"Because a permanent offer would train customers to expect discounts and cut full-price sales.","C":"Because customers dislike saving money on products they already want to buy.","D":"Because sales promotions cannot be advertised inside a shop."},"correctOption":"B","correctAnswer":"Because a permanent offer would train customers to expect discounts and cut full-price sales.","questionType":"MCQ","explanation":{"correct_reason":"A short promotion creates urgency and clears stock, while a permanent one would teach shoppers to wait for discounts and reduce Peverell's normal full-price revenue.","distractor_reasons":{"A":"There is no law limiting sales promotions to one month; businesses choose the timing for commercial reasons.","B":"A short promotion creates urgency and clears stock, while a permanent one would teach shoppers to wait for discounts and reduce Peverell's normal full-price revenue.","C":"Customers generally welcome saving money, so dislike of discounts is not the reason to limit the offer.","D":"In-store promotions such as posters and shelf notices are common and perfectly lawful."}}},{"id":"P1_U3_MCQ_1032","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1032","question":"Colneby Travel wants to grow by selling its existing coach tours to customers in a neighbouring county where it has never advertised. Which change to its marketing is most directly required?","options":{"A":"Redesigning every coach to a new specification.","B":"Increasing the number of head office accountants.","C":"Replacing all existing tour guides with new staff.","D":"Promoting the tours in the new area and choosing suitable local pick-up points."},"correctOption":"D","correctAnswer":"Promoting the tours in the new area and choosing suitable local pick-up points.","questionType":"MCQ","explanation":{"correct_reason":"Entering a new county needs awareness and convenient boarding, so promotion and local pick-up points are the marketing changes that make the existing tours accessible.","distractor_reasons":{"A":"The product is unchanged, so redesigning coaches is not needed to reach a new geographic market.","B":"Extra accountants do not create demand or make the tours convenient for new customers.","C":"Replacing guides would disrupt the existing service without helping the firm enter the new county.","D":"Entering a new county needs awareness and convenient boarding, so promotion and local pick-up points are the marketing changes that make the existing tours accessible."}}},{"id":"P1_U3_MCQ_1033","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1033","question":"Wexley Bakery has seen its share of the local bread market fall for three years while a supermarket chain opened two new stores. Which explanation is most consistent with this trend?","options":{"A":"The supermarket chain has stopped selling bread altogether.","B":"Local demand for bread has fallen to zero in the area.","C":"The supermarket's lower prices and longer opening hours have attracted Wexley's former customers.","D":"Wexley has increased its advertising without changing anything else."},"correctOption":"C","correctAnswer":"The supermarket's lower prices and longer opening hours have attracted Wexley's former customers.","questionType":"MCQ","explanation":{"correct_reason":"Two new supermarkets offering cheaper bread and longer hours give local shoppers stronger reasons to switch, which fits a three-year fall in Wexley's market share.","distractor_reasons":{"A":"If the chain had stopped selling bread, its new stores would not be taking share from Wexley.","B":"Wexley's share is falling, not its absolute sales to zero, and the scenario gives no evidence of collapsing demand.","C":"Two new supermarkets offering cheaper bread and longer hours give local shoppers stronger reasons to switch, which fits a three-year fall in Wexley's market share.","D":"Advertising normally supports share, so it does not explain a three-year decline alongside new supermarket openings."}}},{"id":"P1_U3_MCQ_1034","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1034","question":"Saxthorpe Hotels wants to know why guests rated its breakfast poorly. It could survey 50 guests or hold two small group discussions with eight guests each. Why might the group discussions give deeper insight?","options":{"A":"They allow guests to explain their reasons and respond to each other's comments in detail.","B":"They produce numerical data that is easier to put into a bar chart.","C":"They guarantee that all 50 guests are represented in the findings.","D":"They remove the need to record or analyse what guests say."},"correctOption":"A","correctAnswer":"They allow guests to explain their reasons and respond to each other's comments in detail.","questionType":"MCQ","explanation":{"correct_reason":"Small group discussion encourages guests to explain why the breakfast disappointed them and to build on each other's points, producing richer qualitative detail than tick boxes.","distractor_reasons":{"A":"Small group discussion encourages guests to explain why the breakfast disappointed them and to build on each other's points, producing richer qualitative detail than tick boxes.","B":"Group discussion mainly produces words and opinions rather than neat numerical data for charts.","C":"Sixteen guests in two groups cannot represent all 50 guests, so representation is actually a weakness.","D":"What guests say still has to be recorded and analysed, otherwise no usable findings emerge."}}},{"id":"P1_U3_MCQ_1035","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1035","question":"Dunster Tool Hire wants customers to notice its new cordless tool range once they are inside its own showroom. Which promotional method best suits this aim at low cost?","options":{"A":"A national television campaign running for three months.","B":"A radio advert during a major national sporting event.","C":"A full-page advert in an international trade magazine.","D":"Point-of-sale displays and demonstration stands beside the tools in the showroom."},"correctOption":"D","correctAnswer":"Point-of-sale displays and demonstration stands beside the tools in the showroom.","questionType":"MCQ","explanation":{"correct_reason":"Displays and demonstrations place the message exactly where customers are handling the tools, which is cheap and directly supports the aim of being noticed in store.","distractor_reasons":{"A":"National television is expensive and reaches millions of people who will never enter the showroom.","B":"Radio reaches a broad audience but cannot show customers the tools while they are in the showroom.","C":"A magazine advert informs readers before they visit but does nothing at the shelf where the choice is made.","D":"Displays and demonstrations place the message exactly where customers are handling the tools, which is cheap and directly supports the aim of being noticed in store."}}},{"id":"P1_U3_MCQ_1036","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1036","question":"Rothwell Motors sells family cars and delivery vans. Its vans are bought mainly by small firms, while cars are bought by households. Why should Rothwell use different marketing strategies for the two ranges?","options":{"A":"The two customer groups have different needs, buying processes and media habits.","B":"Vans and cars are legally required to be advertised in separate languages.","C":"Households are unable to buy delivery vans under any circumstances.","D":"One marketing strategy can never cover more than one product."},"correctOption":"A","correctAnswer":"The two customer groups have different needs, buying processes and media habits.","questionType":"MCQ","explanation":{"correct_reason":"Small firms assess running costs and load space while households weigh safety and finance deals, and they read different media, so Rothwell needs separate targeting and messages.","distractor_reasons":{"A":"Small firms assess running costs and load space while households weigh safety and finance deals, and they read different media, so Rothwell needs separate targeting and messages.","B":"There is no legal rule requiring separate languages for van and car advertising.","C":"Households can legally buy vans, although most choose not to, which is a demand issue rather than a ban.","D":"A single strategy can cover several products if the customers are similar, so this blanket claim is false."}}},{"id":"P1_U3_MCQ_1037","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1037","question":"Total spending on wedding photography in a county is $800,000 a year. Aperture & Ash Photography earns $120,000 from wedding work. What is its market share of this market?","options":{"A":"6.7%","B":"15%","C":"12%","D":"1.5%"},"correctOption":"B","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Its $120,000 of wedding revenue divided by the county's $800,000 total gives 0.15, so Aperture & Ash holds a 15% share by value.","distractor_reasons":{"A":"6.7% reverses the calculation and divides the whole county market by the firm's own revenue.","B":"Its $120,000 of wedding revenue divided by the county's $800,000 total gives 0.15, so Aperture & Ash holds a 15% share by value.","C":"12% confuses the $120,000 revenue figure with a percentage of the $800,000 market.","D":"1.5% misplaces the decimal point after dividing $120,000 by $800,000."}}},{"id":"P1_U3_MCQ_1038","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1038","question":"A researcher for Ockendon Garden Village asks shoppers: 'How often do you visit our garden centre?' and offers the boxes never, once a year, monthly and weekly. What type of question is this?","options":{"A":"An open question that invites a long written answer.","B":"A leading question that suggests the preferred answer.","C":"A closed question with fixed response options that are easy to count.","D":"A secondary research question taken from published data."},"correctOption":"C","correctAnswer":"A closed question with fixed response options that are easy to count.","questionType":"MCQ","explanation":{"correct_reason":"The four tick-box answers are fixed, so this is a closed question whose responses can be tallied quickly for frequency analysis.","distractor_reasons":{"A":"No space for a written explanation is offered, so the question is not open-ended.","B":"The options cover a neutral range of visit frequencies and do not push shoppers towards one answer.","C":"The four tick-box answers are fixed, so this is a closed question whose responses can be tallied quickly for frequency analysis.","D":"The data is gathered directly from shoppers, which makes it primary rather than secondary."}}},{"id":"P1_U3_MCQ_1039","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1039","question":"Kellard Print, a small commercial printer, charges $0.40 per leaflet for a bulk order and is paid $2,400 in total for one print run. How many leaflets were printed in that order?","options":{"A":"6,000","B":"960","C":"600","D":"60,000"},"correctOption":"A","correctAnswer":"6,000","questionType":"MCQ","explanation":{"correct_reason":"Dividing the $2,400 total payment by the $0.40 price per leaflet gives 6,000 leaflets printed in the order.","distractor_reasons":{"A":"Dividing the $2,400 total payment by the $0.40 price per leaflet gives 6,000 leaflets printed in the order.","B":"960 multiplies $2,400 by $0.40 rather than dividing the payment by the unit price.","C":"600 misplaces the decimal point when dividing the $2,400 payment by $0.40.","D":"60,000 adds an extra zero, as if each leaflet cost only four cents."}}},{"id":"P1_U3_MCQ_1040","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1040","question":"Bexley Marine Insurance finds that most claims come from customers who did not read the policy documents. Which marketing action would best reduce this problem?","options":{"A":"Raising premiums for every customer without explanation.","B":"Removing all policy documents from the website.","C":"Withdrawing from the marine insurance market entirely.","D":"Sending a short plain-language summary of key policy terms when the policy is sold."},"correctOption":"D","correctAnswer":"Sending a short plain-language summary of key policy terms when the policy is sold.","questionType":"MCQ","explanation":{"correct_reason":"A brief plain-language summary makes the important terms easier for customers to understand, which should reduce avoidable claims and improve customer satisfaction.","distractor_reasons":{"A":"Higher premiums penalise all customers and do nothing to improve understanding of policy terms.","B":"Hiding the documents would make it even harder for customers to know what their policy covers.","C":"Leaving the market is a drastic response that destroys revenue instead of fixing communication.","D":"A brief plain-language summary makes the important terms easier for customers to understand, which should reduce avoidable claims and improve customer satisfaction."}}},{"id":"P1_U3_MCQ_1041","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1041","question":"Consumers in a city spend $5 million a year on carpet cleaning. Freshstart Carpet Care earns $750,000 from this work. What is Freshstart's market share by value?","options":{"A":"6.7%","B":"1.5%","C":"75%","D":"15%"},"correctOption":"D","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Its $750,000 of carpet cleaning revenue divided by the city's $5 million total gives 0.15, which is a 15% market share by value.","distractor_reasons":{"A":"6.7% reverses the division, treating the whole $5 million market as a fraction of Freshstart's own revenue.","B":"1.5% misplaces the decimal point after dividing $750,000 by $5,000,000.","C":"75% mistakes the $750,000 revenue figure for a percentage of the market rather than dividing it.","D":"Its $750,000 of carpet cleaning revenue divided by the city's $5 million total gives 0.15, which is a 15% market share by value."}}},{"id":"P1_U3_MCQ_1042","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1042","question":"Hollinwood Cycles asks 40 randomly selected customers to keep a diary of every journey for two weeks, including distance and purpose. What is the main advantage of this research method?","options":{"A":"It is cheaper than simply asking customers a few verbal questions.","B":"It records actual journeys over time rather than relying on memory at one moment.","C":"It guarantees that the 40 customers represent all cyclists nationally.","D":"It avoids the need to analyse any of the recorded information."},"correctOption":"B","correctAnswer":"It records actual journeys over time rather than relying on memory at one moment.","questionType":"MCQ","explanation":{"correct_reason":"A two-week diary captures real journeys as they happen, avoiding the recall errors that occur when customers are asked to remember trips later.","distractor_reasons":{"A":"Diaries require effort over two weeks and are usually more expensive to administer than a few verbal questions.","B":"A two-week diary captures real journeys as they happen, avoiding the recall errors that occur when customers are asked to remember trips later.","C":"Forty local customers cannot represent all cyclists in the country, so national representation is not guaranteed.","D":"The recorded journeys still have to be coded and analysed before managers can use them."}}},{"id":"P1_U3_MCQ_1043","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1043","question":"Thurlby Furniture makes a bookshelf at a unit cost of $54 and uses cost-plus pricing with a 20% mark-up on that cost. What selling price should it set?","options":{"A":"$10.80","B":"$59.40","C":"$64.80","D":"$74.00"},"correctOption":"C","correctAnswer":"$64.80","questionType":"MCQ","explanation":{"correct_reason":"A 20% mark-up on the $54 unit cost adds $10.80, so the cost-plus selling price is $54 plus $10.80, which equals $64.80.","distractor_reasons":{"A":"$10.80 is only the mark-up value and leaves out the $54 unit cost the price must recover.","B":"$59.40 applies only a 10% mark-up to the $54 cost rather than the 20% that Thurlby uses.","C":"A 20% mark-up on the $54 unit cost adds $10.80, so the cost-plus selling price is $54 plus $10.80, which equals $64.80.","D":"$74.00 applies a mark-up closer to 37% rather than the stated 20% on cost."}}},{"id":"P1_U3_MCQ_1044","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1044","question":"Sedgeworth Pianos has a strong reputation with music schools but almost no sales to households. It wants to enter the household market without damaging its professional image. Which strategy best fits?","options":{"A":"Launch a smaller home piano range, promoted through piano teachers and home furnishing magazines.","B":"Cut prices by 60% on all models and stop dealing with music schools.","C":"Move the factory to a cheaper country and ignore the household segment.","D":"Sell the same concert grand pianos to households with no changes at all."},"correctOption":"A","correctAnswer":"Launch a smaller home piano range, promoted through piano teachers and home furnishing magazines.","questionType":"MCQ","explanation":{"correct_reason":"A smaller home range and teacher recommendations reach households while preserving the professional reputation built with music schools.","distractor_reasons":{"A":"A smaller home range and teacher recommendations reach households while preserving the professional reputation built with music schools.","B":"Deep price cuts and abandoning schools would damage the premium reputation Sedgeworth wants to protect.","C":"Relocating production does nothing to attract households and ignores the stated market opportunity.","D":"Concert grands are too large and costly for most homes, so offering them unchanged will not win the segment."}}},{"id":"P1_U3_MCQ_1045","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1045","question":"Ardenby Laundry finds that customers under 30 mostly book online, while those over 60 prefer to telephone. What does this finding suggest for the business?","options":{"A":"It should offer only one contact method to keep costs low.","B":"It should keep both online booking and telephone contact to serve different customer groups.","C":"It should stop serving customers over 60 because they cost more.","D":"It should close the telephone line and force all customers online."},"correctOption":"B","correctAnswer":"It should keep both online booking and telephone contact to serve different customer groups.","questionType":"MCQ","explanation":{"correct_reason":"Two age groups prefer different channels, so offering both online booking and telephone keeps each segment able to buy, protecting revenue from both.","distractor_reasons":{"A":"One channel would inconvenience one of the two groups and could push them to competitors.","B":"Two age groups prefer different channels, so offering both online booking and telephone keeps each segment able to buy, protecting revenue from both.","C":"Dropping older customers removes a revenue stream without any evidence that they are unprofitable.","D":"Closing the phone line would alienate the over-60 group that prefers to telephone."}}},{"id":"P1_U3_MCQ_1046","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1046","question":"A student interviews shoppers outside a budget supermarket on a weekday morning to estimate demand for a luxury chocolate brand. Which criticism of this research is most serious?","options":{"A":"The sample is small, so no useful opinions will ever be found.","B":"The questionnaire uses numbers, which shoppers cannot understand.","C":"The shoppers interviewed are unlikely to represent the luxury brand's target customers.","D":"The research is secondary, so it must already be out of date."},"correctOption":"C","correctAnswer":"The shoppers interviewed are unlikely to represent the luxury brand's target customers.","questionType":"MCQ","explanation":{"correct_reason":"Budget supermarket shoppers on a weekday morning are a biased group for luxury chocolate, so their views may badly misjudge demand from wealthier buyers.","distractor_reasons":{"A":"A small sample reduces reliability but still yields opinions; the bias in who is questioned is the more serious flaw.","B":"Shoppers routinely answer questions involving prices and quantities without difficulty.","C":"Budget supermarket shoppers on a weekday morning are a biased group for luxury chocolate, so their views may badly misjudge demand from wealthier buyers.","D":"The interviews are first-hand, so the research is primary rather than secondary data."}}},{"id":"P1_U3_MCQ_1047","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1047","question":"Cawston Garden Ornaments spends $18,000 advertising a new fountain and expects to sell 240 of them during the campaign. What is the advertising cost per fountain sold?","options":{"A":"$75","B":"$7.50","C":"$750","D":"$24"},"correctOption":"A","correctAnswer":"$75","questionType":"MCQ","explanation":{"correct_reason":"Dividing the $18,000 advertising budget by the 240 fountains expected to be sold gives $75 of advertising cost per fountain.","distractor_reasons":{"A":"Dividing the $18,000 advertising budget by the 240 fountains expected to be sold gives $75 of advertising cost per fountain.","B":"$7.50 misplaces the decimal point when dividing $18,000 by 240 units.","C":"$750 adds an extra zero, as if the budget were $180,000 rather than $18,000.","D":"$24 divides the budget by 750 rather than by the 240 fountains actually expected to sell."}}},{"id":"P1_U3_MCQ_1048","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1048","question":"Halebury Frozen Foods sells mainly to large supermarket chains, which demand low prices and can switch suppliers quickly. What is the main marketing risk of this strategy?","options":{"A":"Supermarkets always pay above the market price for frozen food.","B":"Selling to chains removes any need for quality control.","C":"Chains refuse to stock branded frozen products of any kind.","D":"Too much bargaining power sits with a few buyers, so margins and sales volumes are vulnerable."},"correctOption":"D","correctAnswer":"Too much bargaining power sits with a few buyers, so margins and sales volumes are vulnerable.","questionType":"MCQ","explanation":{"correct_reason":"Relying on a few powerful chains lets those buyers press for lower prices and move orders elsewhere, which threatens both Halebury's margins and its volume.","distractor_reasons":{"A":"Large chains use their power to negotiate low purchase prices, not premium ones.","B":"Supermarkets impose strict quality standards, so quality control becomes more important rather than unnecessary.","C":"Chains do stock branded frozen foods; the issue is the balance of power, not a refusal to stock brands.","D":"Relying on a few powerful chains lets those buyers press for lower prices and move orders elsewhere, which threatens both Halebury's margins and its volume."}}},{"id":"P1_U3_MCQ_1049","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1049","question":"Penrith Office Supplies has sales of $1.44 million, which its managers calculate is a 12% share of the regional office supplies market. What is the total value of that market?","options":{"A":"$1.73 million","B":"$17.28 million","C":"$12 million","D":"$120 million"},"correctOption":"C","correctAnswer":"$12 million","questionType":"MCQ","explanation":{"correct_reason":"If $1.44 million is 12% of the market, the whole market is $1.44 million divided by 0.12, which equals $12 million.","distractor_reasons":{"A":"$1.73 million multiplies $1.44 million by 1.2 instead of dividing by the 12% share.","B":"$17.28 million multiplies $1.44 million by 12 rather than dividing by 0.12.","C":"If $1.44 million is 12% of the market, the whole market is $1.44 million divided by 0.12, which equals $12 million.","D":"$120 million places the decimal point one place too far to the right after the division."}}},{"id":"P1_U3_MCQ_1050","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1050","question":"Marden Pet Clinic, a veterinary practice with four branches, emails a satisfaction survey to 2,000 clients and receives only 80 replies. What is the response rate, and why does it matter?","options":{"A":"40%, which makes the results highly reliable.","B":"4%, so the replies may not represent the views of all 2,000 clients.","C":"0.4%, which is still enough to represent every client.","D":"25%, which means three-quarters of clients were satisfied."},"correctOption":"B","correctAnswer":"4%, so the replies may not represent the views of all 2,000 clients.","questionType":"MCQ","explanation":{"correct_reason":"Eighty replies out of 2,000 is a 4% response rate, so the sample is small and may not reflect the opinions of the whole client list.","distractor_reasons":{"A":"40% would require 800 replies, not the 80 that Marden actually received.","B":"Eighty replies out of 2,000 is a 4% response rate, so the sample is small and may not reflect the opinions of the whole client list.","C":"0.4% misplaces the decimal point and a tiny response would weaken rather than strengthen representation.","D":"The 80 replies say nothing about how many of the 2,000 clients were satisfied."}}},{"id":"P1_U3_MCQ_1051","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1051","question":"Elmsworth Confectionery packs its fudge in gold boxes for gift shops and in plain bags for garage forecourts. Which element of the marketing mix is being changed between the two versions?","options":{"A":"Place, because gift shops and garages are different outlets.","B":"Product, because packaging is part of how the physical good is presented to buyers.","C":"Price, because the gold box must cost the same as the plain bag.","D":"Promotion, because packaging never communicates anything to customers."},"correctOption":"B","correctAnswer":"Product, because packaging is part of how the physical good is presented to buyers.","questionType":"MCQ","explanation":{"correct_reason":"Packaging design is a product decision because it changes the appearance, protection and perceived quality of the fudge, even when the contents stay the same.","distractor_reasons":{"A":"The outlets differ too, but the question asks about the packaging change, which belongs to the product element.","B":"Packaging design is a product decision because it changes the appearance, protection and perceived quality of the fudge, even when the contents stay the same.","C":"Nothing in the scenario says the two packs carry the same price, and packaging is not primarily a price decision.","D":"Packaging often communicates brand and quality, so it can support promotion rather than being separate from communication."}}},{"id":"P1_U3_MCQ_1052","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1052","question":"Gresham Home Care provides cleaning visits to elderly clients. A rival has begun offering the same service at a lower hourly rate. Which response best protects Gresham's business without starting a damaging price war?","options":{"A":"Match the lower rate exactly and cut staff training to fund it.","B":"Ignore the rival and make no changes to the service.","C":"Emphasise reliable, police-checked carers and offer a free first visit instead of cutting the rate.","D":"Increase the hourly rate to signal higher quality to clients."},"correctOption":"C","correctAnswer":"Emphasise reliable, police-checked carers and offer a free first visit instead of cutting the rate.","questionType":"MCQ","explanation":{"correct_reason":"Highlighting trustworthy, checked carers and adding a free trial raises the perceived value of Gresham's service without triggering a price war that would squeeze margins.","distractor_reasons":{"A":"Matching the rate while cutting training undermines the service quality that elderly clients and their families value most.","B":"Making no changes leaves the cheaper rival as the obvious choice for price-sensitive families.","C":"Highlighting trustworthy, checked carers and adding a free trial raises the perceived value of Gresham's service without triggering a price war that would squeeze margins.","D":"Raising the rate widens the price gap with the rival and may push clients to switch."}}},{"id":"P1_U3_MCQ_1053","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1053","question":"Demand for electric bikes in a country rose from 40,000 units in 2024 to 46,000 units in 2025. What was the percentage growth in this market?","options":{"A":"15%","B":"13%","C":"6%","D":"115%"},"correctOption":"A","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"The market grew by 6,000 units, and 6,000 divided by the original 40,000 multiplied by 100 gives growth of 15%.","distractor_reasons":{"A":"The market grew by 6,000 units, and 6,000 divided by the original 40,000 multiplied by 100 gives growth of 15%.","B":"13% divides the 6,000 increase by the new 46,000 total rather than the 40,000 starting figure.","C":"6% mistakes the 6,000 unit increase for a percentage without dividing by the original market size.","D":"115% is the 2025 market expressed as a percentage of 2024, not the growth rate itself."}}},{"id":"P1_U3_MCQ_1054","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1054","question":"A manager at Stowbridge Leisure reads a two-year-old national report on gym attendance to decide whether to open a new site. Why should the manager treat the report with caution?","options":{"A":"Secondary data is always collected by the manager personally.","B":"National reports never contain any numerical data.","C":"Published reports cannot be used by private businesses.","D":"It was gathered for another purpose and may be too dated or general for the local decision."},"correctOption":"D","correctAnswer":"It was gathered for another purpose and may be too dated or general for the local decision.","questionType":"MCQ","explanation":{"correct_reason":"The report was compiled for a national audience two years ago, so its age and broad scope may not reflect current local demand around the proposed site.","distractor_reasons":{"A":"Secondary data is collected by someone else, which is exactly why the manager did not gather it personally.","B":"National reports usually contain plenty of statistics, including attendance and spending figures.","C":"Private businesses are free to buy and use published reports; there is no such restriction.","D":"The report was compiled for a national audience two years ago, so its age and broad scope may not reflect current local demand around the proposed site."}}},{"id":"P1_U3_MCQ_1055","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1055","question":"Ravensholt Bags makes a rucksack at a unit cost of $45 and applies a 60% mark-up under its cost-plus pricing policy. What selling price does this produce?","options":{"A":"$27","B":"$72","C":"$105","D":"$45.60"},"correctOption":"B","correctAnswer":"$72","questionType":"MCQ","explanation":{"correct_reason":"A 60% mark-up on the $45 unit cost adds $27, so the cost-plus selling price is $45 plus $27, which equals $72 per rucksack.","distractor_reasons":{"A":"$27 is only the mark-up and omits the $45 unit cost that the selling price must recover.","B":"A 60% mark-up on the $45 unit cost adds $27, so the cost-plus selling price is $45 plus $27, which equals $72 per rucksack.","C":"$105 adds the $45 cost twice over, producing a mark-up far above the stated 60%.","D":"$45.60 treats the 60% as 60 cents added to cost rather than 60% of $45."}}},{"id":"P1_U3_MCQ_1056","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1056","question":"Welby Toys, a family-run puzzle maker, sells its products only through independent toy shops and never through supermarkets. How does this distribution choice support its marketing strategy?","options":{"A":"It guarantees the puzzles will be the cheapest on the market.","B":"It removes the need to advertise or build a brand.","C":"It protects a specialist image and lets staff give knowledgeable advice to buyers.","D":"It means the firm no longer needs to choose a price."},"correctOption":"C","correctAnswer":"It protects a specialist image and lets staff give knowledgeable advice to buyers.","questionType":"MCQ","explanation":{"correct_reason":"Independent toy shops reinforce Welby's specialist positioning, and their trained staff can explain the puzzles in ways that support a premium brand image.","distractor_reasons":{"A":"Specialist outlets usually sell at higher prices than supermarkets, so this choice works against being cheapest.","B":"Brand building and advertising are still needed even when specialist retailers are used.","C":"Independent toy shops reinforce Welby's specialist positioning, and their trained staff can explain the puzzles in ways that support a premium brand image.","D":"The manufacturer must still set a recommended price and consider retailer margins whatever channel it uses."}}},{"id":"P1_U3_MCQ_1057","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1057","question":"Cranfield Office Cleaning, which employs 90 cleaners in one city, checks two rivals' prices and service promises every quarter. Why is this competitor monitoring useful?","options":{"A":"It guarantees Cranfield can charge whatever price it wishes.","B":"It removes the need to ask clients for feedback about service quality.","C":"It reveals rivals' exact costs, which Cranfield can then copy precisely.","D":"It shows changes in rivals' offers so Cranfield can adjust its price and service to stay competitive."},"correctOption":"D","correctAnswer":"It shows changes in rivals' offers so Cranfield can adjust its price and service to stay competitive.","questionType":"MCQ","explanation":{"correct_reason":"Regular checks reveal when a rival cuts prices or promises extra services, giving Cranfield early warning to respond before clients switch their contracts.","distractor_reasons":{"A":"Rivals' prices constrain what Cranfield can charge, so monitoring limits rather than guarantees pricing freedom.","B":"Client feedback reveals satisfaction with Cranfield itself, which competitor prices cannot replace.","C":"Published prices do not reveal a rival's internal costs, so exact cost copying is impossible.","D":"Regular checks reveal when a rival cuts prices or promises extra services, giving Cranfield early warning to respond before clients switch their contracts."}}},{"id":"P1_U3_MCQ_1058","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1058","question":"Denby Tools asks 600 randomly selected tradespeople to complete a postal questionnaire about a new drill. Only 90 forms are returned. Which conclusion about the research is most justified?","options":{"A":"The 15% return rate may create bias, so findings should be checked before a launch decision.","B":"The 90 replies are enough to represent all tradespeople in the country.","C":"A 15% response rate proves the questionnaire was perfectly designed.","D":"Postal questionnaires always produce more replies than face-to-face interviews."},"correctOption":"A","correctAnswer":"The 15% return rate may create bias, so findings should be checked before a launch decision.","questionType":"MCQ","explanation":{"correct_reason":"Only 90 of 600 forms came back, a 15% return, and those who reply may differ from those who ignore the survey, so Denby should verify the findings.","distractor_reasons":{"A":"Only 90 of 600 forms came back, a 15% return, and those who reply may differ from those who ignore the survey, so Denby should verify the findings.","B":"Ninety respondents cannot represent every tradesperson nationally, especially when most did not reply.","C":"A low return rate suggests the questionnaire or its distribution failed to engage recipients rather than proving good design.","D":"Face-to-face interviews usually achieve much higher response rates than postal questionnaires."}}},{"id":"P1_U3_MCQ_1059","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1059","question":"Oakhampton Pools budgets $27,000 to promote a new swimming class and expects 900 people to sign up during the campaign. What is the promotional cost per sign-up?","options":{"A":"$3","B":"$270","C":"$30","D":"$33"},"correctOption":"C","correctAnswer":"$30","questionType":"MCQ","explanation":{"correct_reason":"The $27,000 budget divided by the 900 expected sign-ups gives a promotional cost of $30 for each person who joins the class.","distractor_reasons":{"A":"$3 misplaces the decimal point when dividing $27,000 by 900 sign-ups.","B":"$270 divides the budget by 100 rather than by the 900 people expected to sign up.","C":"The $27,000 budget divided by the 900 expected sign-ups gives a promotional cost of $30 for each person who joins the class.","D":"$33 divides the budget by about 818 sign-ups instead of the stated 900."}}},{"id":"P1_U3_MCQ_1060","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1060","question":"InsideOut Storage wants to attract people moving house. Its research shows most moves happen in summer and that customers search online for short-notice space. Which marketing strategy fits this evidence?","options":{"A":"Increase online advertising and short-term offers in the summer months.","B":"Spend the whole annual budget on television in December.","C":"Raise prices in summer and stop all online advertising.","D":"Target only businesses that never move premises."},"correctOption":"A","correctAnswer":"Increase online advertising and short-term offers in the summer months.","questionType":"MCQ","explanation":{"correct_reason":"The research points to summer demand and online searching, so concentrating online promotion and short-term offers in summer matches when and how customers look.","distractor_reasons":{"A":"The research points to summer demand and online searching, so concentrating online promotion and short-term offers in summer matches when and how customers look.","B":"December television spending misses both the summer peak and the online search habit revealed by research.","C":"Raising summer prices while cutting advertising works against the seasonal opportunity the data identifies.","D":"Businesses that never move are a tiny, unrelated segment and ignore the household moving market."}}},{"id":"P1_U3_MCQ_1061","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1061","question":"Total sales of household insurance in a region are worth $40 million a year. Kernwell Insurance earns $6 million of premiums in that region. What market share does Kernwell hold by value?","options":{"A":"6.7%","B":"1.5%","C":"15%","D":"66.7%"},"correctOption":"C","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Kernwell's $6 million of premiums divided by the region's $40 million total gives 0.15, which is a 15% share by value.","distractor_reasons":{"A":"6.7% reverses the division and treats the regional market as a fraction of Kernwell's own premiums.","B":"1.5% misplaces the decimal point after dividing $6 million by $40 million.","C":"Kernwell's $6 million of premiums divided by the region's $40 million total gives 0.15, which is a 15% share by value.","D":"66.7% divides $40 million by $60 million, using numbers that do not reflect the scenario."}}},{"id":"P1_U3_MCQ_1062","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1062","question":"A researcher working for Thackley Retail Park stops shoppers by the entrance and asks: 'Our car park is convenient, isn't it?' Why is this a poor survey question?","options":{"A":"It is leading, because it invites shoppers to agree rather than express a genuine view.","B":"It is too open, so shoppers will write very long answers.","C":"It asks about car parks, which surveys cannot measure.","D":"It contains too many numerical options for shoppers to compare."},"correctOption":"A","correctAnswer":"It is leading, because it invites shoppers to agree rather than express a genuine view.","questionType":"MCQ","explanation":{"correct_reason":"Phrasing the item as 'isn't it?' pushes respondents towards agreement, so the results will overstate satisfaction with the car park.","distractor_reasons":{"A":"Phrasing the item as 'isn't it?' pushes respondents towards agreement, so the results will overstate satisfaction with the car park.","B":"The question is closed and invites a short agree or disagree response, not a long written answer.","C":"Surveys regularly measure satisfaction with facilities such as car parks, so the topic is suitable.","D":"No numbered options are offered at all, so there are no figures for shoppers to compare."}}},{"id":"P1_U3_MCQ_1063","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1063","question":"Skerrymore Outdoors lists a waterproof jacket at $120. In a clearance sale it offers 30% off the listed price. What is the sale price of the jacket?","options":{"A":"$36","B":"$90","C":"$117","D":"$84"},"correctOption":"D","correctAnswer":"$84","questionType":"MCQ","explanation":{"correct_reason":"A 30% discount on $120 removes $36, leaving a sale price of $120 minus $36, which equals $84.","distractor_reasons":{"A":"$36 is only the value of the discount and is not the price the customer actually pays.","B":"$90 applies a 25% discount to $120 rather than the 30% stated in the sale.","C":"$117 removes only $3, which is a 2.5% reduction rather than 30%.","D":"A 30% discount on $120 removes $36, leaving a sale price of $120 minus $36, which equals $84."}}},{"id":"P1_U3_MCQ_1064","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1064","question":"A small independent cinema, the Rexford Picture House, cannot compete with a multiplex on price or screen size. Which strategy is most likely to secure its future?","options":{"A":"Cutting ticket prices below the multiplex and showing the same films.","B":"Building four more screens and matching the multiplex's popcorn prices.","C":"Offering classic films, themed evenings and locally sourced food to a loyal adult audience.","D":"Closing at weekends when the multiplex is busiest."},"correctOption":"C","correctAnswer":"Offering classic films, themed evenings and locally sourced food to a loyal adult audience.","questionType":"MCQ","explanation":{"correct_reason":"Serving a distinctive experience that the multiplex does not offer gives customers a reason to choose the Rexford and avoids a price fight it cannot win.","distractor_reasons":{"A":"Undercutting a larger rival on identical films merely sparks a price war the small cinema cannot fund.","B":"Expanding to four screens copies the multiplex's advantage and demands capital the cinema lacks.","C":"Serving a distinctive experience that the multiplex does not offer gives customers a reason to choose the Rexford and avoids a price fight it cannot win.","D":"Weekends are the busiest cinema period, so closing then would cut off most potential revenue."}}},{"id":"P1_U3_MCQ_1065","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1065","question":"Barrowfield Garden Centre, which trades from a large site near a bypass, sells 18,000 bags of compost a year at $5.50 each. What is its annual revenue from compost?","options":{"A":"$99,000","B":"$9,900","C":"$3,273","D":"$990,000"},"correctOption":"A","correctAnswer":"$99,000","questionType":"MCQ","explanation":{"correct_reason":"Revenue equals 18,000 bags multiplied by the $5.50 price, which calculates to $99,000 of compost sales for the year.","distractor_reasons":{"A":"Revenue equals 18,000 bags multiplied by the $5.50 price, which calculates to $99,000 of compost sales for the year.","B":"$9,900 divides the correct answer by ten, as if the price were $0.55 per bag.","C":"$3,273 divides 18,000 by 5.50 instead of multiplying quantity by price.","D":"$990,000 adds an extra zero, as if the price were $55 per bag."}}},{"id":"P1_U3_MCQ_1066","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1066","question":"Harnwell Foods wants to know how many households in a town would buy a new ready meal and what they would pay. Which research approach is most appropriate?","options":{"A":"Reading the firm's own sales records for its existing products.","B":"Interviewing the firm's production staff about their workload.","C":"Reviewing last year's national advertising spend.","D":"A survey of a random sample of local households asking about buying intentions and acceptable prices."},"correctOption":"D","correctAnswer":"A survey of a random sample of local households asking about buying intentions and acceptable prices.","questionType":"MCQ","explanation":{"correct_reason":"A random sample of local households directly measures both how many would buy and what price they would accept, which are the two questions Harnwell needs answered.","distractor_reasons":{"A":"Past sales of other products say nothing about demand for a new ready meal or its acceptable price.","B":"Production staff know about workloads, not household buying intentions or willingness to pay.","C":"National advertising spend is an internal cost figure and does not reveal local consumer demand.","D":"A random sample of local households directly measures both how many would buy and what price they would accept, which are the two questions Harnwell needs answered."}}},{"id":"P1_U3_MCQ_1067","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1067","question":"Wroxham Lighting makes a desk lamp at a unit cost of $26 and adds a 50% mark-up when setting its cost-plus price. What price does it charge?","options":{"A":"$13","B":"$39","C":"$52","D":"$26.50"},"correctOption":"B","correctAnswer":"$39","questionType":"MCQ","explanation":{"correct_reason":"A 50% mark-up on the $26 unit cost adds $13, so the cost-plus price is $26 plus $13, which equals $39 per lamp.","distractor_reasons":{"A":"$13 is only the mark-up amount and leaves out the $26 unit cost that must also be covered.","B":"A 50% mark-up on the $26 unit cost adds $13, so the cost-plus price is $26 plus $13, which equals $39 per lamp.","C":"$52 doubles the cost and adds nothing further, which applies a 100% mark-up instead of 50%.","D":"$26.50 treats the 50% as 50 cents added to cost rather than half of $26."}}},{"id":"P1_U3_MCQ_1068","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1068","question":"Ashwater Cosmetics sells online only. Its research shows that many customers abandon baskets at checkout because delivery costs appear late. Which marketing action best addresses this?","options":{"A":"Raising product prices to cover the delivery cost silently.","B":"Adding more products to the website homepage.","C":"Showing delivery charges clearly on the product page and offering free delivery above a set spend.","D":"Removing customer reviews from the product pages."},"correctOption":"C","correctAnswer":"Showing delivery charges clearly on the product page and offering free delivery above a set spend.","questionType":"MCQ","explanation":{"correct_reason":"Late, unexpected delivery charges cause the abandoned baskets, so displaying them early and incentivising a higher spend removes the shock at checkout.","distractor_reasons":{"A":"Hiding delivery inside product prices still raises the total and does not make charges transparent.","B":"Adding homepage products does not fix the checkout surprise that is driving customers away.","C":"Late, unexpected delivery charges cause the abandoned baskets, so displaying them early and incentivising a higher spend removes the shock at checkout.","D":"Customer reviews support purchase decisions, so removing them would likely reduce sales further."}}},{"id":"P1_U3_MCQ_1069","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1069","question":"Consumers in a town buy 50,000 takeaway meals a year. Spice Lane Takeaway sells 8,000 of them, while its main rival sells 12,000. What is Spice Lane's market share?","options":{"A":"24%","B":"20%","C":"6.7%","D":"16%"},"correctOption":"D","correctAnswer":"16%","questionType":"MCQ","explanation":{"correct_reason":"Spice Lane's 8,000 meals divided by the town's 50,000 total gives 0.16, which is a 16% share of the takeaway market.","distractor_reasons":{"A":"24% is the main rival's share from 12,000 meals, not Spice Lane's share.","B":"20% would require Spice Lane to sell 10,000 meals, which is more than its actual 8,000.","C":"6.7% divides 8,000 by 120,000 rather than by the correct 50,000 market total.","D":"Spice Lane's 8,000 meals divided by the town's 50,000 total gives 0.16, which is a 16% share of the takeaway market."}}},{"id":"P1_U3_MCQ_1070","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1070","question":"A firm planning a new soft drink has $6,000 for research. Primary interviews would cost $30 each. What does this budget allow, and what is the main limitation of the resulting sample?","options":{"A":"200 interviews, which may be too few to represent the whole target market reliably.","B":"20 interviews, which is more than enough to represent the market.","C":"2,000 interviews, which would guarantee perfect accuracy.","D":"600 interviews, which removes the need for a questionnaire."},"correctOption":"A","correctAnswer":"200 interviews, which may be too few to represent the whole target market reliably.","questionType":"MCQ","explanation":{"correct_reason":"Dividing $6,000 by $30 gives 200 interviews, but a sample that size from a national market may still be too small to be fully representative.","distractor_reasons":{"A":"Dividing $6,000 by $30 gives 200 interviews, but a sample that size from a national market may still be too small to be fully representative.","B":"20 interviews would cost only $600, far below the $6,000 available budget.","C":"2,000 interviews would cost $60,000, which is ten times the stated research budget.","D":"600 interviews would cost $18,000, which exceeds the $6,000 budget entirely."}}},{"id":"P1_U3_MCQ_1071","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1071","question":"Marchmont Cycles, a small independent bike shop, buys safety helmets for $18 each and sells them to customers for $27. What is the mark-up as a percentage of the buying-in cost?","options":{"A":"33.3%","B":"50%","C":"9%","D":"150%"},"correctOption":"B","correctAnswer":"50%","questionType":"MCQ","explanation":{"correct_reason":"The $9 mark-up divided by the $18 buying-in cost gives 0.5, which is a mark-up of 50% on cost.","distractor_reasons":{"A":"33.3% divides the $9 mark-up by the $27 selling price rather than by the $18 cost.","B":"The $9 mark-up divided by the $18 buying-in cost gives 0.5, which is a mark-up of 50% on cost.","C":"9% mistakes the $9 cash mark-up for a percentage without dividing it by the cost price.","D":"150% expresses the $27 selling price as a percentage of the $18 cost, which includes the cost itself."}}},{"id":"P1_U3_MCQ_1072","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1072","question":"Breckon & Vane, a family firm making garden benches from hardwood, faces rising timber costs. Which marketing response protects profit without simply raising prices across the board?","options":{"A":"Reduce the bench guarantee from five years to one month.","B":"Stop advertising and hope existing customers return.","C":"Introduce a smaller, lower-cost bench for price-sensitive buyers while keeping the premium range.","D":"Copy every rival's price exactly, whatever their costs."},"correctOption":"C","correctAnswer":"Introduce a smaller, lower-cost bench for price-sensitive buyers while keeping the premium range.","questionType":"MCQ","explanation":{"correct_reason":"A smaller bench uses less timber and can be sold at a lower price to cost-conscious buyers, while the premium range still carries the higher margin.","distractor_reasons":{"A":"Slashing the guarantee destroys the quality reputation that supports the premium range's higher prices.","B":"Withdrawing advertising would reduce sales exactly when rising costs make volume important.","C":"A smaller bench uses less timber and can be sold at a lower price to cost-conscious buyers, while the premium range still carries the higher margin.","D":"Copying rival prices ignores Breckon's own cost structure and may sell below cost."}}},{"id":"P1_U3_MCQ_1073","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1073","question":"Outdoor clothing sales in a region total $8 million a year. Trailhead Gear sells $960,000 worth. Its rival, Moorland Outfitters, sells $1.44 million worth. What is Trailhead's market share?","options":{"A":"18%","B":"8.3%","C":"12%","D":"14.4%"},"correctOption":"C","correctAnswer":"12%","questionType":"MCQ","explanation":{"correct_reason":"Trailhead's $960,000 of sales divided by the region's $8 million total gives 0.12, a market share of 12%.","distractor_reasons":{"A":"18% is Moorland's share from $1.44 million of sales, not Trailhead's share.","B":"8.3% reverses the division and treats the $8 million market as a fraction of Trailhead's sales.","C":"Trailhead's $960,000 of sales divided by the region's $8 million total gives 0.12, a market share of 12%.","D":"14.4% mistakes Moorland's $1.44 million of sales for a percentage share of Trailhead's revenue."}}},{"id":"P1_U3_MCQ_1074","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1074","question":"Bexhill Music School surveys 300 parents about lesson times. It finds 60% prefer Saturday mornings and 40% prefer weekday evenings. How should managers use this finding?","options":{"A":"Offer both Saturday morning and weekday evening slots to match the split preference.","B":"Offer only evening lessons because 40% is a majority.","C":"Ignore the survey because preferences cannot be measured.","D":"Offer only Saturday lessons because that group is larger."},"correctOption":"A","correctAnswer":"Offer both Saturday morning and weekday evening slots to match the split preference.","questionType":"MCQ","explanation":{"correct_reason":"With 60% preferring Saturday and 40% preferring evenings, running both keeps most families satisfied and avoids losing the sizable evening group.","distractor_reasons":{"A":"With 60% preferring Saturday and 40% preferring evenings, running both keeps most families satisfied and avoids losing the sizable evening group.","B":"40% is a minority, not a majority, so evening-only lessons would exclude the larger Saturday group.","C":"The survey clearly quantifies two preferences, so the data can guide scheduling decisions.","D":"Saturday-only lessons would alienate the 40% of parents who chose weekday evenings."}}},{"id":"P1_U3_MCQ_1075","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1075","question":"Alverton Ceramics produces a teapot at a unit cost of $14. It uses cost-plus pricing with a mark-up of 25% on cost. What selling price results?","options":{"A":"$3.50","B":"$16.80","C":"$17.50","D":"$28.00"},"correctOption":"C","correctAnswer":"$17.50","questionType":"MCQ","explanation":{"correct_reason":"A 25% mark-up on the $14 unit cost adds $3.50, so the cost-plus selling price is $14 plus $3.50, which equals $17.50.","distractor_reasons":{"A":"$3.50 is only the mark-up amount and omits the $14 unit cost the price must recover.","B":"$16.80 applies only a 20% mark-up to the $14 cost rather than the 25% that Alverton uses.","C":"A 25% mark-up on the $14 unit cost adds $3.50, so the cost-plus selling price is $14 plus $3.50, which equals $17.50.","D":"$28.00 doubles the cost, which applies a 100% mark-up rather than the stated 25%."}}},{"id":"P1_U3_MCQ_1076","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1076","question":"Carrickdale Hotels, a 60-room hotel in a busy market town, wants to raise occupancy in January, when rooms are heavily discounted. Which marketing strategy would best support this aim?","options":{"A":"Promote weekend spa packages and partner with local theatres for winter breaks.","B":"Increase January room rates and withdraw all promotions.","C":"Close the hotel for the whole of January.","D":"Advertise only to summer holidaymakers in July."},"correctOption":"A","correctAnswer":"Promote weekend spa packages and partner with local theatres for winter breaks.","questionType":"MCQ","explanation":{"correct_reason":"Weekend packages and theatre partnerships give people specific reasons to stay in January, filling rooms that would otherwise be heavily discounted or empty.","distractor_reasons":{"A":"Weekend packages and theatre partnerships give people specific reasons to stay in January, filling rooms that would otherwise be heavily discounted or empty.","B":"Higher January rates and no promotion would make an already quiet month even emptier.","C":"Closing for the month guarantees zero revenue instead of raising occupancy.","D":"Advertising to summer holidaymakers in July does nothing for January occupancy."}}},{"id":"P1_U3_MCQ_1077","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1077","question":"Wendlebury Bakery spends $12,000 promoting a new sourdough loaf and expects to sell 4,000 loaves during the campaign. What is the promotional cost per loaf?","options":{"A":"$0.30","B":"$3","C":"$30","D":"$4.80"},"correctOption":"B","correctAnswer":"$3","questionType":"MCQ","explanation":{"correct_reason":"The $12,000 promotional budget divided by the 4,000 loaves expected to sell gives a promotional cost of $3 per loaf.","distractor_reasons":{"A":"$0.30 misplaces the decimal point when dividing $12,000 by 4,000 loaves.","B":"The $12,000 promotional budget divided by the 4,000 loaves expected to sell gives a promotional cost of $3 per loaf.","C":"$30 divides the budget by 400 rather than by the 4,000 loaves expected to sell.","D":"$4.80 divides the budget by 2,500 loaves instead of the stated 4,000."}}},{"id":"P1_U3_MCQ_1078","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1078","question":"Somerby Leisure asks every visitor to scan a code and complete a short online form over one weekend in August. Why might the results mislead managers?","options":{"A":"The sample size is guaranteed to be too large to analyse.","B":"Online forms cannot record customer opinions.","C":"Visitors in August are all local residents.","D":"Only visitors that weekend are included, and holiday crowds may differ from visitors at other times."},"correctOption":"D","correctAnswer":"Only visitors that weekend are included, and holiday crowds may differ from visitors at other times.","questionType":"MCQ","explanation":{"correct_reason":"A single August weekend captures holiday visitors who may differ from term-time or winter customers, so the findings may not represent the whole year's market.","distractor_reasons":{"A":"A larger sample usually helps analysis, so size is not the reason the results could mislead.","B":"Online forms are a standard way of recording opinions and can collect both ratings and comments.","C":"August visitors often include tourists, so assuming they are all local residents is false.","D":"A single August weekend captures holiday visitors who may differ from term-time or winter customers, so the findings may not represent the whole year's market."}}},{"id":"P1_U3_MCQ_1079","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1079","question":"Dalton & Reeve sells 5,000 desk organisers a year at $16 each. It is considering a $4 rise in price but expects sales to fall to 4,000 units. What happens to revenue?","options":{"A":"Revenue rises from $80,000 to $80,000, so it is unchanged.","B":"Revenue falls from $80,000 to $64,000.","C":"Revenue rises from $80,000 to $96,000.","D":"Revenue falls from $96,000 to $80,000."},"correctOption":"A","correctAnswer":"Revenue rises from $80,000 to $80,000, so it is unchanged.","questionType":"MCQ","explanation":{"correct_reason":"Current revenue is 5,000 times $16, which is $80,000, and the new revenue is 4,000 times $20, also $80,000, so total revenue does not change.","distractor_reasons":{"A":"Current revenue is 5,000 times $16, which is $80,000, and the new revenue is 4,000 times $20, also $80,000, so total revenue does not change.","B":"$64,000 would need sales of 4,000 units at the old $16 price, but the new price is $20.","C":"$96,000 would need all 4,800 units to sell at $20, which contradicts the expected fall to 4,000.","D":"$96,000 is not the current revenue, since 5,000 units at $16 gives only $80,000."}}},{"id":"P1_U3_MCQ_1080","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1080","question":"Rothbury Garden Rooms sells conservatories to wealthy homeowners and simple sheds to allotment holders. Why does the firm need separate marketing strategies for the two groups?","options":{"A":"Both groups read the same magazines and respond to identical messages.","B":"Marketing strategy can only ever cover one product range.","C":"The two groups differ in income, buying motives and the media they use.","D":"Allotment holders are legally barred from buying conservatories."},"correctOption":"C","correctAnswer":"The two groups differ in income, buying motives and the media they use.","questionType":"MCQ","explanation":{"correct_reason":"Wealthy homeowners and allotment holders have very different budgets, reasons for buying and preferred media, so Rothbury needs distinct messages, channels and prices.","distractor_reasons":{"A":"The two groups usually read different publications and respond to different appeals, so one message will not suit both.","B":"A firm can run several strategies at once, and the scenario shows two ranges needing different treatment.","C":"Wealthy homeowners and allotment holders have very different budgets, reasons for buying and preferred media, so Rothbury needs distinct messages, channels and prices.","D":"There is no legal bar preventing allotment holders from buying conservatories; the difference is income and interest."}}},{"id":"P1_U3_MCQ_1081","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1081","question":"Dog owners in a county buy 90,000 sacks of dog food a year. Marlbrook Outdoor supplies 12,600 of these sacks through farm stores. What is Marlbrook's market share by volume?","options":{"A":"8.6%","B":"12.6%","C":"16.8%","D":"14%"},"correctOption":"D","correctAnswer":"14%","questionType":"MCQ","explanation":{"correct_reason":"Marlbrook's 12,600 sacks divided by the county's 90,000 sack market gives 0.14, which is a 14% share by volume.","distractor_reasons":{"A":"8.6% divides 12,600 by 146,000 rather than by the 90,000 sacks actually sold in the county.","B":"12.6% mistakes the 12,600 sacks figure for a percentage of the total market.","C":"16.8% divides 12,600 by 75,000, using a market size that is not stated in the scenario.","D":"Marlbrook's 12,600 sacks divided by the county's 90,000 sack market gives 0.14, which is a 14% share by volume."}}},{"id":"P1_U3_MCQ_1082","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1082","question":"Brayford Leisure posts a questionnaire to 3,000 members. Most items ask members to tick one of five boxes rather than write a paragraph. Why is this design useful for the business?","options":{"A":"It guarantees that every member will return the form.","B":"Tick-box answers are quick for members to complete and easy to count and compare.","C":"It allows members to raise issues the business never expected.","D":"It removes the need to choose a representative sample."},"correctOption":"B","correctAnswer":"Tick-box answers are quick for members to complete and easy to count and compare.","questionType":"MCQ","explanation":{"correct_reason":"Closed tick-box items take little effort to answer and produce figures that can be totalled and compared quickly across 3,000 members.","distractor_reasons":{"A":"A postal questionnaire cannot force members to reply, and response rates are often low.","B":"Closed tick-box items take little effort to answer and produce figures that can be totalled and compared quickly across 3,000 members.","C":"Unexpected issues are more likely to surface in open questions that invite written comments.","D":"A representative sample still has to be selected before the forms are sent out."}}},{"id":"P1_U3_MCQ_1083","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1083","question":"Holbeach Interiors sells lamp shades to independent lighting shops. It offers these retailers a 20% trade discount off its list price. Why does Holbeach offer this discount?","options":{"A":"To make the shades more expensive for shoppers than the list price suggests.","B":"So retailers can add their own mark-up and still sell at a competitive price while earning a margin.","C":"Because retailers are legally entitled to a discount on every trade order.","D":"To avoid having to set any list price for the shades at all."},"correctOption":"B","correctAnswer":"So retailers can add their own mark-up and still sell at a competitive price while earning a margin.","questionType":"MCQ","explanation":{"correct_reason":"A trade discount leaves room for the lighting shop to add its own profit margin yet still offer shoppers a price Holbeach wants, which encourages retailers to stock the range.","distractor_reasons":{"A":"The discount lowers the retailer's buying cost and normally supports lower, not higher, shop prices.","B":"A trade discount leaves room for the lighting shop to add its own profit margin yet still offer shoppers a price Holbeach wants, which encourages retailers to stock the range.","C":"Trade discounts are a commercial negotiation, not a legal entitlement owed to every retailer.","D":"Holbeach must still publish a list price from which the 20% discount is calculated."}}},{"id":"P1_U3_MCQ_1084","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1084","question":"Wainwright Removals, a family firm with six vans, is deciding how to market its service. Why should it identify its target customers before choosing its price, promotion and vehicle livery?","options":{"A":"Because the marketing mix can then be designed to appeal to those specific customers.","B":"Because identifying customers sets the firm's tax rate for the year.","C":"Because target customers always choose the cheapest removal firm.","D":"Because a target market removes the need to consider competitors."},"correctOption":"A","correctAnswer":"Because the marketing mix can then be designed to appeal to those specific customers.","questionType":"MCQ","explanation":{"correct_reason":"Knowing whether it serves wealthy home movers or budget students lets Wainwright set a matching price, message and service style, making the mix consistent.","distractor_reasons":{"A":"Knowing whether it serves wealthy home movers or budget students lets Wainwright set a matching price, message and service style, making the mix consistent.","B":"Tax rates are set by government rules and are not determined by which customers a firm targets.","C":"Many customers value care, speed or insurance cover more than the lowest quote when moving home.","D":"Rivals still compete for the same target customers, so competition must always be considered."}}},{"id":"P1_U3_MCQ_1085","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1085","question":"Cressage Interiors' market share rose from 7% to 11% after it cut prices sharply, but its profits fell. What does this show about using market share as a measure of success?","options":{"A":"A rising share does not guarantee higher profit, because it may be bought with price cuts that squeeze margins.","B":"Market share and profit always move in the same direction over time.","C":"A higher market share proves that customers are more satisfied than before.","D":"Profit can only rise when market share falls."},"correctOption":"A","correctAnswer":"A rising share does not guarantee higher profit, because it may be bought with price cuts that squeeze margins.","questionType":"MCQ","explanation":{"correct_reason":"Cressage gained share by cutting prices, and the lower margin on each sale outweighed the extra volume, so profit fell despite the larger share.","distractor_reasons":{"A":"Cressage gained share by cutting prices, and the lower margin on each sale outweighed the extra volume, so profit fell despite the larger share.","B":"This case shows share rising while profit falls, which disproves any automatic link between the two.","C":"Share measures sales volume against rivals, not customer satisfaction, which requires separate research.","D":"Profits can rise with a stable or rising share if costs fall or prices are increased successfully."}}},{"id":"P1_U3_MCQ_1086","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1086","question":"Ellingham Foods surveys 25 shoppers about a new sauce and finds 18 like it. It plans to launch nationally on this evidence. Why is this decision risky?","options":{"A":"A sample of 25 is too small to support a reliable conclusion about a national market.","B":"Shoppers are never able to taste food products accurately.","C":"A sample of 25 is far larger than necessary and wastes money.","D":"Taste tests cannot be classified as market research at all."},"correctOption":"A","correctAnswer":"A sample of 25 is too small to support a reliable conclusion about a national market.","questionType":"MCQ","explanation":{"correct_reason":"Twenty-five shoppers are unlikely to represent millions of national consumers, so 18 positive reactions may simply reflect chance rather than genuine demand.","distractor_reasons":{"A":"Twenty-five shoppers are unlikely to represent millions of national consumers, so 18 positive reactions may simply reflect chance rather than genuine demand.","B":"Shoppers can compare and rate tastes effectively; the problem is the number of people asked, not their ability.","C":"Twenty-five is a very small sample for a national launch and saves money only by sacrificing reliability.","D":"Taste testing is a recognised form of primary market research into consumer preferences."}}},{"id":"P1_U3_MCQ_1087","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1087","question":"Pellham Sports charges $84 for a tennis racket. A rival sells a similar racket for $105. By what percentage is Pellham's price lower than the rival's price?","options":{"A":"21%","B":"25%","C":"20%","D":"80%"},"correctOption":"C","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"The $21 price gap divided by the rival's $105 base price gives 0.2, so Pellham's racket is 20% cheaper than the competitor's.","distractor_reasons":{"A":"21% mistakes the $21 cash gap for a percentage without dividing it by the rival's price.","B":"25% divides the $21 gap by Pellham's own $84 price instead of by the rival's $105.","C":"The $21 price gap divided by the rival's $105 base price gives 0.2, so Pellham's racket is 20% cheaper than the competitor's.","D":"80% expresses Pellham's price as a percentage of the rival's price, not the size of the reduction."}}},{"id":"P1_U3_MCQ_1088","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1088","question":"Fotherby Design sells expensive ergonomic office chairs under a premium brand. It is considering selling the same chairs through a discount warehouse under a different name. What is the main risk of this strategy?","options":{"A":"The discount warehouse will refuse to sell any chairs at all.","B":"Ergonomic chairs cannot legally be sold under two brand names.","C":"Selling cheaply elsewhere could damage the premium brand's image and upset existing specialist retailers.","D":"It will automatically increase the premium brand's perceived quality."},"correctOption":"C","correctAnswer":"Selling cheaply elsewhere could damage the premium brand's image and upset existing specialist retailers.","questionType":"MCQ","explanation":{"correct_reason":"If shoppers find the same chair much cheaper under another label, Fotherby's premium price looks unjustified and specialist retailers may feel undercut.","distractor_reasons":{"A":"Discount warehouses exist to sell goods cheaply, so they would normally welcome a supply agreement.","B":"There is no law preventing one manufacturer from selling similar products under different brand names.","C":"If shoppers find the same chair much cheaper under another label, Fotherby's premium price looks unjustified and specialist retailers may feel undercut.","D":"Cheap copies usually dilute rather than enhance the perceived quality of the premium brand."}}},{"id":"P1_U3_MCQ_1089","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1089","question":"Woolmer Estates has sold homes in the same town for 40 years. New online agencies now charge lower fees. Which strength should Woolmer emphasise in its marketing?","options":{"A":"Its long local experience, personal service and knowledge of the neighbourhood.","B":"Its ability to charge the highest fees in the town.","C":"Its lack of any local knowledge compared with online rivals.","D":"Its decision to stop advertising properties altogether."},"correctOption":"A","correctAnswer":"Its long local experience, personal service and knowledge of the neighbourhood.","questionType":"MCQ","explanation":{"correct_reason":"Forty years of local dealing gives Woolmer knowledge and personal contact that low-cost online agencies struggle to match, which justifies its higher fee.","distractor_reasons":{"A":"Forty years of local dealing gives Woolmer knowledge and personal contact that low-cost online agencies struggle to match, which justifies its higher fee.","B":"Being the most expensive is a weakness unless customers can see extra value for the fee.","C":"Lacking local knowledge would remove Woolmer's main advantage over online rivals.","D":"Stopping advertising would reduce the exposure sellers expect when paying an estate agency fee."}}},{"id":"P1_U3_MCQ_1090","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1090","question":"Bexington Motors reviews its own service records for the past three years to see which repairs are most common. What type of data is this and what is its main advantage?","options":{"A":"Primary data from interviews, valued because it is collected fresh.","B":"Secondary data from a competitor, valued because it is independent.","C":"Observation data, valued because it records customer opinions.","D":"Internal secondary data, valued because it already exists and reflects real customer behaviour."},"correctOption":"D","correctAnswer":"Internal secondary data, valued because it already exists and reflects real customer behaviour.","questionType":"MCQ","explanation":{"correct_reason":"The service records were compiled by Bexington itself for repair purposes, so they are internal secondary data that already exist and show actual faults rather than opinions.","distractor_reasons":{"A":"No interviews took place; the figures come from existing service records rather than fresh fieldwork.","B":"The records belong to Bexington, not to a competitor, so the data is internal rather than external.","C":"Service records show what was repaired, not what customers said or were observed doing.","D":"The service records were compiled by Bexington itself for repair purposes, so they are internal secondary data that already exist and show actual faults rather than opinions."}}},{"id":"P1_U3_MCQ_1091","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1091","question":"Caldwell Marine spends $66,000 promoting a new range of boat covers and expects to sell 2,200 covers during the campaign. What is the promotional cost per cover sold?","options":{"A":"$3","B":"$300","C":"$33","D":"$30"},"correctOption":"D","correctAnswer":"$30","questionType":"MCQ","explanation":{"correct_reason":"The $66,000 promotional budget divided by the 2,200 covers expected to sell gives $30 of promotional spending per cover.","distractor_reasons":{"A":"$3 misplaces the decimal point when dividing $66,000 by 2,200 covers.","B":"$300 divides the budget by 220 rather than by the 2,200 covers expected to sell.","C":"$33 divides the budget by 2,000 covers instead of the stated 2,200.","D":"The $66,000 promotional budget divided by the 2,200 covers expected to sell gives $30 of promotional spending per cover."}}},{"id":"P1_U3_MCQ_1092","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1092","question":"Dunholme Pharmacy, which trades from three high-street shops, serves older patients collecting prescriptions and younger shoppers buying skincare. Why might this wider customer base be a marketing advantage?","options":{"A":"It means the pharmacy no longer needs to understand either group.","B":"Different segments can balance each other, so a fall in demand from one group has less impact on total sales.","C":"It guarantees the pharmacy will never face competition in either segment.","D":"It allows the pharmacy to use exactly the same message for both groups."},"correctOption":"B","correctAnswer":"Different segments can balance each other, so a fall in demand from one group has less impact on total sales.","questionType":"MCQ","explanation":{"correct_reason":"Serving two distinct groups spreads risk, because weak trading in skincare need not wipe out prescription income, and the two segments can be marketed differently.","distractor_reasons":{"A":"Serving two segments requires more understanding of customers, not less, because their needs differ.","B":"Serving two distinct groups spreads risk, because weak trading in skincare need not wipe out prescription income, and the two segments can be marketed differently.","C":"Rivals can still target either segment, so a wider customer base does not remove competition.","D":"Older patients and younger skincare buyers respond to different messages, so one message would suit neither well."}}},{"id":"P1_U3_MCQ_1093","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1093","question":"Bakers in a county buy 36,000 sacks of flour a year. Easterby Foods supplies 5,400 of them. What is Easterby's share of this market by volume?","options":{"A":"18%","B":"15%","C":"6.7%","D":"1.5%"},"correctOption":"B","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Easterby's 5,400 sacks divided by the county's 36,000 sack market gives 0.15, a 15% market share by volume.","distractor_reasons":{"A":"18% would require Easterby to supply 6,480 sacks, which is more than the 5,400 it actually sells.","B":"Easterby's 5,400 sacks divided by the county's 36,000 sack market gives 0.15, a 15% market share by volume.","C":"6.7% reverses the division, treating the whole county market as a fraction of Easterby's sales.","D":"1.5% misplaces the decimal point after dividing 5,400 by 36,000."}}},{"id":"P1_U3_MCQ_1094","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1094","question":"Framwell Toys instructs interviewers to question 50 parents in each of three towns but lets each interviewer decide which parents to approach. What is the main weakness of this approach?","options":{"A":"Interviewers may approach only friendly or convenient people, so the sample can be biased.","B":"Quota sampling cannot set a number of respondents in each town.","C":"Interviewing parents in three towns costs nothing at all.","D":"The method produces data that is impossible to record."},"correctOption":"A","correctAnswer":"Interviewers may approach only friendly or convenient people, so the sample can be biased.","questionType":"MCQ","explanation":{"correct_reason":"Quota sampling fixes the number in each group but leaves interviewer choice, so staff may avoid less approachable parents and skew the findings.","distractor_reasons":{"A":"Quota sampling fixes the number in each group but leaves interviewer choice, so staff may avoid less approachable parents and skew the findings.","B":"Setting 50 parents per town is exactly what quota sampling is designed to do.","C":"Paying interviewers in three towns involves real wage and travel costs, not zero cost.","D":"Responses can be recorded on forms or devices as normal, so the method produces usable data."}}},{"id":"P1_U3_MCQ_1095","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1095","question":"Garsdale Windows checks the prices charged by three local rivals for double glazing and sets its own price slightly below their average. Which pricing method is Garsdale using?","options":{"A":"Cost-plus pricing based on its own unit costs.","B":"Price skimming to recover development costs quickly.","C":"Competitive pricing, where the firm's price is set in relation to rivals' prices.","D":"Psychological pricing, where a price like $999 looks cheaper than $1,000."},"correctOption":"C","correctAnswer":"Competitive pricing, where the firm's price is set in relation to rivals' prices.","questionType":"MCQ","explanation":{"correct_reason":"Garsdale sets its price by reference to three rivals' prices rather than its own costs, which is the definition of competitive pricing.","distractor_reasons":{"A":"No unit costs are mentioned; the price is built from competitors' prices instead.","B":"Skimming means a high launch price for a new or innovative product, which is not described here.","C":"Garsdale sets its price by reference to three rivals' prices rather than its own costs, which is the definition of competitive pricing.","D":"The price is not described as ending in 9 or using a psychological trick, only as being below rivals' average."}}},{"id":"P1_U3_MCQ_1096","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1096","question":"Heddon Hotels advertises 'friendly, personal service' on national radio, but online reviews repeatedly complain about rude reception staff. Why is the marketing strategy unlikely to succeed?","options":{"A":"Radio advertising is always ineffective for hotels.","B":"Reviews are written only by people who never stayed.","C":"Friendly service cannot be advertised by any business.","D":"The promise made in promotion is not delivered by staff, so customers will be disappointed."},"correctOption":"D","correctAnswer":"The promise made in promotion is not delivered by staff, so customers will be disappointed.","questionType":"MCQ","explanation":{"correct_reason":"Advertising creates an expectation of friendly service, and rude reception staff break that promise, so guests leave dissatisfied and the campaign's cost is wasted.","distractor_reasons":{"A":"Radio can reach hotel guests effectively; the problem lies in service delivery rather than the medium.","B":"Online reviews are usually written by genuine guests, and repeated complaints suggest a real problem.","C":"Service quality can certainly be advertised, but only if the business can actually deliver it.","D":"Advertising creates an expectation of friendly service, and rude reception staff break that promise, so guests leave dissatisfied and the campaign's cost is wasted."}}},{"id":"P1_U3_MCQ_1097","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1097","question":"Inglewood Print calculates a 15% market share using a definition that includes only small local printers and leaves out online competitors. Why might this figure overstate its position?","options":{"A":"Because 15% is always too small a share to be meaningful.","B":"Because market share is calculated from profit figures rather than sales.","C":"Because large firms cannot be included in any market definition.","D":"Because the chosen definition excludes major competitors, so the share looks stronger than it really is."},"correctOption":"D","correctAnswer":"Because the chosen definition excludes major competitors, so the share looks stronger than it really is.","questionType":"MCQ","explanation":{"correct_reason":"By leaving online printers out of the market, Inglewood divides its sales by a smaller total, so the 15% figure overstates its real strength against all rivals.","distractor_reasons":{"A":"A 15% share can be significant in many markets, so size alone does not make the figure meaningless.","B":"Market share compares sales revenue or volume with the market total, not profit.","C":"Large firms are routinely included when defining a market, so there is no rule excluding them.","D":"By leaving online printers out of the market, Inglewood divides its sales by a smaller total, so the 15% figure overstates its real strength against all rivals."}}},{"id":"P1_U3_MCQ_1098","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1098","question":"Ludlow Furnishings discusses a new sofa range with a group of eight customers who volunteered after seeing a social media post. Why should managers not treat their views as representing all customers?","options":{"A":"Eight people is a large enough group to represent the whole market.","B":"Customers who volunteer are usually experts in furniture design.","C":"The group is small and self-selected, so it may not reflect the wider customer base.","D":"Group discussions cannot produce any useful opinions."},"correctOption":"C","correctAnswer":"The group is small and self-selected, so it may not reflect the wider customer base.","questionType":"MCQ","explanation":{"correct_reason":"Eight volunteers who responded to a social media post are a small, self-selected group, so their tastes may differ sharply from quieter or offline customers.","distractor_reasons":{"A":"Eight people is far too few to represent a whole market, however useful their detailed comments are.","B":"Volunteers are ordinary customers with an interest in the post, not trained furniture design experts.","C":"Eight volunteers who responded to a social media post are a small, self-selected group, so their tastes may differ sharply from quieter or offline customers.","D":"Group discussions produce valuable qualitative insight, even though they cannot be generalised to everyone."}}},{"id":"P1_U3_MCQ_1099","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1099","question":"Loxwood Foods is launching a new soup under its well-known existing brand name rather than as an unknown label. Why does the established brand help the launch?","options":{"A":"It removes the need for any product quality checks.","B":"It allows the soup to be sold without a price.","C":"Customers already trust the name, so they are more willing to try the new soup.","D":"It guarantees retailers will stock the soup in every store."},"correctOption":"C","correctAnswer":"Customers already trust the name, so they are more willing to try the new soup.","questionType":"MCQ","explanation":{"correct_reason":"Shoppers recognise and trust Loxwood's existing brand, which reduces the risk they feel in trying an unfamiliar soup and lowers the promotion needed.","distractor_reasons":{"A":"A known name raises expectations, so quality checks remain essential for every batch of soup.","B":"The soup still needs a price, and branding does not exempt a product from pricing decisions.","C":"Shoppers recognise and trust Loxwood's existing brand, which reduces the risk they feel in trying an unfamiliar soup and lowers the promotion needed.","D":"Retailers decide their own shelf space and may still refuse a new line despite a strong brand."}}},{"id":"P1_U3_MCQ_1100","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1100","question":"Merrifield Cycles set a target of a 25% share of a local market of 24,000 bicycles a year. It actually sold 5,400 bicycles. How should managers judge this result?","options":{"A":"It met the target exactly, because 5,400 is a quarter of 24,000.","B":"It exceeded the target by 600 bicycles.","C":"It missed the target by 2.5 bicycles.","D":"It missed the target by 600 bicycles, since 25% of 24,000 is 6,000."},"correctOption":"D","correctAnswer":"It missed the target by 600 bicycles, since 25% of 24,000 is 6,000.","questionType":"MCQ","explanation":{"correct_reason":"A 25% target equals 6,000 bicycles out of 24,000, so selling 5,400 leaves Merrifield 600 bicycles short of its goal.","distractor_reasons":{"A":"A quarter of 24,000 is 6,000, not 5,400, so the target was not met exactly.","B":"Sales were below rather than above the 6,000 target, so the shortfall is 600 units.","C":"The shortfall is 600 bicycles, not 2.5, because the difference in share is 2.5 percentage points.","D":"A 25% target equals 6,000 bicycles out of 24,000, so selling 5,400 leaves Merrifield 600 bicycles short of its goal."}}},{"id":"P1_U3_MCQ_1101","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1101","question":"Rivermead Pasta Ltd sells $18 million of pasta in a national pasta market worth $120 million a year. A rival, Bexley Foods, holds 35% of the same market. What is Rivermead Pasta Ltd's market share, and how does it compare with Bexley Foods?","options":{"A":"9%, which is 26 percentage points below Bexley Foods","B":"12%, which is 23 percentage points below Bexley Foods","C":"15%, which is 20 percentage points below Bexley Foods","D":"15%, which is 20 percentage points above Bexley Foods"},"correctOption":"C","correctAnswer":"15%, which is 20 percentage points below Bexley Foods","questionType":"MCQ","explanation":{"correct_reason":"Market share is own sales divided by total market sales, so $18 million divided by $120 million gives 15%; Bexley Foods' 35% is 20 percentage points higher than Rivermead's 15%.","distractor_reasons":{"A":"A 9% share would require sales of only about $10.8 million, so this option misdivides the $18 million figure by the $120 million market value.","B":"A 12% share implies sales near $14.4 million, so this option has calculated the division incorrectly and cannot match the $18 million stated.","C":"Market share is own sales divided by total market sales, so $18 million divided by $120 million gives 15%; Bexley Foods' 35% is 20 percentage points higher than Rivermead's 15%.","D":"The 15% figure is correct, but Bexley Foods at 35% is clearly larger, so Rivermead is below rather than above its rival by 20 percentage points."}}},{"id":"P1_U3_MCQ_1102","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1102","question":"Thornbury Kitchens, a fitted-kitchen retailer, posts questionnaires to 400 past customers at a cost of $3.20 each to test response to a new brochure design. Only 25% are returned completed. What is the average cost of each usable completed response?","options":{"A":"$3.20","B":"$12.80","C":"$6.40","D":"$9.60"},"correctOption":"B","correctAnswer":"$12.80","questionType":"MCQ","explanation":{"correct_reason":"Posting 400 questionnaires at $3.20 costs 400 × $3.20 = $1,280, and a 25% return gives 100 usable replies, so $1,280 divided by 100 equals $12.80 per completed response.","distractor_reasons":{"A":"This is only the mailing cost of a single questionnaire and ignores that 300 of the 400 posted forms never return a usable reply.","B":"Posting 400 questionnaires at $3.20 costs 400 × $3.20 = $1,280, and a 25% return gives 100 usable replies, so $1,280 divided by 100 equals $12.80 per completed response.","C":"This would result from dividing the $1,280 total by 200 responses, but a 25% return of 400 questionnaires produces only 100 completed forms.","D":"This would result from assuming 133 responses, whereas 25% of the 400 posted questionnaires is exactly 100 completed returns."}}},{"id":"P1_U3_MCQ_1103","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1103","question":"Marlowe Ridge Hotels sets its room rates by adding a standard 40% mark-up to the $60 cost of providing one room-night, including cleaning, laundry and utilities. Which pricing method is the hotel using, and what room rate results?","options":{"A":"Cost-plus pricing, giving a rate of $84","B":"Competitive pricing, giving a rate of $84","C":"Price skimming, giving a rate of $100","D":"Penetration pricing, giving a rate of $60"},"correctOption":"A","correctAnswer":"Cost-plus pricing, giving a rate of $84","questionType":"MCQ","explanation":{"correct_reason":"A fixed 40% mark-up added to the $60 unit cost is cost-plus pricing, and $60 plus 40% of $60 ($24) produces a room rate of $84.","distractor_reasons":{"A":"A fixed 40% mark-up added to the $60 unit cost is cost-plus pricing, and $60 plus 40% of $60 ($24) produces a room rate of $84.","B":"The $84 rate is right, but competitive pricing means following rivals' rates rather than building a 40% mark-up onto the hotel's own costs.","C":"Skimming means a high launch price for a new or unique product; $100 is also unsupported because 40% of $60 is $24, not $40.","D":"Penetration pricing sets a low price to enter a market, and $60 merely repeats the cost without applying the stated 40% mark-up."}}},{"id":"P1_U3_MCQ_1104","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1104","question":"Pemberly Apparel, a UK online fashion retailer, wants to sell in a new overseas country but has a small marketing budget, no local warehouse and no knowledge of local delivery rules. Which marketing strategy would be most suitable?","options":{"A":"Open a chain of its own retail stores in the overseas country","B":"Run a nationwide television advertising campaign abroad","C":"Build a local distribution centre before taking any orders","D":"Sell through an established local online marketplace"},"correctOption":"D","correctAnswer":"Sell through an established local online marketplace","questionType":"MCQ","explanation":{"correct_reason":"Using an established local marketplace lets Pemberly reach overseas customers with low cost and uses the partner's delivery and payment systems, matching its small budget and lack of local knowledge.","distractor_reasons":{"A":"Opening stores abroad needs heavy capital spending on leases and staff, which conflicts with Pemberly's small marketing budget and lack of local knowledge.","B":"A nationwide television campaign is expensive and risks being wasted because the firm does not yet understand local tastes or delivery rules.","C":"Building a distribution centre before any orders is a large fixed commitment made without evidence of demand, which is very risky for a small online retailer.","D":"Using an established local marketplace lets Pemberly reach overseas customers with low cost and uses the partner's delivery and payment systems, matching its small budget and lack of local knowledge."}}},{"id":"P1_U3_MCQ_1105","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1105","question":"Spending on chilled seafood in one region rose from $25 million to $28 million in a year, while Trevellick Seafoods' own sales stayed unchanged at $3.5 million. What happened to the firm's market share?","options":{"A":"It rose from 12.5% to 14%","B":"It stayed at 14%","C":"It fell from 14% to 12.5%","D":"It fell from 14% to 10%"},"correctOption":"C","correctAnswer":"It fell from 14% to 12.5%","questionType":"MCQ","explanation":{"correct_reason":"In the first year $3.5 million out of $25 million is 14%, but after the market grows to $28 million the same sales give $3.5 million out of $28 million, which is 12.5%.","distractor_reasons":{"A":"The direction is wrong: Trevellick's sales were unchanged while the market grew, so its share must fall rather than rise from 14% to 12.5%.","B":"A constant 14% would require Trevellick's sales to grow to $3.92 million, but the stem says its sales stayed at $3.5 million.","C":"In the first year $3.5 million out of $25 million is 14%, but after the market grows to $28 million the same sales give $3.5 million out of $28 million, which is 12.5%.","D":"A 10% share would need a market of $35 million, which is far larger than the $28 million stated in the stem."}}},{"id":"P1_U3_MCQ_1106","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1106","question":"Oakmere Cycles wants to survey 200 visitors at a weekend cycling show. Interviewers must select people in set proportions by age band and gender so the group reflects the wider cycling population. Which sampling method is being described?","options":{"A":"Random sampling using a lottery of ticket numbers","B":"Test marketing in selected bicycle shops","C":"Desk research using government sports statistics","D":"Quota sampling"},"correctOption":"D","correctAnswer":"Quota sampling","questionType":"MCQ","explanation":{"correct_reason":"Quota sampling means choosing a fixed number of respondents in each pre-set group, here age band and gender, so the sample matches the known mix of the cycling population.","distractor_reasons":{"A":"Random sampling gives everyone an equal chance through a lottery and does not force the sample into set age and gender proportions.","B":"Test marketing means launching the product in a few shops to watch real sales, not interviewing 200 show visitors to fill quotas.","C":"Desk research uses existing published data such as government statistics and involves no interviews with the 200 visitors at the show.","D":"Quota sampling means choosing a fixed number of respondents in each pre-set group, here age band and gender, so the sample matches the known mix of the cycling population."}}},{"id":"P1_U3_MCQ_1107","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1107","question":"Brimsdown Kitchens prints money-off vouchers worth $150 and runs a 'free dishwasher with every kitchen' offer during a quiet January. Which element of the promotional mix is the firm mainly using?","options":{"A":"Sales promotion","B":"Publicity","C":"Sponsorship","D":"Direct mail"},"correctOption":"A","correctAnswer":"Sales promotion","questionType":"MCQ","explanation":{"correct_reason":"Vouchers and a free dishwasher are short-term incentives designed to trigger immediate purchases, which is exactly what sales promotion does within the promotional mix.","distractor_reasons":{"A":"Vouchers and a free dishwasher are short-term incentives designed to trigger immediate purchases, which is exactly what sales promotion does within the promotional mix.","B":"Publicity is free media coverage generated by newsworthy events, whereas these offers are paid incentives created by the company itself.","C":"Sponsorship means paying to be linked with an event or team, and no such event or team is mentioned in the scenario.","D":"Direct mail means sending addressed advertising material, but here the incentives are vouchers and a free appliance rather than posted letters."}}},{"id":"P1_U3_MCQ_1108","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1108","question":"Silverpen Publishing sells school revision guides. Rival publishers copy every title within weeks, and all charge similar prices, so Silverpen's sales are slipping. Which strategy would best protect its sales in the long term?","options":{"A":"Cut prices below cost until rivals leave the market","B":"Build a strong brand with exclusive online tutoring support","C":"Copy rivals' cover designs and titles exactly","D":"Reduce the number of titles it publishes each year"},"correctOption":"B","correctAnswer":"Build a strong brand with exclusive online tutoring support","questionType":"MCQ","explanation":{"correct_reason":"A strong brand plus an exclusive tutoring service creates a unique selling point that rivals cannot copy within weeks, giving customers a reason to stay with Silverpen.","distractor_reasons":{"A":"Selling below cost destroys Silverpen's profit margins and is unsustainable, and rivals could match the price cut rather than leave the market.","B":"A strong brand plus an exclusive tutoring service creates a unique selling point that rivals cannot copy within weeks, giving customers a reason to stay with Silverpen.","C":"Copying rivals' covers and titles removes any difference between the products and makes Silverpen even easier to replace in customers' minds.","D":"Publishing fewer titles shrinks the range customers can buy and reduces revenue without addressing the copying problem at all."}}},{"id":"P1_U3_MCQ_1109","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1109","question":"Draycott Furnishings, a family furniture retailer, finds that customers under 35 now research online first, want flat-pack delivery to their door and prefer light neutral fabrics. Which action best responds to these changing customer needs?","options":{"A":"Increase showroom stock of dark traditional three-piece suites","B":"Stop using social media and rely on newspaper adverts","C":"Raise prices on every line to improve profit margins","D":"Add an online room planner, flat-pack delivery and a wider range of light fabrics"},"correctOption":"D","correctAnswer":"Add an online room planner, flat-pack delivery and a wider range of light fabrics","questionType":"MCQ","explanation":{"correct_reason":"This option matches all three shifts in customer behaviour described, namely online research, home delivery of flat-pack items and a preference for light neutral fabrics.","distractor_reasons":{"A":"Dark traditional suites are the opposite of the light neutral styles younger customers now prefer, so stock would become harder to sell.","B":"Abandoning social media ignores where under-35 customers now research furniture and would cut the firm off from its growing market.","C":"Raising every price does not meet any of the stated needs and may drive price-sensitive younger shoppers to rivals.","D":"This option matches all three shifts in customer behaviour described, namely online research, home delivery of flat-pack items and a preference for light neutral fabrics."}}},{"id":"P1_U3_MCQ_1110","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1110","question":"Lanmoor Dairy asks 50 shoppers in a single supermarket to taste a new yoghurt over two weekends and rate it from 1 to 5. The average rating is 3.9 out of 5. What is the main limitation of this research?","options":{"A":"The sample is small and drawn from one store, so the results may not represent the whole market","B":"Taste ratings are quantitative, so the scores cannot be averaged","C":"Taste tests always produce secondary data rather than primary data","D":"The test proves sales will rise by exactly the same percentage as the rating"},"correctOption":"A","correctAnswer":"The sample is small and drawn from one store, so the results may not represent the whole market","questionType":"MCQ","explanation":{"correct_reason":"Only 50 shoppers in one supermarket were sampled, so the 3.9 rating may reflect that store's customers and cannot be reliably generalised to the national yoghurt market.","distractor_reasons":{"A":"Only 50 shoppers in one supermarket were sampled, so the 3.9 rating may reflect that store's customers and cannot be reliably generalised to the national yoghurt market.","B":"Numerical ratings are quantitative data and can certainly be averaged, which is how the 3.9 score was produced in the first place.","C":"The tasting was carried out by the firm itself, so the ratings are primary data collected first-hand, not secondary data.","D":"A taste score measures preference only and cannot establish that actual sales will rise by any particular percentage."}}},{"id":"P1_U3_MCQ_1111","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1111","question":"Groverston Meats, a small sausage maker, sells through regional wholesalers instead of delivering directly to hundreds of independent butchers. Which is an advantage to Groverston of using this channel of distribution?","options":{"A":"Groverston keeps complete control over how its sausages are displayed in shops","B":"Groverston avoids the cost of making many small deliveries itself","C":"Groverston receives a higher price for every sausage it sells","D":"Groverston no longer needs to promote its products to retailers"},"correctOption":"B","correctAnswer":"Groverston avoids the cost of making many small deliveries itself","questionType":"MCQ","explanation":{"correct_reason":"A wholesaler buys in bulk and breaks the load into small drops for many butchers, so Groverston avoids the transport and administration costs of delivering tiny orders itself.","distractor_reasons":{"A":"Using a wholesaler reduces Groverston's control, because the wholesaler and butchers decide how and where the sausages are presented.","B":"A wholesaler buys in bulk and breaks the load into small drops for many butchers, so Groverston avoids the transport and administration costs of delivering tiny orders itself.","C":"The wholesaler takes its own margin, so Groverston usually receives a lower price per sausage than it would from direct selling.","D":"Promotion is still needed to persuade wholesalers to stock the brand and to attract shoppers, so this channel does not remove it."}}},{"id":"P1_U3_MCQ_1112","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1112","question":"Cracknell Sports sells running shoes in twelve countries using one design and one price. Research shows that shoppers in one country need wider fittings, prefer neutral colours and will not pay the current price. Which marketing strategy is most appropriate there?","options":{"A":"Keep selling exactly the same shoes at the same price in that country","B":"Withdraw from the country and concentrate on existing markets","C":"Adapt the shoe width, colour range and price to local preferences","D":"Increase advertising spending without changing the product or price"},"correctOption":"C","correctAnswer":"Adapt the shoe width, colour range and price to local preferences","questionType":"MCQ","explanation":{"correct_reason":"The research identifies clear local differences in fitting, colour and acceptable price, so adapting the product and price is the strategy most likely to win sales in that country.","distractor_reasons":{"A":"Ignoring evidence that local shoppers need wider fittings and lower prices would leave the shoes unsold in that market.","B":"Withdrawing throws away a market where the firm already sells and where modest product changes could solve the problem.","C":"The research identifies clear local differences in fitting, colour and acceptable price, so adapting the product and price is the strategy most likely to win sales in that country.","D":"Advertising a shoe that does not fit local feet or suit local budgets wastes money, since the underlying offer remains unsuitable."}}},{"id":"P1_U3_MCQ_1113","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1113","question":"Linthorpe Lighting's market share fell from 22% to 17% in two years after an online rival began selling similar LED bulbs at lower prices. The total market for LED bulbs was growing throughout. Which explanation fits these facts?","options":{"A":"Customers switched to the lower-priced online rival, so Linthorpe's sales grew more slowly than the market","B":"The total market for LED bulbs collapsed, which automatically reduced Linthorpe's share","C":"Linthorpe's prices were too low, so it lost revenue on every bulb sold","D":"Linthorpe stopped selling LED bulbs and left the market completely"},"correctOption":"A","correctAnswer":"Customers switched to the lower-priced online rival, so Linthorpe's sales grew more slowly than the market","questionType":"MCQ","explanation":{"correct_reason":"A falling share in a growing market means Linthorpe's own sales rose more slowly than total market sales, which fits customers switching to a cheaper online competitor.","distractor_reasons":{"A":"A falling share in a growing market means Linthorpe's own sales rose more slowly than total market sales, which fits customers switching to a cheaper online competitor.","B":"The stem states the total market was growing, so a collapse in market demand cannot explain the fall from 22% to 17%.","C":"Low prices would normally attract customers rather than lose them, and the rival is described as the cheaper seller.","D":"Linthorpe is still trading and its share is 17%, so it clearly has not stopped selling LED bulbs and left the market."}}},{"id":"P1_U3_MCQ_1114","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1114","question":"Hartsmere Confectionery invites eight regular buyers to a two-hour discussion led by a researcher, who asks how they choose chocolate bars and what they think of a new recipe. Which market research method is being used?","options":{"A":"A postal questionnaire","B":"Observation of shoppers in store","C":"A focus group","D":"Analysis of government statistics"},"correctOption":"C","correctAnswer":"A focus group","questionType":"MCQ","explanation":{"correct_reason":"A small number of customers brought together to discuss their views under a researcher's guidance is a focus group, which produces qualitative insight into why buyers behave as they do.","distractor_reasons":{"A":"A postal questionnaire is sent to respondents individually, whereas these eight buyers meet together and talk in a guided discussion.","B":"Observation would mean watching what shoppers do without questioning them, but here the researcher is asking about opinions and a new recipe.","C":"A small number of customers brought together to discuss their views under a researcher's guidance is a focus group, which produces qualitative insight into why buyers behave as they do.","D":"Government statistics are secondary data already published by others, while this discussion collects new opinions directly from buyers."}}},{"id":"P1_U3_MCQ_1115","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1115","question":"Wexcombe Studios sold candles in plain cardboard boxes at $9 each. After switching to printed gift boxes carrying its brand name, it raised the price to $11 and sales rose by 30%. Which conclusion is best supported?","options":{"A":"The new packaging reduced the firm's fixed costs","B":"Better packaging added value, supporting a higher price and stronger brand recognition","C":"The packaging removed the need for any other promotion","D":"The candles became cheaper to produce after the change"},"correctOption":"B","correctAnswer":"Better packaging added value, supporting a higher price and stronger brand recognition","questionType":"MCQ","explanation":{"correct_reason":"Sales rose 30% at a price $2 higher once the printed gift box carried the brand, showing that packaging added perceived value and helped customers recognise the product.","distractor_reasons":{"A":"Printed gift boxes normally add packaging cost, and packaging is a variable cost rather than a reduction in fixed costs.","B":"Sales rose 30% at a price $2 higher once the printed gift box carried the brand, showing that packaging added perceived value and helped customers recognise the product.","C":"Packaging can support promotion but does not replace advertising, social media or other ways of reaching buyers.","D":"The gift box is an extra production cost, so the candles became more expensive to make rather than cheaper."}}},{"id":"P1_U3_MCQ_1116","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1116","question":"Ashcombe Spas has a marketing budget of $60,000 for the coming year. Managers plan to spend 45% on social media advertising and 30% on a local radio campaign, with the remainder on printed leaflets. How much is available for leaflets?","options":{"A":"$9,000","B":"$18,000","C":"$27,000","D":"$15,000"},"correctOption":"D","correctAnswer":"$15,000","questionType":"MCQ","explanation":{"correct_reason":"Social media takes 45% and radio 30%, which is 75% in total, leaving 25% of the $60,000 budget, and 25% of $60,000 equals $15,000.","distractor_reasons":{"A":"This is 15% of the budget and would follow from subtracting 55% rather than the stated 45% and 30%.","B":"This equals the 30% radio allocation, not the remaining share for leaflet printing.","C":"This is 45% of the budget, which is the social media spending already planned.","D":"Social media takes 45% and radio 30%, which is 75% in total, leaving 25% of the $60,000 budget, and 25% of $60,000 equals $15,000."}}},{"id":"P1_U3_MCQ_1117","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1117","question":"Sturbridge Timber interviewed 500 garden owners about the shed sizes, prices and features they wanted before designing its new range. Every element of the final product was based on those findings. Which approach has the firm taken?","options":{"A":"A market-orientated approach, because the product was designed around customer research","B":"A product-orientated approach, because the firm manufactures garden sheds","C":"A sales-orientated approach, because the range will be advertised","D":"A cost-orientated approach, because timber is the main input"},"correctOption":"A","correctAnswer":"A market-orientated approach, because the product was designed around customer research","questionType":"MCQ","explanation":{"correct_reason":"The firm researched customer needs first and shaped the sizes, prices and features around those findings, which is the defining feature of a market-orientated business.","distractor_reasons":{"A":"The firm researched customer needs first and shaped the sizes, prices and features around those findings, which is the defining feature of a market-orientated business.","B":"Making sheds does not make a firm product-orientated; a product-orientated firm designs first and then tries to sell, which is the opposite of what happened here.","C":"Advertising a finished range is not the same as starting from customer research, so a sales-orientated label does not describe this process.","D":"Using timber as an input says nothing about whether customer needs guided the design, so cost orientation is not the key feature shown."}}},{"id":"P1_U3_MCQ_1118","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1118","question":"Kielder Media Group sets a quota of 240 interviews for its readership survey. The quotas are split between three age bands in the ratio 2:3:3 for readers aged 18-24, 25-44 and 45 and over. How many interviews fall in the 18-24 band?","options":{"A":"45","B":"60","C":"80","D":"120"},"correctOption":"B","correctAnswer":"60","questionType":"MCQ","explanation":{"correct_reason":"The ratio 2:3:3 has eight equal parts, and 240 divided by 8 gives 30 per part, so the 18-24 band with two parts requires 2 × 30 = 60 interviews.","distractor_reasons":{"A":"This would be one and a half parts of 30 and does not match the two parts allocated to the 18-24 band.","B":"The ratio 2:3:3 has eight equal parts, and 240 divided by 8 gives 30 per part, so the 18-24 band with two parts requires 2 × 30 = 60 interviews.","C":"This is three parts of 30 and is the quota for one of the older age bands, not the 18-24 group.","D":"This equals half of the 240 interviews and would only apply if the ratio gave the youngest band four of eight parts."}}},{"id":"P1_U3_MCQ_1119","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1119","question":"Nordwell Footwear lists a range of trainers at $75 a pair and offers retail buyers a trade discount of 20% off the list price. What does a retailer pay Nordwell for each pair of trainers?","options":{"A":"$15","B":"$55","C":"$60","D":"$90"},"correctOption":"C","correctAnswer":"$60","questionType":"MCQ","explanation":{"correct_reason":"A 20% trade discount on the $75 list price is $15, so the retailer pays $75 minus $15, which equals $60 for each pair of trainers.","distractor_reasons":{"A":"This is only the $15 discount itself, not the reduced price the retailer actually hands over.","B":"This implies a discount of $20, which is 26.7% of $75 rather than the stated 20%.","C":"A 20% trade discount on the $75 list price is $15, so the retailer pays $75 minus $15, which equals $60 for each pair of trainers.","D":"This adds the discount to the list price, but a trade discount is deducted from the price rather than added to it."}}},{"id":"P1_U3_MCQ_1120","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1120","question":"Farrowgate Hardware spent $12,000 on a local advertising campaign. Sales then rose from 8,000 to 8,800 units at $40 each, and no other factor changed. How should managers judge whether the campaign was worthwhile?","options":{"A":"No, because sales rose by only 10%","B":"No, because the campaign cost more than the extra sales revenue","C":"Yes, but only because the selling price was increased","D":"Yes, because the extra 800 units add $32,000 of revenue against $12,000 of spending"},"correctOption":"D","correctAnswer":"Yes, because the extra 800 units add $32,000 of revenue against $12,000 of spending","questionType":"MCQ","explanation":{"correct_reason":"The campaign produced 800 extra units, and 800 × $40 gives $32,000 of additional revenue, which comfortably exceeds the $12,000 campaign cost by $20,000.","distractor_reasons":{"A":"A 10% rise in units is not automatically disappointing; the decision depends on whether the extra revenue covers the $12,000 spent.","B":"The extra revenue of $32,000 is well above the $12,000 cost, so the campaign did not cost more than the sales it generated.","C":"The stem states the price stayed at $40 and no other factor changed, so a price increase cannot explain the result.","D":"The campaign produced 800 extra units, and 800 × $40 gives $32,000 of additional revenue, which comfortably exceeds the $12,000 campaign cost by $20,000."}}},{"id":"P1_U3_MCQ_1121","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1121","question":"Willowmere Nurseries currently sells $1.2 million of plants a year in a local garden market worth $8 million. What annual sales would give the firm a 20% market share, and how much more is that than its present revenue?","options":{"A":"$1.6 million, requiring $400,000 more sales","B":"$1.6 million, requiring $1.6 million more sales","C":"$1.44 million, requiring $240,000 more sales","D":"$2.0 million, requiring $800,000 more sales"},"correctOption":"A","correctAnswer":"$1.6 million, requiring $400,000 more sales","questionType":"MCQ","explanation":{"correct_reason":"A 20% share of an $8 million market is 0.20 × $8 million = $1.6 million, and $1.6 million minus the current $1.2 million means $400,000 of extra sales are needed.","distractor_reasons":{"A":"A 20% share of an $8 million market is 0.20 × $8 million = $1.6 million, and $1.6 million minus the current $1.2 million means $400,000 of extra sales are needed.","B":"The $1.6 million target is correct, but only the difference of $400,000 is needed because the firm already sells $1.2 million.","C":"This equals an 18% share of the $8 million market, not the 20% target stated in the question.","D":"This equals a 25% share of the market, which is higher than the stated 20% target."}}},{"id":"P1_U3_MCQ_1122","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1122","question":"Tarnbrook Opticians uses its own appointment records to forecast demand for eye tests, then telephones 60 customers to ask what they think of a new frame range. Which of these sources provides secondary data?","options":{"A":"The 60 telephone interviews","B":"The forecasts based on those interviews","C":"The practice's existing appointment records","D":"Neither source, because both are primary data"},"correctOption":"C","correctAnswer":"The practice's existing appointment records","questionType":"MCQ","explanation":{"correct_reason":"Appointment records already exist inside the practice and were not gathered for this research project, so they are internal secondary data, unlike the new telephone interviews.","distractor_reasons":{"A":"The 60 telephone interviews collect new information directly from customers, which makes them primary rather than secondary data.","B":"Forecasts built from the new interviews rely on primary data, and producing a forecast does not turn that data into secondary data.","C":"Appointment records already exist inside the practice and were not gathered for this research project, so they are internal secondary data, unlike the new telephone interviews.","D":"Only the interviews are primary, while the existing appointment records were collected earlier for another purpose and are therefore secondary."}}},{"id":"P1_U3_MCQ_1123","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1123","question":"Sanderby Optics has sold binoculars only through specialist outdoor shops. It now opens its own website with online ordering and home delivery. Which benefit is most likely from adding this channel of distribution?","options":{"A":"It removes the need to hold any inventory","B":"It guarantees lower courier costs per parcel","C":"It allows the firm to stop advertising in magazines","D":"It reaches customers who have no specialist shop nearby"},"correctOption":"D","correctAnswer":"It reaches customers who have no specialist shop nearby","questionType":"MCQ","explanation":{"correct_reason":"A website with home delivery lets Sanderby sell to people outside the catchment areas of specialist shops, widening its market without opening new branches.","distractor_reasons":{"A":"Website orders still have to be fulfilled from stock, so inventory must be held somewhere in the supply chain.","B":"Single-parcel courier charges are often higher than bulk deliveries, so lower courier costs are not guaranteed.","C":"Online selling increases the need to attract visitors, so magazine or search advertising remains useful rather than unnecessary.","D":"A website with home delivery lets Sanderby sell to people outside the catchment areas of specialist shops, widening its market without opening new branches."}}},{"id":"P1_U3_MCQ_1124","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1124","question":"Staynes Plastics has designed a reusable storage crate and can either launch it across the whole country immediately or sell it first in one region for six months. Which strategy is more prudent, and why?","options":{"A":"Launch nationally at once to spread fixed costs over the largest possible output","B":"Test the crate in one region to limit the cost of failure before a national launch","C":"Delay all promotion until a rival has launched a similar crate","D":"Launch nationally because a regional trial cannot provide useful information"},"correctOption":"B","correctAnswer":"Test the crate in one region to limit the cost of failure before a national launch","questionType":"MCQ","explanation":{"correct_reason":"A six-month regional launch lets Staynes judge demand, price and packaging on a small scale, so any failure costs far less than a nationwide launch that goes wrong.","distractor_reasons":{"A":"A national launch maximises the cost of any mistake, since unsold stock and wasted advertising would be spread across the whole country.","B":"A six-month regional launch lets Staynes judge demand, price and packaging on a small scale, so any failure costs far less than a nationwide launch that goes wrong.","C":"Waiting for a rival gives away first-mover advantage and lets competitors establish their product before Staynes has tested anything.","D":"A regional trial does generate useful evidence about sales, customer reaction and costs before the firm commits nationally."}}},{"id":"P1_U3_MCQ_1125","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1125","question":"Penrhos Vintners gives customers a free tasting after every six bottles bought and sends them a birthday discount. Repeat purchases now account for 62% of its sales. Which benefit of customer loyalty does this illustrate?","options":{"A":"It guarantees that new customers will switch from rivals","B":"It removes the need to monitor competitors' prices","C":"It allows prices to be increased without any limit","D":"Loyal customers provide steady repeat revenue and are cheaper to keep than to replace"},"correctOption":"D","correctAnswer":"Loyal customers provide steady repeat revenue and are cheaper to keep than to replace","questionType":"MCQ","explanation":{"correct_reason":"Repeat buyers already supply 62% of sales without the cost of winning them again, so loyalty gives Penrhos a predictable revenue base at lower marketing cost.","distractor_reasons":{"A":"Loyalty schemes influence existing customers and cannot guarantee that customers of rival wine merchants will switch.","B":"Competitors' prices still affect whether loyal customers stay, so monitoring the market remains necessary.","C":"Even loyal customers will switch if prices rise too far, so loyalty does not permit unlimited price increases.","D":"Repeat buyers already supply 62% of sales without the cost of winning them again, so loyalty gives Penrhos a predictable revenue base at lower marketing cost."}}},{"id":"P1_U3_MCQ_1126","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1126","question":"Cottrell Cleaning has 1,200 business customers and decides to telephone a 10% random sample of them for a satisfaction survey. How many customers will be interviewed in total?","options":{"A":"12","B":"100","C":"120","D":"240"},"correctOption":"C","correctAnswer":"120","questionType":"MCQ","explanation":{"correct_reason":"A 10% sample of the 1,200 business customers is 0.10 × 1,200, which equals 120 customers to be interviewed by telephone.","distractor_reasons":{"A":"This is 1% of 1,200 customers and is one tenth of the sample size required by a 10% sampling fraction.","B":"This would be a sample of about 8.3%, not the stated 10% of the 1,200 business customers.","C":"A 10% sample of the 1,200 business customers is 0.10 × 1,200, which equals 120 customers to be interviewed by telephone.","D":"This equals 20% of the customer list, double the 10% sampling fraction described in the scenario."}}},{"id":"P1_U3_MCQ_1127","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1127","question":"Landsbury Aluminium can exhibit at a trade fair for $9,000 or post brochures to 400 trade buyers at $30 each. Which promotional option is cheaper for the firm, and by how much?","options":{"A":"The brochures, by $3,000","B":"The trade fair, by $3,000","C":"The trade fair, by $12,000","D":"Both options cost exactly the same"},"correctOption":"B","correctAnswer":"The trade fair, by $3,000","questionType":"MCQ","explanation":{"correct_reason":"The 400 brochures cost 400 × $30 = $12,000, so the $9,000 trade fair is cheaper by $12,000 minus $9,000, which is $3,000.","distractor_reasons":{"A":"The brochures cost $12,000, which is more than the $9,000 trade fair, so they are the dearer option rather than the cheaper one.","B":"The 400 brochures cost 400 × $30 = $12,000, so the $9,000 trade fair is cheaper by $12,000 minus $9,000, which is $3,000.","C":"The $12,000 is the total cost of the brochures, not the saving from choosing the trade fair.","D":"The two options differ by $3,000, so they are not equal in cost."}}},{"id":"P1_U3_MCQ_1128","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1128","question":"Westray Systems has signed a contract with a distributor in a country whose rules require all product labels and safety warnings to be printed in the local language. What must Westray do before shipping?","options":{"A":"Translate and adapt its labels so they meet the local legal requirements","B":"Use its existing English labels to keep printing costs down","C":"Abandon the contract and withdraw from the country","D":"Ask the distributor to ignore the labelling rules"},"correctOption":"A","correctAnswer":"Translate and adapt its labels so they meet the local legal requirements","questionType":"MCQ","explanation":{"correct_reason":"Local law requires labels and safety warnings in the national language, so Westray must translate and adapt its packaging to trade legally in that market.","distractor_reasons":{"A":"Local law requires labels and safety warnings in the national language, so Westray must translate and adapt its packaging to trade legally in that market.","B":"Keeping English-only labels would breach the local rules and could lead to fines, recalls or refusal of entry at customs.","C":"Withdrawing is unnecessary because the labelling requirement can be met by translating and adapting the packaging.","D":"The distributor cannot override national law, and asking it to do so would expose both firms to legal penalties."}}},{"id":"P1_U3_MCQ_1129","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1129","question":"Denmarsh Pharmacy groups its customers into commuters, young families and older residents, then stocks different products and opens at different times for each group. Which benefit of market segmentation does this show?","options":{"A":"Marketing can be tailored more closely to each group's needs","B":"Average costs always fall as more groups are added","C":"Competition is removed from each customer group","D":"Less market research is needed once segments are chosen"},"correctOption":"A","correctAnswer":"Marketing can be tailored more closely to each group's needs","questionType":"MCQ","explanation":{"correct_reason":"By stocking different products and setting different opening hours for each group, Denmarsh matches its offer to the specific needs of commuters, families and older residents.","distractor_reasons":{"A":"By stocking different products and setting different opening hours for each group, Denmarsh matches its offer to the specific needs of commuters, families and older residents.","B":"Serving several segments usually raises costs through extra stock and complexity, so average costs do not always fall.","C":"Segmenting does not remove rivals; competing pharmacies can target exactly the same groups.","D":"Choosing and serving segments requires continuing research to check that each group's needs are still being met."}}},{"id":"P1_U3_MCQ_1130","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1130","question":"Quenby Deli is choosing where to open a second shop and uses free census data on household incomes and ages in three districts. Which advantage of secondary data does this illustrate?","options":{"A":"It is always more up to date than newly collected data","B":"It is quicker and cheaper because the information already exists","C":"It is collected specifically to answer the deli's own questions","D":"It cannot be accessed through the internet"},"correctOption":"B","correctAnswer":"It is quicker and cheaper because the information already exists","questionType":"MCQ","explanation":{"correct_reason":"Census figures have already been gathered and published, so Quenby Deli can use them immediately at little cost instead of paying for its own survey of three districts.","distractor_reasons":{"A":"Census data is published only periodically, so it is usually less up to date than data the deli could collect now.","B":"Census figures have already been gathered and published, so Quenby Deli can use them immediately at little cost instead of paying for its own survey of three districts.","C":"Census questions are designed for national purposes, not for the deli's specific questions about opening a second shop.","D":"Census and similar statistics are widely available online, so inaccessibility is not a genuine advantage."}}},{"id":"P1_U3_MCQ_1131","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1131","question":"Barrowman Grocers sells bottles of milk for $0.80 even though each bottle costs $1.05, because shoppers who call in for milk usually buy bread, cereal and coffee too. Which pricing tactic is the grocer using?","options":{"A":"Price skimming","B":"Cost-plus pricing","C":"A loss leader","D":"Penetration pricing"},"correctOption":"C","correctAnswer":"A loss leader","questionType":"MCQ","explanation":{"correct_reason":"Milk is priced at $0.80 against a $1.05 cost so that it makes a loss on purpose, which is a loss leader designed to draw shoppers in to buy profitable items.","distractor_reasons":{"A":"Price skimming means charging a high price at launch to earn from early buyers, which is the opposite of selling milk below cost.","B":"Cost-plus pricing would add a mark-up to the $1.05 cost and produce a price above $1.05, not the $0.80 charged.","C":"Milk is priced at $0.80 against a $1.05 cost so that it makes a loss on purpose, which is a loss leader designed to draw shoppers in to buy profitable items.","D":"Penetration pricing sets a low price to enter a new market, but Barrowman is an established grocer using milk to raise store traffic."}}},{"id":"P1_U3_MCQ_1132","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1132","question":"Hollinsworth Fitness pays a local athlete $600 to post about its new gym. The post is estimated to be seen by 60,000 people. What is the cost of reaching each 1,000 people who see the post?","options":{"A":"$1","B":"$6","C":"$60","D":"$10"},"correctOption":"D","correctAnswer":"$10","questionType":"MCQ","explanation":{"correct_reason":"There are 60 groups of 1,000 people within the 60,000 who see the post, and $600 divided by 60 equals $10 for every 1,000 people reached.","distractor_reasons":{"A":"$1 would mean the post cost only $60 in total, one tenth of the $600 actually paid to the athlete.","B":"$6 would follow from dividing $600 by 100 groups, which would require 100,000 viewers rather than 60,000.","C":"$60 would mean the post cost $3,600, six times the $600 fee stated in the scenario.","D":"There are 60 groups of 1,000 people within the 60,000 who see the post, and $600 divided by 60 equals $10 for every 1,000 people reached."}}},{"id":"P1_U3_MCQ_1133","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1133","question":"Thornbeck Brewing holds 6% of a regional beer market that is not growing at all, and it wants a larger market share. Which action is most likely to achieve this?","options":{"A":"Wait for the total market to expand on its own","B":"Win customers from rival brewers using a stronger local brand and wider pub distribution","C":"Reduce advertising spending to cut costs","D":"Raise prices above every rival in the region"},"correctOption":"B","correctAnswer":"Win customers from rival brewers using a stronger local brand and wider pub distribution","questionType":"MCQ","explanation":{"correct_reason":"In a market that is not growing, extra share can only come from rivals, so building a stronger brand and gaining more pub listings directly attacks competitors' sales.","distractor_reasons":{"A":"A static market gives no extra sales to share out, so waiting cannot increase Thornbeck's 6% share.","B":"In a market that is not growing, extra share can only come from rivals, so building a stronger brand and gaining more pub listings directly attacks competitors' sales.","C":"Cutting advertising weakens the brand just when it must attract rivals' customers, making share growth less likely.","D":"Pricing above every rival in a static market would push price-sensitive drinkers towards competitors and reduce share."}}},{"id":"P1_U3_MCQ_1134","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1134","question":"Ingleby Fitness emails a satisfaction survey only to members who have booked personal training, receives 90% positive replies, and concludes that all members are satisfied. What is the main problem with this conclusion?","options":{"A":"The sample is biased because it excludes members who do not use personal training","B":"A 90% positive response rate is too low to support any conclusion","C":"Email surveys always generate secondary rather than primary data","D":"The firm should have used observation instead of asking questions"},"correctOption":"A","correctAnswer":"The sample is biased because it excludes members who do not use personal training","questionType":"MCQ","explanation":{"correct_reason":"Only members already paying for personal training were surveyed, so their positive views cannot represent the many members who use the gym without that service.","distractor_reasons":{"A":"Only members already paying for personal training were surveyed, so their positive views cannot represent the many members who use the gym without that service.","B":"A 90% positive result is high, and the real weakness is who was asked rather than how favourable the replies were.","C":"Replies sent directly by members are primary data, so emailing respondents does not make the information secondary.","D":"Observation could add insight but cannot explain satisfaction, so it is not a substitute for asking members themselves."}}},{"id":"P1_U3_MCQ_1135","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1135","question":"Marchetti Pasta packs 12,000 boxes a month. A new printed box costs $0.18 compared with $0.11 for the plain box it replaces. What is the extra packaging cost each month?","options":{"A":"$84","B":"$1,320","C":"$2,160","D":"$840"},"correctOption":"D","correctAnswer":"$840","questionType":"MCQ","explanation":{"correct_reason":"The printed box costs $0.07 more than the plain one, and 12,000 boxes × $0.07 gives an extra packaging cost of $840 a month.","distractor_reasons":{"A":"This divides by 1.2 rather than using 12,000 boxes, so it understates the extra cost tenfold.","B":"This equals the full $0.11 cost of 12,000 plain boxes, not the extra cost created by the change.","C":"This equals the full $0.18 cost of 12,000 printed boxes rather than the difference between the two boxes.","D":"The printed box costs $0.07 more than the plain one, and 12,000 boxes × $0.07 gives an extra packaging cost of $840 a month."}}},{"id":"P1_U3_MCQ_1136","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1136","question":"Penhallow Kitchenware plans to sell its four-piece knife set in a country where four-piece sets are thought unlucky and gifts must be elaborately wrapped. Which marketing response is most appropriate?","options":{"A":"Keep the four-piece set and standard wrapping to save costs","B":"Abandon the export plan and stay in the home market","C":"Change the set size and gift wrapping to suit local customs","D":"Reduce the price sharply without changing anything else"},"correctOption":"C","correctAnswer":"Change the set size and gift wrapping to suit local customs","questionType":"MCQ","explanation":{"correct_reason":"Local beliefs about the number four and expectations about gift wrapping are cultural, so adapting the set size and packaging is the change most likely to make the product acceptable.","distractor_reasons":{"A":"Keeping an unlucky set size and plain wrapping would offend local customs and make the knives very hard to sell.","B":"Withdrawing is unnecessary when a straightforward change of set size and wrapping could open the market.","C":"Local beliefs about the number four and expectations about gift wrapping are cultural, so adapting the set size and packaging is the change most likely to make the product acceptable.","D":"A price cut does not address the cultural objection to a four-piece set or the wrapping custom, so sales would still suffer."}}},{"id":"P1_U3_MCQ_1137","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1137","question":"Bexford Coach Tours lost passengers to a rival whose coaches had more legroom, charging points and wi-fi. Bexford has now ordered new coaches with all three features. What does this show about marketing?","options":{"A":"Customers do not really know what they want from a service","B":"Marketing should start by identifying customer needs and then meeting them","C":"Price is the only factor that matters to coach passengers","D":"Competition is irrelevant to businesses that provide services"},"correctOption":"B","correctAnswer":"Marketing should start by identifying customer needs and then meeting them","questionType":"MCQ","explanation":{"correct_reason":"Passengers showed they valued legroom, charging points and wi-fi by moving to the rival, and Bexford responded by providing those features, which is need-based marketing.","distractor_reasons":{"A":"Passengers demonstrated very clearly what they wanted by switching to the rival with better facilities, so their needs were known.","B":"Passengers showed they valued legroom, charging points and wi-fi by moving to the rival, and Bexford responded by providing those features, which is need-based marketing.","C":"Passengers moved for comfort and connectivity rather than price, so price is clearly not the only factor in their choice.","D":"A rival coach operator caused the loss of passengers, which shows competition matters greatly in service businesses."}}},{"id":"P1_U3_MCQ_1138","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1138","question":"Yarnbrook Textiles needs 300 completed questionnaires about a new fabric range. Past surveys have returned 60% of the forms it posted. How many questionnaires must the firm send out to obtain 300 completed replies?","options":{"A":"180","B":"300","C":"500","D":"750"},"correctOption":"C","correctAnswer":"500","questionType":"MCQ","explanation":{"correct_reason":"If 60% of posted forms come back, the firm needs 300 divided by 0.60, which equals 500 questionnaires posted to obtain 300 completed replies.","distractor_reasons":{"A":"This is 60% of 300, which reverses the calculation and would deliver only 108 completed replies at a 60% return rate.","B":"Posting exactly 300 forms would return only about 180 completed replies, short of the 300 the firm needs.","C":"If 60% of posted forms come back, the firm needs 300 divided by 0.60, which equals 500 questionnaires posted to obtain 300 completed replies.","D":"This assumes only a 40% return rate, but the scenario states that 60% of posted forms come back."}}},{"id":"P1_U3_MCQ_1139","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1139","question":"Caldecott Printworks sells greetings cards to 800 small independent shops across the country and finds delivering to each one too costly, so it appoints a national wholesaler. Which factor best explains this choice of channel?","options":{"A":"The cards are highly perishable and must be sold within days","B":"The firm wants direct personal contact with every shopper","C":"The cards are technically complex and need demonstrating","D":"There are many small customers spread over a wide area"},"correctOption":"D","correctAnswer":"There are many small customers spread over a wide area","questionType":"MCQ","explanation":{"correct_reason":"Delivering small orders to 800 scattered shops is expensive, so a wholesaler that consolidates deliveries suits a producer facing many small, widely spread customers.","distractor_reasons":{"A":"Greetings cards are not perishable, so a short channel to sell them quickly is not the reason for using a wholesaler.","B":"Using a wholesaler reduces direct contact with retailers, so wanting contact with every shopper points away from this channel.","C":"Cards need no demonstration, unlike complex technical goods, so this does not explain the wholesaler appointment.","D":"Delivering small orders to 800 scattered shops is expensive, so a wholesaler that consolidates deliveries suits a producer facing many small, widely spread customers."}}},{"id":"P1_U3_MCQ_1140","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1140","question":"Skelton Ridge Software has sales of $4.8 million in a software market worth $60 million. Its three-year marketing strategy targets a 10% market share. How much extra sales revenue must the firm find to reach that target?","options":{"A":"$1.2 million more, taking sales to $6 million","B":"$600,000 more, taking sales to $5.4 million","C":"$1.8 million more, taking sales to $6.6 million","D":"$2.4 million more, taking sales to $7.2 million"},"correctOption":"A","correctAnswer":"$1.2 million more, taking sales to $6 million","questionType":"MCQ","explanation":{"correct_reason":"A 10% share of the $60 million market is $6 million, and $6 million minus the current $4.8 million leaves $1.2 million of extra sales to find.","distractor_reasons":{"A":"A 10% share of the $60 million market is $6 million, and $6 million minus the current $4.8 million leaves $1.2 million of extra sales to find.","B":"This equals a 9% share of the market, one percentage point short of the 10% target in the strategy.","C":"This would produce a share of 11%, overshooting the stated 10% target and overstating the sales needed.","D":"This would produce a 12% share, which is two percentage points above the strategy target."}}},{"id":"P1_U3_MCQ_1141","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1141","question":"Sales of camping stoves in one region rose from $12 million to $15 million over three years. Over the same period Otterbury Outdoor's own stove sales rose from $1.8 million to $2.1 million. How did the firm's market share change?","options":{"A":"It rose from 14% to 15%","B":"It fell from 15% to 14%","C":"It stayed at 15% throughout","D":"It fell from 15% to 12%"},"correctOption":"B","correctAnswer":"It fell from 15% to 14%","questionType":"MCQ","explanation":{"correct_reason":"Otterbury's share began at $1.8 million out of $12 million, which is 15%, and ended at $2.1 million out of $15 million, which is 14%, so the share fell.","distractor_reasons":{"A":"The direction is reversed: 15% was the earlier share and 14% the later one, so the share fell rather than rose.","B":"Otterbury's share began at $1.8 million out of $12 million, which is 15%, and ended at $2.1 million out of $15 million, which is 14%, so the share fell.","C":"A constant 15% would require sales of $2.25 million in the larger market, but the firm reached only $2.1 million.","D":"A 12% share would mean sales of $1.8 million in the $15 million market, but the firm actually sold $2.1 million."}}},{"id":"P1_U3_MCQ_1142","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1142","question":"Marlbrook Pharmacy wants to know why customers under 25 rarely return. It writes its own short interview questions and asks 40 young customers at the counter over a fortnight. Which advantage of primary research does this show?","options":{"A":"The questions can be designed around the firm's own specific problem","B":"It is always cheaper than using published reports","C":"It is always quicker than reading existing data","D":"It guarantees the sample is representative of all shoppers"},"correctOption":"A","correctAnswer":"The questions can be designed around the firm's own specific problem","questionType":"MCQ","explanation":{"correct_reason":"Marlbrook writes its own questions about why young customers fail to return, so the research is tailored precisely to the problem the pharmacy needs to solve.","distractor_reasons":{"A":"Marlbrook writes its own questions about why young customers fail to return, so the research is tailored precisely to the problem the pharmacy needs to solve.","B":"Designing, piloting and carrying out 40 interviews usually costs more than using reports that already exist.","C":"A fortnight of interviewing is slower than reading published data that is available immediately.","D":"Interviewing 40 young customers at one counter cannot guarantee a sample representative of all shoppers."}}},{"id":"P1_U3_MCQ_1143","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1143","question":"Dunmore Hardware is launching a stairlift aimed at homeowners aged 55 to 70 and has a limited advertising budget of $4,000. Which advertising medium would be most suitable for reaching this target group?","options":{"A":"A national television campaign in prime time","B":"Sponsored posts on a teenage gaming website","C":"Advertisements in local newspapers and a retirement magazine","D":"A dance challenge promoted through social media influencers"},"correctOption":"C","correctAnswer":"Advertisements in local newspapers and a retirement magazine","questionType":"MCQ","explanation":{"correct_reason":"Local newspapers and a retirement magazine are read by the 55-to-70 age group and are affordable within $4,000, so the message reaches the intended buyers efficiently.","distractor_reasons":{"A":"A prime-time national television campaign would cost far more than $4,000 and reach many viewers who are not homeowners needing a stairlift.","B":"A teenage gaming site reaches the wrong audience entirely, since teenagers rarely buy or install stairlifts for themselves.","C":"Local newspapers and a retirement magazine are read by the 55-to-70 age group and are affordable within $4,000, so the message reaches the intended buyers efficiently.","D":"A social media dance challenge targets younger users and would waste the limited budget on people outside the target group."}}},{"id":"P1_U3_MCQ_1144","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1144","question":"Ashworth Furnishings used to deliver only within 30 miles of its workshop. It now sells nationwide through its website and uses couriers. Which new problem is the firm most likely to face?","options":{"A":"Far fewer potential customers to serve","B":"A sharp fall in demand for its furniture","C":"It must stop using its own delivery vans","D":"Higher delivery costs and more returned items to handle"},"correctOption":"D","correctAnswer":"Higher delivery costs and more returned items to handle","questionType":"MCQ","explanation":{"correct_reason":"Selling nationwide means long-distance courier charges on every order and more returns when customers cannot inspect furniture first, so distribution costs and admin rise.","distractor_reasons":{"A":"A nationwide website widens the customer base dramatically, so the firm has many more rather than fewer potential customers.","B":"Reaching the whole country normally increases demand, and nothing in the scenario suggests demand will collapse.","C":"The firm can keep its own vans for local drops while using couriers elsewhere, so it need not stop using them.","D":"Selling nationwide means long-distance courier charges on every order and more returns when customers cannot inspect furniture first, so distribution costs and admin rise."}}},{"id":"P1_U3_MCQ_1145","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1145","question":"Wroxham Toys makes a single basic wooden train that sells in 900 toy shops at $12, and it produces 50,000 units a year with heavy advertising on children's television. Which type of market is the firm serving?","options":{"A":"A mass market","B":"A niche market","C":"A market consisting of one retailer","D":"A secondary market"},"correctOption":"A","correctAnswer":"A mass market","questionType":"MCQ","explanation":{"correct_reason":"One standardised train sold through 900 shops with 50,000 units and television advertising targets a very large number of ordinary buyers, which is a mass market.","distractor_reasons":{"A":"One standardised train sold through 900 shops with 50,000 units and television advertising targets a very large number of ordinary buyers, which is a mass market.","B":"A niche market serves a small, specialised group with a distinctive product, whereas this train is a standard toy sold in huge volumes.","C":"The train is sold through 900 shops, so the market is far broader than a single retailer.","D":"Secondary market is not a market type in this context, and the train is sold to final consumers through retailers."}}},{"id":"P1_U3_MCQ_1146","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1146","question":"Lydgate Nurseries asks customers: 'Please describe how you felt about the service you received today and explain what we could improve.' Which type of data will this question produce, and why is it useful?","options":{"A":"Quantitative data that can be averaged easily","B":"Qualitative data that explains the reasons behind customer views","C":"Secondary data taken from published reports","D":"A quota sample of customer responses"},"correctOption":"B","correctAnswer":"Qualitative data that explains the reasons behind customer views","questionType":"MCQ","explanation":{"correct_reason":"An open question asking customers to describe feelings and suggest improvements produces words rather than numbers, which is qualitative data rich in explanation.","distractor_reasons":{"A":"Numbers that can be averaged come from closed rating scales, whereas this open question invites descriptive answers.","B":"An open question asking customers to describe feelings and suggest improvements produces words rather than numbers, which is qualitative data rich in explanation.","C":"Answers given directly by customers are collected first-hand, which makes them primary rather than secondary data.","D":"Quota sampling is a method of choosing respondents, not a type of answer produced by one open question."}}},{"id":"P1_U3_MCQ_1147","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1147","question":"Fernhill Ceramics sells mugs online at $24 each. Courier delivery costs $5.50 per order and protective packaging costs $1.20 per mug. How much of each $24 sale remains to cover the firm's other costs?","options":{"A":"$18.50","B":"$12.30","C":"$17.30","D":"$22.80"},"correctOption":"C","correctAnswer":"$17.30","questionType":"MCQ","explanation":{"correct_reason":"The $24 price less $5.50 courier and $1.20 packaging leaves $24 minus $6.70, which equals $17.30 per mug to cover other costs.","distractor_reasons":{"A":"This deducts only the $5.50 courier charge and forgets the $1.20 spent on protective packaging.","B":"This deducts $11.70 of costs, which is far more than the $6.70 actually stated for courier and packaging.","C":"The $24 price less $5.50 courier and $1.20 packaging leaves $24 minus $6.70, which equals $17.30 per mug to cover other costs.","D":"This adds the courier charge to the price instead of deducting the delivery and packaging costs."}}},{"id":"P1_U3_MCQ_1148","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1148","question":"Barrowdale Foods has won a contract to double its exports, but its bank refuses the loan needed for extra machinery. Which element of its marketing strategy is most directly constrained by this refusal?","options":{"A":"The wording of its advertising","B":"The design of its company logo","C":"The choice of its brand name","D":"The finance available to expand production capacity"},"correctOption":"D","correctAnswer":"The finance available to expand production capacity","questionType":"MCQ","explanation":{"correct_reason":"Doubling exports requires extra machinery, and without the loan Barrowdale cannot fund that capacity, so finance is the factor limiting the strategy.","distractor_reasons":{"A":"Advertising wording costs little and is not affected by a refusal to lend money for machinery.","B":"A logo design is a minor creative decision and does not depend on the machinery loan.","C":"The brand name can stay as it is, so the loan refusal does not constrain this choice at all.","D":"Doubling exports requires extra machinery, and without the loan Barrowdale cannot fund that capacity, so finance is the factor limiting the strategy."}}},{"id":"P1_U3_MCQ_1149","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1149","question":"Harport Foods surveys 500 shoppers in its region and finds that 120 of them recognise its brand name when shown the logo. What is the firm's level of brand awareness among those surveyed?","options":{"A":"24%","B":"12%","C":"42%","D":"38%"},"correctOption":"A","correctAnswer":"24%","questionType":"MCQ","explanation":{"correct_reason":"Brand awareness is 120 shoppers recognising the logo out of 500 surveyed, and 120 divided by 500 equals 0.24, which is 24%.","distractor_reasons":{"A":"Brand awareness is 120 shoppers recognising the logo out of 500 surveyed, and 120 divided by 500 equals 0.24, which is 24%.","B":"This would mean only 60 of the 500 shoppers recognised the logo, half the 120 actually recorded.","C":"This reverses the numbers, treating 500 out of 120 as a percentage instead of 120 out of 500.","D":"This would require 190 shoppers to recognise the logo, well above the 120 reported in the survey."}}},{"id":"P1_U3_MCQ_1150","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1150","question":"To select 100 customers from a list of 2,000, Halstead Cycles numbers every customer and uses a computer to choose 100 numbers without any pattern. Which sampling method is the firm using?","options":{"A":"Quota sampling","B":"Observation of customers in store","C":"Random sampling","D":"Analysis of secondary data"},"correctOption":"C","correctAnswer":"Random sampling","questionType":"MCQ","explanation":{"correct_reason":"Numbering the whole list and letting a computer pick 100 numbers without pattern gives every one of the 2,000 customers an equal chance, which is random sampling.","distractor_reasons":{"A":"Quota sampling fills fixed group targets chosen by an interviewer, whereas here a computer selects from a numbered list with no group targets.","B":"Observation would mean watching customers' behaviour in a shop rather than selecting 100 names from a customer list.","C":"Numbering the whole list and letting a computer pick 100 numbers without pattern gives every one of the 2,000 customers an equal chance, which is random sampling.","D":"The 100 selected customers will provide new information, so this is primary data collection rather than analysis of existing data."}}},{"id":"P1_U3_MCQ_1151","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1151","question":"Sales of Cawston Electronics' portable radio have fallen every year for six years, and rivals now sell digital radios at lower prices. The firm still makes the radio but spends almost nothing promoting it. Which stage of the product life cycle is it in?","options":{"A":"Introduction","B":"Growth","C":"Maturity","D":"Decline"},"correctOption":"D","correctAnswer":"Decline","questionType":"MCQ","explanation":{"correct_reason":"Six years of falling sales while cheaper digital substitutes take over is the decline stage, when a product loses its market and promotion is usually cut back.","distractor_reasons":{"A":"Introduction is the launch period with low but rising sales, which is the opposite of a six-year sales fall.","B":"Growth is a period of rapidly rising sales as customers adopt the product, not a steady long-term decline.","C":"Maturity is when sales level off near their peak, whereas Cawston's sales keep falling every year.","D":"Six years of falling sales while cheaper digital substitutes take over is the decline stage, when a product loses its market and promotion is usually cut back."}}},{"id":"P1_U3_MCQ_1152","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1152","question":"Cranborne Clothing sells identical jeans, sizes and advertising in 14 countries. This keeps costs low, but sales are weak in two markets where shoppers prefer a loose fit. Which conclusion is best?","options":{"A":"Standardisation always maximises sales in every market","B":"Standardisation lowers costs, but the firm should adapt the fit in the two weak markets","C":"The firm should withdraw from all 14 countries","D":"Costs are irrelevant when a firm markets abroad"},"correctOption":"B","correctAnswer":"Standardisation lowers costs, but the firm should adapt the fit in the two weak markets","questionType":"MCQ","explanation":{"correct_reason":"One product and campaign give Cranborne scale economies, yet the weak sales in two countries show that some local adaptation of fit is needed alongside those cost savings.","distractor_reasons":{"A":"Sales are weak in two of the 14 countries, which proves standardisation does not always maximise sales everywhere.","B":"One product and campaign give Cranborne scale economies, yet the weak sales in two countries show that some local adaptation of fit is needed alongside those cost savings.","C":"Only two of the 14 markets are weak, so withdrawing everywhere would throw away twelve successful markets.","D":"Low costs from standardisation are a genuine advantage, so costs clearly matter in international marketing."}}},{"id":"P1_U3_MCQ_1153","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1153","question":"Peverell Opticians has 4,000 customers on its records. During the past year, 1,300 of them bought new glasses or contact lenses from the practice again. What is the firm's repeat purchase rate?","options":{"A":"13%","B":"30.2%","C":"35%","D":"32.5%"},"correctOption":"D","correctAnswer":"32.5%","questionType":"MCQ","explanation":{"correct_reason":"The repeat purchase rate is 1,300 returning customers divided by 4,000 customers in total, which equals 0.325, or 32.5%.","distractor_reasons":{"A":"This treats 1,300 as 13% by moving the decimal point and ignores the 4,000 customer base.","B":"This would need 1,208 repeat buyers, which does not match the 1,300 recorded by Peverell Opticians.","C":"This would need 1,400 repeat buyers, which is 100 more than the number stated in the scenario.","D":"The repeat purchase rate is 1,300 returning customers divided by 4,000 customers in total, which equals 0.325, or 32.5%."}}},{"id":"P1_U3_MCQ_1154","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1154","question":"Before building 40 houses on a new site, Hollingbury Homes surveys 300 local families about the number of bedrooms and price range they want. Why is this research valuable to the developer?","options":{"A":"It reduces the risk of building homes that customers will not buy","B":"It guarantees every house will sell at a profit","C":"It removes competition from other local builders","D":"It sets the final selling prices automatically"},"correctOption":"A","correctAnswer":"It reduces the risk of building homes that customers will not buy","questionType":"MCQ","explanation":{"correct_reason":"Asking families about bedroom numbers and price range before building helps Hollingbury match the houses to demand, lowering the risk of unsold properties.","distractor_reasons":{"A":"Asking families about bedroom numbers and price range before building helps Hollingbury match the houses to demand, lowering the risk of unsold properties.","B":"Research can improve the chances of selling, but it cannot guarantee a profit on all 40 houses.","C":"Other builders remain free to compete on the same site, so research does not remove them.","D":"The developer still decides the asking prices; the survey only provides evidence to guide that decision."}}},{"id":"P1_U3_MCQ_1155","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1155","question":"Saxby Foods has made biscuits sold under a supermarket's own label for years. It now also sells the same biscuits under its own brand name at a higher price. Which advantage does the own brand give Saxby Foods?","options":{"A":"The supermarket will promote the biscuits more heavily","B":"It can build customer loyalty and charge a premium price","C":"It removes rival biscuit brands from supermarket shelves","D":"Its packaging costs will fall significantly"},"correctOption":"B","correctAnswer":"It can build customer loyalty and charge a premium price","questionType":"MCQ","explanation":{"correct_reason":"Selling under its own name lets shoppers recognise and ask for Saxby biscuits, which builds loyalty directly to the maker and supports the higher price.","distractor_reasons":{"A":"Supermarkets promote their own labels most strongly, so they may give less support to a competing manufacturer brand.","B":"Selling under its own name lets shoppers recognise and ask for Saxby biscuits, which builds loyalty directly to the maker and supports the higher price.","C":"Rival brands stay on the shelves, and one extra brand does not remove the competition.","D":"An own brand needs its own designs and print runs, which usually raises packaging costs rather than lowering them."}}},{"id":"P1_U3_MCQ_1156","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1156","question":"Waverley Homecare's clients are mostly over 70 and usually book visits by telephone. Managers plan to close the phone line and take all bookings through a new smartphone app. Why is this strategy risky?","options":{"A":"Smartphone apps are always more expensive to run than phone lines","B":"Older customers never use any form of technology","C":"It may exclude many existing clients who do not use apps","D":"It will reduce the range of care services the firm offers"},"correctOption":"C","correctAnswer":"It may exclude many existing clients who do not use apps","questionType":"MCQ","explanation":{"correct_reason":"Most clients are over 70 and book by telephone, so replacing the phone line with an app could shut out loyal customers who are unwilling or unable to use it.","distractor_reasons":{"A":"App running costs can be low, and the main risk is losing customers rather than the relative cost of the two channels.","B":"Many older people use smartphones, so claiming they never use technology is too sweeping and inaccurate.","C":"Most clients are over 70 and book by telephone, so replacing the phone line with an app could shut out loyal customers who are unwilling or unable to use it.","D":"Changing the booking method does not alter the care services themselves, only how clients arrange them."}}},{"id":"P1_U3_MCQ_1157","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1157","question":"A rival garage begins offering three years of free servicing with every new car. Falconhurst Motors responds by extending its own warranty from three years to five years without changing its prices. What form of competition is Falconhurst using?","options":{"A":"Non-price competition","B":"Price competition","C":"A price war","D":"Predatory pricing"},"correctOption":"A","correctAnswer":"Non-price competition","questionType":"MCQ","explanation":{"correct_reason":"Falconhurst keeps its prices unchanged and competes by improving the warranty instead, which is non-price competition based on added value rather than a lower price.","distractor_reasons":{"A":"Falconhurst keeps its prices unchanged and competes by improving the warranty instead, which is non-price competition based on added value rather than a lower price.","B":"Price competition involves cutting prices, but the stem says Falconhurst left its prices unchanged.","C":"A price war is a series of mutual price cuts, which is not happening because Falconhurst did not reduce prices.","D":"Predatory pricing means setting prices very low to drive rivals out, which again requires price cuts rather than a longer warranty."}}},{"id":"P1_U3_MCQ_1158","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1158","question":"Ashwater Leisure has a market research budget of $9,000. It plans to spend 60% on face-to-face interviews and 25% on an online survey, with the remainder buying a published industry report. How much will the report cost?","options":{"A":"$2,250","B":"$1,350","C":"$5,400","D":"$900"},"correctOption":"B","correctAnswer":"$1,350","questionType":"MCQ","explanation":{"correct_reason":"Interviews take 60% and the online survey 25%, leaving 15% of the $9,000 budget, and 15% of $9,000 equals $1,350 for the industry report.","distractor_reasons":{"A":"This is the 25% allocated to the online survey, not the money left for the published report.","B":"Interviews take 60% and the online survey 25%, leaving 15% of the $9,000 budget, and 15% of $9,000 equals $1,350 for the industry report.","C":"This is the 60% spent on face-to-face interviews, which is the largest single item in the budget.","D":"This is 10% of the budget and would leave the three items adding up to only 95% of the $9,000."}}},{"id":"P1_U3_MCQ_1159","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1159","question":"Lydden Farm sells its milk through vending machines at the farm gate and a local doorstep round, with no supermarket involved. Which advantage does this direct channel of distribution give the farm?","options":{"A":"It removes the need to store milk before sale","B":"It makes selling to distant cities straightforward","C":"It keeps the retailer's margin and gives control over freshness","D":"It removes the need to promote the milk at all"},"correctOption":"C","correctAnswer":"It keeps the retailer's margin and gives control over freshness","questionType":"MCQ","explanation":{"correct_reason":"Selling straight to consumers means no supermarket takes a cut, so Lydden Farm keeps the retail margin and can control how quickly the milk reaches buyers.","distractor_reasons":{"A":"Milk must still be chilled and stored between milking and sale, so storage is not removed by selling directly.","B":"Farm-gate vending and a local round serve nearby customers, so they do not make distant city sales easy.","C":"Selling straight to consumers means no supermarket takes a cut, so Lydden Farm keeps the retail margin and can control how quickly the milk reaches buyers.","D":"The farm still needs signs, a website or leaflets to attract customers to its vending machines and round."}}},{"id":"P1_U3_MCQ_1160","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1160","question":"Marchmont Broadband spent $18,000 on a six-week local campaign of posters, radio adverts and door-to-door sales that attracted 1,500 new customers. What was the average cost of winning each new customer?","options":{"A":"$1.20","B":"$27","C":"$120","D":"$12"},"correctOption":"D","correctAnswer":"$12","questionType":"MCQ","explanation":{"correct_reason":"The $18,000 campaign cost divided by the 1,500 new customers gives $12 spent on average to win each new customer.","distractor_reasons":{"A":"This misplaces the decimal point and would mean the campaign cost only $1,800 for 1,500 customers.","B":"This reverses the calculation by dividing 1,500 customers by $18,000 rather than the cost by the customers.","C":"This is ten times too high and would imply a campaign cost of $180,000.","D":"The $18,000 campaign cost divided by the 1,500 new customers gives $12 spent on average to win each new customer."}}},{"id":"P1_U3_MCQ_1161","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1161","question":"A national kitchen chain opens a store near Ravensworth Kitchens, a small independent, and advertises discounts that the independent cannot match. Which competitive response is most suitable for Ravensworth?","options":{"A":"Match every discount, even if each sale makes a loss","B":"Cut staff numbers so service becomes slower","C":"Focus on personal design advice and careful installation for local customers","D":"Stop all advertising to save money"},"correctOption":"C","correctAnswer":"Focus on personal design advice and careful installation for local customers","questionType":"MCQ","explanation":{"correct_reason":"A small independent cannot win a discount war, but it can compete on personal service and installation quality, which gives local customers a reason to choose it.","distractor_reasons":{"A":"Matching discounts on sales that already lose money would drain Ravensworth's finances and cannot last.","B":"Cutting staff makes service slower and removes the personal attention that is the independent's main advantage.","C":"A small independent cannot win a discount war, but it can compete on personal service and installation quality, which gives local customers a reason to choose it.","D":"Stopping advertising hides the firm from customers just when a larger rival is attracting attention nearby."}}},{"id":"P1_U3_MCQ_1162","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1162","question":"Tidewell Holidays pays $2,400 for 160 face-to-face interviews and a further $600 to print 800 questionnaire forms. What is the average cost of each completed interview?","options":{"A":"$15.00","B":"$3.75","C":"$18.75","D":"$21.25"},"correctOption":"C","correctAnswer":"$18.75","questionType":"MCQ","explanation":{"correct_reason":"Total research spending is $2,400 plus $600, which equals $3,000, and $3,000 divided by the 160 completed interviews gives $18.75 each.","distractor_reasons":{"A":"This uses only the $2,400 fieldwork cost and ignores the $600 spent on printing questionnaire forms.","B":"This divides $600 by 160, using only the printing cost rather than the whole $3,000 research spend.","C":"Total research spending is $2,400 plus $600, which equals $3,000, and $3,000 divided by the 160 completed interviews gives $18.75 each.","D":"This would require total spending of $3,400, which is $400 more than the two costs stated in the scenario."}}},{"id":"P1_U3_MCQ_1163","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1163","question":"Cranmore Insurance runs a television advert showing a flooded family whose claim was paid within three days. The advert aims to change how viewers feel about the company rather than to list policy details. Which type of advertising is this?","options":{"A":"Persuasive advertising","B":"Informative advertising","C":"Sales promotion","D":"Publicity"},"correctOption":"A","correctAnswer":"Persuasive advertising","questionType":"MCQ","explanation":{"correct_reason":"The advert uses an emotional story to change attitudes towards Cranmore rather than simply listing facts, which is the purpose of persuasive advertising.","distractor_reasons":{"A":"The advert uses an emotional story to change attitudes towards Cranmore rather than simply listing facts, which is the purpose of persuasive advertising.","B":"Informative advertising gives factual details such as prices or cover levels, which the stem says this advert does not do.","C":"Sales promotion offers short-term incentives such as vouchers, not a television story about a paid claim.","D":"Publicity is free coverage generated by news, whereas Cranmore has paid for this television advertisement."}}},{"id":"P1_U3_MCQ_1164","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1164","question":"Garsdale Furniture is losing sales to low-cost imported chairs and cannot cut its prices any further without making a loss. Which marketing strategy would best protect the firm's position?","options":{"A":"Reduce the quality of materials to lower costs","B":"Emphasise handcrafted quality and a 15-year guarantee to justify a premium price","C":"Copy the imports' designs and charge the same prices","D":"Stop supplying retailers and close the business"},"correctOption":"B","correctAnswer":"Emphasise handcrafted quality and a 15-year guarantee to justify a premium price","questionType":"MCQ","explanation":{"correct_reason":"Competing on price is impossible, so Garsdale should differentiate on handcrafted quality and a long guarantee that imports cannot easily match, supporting a premium price.","distractor_reasons":{"A":"Cutting material quality would damage the firm's reputation and make its chairs even easier to compare with cheap imports.","B":"Competing on price is impossible, so Garsdale should differentiate on handcrafted quality and a long guarantee that imports cannot easily match, supporting a premium price.","C":"Copying designs offers customers no reason to pay more and leaves the firm with the same cost disadvantage as before.","D":"Closing the business abandons a viable premium market instead of using a strategy that could protect its position."}}},{"id":"P1_U3_MCQ_1165","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1165","question":"Havenport Marine operates in a boat market worth $18 million a year. Families with children under 16 account for 35% of all spending in that market. What is the value of the family segment?","options":{"A":"$3.5 million","B":"$5.4 million","C":"$6.3 million","D":"$12.6 million"},"correctOption":"C","correctAnswer":"$6.3 million","questionType":"MCQ","explanation":{"correct_reason":"The family segment is 35% of the $18 million market, and 0.35 × $18 million equals $6.3 million of annual spending.","distractor_reasons":{"A":"This is about 19% of the market and would leave the family segment far smaller than the stated 35% share.","B":"This equals 30% of the market, five percentage points below the family share of 35%.","C":"The family segment is 35% of the $18 million market, and 0.35 × $18 million equals $6.3 million of annual spending.","D":"This is the 70% left for all other buyers rather than the family segment itself."}}},{"id":"P1_U3_MCQ_1166","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1166","question":"Sandiway Hotels sets its room prices using online guest reviews written six years ago, mostly by business travellers. What is the main weakness of relying on this source?","options":{"A":"Online reviews are always completely fake","B":"The reviews may be out of date and written by an unrepresentative group","C":"Reviews provide quantitative data only and contain no opinions","D":"Reviews are primary data collected by the hotel itself"},"correctOption":"B","correctAnswer":"The reviews may be out of date and written by an unrepresentative group","questionType":"MCQ","explanation":{"correct_reason":"Six-year-old comments from business travellers may not reflect today's market or leisure guests, so the evidence is both dated and drawn from a narrow group.","distractor_reasons":{"A":"Some reviews are unreliable, but claiming they are always completely fake is too sweeping and ignores the more specific problems of age and bias.","B":"Six-year-old comments from business travellers may not reflect today's market or leisure guests, so the evidence is both dated and drawn from a narrow group.","C":"Guest reviews are mostly written opinions and comments, which makes them qualitative rather than purely quantitative.","D":"Reviews are written by guests on third-party sites, so the hotel is using existing secondary data rather than collecting new primary data."}}},{"id":"P1_U3_MCQ_1167","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1167","question":"Pendlebury Sports sold 3,000 rackets at $14 each. After a rival cut its price, Pendlebury reduced its price to $12.50 and sold 3,400 rackets. What happened to total sales revenue?","options":{"A":"It was higher at the old price, at $42,000","B":"It rose to $42,500, which is $2,500 more than before","C":"It stayed unchanged at $42,000","D":"It rose to $42,500, which is $500 more than before"},"correctOption":"D","correctAnswer":"It rose to $42,500, which is $500 more than before","questionType":"MCQ","explanation":{"correct_reason":"The old revenue was 3,000 × $14 = $42,000, and the new revenue is 3,400 × $12.50 = $42,500, so revenue rose by $500 despite the price cut.","distractor_reasons":{"A":"The old revenue was indeed $42,000, but the new revenue of $42,500 is higher, so the old price did not produce more income.","B":"The new revenue is $42,500, but the increase over $42,000 is $500 rather than $2,500.","C":"Revenue changed from $42,000 to $42,500, so it did not stay unchanged even though the difference is small.","D":"The old revenue was 3,000 × $14 = $42,000, and the new revenue is 3,400 × $12.50 = $42,500, so revenue rose by $500 despite the price cut."}}},{"id":"P1_U3_MCQ_1168","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1168","question":"Winstanley Tools can sell through an online marketplace that charges fees of 12% on expected sales of $50,000, or run its own website at a fixed cost of $9,000. Which option is cheaper, and by how much?","options":{"A":"The marketplace, by $3,000","B":"Its own website, by $3,000","C":"The marketplace, by $6,000","D":"Both options cost exactly the same"},"correctOption":"A","correctAnswer":"The marketplace, by $3,000","questionType":"MCQ","explanation":{"correct_reason":"Marketplace fees are 12% of $50,000, which equals $6,000, so the marketplace is cheaper than the $9,000 website by $3,000.","distractor_reasons":{"A":"Marketplace fees are 12% of $50,000, which equals $6,000, so the marketplace is cheaper than the $9,000 website by $3,000.","B":"The website costs $9,000 against $6,000 of marketplace fees, so the website is the dearer option.","C":"The $6,000 is the total marketplace fee, not the difference between the two alternatives.","D":"The two options differ by $3,000, so their costs are not equal."}}},{"id":"P1_U3_MCQ_1169","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1169","question":"Hurstbourne Bakery sold plain loaves at $1.20. After many customers asked for gluten-free bread, it launched a gluten-free range at $2.30 a loaf and sales grew quickly. Which marketing point does this illustrate?","options":{"A":"Meeting an identified customer need can support a higher price","B":"Raising prices always reduces the quantity customers buy","C":"Customers have no influence over the products a firm makes","D":"Specialist ingredients never add to production costs"},"correctOption":"A","correctAnswer":"Meeting an identified customer need can support a higher price","questionType":"MCQ","explanation":{"correct_reason":"The bakery responded to repeated requests by adding a gluten-free range, and customers accepted a price nearly double the plain loaf, showing that meeting a real need supports a premium.","distractor_reasons":{"A":"The bakery responded to repeated requests by adding a gluten-free range, and customers accepted a price nearly double the plain loaf, showing that meeting a real need supports a premium.","B":"Sales grew quickly at the higher price, which contradicts the claim that raising prices always reduces purchases.","C":"The new range exists because customers asked for it, so customers clearly influenced the product decision.","D":"Gluten-free ingredients usually cost more than wheat flour, so they normally add to production costs."}}},{"id":"P1_U3_MCQ_1170","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1170","question":"Marsden Deli surveyed 480 customers about packaging. Of these, 180 said they would pay more for compostable packaging. What percentage of respondents chose compostable packaging?","options":{"A":"27%","B":"45%","C":"33%","D":"37.5%"},"correctOption":"D","correctAnswer":"37.5%","questionType":"MCQ","explanation":{"correct_reason":"The share is 180 respondents out of 480, and 180 divided by 480 equals 0.375, which is 37.5% of those surveyed.","distractor_reasons":{"A":"This would mean about 130 of the 480 respondents chose compostable packaging, not the 180 recorded.","B":"This would require 216 respondents, which is 36 more than the 180 who actually chose compostable packaging.","C":"This equals 158 respondents and does not match the 180 reported by Marsden Deli.","D":"The share is 180 respondents out of 480, and 180 divided by 480 equals 0.375, which is 37.5% of those surveyed."}}},{"id":"P1_U3_MCQ_1171","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1171","question":"Brindley Foods has moved its soups into smaller resealable pouches printed with clear cooking instructions, and sales to single-person households have risen. Which two functions of packaging does this mainly show?","options":{"A":"Reducing unit costs and raising the selling price","B":"Replacing advertising and building a brand name","C":"Protecting the contents and communicating information to buyers","D":"Extending shelf life and removing the need for labelling"},"correctOption":"C","correctAnswer":"Protecting the contents and communicating information to buyers","questionType":"MCQ","explanation":{"correct_reason":"A resealable pouch protects the soup once opened, while printed cooking instructions inform the buyer, so the change illustrates both the protective and informative functions of packaging.","distractor_reasons":{"A":"Printed pouches usually cost more than plain packaging, so the change does not show lower costs or a price increase.","B":"Packaging supports promotion but cannot replace advertising, and the scenario makes no claim about building a brand.","C":"A resealable pouch protects the soup once opened, while printed cooking instructions inform the buyer, so the change illustrates both the protective and informative functions of packaging.","D":"The pouches still carry printed instructions, so labelling is not removed even if shelf life is extended."}}},{"id":"P1_U3_MCQ_1172","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1172","question":"Kelmscott Garden Products can spend $20,000 on social media advertising expected to generate $70,000 of extra sales, or $15,000 on leaflets expected to generate $45,000. Which option gives the better return for each dollar spent?","options":{"A":"Leaflets, because the campaign costs less","B":"Social media, because each $1 spent returns $3.50 of sales against $3.00","C":"Social media, because $70,000 is a larger total than $45,000","D":"Neither, because both campaigns cost exactly the same"},"correctOption":"B","correctAnswer":"Social media, because each $1 spent returns $3.50 of sales against $3.00","questionType":"MCQ","explanation":{"correct_reason":"Social media returns $70,000 from $20,000, which is $3.50 per $1 spent, while leaflets return $45,000 from $15,000, which is $3.00, so social media gives the better return.","distractor_reasons":{"A":"A lower total cost does not mean a better return, because the leaflet campaign also generates less sales per dollar spent.","B":"Social media returns $70,000 from $20,000, which is $3.50 per $1 spent, while leaflets return $45,000 from $15,000, which is $3.00, so social media gives the better return.","C":"The larger total ignores the different spending levels, and comparing returns requires dividing sales by the amount spent.","D":"The two campaigns cost $20,000 and $15,000, so they are clearly not the same cost."}}},{"id":"P1_U3_MCQ_1173","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1173","question":"Sparsholt Motors resolved 250 complaints within 24 hours, and 210 of those customers bought from the firm again. Of 150 complaints that took a week to resolve, only 60 customers returned. Which conclusion is best supported?","options":{"A":"Complaints should be ignored because customers complain anyway","B":"Slow resolution of complaints improves customer loyalty","C":"Fast complaint handling is linked to higher customer retention","D":"All customers who complain leave the business regardless"},"correctOption":"C","correctAnswer":"Fast complaint handling is linked to higher customer retention","questionType":"MCQ","explanation":{"correct_reason":"Fast resolution kept 210 of 250 customers, roughly 84%, while slow resolution kept only 60 of 150, roughly 40%, so speedy handling is associated with much better retention.","distractor_reasons":{"A":"Ignoring complaints would remove the fast handling that is linked to keeping 84% of those customers.","B":"The slow group retained only about 40% of complainants, well below the fast group's 84%, so slow handling is worse.","C":"Fast resolution kept 210 of 250 customers, roughly 84%, while slow resolution kept only 60 of 150, roughly 40%, so speedy handling is associated with much better retention.","D":"Many complainants clearly stayed, since 210 of the fast group and 60 of the slow group bought again."}}},{"id":"P1_U3_MCQ_1174","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1174","question":"Wrenbury Toys videos children playing with a prototype and counts how long each child stays interested, but the researchers never ask the children any questions. What is the main limitation of this research?","options":{"A":"Observation always produces secondary data","B":"Observation cannot record how long a child plays","C":"Children may not be observed in a play setting","D":"Observation shows behaviour but not the reasons behind it"},"correctOption":"D","correctAnswer":"Observation shows behaviour but not the reasons behind it","questionType":"MCQ","explanation":{"correct_reason":"Watching and timing play reveals what children do, but without asking questions the firm cannot learn why a child lost interest or what would hold attention.","distractor_reasons":{"A":"The videos are recorded first-hand by the firm's own researchers, which makes the evidence primary rather than secondary data.","B":"Timing is exactly what observation does well, since researchers can record how many minutes each child stays with the toy.","C":"Play settings are a normal and suitable place to observe children, provided parental consent and safeguards are in place.","D":"Watching and timing play reveals what children do, but without asking questions the firm cannot learn why a child lost interest or what would hold attention."}}},{"id":"P1_U3_MCQ_1175","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1175","question":"Ardent Audio launches patented noise-cancelling headphones at $349, then cuts the price to $279 six months later. Rivals cannot copy the technology during the first year. Why is this pricing approach appropriate?","options":{"A":"Rivals already sell similar headphones at $349","B":"Early adopters will pay a high price for new technology, and the price can fall later","C":"The firm wants the largest possible market share from day one","D":"Production costs are low enough to support any price"},"correctOption":"B","correctAnswer":"Early adopters will pay a high price for new technology, and the price can fall later","questionType":"MCQ","explanation":{"correct_reason":"Price skimming starts high while the patented product is unique and keen buyers will pay $349, then lowers the price to reach more price-sensitive customers after six months.","distractor_reasons":{"A":"The stem says rivals cannot copy the technology in the first year, so they do not yet sell similar headphones at $349.","B":"Price skimming starts high while the patented product is unique and keen buyers will pay $349, then lowers the price to reach more price-sensitive customers after six months.","C":"Maximum early market share would call for a low launch price, which is penetration pricing rather than a $349 launch.","D":"Costs affect the profit at each price but do not explain why a high launch price is cut after the early adopters have bought."}}},{"id":"P1_U3_MCQ_1176","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1176","question":"Baverstock Tools supplies tradespeople. Research shows that 70% of its buyers now order from building sites using a mobile phone. Which change to its marketing strategy is best supported by this finding?","options":{"A":"Move all sales onto printed catalogues posted to home addresses","B":"Extend showroom opening hours and do nothing else","C":"Make its ordering site mobile-friendly and promote it on trade social media","D":"Reduce the product range to a few best-selling lines"},"correctOption":"C","correctAnswer":"Make its ordering site mobile-friendly and promote it on trade social media","questionType":"MCQ","explanation":{"correct_reason":"If 70% of buyers order by mobile from sites, the strategy should make mobile ordering quick and easy and reach tradespeople where they already spend time online.","distractor_reasons":{"A":"Printed catalogues posted home conflict with customers who now order on site from a phone.","B":"Longer showroom hours do not help buyers who are ordering remotely from building sites rather than visiting.","C":"If 70% of buyers order by mobile from sites, the strategy should make mobile ordering quick and easy and reach tradespeople where they already spend time online.","D":"Cutting the range reduces choice for trade buyers and does not respond to the finding about mobile ordering at all."}}},{"id":"P1_U3_MCQ_1177","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1177","question":"Bramshaw Foods sold $7.2 million of sauces when the total market was worth $90 million. The next year it sold $8.4 million while the market grew to $105 million. What happened to Bramshaw's market share?","options":{"A":"It rose from 8% to 9%","B":"It fell from 9% to 8%","C":"It remained at 8%","D":"It rose from 8% to 12%"},"correctOption":"C","correctAnswer":"It remained at 8%","questionType":"MCQ","explanation":{"correct_reason":"In the first year $7.2 million out of $90 million is 8%, and in the second year $8.4 million out of $105 million is also 8%, so the share was unchanged.","distractor_reasons":{"A":"A 9% share in the second year would need sales of $9.45 million, well above the $8.4 million achieved.","B":"The first-year share was 8%, not 9%, so the share did not fall from 9% to 8%.","C":"In the first year $7.2 million out of $90 million is 8%, and in the second year $8.4 million out of $105 million is also 8%, so the share was unchanged.","D":"A 12% share in the second year would require sales of $12.6 million, far more than the $8.4 million recorded."}}},{"id":"P1_U3_MCQ_1178","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1178","question":"Nethercott Plant Hire emails a satisfaction survey to 700 trade customers and receives replies from 12% of them. How many customers replied to the survey?","options":{"A":"70","B":"120","C":"700","D":"84"},"correctOption":"D","correctAnswer":"84","questionType":"MCQ","explanation":{"correct_reason":"A 12% response from 700 customers is 0.12 × 700, which equals 84 replies to the satisfaction survey.","distractor_reasons":{"A":"This is a 10% response rate, which is lower than the 12% stated in the scenario.","B":"This would be a response rate of about 17%, well above the 12% actually achieved.","C":"This assumes every customer replied, but the scenario states that only 12% responded.","D":"A 12% response from 700 customers is 0.12 × 700, which equals 84 replies to the satisfaction survey."}}},{"id":"P1_U3_MCQ_1179","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1179","question":"Tredworth Brewery gives its spent grain to a community garden and organises a river clean-up. A regional newspaper then writes a free article praising the company. Which promotional method has the brewery gained?","options":{"A":"Sales promotion","B":"Sponsorship","C":"Personal selling","D":"Public relations"},"correctOption":"D","correctAnswer":"Public relations","questionType":"MCQ","explanation":{"correct_reason":"Community work that earns favourable free newspaper coverage is public relations, which builds goodwill and a positive image without paying for advertising space.","distractor_reasons":{"A":"Sales promotion offers short-term buying incentives such as vouchers, which the brewery is not giving to customers.","B":"Sponsorship means paying to attach the brand to an event or team, whereas the article came from community activity.","C":"Personal selling involves staff talking to individual buyers, not a newspaper writing about community projects.","D":"Community work that earns favourable free newspaper coverage is public relations, which builds goodwill and a positive image without paying for advertising space."}}},{"id":"P1_U3_MCQ_1180","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1180","question":"Halberton Cycles sells high-priced racing bikes to serious club riders and is considering a cheaper commuter range for everyday cyclists. Which factor is most important in judging whether this new segment will succeed?","options":{"A":"Whether the firm can keep using its existing logo","B":"Whether commuters' needs and price expectations differ from those of club riders","C":"Whether the firm's current advertising uses blue colours","D":"Whether the factory has a staff canteen"},"correctOption":"B","correctAnswer":"Whether commuters' needs and price expectations differ from those of club riders","questionType":"MCQ","explanation":{"correct_reason":"Commuters need different features and lower prices than racing cyclists, so understanding how far their needs differ is central to deciding whether the new range can succeed.","distractor_reasons":{"A":"The logo can stay exactly as it is, so this has almost no bearing on whether commuters will buy the new range.","B":"Commuters need different features and lower prices than racing cyclists, so understanding how far their needs differ is central to deciding whether the new range can succeed.","C":"The colour used in existing advertising is a minor design detail that will not determine demand from commuters.","D":"A staff canteen affects employee welfare and has no direct connection with demand for a commuter bicycle range."}}},{"id":"P1_U3_MCQ_1181","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1181","question":"Aldworth Bakers checks its market share every quarter as well as watching its own sales revenue. Why is market share a more useful measure of marketing performance than sales revenue alone?","options":{"A":"It shows the firm's total profit for the year","B":"It measures customer satisfaction directly","C":"It shows performance relative to the whole market and to competitors","D":"It removes the need for any further market research"},"correctOption":"C","correctAnswer":"It shows performance relative to the whole market and to competitors","questionType":"MCQ","explanation":{"correct_reason":"Sales alone can rise while rivals grow faster, but market share compares Aldworth's sales with total market sales, showing whether it is gaining or losing ground.","distractor_reasons":{"A":"Market share measures sales relative to the market and says nothing about costs, so it cannot show profit.","B":"Satisfaction requires asking customers how they feel; a percentage share of sales does not measure it.","C":"Sales alone can rise while rivals grow faster, but market share compares Aldworth's sales with total market sales, showing whether it is gaining or losing ground.","D":"Market share shows the outcome of past marketing but still leaves questions about why customers behave as they do, so research is still needed."}}},{"id":"P1_U3_MCQ_1182","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1182","question":"Gledhill Furnishings wants 60 interviews with shoppers in a busy city centre, but there is no list of who will be there. Interviewers are told to fill quotas of 20 shoppers in each of three age bands. Why is quota sampling suitable here?","options":{"A":"There is no complete list of shoppers from which to select a random sample","B":"It guarantees that every shopper has an equal chance of being chosen","C":"It means interviewers need not ask any questions at all","D":"It produces secondary data already published by others"},"correctOption":"A","correctAnswer":"There is no complete list of shoppers from which to select a random sample","questionType":"MCQ","explanation":{"correct_reason":"Random sampling requires a full list of the population, and no such list exists for passing shoppers, so quotas let interviewers fill set age bands on the spot.","distractor_reasons":{"A":"Random sampling requires a full list of the population, and no such list exists for passing shoppers, so quotas let interviewers fill set age bands on the spot.","B":"Quota sampling selects respondents by interviewer choice, so shoppers do not have an equal chance of being picked.","C":"Quota sampling still involves asking the 60 selected shoppers the survey questions, so questioning is not avoided.","D":"Interviews carried out by the firm produce new primary data, not secondary data published by someone else."}}},{"id":"P1_U3_MCQ_1183","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1183","question":"Ravensdale Toys sells its wooden puzzles to toy shops, which hold stock, display the puzzles on shelves and sell them to local families. Which function do these retailers perform for consumers?","options":{"A":"Manufacturing the puzzles to the required quality standard","B":"Holding stock so goods are available conveniently nearby","C":"Designing the original product and its packaging","D":"Supplying the raw timber used in production"},"correctOption":"B","correctAnswer":"Holding stock so goods are available conveniently nearby","questionType":"MCQ","explanation":{"correct_reason":"By storing puzzles and displaying them in local shops, retailers let families buy immediately without travelling to the manufacturer, which is a key retail function.","distractor_reasons":{"A":"Manufacturing is carried out by Ravensdale Toys itself, not by the toy shops that resell the puzzles.","B":"By storing puzzles and displaying them in local shops, retailers let families buy immediately without travelling to the manufacturer, which is a key retail function.","C":"Product and packaging design belong to the manufacturer, while retailers mainly choose how to display what they buy.","D":"Timber is bought by the manufacturer, and retailers have no role in supplying raw materials."}}},{"id":"P1_U3_MCQ_1184","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1184","question":"Westerfield Coffee wants to open cafés in six overseas cities quickly but has limited capital of its own. Local operators would invest their own money and follow Westerfield's brand standards. Which market entry method best fits this plan?","options":{"A":"Building company-owned cafés in every city","B":"A joint venture with a single overseas partner","C":"Selling coffee beans through its own website only","D":"Franchising the cafés to local operators"},"correctOption":"D","correctAnswer":"Franchising the cafés to local operators","questionType":"MCQ","explanation":{"correct_reason":"Franchising lets local operators put up the capital while trading under Westerfield's brand standards, so the firm can expand into six cities without funding the cafés itself.","distractor_reasons":{"A":"Company-owned cafés in six cities would demand far more capital than Westerfield currently has available.","B":"One joint venture partner would not normally deliver six city openings quickly and would share control of the brand.","C":"Selling beans online does not create cafés or use local operators who invest their own money.","D":"Franchising lets local operators put up the capital while trading under Westerfield's brand standards, so the firm can expand into six cities without funding the cafés itself."}}},{"id":"P1_U3_MCQ_1185","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1185","question":"Penshurst Optics operates in a regional eyewear market worth $24 million a year. Customers aged 60 and over account for 40% of all spending in that market. What is the value of the over-60 segment?","options":{"A":"$4.8 million","B":"$6.0 million","C":"$9.6 million","D":"$14.4 million"},"correctOption":"C","correctAnswer":"$9.6 million","questionType":"MCQ","explanation":{"correct_reason":"The over-60 group is 40% of the $24 million market, and 0.40 × $24 million equals $9.6 million of annual spending on eyewear.","distractor_reasons":{"A":"This is 20% of the market, half the 40% share attributed to the over-60 segment.","B":"This equals 25% of the $24 million market, which is well below the stated 40% share.","C":"The over-60 group is 40% of the $24 million market, and 0.40 × $24 million equals $9.6 million of annual spending on eyewear.","D":"This is the 60% spent by all other age groups rather than the over-60 segment."}}},{"id":"P1_U3_MCQ_1186","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1186","question":"Ballantyne Garden Machinery, which sells lawnmowers and hedge trimmers through six branches, is deciding how to survey customer satisfaction. Which of these samples is likely to produce the most reliable results?","options":{"A":"600 customers selected at random from across the whole region","B":"60 customers questioned in a single branch","C":"Nine long-standing customers chosen by the manager","D":"One customer interviewed for a full hour"},"correctOption":"A","correctAnswer":"600 customers selected at random from across the whole region","questionType":"MCQ","explanation":{"correct_reason":"A large random sample drawn from the whole region is far more likely to reflect the views of all customers than a small group from one place or chosen by the manager.","distractor_reasons":{"A":"A large random sample drawn from the whole region is far more likely to reflect the views of all customers than a small group from one place or chosen by the manager.","B":"Sixty customers in one branch reflect that branch's catchment only and may not represent the wider customer base.","C":"Nine customers chosen by the manager are a tiny, selected group whose views are likely to be unrepresentative.","D":"One detailed interview gives depth but cannot represent the views of hundreds or thousands of customers."}}},{"id":"P1_U3_MCQ_1187","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1187","question":"Clevedon Ceramics sold 1,800 mugs at $6.50 each. After raising the price to $7.20, it sold 1,650 mugs. What was the effect on total revenue?","options":{"A":"It rose to $11,880, which is $180 more than before","B":"It was higher before, at $11,700, by $180","C":"It rose to $11,880, which is $1,180 more than before","D":"It stayed the same at $11,700"},"correctOption":"A","correctAnswer":"It rose to $11,880, which is $180 more than before","questionType":"MCQ","explanation":{"correct_reason":"Old revenue was 1,800 × $6.50 = $11,700, and new revenue is 1,650 × $7.20 = $11,880, so revenue rose by $180 despite fewer mugs being sold.","distractor_reasons":{"A":"Old revenue was 1,800 × $6.50 = $11,700, and new revenue is 1,650 × $7.20 = $11,880, so revenue rose by $180 despite fewer mugs being sold.","B":"The later revenue of $11,880 is higher, so revenue rose rather than falling by $180.","C":"The difference between $11,700 and $11,880 is $180, not $1,180, so the stated increase is far too large.","D":"The two revenues differ by $180, so revenue did not stay the same."}}},{"id":"P1_U3_MCQ_1188","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1188","question":"Dunton Brewery sells a premium ale only through specialist beer shops at a high price. A discount supermarket chain offers to stock large volumes at a much lower price. Which marketing risk should the brewery consider most carefully?","options":{"A":"Its production costs would fall automatically","B":"It would be guaranteed a higher price per bottle","C":"It would no longer need to advertise","D":"Selling through discounters could weaken its premium brand image"},"correctOption":"D","correctAnswer":"Selling through discounters could weaken its premium brand image","questionType":"MCQ","explanation":{"correct_reason":"A premium ale sold cheaply in a discounter may look less exclusive, so existing specialist customers could question the high price and the brand's image may suffer.","distractor_reasons":{"A":"Higher volume may spread fixed costs, but production costs do not fall automatically and the main risk is to brand image.","B":"The discounter is offering a much lower price, so the brewery would not be guaranteed a higher price per bottle.","C":"The brewery would still need advertising to protect its premium position, especially if it appears in discount stores.","D":"A premium ale sold cheaply in a discounter may look less exclusive, so existing specialist customers could question the high price and the brand's image may suffer."}}},{"id":"P1_U3_MCQ_1189","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1189","question":"Two rival taxi firms in one town have cut fares three times in six months, and both now report falling profits although passenger numbers are steady. Which is the most likely consequence of this price competition?","options":{"A":"Profits always rise because more passengers travel","B":"Lower fares protect sales but reduce the profit earned on each journey","C":"Customers stop comparing the prices of the two firms","D":"The town's taxi market becomes a monopoly immediately"},"correctOption":"B","correctAnswer":"Lower fares protect sales but reduce the profit earned on each journey","questionType":"MCQ","explanation":{"correct_reason":"Passenger numbers are steady while prices fall, so each journey earns a smaller margin, which explains why both firms report lower profits after the repeated cuts.","distractor_reasons":{"A":"Passenger numbers are described as steady, so profits are not rising through extra passengers; both firms report falling profits.","B":"Passenger numbers are steady while prices fall, so each journey earns a smaller margin, which explains why both firms report lower profits after the repeated cuts.","C":"Customers facing repeated fare cuts become more price-aware, so they are likely to compare the two firms even more closely.","D":"Two firms are still competing after the cuts, so the market has not become a monopoly."}}},{"id":"P1_U3_MCQ_1190","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1190","question":"Hollinrake Foods surveyed 250 shoppers about a new low-salt sauce. Of the respondents, 44% said they would definitely buy it at $2.80 a jar. How many respondents said they would definitely buy?","options":{"A":"44","B":"100","C":"110","D":"140"},"correctOption":"C","correctAnswer":"110","questionType":"MCQ","explanation":{"correct_reason":"The number is 44% of 250 respondents, and 0.44 × 250 equals 110 shoppers who said they would definitely buy the sauce.","distractor_reasons":{"A":"This repeats the 44% figure as a number of people rather than applying it to the 250 respondents.","B":"This equals 40% of 250, four percentage points below the 44% reported in the survey.","C":"The number is 44% of 250 respondents, and 0.44 × 250 equals 110 shoppers who said they would definitely buy the sauce.","D":"This equals 56% of 250 and is closer to the share who did not say they would definitely buy."}}},{"id":"P1_U3_MCQ_1191","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1191","question":"Tamarisk Travel prints 8,000 brochures at $0.45 each and gets enquiries that turn into 200 bookings, a 2.5% response rate. What is the average brochure cost of each booking?","options":{"A":"$18.00","B":"$0.45","C":"$1.80","D":"$4.50"},"correctOption":"A","correctAnswer":"$18.00","questionType":"MCQ","explanation":{"correct_reason":"Printing 8,000 brochures at $0.45 costs $3,600, and a 2.5% response gives 200 bookings, so $3,600 divided by 200 equals $18.00 per booking.","distractor_reasons":{"A":"Printing 8,000 brochures at $0.45 costs $3,600, and a 2.5% response gives 200 bookings, so $3,600 divided by 200 equals $18.00 per booking.","B":"This is the cost of printing a single brochure and ignores how many brochures are needed to produce one booking.","C":"This would mean the whole print run cost only $360, one tenth of the actual $3,600 spent.","D":"This would mean 800 bookings rather than the 200 produced by a 2.5% response to 8,000 brochures."}}},{"id":"P1_U3_MCQ_1192","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1192","question":"After every campaign, Cranleigh Systems compares actual sales with the target set in its marketing plan, identifies what went wrong and changes the next campaign. What marketing activity is this?","options":{"A":"Reviewing and controlling the marketing strategy","B":"Carrying out a quota sample of customers","C":"Setting a penetration price for a new product","D":"Selecting a channel of distribution"},"correctOption":"A","correctAnswer":"Reviewing and controlling the marketing strategy","questionType":"MCQ","explanation":{"correct_reason":"Comparing results with planned targets and then adjusting the next campaign is the review and control stage, which keeps the marketing strategy on track.","distractor_reasons":{"A":"Comparing results with planned targets and then adjusting the next campaign is the review and control stage, which keeps the marketing strategy on track.","B":"Quota sampling is a research method for choosing respondents, not the process of comparing sales with targets.","C":"A penetration price is a low launch price decision, whereas this activity evaluates results after campaigns have run.","D":"Choosing a distribution channel decides how goods reach customers and is not the same as reviewing campaign performance."}}},{"id":"P1_U3_MCQ_1193","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1193","question":"Coppice Interiors lost a large contract after late deliveries, and 30% of its remaining customers then moved to rivals after hearing about the problem. Which point about customers does this illustrate?","options":{"A":"Customers matter only to businesses that provide services","B":"Customer needs are fixed and rarely change over time","C":"Satisfied customers will always accept higher prices","D":"Poor satisfaction damages repeat business and word-of-mouth recommendations"},"correctOption":"D","correctAnswer":"Poor satisfaction damages repeat business and word-of-mouth recommendations","questionType":"MCQ","explanation":{"correct_reason":"Late deliveries lost one contract and then 30% of other customers left after hearing about it, showing how dissatisfaction spreads through word of mouth and destroys repeat trade.","distractor_reasons":{"A":"Coppice Interiors supplies goods as well as installation, and customer satisfaction is vital to every type of business.","B":"Customer expectations change constantly, and the scenario shows customers reacting strongly to a service failure.","C":"The customers left because of poor service, which shows satisfaction does not make buyers accept any price.","D":"Late deliveries lost one contract and then 30% of other customers left after hearing about it, showing how dissatisfaction spreads through word of mouth and destroys repeat trade."}}},{"id":"P1_U3_MCQ_1194","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1194","question":"Barrowfield Estates wants detailed explanations from twelve landlords about why they stopped letting through the agency. The agency needs to probe each answer and ask follow-up questions. Which method is most suitable?","options":{"A":"A postal questionnaire sent to 2,000 households","B":"In-depth face-to-face or telephone interviews with the twelve landlords","C":"Observation of landlords visiting the office","D":"Analysis of national housing statistics"},"correctOption":"B","correctAnswer":"In-depth face-to-face or telephone interviews with the twelve landlords","questionType":"MCQ","explanation":{"correct_reason":"A small number of former landlords giving detailed reasons requires interviews where the researcher can probe and follow up each answer, which questionnaires and statistics cannot do.","distractor_reasons":{"A":"A postal questionnaire to 2,000 households would not reach the twelve former landlords and gives no chance to probe answers.","B":"A small number of former landlords giving detailed reasons requires interviews where the researcher can probe and follow up each answer, which questionnaires and statistics cannot do.","C":"Watching landlords visit the office would not reveal why they stopped letting through the agency.","D":"National housing statistics do not explain the personal reasons of these twelve former clients."}}},{"id":"P1_U3_MCQ_1195","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1195","question":"Ottershaw Tools adds a lifetime blade replacement guarantee to its garden shears, raises the price by $8 and sees sales rise. Which benefit does the guarantee create for the firm?","options":{"A":"A lower unit cost of production","B":"A shorter channel of distribution","C":"A unique selling point that supports a premium price","D":"A larger quota sample of buyers"},"correctOption":"C","correctAnswer":"A unique selling point that supports a premium price","questionType":"MCQ","explanation":{"correct_reason":"A lifetime replacement guarantee is a product feature rivals do not offer, so it differentiates the shears and gives customers a reason to accept the $8 higher price.","distractor_reasons":{"A":"Replacing blades free of charge adds future cost to the firm rather than lowering the unit cost of production.","B":"The guarantee concerns the product itself and does not change how many intermediaries sit between maker and buyer.","C":"A lifetime replacement guarantee is a product feature rivals do not offer, so it differentiates the shears and gives customers a reason to accept the $8 higher price.","D":"A quota sample is a market research technique and has nothing to do with a product guarantee."}}},{"id":"P1_U3_MCQ_1196","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1196","question":"Norwood Leisure can serve at most 600 members at its new gym. It could offer premium membership at $90 a month to 400 people or budget membership at $25 a month to 2,000 people. Which strategy fits its capacity?","options":{"A":"The budget option, because a lower price per member is always better","B":"The premium option, because it needs fewer staff","C":"The premium option, because the budget plan needs 2,000 members but capacity is 600","D":"Either option, because capacity does not affect marketing strategy"},"correctOption":"C","correctAnswer":"The premium option, because the budget plan needs 2,000 members but capacity is 600","questionType":"MCQ","explanation":{"correct_reason":"The gym can serve only 600 members, so the budget plan's 2,000 members is impossible, while premium membership at 400 people fits comfortably within capacity.","distractor_reasons":{"A":"A low price is useless if the firm must turn away 1,400 of the 2,000 members the budget plan requires.","B":"Staffing numbers are not given, and the decisive point is that 400 members fit within the 600-member limit.","C":"The gym can serve only 600 members, so the budget plan's 2,000 members is impossible, while premium membership at 400 people fits comfortably within capacity.","D":"Capacity sets a hard limit on how many members can be served, so it directly shapes which strategy is feasible."}}},{"id":"P1_U3_MCQ_1197","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1197","question":"Household spending on pet care in one district rose from $15 million to $18 million over two years. By what percentage did the pet care market grow?","options":{"A":"12%","B":"20%","C":"17%","D":"83%"},"correctOption":"B","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"The market grew by $3 million, and $3 million divided by the original $15 million equals 0.20, which is a 20% increase in pet care spending.","distractor_reasons":{"A":"This would follow from a $1.8 million increase, not the $3 million growth stated in the scenario.","B":"The market grew by $3 million, and $3 million divided by the original $15 million equals 0.20, which is a 20% increase in pet care spending.","C":"This divides the $3 million increase by a base of about $18 million rather than the original $15 million.","D":"This divides $15 million by $18 million, which measures the old level as a share of the new one, not growth."}}},{"id":"P1_U3_MCQ_1198","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1198","question":"A trainee at Cranfield Pet Care is writing a staff guide that compares random and quota sampling methods before the firm surveys its customers. Which statement about quota sampling is correct?","options":{"A":"Interviewers choose respondents to fill pre-set group totals","B":"Every member of the population has an equal chance of selection","C":"It requires a complete list of the whole population","D":"It always produces secondary rather than primary data"},"correctOption":"A","correctAnswer":"Interviewers choose respondents to fill pre-set group totals","questionType":"MCQ","explanation":{"correct_reason":"Quota sampling sets a target number of respondents in each group, such as age band, and leaves interviewers to select suitable people until those totals are filled.","distractor_reasons":{"A":"Quota sampling sets a target number of respondents in each group, such as age band, and leaves interviewers to select suitable people until those totals are filled.","B":"Equal chances of selection are the feature of random sampling, whereas quota interviewers deliberately choose who to approach.","C":"A complete population list is needed for random sampling, but quota sampling works without one, for example in a shopping centre.","D":"Quota sampling gathers new answers straight from respondents, which makes it a primary research method."}}},{"id":"P1_U3_MCQ_1199","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1199","question":"Marden Interiors sells most of its sofas online but keeps one town-centre showroom. Customers say they still want to sit on a sofa and check the fabric before ordering. Why does the showroom remain valuable?","options":{"A":"It reduces the amount of stock the firm must hold","B":"It lets customers inspect quality and comfort before buying","C":"It removes all delivery costs from online orders","D":"It guarantees the firm can charge higher prices than rivals"},"correctOption":"B","correctAnswer":"It lets customers inspect quality and comfort before buying","questionType":"MCQ","explanation":{"correct_reason":"Sofas are high-involvement purchases where buyers want to test comfort and fabric, so a showroom supports the online sales by reducing uncertainty before ordering.","distractor_reasons":{"A":"A showroom normally requires display stock on top of warehouse stock, so it increases rather than reduces the stock the firm holds.","B":"Sofas are high-involvement purchases where buyers want to test comfort and fabric, so a showroom supports the online sales by reducing uncertainty before ordering.","C":"Online orders still need delivery to customers' homes, and running a showroom adds cost rather than removing it.","D":"Rivals may also run showrooms or charge less, so a showroom does not guarantee higher prices."}}},{"id":"P1_U3_MCQ_1200","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1200","question":"Waverton Foods sold 18,000 units before a new marketing campaign and 20,700 units afterwards, with no change in price or in the number of shops stocking the product. By what percentage did sales volume rise?","options":{"A":"2,700%","B":"13%","C":"20%","D":"15%"},"correctOption":"D","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Sales rose by 2,700 units, and 2,700 divided by the original 18,000 units equals 0.15, which is a 15% increase in sales volume.","distractor_reasons":{"A":"This repeats the 2,700 extra units as a percentage instead of dividing by the original 18,000 units.","B":"This divides 2,700 by 20,700, using the later sales figure rather than the original base of 18,000.","C":"A 20% rise would mean selling 21,600 units, which is 900 more than the 20,700 actually achieved.","D":"Sales rose by 2,700 units, and 2,700 divided by the original 18,000 units equals 0.15, which is a 15% increase in sales volume."}}},{"id":"P1_U3_MCQ_1201","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1201","question":"Crestmere Cycles Ltd sold 7,500 touring bicycles in 2025. The total number of touring bicycles sold in the whole national market that year was 125,000. What was Crestmere's market share?","options":{"A":"5.2%","B":"6.0%","C":"7.5%","D":"16.7%"},"correctOption":"B","correctAnswer":"6.0%","questionType":"MCQ","explanation":{"correct_reason":"Market share = 7,500 / 125,000 x 100 = 6.0%. Crestmere therefore supplied 6.0% of all touring bicycles sold in the national market in 2025.","distractor_reasons":{"A":"5.2% would result from dividing 6,500 by 125,000, but Crestmere actually sold 7,500 bicycles.","B":"Market share = 7,500 / 125,000 x 100 = 6.0%. Crestmere therefore supplied 6.0% of all touring bicycles sold in the national market in 2025.","C":"7.5% wrongly treats 7,500 as a share of 100,000 rather than of the stated 125,000 market.","D":"16.7% reverses the calculation (125,000 / 7,500) instead of measuring the firm's share of the market."}}},{"id":"P1_U3_MCQ_1202","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1202","question":"Wexcombe Foods has commissioned its own telephone survey of 500 shoppers to test reactions to a new sauce. No other firm has collected this data before. What type of research is this?","options":{"A":"Primary research","B":"Desk research","C":"Internal records research","D":"Secondary research"},"correctOption":"A","correctAnswer":"Primary research","questionType":"MCQ","explanation":{"correct_reason":"Primary research is data collected first-hand for the specific purpose, and Wexcombe's own 500-person survey fits that definition.","distractor_reasons":{"A":"Primary research is data collected first-hand for the specific purpose, and Wexcombe's own 500-person survey fits that definition.","B":"Desk research is another name for secondary research using existing sources, not a new survey.","C":"Internal records would be the firm's own sales or stock data, not fresh interviews with shoppers.","D":"Secondary research uses data already gathered by someone else, whereas this survey is new."}}},{"id":"P1_U3_MCQ_1203","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1203","question":"Sturgate Pottery makes mugs at a unit cost of $22. It uses cost-plus pricing with a mark-up of 35% on unit cost. What selling price does it set?","options":{"A":"$28.60","B":"$29.70","C":"$31.90","D":"$27.50"},"correctOption":"B","correctAnswer":"$29.70","questionType":"MCQ","explanation":{"correct_reason":"Selling price = $22 x 1.35 = $29.70, which is unit cost plus a 35% mark-up of $7.70.","distractor_reasons":{"A":"$28.60 would apply a 30% mark-up, giving $6.60 rather than $7.70.","B":"Selling price = $22 x 1.35 = $29.70, which is unit cost plus a 35% mark-up of $7.70.","C":"$31.90 would apply a 45% mark-up, which is above the stated rate.","D":"$27.50 would apply a 25% mark-up to $22, not the stated 35%."}}},{"id":"P1_U3_MCQ_1204","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1204","question":"Hollinswood Outdoors plans to target experienced climbers with technical jackets, sell through specialist stores and price above rivals. The owners want one clear document to guide next year's decisions. What is this plan called?","options":{"A":"A cash flow forecast","B":"A production schedule","C":"A staff appraisal plan","D":"A marketing strategy"},"correctOption":"D","correctAnswer":"A marketing strategy","questionType":"MCQ","explanation":{"correct_reason":"A marketing strategy sets a target market and coordinates product, place and price decisions to serve it, which is exactly what Hollinswood has planned.","distractor_reasons":{"A":"A cash flow forecast projects receipts and payments, not target customers or the marketing mix.","B":"A production schedule plans output timing and quantities rather than market positioning.","C":"Staff appraisal assesses employee performance and is unrelated to targeting climbers.","D":"A marketing strategy sets a target market and coordinates product, place and price decisions to serve it, which is exactly what Hollinswood has planned."}}},{"id":"P1_U3_MCQ_1205","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1205","question":"Harbottle Furnishings sold 4,200 oak dining chairs in 2025 at an average selling price of $36 per chair. What was the total sales revenue from these chairs?","options":{"A":"$126,000","B":"$151,200","C":"$145,800","D":"$158,400"},"correctOption":"B","correctAnswer":"$151,200","questionType":"MCQ","explanation":{"correct_reason":"Sales revenue = 4,200 chairs x $36 = $151,200 for the year.","distractor_reasons":{"A":"$126,000 is 4,200 x $30, using $30 rather than the stated $36 price.","B":"Sales revenue = 4,200 chairs x $36 = $151,200 for the year.","C":"$145,800 would arise if only 4,050 chairs were sold at $36, not the 4,200 stated.","D":"$158,400 would require 4,400 chairs at $36, which is 200 more than were sold."}}},{"id":"P1_U3_MCQ_1206","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1206","question":"Kingscote Research charges $36 for each completed interview. A client has a research budget of $7,200. The agency works on a fixed fee per finished interview. How many completed interviews can the client afford?","options":{"A":"240","B":"180","C":"200","D":"216"},"correctOption":"C","correctAnswer":"200","questionType":"MCQ","explanation":{"correct_reason":"$7,200 / $36 per interview = 200 completed interviews.","distractor_reasons":{"A":"240 interviews would cost $8,640, well beyond the available budget.","B":"180 interviews would cost $6,480, leaving $720 of the budget unused.","C":"$7,200 / $36 per interview = 200 completed interviews.","D":"216 interviews would cost $7,776, which exceeds the $7,200 budget."}}},{"id":"P1_U3_MCQ_1207","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1207","question":"Sedgebrook Foods spends $72,000 on a television campaign for its new soup and expects to sell 18,000 tins during the campaign. What is the promotional cost per tin?","options":{"A":"$5.00","B":"$3.50","C":"$4.00","D":"$4.50"},"correctOption":"C","correctAnswer":"$4.00","questionType":"MCQ","explanation":{"correct_reason":"Promotional cost per unit = $72,000 / 18,000 tins = $4.00 per tin.","distractor_reasons":{"A":"$5.00 per tin would imply 14,400 tins at the stated budget.","B":"$3.50 per tin would imply 20,571 tins, more than the number expected.","C":"Promotional cost per unit = $72,000 / 18,000 tins = $4.00 per tin.","D":"$4.50 per tin would imply only 16,000 tins, fewer than expected."}}},{"id":"P1_U3_MCQ_1208","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1208","question":"Wrenbury Publishing earns revenue of $2.5 million and spends $150,000 on marketing. The publisher sells educational books to schools and colleges across the region. What percentage of revenue is its marketing budget?","options":{"A":"6%","B":"7.5%","C":"8%","D":"5%"},"correctOption":"A","correctAnswer":"6%","questionType":"MCQ","explanation":{"correct_reason":"Marketing budget percentage = $150,000 / $2,500,000 x 100 = 6.0%.","distractor_reasons":{"A":"Marketing budget percentage = $150,000 / $2,500,000 x 100 = 6.0%.","B":"7.5% would mean $187,500, well above the $150,000 spent.","C":"8% would mean $200,000, which is $50,000 more than the actual budget.","D":"5% would mean a budget of $125,000, which is $25,000 less."}}},{"id":"P1_U3_MCQ_1209","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1209","question":"Analysts at Dunthorpe Market Reports track the regional outdoor furniture market. Its value was $320,000 in 2024 and $352,000 in 2025. By what percentage did the market grow?","options":{"A":"32%","B":"8%","C":"9%","D":"10%"},"correctOption":"D","correctAnswer":"10%","questionType":"MCQ","explanation":{"correct_reason":"Market growth = ($352,000 - $320,000) / $320,000 x 100 = $32,000 / $320,000 x 100 = 10%.","distractor_reasons":{"A":"32% treats the $32,000 cash increase as a percentage, ignoring the $320,000 base entirely.","B":"8% would follow from a $25,600 increase, not the $32,000 rise shown in the figures.","C":"9% comes from dividing the $32,000 increase by $352,000 instead of by the 2024 base.","D":"Market growth = ($352,000 - $320,000) / $320,000 x 100 = $32,000 / $320,000 x 100 = 10%."}}},{"id":"P1_U3_MCQ_1210","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1210","question":"Morcott Leisure wants to survey 250 of its 5,000 members. It uses a computer to pick 250 members purely by chance from the full membership list. Which sampling method is this?","options":{"A":"Random sampling","B":"Market segmentation","C":"Test marketing","D":"Quota sampling"},"correctOption":"A","correctAnswer":"Random sampling","questionType":"MCQ","explanation":{"correct_reason":"Random sampling gives every member an equal chance of selection, which is exactly what a computer drawing 250 names by chance achieves.","distractor_reasons":{"A":"Random sampling gives every member an equal chance of selection, which is exactly what a computer drawing 250 names by chance achieves.","B":"Market segmentation divides customers into groups; it is not a selection procedure for a survey.","C":"Test marketing trials a product in a limited area rather than selecting survey respondents.","D":"Quota sampling fills preset numbers from chosen groups and relies on interviewer judgement, not pure chance."}}},{"id":"P1_U3_MCQ_1211","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1211","question":"Customers across three countries recognise Ravensbourne Outdoor's green triangle logo and pay more for its jackets than for unbranded equivalents. What does the logo represent?","options":{"A":"A wholesaler's distribution mark","B":"A government safety certificate","C":"A strong brand that supports premium pricing","D":"A loss leader used to clear stock"},"correctOption":"C","correctAnswer":"A strong brand that supports premium pricing","questionType":"MCQ","explanation":{"correct_reason":"A recognised logo linked to consistent quality builds brand identity, and that recognition allows the firm to charge more than unbranded rivals.","distractor_reasons":{"A":"A distribution mark identifies a logistics intermediary, not the manufacturer's own identity.","B":"Safety certificates are regulatory labels, not brand symbols that command a premium.","C":"A recognised logo linked to consistent quality builds brand identity, and that recognition allows the firm to charge more than unbranded rivals.","D":"A loss leader is sold below cost to draw buyers, whereas these jackets sell at a premium."}}},{"id":"P1_U3_MCQ_1212","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1212","question":"Coldharbour Travel decides to focus its advertising on couples aged 25-40 with no children, who book short city breaks. Managers believe this group offers the best fit with their weekend packages. What marketing activity is this?","options":{"A":"Withdrawing from the holiday market","B":"Segmenting the market and targeting one group","C":"Measuring the total size of every market","D":"Reducing production costs through scale"},"correctOption":"B","correctAnswer":"Segmenting the market and targeting one group","questionType":"MCQ","explanation":{"correct_reason":"The firm has divided the holiday market into groups and chosen one segment, couples aged 25-40, as the target for its advertising.","distractor_reasons":{"A":"The firm is focusing its effort on one group, not leaving the market.","B":"The firm has divided the holiday market into groups and chosen one segment, couples aged 25-40, as the target for its advertising.","C":"It is selecting a group to serve, not calculating the size of all markets.","D":"Production cost reductions come from operational decisions, not from choosing a customer group."}}},{"id":"P1_U3_MCQ_1213","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1213","question":"Wenlock Garden Furniture has 3,000 customers who each buy at least twice a year and rarely switch to rivals. Why does this customer loyalty benefit the business?","options":{"A":"It lowers the cost of winning each sale and gives a more predictable revenue stream.","B":"It removes the need to monitor competitors' prices.","C":"It guarantees that the business can raise prices without losing sales.","D":"It means the business no longer needs to advertise at all."},"correctOption":"A","correctAnswer":"It lowers the cost of winning each sale and gives a more predictable revenue stream.","questionType":"MCQ","explanation":{"correct_reason":"Loyal repeat customers cost less to keep than new customers cost to win, and their regular orders make revenue easier to forecast.","distractor_reasons":{"A":"Loyal repeat customers cost less to keep than new customers cost to win, and their regular orders make revenue easier to forecast.","B":"Loyalty reduces but does not remove competitive pressure, so rival prices still need monitoring.","C":"Some loyal customers tolerate small increases, but loyalty alone cannot guarantee sales at any price.","D":"Even loyal customers need reminding and persuading, so some promotion remains necessary."}}},{"id":"P1_U3_MCQ_1214","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1214","question":"Before printing 40,000 questionnaires, Hoyland Drinks asks 45 shoppers to complete the draft and explain any confusing questions. The drinks firm wants reliable answers before committing to a national launch. Why is this pilot test useful?","options":{"A":"It checks that questions are clear before the full survey is printed.","B":"It replaces the need for any sample in the main survey.","C":"It guarantees the full survey will have a 100% response rate.","D":"It provides the final results for the whole market."},"correctOption":"A","correctAnswer":"It checks that questions are clear before the full survey is printed.","questionType":"MCQ","explanation":{"correct_reason":"A pilot test exposes ambiguous or misleading questions on a small group so the wording can be corrected before the costly full print run.","distractor_reasons":{"A":"A pilot test exposes ambiguous or misleading questions on a small group so the wording can be corrected before the costly full print run.","B":"The main survey still needs its own representative sample; a pilot is only a trial.","C":"Piloting improves wording but cannot guarantee that everyone will respond.","D":"Forty-five shoppers are too few to represent the whole market, so results are only indicative."}}},{"id":"P1_U3_MCQ_1215","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1215","question":"Hazelbury Cosmetics packs its serum in an airtight pump bottle that protects the formula, lists ingredients clearly and displays the brand prominently. Which set of functions does the packaging perform?","options":{"A":"Production, pricing and place","B":"Recruitment, training and appraisal","C":"Storage, insurance and audit","D":"Protection, information and promotion"},"correctOption":"D","correctAnswer":"Protection, information and promotion","questionType":"MCQ","explanation":{"correct_reason":"The airtight bottle protects the product, the ingredient list informs buyers and the prominent branding promotes it, covering all three packaging functions.","distractor_reasons":{"A":"Production, pricing and place are separate marketing decisions, not functions of a bottle.","B":"Recruitment, training and appraisal are human resource activities.","C":"Storage and audit relate to operations and finance, not to consumer packaging.","D":"The airtight bottle protects the product, the ingredient list informs buyers and the prominent branding promotes it, covering all three packaging functions."}}},{"id":"P1_U3_MCQ_1216","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1216","question":"Ashby Vale Hotels refurbishes its rooms, trains staff in personal service and charges $240 a night, well above local rivals. What is the hotel doing?","options":{"A":"Using a loss leader to sell restaurant meals","B":"Reducing its service level to cut prices","C":"Positioning itself as a premium brand in the minds of wealthy travellers","D":"Selling below cost to win budget travellers"},"correctOption":"C","correctAnswer":"Positioning itself as a premium brand in the minds of wealthy travellers","questionType":"MCQ","explanation":{"correct_reason":"High-quality refurbishment, trained service and a price above rivals together create a premium position that targets wealthier guests.","distractor_reasons":{"A":"The investment is in rooms and service, not a cheap restaurant offer to draw shoppers.","B":"Service is being improved rather than reduced, and prices are above rivals rather than cut.","C":"High-quality refurbishment, trained service and a price above rivals together create a premium position that targets wealthier guests.","D":"A $240 rate above local rivals is not below-cost selling."}}},{"id":"P1_U3_MCQ_1217","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1217","question":"Pemberton Harps makes hand-built concert harps for professional musicians. It serves a small group of buyers who pay very high prices for craftsmanship. What type of market is Pemberton serving?","options":{"A":"An export market","B":"A mass market","C":"A niche market","D":"A commodity market"},"correctOption":"C","correctAnswer":"A niche market","questionType":"MCQ","explanation":{"correct_reason":"A niche market is a small, specialised segment with distinctive needs; hand-built harps for professional players fit this description and support premium prices.","distractor_reasons":{"A":"Selling to foreign buyers may happen, but exporting is a channel choice, not the small specialist segment described.","B":"A mass market sells standard products to very large numbers of buyers, which is the opposite of hand-built harps.","C":"A niche market is a small, specialised segment with distinctive needs; hand-built harps for professional players fit this description and support premium prices.","D":"A commodity market deals in undifferentiated basics such as wheat or copper, not crafted musical instruments."}}},{"id":"P1_U3_MCQ_1218","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1218","question":"Clevedon Bakery surveys 640 of its 16,000 customers about a new sourdough line. The bakery wants to know how far its customer base reflects the town's shoppers. What percentage of its customers is being surveyed?","options":{"A":"6.4%","B":"3.2%","C":"4.0%","D":"4.5%"},"correctOption":"C","correctAnswer":"4.0%","questionType":"MCQ","explanation":{"correct_reason":"Sample percentage = 640 / 16,000 x 100 = 4.0% of customers.","distractor_reasons":{"A":"6.4% reverses the figures, treating 16,000 as a share of 640 rather than the reverse.","B":"3.2% would mean only 512 customers were surveyed.","C":"Sample percentage = 640 / 16,000 x 100 = 4.0% of customers.","D":"4.5% would mean 720 customers, which is 80 more than were selected."}}},{"id":"P1_U3_MCQ_1219","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1219","question":"Sales of Cresswell Radio's clock radios have fallen for four straight years as buyers switch to smartphone alarms. What stage of the product life cycle is this, and what is a sensible response?","options":{"A":"Decline; consider updating the product or withdrawing it.","B":"Introduction; increase the launch price.","C":"Growth; build extra factory capacity.","D":"Maturity; cut all promotion immediately."},"correctOption":"A","correctAnswer":"Decline; consider updating the product or withdrawing it.","questionType":"MCQ","explanation":{"correct_reason":"Four years of falling sales caused by substitute products indicate decline, so the firm should either refresh the product or plan a withdrawal.","distractor_reasons":{"A":"Four years of falling sales caused by substitute products indicate decline, so the firm should either refresh the product or plan a withdrawal.","B":"Introduction is when sales begin from a low base and grow, not when they fall steadily.","C":"Growth would require rising sales and extra capacity, the opposite of this case.","D":"Maturity is a plateau, not a sustained four-year fall, and promotion is still used at that stage."}}},{"id":"P1_U3_MCQ_1220","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1220","question":"Penborough Sofas uses a modular frame that lets buyers rearrange the sections, a feature no rival offers. Why does this matter for its marketing strategy?","options":{"A":"It allows the firm to ignore customer needs.","B":"It guarantees the firm will become the market leader.","C":"It differentiates the product, giving customers a reason to choose Penborough over rivals.","D":"It lowers the firm's fixed costs automatically."},"correctOption":"C","correctAnswer":"It differentiates the product, giving customers a reason to choose Penborough over rivals.","questionType":"MCQ","explanation":{"correct_reason":"A feature no rival offers is a point of differentiation, giving buyers a specific reason to prefer Penborough's sofas.","distractor_reasons":{"A":"Differentiation must still satisfy customer needs to be valuable.","B":"One distinctive feature helps but cannot guarantee market leadership.","C":"A feature no rival offers is a point of differentiation, giving buyers a specific reason to prefer Penborough's sofas.","D":"A modular frame may raise design and production costs rather than lower fixed costs."}}},{"id":"P1_U3_MCQ_1221","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1221","question":"Dalbeattie Soft Drinks earned $840,000 of revenue in a regional drinks market worth $14 million. The figure covers all soft drinks sold by manufacturers in the region last year. What was its market share by revenue?","options":{"A":"5%","B":"6%","C":"8%","D":"16.7%"},"correctOption":"B","correctAnswer":"6%","questionType":"MCQ","explanation":{"correct_reason":"$840,000 / $14,000,000 x 100 = 6.0%, so Dalbeattie supplied 6% of the market's revenue.","distractor_reasons":{"A":"5% would require revenue of $700,000, which is $140,000 less than was reported.","B":"$840,000 / $14,000,000 x 100 = 6.0%, so Dalbeattie supplied 6% of the market's revenue.","C":"8% would require $1.12 million of revenue, well above the $840,000 actually earned.","D":"16.7% is $14 million divided by $840,000, which inverts the correct calculation."}}},{"id":"P1_U3_MCQ_1222","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1222","question":"Ridgewell Holidays gives guests a card with six fixed statements and boxes from 'very satisfied' to 'very dissatisfied'. The holiday company wants to compare satisfaction levels across its hotels. Why is this closed-question format useful?","options":{"A":"It removes the need to choose a sample.","B":"It produces answers that are easy to compare and count.","C":"It lets each guest write long personal stories.","D":"It removes all possible bias from the survey."},"correctOption":"B","correctAnswer":"It produces answers that are easy to compare and count.","questionType":"MCQ","explanation":{"correct_reason":"Closed questions offer fixed response choices, so the results can be scored, counted and compared across many respondents quickly.","distractor_reasons":{"A":"A sample is still needed; the question format does not decide who is surveyed.","B":"Closed questions offer fixed response choices, so the results can be scored, counted and compared across many respondents quickly.","C":"Long personal stories come from open questions, not from fixed response boxes.","D":"Closed questions reduce analysis effort but can still be biased by the choice of statements."}}},{"id":"P1_U3_MCQ_1223","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1223","question":"Barrowclough Engineering makes 6,000 brackets a year. Fixed costs are $18,000, variable cost is $4 per bracket and the firm adds a 20% mark-up on total unit cost. What price does it set?","options":{"A":"$8.40","B":"$9.20","C":"$7.00","D":"$8.00"},"correctOption":"A","correctAnswer":"$8.40","questionType":"MCQ","explanation":{"correct_reason":"Total cost = $18,000 + (6,000 x $4) = $42,000; unit cost = $42,000 / 6,000 = $7.00; price = $7.00 x 1.20 = $8.40.","distractor_reasons":{"A":"Total cost = $18,000 + (6,000 x $4) = $42,000; unit cost = $42,000 / 6,000 = $7.00; price = $7.00 x 1.20 = $8.40.","B":"$9.20 would apply a mark-up of $2.20, which is 31.4% of cost.","C":"$7.00 is the average unit cost before any mark-up is added.","D":"$8.00 would apply a mark-up of about 14.3%, not the stated 20%."}}},{"id":"P1_U3_MCQ_1224","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1224","question":"A campaign run by Fenwyck Cycles costs $84,000. Each extra unit sold earns $12 of profit. How many additional units must be sold for the campaign to cover its cost?","options":{"A":"6,500","B":"7,000","C":"7,500","D":"6,000"},"correctOption":"B","correctAnswer":"7,000","questionType":"MCQ","explanation":{"correct_reason":"Units needed = $84,000 / $12 profit per unit = 7,000 additional units to cover the campaign cost.","distractor_reasons":{"A":"6,500 units would recover $78,000, still $6,000 short.","B":"Units needed = $84,000 / $12 profit per unit = 7,000 additional units to cover the campaign cost.","C":"7,500 units would recover $90,000, exceeding the cost by $6,000.","D":"6,000 units would recover only $72,000 of the $84,000 cost."}}},{"id":"P1_U3_MCQ_1225","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1225","question":"Cavendish Paper Mills produces standard copy paper in very large volumes and sells it to offices across the country at modest prices. What is the main advantage of serving this mass market?","options":{"A":"It removes the need for any distribution network.","B":"Higher output spreads fixed costs over more units, lowering average cost.","C":"Each customer is willing to pay a unique bespoke price.","D":"It avoids all competition because the product is standardised."},"correctOption":"B","correctAnswer":"Higher output spreads fixed costs over more units, lowering average cost.","questionType":"MCQ","explanation":{"correct_reason":"Selling to a mass market raises output, so fixed costs such as machinery are spread across many units and average unit cost falls.","distractor_reasons":{"A":"A mass market still needs wide distribution to reach many scattered office buyers.","B":"Selling to a mass market raises output, so fixed costs such as machinery are spread across many units and average unit cost falls.","C":"Mass-market buyers pay standard prices; bespoke pricing belongs to niche, customised products.","D":"Standardised products face heavy competition from similar suppliers, not immunity from it."}}},{"id":"P1_U3_MCQ_1226","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1226","question":"Fennimore Kitchens asks shoppers: 'What would make you buy more of our ready-meals?' and leaves space for a written answer. What is the main advantage of this open question?","options":{"A":"It makes the sample statistically representative.","B":"It gives detailed reasons and ideas that fixed options might miss.","C":"It produces figures that can be averaged instantly.","D":"It guarantees every respondent answers in the same way."},"correctOption":"B","correctAnswer":"It gives detailed reasons and ideas that fixed options might miss.","questionType":"MCQ","explanation":{"correct_reason":"Open questions let respondents explain their own reasons in their own words, which can reveal unexpected issues and ideas.","distractor_reasons":{"A":"Representativeness depends on how the sample is chosen, not on the question type.","B":"Open questions let respondents explain their own reasons in their own words, which can reveal unexpected issues and ideas.","C":"Written comments are hard to convert into averages without coding, unlike closed options.","D":"Open answers vary widely, so consistency is their weakness rather than their strength."}}},{"id":"P1_U3_MCQ_1227","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1227","question":"Halstead Audio launches a new high-end headphone at $420, aiming at enthusiasts who want it first, and plans to lower the price later. Which pricing strategy is this?","options":{"A":"Price skimming","B":"Penetration pricing","C":"Loss-leader pricing","D":"Competitive pricing"},"correctOption":"A","correctAnswer":"Price skimming","questionType":"MCQ","explanation":{"correct_reason":"Price skimming sets a high launch price to capture buyers willing to pay most, then reduces the price later to reach more price-sensitive customers.","distractor_reasons":{"A":"Price skimming sets a high launch price to capture buyers willing to pay most, then reduces the price later to reach more price-sensitive customers.","B":"Penetration pricing does the opposite, starting low to win volume quickly.","C":"A loss leader is sold below cost to attract shoppers into a store.","D":"Competitive pricing matches rivals' prices rather than starting high and falling."}}},{"id":"P1_U3_MCQ_1228","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1228","question":"Palgrave Skincare advertises that its cream 'removes all wrinkles permanently within 24 hours', although it holds no evidence. The advert appears on national television and in magazines. Which legal control has it broken?","options":{"A":"Laws requiring all products to carry a five-year guarantee","B":"Rules limiting the number of retail outlets in a town","C":"Consumer protection rules against false and misleading advertising","D":"Weights and measures rules on package sizes"},"correctOption":"C","correctAnswer":"Consumer protection rules against false and misleading advertising","questionType":"MCQ","explanation":{"correct_reason":"Claims that cannot be substantiated deceive buyers, which breaches consumer protection law on false and misleading advertising.","distractor_reasons":{"A":"No general law requires five-year guarantees on cosmetics.","B":"Planning rules on outlet numbers do not govern advertising content.","C":"Claims that cannot be substantiated deceive buyers, which breaches consumer protection law on false and misleading advertising.","D":"Weights and measures concern the quantity stated on a package, not efficacy claims."}}},{"id":"P1_U3_MCQ_1229","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1229","question":"Tarnbrook Cinemas attracted 18,000 customers last year and earned total ticket and snack revenue of $1,440,000. The cinema chain wants to compare spending across its other sites. What was the average revenue per customer?","options":{"A":"$72","B":"$80","C":"$84","D":"$90"},"correctOption":"B","correctAnswer":"$80","questionType":"MCQ","explanation":{"correct_reason":"$1,440,000 / 18,000 customers = $80 of average revenue per customer.","distractor_reasons":{"A":"$72 would result from dividing $1,440,000 by 20,000 customers, not by the 18,000 recorded.","B":"$1,440,000 / 18,000 customers = $80 of average revenue per customer.","C":"$84 would require revenue of $1,512,000 at the stated 18,000 customers.","D":"$90 would require revenue of $1,620,000 from 18,000 customers."}}},{"id":"P1_U3_MCQ_1230","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1230","question":"Bexley Rail sends 900 questionnaires to passengers who travelled in March and receives 558 back. The operator wants to judge satisfaction with its new timetable. What was the response rate?","options":{"A":"55%","B":"58%","C":"62%","D":"64%"},"correctOption":"C","correctAnswer":"62%","questionType":"MCQ","explanation":{"correct_reason":"Response rate = 558 / 900 x 100 = 62% of questionnaires returned.","distractor_reasons":{"A":"55% would mean 495 returns, which is 63 fewer than were received.","B":"58% would mean 522 returns, below the 558 actually returned.","C":"Response rate = 558 / 900 x 100 = 62% of questionnaires returned.","D":"64% would mean 576 returns, above the number actually received."}}},{"id":"P1_U3_MCQ_1231","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1231","question":"Stanmore Home launches its new cleaning spray at $1.50 when rivals charge $3.20, aiming to win shelf space and trial quickly. Which pricing strategy is this?","options":{"A":"Price skimming","B":"Cost-plus pricing","C":"Price discrimination","D":"Penetration pricing"},"correctOption":"D","correctAnswer":"Penetration pricing","questionType":"MCQ","explanation":{"correct_reason":"Penetration pricing sets a low launch price to attract trial and build market share rapidly before the price is adjusted.","distractor_reasons":{"A":"Price skimming starts high to exploit early adopters, the reverse of this low launch price.","B":"Cost-plus pricing is based on adding a mark-up to unit cost, with no reference to rivals.","C":"Price discrimination charges different prices to different groups for the same product, which is not described here.","D":"Penetration pricing sets a low launch price to attract trial and build market share rapidly before the price is adjusted."}}},{"id":"P1_U3_MCQ_1232","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1232","question":"Rothbury Preserves labels its jars '340g' but fills them to only 300g. The preserves are sold in supermarkets across the county. Which consumer protection rule does this breach?","options":{"A":"Weights and measures rules requiring the stated net quantity to be accurate","B":"Advertising rules banning all price comparisons","C":"Employment rules on the minimum wage","D":"Rules requiring every jar to be sold through a wholesaler"},"correctOption":"A","correctAnswer":"Weights and measures rules requiring the stated net quantity to be accurate","questionType":"MCQ","explanation":{"correct_reason":"Weights and measures law requires packages to contain the net quantity stated, so selling 300g as 340g is short-weighting and illegal.","distractor_reasons":{"A":"Weights and measures law requires packages to contain the net quantity stated, so selling 300g as 340g is short-weighting and illegal.","B":"The issue is quantity, not a price comparison claim.","C":"Minimum wage rules concern pay, not the contents of jars.","D":"No law forces a preserves maker to use a wholesaler."}}},{"id":"P1_U3_MCQ_1233","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1233","question":"Millgate Bakery faces two new rivals on its street; all three now cut prices, extend opening hours and improve freshness to win trade. How do customers benefit from this competition?","options":{"A":"They are served by a single supplier controlling the street.","B":"They lose access to fresh bread in the area.","C":"They get lower prices, more choice and better service.","D":"They face higher prices and fewer products."},"correctOption":"C","correctAnswer":"They get lower prices, more choice and better service.","questionType":"MCQ","explanation":{"correct_reason":"Rivalry between the three bakeries pushes each to offer better value, wider choice and improved service, which benefits local customers.","distractor_reasons":{"A":"Three competing shops exist, so no single supplier controls the street.","B":"Improving freshness is part of the competitive response, so fresh bread remains available.","C":"Rivalry between the three bakeries pushes each to offer better value, wider choice and improved service, which benefits local customers.","D":"Competition pushes prices down and ranges up, rather than creating higher prices and fewer products."}}},{"id":"P1_U3_MCQ_1234","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1234","question":"Before opening a cafe, Salterton Catering studies published census data on local incomes and household numbers. What is an advantage of using this existing published data?","options":{"A":"It is always more current than newly collected data.","B":"It is tailored exactly to the cafe's own questions.","C":"It guarantees that the cafe will be profitable.","D":"It is quick and cheap because the information has already been collected."},"correctOption":"D","correctAnswer":"It is quick and cheap because the information has already been collected.","questionType":"MCQ","explanation":{"correct_reason":"Published data is secondary research, already gathered by another body, so it can be obtained quickly and at little cost.","distractor_reasons":{"A":"Census data is usually collected periodically and may be several years old, so it is not necessarily more current.","B":"Existing data was collected for another purpose and may not answer the cafe's specific questions.","C":"Market data informs decisions but cannot guarantee profitability.","D":"Published data is secondary research, already gathered by another body, so it can be obtained quickly and at little cost."}}},{"id":"P1_U3_MCQ_1235","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1235","question":"Millbrook Theatre sells 6,000 tickets for a comedy night at $32 each. It then offers a 25% discount on every ticket. What ticket revenue does it receive?","options":{"A":"$150,000","B":"$132,000","C":"$138,000","D":"$144,000"},"correctOption":"D","correctAnswer":"$144,000","questionType":"MCQ","explanation":{"correct_reason":"Full-price revenue would be 6,000 x $32 = $192,000; a 25% discount leaves 75%, so revenue = $192,000 x 0.75 = $144,000.","distractor_reasons":{"A":"$150,000 would follow from a 21.9% discount, below the stated 25%.","B":"$132,000 would follow from a 31.25% discount, which is more than the offer.","C":"$138,000 would follow from a 28.1% discount, above the stated 25%.","D":"Full-price revenue would be 6,000 x $32 = $192,000; a 25% discount leaves 75%, so revenue = $192,000 x 0.75 = $144,000."}}},{"id":"P1_U3_MCQ_1236","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1236","question":"Harlowgate Footwear appoints an overseas distributor that takes a 15% commission on sales. Overseas sales are expected to reach $620,000. What commission will the distributor receive?","options":{"A":"$86,800","B":"$93,000","C":"$99,200","D":"$78,000"},"correctOption":"B","correctAnswer":"$93,000","questionType":"MCQ","explanation":{"correct_reason":"Commission = 15% of $620,000 = 0.15 x $620,000 = $93,000.","distractor_reasons":{"A":"$86,800 would be a 14% commission, not the stated 15%.","B":"Commission = 15% of $620,000 = 0.15 x $620,000 = $93,000.","C":"$99,200 would be a 16% commission, above the agreed rate.","D":"$78,000 would be 12.58% of sales, below the agreed rate."}}},{"id":"P1_U3_MCQ_1237","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1237","question":"Ramsgill Hardware's main rival has cut prices on power tools by 12%. Ramsgill's costs are already close to its rival's, so it cannot profitably match the cut. Which response is most appropriate?","options":{"A":"Match the cut immediately and accept losses on every drill.","B":"Emphasise longer guarantees, expert advice and fast repairs to justify its price.","C":"Stop selling power tools and leave the market entirely.","D":"Raise prices by 12% to show that its tools are superior."},"correctOption":"B","correctAnswer":"Emphasise longer guarantees, expert advice and fast repairs to justify its price.","questionType":"MCQ","explanation":{"correct_reason":"When price matching would destroy margins, non-price competition through service, expert advice and guarantees can persuade customers to stay and pay more.","distractor_reasons":{"A":"Matching a cut that cannot be funded would turn profitable sales into losses on each drill.","B":"When price matching would destroy margins, non-price competition through service, expert advice and guarantees can persuade customers to stay and pay more.","C":"Withdrawing completely sacrifices an established product line and hands the market to the rival.","D":"A matching 12% rise invites further customer loss without evidence that its tools are superior."}}},{"id":"P1_U3_MCQ_1238","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1238","question":"A researcher working for Wyndham Coffee asks: 'Don't you agree that our wonderful new coffee is far better than the bitter blends sold elsewhere?' What problem does this question create?","options":{"A":"It is a leading question that pushes respondents towards a favourable answer.","B":"It is too short for respondents to understand.","C":"It collects only numerical data.","D":"It uses a sample that is too large."},"correctOption":"A","correctAnswer":"It is a leading question that pushes respondents towards a favourable answer.","questionType":"MCQ","explanation":{"correct_reason":"Loaded words such as 'wonderful' and 'bitter' steer respondents, so the results will be biased towards agreeing with the firm.","distractor_reasons":{"A":"Loaded words such as 'wonderful' and 'bitter' steer respondents, so the results will be biased towards agreeing with the firm.","B":"Length is not the issue; the wording itself suggests the desired answer.","C":"The question invites opinions expressed in words, not numerical measurements.","D":"No sample size is given, and the wording flaw exists regardless of sample size."}}},{"id":"P1_U3_MCQ_1239","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1239","question":"Grangehurst Supermarket sells milk at $0.80 a litre, below its cost of $1.05, because shoppers who come for milk usually buy bread, fruit and other profitable items. What pricing tactic is this?","options":{"A":"A loss leader","B":"Price skimming","C":"Dynamic pricing","D":"A cost-plus price"},"correctOption":"A","correctAnswer":"A loss leader","questionType":"MCQ","explanation":{"correct_reason":"A loss leader is deliberately priced below cost to draw customers in, with profit earned on the other items they buy.","distractor_reasons":{"A":"A loss leader is deliberately priced below cost to draw customers in, with profit earned on the other items they buy.","B":"Price skimming sets a high launch price, not a below-cost staple.","C":"Dynamic pricing varies prices with live demand rather than deliberately sustaining a loss.","D":"Cost-plus pricing adds a mark-up above cost, so it could not produce a price below $1.05."}}},{"id":"P1_U3_MCQ_1240","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1240","question":"Caldermoor Appliances finds that almost every household in its home country already owns its washing machine, so sales barely grow. Why might it enter a foreign market?","options":{"A":"To escape competition, because foreign markets have no rivals","B":"To reduce its product range to a single model","C":"To avoid all transport and tariff costs","D":"To find new customers and renew growth beyond a saturated home market"},"correctOption":"D","correctAnswer":"To find new customers and renew growth beyond a saturated home market","questionType":"MCQ","explanation":{"correct_reason":"A saturated home market offers little room for growth, so entering a foreign market can reach new buyers and raise sales.","distractor_reasons":{"A":"Foreign markets also contain competitors, so entry does not escape competition.","B":"Market entry usually requires adapting or extending the range, not narrowing it.","C":"Selling abroad adds transport, tariff and administration costs rather than avoiding them.","D":"A saturated home market offers little room for growth, so entering a foreign market can reach new buyers and raise sales."}}},{"id":"P1_U3_MCQ_1241","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1241","question":"Oakhanger Sailmakers sold 18,000 boat covers, which represented exactly 12% of all boat covers sold in its market. What was the total size of the market in units?","options":{"A":"216,000","B":"144,000","C":"150,000","D":"180,000"},"correctOption":"C","correctAnswer":"150,000","questionType":"MCQ","explanation":{"correct_reason":"If 18,000 units are 12% of the market, total market = 18,000 / 0.12 = 150,000 units.","distractor_reasons":{"A":"216,000 comes from multiplying 18,000 by 12 instead of dividing by 0.12.","B":"144,000 would apply if 18,000 were 12.5% of the market, not the stated 12%.","C":"If 18,000 units are 12% of the market, total market = 18,000 / 0.12 = 150,000 units.","D":"180,000 would result from treating 18,000 as 10% of the market."}}},{"id":"P1_U3_MCQ_1242","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1242","question":"In a survey of 240 households, 36 said they would buy Farlow Dairies' new doorstep milk service. Farlow plans to launch in a town with 8,000 households. Assuming the sample is representative, how many households would buy?","options":{"A":"960","B":"1,080","C":"1,200","D":"1,440"},"correctOption":"C","correctAnswer":"1,200","questionType":"MCQ","explanation":{"correct_reason":"36 / 240 = 15% of sampled households; 15% of 8,000 households = 1,200 households.","distractor_reasons":{"A":"960 would represent 12% of 8,000, not the 15% found in the sample.","B":"1,080 would represent 13.5% of 8,000 households.","C":"36 / 240 = 15% of sampled households; 15% of 8,000 households = 1,200 households.","D":"1,440 would represent 18% of households, above the survey proportion."}}},{"id":"P1_U3_MCQ_1243","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1243","question":"Dunthorpe Tyres sells a standard tyre at $58, the same price as three rival garages nearby, because drivers compare prices easily. Which pricing method is this?","options":{"A":"Price skimming","B":"Penetration pricing","C":"Premium pricing","D":"Competitive pricing"},"correctOption":"D","correctAnswer":"Competitive pricing","questionType":"MCQ","explanation":{"correct_reason":"Competitive pricing sets a price in line with close rivals in a market where buyers compare offers easily, which suits standard tyres.","distractor_reasons":{"A":"Price skimming sets a high introductory price for an innovative product.","B":"Penetration pricing undercuts rivals sharply at launch to build share.","C":"Premium pricing sets a high price to signal exclusivity, not to match rivals.","D":"Competitive pricing sets a price in line with close rivals in a market where buyers compare offers easily, which suits standard tyres."}}},{"id":"P1_U3_MCQ_1244","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1244","question":"A global burger chain keeps its name and logo everywhere but adds a halal-certified range in Middle Eastern markets. Why does it adapt the product in this way?","options":{"A":"To standardise every menu worldwide without change","B":"To raise prices above all local competitors","C":"To avoid conducting any local market research","D":"To respect local religious dietary rules and increase customer acceptance"},"correctOption":"D","correctAnswer":"To respect local religious dietary rules and increase customer acceptance","questionType":"MCQ","explanation":{"correct_reason":"Adapting the menu to local religious requirements makes the brand acceptable to local consumers while the global identity is retained.","distractor_reasons":{"A":"The chain is adapting rather than standardising its menu in that region.","B":"The purpose is acceptability, not charging more than every local rival.","C":"Understanding local dietary rules requires research and local knowledge, not avoiding it.","D":"Adapting the menu to local religious requirements makes the brand acceptable to local consumers while the global identity is retained."}}},{"id":"P1_U3_MCQ_1245","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1245","question":"Over three years, customers of Melbury Food Hall have shifted from white bread towards sourdough and seeded loaves. Which action best reflects a market-oriented response?","options":{"A":"Adjust the product range and shelf space to match the new buying patterns.","B":"Reduce the number of bakery staff to cut costs regardless of demand.","C":"Advertise that white bread is healthier than sourdough.","D":"Keep the same bread range because it sold well five years ago."},"correctOption":"A","correctAnswer":"Adjust the product range and shelf space to match the new buying patterns.","questionType":"MCQ","explanation":{"correct_reason":"A market-oriented business responds to evidence of changing customer preferences by changing what it stocks and how much space it gives each line.","distractor_reasons":{"A":"A market-oriented business responds to evidence of changing customer preferences by changing what it stocks and how much space it gives each line.","B":"Cutting staff without regard to demand risks poor service in the growing sourdough lines.","C":"Making an unsubstantiated health claim about white bread misleads customers and will not reverse the trend.","D":"Relying on past sales ignores the clear shift in current customer buying behaviour."}}},{"id":"P1_U3_MCQ_1246","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1246","question":"Melbury Skincare invites eight regular customers to a two-hour discussion led by a researcher about a proposed night cream. What is the main strength of this focus group?","options":{"A":"It is cheaper than asking any questions at all.","B":"It prevents participants from influencing each other.","C":"Discussion reveals detailed feelings and reasons behind preferences.","D":"It gives statistically reliable results for the whole population."},"correctOption":"C","correctAnswer":"Discussion reveals detailed feelings and reasons behind preferences.","questionType":"MCQ","explanation":{"correct_reason":"A focus group encourages open discussion, so participants explain and debate their views, revealing feelings that a simple questionnaire may miss.","distractor_reasons":{"A":"Recruiting, hosting and analysing a session costs money, unlike simply reading existing data.","B":"Group interaction is the point of a focus group; participants inevitably influence one another.","C":"A focus group encourages open discussion, so participants explain and debate their views, revealing feelings that a simple questionnaire may miss.","D":"Eight people are too few to be statistically representative of a large population."}}},{"id":"P1_U3_MCQ_1247","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1247","question":"Cobham Confectionery sells boxes of sweets to a wholesaler, which breaks them into smaller quantities for hundreds of corner shops. What function does the wholesaler perform?","options":{"A":"Breaking bulk and providing wide distribution","B":"Manufacturing the sweets at lower cost","C":"Setting the product's brand identity","D":"Providing after-sales repairs"},"correctOption":"A","correctAnswer":"Breaking bulk and providing wide distribution","questionType":"MCQ","explanation":{"correct_reason":"A wholesaler buys in large quantities and breaks them into smaller lots for many small retailers, extending distribution reach.","distractor_reasons":{"A":"A wholesaler buys in large quantities and breaks them into smaller lots for many small retailers, extending distribution reach.","B":"Manufacturing is the producer's activity; the wholesaler only handles and resells stock.","C":"Brand identity is created by the manufacturer's marketing, not by a wholesaler's logistics.","D":"Repairs are unrelated to confectionery distribution."}}},{"id":"P1_U3_MCQ_1248","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1248","question":"A drinks firm translates its home slogan 'Refresh your spirit' literally into another language, where the phrase means 'haunt your soul'. Why is this a marketing risk?","options":{"A":"The translated slogan may offend or confuse local customers and damage the brand.","B":"Import tariffs automatically double when a slogan is translated.","C":"Foreign printers refuse to print any translated text.","D":"Local customers will definitely buy more of the drink."},"correctOption":"A","correctAnswer":"The translated slogan may offend or confuse local customers and damage the brand.","questionType":"MCQ","explanation":{"correct_reason":"A slogan that changes meaning across languages can seem strange or offensive, damaging the brand's credibility in that market.","distractor_reasons":{"A":"A slogan that changes meaning across languages can seem strange or offensive, damaging the brand's credibility in that market.","B":"Tariffs depend on product classification and value, not on advertising wording.","C":"Local media regularly print and broadcast translated copy.","D":"A slogan with an unintended meaning is likely to deter rather than attract buyers."}}},{"id":"P1_U3_MCQ_1249","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1249","question":"Brackenwood Stoves fits every stove with a patented clean-burn system that cuts smoke by 40% compared with rival models. Competitors cannot legally copy the system. What is this feature called?","options":{"A":"A distribution channel","B":"A unique selling point","C":"A loss leader","D":"A market segment"},"correctOption":"B","correctAnswer":"A unique selling point","questionType":"MCQ","explanation":{"correct_reason":"A unique selling point is a feature that distinguishes a product from rivals; the patented clean-burn system is exactly such a differentiator.","distractor_reasons":{"A":"A distribution channel is the route goods take to customers, not a stove's smoke-reducing system.","B":"A unique selling point is a feature that distinguishes a product from rivals; the patented clean-burn system is exactly such a differentiator.","C":"A loss leader is a product sold below cost to attract buyers, not a patented technical feature.","D":"A market segment is a group of buyers with similar needs, not a product characteristic."}}},{"id":"P1_U3_MCQ_1250","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1250","question":"Grafton Retail fits a new store with sensors that record how shoppers move between aisles and where they stop. No questions are asked. Which research method is this?","options":{"A":"A focus group","B":"A postal questionnaire","C":"Secondary desk research","D":"Observation"},"correctOption":"D","correctAnswer":"Observation","questionType":"MCQ","explanation":{"correct_reason":"Observation records actual behaviour without questioning people, and the aisle sensors are doing exactly that.","distractor_reasons":{"A":"A focus group is a moderated discussion, not silent tracking of shopper movement.","B":"A postal questionnaire asks people to report their behaviour in writing.","C":"Desk research uses existing published material rather than new in-store tracking data.","D":"Observation records actual behaviour without questioning people, and the aisle sensors are doing exactly that."}}},{"id":"P1_U3_MCQ_1251","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1251","question":"Pendlebury Motors spends $45,000 promoting its new van and expects to sell 15,000 vans during the campaign. The van is aimed at small building firms. What is the promotional cost per van?","options":{"A":"$3.50","B":"$4.00","C":"$2.50","D":"$3.00"},"correctOption":"D","correctAnswer":"$3.00","questionType":"MCQ","explanation":{"correct_reason":"$45,000 / 15,000 vans = $3.00 of promotional cost per van.","distractor_reasons":{"A":"$3.50 would imply only about 12,857 vans.","B":"$4.00 would imply 11,250 vans, well below the expected 15,000.","C":"$2.50 would imply 18,000 vans from the $45,000 budget.","D":"$45,000 / 15,000 vans = $3.00 of promotional cost per van."}}},{"id":"P1_U3_MCQ_1252","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1252","question":"Sedgefield Instruments expects to sell 18,000 units in Europe at 22 euros each. The exchange rate is $1.15 per euro. What is the expected revenue in dollars?","options":{"A":"$475,200","B":"$435,600","C":"$445,500","D":"$455,400"},"correctOption":"D","correctAnswer":"$455,400","questionType":"MCQ","explanation":{"correct_reason":"Euro revenue = 18,000 x 22 euros = 396,000 euros; converted at $1.15 per euro, dollar revenue = 396,000 x 1.15 = $455,400.","distractor_reasons":{"A":"$475,200 would use an exchange rate of $1.20 per euro.","B":"$435,600 would use an exchange rate of $1.10 per euro.","C":"$445,500 would use an exchange rate of $1.125 per euro.","D":"Euro revenue = 18,000 x 22 euros = 396,000 euros; converted at $1.15 per euro, dollar revenue = 396,000 x 1.15 = $455,400."}}},{"id":"P1_U3_MCQ_1253","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1253","question":"Sallowby Music sold 52,000 downloads in 2024 and 46,800 in 2025. The online music store wants to understand the trend before planning next year's releases. By what percentage did download sales fall?","options":{"A":"8%","B":"10%","C":"11.1%","D":"12%"},"correctOption":"B","correctAnswer":"10%","questionType":"MCQ","explanation":{"correct_reason":"Fall = (52,000 - 46,800) / 52,000 x 100 = 5,200 / 52,000 x 100 = 10%.","distractor_reasons":{"A":"8% would match a fall to 47,840 downloads, not the 46,800 reported.","B":"Fall = (52,000 - 46,800) / 52,000 x 100 = 5,200 / 52,000 x 100 = 10%.","C":"11.1% divides the 5,200 fall by 46,800, using the later year as the base.","D":"12% would require a fall of 6,240 downloads, which is larger than the actual 5,200."}}},{"id":"P1_U3_MCQ_1254","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1254","question":"Penshurst Research spends $4,800 on a project and completes 160 usable interviews. The agency is comparing this project with earlier studies of the same market. What was the cost per completed interview?","options":{"A":"$28","B":"$30","C":"$32","D":"$24"},"correctOption":"B","correctAnswer":"$30","questionType":"MCQ","explanation":{"correct_reason":"$4,800 / 160 interviews = $30 per completed interview.","distractor_reasons":{"A":"$28 would imply about 171 interviews, not the 160 completed.","B":"$4,800 / 160 interviews = $30 per completed interview.","C":"$32 would imply 150 interviews, fewer than the 160 completed.","D":"$24 would imply 200 interviews for the same $4,800 spend."}}},{"id":"P1_U3_MCQ_1255","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1255","question":"Kelmscott Angling Supplies previously sold only from one shop. It now runs a website that takes orders from anglers across the country. What is the main advantage of this move?","options":{"A":"It removes the need to hold any stock.","B":"It eliminates delivery costs entirely.","C":"It guarantees customers cannot compare prices.","D":"It reaches far more customers without the cost of many physical shops."},"correctOption":"D","correctAnswer":"It reaches far more customers without the cost of many physical shops.","questionType":"MCQ","explanation":{"correct_reason":"An online store extends geographic reach and trades around the clock while avoiding the rent and staffing costs of multiple premises.","distractor_reasons":{"A":"Online orders still require stock to be held and replenished.","B":"Delivery and packaging costs are significant for an online angling retailer.","C":"Online buyers can compare prices very easily, which increases competition.","D":"An online store extends geographic reach and trades around the clock while avoiding the rent and staffing costs of multiple premises."}}},{"id":"P1_U3_MCQ_1256","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1256","question":"A small maker of handmade leather notebooks cannot afford a chain of shops. It opens a specialist website serving customers worldwide. Why is this a suitable strategy?","options":{"A":"Low premises costs let it reach a global niche that physical shops could not serve profitably","B":"It removes the need to promote the website at all","C":"It guarantees that larger rivals cannot copy the idea","D":"It allows the firm to ignore delivery and returns"},"correctOption":"A","correctAnswer":"Low premises costs let it reach a global niche that physical shops could not serve profitably","questionType":"MCQ","explanation":{"correct_reason":"An online store avoids multiple shop rents and allows a small specialist maker to reach scattered worldwide buyers who form a viable niche.","distractor_reasons":{"A":"An online store avoids multiple shop rents and allows a small specialist maker to reach scattered worldwide buyers who form a viable niche.","B":"A website still needs promotion to attract visitors and buyers.","C":"Larger rivals can copy an online notebook store relatively easily.","D":"Delivery and returns must be managed carefully in any online business."}}},{"id":"P1_U3_MCQ_1257","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1257","question":"Before designing its new range, Lydgate Outdoor Clothing interviewed 900 hikers about fabrics, pockets and fit, then built the range around those findings. Which approach does this show?","options":{"A":"Market orientation, because customer research shaped the product.","B":"Asset-led orientation, because factories decided the design.","C":"Sales orientation, because the firm only pushes existing stock.","D":"Product orientation, because the firm started with designs."},"correctOption":"A","correctAnswer":"Market orientation, because customer research shaped the product.","questionType":"MCQ","explanation":{"correct_reason":"Market orientation means identifying customer needs first and then designing products to meet them, which is what the 900 interviews achieved.","distractor_reasons":{"A":"Market orientation means identifying customer needs first and then designing products to meet them, which is what the 900 interviews achieved.","B":"No factory constraint drove the design; evidence from hikers did.","C":"Sales orientation focuses on pushing existing products, whereas here the range was designed afresh from research.","D":"Product orientation starts with what the firm can make and then seeks buyers, the reverse of this case."}}},{"id":"P1_U3_MCQ_1258","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1258","question":"Stowford Insights plans two surveys of the same market: one with 120 respondents and one with 600. Both use the same random selection method. What is the likely effect of the larger sample?","options":{"A":"The larger sample will produce exactly the same figures.","B":"Results should be more reliable, but the survey will cost more.","C":"Results will be less reliable because more people confuse the data.","D":"The larger sample removes every possible error."},"correctOption":"B","correctAnswer":"Results should be more reliable, but the survey will cost more.","questionType":"MCQ","explanation":{"correct_reason":"A larger random sample reduces sampling error and gives more trustworthy estimates, though interviewing 600 people costs more than 120.","distractor_reasons":{"A":"Two different samples will produce similar but rarely identical figures.","B":"A larger random sample reduces sampling error and gives more trustworthy estimates, though interviewing 600 people costs more than 120.","C":"More respondents generally improve reliability rather than reduce it.","D":"Sampling error shrinks but other errors, such as poor question wording, can remain."}}},{"id":"P1_U3_MCQ_1259","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1259","question":"Ashfield Joinery sells its bespoke doors directly to builders instead of through wholesalers, so it sets the price and deals with customers itself. Why might it choose this?","options":{"A":"It reduces the administration of handling individual orders.","B":"It guarantees a wider national customer base than wholesalers.","C":"It removes the need to advertise or promote the doors.","D":"It keeps the intermediary's margin and controls pricing and customer relations."},"correctOption":"D","correctAnswer":"It keeps the intermediary's margin and controls pricing and customer relations.","questionType":"MCQ","explanation":{"correct_reason":"Selling direct removes the wholesaler's margin and gives the joinery control over price, brand presentation and customer contact.","distractor_reasons":{"A":"Direct selling adds administration because the firm handles every order itself.","B":"A wholesaler network typically reaches more scattered customers than one joinery can alone.","C":"Direct selling still requires promotion to generate enquiries.","D":"Selling direct removes the wholesaler's margin and gives the joinery control over price, brand presentation and customer contact."}}},{"id":"P1_U3_MCQ_1260","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1260","question":"After a year, Thurlby Toys compares its sales, market share and customer enquiries with the targets set in its marketing plan. What is the firm doing?","options":{"A":"Setting a price using a cost-plus formula","B":"Designing a questionnaire for new research","C":"Selecting a random sample of customers","D":"Evaluating whether its marketing strategy achieved its objectives"},"correctOption":"D","correctAnswer":"Evaluating whether its marketing strategy achieved its objectives","questionType":"MCQ","explanation":{"correct_reason":"Comparing actual sales, share and enquiries against planned targets is an evaluation of whether the strategy worked.","distractor_reasons":{"A":"No cost-plus calculation is described; the focus is on comparing results with objectives.","B":"The firm is not drafting survey questions but reviewing performance data.","C":"No sampling procedure is being used in this review.","D":"Comparing actual sales, share and enquiries against planned targets is an evaluation of whether the strategy worked."}}},{"id":"P1_U3_MCQ_1261","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1261","question":"Grimsdale Pet Supplies answers enquiries within two hours, replaces faulty goods without argument and keeps detailed pet-care advice on its website. Why can this raise sales?","options":{"A":"It reduces the firm's wage bill because staff have less to do.","B":"Good service builds trust and encourages repeat purchase and recommendations.","C":"It allows the firm to ignore competitors' prices permanently.","D":"It removes the need to train any new employees."},"correctOption":"B","correctAnswer":"Good service builds trust and encourages repeat purchase and recommendations.","questionType":"MCQ","explanation":{"correct_reason":"Reliable service creates trust, so customers return and recommend the business, raising sales without price cuts.","distractor_reasons":{"A":"Fast responses and advice require staff time, so service usually adds cost rather than cutting wages.","B":"Reliable service creates trust, so customers return and recommend the business, raising sales without price cuts.","C":"Service helps retain customers but rival pricing still influences buying decisions.","D":"Maintaining service standards depends on training staff, not on abandoning it."}}},{"id":"P1_U3_MCQ_1262","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1262","question":"Barrowby Snacks launches its new lentil crisps in 30 selected supermarkets in one region before a national rollout. The snack firm wants evidence from real shoppers before a national launch. What is this called?","options":{"A":"Test marketing","B":"Market segmentation","C":"Price skimming","D":"Mass customisation"},"correctOption":"A","correctAnswer":"Test marketing","questionType":"MCQ","explanation":{"correct_reason":"Test marketing trials a new product in a limited area to gather real sales evidence before committing to a full launch.","distractor_reasons":{"A":"Test marketing trials a new product in a limited area to gather real sales evidence before committing to a full launch.","B":"Market segmentation groups buyers by characteristics; it does not describe a limited-area launch.","C":"Price skimming is a high initial pricing tactic, not a regional trial.","D":"Mass customisation tailors output to individual buyers, which is unrelated to a regional launch."}}},{"id":"P1_U3_MCQ_1263","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1263","question":"Ormiston Medical launches a home blood-pressure monitor with unfamiliar features. Its adverts explain how to fit the cuff and interpret the readings. Why is informative advertising appropriate here?","options":{"A":"The product is identical to rivals, so emotion alone will sell it.","B":"The firm wants to hide the product's functions from buyers.","C":"Buyers need factual explanation before they understand and trust a new device.","D":"Buyers already know the product and only need reminding."},"correctOption":"C","correctAnswer":"Buyers need factual explanation before they understand and trust a new device.","questionType":"MCQ","explanation":{"correct_reason":"For a new, technically unfamiliar product, informative advertising supplies the facts buyers need in order to understand the benefits and feel confident purchasing.","distractor_reasons":{"A":"The monitor is described as having unfamiliar features, so it is not a commodity.","B":"Informative advertising explains features rather than concealing them.","C":"For a new, technically unfamiliar product, informative advertising supplies the facts buyers need in order to understand the benefits and feel confident purchasing.","D":"Reminder advertising suits established products, not an unfamiliar new monitor."}}},{"id":"P1_U3_MCQ_1264","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1264","question":"Ashbourne Cycles sells 12,000 helmets a year at $28. A campaign is expected to raise unit sales by 25% at the same price. What revenue would the campaign generate?","options":{"A":"$378,000","B":"$392,000","C":"$420,000","D":"$448,000"},"correctOption":"C","correctAnswer":"$420,000","questionType":"MCQ","explanation":{"correct_reason":"New volume = 12,000 x 1.25 = 15,000 helmets; revenue = 15,000 x $28 = $420,000.","distractor_reasons":{"A":"$378,000 is 12,000 x $31.50, which keeps the old volume and changes the price instead.","B":"$392,000 is 14,000 x $28, implying a 16.7% uplift.","C":"New volume = 12,000 x 1.25 = 15,000 helmets; revenue = 15,000 x $28 = $420,000.","D":"$448,000 is 16,000 x $28, implying a 33.3% uplift."}}},{"id":"P1_U3_MCQ_1265","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1265","question":"Redmarley Marine Covers earned $2.16 million from boat covers, in a boat-cover market worth $27 million. The figures come from the firm's audited accounts for the year. What was its market share by value?","options":{"A":"12.5%","B":"6%","C":"8%","D":"9%"},"correctOption":"C","correctAnswer":"8%","questionType":"MCQ","explanation":{"correct_reason":"$2.16 million / $27 million x 100 = 8%, so Ashby held 8% of the market by value.","distractor_reasons":{"A":"12.5% is $27 million divided by $2.16 million, which inverts the calculation.","B":"6% would require revenue of $1.62 million, which is $540,000 below the figure given.","C":"$2.16 million / $27 million x 100 = 8%, so Ashby held 8% of the market by value.","D":"9% would require $2.43 million of revenue, more than Ashby actually earned."}}},{"id":"P1_U3_MCQ_1266","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1266","question":"Aldercot Research has $5,400 to spend and each completed interview costs $18. The agency must stay within the client's fixed budget for fieldwork. How many completed interviews can it buy?","options":{"A":"320","B":"270","C":"288","D":"300"},"correctOption":"D","correctAnswer":"300","questionType":"MCQ","explanation":{"correct_reason":"$5,400 / $18 = 300 completed interviews can be purchased within the budget.","distractor_reasons":{"A":"320 interviews would cost $5,760, exceeding the $5,400 available.","B":"270 interviews would cost $4,860, leaving $540 unspent.","C":"288 interviews would cost $5,184, slightly under the budget.","D":"$5,400 / $18 = 300 completed interviews can be purchased within the budget."}}},{"id":"P1_U3_MCQ_1267","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1267","question":"Two bottled waters are chemically identical, but Sturgate Springs' adverts link its bottle with mountain hiking and vitality. What is the purpose of this persuasive advertising?","options":{"A":"To create an emotional brand image that makes the product stand out from identical rivals.","B":"To explain the chemical composition of the water in detail.","C":"To announce a temporary price reduction.","D":"To warn customers about a product recall."},"correctOption":"A","correctAnswer":"To create an emotional brand image that makes the product stand out from identical rivals.","questionType":"MCQ","explanation":{"correct_reason":"Persuasive advertising builds an emotional association and brand image, which differentiates a product that is physically the same as its rivals.","distractor_reasons":{"A":"Persuasive advertising builds an emotional association and brand image, which differentiates a product that is physically the same as its rivals.","B":"Detailed factual explanation would be informative advertising, not an image-building campaign.","C":"A price reduction would be announced through sales promotion.","D":"Product recalls are communicated through public notices, not lifestyle advertising."}}},{"id":"P1_U3_MCQ_1268","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1268","question":"A snack brand plans cartoon adverts aimed at children for a sugar-heavy cereal. The cereal contains 28g of sugar per 100g. Which ethical concern does this raise?","options":{"A":"The cereal may be sold in too many supermarkets","B":"The adverts may improve the firm's brand image too quickly","C":"Persuading children to want unhealthy food that they cannot judge properly","D":"The advertisements are too expensive for the firm's budget"},"correctOption":"C","correctAnswer":"Persuading children to want unhealthy food that they cannot judge properly","questionType":"MCQ","explanation":{"correct_reason":"Children are less able to evaluate persuasive claims, so marketing sugary food directly to them raises a clear ethical concern about health and influence.","distractor_reasons":{"A":"Wide distribution is a place decision and is not inherently unethical.","B":"Improved brand image is a commercial outcome, not the ethical problem in targeting children.","C":"Children are less able to evaluate persuasive claims, so marketing sugary food directly to them raises a clear ethical concern about health and influence.","D":"Cost is a financial question, not the ethical issue described."}}},{"id":"P1_U3_MCQ_1269","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1269","question":"Kestrelwell Garden Centre sells most of its plants and hanging baskets between April and June, while trade is very quiet in December. How should managers plan for this seasonal pattern?","options":{"A":"Recruit temporary staff and build stock for spring, then reduce staffing in winter.","B":"Keep exactly the same staff levels and stock all year to avoid change.","C":"Raise prices sharply in winter to compensate for low sales.","D":"Close the garden centre permanently in the quieter months."},"correctOption":"A","correctAnswer":"Recruit temporary staff and build stock for spring, then reduce staffing in winter.","questionType":"MCQ","explanation":{"correct_reason":"Seasonal demand requires matching labour and inventory to the busy spring peak and reducing both when trade is quiet, which controls cost and protects service.","distractor_reasons":{"A":"Seasonal demand requires matching labour and inventory to the busy spring peak and reducing both when trade is quiet, which controls cost and protects service.","B":"Fixed staffing and stock through the slow winter raises costs without generating sales.","C":"Higher winter prices would depress already weak demand further.","D":"Closing entirely abandons loyal customers and loses the spring trade that follows."}}},{"id":"P1_U3_MCQ_1270","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1270","question":"Mendlesham Toys relies on a five-year-old national spending report to forecast demand for a new electronic puzzle. Why is this secondary data a weak basis for the forecast?","options":{"A":"It must have been gathered by the firm's own staff.","B":"It is always more expensive than a new survey.","C":"It was collected years ago for another purpose and may not fit the new product.","D":"Secondary data can never be expressed in numbers."},"correctOption":"C","correctAnswer":"It was collected years ago for another purpose and may not fit the new product.","questionType":"MCQ","explanation":{"correct_reason":"Secondary data is gathered by others for their own purposes, and a five-year-old report may be outdated and poorly matched to an electronic puzzle.","distractor_reasons":{"A":"Secondary data comes from outside sources, not the firm's own staff.","B":"Existing published data is usually cheaper than commissioning new research.","C":"Secondary data is gathered by others for their own purposes, and a five-year-old report may be outdated and poorly matched to an electronic puzzle.","D":"Much secondary data, such as spending reports, is numerical."}}},{"id":"P1_U3_MCQ_1271","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1271","question":"Brixworth Coffee offers 'buy two bags, get the third free' for one month only. Coffee shops and online customers are the target buyers. Which promotional method is this?","options":{"A":"Informative advertising","B":"Sales promotion","C":"Public relations","D":"Sponsorship"},"correctOption":"B","correctAnswer":"Sales promotion","questionType":"MCQ","explanation":{"correct_reason":"A short-term offer such as buy two get one free is a sales promotion, designed to boost purchases during a limited period.","distractor_reasons":{"A":"Informative advertising explains product features rather than offering a temporary deal.","B":"A short-term offer such as buy two get one free is a sales promotion, designed to boost purchases during a limited period.","C":"Public relations seeks favourable unpaid publicity rather than a price-based offer.","D":"Sponsorship funds an event or team in exchange for brand exposure."}}},{"id":"P1_U3_MCQ_1272","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1272","question":"Wealdham Foods gives 5,000 small packs of its new granola to shoppers at railway stations to encourage trial. The granola is aimed at breakfast shoppers who have not tried the brand. What promotional purpose does this serve?","options":{"A":"It lets customers try the product and reduces the risk of buying a full pack","B":"It raises the unit price of every full pack sold","C":"It replaces the need for any advertising or branding","D":"It guarantees repeat purchases by every recipient"},"correctOption":"A","correctAnswer":"It lets customers try the product and reduces the risk of buying a full pack","questionType":"MCQ","explanation":{"correct_reason":"Free samples encourage trial by letting shoppers experience the taste without risk, which can convert them into buyers of full packs.","distractor_reasons":{"A":"Free samples encourage trial by letting shoppers experience the taste without risk, which can convert them into buyers of full packs.","B":"Giving away packs adds promotional cost rather than raising the product's unit price.","C":"Sampling supports advertising but cannot replace branding and wider promotion.","D":"Some recipients will dislike the product or not buy again, so repeat purchase is not guaranteed."}}},{"id":"P1_U3_MCQ_1273","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1273","question":"Customers of Aldermere Tea Co. ask for its tea by name, and many continue buying after a rival launches a cheaper blend. What does this show?","options":{"A":"The brand has built loyalty that reduces customers' sensitivity to price.","B":"The firm has become a monopoly with no competitors.","C":"The tea must be sold below cost to keep buyers.","D":"Customers are forced to buy the brand by law."},"correctOption":"A","correctAnswer":"The brand has built loyalty that reduces customers' sensitivity to price.","questionType":"MCQ","explanation":{"correct_reason":"Buyers who request the brand by name and stay after a cheaper rival appears are displaying brand loyalty, which weakens the effect of price competition.","distractor_reasons":{"A":"Buyers who request the brand by name and stay after a cheaper rival appears are displaying brand loyalty, which weakens the effect of price competition.","B":"A rival has entered with a cheaper blend, so the firm clearly faces competition.","C":"No evidence suggests below-cost selling; loyalty is keeping customers at the existing price.","D":"Nothing in the case indicates any legal compulsion to buy the tea."}}},{"id":"P1_U3_MCQ_1274","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1274","question":"Thorncroft Garden Tools emails a survey link to 12,000 past customers. The garden supplier wants quick feedback on a new range of secateurs. Which combination best describes the advantages and limitations of this method?","options":{"A":"Low cost and fast reach, but older or less online customers may be missed.","B":"High cost and slow fieldwork, but every customer is guaranteed to reply.","C":"No sampling issues, because email reaches the entire population.","D":"Perfect accuracy, because online answers cannot be biased."},"correctOption":"A","correctAnswer":"Low cost and fast reach, but older or less online customers may be missed.","questionType":"MCQ","explanation":{"correct_reason":"Email surveys are cheap and quick to distribute widely, but they exclude people who are less comfortable online, which can bias the sample.","distractor_reasons":{"A":"Email surveys are cheap and quick to distribute widely, but they exclude people who are less comfortable online, which can bias the sample.","B":"Email distribution is inexpensive and fast, and response is always voluntary rather than guaranteed.","C":"Reaching many customers does not remove non-response bias from those who ignore the email.","D":"Online responses can still be biased by question wording and by who chooses to reply."}}},{"id":"P1_U3_MCQ_1275","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1275","question":"Threlfall Sportswear pays $2 million to have its logo on a leading cycling team's jerseys, which appear on television in 14 countries. What is the main benefit and main risk of this sponsorship?","options":{"A":"Lower wages, but higher distribution costs.","B":"Wide brand exposure, but reputational damage if the team is involved in a scandal.","C":"Guaranteed sales growth, but no cost to the firm.","D":"Free manufacturing, but loss of control over product design."},"correctOption":"B","correctAnswer":"Wide brand exposure, but reputational damage if the team is involved in a scandal.","questionType":"MCQ","explanation":{"correct_reason":"Sponsorship buys repeated logo exposure to large audiences, but the brand's reputation becomes tied to the team's behaviour and results.","distractor_reasons":{"A":"Sponsorship does not affect wage rates and has no direct link to distribution costs.","B":"Sponsorship buys repeated logo exposure to large audiences, but the brand's reputation becomes tied to the team's behaviour and results.","C":"Sponsorship costs $2 million and cannot guarantee sales growth.","D":"Sponsorship is a promotional payment and has nothing to do with manufacturing."}}},{"id":"P1_U3_MCQ_1276","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1276","question":"Dunmore Tools holds 12,000 units of a market totalling 90,000 units. It wants a 16% share. How many additional units must it sell, assuming the market size is unchanged?","options":{"A":"+2,400","B":"+2,700","C":"+3,600","D":"+1,800"},"correctOption":"A","correctAnswer":"+2,400","questionType":"MCQ","explanation":{"correct_reason":"Target volume = 16% x 90,000 = 14,400 units; extra needed = 14,400 - 12,000 = 2,400 units.","distractor_reasons":{"A":"Target volume = 16% x 90,000 = 14,400 units; extra needed = 14,400 - 12,000 = 2,400 units.","B":"2,700 more units give 14,700, a 16.3% share, slightly above target.","C":"3,600 more units give 15,600, a 17.3% share, above target.","D":"1,800 more units give 13,800, which is only 15.3% of the 90,000 market."}}},{"id":"P1_U3_MCQ_1277","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1277","question":"Marlowe Optics wants $250,000 of revenue from its binoculars, which sell for $125 each. The binoculars are sold mainly to birdwatchers and racegoers. How many pairs must it sell to reach the target?","options":{"A":"2,250","B":"2,500","C":"1,800","D":"2,000"},"correctOption":"D","correctAnswer":"2,000","questionType":"MCQ","explanation":{"correct_reason":"$250,000 / $125 = 2,000 pairs of binoculars are needed to reach the revenue target.","distractor_reasons":{"A":"2,250 pairs would generate $281,250, which exceeds the target.","B":"2,500 pairs would generate $312,500, far above the $250,000 target.","C":"1,800 pairs would generate only $225,000 at $125 each.","D":"$250,000 / $125 = 2,000 pairs of binoculars are needed to reach the revenue target."}}},{"id":"P1_U3_MCQ_1278","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1278","question":"Alderford Research plans 250 telephone interviews at a cost of $27 each. The study covers customer satisfaction with a new loyalty app. What is the total research cost?","options":{"A":"$7,000","B":"$6,250","C":"$6,500","D":"$6,750"},"correctOption":"D","correctAnswer":"$6,750","questionType":"MCQ","explanation":{"correct_reason":"Total cost = 250 interviews x $27 = $6,750.","distractor_reasons":{"A":"$7,000 would follow from a cost of $28 per interview.","B":"$6,250 would follow from 250 interviews at $25 each.","C":"$6,500 would follow from a cost of $26 per interview.","D":"Total cost = 250 interviews x $27 = $6,750."}}},{"id":"P1_U3_MCQ_1279","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1279","question":"Ravensdale Ski Hire cut the weekly hire price from $80 to $68. The ski hire shop wants to advertise the size of the reduction. By what percentage was the price reduced?","options":{"A":"12%","B":"15%","C":"17.6%","D":"20%"},"correctOption":"B","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Reduction = $80 - $68 = $12; percentage cut = $12 / $80 x 100 = 15%.","distractor_reasons":{"A":"12% would mean a cut of $9.60, leaving a price of $70.40.","B":"Reduction = $80 - $68 = $12; percentage cut = $12 / $80 x 100 = 15%.","C":"17.6% divides the $12 cut by the new price of $68, using the wrong base.","D":"20% would mean a cut of $16, giving a price of $64 rather than $68."}}},{"id":"P1_U3_MCQ_1280","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1280","question":"Bexhill Kitchens has only $4,000 for promotion. It can buy a $4,000 newspaper advert reaching 200,000 readers, or targeted social media posts reaching 30,000 likely buyers for $1,200. Which choice best uses the budget?","options":{"A":"Both, even though together they cost $5,200","B":"The social media posts, because they reach likely buyers at lower cost and leave budget for other promotion","C":"The newspaper advert, because a bigger audience is always better value","D":"Neither, because small firms should never promote"},"correctOption":"B","correctAnswer":"The social media posts, because they reach likely buyers at lower cost and leave budget for other promotion","questionType":"MCQ","explanation":{"correct_reason":"Reaching likely buyers at $1,200 leaves $2,800 for other activity and targets the audience more precisely than a broad newspaper audience.","distractor_reasons":{"A":"The combined cost of $5,200 exceeds the $4,000 budget.","B":"Reaching likely buyers at $1,200 leaves $2,800 for other activity and targets the audience more precisely than a broad newspaper audience.","C":"A larger audience is not better value if most readers are unlikely to buy the product.","D":"Small firms can promote effectively through low-cost, targeted channels."}}},{"id":"P1_U3_MCQ_1281","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1281","question":"A new competitor enters Penhallow Instruments' market with a digital gauge that is more accurate and cheaper to run than Penhallow's mechanical model. What should Penhallow do first?","options":{"A":"Double its price to signal higher quality.","B":"Reduce customer service to save money for advertising.","C":"Ignore the entrant because its own product has sold well for years.","D":"Review the product design and consider upgrading or repositioning its gauge."},"correctOption":"D","correctAnswer":"Review the product design and consider upgrading or repositioning its gauge.","questionType":"MCQ","explanation":{"correct_reason":"A rival with a technically superior product threatens the firm's position, so reviewing design and upgrading or repositioning is the logical first response.","distractor_reasons":{"A":"Doubling the price without improving the product would widen the gap with the new entrant.","B":"Cutting service removes an advantage and weakens the offer against the entrant.","C":"Past sales do not protect against a rival whose product is more accurate and cheaper to run.","D":"A rival with a technically superior product threatens the firm's position, so reviewing design and upgrading or repositioning is the logical first response."}}},{"id":"P1_U3_MCQ_1282","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1282","question":"A researcher for Redbourne Insights stands in a shopping centre and must complete 40 interviews with women aged 18-30 and 40 with men aged 31-50. She chooses whomever she can persuade from each group. Which method is this?","options":{"A":"Test marketing","B":"Quota sampling","C":"Random sampling","D":"Secondary research"},"correctOption":"B","correctAnswer":"Quota sampling","questionType":"MCQ","explanation":{"correct_reason":"Quota sampling sets required numbers within chosen groups and the interviewer selects respondents to fill those quotas, which matches this task.","distractor_reasons":{"A":"Test marketing trials a product; it does not describe a surveying technique.","B":"Quota sampling sets required numbers within chosen groups and the interviewer selects respondents to fill those quotas, which matches this task.","C":"Random sampling requires chance selection from a full list, not interviewer choice in a centre.","D":"Secondary research uses existing data rather than new face-to-face interviews."}}},{"id":"P1_U3_MCQ_1283","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1283","question":"A regional newspaper writes a positive feature about Ebberston Dairy's free school milk scheme, without being paid. The dairy has not paid for any advertising space. What promotional method is this?","options":{"A":"Sponsorship","B":"Direct marketing","C":"Public relations","D":"Sales promotion"},"correctOption":"C","correctAnswer":"Public relations","questionType":"MCQ","explanation":{"correct_reason":"Public relations earns favourable unpaid coverage by generating news, and the free feature about the school milk scheme is exactly that.","distractor_reasons":{"A":"Sponsorship involves paying to associate the brand with an event or team.","B":"Direct marketing contacts named customers through mail, email or calls.","C":"Public relations earns favourable unpaid coverage by generating news, and the free feature about the school milk scheme is exactly that.","D":"Sales promotion uses short-term offers or incentives, not editorial coverage."}}},{"id":"P1_U3_MCQ_1284","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1284","question":"Cresswell Foods puts its established 'Cresswell' name on a new range of pasta sauces. What is the main benefit and main risk of this brand extension?","options":{"A":"It prevents the firm from using the brand on any other product","B":"It lowers the price of the original products automatically","C":"Instant recognition helps the launch, but poor sauce quality could damage the original brand","D":"It removes all launch costs and guarantees success"},"correctOption":"C","correctAnswer":"Instant recognition helps the launch, but poor sauce quality could damage the original brand","questionType":"MCQ","explanation":{"correct_reason":"An existing brand name gives a new line immediate recognition and trust, but any quality failure can spread negative associations back to the core brand.","distractor_reasons":{"A":"A brand can be extended to further products; this move does not prevent that.","B":"Putting the name on sauces does not automatically change the prices of existing products.","C":"An existing brand name gives a new line immediate recognition and trust, but any quality failure can spread negative associations back to the core brand.","D":"Brand extension still needs launch promotion and cannot guarantee success."}}},{"id":"P1_U3_MCQ_1285","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1285","question":"Bramblewick Biscuits sells one simple recipe to supermarkets nationwide rather than many speciality lines. The biscuit is sold in plain packaging under the supermarket's own label. Why does a standard product suit a mass-market strategy?","options":{"A":"It guarantees that no rival can launch a similar biscuit.","B":"It permits the firm to avoid all packaging costs.","C":"One recipe allows long production runs and simpler promotion across the country.","D":"It lets every customer receive a personalised product."},"correctOption":"C","correctAnswer":"One recipe allows long production runs and simpler promotion across the country.","questionType":"MCQ","explanation":{"correct_reason":"A single standard recipe supports long production runs, simpler logistics and one national promotional message, all of which lower unit cost for mass-market selling.","distractor_reasons":{"A":"Rivals can easily copy a simple biscuit recipe, so it offers no guarantee against entry.","B":"Packaging is still needed for transport, hygiene and labelling even with one recipe.","C":"A single standard recipe supports long production runs, simpler logistics and one national promotional message, all of which lower unit cost for mass-market selling.","D":"Personalisation is a niche strategy and would raise variety and cost, not lower it."}}},{"id":"P1_U3_MCQ_1286","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1286","question":"A fitness chain surveys only 25 members at one of its gyms and then claims the result applies to all adults in the city. What is the main weakness of this research?","options":{"A":"The survey used people rather than documents, so it is invalid.","B":"The sample is too large for detailed analysis.","C":"Random selection always produces biased results.","D":"The sample is small and drawn from one place, so it may not represent the city."},"correctOption":"D","correctAnswer":"The sample is small and drawn from one place, so it may not represent the city.","questionType":"MCQ","explanation":{"correct_reason":"Twenty-five gym members are a small, location-specific group, so the findings are unlikely to represent the whole city's adults.","distractor_reasons":{"A":"Primary research commonly uses people; that alone does not invalidate it.","B":"Twenty-five is small rather than too large, and its smallness is the weakness.","C":"Random selection is designed to reduce bias, not create it.","D":"Twenty-five gym members are a small, location-specific group, so the findings are unlikely to represent the whole city's adults."}}},{"id":"P1_U3_MCQ_1287","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1287","question":"Milldale Glass makes vases at a unit cost of $14 and applies a 45% mark-up on unit cost. The glassware is sold to independent gift shops. What is the selling price?","options":{"A":"$21.00","B":"$18.90","C":"$19.60","D":"$20.30"},"correctOption":"D","correctAnswer":"$20.30","questionType":"MCQ","explanation":{"correct_reason":"Selling price = $14 x 1.45 = $20.30, which adds a mark-up of $6.30 to the $14 unit cost.","distractor_reasons":{"A":"$21.00 would apply a 50% mark-up, above the stated 45%.","B":"$18.90 would apply a 35% mark-up, $1.40 less than required.","C":"$19.60 would apply a 40% mark-up, giving $5.60 rather than $6.30.","D":"Selling price = $14 x 1.45 = $20.30, which adds a mark-up of $6.30 to the $14 unit cost."}}},{"id":"P1_U3_MCQ_1288","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1288","question":"Aldermere Cheese sells 8,000 truckles a year. It can charge $6 more per truckle than rivals because of its protected recipe. What extra profit does the premium generate if costs are unchanged?","options":{"A":"$54,000","B":"$36,000","C":"$42,000","D":"$48,000"},"correctOption":"D","correctAnswer":"$48,000","questionType":"MCQ","explanation":{"correct_reason":"Extra profit = 8,000 truckles x $6 premium = $48,000, because unit costs are unchanged.","distractor_reasons":{"A":"$54,000 would follow from a premium of $6.75 per truckle.","B":"$36,000 would follow from 6,000 truckles at a $6 premium.","C":"$42,000 would follow from 7,000 truckles at the stated premium.","D":"Extra profit = 8,000 truckles x $6 premium = $48,000, because unit costs are unchanged."}}},{"id":"P1_U3_MCQ_1289","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1289","question":"Thurlby Flooring sold 9,600 units in 2024 when the market totalled 240,000 units. In 2025 it sold 11,500 units in a market of 250,000 units. What was its 2025 market share?","options":{"A":"5.0%","B":"4.0%","C":"4.4%","D":"4.6%"},"correctOption":"D","correctAnswer":"4.6%","questionType":"MCQ","explanation":{"correct_reason":"2025 market share = 11,500 / 250,000 x 100 = 4.6%, up from the 4.0% held in 2024.","distractor_reasons":{"A":"5.0% would require 12,500 units, above the 11,500 actually sold.","B":"4.0% was the 2024 share (9,600 / 240,000), not the 2025 figure.","C":"4.4% would require 11,000 units in the 2025 market, which is 500 fewer than sold.","D":"2025 market share = 11,500 / 250,000 x 100 = 4.6%, up from the 4.0% held in 2024."}}},{"id":"P1_U3_MCQ_1290","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1290","question":"Halloway Foods sets a research budget of $9,000 and allocates 40% to fieldwork, 35% to data analysis and 25% to reporting. How much is spent on fieldwork?","options":{"A":"$4,050","B":"$4,500","C":"$3,150","D":"$3,600"},"correctOption":"D","correctAnswer":"$3,600","questionType":"MCQ","explanation":{"correct_reason":"Fieldwork = 40% of $9,000 = 0.40 x $9,000 = $3,600.","distractor_reasons":{"A":"$4,050 is 45% of the budget, above the stated 40% fieldwork share.","B":"$4,500 is 50% of the budget, well above the fieldwork percentage given.","C":"$3,150 is 35% of the budget, which is the analysis share, not fieldwork.","D":"Fieldwork = 40% of $9,000 = 0.40 x $9,000 = $3,600."}}},{"id":"P1_U3_MCQ_1291","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1291","question":"Oakhampton Ski Resort charges $95 for a lift pass on a busy holiday Saturday and $55 on a quiet Tuesday, changing the price as demand changes. Which pricing method is this?","options":{"A":"Price skimming","B":"Dynamic pricing","C":"Cost-plus pricing","D":"Penetration pricing"},"correctOption":"B","correctAnswer":"Dynamic pricing","questionType":"MCQ","explanation":{"correct_reason":"Dynamic pricing adjusts prices frequently in response to current demand, which explains the higher Saturday and lower Tuesday lift-pass prices.","distractor_reasons":{"A":"Price skimming is a high initial price for an innovation, not a changing daily rate.","B":"Dynamic pricing adjusts prices frequently in response to current demand, which explains the higher Saturday and lower Tuesday lift-pass prices.","C":"Cost-plus pricing adds a fixed mark-up to unit cost and would not vary with day-to-day demand.","D":"Penetration pricing is a low launch price for a new product, not a daily adjustment."}}},{"id":"P1_U3_MCQ_1292","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1292","question":"Sales of Fennimore Razors' battery shaver have fallen for five years and repeat purchases have almost stopped. The shaver was launched eight years ago and has no replacement model. Which strategic choice should managers evaluate?","options":{"A":"Whether to reduce all customer research permanently","B":"Whether to increase the advertising budget without changing anything else","C":"Whether to withdraw the shaver or extend its life by finding new uses or markets","D":"Whether to raise output to fill warehouses with unsold stock"},"correctOption":"C","correctAnswer":"Whether to withdraw the shaver or extend its life by finding new uses or markets","questionType":"MCQ","explanation":{"correct_reason":"A product in sustained decline prompts a choice between withdrawal and an extension strategy that finds new uses or markets for it.","distractor_reasons":{"A":"Research remains useful for deciding the product's future and for other lines.","B":"More advertising alone rarely revives a product whose repeat purchases have almost stopped.","C":"A product in sustained decline prompts a choice between withdrawal and an extension strategy that finds new uses or markets for it.","D":"Raising output of a product with collapsing demand would build unwanted stock."}}},{"id":"P1_U3_MCQ_1293","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1293","question":"Winslade Cameras receives repeated online complaints about slow repairs. Its review score falls from 4.6 to 3.1 stars and enquiries drop. What does this illustrate?","options":{"A":"The firm should raise prices to rebuild its rating.","B":"Customer reviews have no effect on a service business.","C":"Poor service damages reputation, which reduces enquiries and future sales.","D":"Repair delays only affect the customers involved and no one else."},"correctOption":"C","correctAnswer":"Poor service damages reputation, which reduces enquiries and future sales.","questionType":"MCQ","explanation":{"correct_reason":"Public reviews spread quickly online, so slow repairs damage the firm's reputation and deter prospective buyers, cutting enquiries.","distractor_reasons":{"A":"Raising prices does not fix slow repairs and may worsen the rating further.","B":"Reviews are read by prospective buyers and clearly influenced enquiries in this case.","C":"Public reviews spread quickly online, so slow repairs damage the firm's reputation and deter prospective buyers, cutting enquiries.","D":"Online complaints are visible to many people beyond the individual customer."}}},{"id":"P1_U3_MCQ_1294","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1294","question":"Fenwyck Sports buys a published industry report containing rivals' sales volumes and average prices. The sports retailer wants to compare its prices with the industry average. What type of data is this?","options":{"A":"Secondary data","B":"Primary data","C":"A pilot survey","D":"Observation"},"correctOption":"A","correctAnswer":"Secondary data","questionType":"MCQ","explanation":{"correct_reason":"The report was compiled and published by another organisation, so using it is secondary research even though the figures concern competitors.","distractor_reasons":{"A":"The report was compiled and published by another organisation, so using it is secondary research even though the figures concern competitors.","B":"Primary data would be collected first-hand by Fenwyck itself, not bought as a finished report.","C":"A pilot survey is a small trial of the firm's own questionnaire, not a published industry report.","D":"Observation involves watching behaviour directly rather than reading compiled figures."}}},{"id":"P1_U3_MCQ_1295","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1295","question":"Chewing gum and bottled water are stocked in thousands of petrol stations, corner shops and supermarkets so that buyers can find them almost anywhere. Which distribution approach is this?","options":{"A":"Selective distribution in one outlet per town","B":"Intensive distribution","C":"Exclusive distribution","D":"Direct selling only"},"correctOption":"B","correctAnswer":"Intensive distribution","questionType":"MCQ","explanation":{"correct_reason":"Intensive distribution places a low-value convenience product in as many suitable outlets as possible so buyers can purchase it easily.","distractor_reasons":{"A":"Selective distribution uses a limited number of chosen outlets, not thousands of them.","B":"Intensive distribution places a low-value convenience product in as many suitable outlets as possible so buyers can purchase it easily.","C":"Exclusive distribution limits a product to very few outlets, the opposite of this case.","D":"Direct selling would bypass shops entirely, which is not how gum and water reach buyers here."}}},{"id":"P1_U3_MCQ_1296","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1296","question":"Marlow Instruments wants to sell in Asia but has no local staff or contacts. It appoints an established regional distributor. Why is this preferable to opening its own overseas subsidiary?","options":{"A":"It keeps complete control over every retail display","B":"It avoids paying any distributor margin","C":"It guarantees sales will exceed all rivals","D":"It gains local contacts and market knowledge with far lower upfront investment"},"correctOption":"D","correctAnswer":"It gains local contacts and market knowledge with far lower upfront investment","questionType":"MCQ","explanation":{"correct_reason":"Using an established distributor provides local knowledge and customer contacts quickly without the heavy capital cost of a foreign subsidiary.","distractor_reasons":{"A":"Working through a distributor reduces direct control over retail presentation.","B":"Distributors earn a margin or commission for their services.","C":"A distributor agreement cannot guarantee that sales will beat every rival.","D":"Using an established distributor provides local knowledge and customer contacts quickly without the heavy capital cost of a foreign subsidiary."}}},{"id":"P1_U3_MCQ_1297","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1297","question":"Nettlebed Honey sells 3,000 jars a year at $48 each. A rival sells a comparable jar at $40, but Nettlebed's customers stay loyal. How much extra revenue does Nettlebed earn from its $8 price premium?","options":{"A":"$12,000","B":"$18,000","C":"$24,000","D":"$36,000"},"correctOption":"C","correctAnswer":"$24,000","questionType":"MCQ","explanation":{"correct_reason":"Price premium = $48 - $40 = $8 per jar; extra revenue = 3,000 jars x $8 = $24,000.","distractor_reasons":{"A":"$12,000 would follow from a premium of $4, not the $8 difference shown.","B":"$18,000 would follow from 2,250 jars at an $8 premium.","C":"Price premium = $48 - $40 = $8 per jar; extra revenue = 3,000 jars x $8 = $24,000.","D":"$36,000 would follow from a premium of $12 per jar."}}},{"id":"P1_U3_MCQ_1298","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1298","question":"A sample of 350 shoppers found that 84 would pay $12 for a jar of Wroxham Preserves. The town has 25,000 shoppers. Assuming the sample is representative, how many would pay $12?","options":{"A":"7,500","B":"5,250","C":"6,000","D":"6,750"},"correctOption":"C","correctAnswer":"6,000","questionType":"MCQ","explanation":{"correct_reason":"84 / 350 = 24%; 24% of 25,000 shoppers = 6,000 people.","distractor_reasons":{"A":"7,500 represents 30% of 25,000, far above the 24% found in the sample.","B":"5,250 represents 21% of 25,000, which is below the sample's 24%.","C":"84 / 350 = 24%; 24% of 25,000 shoppers = 6,000 people.","D":"6,750 represents 27% of 25,000, above the sample proportion."}}},{"id":"P1_U3_MCQ_1299","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1299","question":"Cawdor Cosmetics spends $60,000 on advertising and distributes 20,000 free samples costing $1.50 each, expecting 30,000 units to be sold. What is the total promotional cost per unit sold?","options":{"A":"$3.00","B":"$3.50","C":"$2.00","D":"$2.50"},"correctOption":"A","correctAnswer":"$3.00","questionType":"MCQ","explanation":{"correct_reason":"Sample cost = 20,000 x $1.50 = $30,000; total promotion = $60,000 + $30,000 = $90,000; cost per unit = $90,000 / 30,000 = $3.00.","distractor_reasons":{"A":"Sample cost = 20,000 x $1.50 = $30,000; total promotion = $60,000 + $30,000 = $90,000; cost per unit = $90,000 / 30,000 = $3.00.","B":"$3.50 would follow from a total of $105,000, overstating the campaign.","C":"$2.00 ignores the $30,000 sample cost entirely.","D":"$2.50 would follow from a total of $75,000, understating the sample cost."}}},{"id":"P1_U3_MCQ_1300","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1300","question":"Salterton Spices spends $110,000 on advertising and gives retailers $40,000 of launch discounts, expecting 25,000 jars to be sold. What is the total promotional cost per jar?","options":{"A":"$5.60","B":"$6.00","C":"$6.60","D":"$4.40"},"correctOption":"B","correctAnswer":"$6.00","questionType":"MCQ","explanation":{"correct_reason":"Total promotion = $110,000 + $40,000 = $150,000; cost per jar = $150,000 / 25,000 = $6.00.","distractor_reasons":{"A":"$5.60 would follow from $140,000 total, understating the discounts.","B":"Total promotion = $110,000 + $40,000 = $150,000; cost per jar = $150,000 / 25,000 = $6.00.","C":"$6.60 would follow from $165,000 total, overstating the campaign.","D":"$4.40 ignores the $40,000 of launch discounts."}}},{"id":"P1_U3_MCQ_1301","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1301","question":"Nettlebed Cycles sold 4,800 bicycles last year. Total bicycle sales in its country reached 60,000 units over the same period. Before setting next year's target, the marketing director wants to know the firm's share of the national market. What is Nettlebed Cycles' market share?","options":{"A":"8%","B":"12.5%","C":"0.8%","D":"80%"},"correctOption":"A","correctAnswer":"8%","questionType":"MCQ","explanation":{"correct_reason":"Market share is the firm's sales divided by total market sales, so 4,800 bicycles divided by 60,000 bicycles gives 0.08, which is 8% of the national market.","distractor_reasons":{"A":"Market share is the firm's sales divided by total market sales, so 4,800 bicycles divided by 60,000 bicycles gives 0.08, which is 8% of the national market.","B":"12.5% would be correct only if Nettlebed had sold 7,500 bicycles, because 7,500 divided by 60,000 equals 12.5%, and no figure in the stem gives that volume.","C":"0.8% mistakes the decimal place: 4,800 divided by 60,000 gives 0.08 as a decimal, which must be multiplied by 100 to become 8%.","D":"80% would require sales of 48,000 bicycles out of the 60,000 total, which is ten times the 4,800 units Nettlebed actually sold."}}},{"id":"P1_U3_MCQ_1302","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1302","question":"Harkwell Pet Foods makes only grain-free food for senior dogs, charging a premium price to owners who want specialist nutrition. Its larger rivals sell cheap food for every dog through supermarkets. Which marketing approach is Harkwell using?","options":{"A":"Mass marketing, because it sells to dog owners in general","B":"Niche marketing aimed at a small, clearly defined group of buyers","C":"Product orientation, because it makes only one type of food","D":"Undifferentiated marketing, because it charges a premium price"},"correctOption":"B","correctAnswer":"Niche marketing aimed at a small, clearly defined group of buyers","questionType":"MCQ","explanation":{"correct_reason":"Harkwell serves a small, specific group of buyers with a specialised product at a premium price, which is the definition of niche marketing rather than selling to the whole market.","distractor_reasons":{"A":"Mass marketing means selling a standard product to the whole market, yet Harkwell deliberately ignores most dog owners and serves only senior dogs.","B":"Harkwell serves a small, specific group of buyers with a specialised product at a premium price, which is the definition of niche marketing rather than selling to the whole market.","C":"Product orientation describes a firm that develops products without studying customers, not a firm that chooses a narrow group of buyers to serve.","D":"Undifferentiated marketing means one offer for everyone, so it cannot describe a firm that targets only owners of senior dogs with specialist food."}}},{"id":"P1_U3_MCQ_1303","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1303","question":"Vellacott Hampers finds that customers keep buying its gift boxes even though rival boxes cost $6 less. Buyers say they trust the Vellacott name and know the contents will arrive undamaged. Which reason for customer choice does this best illustrate?","options":{"A":"The lower price of its gift boxes","B":"Wider distribution through more retail outlets","C":"Brand image and a reputation for reliability","D":"A legal monopoly over gift box design"},"correctOption":"C","correctAnswer":"Brand image and a reputation for reliability","questionType":"MCQ","explanation":{"correct_reason":"Customers are paying $6 more because they trust the Vellacott name and expect safe delivery, so brand image and a reputation for reliability are driving their choice.","distractor_reasons":{"A":"Vellacott's boxes cost $6 more than rival boxes, so a lower price cannot explain why customers keep choosing them. That is why it is not the best answer here.","B":"The stem gives no evidence about the number of outlets, and wider distribution hardly matters when buyers pay a premium for trust.","C":"Customers are paying $6 more because they trust the Vellacott name and expect safe delivery, so brand image and a reputation for reliability are driving their choice.","D":"No firm can hold a legal monopoly over a simple gift box, and the stem describes trust rather than any exclusive legal right."}}},{"id":"P1_U3_MCQ_1304","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1304","question":"Brindlemoor Coffee estimates that the speciality coffee market was worth $48 million two years ago and is worth $60 million now. The owner wants to know how fast the market has grown before approving an expansion. What is the percentage growth in market size?","options":{"A":"12%","B":"20%","C":"125%","D":"25%"},"correctOption":"D","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"Growth is the $12 million increase divided by the original $48 million, which equals 0.25, so the market has grown by 25% over the two years.","distractor_reasons":{"A":"12% comes from treating the $12 million increase as the percentage, but the increase must be divided by the original $48 million market size.","B":"20% would be right if the market had grown from $50 million to $60 million, not from the $48 million given in the stem.","C":"125% confuses the new market size of $60 million as a percentage of $48 million with the growth rate itself.","D":"Growth is the $12 million increase divided by the original $48 million, which equals 0.25, so the market has grown by 25% over the two years."}}},{"id":"P1_U3_MCQ_1305","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1305","question":"Tarnvale Laundry offers a weekly collect-and-return service at $18, aimed at busy professionals aged 25 to 40 living in city flats. It does not seek hotel or hospital contracts. Which term best describes the group Tarnvale has chosen to serve?","options":{"A":"The mass market","B":"A market segment","C":"A distribution channel","D":"A product portfolio"},"correctOption":"B","correctAnswer":"A market segment","questionType":"MCQ","explanation":{"correct_reason":"Tarnvale has divided the laundry market and selected one group with shared characteristics, namely busy city professionals aged 25 to 40, which makes that group a market segment.","distractor_reasons":{"A":"The mass market means aiming at nearly all buyers, but Tarnvale deliberately excludes hotels, hospitals and other groups. The evidence in the scenario does not support this choice.","B":"Tarnvale has divided the laundry market and selected one group with shared characteristics, namely busy city professionals aged 25 to 40, which makes that group a market segment.","C":"A distribution channel is the route a product takes from producer to customer, not a group of buyers with shared needs.","D":"A product portfolio is the collection of products a firm offers, whereas Tarnvale offers one service to one defined group."}}},{"id":"P1_U3_MCQ_1306","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1306","question":"Oakmere Audiology has 900 customers who each pay an average of $1,450 for hearing aids. The clinic's records show that customers aged over 70 generate 60% of its revenue. What revenue comes from customers aged over 70?","options":{"A":"$522,000","B":"$870,000","C":"$783,000","D":"$1,305,000"},"correctOption":"C","correctAnswer":"$783,000","questionType":"MCQ","explanation":{"correct_reason":"Total revenue is 900 customers multiplied by $1,450, which equals $1,305,000, and 60% of that figure is $783,000 earned from the over-70 group.","distractor_reasons":{"A":"$522,000 is 40% of total revenue, so it is the share earned from customers aged 70 and under rather than the over-70 group.","B":"$870,000 would need 600 customers paying $1,450 each, but only 540 customers represent 60% of the 900 total. This reasoning does not fit the situation of the firm.","C":"Total revenue is 900 customers multiplied by $1,450, which equals $1,305,000, and 60% of that figure is $783,000 earned from the over-70 group.","D":"$1,305,000 is the clinic's entire revenue from all 900 customers, before the 60% share is applied. That is not consistent with what the scenario describes."}}},{"id":"P1_U3_MCQ_1307","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1307","question":"Rookery Toys lost 18% of its sales in one year after two discount chains opened nearby and cut prices on similar toys. Rookery kept its own prices unchanged and now offers free gift wrapping. Which statement best explains the fall in sales?","options":{"A":"Demand for toys collapsed across the whole country","B":"Rookery raised its prices above those of its rivals","C":"Rookery stopped all advertising during the year","D":"Rivals sold similar toys more cheaply, so price-sensitive customers switched"},"correctOption":"D","correctAnswer":"Rivals sold similar toys more cheaply, so price-sensitive customers switched","questionType":"MCQ","explanation":{"correct_reason":"The two new discount chains sold similar toys at lower prices, so customers who cared most about price switched, which explains the 18% fall in Rookery's sales.","distractor_reasons":{"A":"Nothing in the stem suggests a national collapse in toy demand; the change is local and follows the arrival of two discount chains.","B":"Rookery kept its prices unchanged, so a price rise by Rookery cannot be the cause of the lost sales. Such a result would not follow from the details given here.","C":"The stem does not mention advertising, and the timing links the lost sales to new rivals cutting prices. That is not consistent with what the scenario describes.","D":"The two new discount chains sold similar toys at lower prices, so customers who cared most about price switched, which explains the 18% fall in Rookery's sales."}}},{"id":"P1_U3_MCQ_1308","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1308","question":"Paprika Gate Spices surveyed 500 cooks and discovered they wanted smaller jars that fit on a spice rack. It redesigned its packaging around that finding and sales rose 22% the following year. Which approach to marketing is described here?","options":{"A":"Market orientation, because decisions began with customer research","B":"Product orientation, because the firm changed its packaging design","C":"Sales orientation, because the firm relied on heavy advertising","D":"Production orientation, because packaging is part of production"},"correctOption":"A","correctAnswer":"Market orientation, because decisions began with customer research","questionType":"MCQ","explanation":{"correct_reason":"The firm started by researching what 500 cooks wanted and then changed its product to match, which is market orientation because customer needs drive the decision.","distractor_reasons":{"A":"The firm started by researching what 500 cooks wanted and then changed its product to match, which is market orientation because customer needs drive the decision.","B":"Product orientation means decisions are driven by what the firm can make, yet here the redesign followed research into customer preferences.","C":"Sales orientation relies on aggressive selling of whatever is produced, but Paprika Gate changed the product to suit researched demand.","D":"Production orientation focuses on efficient output, whereas the stem shows the firm adapting its packaging to a customer complaint. That is why it is not the best answer here."}}},{"id":"P1_U3_MCQ_1309","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1309","question":"Dunlowe Garden Tools sold $2.4 million of tools when the garden tool market was worth $40 million. Last year its sales were $2.7 million and the market had grown to $54 million. What happened to Dunlowe's market share?","options":{"A":"It rose from 6% to 6.75%","B":"It stayed at 6%","C":"It fell from 6% to 5%","D":"It fell from 6% to 4.5%"},"correctOption":"C","correctAnswer":"It fell from 6% to 5%","questionType":"MCQ","explanation":{"correct_reason":"Market share was $2.4 million out of $40 million, or 6%, and became $2.7 million out of $54 million, or 5%, so the share fell by one percentage point.","distractor_reasons":{"A":"6.75% treats the $2.7 million as a share of the old $40 million market instead of the new $54 million market.","B":"Sales grew by $300,000 but the market grew faster, so the share could not have stayed at 6%. The option therefore fails to match the details of the scenario.","C":"Market share was $2.4 million out of $40 million, or 6%, and became $2.7 million out of $54 million, or 5%, so the share fell by one percentage point.","D":"4.5% would require sales of about $2.43 million in the $54 million market, not the $2.7 million actually achieved. This makes the option unsuitable for the scenario described."}}},{"id":"P1_U3_MCQ_1310","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1310","question":"Pellow Ice Cream aims to hold 15% of a regional ice cream market that is forecast to be worth $8.4 million next year. The owner needs a sales target to give the production team. What value of sales must Pellow achieve to meet the aim?","options":{"A":"$840,000","B":"$1,400,000","C":"$12,600,000","D":"$1,260,000"},"correctOption":"D","correctAnswer":"$1,260,000","questionType":"MCQ","explanation":{"correct_reason":"A 15% share of an $8.4 million market is 0.15 multiplied by $8,400,000, which equals $1,260,000 of sales for the year.","distractor_reasons":{"A":"$840,000 is 10% of the market, which would meet a 10% share target rather than the 15% aim in the stem.","B":"$1,400,000 would be a 16.7% share, so it does not match the 15% target the owner has set. That is why it is not the best answer here.","C":"$12,600,000 multiplies the market by 1.5 rather than taking 15% of it, so it is ten times too large. This makes the option unsuitable for the scenario described.","D":"A 15% share of an $8.4 million market is 0.15 multiplied by $8,400,000, which equals $1,260,000 of sales for the year."}}},{"id":"P1_U3_MCQ_1311","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1311","question":"Cranbourne Kitchens charges $22,000 for a fitted kitchen, about $3,000 more than unbranded rivals, and still has a waiting list. Customers mention the ten-year guarantee and the firm's showroom reputation. Which benefit of branding does this show?","options":{"A":"Branding can support a higher price and build customer loyalty","B":"Branding lowers the fixed costs of production","C":"Branding removes the need for any market research","D":"Branding guarantees a larger market share than every rival"},"correctOption":"A","correctAnswer":"Branding can support a higher price and build customer loyalty","questionType":"MCQ","explanation":{"correct_reason":"Customers accept a $3,000 premium because the brand signals a ten-year guarantee and a trusted showroom, so branding supports higher prices and encourages loyalty.","distractor_reasons":{"A":"Customers accept a $3,000 premium because the brand signals a ten-year guarantee and a trusted showroom, so branding supports higher prices and encourages loyalty.","B":"Branding affects how customers value the product, but it does not reduce the fixed costs of making or fitting kitchens.","C":"Cranbourne still needs research to understand buyers, and the stem shows no evidence that branding replaced it. The evidence in the scenario does not support this choice.","D":"A strong brand may help win share, but no brand can guarantee a larger share than every rival in the market."}}},{"id":"P1_U3_MCQ_1312","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1312","question":"Wexden Shoe Repairs completes 1,600 jobs a month. Of these, 640 are express while-you-wait repairs and 560 are standard repairs, with the remainder being contract work for local offices. What percentage of the monthly jobs is contract work?","options":{"A":"20%","B":"25%","C":"35%","D":"40%"},"correctOption":"B","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"Express and standard repairs total 1,200 jobs, leaving 400 contract jobs, and 400 divided by 1,600 equals 0.25, which is 25% of monthly jobs.","distractor_reasons":{"A":"20% would mean only 320 contract jobs, but subtracting 640 and 560 from 1,600 leaves 400 jobs. This makes the option unsuitable for the scenario described.","B":"Express and standard repairs total 1,200 jobs, leaving 400 contract jobs, and 400 divided by 1,600 equals 0.25, which is 25% of monthly jobs.","C":"35% would mean 560 contract jobs, which is the number of standard repairs rather than contract work. So the option does not answer the question that was asked.","D":"40% would mean 640 contract jobs, which is the number of express repairs, so the subtraction has been muddled. This reasoning does not fit the situation of the firm."}}},{"id":"P1_U3_MCQ_1313","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1313","question":"Fenmoor Outdoor Gear saw sales of heavy waterproof jackets fall while lightweight shell jackets rose, even though the two cost about the same. Research linked the shift to milder winters and more people commuting by bicycle. Which explanation of changing customer needs fits best?","options":{"A":"The firm's production costs fell sharply","B":"Its main competitors withdrew from the market","C":"The government raised the price of jackets","D":"Customers' lifestyles and weather conditions changed what they valued"},"correctOption":"D","correctAnswer":"Customers' lifestyles and weather conditions changed what they valued","questionType":"MCQ","explanation":{"correct_reason":"Milder winters and more cycling changed how buyers used their jackets, so they now value light weight over heavy waterproofing, which is a change in customer needs.","distractor_reasons":{"A":"The stem says the two jackets cost about the same, so a fall in production costs does not explain the shift in demand.","B":"No competitor withdrawal is mentioned, and the research points to weather and commuting habits instead. So the option does not answer the question that was asked.","C":"No price change by government is described, and the two products were priced about the same. This reasoning does not fit the situation of the firm.","D":"Milder winters and more cycling changed how buyers used their jackets, so they now value light weight over heavy waterproofing, which is a change in customer needs."}}},{"id":"P1_U3_MCQ_1314","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1314","question":"Skerrow Travel knows that its ferry bookings, worth $3.6 million, represent 12% of the total ferry-booking market. The owner wants the size of the whole market before negotiating with a new partner. What is the total value of the market?","options":{"A":"$30 million","B":"$4.32 million","C":"$7.2 million","D":"$300 million"},"correctOption":"A","correctAnswer":"$30 million","questionType":"MCQ","explanation":{"correct_reason":"If $3.6 million is 12% of the market, the total is $3.6 million divided by 0.12, which equals $30 million for the whole ferry-booking market.","distractor_reasons":{"A":"If $3.6 million is 12% of the market, the total is $3.6 million divided by 0.12, which equals $30 million for the whole ferry-booking market.","B":"$4.32 million adds 20% to $3.6 million, which is not how a 12% share is converted into the size of the whole market.","C":"$7.2 million doubles the firm's own bookings, which would imply a 50% share rather than 12%. Such a result would not follow from the details given here.","D":"$300 million is ten times too large because it divides by 0.012 rather than by 0.12. That is not consistent with what the scenario describes."}}},{"id":"P1_U3_MCQ_1315","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1315","question":"Alderbrook Gin sends a handwritten note and a free tonic glass to any customer who buys three bottles within a year. The proportion of customers buying again rose from 20% to 34%. What is the main purpose of this tactic?","options":{"A":"To reduce the unit cost of producing each bottle","B":"To build customer loyalty so that buyers return","C":"To cut the firm's total spending on promotion","D":"To comply with consumer protection legislation"},"correctOption":"B","correctAnswer":"To build customer loyalty so that buyers return","questionType":"MCQ","explanation":{"correct_reason":"Rewarding repeat buyers with a note and a glass lifted repeat purchase from 20% to 34%, so the tactic builds loyalty and encourages customers to come back.","distractor_reasons":{"A":"Sending gifts adds cost per customer, and nothing in the stem suggests the cost of producing a bottle fell. This reasoning does not fit the situation of the firm.","B":"Rewarding repeat buyers with a note and a glass lifted repeat purchase from 20% to 34%, so the tactic builds loyalty and encourages customers to come back.","C":"The notes and glasses cost money, so this tactic raises promotional spending rather than cutting it. That is not consistent with what the scenario describes.","D":"Consumer protection law does not require firms to reward repeat purchases, so compliance is not the purpose. The option therefore fails to match the details of the scenario."}}},{"id":"P1_U3_MCQ_1316","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1316","question":"Birchmarlow Stationery faces a rival selling identical notebooks 40 cents cheaper. Marlow keeps its price and instead promises next-day delivery and a free pen with every order. Which response to competition is Marlow using?","options":{"A":"Price skimming","B":"Market segmentation","C":"Non-price competition","D":"Product orientation"},"correctOption":"C","correctAnswer":"Non-price competition","questionType":"MCQ","explanation":{"correct_reason":"Marlow refuses to match the rival's lower price and competes on delivery speed and a free pen instead, which is competition on factors other than price.","distractor_reasons":{"A":"Price skimming means launching at a high price and lowering it later, not competing through service and gifts. Such a result would not follow from the details given here.","B":"Market segmentation is dividing buyers into groups, which is not the response described here. That is not consistent with what the scenario describes.","C":"Marlow refuses to match the rival's lower price and competes on delivery speed and a free pen instead, which is competition on factors other than price.","D":"Product orientation is about ignoring customer research, not about how a firm competes with a cheaper rival. That is why it is not the best answer here."}}},{"id":"P1_U3_MCQ_1317","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1317","question":"Trelanyon Wetsuits finds that 70% of its customers are surfers aged 16 to 24 and 30% are families. The owner plans to drop the children's range and concentrate only on young surfers. What is the main risk of this decision?","options":{"A":"It loses the family segment's revenue and depends more heavily on one group","B":"It will certainly increase total sales next year","C":"It will reduce the quality of the wetsuits it makes","D":"It will have to stop all promotion immediately"},"correctOption":"A","correctAnswer":"It loses the family segment's revenue and depends more heavily on one group","questionType":"MCQ","explanation":{"correct_reason":"Dropping the children's range removes the 30% of customers who are families, so revenue falls and the firm becomes more dependent on young surfers alone.","distractor_reasons":{"A":"Dropping the children's range removes the 30% of customers who are families, so revenue falls and the firm becomes more dependent on young surfers alone.","B":"Removing a product range is unlikely to raise total sales automatically, and it definitely ends the family revenue stream. The option therefore fails to match the details of the scenario.","C":"Stopping production of children's wetsuits does not by itself change the quality of the adult wetsuits. That is why it is not the best answer here.","D":"The firm can still promote to young surfers, so ending all promotion is not a necessary consequence. This makes the option unsuitable for the scenario described."}}},{"id":"P1_U3_MCQ_1318","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1318","question":"Ibbotson Hardware designed a paint that dries in ten minutes, but sales are poor because DIY customers say the colour range is too small and the tins are hard to open. The firm did no research before the launch. What does this case illustrate?","options":{"A":"Market research guarantees commercial success","B":"Customers always resist new technology","C":"A product-oriented firm may fail because it ignored customer needs","D":"A wide colour range always raises production costs"},"correctOption":"C","correctAnswer":"A product-oriented firm may fail because it ignored customer needs","questionType":"MCQ","explanation":{"correct_reason":"Ibbotson concentrated on a technical feature it could make and launched without research, so it missed what customers wanted, which is the weakness of product orientation.","distractor_reasons":{"A":"The firm did no research and the launch failed, so this case shows the opposite of research guaranteeing success. The option therefore fails to match the details of the scenario.","B":"Customers did not reject quick-drying paint as such; they objected to a poor colour range and awkward tins. That is why it is not the best answer here.","C":"Ibbotson concentrated on a technical feature it could make and launched without research, so it missed what customers wanted, which is the weakness of product orientation.","D":"The stem gives no cost data, and the failure is about unmet customer needs rather than the cost of colours."}}},{"id":"P1_U3_MCQ_1319","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1319","question":"Harrowridge Bicycles sold $5.4 million of bicycles in a market worth $90 million. Its nearest rival sold $6.3 million in the same market. By how many percentage points does Kestrel's market share trail the rival?","options":{"A":"0.9 percentage points","B":"1 percentage point","C":"6.3 percentage points","D":"7 percentage points"},"correctOption":"B","correctAnswer":"1 percentage point","questionType":"MCQ","explanation":{"correct_reason":"Kestrel holds $5.4 million out of $90 million, which is 6%, while the rival holds 7%, so Kestrel trails the rival by exactly 1 percentage point.","distractor_reasons":{"A":"0.9 of a point comes from subtracting the sales figures, but the gap must be measured after converting each to a share of $90 million.","B":"Kestrel holds $5.4 million out of $90 million, which is 6%, while the rival holds 7%, so Kestrel trails the rival by exactly 1 percentage point.","C":"6.3 points mistakes the rival's $6.3 million of sales for a percentage share of the market. The evidence in the scenario does not support this choice.","D":"7 points is the rival's own market share, not the gap between the rival and Kestrel. So the option does not answer the question that was asked."}}},{"id":"P1_U3_MCQ_1320","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1320","question":"Lulling Dairy is studying the lactose-free milk segment. Of 40,000 local households, 6,000 buy lactose-free products each week, and each buying household spends about $120 a year. What is the maximum annual revenue available from this segment?","options":{"A":"$90,000","B":"$480,000","C":"$4,800,000","D":"$720,000"},"correctOption":"D","correctAnswer":"$720,000","questionType":"MCQ","explanation":{"correct_reason":"Only the 6,000 households that already buy lactose-free products matter, and 6,000 multiplied by $120 a year gives a maximum segment revenue of $720,000.","distractor_reasons":{"A":"$90,000 is not derived from the stem figures and is far below what 6,000 households spending $120 each would generate.","B":"$480,000 would need 4,000 buying households rather than the 6,000 identified in the research. The evidence in the scenario does not support this choice.","C":"$4,800,000 multiplies all 40,000 households by $120, including the 34,000 that never buy lactose-free milk. So the option does not answer the question that was asked.","D":"Only the 6,000 households that already buy lactose-free products matter, and 6,000 multiplied by $120 a year gives a maximum segment revenue of $720,000."}}},{"id":"P1_U3_MCQ_1321","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1321","question":"Pennard Pottery makes 40 handmade mugs a week for one cafe chain, which pays $34 a mug. Larger potteries make thousands of mugs a week and sell them for about $6 each. Which advantage of niche marketing does Pennard enjoy?","options":{"A":"It benefits from very large economies of scale","B":"It can charge a high price for specialised output","C":"It spreads risk across many different markets","D":"It needs no understanding of its customers"},"correctOption":"B","correctAnswer":"It can charge a high price for specialised output","questionType":"MCQ","explanation":{"correct_reason":"Pennard makes a small number of handmade mugs for one specialist buyer, which lets it charge $34 rather than the $6 charged for mass-produced mugs.","distractor_reasons":{"A":"Producing only 40 mugs a week is far too small to create economies of scale, and the larger potteries hold that advantage.","B":"Pennard makes a small number of handmade mugs for one specialist buyer, which lets it charge $34 rather than the $6 charged for mass-produced mugs.","C":"Selling to one cafe chain concentrates risk rather than spreading it across many markets. This reasoning does not fit the situation of the firm.","D":"A niche firm must understand its buyer's needs closely, since the single customer can easily take its business elsewhere. Such a result would not follow from the details given here."}}},{"id":"P1_U3_MCQ_1322","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1322","question":"Greyling Optics finds that 70% of customers now order glasses online and collect them from a nearby pharmacy rather than visiting the store twice. The firm keeps the collection point open despite the cost. Which customer need is it meeting?","options":{"A":"A wider choice of frames","B":"Lower prices","C":"Personal advice from opticians","D":"Convenience"},"correctOption":"D","correctAnswer":"Convenience","questionType":"MCQ","explanation":{"correct_reason":"Customers can order online and pick up nearby instead of making two store visits, so Greyling is meeting their need for convenience in buying and collecting.","distractor_reasons":{"A":"The stem mentions collection, not an increase in the number of frame styles available. So the option does not answer the question that was asked.","B":"No price information is given, so the collection point cannot be explained as a way of cutting prices. This reasoning does not fit the situation of the firm.","C":"Collecting from a pharmacy reduces contact with opticians, so personal advice is not the need being served. Such a result would not follow from the details given here.","D":"Customers can order online and pick up nearby instead of making two store visits, so Greyling is meeting their need for convenience in buying and collecting."}}},{"id":"P1_U3_MCQ_1323","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1323","question":"Sablewood Mattresses sells 1,250 mattresses a year. It wants to raise its share of the local market from 5% to 8% by volume, assuming the total market stays at 25,000 mattresses. How many extra mattresses must it sell to reach the target?","options":{"A":"200","B":"500","C":"750","D":"2,000"},"correctOption":"C","correctAnswer":"750","questionType":"MCQ","explanation":{"correct_reason":"The target rise is 3 percentage points of 25,000 mattresses, and 0.03 multiplied by 25,000 gives 750 extra mattresses a year.","distractor_reasons":{"A":"200 mattresses would add only 0.8 of a percentage point, well short of the 3 point rise needed. This reasoning does not fit the situation of the firm.","B":"500 mattresses would take the share to 7%, not to the 8% target in the stem. Such a result would not follow from the details given here.","C":"The target rise is 3 percentage points of 25,000 mattresses, and 0.03 multiplied by 25,000 gives 750 extra mattresses a year.","D":"2,000 mattresses would be a rise of 8 percentage points, which would double the intended target. The option therefore fails to match the details of the scenario."}}},{"id":"P1_U3_MCQ_1324","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1324","question":"Corrin Hill Whisky's sales to people aged 18 to 30 fell 30% in five years while sales to over-50s rose. The firm now runs tasting events in hotels instead of advertising in nightclubs. Which change in the market is it responding to?","options":{"A":"An ageing customer base with different tastes and spending habits","B":"A fall in the total number of whisky drinkers","C":"A rise in the cost of the barley it buys","D":"New laws banning alcohol advertising"},"correctOption":"A","correctAnswer":"An ageing customer base with different tastes and spending habits","questionType":"MCQ","explanation":{"correct_reason":"Sales are shifting from younger to older buyers, so the firm moved its promotion to hotel tasting events that suit the tastes and habits of an older customer base.","distractor_reasons":{"A":"Sales are shifting from younger to older buyers, so the firm moved its promotion to hotel tasting events that suit the tastes and habits of an older customer base.","B":"Total drinkers may not have fallen, since sales to the over-50s rose while only the younger group declined. That is not consistent with what the scenario describes.","C":"The stem gives no cost data, and a rise in barley costs would not explain moving events to hotels. The option therefore fails to match the details of the scenario.","D":"No advertising ban is mentioned, and the firm is still promoting, just through a different channel. That is why it is not the best answer here."}}},{"id":"P1_U3_MCQ_1325","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1325","question":"Wrenfold Childcare raised its fees by 5% and its waiting list still grew, because parents valued the key-person policy and daily photo updates. Which explanation of customer choice does this support?","options":{"A":"Parents always choose the cheapest childcare provider","B":"Fee rises reduce demand in every childcare market","C":"Parents value service quality and trust more than the lowest price","D":"Waiting lists are caused by excess spare capacity"},"correctOption":"C","correctAnswer":"Parents value service quality and trust more than the lowest price","questionType":"MCQ","explanation":{"correct_reason":"Parents accepted a 5% fee rise because they valued the key-person policy and daily updates, showing that service quality and trust can outweigh price.","distractor_reasons":{"A":"The provider is now 5% more expensive yet demand rose, so price is clearly not the only factor. That is not consistent with what the scenario describes.","B":"The fee rise did not reduce demand here; the waiting list actually grew after the increase. The option therefore fails to match the details of the scenario.","C":"Parents accepted a 5% fee rise because they valued the key-person policy and daily updates, showing that service quality and trust can outweigh price.","D":"A waiting list indicates that demand exceeds places, which is the opposite of excess spare capacity. This makes the option unsuitable for the scenario described."}}},{"id":"P1_U3_MCQ_1326","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1326","question":"Thistlewood Snacks wants to know whether shoppers prefer its new lime flavour. Staff stand in a supermarket and ask 300 shoppers to taste both flavours and say which they would buy. Which type of research is this?","options":{"A":"Primary research using a taste test","B":"Secondary research using a trade journal report","C":"Secondary research using government statistics","D":"Desk research using the firm's own sales records"},"correctOption":"A","correctAnswer":"Primary research using a taste test","questionType":"MCQ","explanation":{"correct_reason":"The firm collects new information directly from 300 shoppers by asking them to taste the product, which is primary research carried out for its own purpose.","distractor_reasons":{"A":"The firm collects new information directly from 300 shoppers by asking them to taste the product, which is primary research carried out for its own purpose.","B":"A trade journal report is already published data collected by someone else, so it would be secondary research. That is why it is not the best answer here.","C":"Government statistics are secondary data, whereas the stem describes fresh data gathered from shoppers. This makes the option unsuitable for the scenario described.","D":"The firm's own sales records are internal secondary data, not a taste test with new respondents. The evidence in the scenario does not support this choice."}}},{"id":"P1_U3_MCQ_1327","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1327","question":"Braddock Footwear posted questionnaires to 2,500 customers and received 425 completed replies within three weeks. The marketing team wants to judge how much weight to give the findings. What was the response rate?","options":{"A":"8.5%","B":"15%","C":"25%","D":"17%"},"correctOption":"D","correctAnswer":"17%","questionType":"MCQ","explanation":{"correct_reason":"The response rate is the 425 replies divided by the 2,500 questionnaires sent, which equals 0.17, or 17% of the customers who were contacted.","distractor_reasons":{"A":"8.5% is half the correct figure and would result from dividing 425 by 5,000 rather than 2,500. That is why it is not the best answer here.","B":"15% would mean 375 replies arrived, which is 50 fewer than the 425 actually received. This makes the option unsuitable for the scenario described.","C":"25% would require 625 replies, well above the number the survey actually produced. The evidence in the scenario does not support this choice.","D":"The response rate is the 425 replies divided by the 2,500 questionnaires sent, which equals 0.17, or 17% of the customers who were contacted."}}},{"id":"P1_U3_MCQ_1328","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1328","question":"Colwyn Kitchenware numbers all 8,000 customers on its database and uses a computer to pick 400 of them purely by chance to receive a survey. What is this selection method called?","options":{"A":"A census of all customers","B":"Random sampling","C":"Secondary data analysis","D":"A focus group"},"correctOption":"B","correctAnswer":"Random sampling","questionType":"MCQ","explanation":{"correct_reason":"Every customer has an equal chance of being picked because a computer selects 400 names purely by chance, which is random sampling from the customer database.","distractor_reasons":{"A":"A census would question all 8,000 customers, but only 400 are being selected. This makes the option unsuitable for the scenario described.","B":"Every customer has an equal chance of being picked because a computer selects 400 names purely by chance, which is random sampling from the customer database.","C":"Secondary data analysis uses information already collected by others, whereas this survey gathers new data. So the option does not answer the question that was asked.","D":"A focus group is a small guided discussion, not a computer selection of 400 customers. This reasoning does not fit the situation of the firm."}}},{"id":"P1_U3_MCQ_1329","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1329","question":"Hesperus Cosmetics tested a new lipstick on 250 shoppers in one city. Of these, 70 said they would buy it at $14. The firm has 20,000 similar shoppers in other cities. At the same rate, what revenue could it expect from them?","options":{"A":"$3,500","B":"$39,200","C":"$280,000","D":"$78,400"},"correctOption":"D","correctAnswer":"$78,400","questionType":"MCQ","explanation":{"correct_reason":"70 of 250 shoppers is 28%, and 28% of 20,000 shoppers is 5,600 buyers; 5,600 multiplied by $14 gives $78,400 of expected revenue.","distractor_reasons":{"A":"$3,500 treats the 250 shoppers as buyers at $14 each instead of scaling the 28% rate to 20,000 shoppers. The evidence in the scenario does not support this choice.","B":"$39,200 is half the correct answer, arising from using 2,800 buyers rather than the 5,600 the sample implies. So the option does not answer the question that was asked.","C":"$280,000 multiplies all 20,000 shoppers by $14 and wrongly assumes every one of them would buy. This reasoning does not fit the situation of the firm.","D":"70 of 250 shoppers is 28%, and 28% of 20,000 shoppers is 5,600 buyers; 5,600 multiplied by $14 gives $78,400 of expected revenue."}}},{"id":"P1_U3_MCQ_1330","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1330","question":"Millrace Flour interviewed 12 bakery owners for an hour each, asking why they had switched flour suppliers. The answers were detailed opinions and complaints rather than numbers. What kind of data did Millrace collect?","options":{"A":"Quantitative data","B":"Qualitative data","C":"Secondary data","D":"Census data"},"correctOption":"B","correctAnswer":"Qualitative data","questionType":"MCQ","explanation":{"correct_reason":"The interviews produced detailed opinions and reasons rather than numerical measurements, which makes the information collected qualitative data. Such a result would not follow from the details given here.","distractor_reasons":{"A":"Quantitative data is numerical, but the stem stresses opinions and complaints rather than figures. So the option does not answer the question that was asked.","B":"The interviews produced detailed opinions and reasons rather than numerical measurements, which makes the information collected qualitative data. Such a result would not follow from the details given here.","C":"The firm gathered the views itself rather than using published information, so the data is primary. Such a result would not follow from the details given here.","D":"A census requires every member of the population to be questioned, yet only 12 owners were interviewed. That is not consistent with what the scenario describes."}}},{"id":"P1_U3_MCQ_1331","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1331","question":"Ormsby Saddlery paid a research agency $4,800 to run a postal survey of 1,200 riders. The owner wants to compare this with the cost of other methods. What was the average cost per questionnaire sent?","options":{"A":"$4.00","B":"$0.40","C":"$40.00","D":"$4,800"},"correctOption":"A","correctAnswer":"$4.00","questionType":"MCQ","explanation":{"correct_reason":"The total cost of $4,800 divided by the 1,200 questionnaires sent gives an average cost of $4.00 for each questionnaire posted.","distractor_reasons":{"A":"The total cost of $4,800 divided by the 1,200 questionnaires sent gives an average cost of $4.00 for each questionnaire posted.","B":"$0.40 places the decimal point one place too far left, making the survey appear ten times cheaper than it was.","C":"$40.00 places the decimal point one place too far right, so it overstates the cost by a factor of ten.","D":"$4,800 is the total bill for the whole survey, not the cost of a single questionnaire. The option therefore fails to match the details of the scenario."}}},{"id":"P1_U3_MCQ_1332","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1332","question":"Pinegrove Vitamins surveyed 30 customers out of 15,000 and found that 90% would buy a new supplement. The manager now wants to launch nationally on this evidence. What is the main weakness of the research?","options":{"A":"The survey used primary data instead of secondary data","B":"A percentage cannot be calculated from 30 replies","C":"The sample is too small to represent 15,000 customers reliably","D":"The research cost more than the launch would earn"},"correctOption":"C","correctAnswer":"The sample is too small to represent 15,000 customers reliably","questionType":"MCQ","explanation":{"correct_reason":"Only 30 of 15,000 customers were asked, so the 90% result may be pure chance and cannot be trusted as a guide to the whole customer base.","distractor_reasons":{"A":"Primary data is appropriate for testing a new product, so using it is not a weakness in itself. Such a result would not follow from the details given here.","B":"A percentage can be calculated from any number of replies; 27 of 30 would give 90%. That is not consistent with what the scenario describes.","C":"Only 30 of 15,000 customers were asked, so the 90% result may be pure chance and cannot be trusted as a guide to the whole customer base.","D":"The stem gives no cost figures for the research or the launch, so this cannot be judged. That is why it is not the best answer here."}}},{"id":"P1_U3_MCQ_1333","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1333","question":"Ravenhill Scooters needs figures on the number of 14 to 17 year olds in three regions before choosing where to launch. It has a small budget and needs the data this week. Which source is most suitable?","options":{"A":"Government population statistics published online","B":"A questionnaire sent to 100 teenagers","C":"A focus group of eight parents","D":"Interviews with rival shop managers"},"correctOption":"A","correctAnswer":"Government population statistics published online","questionType":"MCQ","explanation":{"correct_reason":"Official population statistics already exist for every region, so they give the age data quickly and at almost no cost, which suits the tight budget and deadline.","distractor_reasons":{"A":"Official population statistics already exist for every region, so they give the age data quickly and at almost no cost, which suits the tight budget and deadline.","B":"A questionnaire to 100 teenagers would take time and would not reliably count the population of three regions. The option therefore fails to match the details of the scenario.","C":"Eight parents in a discussion group cannot provide regional population counts. That is why it is not the best answer here.","D":"Rival managers are unlikely to know regional population figures and may refuse to help a competitor. This makes the option unsuitable for the scenario described."}}},{"id":"P1_U3_MCQ_1334","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1334","question":"Shadwell Fishmongers asks customers: 'Our fresh fish is far better than supermarket fish, isn't it?' and records yes or no answers. The owner plans to use the results as proof of quality. What is the main problem with this question?","options":{"A":"It is a closed question, so the answers cannot be counted","B":"It asks about two different topics at once","C":"It uses a sample that is far too large","D":"It is a leading question that pushes respondents to agree"},"correctOption":"D","correctAnswer":"It is a leading question that pushes respondents to agree","questionType":"MCQ","explanation":{"correct_reason":"The wording suggests the answer the owner wants, so respondents are pushed towards saying yes and the results will overstate how good customers think the fish is.","distractor_reasons":{"A":"Closed questions can be counted easily, so that is a strength rather than the problem here. The option therefore fails to match the details of the scenario.","B":"The question compares fresh fish with supermarket fish, which is one topic rather than two. That is why it is not the best answer here.","C":"The stem gives no sample size, and a large sample would improve rather than damage accuracy. This makes the option unsuitable for the scenario described.","D":"The wording suggests the answer the owner wants, so respondents are pushed towards saying yes and the results will overstate how good customers think the fish is."}}},{"id":"P1_U3_MCQ_1335","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1335","question":"Tamsin Vale Jewellery tried its questionnaire on ten staff members before posting it to 2,000 customers, and rewrote two questions that people found confusing. Why is this step worthwhile?","options":{"A":"It increases the response rate by paying respondents","B":"It creates secondary data for the survey","C":"It finds unclear questions before the full survey is sent","D":"It decides which customers to exclude from the sample"},"correctOption":"C","correctAnswer":"It finds unclear questions before the full survey is sent","questionType":"MCQ","explanation":{"correct_reason":"Testing the questionnaire on ten staff showed which two questions were confusing, so they could be rewritten before the 2,000 customers saw the final version.","distractor_reasons":{"A":"No payment is mentioned, and a pilot test does not involve paying the people who complete the final survey. That is why it is not the best answer here.","B":"A pilot test produces feedback on the questions, not secondary data for analysis. This makes the option unsuitable for the scenario described.","C":"Testing the questionnaire on ten staff showed which two questions were confusing, so they could be rewritten before the 2,000 customers saw the final version.","D":"The pilot is about improving the questions, not about choosing which customers to leave out. So the option does not answer the question that was asked."}}},{"id":"P1_U3_MCQ_1336","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1336","question":"Uffcott Preserves is selling its new quince jelly in 15 shops in one county for three months before deciding whether to launch it across the country. Which method is the firm using, and why?","options":{"A":"Secondary research to compare competitors' prices","B":"Test marketing to check demand before full production","C":"A census to count every possible buyer","D":"Market segmentation to divide the county's shoppers"},"correctOption":"B","correctAnswer":"Test marketing to check demand before full production","questionType":"MCQ","explanation":{"correct_reason":"Selling the jelly in 15 shops for three months lets the firm measure real demand on a small scale before committing to national production and distribution.","distractor_reasons":{"A":"The firm is selling a new product rather than reading published price information, so this is not secondary research. This makes the option unsuitable for the scenario described.","B":"Selling the jelly in 15 shops for three months lets the firm measure real demand on a small scale before committing to national production and distribution.","C":"A census would require every potential buyer to be questioned, not a three-month trial in 15 shops. So the option does not answer the question that was asked.","D":"The trial measures sales rather than dividing shoppers into separate groups. This reasoning does not fit the situation of the firm."}}},{"id":"P1_U3_MCQ_1337","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1337","question":"Wandle Candles asks staff to count how many shoppers pick up each candle and how long they hold it, without asking questions or recording opinions. Which research method is this?","options":{"A":"A questionnaire","B":"Observation","C":"An interview","D":"A focus group"},"correctOption":"B","correctAnswer":"Observation","questionType":"MCQ","explanation":{"correct_reason":"Researchers are watching and counting what shoppers actually do without speaking to them, which is observation of behaviour inside the shop.","distractor_reasons":{"A":"A questionnaire requires shoppers to answer written questions, but no questions are asked here. The evidence in the scenario does not support this choice.","B":"Researchers are watching and counting what shoppers actually do without speaking to them, which is observation of behaviour inside the shop.","C":"An interview involves a conversation, whereas staff only watch and count behaviour. This reasoning does not fit the situation of the firm.","D":"A focus group is a guided discussion among selected people, not silent counting of shoppers. Such a result would not follow from the details given here."}}},{"id":"P1_U3_MCQ_1338","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1338","question":"Yarcombe Cider can run an online survey costing $1,800 with an expected 900 replies, or face-to-face interviews costing $3,600 for 300 replies. The owner wants the method with the lower cost for each reply. Which is it, and at what cost?","options":{"A":"The online survey at $2.00 per reply","B":"The interviews at $12.00 per reply","C":"The online survey at $0.50 per reply","D":"The interviews at $6.00 per reply"},"correctOption":"A","correctAnswer":"The online survey at $2.00 per reply","questionType":"MCQ","explanation":{"correct_reason":"The online survey costs $1,800 for 900 replies, which is $2.00 each, while the interviews cost $3,600 for 300 replies, which is $12.00 each.","distractor_reasons":{"A":"The online survey costs $1,800 for 900 replies, which is $2.00 each, while the interviews cost $3,600 for 300 replies, which is $12.00 each.","B":"The interviews do cost $12.00 a reply, but that is higher than $2.00, so they are not the lower-cost method.","C":"$0.50 comes from dividing 900 replies by $1,800, which reverses the calculation. Such a result would not follow from the details given here.","D":"$6.00 is wrong for both methods; the interviews work out at $3,600 divided by 300, which is $12.00. That is not consistent with what the scenario describes."}}},{"id":"P1_U3_MCQ_1339","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1339","question":"Zennor Bathrooms found a trade article from 2016 stating that most homeowners renovate their bathroom every eight years. The firm wants to use this to forecast demand in 2027. What is the main limitation of the data?","options":{"A":"Trade articles are always biased towards manufacturers","B":"The figure came from primary research","C":"It cannot be compared with any other data","D":"The data is old and may no longer reflect current behaviour"},"correctOption":"D","correctAnswer":"The data is old and may no longer reflect current behaviour","questionType":"MCQ","explanation":{"correct_reason":"A 2016 article describes behaviour more than a decade before 2027, so renovation habits may have changed and the forecast could be badly wrong.","distractor_reasons":{"A":"Trade articles can be biased, but the clearer problem here is the age of the data rather than who wrote it.","B":"Data published in an article is secondary, not primary, and its age is the key limitation. Such a result would not follow from the details given here.","C":"The figure could be compared with other sources, so that is not the main limitation. That is not consistent with what the scenario describes.","D":"A 2016 article describes behaviour more than a decade before 2027, so renovation habits may have changed and the forecast could be badly wrong."}}},{"id":"P1_U3_MCQ_1340","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1340","question":"Bellhaven Caravans wants numerical answers from 2,000 owners that can be counted and analysed quickly by one member of staff. Which question design is most suitable for this survey?","options":{"A":"Open questions inviting long written answers","B":"Unstructured interviews lasting an hour","C":"Closed questions with fixed answer choices","D":"A discussion group with no set questions"},"correctOption":"C","correctAnswer":"Closed questions with fixed answer choices","questionType":"MCQ","explanation":{"correct_reason":"Closed questions give every respondent the same fixed choices, so 2,000 replies can be counted and compared quickly without long written answers.","distractor_reasons":{"A":"Open questions produce long written answers that are slow to analyse for 2,000 respondents. Such a result would not follow from the details given here.","B":"Unstructured interviews take an hour each, which is impossible for 2,000 owners on a small budget. That is not consistent with what the scenario describes.","C":"Closed questions give every respondent the same fixed choices, so 2,000 replies can be counted and compared quickly without long written answers.","D":"A discussion group produces detailed opinions from a few people, not countable data from 2,000. That is why it is not the best answer here."}}},{"id":"P1_U3_MCQ_1341","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1341","question":"Cobbett Cheese surveys 1,600 shoppers, but 1,400 of them shop only at farmers' markets, while 80% of the firm's sales come from supermarkets. The manager treats the results as typical of all buyers. What is the main problem?","options":{"A":"The sample is too small to count","B":"Shoppers cannot answer questions about cheese","C":"The sample is not representative of the firm's actual customers","D":"The survey collected only qualitative data"},"correctOption":"C","correctAnswer":"The sample is not representative of the firm's actual customers","questionType":"MCQ","explanation":{"correct_reason":"Most respondents shop at farmers' markets although most of the firm's sales come from supermarkets, so the sample over-represents a group that is unusual for the business.","distractor_reasons":{"A":"1,600 respondents is a large sample, so the size of the group is not the weakness here. That is not consistent with what the scenario describes.","B":"Shoppers can clearly answer questions about cheese, and they did so in this survey. The option therefore fails to match the details of the scenario.","C":"Most respondents shop at farmers' markets although most of the firm's sales come from supermarkets, so the sample over-represents a group that is unusual for the business.","D":"The stem does not say what type of data was collected, and the obvious flaw is who was asked. This makes the option unsuitable for the scenario described."}}},{"id":"P1_U3_MCQ_1342","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1342","question":"Drayholt Pianos is developing a digital piano for beginners and wants feedback on the keyboard weight and the instruction booklet. Why might interviewing 20 beginners itself be better than buying a published market report?","options":{"A":"It is always cheaper than buying a report","B":"The questions can be designed around its own product and customers","C":"The answers are guaranteed to be unbiased","D":"It avoids the need to choose a sample"},"correctOption":"B","correctAnswer":"The questions can be designed around its own product and customers","questionType":"MCQ","explanation":{"correct_reason":"The firm can ask beginners exactly about its own keyboard and booklet, which a general published report would never cover in that much detail.","distractor_reasons":{"A":"Primary interviews are often more expensive than buying an existing report, so cost is not the advantage here. The option therefore fails to match the details of the scenario.","B":"The firm can ask beginners exactly about its own keyboard and booklet, which a general published report would never cover in that much detail.","C":"Interview answers can still be biased, for example if questions are leading, so no guarantee exists. This makes the option unsuitable for the scenario described.","D":"The firm still has to decide which 20 beginners to interview, so a selection is unavoidable. The evidence in the scenario does not support this choice."}}},{"id":"P1_U3_MCQ_1343","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1343","question":"Elverton Lamps asks every one of its 3,200 trade customers to complete a short online form about delivery times. The owner wants a complete picture with no customer left out. Which term describes this research?","options":{"A":"A census","B":"A sample survey","C":"Secondary research","D":"Test marketing"},"correctOption":"A","correctAnswer":"A census","questionType":"MCQ","explanation":{"correct_reason":"Every member of the population of 3,200 trade customers is asked to respond, which is a census rather than a survey of a selected group.","distractor_reasons":{"A":"Every member of the population of 3,200 trade customers is asked to respond, which is a census rather than a survey of a selected group.","B":"A sample survey would question only part of the 3,200 customers, but all of them are being asked. This makes the option unsuitable for the scenario described.","C":"The firm is collecting new information from its own customers, so this is primary research. The evidence in the scenario does not support this choice.","D":"Test marketing involves selling a product in a limited area, not surveying all trade customers. So the option does not answer the question that was asked."}}},{"id":"P1_U3_MCQ_1344","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1344","question":"Foxley Furnishings spent $9,000 on market research last year on total sales of $450,000. The finance manager wants to compare this with other overheads. What was research spending as a percentage of sales?","options":{"A":"0.2%","B":"5%","C":"20%","D":"2%"},"correctOption":"D","correctAnswer":"2%","questionType":"MCQ","explanation":{"correct_reason":"Research spending of $9,000 divided by sales of $450,000 equals 0.02, which is 2% of sales for the year. So the option does not answer the question that was asked.","distractor_reasons":{"A":"0.2% is ten times too small and would mean research spending of only $900. This makes the option unsuitable for the scenario described.","B":"5% would mean spending of $22,500, which is far more than the $9,000 actually spent. The evidence in the scenario does not support this choice.","C":"20% would mean spending $90,000 on research, ten times the real figure. So the option does not answer the question that was asked.","D":"Research spending of $9,000 divided by sales of $450,000 equals 0.02, which is 2% of sales for the year. So the option does not answer the question that was asked."}}},{"id":"P1_U3_MCQ_1345","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1345","question":"Gorsedd Slate invited eight builders to a two-hour discussion about roofing slate, led by a researcher who probed their views on weight, breakages and price. Which method is this, and what does it produce?","options":{"A":"A census, producing numerical data from all builders","B":"Test marketing, producing sales figures from a trial","C":"Observation, producing counts of builders' behaviour","D":"A focus group, producing detailed opinions from a small group"},"correctOption":"D","correctAnswer":"A focus group, producing detailed opinions from a small group","questionType":"MCQ","explanation":{"correct_reason":"Eight builders discussed the product under a researcher's guidance, which is a focus group and produces detailed opinions rather than numerical market data.","distractor_reasons":{"A":"A census would question every builder in the market, not a group of eight. The evidence in the scenario does not support this choice.","B":"No product is being sold in a trial, so no sales figures can come from this discussion. So the option does not answer the question that was asked.","C":"The builders are talking about their views, not being watched, so observation does not describe the method. This reasoning does not fit the situation of the firm.","D":"Eight builders discussed the product under a researcher's guidance, which is a focus group and produces detailed opinions rather than numerical market data."}}},{"id":"P1_U3_MCQ_1346","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1346","question":"Inglemere Honey surveys only the customers who follow its social media page, then claims the results represent all 5,000 buyers. Most of its sales come from farm shops and older customers. What is the main problem with the research?","options":{"A":"The sample is too large to analyse properly","B":"Social media information is always secondary data","C":"The sample is biased because it excludes customers who do not use social media","D":"The survey asks too many closed questions"},"correctOption":"C","correctAnswer":"The sample is biased because it excludes customers who do not use social media","questionType":"MCQ","explanation":{"correct_reason":"Only social media followers are asked, so older farm-shop buyers are left out and the results cannot represent all 5,000 customers fairly.","distractor_reasons":{"A":"The stem does not say the sample is too large, and the real issue is who is included. So the option does not answer the question that was asked.","B":"The firm is collecting its own responses, so the data is primary rather than secondary. This reasoning does not fit the situation of the firm.","C":"Only social media followers are asked, so older farm-shop buyers are left out and the results cannot represent all 5,000 customers fairly.","D":"The type of questions is not described, and the obvious flaw is the group that was chosen. That is not consistent with what the scenario describes."}}},{"id":"P1_U3_MCQ_1347","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1347","question":"Jarrow Bookbinders sent sample folders to 500 schools and 65 placed an order. It now plans to approach 4,000 similar schools. At the same rate, how many orders should it expect?","options":{"A":"260","B":"520","C":"650","D":"1,300"},"correctOption":"B","correctAnswer":"520","questionType":"MCQ","explanation":{"correct_reason":"65 orders from 500 schools is a rate of 13%, and 13% of the 4,000 schools it plans to approach gives an expected 520 orders.","distractor_reasons":{"A":"260 orders would be a rate of only 6.5%, half the rate the trial actually achieved. This reasoning does not fit the situation of the firm.","B":"65 orders from 500 schools is a rate of 13%, and 13% of the 4,000 schools it plans to approach gives an expected 520 orders.","C":"650 orders would need a 16.25% rate, which is well above the 13% observed. That is not consistent with what the scenario describes.","D":"1,300 orders would be a 32.5% rate, more than double the trial's response. The option therefore fails to match the details of the scenario."}}},{"id":"P1_U3_MCQ_1348","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1348","question":"Kilve Chocolates is unsure whether to sell its new salted caramel bar at $2.20 or $2.60. It runs a two-week trial in ten shops at each price and compares the volumes sold. What is the main purpose of this research?","options":{"A":"To see how demand responds to price before setting a national price","B":"To calculate the fixed costs of chocolate production","C":"To recruit new staff for the factory","D":"To meet a legal requirement on price labelling"},"correctOption":"A","correctAnswer":"To see how demand responds to price before setting a national price","questionType":"MCQ","explanation":{"correct_reason":"Testing two prices in ten shops for two weeks shows how many bars sell at $2.20 compared with $2.60, which helps the firm choose a national price.","distractor_reasons":{"A":"Testing two prices in ten shops for two weeks shows how many bars sell at $2.20 compared with $2.60, which helps the firm choose a national price.","B":"A sales trial at two prices does not reveal fixed costs such as factory rent, which come from the accounts.","C":"The trial is about customers and prices, not about finding or hiring production staff. The option therefore fails to match the details of the scenario.","D":"Price labelling law requires accurate labels, but it does not require firms to test two prices in shops. That is why it is not the best answer here."}}},{"id":"P1_U3_MCQ_1349","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1349","question":"Lowther Locksmiths needs national data on how many households rent rather than own their homes. Which is the best reason to use official statistics instead of running its own survey?","options":{"A":"Official statistics are already collected, so they are quicker and cheaper to obtain","B":"Official statistics are collected specifically for locksmiths","C":"Its own survey would be more objective","D":"Official statistics always match the firm's own customers"},"correctOption":"A","correctAnswer":"Official statistics are already collected, so they are quicker and cheaper to obtain","questionType":"MCQ","explanation":{"correct_reason":"The figures already exist, so the firm avoids the cost and delay of designing, posting and analysing its own survey of households across the country.","distractor_reasons":{"A":"The figures already exist, so the firm avoids the cost and delay of designing, posting and analysing its own survey of households across the country.","B":"Official statistics are collected for government purposes, not tailored to the needs of a small locksmith business. The option therefore fails to match the details of the scenario.","C":"A survey run by the firm itself is not automatically more objective, and it would certainly be slower and dearer.","D":"National figures describe all households and cannot be assumed to match the firm's own local customer base exactly. This makes the option unsuitable for the scenario described."}}},{"id":"P1_U3_MCQ_1350","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1350","question":"Mardenholt Motorhomes budgeted $12,000 for market research. It spent $5,400 on interviews and 40% of the budget on an online panel. How much of the research budget is unspent?","options":{"A":"$2,400","B":"$1,800","C":"$6,600","D":"$600"},"correctOption":"B","correctAnswer":"$1,800","questionType":"MCQ","explanation":{"correct_reason":"The online panel took 40% of $12,000, which is $4,800, and adding the $5,400 of interviews gives $10,200 spent, leaving $1,800 unspent.","distractor_reasons":{"A":"$2,400 is the amount left if only the interviews are deducted from the budget, ignoring the $4,800 panel. The option therefore fails to match the details of the scenario.","B":"The online panel took 40% of $12,000, which is $4,800, and adding the $5,400 of interviews gives $10,200 spent, leaving $1,800 unspent.","C":"$6,600 is the total spent on interviews and the panel combined, not the amount left over. This makes the option unsuitable for the scenario described.","D":"$600 is far too small; total spending of $10,200 leaves $1,800 of the $12,000 budget. The evidence in the scenario does not support this choice."}}},{"id":"P1_U3_MCQ_1351","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1351","question":"Nethergill Nurseries grows shrubs at an average cost of $7.20 each. The owner adds a 45% mark-up to set the trade price for garden centres. What selling price does this mark-up give?","options":{"A":"$7.65","B":"$10.00","C":"$11.52","D":"$10.44"},"correctOption":"D","correctAnswer":"$10.44","questionType":"MCQ","explanation":{"correct_reason":"A 45% mark-up on $7.20 is 0.45 multiplied by $7.20, which is $3.24, and adding this to the $7.20 cost gives a trade price of $10.44.","distractor_reasons":{"A":"$7.65 adds only 45 cents to the cost, which is a mark-up of about 6% rather than the 45% required.","B":"$10.00 is a convenient round price but would need a mark-up of $2.80, which is about 39% of cost. This makes the option unsuitable for the scenario described.","C":"$11.52 applies a 60% mark-up to $7.20 rather than the 45% stated in the stem. The evidence in the scenario does not support this choice.","D":"A 45% mark-up on $7.20 is 0.45 multiplied by $7.20, which is $3.24, and adding this to the $7.20 cost gives a trade price of $10.44."}}},{"id":"P1_U3_MCQ_1352","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1352","question":"Old Cutler Knives launches a new kitchen knife set at $19.99, well below its $34 cost-plus target, to win shelf space and encourage trial. It plans to raise the price after six months. Which pricing strategy is this?","options":{"A":"Price skimming","B":"Cost-plus pricing","C":"Penetration pricing","D":"Competitive pricing"},"correctOption":"C","correctAnswer":"Penetration pricing","questionType":"MCQ","explanation":{"correct_reason":"A low launch price of $19.99 is intended to attract buyers and win space on shelves before the price rises, which is penetration pricing.","distractor_reasons":{"A":"Price skimming starts high and falls later, which is the opposite of the low $19.99 launch price described. This makes the option unsuitable for the scenario described.","B":"Cost-plus pricing would give about $34, but the firm has deliberately set a much lower launch price. The evidence in the scenario does not support this choice.","C":"A low launch price of $19.99 is intended to attract buyers and win space on shelves before the price rises, which is penetration pricing.","D":"Competitive pricing follows rivals' prices, yet the stem explains the price by the need to win trial and shelf space."}}},{"id":"P1_U3_MCQ_1353","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1353","question":"Pemberwick Puzzles sells 30,000 jigsaws a year through three wholesalers, who then supply 400 independent shops. Pemberwick has no sales team of its own. What is the main advantage of this channel of distribution?","options":{"A":"Pemberwick keeps the full retail price of every jigsaw","B":"Wholesalers reach many small retailers at lower cost than a direct sales force","C":"Wholesalers take legal ownership of unsold stock only","D":"Pemberwick can control how each shop displays its puzzles"},"correctOption":"B","correctAnswer":"Wholesalers reach many small retailers at lower cost than a direct sales force","questionType":"MCQ","explanation":{"correct_reason":"Three wholesalers already serve 400 small shops, so Pemberwick gains wide coverage without paying for its own sales team to visit every retailer.","distractor_reasons":{"A":"Using wholesalers means Pemberwick sells at a trade price, so it gives up part of the retail price rather than keeping all of it.","B":"Three wholesalers already serve 400 small shops, so Pemberwick gains wide coverage without paying for its own sales team to visit every retailer.","C":"Wholesalers buy the stock outright, so unsold jigsaws are their risk, not a benefit limited to unsold items. This reasoning does not fit the situation of the firm.","D":"Display control is lost when an intermediary sells on to independent shops that decide their own layouts. Such a result would not follow from the details given here."}}},{"id":"P1_U3_MCQ_1354","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1354","question":"Quarrendon Quilts spent $8,000 on a magazine advert that produced 640 extra orders at an average of $45 each. The owner wants to know whether the advert paid for itself. What was the net gain after deducting the advert cost?","options":{"A":"$28,800","B":"$8,000","C":"$20,800","D":"$36,800"},"correctOption":"C","correctAnswer":"$20,800","questionType":"MCQ","explanation":{"correct_reason":"The extra orders brought in 640 multiplied by $45, which is $28,800, and deducting the $8,000 advert cost leaves a net gain of $20,800.","distractor_reasons":{"A":"$28,800 is the extra revenue from the orders before the $8,000 cost of the advert is deducted. So the option does not answer the question that was asked.","B":"$8,000 is the cost of the advert itself, not the gain it produced from the extra orders. This reasoning does not fit the situation of the firm.","C":"The extra orders brought in 640 multiplied by $45, which is $28,800, and deducting the $8,000 advert cost leaves a net gain of $20,800.","D":"$36,800 wrongly adds the advert cost to the extra revenue instead of subtracting it. That is not consistent with what the scenario describes."}}},{"id":"P1_U3_MCQ_1355","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1355","question":"Redmarley Ribbons' best-selling Christmas ribbon has sold at the same volume for five years, while rivals have copied the design and profits are flat. In which stage of the product life cycle is this ribbon?","options":{"A":"Maturity","B":"Introduction","C":"Growth","D":"Decline"},"correctOption":"A","correctAnswer":"Maturity","questionType":"MCQ","explanation":{"correct_reason":"Sales have levelled off for five years, competitors have copied the design and profits are flat, which are the typical signs of the maturity stage.","distractor_reasons":{"A":"Sales have levelled off for five years, competitors have copied the design and profits are flat, which are the typical signs of the maturity stage.","B":"Introduction would mean low and rising sales with heavy launch spending, not five years of steady volume. Such a result would not follow from the details given here.","C":"Growth would show sales rising quickly, whereas the ribbon's volume has stayed the same for five years. That is not consistent with what the scenario describes.","D":"Decline would mean falling sales and shrinking profits, but sales here are steady rather than falling. The option therefore fails to match the details of the scenario."}}},{"id":"P1_U3_MCQ_1356","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1356","question":"Stanbrook Sausages wants to reach families within 20 miles of its factory, has a limited budget and needs to announce a weekend offer. Which promotional medium is most suitable?","options":{"A":"National television advertising","B":"Sponsorship of a national football league","C":"Direct mail to every household in the country","D":"Local radio advertising"},"correctOption":"D","correctAnswer":"Local radio advertising","questionType":"MCQ","explanation":{"correct_reason":"Local radio covers the area around the factory at a modest cost and can announce a weekend offer quickly, which matches the target area and budget.","distractor_reasons":{"A":"National television would reach millions of viewers far outside the 20 mile area and would cost far more than the budget allows.","B":"Sponsoring a national football league is expensive and reaches fans across the country rather than local families. That is not consistent with what the scenario describes.","C":"Mailing every household in the country would waste most of the budget on people who cannot visit the factory. The option therefore fails to match the details of the scenario.","D":"Local radio covers the area around the factory at a modest cost and can announce a weekend offer quickly, which matches the target area and budget."}}},{"id":"P1_U3_MCQ_1357","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1357","question":"Thornbrook Tiles lists a price of $28 per square metre and offers retailers a 25% trade discount. A retailer orders 400 square metres at the discounted price. What does the retailer pay in total?","options":{"A":"$11,200","B":"$5,600","C":"$8,400","D":"$8,000"},"correctOption":"C","correctAnswer":"$8,400","questionType":"MCQ","explanation":{"correct_reason":"A 25% discount cuts the $28 list price to $21 a square metre, and 400 square metres multiplied by $21 gives a total payment of $8,400.","distractor_reasons":{"A":"$11,200 is 400 square metres at the full $28 list price, before the 25% trade discount is applied. That is not consistent with what the scenario describes.","B":"$5,600 would need a 50% discount, which is twice the 25% trade discount offered to retailers. The option therefore fails to match the details of the scenario.","C":"A 25% discount cuts the $28 list price to $21 a square metre, and 400 square metres multiplied by $21 gives a total payment of $8,400.","D":"$8,000 uses a price of $20 a square metre, which is a discount of about 28.6% rather than 25%. This makes the option unsuitable for the scenario described."}}},{"id":"P1_U3_MCQ_1358","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1358","question":"Ulverston Umbrellas redesigned its box to show a photograph of the umbrella open, list its wind rating and include a carrying loop. Which function of packaging does this mainly illustrate?","options":{"A":"Protecting the product during transport only","B":"Reducing the unit cost of production","C":"Meeting a legal requirement on labelling","D":"Communicating product information and attracting buyers"},"correctOption":"D","correctAnswer":"Communicating product information and attracting buyers","questionType":"MCQ","explanation":{"correct_reason":"The photograph, wind rating and carrying loop tell shoppers what the umbrella does and make the pack easier to spot, which is communication and attraction.","distractor_reasons":{"A":"Protection is a packaging function, but a photograph and a wind rating do nothing to protect the umbrella in transit.","B":"A more elaborate box is likely to cost more, so the redesign is not aimed at cutting unit costs. That is why it is not the best answer here.","C":"No law requires a wind rating or a photograph, so legal labelling is not the main purpose. This makes the option unsuitable for the scenario described.","D":"The photograph, wind rating and carrying loop tell shoppers what the umbrella does and make the pack easier to spot, which is communication and attraction."}}},{"id":"P1_U3_MCQ_1359","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1359","question":"Vineholt Vinegars sells 60% of its output through its own website, posting bottles directly to households, and 40% through farm shops. Which element of the marketing mix does the website mainly change?","options":{"A":"The pricing strategy","B":"The place, by creating a direct channel that bypasses retailers","C":"The product design","D":"The promotional sponsorship"},"correctOption":"B","correctAnswer":"The place, by creating a direct channel that bypasses retailers","questionType":"MCQ","explanation":{"correct_reason":"Selling through its own website means Vineholt deals directly with households instead of relying only on retailers, which changes the place element of the mix.","distractor_reasons":{"A":"The stem gives no prices, and a website does not by itself change how the vinegars are priced. That is why it is not the best answer here.","B":"Selling through its own website means Vineholt deals directly with households instead of relying only on retailers, which changes the place element of the mix.","C":"The product is still the same vinegar in the same bottle, so its design has not changed. The evidence in the scenario does not support this choice.","D":"Sponsorship is a promotional tool, not the element affected by selling directly online. So the option does not answer the question that was asked."}}},{"id":"P1_U3_MCQ_1360","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1360","question":"Whitcombe Watches sells 1,500 watches a year at $120 each. It raises the price to $132 and annual sales fall to 1,350 watches. What is the effect on sales revenue?","options":{"A":"A fall of $1,800","B":"A rise of $1,800","C":"A fall of $16,200","D":"No change at all"},"correctOption":"A","correctAnswer":"A fall of $1,800","questionType":"MCQ","explanation":{"correct_reason":"Revenue was 1,500 multiplied by $120, which is $180,000, and became 1,350 multiplied by $132, which is $178,200, so revenue fell by $1,800.","distractor_reasons":{"A":"Revenue was 1,500 multiplied by $120, which is $180,000, and became 1,350 multiplied by $132, which is $178,200, so revenue fell by $1,800.","B":"Revenue has not risen: $178,200 is lower than the original $180,000 by exactly $1,800. The evidence in the scenario does not support this choice.","C":"$16,200 is the fall in the number of watches sold multiplied by 10, which is not a revenue calculation. So the option does not answer the question that was asked.","D":"Revenue changed because the higher price did not fully make up for the 150 fewer watches sold. This reasoning does not fit the situation of the firm."}}},{"id":"P1_U3_MCQ_1361","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1361","question":"Yelland Yarns makes wool from the fleeces of a rare local sheep and prints the farm name on every label. Competitors sell imported yarn at half the price. Which element of the product is Yelland relying on?","options":{"A":"A lower price than its competitors","B":"Wider distribution through large chains","C":"Mass-market advertising on television","D":"A unique selling point based on origin and traceability"},"correctOption":"D","correctAnswer":"A unique selling point based on origin and traceability","questionType":"MCQ","explanation":{"correct_reason":"Rare local fleeces and a named farm on the label give buyers a reason to pay double the imported price, which is a unique selling point built on origin.","distractor_reasons":{"A":"Yelland charges about twice the price of imported yarn, so it is certainly not competing on low price. The evidence in the scenario does not support this choice.","B":"The stem gives no evidence about distribution, and yarn sold through large chains would usually be cheaper. So the option does not answer the question that was asked.","C":"No advertising is mentioned, and a small producer of rare wool would rarely fund television campaigns. This reasoning does not fit the situation of the firm.","D":"Rare local fleeces and a named farm on the label give buyers a reason to pay double the imported price, which is a unique selling point built on origin."}}},{"id":"P1_U3_MCQ_1362","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1362","question":"Zouch Zippers wants a profit of $2.40 on each zip. Its variable cost is $1.10 and it allocates $0.55 of fixed costs to each zip. What price should it set?","options":{"A":"$4.05","B":"$2.95","C":"$3.50","D":"$4.95"},"correctOption":"A","correctAnswer":"$4.05","questionType":"MCQ","explanation":{"correct_reason":"The price must cover the $1.10 variable cost, the $0.55 share of fixed costs and the $2.40 profit, which adds up to $4.05 per zip.","distractor_reasons":{"A":"The price must cover the $1.10 variable cost, the $0.55 share of fixed costs and the $2.40 profit, which adds up to $4.05 per zip.","B":"$2.95 covers the costs of $1.65 and adds only $1.30 of profit, well short of the $2.40 target. This reasoning does not fit the situation of the firm.","C":"$3.50 leaves $1.85 of profit after costs, which is less than the $2.40 the owner wants. Such a result would not follow from the details given here.","D":"$4.95 adds the figures incorrectly and would give $3.30 of profit, far above the target. That is not consistent with what the scenario describes."}}},{"id":"P1_U3_MCQ_1363","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1363","question":"Amberwell Ales offers pubs a deal in quiet January: buy five cases and receive a sixth case free. The brewery hopes pubs will stock and sell more of its beer during a slow month. Which element of the marketing mix is this?","options":{"A":"Public relations","B":"Sponsorship","C":"Sales promotion","D":"Product development"},"correctOption":"C","correctAnswer":"Sales promotion","questionType":"MCQ","explanation":{"correct_reason":"A short-term incentive of one free case for every five bought is a sales promotion designed to increase orders during a quiet month.","distractor_reasons":{"A":"Public relations builds goodwill through publicity and events, not through free cases given to buyers. This reasoning does not fit the situation of the firm.","B":"Sponsorship means paying to be linked to an event or team, which is not described in the stem. Such a result would not follow from the details given here.","C":"A short-term incentive of one free case for every five bought is a sales promotion designed to increase orders during a quiet month.","D":"The product itself is unchanged, since the deal only alters the terms on which cases are bought. The option therefore fails to match the details of the scenario."}}},{"id":"P1_U3_MCQ_1364","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1364","question":"Bickleigh Boats builds about 12 luxury boats a year, each made to one customer's specification and selling for around $90,000. Buyers want to discuss engines, wood and layout directly with the builder. Which distribution method is most suitable?","options":{"A":"Selling through a national chain of discount stores","B":"Direct selling, because each boat is built to an individual specification","C":"Selling through 200 small chandlers","D":"Selling through a wholesaler who supplies marinas"},"correctOption":"B","correctAnswer":"Direct selling, because each boat is built to an individual specification","questionType":"MCQ","explanation":{"correct_reason":"Only 12 boats a year are built to individual orders, so the builder must deal directly with each buyer to agree engines, wood and interior layout.","distractor_reasons":{"A":"Discount stores sell standard products in large volumes and cannot handle bespoke boats selling for $90,000 each. Such a result would not follow from the details given here.","B":"Only 12 boats a year are built to individual orders, so the builder must deal directly with each buyer to agree engines, wood and interior layout.","C":"Two hundred small chandlers would add cost and could not manage lengthy negotiations about each boat's specification. The option therefore fails to match the details of the scenario.","D":"A wholesaler adds another layer between builder and buyer, which works against the direct discussion customers want. That is why it is not the best answer here."}}},{"id":"P1_U3_MCQ_1365","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1365","question":"Cadgwith Crab wants to advertise its fresh crab to holidaymakers travelling along the coast road in summer. Its budget is small and the owner wants the message seen several times by the same visitors. Which promotional medium is most suitable?","options":{"A":"Roadside posters near popular beaches","B":"National newspaper adverts in winter","C":"Trade magazines for fishmongers","D":"Cinema adverts in inland cities"},"correctOption":"A","correctAnswer":"Roadside posters near popular beaches","questionType":"MCQ","explanation":{"correct_reason":"Holidaymakers drive along the coast road in summer, so roadside posters near popular beaches put the message in front of the right audience repeatedly at low cost.","distractor_reasons":{"A":"Holidaymakers drive along the coast road in summer, so roadside posters near popular beaches put the message in front of the right audience repeatedly at low cost.","B":"Winter national newspapers target the wrong season and reach a far wider audience than coastal visitors. The option therefore fails to match the details of the scenario.","C":"Fishmongers are trade buyers, not the holidaymakers to whom the fresh crab is being advertised. That is why it is not the best answer here.","D":"Inland cinemas reach people who are not on the coast and may never visit the area at all. This makes the option unsuitable for the scenario described."}}},{"id":"P1_U3_MCQ_1366","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1366","question":"Denholm Desks donates 50 desks to a local school and invites a newspaper to photograph the handover. The firm hopes the story will improve how local people see the business. Which promotional method is this?","options":{"A":"Sales promotion","B":"Personal selling","C":"Public relations","D":"Direct mail"},"correctOption":"C","correctAnswer":"Public relations","questionType":"MCQ","explanation":{"correct_reason":"Donating desks and generating favourable newspaper coverage is public relations, because it builds goodwill rather than directly selling a product.","distractor_reasons":{"A":"Sales promotion offers a short-term buying incentive such as a discount, which is not what a donation to a school provides.","B":"Personal selling involves staff persuading individual customers to buy, not a newspaper photograph of a donation. That is why it is not the best answer here.","C":"Donating desks and generating favourable newspaper coverage is public relations, because it builds goodwill rather than directly selling a product.","D":"Direct mail sends promotional material to named customers, whereas this story appears in the local press. The evidence in the scenario does not support this choice."}}},{"id":"P1_U3_MCQ_1367","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1367","question":"Eastmarsh Eggs checks the prices charged by three nearby farms every week and then sets its own price two cents below their average. Which pricing strategy is Eastmarsh using?","options":{"A":"Price skimming","B":"Cost-plus pricing","C":"Penetration pricing","D":"Competitive pricing"},"correctOption":"D","correctAnswer":"Competitive pricing","questionType":"MCQ","explanation":{"correct_reason":"Eastmarsh bases its price on what three nearby farms charge and then undercuts their average, which is pricing set in relation to competitors.","distractor_reasons":{"A":"Price skimming means launching high and reducing later, not tracking the prices of three local rivals. That is why it is not the best answer here.","B":"Cost-plus pricing is built from the firm's own costs, but Eastmarsh starts from rivals' prices instead. This makes the option unsuitable for the scenario described.","C":"Penetration pricing sets a low price to enter a market, while Eastmarsh simply follows and slightly undercuts the local average.","D":"Eastmarsh bases its price on what three nearby farms charge and then undercuts their average, which is pricing set in relation to competitors."}}},{"id":"P1_U3_MCQ_1368","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1368","question":"Framling Fruit Farm sells 70% of its 20,000 kg apple crop to wholesalers at $1.20 a kg, and sells the remaining 30% directly to shoppers at $2.00 a kg. What is its total revenue from the crop?","options":{"A":"$24,000","B":"$28,800","C":"$33,600","D":"$40,000"},"correctOption":"B","correctAnswer":"$28,800","questionType":"MCQ","explanation":{"correct_reason":"Wholesale sales are 14,000 kg at $1.20, giving $16,800, and direct sales are 6,000 kg at $2.00, giving $12,000, so total revenue is $28,800.","distractor_reasons":{"A":"$24,000 is the revenue if the whole 20,000 kg crop were sold at $1.20 to wholesalers only. This makes the option unsuitable for the scenario described.","B":"Wholesale sales are 14,000 kg at $1.20, giving $16,800, and direct sales are 6,000 kg at $2.00, giving $12,000, so total revenue is $28,800.","C":"$33,600 uses $1.68 for the wholesale part, which is not the $1.20 price given in the stem. So the option does not answer the question that was asked.","D":"$40,000 assumes all 20,000 kg are sold at the higher $2.00 direct price. This reasoning does not fit the situation of the firm."}}},{"id":"P1_U3_MCQ_1369","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1369","question":"Gweek Glass's range of coloured tumblers is in decline. The firm relaunches the same tumblers in a gift box with a new retro label aimed at younger buyers and sales begin to recover. Which strategy is this?","options":{"A":"Divestment to withdraw the product from the market","B":"An extension strategy to lengthen the product's life","C":"Price skimming to raise the launch price","D":"A cost-plus pricing review"},"correctOption":"B","correctAnswer":"An extension strategy to lengthen the product's life","questionType":"MCQ","explanation":{"correct_reason":"Repackaging and relabelling the tumblers for a new group of buyers gives a declining product fresh appeal, which is an extension strategy.","distractor_reasons":{"A":"Divestment means dropping the product, but Gweek has relaunched it rather than withdrawing it. The evidence in the scenario does not support this choice.","B":"Repackaging and relabelling the tumblers for a new group of buyers gives a declining product fresh appeal, which is an extension strategy.","C":"Price skimming is about setting a high initial price, not about finding new buyers for an old product. This reasoning does not fit the situation of the firm.","D":"No costs or prices are recalculated in the stem, and the change is to the product's presentation. Such a result would not follow from the details given here."}}},{"id":"P1_U3_MCQ_1370","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1370","question":"Hartland Hats sells online to customers in 14 countries and holds no shop stock, despatching everything from one small warehouse. Which is a benefit of this approach to place?","options":{"A":"Customers can try hats on before buying","B":"It removes all delivery costs","C":"It guarantees lower production costs","D":"It reaches customers in many countries without the cost of overseas shops"},"correctOption":"D","correctAnswer":"It reaches customers in many countries without the cost of overseas shops","questionType":"MCQ","explanation":{"correct_reason":"One warehouse and a website let Hartland serve buyers in 14 countries without paying rent and wages for shops in each of those markets.","distractor_reasons":{"A":"Buying online means customers cannot try a hat on first, which is a drawback rather than a benefit. So the option does not answer the question that was asked.","B":"Posting hats to 14 countries creates delivery costs; it certainly does not remove them. This reasoning does not fit the situation of the firm.","C":"Production costs depend on materials and labour, which an online shop does not change. Such a result would not follow from the details given here.","D":"One warehouse and a website let Hartland serve buyers in 14 countries without paying rent and wages for shops in each of those markets."}}},{"id":"P1_U3_MCQ_1371","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1371","question":"Ilsington Ironworks has fixed costs of $18,000 a year and makes 3,000 gates. Each gate uses $14 of materials and $6 of labour. What is the average total cost of one gate?","options":{"A":"$26.00","B":"$20.00","C":"$32.00","D":"$6.00"},"correctOption":"A","correctAnswer":"$26.00","questionType":"MCQ","explanation":{"correct_reason":"Total variable cost is $20 a gate, or $60,000 for 3,000 gates, and adding the $18,000 of fixed costs gives $78,000, which is $26.00 a gate.","distractor_reasons":{"A":"Total variable cost is $20 a gate, or $60,000 for 3,000 gates, and adding the $18,000 of fixed costs gives $78,000, which is $26.00 a gate.","B":"$20.00 is only the variable cost of materials and labour, leaving out the $18,000 of fixed costs. Such a result would not follow from the details given here.","C":"$32.00 would give total costs of $96,000, which is $18,000 more than the firm actually spends. That is not consistent with what the scenario describes.","D":"$6.00 is just the labour cost of one gate and ignores materials and fixed costs. The option therefore fails to match the details of the scenario."}}},{"id":"P1_U3_MCQ_1372","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1372","question":"Jesmond Jams wants hotels and restaurants to stock its 5 kg catering tubs. Its sales staff visit chefs, demonstrate recipes using the jam and negotiate annual supply contracts. Which promotional method is being used?","options":{"A":"Sales promotion","B":"Public relations","C":"Personal selling","D":"Sponsorship"},"correctOption":"C","correctAnswer":"Personal selling","questionType":"MCQ","explanation":{"correct_reason":"Sales staff meet chefs face to face, demonstrate the product and negotiate contracts, which is personal selling to business customers.","distractor_reasons":{"A":"Sales promotion is a short-term incentive such as money off, not a series of face-to-face meetings. Such a result would not follow from the details given here.","B":"Public relations seeks favourable publicity, whereas these staff are directly persuading named buyers. That is not consistent with what the scenario describes.","C":"Sales staff meet chefs face to face, demonstrate the product and negotiate contracts, which is personal selling to business customers.","D":"Sponsorship links the brand to an event or team, which is not described in the stem. That is why it is not the best answer here."}}},{"id":"P1_U3_MCQ_1373","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1373","question":"Kirkby Knitwear sells sweaters at $48 each. A retailer asks for a 20% discount on an order of 250 sweaters, and each sweater costs Kirkby $26 in variable costs. What profit does Kirkby make on this order?","options":{"A":"$2,400","B":"$5,500","C":"$3,100","D":"$3,840"},"correctOption":"C","correctAnswer":"$3,100","questionType":"MCQ","explanation":{"correct_reason":"A 20% discount cuts the price to $38.40, leaving $12.40 per sweater after the $26 cost, and 250 multiplied by $12.40 gives $3,100 of profit.","distractor_reasons":{"A":"$2,400 is the profit at the full $48 price, before the 20% discount is taken off. That is not consistent with what the scenario describes.","B":"$5,500 uses a margin of $22 a sweater, which ignores the $26 variable cost entirely. The option therefore fails to match the details of the scenario.","C":"A 20% discount cuts the price to $38.40, leaving $12.40 per sweater after the $26 cost, and 250 multiplied by $12.40 gives $3,100 of profit.","D":"$3,840 is the total revenue from the order after discount, not the profit left after costs. This makes the option unsuitable for the scenario described."}}},{"id":"P1_U3_MCQ_1374","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1374","question":"Lamorna Leather sells bags under three brand names at different prices: a budget line for students, a mid-range line and a hand-stitched luxury line. Why might it use several brands rather than one?","options":{"A":"To target different segments without damaging the luxury image","B":"To reduce the total cost of advertising to one name","C":"To simplify production to a single design","D":"To avoid the need for market research"},"correctOption":"A","correctAnswer":"To target different segments without damaging the luxury image","questionType":"MCQ","explanation":{"correct_reason":"Separate names let Lamorna appeal to students and mid-market buyers while keeping the luxury line's exclusive image intact, so each segment sees a suitable offer.","distractor_reasons":{"A":"Separate names let Lamorna appeal to students and mid-market buyers while keeping the luxury line's exclusive image intact, so each segment sees a suitable offer.","B":"Running three brands usually raises promotional spending, since each name needs its own advertising. That is why it is not the best answer here.","C":"Three price lines with different materials make production more complex, not simpler. This makes the option unsuitable for the scenario described.","D":"Understanding three different groups of buyers requires more research, not less. The evidence in the scenario does not support this choice."}}},{"id":"P1_U3_MCQ_1375","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1375","question":"Mylor Marine advertises a bucket and spade set at $3.50, below its cost, to attract families into its seaside shop, where they also buy boats, wetsuits and fishing gear. Which pricing tactic is this?","options":{"A":"Price skimming","B":"A loss leader","C":"Penetration pricing","D":"Cost-plus pricing"},"correctOption":"B","correctAnswer":"A loss leader","questionType":"MCQ","explanation":{"correct_reason":"The bucket and spade set is sold below cost to draw families into the shop, where they spend on other products, which is the purpose of a loss leader.","distractor_reasons":{"A":"Price skimming means a high launch price that is reduced later, the opposite of selling below cost. That is why it is not the best answer here.","B":"The bucket and spade set is sold below cost to draw families into the shop, where they spend on other products, which is the purpose of a loss leader.","C":"Penetration pricing sets a low price to build share in a market, not to pull customers towards other products. The evidence in the scenario does not support this choice.","D":"Cost-plus pricing would set a price above cost, but the set is deliberately sold below cost. So the option does not answer the question that was asked."}}},{"id":"P1_U3_MCQ_1376","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1376","question":"Nantwich Nuts has a marketing budget of $50,000. It plans to spend 36% on trade advertising and 28% on a social media campaign, with the remainder going on in-store tastings. How much is available for the tastings?","options":{"A":"$14,000","B":"$21,000","C":"$32,000","D":"$18,000"},"correctOption":"D","correctAnswer":"$18,000","questionType":"MCQ","explanation":{"correct_reason":"Trade advertising takes $18,000 and social media takes $14,000, which is $32,000 in total, leaving $18,000 of the $50,000 budget for tastings.","distractor_reasons":{"A":"$14,000 is the social media share of the budget, not the amount left for tastings. This makes the option unsuitable for the scenario described.","B":"$21,000 is 42% of the budget and does not follow from the two percentages given. The evidence in the scenario does not support this choice.","C":"$32,000 is the combined spend on trade advertising and social media, before tastings are funded. So the option does not answer the question that was asked.","D":"Trade advertising takes $18,000 and social media takes $14,000, which is $32,000 in total, leaving $18,000 of the $50,000 budget for tastings."}}},{"id":"P1_U3_MCQ_1377","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1377","question":"Otterburn Outfitters sells technical climbing gear to experienced mountaineers at premium prices. A supermarket offers to stock a cheaper range that would treble volume but would need lower-grade materials. Which marketing decision is most appropriate, and why?","options":{"A":"Accept, because higher volume always produces higher profit","B":"Accept, because supermarkets pay their suppliers immediately","C":"Cut all promotion, since the supermarket will advertise the range","D":"Refuse, because cheapening the range could destroy the specialist reputation supporting premium prices"},"correctOption":"D","correctAnswer":"Refuse, because cheapening the range could destroy the specialist reputation supporting premium prices","questionType":"MCQ","explanation":{"correct_reason":"The premium prices rest on a specialist reputation, and lower-grade materials sold through a supermarket would undermine the quality image that experienced climbers pay for.","distractor_reasons":{"A":"Higher volume with thinner margins does not automatically raise profit, and a damaged reputation could cut sales further. The evidence in the scenario does not support this choice.","B":"Fast payment does not solve the loss of reputation and price premium that the cheaper range would cause. So the option does not answer the question that was asked.","C":"Withdrawing promotion would weaken the brand further at the moment it is being pushed downmarket. This reasoning does not fit the situation of the firm.","D":"The premium prices rest on a specialist reputation, and lower-grade materials sold through a supermarket would undermine the quality image that experienced climbers pay for."}}},{"id":"P1_U3_MCQ_1378","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1378","question":"Penrhyn Plastics advertises its garden chairs as weatherproof for ten years, although its own tests show the colour fades within two years. A consumer group is preparing a complaint. Which marketing issue does this raise?","options":{"A":"A pricing error caused by cost-plus calculation","B":"Misleading advertising, which is unethical and may be illegal","C":"A distribution problem in the supply chain","D":"A product life cycle extension tactic"},"correctOption":"B","correctAnswer":"Misleading advertising, which is unethical and may be illegal","questionType":"MCQ","explanation":{"correct_reason":"The advert claims ten years of weatherproofing while tests show fading within two, so the claim misleads buyers and breaches rules on honest advertising.","distractor_reasons":{"A":"The problem is the wording of the advert, not the way the price was calculated. So the option does not answer the question that was asked.","B":"The advert claims ten years of weatherproofing while tests show fading within two, so the claim misleads buyers and breaches rules on honest advertising.","C":"No distribution issue is described; the fault lies in what the firm tells customers about the product. Such a result would not follow from the details given here.","D":"Stretching a product's life is a legitimate aim, but making false durability claims is not an acceptable way to do it."}}},{"id":"P1_U3_MCQ_1379","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1379","question":"Quethiock Cordials spent $15,000 on a summer campaign that increased sales by $72,000. The extra sales carried a contribution margin of 40%. What was the net benefit of the campaign?","options":{"A":"$57,000","B":"$28,800","C":"$13,800","D":"$43,200"},"correctOption":"C","correctAnswer":"$13,800","questionType":"MCQ","explanation":{"correct_reason":"The extra sales contributed 40% of $72,000, which is $28,800, and deducting the $15,000 campaign cost leaves a net benefit of $13,800.","distractor_reasons":{"A":"$57,000 deducts the campaign cost from the whole $72,000 of sales without applying the 40% margin. This reasoning does not fit the situation of the firm.","B":"$28,800 is the contribution before the $15,000 cost of running the campaign is deducted. Such a result would not follow from the details given here.","C":"The extra sales contributed 40% of $72,000, which is $28,800, and deducting the $15,000 campaign cost leaves a net benefit of $13,800.","D":"$43,200 is 60% of the extra sales, which applies the wrong margin to the campaign. The option therefore fails to match the details of the scenario."}}},{"id":"P1_U3_MCQ_1380","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1380","question":"Ruan Rugs can produce up to 2,500 hand-woven rugs a year. Research shows that 2,000 wealthy households in its region would each buy one rug at $400. What is the maximum annual revenue from this segment?","options":{"A":"$800,000","B":"$1,000,000","C":"$400,000","D":"$80,000"},"correctOption":"A","correctAnswer":"$800,000","questionType":"MCQ","explanation":{"correct_reason":"Demand is limited to 2,000 households buying one rug each at $400, so the maximum revenue is 2,000 multiplied by $400, which is $800,000.","distractor_reasons":{"A":"Demand is limited to 2,000 households buying one rug each at $400, so the maximum revenue is 2,000 multiplied by $400, which is $800,000.","B":"$1,000,000 uses the 2,500 rugs the firm can produce, but only 2,000 households would actually buy. That is not consistent with what the scenario describes.","C":"$400,000 is the price of one rug multiplied by 1,000 households rather than the 2,000 identified. The option therefore fails to match the details of the scenario.","D":"$80,000 is ten times too small and would mean that only 200 households buy a rug. That is why it is not the best answer here."}}},{"id":"P1_U3_MCQ_1381","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1381","question":"Sennen Surfboards prices its boards 30% above rival brands, sells only through specialist surf shops and sponsors a professional rider. Which marketing strategy is the firm pursuing?","options":{"A":"Premium positioning aimed at serious surfers","B":"A low-price strategy aimed at beginners","C":"Mass distribution through supermarkets","D":"A cost leadership strategy based on large-scale output"},"correctOption":"A","correctAnswer":"Premium positioning aimed at serious surfers","questionType":"MCQ","explanation":{"correct_reason":"A price 30% above rivals, selected specialist shops and a sponsored professional all position the brand as a premium choice for serious surfers.","distractor_reasons":{"A":"A price 30% above rivals, selected specialist shops and a sponsored professional all position the brand as a premium choice for serious surfers.","B":"Beginners usually want low prices, yet Sennen charges 30% more than rival brands. The option therefore fails to match the details of the scenario.","C":"Selling only through specialist surf shops is the opposite of mass distribution through supermarkets. That is why it is not the best answer here.","D":"Cost leadership requires the lowest costs and prices, while Sennen deliberately charges a premium. This makes the option unsuitable for the scenario described."}}},{"id":"P1_U3_MCQ_1382","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1382","question":"Trerice Teas holds 4% of a market worth 25 million teabags a year. It sets an objective of reaching 6% within two years while the total market stays at 25 million teabags. How many extra teabags a year must it sell?","options":{"A":"50,000","B":"500,000","C":"1,500,000","D":"2,000,000"},"correctOption":"B","correctAnswer":"500,000","questionType":"MCQ","explanation":{"correct_reason":"The objective is a gain of 2 percentage points, and 0.02 multiplied by 25 million teabags equals 500,000 extra teabags sold each year.","distractor_reasons":{"A":"50,000 would be only a 0.2 point gain, a tenth of the 2 points needed. The option therefore fails to match the details of the scenario.","B":"The objective is a gain of 2 percentage points, and 0.02 multiplied by 25 million teabags equals 500,000 extra teabags sold each year.","C":"1,500,000 is a 6 point gain, which would lift the firm from nothing to the target share. This makes the option unsuitable for the scenario described.","D":"2,000,000 is an 8 point gain, far beyond the 2 point increase required. The evidence in the scenario does not support this choice."}}},{"id":"P1_U3_MCQ_1383","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1383","question":"Ugborough Upholstery began posting short videos of its workshop on social media. Enquiries rose from 40 to 130 a month at almost no cost beyond the owner's time. Which benefit of digital marketing does this show?","options":{"A":"It guarantees that every viewer becomes a customer","B":"It removes the need for the product to be good","C":"It can reach a wide audience at low cost","D":"It replaces every other element of the marketing mix"},"correctOption":"C","correctAnswer":"It can reach a wide audience at low cost","questionType":"MCQ","explanation":{"correct_reason":"The videos lifted monthly enquiries from 40 to 130 for almost nothing beyond the owner's time, showing that digital media can reach many people cheaply.","distractor_reasons":{"A":"Enquiries are not sales, and no channel can guarantee that every viewer becomes a paying customer. That is why it is not the best answer here.","B":"The videos still show real craftsmanship, and a poor product would soon attract bad reviews. This makes the option unsuitable for the scenario described.","C":"The videos lifted monthly enquiries from 40 to 130 for almost nothing beyond the owner's time, showing that digital media can reach many people cheaply.","D":"The firm still needs a suitable product, price and place, so one channel cannot replace the whole mix. So the option does not answer the question that was asked."}}},{"id":"P1_U3_MCQ_1384","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1384","question":"Ventnor Vinyl sells records in its home country and is considering selling in a neighbouring country where an import tax of 25% applies and cross-border postage is expensive. What should it examine before entering?","options":{"A":"Whether its home customers will stop buying records","B":"Whether it can avoid all foreign competition","C":"Whether records are a legal product in its home country","D":"Whether the tax and delivery costs will make its prices uncompetitive"},"correctOption":"D","correctAnswer":"Whether the tax and delivery costs will make its prices uncompetitive","questionType":"MCQ","explanation":{"correct_reason":"The 25% import tax and high postage add to the price buyers must pay, so Ventnor must check whether its records can still compete with local suppliers.","distractor_reasons":{"A":"Home demand is a separate question, and entering a new country does not by itself stop existing customers buying. This makes the option unsuitable for the scenario described.","B":"No firm can expect to avoid all foreign competition, so that is not a realistic test. The evidence in the scenario does not support this choice.","C":"The legality of records at home is already established by its existing business. So the option does not answer the question that was asked.","D":"The 25% import tax and high postage add to the price buyers must pay, so Ventnor must check whether its records can still compete with local suppliers."}}},{"id":"P1_U3_MCQ_1385","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1385","question":"Warbstow Wool spent $9,600 on a local campaign that attracted 480 new customers. The owner wants to compare this figure with the profit earned from an average customer. What was the cost of attracting each new customer?","options":{"A":"$2","B":"$20","C":"$48","D":"$200"},"correctOption":"B","correctAnswer":"$20","questionType":"MCQ","explanation":{"correct_reason":"The campaign cost of $9,600 divided by the 480 new customers gives $20 spent on attracting each new customer. This reasoning does not fit the situation of the firm.","distractor_reasons":{"A":"$2 divides 960 by 480, losing a zero from the $9,600 campaign cost. The evidence in the scenario does not support this choice.","B":"The campaign cost of $9,600 divided by the 480 new customers gives $20 spent on attracting each new customer. This reasoning does not fit the situation of the firm.","C":"$48 divides $9,600 by 200 rather than by the 480 customers actually attracted. This reasoning does not fit the situation of the firm.","D":"$200 is ten times too high and would mean that only 48 new customers had been won. Such a result would not follow from the details given here."}}},{"id":"P1_U3_MCQ_1386","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1386","question":"Exmoor Eyewear gives every customer a free annual eye check and texts a reminder when it is due. The owner says this supports the firm's marketing strategy. How does the scheme help?","options":{"A":"It reduces the cost of manufacturing lenses","B":"It allows the firm to raise prices without limit","C":"It encourages repeat purchase and builds a long-term relationship","D":"It replaces the need to attract new customers"},"correctOption":"C","correctAnswer":"It encourages repeat purchase and builds a long-term relationship","questionType":"MCQ","explanation":{"correct_reason":"A free annual check and a reminder bring customers back into the shop each year, which builds a long-term relationship and repeated purchases.","distractor_reasons":{"A":"An eye check is a service, and offering it free adds cost rather than lowering the cost of lenses. So the option does not answer the question that was asked.","B":"No scheme allows unlimited price rises, since customers can still compare prices with rivals. This reasoning does not fit the situation of the firm.","C":"A free annual check and a reminder bring customers back into the shop each year, which builds a long-term relationship and repeated purchases.","D":"The firm still needs new customers, because existing ones may move away or stop buying glasses. That is not consistent with what the scenario describes."}}},{"id":"P1_U3_MCQ_1387","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1387","question":"Yalding Yoghurts plans to cut its marketing budget by 60% this year so that short-term profit looks stronger, while its main rivals keep advertising. What is the most likely long-term effect?","options":{"A":"Its fixed costs will rise straight away","B":"Its product quality will improve","C":"Its market share will automatically increase","D":"Brand awareness and sales may fall as rivals stay visible"},"correctOption":"D","correctAnswer":"Brand awareness and sales may fall as rivals stay visible","questionType":"MCQ","explanation":{"correct_reason":"Less promotion means shoppers see the brand less often while rivals remain visible, so awareness and sales are likely to slip over time even if profit improves this year.","distractor_reasons":{"A":"Cutting promotion lowers spending rather than raising fixed costs such as rent and salaries. This reasoning does not fit the situation of the firm.","B":"Advertising budgets do not change the recipe or quality of the yoghurt itself. Such a result would not follow from the details given here.","C":"Share is unlikely to rise automatically when the brand becomes less visible than its rivals. That is not consistent with what the scenario describes.","D":"Less promotion means shoppers see the brand less often while rivals remain visible, so awareness and sales are likely to slip over time even if profit improves this year."}}},{"id":"P1_U3_MCQ_1388","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1388","question":"Barrowden Birdseed plans to advertise its grow-your-own sunflower kit during children's television programmes and to put a free toy in every pack. A consumer group has objected. Which ethical concern is most relevant?","options":{"A":"Advertising to children can be seen as taking advantage of their inexperience","B":"Sunflower seeds are too expensive to produce","C":"Children cannot legally buy birdseed at any age","D":"Television advertising is always dearer than social media"},"correctOption":"A","correctAnswer":"Advertising to children can be seen as taking advantage of their inexperience","questionType":"MCQ","explanation":{"correct_reason":"The campaign targets children with a free toy, which critics argue exploits young viewers who cannot judge advertising claims or manage spending.","distractor_reasons":{"A":"The campaign targets children with a free toy, which critics argue exploits young viewers who cannot judge advertising claims or manage spending.","B":"Production cost is an economic question, not the ethical concern that the consumer group has raised. That is not consistent with what the scenario describes.","C":"There is no general rule banning the sale of birdseed to children, so this is not the issue. The option therefore fails to match the details of the scenario.","D":"The relative cost of media is a budgeting matter, not the ethical objection described. That is why it is not the best answer here."}}},{"id":"P1_U3_MCQ_1389","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1389","question":"Clovelly Crafts sells knitted toys that can be personalised with a child's name and delivered within three days. Larger rivals sell standard toys at similar prices but cannot offer either service. Which basis for competitive advantage is this?","options":{"A":"Being the lowest-cost producer in the market","B":"Selling at the lowest price in the market","C":"Differentiation through a service that rivals find hard to copy","D":"Copying rivals' standard designs as quickly as possible"},"correctOption":"C","correctAnswer":"Differentiation through a service that rivals find hard to copy","questionType":"MCQ","explanation":{"correct_reason":"Personalised names and three-day delivery give buyers something rivals cannot match at a similar price, which is differentiation built on service.","distractor_reasons":{"A":"Cost leadership means producing more cheaply than rivals, and the stem gives no evidence about Clovelly's costs. That is not consistent with what the scenario describes.","B":"Rivals sell at similar prices, so Clovelly is certainly not the cheapest seller in the market. The option therefore fails to match the details of the scenario.","C":"Personalised names and three-day delivery give buyers something rivals cannot match at a similar price, which is differentiation built on service.","D":"Copying rivals' designs would remove the personalisation and speed that win its customers. This makes the option unsuitable for the scenario described."}}},{"id":"P1_U3_MCQ_1390","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1390","question":"Dunster Dressings expects to sell 12,000 jars of its new vegan range at $4.50 each. Each jar costs $2.20 in ingredients and packaging, and launching the range costs $18,000. What is the expected profit?","options":{"A":"$27,600","B":"$54,000","C":"$36,000","D":"$9,600"},"correctOption":"D","correctAnswer":"$9,600","questionType":"MCQ","explanation":{"correct_reason":"Each jar leaves $2.30 after variable costs, so 12,000 jars contribute $27,600, and deducting the $18,000 launch cost leaves an expected profit of $9,600.","distractor_reasons":{"A":"$27,600 is the total contribution before the $18,000 launch cost is deducted. The option therefore fails to match the details of the scenario.","B":"$54,000 is the sales revenue from 12,000 jars at $4.50, before any costs are taken off. That is why it is not the best answer here.","C":"$36,000 is the total variable cost of the jars, not the profit the range would earn. This makes the option unsuitable for the scenario described.","D":"Each jar leaves $2.30 after variable costs, so 12,000 jars contribute $27,600, and deducting the $18,000 launch cost leaves an expected profit of $9,600."}}},{"id":"P1_U3_MCQ_1391","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1391","question":"Elmscott Engines sells the same generator in three versions: a basic model for households, a silenced model for campsites and a heavy-duty model for builders. What is the firm doing?","options":{"A":"Segmenting the market and adapting the product to each segment","B":"Selling one undifferentiated product to the whole market","C":"Reducing its product range in order to cut costs","D":"Using penetration pricing in all three markets"},"correctOption":"A","correctAnswer":"Segmenting the market and adapting the product to each segment","questionType":"MCQ","explanation":{"correct_reason":"Three versions of one generator are designed for three distinct groups of buyers, so the firm is segmenting the market and adapting its product to each group.","distractor_reasons":{"A":"Three versions of one generator are designed for three distinct groups of buyers, so the firm is segmenting the market and adapting its product to each group.","B":"Undifferentiated selling means one standard product for everyone, but three separate versions are offered. This makes the option unsuitable for the scenario described.","C":"Adding two extra versions widens the range rather than reducing it. The evidence in the scenario does not support this choice.","D":"No prices are given, and the differences described are in design rather than price. So the option does not answer the question that was asked."}}},{"id":"P1_U3_MCQ_1392","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1392","question":"Fowey Fudge's viral video brought 3,000 orders in one week, but the firm could make only 900 boxes and had to delay deliveries. What lesson for marketing strategy does this show?","options":{"A":"Viral videos never produce profitable sales","B":"Demand created by promotion must be matched by production capacity","C":"The firm should stop using social media altogether","D":"Delayed deliveries always increase customer loyalty"},"correctOption":"B","correctAnswer":"Demand created by promotion must be matched by production capacity","questionType":"MCQ","explanation":{"correct_reason":"Promotion created 3,000 orders while the firm could make only 900 boxes, so marketing must be planned alongside the capacity to supply customers.","distractor_reasons":{"A":"The video did produce sales; the problem was the firm's inability to make enough boxes to fulfil them. This makes the option unsuitable for the scenario described.","B":"Promotion created 3,000 orders while the firm could make only 900 boxes, so marketing must be planned alongside the capacity to supply customers.","C":"Abandoning social media would not fix a capacity problem and would lose a cheap promotional channel. So the option does not answer the question that was asked.","D":"Delays usually damage loyalty, especially for a food gift that customers expect in time for an occasion. This reasoning does not fit the situation of the firm."}}},{"id":"P1_U3_MCQ_1393","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1393","question":"Godrevy Gifts had sales of $180,000 in a market worth $3 million. After a campaign, its sales rose to $225,000 while the market stayed at $3 million. By how many percentage points did its market share rise?","options":{"A":"0.5 percentage points","B":"4.5 percentage points","C":"6 percentage points","D":"1.5 percentage points"},"correctOption":"D","correctAnswer":"1.5 percentage points","questionType":"MCQ","explanation":{"correct_reason":"The share was $180,000 out of $3 million, or 6%, and became $225,000 out of $3 million, or 7.5%, so the rise was 1.5 percentage points.","distractor_reasons":{"A":"0.5 points would need the sales increase to be about $15,000 rather than the $45,000 achieved. The evidence in the scenario does not support this choice.","B":"4.5 points is three times the actual rise and would take the firm well above a 10% share. So the option does not answer the question that was asked.","C":"6 points is the original market share, not the amount by which the share increased. This reasoning does not fit the situation of the firm.","D":"The share was $180,000 out of $3 million, or 6%, and became $225,000 out of $3 million, or 7.5%, so the rise was 1.5 percentage points."}}},{"id":"P1_U3_MCQ_1394","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1394","question":"Helford Herbals sponsors a national gardening show and gives every visitor a seed packet carrying a discount code. Which marketing objective does this mainly serve?","options":{"A":"Raising brand awareness among gardeners and encouraging a first purchase","B":"Reducing the variable cost of production","C":"Shortening the product life cycle","D":"Complying with advertising regulations"},"correctOption":"A","correctAnswer":"Raising brand awareness among gardeners and encouraging a first purchase","questionType":"MCQ","explanation":{"correct_reason":"The sponsorship puts the brand in front of gardeners at a relevant event, and the coded packet turns that visibility into a discounted first purchase.","distractor_reasons":{"A":"The sponsorship puts the brand in front of gardeners at a relevant event, and the coded packet turns that visibility into a discounted first purchase.","B":"Sponsorship fees and free seed packets add cost rather than lowering the variable cost of production. This reasoning does not fit the situation of the firm.","C":"No firm aims to shorten a product's life, and sponsorship is meant to extend sales. Such a result would not follow from the details given here.","D":"Advertising rules do not require a firm to sponsor a gardening show. That is not consistent with what the scenario describes."}}},{"id":"P1_U3_MCQ_1395","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1395","question":"Iddesleigh Inks sells refill bottles at $9 and sealed printer cartridges at $31, although both contain similar ink. Buyers of refills accept more mess and effort. What best explains the price difference?","options":{"A":"The refill bottle contains far more ink than the cartridge","B":"The two groups of buyers have different needs and price sensitivity, so the firm prices each accordingly","C":"Refill buyers are less sensitive to price than cartridge buyers","D":"Both products cost exactly the same to make and market"},"correctOption":"B","correctAnswer":"The two groups of buyers have different needs and price sensitivity, so the firm prices each accordingly","questionType":"MCQ","explanation":{"correct_reason":"Refill buyers trade mess and effort for a low price, while cartridge buyers pay for convenience, so different needs and price sensitivity support very different prices.","distractor_reasons":{"A":"The stem says both contain similar ink, so the volume of ink cannot explain a price more than three times higher.","B":"Refill buyers trade mess and effort for a low price, while cartridge buyers pay for convenience, so different needs and price sensitivity support very different prices.","C":"Refill buyers are attracted by the $9 price, which shows they are more price sensitive rather than less. That is not consistent with what the scenario describes.","D":"Prices differ because buyers value the products differently, not because the costs are identical. The option therefore fails to match the details of the scenario."}}},{"id":"P1_U3_MCQ_1396","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1396","question":"Jacobstow Jute wants sales of $540,000 next year, which is 20% higher than this year. The owner needs this year's figure to set production budgets and order raw materials. What were this year's sales?","options":{"A":"$432,000","B":"$648,000","C":"$450,000","D":"$520,000"},"correctOption":"C","correctAnswer":"$450,000","questionType":"MCQ","explanation":{"correct_reason":"If $540,000 is 120% of this year's sales, dividing $540,000 by 1.2 gives $450,000 as the sales figure for this year.","distractor_reasons":{"A":"$432,000 is 20% below $540,000, which treats the target as the starting point instead of the result. Such a result would not follow from the details given here.","B":"$648,000 adds 20% to the target instead of removing the growth already included in it. That is not consistent with what the scenario describes.","C":"If $540,000 is 120% of this year's sales, dividing $540,000 by 1.2 gives $450,000 as the sales figure for this year.","D":"$520,000 leaves only $20,000 of growth, which is about 3.8% rather than the 20% stated. That is why it is not the best answer here."}}},{"id":"P1_U3_MCQ_1397","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1397","question":"Kenwyn Kites uses the same logo, colours and flies-in-any-wind slogan on its kites, windsocks, packaging and website. The owner refuses to change any of them. Why is this consistency useful?","options":{"A":"It builds a recognisable brand image wherever customers meet the firm","B":"It reduces the cost of raw materials","C":"It lets each product target a completely different segment","D":"It removes the need to research customer needs"},"correctOption":"A","correctAnswer":"It builds a recognisable brand image wherever customers meet the firm","questionType":"MCQ","explanation":{"correct_reason":"Repeating the logo, colours and slogan everywhere makes the brand easy to recognise and links all the firm's products together in customers' minds.","distractor_reasons":{"A":"Repeating the logo, colours and slogan everywhere makes the brand easy to recognise and links all the firm's products together in customers' minds.","B":"Logos and slogans are design elements and do not change the cost of fabric, spars or string. The option therefore fails to match the details of the scenario.","C":"A shared identity does the opposite, tying the products together rather than separating them for different segments. That is why it is not the best answer here.","D":"Branding does not tell the firm what customers want, so market research is still needed. This makes the option unsuitable for the scenario described."}}},{"id":"P1_U3_MCQ_1398","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1398","question":"Lerryn Ladders prints the words eco-friendly on its packaging, but its aluminium comes from a smelter powered by coal. A journalist is investigating the claim. What is the main risk to the business?","options":{"A":"A rise in the market price of aluminium","B":"Higher distribution costs caused by the article","C":"A fall in the number of ladder designs offered","D":"Damage to the brand's reputation and possible legal action over a false claim"},"correctOption":"D","correctAnswer":"Damage to the brand's reputation and possible legal action over a false claim","questionType":"MCQ","explanation":{"correct_reason":"The green claim conflicts with coal-powered production, so exposure could damage trust in the brand and lead to action over misleading environmental marketing.","distractor_reasons":{"A":"The risk described is reputational, not a change in the price of the metal it buys. The option therefore fails to match the details of the scenario.","B":"A newspaper article does not itself raise transport costs, although it may reduce sales. That is why it is not the best answer here.","C":"The number of ladder designs is unaffected by a dispute about an environmental claim. This makes the option unsuitable for the scenario described.","D":"The green claim conflicts with coal-powered production, so exposure could damage trust in the brand and lead to action over misleading environmental marketing."}}},{"id":"P1_U3_MCQ_1399","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1399","question":"Morwenstow Mugs pays $4,200 for a stand at a craft fair and sells 700 mugs there at $12 each. Each mug costs $5.50 in materials. What is the net gain from attending the fair?","options":{"A":"$4,550","B":"$350","C":"$8,400","D":"$1,050"},"correctOption":"B","correctAnswer":"$350","questionType":"MCQ","explanation":{"correct_reason":"Each mug leaves $6.50 after materials, so 700 mugs contribute $4,550, and deducting the $4,200 stand cost leaves a net gain of $350.","distractor_reasons":{"A":"$4,550 is the contribution from the mugs before the $4,200 stand cost is deducted. That is why it is not the best answer here.","B":"Each mug leaves $6.50 after materials, so 700 mugs contribute $4,550, and deducting the $4,200 stand cost leaves a net gain of $350.","C":"$8,400 is the total revenue from 700 mugs at $12, ignoring both materials and the stand cost. The evidence in the scenario does not support this choice.","D":"$1,050 is the total materials cost of the mugs, not the gain from attending the fair. So the option does not answer the question that was asked."}}},{"id":"P1_U3_MCQ_1400","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1400","question":"Newlyn Nets sells to 40 harbour shops and wants to grow. Option one is national advertising to sea anglers; option two is a low-price line for garden centres. Which factor matters most in choosing between them?","options":{"A":"Which option uses the most colourful advertising","B":"Which option copies the largest rival's current campaign","C":"Whether the firm has the capacity and margins to serve the new customers profitably","D":"Which option requires the fewest staff meetings"},"correctOption":"C","correctAnswer":"Whether the firm has the capacity and margins to serve the new customers profitably","questionType":"MCQ","explanation":{"correct_reason":"Either route only works if Newlyn can make enough nets and earn an acceptable margin from the new buyers, so capacity and profitability must be checked first.","distractor_reasons":{"A":"Colourful advertising says nothing about whether the strategy can actually be delivered and paid for. This makes the option unsuitable for the scenario described.","B":"Copying a rival does not show that the option fits Newlyn's own capacity, costs or customers. The evidence in the scenario does not support this choice.","C":"Either route only works if Newlyn can make enough nets and earn an acceptable margin from the new buyers, so capacity and profitability must be checked first.","D":"The number of meetings is an internal detail with little bearing on commercial success. This reasoning does not fit the situation of the firm."}}},{"id":"P1_U3_MCQ_1401","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1401","question":"Halbrook Outdoors sold 18,000 tents last year in a country where total tent sales were 450,000 units. The marketing director wants to know what share of the national tent market the business achieved. What was Halbrook Outdoors' market share?","options":{"A":"2.5%","B":"25%","C":"4.0%","D":"0.4%"},"correctOption":"C","correctAnswer":"4.0%","questionType":"MCQ","explanation":{"correct_reason":"Market share is the firm's sales divided by total market sales, so 18,000 tents divided by 450,000 tents multiplied by 100 gives Halbrook Outdoors a share of 4.0%.","distractor_reasons":{"A":"2.5% would require sales of only 11,250 tents in the 450,000-unit market, which does not match the 18,000 tents Halbrook Outdoors actually sold.","B":"25% comes from dividing 450,000 by 18,000 and reading the result as a percentage, which reverses the market share calculation.","C":"Market share is the firm's sales divided by total market sales, so 18,000 tents divided by 450,000 tents multiplied by 100 gives Halbrook Outdoors a share of 4.0%.","D":"0.4% is the result of a decimal place error; 18,000 divided by 450,000 is 0.04, which converts to 4.0% and not 0.4%."}}},{"id":"P1_U3_MCQ_1402","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1402","question":"Harbourlight Hotels asked a random sample of 500 guests whether they would use a spa if one were built. Of those asked, 32% said yes. The hotel expects 40,000 guests next year and wants a rough estimate of potential spa demand. How many guests does the survey suggest would use the spa?","options":{"A":"1,280","B":"3,200","C":"12,800","D":"128,000"},"correctOption":"C","correctAnswer":"12,800","questionType":"MCQ","explanation":{"correct_reason":"The survey suggests 32% of guests would use the spa, so 32% of the 40,000 expected guests is 0.32 multiplied by 40,000, which equals 12,800 potential users.","distractor_reasons":{"A":"1,280 is a decimal place error; 32% of 40,000 is 12,800, ten times larger than this estimate, and it therefore does not follow from the stated values.","B":"3,200 would be the estimate if only 8% of guests said yes, but the survey found 32% support, so it cannot be the correct result of this calculation.","C":"The survey suggests 32% of guests would use the spa, so 32% of the 40,000 expected guests is 0.32 multiplied by 40,000, which equals 12,800 potential users.","D":"128,000 exceeds the 40,000 expected guests, so it cannot be a valid estimate of potential spa users, which is inconsistent with the values quoted above."}}},{"id":"P1_U3_MCQ_1403","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1403","question":"Hazelmere Health makes a vitamin supplement that costs $24 in materials and labour per pack. The finance manager adds a 25% markup to the unit cost to set the selling price for pharmacies. What price should be charged for each pack?","options":{"A":"$26.00","B":"$29.00","C":"$30.00","D":"$48.00"},"correctOption":"C","correctAnswer":"$30.00","questionType":"MCQ","explanation":{"correct_reason":"Cost-plus pricing adds a percentage markup to unit cost, so 25% of $24 is $6, and $24 plus $6 gives a selling price of $30 per pack.","distractor_reasons":{"A":"$26.00 adds only $2 to the unit cost, which is about 8.3% rather than the 25% markup specified, so it cannot be the correct result of this calculation.","B":"$29.00 adds $5 to the unit cost, which is roughly 21% rather than the 25% markup the finance manager requires.","C":"Cost-plus pricing adds a percentage markup to unit cost, so 25% of $24 is $6, and $24 plus $6 gives a selling price of $30 per pack.","D":"$48.00 doubles the unit cost, which is a 100% markup and far above the 25% specified, so it does not match the figures given in the stem."}}},{"id":"P1_U3_MCQ_1404","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1404","question":"Hollinwood Hats plans to sell its waterproof hats in three overseas countries. Local labelling rules and sizing conventions differ in each market, and adapting the packaging and size range will cost $14,000 per country. What total adaptation cost does the company face?","options":{"A":"$17,000","B":"$28,000","C":"$42,000","D":"$140,000"},"correctOption":"C","correctAnswer":"$42,000","questionType":"MCQ","explanation":{"correct_reason":"Adapting for three markets at $14,000 each costs 3 multiplied by $14,000, which equals $42,000 before Hollinwood Hats can launch in all three countries.","distractor_reasons":{"A":"$17,000 adds $3,000 to one market's cost, which does not reflect three separate adaptations, and the numbers in the stem do not support this figure.","B":"$28,000 covers only two of the three markets and leaves one country without its adaptation budget, and the numbers in the stem do not support this figure.","C":"Adapting for three markets at $14,000 each costs 3 multiplied by $14,000, which equals $42,000 before Hollinwood Hats can launch in all three countries.","D":"$140,000 is ten times the correct amount and would imply a cost of about $46,667 per country, which is inconsistent with the values quoted above."}}},{"id":"P1_U3_MCQ_1405","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1405","question":"Mirevale Dairy operates in a regional dairy market that was worth $240 million two years ago and is now worth $276 million. The board is reviewing whether demand for its products is expanding. By what percentage did the value of this market grow?","options":{"A":"36%","B":"13%","C":"115%","D":"15%"},"correctOption":"D","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Market growth is the change in market value divided by the original value, so $276 million minus $240 million equals $36 million, and $36 million divided by $240 million gives 15% growth.","distractor_reasons":{"A":"36% is the absolute increase measured in millions of dollars, not a percentage of the original $240 million market value.","B":"13% is found by dividing the $36 million increase by the new $276 million value instead of by the original $240 million value.","C":"115% wrongly treats the new $276 million market value as a percentage of the original $240 million instead of measuring the change.","D":"Market growth is the change in market value divided by the original value, so $276 million minus $240 million equals $36 million, and $36 million divided by $240 million gives 15% growth."}}},{"id":"P1_U3_MCQ_1406","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1406","question":"Inkwell Stationery is planning a new range of recycled notebooks and has downloaded free population and household-spending statistics from a government website. The owner wants quick background data before commissioning any fieldwork. What is the main advantage of this secondary research?","options":{"A":"It is quick and free to obtain, although it may not be specific to the firm's needs","B":"It is always more accurate than primary research","C":"It is tailored exactly to the notebook market","D":"It is impossible for small firms to find"},"correctOption":"A","correctAnswer":"It is quick and free to obtain, although it may not be specific to the firm's needs","questionType":"MCQ","explanation":{"correct_reason":"Government statistics are already collected and published, so Inkwell Stationery can obtain them quickly and at no cost, but they may be too general for its specific notebook range.","distractor_reasons":{"A":"Government statistics are already collected and published, so Inkwell Stationery can obtain them quickly and at no cost, but they may be too general for its specific notebook range.","B":"Published statistics cannot be assumed more accurate than primary data collected for the specific purpose, as they may be aggregated or outdated.","C":"Government population and spending data are broad, so they are not tailored to the notebook market the way purpose-built primary research would be.","D":"The stem states the owner downloaded the statistics from a government website, which shows they are readily available to small firms."}}},{"id":"P1_U3_MCQ_1407","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1407","question":"Ironbark Instruments normally sells its beginner violin for $80. For a music festival promotion it offers 15% off the normal price to customers who order during the weekend. What is the promotional price of the violin?","options":{"A":"$65","B":"$68","C":"$72","D":"$92"},"correctOption":"B","correctAnswer":"$68","questionType":"MCQ","explanation":{"correct_reason":"A 15% discount reduces the $80 price by $12, because 0.15 multiplied by $80 is $12, so customers pay $80 minus $12, which is $68.","distractor_reasons":{"A":"$65 would be a discount of $15, which is 18.75% of $80 rather than the 15% offered, and it therefore does not follow from the stated values.","B":"A 15% discount reduces the $80 price by $12, because 0.15 multiplied by $80 is $12, so customers pay $80 minus $12, which is $68.","C":"$72 would be a discount of $8, which is only 10% of the normal price, and the numbers in the stem do not support this figure.","D":"$92 adds 15% to the price instead of subtracting it, which turns a discount into a surcharge, so it would give the wrong total for the business."}}},{"id":"P1_U3_MCQ_1408","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1408","question":"Ingleby Inks wants to enter a fast-growing Asian market but lacks local contacts and knowledge of retail regulations. It forms a partnership with an established local printing firm, sharing the investment and the profits. What is the main benefit of this joint venture?","options":{"A":"Ingleby Inks keeps all of the profits","B":"It removes all commercial risk","C":"It requires no capital from either partner","D":"The local partner provides market knowledge while costs and risks are shared"},"correctOption":"D","correctAnswer":"The local partner provides market knowledge while costs and risks are shared","questionType":"MCQ","explanation":{"correct_reason":"A joint venture brings in a local partner who understands regulations and retail contacts, and sharing the investment means Ingleby Inks bears less cost and risk than entering alone.","distractor_reasons":{"A":"A joint venture shares profits with the partner, so Ingleby Inks does not keep all of them, which means it does not meet the requirement set out in the stem.","B":"Sharing risk reduces exposure but cannot remove commercial risk, since the venture can still fail, so it does not provide what the business actually needs.","C":"Both partners contribute capital and resources, so claiming no capital is required contradicts the idea of a joint venture, which does not help the business achieve the outcome it wants.","D":"A joint venture brings in a local partner who understands regulations and retail contacts, and sharing the investment means Ingleby Inks bears less cost and risk than entering alone."}}},{"id":"P1_U3_MCQ_1409","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1409","question":"Quince & Loom held a 12% share of the online homeware market in 2024 and a 15% share in 2025. The founder wants a simple measure of how much ground the brand gained against its rivals over the year. By how much did its market share rise?","options":{"A":"3 percentage points","B":"25 percentage points","C":"1.25 percentage points","D":"0.25 percentage points"},"correctOption":"A","correctAnswer":"3 percentage points","questionType":"MCQ","explanation":{"correct_reason":"Market share moved from 12% to 15%, and the difference between two percentages is measured in percentage points, so the rise is 15 minus 12, which equals 3 percentage points.","distractor_reasons":{"A":"Market share moved from 12% to 15%, and the difference between two percentages is measured in percentage points, so the rise is 15 minus 12, which equals 3 percentage points.","B":"25 percentage points confuses a relative increase with an absolute one; the 3-point gain is 25% of the old 12% share, not 25 points.","C":"1.25 percentage points comes from dividing the 15% new share by the old 12% share, which is not how a change in share is measured.","D":"0.25 percentage points is a decimal error; the arithmetic difference between 15% and 12% is 3 points, not 0.25, which is not the outcome produced by the figures provided."}}},{"id":"P1_U3_MCQ_1410","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1410","question":"Juniper Jar Sauces paid a research agency $4,800 to complete 600 questionnaires with shoppers in supermarkets. The marketing manager wants to compare this with the cost of online surveys before planning next year's research. What was the cost per completed questionnaire?","options":{"A":"$0.80","B":"$80","C":"$8","D":"$12"},"correctOption":"C","correctAnswer":"$8","questionType":"MCQ","explanation":{"correct_reason":"Cost per completed questionnaire is total cost divided by the number completed, so $4,800 divided by 600 questionnaires equals $8 for each completed response.","distractor_reasons":{"A":"$0.80 is a decimal place error; $4,800 divided by 600 is $8, ten times larger than this figure, and it therefore does not follow from the stated values.","B":"$80 would mean only 60 questionnaires were completed at the $4,800 total, but the stem states 600 were completed, so it cannot be the correct result of this calculation.","C":"Cost per completed questionnaire is total cost divided by the number completed, so $4,800 divided by 600 questionnaires equals $8 for each completed response.","D":"$12 would require a total cost of $7,200 for 600 questionnaires, which is higher than the $4,800 actually paid, so it cannot be the correct result of this calculation."}}},{"id":"P1_U3_MCQ_1411","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1411","question":"Jasmine Junction sells scented candles at $36 each. Last month the shop sold 2,500 candles, and the owner wants to see the effect of the price on total sales income before changing the price. What was total revenue from candle sales?","options":{"A":"$9,000","B":"$72,000","C":"$93,600","D":"$90,000"},"correctOption":"D","correctAnswer":"$90,000","questionType":"MCQ","explanation":{"correct_reason":"Total revenue is price multiplied by quantity sold, so $36 multiplied by 2,500 candles equals $90,000 of revenue for Jasmine Junction last month.","distractor_reasons":{"A":"$9,000 is a decimal place error; $36 multiplied by 2,500 is $90,000, ten times larger, so it cannot be the correct result of this calculation.","B":"$72,000 would result from selling 2,000 candles at $36, but the stem states 2,500 were sold, which is not the outcome produced by the figures provided.","C":"$93,600 adds 4% to the correct revenue and does not follow from multiplying $36 by 2,500, and the numbers in the stem do not support this figure.","D":"Total revenue is price multiplied by quantity sold, so $36 multiplied by 2,500 candles equals $90,000 of revenue for Jasmine Junction last month."}}},{"id":"P1_U3_MCQ_1412","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1412","question":"Jarrow Joinery already makes flat-pack kitchens in its home factory and now ships containers to an independent distributor in Ireland, which sells them to local builders' merchants. The owner wants to test foreign demand without building overseas factories. What is the main advantage of this exporting approach?","options":{"A":"There are no transport or tariff costs","B":"It guarantees the product suits Irish tastes","C":"No product adaptation is ever needed","D":"It involves low commitment and uses existing production capacity"},"correctOption":"D","correctAnswer":"It involves low commitment and uses existing production capacity","questionType":"MCQ","explanation":{"correct_reason":"Exporting through a distributor lets Jarrow Joinery use its existing factory and test Irish demand without the cost and commitment of setting up overseas operations.","distractor_reasons":{"A":"Shipping containers to Ireland involves transport costs, and tariffs may also apply, so these costs are not avoided, and it would not solve the problem described in the scenario.","B":"Demand in Ireland is not yet known, and exporting does not guarantee that Irish buyers will like the kitchens, which does not help the business achieve the outcome it wants.","C":"Selling abroad may require changes to sizes, plugs or labelling, so exporting does not remove the need for adaptation, and it would be a poor decision for the business in this case.","D":"Exporting through a distributor lets Jarrow Joinery use its existing factory and test Irish demand without the cost and commitment of setting up overseas operations."}}},{"id":"P1_U3_MCQ_1413","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1413","question":"Brackenwood Tours designs walking holidays for people aged 18 to 30 and advertises through university societies and climbing clubs. Its research shows this group wants low-cost adventure travel. Which basis for market segmentation is Brackenwood Tours mainly using?","options":{"A":"Demographic segmentation by age","B":"Geographic segmentation by region","C":"Income segmentation by earnings","D":"Behavioural segmentation by loyalty"},"correctOption":"A","correctAnswer":"Demographic segmentation by age","questionType":"MCQ","explanation":{"correct_reason":"The business defines its target group by a demographic characteristic, age, focusing on 18 to 30 year olds, so demographic segmentation by age is the basis being applied here.","distractor_reasons":{"A":"The business defines its target group by a demographic characteristic, age, focusing on 18 to 30 year olds, so demographic segmentation by age is the basis being applied here.","B":"Geographic segmentation would divide customers by where they live, such as county or country, but Brackenwood Tours selects customers by their age instead.","C":"Income segmentation would group buyers by earnings bands, yet the stem describes an age range and adventure interests rather than income levels.","D":"Behavioural segmentation by loyalty would group customers by repeat purchase patterns, but the target group here is identified by age before any purchase history exists."}}},{"id":"P1_U3_MCQ_1414","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1414","question":"Kindlewood Camping asks customers who stay at its sites to write freely about what they most enjoyed and what could be improved. The responses are long and varied, and the manager must read them all to spot common themes. What type of question is being used?","options":{"A":"A closed question producing numerical data","B":"An open question producing detailed opinions that are harder to analyse","C":"A question that forces a yes or no answer","D":"A secondary research technique"},"correctOption":"B","correctAnswer":"An open question producing detailed opinions that are harder to analyse","questionType":"MCQ","explanation":{"correct_reason":"Open questions invite customers to answer in their own words, so they produce rich opinions and suggestions for Kindlewood Camping, but the varied responses take more effort to group and analyse.","distractor_reasons":{"A":"Closed questions offer fixed choices and produce data that is easy to count, whereas these free written answers are long and varied.","B":"Open questions invite customers to answer in their own words, so they produce rich opinions and suggestions for Kindlewood Camping, but the varied responses take more effort to group and analyse.","C":"A yes or no question would produce a single fixed response, but customers here can write freely about anything they choose.","D":"The answers come directly from guests, which makes this primary research rather than the use of existing secondary data, and it would not solve the problem described in the scenario."}}},{"id":"P1_U3_MCQ_1415","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1415","question":"Kelpwick Kitchens is launching a new budget kettle into a crowded market. It sets the price well below rival kettles for the first six months to attract large numbers of first-time buyers and build market share quickly. Which pricing strategy is being used?","options":{"A":"Price skimming","B":"Competitive pricing","C":"Premium pricing","D":"Penetration pricing"},"correctOption":"D","correctAnswer":"Penetration pricing","questionType":"MCQ","explanation":{"correct_reason":"Penetration pricing sets a low launch price to attract buyers quickly and build market share, which is exactly what Kelpwick Kitchens is doing with its budget kettle.","distractor_reasons":{"A":"Price skimming starts high and falls later, which is the opposite of launching well below rivals to win volume, so it is less suitable than the alternative described.","B":"Competitive pricing matches rivals' prices, but this kettle is deliberately set well below them, which makes it a weaker choice than the correct option here.","C":"Premium pricing charges above rivals to signal quality, whereas this launch price is lower than competitors', so it does not provide what the business actually needs.","D":"Penetration pricing sets a low launch price to attract buyers quickly and build market share, which is exactly what Kelpwick Kitchens is doing with its budget kettle."}}},{"id":"P1_U3_MCQ_1416","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1416","question":"Kippax Kettles allows a manufacturer in another country to produce its patented kettle design and sell it there. In return, Kippax receives a royalty on every kettle sold. Kippax does not invest in the foreign factory or manage its staff. What method of entering international markets is this?","options":{"A":"A joint venture","B":"Exporting","C":"Franchising","D":"Licensing"},"correctOption":"D","correctAnswer":"Licensing","questionType":"MCQ","explanation":{"correct_reason":"Licensing grants another business the right to use a design or brand in return for a fee, which is exactly the arrangement Kippax Kettles has made for its patented kettle design.","distractor_reasons":{"A":"A joint venture involves shared ownership and investment, but Kippax neither invests in the foreign factory nor manages it, which makes it a weaker choice than the correct option here.","B":"Exporting means shipping goods made at home, whereas this foreign manufacturer produces the kettles itself under licence, so it does not provide what the business actually needs.","C":"Franchising grants rights to a complete business format, while here only the kettle design is licensed for a royalty, and it would not solve the problem described in the scenario.","D":"Licensing grants another business the right to use a design or brand in return for a fee, which is exactly the arrangement Kippax Kettles has made for its patented kettle design."}}},{"id":"P1_U3_MCQ_1417","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1417","question":"Silverpin Jewellery repairs rings in about 48 hours, but a new rival promises same-day repairs and has won several long-standing customers. The owner is reviewing what customers really value when choosing a jeweller. What does this situation best illustrate?","options":{"A":"Customers never value after-sales service","B":"Price is the only factor customers consider","C":"Market research is unnecessary for small firms","D":"Customer needs include service and convenience, so the faster rival has gained a competitive advantage"},"correctOption":"D","correctAnswer":"Customer needs include service and convenience, so the faster rival has gained a competitive advantage","questionType":"MCQ","explanation":{"correct_reason":"Customers wanted repairs completed quickly, which is a service and convenience need, so the rival that promises same-day work has created a competitive advantage that persuaded several loyal buyers to switch.","distractor_reasons":{"A":"The loss of long-standing customers to a faster repair service shows that after-sales service is valued, so claiming customers never value it contradicts the evidence.","B":"Nothing in the stem mentions price; customers switched because of repair speed, which shows factors other than price can drive their choices.","C":"The owner is learning about customer priorities from the rival's success, which is exactly the kind of insight market research is meant to provide.","D":"Customers wanted repairs completed quickly, which is a service and convenience need, so the rival that promises same-day work has created a competitive advantage that persuaded several loyal buyers to switch."}}},{"id":"P1_U3_MCQ_1418","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1418","question":"Larkmead Landscapes has drafted a questionnaire that includes the statement: 'Don't you agree our excellent service is worth paying a premium for?' The owner wants reliable evidence about whether customers would accept higher prices. What is the main problem with this question?","options":{"A":"It is too short to be understood","B":"It is a leading question that pushes customers towards the answer the owner wants","C":"It is too expensive to administer","D":"It uses a random sample"},"correctOption":"B","correctAnswer":"It is a leading question that pushes customers towards the answer the owner wants","questionType":"MCQ","explanation":{"correct_reason":"The wording suggests that the service is excellent and that a premium is justified, so it nudges respondents towards agreeing and would give Larkmead Landscapes biased, unreliable evidence.","distractor_reasons":{"A":"The question is easy to understand, and its brevity is not the issue; the problem is the biased way it is phrased.","B":"The wording suggests that the service is excellent and that a premium is justified, so it nudges respondents towards agreeing and would give Larkmead Landscapes biased, unreliable evidence.","C":"Cost is not created by the wording of a single question, so the expense of administering the survey is not the main problem described.","D":"The stem does not say a random sample was used, and the sampling method is separate from the leading wording of this question."}}},{"id":"P1_U3_MCQ_1419","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1419","question":"Lanternfish Lamps launches a designer lamp at $180, far above similar lamps, targeting early adopters who want the newest style. After six months it plans to cut the price to attract wider buyers. Which strategy is this?","options":{"A":"Penetration pricing","B":"Price skimming","C":"Loss leader pricing","D":"Competitive pricing"},"correctOption":"B","correctAnswer":"Price skimming","questionType":"MCQ","explanation":{"correct_reason":"Price skimming launches at a high price to earn high margins from early adopters and then lowers the price to reach more price-sensitive buyers, which is Lanternfish Lamps' plan.","distractor_reasons":{"A":"Penetration pricing would start low and possibly rise later, the reverse of this high launch price, so it is not the best answer among the options given.","B":"Price skimming launches at a high price to earn high margins from early adopters and then lowers the price to reach more price-sensitive buyers, which is Lanternfish Lamps' plan.","C":"A loss leader is sold below cost to attract customers who buy other products, but this lamp is launched at a premium.","D":"Competitive pricing would match rivals rather than deliberately charging far more than similar lamps, so it is less suitable than the alternative described."}}},{"id":"P1_U3_MCQ_1420","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1420","question":"Lowther Leather sells the right to run a branded Lowther shop to entrepreneurs in two Gulf cities. Buyers pay an upfront fee and a share of sales, and must follow Lowther's product range, pricing rules and staff training. What method of international expansion is this?","options":{"A":"Licensing","B":"A joint venture","C":"Exporting","D":"Franchising"},"correctOption":"D","correctAnswer":"Franchising","questionType":"MCQ","explanation":{"correct_reason":"Franchising grants an independent operator the right to trade under a brand using a prescribed business format, which matches Lowther Leather's fees, product range and training rules.","distractor_reasons":{"A":"Licensing usually covers a design or patent rather than a complete shop format with pricing rules and staff training, which means it does not meet the requirement set out in the stem.","B":"A joint venture means shared ownership of a business, not selling operating rights to independent entrepreneurs, and it would be a poor decision for the business in this case.","C":"Exporting would mean sending Lowther products abroad, but here local entrepreneurs run branded shops under a franchise, so it is less suitable than the alternative described.","D":"Franchising grants an independent operator the right to trade under a brand using a prescribed business format, which matches Lowther Leather's fees, product range and training rules."}}},{"id":"P1_U3_MCQ_1421","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1421","question":"Fernacre Gardens used to design plant ranges first and then look for buyers. After a survey showed customers wanted low-maintenance plants for small balconies, it redesigned its whole range around that finding. Which approach to marketing is Fernacre Gardens now demonstrating?","options":{"A":"Market orientation","B":"Product orientation","C":"Production orientation","D":"Selling orientation that ignores research"},"correctOption":"A","correctAnswer":"Market orientation","questionType":"MCQ","explanation":{"correct_reason":"Market orientation means finding out what customers want and then designing products to meet those needs, which is what Fernacre Gardens did when it rebuilt its range around the balcony survey.","distractor_reasons":{"A":"Market orientation means finding out what customers want and then designing products to meet those needs, which is what Fernacre Gardens did when it rebuilt its range around the balcony survey.","B":"Product orientation means the business focuses on making goods it believes are good and then tries to sell them, the opposite of starting from customer research.","C":"Production orientation concentrates on efficient output and lowering costs rather than on researching and responding to customer preferences, which does not help the business achieve the outcome it wants.","D":"The business acted directly on survey evidence, so describing it as ignoring research reverses what the stem describes, and it would be a poor decision for the business in this case."}}},{"id":"P1_U3_MCQ_1422","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1422","question":"Marigold Mowers wants to survey 200 of its 9,000 previous customers. The owner writes every customer name on a ticket, mixes them in a drum and draws 200 tickets without looking. Which sampling method is being used?","options":{"A":"Random sampling","B":"Quota sampling","C":"Secondary research","D":"Observation"},"correctOption":"A","correctAnswer":"Random sampling","questionType":"MCQ","explanation":{"correct_reason":"Drawing tickets from a mixed drum gives every customer an equal chance of selection, which is the defining feature of random sampling, so Marigold Mowers is using a random sample.","distractor_reasons":{"A":"Drawing tickets from a mixed drum gives every customer an equal chance of selection, which is the defining feature of random sampling, so Marigold Mowers is using a random sample.","B":"Quota sampling sets fixed numbers of respondents in predetermined groups, but here every customer has an equal chance with no group targets.","C":"Secondary research uses data already collected by someone else, whereas the owner is selecting customers to question directly, which makes it a weaker choice than the correct option here.","D":"Observation means watching behaviour without asking questions, but this plan involves drawing customers to survey them, so it does not provide what the business actually needs."}}},{"id":"P1_U3_MCQ_1423","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1423","question":"Mossgrove Music charges $22 for a half-hour guitar lesson because the three other music schools in town all charge between $20 and $24. The owner monitors rivals' prices each term and adjusts accordingly. Which pricing strategy is Mossgrove Music using?","options":{"A":"Cost-plus pricing","B":"Price skimming","C":"Penetration pricing","D":"Competitive pricing"},"correctOption":"D","correctAnswer":"Competitive pricing","questionType":"MCQ","explanation":{"correct_reason":"Competitive pricing sets a price in line with rivals, and Mossgrove Music charges $22 within the $20 to $24 range used by the other music schools in town.","distractor_reasons":{"A":"Cost-plus pricing would build the fee from the cost of the lesson plus a markup, but the stem explains the fee by reference to rivals.","B":"Price skimming would set a high initial price for a new or unique service, not a fee matched to local competitors.","C":"Penetration pricing would undercut rivals to win customers quickly, whereas $22 sits inside the local $20 to $24 range, which means the arithmetic has been misapplied here.","D":"Competitive pricing sets a price in line with rivals, and Mossgrove Music charges $22 within the $20 to $24 range used by the other music schools in town."}}},{"id":"P1_U3_MCQ_1424","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1424","question":"Millrace Mills sells sliced bread in four countries. It has changed the sweetness and crust colour of its loaves in each market after research showed strong local preferences. Why has the company adapted its product rather than using one standard recipe?","options":{"A":"Consumer tastes and cultural preferences differ between markets","B":"Only legal requirements ever vary between countries","C":"Adaptation always reduces production costs","D":"Exchange rates determine how bread should taste"},"correctOption":"A","correctAnswer":"Consumer tastes and cultural preferences differ between markets","questionType":"MCQ","explanation":{"correct_reason":"Food tastes are shaped by culture and habit, so Millrace Mills changes sweetness and crust colour to match what shoppers in each country expect and prefer.","distractor_reasons":{"A":"Food tastes are shaped by culture and habit, so Millrace Mills changes sweetness and crust colour to match what shoppers in each country expect and prefer.","B":"Legal rules can differ, but the stem specifically reports local taste preferences, which are cultural rather than legal, so it is less suitable than the alternative described.","C":"Running several recipes usually raises costs by reducing economies of scale, so adaptation does not always cut costs, which makes it a weaker choice than the correct option here.","D":"Exchange rates affect prices and costs, not the sweetness or crust colour that consumers prefer, so it is not the best answer among the options given."}}},{"id":"P1_U3_MCQ_1425","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1425","question":"Kestrel Hollow Bikes earned revenue of $1,440,000 last year from 24,000 customers, most of whom bought once. The marketing team wants to know the average amount each customer spent so it can judge whether upselling could work. What was the average revenue per customer?","options":{"A":"$6","B":"$600","C":"$60","D":"$1,667"},"correctOption":"C","correctAnswer":"$60","questionType":"MCQ","explanation":{"correct_reason":"Average revenue per customer is total revenue divided by the number of customers, so $1,440,000 divided by 24,000 customers gives $60 spent per customer.","distractor_reasons":{"A":"$6 is a decimal place error; dividing $1,440,000 by 24,000 gives $60, not $6, so the average spend is ten times larger.","B":"$600 would require only 2,400 customers at the same revenue, which is one tenth of the 24,000 customers stated in the stem.","C":"Average revenue per customer is total revenue divided by the number of customers, so $1,440,000 divided by 24,000 customers gives $60 spent per customer.","D":"$1,667 comes from dividing the 24,000 customers by the $1,440,000 revenue and misreading the units, which is not an average spend figure."}}},{"id":"P1_U3_MCQ_1426","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1426","question":"Nutmeg Notes wants opinions from 60 shoppers. A researcher stands outside a station and deliberately questions 30 people aged under 30 and 30 people aged 30 or over, stopping when each group is full. Which sampling method is this?","options":{"A":"Random sampling","B":"Secondary research","C":"Quota sampling","D":"Test marketing"},"correctOption":"C","correctAnswer":"Quota sampling","questionType":"MCQ","explanation":{"correct_reason":"The researcher is filling fixed targets of 30 people in each age group, which is quota sampling because the sample is built to match predetermined group sizes rather than giving everyone an equal chance.","distractor_reasons":{"A":"Random sampling requires every member of the population to have an equal chance of selection, but here the researcher chooses people until each age quota is filled.","B":"Secondary research uses existing data, while this researcher is collecting new opinions directly from shoppers, so it is not the best answer among the options given.","C":"The researcher is filling fixed targets of 30 people in each age group, which is quota sampling because the sample is built to match predetermined group sizes rather than giving everyone an equal chance.","D":"Test marketing involves selling a product in a limited area, not selecting respondents to fill age quotas for a survey."}}},{"id":"P1_U3_MCQ_1427","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1427","question":"Nightjar Naturals sells its shampoo to retailers at a recommended retail price of $50 a bottle. The retailer keeps a 30% margin on that price and pays the rest to Nightjar Naturals. How much does Nightjar Naturals receive per bottle?","options":{"A":"$15","B":"$30","C":"$45","D":"$35"},"correctOption":"D","correctAnswer":"$35","questionType":"MCQ","explanation":{"correct_reason":"The retailer keeps 30% of the $50 retail price, which is $15, so Nightjar Naturals receives the remaining $50 minus $15, giving $35 per bottle.","distractor_reasons":{"A":"$15 is the retailer's margin, not the amount passed back to Nightjar Naturals, so it cannot be the correct result of this calculation.","B":"$30 would be the manufacturer's share if the retailer kept 40%, but the stem states a 30% margin, which is not the outcome produced by the figures provided.","C":"$45 would leave the retailer only $5, which is a 10% margin rather than the 30% stated, and the numbers in the stem do not support this figure.","D":"The retailer keeps 30% of the $50 retail price, which is $15, so Nightjar Naturals receives the remaining $50 minus $15, giving $35 per bottle."}}},{"id":"P1_U3_MCQ_1428","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1428","question":"Netherby Nets wants to sell fishing nets in three countries. Each requires different safety warnings, packaging languages and maximum mesh sizes before the nets can be sold legally. What explains these differences?","options":{"A":"Consumer protection and product regulations vary between countries","B":"All countries apply identical technical standards","C":"Branding is irrelevant in international markets","D":"Distribution costs are the same everywhere"},"correctOption":"A","correctAnswer":"Consumer protection and product regulations vary between countries","questionType":"MCQ","explanation":{"correct_reason":"Countries set their own consumer protection laws and technical standards, so Netherby Nets must meet different warning, language and mesh-size rules in each market.","distractor_reasons":{"A":"Countries set their own consumer protection laws and technical standards, so Netherby Nets must meet different warning, language and mesh-size rules in each market.","B":"The need for different warnings and mesh sizes shows that standards are not identical across the three countries, and it would be a poor decision for the business in this case.","C":"Branding still matters internationally, but the stem is about legal requirements rather than brand image, so it is less suitable than the alternative described.","D":"The stem describes regulatory differences, not transport or distribution costs, which does not help the business achieve the outcome it wants."}}},{"id":"P1_U3_MCQ_1429","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1429","question":"Northgate Noodles has spent $30,000 designing a distinctive red logo, matching packaging and a consistent slogan across its ready meals. The owner expects this investment to help the meals stand out on supermarket shelves. What is the main benefit of this branding?","options":{"A":"It guarantees lower production costs","B":"It removes the need to compete on quality","C":"It means the business no longer needs advertising","D":"It builds customer recognition and can support a higher price and repeat purchases"},"correctOption":"D","correctAnswer":"It builds customer recognition and can support a higher price and repeat purchases","questionType":"MCQ","explanation":{"correct_reason":"A recognisable logo, packaging and slogan help shoppers identify Northgate Noodles quickly, which builds brand recognition and can justify a higher price while encouraging repeat purchases.","distractor_reasons":{"A":"Branding adds design and promotion costs rather than guaranteeing lower production costs, and it does nothing to reduce the cost of ingredients or cooking.","B":"A strong brand can support quality perceptions but cannot remove competition; rivals still compete on taste, price and availability, so it is less suitable than the alternative described.","C":"Branding and advertising work together, and a logo alone does not spread awareness, so the need for advertising continues, which makes it a weaker choice than the correct option here.","D":"A recognisable logo, packaging and slogan help shoppers identify Northgate Noodles quickly, which builds brand recognition and can justify a higher price while encouraging repeat purchases."}}},{"id":"P1_U3_MCQ_1430","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1430","question":"Orchardgate Organics invited eight regular customers to a two-hour discussion about its new compostable packaging. A researcher guided the conversation while the group commented on the look, feel and disposal instructions. Which research method is being used?","options":{"A":"A focus group producing qualitative views","B":"A postal questionnaire producing numerical data","C":"Government secondary statistics","D":"Random sampling of the whole population"},"correctOption":"A","correctAnswer":"A focus group producing qualitative views","questionType":"MCQ","explanation":{"correct_reason":"A small guided discussion among selected customers is a focus group, and it produces qualitative opinions about the packaging that Orchardgate Organics can use to refine the design.","distractor_reasons":{"A":"A small guided discussion among selected customers is a focus group, and it produces qualitative opinions about the packaging that Orchardgate Organics can use to refine the design.","B":"A postal questionnaire is sent to respondents to complete alone, whereas these eight customers discussed the packaging together with a researcher present.","C":"Government statistics are secondary data collected by an official body, but these views were gathered directly from the firm's own customers.","D":"The stem describes a discussion group rather than the selection process used to choose a representative sample of all customers."}}},{"id":"P1_U3_MCQ_1431","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1431","question":"Oriel & Oak's best-selling oak shelf has had flat sales for two years, and the product is now in the maturity stage of its life cycle. The marketing team wants to extend its life rather than launch a replacement. Which action is most appropriate?","options":{"A":"Raise the price sharply without changing the product","B":"Add new finishes and a modular fitting to refresh the design","C":"Stop all advertising for the shelf","D":"Ignore the flat sales and make no changes"},"correctOption":"B","correctAnswer":"Add new finishes and a modular fitting to refresh the design","questionType":"MCQ","explanation":{"correct_reason":"An extension strategy refreshes a mature product to attract new and existing buyers, so adding finishes and a modular fitting gives Oriel & Oak's shelf a new reason to be purchased.","distractor_reasons":{"A":"A sharp price rise without product improvements is likely to accelerate decline by making the shelf less attractive than rivals.","B":"An extension strategy refreshes a mature product to attract new and existing buyers, so adding finishes and a modular fitting gives Oriel & Oak's shelf a new reason to be purchased.","C":"Cutting advertising during maturity reduces awareness and removes support for sales, which speeds up the product's decline, so it is not the best answer among the options given.","D":"Doing nothing leaves the shelf in its mature stage with flat sales and allows rivals to take customers, and it would not solve the problem described in the scenario."}}},{"id":"P1_U3_MCQ_1432","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1432","question":"Overdale Ovens aims to earn $18 million of sales in a national oven market worth $150 million. The board wants to know what share of the market this target represents before approving the expansion. What market share would the target require?","options":{"A":"8.3%","B":"12%","C":"18%","D":"1.2%"},"correctOption":"B","correctAnswer":"12%","questionType":"MCQ","explanation":{"correct_reason":"The target share is the sales target divided by the market value, so $18 million divided by $150 million multiplied by 100 equals 12% of the market.","distractor_reasons":{"A":"8.3% comes from dividing $150 million by $18 million, which reverses the market share calculation, and it therefore does not follow from the stated values.","B":"The target share is the sales target divided by the market value, so $18 million divided by $150 million multiplied by 100 equals 12% of the market.","C":"18% repeats the $18 million target as a percentage without dividing by the $150 million market, and it therefore does not follow from the stated values.","D":"1.2% is a decimal place error; $18 million is 12% of $150 million, not 1.2%, so it cannot be the correct result of this calculation."}}},{"id":"P1_U3_MCQ_1433","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1433","question":"Copperleaf Cosmetics had sales of $8.4 million last year, which represented 7% of the total market for its type of product. The finance director now wants to know the size of the whole market before approving an expansion plan. What was the total market size?","options":{"A":"$58.8 million","B":"$120 million","C":"$12 million","D":"$588 million"},"correctOption":"B","correctAnswer":"$120 million","questionType":"MCQ","explanation":{"correct_reason":"If $8.4 million is 7% of the market, the whole market equals $8.4 million divided by 0.07, which gives $120 million, so the market is far larger than Copperleaf's own sales.","distractor_reasons":{"A":"$58.8 million comes from multiplying $8.4 million by 7 instead of dividing by 0.07, so it treats the share as a multiplier.","B":"If $8.4 million is 7% of the market, the whole market equals $8.4 million divided by 0.07, which gives $120 million, so the market is far larger than Copperleaf's own sales.","C":"$12 million is close to the sales figure plus half of it and does not follow from dividing $8.4 million by 7%.","D":"$588 million is a decimal place error; dividing $8.4 million by 0.07 gives $120 million, not $588 million, which is not the outcome produced by the figures provided."}}},{"id":"P1_U3_MCQ_1434","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1434","question":"Pebblebrook Pools sent a questionnaire by post to 800 recent customers and received 240 completed replies. Before deciding how much confidence to place in the findings, the manager wants to know the response rate. What was the response rate?","options":{"A":"24%","B":"30%","C":"33.3%","D":"70%"},"correctOption":"B","correctAnswer":"30%","questionType":"MCQ","explanation":{"correct_reason":"The response rate is completed replies divided by questionnaires sent, so 240 divided by 800 multiplied by 100 equals a response rate of 30%.","distractor_reasons":{"A":"24% repeats the 240 replies as a percentage without dividing by the 800 questionnaires that were sent out, and it therefore does not follow from the stated values.","B":"The response rate is completed replies divided by questionnaires sent, so 240 divided by 800 multiplied by 100 equals a response rate of 30%.","C":"33.3% comes from dividing 800 by 240, which reverses the response rate calculation, so it does not match the figures given in the stem.","D":"70% is the proportion that did not reply, not the response rate of 30% that Pebblebrook Pools achieved, and the numbers in the stem do not support this figure."}}},{"id":"P1_U3_MCQ_1435","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1435","question":"Pinecrest Paints sells its emulsion in strong plastic tubs that carry the colour name, coverage details and safety warnings. The tubs also stack neatly for display. Which function of packaging is shown by the tub protecting the paint and carrying information?","options":{"A":"Reducing the rate of VAT","B":"Guaranteeing higher sales","C":"Replacing the need for branding","D":"Protecting the product and providing information to the buyer"},"correctOption":"D","correctAnswer":"Protecting the product and providing information to the buyer","questionType":"MCQ","explanation":{"correct_reason":"Packaging has several functions, and the strong tub protects the emulsion in transit while the label gives the colour, coverage and safety details that Pinecrest Paints' customers need.","distractor_reasons":{"A":"VAT is a tax set by government, and packaging design has no direct role in changing the rate charged, which means it does not meet the requirement set out in the stem.","B":"Good packaging supports sales but cannot guarantee them, because price, quality and rivals also influence demand, which means it does not meet the requirement set out in the stem.","C":"Packaging carries the brand and reinforces it, so it works alongside branding rather than replacing it, and it would not solve the problem described in the scenario.","D":"Packaging has several functions, and the strong tub protects the emulsion in transit while the label gives the colour, coverage and safety details that Pinecrest Paints' customers need."}}},{"id":"P1_U3_MCQ_1436","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1436","question":"Penhallow Pots has a small marketing budget and wants to reach craft shops in several countries. It posts making videos on social media, answers enquiries online and ships sample pots to interested retailers. What is the main benefit of this digital approach for international growth?","options":{"A":"It replaces the need for good product quality","B":"It removes cultural differences between markets","C":"It means no logistics or shipping are needed","D":"It provides low-cost global awareness and direct enquiries from buyers"},"correctOption":"D","correctAnswer":"It provides low-cost global awareness and direct enquiries from buyers","questionType":"MCQ","explanation":{"correct_reason":"Social media lets a small firm reach buyers in many countries at low cost, and direct enquiries mean Penhallow Pots can build overseas contacts without an expensive sales network.","distractor_reasons":{"A":"Videos can attract interest, but retailers will only reorder if the pots are good, so quality still matters, which makes it a weaker choice than the correct option here.","B":"Digital marketing crosses borders but does not remove differences in language, taste or business practice, and it would be a poor decision for the business in this case.","C":"Samples and sold pots still have to be packed and shipped, so logistics remain necessary, which means it does not meet the requirement set out in the stem.","D":"Social media lets a small firm reach buyers in many countries at low cost, and direct enquiries mean Penhallow Pots can build overseas contacts without an expensive sales network."}}},{"id":"P1_U3_MCQ_1437","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1437","question":"Tideline Surfwear finds that 40% of its sales come from customers who bought before, and these repeat buyers cost almost nothing to reach because they follow the brand online. The owner is comparing this with the cost of attracting new buyers. Why does customer loyalty matter here?","options":{"A":"It immediately lowers fixed costs","B":"It removes the need for good product quality","C":"It provides stable revenue and is usually cheaper than acquiring new customers","D":"It guarantees the market will grow"},"correctOption":"C","correctAnswer":"It provides stable revenue and is usually cheaper than acquiring new customers","questionType":"MCQ","explanation":{"correct_reason":"Repeat buyers generate a dependable flow of revenue and are cheap to reach through existing channels, so loyalty usually costs less than persuading new customers to try the brand.","distractor_reasons":{"A":"Loyalty may raise sales but does not immediately reduce fixed costs such as rent or machinery, which stay the same in the short run.","B":"Loyal customers still expect quality, and losing it would encourage them to switch, so loyalty does not remove the need for quality.","C":"Repeat buyers generate a dependable flow of revenue and are cheap to reach through existing channels, so loyalty usually costs less than persuading new customers to try the brand.","D":"Loyalty affects the firm's own sales, but total market growth depends on many other factors such as incomes and population."}}},{"id":"P1_U3_MCQ_1438","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1438","question":"Quarrystone Tiles wants to know how long customers spend in its showroom and which displays they stop at. A researcher sits quietly at the back and records movements and time spent without speaking to shoppers. Which method is being used?","options":{"A":"Observation","B":"A questionnaire","C":"A face-to-face interview","D":"Secondary research"},"correctOption":"A","correctAnswer":"Observation","questionType":"MCQ","explanation":{"correct_reason":"Observation involves watching and recording behaviour without questioning people, so the researcher is observing how long Quarrystone Tiles' customers spend and which displays attract them.","distractor_reasons":{"A":"Observation involves watching and recording behaviour without questioning people, so the researcher is observing how long Quarrystone Tiles' customers spend and which displays attract them.","B":"A questionnaire would require shoppers to answer written questions, but the researcher stays silent and only records what people do.","C":"An interview involves asking customers questions, whereas this researcher deliberately avoids speaking to them, which makes it a weaker choice than the correct option here.","D":"Secondary research uses existing data, but this researcher is collecting new evidence directly in the showroom, so it does not provide what the business actually needs."}}},{"id":"P1_U3_MCQ_1439","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1439","question":"Quickthorn Quilts sells only through its own website and keeps the full retail price instead of sharing it with shops. It also collects customers' email addresses and reviews directly. What is the main advantage of this direct distribution channel?","options":{"A":"It always lowers delivery costs","B":"It keeps the full retail price and gives direct access to customer data","C":"It removes the need for any promotion","D":"It avoids all competition"},"correctOption":"B","correctAnswer":"It keeps the full retail price and gives direct access to customer data","questionType":"MCQ","explanation":{"correct_reason":"Selling direct means Quickthorn Quilts does not give a retailer a share of the price and can gather email addresses and reviews, giving it both higher revenue per quilt and useful customer data.","distractor_reasons":{"A":"Selling online means the business handles delivery itself, which can raise rather than lower delivery costs, and it would be a poor decision for the business in this case.","B":"Selling direct means Quickthorn Quilts does not give a retailer a share of the price and can gather email addresses and reviews, giving it both higher revenue per quilt and useful customer data.","C":"A website still needs promotion to attract visitors, so direct selling does not remove the need for marketing, which makes it a weaker choice than the correct option here.","D":"Rivals can sell online too, so choosing a direct channel does not remove competition, and it would not solve the problem described in the scenario."}}},{"id":"P1_U3_MCQ_1440","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1440","question":"Ravensworth Ropes wants buyers to see it as the safest choice for professional climbers rather than as a cheap general-purpose supplier. It is changing its logo, sponsorship and pricing to support that image. What is this decision called?","options":{"A":"Market segmentation","B":"Mass marketing","C":"Market research","D":"Market positioning"},"correctOption":"D","correctAnswer":"Market positioning","questionType":"MCQ","explanation":{"correct_reason":"Market positioning is about creating a distinct place for a brand in customers' minds, so reshaping the logo, sponsorship and price to be seen as the safest professional rope is a positioning decision.","distractor_reasons":{"A":"Segmentation divides the market into groups of buyers, while this decision concerns the image Ravensworth Ropes wants within its chosen market.","B":"Mass marketing targets the whole market with one offer, but this strategy deliberately focuses on professional climbers, so it does not provide what the business actually needs.","C":"Market research gathers information, whereas the stem describes actions taken to shape customer perceptions, and it would not solve the problem described in the scenario.","D":"Market positioning is about creating a distinct place for a brand in customers' minds, so reshaping the logo, sponsorship and price to be seen as the safest professional rope is a positioning decision."}}},{"id":"P1_U3_MCQ_1441","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1441","question":"Oakhurst Optics gives every customer a free eye test and a two-year frame guarantee, while rival opticians charge separately for tests. The manager uses this offer in all advertising. What is the free test and guarantee best described as?","options":{"A":"A distribution channel","B":"A unique selling point","C":"A market segment","D":"A method of secondary research"},"correctOption":"B","correctAnswer":"A unique selling point","questionType":"MCQ","explanation":{"correct_reason":"A unique selling point is a feature that distinguishes a product from rivals, and the free eye test with a two-year guarantee does exactly that by giving Oakhurst Optics an advantage rivals do not match.","distractor_reasons":{"A":"A distribution channel describes how a product reaches the customer, such as shops or websites, not an added service included with the purchase.","B":"A unique selling point is a feature that distinguishes a product from rivals, and the free eye test with a two-year guarantee does exactly that by giving Oakhurst Optics an advantage rivals do not match.","C":"A market segment is a group of buyers with similar characteristics, whereas the free test and guarantee are features of the offer itself.","D":"Secondary research is the use of existing data, and the guarantee is a promotional feature rather than a research method."}}},{"id":"P1_U3_MCQ_1442","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1442","question":"Rosemere Rugs plans to sell a new washable rug nationally. Before the full launch, it stocks the range in five stores in one region for eight weeks and monitors sales and customer comments. Why is Rosemere Rugs using this approach?","options":{"A":"To guarantee the national launch will succeed","B":"To replace all other forms of market research","C":"To test customer response on a small scale and reduce the risk of a costly failure","D":"To cut the production cost of each rug"},"correctOption":"C","correctAnswer":"To test customer response on a small scale and reduce the risk of a costly failure","questionType":"MCQ","explanation":{"correct_reason":"A limited regional trial lets Rosemere Rugs see how shoppers react before committing to a national launch, which reduces the risk and cost of a full-scale failure.","distractor_reasons":{"A":"A trial provides evidence but cannot guarantee success, because demand in other regions and the actions of rivals may differ.","B":"The trial adds to the firm's research rather than replacing other methods such as surveys of customer preferences, so it is not the best answer among the options given.","C":"A limited regional trial lets Rosemere Rugs see how shoppers react before committing to a national launch, which reduces the risk and cost of a full-scale failure.","D":"Selling in five stores does not change the cost of making each rug, so the trial is about testing demand rather than cutting production costs."}}},{"id":"P1_U3_MCQ_1443","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1443","question":"Rowanberry Roasters used to sell coffee only to cafes within 20 miles of its roastery. It now sells beans through an online shop to households across the country. How has e-commerce mainly changed the place element of its marketing mix?","options":{"A":"It has removed the need for any distribution","B":"It has widened market reach far beyond the local area","C":"It has reduced the quality of the coffee","D":"It has eliminated competition from other roasters"},"correctOption":"B","correctAnswer":"It has widened market reach far beyond the local area","questionType":"MCQ","explanation":{"correct_reason":"E-commerce lets Rowanberry Roasters sell to households nationwide rather than only to local cafes, so the place element now covers a much wider market reach than before.","distractor_reasons":{"A":"Online orders still have to be packed and delivered, so distribution is changed rather than removed, which means it does not meet the requirement set out in the stem.","B":"E-commerce lets Rowanberry Roasters sell to households nationwide rather than only to local cafes, so the place element now covers a much wider market reach than before.","C":"The sales channel does not alter the roasting process, so selling online does not reduce the quality of the coffee.","D":"Other roasters can also sell online, and the internet may increase rather than eliminate competition, so it is not the best answer among the options given."}}},{"id":"P1_U3_MCQ_1444","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1444","question":"Sandalwood Saws includes free lifetime blade sharpening with every saw it sells to tree surgeons. Rivals sell similar saws but charge for sharpening. The company uses this service in its advertising. What is this an example of?","options":{"A":"Differentiation through added service","B":"Penetration pricing","C":"Market segmentation","D":"Franchising"},"correctOption":"A","correctAnswer":"Differentiation through added service","questionType":"MCQ","explanation":{"correct_reason":"Differentiation makes a product stand out from rivals, and free lifetime sharpening gives Sandalwood Saws a distinctive service that similar saws from competitors do not include.","distractor_reasons":{"A":"Differentiation makes a product stand out from rivals, and free lifetime sharpening gives Sandalwood Saws a distinctive service that similar saws from competitors do not include.","B":"Penetration pricing is a low launch price, but the stem describes an added service rather than a pricing tactic, and it would be a poor decision for the business in this case.","C":"Segmentation is about grouping customers, whereas this is a feature of the offer used to compete, so it is less suitable than the alternative described.","D":"Franchising involves licensing a business format to independent operators, which is unrelated to free sharpening, and it would not solve the problem described in the scenario."}}},{"id":"P1_U3_MCQ_1445","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1445","question":"Plumtree Preserves launched a premium range of small-batch jams. Sales of the range rose from $52 million to $65 million over the year as more shoppers bought speciality foods. By what percentage did sales of the premium range grow?","options":{"A":"13%","B":"20%","C":"80%","D":"25%"},"correctOption":"D","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"Growth is the increase divided by the original figure, so $65 million minus $52 million equals $13 million, and $13 million divided by $52 million multiplied by 100 gives 25% growth.","distractor_reasons":{"A":"13% is the absolute increase in millions of dollars placed over the original figure incorrectly, since $13 million is 25% of $52 million.","B":"20% does not match the figures; the increase of $13 million is exactly one quarter of the original $52 million, which is 25%.","C":"80% would be the result of dividing $52 million by $65 million, which reverses the growth calculation and understates the expansion.","D":"Growth is the increase divided by the original figure, so $65 million minus $52 million equals $13 million, and $13 million divided by $52 million multiplied by 100 gives 25% growth."}}},{"id":"P1_U3_MCQ_1446","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1446","question":"Saffron Street Spices surveyed 600 shoppers about their preferred spice strength. Exactly 150 said they preferred mild blends, while the rest chose medium or hot. The owner wants to know what proportion of the sample preferred mild. What percentage preferred mild?","options":{"A":"15%","B":"40%","C":"25%","D":"4%"},"correctOption":"C","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"The proportion preferring mild is 150 out of 600, and 150 divided by 600 multiplied by 100 equals 25%, so one quarter of the sample chose mild blends.","distractor_reasons":{"A":"15% would require 90 of the 600 respondents to choose mild, but the stem states that 150 did so, so it would give the wrong total for the business.","B":"40% would require 240 respondents, which is the number choosing medium or hot rather than the 150 choosing mild, and it therefore does not follow from the stated values.","C":"The proportion preferring mild is 150 out of 600, and 150 divided by 600 multiplied by 100 equals 25%, so one quarter of the sample chose mild blends.","D":"4% is a decimal place error; 150 divided by 600 is 0.25, which is 25% rather than 4%, and the numbers in the stem do not support this figure."}}},{"id":"P1_U3_MCQ_1447","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1447","question":"Stonewick Studios has produced a radio advert that gives its new address, opening hours, course dates and the instruments it teaches. The advert does not compare the studio with rivals or offer a discount. What type of advertising is this?","options":{"A":"Persuasive advertising","B":"Informative advertising","C":"Sales promotion","D":"Sponsorship"},"correctOption":"B","correctAnswer":"Informative advertising","questionType":"MCQ","explanation":{"correct_reason":"Informative advertising gives customers factual details about a product or service, and this advert supplies the address, hours, dates and instruments taught by Stonewick Studios.","distractor_reasons":{"A":"Persuasive advertising tries to convince buyers to choose one brand over another, but this advert simply states facts without comparison.","B":"Informative advertising gives customers factual details about a product or service, and this advert supplies the address, hours, dates and instruments taught by Stonewick Studios.","C":"Sales promotion offers a short-term incentive such as a discount, and no such incentive is described here, which does not help the business achieve the outcome it wants.","D":"Sponsorship involves funding an event or team in return for publicity, which this radio advert does not involve, so it is less suitable than the alternative described."}}},{"id":"P1_U3_MCQ_1448","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1448","question":"Tarnbrook Tables makes garden tables at a unit cost of $18. Packing and freight to an overseas customer add $3 per table, and the tables sell abroad for $30 each. The export manager wants the contribution each exported table makes. What is the contribution per unit?","options":{"A":"$9","B":"$12","C":"$21","D":"$30"},"correctOption":"A","correctAnswer":"$9","questionType":"MCQ","explanation":{"correct_reason":"Contribution is the selling price minus the variable cost of getting the table to the customer, so $30 minus the $18 unit cost and $3 freight equals $9 per table.","distractor_reasons":{"A":"Contribution is the selling price minus the variable cost of getting the table to the customer, so $30 minus the $18 unit cost and $3 freight equals $9 per table.","B":"$12 ignores the $3 packing and freight, so it overstates the contribution from each exported table, and the numbers in the stem do not support this figure.","C":"$21 is the total variable cost of $18 plus $3, not the contribution left after those costs, and it therefore does not follow from the stated values.","D":"$30 is the selling price itself, before any of the unit or freight costs are deducted, so it cannot be the correct result of this calculation."}}},{"id":"P1_U3_MCQ_1449","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1449","question":"Redkite Rail has seen passenger numbers rise sharply since it introduced contactless payment, live delay alerts and seat reservations through a mobile app. Managers say commuters now expect these digital services as standard. Which change in customer behaviour does this best reflect?","options":{"A":"Falling household incomes","B":"A growing demand for convenience and digital service","C":"A preference for paper tickets and queues","D":"A decline in online shopping"},"correctOption":"B","correctAnswer":"A growing demand for convenience and digital service","questionType":"MCQ","explanation":{"correct_reason":"Passengers are choosing the operator that lets them pay, plan and reserve quickly through a phone, which shows a growing demand for convenience and digital service rather than a preference for older methods.","distractor_reasons":{"A":"The stem reports rising passenger numbers after digital improvements, and it gives no evidence about household incomes falling, which does not help the business achieve the outcome it wants.","B":"Passengers are choosing the operator that lets them pay, plan and reserve quickly through a phone, which shows a growing demand for convenience and digital service rather than a preference for older methods.","C":"The rise followed the introduction of contactless payment and an app, so passengers are moving away from paper tickets rather than towards them.","D":"Rail travel and online shopping are different activities, and nothing in the stem suggests that online shopping is declining, so it is not the best answer among the options given."}}},{"id":"P1_U3_MCQ_1450","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1450","question":"Thornbury Tandems collects 1,000 customer ratings, each scored from 1 to 5, after every repair. The manager plans to calculate an average score and compare it with last year's figure. Why is this data best described as quantitative?","options":{"A":"Because it is based on personal opinions","B":"Because the sample is small","C":"Because it was collected face to face","D":"Because it consists of numerical values that can be analysed statistically"},"correctOption":"D","correctAnswer":"Because it consists of numerical values that can be analysed statistically","questionType":"MCQ","explanation":{"correct_reason":"The ratings are numbers on a scale, so the manager can calculate averages and compare periods, which makes the data quantitative rather than descriptive opinion.","distractor_reasons":{"A":"Opinions expressed in words would be qualitative, whereas these responses are recorded as numbers on a fixed scale, and it would not solve the problem described in the scenario.","B":"Quantitative data can come from samples of any size, so the size of the sample does not determine whether data is quantitative.","C":"The way data is collected does not make it quantitative; it is the numerical form of the ratings that does.","D":"The ratings are numbers on a scale, so the manager can calculate averages and compare periods, which makes the data quantitative rather than descriptive opinion."}}},{"id":"P1_U3_MCQ_1451","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1451","question":"Tanglewood Toys prints vouchers that give parents $5 off any purchase over $30 during the first week of December. The offer runs for seven days only and is designed to bring shoppers into the store before Christmas. Which promotional method is this?","options":{"A":"Public relations","B":"Sales promotion","C":"Sponsorship","D":"Direct mail"},"correctOption":"B","correctAnswer":"Sales promotion","questionType":"MCQ","explanation":{"correct_reason":"A short-term incentive such as $5 off a purchase is sales promotion, used by Tanglewood Toys to stimulate demand during a specific week.","distractor_reasons":{"A":"Public relations seeks favourable publicity through media coverage, not a time-limited money-off voucher, so it is not the best answer among the options given.","B":"A short-term incentive such as $5 off a purchase is sales promotion, used by Tanglewood Toys to stimulate demand during a specific week.","C":"Sponsorship links a brand to an event or team, whereas this offer is a discount voucher for shoppers, and it would be a poor decision for the business in this case.","D":"Direct mail sends material to named individuals, but the stem describes vouchers available to parents generally in store, so it is less suitable than the alternative described."}}},{"id":"P1_U3_MCQ_1452","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1452","question":"Ulverston Umbrellas sells at $40 in its home market but plans to charge the equivalent of $22 in a lower-income country where rivals sell similar umbrellas for about $20. The company still expects a profit at that price. Why lower the price in this market?","options":{"A":"Production costs are higher there","B":"A high price would strengthen its premium image","C":"Lower purchasing power means customers cannot pay the home-market price","D":"Import tariffs automatically set the price"},"correctOption":"C","correctAnswer":"Lower purchasing power means customers cannot pay the home-market price","questionType":"MCQ","explanation":{"correct_reason":"Average incomes are lower in the new market, so customers cannot afford the $40 home price and Ulverston Umbrellas must price near local rivals at about $22 to win sales.","distractor_reasons":{"A":"Higher production costs would push the price up, but the stem explains the lower price by local incomes and rival prices.","B":"A premium image would require a high price, yet the plan is to price close to cheaper local rivals, and it would be a poor decision for the business in this case.","C":"Average incomes are lower in the new market, so customers cannot afford the $40 home price and Ulverston Umbrellas must price near local rivals at about $22 to win sales.","D":"Tariffs may affect the final price, but the stem explains the decision by purchasing power and competition, which does not help the business achieve the outcome it wants."}}},{"id":"P1_U3_MCQ_1453","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1453","question":"Saltmarsh Seafoods sells one standard frozen fish range to supermarkets across the country, producing in very large volumes so that each pack costs less to make. It does not tailor the range to particular groups of shoppers. Which approach is Saltmarsh Seafoods using?","options":{"A":"Mass marketing","B":"Niche marketing","C":"Market segmentation","D":"Product differentiation"},"correctOption":"A","correctAnswer":"Mass marketing","questionType":"MCQ","explanation":{"correct_reason":"Mass marketing means selling one standard product to the whole market rather than targeting a small segment, and Saltmarsh Seafoods does this by selling a single frozen range nationally at high volume.","distractor_reasons":{"A":"Mass marketing means selling one standard product to the whole market rather than targeting a small segment, and Saltmarsh Seafoods does this by selling a single frozen range nationally at high volume.","B":"Niche marketing focuses on a small, specialised group of customers, but this business sells a standard range to supermarkets across the whole country.","C":"Market segmentation means dividing buyers into groups and targeting them separately, which the stem says the business does not do.","D":"Product differentiation means making the offer distinct from rivals, yet the stem describes a standard range sold on low unit cost rather than distinctive features."}}},{"id":"P1_U3_MCQ_1454","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1454","question":"Umberly Umbrellas plans to email an online survey to 5,000 customers because it is cheap and results arrive within days. The owner is aware, however, that some older customers rarely use email. What is the main limitation of this research method?","options":{"A":"It guarantees a representative sample","B":"It always produces a high response rate","C":"It may exclude customers without internet access and bias the results","D":"It cannot produce quantitative data"},"correctOption":"C","correctAnswer":"It may exclude customers without internet access and bias the results","questionType":"MCQ","explanation":{"correct_reason":"An email-only survey reaches customers who use the internet, so older or less connected customers may be left out and the results may not represent all of Umberly Umbrellas' buyers.","distractor_reasons":{"A":"Reaching only email users makes the sample less representative, so an online survey cannot guarantee a representative sample, and it would be a poor decision for the business in this case.","B":"Online surveys often suffer from low response rates, and nothing in the stem suggests that most recipients will reply, which does not help the business achieve the outcome it wants.","C":"An email-only survey reaches customers who use the internet, so older or less connected customers may be left out and the results may not represent all of Umberly Umbrellas' buyers.","D":"Online surveys can include rating scales and multiple-choice items, so they are perfectly capable of producing quantitative data, and it would not solve the problem described in the scenario."}}},{"id":"P1_U3_MCQ_1455","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1455","question":"Underhill Upholstery pays $12,000 a year to have its name printed on the shirts of a local football club that plays in front of crowds and appears on regional television. The owner wants wider awareness rather than immediate discount sales. Which promotional method is being used?","options":{"A":"Sales promotion","B":"Sponsorship","C":"Personal selling","D":"Market research"},"correctOption":"B","correctAnswer":"Sponsorship","questionType":"MCQ","explanation":{"correct_reason":"Sponsorship funds an event or team in exchange for brand exposure, and Underhill Upholstery's payment puts its name on the club's shirts and on regional television.","distractor_reasons":{"A":"Sales promotion uses short-term incentives such as coupons, not a season-long payment to a football club, which does not help the business achieve the outcome it wants.","B":"Sponsorship funds an event or team in exchange for brand exposure, and Underhill Upholstery's payment puts its name on the club's shirts and on regional television.","C":"Personal selling involves direct conversations with individual buyers, which is not what shirt sponsorship involves, and it would not solve the problem described in the scenario.","D":"Market research gathers information about customers, whereas this payment is intended to raise public awareness of the brand, and it would not solve the problem described in the scenario."}}},{"id":"P1_U3_MCQ_1456","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1456","question":"Vexley Vacuums wants to sell in a country where retailers control access to shoppers and local regulation is unfamiliar. It appoints an established local distributor that already supplies 300 stores. Why is this distribution partner useful?","options":{"A":"It removes all set-up costs","B":"It guarantees that every store will stock the vacuums","C":"It knows the market and already provides access to retail outlets","D":"It removes the need for any market research"},"correctOption":"C","correctAnswer":"It knows the market and already provides access to retail outlets","questionType":"MCQ","explanation":{"correct_reason":"A local distributor already understands the regulations and has relationships with 300 stores, giving Vexley Vacuums immediate access to retail outlets it could not easily build alone.","distractor_reasons":{"A":"Appointing a distributor may reduce some costs, but the firm still incurs costs such as stock and agreements, so they are not removed.","B":"A distributor supplies many stores but cannot guarantee that every one will agree to stock a new brand, so it does not provide what the business actually needs.","C":"A local distributor already understands the regulations and has relationships with 300 stores, giving Vexley Vacuums immediate access to retail outlets it could not easily build alone.","D":"The distributor's knowledge helps, but Vexley Vacuums still needs research on demand, pricing and competitors, so it is not the best answer among the options given."}}},{"id":"P1_U3_MCQ_1457","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1457","question":"Thistlewick Tea sold 3,600 packs last month in a regional market where total sales were 60,000 packs. The marketing manager is preparing a report for a bank loan application and needs the brand's share of this market. What market share did Thistlewick Tea hold?","options":{"A":"0.6%","B":"6%","C":"16.7%","D":"60%"},"correctOption":"B","correctAnswer":"6%","questionType":"MCQ","explanation":{"correct_reason":"Market share equals the firm's sales divided by total market sales, so 3,600 packs divided by 60,000 packs multiplied by 100 gives Thistlewick Tea a share of 6%.","distractor_reasons":{"A":"0.6% is a decimal place error; 3,600 divided by 60,000 is 0.06, which converts to 6% rather than 0.6%, and it therefore does not follow from the stated values.","B":"Market share equals the firm's sales divided by total market sales, so 3,600 packs divided by 60,000 packs multiplied by 100 gives Thistlewick Tea a share of 6%.","C":"16.7% comes from dividing 60,000 by 3,600, which reverses the market share calculation, and the numbers in the stem do not support this figure.","D":"60% would mean the brand sold more than half of all packs, but 3,600 out of 60,000 is only one tenth of that share."}}},{"id":"P1_U3_MCQ_1458","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1458","question":"Velvet Fern Fashion has set aside $18,000 for market research next year. The plan allocates 45% of this budget to fieldwork such as interviews and store trials. How much money is allocated to fieldwork?","options":{"A":"$4,500","B":"$8,100","C":"$9,900","D":"$810"},"correctOption":"B","correctAnswer":"$8,100","questionType":"MCQ","explanation":{"correct_reason":"Fieldwork receives 45% of the $18,000 budget, and 0.45 multiplied by $18,000 equals $8,100, leaving the remaining $9,900 for other research activities.","distractor_reasons":{"A":"$4,500 is 25% of $18,000, not the 45% share stated for fieldwork in the research plan, and it therefore does not follow from the stated values.","B":"Fieldwork receives 45% of the $18,000 budget, and 0.45 multiplied by $18,000 equals $8,100, leaving the remaining $9,900 for other research activities.","C":"$9,900 is the 55% left after fieldwork, so it is the amount for other activities rather than the fieldwork allocation.","D":"$810 is a decimal place error; 45% of $18,000 is $8,100, ten times larger than this figure, and the numbers in the stem do not support this figure."}}},{"id":"P1_U3_MCQ_1459","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1459","question":"Verbena Vintners is planning a launch campaign. A television slot costs $28,000, social media advertising costs $6,500 and printed leaflets cost $3,500. The owner wants the total cost before deciding whether the campaign fits the budget. What is the total campaign cost?","options":{"A":"$34,500","B":"$37,500","C":"$38,000","D":"$48,000"},"correctOption":"C","correctAnswer":"$38,000","questionType":"MCQ","explanation":{"correct_reason":"Adding the three media costs gives $28,000 plus $6,500 plus $3,500, which equals $38,000 for the complete launch campaign. This is exactly the outcome the figures and the scenario point to.","distractor_reasons":{"A":"$34,500 adds only the television and social media costs and omits the $3,500 for printed leaflets, so it cannot be the correct result of this calculation.","B":"$37,500 leaves out $500 of the stated costs and does not match the three figures in the stem, which is not the outcome produced by the figures provided.","C":"Adding the three media costs gives $28,000 plus $6,500 plus $3,500, which equals $38,000 for the complete launch campaign. This is exactly the outcome the figures and the scenario point to.","D":"$48,000 adds an extra $10,000 that is not part of any of the three stated costs, so it would give the wrong total for the business."}}},{"id":"P1_U3_MCQ_1460","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1460","question":"Westray Windows has been advertising that its double glazing is '50% cheaper than any rival' without any evidence. A trade body warns that the claim breaks advertising rules. Why should Westray Windows stop using the claim?","options":{"A":"Misleading claims are unethical and illegal and can damage customer trust","B":"All advertising of windows is prohibited","C":"Making claims always raises production costs","D":"Customers dislike every form of advertising"},"correctOption":"A","correctAnswer":"Misleading claims are unethical and illegal and can damage customer trust","questionType":"MCQ","explanation":{"correct_reason":"An unsupported '50% cheaper' claim misleads buyers, breaches advertising rules and risks fines and lost trust, so Westray Windows should withdraw it and use evidence-based messages.","distractor_reasons":{"A":"An unsupported '50% cheaper' claim misleads buyers, breaches advertising rules and risks fines and lost trust, so Westray Windows should withdraw it and use evidence-based messages.","B":"Advertising windows is allowed, and the problem is the unproven claim rather than the product category, which does not help the business achieve the outcome it wants.","C":"The wording of an advert does not change factory costs, so the issue is honesty and legality, not production expense.","D":"Customers may respond well to honest advertising, so general dislike of advertising is not the reason to stop this claim."}}},{"id":"P1_U3_MCQ_1461","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1461","question":"Vantage Vans supplies fleets of delivery vehicles to courier firms and also sells a few vans to individual tradespeople. Its research shows fleet buyers care about servicing contracts, while households care about price. Which segmentation variable is most useful for separating these two groups?","options":{"A":"The type of customer, business or household","B":"The colour of the vehicle","C":"The number of wheels on the vehicle","D":"The day of the week of purchase"},"correctOption":"A","correctAnswer":"The type of customer, business or household","questionType":"MCQ","explanation":{"correct_reason":"Fleet buyers and households have different needs and buying processes, so segmenting by type of customer, business versus household, is the most useful way to separate them before choosing a marketing approach.","distractor_reasons":{"A":"Fleet buyers and households have different needs and buying processes, so segmenting by type of customer, business versus household, is the most useful way to separate them before choosing a marketing approach.","B":"Vehicle colour is a product feature that can be varied for any buyer, and it does not explain the different servicing and price priorities described.","C":"The number of wheels is the same for the delivery vans and the household vans, so it cannot separate the two groups at all.","D":"The day of purchase is a timing detail rather than a characteristic that explains why fleet buyers and households want different things."}}},{"id":"P1_U3_MCQ_1462","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1462","question":"Wrenfield Interiors surveyed 30 of its 12,000 customers about a new design service and found that 70% were interested. The owner plans to base a $200,000 investment on this result. What is the main weakness of the research?","options":{"A":"The sample is far too large to manage","B":"The research was completely free","C":"The sample is too small to be representative, so the findings may be unreliable","D":"The results are certain to be biased upwards"},"correctOption":"C","correctAnswer":"The sample is too small to be representative, so the findings may be unreliable","questionType":"MCQ","explanation":{"correct_reason":"Thirty replies out of 12,000 customers is a tiny fraction of the customer base, so the 70% result may not reflect the wider market and is a shaky basis for a $200,000 decision.","distractor_reasons":{"A":"Thirty respondents is a small sample, not an unmanageably large one, so size is a problem in the opposite direction.","B":"Cost is not the issue raised; the concern is whether such a small number of replies can represent 12,000 customers.","C":"Thirty replies out of 12,000 customers is a tiny fraction of the customer base, so the 70% result may not reflect the wider market and is a shaky basis for a $200,000 decision.","D":"The direction of any bias is not known from the stem, and the real problem is the limited sample rather than a proven upward bias."}}},{"id":"P1_U3_MCQ_1463","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1463","question":"Whitlow Watchmakers sells its watches in rigid leather boxes with a soft lining and a numbered certificate inside. The boxes cost $9 each, well above ordinary cardboard packaging. What is the main marketing purpose of this packaging?","options":{"A":"To lower the unit cost of each watch","B":"To enhance perceived quality and support a premium price","C":"To reduce the need for product quality","D":"To guarantee repeat purchases"},"correctOption":"B","correctAnswer":"To enhance perceived quality and support a premium price","questionType":"MCQ","explanation":{"correct_reason":"Premium packaging shapes how buyers judge a product, so the leather box and certificate make Whitlow Watchmakers' watches feel more valuable and help justify a high price.","distractor_reasons":{"A":"At $9 each the boxes raise costs rather than lower them, so cost saving is not the purpose, which is not the outcome produced by the figures provided.","B":"Premium packaging shapes how buyers judge a product, so the leather box and certificate make Whitlow Watchmakers' watches feel more valuable and help justify a high price.","C":"Packaging can create an impression but cannot compensate for a poor watch, so product quality still matters, which does not help the business achieve the outcome it wants.","D":"Attractive packaging may encourage a first purchase but cannot guarantee that a customer will return, and it would not solve the problem described in the scenario."}}},{"id":"P1_U3_MCQ_1464","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1464","question":"Yalding Yurts earned $4.2 million from overseas sales last year. After appointing agents in two new countries, overseas sales rose to $5.46 million this year. The directors want to measure the growth in international revenue. By what percentage did overseas sales grow?","options":{"A":"23%","B":"30%","C":"26%","D":"130%"},"correctOption":"B","correctAnswer":"30%","questionType":"MCQ","explanation":{"correct_reason":"Overseas sales rose by $1.26 million, and $1.26 million divided by the original $4.2 million multiplied by 100 gives 30% growth in international revenue.","distractor_reasons":{"A":"23% does not match the figures; the $1.26 million increase is exactly 30% of the original $4.2 million, so it does not match the figures given in the stem.","B":"Overseas sales rose by $1.26 million, and $1.26 million divided by the original $4.2 million multiplied by 100 gives 30% growth in international revenue.","C":"26% comes from dividing the increase by the new $5.46 million figure rather than by the original $4.2 million, and it therefore does not follow from the stated values.","D":"130% wrongly treats the new $5.46 million as a percentage of the original $4.2 million instead of measuring the change."}}},{"id":"P1_U3_MCQ_1465","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1465","question":"Yarrowfield Yarns faces imported yarn that sells for 20% less than its own product. The owner cannot match the import price without making a loss and is deciding how to compete instead. Which response is most likely to protect Yarrowfield Yarns' sales?","options":{"A":"Ignore the imports and change nothing","B":"Raise prices further above the imports","C":"Emphasise British wool quality and traceable origin to differentiate the yarn","D":"Stop selling yarn altogether"},"correctOption":"C","correctAnswer":"Emphasise British wool quality and traceable origin to differentiate the yarn","questionType":"MCQ","explanation":{"correct_reason":"When a rival competes on lower price, a firm that cannot match it can differentiate by stressing quality and traceable British origin, giving customers a reason to pay more for Yarrowfield Yarns.","distractor_reasons":{"A":"Doing nothing leaves customers with a cheaper import and no new reason to stay, so sales are likely to keep falling.","B":"Raising prices widens the gap with the cheaper imports and makes the yarn less attractive unless a clear quality reason is given.","C":"When a rival competes on lower price, a firm that cannot match it can differentiate by stressing quality and traceable British origin, giving customers a reason to pay more for Yarrowfield Yarns.","D":"Withdrawing from the market abandons existing customers and sales rather than competing, and it does not address the import threat."}}},{"id":"P1_U3_MCQ_1466","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1466","question":"Yewbarrow Yoghurts is preparing a 2026 launch and is using a survey of consumer food preferences published in 2019. The marketing manager likes the report because it is detailed and cheap to obtain. What is the main risk of relying on this source?","options":{"A":"The data may be outdated and no longer reflect current tastes","B":"Secondary data is always incorrect","C":"Published reports are too expensive for small firms","D":"The sample must have been too large"},"correctOption":"A","correctAnswer":"The data may be outdated and no longer reflect current tastes","questionType":"MCQ","explanation":{"correct_reason":"A seven-year-old report may describe preferences that have since changed, so Yewbarrow Yoghurts could design its 2026 launch around outdated tastes and lose sales.","distractor_reasons":{"A":"A seven-year-old report may describe preferences that have since changed, so Yewbarrow Yoghurts could design its 2026 launch around outdated tastes and lose sales.","B":"Secondary data can be reliable, and the issue here is the age of the report rather than a claim that all such data is wrong.","C":"The stem says the report is cheap to obtain, so expense is not the limitation being described, which means it does not meet the requirement set out in the stem.","D":"A large sample is usually an advantage, and nothing in the stem suggests that sample size is the problem, so it does not provide what the business actually needs."}}},{"id":"P1_U3_MCQ_1467","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1467","question":"Yarrowbank Yachts has redesigned its smallest yacht so that one person can raise the mast and handle it in strong winds. The change is intended to appeal to solo sailors. Which element of the marketing mix has been changed?","options":{"A":"Price","B":"Place","C":"Product","D":"Promotion"},"correctOption":"C","correctAnswer":"Product","questionType":"MCQ","explanation":{"correct_reason":"The product element covers design, features and performance, so redesigning the yacht for easier solo handling is a change to Yarrowbank Yachts' product.","distractor_reasons":{"A":"Price refers to what customers pay, and no change to the yacht's price is described, which does not help the business achieve the outcome it wants.","B":"Place concerns how the yacht reaches buyers, such as dealerships or boat shows, not its design, which means it does not meet the requirement set out in the stem.","C":"The product element covers design, features and performance, so redesigning the yacht for easier solo handling is a change to Yarrowbank Yachts' product.","D":"Promotion covers advertising and other communication, whereas the change here is to the physical yacht itself, so it is less suitable than the alternative described."}}},{"id":"P1_U3_MCQ_1468","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1468","question":"Zouch Zesters has switched to compostable sachets and a recyclable outer box, and now features these changes in its adverts to shops and shoppers. The owner hopes this will appeal to buyers who avoid unnecessary plastic. What is the main marketing benefit of this change?","options":{"A":"It appeals to environmentally conscious customers and differentiates the brand","B":"It always lowers packaging costs","C":"It removes competition from other spice brands","D":"It means the company no longer needs to prove its claims"},"correctOption":"A","correctAnswer":"It appeals to environmentally conscious customers and differentiates the brand","questionType":"MCQ","explanation":{"correct_reason":"Environmental concerns influence many buyers, so compostable sachets and a recyclable box give Zouch Zesters a meaningful difference that can attract shoppers who care about plastic waste.","distractor_reasons":{"A":"Environmental concerns influence many buyers, so compostable sachets and a recyclable box give Zouch Zesters a meaningful difference that can attract shoppers who care about plastic waste.","B":"Compostable materials often cost more than conventional plastic, so the change does not automatically reduce costs, and it would be a poor decision for the business in this case.","C":"Rivals can also adopt greener packaging, so the change does not remove competition, which does not help the business achieve the outcome it wants.","D":"Green claims must still be accurate and provable, or they risk misleading customers and breaking advertising rules, which does not help the business achieve the outcome it wants."}}},{"id":"P1_U3_MCQ_1469","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1469","question":"Zephyr Analytics estimates that the market for small-business data tools is worth $300 million a year. The founders want to win an 8% share within three years and are setting a sales target for their business plan. What sales revenue would an 8% share represent?","options":{"A":"$24 million","B":"$37.5 million","C":"$2.4 million","D":"$240 million"},"correctOption":"A","correctAnswer":"$24 million","questionType":"MCQ","explanation":{"correct_reason":"An 8% share of a $300 million market is found by multiplying $300 million by 0.08, which gives a sales target of $24 million for Zephyr Analytics.","distractor_reasons":{"A":"An 8% share of a $300 million market is found by multiplying $300 million by 0.08, which gives a sales target of $24 million for Zephyr Analytics.","B":"$37.5 million comes from dividing $300 million by 8%, which treats the share as a divisor rather than a proportion of the market.","C":"$2.4 million is a decimal place error; 8% of $300 million is $24 million, ten times larger, which is inconsistent with the values quoted above.","D":"$240 million would be an 80% share, far above the 8% target the founders set, so it does not match the figures given in the stem."}}},{"id":"P1_U3_MCQ_1470","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1470","question":"Zinc & Zest surveyed a random sample of 400 households in a town of 25,000 households. Eighteen per cent of those surveyed said they buy energy bars every week. The owner wants a rough estimate of weekly energy-bar buyers in the town. How many households does the survey suggest?","options":{"A":"450","B":"4,500","C":"7,200","D":"45,000"},"correctOption":"B","correctAnswer":"4,500","questionType":"MCQ","explanation":{"correct_reason":"The survey indicates 18% of households buy energy bars weekly, and 0.18 multiplied by 25,000 households equals 4,500 households in the town.","distractor_reasons":{"A":"450 is a decimal place error; 18% of 25,000 is 4,500, ten times larger than this estimate, so it would give the wrong total for the business.","B":"The survey indicates 18% of households buy energy bars weekly, and 0.18 multiplied by 25,000 households equals 4,500 households in the town.","C":"7,200 would follow from a 28.8% share, not the 18% found in the survey, so it does not match the figures given in the stem.","D":"45,000 exceeds the 25,000 households in the town, so it cannot be a valid estimate, which is not the outcome produced by the figures provided."}}},{"id":"P1_U3_MCQ_1471","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1471","question":"Zenith Zips makes zips in large batches and sells them to a wholesaler, which splits the batches and supplies hundreds of small clothing workshops that each need only a few hundred zips. What role does the wholesaler perform?","options":{"A":"It sets the advertising budget for Zenith Zips","B":"It owns all the clothing workshops","C":"It breaks bulk and distributes small quantities to many retailers","D":"It manufactures the zips"},"correctOption":"C","correctAnswer":"It breaks bulk and distributes small quantities to many retailers","questionType":"MCQ","explanation":{"correct_reason":"A wholesaler buys in bulk and breaks it into smaller quantities for many small buyers, which is how the wholesaler connects Zenith Zips with hundreds of workshops that need only small orders.","distractor_reasons":{"A":"Advertising budgets are set by the producer or retailer, and the wholesaler's role in this stem is distribution rather than promotion.","B":"The workshops are separate businesses buying zips, not outlets owned by the wholesaler, which makes it a weaker choice than the correct option here.","C":"A wholesaler buys in bulk and breaks it into smaller quantities for many small buyers, which is how the wholesaler connects Zenith Zips with hundreds of workshops that need only small orders.","D":"Zenith Zips makes the zips, while the wholesaler only buys, splits and resells them, and it would not solve the problem described in the scenario."}}},{"id":"P1_U3_MCQ_1472","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1472","question":"Amberwood Apiaries records each customer's past orders, favourite honey types and usual order size, then sends tailored offers and reminders before the customer normally reorders. What marketing technique is being used?","options":{"A":"Market research","B":"Market segmentation alone","C":"Franchising","D":"Customer relationship management"},"correctOption":"D","correctAnswer":"Customer relationship management","questionType":"MCQ","explanation":{"correct_reason":"Customer relationship management uses detailed customer data to build loyalty through personalised contact, which is what Amberwood Apiaries does with tailored offers and reorder reminders.","distractor_reasons":{"A":"Market research gathers information to inform decisions, whereas this system uses existing customer data to manage ongoing relationships, which makes it a weaker choice than the correct option here.","B":"Segmenting groups customers broadly, but this activity tracks individuals and contacts them personally, so it does not provide what the business actually needs.","C":"Franchising is a way of expanding through independent operators, not a method of managing customer data, and it would not solve the problem described in the scenario.","D":"Customer relationship management uses detailed customer data to build loyalty through personalised contact, which is what Amberwood Apiaries does with tailored offers and reorder reminders."}}},{"id":"P1_U3_MCQ_1473","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1473","question":"Amberlyn Ales began printing its phone number on every bottle after customers complained that caps were hard to open. The number of complaints fell by two thirds within three months. What does this show about responding to customer feedback?","options":{"A":"It guarantees a higher market share","B":"It removes the need for market research","C":"It raises costs with no benefit","D":"It can improve customer satisfaction and encourage repeat purchases"},"correctOption":"D","correctAnswer":"It can improve customer satisfaction and encourage repeat purchases","questionType":"MCQ","explanation":{"correct_reason":"Acting on complaints about hard-to-open caps removed a source of frustration, which improved customer satisfaction and makes repeat purchases more likely for Amberlyn Ales.","distractor_reasons":{"A":"Complaints fell, but market share also depends on rivals, prices and distribution, so one improvement cannot guarantee a higher share.","B":"The phone number generated useful feedback, but the business still needs research to understand preferences and competitors, and it would not solve the problem described in the scenario.","C":"The fall in complaints shows a clear benefit, so claiming the change brought no benefit contradicts the evidence in the stem.","D":"Acting on complaints about hard-to-open caps removed a source of frustration, which improved customer satisfaction and makes repeat purchases more likely for Amberlyn Ales."}}},{"id":"P1_U3_MCQ_1474","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1474","question":"Alderley Aquatics wants to understand why a rival chain attracts so many families. It buys the rival's published annual report and a trade magazine article containing visitor numbers and pricing. What type of research is Alderley Aquatics using?","options":{"A":"Primary research","B":"Qualitative interviews","C":"Secondary research","D":"Observation of shoppers"},"correctOption":"C","correctAnswer":"Secondary research","questionType":"MCQ","explanation":{"correct_reason":"The annual report and magazine article already exist and were produced by others, so using them is secondary research, which gives Alderley Aquatics background evidence without collecting new data.","distractor_reasons":{"A":"Primary research involves collecting new data directly, but these documents were published before Alderley Aquatics began its investigation, and it would not solve the problem described in the scenario.","B":"No interviews are described; the firm is reading published documents rather than questioning people itself, so it is not the best answer among the options given.","C":"The annual report and magazine article already exist and were produced by others, so using them is secondary research, which gives Alderley Aquatics background evidence without collecting new data.","D":"Observation would mean watching shoppers directly, whereas the evidence here comes from existing written sources, and it would be a poor decision for the business in this case."}}},{"id":"P1_U3_MCQ_1475","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1475","question":"Ashcombe Apparel wants to earn $120,000 from sales of a jacket priced at $40. The design and production capacity are already in place, and the owner needs to know how many jackets must be sold to hit the revenue target. How many jackets are required?","options":{"A":"480","B":"2,400","C":"3,000","D":"4,800"},"correctOption":"C","correctAnswer":"3,000","questionType":"MCQ","explanation":{"correct_reason":"The number of jackets needed is the revenue target divided by the price, so $120,000 divided by $40 equals 3,000 jackets for Ashcombe Apparel to reach its target.","distractor_reasons":{"A":"480 would generate only $19,200 at $40 each, far below the $120,000 target, so it cannot be the correct result of this calculation.","B":"2,400 jackets would earn $96,000, which is $24,000 short of the target, so it does not match the figures given in the stem.","C":"The number of jackets needed is the revenue target divided by the price, so $120,000 divided by $40 equals 3,000 jackets for Ashcombe Apparel to reach its target.","D":"4,800 jackets would earn $192,000, well above the $120,000 the owner wants, so it would give the wrong total for the business."}}},{"id":"P1_U3_MCQ_1476","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1476","question":"Brightwater Boats follows a formal process when developing a new model: staff suggest concepts, managers screen them, engineers build a prototype, selected customers test it, and only then is it launched. Which stage comes first?","options":{"A":"Launching the product","B":"Screening the ideas","C":"Building the prototype","D":"Generating new product ideas"},"correctOption":"D","correctAnswer":"Generating new product ideas","questionType":"MCQ","explanation":{"correct_reason":"New product development begins with generating ideas, because there is nothing to screen, prototype or launch until possible concepts have been suggested by staff and others.","distractor_reasons":{"A":"Launch comes at the end of development, after screening, prototypes and customer testing have taken place, which means it does not meet the requirement set out in the stem.","B":"Screening can only happen once ideas exist, so it follows idea generation rather than coming first, and it would not solve the problem described in the scenario.","C":"A prototype is built after an idea has been generated and accepted, so it is a later stage, which means it does not meet the requirement set out in the stem.","D":"New product development begins with generating ideas, because there is nothing to screen, prototype or launch until possible concepts have been suggested by staff and others."}}},{"id":"P1_U3_MCQ_1477","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1477","question":"Bellhouse Books publishes rare local-history titles for collectors in one county. Large publishers ignore this small group because volumes are low, but Bellhouse's customers are loyal and pay high prices. What is the main advantage of this niche approach?","options":{"A":"Lower unit costs than mass-market publishers","B":"Less direct competition and loyal customers willing to pay more","C":"Guaranteed rapid growth","D":"No need to identify target customers"},"correctOption":"B","correctAnswer":"Less direct competition and loyal customers willing to pay more","questionType":"MCQ","explanation":{"correct_reason":"By serving a small segment that large publishers ignore, Bellhouse Books faces less direct competition and can charge higher prices to loyal collectors, which is the main advantage of niche marketing.","distractor_reasons":{"A":"Short print runs usually raise unit costs rather than lower them, so niche publishing is unlikely to beat mass-market publishers on cost.","B":"By serving a small segment that large publishers ignore, Bellhouse Books faces less direct competition and can charge higher prices to loyal collectors, which is the main advantage of niche marketing.","C":"A small niche has limited room to grow, and loyalty does not guarantee rapid expansion, so rapid growth cannot be assumed.","D":"Niche marketing depends on identifying a specific group precisely, so it increases rather than removes the need to know the target customer."}}},{"id":"P1_U3_MCQ_1478","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1478","question":"Birchwood Bindery has written a questionnaire for its business customers but first gives it to 15 friendly clients and asks whether any wording is confusing. It then revises two questions before sending the survey to 2,000 firms. Why did Birchwood Bindery take this step?","options":{"A":"To increase the final sample size","B":"To identify unclear questions and fix them before the full survey","C":"To replace the need for analysis","D":"To guarantee a random sample"},"correctOption":"B","correctAnswer":"To identify unclear questions and fix them before the full survey","questionType":"MCQ","explanation":{"correct_reason":"Testing the draft on a small group is a pilot survey, and it lets Birchwood Bindery spot confusing wording and correct it before spending money on 2,000 questionnaires.","distractor_reasons":{"A":"The 15 testers are not added to the main sample, so the pilot does not increase the size of the final survey.","B":"Testing the draft on a small group is a pilot survey, and it lets Birchwood Bindery spot confusing wording and correct it before spending money on 2,000 questionnaires.","C":"The pilot improves the questionnaire but does not analyse the results, so the full survey still has to be examined.","D":"A pilot tests the wording and does not control how the 2,000 firms are selected, so it cannot guarantee a random sample."}}},{"id":"P1_U3_MCQ_1479","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1479","question":"Blakeney Boats builds wooden boats by hand and charges about 40% more than factories that use moulded hulls. Buyers value the craftsmanship and waiting list, and the boats are marketed as hand-finished. Which pricing strategy is Blakeney Boats using?","options":{"A":"Penetration pricing","B":"Competitive pricing","C":"Cost-plus pricing","D":"Premium pricing"},"correctOption":"D","correctAnswer":"Premium pricing","questionType":"MCQ","explanation":{"correct_reason":"Premium pricing sets a high price to reflect exceptional quality and exclusivity, which fits Blakeney Boats' hand-built craft and its price about 40% above moulded-hull rivals.","distractor_reasons":{"A":"Penetration pricing would set a low price to win volume, the opposite of charging 40% above rivals, which is inconsistent with the values quoted above.","B":"Competitive pricing matches competitors, but Blakeney Boats deliberately prices above them, which makes it a weaker choice than the correct option here.","C":"Cost-plus pricing is based on adding a markup to cost, while the stem explains the price by craftsmanship and buyer perceptions.","D":"Premium pricing sets a high price to reflect exceptional quality and exclusivity, which fits Blakeney Boats' hand-built craft and its price about 40% above moulded-hull rivals."}}},{"id":"P1_U3_MCQ_1480","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1480","question":"Coldharbour Ciders sells a 12-bottle case for $45 in its home market. It is quoting a price to a distributor in a country where $1 buys 0.80 euros. Ignoring transport and taxes, what is the case price in euros?","options":{"A":"€56.25","B":"€40.00","C":"€36.00","D":"€360.00"},"correctOption":"C","correctAnswer":"€36.00","questionType":"MCQ","explanation":{"correct_reason":"At an exchange rate of $1 to €0.80, a $45 case is worth 45 multiplied by 0.80, which equals €36.00 for the overseas distributor.","distractor_reasons":{"A":"€56.25 comes from dividing $45 by 0.80, which applies the exchange rate in the wrong direction, so it would give the wrong total for the business.","B":"€40.00 assumes a rate of about €0.889 per dollar rather than the €0.80 stated, which means the arithmetic has been misapplied here.","C":"At an exchange rate of $1 to €0.80, a $45 case is worth 45 multiplied by 0.80, which equals €36.00 for the overseas distributor.","D":"€360.00 is a decimal place error; $45 multiplied by 0.80 is €36.00, ten times smaller, so it cannot be the correct result of this calculation."}}},{"id":"P1_U3_MCQ_1481","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1481","question":"Cinderpath Coffee earns $1.26 million of its $4.2 million annual revenue from customers who buy beans for home brewing, while the rest comes from cafes and offices. The owner is reviewing how dependent the business is on this one segment. What percentage of revenue comes from home brewers?","options":{"A":"12.6%","B":"42%","C":"3%","D":"30%"},"correctOption":"D","correctAnswer":"30%","questionType":"MCQ","explanation":{"correct_reason":"The home-brewing segment contributes $1.26 million out of $4.2 million, and $1.26 million divided by $4.2 million multiplied by 100 equals 30% of Cinderpath Coffee's revenue.","distractor_reasons":{"A":"12.6% repeats the digits of the $1.26 million figure rather than calculating its proportion of $4.2 million, which means the arithmetic has been misapplied here.","B":"42% comes from reading the $4.2 million total as a percentage, which confuses the total revenue with the segment's share.","C":"3% does not follow from the figures; $1.26 million is close to one third of $4.2 million, which is about 30%, not 3%.","D":"The home-brewing segment contributes $1.26 million out of $4.2 million, and $1.26 million divided by $4.2 million multiplied by 100 equals 30% of Cinderpath Coffee's revenue."}}},{"id":"P1_U3_MCQ_1482","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1482","question":"Cloverdale Candles employs 12 interviewers, and each can complete 15 interviews in a day. The research agency has been commissioned to collect 1,800 interviews for a customer survey. How many days will the team need to finish the fieldwork?","options":{"A":"12 days","B":"15 days","C":"8 days","D":"10 days"},"correctOption":"D","correctAnswer":"10 days","questionType":"MCQ","explanation":{"correct_reason":"Each day the team completes 12 interviewers multiplied by 15 interviews, which is 180 interviews, so 1,800 interviews divided by 180 per day gives 10 days of fieldwork.","distractor_reasons":{"A":"12 days confuses the number of interviewers with the number of days and does not use the 1,800 target, and it therefore does not follow from the stated values.","B":"15 days repeats the daily interviews per interviewer and ignores the team of 12 and the 1,800 target, so it cannot be the correct result of this calculation.","C":"8 days would produce only 1,440 interviews, which is short of the 1,800 the agency has been asked to collect.","D":"Each day the team completes 12 interviewers multiplied by 15 interviews, which is 180 interviews, so 1,800 interviews divided by 180 per day gives 10 days of fieldwork."}}},{"id":"P1_U3_MCQ_1483","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1483","question":"Cottlestone Cheeses spends $54,000 on advertising and in-store tastings out of a total marketing budget of $360,000. The owner is reviewing whether promotion takes too large a share of the budget. What percentage of the marketing budget goes on promotion?","options":{"A":"5.4%","B":"12%","C":"54%","D":"15%"},"correctOption":"D","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Promotion's share is $54,000 divided by $360,000 multiplied by 100, which equals 15% of Cottlestone Cheeses' total marketing budget. This is exactly the outcome the figures and the scenario point to.","distractor_reasons":{"A":"5.4% repeats the digits of $54,000 without relating them to the $360,000 budget, so it cannot be the correct result of this calculation.","B":"12% would equal $43,200 of the budget, which is less than the $54,000 actually spent, and the numbers in the stem do not support this figure.","C":"54% would mean $194,400 of the $360,000 budget, far more than the promotion spend stated, and the numbers in the stem do not support this figure.","D":"Promotion's share is $54,000 divided by $360,000 multiplied by 100, which equals 15% of Cottlestone Cheeses' total marketing budget. This is exactly the outcome the figures and the scenario point to."}}},{"id":"P1_U3_MCQ_1484","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1484","question":"Deepdale Drones has sold its original survey drone at home for four years and sales have levelled off. It now plans to launch the same model in two countries where few firms use survey drones. Why is this an appropriate marketing strategy?","options":{"A":"Finding new customers abroad can extend the product's life and spread risk","B":"It automatically improves the drone's technology","C":"It reduces the firm's fixed costs immediately","D":"It avoids all competition in the new countries"},"correctOption":"A","correctAnswer":"Finding new customers abroad can extend the product's life and spread risk","questionType":"MCQ","explanation":{"correct_reason":"Selling a mature product in markets where it is still new brings in extra sales and reduces dependence on the home market, which extends the product's life for Deepdale Drones.","distractor_reasons":{"A":"Selling a mature product in markets where it is still new brings in extra sales and reduces dependence on the home market, which extends the product's life for Deepdale Drones.","B":"Launching the existing model abroad does not change its design, so the technology stays the same, which does not help the business achieve the outcome it wants.","C":"Entering new countries usually adds costs such as marketing and distribution, so fixed costs may rise rather than fall, which makes it a weaker choice than the correct option here.","D":"Local firms may already offer survey drones, so entering a new country does not guarantee freedom from competition, and it would not solve the problem described in the scenario."}}},{"id":"P1_U3_MCQ_1485","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1485","question":"Driftwood Furnishings has built its reputation on affordable flat-pack desks for students. It now plans to relaunch as a premium brand with solid oak furniture at three times the price. What is the main marketing risk of this repositioning?","options":{"A":"Existing budget customers may leave while premium buyers may not accept the new image","B":"Costs will certainly fall","C":"Competitors are forced to leave the market","D":"The brand image will change instantly at no cost"},"correctOption":"A","correctAnswer":"Existing budget customers may leave while premium buyers may not accept the new image","questionType":"MCQ","explanation":{"correct_reason":"Repositioning abandons the price-sensitive students who made the brand successful, and premium buyers may doubt that a budget flat-pack name can deliver genuine luxury, so Driftwood Furnishings risks losing both groups.","distractor_reasons":{"A":"Repositioning abandons the price-sensitive students who made the brand successful, and premium buyers may doubt that a budget flat-pack name can deliver genuine luxury, so Driftwood Furnishings risks losing both groups.","B":"Solid oak furniture at three times the price normally raises material and production costs rather than making them fall, so it is less suitable than the alternative described.","C":"A repositioning by one firm does not force rivals out of the market; competitors may instead exploit the gap left in budget furniture.","D":"Brand image lives in customers' minds and changes slowly, so a relaunch is costly and cannot transform perceptions instantly, which means it does not meet the requirement set out in the stem."}}},{"id":"P1_U3_MCQ_1486","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1486","question":"Dovetail Desks wants to survey its trade customers but first needs a complete list of them from which to select people. The sales team supplies an up-to-date list of every account with an email address. What is this list called?","options":{"A":"A sampling frame","B":"A questionnaire","C":"A sample size","D":"A research budget"},"correctOption":"A","correctAnswer":"A sampling frame","questionType":"MCQ","explanation":{"correct_reason":"A sampling frame is the complete list of the population from which a sample is drawn, so the sales team's list of every trade account is the sampling frame for Dovetail Desks.","distractor_reasons":{"A":"A sampling frame is the complete list of the population from which a sample is drawn, so the sales team's list of every trade account is the sampling frame for Dovetail Desks.","B":"A questionnaire is the set of questions put to respondents, not the list of customers from which they are chosen.","C":"Sample size is the number of people selected, such as 200 accounts, rather than the full list itself, so it does not match the figures given in the stem.","D":"The research budget is the money available for the project, not the record of customers used for selection, so it does not provide what the business actually needs."}}},{"id":"P1_U3_MCQ_1487","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1487","question":"Dunmoor Doors sells most of its standard interior doors to homeowners who want to collect a door the same day. Instead of opening city-centre showrooms, it stocks local DIY stores within a short drive of housing estates. Why is this place decision appropriate?","options":{"A":"Target customers value convenient local purchase for bulky everyday items","B":"City-centre rents are always lower","C":"The doors are luxury products bought rarely","D":"Online selling is banned for doors"},"correctOption":"A","correctAnswer":"Target customers value convenient local purchase for bulky everyday items","questionType":"MCQ","explanation":{"correct_reason":"Homeowners replacing a door need it quickly and must transport it, so stocking local DIY stores within a short drive makes buying convenient for Dunmoor Doors' target customers.","distractor_reasons":{"A":"Homeowners replacing a door need it quickly and must transport it, so stocking local DIY stores within a short drive makes buying convenient for Dunmoor Doors' target customers.","B":"City-centre rents are usually higher, and the stem explains the choice by customer convenience rather than rent, so it is not the best answer among the options given.","C":"The stem describes standard interior doors bought for same-day collection, which are everyday rather than luxury products, and it would be a poor decision for the business in this case.","D":"Nothing in the stem says online selling is banned; the issue is that bulky doors are convenient to buy locally."}}},{"id":"P1_U3_MCQ_1488","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1488","question":"Eastgate Eyewear uses exactly the same frames, lenses and packaging in every country to keep production simple and benefit from large-scale output. Managers are now reviewing the risks of this standardised approach. What is the main risk?","options":{"A":"Production costs will be higher","B":"The brand will look different in each market","C":"Launching products will take longer","D":"The offer may not suit local needs, tastes or regulations"},"correctOption":"D","correctAnswer":"The offer may not suit local needs, tastes or regulations","questionType":"MCQ","explanation":{"correct_reason":"Standardisation gains scale but assumes buyers everywhere want the same product, so Eastgate Eyewear may find that frame styles, fit or labelling rules in some countries do not match its standard offer.","distractor_reasons":{"A":"One standard design usually lowers unit costs through economies of scale rather than raising them, which makes it a weaker choice than the correct option here.","B":"Standardisation keeps the brand consistent, so looking different in each market is not the risk, and it would be a poor decision for the business in this case.","C":"Using one version avoids market-by-market redesign, which normally speeds up launch rather than delaying it, so it is less suitable than the alternative described.","D":"Standardisation gains scale but assumes buyers everywhere want the same product, so Eastgate Eyewear may find that frame styles, fit or labelling rules in some countries do not match its standard offer."}}},{"id":"P1_U3_MCQ_1489","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1489","question":"Elderberry Events operates in a corporate events market that was worth $180 million last year but is now worth $162 million as firms cut spending. The directors are assessing whether demand is shrinking before investing in new venues. By what percentage did the market change?","options":{"A":"18%","B":"11.1%","C":"10% fall","D":"90% fall"},"correctOption":"C","correctAnswer":"10% fall","questionType":"MCQ","explanation":{"correct_reason":"The market fell by $18 million, and $18 million divided by the original $180 million equals 10%, so Elderberry Events faces a 10% fall in the value of its market.","distractor_reasons":{"A":"18% is the absolute fall expressed in millions of dollars, not the percentage change from the original $180 million market.","B":"11.1% comes from dividing the $18 million fall by the new $162 million value instead of by the original $180 million.","C":"The market fell by $18 million, and $18 million divided by the original $180 million equals 10%, so Elderberry Events faces a 10% fall in the value of its market.","D":"90% fall would mean the market almost disappeared, but $162 million of the original $180 million is still being spent."}}},{"id":"P1_U3_MCQ_1490","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1490","question":"Ember Row Eateries sends researchers to talk to diners at their tables, allowing them to explain what they mean and ask follow-up questions about the menu. The owner expects richer answers than a written survey would give. What is the main advantage of this interview method?","options":{"A":"The interviewer can clarify questions and probe answers in depth","B":"It is always cheaper than an online survey","C":"It removes all interviewer bias","D":"It guarantees the sample is representative"},"correctOption":"A","correctAnswer":"The interviewer can clarify questions and probe answers in depth","questionType":"MCQ","explanation":{"correct_reason":"Face-to-face interviews let the researcher explain unclear questions and follow up on interesting answers, so Ember Lane Eateries gains deeper insight into what diners really think.","distractor_reasons":{"A":"Face-to-face interviews let the researcher explain unclear questions and follow up on interesting answers, so Ember Lane Eateries gains deeper insight into what diners really think.","B":"Paying researchers to visit tables is labour-intensive and usually costs more than sending an online survey, so it is not the best answer among the options given.","C":"Interviewers can influence responses through tone or body language, so the method does not remove interviewer bias, and it would not solve the problem described in the scenario.","D":"Representativeness depends on how diners are selected, and simply interviewing them face to face does not guarantee it, so it does not provide what the business actually needs."}}},{"id":"P1_U3_MCQ_1491","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1491","question":"Elmsworth Engines sells industrial engines to factories, where each order can be worth $250,000 and buyers need detailed technical advice before choosing. The sales director is choosing the main promotional method for this market. Which is most suitable?","options":{"A":"Cartoon television adverts aimed at children","B":"Celebrity posts on social media for teenagers","C":"Trade exhibitions and direct sales visits to buyers","D":"Free samples handed out in shopping centres"},"correctOption":"C","correctAnswer":"Trade exhibitions and direct sales visits to buyers","questionType":"MCQ","explanation":{"correct_reason":"Industrial buyers need technical information and a relationship with the seller, so trade exhibitions and direct sales visits allow Elmsworth Engines to explain complex engines and negotiate large orders.","distractor_reasons":{"A":"Children do not buy industrial engines, so a cartoon television advert would reach none of the relevant decision makers, which makes it a weaker choice than the correct option here.","B":"Teenagers on social media are not the factory managers who place $250,000 engine orders, which is not the outcome produced by the figures provided.","C":"Industrial buyers need technical information and a relationship with the seller, so trade exhibitions and direct sales visits allow Elmsworth Engines to explain complex engines and negotiate large orders.","D":"Shopping-centre samples do not suit heavy industrial engines or the detailed advice that factory buyers require, so it is less suitable than the alternative described."}}},{"id":"P1_U3_MCQ_1492","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1492","question":"Fenwick Fountains has an international marketing budget of $240,000. It plans to allocate 40% of this to its largest overseas market and divide the rest between two smaller markets. How much will the largest market receive?","options":{"A":"$60,000","B":"$24,000","C":"$144,000","D":"$96,000"},"correctOption":"D","correctAnswer":"$96,000","questionType":"MCQ","explanation":{"correct_reason":"The largest market receives 40% of the $240,000 budget, and 0.40 multiplied by $240,000 equals $96,000, leaving $144,000 for the two smaller markets.","distractor_reasons":{"A":"$60,000 is 25% of the budget, not the 40% share planned for the largest market, which is not the outcome produced by the figures provided.","B":"$24,000 is 10% of the budget, far below the stated 40% allocation, and the numbers in the stem do not support this figure.","C":"$144,000 is the 60% left for the two smaller markets, not the amount going to the largest one, so it would give the wrong total for the business.","D":"The largest market receives 40% of the $240,000 budget, and 0.40 multiplied by $240,000 equals $96,000, leaving $144,000 for the two smaller markets."}}},{"id":"P1_U3_MCQ_1493","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1493","question":"Flintlock Fireplaces calculates that winning a new customer costs about $180 in advertising and discounts, while keeping an existing customer costs about $30 in servicing and reminders. The owner is deciding where to focus the marketing budget. What does this comparison suggest?","options":{"A":"Retaining customers can be cheaper than winning new ones","B":"All customers are equally profitable","C":"Acquiring new customers is always cheaper","D":"Loyalty has no effect on revenue"},"correctOption":"A","correctAnswer":"Retaining customers can be cheaper than winning new ones","questionType":"MCQ","explanation":{"correct_reason":"Spending $30 to keep a customer is much cheaper than spending $180 to win a new one, so Flintlock Fireplaces can get more value from its budget by focusing on retention.","distractor_reasons":{"A":"Spending $30 to keep a customer is much cheaper than spending $180 to win a new one, so Flintlock Fireplaces can get more value from its budget by focusing on retention.","B":"The two figures show very different costs for existing and new customers, so treating all customers as equally profitable ignores that difference.","C":"The stem shows acquisition costs $180 against $30 for retention, so acquisition is six times more expensive, not cheaper, which is inconsistent with the values quoted above.","D":"Retained customers continue buying and therefore generate revenue, so loyalty clearly affects the firm's income, which makes it a weaker choice than the correct option here."}}},{"id":"P1_U3_MCQ_1494","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1494","question":"Foxglove Florists posted 500 questionnaires to past customers and received only 40 back. The owner is tempted to treat the replies as typical of all customers. Why should the owner be cautious?","options":{"A":"The response rate is so high that the data is unusable","B":"Such a low response may make the findings unrepresentative of all customers","C":"Postal surveys are always the cheapest method","D":"A low response rate proves there is no bias"},"correctOption":"B","correctAnswer":"Such a low response may make the findings unrepresentative of all customers","questionType":"MCQ","explanation":{"correct_reason":"Only 40 of 500 customers replied, so the views of the 460 who did not reply are missing and may differ, which makes the findings a weak guide to Foxglove Florists' whole customer base.","distractor_reasons":{"A":"The response rate is low at 8%, not high, and the problem is the small number of replies rather than an excess of data.","B":"Only 40 of 500 customers replied, so the views of the 460 who did not reply are missing and may differ, which makes the findings a weak guide to Foxglove Florists' whole customer base.","C":"Whether postal surveys are cheapest is not the issue; the concern is whether 40 replies can represent all past customers.","D":"A low response rate raises the risk of bias because non-respondents may have different views, so it does not prove the absence of bias."}}},{"id":"P1_U3_MCQ_1495","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1495","question":"Fairweather Frames lets customers take a framed print home for 30 days and return it for a full refund if they do not like it. The owner hopes this will persuade hesitant buyers to try the product. What is the main purpose of this offer?","options":{"A":"To raise the selling price","B":"To replace the need for product quality","C":"To encourage trial and reduce the risk perceived by customers","D":"To reduce the number of distribution outlets"},"correctOption":"C","correctAnswer":"To encourage trial and reduce the risk perceived by customers","questionType":"MCQ","explanation":{"correct_reason":"A free trial period lowers the risk of trying something new, so hesitant customers are more willing to take a Fairweather Frames print home and may decide to keep it.","distractor_reasons":{"A":"The offer is a refund guarantee rather than a reason to charge a higher price, and no price rise is mentioned.","B":"Customers can still return the print, so the quality of the product must be good enough to make them keep it.","C":"A free trial period lowers the risk of trying something new, so hesitant customers are more willing to take a Fairweather Frames print home and may decide to keep it.","D":"The trial affects customer confidence at the point of sale and does nothing to change how many outlets stock the frames."}}},{"id":"P1_U3_MCQ_1496","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1496","question":"Galloway Greetings publishes cards celebrating Scottish holidays and sells mainly to expatriate Scots in Canada and Australia. Large card companies overlook this group because sales volumes are modest. Why is this niche international strategy suitable?","options":{"A":"It serves a small group with specific needs and faces little direct competition","B":"It targets the largest possible worldwide market","C":"It guarantees the lowest production costs","D":"It avoids the need for any market research"},"correctOption":"A","correctAnswer":"It serves a small group with specific needs and faces little direct competition","questionType":"MCQ","explanation":{"correct_reason":"Serving expatriate Scots with culturally specific cards gives Galloway Greetings a clearly defined group with particular needs that large publishers ignore, so competition is limited.","distractor_reasons":{"A":"Serving expatriate Scots with culturally specific cards gives Galloway Greetings a clearly defined group with particular needs that large publishers ignore, so competition is limited.","B":"The strategy deliberately targets a small group rather than the whole worldwide card market, so it does not provide what the business actually needs.","C":"Small print runs usually raise unit costs, so the niche approach does not guarantee low production costs, which means it does not meet the requirement set out in the stem.","D":"Understanding what expatriate Scots want still requires research, so the niche approach does not remove it, and it would be a poor decision for the business in this case."}}},{"id":"P1_U3_MCQ_1497","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1497","question":"Gable & Grain sells everyday sliced loaves that households buy every week and also makes celebration cakes ordered for birthdays and weddings. The owner is explaining the difference between needs and wants to a new marketing assistant. Which statement is correct?","options":{"A":"Wants are essential items and needs are luxuries","B":"Needs apply only to business customers","C":"Needs are essentials, while wants are desirable extras that marketing can stimulate","D":"There is no meaningful difference between needs and wants"},"correctOption":"C","correctAnswer":"Needs are essentials, while wants are desirable extras that marketing can stimulate","questionType":"MCQ","explanation":{"correct_reason":"Needs are the basic essentials people must have, such as bread, while wants are desirable extras such as celebration cakes, and marketing can stimulate demand for those extras.","distractor_reasons":{"A":"This reverses the terms: bread is an essential need, whereas a celebration cake is a desirable want rather than a necessity.","B":"Households as well as businesses have needs, and the stem describes ordinary shoppers buying bread and cakes, which makes it a weaker choice than the correct option here.","C":"Needs are the basic essentials people must have, such as bread, while wants are desirable extras such as celebration cakes, and marketing can stimulate demand for those extras.","D":"The distinction matters for marketing because essentials are bought routinely while wants can be influenced by promotion and image, which means it does not meet the requirement set out in the stem."}}},{"id":"P1_U3_MCQ_1498","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1498","question":"Gorsehill Garages asked five customers to rate its service from 1 to 5. The ratings were 4, 3, 5, 2 and 1. The manager wants a single figure that summarises typical satisfaction before deciding whether to change the booking system. What is the mean rating?","options":{"A":"2.5","B":"3.0","C":"3.75","D":"15"},"correctOption":"B","correctAnswer":"3.0","questionType":"MCQ","explanation":{"correct_reason":"The mean is the total of the ratings divided by the number of ratings, so 4 plus 3 plus 5 plus 2 plus 1 equals 15, and 15 divided by 5 customers gives a mean of 3.0.","distractor_reasons":{"A":"2.5 is the middle value when the ratings are placed in order, which is the median rather than the mean the manager asked for.","B":"The mean is the total of the ratings divided by the number of ratings, so 4 plus 3 plus 5 plus 2 plus 1 equals 15, and 15 divided by 5 customers gives a mean of 3.0.","C":"3.75 would require a total of 18.75 across five ratings, but the five ratings add up to only 15, which is not the outcome produced by the figures provided.","D":"15 is the total of all five ratings, not the mean, because it has not been divided by the number of customers."}}},{"id":"P1_U3_MCQ_1499","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1499","question":"Glasson Gloves sells 4,000 pairs of work gloves a month at $12 a pair to industrial suppliers. The owner is preparing a bank report and needs the total monthly revenue from these gloves. What is the total monthly revenue?","options":{"A":"$4,800","B":"$48,000","C":"$52,000","D":"$480,000"},"correctOption":"B","correctAnswer":"$48,000","questionType":"MCQ","explanation":{"correct_reason":"Total revenue equals price multiplied by quantity, so 4,000 pairs at $12 each gives 4,000 multiplied by $12, which equals $48,000 a month.","distractor_reasons":{"A":"$4,800 is a decimal place error; 4,000 multiplied by $12 is $48,000, ten times larger, so it cannot be the correct result of this calculation.","B":"Total revenue equals price multiplied by quantity, so 4,000 pairs at $12 each gives 4,000 multiplied by $12, which equals $48,000 a month.","C":"$52,000 adds $4,000 to the correct figure, which would mean selling 4,333 pairs rather than 4,000, so it does not match the figures given in the stem.","D":"$480,000 is ten times the correct revenue and would require 40,000 pairs at $12 each, so it would give the wrong total for the business."}}},{"id":"P1_U3_MCQ_1500","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1500","question":"Wexcombe Wagons has divided its buyers into groups such as rural families, urban delivery firms and event organisers. It now decides to sell only to rural families and to design its whole offer around them. What is this decision called?","options":{"A":"Market targeting","B":"Market research","C":"Product development","D":"Franchising"},"correctOption":"A","correctAnswer":"Market targeting","questionType":"MCQ","explanation":{"correct_reason":"Market targeting is the choice of which segment or segments to serve, so deciding to focus only on rural families is a targeting decision by Wexcombe Wagons.","distractor_reasons":{"A":"Market targeting is the choice of which segment or segments to serve, so deciding to focus only on rural families is a targeting decision by Wexcombe Wagons.","B":"Market research is the collection of information about customers, which informs but is not the same as choosing a segment.","C":"Product development is the process of creating or improving a product, not selecting which customer group to serve, so it is less suitable than the alternative described.","D":"Franchising is a method of expanding through independent operators and has nothing to do with segment choice, which does not help the business achieve the outcome it wants."}}},{"id":"P1_U3_MCQ_1501","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1501","question":"Zephquil Ceramics Ltd in Lisbon, Portugal sold 9,000 glazed tiles in 2026. Total tile sales in its national market were 120,000 units that year. What was Zephquil Ceramics' market share?","options":{"A":"0.75%","B":"7.5%","C":"13.3%","D":"75%"},"correctOption":"B","correctAnswer":"7.5%","questionType":"MCQ","explanation":{"correct_reason":"Market share equals the firm's unit sales divided by total market sales, then multiplied by 100. Zephquil sold 9,000 of 120,000 tiles, so 9,000 divided by 120,000 times 100 gives exactly 7.5%.","distractor_reasons":{"A":"0.75% moves the decimal one place too far. Dividing 9,000 by 120,000 gives 0.075, and converting that fraction into a percentage requires multiplying by 100 to reach 7.5%.","B":"Market share equals the firm's unit sales divided by total market sales, then multiplied by 100. Zephquil sold 9,000 of 120,000 tiles, so 9,000 divided by 120,000 times 100 gives exactly 7.5%.","C":"13.3% would come from inverting the ratio and dividing 120,000 by 9,000. Market share is the firm's sales over the whole market, not the total market over the firm's sales.","D":"75% wrongly treats 9,000 as three quarters of 120,000. In reality 9,000 is a small fraction of the 120,000 glazed tiles sold across the national market."}}},{"id":"P1_U3_MCQ_1502","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1502","question":"Marrowgate Foods Ltd in Nairobi, Kenya noticed sales of its spiced snack falling. Managers need detailed explanations of why regular customers switched to rival brands. Which research method is most suitable for exploring these individual reasons?","options":{"A":"A postal questionnaire with closed questions sent to 5,000 households.","B":"An in-depth interview with a small number of former customers.","C":"A nationwide telephone survey of 2,000 randomly selected people.","D":"Reading government statistics on household snack consumption."},"correctOption":"B","correctAnswer":"An in-depth interview with a small number of former customers.","questionType":"MCQ","explanation":{"correct_reason":"In-depth interviews with former customers let researchers probe individual motives and follow up answers, which is ideal for discovering exactly why people switched from Marrowgate Foods' spiced snack to competing products.","distractor_reasons":{"A":"A postal questionnaire with closed questions cannot explore individual reasoning in depth; it measures how many people hold a view rather than explaining why Marrowgate Foods lost particular customers.","B":"In-depth interviews with former customers let researchers probe individual motives and follow up answers, which is ideal for discovering exactly why people switched from Marrowgate Foods' spiced snack to competing products.","C":"A large telephone survey can measure the scale of a problem but offers little detail on personal motivations, so it would not reveal why specific buyers abandoned the spiced snack.","D":"Government consumption statistics show broad trends only and cannot reveal why particular customers rejected Marrowgate Foods' snack in favour of rival brands in Nairobi."}}},{"id":"P1_U3_MCQ_1503","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1503","question":"Orchvale Lighting Ltd in Krakow, Poland manufactures a wall sconce for a unit cost of $18. The firm applies a cost-plus mark-up of 40% to cover overheads and profit. What selling price should it charge for each sconce?","options":{"A":"$7.20","B":"$40.00","C":"$25.20","D":"$18.40"},"correctOption":"C","correctAnswer":"$25.20","questionType":"MCQ","explanation":{"correct_reason":"A 40% mark-up on the $18 unit cost adds $7.20. Adding this amount to the original $18 cost gives a selling price of $25.20 for each wall sconce made by Orchvale Lighting.","distractor_reasons":{"A":"$7.20 is only the value of the mark-up itself. The selling price must also recover the $18 unit cost, so it cannot consist of the addition alone.","B":"$40.00 would require adding $22 to the $18 cost, which represents a mark-up far larger than the 40% stated in the question.","C":"A 40% mark-up on the $18 unit cost adds $7.20. Adding this amount to the original $18 cost gives a selling price of $25.20 for each wall sconce made by Orchvale Lighting.","D":"$18.40 adds only $0.40 to the $18 cost, as though the mark-up were roughly 2% rather than the 40% specified by Orchvale Lighting."}}},{"id":"P1_U3_MCQ_1504","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1504","question":"Brindlebay Tours Ltd in Cape Town, South Africa divides holidaymakers by age, income and interests, then designs guided wine tours for retired professionals with high disposable income. What marketing approach is this company using?","options":{"A":"Mass marketing, because one tour is offered to every holidaymaker.","B":"Market segmentation followed by targeting one attractive group of customers.","C":"Cost-plus pricing, because the tour price is set from the cost of the wine.","D":"Primary research, because the firm collects new data from tourists."},"correctOption":"B","correctAnswer":"Market segmentation followed by targeting one attractive group of customers.","questionType":"MCQ","explanation":{"correct_reason":"Brindlebay Tours first splits the holiday market by age, income and interests and then concentrates its wine tours on retired professionals, which is segmentation followed by targeting a chosen customer segment.","distractor_reasons":{"A":"Mass marketing would ignore differences between holidaymakers and appeal to everyone with one offer, the opposite of focusing narrowly on retired professionals with high incomes.","B":"Brindlebay Tours first splits the holiday market by age, income and interests and then concentrates its wine tours on retired professionals, which is segmentation followed by targeting a chosen customer segment.","C":"Cost-plus pricing is a way of setting a selling price from costs. It does not describe dividing customers into groups and deciding which group to serve with wine tours.","D":"Primary research means gathering new data from respondents. The scenario describes grouping and selecting customers, not the collection of survey evidence from tourists."}}},{"id":"P1_U3_MCQ_1505","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1505","question":"Kalumbra Dairy Ltd in Lusaka, Zambia estimates its local yoghurt market grew from $8 million in 2025 to $9.2 million in 2026. What was the market's percentage growth over that year?","options":{"A":"12%","B":"15%","C":"1.2%","D":"115%"},"correctOption":"B","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Growth equals the change divided by the original value. The yoghurt market rose by $1.2 million from $8 million, so 1.2 divided by 8 times 100 gives 15% annual growth for Kalumbra Dairy.","distractor_reasons":{"A":"12% is found by dividing the $1.2 million increase by the new $9.2 million total, but percentage growth must use the original $8 million as its base figure.","B":"Growth equals the change divided by the original value. The yoghurt market rose by $1.2 million from $8 million, so 1.2 divided by 8 times 100 gives 15% annual growth for Kalumbra Dairy.","C":"1.2% confuses the $1.2 million rise with a percentage. The increase must be divided by the original $8 million and then multiplied by 100.","D":"115% is the new market size expressed as a percentage of the old one. The actual growth is the extra 15% above the original $8 million level."}}},{"id":"P1_U3_MCQ_1506","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1506","question":"Vantara Cosmetics Ltd in Singapore wants its survey of 2,000 shoppers to reflect the true proportions of each age group in the local population. Which sampling method should the company use?","options":{"A":"Quota sampling, setting each age group's share in the sample to match its share of the population.","B":"Selecting only the first 2,000 shoppers who volunteer, until the target is reached.","C":"Questioning only Vantara's existing loyalty-card holders about their habits.","D":"Letting researchers choose respondents wherever the store is busiest."},"correctOption":"A","correctAnswer":"Quota sampling, setting each age group's share in the sample to match its share of the population.","questionType":"MCQ","explanation":{"correct_reason":"Quota sampling sets the proportion of each age group in the sample to mirror its proportion in the population, so Vantara Cosmetics' 2,000 shoppers would represent the local age mix accurately.","distractor_reasons":{"A":"Quota sampling sets the proportion of each age group in the sample to mirror its proportion in the population, so Vantara Cosmetics' 2,000 shoppers would represent the local age mix accurately.","B":"Taking the first 2,000 volunteers produces a self-selected group unlikely to match the population's age mix, biasing the survey toward eager and available shoppers.","C":"Loyalty-card holders are already loyal customers, so their age profile would not represent all shoppers and the survey would miss potential new buyers.","D":"Allowing researchers to pick whoever they like in a busy aisle introduces personal bias and does not guarantee that each age group appears in its true proportion."}}},{"id":"P1_U3_MCQ_1507","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1507","question":"Selwick Sports Ltd in Melbourne, Australia launches a new running shoe and uses social media influencers to build quick awareness among young runners at a modest cost. Which element of the marketing mix does this activity mainly illustrate?","options":{"A":"Price","B":"Product","C":"Promotion","D":"Place"},"correctOption":"C","correctAnswer":"Promotion","questionType":"MCQ","explanation":{"correct_reason":"Using influencers to communicate the shoe's benefits and create awareness is promotion, one of the four marketing mix elements, aimed at informing and persuading Selwick Sports' target runners.","distractor_reasons":{"A":"Price concerns how much customers pay and which pricing method is used. Influencer activity does not set or communicate the selling price of Selwick Sports' shoe.","B":"Product covers the shoe's design, quality and branding. The scenario focuses on communicating with runners rather than altering the physical shoe itself.","C":"Using influencers to communicate the shoe's benefits and create awareness is promotion, one of the four marketing mix elements, aimed at informing and persuading Selwick Sports' target runners.","D":"Place is about distribution channels and where the shoe is sold. Social media influencers raise awareness rather than delivering the product to customers."}}},{"id":"P1_U3_MCQ_1508","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1508","question":"Thornefield Hardware Ltd in Manchester, United Kingdom offers a lifetime guarantee on every hand tool, while rival firms offer only one year. What does this guarantee give Thornefield in a competitive market?","options":{"A":"A lower unit cost than all of its competitors.","B":"A unique selling point that differentiates its tools from rivals.","C":"A legal requirement placed on all tool manufacturers.","D":"A reduction in the price it pays its component suppliers."},"correctOption":"B","correctAnswer":"A unique selling point that differentiates its tools from rivals.","questionType":"MCQ","explanation":{"correct_reason":"A lifetime guarantee that competitors do not match is a unique selling point. It differentiates Thornefield Hardware's tools and gives customers a clear reason to choose them over rival products.","distractor_reasons":{"A":"A guarantee does not by itself lower production costs; it may even raise them because more tools will have to be replaced under the lifetime warranty.","B":"A lifetime guarantee that competitors do not match is a unique selling point. It differentiates Thornefield Hardware's tools and gives customers a clear reason to choose them over rival products.","C":"A lifetime guarantee is a voluntary competitive offer, not a legal requirement imposed on every tool manufacturer operating in the market.","D":"The guarantee is given to buyers after purchase and does not change the price Thornefield Hardware pays its suppliers for components."}}},{"id":"P1_U3_MCQ_1509","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1509","question":"Draymoor Tickets Ltd in Toronto, Canada sells 24,000 concert tickets and knows this equals 8% of the total city market. What is the size of the entire concert ticket market in Toronto?","options":{"A":"300,000 tickets","B":"192,000 tickets","C":"3,000 tickets","D":"30,000 tickets"},"correctOption":"A","correctAnswer":"300,000 tickets","questionType":"MCQ","explanation":{"correct_reason":"If 24,000 tickets equal 8% of the market, total market size is 24,000 divided by 0.08, which equals 300,000 tickets across the whole city of Toronto.","distractor_reasons":{"A":"If 24,000 tickets equal 8% of the market, total market size is 24,000 divided by 0.08, which equals 300,000 tickets across the whole city of Toronto.","B":"192,000 comes from multiplying 24,000 by eight, which would treat Draymoor's sales as eight times the market rather than one eighth of it.","C":"3,000 comes from dividing 24,000 by 8 but forgetting to multiply by 100, which converts the 8% share into the decimal 0.08 needed here.","D":"30,000 would imply Draymoor sells 80% of the market, not 8%, because 24,000 out of 30,000 is four fifths of all the tickets."}}},{"id":"P1_U3_MCQ_1510","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1510","question":"Elmgate Pharmacy Ltd in Dublin, Ireland uses published government health statistics to estimate local demand for vitamin supplements before launching a new range. What type of data is the pharmacy using?","options":{"A":"Primary data collected directly from customers.","B":"Secondary data that already exists in published form.","C":"Qualitative data gathered through small focus groups.","D":"Experimental data from a controlled test market."},"correctOption":"B","correctAnswer":"Secondary data that already exists in published form.","questionType":"MCQ","explanation":{"correct_reason":"Published government statistics were collected by someone else for another purpose, so they are secondary data that Elmgate Pharmacy can obtain quickly and cheaply in Dublin.","distractor_reasons":{"A":"Primary data are gathered first-hand from respondents. Government statistics were not collected by Elmgate Pharmacy itself for this particular decision. The details given about Elmgate Pharmacy Ltd support Secondary data that already exists in published form, so this answer is unsuitable.","B":"Published government statistics were collected by someone else for another purpose, so they are secondary data that Elmgate Pharmacy can obtain quickly and cheaply in Dublin.","C":"Qualitative data are opinions and feelings from small groups. Health statistics are numerical and already published, so they are not qualitative focus-group findings.","D":"Experimental data would come from a controlled test market run by the firm. Using existing government reports involves no experiment carried out by Elmgate Pharmacy."}}},{"id":"P1_U3_MCQ_1511","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1511","question":"Fennwick Bakeries Ltd in Accra, Ghana sells its bread through independent grocers and its own delivery vans rather than through one supermarket chain. Which part of the marketing mix does this distribution arrangement illustrate?","options":{"A":"Product","B":"Price","C":"Promotion","D":"Place"},"correctOption":"D","correctAnswer":"Place","questionType":"MCQ","explanation":{"correct_reason":"Place concerns how a product reaches the customer. Using grocers and delivery vans is a distribution decision that makes Fennwick Bakeries' bread available to buyers throughout Accra.","distractor_reasons":{"A":"Product relates to the bread's recipe, quality and packaging. Choosing grocers and vans does not change the physical loaf or the brand that Fennwick Bakeries sells.","B":"Price is what customers pay. The scenario says nothing about the loaf's selling price or any discount, only about how the bread is distributed to shops.","C":"Promotion communicates with customers through advertising or special offers. The grocers and vans are routes to market, not promotional messages about the bread.","D":"Place concerns how a product reaches the customer. Using grocers and delivery vans is a distribution decision that makes Fennwick Bakeries' bread available to buyers throughout Accra."}}},{"id":"P1_U3_MCQ_1512","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1512","question":"Glenherva Textiles Ltd in Chiang Mai, Thailand makes hand-woven scarves and sells them only to a small number of boutique hotels, rather than to the general public. Which market strategy is the firm pursuing?","options":{"A":"Mass marketing, aiming at the whole population.","B":"Niche marketing, concentrating on a narrow, specialised group of buyers.","C":"Undifferentiated marketing, using one offer for every customer.","D":"Cost leadership, competing by being the cheapest producer."},"correctOption":"B","correctAnswer":"Niche marketing, concentrating on a narrow, specialised group of buyers.","questionType":"MCQ","explanation":{"correct_reason":"By serving only boutique hotels with hand-woven scarves, Glenherva Textiles concentrates on a narrow specialist segment, which is the essence of niche marketing rather than broad mass appeal.","distractor_reasons":{"A":"Mass marketing would target the whole population with a widely available product, whereas Glenherva deliberately limits its customers to a few boutique hotels.","B":"By serving only boutique hotels with hand-woven scarves, Glenherva Textiles concentrates on a narrow specialist segment, which is the essence of niche marketing rather than broad mass appeal.","C":"Undifferentiated marketing ignores segment differences and offers one product to all buyers, the opposite of specialising for a handful of boutique hotels.","D":"Cost leadership means competing on low price and high volume. Hand-woven scarves sold to a few hotels suggest differentiation rather than being the lowest-cost producer."}}},{"id":"P1_U3_MCQ_1513","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1513","question":"Hurstan Motors Ltd in Busan, South Korea held 6% of the local car market in 2025 and 9% in 2026. By how many percentage points did its market share increase over the year?","options":{"A":"3 percentage points","B":"50 percentage points","C":"6 percentage points","D":"1.5 percentage points"},"correctOption":"A","correctAnswer":"3 percentage points","questionType":"MCQ","explanation":{"correct_reason":"The change in market share is found by subtracting the earlier share from the later one. Nine percent minus 6% equals a rise of exactly 3 percentage points for Hurstan Motors.","distractor_reasons":{"A":"The change in market share is found by subtracting the earlier share from the later one. Nine percent minus 6% equals a rise of exactly 3 percentage points for Hurstan Motors.","B":"50 is the relative percentage increase, found from 3 divided by 6, but the question asks for percentage points, which are the simple difference between the two shares.","C":"6 percentage points is the entire 2025 share. The increase is the gap between 6% and 9%, not the starting value that Hurstan Motors began with.","D":"1.5 comes from halving the 3-point gap. Subtracting 6% from 9% gives a difference of 3 percentage points, not 1.5. For Hurstan Motors Ltd, the facts point to 3 percentage points, so this option cannot be correct."}}},{"id":"P1_U3_MCQ_1514","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1514","question":"Iverdale Clinics Ltd in Sao Paulo, Brazil drafted a patient survey containing the item: 'Don't you agree our service is excellent?' What is the main flaw with this particular question?","options":{"A":"It is a leading question that pressures patients to agree.","B":"It uses closed response formats that are hard to analyse.","C":"It asks about a topic unsuitable for primary research.","D":"It can only be asked during a face-to-face interview."},"correctOption":"A","correctAnswer":"It is a leading question that pressures patients to agree.","questionType":"MCQ","explanation":{"correct_reason":"The phrase 'Don't you agree' suggests the desired answer, so patients are nudged toward agreeing. A neutral item such as 'How would you rate our service?' would avoid this bias in Iverdale's survey.","distractor_reasons":{"A":"The phrase 'Don't you agree' suggests the desired answer, so patients are nudged toward agreeing. A neutral item such as 'How would you rate our service?' would avoid this bias in Iverdale's survey.","B":"The problem is not closed responses but the wording. Even a closed rating scale would be flawed if it were introduced by such a leading phrase.","C":"Service quality is entirely suitable for primary research. The flaw lies in how the item is phrased, not in the decision to ask Iverdale's patients at all.","D":"The question could be asked online, by post or in person. Its weakness is bias from leading wording, not a restriction on the interview method used."}}},{"id":"P1_U3_MCQ_1515","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1515","question":"Jarviston Toys Ltd in Copenhagen, Denmark adds a recognisable mascot character and distinctive packaging to its range of building blocks. Which part of the marketing mix is being changed by this decision?","options":{"A":"Product","B":"Price","C":"Promotion","D":"Place"},"correctOption":"A","correctAnswer":"Product","questionType":"MCQ","explanation":{"correct_reason":"Branding, packaging and a mascot are all part of the product element of the marketing mix. They help Jarviston Toys differentiate its building blocks from competing products in Denmark.","distractor_reasons":{"A":"Branding, packaging and a mascot are all part of the product element of the marketing mix. They help Jarviston Toys differentiate its building blocks from competing products in Denmark.","B":"Price concerns the amount charged and the pricing method used. Adding a mascot does not change what customers pay for the building blocks.","C":"Promotion is communication with buyers. Although a mascot may aid recognition, the scenario describes changing the product's packaging and identity rather than running an advertising campaign.","D":"Place is about distribution and where goods are sold. Packaging design does not decide which shops choose to stock Jarviston Toys' building blocks."}}},{"id":"P1_U3_MCQ_1516","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1516","question":"Kelvera Salons Ltd in Oslo, Norway deliberately presents itself as a premium, high-priced and exclusive hair salon while nearby rivals compete mainly on low prices. What marketing activity is this?","options":{"A":"Market positioning, creating a distinct image in customers' minds.","B":"Cost leadership, by undercutting the prices of rival salons.","C":"Market research, by gathering detailed data on customer tastes.","D":"Mass production, by standardising the service it delivers."},"correctOption":"A","correctAnswer":"Market positioning, creating a distinct image in customers' minds.","questionType":"MCQ","explanation":{"correct_reason":"Kelvera Salons chooses a premium, exclusive image that contrasts sharply with low-price rivals. This is market positioning designed to occupy a distinct place in the minds of Oslo customers.","distractor_reasons":{"A":"Kelvera Salons chooses a premium, exclusive image that contrasts sharply with low-price rivals. This is market positioning designed to occupy a distinct place in the minds of Oslo customers.","B":"Cost leadership would mean charging less than competitors. Kelvera does the opposite by setting high prices and emphasising exclusivity to its clients.","C":"Market research involves collecting evidence from customers. The scenario describes the image the salon projects, not the gathering of data about customer tastes.","D":"Mass production applies to making standardised goods in bulk, not to a salon that is differentiating its service image in a competitive Oslo market."}}},{"id":"P1_U3_MCQ_1517","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1517","question":"Lorwick Dairy Ltd in Kampala, Uganda increased its monthly milk sales from 40,000 litres to 46,000 litres after running a new advertising campaign. What was the percentage increase in its sales?","options":{"A":"15%","B":"6%","C":"13%","D":"115%"},"correctOption":"A","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Sales rose by 6,000 litres from a base of 40,000. Dividing 6,000 by 40,000 and multiplying by 100 gives a 15% increase for Lorwick Dairy's monthly milk sales.","distractor_reasons":{"A":"Sales rose by 6,000 litres from a base of 40,000. Dividing 6,000 by 40,000 and multiplying by 100 gives a 15% increase for Lorwick Dairy's monthly milk sales.","B":"6% is found by dividing the 6,000-litre rise by the new total of 46,000. Percentage change must instead use the original 40,000 litres as the denominator.","C":"13% would come from comparing the increase with the average of the old and new sales levels, which is not the standard method of calculating percentage growth.","D":"115% describes the new sales level as a share of the old one, not the increase, which is only the extra 15% above 40,000 litres."}}},{"id":"P1_U3_MCQ_1518","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1518","question":"Merivale Tours Ltd in Queenstown, New Zealand wants quick, low-cost feedback from 500 tourists using a simple rating scale for every question. Which data collection method is most appropriate?","options":{"A":"A structured questionnaire distributed to all 500 tourists.","B":"An in-depth interview with each of the 500 tourists.","C":"A focus group of eight tourists discussing their holiday at length.","D":"Observation of tourists without asking them any questions."},"correctOption":"A","correctAnswer":"A structured questionnaire distributed to all 500 tourists.","questionType":"MCQ","explanation":{"correct_reason":"A structured questionnaire with rating scales can be answered quickly by 500 tourists at low cost, and the resulting responses are easy to tabulate and compare for Merivale Tours.","distractor_reasons":{"A":"A structured questionnaire with rating scales can be answered quickly by 500 tourists at low cost, and the resulting responses are easy to tabulate and compare for Merivale Tours.","B":"Interviewing 500 people individually would be slow and expensive, and the open answers would be difficult to summarise for Merivale Tours' simple rating needs.","C":"A focus group of eight gives depth but only a tiny sample, so it cannot supply 500 separate responses for a broad picture of tourist satisfaction.","D":"Observation records behaviour but not opinions or ratings, so it could not provide the structured feedback that Merivale Tours requires from its customers."}}},{"id":"P1_U3_MCQ_1519","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1519","question":"Norfield Software Ltd in Hyderabad, India launches a new budgeting app at a deliberately low price to attract a large customer base quickly before raising it later. Which pricing strategy is being used?","options":{"A":"Price skimming, charging a high initial price.","B":"Penetration pricing, setting a low price to win market share.","C":"Cost-plus pricing, adding a mark-up to unit cost.","D":"Premium pricing, signalling luxury through a high price."},"correctOption":"B","correctAnswer":"Penetration pricing, setting a low price to win market share.","questionType":"MCQ","explanation":{"correct_reason":"Charging a deliberately low launch price to build a large customer base quickly is penetration pricing, a strategy aimed at gaining market share before Norfield Software raises the price.","distractor_reasons":{"A":"Price skimming sets a high initial price to earn revenue from keen early buyers, the exact opposite of the low launch price chosen by Norfield Software.","B":"Charging a deliberately low launch price to build a large customer base quickly is penetration pricing, a strategy aimed at gaining market share before Norfield Software raises the price.","C":"Cost-plus pricing sets a price from production cost plus a mark-up. This scenario stresses a low market-entry price rather than a calculation based on costs.","D":"Premium pricing uses a high price to suggest luxury and quality, which conflicts directly with the low price selected to attract budgeting app users."}}},{"id":"P1_U3_MCQ_1520","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1520","question":"Oakhill Coffee Ltd in Seattle, United States gives customers a loyalty card offering a free drink after ten purchases. What is the primary marketing aim of this scheme?","options":{"A":"To reduce the cost of the coffee beans it buys.","B":"To encourage repeat purchases and build customer loyalty.","C":"To change the legal structure of the business.","D":"To gather primary data about competitor prices."},"correctOption":"B","correctAnswer":"To encourage repeat purchases and build customer loyalty.","questionType":"MCQ","explanation":{"correct_reason":"A free drink after ten purchases rewards repeat custom, so Oakhill Coffee's card is designed to retain buyers and encourage them to return rather than switch to rival cafes.","distractor_reasons":{"A":"A loyalty card rewards customers after purchase and does not lower the price that Oakhill Coffee pays its bean suppliers for raw materials.","B":"A free drink after ten purchases rewards repeat custom, so Oakhill Coffee's card is designed to retain buyers and encourage them to return rather than switch to rival cafes.","C":"The scheme is a marketing incentive, not a change in the firm's legal structure such as becoming a limited company or a partnership.","D":"The card tracks a customer's own purchases; it is not a method for collecting data about the prices charged by competing coffee shops."}}},{"id":"P1_U3_MCQ_1521","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1521","question":"Penharrow Foods Ltd in Lagos, Nigeria sold 15,000 packets of its instant soup in 2026. The total soup market in Lagos recorded 250,000 packets over the same period. What was Penharrow Foods' market share?","options":{"A":"2.4%","B":"60%","C":"16.7%","D":"6%"},"correctOption":"D","correctAnswer":"6%","questionType":"MCQ","explanation":{"correct_reason":"Market share is the company's sales divided by total market sales, multiplied by 100. With 15,000 packets sold out of 250,000, Penharrow Foods held exactly 6% of the Lagos soup market.","distractor_reasons":{"A":"2.4% would result from dividing 250,000 by 15,000 and taking a reciprocal incorrectly; the correct ratio compares Penharrow's 15,000 packets with the whole market.","B":"60% mistakes a sixth for three fifths. Fifteen thousand packets are only a small portion of the 250,000 packets sold across the Lagos soup market.","C":"16.7% comes from dividing 250,000 by 15,000 instead of the other way round, reversing numerator and denominator in the market share formula.","D":"Market share is the company's sales divided by total market sales, multiplied by 100. With 15,000 packets sold out of 250,000, Penharrow Foods held exactly 6% of the Lagos soup market."}}},{"id":"P1_U3_MCQ_1522","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1522","question":"Quillstone Cafes Ltd in Buenos Aires, Argentina wants to see which drinks customers actually choose at a new self-service counter, without influencing their behaviour. Which research method should the company use?","options":{"A":"A postal survey mailed to 1,000 local households.","B":"A telephone interview with 200 randomly selected people.","C":"Observation of customers as they use the counter.","D":"Analysis of published government statistics on drinking."},"correctOption":"C","correctAnswer":"Observation of customers as they use the counter.","questionType":"MCQ","explanation":{"correct_reason":"Observation records actual behaviour in a natural setting without asking questions, so Quillstone Cafes can see which drinks Buenos Aires customers really pick at the self-service counter.","distractor_reasons":{"A":"A postal survey asks people to report choices later and may not reflect real behaviour at the counter; it also cannot capture the immediate selection process.","B":"A telephone interview relies on what people say they do. It would not show the actual drink choices made by customers at Quillstone Cafes' new counter.","C":"Observation records actual behaviour in a natural setting without asking questions, so Quillstone Cafes can see which drinks Buenos Aires customers really pick at the self-service counter.","D":"Published statistics describe broad national patterns and cannot reveal the specific choices made by individuals at one cafe in Buenos Aires."}}},{"id":"P1_U3_MCQ_1523","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1523","question":"Ravelton Supermarkets Ltd in Johannesburg, South Africa sells a litre of milk below its own purchase cost to attract shoppers into the store, expecting them to buy other profitable items. What pricing strategy is this?","options":{"A":"Price skimming, charging a high launch price.","B":"Premium pricing, suggesting luxury through a high price.","C":"Cost-plus pricing, adding a mark-up to unit cost.","D":"Loss leader pricing, selling below cost to draw customers in."},"correctOption":"D","correctAnswer":"Loss leader pricing, selling below cost to draw customers in.","questionType":"MCQ","explanation":{"correct_reason":"Selling one product below cost to draw customers in and then sell them other profitable items is loss leader pricing, used by Ravelton Supermarkets to increase overall basket value.","distractor_reasons":{"A":"Price skimming means charging a high price at launch to earn maximum revenue from keen buyers, not selling milk below cost to attract shoppers into the store.","B":"Premium pricing sets a high price to signal quality and exclusivity. Ravelton is doing the reverse by pricing milk lower than its own purchase cost.","C":"Cost-plus pricing adds a mark-up to the cost of a product. Selling below cost contradicts this method because there is no positive mark-up on the milk.","D":"Selling one product below cost to draw customers in and then sell them other profitable items is loss leader pricing, used by Ravelton Supermarkets to increase overall basket value."}}},{"id":"P1_U3_MCQ_1524","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1524","question":"Sableton Publishing Ltd in Adelaide, Australia currently sells science textbooks to secondary schools at home and now starts selling the same titles to adult learners on nearby Pacific islands. Which growth strategy is this?","options":{"A":"Market penetration, selling more of the same to existing schools.","B":"Product development, creating new books for existing schools.","C":"Market development, taking existing products into new markets.","D":"Diversification, launching new products in new markets."},"correctOption":"C","correctAnswer":"Market development, taking existing products into new markets.","questionType":"MCQ","explanation":{"correct_reason":"Sableton is keeping its existing science textbooks but entering new markets, adult learners on Pacific islands, so this is market development rather than any change to the product itself.","distractor_reasons":{"A":"Market penetration would mean selling more of the same textbooks to the same secondary schools, not reaching a different group of adult learners abroad.","B":"Product development creates new or improved products for existing customers. Sableton is using the same science titles, so the product has not been developed.","C":"Sableton is keeping its existing science textbooks but entering new markets, adult learners on Pacific islands, so this is market development rather than any change to the product itself.","D":"Diversification involves new products in new markets. Here the textbooks already exist, so only the market is new and the product has not changed."}}},{"id":"P1_U3_MCQ_1525","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1525","question":"Tarnbury Tours Ltd in Prague, Czech Republic saw its share of the city walking-tour market fall from 12% in 2025 to 9% in 2026. By how many percentage points did its market share fall over the year?","options":{"A":"3%","B":"25 percentage points","C":"21 percentage points","D":"3 percentage points"},"correctOption":"D","correctAnswer":"3 percentage points","questionType":"MCQ","explanation":{"correct_reason":"The fall in share is the earlier figure minus the later figure. Twelve percent minus 9% equals a decline of 3 percentage points for Tarnbury Tours in Prague.","distractor_reasons":{"A":"3% expresses a relative percentage fall, but the question asks for percentage points, which are the straightforward arithmetic difference between 12% and 9%.","B":"25 would be the relative decline, calculated as 3 divided by 12, but that is a percentage change rather than the difference in percentage points requested.","C":"21 percentage points adds the two shares together. The decline is the gap between them, which is 3 percentage points, not their sum.","D":"The fall in share is the earlier figure minus the later figure. Twelve percent minus 9% equals a decline of 3 percentage points for Tarnbury Tours in Prague."}}},{"id":"P1_U3_MCQ_1526","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1526","question":"Umbra Wines Ltd in Mendoza, Argentina wants to explore how consumers feel about a proposed new wine label and the words they use to describe it. Which research method would best reveal these views?","options":{"A":"A census of every household in Mendoza.","B":"A structured questionnaire using only closed questions.","C":"A focus group of eight regular wine buyers.","D":"A review of sales invoices from the previous year."},"correctOption":"C","correctAnswer":"A focus group of eight regular wine buyers.","questionType":"MCQ","explanation":{"correct_reason":"A focus group of eight regular buyers lets a moderator probe feelings and language in detail, making it ideal for exploring reactions to the proposed new Umbra Wines label.","distractor_reasons":{"A":"A census of every household would be extremely costly and would collect mostly numerical answers, not the rich feelings and vocabulary the firm wants.","B":"A structured questionnaire with closed questions limits respondents to preset answers, so it would not capture the spontaneous words people use about the label.","C":"A focus group of eight regular buyers lets a moderator probe feelings and language in detail, making it ideal for exploring reactions to the proposed new Umbra Wines label.","D":"Last year's sales invoices show what sold, not why customers felt a certain way or how they would describe the proposed new wine label."}}},{"id":"P1_U3_MCQ_1527","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1527","question":"Velmere Fashion Ltd in Istanbul, Turkey sells its clothing only through its own website and social media storefront, with no physical shops at all. Which element of the marketing mix is mainly illustrated by this choice?","options":{"A":"Product","B":"Price","C":"Promotion","D":"Place"},"correctOption":"D","correctAnswer":"Place","questionType":"MCQ","explanation":{"correct_reason":"Place covers the channels through which a product reaches customers. Selling only through a website and social storefront is a distribution decision made by Velmere Fashion in Istanbul.","distractor_reasons":{"A":"Product concerns the clothing's design, fabric and quality. The scenario describes where garments are sold, not how the clothing itself is made.","B":"Price is the amount charged to customers. The question gives no information about Velmere Fashion's prices, discounts or payment terms. Velmere Fashion Ltd's circumstances match Place, so this option does not fit.","C":"Promotion communicates with buyers through advertising and social posts, but the central decision here is the channel used to deliver the clothing to customers.","D":"Place covers the channels through which a product reaches customers. Selling only through a website and social storefront is a distribution decision made by Velmere Fashion in Istanbul."}}},{"id":"P1_U3_MCQ_1528","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1528","question":"Wrenwick Hotels Ltd in Bangkok, Thailand separates its customers into business travellers and holiday tourists so it can design different room packages for each group. What is the main benefit of this segmentation?","options":{"A":"It removes the need for any further market research.","B":"It guarantees a higher market share for every hotel.","C":"It lets the firm tailor its offer to distinct customer needs.","D":"It eliminates competition from other Bangkok hotels."},"correctOption":"C","correctAnswer":"It lets the firm tailor its offer to distinct customer needs.","questionType":"MCQ","explanation":{"correct_reason":"Segmenting into business travellers and tourists lets Wrenwick Hotels tailor room packages to each group's distinct needs, which should improve satisfaction and sales compared with one generic offer.","distractor_reasons":{"A":"Segmentation does not remove the need for research; Wrenwick still needs evidence about what each group of Bangkok travellers actually wants.","B":"Segmentation cannot guarantee a higher market share, because rivals may serve the same segments well and customer choices can change over time.","C":"Segmenting into business travellers and tourists lets Wrenwick Hotels tailor room packages to each group's distinct needs, which should improve satisfaction and sales compared with one generic offer.","D":"Segmentation does not eliminate competitors. Other Bangkok hotels can target the same business and tourist groups with their own room packages."}}},{"id":"P1_U3_MCQ_1529","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1529","question":"Yarrowgate Electronics Ltd in Osaka, Japan sold 38,000 wireless earbuds in 2026. The total earbud market in the Osaka region was 190,000 units that year. What market share did Yarrowgate achieve?","options":{"A":"5%","B":"0.5%","C":"38%","D":"20%"},"correctOption":"D","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"Market share is the firm's sales over total market sales times 100. Yarrowgate sold 38,000 of 190,000 earbuds, and 38,000 divided by 190,000 times 100 equals 20%.","distractor_reasons":{"A":"5% comes from dividing 190,000 by 38,000, reversing the fraction, instead of putting Yarrowgate's own sales over the whole Osaka market.","B":"0.5% would require moving the decimal far beyond the true result. Thirty-eight thousand out of 190,000 is one fifth of the regional market.","C":"38% wrongly takes the 38,000 sales figure as a percentage directly, ignoring that it must be divided by the 190,000 total market units.","D":"Market share is the firm's sales over total market sales times 100. Yarrowgate sold 38,000 of 190,000 earbuds, and 38,000 divided by 190,000 times 100 equals 20%."}}},{"id":"P1_U3_MCQ_1530","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1530","question":"Zelcrest Sports Ltd in Vancouver, Canada uses its own sales invoices from the past three years to forecast demand for the next season. What kind of data is the company analysing?","options":{"A":"Primary data gathered from a brand-new survey.","B":"Qualitative data obtained from a focus group.","C":"Secondary data held internally by the business.","D":"Experimental data from a controlled test market."},"correctOption":"C","correctAnswer":"Secondary data held internally by the business.","questionType":"MCQ","explanation":{"correct_reason":"Sales invoices were recorded for routine trading, not for this forecast, so Zelcrest Sports is analysing internal secondary data that already exists within the business.","distractor_reasons":{"A":"Primary data would require Zelcrest Sports to collect fresh information from customers. Old invoices were created for ordinary sales administration, not for this research.","B":"Qualitative data consist of opinions, attitudes and descriptions. Sales invoices are numerical records of transactions, so they are not qualitative evidence.","C":"Sales invoices were recorded for routine trading, not for this forecast, so Zelcrest Sports is analysing internal secondary data that already exists within the business.","D":"Experimental data arise from a controlled test the firm runs. Looking back at three years of past invoices involves no new experiment in Vancouver."}}},{"id":"P1_U3_MCQ_1531","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1531","question":"Cindergrove Ceramics Ltd in Valencia, Spain introduces a resealable, eco-friendly package for its ceramic tiles so that the product stands out on shelves. Which marketing mix element is being changed?","options":{"A":"Price","B":"Promotion","C":"Place","D":"Product"},"correctOption":"D","correctAnswer":"Product","questionType":"MCQ","explanation":{"correct_reason":"Packaging is part of the product element. By adding a resealable, eco-friendly package, Cindergrove Ceramics changes the physical offering that customers in Valencia see and handle.","distractor_reasons":{"A":"Price concerns the amount paid by customers. A new package does not by itself set the selling price of the ceramic tiles.","B":"Promotion communicates messages to buyers. Although the package may carry a logo, the change described is to the product's physical form rather than an advertising campaign.","C":"Place is about distribution routes and stockists. Adding a resealable package does not decide which shops in Valencia choose to sell the tiles.","D":"Packaging is part of the product element. By adding a resealable, eco-friendly package, Cindergrove Ceramics changes the physical offering that customers in Valencia see and handle."}}},{"id":"P1_U3_MCQ_1532","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1532","question":"Beckmoor Hardware Ltd in Foshan, China standardises its fittings and buys components in bulk so it can charge the lowest prices in the national market. Which competitive strategy is the firm following?","options":{"A":"Differentiation, offering unique features.","B":"Niche marketing, targeting a narrow customer group.","C":"Cost leadership, competing on the lowest price.","D":"Premium positioning, charging the highest price."},"correctOption":"C","correctAnswer":"Cost leadership, competing on the lowest price.","questionType":"MCQ","explanation":{"correct_reason":"By standardising products and buying in bulk to keep costs low, Beckmoor Hardware can undercut rivals on price, which is the essence of a cost leadership strategy.","distractor_reasons":{"A":"Differentiation means offering unique features that justify a higher price. Beckmoor is doing the opposite by standardising fittings to reduce costs.","B":"Niche marketing concentrates on a narrow customer group. Beckmoor sells standard fittings across the whole national market, not to a specialist segment.","C":"By standardising products and buying in bulk to keep costs low, Beckmoor Hardware can undercut rivals on price, which is the essence of a cost leadership strategy.","D":"Premium positioning charges high prices to signal quality. Beckmoor competes by charging the lowest prices in the market, not the highest."}}},{"id":"P1_U3_MCQ_1533","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1533","question":"Corvale Bakeries Ltd in Manila, Philippines sells 12,000 loaves of bread each week at a selling price of $2.50 per loaf. What is the bakery's weekly total revenue from bread sales?","options":{"A":"$4,800","B":"$24,000","C":"$30,500","D":"$30,000"},"correctOption":"D","correctAnswer":"$30,000","questionType":"MCQ","explanation":{"correct_reason":"Total revenue equals price multiplied by quantity sold. Corvale Bakeries sells 12,000 loaves at $2.50 each, giving weekly revenue of 12,000 times $2.50, which is $30,000.","distractor_reasons":{"A":"$4,800 comes from dividing 12,000 by 2.5, confusing revenue with a quantity calculation rather than multiplying price by sales volume. The details given about Corvale Bakeries Ltd support $30,000, so this answer is unsuitable.","B":"$24,000 would be the revenue if each loaf sold for $2 rather than $2.50; it ignores the extra $0.50 earned on every one of the 12,000 loaves.","C":"$30,500 adds $500 to the correct revenue without any basis in the figures, since 12,000 times $2.50 is exactly $30,000. The scenario for Corvale Bakeries Ltd instead describes $30,000, which rules this alternative out.","D":"Total revenue equals price multiplied by quantity sold. Corvale Bakeries sells 12,000 loaves at $2.50 each, giving weekly revenue of 12,000 times $2.50, which is $30,000."}}},{"id":"P1_U3_MCQ_1534","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1534","question":"Eldermere Research Ltd in Helsinki, Finland sent 4,000 online questionnaires to local residents and received 1,000 completed responses. What was the response rate for this survey?","options":{"A":"4%","B":"400%","C":"25%","D":"0.25%"},"correctOption":"C","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"Response rate is completed returns divided by questionnaires sent, times 100. Eldermere received 1,000 of 4,000, so 1,000 divided by 4,000 times 100 equals 25%.","distractor_reasons":{"A":"4% comes from dividing 4,000 by 1,000 and then inverting badly; the correct fraction puts returned questionnaires over the number sent out.","B":"400% reverses the fraction, dividing 4,000 sent by 1,000 returned. A response rate cannot exceed 100% when only some forms are returned.","C":"Response rate is completed returns divided by questionnaires sent, times 100. Eldermere received 1,000 of 4,000, so 1,000 divided by 4,000 times 100 equals 25%.","D":"0.25% confuses the decimal 0.25 with a percentage. Multiplying 0.25 by 100 converts the proportion into the correct 25% response rate."}}},{"id":"P1_U3_MCQ_1535","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1535","question":"Falstone Pharmacy Ltd in Kuala Lumpur, Malaysia runs a two-week 'buy one, get one free' offer on sunscreen to boost footfall. Which element of the marketing mix does this short-term offer belong to?","options":{"A":"Product","B":"Price","C":"Place","D":"Promotion"},"correctOption":"D","correctAnswer":"Promotion","questionType":"MCQ","explanation":{"correct_reason":"A time-limited 'buy one, get one free' incentive is a sales promotion tactic, which sits within the promotion element of the marketing mix used by Falstone Pharmacy.","distractor_reasons":{"A":"Product relates to the sunscreen's formulation, packaging and brand, not to a temporary incentive designed to attract shoppers into the pharmacy.","B":"Price is the regular amount charged for a product. Although the offer changes effective value, it is a promotional deal rather than a permanent pricing policy.","C":"Place concerns where the sunscreen is sold. The buy-one-get-one-free offer does not change the distribution channel used by Falstone Pharmacy. Falstone Pharmacy Ltd's circumstances match Promotion, so this option does not fit.","D":"A time-limited 'buy one, get one free' incentive is a sales promotion tactic, which sits within the promotion element of the marketing mix used by Falstone Pharmacy."}}},{"id":"P1_U3_MCQ_1536","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1536","question":"Glencairn Fitness Ltd in Stockholm, Sweden found through customer interviews that busy professionals wanted very short workouts, so it created 30-minute express sessions. Which business orientation does this illustrate?","options":{"A":"A production orientation, focused on efficient output.","B":"A sales orientation, pushing existing services harder.","C":"A market orientation, responding to identified customer needs.","D":"A product orientation, improving the service without research."},"correctOption":"C","correctAnswer":"A market orientation, responding to identified customer needs.","questionType":"MCQ","explanation":{"correct_reason":"Glencairn Fitness identified a need through interviews and then designed 30-minute sessions to satisfy it, which demonstrates a market orientation centred on customer needs.","distractor_reasons":{"A":"A production orientation would emphasise efficient, standardised delivery regardless of what customers said; Glencairn changed its service to match expressed needs.","B":"A sales orientation pushes existing services with heavy selling. Here the firm first listened to clients and then created a new express format for them.","C":"Glencairn Fitness identified a need through interviews and then designed 30-minute sessions to satisfy it, which demonstrates a market orientation centred on customer needs.","D":"A product orientation improves the offering based on the firm's own ideas. Glencairn used customer interviews, so its decisions came from the market."}}},{"id":"P1_U3_MCQ_1537","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1537","question":"Harlowprint Ltd in Dar es Salaam, Tanzania estimates the local notebook market expanded from 50,000 units in 2025 to 57,500 units in 2026. What was the market's percentage growth over the year?","options":{"A":"7.5%","B":"13%","C":"115%","D":"15%"},"correctOption":"D","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Growth equals the increase divided by the starting value. The market grew by 7,500 units from 50,000, so 7,500 divided by 50,000 times 100 gives 15% growth.","distractor_reasons":{"A":"7.5% treats the 7,500-unit increase as though it were already a percentage. It must be divided by the original 50,000 units first.","B":"13% would use the new total of 57,500 as the denominator. Percentage growth is measured against the original 50,000 units in Tanzania.","C":"115% is the new market size relative to the old one, not the growth, which is only the extra 15% above the original 50,000 units.","D":"Growth equals the increase divided by the starting value. The market grew by 7,500 units from 50,000, so 7,500 divided by 50,000 times 100 gives 15% growth."}}},{"id":"P1_U3_MCQ_1538","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1538","question":"Invermere Foods Ltd in Wellington, New Zealand wants exact information about the snack-buying habits of all 300 of its employees. Which research approach should the company choose?","options":{"A":"A sample survey of just 30 employees.","B":"A focus group of six senior managers.","C":"A census covering all 300 employees.","D":"Observation of shoppers in one local store."},"correctOption":"C","correctAnswer":"A census covering all 300 employees.","questionType":"MCQ","explanation":{"correct_reason":"A census questions every member of the group. Since Invermere Foods needs exact information about all 300 employees, surveying the whole group avoids sampling error entirely.","distractor_reasons":{"A":"A sample of 30 employees would give only an estimate and would leave 270 people unrepresented, which does not meet the need for exact information.","B":"A focus group of six managers gives depth but covers a tiny fraction of the 300 employees and focuses on opinions rather than exact buying habits.","C":"A census questions every member of the group. Since Invermere Foods needs exact information about all 300 employees, surveying the whole group avoids sampling error entirely.","D":"Observing shoppers in one store records the behaviour of passers-by, not the specific snack habits of Invermere Foods' own 300 employees."}}},{"id":"P1_U3_MCQ_1539","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1539","question":"Jarrowton Electronics Ltd in Seoul, South Korea launches a cutting-edge gadget at a very high price, aiming to earn strong revenue from keen early adopters before lowering it. Which pricing strategy is this?","options":{"A":"Penetration pricing, setting a low launch price.","B":"Loss leader pricing, selling below cost.","C":"Cost-plus pricing, adding a mark-up to cost.","D":"Price skimming, charging a high initial price."},"correctOption":"D","correctAnswer":"Price skimming, charging a high initial price.","questionType":"MCQ","explanation":{"correct_reason":"Setting a high initial price to maximise revenue from early adopters before reducing it later is price skimming, the strategy Jarrowton Electronics is using in Seoul.","distractor_reasons":{"A":"Penetration pricing sets a low price to win market share quickly, the opposite of Jarrowton's very high launch price for the new gadget.","B":"Loss leader pricing sells an item below cost to attract customers. Jarrowton is charging a premium price, not a below-cost one.","C":"Cost-plus pricing builds a price from unit cost plus a mark-up. The scenario emphasises a high launch price aimed at early adopters, not a cost calculation.","D":"Setting a high initial price to maximise revenue from early adopters before reducing it later is price skimming, the strategy Jarrowton Electronics is using in Seoul."}}},{"id":"P1_U3_MCQ_1540","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1540","question":"Kelmscott Textiles Ltd in Birmingham, United Kingdom uses certified organic cotton and fair-trade labelling that competing firms do not offer. What does this give the company in its market?","options":{"A":"A cost leadership position based on the lowest price.","B":"A legal monopoly in the organic cotton market.","C":"A differentiated product with a competitive advantage.","D":"A reduction in the firm's total production costs."},"correctOption":"C","correctAnswer":"A differentiated product with a competitive advantage.","questionType":"MCQ","explanation":{"correct_reason":"Organic cotton and fair-trade certification are features rivals cannot match, so Kelmscott Textiles has a differentiated product and a competitive advantage with ethical shoppers.","distractor_reasons":{"A":"Cost leadership means being the lowest-cost producer. Organic cotton and fair-trade certification usually raise costs rather than lower them. In Kelmscott Textiles Ltd's case, the correct description is A differentiated product with a competitive advantage, not this choice.","B":"Using organic cotton does not create a legal monopoly; other firms are free to source and certify organic cotton for their own products.","C":"Organic cotton and fair-trade certification are features rivals cannot match, so Kelmscott Textiles has a differentiated product and a competitive advantage with ethical shoppers.","D":"Certification and organic materials tend to increase expenses, so they do not reduce Kelmscott Textiles' total costs of production. For Kelmscott Textiles Ltd, the facts point to A differentiated product with a competitive advantage, so this option cannot be correct."}}},{"id":"P1_U3_MCQ_1541","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1541","question":"Lorvale Motors Ltd in Pretoria, South Africa reports the local sedan market rose from 80,000 units in 2025 to 92,000 units in 2026. What was the market's percentage growth over the year?","options":{"A":"12%","B":"15%","C":"8%","D":"115%"},"correctOption":"B","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Growth is the increase divided by the original market size. The sedan market added 12,000 units on a base of 80,000, so 12,000 divided by 80,000 times 100 equals 15%.","distractor_reasons":{"A":"12% divides the 12,000-unit rise by the new total of 92,000; growth must be calculated against the original 80,000 units instead.","B":"Growth is the increase divided by the original market size. The sedan market added 12,000 units on a base of 80,000, so 12,000 divided by 80,000 times 100 equals 15%.","C":"8% would come from comparing the increase with a figure other than the starting market size; the correct base is 80,000 units in 2025.","D":"115% is the new market expressed as a percentage of the old one. Growth is just the additional 15% above the original level in Pretoria."}}},{"id":"P1_U3_MCQ_1542","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1542","question":"Marlton Research Ltd in Hanoi, Vietnam collected 2,000 responses from people who clicked a social media advert. What is the main concern about the reliability of this sample?","options":{"A":"The sample may be biased because it only includes people who saw the advert.","B":"Online surveys are always more reliable than face-to-face interviews.","C":"A sample of 2,000 is too small to produce any useful data.","D":"The data cannot be used because they are primary rather than secondary."},"correctOption":"A","correctAnswer":"The sample may be biased because it only includes people who saw the advert.","questionType":"MCQ","explanation":{"correct_reason":"Only people who saw and clicked the advert could respond, so the sample excludes many local consumers and is likely to be biased toward social media users interested in the product.","distractor_reasons":{"A":"Only people who saw and clicked the advert could respond, so the sample excludes many local consumers and is likely to be biased toward social media users interested in the product.","B":"Online surveys are not automatically more reliable; reliability depends on sampling and question design, and this particular sample has a clear selection bias.","C":"A sample of 2,000 is not inherently too small. The problem is who was included, not the number of responses collected in Hanoi.","D":"Primary data can be perfectly valid. The issue is the biased way these primary responses were recruited, not the fact that they are first-hand data."}}},{"id":"P1_U3_MCQ_1543","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1543","question":"Norwick Grocers Ltd in Cork, Ireland supplies 200 small shops through a regional wholesaler rather than delivering directly to each one. Which element of the marketing mix does this arrangement illustrate?","options":{"A":"Product","B":"Place","C":"Price","D":"Promotion"},"correctOption":"B","correctAnswer":"Place","questionType":"MCQ","explanation":{"correct_reason":"Choosing a wholesaler as an intermediary is a distribution decision, so it belongs to place, the marketing mix element concerned with getting goods to customers.","distractor_reasons":{"A":"Product concerns the groceries themselves, their quality and packaging. Using a wholesaler does not change the physical goods Norwick Grocers sells.","B":"Choosing a wholesaler as an intermediary is a distribution decision, so it belongs to place, the marketing mix element concerned with getting goods to customers.","C":"Price is the amount charged to customers. The scenario gives no pricing figures and describes only how the groceries reach the 200 shops.","D":"Promotion communicates with buyers. A wholesaler moves goods through the channel; it is not an advertising or sales-promotion message. Norwick Grocers Ltd's circumstances match Place, so this option does not fit."}}},{"id":"P1_U3_MCQ_1544","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1544","question":"Perenthorpe Tours Ltd in Reykjavik, Iceland offers small-group trips led by local guides, while large coach firms run big impersonal tours. What does Perenthorpe offer its customers?","options":{"A":"A unique selling point based on small groups and local guides.","B":"A legal barrier that prevents coach operators from trading.","C":"The lowest possible price in the Icelandic tour market.","D":"A reduction in the cost of running each guided trip."},"correctOption":"A","correctAnswer":"A unique selling point based on small groups and local guides.","questionType":"MCQ","explanation":{"correct_reason":"Small groups and local guides are features the big coach operators do not provide, so Perenthorpe Tours has a unique selling point that differentiates its trips in Reykjavik.","distractor_reasons":{"A":"Small groups and local guides are features the big coach operators do not provide, so Perenthorpe Tours has a unique selling point that differentiates its trips in Reykjavik.","B":"There is no legal barrier described; other firms are free to run small-group tours if they choose, so Perenthorpe does not hold a monopoly position.","C":"Small-group tours with a personal guide typically cost more per person, not less, so Perenthorpe is not competing on the lowest price.","D":"Small groups may raise the cost per customer because of lower capacity utilisation, so the scenario does not suggest any reduction in operating costs."}}},{"id":"P1_U3_MCQ_1545","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1545","question":"Quentrell Foods Ltd in Kumasi, Ghana sold 7,500 jars of pepper sauce in 2026 out of a total city market of 50,000 jars. What was the company's market share?","options":{"A":"6.7%","B":"15%","C":"0.15%","D":"66.7%"},"correctOption":"B","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Market share equals the firm's sales divided by the total market, times 100. Quentrell sold 7,500 of 50,000 jars, and 7,500 divided by 50,000 times 100 equals 15%.","distractor_reasons":{"A":"6.7% comes from dividing 50,000 by 7,500 and reversing the correct ratio; market share puts the firm's own sales on top.","B":"Market share equals the firm's sales divided by the total market, times 100. Quentrell sold 7,500 of 50,000 jars, and 7,500 divided by 50,000 times 100 equals 15%.","C":"0.15% confuses the decimal 0.15 with a percentage. Multiplying by 100 converts 7,500 out of 50,000 into the true 15% market share.","D":"66.7% would require Quentrell to sell two thirds of the market, whereas 7,500 out of 50,000 jars is only 15% of sales in Kumasi."}}},{"id":"P1_U3_MCQ_1546","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1546","question":"Ravelle Motors Ltd in Nagoya, Japan sent a satisfaction questionnaire only to customers who had made a complaint. What is the main problem with this research approach?","options":{"A":"The sample over-represents dissatisfied customers and will bias the results.","B":"Questionnaires cannot be used to measure customer satisfaction.","C":"The sample is too large for the company to manage and analyse.","D":"Primary data are always less accurate than secondary data."},"correctOption":"A","correctAnswer":"The sample over-represents dissatisfied customers and will bias the results.","questionType":"MCQ","explanation":{"correct_reason":"Sending the questionnaire only to complainers over-represents dissatisfied buyers, so the results will understate overall satisfaction with Ravelle Motors' cars in Nagoya.","distractor_reasons":{"A":"Sending the questionnaire only to complainers over-represents dissatisfied buyers, so the results will understate overall satisfaction with Ravelle Motors' cars in Nagoya.","B":"Questionnaires are widely used to measure satisfaction. The weakness here is who received the form, not the choice of data collection method.","C":"The number of complainers is not described as large. Even a small sample drawn only from complainers would be biased and unrepresentative.","D":"Primary data are not automatically less accurate than secondary data. The issue is biased sampling, not the first-hand nature of the information."}}},{"id":"P1_U3_MCQ_1547","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1547","question":"Tafara Foods Ltd in Addis Ababa, Ethiopia sells a jar of honey for $12. The variable cost of making and packaging each jar is $7. What is the contribution per jar towards fixed costs and profit?","options":{"A":"$7","B":"$5","C":"$19","D":"$2.40"},"correctOption":"B","correctAnswer":"$5","questionType":"MCQ","explanation":{"correct_reason":"Contribution per unit is selling price minus variable cost. Tafara Foods receives $12 per jar and spends $7 on variable costs, leaving $5 of contribution per jar.","distractor_reasons":{"A":"$7 is the variable cost itself, not the contribution. Contribution is what remains after that $7 cost is deducted from the $12 selling price.","B":"Contribution per unit is selling price minus variable cost. Tafara Foods receives $12 per jar and spends $7 on variable costs, leaving $5 of contribution per jar.","C":"$19 adds the $12 price to the $7 cost. Contribution requires subtraction, not addition, so this figure overstates the money available per jar.","D":"$2.40 wrongly applies a percentage to the figures; the question asks for a simple subtraction of $7 from the $12 selling price."}}},{"id":"P1_U3_MCQ_1548","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1548","question":"Ullswater Hotels Ltd in Bath, United Kingdom groups its guests by age, income and family size when designing holiday packages. Which basis of market segmentation is being used?","options":{"A":"Demographic factors such as age and income.","B":"Geographic factors such as climate and region.","C":"Psychographic factors such as lifestyle and values.","D":"Behavioural factors such as purchase frequency."},"correctOption":"A","correctAnswer":"Demographic factors such as age and income.","questionType":"MCQ","explanation":{"correct_reason":"Age, income and family size are demographic variables, so Ullswater Hotels is segmenting its market on demographic factors rather than on location or lifestyle.","distractor_reasons":{"A":"Age, income and family size are demographic variables, so Ullswater Hotels is segmenting its market on demographic factors rather than on location or lifestyle.","B":"Geographic segmentation divides customers by place, climate or region. Ullswater is using personal characteristics of its guests, not where those guests live.","C":"Psychographic segmentation uses attitudes, values and lifestyle. Age and income are objective demographic measures, not personality-based categories. In Ullswater Hotels Ltd's case, the correct description is Demographic factors such as age and income, not this choice.","D":"Behavioural segmentation looks at how often people buy or how loyal they are. Family size and income do not describe purchase behaviour."}}},{"id":"P1_U3_MCQ_1549","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1549","question":"Vellhaven Retail Ltd in Auckland, New Zealand increased its annual revenue from $2 million in 2025 to $2.4 million in 2026. What was the percentage growth in its revenue?","options":{"A":"40%","B":"20%","C":"4%","D":"120%"},"correctOption":"B","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"Revenue grew by $0.4 million on an original base of $2 million. Dividing 0.4 by 2 and multiplying by 100 gives 20% revenue growth for Vellhaven Retail.","distractor_reasons":{"A":"40% would be correct only if the original revenue had been $1 million. The base here is $2 million, giving revenue growth of 20%.","B":"Revenue grew by $0.4 million on an original base of $2 million. Dividing 0.4 by 2 and multiplying by 100 gives 20% revenue growth for Vellhaven Retail.","C":"4% comes from treating the $0.4 million increase as a percentage directly, without dividing it by the $2 million starting figure.","D":"120% describes the new revenue as a share of the old, not the growth, which is the extra 20% above the original $2 million."}}},{"id":"P1_U3_MCQ_1550","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1550","question":"Wexford Foods Ltd in Galway, Ireland wants to find out whether a new packet colour actually changes sales, so it plans to compare two similar shops using different packaging. Which method is this?","options":{"A":"An experiment comparing sales in two similar stores.","B":"A focus group discussing several packaging colours.","C":"A postal survey sent to 5,000 local households.","D":"A census of all shop assistants in Galway."},"correctOption":"A","correctAnswer":"An experiment comparing sales in two similar stores.","questionType":"MCQ","explanation":{"correct_reason":"Changing the packaging in one store while keeping a comparable store unchanged is an experiment, allowing Wexford Foods to isolate the effect of packet colour on actual sales.","distractor_reasons":{"A":"Changing the packaging in one store while keeping a comparable store unchanged is an experiment, allowing Wexford Foods to isolate the effect of packet colour on actual sales.","B":"A focus group would reveal opinions about colours but would not show whether sales actually change, which is what Wexford Foods wants to measure.","C":"A postal survey asks about intentions rather than observed purchases and would not establish whether a colour change affects real buying behaviour.","D":"A census of shop assistants would record staff opinions, not customer responses to the new packet colour in the two Galway stores."}}},{"id":"P1_U3_MCQ_1551","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1551","question":"Xanthe Interiors Ltd in Montreal, Canada sells high-value bespoke furniture through salespeople who demonstrate products in the showroom and answer customer questions face to face. Which form of promotion is this?","options":{"A":"Advertising","B":"Personal selling","C":"Public relations","D":"Sales promotion"},"correctOption":"B","correctAnswer":"Personal selling","questionType":"MCQ","explanation":{"correct_reason":"Face-to-face communication between a salesperson and a buyer, with demonstration and questions, is personal selling, used here for high-value bespoke furniture in Montreal.","distractor_reasons":{"A":"Advertising is a paid, non-personal message through media such as television or social platforms. Xanthe's approach relies on direct conversation with each buyer.","B":"Face-to-face communication between a salesperson and a buyer, with demonstration and questions, is personal selling, used here for high-value bespoke furniture in Montreal.","C":"Public relations builds a favourable image with the public through publicity and events, rather than one-to-one selling of bespoke furniture to individual customers.","D":"Sales promotion uses short-term incentives such as discounts or competitions. Demonstrating furniture and answering questions is personal selling, not an incentive scheme."}}},{"id":"P1_U3_MCQ_1552","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1552","question":"Yewbank Soaps Ltd in Jakarta, Indonesia holds the largest share of the local soap market and its pricing decisions are closely watched by competitors. What role does Yewbank play in this market?","options":{"A":"A market leader with the largest share.","B":"A market follower with a small share.","C":"A market nicher serving one narrow segment.","D":"A new entrant with no established position."},"correctOption":"A","correctAnswer":"A market leader with the largest share.","questionType":"MCQ","explanation":{"correct_reason":"A firm with the largest market share whose actions influence rivals is the market leader, so Yewbank Soaps occupies that position in Jakarta's competitive soap market.","distractor_reasons":{"A":"A firm with the largest market share whose actions influence rivals is the market leader, so Yewbank Soaps occupies that position in Jakarta's competitive soap market.","B":"A market follower has a smaller share and copies the leader. Yewbank instead has the largest share and its decisions influence other soap firms.","C":"A market nicher focuses on a narrow segment, while Yewbank leads the whole Jakarta soap market with the biggest share of total sales.","D":"A new entrant would have little established share and would not have competitors watching its every pricing decision in Indonesia. Yewbank Soaps Ltd's circumstances match A market leader with the largest share, so this option does not fit."}}},{"id":"P1_U3_MCQ_1553","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1553","question":"Zerelda Tours Ltd in Marrakesh, Morocco sold 3,600 desert excursions in 2026. The total market for excursions in the city was 45,000 that year. What was Zerelda's market share?","options":{"A":"12.5%","B":"8%","C":"0.8%","D":"80%"},"correctOption":"B","correctAnswer":"8%","questionType":"MCQ","explanation":{"correct_reason":"Market share is the firm's sales divided by total market sales, times 100. Zerelda sold 3,600 of 45,000 trips, so 3,600 divided by 45,000 times 100 equals 8%.","distractor_reasons":{"A":"12.5% would be the result of dividing 45,000 by 3,600 and inverting. The correct ratio puts Zerelda's own sales over the whole Marrakesh market.","B":"Market share is the firm's sales divided by total market sales, times 100. Zerelda sold 3,600 of 45,000 trips, so 3,600 divided by 45,000 times 100 equals 8%.","C":"0.8% moves the decimal one place too far. Converting 3,600 out of 45,000 into a percentage gives 8%, not 0.8%. Zerelda Tours Ltd's circumstances match 8%, so this option does not fit.","D":"80% treats 3,600 as four fifths of 45,000, whereas it is actually a small fraction of the city's total excursion sales."}}},{"id":"P1_U3_MCQ_1554","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1554","question":"Amberton Clinics Ltd in Lahore, Pakistan asks patients to describe in their own words how they felt about their treatment. What type of data is the clinic collecting?","options":{"A":"Qualitative primary data.","B":"Quantitative secondary data.","C":"Quantitative primary data.","D":"Qualitative secondary data."},"correctOption":"A","correctAnswer":"Qualitative primary data.","questionType":"MCQ","explanation":{"correct_reason":"The clinic gathers first-hand opinions expressed in words rather than numbers, so these are qualitative primary data collected directly from patients in Lahore.","distractor_reasons":{"A":"The clinic gathers first-hand opinions expressed in words rather than numbers, so these are qualitative primary data collected directly from patients in Lahore.","B":"Secondary data already exist from another source. These comments are new and collected by the clinic itself, and they are words rather than figures.","C":"Quantitative data are numerical and can be counted. Open-ended descriptions of feelings are not numbers, so they are qualitative rather than quantitative.","D":"The comments are first-hand accounts from patients, not pre-existing records. They are primary data even though they are qualitative in form."}}},{"id":"P1_U3_MCQ_1555","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1555","question":"Brindlewood Foods Ltd in Bologna, Italy sells pasta, sauces and olive oil under one shared family name rather than giving each item its own brand. What branding approach is this?","options":{"A":"Individual branding, giving each product a different name.","B":"Family branding, using one name for several products.","C":"No branding, selling products without any name.","D":"Private labelling, producing for another retailer's brand."},"correctOption":"B","correctAnswer":"Family branding, using one name for several products.","questionType":"MCQ","explanation":{"correct_reason":"Using one name across several related products is family branding, which lets Brindlewood Foods build a single reputation and promote the pasta, sauces and oil together.","distractor_reasons":{"A":"Individual branding would give the pasta, sauces and oil separate names. Brindlewood deliberately uses the same name for all three products.","B":"Using one name across several related products is family branding, which lets Brindlewood Foods build a single reputation and promote the pasta, sauces and oil together.","C":"The products clearly carry a shared name, so they are branded. Selling without any brand would mean plain, unlabelled goods on the shelf.","D":"Private labelling means making goods for a retailer to sell under its own name. Brindlewood is marketing its own family brand in Bologna."}}},{"id":"P1_U3_MCQ_1556","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1556","question":"Cresswell Toys Ltd in Sheffield, United Kingdom watches children playing and identifies what they enjoy before designing any new toy. What is the starting point of this company's marketing approach?","options":{"A":"Identifying customer needs before designing the product.","B":"Setting the highest price the market will bear.","C":"Maximising output to achieve low unit costs.","D":"Copying competitors' products exactly."},"correctOption":"A","correctAnswer":"Identifying customer needs before designing the product.","questionType":"MCQ","explanation":{"correct_reason":"Cresswell Toys begins by observing and understanding what children actually want, then designs products to satisfy those needs, which is the starting point of a marketing approach.","distractor_reasons":{"A":"Cresswell Toys begins by observing and understanding what children actually want, then designs products to satisfy those needs, which is the starting point of a marketing approach.","B":"Setting the highest possible price is a pricing decision, not the starting point described here. The firm first observes children's play in Sheffield.","C":"Maximising output to reduce unit costs is a production goal. Cresswell begins with customer observation rather than with volume targets. The scenario for Cresswell Toys Ltd instead describes Identifying customer needs before designing the product, which rules this alternative out.","D":"Copying rivals exactly would not require watching children play. The scenario describes original design based on observed customer needs. In Cresswell Toys Ltd's case, the correct description is Identifying customer needs before designing the product, not this choice."}}},{"id":"P1_U3_MCQ_1557","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1557","question":"Dornley Optics Ltd in Zurich, Switzerland sold 6,000 spectacle lenses in 2026. Total lens sales across the Swiss market were 50,000 units that year. What market share did Dornley achieve?","options":{"A":"20%","B":"12%","C":"1.2%","D":"83.3%"},"correctOption":"B","correctAnswer":"12%","questionType":"MCQ","explanation":{"correct_reason":"Market share is the company's sales divided by total market sales, times 100. Dornley sold 6,000 of 50,000 lenses, so 6,000 divided by 50,000 times 100 equals 12%.","distractor_reasons":{"A":"20% comes from dividing 50,000 by 6,000 and inverting the fraction; the correct calculation puts Dornley's sales over total market sales.","B":"Market share is the company's sales divided by total market sales, times 100. Dornley sold 6,000 of 50,000 lenses, so 6,000 divided by 50,000 times 100 equals 12%.","C":"1.2% results from forgetting to multiply by 100. Converting the decimal 0.12 into a percentage gives the true 12% share in Switzerland.","D":"83.3% would imply Dornley sold five sixths of all lenses in Switzerland, whereas 6,000 out of 50,000 is only 12%. Dornley Optics Ltd's circumstances match 12%, so this option does not fit."}}},{"id":"P1_U3_MCQ_1558","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1558","question":"Ellesmere Hotels Ltd in Vienna, Austria analyses its own booking records from the past year to find out which room types are most popular. What kind of data is this?","options":{"A":"Internal secondary data collected for routine bookings.","B":"External secondary data from government reports.","C":"Primary data from a brand-new guest survey.","D":"Qualitative data from guest interviews."},"correctOption":"A","correctAnswer":"Internal secondary data collected for routine bookings.","questionType":"MCQ","explanation":{"correct_reason":"The booking records were created for everyday reservations, not for this study, so Ellesmere Hotels is using internal secondary data that already exists within the business.","distractor_reasons":{"A":"The booking records were created for everyday reservations, not for this study, so Ellesmere Hotels is using internal secondary data that already exists within the business.","B":"External secondary data come from outside organisations such as governments. These records belong to Ellesmere Hotels itself, so they are internal data.","C":"Primary data would require a new survey of guests. The hotel is re-analysing records that were already collected for normal operations in Vienna.","D":"Qualitative data are words and opinions. Booking records are numerical counts of room types, so they are not qualitative interview material."}}},{"id":"P1_U3_MCQ_1559","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1559","question":"Framlington Coffee Ltd in Kigali, Rwanda sells its roasted coffee exclusively through one national supermarket chain rather than through independent shops. Which element of the marketing mix is this decision about?","options":{"A":"Product","B":"Place","C":"Price","D":"Promotion"},"correctOption":"B","correctAnswer":"Place","questionType":"MCQ","explanation":{"correct_reason":"Deciding which retail chain stocks the coffee is a distribution choice, so it belongs to place, the marketing mix element that gets products to the final customer.","distractor_reasons":{"A":"Product concerns the coffee's blend, roast and packaging. Choosing a supermarket chain does not change the coffee itself in Kigali. In Framlington Coffee Ltd's case, the correct description is Place, not this choice.","B":"Deciding which retail chain stocks the coffee is a distribution choice, so it belongs to place, the marketing mix element that gets products to the final customer.","C":"Price is the amount the customer pays. The scenario gives no price information and focuses on where the coffee is available to shoppers.","D":"Promotion communicates the product's benefits. Securing a supermarket stockist is a channel decision rather than an advertising message. For Framlington Coffee Ltd, the facts point to Place, so this option cannot be correct."}}},{"id":"P1_U3_MCQ_1560","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1560","question":"Harrowvale Foods Ltd in Bristol, United Kingdom originally sold a health drink as an expensive premium product and now relaunches it as an affordable everyday drink for families. What marketing strategy is this?","options":{"A":"Repositioning the product to appeal to a different market segment.","B":"Increasing the price to reinforce a premium image.","C":"Withdrawing the product from the market entirely.","D":"Changing the legal ownership of the company."},"correctOption":"A","correctAnswer":"Repositioning the product to appeal to a different market segment.","questionType":"MCQ","explanation":{"correct_reason":"Changing the drink's image and price from premium to everyday family use is repositioning, designed to shift the product toward a broader segment of buyers in Bristol.","distractor_reasons":{"A":"Changing the drink's image and price from premium to everyday family use is repositioning, designed to shift the product toward a broader segment of buyers in Bristol.","B":"The firm is lowering the price to reach families, not raising it to reinforce a premium image for the drink. For Harrowvale Foods Ltd, the facts point to Repositioning the product to appeal to a different market segment, so this option cannot be correct.","C":"The product is being relaunched rather than withdrawn. Harrowvale Foods continues to sell the drink to a new group of customers.","D":"Repositioning changes how customers see the product, not the legal ownership or structure of Harrowvale Foods Ltd. In Harrowvale Foods Ltd's case, the correct description is Repositioning the product to appeal to a different market segment, not this choice."}}},{"id":"P1_U3_MCQ_1561","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1561","question":"Ivydene Motors Ltd in Turin, Italy sold 9,000 cars in 2026 and calculates this was 15% of the total Italian market. What was the size of that market in units?","options":{"A":"45,000 cars","B":"135,000 cars","C":"60,000 cars","D":"6,000 cars"},"correctOption":"C","correctAnswer":"60,000 cars","questionType":"MCQ","explanation":{"correct_reason":"If 9,000 cars represent 15% of the market, the total is 9,000 divided by 0.15, which equals 60,000 cars sold across Italy in 2026.","distractor_reasons":{"A":"45,000 comes from subtracting 15% of 9,000 from 9,000. To find the whole market, the known share of 9,000 cars must be divided by 0.15.","B":"135,000 would result from multiplying 9,000 by fifteen, treating the 15% share as fifteen times the firm's sales rather than a fraction of the market.","C":"If 9,000 cars represent 15% of the market, the total is 9,000 divided by 0.15, which equals 60,000 cars sold across Italy in 2026.","D":"6,000 is 15% of 9,000 rather than the total market. The 9,000 cars already represent the known 15% slice of Italian sales."}}},{"id":"P1_U3_MCQ_1562","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1562","question":"Jarrowvale Foods Ltd in Minneapolis, United States wants to check how a new snack sells in real conditions before a national launch, so it sells it in two representative cities. What is this?","options":{"A":"A census of every household in the country.","B":"A focus group of twelve consumers.","C":"A postal survey sent to 3,000 homes.","D":"Test marketing in two representative cities."},"correctOption":"D","correctAnswer":"Test marketing in two representative cities.","questionType":"MCQ","explanation":{"correct_reason":"Launching the snack on a limited scale in two cities to observe real purchasing before a national rollout is test marketing, reducing the risk of a full launch.","distractor_reasons":{"A":"A census would survey every household in the country and would be enormously expensive; it would not show actual purchasing behaviour for the new snack.","B":"A focus group of twelve gives opinions before launch but cannot show how the snack performs in real stores over several weeks.","C":"A postal survey asks about intended purchases rather than observed sales in shops, so it cannot test real market performance in Minneapolis.","D":"Launching the snack on a limited scale in two cities to observe real purchasing before a national rollout is test marketing, reducing the risk of a full launch."}}},{"id":"P1_U3_MCQ_1563","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1563","question":"Kelso Retail Ltd in Nagasaki, Japan prices a kitchen appliance at $9.99 rather than $10.00 because customers perceive it as much cheaper. Which pricing strategy is this?","options":{"A":"Cost-plus pricing, adding a mark-up.","B":"Penetration pricing, setting a low price.","C":"Psychological pricing, using just-below-round figures.","D":"Premium pricing, signalling luxury through price."},"correctOption":"C","correctAnswer":"Psychological pricing, using just-below-round figures.","questionType":"MCQ","explanation":{"correct_reason":"Setting a price just below a round number to influence perception is psychological pricing, used by Kelso Retail to make the $9.99 appliance seem much cheaper than $10.00.","distractor_reasons":{"A":"Cost-plus pricing sets a price from unit cost plus a mark-up. The $9.99 figure is chosen for its effect on buyers, not from a cost calculation.","B":"Penetration pricing uses a low price to win market share. A one-cent difference from $10 is not a serious attempt to undercut rivals in Nagasaki.","C":"Setting a price just below a round number to influence perception is psychological pricing, used by Kelso Retail to make the $9.99 appliance seem much cheaper than $10.00.","D":"Premium pricing charges a high price to signal quality. Pricing at $9.99 signals affordability, not exclusivity or luxury. For Kelso Retail Ltd, the facts point to Psychological pricing, using just-below-round figures, so this option cannot be correct."}}},{"id":"P1_U3_MCQ_1564","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1564","question":"Larchfield Apparel Ltd in Dhaka, Bangladesh produces one standard T-shirt in bulk and sells it to all kinds of customers at a low price. Which market strategy is the firm using?","options":{"A":"Niche marketing, serving a narrow customer group.","B":"Differentiation, offering unique product features.","C":"Premium positioning, charging high prices.","D":"Mass marketing, using one standard product for all buyers."},"correctOption":"D","correctAnswer":"Mass marketing, using one standard product for all buyers.","questionType":"MCQ","explanation":{"correct_reason":"Offering one standard T-shirt to the whole market without tailoring to segments is mass marketing, relying on high volume and low prices for buyers in Dhaka.","distractor_reasons":{"A":"Niche marketing would target a narrow specialist group. Larchfield sells the same T-shirt to everyone rather than focusing on one defined segment.","B":"Differentiation means unique features that set a product apart. A standard T-shirt has no distinguishing features described in the scenario. The details given about Larchfield Apparel Ltd support Mass marketing, using one standard product for all buyers, so this answer is unsuitable.","C":"Premium positioning charges a high price to signal quality, whereas Larchfield sells its T-shirts at a low price to a broad mass market.","D":"Offering one standard T-shirt to the whole market without tailoring to segments is mass marketing, relying on high volume and low prices for buyers in Dhaka."}}},{"id":"P1_U3_MCQ_1565","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1565","question":"Marrowick Tickets Ltd in Glasgow, United Kingdom sold 22,500 theatre tickets in 2026. Total theatre ticket sales in the city were 90,000 that year. What was Marrowick's market share?","options":{"A":"4%","B":"2.5%","C":"25%","D":"250%"},"correctOption":"C","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"Market share equals the firm's sales divided by total market sales, times 100. Marrowick sold 22,500 of 90,000 tickets, so 22,500 divided by 90,000 times 100 is 25%.","distractor_reasons":{"A":"4% comes from dividing 90,000 by 22,500 and inverting the fraction; the correct ratio puts Marrowick's own ticket sales over the whole market.","B":"2.5% results from forgetting to multiply the decimal 0.25 by 100, which would convert it into the correct percentage share in Glasgow.","C":"Market share equals the firm's sales divided by total market sales, times 100. Marrowick sold 22,500 of 90,000 tickets, so 22,500 divided by 90,000 times 100 is 25%.","D":"250% would be impossible for one firm's share of a market it belongs to; 22,500 out of 90,000 theatre tickets is only 25%."}}},{"id":"P1_U3_MCQ_1566","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1566","question":"Northend Cafes Ltd in Lyon, France observes how long queues form at lunchtime rather than asking customers about their habits. What is the main advantage of this observational research?","options":{"A":"It is always cheaper than every other research method.","B":"It provides detailed explanations of customer motives.","C":"It guarantees a representative sample of all customers.","D":"It records actual behaviour in a natural setting."},"correctOption":"D","correctAnswer":"It records actual behaviour in a natural setting.","questionType":"MCQ","explanation":{"correct_reason":"Observation captures what people actually do in a natural setting, so Northend Cafes sees real queuing behaviour at its Lyon outlets rather than relying on reported habits.","distractor_reasons":{"A":"Observation is not always cheaper; training observers and recording behaviour across many days can cost more than a simple questionnaire. For Northend Cafes Ltd, the facts point to It records actual behaviour in a natural setting, so this option cannot be correct.","B":"Observation shows what happens but not why. It cannot provide detailed explanations of motives without asking customers direct questions. The scenario for Northend Cafes Ltd instead describes It records actual behaviour in a natural setting, which rules this alternative out.","C":"Observation does not guarantee representativeness; watching only one branch at one time may give a misleading picture of all customers. In Northend Cafes Ltd's case, the correct description is It records actual behaviour in a natural setting, not this choice.","D":"Observation captures what people actually do in a natural setting, so Northend Cafes sees real queuing behaviour at its Lyon outlets rather than relying on reported habits."}}},{"id":"P1_U3_MCQ_1567","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1567","question":"Orchardvale Winery Ltd in Stellenbosch, South Africa sponsors a local arts festival and issues press releases about its support for the arts. Which form of promotion is this?","options":{"A":"Advertising","B":"Personal selling","C":"Public relations","D":"Sales promotion"},"correctOption":"C","correctAnswer":"Public relations","questionType":"MCQ","explanation":{"correct_reason":"Sponsorship and press coverage designed to build a favourable public image are public relations, used by Orchardvale Winery to strengthen its local reputation.","distractor_reasons":{"A":"Advertising involves paid messages in media. Sponsoring a festival and gaining press coverage rely on publicity rather than buying advertising space.","B":"Personal selling is face-to-face selling to individual buyers. Sponsoring a community festival is not a one-to-one sales conversation with customers. In Orchardvale Winery Ltd's case, the correct description is Public relations, not this choice.","C":"Sponsorship and press coverage designed to build a favourable public image are public relations, used by Orchardvale Winery to strengthen its local reputation.","D":"Sales promotion offers short-term incentives such as discounts. The winery's sponsorship aims at long-term goodwill rather than an immediate sales incentive."}}},{"id":"P1_U3_MCQ_1568","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1568","question":"Pennard Meals Ltd in Singapore faces a rival's price cut. Instead of lowering its own price, it starts offering free delivery to customers. What strategy is this?","options":{"A":"Price matching, copying the rival's price cut.","B":"Cost leadership, becoming the cheapest producer.","C":"Withdrawing from the market completely.","D":"Non-price competition through an added service."},"correctOption":"D","correctAnswer":"Non-price competition through an added service.","questionType":"MCQ","explanation":{"correct_reason":"Adding free delivery rather than cutting price is non-price competition, through which Pennard Meals tries to make its service more attractive than the rival's cheaper offer.","distractor_reasons":{"A":"Pennard Meals is not matching the rival's lower price; it is adding a service instead, so price matching does not describe its response.","B":"Cost leadership means achieving the lowest costs and prices. Offering free delivery adds a cost rather than reducing prices for customers in Singapore.","C":"The company is responding with a new service, not leaving the market. Withdrawal would mean ceasing to sell meals altogether. The details given about Pennard Meals Ltd support Non-price competition through an added service, so this answer is unsuitable.","D":"Adding free delivery rather than cutting price is non-price competition, through which Pennard Meals tries to make its service more attractive than the rival's cheaper offer."}}},{"id":"P1_U3_MCQ_1569","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1569","question":"Quillwater Dairy Ltd in Harare, Zimbabwe sells 27,000 litres of milk a month. The total monthly milk market in Harare is 300,000 litres. What share of the market does Quillwater hold?","options":{"A":"3%","B":"11.1%","C":"9%","D":"90%"},"correctOption":"C","correctAnswer":"9%","questionType":"MCQ","explanation":{"correct_reason":"Market share is the firm's sales divided by total market sales, times 100. Quillwater sells 27,000 of 300,000 litres, so 27,000 divided by 300,000 times 100 equals 9%.","distractor_reasons":{"A":"3% would come from dividing 300,000 by 27,000 and inverting; the correct fraction is Quillwater's own sales over the whole Harare market.","B":"11.1% reverses the ratio by dividing 300,000 litres by 27,000 litres instead of comparing the firm's output with the total market.","C":"Market share is the firm's sales divided by total market sales, times 100. Quillwater sells 27,000 of 300,000 litres, so 27,000 divided by 300,000 times 100 equals 9%.","D":"90% treats 27,000 litres as nine tenths of the market, whereas in fact it is only 9% of the 300,000 litres sold monthly."}}},{"id":"P1_U3_MCQ_1570","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1570","question":"Redmere Research Ltd in Santiago, Chile needs to count how many shoppers prefer each of five cereal brands. Which question format will make the results easiest to analyse?","options":{"A":"Open questions, because they allow unlimited detail.","B":"Focus groups, because they produce numerical data.","C":"Observation, because it records opinions directly.","D":"Closed questions, because answers are easy to count and compare."},"correctOption":"D","correctAnswer":"Closed questions, because answers are easy to count and compare.","questionType":"MCQ","explanation":{"correct_reason":"Closed questions give preset choices that can be tallied quickly, so Redmere can count preferences for the five cereal brands and compare them numerically.","distractor_reasons":{"A":"Open questions produce varied written answers that are hard to count, so they would not help Redmere compare five cereal brands numerically.","B":"Focus groups generate detailed discussion but with tiny samples, not the numerical counts of brand preferences needed across Santiago shoppers. The scenario for Redmere Research Ltd instead describes Closed questions, because answers are easy to count and compare, which rules this alternative out.","C":"Observation records behaviour, not stated brand preferences, and cannot show which of the five cereals shoppers say they prefer. In Redmere Research Ltd's case, the correct description is Closed questions, because answers are easy to count and compare, not this choice.","D":"Closed questions give preset choices that can be tallied quickly, so Redmere can count preferences for the five cereal brands and compare them numerically."}}},{"id":"P1_U3_MCQ_1571","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1571","question":"Saltwick Hotels Ltd in Phuket, Thailand charges much lower room rates in the rainy season when demand is weak, and higher rates in peak season. What pricing approach is this?","options":{"A":"Cost-plus pricing, adding a mark-up to cost.","B":"Price skimming, charging a high launch price.","C":"Demand-based pricing, varying price with the season.","D":"Loss leader pricing, selling below cost."},"correctOption":"C","correctAnswer":"Demand-based pricing, varying price with the season.","questionType":"MCQ","explanation":{"correct_reason":"Changing room rates according to the level of demand at different times of year is demand-based pricing, used by Saltwick Hotels to fill rooms in the quiet season.","distractor_reasons":{"A":"Cost-plus pricing sets a price from costs plus a mark-up. Saltwick's rates change with demand rather than with any stated cost figure.","B":"Price skimming sets a high launch price for a new product. Seasonal room rates are not a launch strategy for a hotel in Phuket.","C":"Changing room rates according to the level of demand at different times of year is demand-based pricing, used by Saltwick Hotels to fill rooms in the quiet season.","D":"Loss leader pricing sells below cost to attract buyers. Lower rainy-season rates are a demand-based adjustment, not necessarily priced below cost."}}},{"id":"P1_U3_MCQ_1572","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1572","question":"Tarnwood Publishing Ltd in Ottawa, Canada asked readers which features they wanted before launching a magazine, rather than relying on editors' instincts. Which orientation does this show?","options":{"A":"A production orientation, focused on maximising output.","B":"A product orientation, relying on editorial instinct.","C":"A sales orientation, pushing a fixed product.","D":"A market orientation, building the product around reader research."},"correctOption":"D","correctAnswer":"A market orientation, building the product around reader research.","questionType":"MCQ","explanation":{"correct_reason":"Tarnwood based the magazine's content on research into what readers actually want, which demonstrates a market orientation built around customer needs in Ottawa.","distractor_reasons":{"A":"A production orientation concentrates on efficient output and low costs. Tarnwood's decisions came from reader research, not from volume goals. In Tarnwood Publishing Ltd's case, the correct description is A market orientation, building the product around reader research, not this choice.","B":"A product orientation relies on the firm's own ideas about the product. Here editors set aside their instincts in favour of evidence from readers.","C":"A sales orientation pushes an existing product with promotions. Tarnwood designed the magazine around customer preferences before its launch. The details given about Tarnwood Publishing Ltd support A market orientation, building the product around reader research, so this answer is unsuitable.","D":"Tarnwood based the magazine's content on research into what readers actually want, which demonstrates a market orientation built around customer needs in Ottawa."}}},{"id":"P1_U3_MCQ_1573","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1573","question":"Umberly Foods Ltd in Dakar, Senegal estimates its local soup market grew from $5 million in 2025 to $5.4 million in 2026. What was the percentage growth of the market?","options":{"A":"4%","B":"108%","C":"8%","D":"0.8%"},"correctOption":"C","correctAnswer":"8%","questionType":"MCQ","explanation":{"correct_reason":"Growth equals the increase divided by the starting value. The soup market added $0.4 million on a base of $5 million, so 0.4 divided by 5 times 100 gives 8%.","distractor_reasons":{"A":"4% comes from treating the $0.4 million increase as a percentage directly without dividing by the original $5 million market size.","B":"108% describes the new market as a share of the old, not the growth, which is only the extra 8% above the original $5 million.","C":"Growth equals the increase divided by the starting value. The soup market added $0.4 million on a base of $5 million, so 0.4 divided by 5 times 100 gives 8%.","D":"0.8% results from misplacing the decimal point when converting the $0.4 million rise into a percentage of the $5 million market in Dakar."}}},{"id":"P1_U3_MCQ_1574","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1574","question":"Vellwick Research Ltd in Limerick, Ireland tests a draft questionnaire on 30 people before mailing it to 5,000 households. What is the main purpose of this pilot test?","options":{"A":"To guarantee that every respondent answers honestly.","B":"To calculate the exact market share of the product.","C":"To remove the need to sample the wider population.","D":"To identify ambiguous wording before the full survey."},"correctOption":"D","correctAnswer":"To identify ambiguous wording before the full survey.","questionType":"MCQ","explanation":{"correct_reason":"A pilot on 30 people reveals unclear or leading wording and layout faults, so Vellwick can fix the questionnaire before spending money on the full 5,000-household survey.","distractor_reasons":{"A":"A pilot can improve wording but cannot guarantee that respondents in the main survey will answer honestly or complete every item.","B":"Thirty pilot respondents cannot establish market share, which depends on actual sales compared with total market sales after the launch. For Vellwick Research Ltd, the facts point to To identify ambiguous wording before the full survey, so this option cannot be correct.","C":"The pilot is itself a small sample and does not remove the need to sample the wider population in the main survey across Limerick.","D":"A pilot on 30 people reveals unclear or leading wording and layout faults, so Vellwick can fix the questionnaire before spending money on the full 5,000-household survey."}}},{"id":"P1_U3_MCQ_1575","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1575","question":"Wexham Toiletries Ltd in Leeds, United Kingdom offers five different shampoo variants, each aimed at a different hair type, under the same company name. What does this illustrate?","options":{"A":"A narrow product line with just one item.","B":"A private labelling arrangement.","C":"A broad product mix of related items.","D":"A loss leader pricing strategy."},"correctOption":"C","correctAnswer":"A broad product mix of related items.","questionType":"MCQ","explanation":{"correct_reason":"Offering several related shampoo variants is a broad product mix, allowing Wexham Toiletries to serve different hair types while sharing one company reputation in Leeds.","distractor_reasons":{"A":"A narrow product line with one item would be the opposite; Wexham offers five distinct shampoo variants for different hair types.","B":"Private labelling means producing goods for a retailer's own brand. These shampoos are sold under Wexham's company name in Leeds. The scenario for Wexham Toiletries Ltd instead describes A broad product mix of related items, which rules this alternative out.","C":"Offering several related shampoo variants is a broad product mix, allowing Wexham Toiletries to serve different hair types while sharing one company reputation in Leeds.","D":"A loss leader is priced below cost to attract customers. The scenario describes a range of shampoos and says nothing about below-cost pricing."}}},{"id":"P1_U3_MCQ_1576","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1576","question":"Xerona Electronics Ltd in Shenzhen, China enjoys strong brand loyalty, with many customers buying its accessories again rather than switching to rivals. What advantage does this bring?","options":{"A":"It removes all competition from the market.","B":"It guarantees the lowest production costs.","C":"It eliminates the need for any product development.","D":"It gives more predictable repeat sales and can reduce promotion costs."},"correctOption":"D","correctAnswer":"It gives more predictable repeat sales and can reduce promotion costs.","questionType":"MCQ","explanation":{"correct_reason":"Loyal customers generate more predictable repeat sales and need less persuasion, so Xerona can spend less on attracting new buyers in a competitive Shenzhen market.","distractor_reasons":{"A":"Brand loyalty does not remove competitors; rival firms can still attract Xerona's customers with new products or better offers. The scenario for Xerona Electronics Ltd instead describes It gives more predictable repeat sales and can reduce promotion costs, which rules this alternative out.","B":"Loyalty affects demand, not the cost of production. Xerona's manufacturing costs depend on inputs and processes, not on customer devotion. In Xerona Electronics Ltd's case, the correct description is It gives more predictable repeat sales and can reduce promotion costs, not this choice.","C":"Loyal customers still expect improved products, so Xerona cannot stop developing new accessories simply because its buyers are faithful. Xerona Electronics Ltd's circumstances match It gives more predictable repeat sales and can reduce promotion costs, so this option does not fit.","D":"Loyal customers generate more predictable repeat sales and need less persuasion, so Xerona can spend less on attracting new buyers in a competitive Shenzhen market."}}},{"id":"P1_U3_MCQ_1577","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1577","question":"Yarwell Motors Ltd in Chennai, India increased its share of the local scooter market from 18% in 2025 to 24% in 2026. By how many percentage points did its share rise?","options":{"A":"6%","B":"33 percentage points","C":"6 percentage points","D":"42 percentage points"},"correctOption":"C","correctAnswer":"6 percentage points","questionType":"MCQ","explanation":{"correct_reason":"The rise in share is the later figure minus the earlier one. Twenty-four percent minus 18% equals an increase of 6 percentage points for Yarwell Motors.","distractor_reasons":{"A":"6% is a relative percentage change, but the question asks for percentage points, the simple difference between 24% and 18%. In Yarwell Motors Ltd's case, the correct description is 6 percentage points, not this choice.","B":"33 would be the relative increase, found from 6 divided by 18, but that is a percentage change, not the difference in percentage points.","C":"The rise in share is the later figure minus the earlier one. Twenty-four percent minus 18% equals an increase of 6 percentage points for Yarwell Motors.","D":"42 percentage points adds the two shares together. The increase is the gap between them, which is 6 percentage points, not their sum."}}},{"id":"P1_U3_MCQ_1578","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1578","question":"Zelwick Clothing Ltd in Brno, Czech Republic interviews 15 customers individually about their clothing shopping habits and preferences. What is the main benefit of using interviews here?","options":{"A":"They produce large amounts of easily counted numerical data.","B":"They are the cheapest way to survey thousands of people.","C":"They guarantee a representative sample of the whole population.","D":"They allow the interviewer to probe answers and ask follow-up questions."},"correctOption":"D","correctAnswer":"They allow the interviewer to probe answers and ask follow-up questions.","questionType":"MCQ","explanation":{"correct_reason":"Face-to-face interviews let the researcher probe interesting answers and ask follow-up questions, giving Zelwick Clothing richer detail from its 15 customers.","distractor_reasons":{"A":"Interviews usually yield qualitative detail rather than large amounts of numerical data that can be tallied easily by the company. Zelwick Clothing Ltd's circumstances match They allow the interviewer to probe answers and ask follow-up questions, so this option does not fit.","B":"Interviewing thousands of people would be costly and slow; 15 individual interviews are chosen for depth, not for cheap mass coverage.","C":"A small group of 15 cannot guarantee representativeness; interviews are valued for depth rather than statistical representativeness. For Zelwick Clothing Ltd, the facts point to They allow the interviewer to probe answers and ask follow-up questions, so this option cannot be correct.","D":"Face-to-face interviews let the researcher probe interesting answers and ask follow-up questions, giving Zelwick Clothing richer detail from its 15 customers."}}},{"id":"P1_U3_MCQ_1579","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1579","question":"Ashgrove Bakeries Ltd in Mombasa, Kenya chooses a new outlet site next to a busy railway station to catch commuters. Which element of the marketing mix does this location decision represent?","options":{"A":"Product","B":"Price","C":"Place","D":"Promotion"},"correctOption":"C","correctAnswer":"Place","questionType":"MCQ","explanation":{"correct_reason":"Location is part of place, the marketing mix element concerned with making the product available where customers can conveniently buy it, here at Mombasa station.","distractor_reasons":{"A":"Product concerns the bread's recipe and packaging. Choosing a site beside a railway station does not change Ashgrove's bakery products. The details given about Ashgrove Bakeries Ltd support Place, so this answer is unsuitable.","B":"Price is what customers pay. The scenario mentions no price change, only the physical location of the new Mombasa outlet. For Ashgrove Bakeries Ltd, the facts point to Place, so this option cannot be correct.","C":"Location is part of place, the marketing mix element concerned with making the product available where customers can conveniently buy it, here at Mombasa station.","D":"Promotion communicates with buyers. Selecting a site near commuters is a distribution decision rather than an advertising message. In Ashgrove Bakeries Ltd's case, the correct description is Place, not this choice."}}},{"id":"P1_U3_MCQ_1580","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1580","question":"Bramhall Sauces Ltd in Kingston, Jamaica copies the packaging and prices of the best-selling sauce brand rather than trying to overtake it. What market role is Bramhall playing?","options":{"A":"Market leader, setting the pace for other firms.","B":"Market nicher, serving one narrow customer group.","C":"Market challenger, attacking the leader directly.","D":"Market follower, imitating the leading firm."},"correctOption":"D","correctAnswer":"Market follower, imitating the leading firm.","questionType":"MCQ","explanation":{"correct_reason":"A firm that imitates the leading brand's packaging and prices instead of challenging it is acting as a market follower in the Jamaican sauce market.","distractor_reasons":{"A":"A market leader has the largest share and sets the pace. Bramhall copies another brand rather than leading the market in Kingston.","B":"A market nicher serves a narrow specialist group. Bramhall is imitating the broad-market leader, not focusing on a niche segment. In Bramhall Sauces Ltd's case, the correct description is Market follower, imitating the leading firm, not this choice.","C":"A market challenger attacks the leader with aggressive pricing or innovation. Bramhall follows the leader's choices instead of attacking them. Bramhall Sauces Ltd's circumstances match Market follower, imitating the leading firm, so this option does not fit.","D":"A firm that imitates the leading brand's packaging and prices instead of challenging it is acting as a market follower in the Jamaican sauce market."}}},{"id":"P1_U3_MCQ_1581","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1581","question":"Corwyn Foods Ltd in Rio de Janeiro, Brazil sold 18,000 packets of cheese bread in 2026 out of a city market of 80,000 packets. What was the company's market share?","options":{"A":"12.5%","B":"22.5%","C":"2.25%","D":"80%"},"correctOption":"B","correctAnswer":"22.5%","questionType":"MCQ","explanation":{"correct_reason":"Market share equals the firm's sales divided by total market sales, times 100. Corwyn sold 18,000 of 80,000 packets, so 18,000 divided by 80,000 times 100 equals 22.5%.","distractor_reasons":{"A":"12.5% would require Corwyn to sell 10,000 of the 80,000 packets. The stated 18,000 packets give a market share of 22.5%.","B":"Market share equals the firm's sales divided by total market sales, times 100. Corwyn sold 18,000 of 80,000 packets, so 18,000 divided by 80,000 times 100 equals 22.5%.","C":"2.25% comes from misplacing the decimal point when converting 18,000 out of 80,000 into a percentage share of the Rio market.","D":"80% mistakenly uses the market total as though it were the firm's share; the correct comparison is 18,000 divided by 80,000 packets."}}},{"id":"P1_U3_MCQ_1582","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1582","question":"Dorneval Research Ltd in Porto, Portugal tried a draft survey on 25 people and found that one question was confusing. What was the main purpose of this trial?","options":{"A":"To detect confusing wording before the main survey.","B":"To prove that every respondent will tell the truth.","C":"To calculate the exact market share of the product.","D":"To remove the need for sampling altogether."},"correctOption":"A","correctAnswer":"To detect confusing wording before the main survey.","questionType":"MCQ","explanation":{"correct_reason":"Testing on 25 people exposed a confusing item so Dorneval could rewrite it before the main survey, avoiding wasted responses and misleading data from Porto shoppers.","distractor_reasons":{"A":"Testing on 25 people exposed a confusing item so Dorneval could rewrite it before the main survey, avoiding wasted responses and misleading data from Porto shoppers.","B":"A small trial cannot guarantee truthful answers in the main survey; honesty depends on respondents and question design, not on running a pilot.","C":"Twenty-five trial respondents cannot calculate market share, which requires sales data compared with total sales in the whole market. For Dorneval Research Ltd, the facts point to To detect confusing wording before the main survey, so this option cannot be correct.","D":"The trial is itself a small sample and does not remove the need to sample the target population in the full survey."}}},{"id":"P1_U3_MCQ_1583","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1583","question":"Eldonvale Lighting Ltd in Amsterdam, Netherlands makes a pendant lamp for a unit cost of $40 and adds a 30% mark-up. What selling price should the company charge?","options":{"A":"$12","B":"$52","C":"$70","D":"$40.30"},"correctOption":"B","correctAnswer":"$52","questionType":"MCQ","explanation":{"correct_reason":"A 30% mark-up on the $40 unit cost adds $12. Adding this amount to $40 gives a selling price of $52 for each pendant lamp made by Eldonvale Lighting.","distractor_reasons":{"A":"$12 is only the mark-up amount. The selling price must also cover the original $40 unit cost, so it cannot be just the addition.","B":"A 30% mark-up on the $40 unit cost adds $12. Adding this amount to $40 gives a selling price of $52 for each pendant lamp made by Eldonvale Lighting.","C":"$70 would require adding $30 to the $40 cost, representing a 75% mark-up rather than the 30% stated in the question.","D":"$40.30 adds only $0.30, as though the mark-up were less than 1%, not the 30% that Eldonvale applies in Amsterdam. In Eldonvale Lighting Ltd's case, the correct description is $52, not this choice."}}},{"id":"P1_U3_MCQ_1584","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1584","question":"Falton Hotels Ltd in Nice, France divides guests into couples, families and business travellers, then creates tailored packages for each group. What is the main benefit of this segmentation?","options":{"A":"Offers can be designed to match each group's particular needs.","B":"The firm no longer needs to advertise its rooms.","C":"It guarantees a legal monopoly in Nice.","D":"It removes all competitors from the market."},"correctOption":"A","correctAnswer":"Offers can be designed to match each group's particular needs.","questionType":"MCQ","explanation":{"correct_reason":"Segmenting lets Falton Hotels design packages that match the particular needs of couples, families and business guests, making each offer more appealing than a single generic package.","distractor_reasons":{"A":"Segmenting lets Falton Hotels design packages that match the particular needs of couples, families and business guests, making each offer more appealing than a single generic package.","B":"Segmentation does not remove the need to advertise; Falton must still promote its tailored packages to each group of guests in Nice.","C":"Segmentation cannot create a legal monopoly. Other hotels in Nice are free to target couples, families and business travellers too. In Falton Hotels Ltd's case, the correct description is Offers can be designed to match each group's particular needs, not this choice.","D":"Competitors remain in the market. Segmentation helps Falton serve groups better but does not eliminate rival hotels in France. Falton Hotels Ltd's circumstances match Offers can be designed to match each group's particular needs, so this option does not fit."}}},{"id":"P1_U3_MCQ_1585","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1585","question":"Garrow Tickets Ltd in Dubai, United Arab Emirates estimates the local concert market grew from $8 million in 2025 to $8.4 million in 2026. What was the market's percentage growth?","options":{"A":"4%","B":"5%","C":"0.5%","D":"105%"},"correctOption":"B","correctAnswer":"5%","questionType":"MCQ","explanation":{"correct_reason":"Growth equals the increase divided by the original value. The concert market added $0.4 million on a base of $8 million, so 0.4 divided by 8 times 100 gives 5%.","distractor_reasons":{"A":"4% would use $10 million as the base rather than the actual starting market of $8 million in Dubai. The scenario for Garrow Tickets Ltd instead describes 5%, which rules this alternative out.","B":"Growth equals the increase divided by the original value. The concert market added $0.4 million on a base of $8 million, so 0.4 divided by 8 times 100 gives 5%.","C":"0.5% confuses the decimal 0.05 with a percentage. Multiplying by 100 converts the increase into the true 5% market growth. Garrow Tickets Ltd's circumstances match 5%, so this option does not fit.","D":"105% describes the new market relative to the old, not the growth, which is only the extra 5% above the original $8 million."}}},{"id":"P1_U3_MCQ_1586","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1586","question":"Harlton Research Ltd in Gothenburg, Sweden uses a published trade association report to estimate the size of the local coffee market. What kind of data is this?","options":{"A":"External secondary data published by another organisation.","B":"Internal secondary data from the firm's own records.","C":"Primary data collected directly from customers.","D":"Qualitative data from customer interviews."},"correctOption":"A","correctAnswer":"External secondary data published by another organisation.","questionType":"MCQ","explanation":{"correct_reason":"The report was produced by an outside trade association and already exists, so Harlton is using external secondary data rather than collecting new information itself.","distractor_reasons":{"A":"The report was produced by an outside trade association and already exists, so Harlton is using external secondary data rather than collecting new information itself.","B":"Internal secondary data come from within the firm's own records. A trade association report is produced outside Harlton Research in Gothenburg.","C":"Primary data would require Harlton to gather fresh evidence from Swedish consumers. The report was compiled by another body for its own purposes.","D":"Qualitative data are descriptive words and opinions. A market-size report contains published numerical estimates, not interview material. For Harlton Research Ltd, the facts point to External secondary data published by another organisation, so this option cannot be correct."}}},{"id":"P1_U3_MCQ_1587","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1587","question":"Inverton Motors Ltd in Detroit, United States pays for television and social media adverts to announce a new car model to millions of viewers. Which form of promotion is this?","options":{"A":"Public relations","B":"Advertising","C":"Personal selling","D":"Sales promotion"},"correctOption":"B","correctAnswer":"Advertising","questionType":"MCQ","explanation":{"correct_reason":"Paying for non-personal messages through mass media such as television and social platforms is advertising, used by Inverton Motors to reach a wide audience quickly.","distractor_reasons":{"A":"Public relations seeks favourable publicity without paying for media space. Inverton is buying advertising slots to announce its new car in Detroit.","B":"Paying for non-personal messages through mass media such as television and social platforms is advertising, used by Inverton Motors to reach a wide audience quickly.","C":"Personal selling involves face-to-face conversations with individual buyers. Televised adverts are a mass, non-personal form of communication. For Inverton Motors Ltd, the facts point to Advertising, so this option cannot be correct.","D":"Sales promotion offers short-term incentives such as discounts. Paying for adverts to build awareness is advertising, not an incentive scheme. The scenario for Inverton Motors Ltd instead describes Advertising, which rules this alternative out."}}},{"id":"P1_U3_MCQ_1588","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1588","question":"Juncroft Airlines Ltd in Kuching, Malaysia separates frequent flyers from occasional travellers when designing special seat offers and discounts. Which basis of market segmentation is this?","options":{"A":"Behavioural factors such as frequency of purchase.","B":"Demographic factors such as age and income.","C":"Geographic factors such as region or climate.","D":"Psychographic factors such as lifestyle and values."},"correctOption":"A","correctAnswer":"Behavioural factors such as frequency of purchase.","questionType":"MCQ","explanation":{"correct_reason":"Frequency of flying is a behavioural variable, so Juncroft Airlines is using behavioural segmentation rather than dividing customers by age, income or location.","distractor_reasons":{"A":"Frequency of flying is a behavioural variable, so Juncroft Airlines is using behavioural segmentation rather than dividing customers by age, income or location.","B":"Demographic segmentation uses age, income and family size. Juncroft is grouping passengers by how often they fly, which is a behavioural measure.","C":"Geographic segmentation divides customers by place or region. Both frequent and occasional flyers live in the same area around Kuching. The scenario for Juncroft Airlines Ltd instead describes Behavioural factors such as frequency of purchase, which rules this alternative out.","D":"Psychographic segmentation uses lifestyle and values. Flying frequency is an observable behaviour, not a personality or value category. In Juncroft Airlines Ltd's case, the correct description is Behavioural factors such as frequency of purchase, not this choice."}}},{"id":"P1_U3_MCQ_1589","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1589","question":"Kelvedon Foods Ltd in Nakuru, Kenya sold 12,600 jars of jam in 2026. Total jam sales in the local market were 42,000 jars. What market share did Kelvedon achieve?","options":{"A":"3%","B":"30%","C":"70%","D":"0.3%"},"correctOption":"B","correctAnswer":"30%","questionType":"MCQ","explanation":{"correct_reason":"Market share is the firm's sales divided by total market sales, times 100. Kelvedon sold 12,600 of 42,000 jars, so 12,600 divided by 42,000 times 100 equals 30%.","distractor_reasons":{"A":"3% comes from moving the decimal point too far when converting 12,600 out of 42,000 into a percentage share of the Nakuru market.","B":"Market share is the firm's sales divided by total market sales, times 100. Kelvedon sold 12,600 of 42,000 jars, so 12,600 divided by 42,000 times 100 equals 30%.","C":"70% would be the share if Kelvedon sold 29,400 jars. The actual 12,600 jars represent only 30% of total jam sales in Nakuru.","D":"0.3% results from forgetting to multiply the decimal 0.3 by 100, which would convert it into the correct 30% market share."}}},{"id":"P1_U3_MCQ_1590","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1590","question":"Loriston Tours Ltd in Ho Chi Minh City surveys 200 visitors at one busy market stall to measure citywide tourist satisfaction. What is the main weakness of this survey?","options":{"A":"The sample is biased toward visitors at one particular site.","B":"Primary data are always unreliable for tourism research.","C":"The sample size of 200 is too small to draw any conclusions.","D":"Questionnaires cannot be used to measure satisfaction."},"correctOption":"A","correctAnswer":"The sample is biased toward visitors at one particular site.","questionType":"MCQ","explanation":{"correct_reason":"Questioning only people at one market stall biases the sample toward visitors to that site, so it cannot represent all tourists across Ho Chi Minh City.","distractor_reasons":{"A":"Questioning only people at one market stall biases the sample toward visitors to that site, so it cannot represent all tourists across Ho Chi Minh City.","B":"Primary data are not automatically unreliable. The weakness is the location-based sampling, not the first-hand collection of responses. Loriston Tours Ltd's circumstances match The sample is biased toward visitors at one particular site, so this option does not fit.","C":"Two hundred responses are a reasonable size, but they are all drawn from one site; the problem is where they were collected, not how many.","D":"Questionnaires are commonly used to measure satisfaction. The issue is that this particular sample comes from only one location in the city."}}},{"id":"P1_U3_MCQ_1591","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1591","question":"Marlowe Cosmetics Ltd in Paris, France sells its products through home parties hosted by independent sellers rather than through retail shops. Which element of the marketing mix does this illustrate?","options":{"A":"Product","B":"Place","C":"Price","D":"Promotion"},"correctOption":"B","correctAnswer":"Place","questionType":"MCQ","explanation":{"correct_reason":"Selling through home parties is a choice of distribution channel, so it belongs to place, the marketing mix element concerned with reaching customers in Paris.","distractor_reasons":{"A":"Product concerns the cosmetics' formulation and packaging. Hosting home parties does not change the products themselves in Paris. Marlowe Cosmetics Ltd's circumstances match Place, so this option does not fit.","B":"Selling through home parties is a choice of distribution channel, so it belongs to place, the marketing mix element concerned with reaching customers in Paris.","C":"Price is the amount charged. The scenario gives no pricing details and focuses on how the cosmetics reach their buyers. For Marlowe Cosmetics Ltd, the facts point to Place, so this option cannot be correct.","D":"Promotion communicates benefits to customers. The home party is primarily a selling channel, making this a place decision rather than an advert."}}},{"id":"P1_U3_MCQ_1592","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1592","question":"Northgate Beverages Ltd in Belfast, United Kingdom is the second-largest drinks firm in its market and invests heavily in advertising to overtake the leader. What role is it playing?","options":{"A":"A market challenger trying to overtake the leader.","B":"A market leader with the biggest share.","C":"A market follower copying the leader's choices.","D":"A market nicher in a tiny specialist segment."},"correctOption":"A","correctAnswer":"A market challenger trying to overtake the leader.","questionType":"MCQ","explanation":{"correct_reason":"A firm that is not the leader but aggressively tries to gain share from it is a market challenger, which describes Northgate Beverages' strategy in Belfast.","distractor_reasons":{"A":"A firm that is not the leader but aggressively tries to gain share from it is a market challenger, which describes Northgate Beverages' strategy in Belfast.","B":"A market leader already holds the largest share. Northgate is second and is trying to displace the current leader in Belfast.","C":"A market follower imitates the leader rather than attacking it. Northgate is investing aggressively to take share from the leader. The scenario for Northgate Beverages Ltd instead describes A market challenger trying to overtake the leader, which rules this alternative out.","D":"A market nicher focuses on a narrow segment. Northgate is competing broadly across the Belfast drinks market, not in a tiny niche."}}},{"id":"P1_U3_MCQ_1593","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1593","question":"Ormiston Toys Ltd in Calgary, Canada increased its share of the local toy market from 5% in 2025 to 8% in 2026. By how many percentage points did its share rise?","options":{"A":"3%","B":"3 percentage points","C":"60 percentage points","D":"13 percentage points"},"correctOption":"B","correctAnswer":"3 percentage points","questionType":"MCQ","explanation":{"correct_reason":"The increase is the later share minus the earlier one. Eight percent minus 5% equals a rise of 3 percentage points for Ormiston Toys in Calgary.","distractor_reasons":{"A":"3% is a relative percentage change, but the question asks for percentage points, the straightforward difference between 8% and 5%. For Ormiston Toys Ltd, the facts point to 3 percentage points, so this option cannot be correct.","B":"The increase is the later share minus the earlier one. Eight percent minus 5% equals a rise of 3 percentage points for Ormiston Toys in Calgary.","C":"60 would be the relative increase, from 3 divided by 5, but that is a percentage change rather than a difference in percentage points.","D":"13 percentage points adds the two shares together. The rise is the gap between them, which is 3 percentage points, not their sum."}}},{"id":"P1_U3_MCQ_1594","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1594","question":"Penrose Tours Ltd in Venice, Italy uses published tourism statistics instead of commissioning a fresh survey. What is the main advantage of these secondary data?","options":{"A":"They are usually quicker and cheaper to obtain than new research.","B":"They are always perfectly suited to the firm's exact question.","C":"They are collected first-hand by the business itself.","D":"They are always more detailed than primary data."},"correctOption":"A","correctAnswer":"They are usually quicker and cheaper to obtain than new research.","questionType":"MCQ","explanation":{"correct_reason":"Secondary data such as published tourism statistics are already available, so Penrose Tours can obtain them quickly and cheaply without funding new research in Venice.","distractor_reasons":{"A":"Secondary data such as published tourism statistics are already available, so Penrose Tours can obtain them quickly and cheaply without funding new research in Venice.","B":"Secondary data were collected for other purposes and may not match the firm's exact question, so they are not always perfectly suited.","C":"Data collected first-hand by the business are primary data. Penrose is using statistics published by an outside body in Italy. Penrose Tours Ltd's circumstances match They are usually quicker and cheaper to obtain than new research, so this option does not fit.","D":"Secondary data are not always more detailed than primary data; a purpose-built survey can provide far more specific detail. The details given about Penrose Tours Ltd support They are usually quicker and cheaper to obtain than new research, so this answer is unsuitable."}}},{"id":"P1_U3_MCQ_1595","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1595","question":"Quillberry Coffee Ltd in Portland, United States raised the price of a latte from $4.00 to $4.40, and daily sales fell from 1,000 to 800 cups. What is the price elasticity of demand, as an absolute value?","options":{"A":"0.5","B":"2","C":"1","D":"10%"},"correctOption":"B","correctAnswer":"2","questionType":"MCQ","explanation":{"correct_reason":"Price rose from $4.00 to $4.40, a 10% increase, while quantity fell from 1,000 to 800, a 20% fall. Elasticity is 20 divided by 10, giving an absolute value of 2.","distractor_reasons":{"A":"0.5 reverses the ratio, dividing the 10% price change by the 20% quantity change. Elasticity puts the quantity change on top.","B":"Price rose from $4.00 to $4.40, a 10% increase, while quantity fell from 1,000 to 800, a 20% fall. Elasticity is 20 divided by 10, giving an absolute value of 2.","C":"1 would suggest unit elasticity, but sales fell by twice the percentage of the price rise, giving an absolute elasticity of 2.","D":"10% is only the price increase. Elasticity compares the 20% fall in quantity with that 10% price rise, producing the number 2."}}},{"id":"P1_U3_MCQ_1596","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1596","question":"Riponvale Furniture Ltd in Aarhus, Denmark lets customers choose the fabric and finish of made-to-order sofas, unlike rivals selling standard designs. What strategy is this?","options":{"A":"Differentiation by offering customised products.","B":"Cost leadership through standardisation.","C":"Withdrawal from the furniture market.","D":"Market follower imitating the leading brand."},"correctOption":"A","correctAnswer":"Differentiation by offering customised products.","questionType":"MCQ","explanation":{"correct_reason":"Offering customised fabric and finishes gives Riponvale Furniture a distinctive product that rivals do not match, which is a differentiation strategy in Aarhus.","distractor_reasons":{"A":"Offering customised fabric and finishes gives Riponvale Furniture a distinctive product that rivals do not match, which is a differentiation strategy in Aarhus.","B":"Cost leadership relies on standardised, high-volume production. Custom-made sofas with customer choices are the opposite of standardisation. The details given about Riponvale Furniture Ltd support Differentiation by offering customised products, so this answer is unsuitable.","C":"The company is actively selling made-to-order sofas, not leaving the market. Withdrawal would mean ceasing production entirely. For Riponvale Furniture Ltd, the facts point to Differentiation by offering customised products, so this option cannot be correct.","D":"A market follower copies the leading firm. Riponvale is creating a distinctive offer through customer choice, not imitating rivals in Denmark."}}},{"id":"P1_U3_MCQ_1597","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1597","question":"Taviston Foods Ltd in Seville, Spain sold 32,000 packs of olives in 2026. Total olive sales in the local market were 80,000 packs. What was Taviston's market share?","options":{"A":"4%","B":"40%","C":"25%","D":"80%"},"correctOption":"B","correctAnswer":"40%","questionType":"MCQ","explanation":{"correct_reason":"Market share is the firm's sales divided by total market sales, times 100. Taviston sold 32,000 of 80,000 packs, so 32,000 divided by 80,000 times 100 equals 40%.","distractor_reasons":{"A":"4% moves the decimal point one place too far when converting 32,000 out of 80,000 into a percentage share of the Seville market.","B":"Market share is the firm's sales divided by total market sales, times 100. Taviston sold 32,000 of 80,000 packs, so 32,000 divided by 80,000 times 100 equals 40%.","C":"25% would be the share if Taviston sold 20,000 packs. The actual figure of 32,000 out of 80,000 gives 40% in Seville.","D":"80% mistakenly uses the market total as the firm's share; 32,000 divided by 80,000 is 40% of the local Spanish market."}}},{"id":"P1_U3_MCQ_1598","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1598","question":"Umbray Research Ltd in Montevideo, Uruguay records shoppers' opinions in a city centre survey without telling them that a competitor funded the study. What ethical concern does this raise?","options":{"A":"Respondents should know who commissioned the study and how data will be used.","B":"Primary research can never be ethical in any circumstances.","C":"Anonymity is not important in market research.","D":"The sample must contain at least 1,000 people to be valid."},"correctOption":"A","correctAnswer":"Respondents should know who commissioned the study and how data will be used.","questionType":"MCQ","explanation":{"correct_reason":"Respondents should be told who commissioned the research and how their answers will be used, so hidden funding undermines informed consent and trust in Umbray's work.","distractor_reasons":{"A":"Respondents should be told who commissioned the research and how their answers will be used, so hidden funding undermines informed consent and trust in Umbray's work.","B":"Primary research can be entirely ethical when participants consent and are treated honestly, so it is not inherently wrong. The scenario for Umbray Research Ltd instead describes Respondents should know who commissioned the study and how data will be used, which rules this alternative out.","C":"Anonymity and confidentiality remain important in market research; revealing who funded a study does not remove the need to protect respondents.","D":"There is no fixed rule that a valid sample must contain 1,000 people. The issue here is disclosure of the funder, not sample size."}}},{"id":"P1_U3_MCQ_1599","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1599","question":"Vellfield Media Ltd in Berlin, Germany launches a streaming service at a low monthly subscription price to attract as many subscribers as possible before raising it. Which pricing strategy is this?","options":{"A":"Price skimming, charging a high initial price.","B":"Penetration pricing, setting a low price to gain customers.","C":"Cost-plus pricing, adding a mark-up to costs.","D":"Premium pricing, signalling quality with a high price."},"correctOption":"B","correctAnswer":"Penetration pricing, setting a low price to gain customers.","questionType":"MCQ","explanation":{"correct_reason":"Setting a low introductory price to win a large customer base quickly is penetration pricing, used by Vellfield Media to build subscribers before raising the subscription.","distractor_reasons":{"A":"Price skimming charges a high price to early adopters first. Vellfield is doing the opposite by starting with a low subscription price in Berlin.","B":"Setting a low introductory price to win a large customer base quickly is penetration pricing, used by Vellfield Media to build subscribers before raising the subscription.","C":"Cost-plus pricing derives a price from costs plus a mark-up. The scenario emphasises a deliberately low launch price to attract new subscribers.","D":"Premium pricing uses a high price to convey quality. A low subscription price signals affordability, not exclusivity or luxury. The details given about Vellfield Media Ltd support Penetration pricing, setting a low price to gain customers, so this answer is unsuitable."}}},{"id":"P1_U3_MCQ_1600","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1600","question":"Wrenvale Clinics Ltd in Brisbane, Australia presents itself as a family-friendly clinic with evening appointments, while nearby practices emphasise speed and low prices. What is this?","options":{"A":"Market positioning, building a distinct family-friendly image.","B":"Cost leadership, charging the lowest possible prices.","C":"Mass production of standardised treatments.","D":"Market research, collecting customer opinions."},"correctOption":"A","correctAnswer":"Market positioning, building a distinct family-friendly image.","questionType":"MCQ","explanation":{"correct_reason":"Wrenvale is creating a distinct family-friendly image with evening hours that differs from nearby clinics, which is market positioning in the minds of Brisbane customers.","distractor_reasons":{"A":"Wrenvale is creating a distinct family-friendly image with evening hours that differs from nearby clinics, which is market positioning in the minds of Brisbane customers.","B":"Cost leadership means competing on the lowest prices. The scenario emphasises a family-friendly image and evening hours, not undercutting rivals. For Wrenvale Clinics Ltd, the facts point to Market positioning, building a distinct family-friendly image, so this option cannot be correct.","C":"Mass production applies to standardised manufacturing in bulk, not to a clinic differentiating its service image in Brisbane. The scenario for Wrenvale Clinics Ltd instead describes Market positioning, building a distinct family-friendly image, which rules this alternative out.","D":"Market research involves gathering data. The scenario describes the image Wrenvale projects rather than the collection of customer opinions. In Wrenvale Clinics Ltd's case, the correct description is Market positioning, building a distinct family-friendly image, not this choice."}}},{"id":"P1_U3_MCQ_1601","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1601","question":"Kirana Snacks in Jakarta sells $9 million of spiced cassava chips in a national chips market worth $60 million a year. Its rival, Seda Foods, holds 28% of the same market. What is Kirana Snacks' market share and how does it compare with Seda Foods?","options":{"A":"12%, which is 16 percentage points below Seda Foods","B":"15%, which is 13 percentage points below Seda Foods","C":"18%, which is 10 percentage points below Seda Foods","D":"15%, which is 13 percentage points above Seda Foods"},"correctOption":"B","correctAnswer":"15%, which is 13 percentage points below Seda Foods","questionType":"MCQ","explanation":{"correct_reason":"Market share equals a firm's own sales divided by total market sales, so $9 million divided by $60 million gives 15%; Seda Foods' 28% is 13 percentage points higher than Kirana Snacks' 15%, so Kirana trails its rival by 13 points.","distractor_reasons":{"A":"A 12% share would need sales of $7.2 million, not the $9 million stated, so this option has divided the wrong figures; the gap to Seda Foods would then be 16 points.","B":"Market share equals a firm's own sales divided by total market sales, so $9 million divided by $60 million gives 15%; Seda Foods' 28% is 13 percentage points higher than Kirana Snacks' 15%, so Kirana trails its rival by 13 points.","C":"An 18% share would require $10.8 million of sales, which exceeds the $9 million Kirana Snacks actually records; the comparison with the rival's 28% is therefore also wrong.","D":"The 15% share is right, but at 28% Seda Foods is the larger business, so Kirana Snacks is below its rival by 13 percentage points rather than above it."}}},{"id":"P1_U3_MCQ_1602","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1602","question":"A pottery studio in Lisbon mails 500 questionnaires at $2.40 each to gather views on a new ceramic range. Only 30% of the forms are returned fully completed. What is the average cost of each usable completed questionnaire?","options":{"A":"$2.40","B":"$16.00","C":"$4.80","D":"$8.00"},"correctOption":"D","correctAnswer":"$8.00","questionType":"MCQ","explanation":{"correct_reason":"Mailing 500 questionnaires at $2.40 each costs $1,200, and a 30% return yields 150 completed forms, so $1,200 divided by 150 gives exactly $8.00 per usable response for the Lisbon studio.","distractor_reasons":{"A":"$2.40 is merely the postage on one questionnaire; it ignores the 350 forms never returned and spreads none of the $1,200 total cost across the replies received.","B":"$16.00 would arise from dividing the $1,200 cost by only 75 replies, but 30% of the 500 mailed forms is 150 completed responses, not 75.","C":"$4.80 comes from assuming 250 returns, equivalent to a 50% response rate, whereas the pottery studio in Lisbon receives only 30% of its 500 forms back.","D":"Mailing 500 questionnaires at $2.40 each costs $1,200, and a 30% return yields 150 completed forms, so $1,200 divided by 150 gives exactly $8.00 per usable response for the Lisbon studio."}}},{"id":"P1_U3_MCQ_1603","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1603","question":"A workshop in Hanoi makes bamboo lamps with a production cost of $24 per unit and adds a 25% mark-up to set its selling price. What price does the workshop charge, and what is the mark-up in dollars per lamp?","options":{"A":"$30, with a $6 mark-up","B":"$24, with a $6 mark-up","C":"$30, with a $24 mark-up","D":"$32, with an $8 mark-up"},"correctOption":"A","correctAnswer":"$30, with a $6 mark-up","questionType":"MCQ","explanation":{"correct_reason":"A 25% mark-up on the $24 production cost is $24 multiplied by 0.25, which is $6, so the Hanoi workshop charges $24 plus $6 = $30 per lamp and the dollar mark-up is $6.","distractor_reasons":{"B":"$24 is the production cost before any mark-up, not the selling price; adding the $6 mark-up to it gives $30, so this option stops one step short of the answer.","C":"The $30 price is correct, but $24 is the original cost, not the mark-up; the mark-up is 25% of $24, which equals $6, not the full $24 cost.","D":"$32 would require a mark-up of $8, which is one third of the $24 cost; the stated mark-up is 25%, giving $6 and a final price of $30.","A":"A 25% mark-up on the $24 production cost is $24 multiplied by 0.25, which is $6, so the Hanoi workshop charges $24 plus $6 = $30 per lamp and the dollar mark-up is $6."}}},{"id":"P1_U3_MCQ_1604","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1604","question":"A sports drink brand in Melbourne groups buyers into school pupils, adults aged 25 to 40 and retirees, then designs a different flavour and advert for each age band. Which segmentation base is the brand using?","options":{"A":"Geographic segmentation, because each age band shops in a different suburb","B":"Behavioural segmentation, because each age band buys on different occasions","C":"Demographic segmentation, because the groups are defined by age","D":"Psychographic segmentation, because each age band holds identical values"},"correctOption":"C","correctAnswer":"Demographic segmentation, because the groups are defined by age","questionType":"MCQ","explanation":{"correct_reason":"Age is a demographic variable, so splitting Melbourne buyers into school pupils, adults aged 25 to 40 and retirees is demographic segmentation; each age band then receives a flavour and advert tailored to it.","distractor_reasons":{"A":"Geographic segmentation divides a market by location such as suburbs or regions, but the Melbourne brand groups its customers by age band, which is a demographic rather than a place-based variable.","B":"Behavioural segmentation groups buyers by usage rate, loyalty or purchase occasion; the brand instead defines its three groups by age, which is clearly a demographic characteristic.","D":"Psychographic segmentation uses lifestyle, values and personality; the scenario describes age bands and offers no evidence that the Melbourne groups differ in values or outlook.","C":"Age is a demographic variable, so splitting Melbourne buyers into school pupils, adults aged 25 to 40 and retirees is demographic segmentation; each age band then receives a flavour and advert tailored to it."}}},{"id":"P1_U3_MCQ_1605","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1605","question":"A coffee capsule maker in Nairobi sold 400,000 packs last year and 460,000 packs this year, while total industry volume stayed unchanged. What was the brand's percentage growth in unit sales over the year?","options":{"A":"10%","B":"12%","C":"15%","D":"60%"},"correctOption":"C","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Growth in unit sales is the change divided by the original amount, so 460,000 minus 400,000 gives 60,000 extra packs, and 60,000 over the starting 400,000 packs equals 15% growth.","distractor_reasons":{"A":"10% would imply only 40,000 extra packs, but the Nairobi maker went from 400,000 to 460,000, an increase of 60,000 units measured against the original figure.","B":"12% would correspond to 48,000 additional packs; the actual rise from 400,000 to 460,000 packs is 60,000, which is 15% of the starting volume.","D":"60,000 is the absolute increase in packs, not a percentage; that rise must be divided by the original 400,000 packs to obtain the 15% growth rate.","C":"Growth in unit sales is the change divided by the original amount, so 460,000 minus 400,000 gives 60,000 extra packs, and 60,000 over the starting 400,000 packs equals 15% growth."}}},{"id":"P1_U3_MCQ_1606","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1606","question":"A tea brand in Colombo buys a published industry report on household tea consumption and uses it to plan a new blend, without collecting any fresh information from shoppers itself. Which type of market research is this?","options":{"A":"Desk research using secondary data","B":"Field research using primary data","C":"Quota sampling of regular tea drinkers","D":"A customer panel run by the brand"},"correctOption":"A","correctAnswer":"Desk research using secondary data","questionType":"MCQ","explanation":{"correct_reason":"A published industry report is information gathered by somebody else, so reusing it is desk research based on secondary data; the Colombo brand collects no new information from tea drinkers itself.","distractor_reasons":{"B":"Primary or field research means collecting new data directly from consumers through surveys or interviews; the Colombo brand merely reuses an existing published report.","C":"Quota sampling is a field technique for selecting interviewees; no respondents are selected or questioned in this case, only a pre-existing report is consulted.","D":"Running a customer panel would generate fresh primary data from participants, but the scenario says the brand buys a report and gathers nothing directly from shoppers.","A":"A published industry report is information gathered by somebody else, so reusing it is desk research based on secondary data; the Colombo brand collects no new information from tea drinkers itself."}}},{"id":"P1_U3_MCQ_1607","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1607","question":"A stationery firm in Krakow sells 12,000 notebooks at $4.50 each and 3,000 pens at $1.50 each in one month. What is the firm's total monthly sales revenue from these two lines?","options":{"A":"$54,000","B":"$55,500","C":"$56,500","D":"$58,500"},"correctOption":"D","correctAnswer":"$58,500","questionType":"MCQ","explanation":{"correct_reason":"Notebook revenue is 12,000 multiplied by $4.50, which is $54,000, and pen revenue is 3,000 multiplied by $1.50, which is $4,500, so total monthly sales revenue for the Krakow firm is $58,500.","distractor_reasons":{"A":"$54,000 counts only the notebook sales and leaves out the $4,500 earned from the 3,000 pens sold by the Krakow firm in the same month.","B":"$55,500 would result from valuing each pen at $0.50; the stated price is $1.50, so the 3,000 pens contribute $4,500 of revenue.","C":"$56,500 miscalculates pen revenue as $2,500; at $1.50 each, the 3,000 pens actually generate $4,500 in sales. The business's circumstances match $58,500, so this option does not fit.","D":"Notebook revenue is 12,000 multiplied by $4.50, which is $54,000, and pen revenue is 3,000 multiplied by $1.50, which is $4,500, so total monthly sales revenue for the Krakow firm is $58,500."}}},{"id":"P1_U3_MCQ_1608","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1608","question":"A budget airline in Bangkok offers one standard fare and one cabin class to every passenger, with no separate business or family packages. Which targeting approach is the airline using for its customers?","options":{"A":"Differentiated marketing","B":"Undifferentiated mass marketing","C":"Concentrated niche marketing","D":"Behavioural segmentation"},"correctOption":"B","correctAnswer":"Undifferentiated mass marketing","questionType":"MCQ","explanation":{"correct_reason":"Offering a single standard fare and one cabin class to all passengers treats the whole market as one group, which is undifferentiated or mass marketing, as practised by this Bangkok airline.","distractor_reasons":{"A":"Differentiated marketing would create separate offers for distinct segments, such as business and family fares, which this Bangkok airline deliberately declines to provide.","C":"Concentrated niche marketing focuses on one narrow segment, but the airline serves every passenger with the same standard product rather than targeting a single group.","D":"Behavioural segmentation divides buyers by usage or loyalty; the airline makes no such split when it offers one identical fare to every passenger.","B":"Offering a single standard fare and one cabin class to all passengers treats the whole market as one group, which is undifferentiated or mass marketing, as practised by this Bangkok airline."}}},{"id":"P1_U3_MCQ_1609","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1609","question":"A dairy brand in Kampala holds 12% of the local yoghurt market and records annual sales of $6 million. What is the total value of the Ugandan yoghurt market in which the brand competes?","options":{"A":"$50 million","B":"$72 million","C":"$48 million","D":"$18 million"},"correctOption":"A","correctAnswer":"$50 million","questionType":"MCQ","explanation":{"correct_reason":"Market size equals the brand's sales divided by its share, so $6 million divided by 12% gives $50 million as the total value of the yoghurt market served in Kampala.","distractor_reasons":{"B":"$72 million would come from multiplying $6 million by 12%, producing a figure only slightly larger than the brand's own sales and far too small for the whole market.","C":"$48 million assumes a 12.5% share; at the stated 12%, the $6 million of sales represents exactly one eighth of a $50 million total market.","D":"$18 million is three times the brand's sales and would imply a 33% share, which contradicts the 12% market share given in the scenario.","A":"Market size equals the brand's sales divided by its share, so $6 million divided by 12% gives $50 million as the total value of the yoghurt market served in Kampala."}}},{"id":"P1_U3_MCQ_1610","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1610","question":"An ornaments retailer in Prague sends 800 email surveys and receives 168 completed replies. What is the response rate, and how many additional replies are needed to reach a 25% response rate?","options":{"A":"21%, requiring 24 more replies","B":"21%, requiring 32 more replies","C":"24%, requiring 8 more replies","D":"25%, requiring no more replies"},"correctOption":"B","correctAnswer":"21%, requiring 32 more replies","questionType":"MCQ","explanation":{"correct_reason":"Dividing 168 by 800 gives a 21% response rate, and a 25% rate on 800 emails requires 200 replies, so the Prague retailer needs 32 more completed responses to hit that target.","distractor_reasons":{"A":"The 21% rate is correct, but reaching 25% of 800 emails requires 200 replies rather than 192, so 32 more are needed rather than only 24.","C":"168 replies from 800 emails is 21%, not 24%; the difference between 21% and a 25% target on 800 surveys equals 32 missing responses.","D":"The current response rate is 21%, so the 25% target has not yet been met; 200 replies would be needed, which is 32 more than the 168 already received.","B":"Dividing 168 by 800 gives a 21% response rate, and a 25% rate on 800 emails requires 200 replies, so the Prague retailer needs 32 more completed responses to hit that target."}}},{"id":"P1_U3_MCQ_1611","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1611","question":"A phone case maker in Shenzhen embosses each case with the buyer's name and offers a two-year replacement guarantee that competitors do not match. Which element of the marketing mix is being emphasised most strongly?","options":{"A":"Price","B":"Place","C":"Product","D":"Promotion"},"correctOption":"C","correctAnswer":"Product","questionType":"MCQ","explanation":{"correct_reason":"Personalised name embossing and a longer replacement guarantee are features of the physical item itself, so the Shenzhen maker is emphasising the product element of the marketing mix.","distractor_reasons":{"B":"Place concerns distribution channels and market coverage, not design features or guarantees; the cases are distinguished by what the customer actually receives.","A":"Price concerns the amount charged to buyers; although a guarantee has cost implications, the scenario describes product features rather than the pricing decision itself.","D":"Promotion covers advertising, branding and sales messages, whereas personalised embossing and a two-year replacement promise are built into the item offered to customers.","C":"Personalised name embossing and a longer replacement guarantee are features of the physical item itself, so the Shenzhen maker is emphasising the product element of the marketing mix."}}},{"id":"P1_U3_MCQ_1612","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1612","question":"A bakery chain in Accra sold $2.4 million of bread last year and forecasts 10% sales growth, but an oven upgrade cuts capacity so actual sales reach only 80% of the forecast. What are actual sales?","options":{"A":"$2.64 million","B":"$2.16 million","C":"$2.40 million","D":"$2.112 million"},"correctOption":"D","correctAnswer":"$2.112 million","questionType":"MCQ","explanation":{"correct_reason":"A 10% rise on $2.4 million gives a $2.64 million forecast, and selling only 80% of that forecast yields $2.112 million, so the Accra bakeries actually record $2.112 million of bread sales.","distractor_reasons":{"A":"$2.64 million is the forecast after 10% growth, not the amount actually sold once the capacity limit reduces output to 80% of that forecast.","B":"$2.16 million is 90% of the $2.4 million forecast basis; the scenario states that capacity allows only 80% of the $2.64 million forecast to be sold.","C":"$2.4 million is last year's sales figure and ignores both the 10% growth forecast and the 80% capacity constraint described for the Accra chain.","D":"A 10% rise on $2.4 million gives a $2.64 million forecast, and selling only 80% of that forecast yields $2.112 million, so the Accra bakeries actually record $2.112 million of bread sales."}}},{"id":"P1_U3_MCQ_1613","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1613","question":"A kite shop in Cape Town sells 240 kites at $35 each and gives a $5 discount on 40 of them. What is the shop's total revenue from all 240 sales in the period?","options":{"A":"$8,400","B":"$8,200","C":"$8,000","D":"$7,000"},"correctOption":"B","correctAnswer":"$8,200","questionType":"MCQ","explanation":{"correct_reason":"Forty discounted kites sell at $30 each, raising $1,200, and the remaining 200 at $35 raise $7,000, so total revenue for the Cape Town kite shop is $8,200.","distractor_reasons":{"A":"$8,400 assumes all 240 kites sell at the full $35 and ignores the $5 discount given on 40 of them, which reduces revenue by $200.","C":"$8,000 would require a $10 discount on each of the 40 kites; the stated reduction is only $5 per kite on those particular sales.","D":"$7,000 counts only the 200 full-price kites and entirely omits the $1,200 raised by the shop from the 40 discounted kites.","B":"Forty discounted kites sell at $30 each, raising $1,200, and the remaining 200 at $35 raise $7,000, so total revenue for the Cape Town kite shop is $8,200."}}},{"id":"P1_U3_MCQ_1614","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1614","question":"A researcher in Manila questions 30 shoppers from each of five income bands, letting interviewers choose whoever they judge suitable within each band, to test a new detergent. Which sampling method is this?","options":{"A":"Quota sampling","B":"Simple random sampling","C":"Desk research","D":"A volunteer panel"},"correctOption":"A","correctAnswer":"Quota sampling","questionType":"MCQ","explanation":{"correct_reason":"Quota sampling fixes the number chosen from each sub-group and lets interviewers select respondents inside each quota; the Manila researcher sets 30 shoppers per income band, which matches this method.","distractor_reasons":{"B":"Simple random sampling gives every shopper an equal chance through a random list; here interviewers deliberately pick respondents to fill set quotas within each income band.","C":"Desk research reuses existing published information, whereas the Manila study questions shoppers directly and therefore collects fresh primary data from respondents.","D":"A volunteer panel depends on people choosing to take part, but the researcher actively selects 30 shoppers from each income band rather than waiting for volunteers.","A":"Quota sampling fixes the number chosen from each sub-group and lets interviewers select respondents inside each quota; the Manila researcher sets 30 shoppers per income band, which matches this method."}}},{"id":"P1_U3_MCQ_1615","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1615","question":"A candle maker in Sofia sells each scented jar for $18 and it costs $12 to make. What is the gross profit margin per jar, expressed as a percentage of the selling price?","options":{"A":"50%","B":"25%","C":"33.3%","D":"66.7%"},"correctOption":"C","correctAnswer":"33.3%","questionType":"MCQ","explanation":{"correct_reason":"Gross profit per jar is $18 minus $12, which is $6, and $6 divided by the $18 selling price equals 33.3%, so the Sofia candle maker keeps about one third of each sale as gross profit.","distractor_reasons":{"A":"50% would come from dividing the $6 profit by the $12 cost, giving a mark-up on cost rather than a margin measured against the $18 selling price.","B":"25% would require profit of $4.50 on an $18 jar; the actual profit is $6 because the jar costs only $12 to produce in Sofia.","D":"66.7% is the production cost as a share of the $18 price; the remaining 33.3%, not 66.7%, represents the gross profit margin on each jar.","C":"Gross profit per jar is $18 minus $12, which is $6, and $6 divided by the $18 selling price equals 33.3%, so the Sofia candle maker keeps about one third of each sale as gross profit."}}},{"id":"P1_U3_MCQ_1616","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1616","question":"A gym in Toronto advertises itself as the quiet, adults-only fitness club with no children's classes, aiming at professionals who want a calm workout. Which marketing decision is this best described as?","options":{"A":"Market segmentation","B":"Product positioning","C":"Mass marketing","D":"Market research"},"correctOption":"B","correctAnswer":"Product positioning","questionType":"MCQ","explanation":{"correct_reason":"Positioning shapes how an offering is perceived relative to rivals; by presenting itself as a quiet adults-only club for professionals, the Toronto gym is defining its position in the local market.","distractor_reasons":{"A":"Segmentation divides buyers into distinct groups; the gym has already chosen its customers and is now shaping the image of the club in the minds of those professionals.","C":"Mass marketing targets the whole market with one broad offer, whereas this gym deliberately excludes children and promotes a specific calm image to a narrower audience.","D":"Market research gathers information about customers and competitors; advertising a calm adults-only image is a positioning decision rather than a data collection exercise.","B":"Positioning shapes how an offering is perceived relative to rivals; by presenting itself as a quiet adults-only club for professionals, the Toronto gym is defining its position in the local market."}}},{"id":"P1_U3_MCQ_1617","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1617","question":"A cinema in Oslo sold 1,200 tickets in June and only 900 in July after a competing screen opened nearby. What was the percentage fall in ticket sales between the two months?","options":{"A":"25%","B":"33.3%","C":"30%","D":"75%"},"correctOption":"A","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"Ticket sales fell by 1,200 minus 900, which is 300, and 300 divided by the original 1,200 tickets equals a 25% decline for the Oslo cinema after the rival screen opened.","distractor_reasons":{"B":"33.3% comes from dividing the 300 lost tickets by the 900 that remain; a percentage change must instead use the original 1,200 tickets as its denominator.","C":"30% would mean losing 360 of the original 1,200 tickets; the actual decline from 1,200 to 900 is 300 tickets, which is 25%.","D":"75% is the share of June tickets still sold in July; the decrease is the complementary 25%, so this option reports retention rather than the fall.","A":"Ticket sales fell by 1,200 minus 900, which is 300, and 300 divided by the original 1,200 tickets equals a 25% decline for the Oslo cinema after the rival screen opened."}}},{"id":"P1_U3_MCQ_1618","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1618","question":"A software firm in Berlin spends $4,800 on a campaign that generates 120 enquiries, of which 20 become paying customers. What is the advertising cost per enquiry and per new customer?","options":{"A":"$40 per enquiry and $120 per customer","B":"$120 per enquiry and $240 per customer","C":"$40 per enquiry and $200 per customer","D":"$40 per enquiry and $240 per customer"},"correctOption":"D","correctAnswer":"$40 per enquiry and $240 per customer","questionType":"MCQ","explanation":{"correct_reason":"Dividing $4,800 by 120 enquiries gives $40 per lead, while dividing the same $4,800 by the 20 customers who buy gives $240 per new customer for the Berlin software campaign.","distractor_reasons":{"A":"The $40 cost per enquiry is correct, but $120 per customer would require 40 buyers; only 20 of the 120 Berlin enquiries actually convert into customers.","B":"$120 per enquiry would arise from dividing $4,800 by 40 rather than by 120 enquiries; the campaign in fact generates 120 enquiries in total.","C":"The $40 lead cost is right, but dividing the $4,800 spend by 20 new customers gives $240, not $200, so the customer cost is understated here.","D":"Dividing $4,800 by 120 enquiries gives $40 per lead, while dividing the same $4,800 by the 20 customers who buy gives $240 per new customer for the Berlin software campaign."}}},{"id":"P1_U3_MCQ_1619","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1619","question":"A cheese maker in Bern arranges for its products to be stocked in 300 supermarkets and sold through a delivery app, while keeping the recipe, label and price unchanged. Which marketing mix element is being changed?","options":{"A":"Product","B":"Price","C":"Place","D":"Promotion"},"correctOption":"C","correctAnswer":"Place","questionType":"MCQ","explanation":{"correct_reason":"Place covers distribution channels and availability; adding 300 supermarket stockists and a delivery app changes where customers can buy the Bern cheese, not its recipe, price or advertising.","distractor_reasons":{"B":"Price concerns the amount charged to buyers, and no change to the cheese's selling price is mentioned; only the locations where it can be purchased are altered.","A":"Product decisions involve the recipe, packaging and label, all of which stay unchanged in this Bern cheese maker's distribution plan for supermarkets and the app.","D":"Promotion involves advertising and sales appeals, whereas gaining 300 new stockists and joining a delivery app are distribution decisions about availability.","C":"Place covers distribution channels and availability; adding 300 supermarket stockists and a delivery app changes where customers can buy the Bern cheese, not its recipe, price or advertising."}}},{"id":"P1_U3_MCQ_1620","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1620","question":"A shampoo brand in Seoul held 8% of a $200 million market last year; this year its sales rose to $22 million while the total market grew to $220 million. What is its market share now?","options":{"A":"8%","B":"10%","C":"11%","D":"12%"},"correctOption":"B","correctAnswer":"10%","questionType":"MCQ","explanation":{"correct_reason":"Current share is own sales divided by total market value, so $22 million divided by $220 million equals 10% for the Seoul shampoo brand, an increase on the 8% held last year.","distractor_reasons":{"A":"8% was last year's share of the $200 million market; with current sales of $22 million in a $220 million market, the brand's share has risen to 10%.","C":"11% would come from dividing $22 million by last year's $200 million market, but the correct current market value to use in the calculation is $220 million.","D":"12% would require sales of $26.4 million in a $220 million market; the Seoul brand records only $22 million, which is a 10% share.","B":"Current share is own sales divided by total market value, so $22 million divided by $220 million equals 10% for the Seoul shampoo brand, an increase on the 8% held last year."}}},{"id":"P1_U3_MCQ_1621","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1621","question":"A bicycle repair shop in Lyon notices that commuters arrive late because they cannot get help after 6 pm, so it opens an evening service. Which marketing concept does this decision best illustrate?","options":{"A":"Product orientation","B":"Sales orientation","C":"Production orientation","D":"Customer needs identification"},"correctOption":"D","correctAnswer":"Customer needs identification","questionType":"MCQ","explanation":{"correct_reason":"The Lyon shop observes a real commuter problem and changes its service to satisfy it, which shows the marketing concept of identifying customer needs and responding to them profitably.","distractor_reasons":{"A":"Product orientation focuses on the product itself and assumes it will sell; here the shop changes its opening hours to meet a need observed among local commuters.","C":"Production orientation emphasises efficient output and low unit costs, whereas the Lyon shop's decision is driven by commuter convenience rather than production efficiency.","B":"Sales orientation relies on heavy selling to shift existing services, but the evening opening is a direct response to what customers want, not a selling campaign.","D":"The Lyon shop observes a real commuter problem and changes its service to satisfy it, which shows the marketing concept of identifying customer needs and responding to them profitably."}}},{"id":"P1_U3_MCQ_1622","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1622","question":"A research agency in Dublin plans 250 face-to-face interviews costing $14 each and 150 online responses costing $3 each. What is the total cost of collecting all 400 responses?","options":{"A":"$3,950","B":"$3,500","C":"$4,400","D":"$3,050"},"correctOption":"A","correctAnswer":"$3,950","questionType":"MCQ","explanation":{"correct_reason":"Face-to-face interviews cost 250 multiplied by $14, which is $3,500, and online responses cost 150 multiplied by $3, which is $450, so the Dublin agency spends $3,950 in total.","distractor_reasons":{"B":"$3,500 covers only the 250 face-to-face interviews and completely leaves out the $450 that the Dublin agency spends on the 150 online responses.","C":"$4,400 would arise from charging $6 for each online response; the stated cost is $3, so those 150 responses add only $450 to the total.","D":"$3,050 incorrectly values face-to-face interviews at $11 each; at the stated $14 each, the 250 interviews cost $3,500. The scenario for the business instead describes $3,950, which rules this alternative out.","A":"Face-to-face interviews cost 250 multiplied by $14, which is $3,500, and online responses cost 150 multiplied by $3, which is $450, so the Dublin agency spends $3,950 in total."}}},{"id":"P1_U3_MCQ_1623","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1623","question":"A bookshop in Bordeaux prices a novel at $28 and offers a 15% student discount. What price does a student pay, and what is the value of the discount in dollars?","options":{"A":"$23.00, a $5 discount","B":"$24.00, a $4 discount","C":"$23.80, a $4.20 discount","D":"$25.20, a $2.80 discount"},"correctOption":"C","correctAnswer":"$23.80, a $4.20 discount","questionType":"MCQ","explanation":{"correct_reason":"A 15% discount on the $28 novel is $4.20, so the Bordeaux bookshop charges students $28 minus $4.20, which is $23.80 per copy of the book.","distractor_reasons":{"A":"$23.00 would require a $5 discount, which is about 17.9% of $28, rather than the 15% student reduction stated for the Bordeaux bookshop.","B":"$24.00 implies a $4 discount, roughly 14.3% of the $28 price; 15% of $28 is exactly $4.20, so this option rounds incorrectly.","D":"$25.20 is the price after only a 10% reduction; the bookshop advertises a 15% student discount, giving $23.80 and a $4.20 saving.","C":"A 15% discount on the $28 novel is $4.20, so the Bordeaux bookshop charges students $28 minus $4.20, which is $23.80 per copy of the book."}}},{"id":"P1_U3_MCQ_1624","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1624","question":"A soap maker in Zurich produces only hand-made, unscented bars for people with sensitive skin and sells them through skin clinics rather than supermarkets. Which market strategy is being followed?","options":{"A":"Mass marketing","B":"Differentiated marketing","C":"Undifferentiated marketing","D":"Niche marketing"},"correctOption":"D","correctAnswer":"Niche marketing","questionType":"MCQ","explanation":{"correct_reason":"Concentrating on a narrow group with sensitive skin and selling through specialist clinics is niche marketing, focusing on one well-defined segment instead of the whole soap market.","distractor_reasons":{"A":"Mass marketing would target all soap buyers with one broad offer, whereas the Zurich maker deliberately serves only people with sensitive skin through clinics.","B":"Differentiated marketing means offering separate products to several different segments, but this maker concentrates on just one narrow group of sensitive-skin buyers.","C":"Undifferentiated marketing treats the entire market alike with one product and wide distribution, unlike the clinic-only, specialist focus described in this scenario.","D":"Concentrating on a narrow group with sensitive skin and selling through specialist clinics is niche marketing, focusing on one well-defined segment instead of the whole soap market."}}},{"id":"P1_U3_MCQ_1625","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1625","question":"In a $500 million mobile phone market, a brand in Sao Paulo records $75 million of sales while its largest rival records $125 million. What is the gap between the two firms' market shares?","options":{"A":"5 percentage points","B":"10 percentage points","C":"15 percentage points","D":"25 percentage points"},"correctOption":"B","correctAnswer":"10 percentage points","questionType":"MCQ","explanation":{"correct_reason":"The Sao Paulo brand holds $75 million divided by $500 million, which is 15%, and the rival holds $125 million divided by $500 million, which is 25%, leaving a gap of 10 percentage points.","distractor_reasons":{"A":"A 5 point gap would require the rival to hold 20%, equal to $100 million of sales, not the $125 million recorded by the larger firm in this market.","C":"15% is the Sao Paulo brand's own share of the $500 million market, not the difference between the shares of the two competing businesses.","D":"25% is the rival's share of the market; subtracting the brand's 15% from it gives the 10 percentage point gap asked for in the question.","B":"The Sao Paulo brand holds $75 million divided by $500 million, which is 15%, and the rival holds $125 million divided by $500 million, which is 25%, leaving a gap of 10 percentage points."}}},{"id":"P1_U3_MCQ_1626","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1626","question":"A researcher in Seville watches 60 shoppers in a supermarket aisle and records which cereal boxes they pick up, without asking any questions at all. Which market research method is being used?","options":{"A":"Observation","B":"Postal questionnaire","C":"Focus group","D":"Secondary data analysis"},"correctOption":"A","correctAnswer":"Observation","questionType":"MCQ","explanation":{"correct_reason":"Recording shoppers' actual choices in the Seville aisle without questioning them is observation research, which captures real behaviour directly rather than relying on what people say they do.","distractor_reasons":{"A":"Recording shoppers' actual choices in the Seville aisle without questioning them is observation research, which captures real behaviour directly rather than relying on what people say they do.","B":"A postal questionnaire would ask respondents questions in writing and wait for returns; the Seville researcher simply watches behaviour and asks the shoppers nothing.","C":"A focus group brings a small group together to discuss views with a moderator; the Seville study records silent in-store behaviour, not a group discussion.","D":"Secondary data analysis reuses information collected earlier by others; here the Seville researcher gathers completely new first-hand observations inside the store."}}},{"id":"P1_U3_MCQ_1627","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1627","question":"A cereal brand in Winnipeg offers a free toy inside every box for two months to encourage trial among young children. Which element of the marketing mix does this activity mainly represent?","options":{"A":"Price","B":"Place","C":"Promotion","D":"Product"},"correctOption":"C","correctAnswer":"Promotion","questionType":"MCQ","explanation":{"correct_reason":"A free toy used as a short-term incentive to encourage trial is a sales promotion activity, so the Winnipeg cereal brand is mainly using the promotion element of the marketing mix.","distractor_reasons":{"A":"Price concerns the amount customers pay, and the box price is unchanged; the toy acts as a promotional incentive rather than as a discount on the selling price.","B":"Place concerns distribution and availability of the cereal boxes; offering a free toy does not change the shops where Winnipeg customers can buy them.","D":"The cereal recipe and pack design are not altered by inserting a toy as a temporary incentive, so this is not principally a product design decision.","C":"A free toy used as a short-term incentive to encourage trial is a sales promotion activity, so the Winnipeg cereal brand is mainly using the promotion element of the marketing mix."}}},{"id":"P1_U3_MCQ_1628","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1628","question":"A cosmetics firm in Marseille competes by matching rivals' prices exactly and copying their packaging, rather than researching what its own customers want. Which strategic outlook does this show?","options":{"A":"Market oriented","B":"Competitor oriented","C":"Customer led","D":"Niche focused"},"correctOption":"B","correctAnswer":"Competitor oriented","questionType":"MCQ","explanation":{"correct_reason":"Copying rivals' prices and packaging while ignoring customer research reveals a competitor-oriented outlook, in which the Marseille firm reacts to competitors instead of studying buyer needs.","distractor_reasons":{"A":"A market-oriented business starts from customer needs and research, but the Marseille firm watches rival products and copies their decisions rather than consulting buyers.","C":"A customer-led approach would gather views from the firm's own buyers; no such research is described, only imitation of what competing cosmetics firms already do.","D":"Niche focus means concentrating on one narrow segment, whereas the firm is copying competitors broadly and shows no sign of targeting a specific group.","B":"Copying rivals' prices and packaging while ignoring customer research reveals a competitor-oriented outlook, in which the Marseille firm reacts to competitors instead of studying buyer needs."}}},{"id":"P1_U3_MCQ_1629","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1629","question":"A water bottle brand in Tashkent held 9% of a market worth $80 million last year. The market then grew by 25% while the brand kept its 9% share. What is the brand's sales value this year?","options":{"A":"$7.2 million","B":"$10 million","C":"$8 million","D":"$9 million"},"correctOption":"D","correctAnswer":"$9 million","questionType":"MCQ","explanation":{"correct_reason":"The market grows from $80 million to $100 million after 25% growth, and holding a 9% share of that new total gives $9 million of sales for the Tashkent water bottle brand.","distractor_reasons":{"A":"$7.2 million is 9% of last year's $80 million market; the market has since grown by 25% to $100 million, so the brand's sales have risen too.","B":"$10 million would represent a 10% share of the new $100 million market; the brand keeps its 9% share, giving sales of $9 million.","C":"$8 million would be 8% of the enlarged market; no fall in share is stated, so the Tashkent brand holds 9% and reaches $9 million.","D":"The market grows from $80 million to $100 million after 25% growth, and holding a 9% share of that new total gives $9 million of sales for the Tashkent water bottle brand."}}},{"id":"P1_U3_MCQ_1630","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1630","question":"A survey in Montreal asks shoppers to choose one of five fixed answers about their preferred packaging colour, rather than describing their views in their own words. Which question type is being used?","options":{"A":"Closed questions","B":"Open questions","C":"Observation","D":"Secondary data"},"correctOption":"A","correctAnswer":"Closed questions","questionType":"MCQ","explanation":{"correct_reason":"Offering five fixed answer choices restricts respondents to set options, making these closed questions; they are quick to code but can miss views outside the listed Montreal colours.","distractor_reasons":{"B":"Open questions allow respondents to answer freely in their own words, but the Montreal survey limits shoppers to five pre-set choices about packaging colour.","C":"Observation records behaviour without asking any questions, whereas the Montreal study asks shoppers to select an answer about their colour preference.","D":"Secondary data is information collected previously by other organisations; this survey gathers brand-new responses directly from Montreal shoppers. For the business, the facts point to Closed questions, so this option cannot be correct.","A":"Offering five fixed answer choices restricts respondents to set options, making these closed questions; they are quick to code but can miss views outside the listed Montreal colours."}}},{"id":"P1_U3_MCQ_1631","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1631","question":"A juice bar in Quito wants a 40% gross margin on each drink, calculated on the selling price, and each drink costs $1.80 to make. What selling price must the bar charge?","options":{"A":"$2.52","B":"$3.00","C":"$2.88","D":"$4.50"},"correctOption":"B","correctAnswer":"$3.00","questionType":"MCQ","explanation":{"correct_reason":"With a 40% margin on selling price, the $1.80 cost must equal 60% of the price, so price is $1.80 divided by 0.6, which gives $3.00 per juice at the Quito bar.","distractor_reasons":{"A":"$2.52 comes from adding 40% of $1.80 to the cost, which is a 40% mark-up on cost rather than the required 40% margin on the selling price.","C":"$2.88 would leave a gross profit of $1.08, equal to 37.5% of that price, so it does not deliver the 40% gross margin wanted in Quito.","D":"$4.50 would produce a gross profit of $2.70, which is 60% of the price, giving a 60% margin rather than the required 40%.","B":"With a 40% margin on selling price, the $1.80 cost must equal 60% of the price, so price is $1.80 divided by 0.6, which gives $3.00 per juice at the Quito bar."}}},{"id":"P1_U3_MCQ_1632","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1632","question":"A rice brand in Yangon sets a goal of raising its share of the national rice market from 6% to 9% within two years by expanding its distribution network. Which type of marketing objective is this?","options":{"A":"Profit objective","B":"Sales revenue objective","C":"Customer satisfaction objective","D":"Market share objective"},"correctOption":"D","correctAnswer":"Market share objective","questionType":"MCQ","explanation":{"correct_reason":"Setting a target share of the national market, from 6% up to 9%, is a market share objective because the Yangon brand measures success by its portion of total industry sales.","distractor_reasons":{"A":"A profit objective would state a target quantity of earnings; the Yangon brand instead specifies a percentage share of the national rice market.","B":"A revenue objective would name a sales value in dollars, whereas this goal is expressed as a percentage of all rice sold nationally.","C":"A satisfaction objective would track customer ratings or complaint numbers, not the proportion of the rice market captured by the brand.","D":"Setting a target share of the national market, from 6% up to 9%, is a market share objective because the Yangon brand measures success by its portion of total industry sales."}}},{"id":"P1_U3_MCQ_1633","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1633","question":"A bakery in Tunis sees total cake sales in its city rising by 8% while its own sales stay completely flat. What is happening to the bakery's share of the local cake market?","options":{"A":"It rises","B":"It stays the same","C":"It falls","D":"It doubles"},"correctOption":"C","correctAnswer":"It falls","questionType":"MCQ","explanation":{"correct_reason":"If the whole Tunis cake market grows by 8% while this bakery's sales do not change, its portion of the larger market necessarily becomes smaller, so its market share falls.","distractor_reasons":{"A":"A rising share would need the bakery's sales to grow faster than the market; instead the bakery is flat while the Tunis market expands by 8%.","B":"A constant share would require sales to rise in line with the 8% market growth; flat sales against a growing market mean the share declines.","D":"Nothing suggests sales double; the bakery's own sales are unchanged while the surrounding market in Tunis grows by 8%, so share falls.","C":"If the whole Tunis cake market grows by 8% while this bakery's sales do not change, its portion of the larger market necessarily becomes smaller, so its market share falls."}}},{"id":"P1_U3_MCQ_1634","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1634","question":"A survey firm in Adelaide needs 1,200 completed responses spread across four equal city districts and expects a 60% completion rate. How many questionnaires must it send in total?","options":{"A":"1,800","B":"1,920","C":"2,000","D":"2,400"},"correctOption":"C","correctAnswer":"2,000","questionType":"MCQ","explanation":{"correct_reason":"To obtain 1,200 completed forms at a 60% response rate, the Adelaide firm must distribute 1,200 divided by 0.6, which equals 2,000 questionnaires altogether.","distractor_reasons":{"A":"Sending 1,800 questionnaires at 60% completion would yield 1,080 usable replies, which falls short of the 1,200 responses the Adelaide firm requires.","B":"Sending 1,920 questionnaires would produce 1,152 completed forms at a 60% rate, still below the target of 1,200 responses for the survey.","D":"Sending 2,400 questionnaires at 60% would give 1,440 replies, overshooting the 1,200 target; exactly 2,000 are needed. The details given about the business support 2,000, so this answer is unsuitable.","C":"To obtain 1,200 completed forms at a 60% response rate, the Adelaide firm must distribute 1,200 divided by 0.6, which equals 2,000 questionnaires altogether."}}},{"id":"P1_U3_MCQ_1635","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1635","question":"A cosmetics company in Milan sells shampoos, conditioners and hair masks under one brand name, all aimed at hair care buyers. What is this group of closely related products called?","options":{"A":"A product line","B":"A product mix width","C":"A new product","D":"A distribution channel"},"correctOption":"A","correctAnswer":"A product line","questionType":"MCQ","explanation":{"correct_reason":"Shampoos, conditioners and hair masks are closely related items serving the same hair care need, so together they form a product line inside the Milan company's wider range of offerings.","distractor_reasons":{"B":"Product mix width describes how many different product lines a company offers, not the set of related items contained within one hair care line.","C":"These are established items sold together as a range; the term new product would apply to a recently launched offering, which is not described here.","D":"A distribution channel is the route a product takes to reach buyers, not the collection of related hair care items sold under the same Milan brand.","A":"Shampoos, conditioners and hair masks are closely related items serving the same hair care need, so together they form a product line inside the Milan company's wider range of offerings."}}},{"id":"P1_U3_MCQ_1636","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1636","question":"A laptop maker in Taipei wins orders by offering a three-year on-site repair service that rivals do not provide, even though its prices are slightly higher. Which source of competitive advantage is it using?","options":{"A":"Cost leadership","B":"Mass marketing","C":"Market skimming","D":"Differentiation"},"correctOption":"D","correctAnswer":"Differentiation","questionType":"MCQ","explanation":{"correct_reason":"A unique three-year on-site repair service sets the Taipei laptop maker apart from rivals, so it competes through differentiation rather than by being the lowest-cost producer.","distractor_reasons":{"A":"Cost leadership means being the cheapest supplier, but this laptop maker charges slightly higher prices and wins business through an extra repair service.","B":"Mass marketing targets all buyers with one broad offer; the scenario highlights a distinctive service benefit rather than the breadth of the target market.","C":"Skimming sets a high initial price for a new product, whereas the Taipei firm's advantage comes from a service that competitors do not match.","D":"A unique three-year on-site repair service sets the Taipei laptop maker apart from rivals, so it competes through differentiation rather than by being the lowest-cost producer."}}},{"id":"P1_U3_MCQ_1637","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1637","question":"An ice cream parlour in Valencia finds customers asking for lower-sugar options after a local health campaign, and develops a fruit sorbet range in response. Which marketing idea does this show?","options":{"A":"Production orientation","B":"Responding to customer needs","C":"Sales orientation","D":"Product orientation"},"correctOption":"B","correctAnswer":"Responding to customer needs","questionType":"MCQ","explanation":{"correct_reason":"The Valencia parlour listens to a stated customer preference for less sugar and creates a suitable sorbet range, illustrating how marketing responds to customer needs with a profitable offering.","distractor_reasons":{"A":"Production orientation focuses on efficient output and lower costs, not on changing a recipe after local customers request less sugar in their ice cream.","C":"Sales orientation would push existing stock through promotion; instead the parlour develops a new sorbet range after hearing what buyers in Valencia want.","D":"Product orientation assumes a good product sells itself, but this parlour changes its range specifically because customers expressed a new preference.","B":"The Valencia parlour listens to a stated customer preference for less sugar and creates a suitable sorbet range, illustrating how marketing responds to customer needs with a profitable offering."}}},{"id":"P1_U3_MCQ_1638","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1638","question":"A hotel in Seville gathers comments directly from 200 guests at check-out, while a rival relies on an old tourism report. What is the main advantage of the hotel's own approach?","options":{"A":"The information is current and specific to its own guests","B":"It costs nothing at all to collect","C":"One person can gather it within an hour","D":"It is more detailed than any possible survey"},"correctOption":"A","correctAnswer":"The information is current and specific to its own guests","questionType":"MCQ","explanation":{"correct_reason":"Comments taken at check-out are fresh primary data from the Seville hotel's own customers, so the findings are up to date and directly relevant to that hotel's service.","distractor_reasons":{"B":"Questioning 200 guests is not costless; staff time and any incentives must be paid for, even though the hotel avoids buying an outside report.","C":"Collecting 200 individual comments takes much longer than an hour, so speed is not the real advantage claimed for the Seville hotel's approach.","D":"The hotel's information is relevant rather than automatically more detailed; a thorough report may contain more statistical depth than brief check-out comments.","A":"Comments taken at check-out are fresh primary data from the Seville hotel's own customers, so the findings are up to date and directly relevant to that hotel's service."}}},{"id":"P1_U3_MCQ_1639","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1639","question":"A tea shop in Colombo sells 3,500 cups at $2.20 each and 900 cakes at $3.00 each in a week. What is the shop's total revenue from these two lines?","options":{"A":"$10,400","B":"$9,700","C":"$10,100","D":"$7,700"},"correctOption":"A","correctAnswer":"$10,400","questionType":"MCQ","explanation":{"correct_reason":"Tea sales of 3,500 cups at $2.20 bring $7,700 and 900 cakes at $3.00 bring $2,700, so the Colombo shop's total revenue from these two lines is $10,400.","distractor_reasons":{"B":"$9,700 would arise from valuing each cake at about $2.22; at the stated $3.00, the 900 cakes contribute $2,700 of revenue.","C":"$10,100 would require cake revenue of $2,400, but 900 cakes priced at $3.00 actually generate $2,700 for the Colombo shop. The business's circumstances match $10,400, so this option does not fit.","D":"$7,700 counts only the tea sales and completely ignores the $2,700 earned from the 900 cakes sold during the same week.","A":"Tea sales of 3,500 cups at $2.20 bring $7,700 and 900 cakes at $3.00 bring $2,700, so the Colombo shop's total revenue from these two lines is $10,400."}}},{"id":"P1_U3_MCQ_1640","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1640","question":"An insurance firm in Dublin tailors policies separately for students, families and retirees instead of selling a single standard plan. What is the main benefit of this approach?","options":{"A":"It removes the need for any advertising","B":"It matches offerings more closely to different customer groups","C":"It guarantees lower costs than all rivals","D":"It eliminates competition in the market"},"correctOption":"B","correctAnswer":"It matches offerings more closely to different customer groups","questionType":"MCQ","explanation":{"correct_reason":"Tailoring policies to students, families and retirees lets the Dublin insurer match features and premiums to each group's needs, which is the central benefit of market segmentation.","distractor_reasons":{"A":"Segmentation does not remove the need for advertising; every tailored policy still needs promotion to reach its intended group of Dublin buyers.","C":"Offering several tailored plans may actually raise costs, so being cheaper than competitors is not guaranteed by segmentation on its own.","D":"Segmentation cannot eliminate competition; other insurers continue to serve the same student, family and retiree groups in the market. The scenario for the business instead describes It matches offerings more closely to different customer groups, which rules this alternative out.","B":"Tailoring policies to students, families and retirees lets the Dublin insurer match features and premiums to each group's needs, which is the central benefit of market segmentation."}}},{"id":"P1_U3_MCQ_1641","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1641","question":"A chocolate maker in Antwerp claims to be the city's leading brand because it has the highest sales revenue, yet a rival sells more bars at a lower price. Which measure would best test that leadership claim?","options":{"A":"Total revenue alone","B":"The price per bar","C":"Market share measured in bars sold","D":"Advertising spending"},"correctOption":"C","correctAnswer":"Market share measured in bars sold","questionType":"MCQ","explanation":{"correct_reason":"Because the rival moves more chocolate bars, comparing shares measured in units sold gives a fairer test of leadership in Antwerp than revenue, which is inflated by the higher price.","distractor_reasons":{"A":"Total revenue alone favours the higher-priced Antwerp brand and does not show which chocolate maker actually supplies more of the market by volume.","B":"Price per bar helps explain the revenue difference but does not by itself reveal which firm reaches more chocolate buyers in the city.","D":"Advertising spending measures promotional effort rather than the portion of the Antwerp chocolate market captured by either business. In the business's case, the correct description is Market share measured in bars sold, not this choice.","C":"Because the rival moves more chocolate bars, comparing shares measured in units sold gives a fairer test of leadership in Antwerp than revenue, which is inflated by the higher price."}}},{"id":"P1_U3_MCQ_1642","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1642","question":"A market researcher in Gothenburg discovers that an industry report used last year is already three years out of date. What is the main weakness of relying on it for a new decision?","options":{"A":"The figures may no longer reflect current customer behaviour","B":"Secondary data is always expensive to obtain","C":"It must contain far too many respondents","D":"It cannot be combined with any fresh survey"},"correctOption":"A","correctAnswer":"The figures may no longer reflect current customer behaviour","questionType":"MCQ","explanation":{"correct_reason":"Outdated information may no longer describe current buying habits in Gothenburg, so relying on a three-year-old report risks decisions based on behaviour that has since changed.","distractor_reasons":{"B":"Cost is not the weakness here; the difficulty is the age of the information, even if the old report was inexpensive for the researcher to obtain.","C":"Having many respondents is normally an advantage, not a weakness; the real problem with the Gothenburg report is that its figures are three years old.","D":"Older reports can be combined with fresh survey results; the concern is relevance to current decisions, not an absolute ban on mixing research methods.","A":"Outdated information may no longer describe current buying habits in Gothenburg, so relying on a three-year-old report risks decisions based on behaviour that has since changed."}}},{"id":"P1_U3_MCQ_1643","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1643","question":"A tablet maker in Davao launches at a very low price to win a large customer base quickly, planning to raise prices once demand is established. Which pricing strategy is being used?","options":{"A":"Cost-plus pricing","B":"Price skimming","C":"Penetration pricing","D":"Premium pricing"},"correctOption":"C","correctAnswer":"Penetration pricing","questionType":"MCQ","explanation":{"correct_reason":"Launching at a deliberately low price to build a broad customer base quickly is penetration pricing; the Davao tablet maker accepts small early margins to establish market share.","distractor_reasons":{"A":"Cost-plus pricing adds a mark-up to unit cost, but the scenario describes an intentional low launch price rather than a calculation based on production cost.","B":"Skimming starts with a high price to earn large margins before reducing it, the opposite of the low-price launch chosen by the Davao tablet maker.","D":"Premium pricing sets a high price to signal quality, whereas this firm starts below rivals to attract buyers rapidly and build a customer base.","C":"Launching at a deliberately low price to build a broad customer base quickly is penetration pricing; the Davao tablet maker accepts small early margins to establish market share."}}},{"id":"P1_U3_MCQ_1644","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1644","question":"A phone accessories firm in Belgrade sets a target of selling one in five of all protective cases bought in its home market within three years. What kind of marketing objective is this?","options":{"A":"A cost objective","B":"A distribution objective","C":"A customer service objective","D":"A market share objective"},"correctOption":"D","correctAnswer":"A market share objective","questionType":"MCQ","explanation":{"correct_reason":"Selling one in five cases in the Belgrade market means aiming for a 20% market share, so this is a market share objective expressed as a portion of total cases sold.","distractor_reasons":{"A":"A cost objective would target unit production costs or overheads, not the proportion of all protective cases purchased in the Belgrade market.","B":"Distribution objectives concern numbers of outlets or coverage, whereas the Belgrade firm states a goal for its share of all cases bought.","C":"A service objective would measure delivery speed or complaint handling, while this firm sets a target for its portion of total market sales.","D":"Selling one in five cases in the Belgrade market means aiming for a 20% market share, so this is a market share objective expressed as a portion of total cases sold."}}},{"id":"P1_U3_MCQ_1645","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1645","question":"A baker in Luxor sells $12 million of bread in a city market worth $150 million a year. What is the baker's market share, and what share is left for all competitors combined?","options":{"A":"8%, with 82% for rivals","B":"8%, with 92% for rivals","C":"12%, with 88% for rivals","D":"18%, with 82% for rivals"},"correctOption":"B","correctAnswer":"8%, with 92% for rivals","questionType":"MCQ","explanation":{"correct_reason":"The Luxor baker's share is $12 million divided by $150 million, which is 8%, so all competing bakeries together hold the other 92% of the city bread market.","distractor_reasons":{"A":"The 8% share is correct, but rivals hold 100% minus 8%, which is 92% of the Luxor bread market, not 82%.","C":"12% would come from dividing $150 million by $12 million in the wrong direction; $12 million of sales is 8% of a $150 million market.","D":"18% is much too high because $12 million is well under one fifth of the $150 million total value of the Luxor bread market.","B":"The Luxor baker's share is $12 million divided by $150 million, which is 8%, so all competing bakeries together hold the other 92% of the city bread market."}}},{"id":"P1_U3_MCQ_1646","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1646","question":"A tourism board in Fiji conducts 400 street interviews with visitors to learn why they chose the islands, rather than reading an old tourism report. What kind of data is it collecting?","options":{"A":"Primary data gathered first-hand","B":"Only secondary data","C":"Desk research","D":"Published government statistics"},"correctOption":"A","correctAnswer":"Primary data gathered first-hand","questionType":"MCQ","explanation":{"correct_reason":"Street interviews collect new information straight from Fiji's visitors, so the tourism board is gathering primary data that includes both counts and comments about reasons for visiting.","distractor_reasons":{"B":"Secondary data comes from sources collected earlier by other organisations; these 400 interviews are fresh evidence gathered by the tourism board itself.","C":"Desk research uses existing reports and statistics without fieldwork, whereas conducting 400 street interviews in Fiji is clearly field research. The scenario for the business instead describes Primary data gathered first-hand, which rules this alternative out.","D":"Published statistics already exist before a study begins; the board's interviews create brand-new responses from the visitors who are questioned. In the business's case, the correct description is Primary data gathered first-hand, not this choice.","A":"Street interviews collect new information straight from Fiji's visitors, so the tourism board is gathering primary data that includes both counts and comments about reasons for visiting."}}},{"id":"P1_U3_MCQ_1647","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1647","question":"A coffee roaster in Medellin prints a distinctive logo and a fair-trade promise on every bag so that shoppers can recognise it instantly on a crowded shelf. Which marketing mix decision is this?","options":{"A":"Place","B":"Price","C":"Product branding","D":"Distribution"},"correctOption":"C","correctAnswer":"Product branding","questionType":"MCQ","explanation":{"correct_reason":"A distinctive logo and stated fair-trade promise identify the Medellin roaster's coffee to shoppers, which is a branding decision within the product element of the marketing mix.","distractor_reasons":{"B":"Price decisions concern the amount charged, and a logo or fair-trade promise does not set or change the price of the coffee bags on the shelf.","A":"Place concerns distribution outlets and availability, whereas a recognisable logo on the bag affects how the product is identified by customers.","D":"Distribution describes how goods reach buyers; distinctive packaging helps identify the coffee but does not decide which shops stock it. The business's circumstances match Product branding, so this option does not fit.","C":"A distinctive logo and stated fair-trade promise identify the Medellin roaster's coffee to shoppers, which is a branding decision within the product element of the marketing mix."}}},{"id":"P1_U3_MCQ_1648","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1648","question":"A juice company in Lahore moves from cheap canned drinks to premium cold-pressed bottles sold in gyms, deliberately changing its image and the buyers it targets. What marketing strategy is this?","options":{"A":"Maintaining market share","B":"Cost reduction","C":"Mass marketing","D":"Repositioning"},"correctOption":"D","correctAnswer":"Repositioning","questionType":"MCQ","explanation":{"correct_reason":"Changing from cheap canned drinks to premium cold-pressed bottles aimed at gym users alters the brand's image and target buyers, which is repositioning in the Lahore market.","distractor_reasons":{"A":"Maintaining share would mean keeping existing customers; this Lahore company deliberately changes both its product and the group of buyers it targets.","B":"Cost reduction would lower expenses to support cheaper prices, whereas the move into premium bottles raises quality and is likely to increase unit costs.","C":"Mass marketing targets everyone with one broad offer, but the Lahore juice company now concentrates on a specific premium, health-conscious audience.","D":"Changing from cheap canned drinks to premium cold-pressed bottles aimed at gym users alters the brand's image and target buyers, which is repositioning in the Lahore market."}}},{"id":"P1_U3_MCQ_1649","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1649","question":"A spice company in Casablanca decides to measure its sales against all seasonings sold in Morocco rather than only against other spice brands. What exactly has the company changed?","options":{"A":"Its production costs","B":"The market against which share is measured","C":"Its delivery service","D":"Its legal structure"},"correctOption":"B","correctAnswer":"The market against which share is measured","questionType":"MCQ","explanation":{"correct_reason":"Counting all seasonings instead of just spice brands broadens the market definition used to calculate share, so the Casablanca company's measured market share will change as a result.","distractor_reasons":{"A":"Production costs depend on ingredients and processes, not on choosing the market used as a benchmark for the company's sales in Morocco.","C":"Delivery arrangements are a distribution matter, whereas the Casablanca company changes only the comparison market used for its sales figures. The details given about the business support The market against which share is measured, so this answer is unsuitable.","D":"Legal structure concerns ownership and liability, which is unrelated to how widely the firm defines its market when calculating share. For the business, the facts point to The market against which share is measured, so this option cannot be correct.","B":"Counting all seasonings instead of just spice brands broadens the market definition used to calculate share, so the Casablanca company's measured market share will change as a result."}}},{"id":"P1_U3_MCQ_1650","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1650","question":"A research team in Bucharest draws its sample only from a list of loyalty-card members when estimating the opinions of all shoppers. What is the main problem with this approach?","options":{"A":"The sample will certainly be too large","B":"The interviews will take too long","C":"Non-members are excluded, so it may be unrepresentative","D":"The questions would have to be closed"},"correctOption":"C","correctAnswer":"Non-members are excluded, so it may be unrepresentative","questionType":"MCQ","explanation":{"correct_reason":"Using only loyalty-card members leaves out shoppers without cards, so the Bucharest sample may fail to represent all customers and could bias the opinion results.","distractor_reasons":{"A":"Sample size is not the issue here; the weakness is that the loyalty-card list excludes a whole group of shoppers from the Bucharest population.","B":"Interview length is a practical detail, not the central methodological flaw of selecting names solely from a loyalty-card membership list. For the business, the facts point to Non-members are excluded, so it may be unrepresentative, so this option cannot be correct.","D":"Question format is not dictated by the sampling frame; open or closed questions could be asked of either type of sample in this study.","C":"Using only loyalty-card members leaves out shoppers without cards, so the Bucharest sample may fail to represent all customers and could bias the opinion results."}}},{"id":"P1_U3_MCQ_1651","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1651","question":"A soft drink maker in Accra wants its cans available in every kiosk, supermarket and school canteen across the city. Which distribution strategy is the maker pursuing?","options":{"A":"Intensive distribution","B":"Exclusive distribution","C":"Selective distribution","D":"Direct mail selling"},"correctOption":"A","correctAnswer":"Intensive distribution","questionType":"MCQ","explanation":{"correct_reason":"Aiming to stock every kiosk, supermarket and canteen is intensive distribution, which maximises market coverage so the Accra soft drink can be bought almost anywhere a customer goes.","distractor_reasons":{"A":"Aiming to stock every kiosk, supermarket and canteen is intensive distribution, which maximises market coverage so the Accra soft drink can be bought almost anywhere a customer goes.","B":"Exclusive distribution limits sales to a single outlet in an area, the opposite of placing cans in every kiosk and supermarket right across Accra.","C":"Selective distribution uses a limited number of carefully chosen outlets, whereas the soft drink maker wants its cans in all possible outlets in the city.","D":"Direct mail selling sends offers straight to customers rather than placing goods in retail outlets, so it does not match the strategy described for Accra."}}},{"id":"P1_U3_MCQ_1652","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1652","question":"A mobile network in Kuala Lumpur offers free data to subscribers who stay for two years instead of spending heavily on adverts to attract new customers. Which strategic focus is this?","options":{"A":"Market development","B":"Mass marketing","C":"Price skimming","D":"Customer retention"},"correctOption":"D","correctAnswer":"Customer retention","questionType":"MCQ","explanation":{"correct_reason":"Rewarding existing subscribers with free data to encourage them to stay is a customer retention focus, aiming to keep current customers rather than chase new ones with advertising.","distractor_reasons":{"D":"Rewarding existing subscribers with free data to encourage them to stay is a customer retention focus, aiming to keep current customers rather than chase new ones with advertising.","A":"Market development means finding new customers or new areas, but the Kuala Lumpur network concentrates on keeping the subscribers it already has.","B":"Mass marketing addresses a broad audience with one message, whereas the loyalty reward is aimed specifically at existing subscribers who remain with the network.","C":"Skimming involves a high launch price for a new offering; free data for loyal customers is a retention incentive and not a launch pricing tactic."}}},{"id":"P1_U3_MCQ_1653","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1653","question":"The market for electric scooters in Rotterdam grew from $40 million to $52 million in a single year. Which conclusion can be drawn about this market from those figures?","options":{"A":"It is shrinking","B":"It is a growing market","C":"It has reached saturation","D":"Its total value is unchanged"},"correctOption":"B","correctAnswer":"It is a growing market","questionType":"MCQ","explanation":{"correct_reason":"Total market value rises from $40 million to $52 million, an increase of $12 million, so the Rotterdam electric scooter market is growing rather than contracting or saturated.","distractor_reasons":{"B":"Total market value rises from $40 million to $52 million, an increase of $12 million, so the Rotterdam electric scooter market is growing rather than contracting or saturated.","A":"The market value rises rather than falls; going from $40 million to $52 million shows clear expansion, not a shrinking market in Rotterdam.","C":"Saturation implies little room for further growth, but a rise of $12 million in one year suggests the Rotterdam market is still expanding.","D":"The value plainly changes, from $40 million up to $52 million, so it cannot correctly be described as unchanged over the year."}}},{"id":"P1_U3_MCQ_1654","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1654","question":"A furniture chain in Oslo interviews only shoppers who are buying a sofa when trying to discover why people do not visit its stores. What is the main flaw in this research?","options":{"A":"The questions are too open","B":"The sample is far too large","C":"It excludes the very people it aims to study","D":"It relies on secondary data"},"correctOption":"C","correctAnswer":"It excludes the very people it aims to study","questionType":"MCQ","explanation":{"correct_reason":"People buying sofas are precisely those who do visit the stores, so the Oslo chain misses non-visitors entirely and cannot learn why they stay away from its furniture shops.","distractor_reasons":{"C":"People buying sofas are precisely those who do visit the stores, so the Oslo chain misses non-visitors entirely and cannot learn why they stay away from its furniture shops.","A":"The difficulty is not question style but who is questioned; asking current buyers cannot reveal the views of people who never visit the Oslo stores.","B":"A large sample is normally helpful and no size is given; the weakness is that the chosen respondents are the wrong group of people altogether.","D":"The chain collects new responses from shoppers, so this is primary research; the problem lies in who is selected, not in using old information."}}},{"id":"P1_U3_MCQ_1655","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1655","question":"A household goods firm in Guadalajara adds a line of cleaning products alongside its existing cookware and bedding ranges. What has changed in its product mix?","options":{"A":"Its price structure","B":"Its distribution channels","C":"Its brand image only","D":"The width of its product mix"},"correctOption":"D","correctAnswer":"The width of its product mix","questionType":"MCQ","explanation":{"correct_reason":"Adding a cleaning products line alongside cookware and bedding increases the number of distinct product lines, so the width of the Guadalajara firm's product mix has grown.","distractor_reasons":{"D":"Adding a cleaning products line alongside cookware and bedding increases the number of distinct product lines, so the width of the Guadalajara firm's product mix has grown.","A":"No prices are mentioned in the scenario; adding a new category of goods changes the range offered rather than the firm's pricing structure.","B":"Distribution channels are not discussed; the change is in the variety of product lines made by the Guadalajara household goods firm.","C":"A new product line affects more than image alone, because it broadens what the company actually offers to customers in the household market."}}},{"id":"P1_U3_MCQ_1656","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1656","question":"A detergent brand in Lahore faces a new rival and responds with more advertising and loyalty rewards, hoping to keep its existing 22% share. What strategy is it pursuing?","options":{"A":"Defending market share","B":"Niche marketing","C":"Cost leadership","D":"Harvesting the market"},"correctOption":"A","correctAnswer":"Defending market share","questionType":"MCQ","explanation":{"correct_reason":"Increasing promotion and rewards to hold on to an existing 22% share is a strategy of defending market share against the new rival in the Lahore detergent market.","distractor_reasons":{"A":"Increasing promotion and rewards to hold on to an existing 22% share is a strategy of defending market share against the new rival in the Lahore detergent market.","B":"Niche marketing concentrates on a narrow segment, whereas the Lahore brand tries to protect its broad 22% share of the whole detergent market.","C":"Cost leadership means competing through low prices and costs, but the brand responds with advertising and loyalty rewards rather than cheaper production.","D":"Harvesting would cut spending to gain short-term cash, the opposite of raising advertising expenditure to defend the brand's position. The business's circumstances match Defending market share, so this option does not fit."}}},{"id":"P1_U3_MCQ_1657","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1657","question":"An online retailer in Tallinn reviews a year of order data and discovers that its buyers fall into two clear groups: price-conscious students and time-poor professionals. What has the retailer identified?","options":{"A":"Two distribution channels","B":"Two legal entities","C":"Two distinct customer segments","D":"Two production methods"},"correctOption":"C","correctAnswer":"Two distinct customer segments","questionType":"MCQ","explanation":{"correct_reason":"Students seeking low prices and professionals short of time have different needs, so the Tallinn retailer has identified two distinct customer segments within its market.","distractor_reasons":{"C":"Students seeking low prices and professionals short of time have different needs, so the Tallinn retailer has identified two distinct customer segments within its market.","A":"Distribution channels are ways of delivering goods; the retailer has instead grouped buyers according to their differing needs and priorities. The scenario for the business instead describes Two distinct customer segments, which rules this alternative out.","B":"Legal entities relate to company structure, not to groups of customers with differing buying behaviour in the Tallinn online market. In the business's case, the correct description is Two distinct customer segments, not this choice.","D":"Production methods concern how goods are made, whereas the retailer's discovery is about who its customers are and what they value."}}},{"id":"P1_U3_MCQ_1658","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1658","question":"A cosmetics brand in Oslo combines sales figures, a customer survey and focus groups before deciding on a new fragrance. What is the main benefit of using several research methods?","options":{"A":"It guarantees a successful product","B":"Findings can be cross-checked for greater reliability","C":"It removes all research costs","D":"It makes surveys unnecessary"},"correctOption":"B","correctAnswer":"Findings can be cross-checked for greater reliability","questionType":"MCQ","explanation":{"correct_reason":"Using sales data, a survey and focus groups lets the Oslo brand cross-check findings from different sources, improving the reliability of the decision about its new fragrance.","distractor_reasons":{"B":"Using sales data, a survey and focus groups lets the Oslo brand cross-check findings from different sources, improving the reliability of the decision about its new fragrance.","A":"Several methods improve the evidence but cannot guarantee success, because customer tastes may still change after the Oslo fragrance is launched.","C":"Running three research methods costs more rather than less, and there is no suggestion that the cosmetics brand avoids all research spending.","D":"The brand deliberately keeps the survey alongside other methods, so surveys are clearly still part of its research process for the new fragrance."}}},{"id":"P1_U3_MCQ_1659","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1659","question":"A detergent brand in Glasgow holds 16% of a market worth $250 million and spends $8 million on advertising. What is its sales revenue, and what share of that revenue is the advertising?","options":{"A":"$40 million and 10%","B":"$25 million and 32%","C":"$40 million and 20%","D":"$16 million and 50%"},"correctOption":"C","correctAnswer":"$40 million and 20%","questionType":"MCQ","explanation":{"correct_reason":"A 16% share of the $250 million market gives $40 million of sales, so the $8 million advertising spend equals 20% of the Glasgow detergent brand's revenue.","distractor_reasons":{"C":"A 16% share of the $250 million market gives $40 million of sales, so the $8 million advertising spend equals 20% of the Glasgow detergent brand's revenue.","A":"The $40 million sales figure is correct, but $8 million is 20% of $40 million rather than 10% of the Glasgow brand's sales revenue.","B":"$25 million would be 10% of the market; at the stated 16% share the brand actually sells $40 million worth of detergent.","D":"$16 million confuses the 16% share with a dollar amount; the brand's sales are $40 million and advertising is 20% of that revenue."}}},{"id":"P1_U3_MCQ_1660","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1660","question":"A delivery app in Manila launches ahead of rivals in a small city and quickly builds a large user base and strong brand recognition. Which strategic advantage is it gaining?","options":{"A":"First-mover advantage","B":"Cost leadership","C":"Market skimming","D":"Niche concentration"},"correctOption":"A","correctAnswer":"First-mover advantage","questionType":"MCQ","explanation":{"correct_reason":"Launching ahead of competitors lets the Manila app secure users and brand awareness before rivals arrive, which is the essence of a first-mover advantage in a new market.","distractor_reasons":{"A":"Launching ahead of competitors lets the Manila app secure users and brand awareness before rivals arrive, which is the essence of a first-mover advantage in a new market.","B":"Cost leadership requires being the lowest-cost provider, but the advantage described is being early and building recognition, not having lower operating costs.","C":"Skimming concerns setting a high initial price, and no pricing decision is mentioned for the early launch of the Manila delivery app.","D":"Niche concentration focuses on a narrow customer group, whereas the Manila app builds a broad user base across the city ahead of its rivals."}}},{"id":"P1_U3_MCQ_1661","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1661","question":"A yogurt brand in Kampala doubles its sales while the total market for yogurt triples in size over the same period. What happens to the brand's market share?","options":{"A":"It doubles","B":"It stays unchanged","C":"It falls","D":"It triples"},"correctOption":"C","correctAnswer":"It falls","questionType":"MCQ","explanation":{"correct_reason":"If the brand's sales double but the whole market grows threefold, the brand's portion of that market becomes smaller, so its market share falls even though its sales rise.","distractor_reasons":{"C":"If the brand's sales double but the whole market grows threefold, the brand's portion of that market becomes smaller, so its market share falls even though its sales rise.","A":"Doubling sales does not double share because the total Kampala market grows even faster, by three times its original size over the period.","B":"A constant share would require sales to triple along with the market; sales only double, so the brand loses ground proportionately.","D":"Tripling the market does not triple the brand's share; with its sales only doubling, the brand's percentage of the larger market declines."}}},{"id":"P1_U3_MCQ_1662","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1662","question":"A survey in Naples asks respondents, 'How much do you love our delicious new pasta sauce?' before they have tasted it. What is the main problem with this question?","options":{"A":"It is a closed question","B":"It is leading and may bias answers","C":"It asks only about the price","D":"It relies on secondary data"},"correctOption":"B","correctAnswer":"It is leading and may bias answers","questionType":"MCQ","explanation":{"correct_reason":"Calling the sauce delicious and asking how much respondents love it pushes them towards a positive reply, so the Naples question is leading and is likely to bias the answers.","distractor_reasons":{"B":"Calling the sauce delicious and asking how much respondents love it pushes them towards a positive reply, so the Naples question is leading and is likely to bias the answers.","A":"The question need not be closed, since respondents could answer freely; its real flaw is flattering wording rather than the format of the answers.","C":"The question concerns liking the sauce rather than its price, so a focus on price does not describe the difficulty with this Naples survey item.","D":"A survey question gathers primary data from respondents, so the issue is the biased wording, not any dependence on secondary information."}}},{"id":"P1_U3_MCQ_1663","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1663","question":"A museum in Vienna charges half price for students and pensioners while adults pay the full admission fee. Which pricing practice is the museum using?","options":{"A":"Cost-plus pricing","B":"Loss leader pricing","C":"Penetration pricing","D":"Price discrimination"},"correctOption":"D","correctAnswer":"Price discrimination","questionType":"MCQ","explanation":{"correct_reason":"Charging different prices to distinct customer groups for the same museum entry is price discrimination, using student and pensioner status to separate buyers by willingness to pay.","distractor_reasons":{"D":"Charging different prices to distinct customer groups for the same museum entry is price discrimination, using student and pensioner status to separate buyers by willingness to pay.","A":"Cost-plus pricing adds a mark-up to costs, but the Vienna museum sets different prices by customer type rather than calculating a single cost-based price.","B":"A loss leader sells an item below cost to attracting other purchases, whereas reduced student tickets at the museum are simply a cheaper category of admission.","C":"Penetration pricing sets a low launch price to enter a market, while the Vienna museum routinely charges different groups different admission prices."}}},{"id":"P1_U3_MCQ_1664","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1664","question":"A perfume brand in Paris wants to increase repeat purchases among its existing customers rather than concentrate on finding new buyers. Which marketing objective does this represent?","options":{"A":"Customer retention objective","B":"Market growth objective","C":"New product objective","D":"Market share objective"},"correctOption":"A","correctAnswer":"Customer retention objective","questionType":"MCQ","explanation":{"correct_reason":"Encouraging existing perfume buyers to purchase again is a customer retention objective, focused on keeping current customers instead of attracting new ones in Paris.","distractor_reasons":{"A":"Encouraging existing perfume buyers to purchase again is a customer retention objective, focused on keeping current customers instead of attracting new ones in Paris.","B":"A market growth objective would seek more customers or higher total sales, but this Paris brand concentrates on repeat buying by the people it already serves.","C":"A new product objective would involve launching a fragrance, whereas the scenario is about encouraging repeat purchases among existing perfume customers.","D":"A market share objective compares the brand's sales with total market sales, and no such comparison is stated for the Paris perfume brand."}}},{"id":"P1_U3_MCQ_1665","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1665","question":"A snack brand in Lima sees its market share rise even though its own total sales revenue is unchanged. What must have happened to the overall snack market?","options":{"A":"The market must have grown","B":"The market must have stayed the same","C":"The market must have shrunk","D":"The market must have doubled"},"correctOption":"C","correctAnswer":"The market must have shrunk","questionType":"MCQ","explanation":{"correct_reason":"Share equals own sales divided by total market sales, so with the Lima brand's sales unchanged, a higher share can only arise if total sales in the snack market have fallen.","distractor_reasons":{"C":"Share equals own sales divided by total market sales, so with the Lima brand's sales unchanged, a higher share can only arise if total sales in the snack market have fallen.","A":"If the market grew while the brand's sales stayed flat, its share would fall rather than rise, because the denominator would be larger.","B":"An unchanged market combined with unchanged brand sales would leave the share exactly the same, so it cannot explain a rise in share.","D":"A doubled market would roughly halve the brand's share if its sales were unchanged, whereas the scenario says the share actually rose."}}},{"id":"P1_U3_MCQ_1666","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1666","question":"A polling firm in Wellington draws 200 names at random from the city electoral register to estimate residents' opinions about shopping. What sampling approach is this?","options":{"A":"Quota sampling","B":"Simple random sampling","C":"Observation","D":"Secondary research"},"correctOption":"B","correctAnswer":"Simple random sampling","questionType":"MCQ","explanation":{"correct_reason":"Drawing names at random from a complete register gives each resident an equal chance of selection, which is simple random sampling for the Wellington opinion poll.","distractor_reasons":{"B":"Drawing names at random from a complete register gives each resident an equal chance of selection, which is simple random sampling for the Wellington opinion poll.","A":"Quota sampling fixes numbers from sub-groups and lets interviewers choose within them, whereas the Wellington firm draws names randomly from a register.","C":"Observation records behaviour without questioning people, but the Wellington firm selects respondents in order to ask about their shopping opinions. The business's circumstances match Simple random sampling, so this option does not fit.","D":"Secondary research reuses earlier data, whereas the firm creates a new sample from the electoral register and questions those residents directly."}}},{"id":"P1_U3_MCQ_1667","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1667","question":"A vacuum cleaner maker in Turin offers a free five-year service plan that no rival matches, while keeping its list price unchanged. How is the maker seeking an advantage?","options":{"A":"Through lower prices","B":"Through wider distribution","C":"Through heavier advertising","D":"Through a distinctive product benefit"},"correctOption":"D","correctAnswer":"Through a distinctive product benefit","questionType":"MCQ","explanation":{"correct_reason":"A five-year service plan unmatched by competitors is a distinctive product benefit, so the Turin maker seeks advantage through the product rather than through price, place or promotion.","distractor_reasons":{"D":"A five-year service plan unmatched by competitors is a distinctive product benefit, so the Turin maker seeks advantage through the product rather than through price, place or promotion.","A":"The list price is unchanged, so the firm is not competing by being cheaper; its appeal lies in the extra service attached to the vacuum cleaner.","B":"No change in the number or type of outlets is described, so the advantage does not come from wider distribution of the Turin vacuum cleaners.","C":"Advertising may communicate the offer, but the true source of advantage is the service benefit itself rather than spending more on promotion."}}},{"id":"P1_U3_MCQ_1668","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1668","question":"A bank in Nairobi creates a separate mobile savings account for market traders with features matching their daily cash flow, instead of one account for everyone. Which strategy is this?","options":{"A":"Targeted marketing to a segment","B":"Undifferentiated marketing","C":"Mass marketing","D":"Cost leadership"},"correctOption":"A","correctAnswer":"Targeted marketing to a segment","questionType":"MCQ","explanation":{"correct_reason":"Designing an account specifically for market traders targets one segment with features suited to its cash flow, rather than offering an identical account to every Nairobi customer.","distractor_reasons":{"A":"Designing an account specifically for market traders targets one segment with features suited to its cash flow, rather than offering an identical account to every Nairobi customer.","B":"Undifferentiated marketing offers the same product to all buyers, unlike the Nairobi bank's account built specially for market traders. The details given about the business support Targeted marketing to a segment, so this answer is unsuitable.","C":"Mass marketing aims at the whole market with one broad message, whereas the Nairobi bank concentrates on a particular group of customers.","D":"Cost leadership means competing through low costs and prices, but the scenario emphasises tailoring account features to a specific group of traders."}}},{"id":"P1_U3_MCQ_1669","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1669","question":"Total sales in the mobile phone market in Lima are flat, but one brand's sales are rising quickly. What must be happening to that brand's competitors?","options":{"A":"They are all growing as well","B":"Their costs must be falling","C":"They are collectively losing market share","D":"The whole market is shrinking"},"correctOption":"C","correctAnswer":"They are collectively losing market share","questionType":"MCQ","explanation":{"correct_reason":"With total market sales flat and one brand gaining sales, the other firms must together be losing sales and therefore losing market share in the Lima mobile phone market.","distractor_reasons":{"C":"With total market sales flat and one brand gaining sales, the other firms must together be losing sales and therefore losing market share in the Lima mobile phone market.","A":"If competitors were all growing as well, total market sales would rise; flat total sales mean one brand's gains come at the expense of others.","B":"Costs are not mentioned, and the conclusion concerns market shares, which depend on sales rather than on the producers' cost levels.","D":"The market is flat rather than shrinking; the gain by one Lima brand is offset by declines among its competitors in the same period."}}},{"id":"P1_U3_MCQ_1670","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1670","question":"A snack firm in Quito runs a small trial of a new flavour in two districts before a national launch, checking purchase rates and customer comments. What is the purpose of this pilot?","options":{"A":"To avoid the need for any further research","B":"To test response on a small scale before a full launch","C":"To decide the company's legal structure","D":"To eliminate competing snack firms"},"correctOption":"B","correctAnswer":"To test response on a small scale before a full launch","questionType":"MCQ","explanation":{"correct_reason":"A limited trial in two Quito districts lets the firm measure real purchase rates and reactions before spending on a national launch, reducing the risk of a failed flavour.","distractor_reasons":{"B":"A limited trial in two Quito districts lets the firm measure real purchase rates and reactions before spending on a national launch, reducing the risk of a failed flavour.","A":"A pilot does not end research; the comments gathered in the Quito trial inform decisions and may prompt further testing before the national launch.","C":"Legal structure concerns ownership and liability, which is unrelated to testing how customers respond to a new snack flavour in Quito.","D":"A small product trial cannot remove competitors from the market; its purpose is to learn about demand before committing to a wider launch."}}},{"id":"P1_U3_MCQ_1671","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1671","question":"A date shop in Istanbul sends out 4,000 boxes priced at $6 each, but 500 boxes are returned unsold and cannot be charged for. What is the shop's actual revenue?","options":{"A":"$24,000","B":"$21,500","C":"$22,500","D":"$21,000"},"correctOption":"D","correctAnswer":"$21,000","questionType":"MCQ","explanation":{"correct_reason":"Only 4,000 minus 500, which is 3,500 boxes, are actually paid for, and 3,500 multiplied by $6 gives $21,000 of revenue for the Istanbul date shop.","distractor_reasons":{"D":"Only 4,000 minus 500, which is 3,500 boxes, are actually paid for, and 3,500 multiplied by $6 gives $21,000 of revenue for the Istanbul date shop.","A":"$24,000 assumes all 4,000 boxes are sold and ignores the 500 returned boxes for which the Istanbul shop can charge nothing.","B":"$21,500 would result from treating only 416 of the 500 returned boxes as unsold, but all 500 returns generate no revenue at all.","C":"$22,500 would imply 3,750 paid boxes, whereas the Istanbul shop receives payment for 3,500 boxes after the 500 returns. The details given about the business support $21,000, so this answer is unsuitable."}}},{"id":"P1_U3_MCQ_1672","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1672","question":"A laptop brand in Taipei is known for long battery life and targets travelling professionals, while a rival stresses its low price. How are the two brands competing?","options":{"A":"Through different positions in the same market","B":"Through identical positioning","C":"By both leaving the market","D":"Through legal restructuring"},"correctOption":"A","correctAnswer":"Through different positions in the same market","questionType":"MCQ","explanation":{"correct_reason":"One Taipei brand positions itself on battery life for travellers and the rival on low price, so they occupy different positions within the same laptop market.","distractor_reasons":{"A":"One Taipei brand positions itself on battery life for travellers and the rival on low price, so they occupy different positions within the same laptop market.","B":"Their positions are plainly different, since one sells endurance for travelling professionals and the other makes a low-price appeal to buyers.","C":"Neither brand is leaving the market; both continue to sell laptops but appeal to customers through different benefits and images. For the business, the facts point to Through different positions in the same market, so this option cannot be correct.","D":"Legal restructuring concerns company ownership, whereas the comparison here is about how the two brands are positioned in customers' minds. The scenario for the business instead describes Through different positions in the same market, which rules this alternative out."}}},{"id":"P1_U3_MCQ_1673","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1673","question":"A smoothie bar in Miami finds that customers say they want sweeter drinks, but sales data show the fastest growth is in low-sugar options. Which approach best explains this?","options":{"A":"Ignoring all customer data","B":"Following stated wants only","C":"Distinguishing stated wants from revealed behaviour","D":"Removing every product line"},"correctOption":"C","correctAnswer":"Distinguishing stated wants from revealed behaviour","questionType":"MCQ","explanation":{"correct_reason":"The Miami bar compares what customers say they want with what they actually buy, distinguishing stated wants from revealed behaviour when deciding its smoothie range.","distractor_reasons":{"C":"The Miami bar compares what customers say they want with what they actually buy, distinguishing stated wants from revealed behaviour when deciding its smoothie range.","A":"The bar uses both comments and sales data, so it is not ignoring customer information but interpreting two different kinds of evidence about preferences.","B":"Following stated wants alone would mean making drinks sweeter, yet the Miami sales data point to growing demand for low-sugar smoothies instead.","D":"There is no suggestion of removing all product lines; the bar is weighing conflicting signals about what its customers truly prefer."}}},{"id":"P1_U3_MCQ_1674","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1674","question":"A research firm in Lisbon uses an outdated address list that omits newly built neighbourhoods when recruiting people for a survey. What problem is most likely to result?","options":{"A":"Every respondent will be too young","B":"Some residents have no chance of selection and results may be biased","C":"The survey will be far too cheap","D":"The collected data will be secondary"},"correctOption":"B","correctAnswer":"Some residents have no chance of selection and results may be biased","questionType":"MCQ","explanation":{"correct_reason":"An address list missing new neighbourhoods excludes those residents entirely, so the Lisbon sample cannot represent the whole population and the survey findings may be biased.","distractor_reasons":{"B":"An address list missing new neighbourhoods excludes those residents entirely, so the Lisbon sample cannot represent the whole population and the survey findings may be biased.","A":"Age is not the issue here; the omission is of whole neighbourhoods, which are likely to contain residents from every age group.","C":"Cost is not the concern; the difficulty is coverage of the population, not how much the Lisbon survey ultimately costs to run.","D":"Responses collected from recruited participants are primary data, so the weakness lies in the sampling frame used to find those people."}}},{"id":"P1_U3_MCQ_1675","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1675","question":"A baker in Krakow delivers bread to 50 cafes and sells none through a shop of its own. Which element of the marketing mix does this arrangement mainly illustrate?","options":{"A":"Product","B":"Price","C":"Promotion","D":"Place"},"correctOption":"D","correctAnswer":"Place","questionType":"MCQ","explanation":{"correct_reason":"Supplying 50 cafes and having no own shop is a decision about distribution channels and outlets, which is the place element of the marketing mix for the Krakow baker.","distractor_reasons":{"D":"Supplying 50 cafes and having no own shop is a decision about distribution channels and outlets, which is the place element of the marketing mix for the Krakow baker.","A":"The bread recipe and packaging are not discussed; the scenario describes where the Krakow baker's bread is made available to customers.","B":"No selling price is given, so this arrangement cannot be classified as a pricing decision for the bread produced by the Krakow baker.","C":"Promotion concerns advertising and sales messages, whereas delivering bread to 50 cafes is about getting the product to where buyers can access it."}}},{"id":"P1_U3_MCQ_1676","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1676","question":"A rice exporter in Bangkok decides to sell its existing product in three new countries rather than increase sales in the markets it already serves. Which growth strategy is this?","options":{"A":"Increasing share of current markets","B":"Improving existing products","C":"Cutting production costs","D":"Entering new geographic markets"},"correctOption":"D","correctAnswer":"Entering new geographic markets","questionType":"MCQ","explanation":{"correct_reason":"Taking its rice into three new countries is geographic market expansion, seeking growth from new markets rather than from a larger share of the Bangkok exporter's current ones.","distractor_reasons":{"D":"Taking its rice into three new countries is geographic market expansion, seeking growth from new markets rather than from a larger share of the Bangkok exporter's current ones.","A":"Increasing share of current markets would mean selling more rice where the Bangkok exporter already operates, not opening up three new countries.","B":"Improving existing products concerns changes to the rice itself, whereas the decision is to sell the same product in additional countries.","C":"Cutting production costs is an efficiency measure rather than a growth route into three new countries for the rice exporter. The details given about the business support Entering new geographic markets, so this answer is unsuitable."}}},{"id":"P1_U3_MCQ_1677","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1677","question":"A cinema in Adelaide treats streaming services and rival cinemas as competitors when measuring its market. How does this wider definition affect its market share calculation?","options":{"A":"It makes the measured market smaller","B":"It broadens the market, reducing its share","C":"It has no effect on the share","D":"It automatically doubles its share"},"correctOption":"B","correctAnswer":"It broadens the market, reducing its share","questionType":"MCQ","explanation":{"correct_reason":"Counting streaming services alongside other cinemas enlarges the total market used as the denominator, so the Adelaide cinema's measured share becomes smaller than if only cinemas were counted.","distractor_reasons":{"B":"Counting streaming services alongside other cinemas enlarges the total market used as the denominator, so the Adelaide cinema's measured share becomes smaller than if only cinemas were counted.","A":"Adding streaming services widens rather than narrows the market definition, so the denominator grows and the cinema's measured share falls. The business's circumstances match It broadens the market, reducing its share, so this option does not fit.","C":"Market definition matters because share divides the cinema's sales by total market sales; adding competitors changes the denominator and thus the share.","D":"Nothing doubles here; widening the Adelaide market to include streaming would lower, not raise, the cinema's percentage share. The scenario for the business instead describes It broadens the market, reducing its share, which rules this alternative out."}}},{"id":"P1_U3_MCQ_1678","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1678","question":"A market researcher in Toronto offers gift vouchers to children in exchange for completing a survey about snacks, without informing their parents. What is the main ethical concern?","options":{"A":"The resulting data will be inaccurate","B":"The sample is far too large","C":"Consent from parents and participants is lacking","D":"The questions are all closed"},"correctOption":"C","correctAnswer":"Consent from parents and participants is lacking","questionType":"MCQ","explanation":{"correct_reason":"Rewarding children to complete a survey without parental permission raises a consent and exploitation concern, so the Toronto study fails to protect vulnerable research participants.","distractor_reasons":{"C":"Rewarding children to complete a survey without parental permission raises a consent and exploitation concern, so the Toronto study fails to protect vulnerable research participants.","A":"Accuracy may be affected, but the central ethical issue is that children are questioned and rewarded without proper parental consent in Toronto.","B":"No sample size is given, and size alone is not an ethical matter; the concern is permission from parents and the children themselves.","D":"Question format is not an ethical problem here; closed questions could be perfectly acceptable if proper consent had been obtained. In the business's case, the correct description is Consent from parents and participants is lacking, not this choice."}}},{"id":"P1_U3_MCQ_1679","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1679","question":"A supermarket in Tunis matches a rival's price cut on flour rather than trying to undercut it, keeping its own price identical to the competitor's. Which pricing approach is this?","options":{"A":"Price skimming","B":"Cost-plus pricing","C":"Penetration pricing","D":"Competitive going-rate pricing"},"correctOption":"D","correctAnswer":"Competitive going-rate pricing","questionType":"MCQ","explanation":{"correct_reason":"Setting its flour price to match a rival's rather than calculating from costs or undercutting is competitive going-rate pricing, as used by the Tunis supermarket.","distractor_reasons":{"D":"Setting its flour price to match a rival's rather than calculating from costs or undercutting is competitive going-rate pricing, as used by the Tunis supermarket.","A":"Skimming starts with a high price and later reduces it; the Tunis supermarket simply follows the current price set by a competitor.","B":"Cost-plus pricing would add a mark-up to the flour's cost, but the supermarket bases its decision on the rival's price instead.","C":"Penetration pricing sets a deliberately low launch price to win share, whereas the Tunis match merely follows an existing competitor's cut."}}},{"id":"P1_U3_MCQ_1680","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1680","question":"A clothing brand in Madrid focuses on affordable, modest styles for young Muslim women rather than attempting to appeal to every shopper. Which strategy gives it the clearest advantage?","options":{"A":"Concentrating on a specific segment","B":"Undifferentiated mass marketing","C":"Producing the widest possible range","D":"Copying every rival's designs"},"correctOption":"A","correctAnswer":"Concentrating on a specific segment","questionType":"MCQ","explanation":{"correct_reason":"Concentrating on one clearly defined group lets the Madrid brand tailor styles and messages to those buyers, which is the advantage of a focused segment strategy.","distractor_reasons":{"A":"Concentrating on one clearly defined group lets the Madrid brand tailor styles and messages to those buyers, which is the advantage of a focused segment strategy.","B":"Undifferentiated mass marketing appeals to everyone with one offer, the opposite of the Madrid brand's deliberate focus on a specific group.","C":"Producing the widest range would spread resources thinly and dilute the brand's appeal, rather than concentrating on a defined group of buyers.","D":"Copying rivals' designs would remove the brand's distinctiveness, whereas focusing on a specific group gives it a clear position in Madrid."}}},{"id":"P1_U3_MCQ_1681","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1681","question":"The market for cosmetics in Osaka grew from $90 million to $108 million over one year. What was the market's percentage growth rate during that year?","options":{"A":"12%","B":"20%","C":"18%","D":"8%"},"correctOption":"B","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"Growth is the change divided by the starting value, so $108 million minus $90 million is $18 million, and $18 million over $90 million equals 20% market growth in Osaka.","distractor_reasons":{"B":"Growth is the change divided by the starting value, so $108 million minus $90 million is $18 million, and $18 million over $90 million equals 20% market growth in Osaka.","A":"12% would require an increase of $10.8 million; the Osaka cosmetics market actually expanded by $18 million from $90 million to $108 million.","C":"18% is the increase expressed in millions of dollars rather than a percentage; $18 million must be divided by the original $90 million to give 20%.","D":"8% would arise from dividing $18 million by the ending value of $108 million; percentage growth uses the starting value of $90 million."}}},{"id":"P1_U3_MCQ_1682","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1682","question":"A hotel chain in Edinburgh asks guests, 'What could we improve about your stay?', allowing answers of any length. What is the main advantage of this type of question?","options":{"A":"Answers are very quick to count","B":"It produces only numerical answers","C":"It can reveal unexpected issues the hotel had not considered","D":"It guarantees a higher response rate"},"correctOption":"C","correctAnswer":"It can reveal unexpected issues the hotel had not considered","questionType":"MCQ","explanation":{"correct_reason":"An open question lets Edinburgh guests raise issues the hotel had not anticipated, giving richer insight than a fixed list of possible answers would allow.","distractor_reasons":{"C":"An open question lets Edinburgh guests raise issues the hotel had not anticipated, giving richer insight than a fixed list of possible answers would allow.","A":"Open answers are harder and slower to count than closed ones, so ease of analysis is not the advantage claimed for this Edinburgh question.","B":"Open questions produce words rather than only numbers, so the hotel gains comments and explanations from the guests who answer. For the business, the facts point to It can reveal unexpected issues the hotel had not considered, so this option cannot be correct.","D":"Open questions do not guarantee better response rates; guests may still choose not to answer, so this is not a certain benefit."}}},{"id":"P1_U3_MCQ_1683","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1683","question":"A tea company in Hangzhou sells eight different blends within its single loose-leaf tea line, all packed in identical tins. What does this illustrate about the company's product mix?","options":{"A":"A narrow product mix width","B":"A short product line","C":"A single distribution channel","D":"A long product line"},"correctOption":"D","correctAnswer":"A long product line","questionType":"MCQ","explanation":{"correct_reason":"Eight blends in one loose-leaf line show the length of that line, so the Hangzhou tea company has a long product line of closely related items.","distractor_reasons":{"D":"Eight blends in one loose-leaf line show the length of that line, so the Hangzhou tea company has a long product line of closely related items.","A":"Width refers to how many different lines are offered, whereas the scenario describes many items inside one line, which is a matter of length.","B":"A short line would contain only a few items; eight distinct blends make a relatively long line of loose-leaf teas in Hangzhou.","C":"Distribution channels concern where goods are sold, not how many different blends the Hangzhou tea company offers in its product line."}}},{"id":"P1_U3_MCQ_1684","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1684","question":"A snack brand in Bogota wants to grow sales without changing its product or entering new countries, by taking customers away from rivals. Which route to growth is this?","options":{"A":"Increasing share of its existing market","B":"Product development","C":"Geographic expansion","D":"Diversification"},"correctOption":"A","correctAnswer":"Increasing share of its existing market","questionType":"MCQ","explanation":{"correct_reason":"Winning customers from competitors while keeping the same product and staying in Bogota is growth through a larger share of the brand's existing snack market.","distractor_reasons":{"A":"Winning customers from competitors while keeping the same product and staying in Bogota is growth through a larger share of the brand's existing snack market.","B":"Product development would involve new or improved snacks, but the Bogota brand keeps its product unchanged and competes for existing buyers.","C":"Geographic expansion means entering other countries or regions, which the Bogota brand explicitly avoids in this growth plan. The business's circumstances match Increasing share of its existing market, so this option does not fit.","D":"Diversification means moving into unrelated products, whereas the Bogota brand stays in the same snack market to chase rivals' customers. The details given about the business support Increasing share of its existing market, so this answer is unsuitable."}}},{"id":"P1_U3_MCQ_1685","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1685","question":"A hotel in Cancun installs quiet air conditioning in every bedroom after guests repeatedly complain about noise at night. Which marketing concept does this decision illustrate?","options":{"A":"Production orientation","B":"Satisfying customer needs","C":"Sales orientation","D":"Market skimming"},"correctOption":"B","correctAnswer":"Satisfying customer needs","questionType":"MCQ","explanation":{"correct_reason":"Responding to repeated guest complaints by installing quieter units shows the Cancun hotel identifying and satisfying a genuine customer need about comfort at night.","distractor_reasons":{"B":"Responding to repeated guest complaints by installing quieter units shows the Cancun hotel identifying and satisfying a genuine customer need about comfort at night.","A":"Production orientation emphasises efficient output and cost control, not changing equipment because guests in Cancun complain about noise. In the business's case, the correct description is Satisfying customer needs, not this choice.","C":"Sales orientation pushes existing services harder through promotion; the hotel instead changes the service itself to meet a clearly stated need.","D":"Skimming concerns a high launch price, which has nothing to do with responding to guest complaints about noisy air conditioning in Cancun."}}},{"id":"P1_U3_MCQ_1686","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1686","question":"A research team in Helsinki uses a questionnaire written in English for respondents who mainly speak Finnish, with no translation provided. What is the main threat to the results?","options":{"A":"The sample will be too large","B":"The data will be secondary","C":"Respondents may misunderstand questions and answer unreliably","D":"The questions will be too closed"},"correctOption":"C","correctAnswer":"Respondents may misunderstand questions and answer unreliably","questionType":"MCQ","explanation":{"correct_reason":"If Helsinki respondents do not understand the English questions well, their answers may not reflect their true views, so the untranslated survey results lack validity.","distractor_reasons":{"C":"If Helsinki respondents do not understand the English questions well, their answers may not reflect their true views, so the untranslated survey results lack validity.","A":"Sample size is not the issue; the problem is that language barriers can distort what the Finnish-speaking respondents report in their answers.","B":"The questionnaire collects new answers, which are primary data; the threat comes from comprehension, not from reusing old information. The details given about the business support Respondents may misunderstand questions and answer unreliably, so this answer is unsuitable.","D":"Closed questions can be valid if respondents understand them; the difficulty in Helsinki is the untranslated language, not the answer format."}}},{"id":"P1_U3_MCQ_1687","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1687","question":"A bakery in Seville sells 1,000 loaves at $2 each and 200 cakes at $4 each, but gives a 25% discount on every cake. What is the bakery's total revenue?","options":{"A":"$2,400","B":"$2,800","C":"$2,000","D":"$2,600"},"correctOption":"D","correctAnswer":"$2,600","questionType":"MCQ","explanation":{"correct_reason":"Loaves bring 1,000 multiplied by $2, which is $2,000, and 200 cakes after a 25% discount sell for $3 each, adding $600, so total Seville bakery revenue is $2,600.","distractor_reasons":{"D":"Loaves bring 1,000 multiplied by $2, which is $2,000, and 200 cakes after a 25% discount sell for $3 each, adding $600, so total Seville bakery revenue is $2,600.","A":"$2,400 would arise if the 25% discount were also applied to the loaves, but only the 200 cakes in Seville are reduced in price.","B":"$2,800 assumes all 200 cakes sell at the full $4, ignoring the 25% discount that cuts cake revenue down to $600.","C":"$2,000 counts only the 1,000 loaves and leaves out entirely the $600 earned from the discounted cakes in Seville. The scenario for the business instead describes $2,600, which rules this alternative out."}}},{"id":"P1_U3_MCQ_1688","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1688","question":"A coffee chain in Vancouver gives a free drink after ten purchases to encourage repeat visits. What is the main strategic aim of this scheme?","options":{"A":"Building customer loyalty and repeat custom","B":"Reducing the range of drinks","C":"Entering new geographic markets","D":"Changing the company's legal structure"},"correctOption":"A","correctAnswer":"Building customer loyalty and repeat custom","questionType":"MCQ","explanation":{"correct_reason":"Rewarding ten purchases with a free drink encourages Vancouver customers to return, so the scheme aims to build loyalty and repeat business rather than attract one-off buyers.","distractor_reasons":{"A":"Rewarding ten purchases with a free drink encourages Vancouver customers to return, so the scheme aims to build loyalty and repeat business rather than attract one-off buyers.","B":"Nothing suggests fewer drinks are offered; the loyalty card changes the rewards, not the range of coffee available in Vancouver. The scenario for the business instead describes Building customer loyalty and repeat custom, which rules this alternative out.","C":"The scheme targets existing customers rather than entering new geographic markets or seeking entirely new customer groups. In the business's case, the correct description is Building customer loyalty and repeat custom, not this choice.","D":"Legal structure concerns ownership and liability, which is unrelated to a Vancouver coffee shop's repeat-purchase reward scheme. The business's circumstances match Building customer loyalty and repeat custom, so this option does not fit."}}},{"id":"P1_U3_MCQ_1689","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1689","question":"Two firms in a market have identical sales revenue, but one sells many more units at lower prices. Which statement about their market shares is correct?","options":{"A":"The higher-price firm has a larger share","B":"They have equal market share by value","C":"The lower-price firm has a larger share","D":"Neither firm has any measurable share"},"correctOption":"B","correctAnswer":"They have equal market share by value","questionType":"MCQ","explanation":{"correct_reason":"Market share by value uses sales revenue, so with equal revenue both firms hold the same share of total market value, even though their unit volumes differ sharply.","distractor_reasons":{"B":"Market share by value uses sales revenue, so with equal revenue both firms hold the same share of total market value, even though their unit volumes differ sharply.","A":"A higher price does not create a larger value share when revenues are equal; both firms contribute the same sales value to the total market.","C":"Selling more units at lower prices need not give a larger value share, because the total sales revenue recorded by the two firms is the same.","D":"Both firms record sales revenue, so each must hold a positive share of the total value of the market they compete in."}}},{"id":"P1_U3_MCQ_1690","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1690","question":"A toy firm in Montreal brings together eight parents and a moderator to discuss what they want from a new board game. Which market research method is being used?","options":{"A":"Postal survey","B":"Observation in shops","C":"Focus group","D":"Secondary report"},"correctOption":"C","correctAnswer":"Focus group","questionType":"MCQ","explanation":{"correct_reason":"A moderator leading a discussion with eight parents is a focus group, which gathers qualitative views about the board game directly from potential buyers in Montreal.","distractor_reasons":{"C":"A moderator leading a discussion with eight parents is a focus group, which gathers qualitative views about the board game directly from potential buyers in Montreal.","A":"A postal survey sends written questions to many respondents rather than convening a small group for a moderated discussion in Montreal.","B":"Observation would watch shoppers' behaviour silently, whereas the toy firm asks parents to express their views in a group discussion setting.","D":"A secondary report reuses information gathered earlier by others, but the Montreal firm generates new comments from the parents it brings together."}}},{"id":"P1_U3_MCQ_1691","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1691","question":"A luxury watchmaker in Geneva sells its watches through only three authorised dealers worldwide in order to preserve exclusivity and control service quality. Which distribution policy is being followed?","options":{"A":"Intensive distribution","B":"Selective distribution","C":"Mass distribution","D":"Exclusive distribution"},"correctOption":"D","correctAnswer":"Exclusive distribution","questionType":"MCQ","explanation":{"correct_reason":"Limiting sales to just three authorised dealers is exclusive distribution, used by the Geneva watchmaker to control availability and protect the brand's exclusive image.","distractor_reasons":{"D":"Limiting sales to just three authorised dealers is exclusive distribution, used by the Geneva watchmaker to control availability and protect the brand's exclusive image.","A":"Intensive distribution aims for very wide availability, the opposite of the three-dealer policy chosen by the Geneva watchmaker. The details given about the business support Exclusive distribution, so this answer is unsuitable.","B":"Selective distribution uses several carefully chosen outlets, whereas restricting sales to only three dealers worldwide is far more exclusive. For the business, the facts point to Exclusive distribution, so this option cannot be correct.","C":"Mass distribution puts products in as many outlets as possible, which would undermine the exclusivity the Geneva watchmaker wants to preserve."}}},{"id":"P1_U3_MCQ_1692","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1692","question":"A detergent brand in Manila cuts its price below rivals and sees its market share rise, but its profit per unit falls. What trade-off is the brand making?","options":{"A":"Trading unit profit for a larger market share","B":"Trading share for higher unit profit","C":"Increasing both share and unit profit","D":"Withdrawing from the market"},"correctOption":"A","correctAnswer":"Trading unit profit for a larger market share","questionType":"MCQ","explanation":{"correct_reason":"The lower price wins more buyers and a bigger share while reducing profit on each unit, so the Manila brand is exchanging unit profitability for market share.","distractor_reasons":{"A":"The lower price wins more buyers and a bigger share while reducing profit on each unit, so the Manila brand is exchanging unit profitability for market share.","B":"The opposite occurs here, because profit per unit falls while share rises, so the brand is not trading share for higher unit profit.","C":"Both measures do not rise together; the stated fall in profit per unit means one is being sacrificed in order to gain the other.","D":"The brand remains in the Manila detergent market and is actually gaining share, so it is certainly not withdrawing from the market."}}},{"id":"P1_U3_MCQ_1693","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1693","question":"The market for electric bikes in Antwerp is expanding rapidly, while one brand's sales grow only slowly. What is likely to happen to that brand's market share?","options":{"A":"It will rise","B":"It will fall as the market grows faster","C":"It will stay exactly the same","D":"It will certainly double"},"correctOption":"B","correctAnswer":"It will fall as the market grows faster","questionType":"MCQ","explanation":{"correct_reason":"When the whole Antwerp market expands more quickly than a brand's own sales, that brand captures a smaller proportion of sales, so its market share will fall.","distractor_reasons":{"B":"When the whole Antwerp market expands more quickly than a brand's own sales, that brand captures a smaller proportion of sales, so its market share will fall.","A":"A rising share needs the brand's sales to grow faster than the market; here the Antwerp market is expanding much more quickly than the brand.","C":"A steady share would require sales to keep pace with the rapidly growing market, but the brand's sales are increasing only slowly.","D":"Nothing suggests doubling; with sales lagging the market's expansion, the brand's percentage share is set to decline rather than double. The details given about the business support It will fall as the market grows faster, so this answer is unsuitable."}}},{"id":"P1_U3_MCQ_1694","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1694","question":"A questionnaire in Lima asks about satisfaction only after describing the company's many awards. What is the most likely problem with this order of questions?","options":{"A":"Respondents will skip every question","B":"The data collected will be secondary","C":"The awards may bias respondents towards positive answers","D":"The sample will be unrepresentative"},"correctOption":"C","correctAnswer":"The awards may bias respondents towards positive answers","questionType":"MCQ","explanation":{"correct_reason":"Listing awards before the satisfaction question may prime Lima respondents to answer favourably, so the order of the questions threatens the objectivity of the responses.","distractor_reasons":{"C":"Listing awards before the satisfaction question may prime Lima respondents to answer favourably, so the order of the questions threatens the objectivity of the responses.","A":"Respondents are unlikely to skip everything merely because awards are described first; the real risk is biased answers, not wholesale non-response.","B":"The questionnaire still gathers new responses from respondents, so the information collected is primary rather than secondary data. The business's circumstances match The awards may bias respondents towards positive answers, so this option does not fit.","D":"Sampling decides who is questioned, whereas the difficulty described here concerns how the questions are framed and ordered in Lima. For the business, the facts point to The awards may bias respondents towards positive answers, so this option cannot be correct."}}},{"id":"P1_U3_MCQ_1695","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1695","question":"A flower shop in Oslo buys bouquets for $12 and sells them for $20. What is the mark-up on cost and the gross margin on the selling price?","options":{"A":"40% mark-up and 66.7% margin","B":"60% mark-up and 33.3% margin","C":"50% mark-up and 50% margin","D":"66.7% mark-up and 40% margin"},"correctOption":"D","correctAnswer":"66.7% mark-up and 40% margin","questionType":"MCQ","explanation":{"correct_reason":"Gross profit is $20 minus $12, which is $8, so mark-up on cost is $8 over $12 = 66.7%, while gross margin on the $20 selling price is $8 over $20 = 40%.","distractor_reasons":{"D":"Gross profit is $20 minus $12, which is $8, so mark-up on cost is $8 over $12 = 66.7%, while gross margin on the $20 selling price is $8 over $20 = 40%.","A":"The two percentages are reversed: 40% is the margin measured on the $20 price and 66.7% is the mark-up calculated on the $12 cost.","B":"A 60% mark-up would need $7.20 of profit on $12, but the Oslo shop earns $8, giving a 66.7% mark-up and a 40% margin.","C":"A 50% mark-up would require profit of $6 on the $12 cost; actual profit is $8, giving 66.7% on cost and 40% on price."}}},{"id":"P1_U3_MCQ_1696","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1696","question":"A noodle shop in Chiang Mai highlights its use of local organic herbs and displays them on the menu to distinguish itself from rival shops. What strategy is being used?","options":{"A":"Differentiation through product features","B":"Cost leadership","C":"Mass marketing","D":"Market skimming"},"correctOption":"A","correctAnswer":"Differentiation through product features","questionType":"MCQ","explanation":{"correct_reason":"Emphasising local organic herbs on the menu sets the Chiang Mai noodle shop apart from rivals based on product attributes, which is a clear differentiation strategy.","distractor_reasons":{"A":"Emphasising local organic herbs on the menu sets the Chiang Mai noodle shop apart from rivals based on product attributes, which is a clear differentiation strategy.","B":"Cost leadership means competing on low prices, whereas highlighting premium organic ingredients focuses on distinctive quality rather than cheapness. For the business, the facts point to Differentiation through product features, so this option cannot be correct.","C":"Mass marketing targets everyone with one broad offer, but the Chiang Mai shop differentiates itself through a specific product characteristic. The scenario for the business instead describes Differentiation through product features, which rules this alternative out.","D":"Skimming sets a high initial price for a new product; the noodle shop's advantage comes from its organic ingredients, not from a launch pricing tactic."}}},{"id":"P1_U3_MCQ_1697","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1697","question":"A company holds 25% of its market. If the total market doubles over two years while the company's own sales stay exactly the same, what happens to its share?","options":{"A":"It rises to 50%","B":"It falls to 12.5%","C":"It stays at 25%","D":"It falls to 20%"},"correctOption":"B","correctAnswer":"It falls to 12.5%","questionType":"MCQ","explanation":{"correct_reason":"Share equals own sales divided by total market sales, so doubling the market while sales are unchanged halves the company's share, from 25% down to 12.5%.","distractor_reasons":{"B":"Share equals own sales divided by total market sales, so doubling the market while sales are unchanged halves the company's share, from 25% down to 12.5%.","A":"A doubling of the market reduces rather than raises the share when the company's own sales do not change at all over the two years.","C":"A constant share would require the company's sales to double along with the market, but here its sales are unchanged. In the business's case, the correct description is It falls to 12.5%, not this choice.","D":"Halving 25% gives 12.5%, not 20%; the denominator doubles while the numerator remains fixed at the same level. The business's circumstances match It falls to 12.5%, so this option does not fit."}}},{"id":"P1_U3_MCQ_1698","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1698","question":"A survey in Dublin questions 500 people at a single football match to estimate the whole city's views on public transport. What is the main weakness of this approach?","options":{"A":"The sample is too small","B":"The questions must be closed","C":"The sample is biased towards football fans","D":"It relies on secondary data"},"correctOption":"C","correctAnswer":"The sample is biased towards football fans","questionType":"MCQ","explanation":{"correct_reason":"Questioning people at one football match over-represents football fans, so the Dublin sample is unlikely to represent all residents' views about public transport.","distractor_reasons":{"C":"Questioning people at one football match over-represents football fans, so the Dublin sample is unlikely to represent all residents' views about public transport.","A":"Five hundred respondents is a reasonably large number; the problem is where they were recruited rather than the count of responses obtained.","B":"Question format is not the issue; open or closed questions would still be answered by a biased group of football spectators at the match.","D":"The survey collects fresh views from the people questioned, so it is primary research; the weakness lies in the sampling location."}}},{"id":"P1_U3_MCQ_1699","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1699","question":"A juice brand in Sao Paulo switches to recyclable bottles and prints the recycling message prominently, keeping the juice and its price unchanged. Which marketing mix element is highlighted?","options":{"A":"Product packaging","B":"Price","C":"Place","D":"Promotion only"},"correctOption":"A","correctAnswer":"Product packaging","questionType":"MCQ","explanation":{"correct_reason":"Changing to recyclable bottles and printing messages on them alters the product's packaging, so the Sao Paulo juice brand is highlighting the product element of the mix.","distractor_reasons":{"A":"Changing to recyclable bottles and printing messages on them alters the product's packaging, so the Sao Paulo juice brand is highlighting the product element of the mix.","B":"The juice price is unchanged, so this is not a pricing decision even though the new packaging may have cost implications.","C":"No change in outlets or distribution is described; the switch mainly concerns the bottle in which the juice is sold to customers.","D":"The recycling message is printed on the bottle as part of its packaging and the juice is unchanged, so packaging rather than promotion alone is central."}}},{"id":"P1_U3_MCQ_1700","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1700","question":"A skincare brand in Seoul had $30 million of sales in a $300 million market. Next year its sales rise to $36 million while the total market stays at $300 million. By how many percentage points does its share rise?","options":{"A":"1 percentage point","B":"6 percentage points","C":"20 percentage points","D":"2 percentage points"},"correctOption":"D","correctAnswer":"2 percentage points","questionType":"MCQ","explanation":{"correct_reason":"The Seoul brand's share rises from $30 million divided by $300 million, which is 10%, to $36 million divided by $300 million, which is 12%, a gain of 2 percentage points.","distractor_reasons":{"D":"The Seoul brand's share rises from $30 million divided by $300 million, which is 10%, to $36 million divided by $300 million, which is 12%, a gain of 2 percentage points.","A":"One point would require sales of $33 million; the rise to $36 million moves the Seoul share from 10% up to 12%, a two point gain.","B":"Six percentage points confuses the $6 million increase in sales with share points; dividing by the $300 million market gives only two points.","C":"20% is the growth in the brand's own sales, not the change in its market share, which increases by just 2 percentage points."}}},{"id":"P1_U3_MCQ_1701","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1701","question":"Trivana Ceramics Ltd in Fes, Morocco recorded $6 million of sales of its hand-painted tiles in 2026. Industry figures show the whole Moroccan decorative tile market was worth $40 million that year. What was Trivana Ceramics' market share in 2026?","options":{"A":"15%","B":"12%","C":"20%","D":"25%"},"correctOption":"A","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Market share is the firm's sales divided by total market sales, multiplied by 100. Trivana's $6 million divided by the $40 million Moroccan market equals 0.15, so its share was exactly 15% in 2026.","distractor_reasons":{"A":"Market share is the firm's sales divided by total market sales, multiplied by 100. Trivana's $6 million divided by the $40 million Moroccan market equals 0.15, so its share was exactly 15% in 2026.","B":"A 12% share would require sales of $4.8 million in a $40 million market, which is below the $6 million Trivana actually recorded, so this figure understates the business.","C":"A 20% share would mean $8 million of sales, exceeding the $6 million stated; this option has divided the $40 million market by $6 million sales instead of the reverse.","D":"A 25% share would need $10 million of sales, well above the $6 million Trivana generated, so it cannot follow from the two figures given in the scenario."}}},{"id":"P1_U3_MCQ_1702","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1702","question":"Vespara Tours Ltd in Chiang Mai, Thailand wants to know why recent customers rated its river cruises so highly. It plans to contact those customers directly and ask them open-ended questions about their experience. Which approach would generate primary qualitative data for Vespara Tours?","options":{"A":"Reading published government tourism statistics","B":"Analysing its own past booking invoices","C":"Conducting in-depth interviews with recent customers","D":"Comparing the advertised prices of rival cruise firms"},"correctOption":"C","correctAnswer":"Conducting in-depth interviews with recent customers","questionType":"MCQ","explanation":{"correct_reason":"Primary research gathers new evidence first-hand from the target group, and open-ended answers produce words rather than numbers. Interviewing Vespara's own recent customers directly therefore yields primary qualitative insight into why they rated the cruises highly.","distractor_reasons":{"A":"Published government statistics already exist and were collected by another body, making them secondary data, and they are usually numerical rather than the open-ended personal views Vespara needs.","B":"The firm's own invoices are existing records, so using them is secondary research, and they show only bookings and amounts rather than the reasons behind customers' high ratings.","C":"Primary research gathers new evidence first-hand from the target group, and open-ended answers produce words rather than numbers. Interviewing Vespara's own recent customers directly therefore yields primary qualitative insight into why they rated the cruises highly.","D":"Rivals' advertised prices are published information gathered by other businesses, so this is secondary research and, being numerical, it reveals nothing about Vespara's own customers' opinions."}}},{"id":"P1_U3_MCQ_1703","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1703","question":"A workshop in Hanoi, Vietnam makes bamboo lamps with a unit production cost of $24 and adds a 25% mark-up to set its selling price. What price does the workshop charge, and what is the mark-up in dollars per lamp?","options":{"A":"$30 price and a $24 mark-up","B":"$30 price and a $6 mark-up","C":"$32 price and an $8 mark-up","D":"$24 price and a $6 mark-up"},"correctOption":"B","correctAnswer":"$30 price and a $6 mark-up","questionType":"MCQ","explanation":{"correct_reason":"A 25% mark-up on the $24 cost is 0.25 times $24, which equals $6. Adding this to cost gives a selling price of $30 per lamp, so the correct option states a $30 price and a $6 mark-up.","distractor_reasons":{"A":"The $30 price is right, but the mark-up is 25% of $24, which is $6, not the $24 mistakenly listed here as the extra amount added to the cost of making one lamp.","B":"A 25% mark-up on the $24 cost is 0.25 times $24, which equals $6. Adding this to cost gives a selling price of $30 per lamp, so the correct option states a $30 price and a $6 mark-up.","C":"An $8 mark-up would be one third of cost, not the stated 25%; 0.25 times $24 is $6, so the correct price is $30 and not the $32 shown in this option.","D":"A $24 price would leave no mark-up at all, ignoring the 25% addition entirely; the $6 figure is the true mark-up but the price must be $24 plus $6, which is $30."}}},{"id":"P1_U3_MCQ_1704","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1704","question":"Pellworth Hotels Ltd in Cape Town, South Africa separates its guests into leisure travellers, conference delegates and wedding parties, then designs distinct packages and messages for each group. Which marketing strategy is the hotel pursuing?","options":{"A":"Mass marketing","B":"Product orientation","C":"Undifferentiated marketing","D":"Market segmentation"},"correctOption":"D","correctAnswer":"Market segmentation","questionType":"MCQ","explanation":{"correct_reason":"Market segmentation divides a broad market into identifiable groups with similar needs, then tailors offerings to them. Pellworth's three guest types with separate packages fit this exactly, unlike treating all customers as one homogeneous group.","distractor_reasons":{"A":"Mass marketing would use one standard package and a single message for every guest, whereas Pellworth deliberately creates different offerings for leisure, conference and wedding customers.","B":"Product orientation focuses on what the firm can make rather than on distinct customer groups; Pellworth is instead identifying guest needs and adapting its packages to each segment.","C":"Undifferentiated marketing ignores differences between buyers and targets the whole market alike, the opposite of Pellworth's approach of designing separate packages for three guest categories.","D":"Market segmentation divides a broad market into identifiable groups with similar needs, then tailors offerings to them. Pellworth's three guest types with separate packages fit this exactly, unlike treating all customers as one homogeneous group."}}},{"id":"P1_U3_MCQ_1705","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1705","question":"A supermarket chain in Nairobi, Kenya found that 8,400 of its 12,000 regular shoppers said reliable home delivery was their most important buying factor. Which conclusion should the marketing team draw about its customers?","options":{"A":"Price is the dominant purchase criterion","B":"Delivery reliability matters more than the chain assumed","C":"Only a small minority value delivery service","D":"Customer needs are identical across all shoppers"},"correctOption":"B","correctAnswer":"Delivery reliability matters more than the chain assumed","questionType":"MCQ","explanation":{"correct_reason":"With 8,400 of 12,000 shoppers naming reliable delivery as most important, that is 70% of respondents, a clear majority. The chain should conclude that delivery reliability is highly valued, more so than it may have assumed.","distractor_reasons":{"A":"The survey identifies reliable delivery, not price, as the leading factor, so nothing in the 8,400 responses supports the claim that price dominates purchase decisions for these shoppers.","B":"With 8,400 of 12,000 shoppers naming reliable delivery as most important, that is 70% of respondents, a clear majority. The chain should conclude that delivery reliability is highly valued, more so than it may have assumed.","C":"With 8,400 of 12,000 shoppers, or 70%, rating delivery as most important, a large majority value it; calling this a small minority directly contradicts the proportion reported.","D":"The responses show one dominant preference among these shoppers but say nothing about all customer needs being identical; in fact the survey points to a single clear priority, not uniformity."}}},{"id":"P1_U3_MCQ_1706","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1706","question":"A cosmetics firm in Lyon, France mails 600 questionnaires to a random sample of its customers. In total 180 fully completed forms are returned. What is the response rate for this survey?","options":{"A":"30%","B":"18%","C":"3%","D":"333%"},"correctOption":"A","correctAnswer":"30%","questionType":"MCQ","explanation":{"correct_reason":"The response rate is completed returns divided by questionnaires sent, multiplied by 100. Here 180 divided by 600 equals 0.30, so exactly 30% of the questionnaires were returned fully completed by the sampled customers.","distractor_reasons":{"A":"The response rate is completed returns divided by questionnaires sent, multiplied by 100. Here 180 divided by 600 equals 0.30, so exactly 30% of the questionnaires were returned fully completed by the sampled customers.","B":"An 18% rate would correspond to only 108 completed forms out of 600, not the 180 actually returned, so this option has misread the number of responses received.","C":"A 3% rate would be just 18 completed questionnaires, an order of magnitude below the 180 reported; the decimal place has been shifted in this option.","D":"A rate above 100% is impossible here because only 180 of 600 forms came back; this option has divided 600 by 180 and expressed the result incorrectly as a percentage."}}},{"id":"P1_U3_MCQ_1707","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1707","question":"A shoe maker in Porto, Portugal sells its running shoes mainly through independent sports shops and a small number of specialist outlets rather than through its own stores. Which element of the marketing mix does this describe?","options":{"A":"Product","B":"Price","C":"Promotion","D":"Place"},"correctOption":"D","correctAnswer":"Place","questionType":"MCQ","explanation":{"correct_reason":"Place concerns how a product reaches the customer, including the choice of distribution channels and outlets. Selling through independent sports shops and specialists describes the route to market, so it is clearly a place decision for the shoe maker.","distractor_reasons":{"A":"Product decisions concern features, design, branding and packaging of the shoe itself, not which shops stock it; the scenario says nothing about the shoe's specification.","B":"Price decisions set the amount charged, discounts and payment terms; no selling price or margin is mentioned, so this cannot be the mix element illustrated here.","C":"Promotion covers advertising, sales promotions and personal selling used to communicate with buyers; using intermediaries to distribute the shoes is not a communication activity.","D":"Place concerns how a product reaches the customer, including the choice of distribution channels and outlets. Selling through independent sports shops and specialists describes the route to market, so it is clearly a place decision for the shoe maker."}}},{"id":"P1_U3_MCQ_1708","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1708","question":"A coffee chain in Seattle, United States issues a card that gives a free drink after every ten purchases and sends members personal offers on their birthdays. What is the primary strategic aim of this scheme?","options":{"A":"To reduce the cost of each cup sold","B":"To build customer loyalty and encourage repeat purchases","C":"To remove the need for any advertising","D":"To sell the same product to entirely new markets"},"correctOption":"B","correctAnswer":"To build customer loyalty and encourage repeat purchases","questionType":"MCQ","explanation":{"correct_reason":"A loyalty card that rewards repeated buying and sends personalised offers is designed to retain existing customers and increase their purchase frequency. The free drink after ten purchases directly encourages customers to return rather than switching.","distractor_reasons":{"A":"Giving away a free drink after ten purchases raises, not lowers, the average cost per cup, and the scheme says nothing about changing the chain's production or operating costs.","B":"A loyalty card that rewards repeated buying and sends personalised offers is designed to retain existing customers and increase their purchase frequency. The free drink after ten purchases directly encourages customers to return rather than switching.","C":"A loyalty scheme does not eliminate the need for advertising; attracting new customers still normally requires promotion, so removing all advertising is not the aim described here.","D":"The card targets the chain's existing repeat buyers with birthday offers, not entirely new markets, so this is a retention rather than a market-development initiative."}}},{"id":"P1_U3_MCQ_1709","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1709","question":"A grain mill in Alexandria, Egypt sold 12,000 tonnes of flour in 2026 in a national flour market of 80,000 tonnes. Its largest competitor holds 35% of the same market. What is the mill's market share and the gap to that competitor?","options":{"A":"12%, which is 23 percentage points below the competitor","B":"15%, which is 20 percentage points below the competitor","C":"18%, which is 17 percentage points below the competitor","D":"15%, which is 20 percentage points above the competitor"},"correctOption":"B","correctAnswer":"15%, which is 20 percentage points below the competitor","questionType":"MCQ","explanation":{"correct_reason":"Market share is own sales divided by total market sales, so 12,000 tonnes divided by 80,000 tonnes gives 15%; the rival's 35% is 20 percentage points higher, so the mill trails by 20 points.","distractor_reasons":{"A":"A 12% share would require only 9,600 tonnes of sales, below the 12,000 tonnes recorded, so this option has divided the wrong figures and the 23-point gap is also wrong.","B":"Market share is own sales divided by total market sales, so 12,000 tonnes divided by 80,000 tonnes gives 15%; the rival's 35% is 20 percentage points higher, so the mill trails by 20 points.","C":"An 18% share would mean 14,400 tonnes of flour, above the 12,000 tonnes sold, and the 17-point gap is likewise wrong; these figures are not derivable from the scenario.","D":"The 15% share is right, but the competitor's 35% is larger, so the mill is below the rival by 20 percentage points rather than above it as this option states."}}},{"id":"P1_U3_MCQ_1710","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1710","question":"A research agency in São Paulo, Brazil needs exact numerical information on how many households buy a new drink each month. It decides to count purchases from a large, representative group via a structured form. Which data collection method is being used?","options":{"A":"Focus groups","B":"Observation of shopping behaviour","C":"Open-ended interviews","D":"A questionnaire survey"},"correctOption":"D","correctAnswer":"A questionnaire survey","questionType":"MCQ","explanation":{"correct_reason":"A structured form administered to a representative group that yields countable numerical answers about purchasing is a questionnaire survey. The emphasis on exact figures and a large sample confirms quantitative data collection through a questionnaire.","distractor_reasons":{"A":"Focus groups are small discussions producing exploratory, subjective views, not exact counts from a large representative group, so they would not supply the numerical data required here.","B":"Observation records behaviour as it happens but cannot easily establish how many households bought a drink monthly or why; it does not use a structured form put to a large sample.","C":"Open-ended interviews generate qualitative words rather than the exact numerical purchase counts the agency needs, and they are normally too small-scale to represent a large group.","D":"A structured form administered to a representative group that yields countable numerical answers about purchasing is a questionnaire survey. The emphasis on exact figures and a large sample confirms quantitative data collection through a questionnaire."}}},{"id":"P1_U3_MCQ_1711","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1711","question":"A bakery in Accra, Ghana bakes loaves at a cost of $1.20 each and wants a mark-up of 50% on cost. What selling price should it set per loaf?","options":{"A":"$1.80","B":"$1.70","C":"$2.40","D":"$1.20"},"correctOption":"A","correctAnswer":"$1.80","questionType":"MCQ","explanation":{"correct_reason":"A 50% mark-up on the $1.20 cost is 0.50 times $1.20, which is $0.60. Adding this to the cost gives $1.80 per loaf, so the bakery should charge $1.80 to achieve the intended mark-up.","distractor_reasons":{"A":"A 50% mark-up on the $1.20 cost is 0.50 times $1.20, which is $0.60. Adding this to the cost gives $1.80 per loaf, so the bakery should charge $1.80 to achieve the intended mark-up.","B":"$1.70 implies a mark-up of only $0.50, which is about 42% of the $1.20 cost, not the 50% the bakery intends to apply to each loaf.","C":"$2.40 would be a 100% mark-up, doubling the $1.20 cost; the intended 50% addition is only $0.60, giving a price of $1.80.","D":"$1.20 is simply the production cost with no mark-up added at all, so it would leave the bakery no margin and ignore the stated 50% requirement."}}},{"id":"P1_U3_MCQ_1712","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1712","question":"A textile maker in Chiang Mai, Thailand produces a small range of hand-woven scarves for wealthy tourists seeking unique souvenirs, charging high prices to this narrow group. Which market strategy is the maker using?","options":{"A":"Mass marketing","B":"Cost leadership","C":"Niche marketing","D":"Product orientation"},"correctOption":"C","correctAnswer":"Niche marketing","questionType":"MCQ","explanation":{"correct_reason":"By focusing on a narrow group of wealthy tourists wanting unique souvenirs and charging premium prices, the maker concentrates on a specific segment rather than the whole market. That is niche marketing.","distractor_reasons":{"A":"Mass marketing targets the entire market with one standard offering, while the Chiang Mai maker deliberately serves only a small, specialised group of souvenir buyers.","B":"Cost leadership competes on low prices for a broad market; the maker charges high prices to a narrow group, so it is not pursuing a low-cost strategy.","C":"By focusing on a narrow group of wealthy tourists wanting unique souvenirs and charging premium prices, the maker concentrates on a specific segment rather than the whole market. That is niche marketing.","D":"Product orientation emphasises what the firm can produce rather than a defined customer group; the maker is instead selecting and serving a particular tourist segment."}}},{"id":"P1_U3_MCQ_1713","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1713","question":"A mobile phone retailer in Toronto, Canada had 6% of its local market in 2025. During 2026 the total market grew by 10% while the retailer's sales stayed unchanged. What most likely happened to its market share?","options":{"A":"It rose to 6.6%","B":"It stayed at exactly 6%","C":"It doubled to 12%","D":"It fell to about 5.45%"},"correctOption":"D","correctAnswer":"It fell to about 5.45%","questionType":"MCQ","explanation":{"correct_reason":"If the total market grew by 10% but the retailer's sales were unchanged, its share falls. The new share is 6% divided by 1.10, which is about 5.45%, so the retailer lost ground because competitors captured the market growth.","distractor_reasons":{"A":"A rise to 6.6% would occur only if the retailer's own sales had grown by 10% along with the market; the scenario states its sales stayed unchanged, so its share cannot rise.","B":"The share stays at 6% only if the retailer's sales grow at exactly the same rate as the market; with its sales flat and the market up 10%, the share must decline.","C":"Doubling to 12% would require the retailer's sales to grow far faster than the 10% market expansion; with sales unchanged its share falls rather than rises.","D":"If the total market grew by 10% but the retailer's sales were unchanged, its share falls. The new share is 6% divided by 1.10, which is about 5.45%, so the retailer lost ground because competitors captured the market growth."}}},{"id":"P1_U3_MCQ_1714","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1714","question":"A dairy company in Kampala, Uganda drafts a questionnaire with 40 questions and tests it on 25 staff before using it with customers. Several questions are confusing and are rewritten. What is this preliminary step called?","options":{"A":"Secondary data collection","B":"Pilot testing","C":"Random sampling","D":"Market segmentation"},"correctOption":"B","correctAnswer":"Pilot testing","questionType":"MCQ","explanation":{"correct_reason":"Trying a draft questionnaire on a small group before the full survey, then amending confusing questions, is pilot testing. It helps the dairy firm detect ambiguous wording so the main customer survey gathers reliable, usable answers.","distractor_reasons":{"A":"Secondary data collection uses information that already exists elsewhere; here the firm is trying out a newly written questionnaire, so this is primary research preparation, not secondary data use.","B":"Trying a draft questionnaire on a small group before the full survey, then amending confusing questions, is pilot testing. It helps the dairy firm detect ambiguous wording so the main customer survey gathers reliable, usable answers.","C":"Random sampling is a way of selecting respondents so each has an equal chance, whereas testing the wording of a draft form on staff is about refining the instrument, not selecting a sample.","D":"Market segmentation divides customers into groups; nothing in the scenario involves grouping customers, only checking whether the questions are clear before the survey."}}},{"id":"P1_U3_MCQ_1715","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1715","question":"A drinks producer in Manila, Philippines launches a new energy drink at a deliberately high price, then plans to lower it after rivals have entered. Which pricing strategy does this illustrate?","options":{"A":"Penetration pricing","B":"Cost-plus pricing","C":"Price skimming","D":"Loss leader pricing"},"correctOption":"C","correctAnswer":"Price skimming","questionType":"MCQ","explanation":{"correct_reason":"Setting a high initial price to skim revenue from keen early buyers before reducing it later is price skimming. The Manila producer is charging a premium first and planning a cut as competitors arrive, which matches this strategy.","distractor_reasons":{"A":"Penetration pricing sets a low initial price to gain share quickly and then may raise it; the producer is doing the opposite by starting high and reducing later.","B":"Cost-plus pricing sets price by adding a mark-up to unit cost, with no mention of a high launch price followed by a planned reduction as competitors enter.","C":"Setting a high initial price to skim revenue from keen early buyers before reducing it later is price skimming. The Manila producer is charging a premium first and planning a cut as competitors arrive, which matches this strategy.","D":"Loss leader pricing sells one product below cost to attract customers who buy other items; here the drink is launched at a high price, not a deliberately loss-making one."}}},{"id":"P1_U3_MCQ_1716","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1716","question":"A furniture maker in Copenhagen, Denmark positions its products as sustainably sourced and handcrafted, charging premium prices to environmentally conscious buyers. What is the firm seeking to create through this positioning?","options":{"A":"A distinct competitive advantage","B":"A lower unit production cost","C":"A mass-market product with no rivals","D":"An end to all customer research"},"correctOption":"A","correctAnswer":"A distinct competitive advantage","questionType":"MCQ","explanation":{"correct_reason":"Positioning a product as sustainable and handcrafted for a specific buyer group makes it stand out from rivals and gives customers a reason to choose it. This creates a differentiated competitive advantage built on values the target customers reward.","distractor_reasons":{"A":"Positioning a product as sustainable and handcrafted for a specific buyer group makes it stand out from rivals and gives customers a reason to choose it. This creates a differentiated competitive advantage built on values the target customers reward.","B":"Handcrafting and sustainable sourcing tend to raise costs rather than lower them, and the scenario describes a premium price, not a cost-reduction objective.","C":"The maker targets environmentally conscious buyers with a distinctive offering, so it is not a no-frills mass-market product and it still faces competing furniture firms.","D":"Understanding what environmentally conscious buyers value requires market research; positioning on those values does not remove the need for it. For the business, the facts point to A distinct competitive advantage, so this option cannot be correct."}}},{"id":"P1_U3_MCQ_1717","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1717","question":"Braywell Foods Ltd in Lagos, Nigeria sold 24,000 packets of instant soup in 2026, up from 20,000 in 2025. What was the percentage increase in packets sold?","options":{"A":"16%","B":"20%","C":"24%","D":"4%"},"correctOption":"B","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"The increase is 24,000 minus 20,000, which is 4,000 packets. Dividing 4,000 by the 20,000 baseline and multiplying by 100 gives a 20% rise in packets sold for Braywell Foods between 2025 and 2026.","distractor_reasons":{"A":"A 16% rise would be 3,200 extra packets on a 20,000 base, not the 4,000 extra actually recorded, so this option has used the wrong increase.","B":"The increase is 24,000 minus 20,000, which is 4,000 packets. Dividing 4,000 by the 20,000 baseline and multiplying by 100 gives a 20% rise in packets sold for Braywell Foods between 2025 and 2026.","C":"Taking 24% mistakenly divides the 4,000 increase by the new total of 24,000; percentage growth must use the original 20,000 figure, giving 20%.","D":"The 4,000-packet increase is an absolute change; expressing it as a percentage requires dividing by the 20,000 baseline, which gives 20% rather than 4%."}}},{"id":"P1_U3_MCQ_1718","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1718","question":"A hotel chain in Bangkok, Thailand analyses its own booking records from the past three years to spot seasonal demand patterns before planning promotions. What type of research is this?","options":{"A":"Primary qualitative research","B":"A focus group study","C":"Observation of competitor prices","D":"Secondary research using internal data"},"correctOption":"D","correctAnswer":"Secondary research using internal data","questionType":"MCQ","explanation":{"correct_reason":"The booking records already exist inside the business and were gathered for operational purposes, so reusing them is secondary research using internal data. The chain is analysing historical figures rather than collecting new evidence from customers.","distractor_reasons":{"A":"Primary research collects new first-hand evidence, but the chain is reusing records it already holds, so this is secondary analysis rather than primary investigation.","B":"A focus group is a small discussion generating qualitative opinions; the chain is examining numerical booking records spanning three years, not running group discussions.","C":"Observing competitor prices would mean collecting new data about rivals, whereas the chain is reusing its own historical booking records, which are internal secondary data.","D":"The booking records already exist inside the business and were gathered for operational purposes, so reusing them is secondary research using internal data. The chain is analysing historical figures rather than collecting new evidence from customers."}}},{"id":"P1_U3_MCQ_1719","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1719","question":"A stationery firm in Seoul, South Korea prices its bestselling notebook at $9.99 rather than $10.00 to make the product appear cheaper to shoppers. Which pricing technique is the firm using?","options":{"A":"Psychological pricing","B":"Cost-plus pricing","C":"Price skimming","D":"Loss leader pricing"},"correctOption":"A","correctAnswer":"Psychological pricing","questionType":"MCQ","explanation":{"correct_reason":"Setting a price just below a round number, such as $9.99 rather than $10.00, is psychological pricing. It exploits customers' tendency to perceive the price as belonging to a lower band, making the notebook seem better value.","distractor_reasons":{"A":"Setting a price just below a round number, such as $9.99 rather than $10.00, is psychological pricing. It exploits customers' tendency to perceive the price as belonging to a lower band, making the notebook seem better value.","B":"Cost-plus pricing would require adding a mark-up to a known unit cost, which is not stated; the $9.99 figure is chosen for its visual effect, not from a cost calculation.","C":"Price skimming involves a high launch price that is later reduced; a one-cent gap below a round number has nothing to do with skimming revenue over time.","D":"A loss leader is sold below cost to attract other purchases, but no cost is given and $9.99 is a standard round-number-undercutting tactic, so psychological pricing is correct."}}},{"id":"P1_U3_MCQ_1720","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1720","question":"A sportswear brand in Melbourne, Australia finds that its widely available T-shirts sell well to gym-goers aged 18 to 25, so it focuses advertising on that age group. What is the brand doing?","options":{"A":"Reducing its product range","B":"Practising mass marketing","C":"Targeting a specific market segment","D":"Collecting primary data"},"correctOption":"C","correctAnswer":"Targeting a specific market segment","questionType":"MCQ","explanation":{"correct_reason":"Having identified that gym-goers aged 18 to 25 buy the T-shirts, the brand directs its advertising at that defined group. This is targeting a specific market segment, focusing promotional effort on the buyers most likely to respond.","distractor_reasons":{"A":"Nothing in the scenario says the brand is cutting the number of products it offers; it is changing where it advertises, not narrowing its product range.","B":"Mass marketing would address the whole market with a single message, whereas the brand deliberately concentrates on one age group, so it is not mass marketing.","C":"Having identified that gym-goers aged 18 to 25 buy the T-shirts, the brand directs its advertising at that defined group. This is targeting a specific market segment, focusing promotional effort on the buyers most likely to respond.","D":"Although research may have revealed the age group, the described action of focusing advertising is a targeting decision, not itself the collection of primary data."}}},{"id":"P1_U3_MCQ_1721","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1721","question":"A smartphone maker in Shenzhen, China claims its handsets last 30% longer on one charge than any rival, a benefit no competitor advertises. What does this claim give the business?","options":{"A":"A unique selling point","B":"A lower market share","C":"Higher production costs only","D":"A mass-market commodity"},"correctOption":"A","correctAnswer":"A unique selling point","questionType":"MCQ","explanation":{"correct_reason":"A benefit that no competitor offers, such as 30% longer battery life, distinguishes the handset and gives buyers a clear reason to choose it. That is a unique selling point, setting the product apart in a crowded smartphone market.","distractor_reasons":{"A":"A benefit that no competitor offers, such as 30% longer battery life, distinguishes the handset and gives buyers a clear reason to choose it. That is a unique selling point, setting the product apart in a crowded smartphone market.","B":"A distinctive benefit would normally help attract customers rather than reduce market share, and the scenario gives no figures showing the maker's share has fallen.","C":"Longer battery life may involve costs, but the claim's marketing purpose is to differentiate the handset, not merely to describe the firm's cost structure.","D":"A commodity is an undifferentiated product, whereas the 30% longer life is a specific advertised difference, so the handset is not a mass-market commodity."}}},{"id":"P1_U3_MCQ_1722","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1722","question":"A chocolate maker in Brussels, Belgium wants to explore how consumers feel about a new dark chocolate flavour and encourages participants to describe their reactions freely in small group discussions. Which method is being used?","options":{"A":"A postal questionnaire","B":"Analysis of sales invoices","C":"A focus group","D":"A random sample survey"},"correctOption":"C","correctAnswer":"A focus group","questionType":"MCQ","explanation":{"correct_reason":"A small group discussion in which participants freely describe their feelings is a focus group, generating qualitative insight into attitudes. The Brussels maker is seeking exploratory views about a new flavour, which is exactly what this method provides.","distractor_reasons":{"A":"A postal questionnaire uses written structured questions sent to respondents, not a facilitated small-group conversation about feelings toward a new product.","B":"Sales invoices are existing financial records showing what was bought, not participants' feelings, and they would not capture how consumers describe a new flavour in discussion.","C":"A small group discussion in which participants freely describe their feelings is a focus group, generating qualitative insight into attitudes. The Brussels maker is seeking exploratory views about a new flavour, which is exactly what this method provides.","D":"A random sample survey collects structured numerical answers from a larger, randomly chosen group, whereas the chocolate maker is running a small exploratory discussion about feelings."}}},{"id":"P1_U3_MCQ_1723","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1723","question":"A pharmaceutical firm in Zurich, Switzerland sells prescription medicines directly to hospitals and pharmacies, using its own sales representatives rather than supermarkets. Which element of the marketing mix is this?","options":{"A":"Product","B":"Place","C":"Promotion","D":"Price"},"correctOption":"B","correctAnswer":"Place","questionType":"MCQ","explanation":{"correct_reason":"Place is about the channels through which a product reaches its buyers. Using its own representatives to supply hospitals and pharmacies describes the firm's distribution route, so this is a place decision within the marketing mix.","distractor_reasons":{"A":"Product decisions concern the medicine's formulation, packaging and brand name; the scenario focuses on how it is delivered to customers, not on the product itself.","B":"Place is about the channels through which a product reaches its buyers. Using its own representatives to supply hospitals and pharmacies describes the firm's distribution route, so this is a place decision within the marketing mix.","C":"Although sales representatives communicate with buyers, the emphasis here is on the channel used to supply hospitals and pharmacies, which is a distribution or place matter.","D":"No price, discount or payment term is mentioned, so the mix element illustrated cannot be price, which concerns the amount customers pay."}}},{"id":"P1_U3_MCQ_1724","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1724","question":"A budget airline in Kuala Lumpur, Malaysia faces a rival's fare cut. Instead of matching it, the airline emphasizes its more frequent departures and free seat selection. Which strategic response is this?","options":{"A":"Price war","B":"Cost leadership","C":"Product development","D":"Differentiation"},"correctOption":"D","correctAnswer":"Differentiation","questionType":"MCQ","explanation":{"correct_reason":"Rather than cutting fares, the airline highlights service features rivals lack, such as frequent departures and free seat selection. This makes its offering distinct in customers' eyes, which is a differentiation response to a competitor's price cut.","distractor_reasons":{"A":"A price war involves repeatedly lowering fares to undercut rivals; the airline explicitly avoids matching the cut, so it is not engaging in a price war.","B":"Cost leadership means competing through the lowest costs and prices; the airline is instead adding valued services, so it is not pursuing a low-cost position here.","C":"Product development would mean launching a new or improved service; the airline's existing departures and seat choice are being promoted differently, not newly created.","D":"Rather than cutting fares, the airline highlights service features rivals lack, such as frequent departures and free seat selection. This makes its offering distinct in customers' eyes, which is a differentiation response to a competitor's price cut."}}},{"id":"P1_U3_MCQ_1725","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1725","question":"A spice exporter in Zanzibar, Tanzania shipped 14,000 kilograms of cloves in 2026 in a national clove market of 70,000 kilograms. What was its market share by volume?","options":{"A":"10%","B":"25%","C":"20%","D":"14%"},"correctOption":"C","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"Market share by volume is the firm's output divided by total market volume, multiplied by 100. The exporter's 14,000 kilograms divided by the 70,000-kilogram market equals 0.20, so its share was 20%.","distractor_reasons":{"A":"A 10% share would be 7,000 kilograms out of 70,000, only half the 14,000 kilograms actually shipped by this exporter. In the business's case, the correct description is 20%, not this choice.","B":"A 25% share would require 17,500 kilograms, above the 14,000 shipped; this option has divided the market by the firm's volume instead.","C":"Market share by volume is the firm's output divided by total market volume, multiplied by 100. The exporter's 14,000 kilograms divided by the 70,000-kilogram market equals 0.20, so its share was 20%.","D":"A 14% share would be 9,800 kilograms, below the 14,000 recorded; the correct calculation divides 14,000 by 70,000 to give 20%."}}},{"id":"P1_U3_MCQ_1726","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1726","question":"A furniture retailer in Stockholm, Sweden wants industry-wide figures on household spending on home furnishings and buys a published market report from an independent research firm. What kind of data has the retailer bought?","options":{"A":"Primary qualitative data","B":"Internal secondary data","C":"External secondary data","D":"Primary quantitative data"},"correctOption":"C","correctAnswer":"External secondary data","questionType":"MCQ","explanation":{"correct_reason":"The report was produced by another organisation and already existed before the retailer bought it, so it is secondary data. Because the source lies outside the business, it is external secondary data, not evidence the retailer gathered itself.","distractor_reasons":{"A":"Primary data is collected first-hand by the user, but the retailer purchased an existing report, so it is secondary; the figures are also numerical rather than the words typical of qualitative work.","B":"Internal secondary data comes from records inside the firm, such as its own sales invoices; a report written by an outside research firm is external to the retailer.","C":"The report was produced by another organisation and already existed before the retailer bought it, so it is secondary data. Because the source lies outside the business, it is external secondary data, not evidence the retailer gathered itself.","D":"Primary quantitative data would require the retailer to run its own structured survey; simply buying a ready-made published report means the data is secondary, even if it is numerical."}}},{"id":"P1_U3_MCQ_1727","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1727","question":"An electronics shop in Osaka, Japan buys a blender for $40 and lists it at $75. During a sale it offers a 20% discount off the list price. What is the sale price and the shop's profit on each blender sold?","options":{"A":"$55 sale price and $15 profit","B":"$60 sale price and $20 profit","C":"$65 sale price and $25 profit","D":"$60 sale price and $40 profit"},"correctOption":"B","correctAnswer":"$60 sale price and $20 profit","questionType":"MCQ","explanation":{"correct_reason":"A 20% discount on the $75 list price is $15, leaving a sale price of $60. Subtracting the $40 cost gives $20 profit per blender, so the shop earns $20 on each unit at the discounted price.","distractor_reasons":{"A":"A $55 price would need a $20 discount, which is about 27% of the $75 list price, not 20%; the true discount is $15 and the resulting profit is $20.","B":"A 20% discount on the $75 list price is $15, leaving a sale price of $60. Subtracting the $40 cost gives $20 profit per blender, so the shop earns $20 on each unit at the discounted price.","C":"A $65 price implies only a $10 discount, about 13% off $75, not the stated 20%; the correct discount is $15, giving a $60 price and $20 profit.","D":"The $60 sale price is right, but $40 is the shop's purchase cost, not its profit; profit is the $60 selling price minus the $40 cost, which equals $20."}}},{"id":"P1_U3_MCQ_1728","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1728","question":"A skincare brand in Seoul, South Korea already sells its cleansers to loyal local customers and now introduces a new sunscreen line aimed at those same buyers. Which growth strategy is the brand following?","options":{"A":"Market penetration","B":"Market development","C":"Diversification","D":"Product development"},"correctOption":"D","correctAnswer":"Product development","questionType":"MCQ","explanation":{"correct_reason":"Creating a new sunscreen line for the brand's existing customers is product development: a new offering directed at a market the business already serves. It differs from taking existing products into entirely new markets.","distractor_reasons":{"A":"Market penetration means selling more of the existing products to current customers; the brand is launching a genuinely new sunscreen, so it is developing the product rather than merely penetrating further.","B":"Market development would take existing cleansers into new markets such as overseas buyers; here the customers stay the same and the product is new, so this is not market development.","C":"Diversification involves new products in entirely new markets; the sunscreen goes to the brand's existing loyal buyers, so it is a narrower product-development move.","D":"Creating a new sunscreen line for the brand's existing customers is product development: a new offering directed at a market the business already serves. It differs from taking existing products into entirely new markets."}}},{"id":"P1_U3_MCQ_1729","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1729","question":"A cereal maker in Johannesburg, South Africa finds that buyers choose low-sugar varieties because they want a healthier breakfast, rather than simply wanting a sweeter taste. Which marketing concept does this illustrate?","options":{"A":"Mass marketing versus niche marketing","B":"Product orientation versus sales orientation","C":"Customer needs versus wants","D":"Primary research versus secondary research"},"correctOption":"C","correctAnswer":"Customer needs versus wants","questionType":"MCQ","explanation":{"correct_reason":"The need is a basic requirement such as nourishment and health, while the want is the particular low-sugar cereal chosen to satisfy it. Recognising this distinction helps the maker design products that satisfy underlying customer needs.","distractor_reasons":{"A":"Mass versus niche marketing concerns how broadly a firm targets buyers, not the difference between a basic requirement for health and the specific low-sugar product preferred.","B":"Product and sales orientations describe a firm's internal focus, whereas the scenario is about interpreting what customers require, not about the maker's own production or selling emphasis.","D":"The two research types concern how information is gathered; the scenario instead concerns the meaning of customers' stated preference for low sugar, which is a needs-and-wants issue.","C":"The need is a basic requirement such as nourishment and health, while the want is the particular low-sugar cereal chosen to satisfy it. Recognising this distinction helps the maker design products that satisfy underlying customer needs."}}},{"id":"P1_U3_MCQ_1730","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1730","question":"A survey team in Nairobi, Kenya numbers every household on a complete local list and uses a computer to select 300 of them, giving each household an equal chance of being chosen. What is the main advantage of this sampling approach?","options":{"A":"Every household has an equal chance, which reduces selection bias","B":"It guarantees each subgroup is represented in exact proportion","C":"It is the cheapest way to gather detailed qualitative opinions","D":"It ensures that only the firm's loyal customers are included"},"correctOption":"A","correctAnswer":"Every household has an equal chance, which reduces selection bias","questionType":"MCQ","explanation":{"correct_reason":"When every household has an equal chance of selection, the researcher's own preferences cannot skew the sample, so random sampling reduces bias. This makes the 300 households a fairer basis for estimating opinion across the whole area.","distractor_reasons":{"B":"Equal chances do not guarantee exact proportions of every subgroup in a sample of 300; that would require a different approach, so the claim of exact representation is too strong.","C":"The method is about choosing respondents, not about cheapness or detailed qualitative opinion; structured surveys of 300 households are quantitative and can be relatively costly.","D":"The list covers every local household, not just loyal customers, and the random selection deliberately avoids hand-picking a particular group such as existing buyers.","A":"When every household has an equal chance of selection, the researcher's own preferences cannot skew the sample, so random sampling reduces bias. This makes the 300 households a fairer basis for estimating opinion across the whole area."}}},{"id":"P1_U3_MCQ_1731","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1731","question":"A supermarket in Lisbon, Portugal runs a two-week 'buy one, get one free' offer on olive oil and puts large signs about it at the store entrance. Which element of the marketing mix is this mainly about?","options":{"A":"Place","B":"Price","C":"Product","D":"Promotion"},"correctOption":"D","correctAnswer":"Promotion","questionType":"MCQ","explanation":{"correct_reason":"A temporary 'buy one, get one free' deal supported by prominent signs is a sales promotion, used to communicate with and stimulate customers. The emphasis on announcing the offer makes promotion the correct mix element here.","distractor_reasons":{"A":"Place concerns channels and locations where goods are sold; while the offer runs in a store, the activity described is the promotional deal and the signs, not a change of distribution route.","B":"Although the deal affects what customers pay, its purpose is a short-term promotional incentive advertised with signs, so the mix element on show is promotion rather than a pricing policy.","C":"Product decisions concern the olive oil's features, quality and packaging; the scenario describes a temporary offer and signage, not any change to the product itself.","D":"A temporary 'buy one, get one free' deal supported by prominent signs is a sales promotion, used to communicate with and stimulate customers. The emphasis on announcing the offer makes promotion the correct mix element here."}}},{"id":"P1_U3_MCQ_1732","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1732","question":"A coffee roaster in Medellín, Colombia currently sells all its beans within Colombia and plans to export them to cafés in Spain for the first time. Which growth strategy is this?","options":{"A":"Product development","B":"Market development","C":"Market penetration","D":"Diversification"},"correctOption":"B","correctAnswer":"Market development","questionType":"MCQ","explanation":{"correct_reason":"Taking the roaster's existing beans into a new geographical market, Spanish cafés, is market development. The product stays the same while the customers and country are new, which distinguishes this strategy from product changes.","distractor_reasons":{"A":"Product development means offering new products to existing customers; the roaster keeps the same beans, so this is a market move rather than a change to the product range.","C":"Market penetration seeks greater sales of existing products in current markets; exporting to Spain for the first time enters a market the roaster does not yet serve.","D":"Diversification requires both new products and new markets; here only the market is new while the coffee beans themselves are unchanged.","B":"Taking the roaster's existing beans into a new geographical market, Spanish cafés, is market development. The product stays the same while the customers and country are new, which distinguishes this strategy from product changes."}}},{"id":"P1_U3_MCQ_1733","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1733","question":"A cosmetics brand in Warsaw, Poland increased its sales from $8 million in 2025 to $9.2 million in 2026. What was its percentage growth in sales over the year?","options":{"A":"12%","B":"15%","C":"18%","D":"20%"},"correctOption":"B","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Sales rose from $8 million to $9.2 million, an increase of $1.2 million. Dividing $1.2 million by the starting $8 million and multiplying by 100 gives 15% growth for the Warsaw brand.","distractor_reasons":{"A":"A 12% increase on $8 million would be $0.96 million, less than the actual $1.2 million rise, so this option has calculated growth against the wrong base.","C":"An 18% rise would add $1.44 million to the original sales; the actual increase is $1.2 million, giving 15% rather than 18%.","D":"A 20% growth rate would mean sales of $9.6 million in 2026; the figure recorded is $9.2 million, so the percentage increase is 15%.","B":"Sales rose from $8 million to $9.2 million, an increase of $1.2 million. Dividing $1.2 million by the starting $8 million and multiplying by 100 gives 15% growth for the Warsaw brand."}}},{"id":"P1_U3_MCQ_1734","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1734","question":"A toy firm in Copenhagen, Denmark invites children into a playroom and quietly watches which parts of a new toy they use, without asking any questions. Which primary research method is being used?","options":{"A":"A questionnaire survey","B":"A focus group","C":"Secondary data analysis","D":"Observation"},"correctOption":"D","correctAnswer":"Observation","questionType":"MCQ","explanation":{"correct_reason":"Watching and recording behaviour as it happens, without questioning participants, is observation. The firm gains first-hand evidence of which toy features children actually use, which is the essence of this primary method.","distractor_reasons":{"A":"A questionnaire survey asks structured questions and records verbal answers; the researchers here ask nothing and simply watch what the children do with the toy.","B":"A focus group involves a facilitated discussion in which participants talk about their views, whereas the children are being watched silently rather than invited to discuss.","C":"Secondary analysis reuses existing data, but the firm is collecting brand-new first-hand evidence by watching children, so this is primary research.","D":"Watching and recording behaviour as it happens, without questioning participants, is observation. The firm gains first-hand evidence of which toy features children actually use, which is the essence of this primary method."}}},{"id":"P1_U3_MCQ_1735","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1735","question":"A clothing shop in Dublin, Ireland prices a jacket at $80, reduces it by 25% in a sale, and bought each jacket for $45. What is the sale price and the shop's profit per jacket?","options":{"A":"$60 sale price and $15 profit","B":"$55 sale price and $10 profit","C":"$60 sale price and $35 profit","D":"$75 sale price and $30 profit"},"correctOption":"A","correctAnswer":"$60 sale price and $15 profit","questionType":"MCQ","explanation":{"correct_reason":"A 25% reduction on the $80 price is $20, so the sale price is $60. Deducting the $45 cost leaves $15 profit per jacket, which is the figure the shop keeps on each sale.","distractor_reasons":{"B":"A $55 price would require a $25 discount, roughly 31% off $80, not 25%; the correct reduction is $20, giving a $60 price and $15 profit.","C":"The $60 sale price is correct, but $35 wrongly uses the $80 original price minus the $45 cost; profit must be based on the actual sale price of $60.","D":"A $75 price would be only a $5 reduction, far below the 25% discount stated; the true sale price is $60 and the resulting profit is $15.","A":"A 25% reduction on the $80 price is $20, so the sale price is $60. Deducting the $45 cost leaves $15 profit per jacket, which is the figure the shop keeps on each sale."}}},{"id":"P1_U3_MCQ_1736","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1736","question":"A soft drink maker in Accra, Ghana originally advertised to teenagers but now campaigns to adults by emphasising zero sugar and health benefits. What is the maker doing?","options":{"A":"Market segmentation","B":"Niche marketing","C":"Repositioning the brand","D":"Price skimming"},"correctOption":"C","correctAnswer":"Repositioning the brand","questionType":"MCQ","explanation":{"correct_reason":"Changing the message and target audience from teenagers to adults, with a new zero-sugar health emphasis, alters how the drink is perceived. That is repositioning the brand in the market.","distractor_reasons":{"A":"Market segmentation is the act of dividing buyers into groups, but the maker is changing the image and audience of an existing brand, which is a repositioning decision.","B":"Niche marketing concentrates on a small specialised group; the maker is broadening from teenagers toward adults rather than focusing narrowly on one niche.","D":"Price skimming sets a high initial price that falls later; no price change is described, only a new health-focused message aimed at different buyers.","C":"Changing the message and target audience from teenagers to adults, with a new zero-sugar health emphasis, alters how the drink is perceived. That is repositioning the brand in the market."}}},{"id":"P1_U3_MCQ_1737","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1737","question":"A courier firm in Manila, Philippines is losing customers because parcels arrive late, and a survey shows a rival delivers a full day faster. What should the firm prioritise to become more competitive?","options":{"A":"Increasing its delivery prices","B":"Reducing its advertising budget","C":"Changing its legal structure","D":"Improving delivery reliability to meet customer needs"},"correctOption":"D","correctAnswer":"Improving delivery reliability to meet customer needs","questionType":"MCQ","explanation":{"correct_reason":"Late parcels are the stated cause of lost customers, and a rival is a full day faster. Improving reliability directly addresses the customer need for timely delivery, helping the courier compete effectively against that rival.","distractor_reasons":{"A":"Raising prices when service is already poor would make the courier less attractive, not more competitive, and does nothing to fix the late deliveries driving customers away.","B":"Cutting advertising might save money but leaves the underlying problem of slow deliveries untouched, so it cannot win back customers who value speed.","C":"Changing legal structure affects ownership and liability rather than delivery speed, so it would not solve the specific reliability problem revealed by the survey.","D":"Late parcels are the stated cause of lost customers, and a rival is a full day faster. Improving reliability directly addresses the customer need for timely delivery, helping the courier compete effectively against that rival."}}},{"id":"P1_U3_MCQ_1738","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1738","question":"A research team in Bogotá, Colombia surveys only shoppers inside one upmarket shopping mall when testing a cheap household product. What is the main weakness of this approach?","options":{"A":"The sample is far too large to analyse","B":"The sample is biased and not representative of buyers","C":"The information collected counts as secondary data","D":"The questions asked are necessarily open-ended"},"correctOption":"B","correctAnswer":"The sample is biased and not representative of buyers","questionType":"MCQ","explanation":{"correct_reason":"Shoppers in one upmarket mall are unlikely to reflect all potential buyers of a cheap product, so the results are distorted toward wealthier consumers. A biased sample cannot be treated as representative of the wider market.","distractor_reasons":{"A":"The scenario does not say the sample is too large; the flaw is where respondents were found, not the number surveyed, which could in fact be quite small.","C":"Questioning shoppers creates new first-hand evidence, so it is primary research; the problem concerns who was selected, not whether the data existed beforehand.","D":"Nothing about question style is stated, and the shoppers could be asked structured questions; the weakness lies in the biased location rather than open-ended wording.","B":"Shoppers in one upmarket mall are unlikely to reflect all potential buyers of a cheap product, so the results are distorted toward wealthier consumers. A biased sample cannot be treated as representative of the wider market."}}},{"id":"P1_U3_MCQ_1739","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1739","question":"A tea company in Colombo, Sri Lanka gives its packets a distinctive logo and colour scheme so that shoppers recognise the brand instantly on a crowded shelf. Which element of the marketing mix is this?","options":{"A":"Place","B":"Price","C":"Product","D":"Promotion"},"correctOption":"C","correctAnswer":"Product","questionType":"MCQ","explanation":{"correct_reason":"Branding and packaging are part of the product element of the marketing mix. A distinctive logo and colour scheme help the tea stand out and shape customers' perception of what is being bought.","distractor_reasons":{"A":"Place concerns how the tea reaches shops and which outlets stock it; a logo and colour scheme change the item itself, not its distribution route.","B":"Price decisions set the amount charged and any discounts; no price is mentioned, so the brand identity described belongs to the product rather than to pricing.","D":"Promotion communicates with customers through advertising and sales messages; while the packet helps recognition, the logo and colours are part of the product's branding.","C":"Branding and packaging are part of the product element of the marketing mix. A distinctive logo and colour scheme help the tea stand out and shape customers' perception of what is being bought."}}},{"id":"P1_U3_MCQ_1740","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1740","question":"A hotel in Prague, Czech Republic targets business travellers with fast Wi-Fi and meeting rooms, while nearby rivals mainly attract holiday tourists. What is the hotel's approach?","options":{"A":"Targeting a distinct segment with a tailored offering","B":"Mass marketing to the whole market","C":"Cost leadership through the lowest prices","D":"Avoiding any form of segmentation"},"correctOption":"A","correctAnswer":"Targeting a distinct segment with a tailored offering","questionType":"MCQ","explanation":{"correct_reason":"By identifying business travellers and providing amenities they value, such as Wi-Fi and meeting rooms, the hotel selects a specific segment and shapes its offering around it. That is targeted, segmented marketing.","distractor_reasons":{"B":"Mass marketing would offer one standard service to every guest; the hotel deliberately focuses on business travellers rather than all potential visitors to Prague.","C":"Cost leadership competes on low prices, but the hotel is differentiating through facilities for business guests and no cheap-price claim is made.","D":"The hotel is clearly distinguishing a business segment from leisure tourists, so it is using segmentation rather than avoiding it. In the business's case, the correct description is Targeting a distinct segment with a tailored offering, not this choice.","A":"By identifying business travellers and providing amenities they value, such as Wi-Fi and meeting rooms, the hotel selects a specific segment and shapes its offering around it. That is targeted, segmented marketing."}}},{"id":"P1_U3_MCQ_1741","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1741","question":"A bakery chain in Casablanca, Morocco sold 5,400 cakes in 2026 in a city wide cake market of 18,000 units. What was the chain's market share by volume?","options":{"A":"25%","B":"30%","C":"33%","D":"36%"},"correctOption":"B","correctAnswer":"30%","questionType":"MCQ","explanation":{"correct_reason":"Market share by volume is the firm's unit sales divided by total market units, times 100. The chain's 5,400 cakes divided by the 18,000-cake market equals 0.30, giving a 30% share in Casablanca.","distractor_reasons":{"A":"A 25% share would be 4,500 cakes out of 18,000, fewer than the 5,400 sold, so this option understates the chain's position in the market.","C":"A 33% share would require about 5,940 cakes, above the 5,400 recorded; the exact calculation gives 30% for the Casablanca chain.","D":"A 36% share would mean 6,480 cakes, exceeding the 5,400 actually sold, so this figure cannot be derived from the given numbers.","B":"Market share by volume is the firm's unit sales divided by total market units, times 100. The chain's 5,400 cakes divided by the 18,000-cake market equals 0.30, giving a 30% share in Casablanca."}}},{"id":"P1_U3_MCQ_1742","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1742","question":"An airline in Addis Ababa, Ethiopia examines complaints logged by its own call centre to identify recurring service problems. What type of research is this?","options":{"A":"External secondary research","B":"Primary research using experiments","C":"Observation of competitor behaviour","D":"Internal secondary research"},"correctOption":"D","correctAnswer":"Internal secondary research","questionType":"MCQ","explanation":{"correct_reason":"The complaint logs already exist within the airline and were recorded for operational reasons, so analysing them is secondary research using internal data. No new evidence is gathered directly from passengers for this study.","distractor_reasons":{"A":"The records belong to the airline itself, so they are internal rather than external; external secondary data would come from another organisation such as a government agency.","B":"Primary research collects new first-hand evidence, but the airline is reusing existing logs, and no controlled experiment or new survey of passengers is described.","C":"Watching competitors would involve gathering fresh data about other airlines; examining the airline's own complaint records is analysis of internal existing information.","D":"The complaint logs already exist within the airline and were recorded for operational reasons, so analysing them is secondary research using internal data. No new evidence is gathered directly from passengers for this study."}}},{"id":"P1_U3_MCQ_1743","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1743","question":"A bakery in Tallinn, Estonia sells cakes for $12 each with a variable cost of $7 per cake and monthly fixed costs of $1,500. If it sells 500 cakes in a month, what is its monthly profit?","options":{"A":"$1,000","B":"$2,500","C":"$1,500","D":"$600"},"correctOption":"A","correctAnswer":"$1,000","questionType":"MCQ","explanation":{"correct_reason":"Each cake contributes $12 minus $7, which is $5. Selling 500 cakes gives $2,500 of total contribution, and deducting the $1,500 fixed costs leaves a monthly profit of $1,000 for the bakery.","distractor_reasons":{"B":"$2,500 is the total contribution from 500 cakes at $5 each, but fixed costs of $1,500 must still be deducted, so it is not the profit.","C":"$1,500 is simply the monthly fixed cost; profit requires subtracting that figure from the $2,500 contribution earned on the 500 cakes sold.","D":"$600 does not follow from the figures: 500 cakes at $5 contribution gives $2,500, and taking away $1,500 leaves $1,000. For the business, the facts point to $1,000, so this option cannot be correct.","A":"Each cake contributes $12 minus $7, which is $5. Selling 500 cakes gives $2,500 of total contribution, and deducting the $1,500 fixed costs leaves a monthly profit of $1,000 for the bakery."}}},{"id":"P1_U3_MCQ_1744","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1744","question":"A gym in Brisbane, Australia offers discounted annual memberships and free personal training sessions to members who renew. What is the main strategic aim of these offers?","options":{"A":"To attract only brand-new customers","B":"To lower the quality of its facilities","C":"To build long-term customer relationships","D":"To remove all competing gyms from the area"},"correctOption":"C","correctAnswer":"To build long-term customer relationships","questionType":"MCQ","explanation":{"correct_reason":"Rewarding members who renew encourages them to stay with the gym and deepens the ongoing relationship. The free training sessions and renewal discounts aimed at existing members are designed to build long-term loyalty.","distractor_reasons":{"A":"The offers go specifically to members who renew, so they target existing customers rather than brand-new ones, which the reward scheme does not address.","B":"Adding free training sessions improves the service on offer and says nothing about reducing facility quality, which would not help retain members in any case.","D":"A gym cannot eliminate competitors through renewal discounts; the scheme is about keeping its own members, not about removing rival businesses from the area.","C":"Rewarding members who renew encourages them to stay with the gym and deepens the ongoing relationship. The free training sessions and renewal discounts aimed at existing members are designed to build long-term loyalty."}}},{"id":"P1_U3_MCQ_1745","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1745","question":"A restaurant in Bangkok, Thailand regularly asks diners what they would like and then adapts its menu and opening hours accordingly. Which business orientation does this demonstrate?","options":{"A":"Market orientation","B":"Product orientation","C":"Production orientation","D":"Sales orientation"},"correctOption":"A","correctAnswer":"Market orientation","questionType":"MCQ","explanation":{"correct_reason":"A market orientation puts customer needs at the centre of decisions. By asking diners what they want and changing the menu and hours in response, the Bangkok restaurant is putting customer preferences first.","distractor_reasons":{"B":"Product orientation concentrates on the product the firm wants to make, but the restaurant changes its menu based on diner feedback rather than on its own preferences.","C":"Production orientation emphasises efficient output and capacity, whereas the restaurant is adapting to what customers request, not simply to what is easiest to produce.","D":"Sales orientation focuses on persuasive selling to shift existing stock; the restaurant instead gathers information first and then adjusts its offering to match it.","A":"A market orientation puts customer needs at the centre of decisions. By asking diners what they want and changing the menu and hours in response, the Bangkok restaurant is putting customer preferences first."}}},{"id":"P1_U3_MCQ_1746","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1746","question":"A cosmetics firm in Melbourne, Australia uses published census data to estimate local demand before paying for expensive fieldwork. What is the main advantage of using this data first?","options":{"A":"It is always more accurate than primary data","B":"It gives detailed open-ended customer opinions","C":"It is quicker and cheaper to obtain","D":"It guarantees a perfectly representative sample"},"correctOption":"C","correctAnswer":"It is quicker and cheaper to obtain","questionType":"MCQ","explanation":{"correct_reason":"Published census figures already exist, so the firm can consult them immediately and at little cost compared with commissioning new fieldwork. Speed and lower expense are the key advantages of using secondary data first.","distractor_reasons":{"A":"Secondary data is not automatically more accurate; census figures may be outdated or too broad, so the firm may still need primary research for its specific question.","B":"Census data consists of numerical statistics, not the detailed open-ended opinions that interviews or focus groups would provide about cosmetics. The scenario for the business instead describes It is quicker and cheaper to obtain, which rules this alternative out.","D":"Using published data does not guarantee a sample designed for the firm's purpose; it describes a whole population but may not match the target customers precisely.","C":"Published census figures already exist, so the firm can consult them immediately and at little cost compared with commissioning new fieldwork. Speed and lower expense are the key advantages of using secondary data first."}}},{"id":"P1_U3_MCQ_1747","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1747","question":"A book publisher in Toronto, Canada sells titles through online retailers and independent bookshops rather than opening its own stores. Which element of the marketing mix is this decision about?","options":{"A":"Product","B":"Place","C":"Promotion","D":"Price"},"correctOption":"B","correctAnswer":"Place","questionType":"MCQ","explanation":{"correct_reason":"Place covers the routes by which a product reaches customers, including which intermediaries are used. Choosing online retailers and bookshops instead of own stores is a clear distribution decision within the mix.","distractor_reasons":{"A":"Product decisions concern the books' content, design and packaging; the publisher is choosing where to sell them, not altering the books themselves.","C":"Promotion involves communicating with readers through advertising and events; using retailers to distribute the books is about availability, not about promotional messages.","D":"No cover price or discount is discussed, so this cannot be a price decision; the scenario is entirely about sales channels.","B":"Place covers the routes by which a product reaches customers, including which intermediaries are used. Choosing online retailers and bookshops instead of own stores is a clear distribution decision within the mix."}}},{"id":"P1_U3_MCQ_1748","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1748","question":"A bank in Kuala Lumpur, Malaysia assigns relationship managers to high-value clients and tailors services to each client's circumstances. Which marketing strategy is the bank applying?","options":{"A":"Mass marketing","B":"Undifferentiated marketing","C":"Price skimming","D":"Relationship marketing"},"correctOption":"D","correctAnswer":"Relationship marketing","questionType":"MCQ","explanation":{"correct_reason":"Building long-term, personal links with valuable clients through dedicated managers and tailored services is relationship marketing. The focus is on retaining and deepening individual customer relationships rather than one-off sales.","distractor_reasons":{"A":"Mass marketing addresses a whole market with a single standard message, whereas the bank is giving high-value clients individual attention from relationship managers.","B":"Undifferentiated marketing ignores differences between customers, the opposite of the bank's approach of tailoring services to each client's circumstances in Luxembourg.","C":"Price skimming concerns a high launch price that is later reduced; no pricing sequence is described, only personalised ongoing service for clients.","D":"Building long-term, personal links with valuable clients through dedicated managers and tailored services is relationship marketing. The focus is on retaining and deepening individual customer relationships rather than one-off sales."}}},{"id":"P1_U3_MCQ_1749","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1749","question":"A detergent brand in Lagos, Nigeria held 20% of a $50 million market in 2025. In 2026 the market was worth $60 million and the brand's sales reached $15 million. What happened to its market share?","options":{"A":"It fell to about 16.7%","B":"It stayed at exactly 20%","C":"It rose to 25%","D":"It rose to 30%"},"correctOption":"C","correctAnswer":"It rose to 25%","questionType":"MCQ","explanation":{"correct_reason":"In 2026 the brand's $15 million of sales divided by the $60 million market is 25%. Compared with its 20% share in 2025, the brand gained 5 percentage points, even though the market itself grew.","distractor_reasons":{"A":"The share did not fall; $15 million out of $60 million is 25%, and the 16.7% figure wrongly divides the 2025 sales by the new, larger market.","B":"A 20% share of the $60 million market would be $12 million of sales, but the brand achieved $15 million, so its share increased rather than staying flat.","D":"A 30% share would require $18 million of sales in the $60 million market; actual sales were $15 million, giving 25% not 30%.","C":"In 2026 the brand's $15 million of sales divided by the $60 million market is 25%. Compared with its 20% share in 2025, the brand gained 5 percentage points, even though the market itself grew."}}},{"id":"P1_U3_MCQ_1750","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1750","question":"A survey team in Santiago, Chile drafts a question that asks 'How much do you love our wonderful new product?' before showing any alternative. What is the main problem with this question?","options":{"A":"It is a leading question that biases the answer","B":"It asks for numerical data only","C":"The sample used is far too large","D":"It relies on secondary information"},"correctOption":"A","correctAnswer":"It is a leading question that biases the answer","questionType":"MCQ","explanation":{"correct_reason":"Words such as 'love' and 'wonderful' push respondents toward a positive reply, making the item a leading question. Neutral wording is needed so the survey records genuine opinions rather than answers suggested by the question itself.","distractor_reasons":{"B":"The question is not limited to numerical answers; the real flaw is its emotive wording, which steers respondents toward a favourable response about the new product.","C":"The size of the sample is not mentioned and is not the issue here; even a small sample would still produce distorted answers from this badly worded question.","D":"Asking shoppers directly would create new first-hand evidence, so the data is primary; the problem is the biased phrasing, not the source of the information.","A":"Words such as 'love' and 'wonderful' push respondents toward a positive reply, making the item a leading question. Neutral wording is needed so the survey records genuine opinions rather than answers suggested by the question itself."}}},{"id":"P1_U3_MCQ_1751","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1751","question":"A toy shop in Helsinki, Finland buys a board game for $18 and applies a mark-up of 40% on cost. What is the selling price and the mark-up in dollars per game?","options":{"A":"$25.20 price and $7.20 mark-up","B":"$25.20 price and $18 mark-up","C":"$22.00 price and $4.00 mark-up","D":"$18.00 price and $7.20 mark-up"},"correctOption":"A","correctAnswer":"$25.20 price and $7.20 mark-up","questionType":"MCQ","explanation":{"correct_reason":"A 40% mark-up on the $18 cost is 0.40 times $18, which equals $7.20. Adding that to cost gives a selling price of $25.20, so the shop charges $25.20 and earns a $7.20 mark-up per game.","distractor_reasons":{"B":"The $25.20 price is right, but $18 is the shop's original cost, not the mark-up; the addition is 40% of $18, which is $7.20.","C":"A $4.00 mark-up would be about 22% of the $18 cost, not 40%; the correct addition is $7.20, giving a price of $25.20.","D":"An $18.00 price leaves no mark-up at all and ignores the stated 40% addition; the true selling price is $18 plus $7.20, which is $25.20.","A":"A 40% mark-up on the $18 cost is 0.40 times $18, which equals $7.20. Adding that to cost gives a selling price of $25.20, so the shop charges $25.20 and earns a $7.20 mark-up per game."}}},{"id":"P1_U3_MCQ_1752","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1752","question":"A snack brand in Guadalajara, Mexico previously sold one product to everybody, but now designs separate packaging and advertisements for children and for office workers. What strategy is the brand adopting?","options":{"A":"Mass marketing","B":"Cost leadership","C":"Market segmentation","D":"Product orientation"},"correctOption":"C","correctAnswer":"Market segmentation","questionType":"MCQ","explanation":{"correct_reason":"Dividing buyers into two identifiable groups and creating distinct packaging and messages for each is market segmentation. The brand recognises that children and office workers have different preferences and tailors its approach accordingly.","distractor_reasons":{"A":"Mass marketing would use one package and a single message for everyone, whereas the brand now deliberately separates children from office workers with tailored materials.","B":"Cost leadership competes through low prices and efficiency; nothing about pricing or costs is described, only different offerings for two customer groups.","D":"Product orientation focuses on what the producer wants to make, but the brand is responding to differing needs of two groups, which is a customer-based approach.","C":"Dividing buyers into two identifiable groups and creating distinct packaging and messages for each is market segmentation. The brand recognises that children and office workers have different preferences and tailors its approach accordingly."}}},{"id":"P1_U3_MCQ_1753","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1753","question":"A hotel chain in Athens, Greece notices that guests increasingly compare prices on travel websites and choose hotels largely on the basis of reviews left by previous visitors. What does this reveal about modern customers?","options":{"A":"Customers rarely look at other buyers' opinions","B":"Price is the only factor in hotel choice","C":"Distribution channels no longer matter to hotels","D":"Customers use external information and peer reviews when choosing"},"correctOption":"D","correctAnswer":"Customers use external information and peer reviews when choosing","questionType":"MCQ","explanation":{"correct_reason":"The chain's guests consult comparison websites and other travellers' reviews before booking, showing that external information and peer opinions shape decisions. Understanding these influences helps the hotel manage its reputation.","distractor_reasons":{"A":"The scenario says guests choose largely on reviews left by previous visitors, so they clearly do consult other buyers' opinions, often in detail.","B":"Although price comparisons are mentioned, reviews are described as a major influence too, so it is wrong to claim that price is the only factor in the decision.","C":"The travel websites are themselves an important route to customers, so distribution channels still matter greatly to the hotel chain. For the business, the facts point to Customers use external information and peer reviews when choosing, so this option cannot be correct.","D":"The chain's guests consult comparison websites and other travellers' reviews before booking, showing that external information and peer opinions shape decisions. Understanding these influences helps the hotel manage its reputation."}}},{"id":"P1_U3_MCQ_1754","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1754","question":"A researcher in Lisbon, Portugal wants to understand why shoppers choose certain brands and invites eight of them to discuss their views freely with a moderator. Which research method is being used?","options":{"A":"A postal survey","B":"A focus group","C":"Analysis of sales figures","D":"Observation of purchases"},"correctOption":"B","correctAnswer":"A focus group","questionType":"MCQ","explanation":{"correct_reason":"A small group of people discussing their views freely under a moderator is a focus group. It produces qualitative insight into the reasons behind brand choices that numerical sales figures alone cannot explain.","distractor_reasons":{"A":"A postal survey sends structured written questions and is normally distributed to many people, not eight participants in a moderated discussion.","C":"Sales figures are existing numerical records and cannot reveal the reasons behind brand choices; the researcher is collecting new first-hand opinions.","D":"Observation watches behaviour without asking about reasons, while here the shoppers are talking about why they choose particular brands in Lisbon.","B":"A small group of people discussing their views freely under a moderator is a focus group. It produces qualitative insight into the reasons behind brand choices that numerical sales figures alone cannot explain."}}},{"id":"P1_U3_MCQ_1755","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1755","question":"A university in Leeds, United Kingdom publishes its annual tuition fees and offers a discount to students who apply before March. Which two elements of the marketing mix are illustrated?","options":{"A":"Product and place","B":"Place and promotion","C":"Price and promotion","D":"Product and price"},"correctOption":"C","correctAnswer":"Price and promotion","questionType":"MCQ","explanation":{"correct_reason":"Announcing the tuition fee is a price decision, while the early-application discount is a short-term incentive used to attract students. Together they illustrate the price and promotion elements of the mix.","distractor_reasons":{"A":"No detail about the course's content or about where it is delivered is given; the scenario centres on the fee and the early discount, not product or place.","B":"Although the discount promotes the university, there is no mention of distribution channels or locations, so place is not one of the elements shown.","D":"The fee is clearly a price matter, but the course itself is not described; the discount is a promotional incentive rather than a feature of the product.","C":"Announcing the tuition fee is a price decision, while the early-application discount is a short-term incentive used to attract students. Together they illustrate the price and promotion elements of the mix."}}},{"id":"P1_U3_MCQ_1756","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1756","question":"A cosmetics brand in Paris, France launches a luxury sub-brand for high-income shoppers while keeping its existing affordable range for students. What is this approach called?","options":{"A":"Market segmentation with differentiated offerings","B":"Mass marketing","C":"Cost leadership","D":"Market penetration"},"correctOption":"A","correctAnswer":"Market segmentation with differentiated offerings","questionType":"MCQ","explanation":{"correct_reason":"The brand identifies two distinct customer groups with different needs and budgets, then offers each a tailored range. This is market segmentation with differentiated offerings rather than a single product for everyone.","distractor_reasons":{"B":"Mass marketing uses one offering for the entire market, whereas the Paris brand deliberately provides a luxury line and an affordable line for separate groups.","C":"Cost leadership means competing on the lowest prices; the luxury sub-brand carries premium positioning, so cost leadership does not describe this approach.","D":"Market penetration means selling more of the same products in existing markets; here the brand is introducing a distinct new range aimed at different buyers.","A":"The brand identifies two distinct customer groups with different needs and budgets, then offers each a tailored range. This is market segmentation with differentiated offerings rather than a single product for everyone."}}},{"id":"P1_U3_MCQ_1757","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1757","question":"A bottled water brand in Lima, Peru sold 45,000 bottles in 2026, up from 36,000 bottles in 2025. What was the percentage increase in sales?","options":{"A":"20%","B":"25%","C":"30%","D":"9%"},"correctOption":"B","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"Sales rose from 36,000 to 45,000 bottles, an increase of 9,000. Dividing 9,000 by the original 36,000 and multiplying by 100 gives a 25% increase in the brand's sales.","distractor_reasons":{"A":"A 20% increase would add 7,200 bottles to the 36,000 baseline, fewer than the 9,000 actually gained, so this option understates the growth.","C":"A 30% rise would be 10,800 extra bottles; the real increase is 9,000, which is 25% of the original figure. The details given about the business support 25%, so this answer is unsuitable.","D":"The 9,000-bottle increase is an absolute number; converting it to a percentage requires dividing by 36,000, which yields 25% rather than 9%.","B":"Sales rose from 36,000 to 45,000 bottles, an increase of 9,000. Dividing 9,000 by the original 36,000 and multiplying by 100 gives a 25% increase in the brand's sales."}}},{"id":"P1_U3_MCQ_1758","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1758","question":"A bakery in Krakow, Poland wants to know whether a new wrapper colour increases sales and shows identical loaves in two different wrappers to two similar groups of shoppers. Which research method is this?","options":{"A":"A focus group","B":"Secondary data analysis","C":"An open-ended interview","D":"An experiment"},"correctOption":"D","correctAnswer":"An experiment","questionType":"MCQ","explanation":{"correct_reason":"Changing one factor, the wrapper colour, while keeping other conditions similar and comparing the two groups is an experiment. It lets the bakery test a cause-and-effect relationship between packaging and purchases.","distractor_reasons":{"A":"A focus group is a discussion about attitudes, not a controlled comparison of sales between two groups exposed to different wrappers.","B":"The bakery is gathering new first-hand evidence rather than reusing existing records, so this is primary research and not secondary data analysis.","C":"An open-ended interview collects spoken opinions from individuals; comparing purchases across two groups with one changed factor is a controlled test instead.","D":"Changing one factor, the wrapper colour, while keeping other conditions similar and comparing the two groups is an experiment. It lets the bakery test a cause-and-effect relationship between packaging and purchases."}}},{"id":"P1_U3_MCQ_1759","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1759","question":"A hardware store in Nairobi, Kenya sells a power drill for $90 having bought it for $60. What is the mark-up as a percentage of cost?","options":{"A":"50%","B":"30%","C":"33.3%","D":"60%"},"correctOption":"A","correctAnswer":"50%","questionType":"MCQ","explanation":{"correct_reason":"The mark-up in dollars is $90 minus $60, which is $30. Expressed as a percentage of the $60 cost, 30 divided by 60 equals 0.5, so the mark-up is 50% of cost.","distractor_reasons":{"B":"A 30% mark-up on cost would be $18, giving a price of $78; the actual extra amount is $30, which is 50% of the $60 cost.","C":"The 33.3% figure wrongly divides the $30 mark-up by the $90 selling price, which calculates margin on sales rather than the mark-up on cost requested here.","D":"A 60% mark-up would be $36 on a $60 cost, giving a $96 price; the store charges $90, so the mark-up is 50%.","A":"The mark-up in dollars is $90 minus $60, which is $30. Expressed as a percentage of the $60 cost, 30 divided by 60 equals 0.5, so the mark-up is 50% of cost."}}},{"id":"P1_U3_MCQ_1760","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1760","question":"A ride-hailing firm in Jakarta, Indonesia already has many regular passengers and now adds a food-delivery service for those same users. Which growth strategy is it pursuing?","options":{"A":"Market development","B":"Market penetration","C":"Product development","D":"Diversification"},"correctOption":"C","correctAnswer":"Product development","questionType":"MCQ","explanation":{"correct_reason":"Offering a new food-delivery service to the firm's existing passenger base is product development: a new service aimed at a market the business already serves. The customers stay the same while the offering expands.","distractor_reasons":{"A":"Market development would take the existing ride service into a new market such as another country; here the users are already customers and the service is new.","B":"Market penetration means increasing use of the existing ride service among current users; adding food delivery creates a genuinely new service rather than deeper use of the old one.","D":"Diversification needs both new products and new markets; the firm keeps its existing customers, so this is a narrower product-development move.","C":"Offering a new food-delivery service to the firm's existing passenger base is product development: a new service aimed at a market the business already serves. The customers stay the same while the offering expands."}}},{"id":"P1_U3_MCQ_1761","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1761","question":"A bookstore chain in Melbourne, Australia sold 9,000 books in 2026 in a local book market of 45,000 units. What was the chain's market share by volume?","options":{"A":"20%","B":"25%","C":"18%","D":"5%"},"correctOption":"A","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"Market share by volume equals the firm's unit sales divided by total market units, multiplied by 100. The chain's 9,000 books divided by the 45,000-book market gives 0.20, so its share is 20%.","distractor_reasons":{"B":"A 25% share would require 11,250 books, more than the 9,000 sold, so this option overstates the chain's true position in the market.","C":"An 18% share would be 8,100 books out of 45,000, below the 9,000 recorded; the exact calculation gives 20% for the chain.","D":"A 5% share would be just 2,250 books, far fewer than the 9,000 actually sold, so this cannot follow from the figures given.","A":"Market share by volume equals the firm's unit sales divided by total market units, multiplied by 100. The chain's 9,000 books divided by the 45,000-book market gives 0.20, so its share is 20%."}}},{"id":"P1_U3_MCQ_1762","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1762","question":"A research team in Accra, Ghana records the exact number of canned drinks purchased in each of 50 shops. Which statement about the data being collected is correct?","options":{"A":"It always comes from focus groups","B":"It consists of personal opinions and feelings","C":"It can be counted and expressed numerically","D":"It can only ever be secondary information"},"correctOption":"C","correctAnswer":"It can be counted and expressed numerically","questionType":"MCQ","explanation":{"correct_reason":"Counts of cans sold are numerical measurements, which makes them quantitative data. Such figures can be added, averaged and compared statistically across the 50 shops in the survey.","distractor_reasons":{"A":"Focus groups generate spoken opinions rather than exact counts, and numerical purchase figures can come from invoices, tills or direct counting instead.","B":"Opinions and feelings are qualitative data; the team is recording precise numbers of cans, which is a different kind of information.","D":"Counting purchases in shops creates new first-hand evidence, so it is primary data; numerical information is not restricted to secondary sources.","C":"Counts of cans sold are numerical measurements, which makes them quantitative data. Such figures can be added, averaged and compared statistically across the 50 shops in the survey."}}},{"id":"P1_U3_MCQ_1763","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1763","question":"A mobile network in Manila, Philippines offers a free second SIM card to every customer who signs a new contract this month. Which element of the marketing mix does this mainly illustrate?","options":{"A":"Place","B":"Promotion","C":"Product","D":"Price"},"correctOption":"B","correctAnswer":"Promotion","questionType":"MCQ","explanation":{"correct_reason":"A limited-time free gift attached to signing a contract is a sales promotion designed to stimulate purchases. The emphasis on encouraging new contracts through an incentive makes promotion the correct mix element.","distractor_reasons":{"A":"Place concerns where and how the service is sold; the free SIM is an incentive to buy rather than a change in distribution channels.","C":"Product decisions concern the features and quality of the network service; the extra SIM is a temporary inducement, not a change to the core service itself.","D":"Although the gift has a value, the scenario describes a short-term promotional offer rather than a general pricing policy for the network's contracts.","B":"A limited-time free gift attached to signing a contract is a sales promotion designed to stimulate purchases. The emphasis on encouraging new contracts through an incentive makes promotion the correct mix element."}}},{"id":"P1_U3_MCQ_1764","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1764","question":"A private bank in Luxembourg offers bespoke wealth-management services only to very high-net-worth individuals, rather than to the general public. Which strategy is the bank following?","options":{"A":"Mass marketing","B":"Cost leadership","C":"Market development","D":"Niche marketing"},"correctOption":"D","correctAnswer":"Niche marketing","questionType":"MCQ","explanation":{"correct_reason":"By concentrating on a narrow, specialised group of very wealthy clients with a tailored service, the bank is targeting a niche. It ignores the mass market in favour of customers with distinctive needs.","distractor_reasons":{"A":"Mass marketing addresses the whole population with one standard offering, whereas the bank deliberately restricts its services to a small group of wealthy individuals.","B":"Cost leadership competes on low prices for broad markets; bespoke wealth management is a high-value, personalised service, not a low-cost strategy.","C":"Market development takes existing services into new markets such as another country; the bank is focusing narrowly on one client type rather than expanding geographically.","D":"By concentrating on a narrow, specialised group of very wealthy clients with a tailored service, the bank is targeting a niche. It ignores the mass market in favour of customers with distinctive needs."}}},{"id":"P1_U3_MCQ_1765","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1765","question":"A coffee shop chain in Seoul, South Korea grew from 12,000 regular customers in 2025 to 15,000 in 2026. What was the percentage increase in its customer base?","options":{"A":"20%","B":"30%","C":"25%","D":"3%"},"correctOption":"C","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"The customer base rose by 3,000, from 12,000 to 15,000. Dividing the 3,000 increase by the original 12,000 and multiplying by 100 gives a 25% growth in regular customers.","distractor_reasons":{"A":"A 20% rise on 12,000 would be 2,400 extra customers, below the 3,000 actually gained, so this option understates the increase.","B":"A 30% increase would add 3,600 customers to the starting base; the real gain is 3,000, which is 25% of 12,000.","D":"The 3,000 additional customers is an absolute figure; expressing it as a percentage requires division by 12,000, which gives 25% rather than 3%.","C":"The customer base rose by 3,000, from 12,000 to 15,000. Dividing the 3,000 increase by the original 12,000 and multiplying by 100 gives a 25% growth in regular customers."}}},{"id":"P1_U3_MCQ_1766","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1766","question":"A research team in Dublin, Ireland needs its sample of 500 shoppers to contain the same proportion of each age group as the local population, so it sets a target number for every age band. Which sampling method is this?","options":{"A":"Quota sampling","B":"Random sampling","C":"Observation","D":"Secondary research"},"correctOption":"A","correctAnswer":"Quota sampling","questionType":"MCQ","explanation":{"correct_reason":"Setting target numbers so that subgroups appear in the same proportions as the population is quota sampling. The Dublin team controls the composition of its 500 shoppers to mirror the age structure of local residents.","distractor_reasons":{"B":"Random sampling gives each person an equal chance but does not deliberately set numbers for each age band, so it would not guarantee matching population proportions.","C":"Observation records behaviour without selecting a sample to match a population profile; the team is actively setting quotas for age groups.","D":"Selecting and questioning 500 shoppers creates new first-hand evidence, so it is primary research, not the reuse of existing secondary information.","A":"Setting target numbers so that subgroups appear in the same proportions as the population is quota sampling. The Dublin team controls the composition of its 500 shoppers to mirror the age structure of local residents."}}},{"id":"P1_U3_MCQ_1767","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1767","question":"A café in Wellington, New Zealand sells coffee for $5 a cup, with a variable cost of $1.50 per cup and monthly fixed costs of $3,500. How many cups must it sell each month to break even?","options":{"A":"700 cups","B":"1,167 cups","C":"778 cups","D":"1,000 cups"},"correctOption":"D","correctAnswer":"1,000 cups","questionType":"MCQ","explanation":{"correct_reason":"Each cup contributes $5 minus $1.50, which is $3.50. Dividing the $3,500 fixed costs by $3.50 gives 1,000 cups, so the café must sell that many each month to cover all its costs.","distractor_reasons":{"A":"700 cups would generate only $2,450 of contribution at $3.50 each, short of the $3,500 fixed costs, so the café would still make a loss.","B":"About 1,167 cups comes from dividing the fixed costs by the $3 selling price rather than by the $3.50 contribution, so it ignores the variable cost correctly.","C":"Roughly 778 cups is not derivable from these figures; the correct method divides $3,500 by the $3.50 contribution per cup to obtain 1,000.","D":"Each cup contributes $5 minus $1.50, which is $3.50. Dividing the $3,500 fixed costs by $3.50 gives 1,000 cups, so the café must sell that many each month to cover all its costs."}}},{"id":"P1_U3_MCQ_1768","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1768","question":"A hotel in Reykjavik, Iceland runs social media advertisements showing northern lights experiences to attract winter visitors. What is the main aim of this activity?","options":{"A":"To collect primary research data","B":"To promote a distinctive experience to a target market","C":"To reduce the hotel's operating costs","D":"To change the hotel's legal structure"},"correctOption":"B","correctAnswer":"To promote a distinctive experience to a target market","questionType":"MCQ","explanation":{"correct_reason":"The advertisements highlight a distinctive northern lights experience to draw winter visitors, so the activity promotes an offering to a chosen market. Its purpose is to attract bookings by communicating what makes the hotel appealing.","distractor_reasons":{"A":"The hotel is placing advertisements, not collecting first-hand evidence from customers; no survey, interview or observation is described in Reykjavik at all.","C":"Running a social media campaign involves spending rather than saving money, and the scenario gives no information about changes to the hotel's operating costs.","D":"Changing legal structure concerns ownership and liability, which is unrelated to advertising the hotel's northern lights experience to holidaymakers in Iceland.","B":"The advertisements highlight a distinctive northern lights experience to draw winter visitors, so the activity promotes an offering to a chosen market. Its purpose is to attract bookings by communicating what makes the hotel appealing."}}},{"id":"P1_U3_MCQ_1769","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1769","question":"A supermarket in Singapore notices that sales of its own-brand milk rose sharply in the same month a rival increased its milk price. What is the most reasonable interpretation?","options":{"A":"Customers had become insensitive to price changes","B":"Some shoppers switched to a cheaper alternative","C":"The supermarket's overall market share must have fallen","D":"The quality of the own-brand milk declined"},"correctOption":"B","correctAnswer":"Some shoppers switched to a cheaper alternative","questionType":"MCQ","explanation":{"correct_reason":"When a rival raises its price, a cheaper own-brand becomes relatively more attractive, so the rise in own-brand sales is best explained by customers switching to that alternative in response to the price change.","distractor_reasons":{"A":"The opposite is implied: the change in relative prices appears to have influenced buying behaviour, which suggests customers do respond to price differences.","C":"Nothing about total market sales or competitors' volumes is given, so no conclusion about the supermarket's overall market share can be drawn from these figures.","D":"A fall in quality would likely reduce sales, not increase them, and the scenario provides no evidence about the milk's quality at all.","B":"When a rival raises its price, a cheaper own-brand becomes relatively more attractive, so the rise in own-brand sales is best explained by customers switching to that alternative in response to the price change."}}},{"id":"P1_U3_MCQ_1770","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1770","question":"A firm in Buenos Aires, Argentina prepares its customer questionnaire in both Spanish and English because its shoppers speak different languages. Why is this important?","options":{"A":"To make the collected information secondary","B":"To reduce the number of people surveyed","C":"To avoid carrying out any primary research","D":"So respondents understand the questions and give valid answers"},"correctOption":"D","correctAnswer":"So respondents understand the questions and give valid answers","questionType":"MCQ","explanation":{"correct_reason":"If respondents cannot understand the wording, their answers will be meaningless. Translating the questionnaire helps each shopper interpret the questions correctly, producing reliable and valid primary data for the firm.","distractor_reasons":{"A":"Translating a newly written questionnaire does not change it into secondary data; the firm is still gathering evidence first-hand from its own customers.","B":"Offering two language versions is intended to include more respondents, not to cut the number surveyed, and it has no effect on sample size targets.","C":"The questionnaire is a primary research instrument, and translating it improves that research rather than avoiding it altogether for the Argentine firm.","D":"If respondents cannot understand the wording, their answers will be meaningless. Translating the questionnaire helps each shopper interpret the questions correctly, producing reliable and valid primary data for the firm."}}},{"id":"P1_U3_MCQ_1771","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1771","question":"A furniture maker in Stockholm, Sweden offers a five-year guarantee on every sofa it sells, promising free repairs if faults appear. Which element of the marketing mix is this mainly about?","options":{"A":"Product","B":"Place","C":"Promotion","D":"Price"},"correctOption":"A","correctAnswer":"Product","questionType":"MCQ","explanation":{"correct_reason":"A guarantee is part of the product offering, adding reassurance about quality and after-sales support. It changes what the customer receives with the sofa, so it belongs to the product element of the mix.","distractor_reasons":{"B":"Place concerns the channels used to deliver the sofa to buyers; a promise of free repairs is not about distribution or where the product is sold.","C":"Although the guarantee can be advertised, it is a feature of the product itself rather than a separate communication or sales-promotion activity.","D":"No price, discount or payment condition is mentioned; the guarantee concerns the quality promise attached to the product, not the amount charged.","A":"A guarantee is part of the product offering, adding reassurance about quality and after-sales support. It changes what the customer receives with the sofa, so it belongs to the product element of the mix."}}},{"id":"P1_U3_MCQ_1772","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1772","question":"An airline in Doha, Qatar introduces a loyalty scheme with tiered status and exclusive lounge access for its most frequent flyers. What is the main strategic aim?","options":{"A":"To reduce the number of routes it operates","B":"To collect secondary market data","C":"To retain high-value customers and encourage repeat custom","D":"To remove all competing airlines"},"correctOption":"C","correctAnswer":"To retain high-value customers and encourage repeat custom","questionType":"MCQ","explanation":{"correct_reason":"Tiered status and lounge access reward frequent flyers, giving them reasons to keep choosing the same airline. The scheme is designed to retain valuable customers and stimulate repeat purchases rather than attract one-off buyers.","distractor_reasons":{"A":"The loyalty scheme concerns passenger rewards and says nothing about cutting routes; it is designed to increase custom, not reduce operations.","B":"Although the airline may learn from member behaviour, the programme itself is a retention tool rather than a method of gathering existing secondary data.","D":"No business can eliminate all competitors through a loyalty scheme; its purpose is to win and keep customers, not to remove rival airlines from the market.","C":"Tiered status and lounge access reward frequent flyers, giving them reasons to keep choosing the same airline. The scheme is designed to retain valuable customers and stimulate repeat purchases rather than attract one-off buyers."}}},{"id":"P1_U3_MCQ_1773","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1773","question":"An electronics chain in Taipei, Taiwan sold 8,000 laptops in 2026 in a city wide laptop market of 40,000 units. What was its market share by volume?","options":{"A":"16%","B":"25%","C":"32%","D":"20%"},"correctOption":"D","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"Market share by volume is unit sales divided by total market units, times 100. The chain sold 8,000 of the 40,000 laptops, which is 0.20, giving it a 20% share of the Taipei market.","distractor_reasons":{"A":"A 16% share would be 6,400 laptops, fewer than the 8,000 sold, so this option underestimates the chain's true position. For the business, the facts point to 20%, so this option cannot be correct.","B":"A 25% share would require 10,000 laptops, more than the 8,000 recorded; dividing 40,000 by 8,000 has inverted the calculation. The scenario for the business instead describes 20%, which rules this alternative out.","C":"A 32% share would mean 12,800 laptops, well above the actual 8,000 units sold, so it cannot be derived from the figures supplied.","D":"Market share by volume is unit sales divided by total market units, times 100. The chain sold 8,000 of the 40,000 laptops, which is 0.20, giving it a 20% share of the Taipei market."}}},{"id":"P1_U3_MCQ_1774","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1774","question":"A survey team in Lisbon, Portugal mails 800 questionnaires to local residents about shopping habits and receives 240 fully completed responses. What was the response rate for this survey?","options":{"A":"24%","B":"30%","C":"3%","D":"33%"},"correctOption":"B","correctAnswer":"30%","questionType":"MCQ","explanation":{"correct_reason":"The response rate is completed returns divided by questionnaires sent, multiplied by 100. Here 240 divided by 800 equals 0.30, so exactly 30% of the questionnaires were returned fully completed.","distractor_reasons":{"A":"A 24% rate would mean only 192 completed forms out of 800, below the 240 actually returned, so this option has miscounted the responses.","C":"A 3% rate would be just 24 completed questionnaires, an order of magnitude below the 240 received; the decimal point has been misplaced.","D":"A 33% rate would require about 264 completed forms; the actual number is 240, giving exactly 30% rather than 33%. The details given about the business support 30%, so this answer is unsuitable.","B":"The response rate is completed returns divided by questionnaires sent, multiplied by 100. Here 240 divided by 800 equals 0.30, so exactly 30% of the questionnaires were returned fully completed."}}},{"id":"P1_U3_MCQ_1775","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1775","question":"A bookstore in Auckland, New Zealand buys a novel for $12 and wants a mark-up of 40% on cost. What price should it charge and what is the mark-up per book?","options":{"A":"$15.60 price and $3.60 mark-up","B":"$16.00 price and $4.00 mark-up","C":"$16.80 price and $4.80 mark-up","D":"$12.48 price and $0.48 mark-up"},"correctOption":"C","correctAnswer":"$16.80 price and $4.80 mark-up","questionType":"MCQ","explanation":{"correct_reason":"A 40% mark-up on the $12 cost is 0.40 times $12, which equals $4.80. Adding this to cost gives a selling price of $16.80, so the bookstore charges $16.80 and keeps $4.80 per book.","distractor_reasons":{"A":"A $3.60 mark-up is 30% of the $12 cost, not 40%; the correct addition is $4.80 and the correct price is $16.80.","B":"A $4.00 mark-up is about 33% of $12, not the stated 40%; the calculation should be 0.40 times $12, giving $4.80.","D":"A mark-up of just $0.48 is only 4% of the $12 cost, not 40%, so this option has misplaced the decimal point.","C":"A 40% mark-up on the $12 cost is 0.40 times $12, which equals $4.80. Adding this to cost gives a selling price of $16.80, so the bookstore charges $16.80 and keeps $4.80 per book."}}},{"id":"P1_U3_MCQ_1776","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1776","question":"A cinema chain in Dublin, Ireland offers cheap Tuesday tickets and a loyalty card to encourage its existing patrons to visit more often. Which growth strategy is the chain using?","options":{"A":"Market penetration","B":"Market development","C":"Product development","D":"Diversification"},"correctOption":"A","correctAnswer":"Market penetration","questionType":"MCQ","explanation":{"correct_reason":"Encouraging current customers to make more visits through cheaper tickets and rewards is market penetration. The chain deepens its sales of existing services among the market it already serves rather than finding new buyers.","distractor_reasons":{"B":"Market development takes existing services to new markets such as another city; the cinema is aiming at its existing patrons, so this is not market development.","C":"Product development introduces new offerings, but cheap tickets and a loyalty card do not change the films or services on offer, only how often people buy them.","D":"Diversification requires new products in new markets; the chain is simply stimulating repeat use of its current cinemas by current customers.","A":"Encouraging current customers to make more visits through cheaper tickets and rewards is market penetration. The chain deepens its sales of existing services among the market it already serves rather than finding new buyers."}}},{"id":"P1_U3_MCQ_1777","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1777","question":"A hotel in Verona, Italy notices that more guests book through its own website after it promises the lowest price there. What does this change suggest about customer behaviour?","options":{"A":"Customers are avoiding all online booking channels","B":"A price guarantee is shifting bookings toward the hotel's direct channel","C":"Price has stopped influencing guests' choices","D":"Competition between hotels has come to an end"},"correctOption":"B","correctAnswer":"A price guarantee is shifting bookings toward the hotel's direct channel","questionType":"MCQ","explanation":{"correct_reason":"The rise in direct bookings follows the promise of the lowest price on the hotel's own site, so customers are responding to that guarantee. It shows buyers react to where the best deal is available.","distractor_reasons":{"A":"Guests are still booking online through the hotel's own website, so they are not avoiding online channels; they are choosing a different online route.","C":"The guarantee works precisely because price matters to guests, so the claim that price has stopped influencing their choices contradicts the observed change.","D":"A single hotel's booking pattern says nothing about competition ending; other hotels continue to compete for the same guests in Verona.","B":"The rise in direct bookings follows the promise of the lowest price on the hotel's own site, so customers are responding to that guarantee. It shows buyers react to where the best deal is available."}}},{"id":"P1_U3_MCQ_1778","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1778","question":"An agency in Oslo, Norway explores attitudes to electric cars through one-to-one conversations with a few experts, asking follow-up questions to probe their answers. Which research method is being used?","options":{"A":"A postal questionnaire","B":"Observation of behaviour","C":"Secondary data analysis","D":"An in-depth interview"},"correctOption":"D","correctAnswer":"An in-depth interview","questionType":"MCQ","explanation":{"correct_reason":"A detailed one-to-one conversation that allows the researcher to probe answers is an in-depth interview. It yields rich qualitative insight into why the experts hold particular attitudes to electric cars.","distractor_reasons":{"A":"A postal questionnaire uses fixed written questions sent to respondents and cannot adapt with follow-up probes during a face-to-face conversation. For the business, the facts point to An in-depth interview, so this option cannot be correct.","B":"Observation records what people do without asking about their attitudes; here the experts are explaining their views in conversation with the researcher.","C":"The agency is collecting new first-hand opinions from experts, whereas secondary analysis would reuse existing reports or statistics gathered by others.","D":"A detailed one-to-one conversation that allows the researcher to probe answers is an in-depth interview. It yields rich qualitative insight into why the experts hold particular attitudes to electric cars."}}},{"id":"P1_U3_MCQ_1779","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1779","question":"A phone maker in Gothenburg, Sweden adds a longer-lasting battery and a water-resistant casing to its newest handset. Which element of the marketing mix is being changed?","options":{"A":"Product","B":"Price","C":"Place","D":"Promotion"},"correctOption":"A","correctAnswer":"Product","questionType":"MCQ","explanation":{"correct_reason":"Battery life and water resistance are physical features of the handset, so the maker is altering the product itself. Improving specifications gives customers a tangible reason to choose the new model.","distractor_reasons":{"B":"No price, discount or payment term is mentioned, so the change cannot be a pricing decision; the improvements concern what the phone can do.","C":"Place concerns how the phone reaches customers through shops or online channels, not the technical features built into the handset. The business's circumstances match Product, so this option does not fit.","D":"Promotion covers advertising and sales messages, while the scenario describes actual changes to the handset's design, which is a product decision.","A":"Battery life and water resistance are physical features of the handset, so the maker is altering the product itself. Improving specifications gives customers a tangible reason to choose the new model."}}},{"id":"P1_U3_MCQ_1780","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1780","question":"A meal-kit service in Vienna, Austria offers ready-to-cook boxes with flexible delivery slots and simple recipe cards aimed at busy professionals who lack time to shop and cook. What is the service doing?","options":{"A":"Mass marketing to every household","B":"Competing solely on the lowest price","C":"Target marketing based on a defined customer segment","D":"Focusing only on what it can produce"},"correctOption":"C","correctAnswer":"Target marketing based on a defined customer segment","questionType":"MCQ","explanation":{"correct_reason":"By identifying busy professionals and shaping the boxes and delivery options around their needs, the service is targeting a specific segment. It concentrates its offering on buyers most likely to value convenience.","distractor_reasons":{"A":"Mass marketing would address all households with one standard offer, whereas the Viennese service deliberately focuses on a particular group with time pressures.","B":"The service competes through convenience and flexible delivery rather than through being the cheapest, so low price is not the basis described.","D":"The offering is shaped around customers' needs, which is a market-oriented approach, not an inward focus on production alone in Vienna.","C":"By identifying busy professionals and shaping the boxes and delivery options around their needs, the service is targeting a specific segment. It concentrates its offering on buyers most likely to value convenience."}}},{"id":"P1_U3_MCQ_1781","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1781","question":"A cosmetics retailer in Kuala Lumpur, Malaysia recorded $4 million of skincare sales in 2026 in a total local skincare market worth $20 million. What was its market share?","options":{"A":"20%","B":"25%","C":"16%","D":"5%"},"correctOption":"A","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"Market share equals the firm's sales divided by total market sales, times 100. The retailer's $4 million divided by the $20 million Malaysian market is 0.20, so its share was 20% in 2026.","distractor_reasons":{"B":"A 25% share would require $5 million of sales in a $20 million market, more than the $4 million the retailer actually recorded.","C":"A 16% share would be $3.2 million of sales, below the $4 million stated, so this option understates the retailer's true position.","D":"A 5% share would be only $1 million of sales, far less than the $4 million achieved, so it cannot be derived from the given figures.","A":"Market share equals the firm's sales divided by total market sales, times 100. The retailer's $4 million divided by the $20 million Malaysian market is 0.20, so its share was 20% in 2026."}}},{"id":"P1_U3_MCQ_1782","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1782","question":"A researcher in Hanoi, Vietnam wants to find out how many households own a washing machine and asks a large representative sample a short, fixed set of questions. Which method is being used?","options":{"A":"A focus group","B":"Observation of behaviour","C":"A questionnaire survey","D":"An experiment"},"correctOption":"C","correctAnswer":"A questionnaire survey","questionType":"MCQ","explanation":{"correct_reason":"A fixed set of questions put to a large representative sample to produce countable answers is a questionnaire survey. It will show how many households own a washing machine across the population studied.","distractor_reasons":{"A":"A focus group is a small discussion generating qualitative views, not a structured count of ownership across a large representative sample of households.","B":"Observation would mean watching behaviour rather than asking fixed questions, and it could not easily establish ownership of a washing machine in every home.","D":"An experiment changes one factor to test cause and effect; the researcher is simply measuring existing ownership, so no experimental treatment is involved.","C":"A fixed set of questions put to a large representative sample to produce countable answers is a questionnaire survey. It will show how many households own a washing machine across the population studied."}}},{"id":"P1_U3_MCQ_1783","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1783","question":"A bakery in Prague, Czech Republic sells pastries for $6 each, with a variable cost of $2 per pastry and monthly fixed costs of $2,400. How many pastries must it sell each month to break even?","options":{"A":"400 pastries","B":"600 pastries","C":"800 pastries","D":"1,200 pastries"},"correctOption":"B","correctAnswer":"600 pastries","questionType":"MCQ","explanation":{"correct_reason":"Each pastry contributes $6 minus $2, which is $4. Dividing the $2,400 fixed costs by the $4 contribution gives 600 pastries, the volume needed for the bakery to cover all its costs.","distractor_reasons":{"A":"At 400 pastries the bakery earns $1,600 of contribution, which is less than the $2,400 fixed costs, so it would still make a loss.","C":"Selling 800 pastries would generate $3,200 of contribution, more than needed to cover costs; that is above, not at, the break-even point.","D":"A figure of 1,200 pastries comes from dividing fixed costs by the $2 variable cost rather than by the $4 contribution, so it is incorrect.","B":"Each pastry contributes $6 minus $2, which is $4. Dividing the $2,400 fixed costs by the $4 contribution gives 600 pastries, the volume needed for the bakery to cover all its costs."}}},{"id":"P1_U3_MCQ_1784","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1784","question":"A streaming platform in São Paulo, Brazil offers a family plan with a lower per-person price than individual subscriptions to keep households signed up. What is the main aim of this offer?","options":{"A":"To reduce the quality of its content","B":"To gather secondary market data","C":"To withdraw from the streaming market","D":"To retain customers by offering better value for groups"},"correctOption":"D","correctAnswer":"To retain customers by offering better value for groups","questionType":"MCQ","explanation":{"correct_reason":"The cheaper per-person family plan gives households a stronger reason to stay subscribed, so the offer aims to retain customers through better group value and reduce the chance they cancel.","distractor_reasons":{"A":"The platform is adding value through a cheaper group rate, not lowering content quality; nothing in the scenario suggests the films or series are worse.","B":"Introducing a pricing plan is a commercial decision, not a method of collecting secondary data that already exists elsewhere about consumer behaviour.","C":"Offering better value is designed to keep subscribers, the opposite of withdrawing from the market, and no exit plan is mentioned.","D":"The cheaper per-person family plan gives households a stronger reason to stay subscribed, so the offer aims to retain customers through better group value and reduce the chance they cancel."}}},{"id":"P1_U3_MCQ_1785","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1785","question":"A mobile network in Cairo, Egypt held 15% of a $40 million market in 2025. In 2026 its sales were $9 million in a market worth $50 million. What happened to its market share?","options":{"A":"It fell to 12%","B":"It remained at 15%","C":"It rose to 18%","D":"It rose to 22.5%"},"correctOption":"C","correctAnswer":"It rose to 18%","questionType":"MCQ","explanation":{"correct_reason":"In 2026 the network's $9 million of sales divided by the $50 million market gives 18%. Compared with 15% in 2025, its share rose by 3 percentage points despite the market expanding.","distractor_reasons":{"A":"The share did not fall: $9 million out of $50 million is 18%, and the 12% figure wrongly divides the 2025 sales amount by the larger 2026 market.","B":"A 15% share of the $50 million market would be $7.5 million of sales; the network achieved $9 million, so its share increased.","D":"A 22.5% share would require $11.25 million of sales in the $50 million market; actual sales were $9 million, giving 18%.","C":"In 2026 the network's $9 million of sales divided by the $50 million market gives 18%. Compared with 15% in 2025, its share rose by 3 percentage points despite the market expanding."}}},{"id":"P1_U3_MCQ_1786","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1786","question":"A research team in Pretoria, South Africa gathers detailed opinions from a small group of teenagers about a new snack, letting them talk freely among themselves with a moderator. Which method is this?","options":{"A":"A focus group","B":"A postal questionnaire","C":"Secondary data analysis","D":"An experiment"},"correctOption":"A","correctAnswer":"A focus group","questionType":"MCQ","explanation":{"correct_reason":"A moderated discussion in which a small group talks freely about a product is a focus group. It provides qualitative insight into teenagers' attitudes that a numerical survey would not uncover.","distractor_reasons":{"B":"A postal questionnaire sends fixed written questions and records individual answers, not a free-flowing group discussion guided by a moderator. For the business, the facts point to A focus group, so this option cannot be correct.","C":"The team is collecting new first-hand views from teenagers, whereas secondary analysis would reuse information collected previously by someone else. The scenario for the business instead describes A focus group, which rules this alternative out.","D":"An experiment manipulates a factor to test its effect; here the researcher is listening to opinions, not comparing groups under different conditions.","A":"A moderated discussion in which a small group talks freely about a product is a focus group. It provides qualitative insight into teenagers' attitudes that a numerical survey would not uncover."}}},{"id":"P1_U3_MCQ_1787","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1787","question":"A car manufacturer in Stuttgart, Germany sells its vehicles through franchised dealers and an online configurator rather than company-owned showrooms. Which element of the marketing mix is this about?","options":{"A":"Product","B":"Price","C":"Promotion","D":"Place"},"correctOption":"D","correctAnswer":"Place","questionType":"MCQ","explanation":{"correct_reason":"Place covers the routes by which products reach buyers. Using franchised dealers and an online configurator instead of owned showrooms describes the manufacturer's distribution channels, so this is a place decision.","distractor_reasons":{"A":"Product decisions concern the vehicles' design and features; the scenario describes how cars are sold to customers, not how they are built.","B":"No price, discount or financing term is mentioned, so the mix element shown is not price but the channel used to reach buyers.","C":"Promotion involves advertising and sales messages; an online configurator here functions as a sales channel, which is a place matter. In the business's case, the correct description is Place, not this choice.","D":"Place covers the routes by which products reach buyers. Using franchised dealers and an online configurator instead of owned showrooms describes the manufacturer's distribution channels, so this is a place decision."}}},{"id":"P1_U3_MCQ_1788","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1788","question":"A publisher in Krakow, Poland launches an audiobook service aimed at its existing readers, who already buy its printed books. Which growth strategy is this?","options":{"A":"Market penetration","B":"Product development","C":"Market development","D":"Diversification"},"correctOption":"B","correctAnswer":"Product development","questionType":"MCQ","explanation":{"correct_reason":"Offering a new audiobook format to customers who already buy the publisher's books is product development. The market stays the same while the company creates a new offering for it.","distractor_reasons":{"A":"Market penetration means selling more of the existing printed books to current readers; audiobooks are a new product rather than deeper sales of the old one.","C":"Market development takes existing products into new markets such as overseas readers; here the customers are already known and the product is new.","D":"Diversification requires new products in new markets; the publisher keeps its existing reader base, so this is a narrower product-development move.","B":"Offering a new audiobook format to customers who already buy the publisher's books is product development. The market stays the same while the company creates a new offering for it."}}},{"id":"P1_U3_MCQ_1789","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1789","question":"A snack brand in Accra, Ghana sold 18,000 packets of roasted peanuts in 2026 in a city wide market of 90,000 packets. What was its market share by volume?","options":{"A":"18%","B":"20%","C":"25%","D":"5%"},"correctOption":"B","correctAnswer":"20%","questionType":"MCQ","explanation":{"correct_reason":"Market share by volume is the brand's unit sales divided by total market units, times 100. The 18,000 packets divided by the 90,000-packet market gives 0.20, so the brand held a 20% share.","distractor_reasons":{"A":"An 18% share would be 16,200 packets, fewer than the 18,000 sold, so this option slightly understates the brand's true position.","C":"A 25% share would require 22,500 packets, more than the 18,000 actually sold, so this figure cannot be derived from the data.","D":"A 5% share would be only 4,500 packets, far below the 18,000 recorded, and does not follow from dividing 18,000 by 90,000.","B":"Market share by volume is the brand's unit sales divided by total market units, times 100. The 18,000 packets divided by the 90,000-packet market gives 0.20, so the brand held a 20% share."}}},{"id":"P1_U3_MCQ_1790","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1790","question":"A research team in Santiago, Chile wants to know how often shoppers buy breakfast cereal and asks participants to record every purchase in a booklet over four weeks. What is this method called?","options":{"A":"A focus group","B":"Secondary data analysis","C":"An experiment","D":"A consumer diary"},"correctOption":"D","correctAnswer":"A consumer diary","questionType":"MCQ","explanation":{"correct_reason":"Asking participants to record their own purchases over a period is a consumer diary. It gathers first-hand evidence of actual buying frequency rather than relying on memory in a single interview.","distractor_reasons":{"A":"A focus group is a moderated discussion among a small group, not a record of purchases made by participants across several weeks.","B":"The team is collecting new first-hand records from shoppers, whereas secondary analysis would use information gathered earlier by another organisation. For the business, the facts point to A consumer diary, so this option cannot be correct.","C":"An experiment alters a factor to measure its effect; recording what shoppers already buy over four weeks involves no manipulated treatment.","D":"Asking participants to record their own purchases over a period is a consumer diary. It gathers first-hand evidence of actual buying frequency rather than relying on memory in a single interview."}}},{"id":"P1_U3_MCQ_1791","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1791","question":"A stationery shop in Dublin, Ireland buys pens for $0.50 each and sells them for $0.80. What is the mark-up as a percentage of cost?","options":{"A":"60%","B":"30%","C":"37.5%","D":"50%"},"correctOption":"A","correctAnswer":"60%","questionType":"MCQ","explanation":{"correct_reason":"The mark-up in dollars is $0.80 minus $0.50, which is $0.30. Dividing $0.30 by the $0.50 cost gives 0.60, so the shop adds a 60% mark-up on what it pays for each pen.","distractor_reasons":{"B":"Thirty percent is the mark-up expressed as a share of the selling price, not of cost; the question asks for a percentage of the $0.50 cost.","C":"The 37.5% figure comes from dividing $0.30 by the $0.80 selling price in the wrong direction; the required base is the cost of $0.50.","D":"A 50% mark-up on $0.50 would be $0.25, giving a price of $0.75; the actual price is $0.80, so the mark-up is 60%.","A":"The mark-up in dollars is $0.80 minus $0.50, which is $0.30. Dividing $0.30 by the $0.50 cost gives 0.60, so the shop adds a 60% mark-up on what it pays for each pen."}}},{"id":"P1_U3_MCQ_1792","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1792","question":"A fashion retailer in Milan, Italy launches a second-hand clothing line to appeal to environmentally conscious shoppers it had not previously reached. What is this move?","options":{"A":"Cost leadership","B":"Mass marketing","C":"A new offering aimed at a specific customer segment","D":"Market penetration"},"correctOption":"C","correctAnswer":"A new offering aimed at a specific customer segment","questionType":"MCQ","explanation":{"correct_reason":"The retailer introduces a distinct second-hand range for environmentally conscious buyers, a segment it did not serve before. This combines a new offering with a clearly identified customer group.","distractor_reasons":{"A":"Cost leadership competes through low prices for a broad market; the second-hand line is positioned around environmental values rather than being the cheapest option.","B":"Mass marketing offers one standard product to everyone, whereas the retailer is deliberately targeting a specific group concerned about the environment.","D":"Market penetration increases sales of existing products in current markets; a new second-hand range aimed at new buyers is a different strategic move.","C":"The retailer introduces a distinct second-hand range for environmentally conscious buyers, a segment it did not serve before. This combines a new offering with a clearly identified customer group."}}},{"id":"P1_U3_MCQ_1793","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1793","question":"A coffee brand in Bogotá, Colombia increased its sales from 10,000 bags in 2025 to 12,500 bags in 2026. What was the percentage increase in sales?","options":{"A":"20%","B":"22%","C":"30%","D":"25%"},"correctOption":"D","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"Sales rose by 2,500 bags, from 10,000 to 12,500. Dividing the 2,500 increase by the original 10,000 and multiplying by 100 gives a 25% rise in the brand's sales.","distractor_reasons":{"A":"A 20% rise on 10,000 bags would be 2,000 extra, fewer than the 2,500 actually sold, so this option understates the growth.","B":"A 22% increase would add 2,200 bags to the original total; the real gain is 2,500, which is 25% of 10,000.","C":"A 30% rise would be 3,000 additional bags; the recorded increase is 2,500, giving 25% rather than 30% for the Colombian brand.","D":"Sales rose by 2,500 bags, from 10,000 to 12,500. Dividing the 2,500 increase by the original 10,000 and multiplying by 100 gives a 25% rise in the brand's sales."}}},{"id":"P1_U3_MCQ_1794","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1794","question":"A researcher in Glasgow, Scotland wants numerical answers from 1,000 households using the same set of structured questions posted online. Which data collection method does this describe?","options":{"A":"A focus group","B":"An online questionnaire survey","C":"Secondary research","D":"Observation"},"correctOption":"B","correctAnswer":"An online questionnaire survey","questionType":"MCQ","explanation":{"correct_reason":"A standard set of structured questions sent online to many households, producing numerical answers, is an online questionnaire survey. It is a primary quantitative method suited to gathering consistent data at scale.","distractor_reasons":{"A":"A focus group is a small qualitative discussion, not a structured set of questions distributed to a thousand separate households for numerical answers.","C":"The researcher is gathering new first-hand answers, so the information is primary; secondary research reuses data that already exists from other sources.","D":"Observation records behaviour without asking questions; the researcher in Glasgow is instead posting a fixed set of questions to respondents. The scenario for the business instead describes An online questionnaire survey, which rules this alternative out.","B":"A standard set of structured questions sent online to many households, producing numerical answers, is an online questionnaire survey. It is a primary quantitative method suited to gathering consistent data at scale."}}},{"id":"P1_U3_MCQ_1795","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1795","question":"A winery in Mendoza, Argentina offers free tastings and guided cellar tours to attract visitors and encourage them to buy its wine. Which element of the marketing mix is this?","options":{"A":"Product","B":"Price","C":"Promotion","D":"Place"},"correctOption":"C","correctAnswer":"Promotion","questionType":"MCQ","explanation":{"correct_reason":"Free tastings and tours are activities used to communicate with potential customers and stimulate interest in the wine. They are sales promotion techniques, making promotion the correct element of the mix.","distractor_reasons":{"A":"Product decisions concern the wine's flavour, label and packaging; the tastings and tours are activities designed to attract buyers rather than changes to the wine.","B":"No price, discount or payment condition is given, so the activity illustrated is not a pricing decision but a way of engaging visitors.","D":"Place concerns where the wine is sold; although tours happen at the cellar, their purpose here is to promote the product to visitors.","C":"Free tastings and tours are activities used to communicate with potential customers and stimulate interest in the wine. They are sales promotion techniques, making promotion the correct element of the mix."}}},{"id":"P1_U3_MCQ_1796","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1796","question":"A smartphone brand in Taipei, Taiwan emphasises the strong privacy features of its devices in adverts, unlike rivals that focus on camera quality. What strategy is the brand using?","options":{"A":"Differentiation","B":"Cost leadership","C":"Mass marketing","D":"Market penetration"},"correctOption":"A","correctAnswer":"Differentiation","questionType":"MCQ","explanation":{"correct_reason":"By highlighting privacy features that rivals do not stress, the brand makes its phones distinct in customers' eyes. This is differentiation, giving buyers a specific reason to choose it over competitors.","distractor_reasons":{"B":"Cost leadership competes on the lowest prices; the adverts focus on a unique feature rather than on cheapness or efficient production.","C":"Mass marketing targets everyone with one generic message, whereas the brand is promoting a particular attribute that sets it apart from rivals.","D":"Market penetration seeks more sales of current products in existing markets through tactics like lower prices; the strategy described is about making the product distinctive.","A":"By highlighting privacy features that rivals do not stress, the brand makes its phones distinct in customers' eyes. This is differentiation, giving buyers a specific reason to choose it over competitors."}}},{"id":"P1_U3_MCQ_1797","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1797","question":"A furniture retailer in Copenhagen, Denmark sold 7,500 sofas in 2026 in a national sofa market of 30,000 units. What was its market share by volume?","options":{"A":"20%","B":"25%","C":"30%","D":"15%"},"correctOption":"B","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"Market share by volume equals the firm's unit sales divided by total market units, multiplied by 100. The retailer's 7,500 sofas divided by the 30,000-unit market gives 0.25, so its share was 25%.","distractor_reasons":{"A":"A 20% share would be 6,000 sofas out of 30,000, below the 7,500 sold, so this option understates the retailer's true position.","C":"A 30% share would require 9,000 sofas, more than the 7,500 recorded; this option has likely inverted the division in Copenhagen.","D":"A 15% share would be just 4,500 sofas, far fewer than the 7,500 actually sold, and cannot be derived from the given figures.","B":"Market share by volume equals the firm's unit sales divided by total market units, multiplied by 100. The retailer's 7,500 sofas divided by the 30,000-unit market gives 0.25, so its share was 25%."}}},{"id":"P1_U3_MCQ_1798","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1798","question":"A research team in Accra, Ghana uses figures from a recent government census instead of collecting new information from consumers. What type of research is this?","options":{"A":"Primary qualitative research","B":"An experiment","C":"A focus group","D":"Secondary research"},"correctOption":"D","correctAnswer":"Secondary research","questionType":"MCQ","explanation":{"correct_reason":"Census figures were collected by the government for its own purposes and already exist, so using them is secondary research. The team avoids the cost of gathering equivalent data first-hand.","distractor_reasons":{"A":"Primary research involves collecting new first-hand evidence, but the team is reusing existing census data, which is secondary and largely numerical.","B":"An experiment manipulates a variable and observes the result; using published census statistics involves no such controlled test or new data collection.","C":"A focus group is a small discussion that generates qualitative opinions, whereas census figures are existing numerical statistics compiled by a government body.","D":"Census figures were collected by the government for its own purposes and already exist, so using them is secondary research. The team avoids the cost of gathering equivalent data first-hand."}}},{"id":"P1_U3_MCQ_1799","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1799","question":"A hotel in Phuket, Thailand charges much lower room rates during the rainy season and higher rates at the height of the tourist season. Which pricing approach does this illustrate?","options":{"A":"Demand-based seasonal pricing","B":"Cost-plus pricing","C":"Loss leader pricing","D":"Price skimming"},"correctOption":"A","correctAnswer":"Demand-based seasonal pricing","questionType":"MCQ","explanation":{"correct_reason":"The hotel varies its rates with the level of demand across the year, charging less when visitors are few and more at peak times. This is demand-based seasonal pricing rather than a fixed cost-based figure.","distractor_reasons":{"B":"Cost-plus pricing adds a fixed mark-up to unit cost and would not explain systematic changes between wet and peak seasons, which reflect demand.","C":"A loss leader sells below cost to attract other purchases; the hotel's lower wet-season rate is a demand-based adjustment, not a deliberate loss on every room.","D":"Price skimming means starting high and reducing over time as competitors arrive; seasonal swings that repeat each year are a different pricing approach.","A":"The hotel varies its rates with the level of demand across the year, charging less when visitors are few and more at peak times. This is demand-based seasonal pricing rather than a fixed cost-based figure."}}},{"id":"P1_U3_MCQ_1800","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1800","question":"A skincare brand in Paris, France donates part of every sale to local environmental projects and highlights this in its advertising. What is the brand mainly trying to achieve?","options":{"A":"To lower its manufacturing costs","B":"To collect primary research data","C":"To build an ethical brand image that appeals to values-driven customers","D":"To drive all competitors out of business"},"correctOption":"C","correctAnswer":"To build an ethical brand image that appeals to values-driven customers","questionType":"MCQ","explanation":{"correct_reason":"Donating to environmental projects and advertising that fact shapes how customers perceive the brand, appealing to people who care about such values. It is an ethical positioning strategy aimed at building goodwill and preference.","distractor_reasons":{"A":"Donating part of each sale is an expense rather than a way of cutting manufacturing costs, and no production changes are described in the scenario.","B":"Advertising charitable giving communicates a message to the public; it is not a method of gathering first-hand research evidence from customers.","D":"A brand cannot eliminate every rival through charitable donations; the purpose is to attract customers who share its values, not to remove competitors.","C":"Donating to environmental projects and advertising that fact shapes how customers perceive the brand, appealing to people who care about such values. It is an ethical positioning strategy aimed at building goodwill and preference."}}},{"id":"P1_U3_MCQ_1801","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1801","question":"Ghent Ceramics, based in Bruges, Belgium, sold 12,000 hand-painted vases last year at an average selling price of $18 each. The marketing manager wants to report total sales revenue in the annual review. What was the total revenue from vase sales last year?","options":{"A":"$21,600","B":"$216,000","C":"$206,000","D":"$2,160,000"},"correctOption":"B","correctAnswer":"$216,000","questionType":"MCQ","explanation":{"correct_reason":"Total sales revenue is found by multiplying the number of units sold by the average selling price. Ghent Ceramics sold 12,000 vases at $18 each, and 12,000 multiplied by $18 gives $216,000, so that is the revenue from vase sales.","distractor_reasons":{"A":"$21,600 is a decimal-place error: multiplying 12,000 by $18 gives $216,000, ten times larger. It would only be correct if the firm sold 1,200 vases rather than the 12,000 stated in the scenario.","B":"Total sales revenue is found by multiplying the number of units sold by the average selling price. Ghent Ceramics sold 12,000 vases at $18 each, and 12,000 multiplied by $18 gives $216,000, so that is the revenue from vase sales.","C":"$206,000 wrongly subtracts $10,000 from the true revenue. There is no basis in the stem for such a deduction; revenue is simply 12,000 vases multiplied by $18, which equals $216,000.","D":"$2,160,000 is ten times the correct figure and would require 120,000 vases at $18 each. Ghent Ceramics sold only 12,000 vases, so this overstates revenue by a factor of ten."}}},{"id":"P1_U3_MCQ_1802","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1802","question":"Lyon Footwear, based in Nice, France, asked 800 shoppers in a street survey whether they would buy a new running shoe. 240 of those questioned answered yes. What percentage of the respondents said they would buy the shoe?","options":{"A":"20%","B":"24%","C":"33%","D":"30%"},"correctOption":"D","correctAnswer":"30%","questionType":"MCQ","explanation":{"correct_reason":"The percentage is the number giving the response divided by the total surveyed, multiplied by 100. Here 240 shoppers said yes out of 800 surveyed, and 240 divided by 800 equals 0.3, which is 30 percent.","distractor_reasons":{"A":"20 percent would mean only 160 of the 800 shoppers said yes. Since 240 shoppers answered yes, the correct proportion is 240 out of 800, which is 30 percent, not 20 percent.","B":"24 percent confuses the figure 240 with a percentage. The 240 is a count of shoppers, not a percentage; dividing 240 by the 800 surveyed gives 30 percent.","C":"33 percent would require about 264 yes answers out of 800. The survey recorded 240 yes answers, so 30 percent is the accurate percentage of respondents.","D":"The percentage is the number giving the response divided by the total surveyed, multiplied by 100. Here 240 shoppers said yes out of 800 surveyed, and 240 divided by 800 equals 0.3, which is 30 percent."}}},{"id":"P1_U3_MCQ_1803","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1803","question":"Naples Bakery, based in Turin, Italy, makes a celebration cake for $6 in ingredients and labour. It uses cost-plus pricing and adds a mark-up of 50 percent on the cost. What is the selling price the bakery should charge?","options":{"A":"$9","B":"$6.50","C":"$12","D":"$15"},"correctOption":"A","correctAnswer":"$9","questionType":"MCQ","explanation":{"correct_reason":"A 50 percent mark-up on cost means adding half of the $6 cost, which is $3, to the original $6. The selling price is therefore $6 plus $3, giving $9, so option A is correct.","distractor_reasons":{"A":"A 50 percent mark-up on cost means adding half of the $6 cost, which is $3, to the original $6. The selling price is therefore $6 plus $3, giving $9, so option A is correct.","B":"$6.50 adds only a 50 cent mark-up, which is less than one percent of the $6 cost, not the 50 percent mark-up stated. The correct calculation adds $3, not 50 cents.","C":"$12 would be a 100 percent mark-up on the $6 cost, doubling it. The bakery only adds 50 percent, so the price is $9 rather than $12.","D":"$15 is well above the stated cost of $6 and implies a mark-up far greater than 50 percent, so it cannot be the correct cost-plus price."}}},{"id":"P1_U3_MCQ_1804","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1804","question":"Trieste Packaging, based in Milan, Italy, sold 45,000 boxes of food containers last year. Industry figures show the whole market for food containers was 300,000 boxes over the same period. What was Trieste Packaging's market share last year?","options":{"A":"5%","B":"10%","C":"15%","D":"30%"},"correctOption":"C","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Market share is the firm's sales divided by total market sales, multiplied by 100. Trieste Packaging sold 45,000 boxes out of a 300,000-box market, and 45,000 divided by 300,000 is 0.15, which equals 15 percent.","distractor_reasons":{"A":"5 percent would correspond to only 15,000 boxes out of 300,000. The firm actually sold 45,000 boxes, three times that amount, so its market share is 15 percent.","B":"10 percent would mean 30,000 boxes in a 300,000-unit market. Since Trieste Packaging sold 45,000 boxes, its share is 15 percent rather than 10 percent.","C":"Market share is the firm's sales divided by total market sales, multiplied by 100. Trieste Packaging sold 45,000 boxes out of a 300,000-box market, and 45,000 divided by 300,000 is 0.15, which equals 15 percent.","D":"30 percent would require 90,000 boxes, twice the 45,000 the firm sold. The correct share is 45,000 out of 300,000, which is 15 percent."}}},{"id":"P1_U3_MCQ_1805","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1805","question":"Salzburg Hardware, based in Linz, Austria, produces heavy-duty drill bits and sells them only to professional construction firms, ignoring casual do-it-yourself buyers. It designs its advertising around the needs of this small, specialist group. What is this approach called?","options":{"A":"Mass marketing","B":"Niche marketing","C":"Market research","D":"Product orientation"},"correctOption":"B","correctAnswer":"Niche marketing","questionType":"MCQ","explanation":{"correct_reason":"Niche marketing means concentrating on a small, specialised customer group. Salzburg Hardware focuses only on professional construction firms with heavy-duty drill bits, so it is serving a niche rather than the whole market.","distractor_reasons":{"A":"Mass marketing aims at the whole market with one general offer. Salzburg Hardware deliberately excludes casual buyers and targets only professional construction firms, so it is not using a mass-market approach.","B":"Niche marketing means concentrating on a small, specialised customer group. Salzburg Hardware focuses only on professional construction firms with heavy-duty drill bits, so it is serving a niche rather than the whole market.","C":"Market research is the gathering of information about customers. The scenario describes which customers the firm chooses to serve, not the collection of data about them.","D":"Product orientation means focusing on the product rather than customer needs. Here the firm designs its offer around a specific group's needs, which shows a customer focus."}}},{"id":"P1_U3_MCQ_1806","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1806","question":"Braga Refreshments, based in Porto, Portugal, wants to understand soft-drink trends. Instead of asking customers directly, it purchases a report that a trade association compiled last year from existing sales records. What type of research data has Braga Refreshments obtained?","options":{"A":"Primary qualitative data","B":"Primary quantitative data","C":"Field research data","D":"Secondary research data"},"correctOption":"D","correctAnswer":"Secondary research data","questionType":"MCQ","explanation":{"correct_reason":"Secondary research uses information that already exists and was collected by someone else. The trade association's report was compiled from earlier records, so the data Braga Refreshments bought is secondary rather than newly gathered.","distractor_reasons":{"A":"Primary qualitative data would come from new, non-numeric research such as interviews the firm conducts itself. Braga Refreshments bought an existing report, so the data are not primary.","B":"Primary quantitative data are new numerical figures collected first-hand by the business. The purchased report was compiled by another body from past records, so it is not primary.","C":"Field research involves collecting data directly from respondents in the marketplace. Buying a ready-made report involves no such fieldwork, so this option is incorrect.","D":"Secondary research uses information that already exists and was collected by someone else. The trade association's report was compiled from earlier records, so the data Braga Refreshments bought is secondary rather than newly gathered."}}},{"id":"P1_U3_MCQ_1807","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1807","question":"Faro Optics, based in Lisbon, Portugal, manufactures prescription glasses and supplies them through independent opticians across the country rather than opening its own stores. Which element of the marketing mix does this decision about how customers obtain the glasses illustrate?","options":{"A":"Place","B":"Product","C":"Price","D":"Promotion"},"correctOption":"A","correctAnswer":"Place","questionType":"MCQ","explanation":{"correct_reason":"Place, or distribution, concerns how a product reaches the customer. By supplying glasses through independent opticians instead of its own outlets, Faro Optics is making a decision about the place element of the mix.","distractor_reasons":{"A":"Place, or distribution, concerns how a product reaches the customer. By supplying glasses through independent opticians instead of its own outlets, Faro Optics is making a decision about the place element of the mix.","B":"Product refers to the design, quality and branding of the glasses themselves. The scenario is about where customers buy them, not about the features of the product.","C":"Price concerns what customers pay and the pricing method used. The decision to use independent opticians is about distribution routes, not about setting a price.","D":"Promotion covers advertising and sales messages. Supplying glasses through opticians is a channel decision, not a communication decision, so it belongs to place."}}},{"id":"P1_U3_MCQ_1808","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1808","question":"Bilbao Furniture, based in Madrid, Spain, advertises its flat-pack desks with the claim that a customer can assemble them in thirty minutes without tools, a benefit rivals do not offer. What is this distinctive claim about the product called?","options":{"A":"Market segmentation","B":"Sales orientation","C":"Unique selling point","D":"Market research"},"correctOption":"C","correctAnswer":"Unique selling point","questionType":"MCQ","explanation":{"correct_reason":"A unique selling point is a feature that sets a product apart from competitors. Bilbao Furniture's thirty-minute, tool-free assembly is a benefit rivals lack, so the claim is a unique selling point.","distractor_reasons":{"A":"Market segmentation is the division of buyers into groups with shared characteristics. The thirty-minute assembly claim is about the product's appeal, not about dividing customers into groups.","B":"Sales orientation emphasises aggressive selling rather than a distinctive product benefit. The scenario highlights a genuine product difference, so it is not simply a sales approach.","C":"A unique selling point is a feature that sets a product apart from competitors. Bilbao Furniture's thirty-minute, tool-free assembly is a benefit rivals lack, so the claim is a unique selling point.","D":"Market research is the collection of customer information. The claim itself is a competitive message, not a method of gathering information about buyers."}}},{"id":"P1_U3_MCQ_1809","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1809","question":"Tarragona Dairy, based in Valencia, Spain, saw the total market for its yoghurt category rise from $40 million to $46 million in one year. The marketing director needs the percentage growth of the category. What was the market growth rate?","options":{"A":"15%","B":"6%","C":"12%","D":"46%"},"correctOption":"A","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Percentage growth equals the increase divided by the original value, multiplied by 100. The market rose from $40 million to $46 million, an increase of $6 million, and 6 divided by 40 is 0.15, or 15 percent.","distractor_reasons":{"A":"Percentage growth equals the increase divided by the original value, multiplied by 100. The market rose from $40 million to $46 million, an increase of $6 million, and 6 divided by 40 is 0.15, or 15 percent.","B":"6 percent confuses the $6 million increase with a percentage. The increase must be divided by the original $40 million, giving 15 percent, so 6 percent is wrong.","C":"12 percent would imply an increase of $4.8 million on the original $40 million. The actual rise was $6 million, which gives 15 percent growth.","D":"46 percent mistakes the new market value figure for a growth rate. Growth is the change relative to the starting value, so the correct rate is 15 percent."}}},{"id":"P1_U3_MCQ_1810","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1810","question":"Perugia Stationery, based in Rome, Italy, has a list of 2,000 registered customers and uses a computer to pick 200 names, giving every customer an equal chance of being chosen. What sampling method is the firm using?","options":{"A":"Quota sampling","B":"Random sampling","C":"Focus group sampling","D":"Desk research"},"correctOption":"B","correctAnswer":"Random sampling","questionType":"MCQ","explanation":{"correct_reason":"Random sampling gives every member of the population an equal chance of selection. Perugia Stationery uses a computer to choose 200 of its 2,000 customers so each has an equal probability, which is random sampling.","distractor_reasons":{"A":"Quota sampling sets targets for categories of people and then fills them non-randomly. Perugia Stationery gives every customer an equal chance through computer selection, so it is not using quotas.","B":"Random sampling gives every member of the population an equal chance of selection. Perugia Stationery uses a computer to choose 200 of its 2,000 customers so each has an equal probability, which is random sampling.","C":"A focus group is a small group interview used to explore attitudes in depth. Choosing 200 names from a customer list is a survey sampling method, not a focus group.","D":"Desk research uses existing published information. Selecting customers from a list to contact is primary field research, so desk research is not the correct description."}}},{"id":"P1_U3_MCQ_1811","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1811","question":"Bologna Hampers, based in Florence, Italy, runs a six-week offer in which customers who buy two gift hampers receive a third at no charge. The aim is to boost short-term sales. Which element of the promotion mix is this?","options":{"A":"Public relations","B":"Personal selling","C":"Direct marketing","D":"Sales promotion"},"correctOption":"D","correctAnswer":"Sales promotion","questionType":"MCQ","explanation":{"correct_reason":"Sales promotion uses short-term incentives to encourage a quick purchase. The buy-two-get-one-free offer is a time-limited incentive designed to raise sales rapidly, so it is sales promotion.","distractor_reasons":{"A":"Public relations builds relationships and goodwill through unpaid communication. A buy-two-get-one-free discount is a direct sales incentive, not a public relations activity.","B":"Personal selling involves face-to-face communication between a seller and a buyer. The offer applies to all customers regardless of any sales conversation, so it is not personal selling.","C":"Direct marketing communicates directly with individual customers, often by post or email. A store-wide free-gift offer is not targeted communication to named individuals.","D":"Sales promotion uses short-term incentives to encourage a quick purchase. The buy-two-get-one-free offer is a time-limited incentive designed to raise sales rapidly, so it is sales promotion."}}},{"id":"P1_U3_MCQ_1812","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1812","question":"Padua Luggage, based in Venice, Italy, divides its customers into students, business travellers and retired people, then designs separate suitcase ranges for each group. Which basis for market segmentation is the firm using?","options":{"A":"Demographic","B":"Geographic","C":"Psychographic","D":"Behavioural"},"correctOption":"A","correctAnswer":"Demographic","questionType":"MCQ","explanation":{"correct_reason":"Demographic segmentation divides buyers by characteristics such as age or life stage. Students, business travellers and retired people are age or occupation groups, so Padua Luggage is segmenting on a demographic basis.","distractor_reasons":{"A":"Demographic segmentation divides buyers by characteristics such as age or life stage. Students, business travellers and retired people are age or occupation groups, so Padua Luggage is segmenting on a demographic basis.","B":"Geographic segmentation divides markets by place, such as regions or countries. Padua Luggage is grouping customers by age and occupation, not by where they live.","C":"Psychographic segmentation groups people by lifestyle, values or personality. The categories of student, worker and retiree relate to age and occupation rather than lifestyle attitudes.","D":"Behavioural segmentation uses buying habits or usage rates. The scenario describes customer groups defined by life stage, not by how often or when they buy."}}},{"id":"P1_U3_MCQ_1813","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1813","question":"Bari Sportswear, based in Naples, Italy, offers free lifetime repairs on its jackets, a service no rival provides. Customers often mention this when choosing the brand. What does the repair promise give Bari Sportswear in its market?","options":{"A":"Market orientation","B":"Product orientation","C":"Competitive advantage","D":"Market share"},"correctOption":"C","correctAnswer":"Competitive advantage","questionType":"MCQ","explanation":{"correct_reason":"A competitive advantage is something a firm does better than rivals that attracts customers. Free lifetime repairs are unique to Bari Sportswear and influence choice, so the promise gives the firm a competitive advantage.","distractor_reasons":{"A":"Market orientation means putting customer needs at the centre of decisions. While the repair service is customer-friendly, the question asks what the firm gains relative to rivals, which is a competitive advantage.","B":"Product orientation focuses on the product rather than the market. The lifetime repair promise is a service that differentiates the firm, so product orientation does not describe the benefit gained.","C":"A competitive advantage is something a firm does better than rivals that attracts customers. Free lifetime repairs are unique to Bari Sportswear and influence choice, so the promise gives the firm a competitive advantage.","D":"Market share is the proportion of total sales a firm holds. No sales figures are given here; the repair promise is a source of advantage rather than a share figure."}}},{"id":"P1_U3_MCQ_1814","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1814","question":"Palermo Skincare, based in Catania, Italy, mailed 1,500 questionnaires to households and received 450 completed responses. The research manager wants to know the response rate. What percentage of questionnaires were returned?","options":{"A":"20%","B":"30%","C":"45%","D":"3%"},"correctOption":"B","correctAnswer":"30%","questionType":"MCQ","explanation":{"correct_reason":"The response rate is completed returns divided by questionnaires sent, multiplied by 100. Palermo Skincare received 450 completed forms from 1,500 sent, and 450 divided by 1,500 equals 0.3, which is 30 percent.","distractor_reasons":{"A":"20 percent would mean only 300 of the 1,500 questionnaires were returned. The actual number returned was 450, giving a response rate of 30 percent rather than 20 percent.","B":"The response rate is completed returns divided by questionnaires sent, multiplied by 100. Palermo Skincare received 450 completed forms from 1,500 sent, and 450 divided by 1,500 equals 0.3, which is 30 percent.","C":"45 percent confuses the 450 count with a percentage. With 1,500 questionnaires sent, 450 returns represent 30 percent, not 45 percent.","D":"3 percent would imply only 45 returns. Since 450 completed questionnaires came back from 1,500 sent, the correct response rate is 30 percent."}}},{"id":"P1_U3_MCQ_1815","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1815","question":"Catania Jewellery, based in Syracuse, Italy, makes a silver bracelet for $40. It wants a profit margin of 20 percent of the selling price. What selling price must the firm charge to achieve exactly that margin?","options":{"A":"$48","B":"$60","C":"$45","D":"$50"},"correctOption":"D","correctAnswer":"$50","questionType":"MCQ","explanation":{"correct_reason":"If profit is 20 percent of the selling price, the $40 cost is the remaining 80 percent. Dividing $40 by 0.8 gives $50, so the selling price is $50 and the profit is $10.","distractor_reasons":{"A":"$48 adds 20 percent of the $40 cost, giving a mark-up on cost, not a 20 percent margin on selling price. The required price is $50.","B":"$60 would leave a $20 profit on a $60 price, which is a 33 percent margin, not the 20 percent the firm wants.","C":"$45 would give only $5 profit on a $45 price, roughly 11 percent, so it does not achieve a 20 percent margin.","D":"If profit is 20 percent of the selling price, the $40 cost is the remaining 80 percent. Dividing $40 by 0.8 gives $50, so the selling price is $50 and the profit is $10."}}},{"id":"P1_U3_MCQ_1816","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1816","question":"Split Toymaking, based in Zagreb, Croatia, raised its market share from 8 percent to 12 percent last year while the total market size was unchanged. What must have happened to the firm's own sales over the year?","options":{"A":"They increased","B":"They fell","C":"They stayed the same","D":"They doubled"},"correctOption":"A","correctAnswer":"They increased","questionType":"MCQ","explanation":{"correct_reason":"Market share is the firm's sales as a proportion of total market sales. If the total market was unchanged and the share rose from 8 to 12 percent, the firm's own sales must have increased.","distractor_reasons":{"A":"Market share is the firm's sales as a proportion of total market sales. If the total market was unchanged and the share rose from 8 to 12 percent, the firm's own sales must have increased.","B":"Falling sales would reduce market share when the total market is constant. Since the share rose from 8 to 12 percent, sales cannot have fallen.","C":"Unchanged sales would keep the share constant at 8 percent, not raise it to 12 percent. A higher share with a constant market requires higher sales.","D":"Doubling sales would double the share from 8 to 16 percent, not to 12 percent. The share rose by half, so sales rose by half, not by 100 percent."}}},{"id":"P1_U3_MCQ_1817","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1817","question":"Zadar Bicycles, based in Split, Croatia, finds that commuters ask for built-in GPS tracking on its bikes. The marketing team notes that the deeper requirement is simply reliable, safe transport to work. What is the GPS request an example of?","options":{"A":"Need","B":"Basic requirement","C":"Want","D":"Necessity"},"correctOption":"C","correctAnswer":"Want","questionType":"MCQ","explanation":{"correct_reason":"A want is a particular way of satisfying an underlying need. Commuters need reliable, safe transport, and GPS tracking is one desired extra, so the request illustrates a want rather than a basic need.","distractor_reasons":{"A":"A need is a basic requirement such as safe transport. GPS tracking is not basic to getting to work; it is a preferred addition, so it is a want.","B":"A basic requirement would be something essential like a functioning bicycle. GPS tracking is an optional feature, so it does not count as a basic requirement.","C":"A want is a particular way of satisfying an underlying need. Commuters need reliable, safe transport, and GPS tracking is one desired extra, so the request illustrates a want rather than a basic need.","D":"A necessity is essential for survival or basic functioning. GPS tracking is a convenience, so calling it a necessity would be incorrect."}}},{"id":"P1_U3_MCQ_1818","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1818","question":"Rijeka Cookware, based in Rijeka, Croatia, spent $4,800 on a customer survey and obtained 120 usable responses. The finance manager wants the cost of each usable response. What was the cost per usable response?","options":{"A":"$40","B":"$48","C":"$120","D":"$400"},"correctOption":"A","correctAnswer":"$40","questionType":"MCQ","explanation":{"correct_reason":"Cost per response is total survey cost divided by the number of usable responses. Rijeka Cookware spent $4,800 and gained 120 usable responses, and $4,800 divided by 120 equals $40 per response.","distractor_reasons":{"A":"Cost per response is total survey cost divided by the number of usable responses. Rijeka Cookware spent $4,800 and gained 120 usable responses, and $4,800 divided by 120 equals $40 per response.","B":"$48 would be the result of dividing $4,800 by 100, not by the 120 responses actually obtained. The correct figure is $40.","C":"$120 mistakes the number of responses for a cost. Dividing the $4,800 cost by 120 responses gives $40, so this option is wrong.","D":"$400 is ten times the correct cost and would imply only 12 responses. With 120 usable responses, the cost is $40 each."}}},{"id":"P1_U3_MCQ_1819","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1819","question":"Ljubljana Lighting, based in Ljubljana, Slovenia, lists a floor lamp at $250 and offers a temporary discount of 20 percent. What is the price a customer pays during the discount period?","options":{"A":"$230","B":"$200","C":"$50","D":"$270"},"correctOption":"B","correctAnswer":"$200","questionType":"MCQ","explanation":{"correct_reason":"A 20 percent discount on $250 is $50, because 250 multiplied by 0.2 equals 50. Subtracting $50 from the $250 list price gives a sale price of $200.","distractor_reasons":{"A":"$230 subtracts only $20, which is an 8 percent discount rather than 20 percent. The correct reduction is $50, giving a $200 price.","B":"A 20 percent discount on $250 is $50, because 250 multiplied by 0.2 equals 50. Subtracting $50 from the $250 list price gives a sale price of $200.","C":"$50 is the amount of the discount, not the price paid. The customer pays the list price less the discount, which is $200.","D":"$270 adds the discount to the list price instead of subtracting it. A discount lowers the price, so the correct figure is $200."}}},{"id":"P1_U3_MCQ_1820","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1820","question":"Bratislava Floorcoverings, based in Bratislava, Slovakia, sells an average of 1,200 ceramic tiles per week. The marketing planner wants a simple annual sales forecast assuming 52 trading weeks. What is the forecast annual volume?","options":{"A":"6,240 tiles","B":"14,400 tiles","C":"62,400 tiles","D":"624,000 tiles"},"correctOption":"C","correctAnswer":"62,400 tiles","questionType":"MCQ","explanation":{"correct_reason":"The annual forecast is the weekly average multiplied by the number of trading weeks. Bratislava Floorcoverings sells 1,200 tiles a week, and 1,200 multiplied by 52 weeks gives 62,400 tiles a year.","distractor_reasons":{"A":"6,240 is one tenth of the correct total and would result from using 5.2 weeks rather than 52. Multiplying 1,200 by 52 gives 62,400.","B":"14,400 would come from multiplying 1,200 by 12 months, treating a month as a week. The forecast uses 52 weeks, so the answer is 62,400.","C":"The annual forecast is the weekly average multiplied by the number of trading weeks. Bratislava Floorcoverings sells 1,200 tiles a week, and 1,200 multiplied by 52 weeks gives 62,400 tiles a year.","D":"624,000 is ten times the correct forecast and would require 520 weeks. With 52 weeks and 1,200 tiles a week, the total is 62,400."}}},{"id":"P1_U3_MCQ_1821","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1821","question":"Debrecen Herbals, based in Budapest, Hungary, produces one standard herbal tea and promotes it identically to all households across the country, with no attempt to separate customer groups. Which approach to the market is this?","options":{"A":"Niche marketing","B":"Target marketing","C":"Relationship marketing","D":"Mass marketing"},"correctOption":"D","correctAnswer":"Mass marketing","questionType":"MCQ","explanation":{"correct_reason":"Mass marketing aims a single offer at the whole market without segmenting. Debrecen Herbals sells one tea to every household using the same promotion, so it is practising mass marketing.","distractor_reasons":{"A":"Niche marketing concentrates on a small specialist group. Debrecen Herbals addresses all households with one product, which is the opposite of a niche focus.","B":"Target marketing involves selecting particular segments to serve. This firm makes no segment choices at all, so target marketing does not describe its approach.","C":"Relationship marketing focuses on building long-term ties with individual customers. The scenario describes undifferentiated national promotion, not one-to-one relationship building. The scenario for Debrecen Herbals instead describes Mass marketing, which rules this alternative out.","D":"Mass marketing aims a single offer at the whole market without segmenting. Debrecen Herbals sells one tea to every household using the same promotion, so it is practising mass marketing."}}},{"id":"P1_U3_MCQ_1822","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1822","question":"Pecs Greetings, based in Pecs, Hungary, uses free population statistics published by the government rather than paying for its own survey. Which advantage of secondary research is illustrated by this decision?","options":{"A":"It is cheaper and quicker to obtain","B":"It is always more accurate","C":"It is collected first-hand","D":"It cannot become out of date"},"correctOption":"A","correctAnswer":"It is cheaper and quicker to obtain","questionType":"MCQ","explanation":{"correct_reason":"Secondary data already exist, so they are usually cheaper and faster to obtain than collecting fresh primary data. Pecs Greetings avoids survey costs by using free government statistics, which shows this cost and time advantage.","distractor_reasons":{"A":"Secondary data already exist, so they are usually cheaper and faster to obtain than collecting fresh primary data. Pecs Greetings avoids survey costs by using free government statistics, which shows this cost and time advantage.","B":"Secondary data are not always more accurate; they may have been collected for a different purpose. The clear advantage here is lower cost and speed, not guaranteed accuracy.","C":"Data collected first-hand would be primary research. Pecs Greetings is using existing government statistics, so the data are secondary and not gathered first-hand.","D":"Secondary data can become out of date because they were collected earlier. The scenario shows cost savings, not freedom from ageing."}}},{"id":"P1_U3_MCQ_1823","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1823","question":"Vilnius Pet Supplies, based in Vilnius, Lithuania, gives its dog food a distinctive name, logo and colour scheme so owners can recognise it instantly on a crowded shelf. What is this use of a name and symbol called?","options":{"A":"Market research","B":"Sales promotion","C":"Branding","D":"Distribution"},"correctOption":"C","correctAnswer":"Branding","questionType":"MCQ","explanation":{"correct_reason":"Branding is the use of a name, symbol or design to identify a product and distinguish it from rivals. The distinctive name, logo and colours used by Vilnius Pet Supplies are branding.","distractor_reasons":{"A":"Market research is the collection of information about customers. Choosing a name and logo is a product decision, not a research activity.","B":"Sales promotion uses short-term incentives to stimulate purchases. A name and logo are long-term identifiers, not a temporary incentive. In Vilnius Pet's case, the correct description is Branding, not this choice.","C":"Branding is the use of a name, symbol or design to identify a product and distinguish it from rivals. The distinctive name, logo and colours used by Vilnius Pet Supplies are branding.","D":"Distribution concerns how a product reaches customers. The name and logo help recognition, so they belong to branding rather than distribution."}}},{"id":"P1_U3_MCQ_1824","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1824","question":"Kaunas Aquatics, based in Kaunas, Lithuania, has identified several distinct groups of swimming-pool owners and now decides to concentrate its effort on just two of those groups. What is this decision called?","options":{"A":"Market segmentation","B":"Market targeting","C":"Market research","D":"Market positioning"},"correctOption":"B","correctAnswer":"Market targeting","questionType":"MCQ","explanation":{"correct_reason":"Market targeting is the choice of which identified segments to serve. Kaunas Aquatics first identified several groups and then selected two, so the decision is one of market targeting.","distractor_reasons":{"A":"Market segmentation is the act of dividing buyers into groups. That step has already happened; the scenario describes choosing which groups to serve, which is targeting.","B":"Market targeting is the choice of which identified segments to serve. Kaunas Aquatics first identified several groups and then selected two, so the decision is one of market targeting.","C":"Market research gathers the information used to find segments. The firm is past the research stage and is choosing segments, so this option is not correct.","D":"Market positioning concerns how a product is perceived relative to rivals. The decision described is which customer groups to serve, not how to be perceived."}}},{"id":"P1_U3_MCQ_1825","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1825","question":"Tartu Confectionery, based in Tallinn, Estonia, sells boxes of chocolates to hotels and cafés, which then resell them to their guests. The firm does not sell directly to the people eating the chocolates. What kind of market is it supplying?","options":{"A":"Business-to-business market","B":"Consumer market","C":"Mass market","D":"Niche market"},"correctOption":"A","correctAnswer":"Business-to-business market","questionType":"MCQ","explanation":{"correct_reason":"A business-to-business market consists of organisations buying goods for resale or use in their own operations. Tartu Confectionery sells to hotels and cafés for resale, so it operates in the organisational market.","distractor_reasons":{"A":"A business-to-business market consists of organisations buying goods for resale or use in their own operations. Tartu Confectionery sells to hotels and cafés for resale, so it operates in the organisational market.","B":"A consumer market involves selling to the final users for personal consumption. Tartu Confectionery sells to businesses that resell, not directly to the people eating the chocolates.","C":"A mass market aims at a large, undifferentiated group of buyers. The scenario describes the type of customer, not the breadth of the market covered.","D":"A niche market targets a narrow specialist group. The question is about selling to organisations rather than final consumers, not about how narrow the market is."}}},{"id":"P1_U3_MCQ_1826","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1826","question":"Turku Apparel, based in Helsinki, Finland, asked five customers how much they spent on clothing last month and received the figures $20, $30, $40, $50 and $60. What was the mean amount spent by these five respondents?","options":{"A":"$30","B":"$35","C":"$45","D":"$40"},"correctOption":"D","correctAnswer":"$40","questionType":"MCQ","explanation":{"correct_reason":"The mean is the sum of the values divided by the number of values. The five amounts total $200, and $200 divided by 5 respondents gives a mean spending figure of $40.","distractor_reasons":{"A":"$30 is below the true average and corresponds to ignoring the two highest figures. The correct mean uses all five amounts and equals $40.","B":"$35 would result from dividing $175 by 5. The five amounts actually sum to $200, so the mean is $40. For Turku Apparel, the facts point to $40, so this option cannot be correct.","C":"$45 is the mean of only the top three figures. Including all five responses gives a mean of $40, not $45.","D":"The mean is the sum of the values divided by the number of values. The five amounts total $200, and $200 divided by 5 respondents gives a mean spending figure of $40."}}},{"id":"P1_U3_MCQ_1827","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1827","question":"Tampere Leather, based in Tampere, Finland, sells a leather belt for $30. The material and labour cost for each belt is $18. What is the contribution earned on each belt sold?","options":{"A":"$12","B":"$18","C":"$30","D":"$48"},"correctOption":"A","correctAnswer":"$12","questionType":"MCQ","explanation":{"correct_reason":"Contribution per unit is the selling price less the variable cost of making that unit. Tampere Leather receives $30 for each belt and spends $18 on materials and labour, so the contribution is $12.","distractor_reasons":{"A":"Contribution per unit is the selling price less the variable cost of making that unit. Tampere Leather receives $30 for each belt and spends $18 on materials and labour, so the contribution is $12.","B":"$18 is the cost of making the belt, not the contribution. Contribution is the selling price minus that cost, which equals $12.","C":"$30 is the selling price, not the amount left after variable costs. Subtracting the $18 cost leaves a contribution of $12.","D":"$48 adds the cost to the price, which is meaningless here. Contribution deducts cost from price, giving $12 per belt. Tampere Leather's circumstances match $12, so this option does not fit."}}},{"id":"P1_U3_MCQ_1828","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1828","question":"Aarhus Homewares, based in Aarhus, Denmark, kept its own sales unchanged last year while the total market for kitchenware grew by 10 percent. What happened to the firm's market share over the year?","options":{"A":"It rose","B":"It stayed the same","C":"It fell","D":"It doubled"},"correctOption":"C","correctAnswer":"It fell","questionType":"MCQ","explanation":{"correct_reason":"Market share is the firm's sales divided by total market sales. With the firm's sales flat and the overall market 10 percent larger, the same numerator over a bigger denominator means the share fell.","distractor_reasons":{"A":"A rising share would need the firm's sales to grow faster than the market. Sales were unchanged while the market expanded, so the share could not have risen.","B":"An unchanged share would require the firm's sales to grow at the same 10 percent rate as the market. They did not, so the share cannot be unchanged.","C":"Market share is the firm's sales divided by total market sales. With the firm's sales flat and the overall market 10 percent larger, the same numerator over a bigger denominator means the share fell.","D":"Doubling is impossible when sales were flat and the market grew only 10 percent. The share must have fallen, though only slightly."}}},{"id":"P1_U3_MCQ_1829","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1829","question":"Odense Cosmetics, based in Odense, Denmark, promises free home delivery within twenty-four hours, while competing firms take three days. Many customers choose the firm because of this speed. What does the delivery promise represent?","options":{"A":"Product orientation","B":"Competitive advantage through customer service","C":"Market segmentation","D":"Sales promotion"},"correctOption":"B","correctAnswer":"Competitive advantage through customer service","questionType":"MCQ","explanation":{"correct_reason":"A competitive advantage can come from superior customer service. Odense Cosmetics delivers in twenty-four hours against rivals' three days, and customers choose it for that reason, so the promise is a service-based advantage.","distractor_reasons":{"A":"Product orientation focuses on the product itself rather than service or market needs. The scenario highlights a delivery service that wins customers, so it is not product orientation.","B":"A competitive advantage can come from superior customer service. Odense Cosmetics delivers in twenty-four hours against rivals' three days, and customers choose it for that reason, so the promise is a service-based advantage.","C":"Market segmentation divides buyers into groups. The delivery promise is the same for all customers, so it does not involve splitting buyers into segments.","D":"Sales promotion uses short-term incentives such as discounts. Free fast delivery is an ongoing service, not a limited-time promotional offer. For Odense Cosmetics, the facts point to Competitive advantage through customer service, so this option cannot be correct."}}},{"id":"P1_U3_MCQ_1830","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1830","question":"Stavanger Safes, based in Stavanger, Norway, has 6,000 business customers and decides to survey a sample equal to 5 percent of that population. How many customers should be included in the sample?","options":{"A":"30","B":"300","C":"600","D":"1,200"},"correctOption":"B","correctAnswer":"300","questionType":"MCQ","explanation":{"correct_reason":"The sample size is the population multiplied by the required percentage. Stavanger Safes has 6,000 customers and 5 percent of 6,000 is 300, so 300 customers should be surveyed.","distractor_reasons":{"A":"30 is 5 percent of 600, not of 6,000. With a population of 6,000 business customers, 5 percent gives 300. The details given about Stavanger Safes support 300, so this answer is unsuitable.","B":"The sample size is the population multiplied by the required percentage. Stavanger Safes has 6,000 customers and 5 percent of 6,000 is 300, so 300 customers should be surveyed.","C":"600 is 10 percent of the 6,000 customers. The firm wants a 5 percent sample, which is 300 customers. The scenario for Stavanger Safes instead describes 300, which rules this alternative out.","D":"1,200 is 20 percent of 6,000, four times the intended sample. The correct 5 percent sample is 300. In Stavanger Safes's case, the correct description is 300, not this choice."}}},{"id":"P1_U3_MCQ_1831","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1831","question":"Kristiansand Blinds, based in Kristiansand, Norway, launched a new energy-saving blind two years ago and sales have risen sharply each year as awareness spreads. Which stage of the product life cycle is the blind in?","options":{"A":"Growth","B":"Decline","C":"Maturity","D":"Withdrawal"},"correctOption":"A","correctAnswer":"Growth","questionType":"MCQ","explanation":{"correct_reason":"The growth stage is marked by rapidly rising sales as a product wins acceptance. Kristiansand Blinds' sales have climbed sharply for two years since launch, which matches the growth stage.","distractor_reasons":{"A":"The growth stage is marked by rapidly rising sales as a product wins acceptance. Kristiansand Blinds' sales have climbed sharply for two years since launch, which matches the growth stage.","B":"Decline involves falling sales, the opposite of what is happening. Sales of the new blind have risen sharply each year, so the product is not in decline.","C":"Maturity is reached when sales growth slows and levels off. The blind's sales are still rising rapidly, so it has not yet reached maturity.","D":"Withdrawal would mean removing the product from the market. The firm is experiencing rising sales, so withdrawal is clearly not the current stage."}}},{"id":"P1_U3_MCQ_1832","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1832","question":"Reykjavik Fishing Gear, based in Reykjavik, Iceland, states that it aims to raise its share of the national market from 12 percent to 18 percent within two years. What kind of business objective has the firm set?","options":{"A":"A production objective","B":"A financial objective","C":"A customer service objective","D":"A marketing objective"},"correctOption":"D","correctAnswer":"A marketing objective","questionType":"MCQ","explanation":{"correct_reason":"A marketing objective concerns market-related goals such as share, sales or customer reach. Reykjavik Fishing Gear aims to increase market share from 12 to 18 percent, which is a marketing objective.","distractor_reasons":{"A":"A production objective would concern output volumes or efficiency. Raising market share is about performance in the marketplace, not the production process.","B":"A financial objective would target profit, revenue or cash. The stated goal is a share of the market, so it is not primarily financial.","C":"A customer service objective would target delivery times or satisfaction levels. Increasing market share is a broader market goal, not a service target.","D":"A marketing objective concerns market-related goals such as share, sales or customer reach. Reykjavik Fishing Gear aims to increase market share from 12 to 18 percent, which is a marketing objective."}}},{"id":"P1_U3_MCQ_1833","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1833","question":"Akureyri Woollens, based in Akureyri, Iceland, recorded sales revenue of $15 million last year. The total Icelandic market for woollens was worth $120 million over the same period. What was the firm's market share by value?","options":{"A":"8%","B":"10%","C":"12.5%","D":"15%"},"correctOption":"C","correctAnswer":"12.5%","questionType":"MCQ","explanation":{"correct_reason":"Market share by value is the firm's revenue divided by total market value, multiplied by 100. Akureyri Woollens earned $15 million in a $120 million market, and 15 divided by 120 is 0.125, or 12.5 percent.","distractor_reasons":{"A":"8 percent would mean revenue of $9.6 million in a $120 million market. The firm earned $15 million, giving a share of 12.5 percent.","B":"10 percent corresponds to $12 million of sales. Since Akureyri Woollens earned $15 million, its share is 12.5 percent. Akureyri Woollens's circumstances match 12.5%, so this option does not fit.","C":"Market share by value is the firm's revenue divided by total market value, multiplied by 100. Akureyri Woollens earned $15 million in a $120 million market, and 15 divided by 120 is 0.125, or 12.5 percent.","D":"15 percent mistakes the $15 million revenue figure for a share. Dividing $15 million by the $120 million market gives 12.5 percent."}}},{"id":"P1_U3_MCQ_1834","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1834","question":"Galway Bakeware, based in Galway, Ireland, surveyed 2,400 households and found that 35 percent of them had bought baking tins in the past year. How many of the surveyed households had made such a purchase?","options":{"A":"840","B":"240","C":"700","D":"960"},"correctOption":"A","correctAnswer":"840","questionType":"MCQ","explanation":{"correct_reason":"The number of households is the survey total multiplied by the percentage. Galway Bakeware surveyed 2,400 households and 35 percent bought tins, and 2,400 multiplied by 0.35 equals 840 households.","distractor_reasons":{"A":"The number of households is the survey total multiplied by the percentage. Galway Bakeware surveyed 2,400 households and 35 percent bought tins, and 2,400 multiplied by 0.35 equals 840 households.","B":"240 is roughly ten percent of the sample, not 35 percent. Multiplying 2,400 by 0.35 gives 840 households. The details given about Galway Bakeware support 840, so this answer is unsuitable.","C":"700 would come from using a rate of about 29 percent. The stated figure is 35 percent of 2,400, which is 840.","D":"960 is 40 percent of 2,400, above the 35 percent reported. The correct count is 840 households. The scenario for Galway Bakeware instead describes 840, which rules this alternative out."}}},{"id":"P1_U3_MCQ_1835","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1835","question":"Limerick Cleaning, based in Limerick, Ireland, provides a carpet-cleaning service that costs the firm $25 per job and is sold for $40. What is the percentage mark-up on cost for each job?","options":{"A":"15%","B":"25%","C":"37.5%","D":"60%"},"correctOption":"D","correctAnswer":"60%","questionType":"MCQ","explanation":{"correct_reason":"Mark-up on cost is the profit added divided by the cost, multiplied by 100. The profit is $40 minus $25, which is $15, and $15 divided by the $25 cost equals 0.6, or 60 percent.","distractor_reasons":{"A":"15 percent confuses the $15 profit with a percentage. The mark-up is the profit relative to the $25 cost, which is 60 percent.","B":"25 percent is the cost expressed as a fraction of the price. The mark-up on cost is $15 profit over $25 cost, equal to 60 percent.","C":"37.5 percent is the profit margin on selling price, $15 over $40. The question asks for mark-up on cost, which is 60 percent.","D":"Mark-up on cost is the profit added divided by the cost, multiplied by 100. The profit is $40 minus $25, which is $15, and $15 divided by the $25 cost equals 0.6, or 60 percent."}}},{"id":"P1_U3_MCQ_1836","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1836","question":"Cork Tiles, based in Cork, Ireland, estimates the national tile market at $92 million this year and expects it to grow by 10 percent over the next twelve months. What is the forecast market value next year?","options":{"A":"$100 million","B":"$101.2 million","C":"$102 million","D":"$9.2 million"},"correctOption":"B","correctAnswer":"$101.2 million","questionType":"MCQ","explanation":{"correct_reason":"A 10 percent increase on $92 million is $9.2 million, since 92 multiplied by 0.1 equals 9.2. Adding $9.2 million to $92 million gives a forecast market value of $101.2 million.","distractor_reasons":{"A":"$100 million rounds the increase incorrectly to $8 million. A true 10 percent of $92 million is $9.2 million, giving $101.2 million.","B":"A 10 percent increase on $92 million is $9.2 million, since 92 multiplied by 0.1 equals 9.2. Adding $9.2 million to $92 million gives a forecast market value of $101.2 million.","C":"$102 million uses a $10 million increase, which is about 10.9 percent. The exact 10 percent rise gives $101.2 million. In Cork Tiles's case, the correct description is $101.2 million, not this choice.","D":"$9.2 million is the amount of growth, not the new market value. Adding it to $92 million gives $101.2 million. Cork Tiles's circumstances match $101.2 million, so this option does not fit."}}},{"id":"P1_U3_MCQ_1837","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1837","question":"Waterford Glassware, based in Waterford, Ireland, begins each product idea by asking customers what they want, then designs the glassware to meet those stated needs. Which business orientation does this describe?","options":{"A":"Sales orientation","B":"Market orientation","C":"Production orientation","D":"Product orientation"},"correctOption":"B","correctAnswer":"Market orientation","questionType":"MCQ","explanation":{"correct_reason":"A market orientation puts customer needs at the centre of decision-making. Waterford Glassware researches what buyers want before designing products, so it demonstrates a market orientation.","distractor_reasons":{"A":"A sales orientation focuses on selling what has already been made, often through heavy promotion. Waterford Glassware starts with customer research, so it is not sales-oriented.","B":"A market orientation puts customer needs at the centre of decision-making. Waterford Glassware researches what buyers want before designing products, so it demonstrates a market orientation.","C":"A production orientation emphasises efficient manufacture and capacity. The firm is driven by customer wishes rather than production convenience. Waterford Glassware's circumstances match Market orientation, so this option does not fit.","D":"A product orientation focuses on the product itself and its features. Waterford Glassware instead begins with customer needs, which is a market orientation."}}},{"id":"P1_U3_MCQ_1838","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1838","question":"Kilkenny Crafts, based in Kilkenny, Ireland, researches customer opinions by questioning only people leaving its own shop on a Saturday morning. What is the main weakness of this research method?","options":{"A":"Secondary data problem","B":"Quantitative data problem","C":"Sampling bias","D":"Focus group problem"},"correctOption":"C","correctAnswer":"Sampling bias","questionType":"MCQ","explanation":{"correct_reason":"Sampling bias occurs when the people questioned are not representative of all customers. By asking only shoppers leaving its own store, Kilkenny Crafts excludes non-customers and other times, so the sample is biased.","distractor_reasons":{"A":"The problem is not that the data are secondary; the firm is collecting fresh opinions. The flaw is that the people selected are unrepresentative, which is sampling bias.","B":"Quantitative data are simply numerical information; they are not inherently flawed. The weakness here lies in who was chosen, not in the type of data.","C":"Sampling bias occurs when the people questioned are not representative of all customers. By asking only shoppers leaving its own store, Kilkenny Crafts excludes non-customers and other times, so the sample is biased.","D":"A focus group is a particular research method involving group discussion. Kilkenny Crafts is conducting individual street interviews, and the issue is bias rather than method choice."}}},{"id":"P1_U3_MCQ_1839","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1839","question":"Dundee Jams, based in Dundee, Scotland, sells all of its products through its own website and delivers directly to buyers, with no shops or intermediaries involved. Which distribution approach is the firm using?","options":{"A":"Direct distribution","B":"Indirect distribution","C":"Wholesale distribution","D":"Franchising"},"correctOption":"A","correctAnswer":"Direct distribution","questionType":"MCQ","explanation":{"correct_reason":"Direct distribution means selling straight to the final customer without intermediaries. Dundee Jams uses only its own website and delivers to buyers itself, so it is using direct distribution.","distractor_reasons":{"A":"Direct distribution means selling straight to the final customer without intermediaries. Dundee Jams uses only its own website and delivers to buyers itself, so it is using direct distribution.","B":"Indirect distribution uses intermediaries such as retailers or wholesalers. Dundee Jams has no such middlemen, so its approach is direct. The details given about Dundee Jams support Direct distribution, so this answer is unsuitable.","C":"Wholesale distribution involves selling in bulk to intermediaries who resell. The firm sells individual orders to final buyers online, not to wholesalers.","D":"Franchising lets independent operators trade under a brand. Dundee Jams sells through its own website, not through franchisees. The scenario for Dundee Jams instead describes Direct distribution, which rules this alternative out."}}},{"id":"P1_U3_MCQ_1840","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1840","question":"Aberdeen Knitwear, based in Aberdeen, Scotland, constantly benchmarks its costs against competitors and prices its jumpers below rivals while keeping a similar design. Which competitive strategy is the firm pursuing?","options":{"A":"Differentiation","B":"Niche marketing","C":"Market development","D":"Cost leadership"},"correctOption":"D","correctAnswer":"Cost leadership","questionType":"MCQ","explanation":{"correct_reason":"Cost leadership means becoming the lowest-cost producer so prices can undercut rivals. Aberdeen Knitwear monitors costs and prices below competitors with comparable designs, so it is pursuing cost leadership.","distractor_reasons":{"A":"Differentiation means offering something uniquely valued, such as superior quality or branding. Aberdeen Knitwear's jumpers are similar in design, so it is competing on cost rather than difference.","B":"Niche marketing targets a narrow customer group. The scenario describes competing on price across the market, not focusing on a specialist segment.","C":"Market development means selling existing products to new markets. The firm is not entering new markets; it is undercutting rivals on price.","D":"Cost leadership means becoming the lowest-cost producer so prices can undercut rivals. Aberdeen Knitwear monitors costs and prices below competitors with comparable designs, so it is pursuing cost leadership."}}},{"id":"P1_U3_MCQ_1841","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1841","question":"Inverness Outdoors, based in Inverness, Scotland, is studying the people who need waterproof jackets, have the money to buy them and are willing to do so. What is this group of potential buyers called?","options":{"A":"Industry","B":"Market","C":"Target segment","D":"Distribution channel"},"correctOption":"B","correctAnswer":"Market","questionType":"MCQ","explanation":{"correct_reason":"A market consists of people with a need or want, the ability to pay and the willingness to buy. Those potential jacket buyers described for Inverness Outdoors make up a market.","distractor_reasons":{"A":"An industry is a group of firms producing similar products. The people described are buyers, not producers, so they form a market.","B":"A market consists of people with a need or want, the ability to pay and the willingness to buy. Those potential jacket buyers described for Inverness Outdoors make up a market.","C":"A target segment is a specific subgroup a firm chooses to serve. The description refers to all potential buyers, which is the broader market.","D":"A distribution channel is the route a product takes to customers. The group described is the customers themselves, not a channel."}}},{"id":"P1_U3_MCQ_1842","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1842","question":"Stirling Gym Equipment, based in Stirling, Scotland, surveyed 1,250 gym members and found that 18 percent intended to buy a new rowing machine. How many of those surveyed intended to make the purchase?","options":{"A":"250","B":"225","C":"180","D":"125"},"correctOption":"B","correctAnswer":"225","questionType":"MCQ","explanation":{"correct_reason":"The number of buyers is the survey total multiplied by the percentage. Stirling Gym Equipment surveyed 1,250 members and 18 percent intended to buy, and 1,250 multiplied by 0.18 equals 225.","distractor_reasons":{"A":"250 is 20 percent of 1,250, not the 18 percent reported. Multiplying 1,250 by 0.18 gives 225 members. In Stirling Gym Equipment's case, the correct description is 225, not this choice.","B":"The number of buyers is the survey total multiplied by the percentage. Stirling Gym Equipment surveyed 1,250 members and 18 percent intended to buy, and 1,250 multiplied by 0.18 equals 225.","C":"180 would come from misplacing the decimal when converting 18 percent. The correct 18 percent of 1,250 is 225. The details given about Stirling Gym Equipment support 225, so this answer is unsuitable.","D":"125 is ten percent of the sample. Since 18 percent intended to buy, the correct number is 225. For Stirling Gym Equipment, the facts point to 225, so this option cannot be correct."}}},{"id":"P1_U3_MCQ_1843","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1843","question":"Perth Soft Drinks, based in Perth, Scotland, launches a new energy drink at a deliberately low price to attract customers quickly from established brands and build market share. Which pricing method is being used?","options":{"A":"Penetration pricing","B":"Price skimming","C":"Cost-plus pricing","D":"Competitive pricing"},"correctOption":"A","correctAnswer":"Penetration pricing","questionType":"MCQ","explanation":{"correct_reason":"Penetration pricing sets a low initial price to win customers and gain share rapidly. Perth Soft Drinks prices its new drink low to take buyers from rivals, so it is using penetration pricing.","distractor_reasons":{"A":"Penetration pricing sets a low initial price to win customers and gain share rapidly. Perth Soft Drinks prices its new drink low to take buyers from rivals, so it is using penetration pricing.","B":"Price skimming sets a high initial price, the opposite of this case. The new drink is launched deliberately low, so it is not skimming.","C":"Cost-plus pricing sets a price by adding a mark-up to costs. The scenario describes a low launch price aimed at share, not a cost calculation.","D":"Competitive pricing sets a price close to rivals. Perth Soft Drinks prices below rivals to win share, which is penetration pricing."}}},{"id":"P1_U3_MCQ_1844","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1844","question":"Swansea Snacks, based in Swansea, Wales, divides its market into groups such as students, office workers and families, then tailors flavours and promotions to each. What is the main benefit of this segmentation?","options":{"A":"It removes competition","B":"It lowers production costs automatically","C":"It helps a firm meet the needs of distinct customer groups more precisely","D":"It guarantees higher profits"},"correctOption":"C","correctAnswer":"It helps a firm meet the needs of distinct customer groups more precisely","questionType":"MCQ","explanation":{"correct_reason":"Segmentation lets a firm tailor its offer to the particular needs of different buyer groups. Swansea Snacks adapts flavours and promotions for students, workers and families, so it meets distinct needs more precisely.","distractor_reasons":{"A":"Segmentation does not remove competitors; rivals remain in the market. Its benefit is better matching of products to customer groups, not eliminating competition.","B":"Segmentation can raise costs because separate products and campaigns are needed. It does not automatically lower production costs. For Swansea Snacks, the facts point to It helps a firm meet the needs of distinct customer groups more precisely, so this option cannot be correct.","C":"Segmentation lets a firm tailor its offer to the particular needs of different buyer groups. Swansea Snacks adapts flavours and promotions for students, workers and families, so it meets distinct needs more precisely.","D":"Segmentation does not guarantee higher profits; outcomes depend on execution. The direct benefit is more precisely meeting the needs of different groups."}}},{"id":"P1_U3_MCQ_1845","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1845","question":"Cardiff Greeting Cards, based in Cardiff, Wales, keeps a database of regular customers and sends them personalised offers around birthdays and anniversaries to encourage repeat purchases. Which approach to customers is this?","options":{"A":"Mass marketing","B":"Sales orientation","C":"Product orientation","D":"Relationship marketing"},"correctOption":"D","correctAnswer":"Relationship marketing","questionType":"MCQ","explanation":{"correct_reason":"Relationship marketing builds long-term ties with customers to encourage repeat business. Cardiff Greeting Cards uses a database and personalised offers to keep buyers returning, so it is relationship marketing.","distractor_reasons":{"A":"Mass marketing uses one undifferentiated message for everyone. Personalised offers based on customer records are the opposite of a mass approach.","B":"Sales orientation focuses on pushing sales of existing products. The database approach is about maintaining ongoing relationships, not one-off selling. The scenario for Cardiff Greeting Cards instead describes Relationship marketing, which rules this alternative out.","C":"Product orientation centres on the product itself. Cardiff Greeting Cards focuses on individual customer relationships, so product orientation does not fit.","D":"Relationship marketing builds long-term ties with customers to encourage repeat business. Cardiff Greeting Cards uses a database and personalised offers to keep buyers returning, so it is relationship marketing."}}},{"id":"P1_U3_MCQ_1846","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1846","question":"Belfast Frozen Foods, based in Belfast, Northern Ireland, sends researchers to supermarkets to watch silently how shoppers compare and select frozen meals, without asking them any questions. What primary research method is being used?","options":{"A":"Observation","B":"Experiment","C":"Questionnaire","D":"Secondary research"},"correctOption":"A","correctAnswer":"Observation","questionType":"MCQ","explanation":{"correct_reason":"Observation involves watching and recording behaviour without asking questions. Belfast Frozen Foods' researchers watch shoppers choosing meals in-store, so the method is observation.","distractor_reasons":{"A":"Observation involves watching and recording behaviour without asking questions. Belfast Frozen Foods' researchers watch shoppers choosing meals in-store, so the method is observation.","B":"An experiment changes a variable to measure an effect, such as altering a price. The researchers change nothing and simply watch, so this is not an experiment.","C":"A questionnaire asks respondents set questions. Here no questions are put to shoppers; their behaviour is watched, so it is not a questionnaire.","D":"Secondary research uses existing data. Watching shoppers in person generates new first-hand data, so it is primary observation. The details given about Belfast Frozen Foods support Observation, so this answer is unsuitable."}}},{"id":"P1_U3_MCQ_1847","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1847","question":"Newry Fabrics, based in Newry, Northern Ireland, sold 4,000 metres of curtain material last month for total revenue of $28,000. What was the average selling price per metre of material?","options":{"A":"$6","B":"$7","C":"$8","D":"$28"},"correctOption":"B","correctAnswer":"$7","questionType":"MCQ","explanation":{"correct_reason":"Average selling price is total revenue divided by the quantity sold. Newry Fabrics earned $28,000 from 4,000 metres, and $28,000 divided by 4,000 equals $7 per metre.","distractor_reasons":{"A":"$6 would give revenue of only $24,000 on 4,000 metres. The actual revenue was $28,000, so the average price is $7.","B":"Average selling price is total revenue divided by the quantity sold. Newry Fabrics earned $28,000 from 4,000 metres, and $28,000 divided by 4,000 equals $7 per metre.","C":"$8 would produce $32,000 from 4,000 metres, above the stated revenue. Dividing $28,000 by 4,000 gives $7. The details given about Newry Fabrics support $7, so this answer is unsuitable.","D":"$28 is a tenth of the revenue figure, not a price per metre. The correct average is $7. For Newry Fabrics, the facts point to $7, so this option cannot be correct."}}},{"id":"P1_U3_MCQ_1848","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1848","question":"Pisa Shoes, based in Pisa, Italy, kept its market share at 9 percent last year while the total shoe market grew by 20 percent. What happened to the firm's own sales?","options":{"A":"They grew by about 20%","B":"They fell","C":"They stayed the same","D":"They doubled"},"correctOption":"A","correctAnswer":"They grew by about 20%","questionType":"MCQ","explanation":{"correct_reason":"If share stays constant, the firm's sales change at the same rate as the total market. With the market up 20 percent and share unchanged at 9 percent, Pisa Shoes' sales also rose by 20 percent.","distractor_reasons":{"A":"If share stays constant, the firm's sales change at the same rate as the total market. With the market up 20 percent and share unchanged at 9 percent, Pisa Shoes' sales also rose by 20 percent.","B":"Falling sales would reduce share if the market grew. Since the share stayed at 9 percent while the market expanded, sales must have grown.","C":"Unchanged sales would cause share to fall when the market grows 20 percent. The share held steady, so sales grew with the market.","D":"Doubling sales would raise share well above 9 percent. With share flat, sales grew at the market rate of 20 percent, not 100 percent."}}},{"id":"P1_U3_MCQ_1849","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1849","question":"Siena Olive Oil, based in Siena, Italy, supplies only a small number of premium restaurants and charges a high price for its limited output, ignoring ordinary households. Which market approach does this illustrate?","options":{"A":"Mass marketing","B":"Undifferentiated marketing","C":"Niche marketing","D":"Direct marketing"},"correctOption":"C","correctAnswer":"Niche marketing","questionType":"MCQ","explanation":{"correct_reason":"Niche marketing targets a narrow, specialist group with a tailored offer. Siena Olive Oil focuses on premium restaurants and ignores households, so it is serving a niche.","distractor_reasons":{"A":"Mass marketing aims at the whole market with one offer. Supplying only premium restaurants is a narrow focus, not a mass approach.","B":"Undifferentiated marketing treats all customers alike. Siena Olive Oil deliberately selects one specialist buyer group, so it is differentiated. For Siena Olive Oil, the facts point to Niche marketing, so this option cannot be correct.","C":"Niche marketing targets a narrow, specialist group with a tailored offer. Siena Olive Oil focuses on premium restaurants and ignores households, so it is serving a niche.","D":"Direct marketing communicates personally with customers, often by mail or online. The scenario describes which buyer group is served, not the communication channel."}}},{"id":"P1_U3_MCQ_1850","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1850","question":"Como Silk, based in Como, Italy, sent a questionnaire to 1,250 customers and had a 64 percent response rate. How many customers returned a completed questionnaire?","options":{"A":"640","B":"750","C":"1,000","D":"800"},"correctOption":"D","correctAnswer":"800","questionType":"MCQ","explanation":{"correct_reason":"The number of returns is the number sent multiplied by the response rate. Como Silk sent 1,250 questionnaires with 64 percent returned, and 1,250 multiplied by 0.64 equals 800.","distractor_reasons":{"A":"640 would result from using a rate of about 51 percent. With 64 percent of 1,250 returned, the correct figure is 800.","B":"750 is 60 percent of 1,250, below the stated 64 percent. The actual number returned is 800. In Como Silk's case, the correct description is 800, not this choice.","C":"1,000 is 80 percent of the sample. Since only 64 percent responded, the correct count is 800. Como Silk's circumstances match 800, so this option does not fit.","D":"The number of returns is the number sent multiplied by the response rate. Como Silk sent 1,250 questionnaires with 64 percent returned, and 1,250 multiplied by 0.64 equals 800."}}},{"id":"P1_U3_MCQ_1851","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1851","question":"Bergamo Pasta, based in Bergamo, Italy, earned $140,000 revenue from its fresh pasta last month while the direct material and labour costs totalled $60,000. What was the total contribution from pasta sales?","options":{"A":"$60,000","B":"$80,000","C":"$140,000","D":"$200,000"},"correctOption":"B","correctAnswer":"$80,000","questionType":"MCQ","explanation":{"correct_reason":"Total contribution is sales revenue less the direct variable costs. Bergamo Pasta received $140,000 and spent $60,000 on materials and labour, so contribution equals $80,000.","distractor_reasons":{"A":"$60,000 is the cost figure, not the contribution. Contribution deducts costs from revenue, so the answer is $140,000 minus $60,000, which is $80,000.","B":"Total contribution is sales revenue less the direct variable costs. Bergamo Pasta received $140,000 and spent $60,000 on materials and labour, so contribution equals $80,000.","C":"$140,000 is the total revenue, not the amount left after variable costs. Subtracting the $60,000 cost leaves $80,000 of contribution. The details given about Bergamo Pasta support $80,000, so this answer is unsuitable.","D":"$200,000 adds revenue and costs together, which is not meaningful. Contribution subtracts cost from revenue, giving $80,000. For Bergamo Pasta, the facts point to $80,000, so this option cannot be correct."}}},{"id":"P1_U3_MCQ_1852","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1852","question":"Vicenza Valves, based in Vicenza, Italy, holds a 25 percent share of a national industrial-valve market worth $200 million. What value of sales does the firm make in that market?","options":{"A":"$25 million","B":"$40 million","C":"$50 million","D":"$75 million"},"correctOption":"C","correctAnswer":"$50 million","questionType":"MCQ","explanation":{"correct_reason":"Sales value is market share multiplied by total market value. Vicenza Valves has 25 percent of a $200 million market, and 0.25 multiplied by $200 million gives $50 million.","distractor_reasons":{"A":"$25 million is half the correct figure and would represent 12.5 percent of the market. A 25 percent share of $200 million is $50 million.","B":"$40 million corresponds to a 20 percent share. Since the firm holds 25 percent of $200 million, its sales are $50 million.","C":"Sales value is market share multiplied by total market value. Vicenza Valves has 25 percent of a $200 million market, and 0.25 multiplied by $200 million gives $50 million.","D":"$75 million would be 37.5 percent of the market. The stated 25 percent share gives $50 million of sales. The scenario for Vicenza Valves instead describes $50 million, which rules this alternative out."}}},{"id":"P1_U3_MCQ_1853","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1853","question":"Udine Cheese, based in Udine, Italy, sold 8,000 wheels of cheese last year at an average price of $25 per wheel. What was the total revenue from these cheese sales?","options":{"A":"$200,000","B":"$20,000","C":"$180,000","D":"$2,000,000"},"correctOption":"A","correctAnswer":"$200,000","questionType":"MCQ","explanation":{"correct_reason":"Revenue equals price multiplied by quantity. Udine Cheese sold 8,000 wheels at $25 each, and 8,000 multiplied by $25 gives $200,000 in total sales revenue.","distractor_reasons":{"A":"Revenue equals price multiplied by quantity. Udine Cheese sold 8,000 wheels at $25 each, and 8,000 multiplied by $25 gives $200,000 in total sales revenue.","B":"$20,000 is a decimal-place error, a tenth of the true revenue. Selling 8,000 wheels at $25 each yields $200,000, not $20,000.","C":"$180,000 wrongly subtracts $20,000 from the correct total. There is no deduction in the stem; revenue is simply 8,000 times $25.","D":"$2,000,000 is ten times too large and would need 80,000 wheels. Udine Cheese sold 8,000 wheels, giving $200,000. In Udine Cheese's case, the correct description is $200,000, not this choice."}}},{"id":"P1_U3_MCQ_1854","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1854","question":"Rimini Gelato, based in Rimini, Italy, runs small discussion groups asking customers to describe in words why they prefer certain ice-cream flavours. What type of data does this research mainly produce?","options":{"A":"Quantitative data","B":"Secondary data","C":"Primary numerical data","D":"Qualitative data"},"correctOption":"D","correctAnswer":"Qualitative data","questionType":"MCQ","explanation":{"correct_reason":"Qualitative data are non-numeric, expressed in words and opinions. Rimini Gelato's discussion groups collect descriptions and reasons, so the research mainly produces qualitative data.","distractor_reasons":{"A":"Quantitative data are numerical counts or measurements. The firm is gathering spoken explanations rather than numbers, so the data are not quantitative.","B":"Secondary data already exist from other sources. The discussion groups generate new information first-hand, so the data are primary, not secondary.","C":"Primary numerical data would be counts such as how many people chose a flavour. The groups produce descriptive words, so this option is wrong.","D":"Qualitative data are non-numeric, expressed in words and opinions. Rimini Gelato's discussion groups collect descriptions and reasons, so the research mainly produces qualitative data."}}},{"id":"P1_U3_MCQ_1855","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1855","question":"Brest Rainwear, based in Brest, France, wraps its jackets in recyclable waterproof packaging that prevents damage in transit and carries the company logo. Which functions of packaging does this illustrate?","options":{"A":"Protection and promotion of the product","B":"Only reducing labour costs","C":"Only legal compliance","D":"Increasing production speed"},"correctOption":"A","correctAnswer":"Protection and promotion of the product","questionType":"MCQ","explanation":{"correct_reason":"Packaging protects goods and promotes them. Brest Rainwear's wrapper prevents damage in transit and displays the logo, so it performs both a protective and a promotional function.","distractor_reasons":{"A":"Packaging protects goods and promotes them. Brest Rainwear's wrapper prevents damage in transit and displays the logo, so it performs both a protective and a promotional function.","B":"Packaging is not mainly about reducing labour costs. The recyclable wrap described protects the jackets and carries the logo, which are protection and promotion roles.","C":"Legal compliance may be one packaging concern, but the scenario highlights damage prevention and branding, not meeting regulations. Brest Rainwear's circumstances match Protection and promotion of the product, so this option does not fit.","D":"Packaging does not increase production speed. Its roles here are shielding the jackets and advertising the brand. The details given about Brest Rainwear support Protection and promotion of the product, so this answer is unsuitable."}}},{"id":"P1_U3_MCQ_1856","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1856","question":"Nantes Biscuits, based in Nantes, France, wants buyers to see its biscuits as a premium, health-conscious choice while rivals are known for cheap, sugary snacks. What is the firm trying to establish in buyers' minds?","options":{"A":"Market segmentation","B":"Market positioning","C":"Market research","D":"Market targeting"},"correctOption":"B","correctAnswer":"Market positioning","questionType":"MCQ","explanation":{"correct_reason":"Market positioning is shaping how a product is perceived relative to competitors. Nantes Biscuits aims to be seen as premium and health-conscious against rivals' cheap snacks, so it is positioning its brand.","distractor_reasons":{"A":"Market segmentation divides buyers into groups. The scenario is about the image in buyers' minds, not about dividing customers into groups.","B":"Market positioning is shaping how a product is perceived relative to competitors. Nantes Biscuits aims to be seen as premium and health-conscious against rivals' cheap snacks, so it is positioning its brand.","C":"Market research gathers information. The firm is shaping perceptions, not collecting data, so research is not the correct description. The details given about Nantes Biscuits support Market positioning, so this answer is unsuitable.","D":"Market targeting chooses which segments to serve. Nantes Biscuits is defining how it wants to be perceived, which is positioning. For Nantes Biscuits, the facts point to Market positioning, so this option cannot be correct."}}},{"id":"P1_U3_MCQ_1857","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1857","question":"Rennes Prams, based in Rennes, France, competes with several other manufacturers of baby carriages for the same buyers. What is the term for all these firms producing similar products?","options":{"A":"A market","B":"An industry","C":"A segment","D":"A channel"},"correctOption":"B","correctAnswer":"An industry","questionType":"MCQ","explanation":{"correct_reason":"An industry is the set of firms producing similar goods or services. The baby-carriage makers competing with Rennes Prams form an industry, while the buyers themselves would form a market.","distractor_reasons":{"A":"A market consists of the buyers with needs and buying power, not the competing producers. The term for the rival firms is an industry.","B":"An industry is the set of firms producing similar goods or services. The baby-carriage makers competing with Rennes Prams form an industry, while the buyers themselves would form a market.","C":"A segment is a subgroup of customers within a market. The question asks about the competing firms, not about a group of buyers.","D":"A channel is the route by which goods reach customers. The other pram makers are competitors, not a distribution route. The scenario for Rennes Prams instead describes An industry, which rules this alternative out."}}},{"id":"P1_U3_MCQ_1858","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1858","question":"Dijon Mustard, based in Dijon, France, brings eight target customers together with a moderator to discuss their reactions to three proposed jar designs. What primary research method is being used?","options":{"A":"Focus group","B":"Observation","C":"Secondary research","D":"Questionnaire"},"correctOption":"A","correctAnswer":"Focus group","questionType":"MCQ","explanation":{"correct_reason":"A focus group is a small group of people guided by a moderator to discuss their views. Dijon Mustard's eight customers discussing jar designs form a focus group.","distractor_reasons":{"A":"A focus group is a small group of people guided by a moderator to discuss their views. Dijon Mustard's eight customers discussing jar designs form a focus group.","B":"Observation records behaviour without discussion. Here customers talk about their reactions, so the method is a focus group rather than observation.","C":"Secondary research uses existing data. Bringing customers together to discuss designs creates new first-hand data, so it is primary research. The scenario for Dijon Mustard instead describes Focus group, which rules this alternative out.","D":"A questionnaire uses a set list of questions, usually completed individually. The moderated group discussion is a focus group. In Dijon Mustard's case, the correct description is Focus group, not this choice."}}},{"id":"P1_U3_MCQ_1859","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1859","question":"Grenoble Gloves, based in Grenoble, France, offers ski gloves, cycling gloves and gardening gloves under one brand name. What is the range of different products a firm offers called?","options":{"A":"Market segmentation","B":"Sales promotion","C":"Distribution channel","D":"Product mix"},"correctOption":"D","correctAnswer":"Product mix","questionType":"MCQ","explanation":{"correct_reason":"The product mix is the full range of products a business offers for sale. Grenoble Gloves sells several distinct glove types under one brand, so the range is its product mix.","distractor_reasons":{"A":"Market segmentation divides customers into groups. The scenario describes the firm's range of products, not a division of buyers. For Grenoble Gloves, the facts point to Product mix, so this option cannot be correct.","B":"Sales promotion involves short-term incentives. Offering several glove types is a product-range decision, not a promotional tactic. The scenario for Grenoble Gloves instead describes Product mix, which rules this alternative out.","C":"A distribution channel is a route to market. The different glove types are part of the product mix, not channels. In Grenoble Gloves's case, the correct description is Product mix, not this choice.","D":"The product mix is the full range of products a business offers for sale. Grenoble Gloves sells several distinct glove types under one brand, so the range is its product mix."}}},{"id":"P1_U3_MCQ_1860","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1860","question":"Montpellier Herbal Teas, based in Montpellier, France, studies last year's sales and current market trends to estimate how much tea it will sell next year. What business activity is this?","options":{"A":"Market research","B":"Sales forecasting","C":"Budgeting","D":"Target marketing"},"correctOption":"B","correctAnswer":"Sales forecasting","questionType":"MCQ","explanation":{"correct_reason":"Sales forecasting estimates future sales using past data and trends. Montpellier Herbal Teas uses last year's sales and current trends to predict next year's volume, so this is sales forecasting.","distractor_reasons":{"A":"Market research gathers information about customers and markets. Using existing figures to predict future sales is forecasting, not the collection of new data.","B":"Sales forecasting estimates future sales using past data and trends. Montpellier Herbal Teas uses last year's sales and current trends to predict next year's volume, so this is sales forecasting.","C":"Budgeting allocates financial resources. The scenario describes predicting sales volume, which is a forecast rather than a budget. The details given about Montpellier Herbal Teas support Sales forecasting, so this answer is unsuitable.","D":"Target marketing selects customer groups to serve. Estimating future sales is forecasting, not choosing segments. For Montpellier Herbal Teas, the facts point to Sales forecasting, so this option cannot be correct."}}},{"id":"P1_U3_MCQ_1861","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1861","question":"Toulouse Model Kits, based in Toulouse, France, sells plastic aircraft kits directly to hobbyists who buy them for their own leisure. What type of market is the firm supplying?","options":{"A":"Consumer market","B":"Organisational market","C":"Industrial market","D":"Wholesale market"},"correctOption":"A","correctAnswer":"Consumer market","questionType":"MCQ","explanation":{"correct_reason":"A consumer market consists of individuals buying goods for personal use. Toulouse Model Kits sells to hobbyists for their own leisure, so it operates in the consumer market.","distractor_reasons":{"A":"A consumer market consists of individuals buying goods for personal use. Toulouse Model Kits sells to hobbyists for their own leisure, so it operates in the consumer market.","B":"An organisational market involves businesses or institutions buying for resale or use. The buyers here are individuals pursuing a hobby, not organisations.","C":"An industrial market involves purchases of goods for production. Model kits bought for leisure are consumer goods, not industrial purchases. For Toulouse Model Kits, the facts point to Consumer market, so this option cannot be correct.","D":"A wholesale market involves bulk sales to intermediaries. Selling kits directly to individual hobbyists is retailing to consumers. The scenario for Toulouse Model Kits instead describes Consumer market, which rules this alternative out."}}},{"id":"P1_U3_MCQ_1862","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1862","question":"Nice Perfumes, based in Nice, France, selects 500 names at random from its list of 5,000 customers. What is the main advantage of choosing the sample in this way?","options":{"A":"It guarantees correct answers","B":"It is the cheapest method","C":"It gives every customer an equal chance and tends to be representative","D":"It produces qualitative data only"},"correctOption":"C","correctAnswer":"It gives every customer an equal chance and tends to be representative","questionType":"MCQ","explanation":{"correct_reason":"Random sampling gives every member of the population an equal chance of selection, which helps make the sample representative. Nice Perfumes' random draw of 500 from 5,000 customers has that advantage.","distractor_reasons":{"A":"Random sampling does not guarantee correct answers; responses can still be inaccurate. Its advantage is representativeness, not certainty of accuracy. The details given about Nice Perfumes support It gives every customer an equal chance and tends to be representative, so this answer is unsuitable.","B":"Random sampling is not necessarily the cheapest method. The key benefit is that each customer has an equal chance of being chosen.","C":"Random sampling gives every member of the population an equal chance of selection, which helps make the sample representative. Nice Perfumes' random draw of 500 from 5,000 customers has that advantage.","D":"Random sampling can produce numerical data from a survey; it is not limited to qualitative information. The advantage concerns representativeness. In Nice Perfumes's case, the correct description is It gives every customer an equal chance and tends to be representative, not this choice."}}},{"id":"P1_U3_MCQ_1863","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1863","question":"Marseille Soap, based in Marseille, France, launches a new luxury soap at a high price and plans to lower it gradually once eager early buyers have purchased. Which pricing method is this?","options":{"A":"Penetration pricing","B":"Loss leader","C":"Cost-plus pricing","D":"Price skimming"},"correctOption":"D","correctAnswer":"Price skimming","questionType":"MCQ","explanation":{"correct_reason":"Price skimming sets a high initial price to capture willing buyers before reducing it later. Marseille Soap's high launch price followed by gradual reductions is skimming.","distractor_reasons":{"A":"Penetration pricing sets a low price to win share quickly. The soap is launched high, so this is the opposite approach.","B":"A loss leader sells below cost to attract customers. The luxury soap is priced high, not below cost. The scenario for Marseille Soap instead describes Price skimming, which rules this alternative out.","C":"Cost-plus pricing adds a mark-up to costs. The scenario emphasises a high launch price and later reductions, which is skimming. In Marseille Soap's case, the correct description is Price skimming, not this choice.","D":"Price skimming sets a high initial price to capture willing buyers before reducing it later. Marseille Soap's high launch price followed by gradual reductions is skimming."}}},{"id":"P1_U3_MCQ_1864","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1864","question":"Tours Chocolate, based in Tours, France, monitors its share of the national chocolate market each quarter to judge how well it is doing against competitors. Why is market share useful to the firm?","options":{"A":"It shows how well the firm is performing relative to competitors","B":"It shows legal compliance","C":"It measures production speed","D":"It calculates tax"},"correctOption":"A","correctAnswer":"It shows how well the firm is performing relative to competitors","questionType":"MCQ","explanation":{"correct_reason":"Market share shows a firm's sales relative to the whole market and its rivals. Tours Chocolate uses its share each quarter as a measure of competitive performance.","distractor_reasons":{"A":"Market share shows a firm's sales relative to the whole market and its rivals. Tours Chocolate uses its share each quarter as a measure of competitive performance.","B":"Market share has nothing to do with legal compliance. It is a commercial measure of performance relative to competitors. In Tours Chocolate's case, the correct description is It shows how well the firm is performing relative to competitors, not this choice.","C":"Production speed is an operations measure, not a market measure. Share indicates how much of the market the firm captures. Tours Chocolate's circumstances match It shows how well the firm is performing relative to competitors, so this option does not fit.","D":"Tax calculation relies on profits and rates, not market share. The firm uses share to assess competitive standing. The details given about Tours Chocolate support It shows how well the firm is performing relative to competitors, so this answer is unsuitable."}}},{"id":"P1_U3_MCQ_1865","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1865","question":"Orleans Pottery, based in Orleans, France, groups its customers into occasional buyers, regular buyers and loyal repeat purchasers, then offers each group different incentives. Which basis of segmentation is this?","options":{"A":"Geographic","B":"Behavioural","C":"Demographic","D":"Psychographic"},"correctOption":"B","correctAnswer":"Behavioural","questionType":"MCQ","explanation":{"correct_reason":"Behavioural segmentation groups buyers by their buying habits or usage. Orleans Pottery classifies customers by purchase frequency and loyalty, so it is using behavioural segmentation.","distractor_reasons":{"A":"Geographic segmentation groups buyers by location. The categories of occasional, regular and loyal relate to buying behaviour, not place. In Orleans Pottery's case, the correct description is Behavioural, not this choice.","B":"Behavioural segmentation groups buyers by their buying habits or usage. Orleans Pottery classifies customers by purchase frequency and loyalty, so it is using behavioural segmentation.","C":"Demographic segmentation uses age, income or occupation. Purchase frequency is a behaviour, not a demographic characteristic. The details given about Orleans Pottery support Behavioural, so this answer is unsuitable.","D":"Psychographic segmentation uses lifestyle and values. Buying frequency is an observable behaviour, so behavioural is the correct basis. For Orleans Pottery, the facts point to Behavioural, so this option cannot be correct."}}},{"id":"P1_U3_MCQ_1866","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1866","question":"Rouen Candles, based in Rouen, France, surveyed 1,800 customers and found that 45 percent preferred a lavender scent. How many of those surveyed chose lavender?","options":{"A":"720","B":"800","C":"810","D":"900"},"correctOption":"C","correctAnswer":"810","questionType":"MCQ","explanation":{"correct_reason":"The count is the survey total multiplied by the percentage. Rouen Candles surveyed 1,800 customers and 45 percent chose lavender, and 1,800 multiplied by 0.45 equals 810.","distractor_reasons":{"A":"720 is 40 percent of 1,800, below the reported 45 percent. Multiplying 1,800 by 0.45 gives 810 customers. Rouen Candles's circumstances match 810, so this option does not fit.","B":"800 is close but not exact; 45 percent of 1,800 is 810. The correct count is 810. The details given about Rouen Candles support 810, so this answer is unsuitable.","C":"The count is the survey total multiplied by the percentage. Rouen Candles surveyed 1,800 customers and 45 percent chose lavender, and 1,800 multiplied by 0.45 equals 810.","D":"900 is 50 percent of the sample. Since only 45 percent preferred lavender, the correct figure is 810. The scenario for Rouen Candles instead describes 810, which rules this alternative out."}}},{"id":"P1_U3_MCQ_1867","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1867","question":"Caen Seafood, based in Caen, France, buys and prepares a seafood platter for $16 and adds a mark-up of 25 percent on cost. What is the selling price of the platter?","options":{"A":"$20","B":"$16","C":"$12","D":"$25"},"correctOption":"A","correctAnswer":"$20","questionType":"MCQ","explanation":{"correct_reason":"A 25 percent mark-up on the $16 cost adds $4, because 16 multiplied by 0.25 is 4. Adding $4 to $16 gives a selling price of $20.","distractor_reasons":{"A":"A 25 percent mark-up on the $16 cost adds $4, because 16 multiplied by 0.25 is 4. Adding $4 to $16 gives a selling price of $20.","B":"$16 is the cost price before any mark-up. Adding 25 percent of $16, which is $4, gives the $20 selling price.","C":"$12 would be a 25 percent discount on the cost, not a mark-up. The price must be above cost, so it is $20.","D":"$25 mistakes the percentage figure for a price. The correct price is cost plus 25 percent, which is $20. In Caen Seafood's case, the correct description is $20, not this choice."}}},{"id":"P1_U3_MCQ_1868","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1868","question":"Cherbourg Rope, based in Cherbourg, France, increased its sales from $20 million to $24 million while the total market remained at $200 million. By how many percentage points did its market share rise?","options":{"A":"1 percentage point","B":"4 percentage points","C":"20 percentage points","D":"2 percentage points"},"correctOption":"D","correctAnswer":"2 percentage points","questionType":"MCQ","explanation":{"correct_reason":"Share was $20m over $200m, which is 10 percent, and became $24m over $200m, which is 12 percent. The share therefore rose by 2 percentage points.","distractor_reasons":{"A":"1 percentage point is too small; the share moved from 10 to 12 percent. The increase is 2 percentage points. For Cherbourg Rope, the facts point to 2 percentage points, so this option cannot be correct.","B":"4 percentage points would require the share to reach 14 percent. Sales of $24 million in a $200 million market give 12 percent.","C":"20 is the original percentage, not the change. The share rose from 10 percent to 12 percent, a rise of 2 points.","D":"Share was $20m over $200m, which is 10 percent, and became $24m over $200m, which is 12 percent. The share therefore rose by 2 percentage points."}}},{"id":"P1_U3_MCQ_1869","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1869","question":"Lorient Sailing, based in Lorient, France, aims to achieve an 8 percent share of the national sailing-equipment market, which is worth $150 million. What sales revenue must the firm reach?","options":{"A":"$10 million","B":"$12 million","C":"$15 million","D":"$18 million"},"correctOption":"B","correctAnswer":"$12 million","questionType":"MCQ","explanation":{"correct_reason":"Target revenue is the desired share multiplied by total market value. Lorient Sailing wants 8 percent of a $150 million market, and 0.08 multiplied by $150 million equals $12 million.","distractor_reasons":{"A":"$10 million is about 6.7 percent of the market. An 8 percent share of $150 million requires $12 million of sales.","B":"Target revenue is the desired share multiplied by total market value. Lorient Sailing wants 8 percent of a $150 million market, and 0.08 multiplied by $150 million equals $12 million.","C":"$15 million is 10 percent of the market. The 8 percent target corresponds to $12 million. Lorient Sailing's circumstances match $12 million, so this option does not fit.","D":"$18 million is 12 percent of $150 million. The correct target revenue is $12 million. The details given about Lorient Sailing support $12 million, so this answer is unsuitable."}}},{"id":"P1_U3_MCQ_1870","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1870","question":"Vannes Oysters, based in Vannes, France, reads a rival's published annual report to learn about that competitor's sales. What sort of research source is the annual report?","options":{"A":"Primary internal data","B":"Primary external data","C":"Secondary external data","D":"Secondary internal data"},"correctOption":"C","correctAnswer":"Secondary external data","questionType":"MCQ","explanation":{"correct_reason":"Secondary data already exist and come from outside the firm when published by another organisation. The rival's annual report was produced by someone else, so it is a secondary external source.","distractor_reasons":{"A":"Primary internal data would be collected first-hand inside the firm, such as its own sales records. The rival's report is neither first-hand nor internal.","B":"Primary external data would be gathered directly from outside people by the firm itself. Reading an existing report is not first-hand collection.","C":"Secondary data already exist and come from outside the firm when published by another organisation. The rival's annual report was produced by someone else, so it is a secondary external source.","D":"Secondary internal data are existing records within the firm. A rival's published report originates outside the business, so it is external."}}},{"id":"P1_U3_MCQ_1871","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1871","question":"Angers Slates, based in Angers, France, sponsors local community festivals and issues positive news stories about its involvement to build goodwill. Which element of the promotion mix is this?","options":{"A":"Public relations","B":"Sales promotion","C":"Personal selling","D":"Direct marketing"},"correctOption":"A","correctAnswer":"Public relations","questionType":"MCQ","explanation":{"correct_reason":"Public relations builds goodwill and a favourable image through unpaid communication. Angers Slates sponsors events and shares news stories to improve its standing, so this is public relations.","distractor_reasons":{"A":"Public relations builds goodwill and a favourable image through unpaid communication. Angers Slates sponsors events and shares news stories to improve its standing, so this is public relations.","B":"Sales promotion uses short-term incentives like discounts to boost sales. Sponsorship and news stories aim at goodwill, not immediate sales. For Angers Slates, the facts point to Public relations, so this option cannot be correct.","C":"Personal selling is face-to-face selling to individual buyers. Sponsoring festivals is not a one-to-one selling activity. The scenario for Angers Slates instead describes Public relations, which rules this alternative out.","D":"Direct marketing targets named individuals with a direct message. Community sponsorship is aimed at the wider public, not individual recipients. In Angers Slates's case, the correct description is Public relations, not this choice."}}},{"id":"P1_U3_MCQ_1872","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1872","question":"Poitiers Brushes, based in Poitiers, France, tracks how fast the overall market for painting brushes is expanding. Why is monitoring market growth useful to the firm?","options":{"A":"To predict competitor prices","B":"To identify opportunities and threats in the market","C":"To calculate tax","D":"To set legal standards"},"correctOption":"B","correctAnswer":"To identify opportunities and threats in the market","questionType":"MCQ","explanation":{"correct_reason":"Market growth reveals whether demand is expanding or shrinking, helping a firm spot opportunities and threats. Poitiers Brushes watches the brush market's growth to inform its plans.","distractor_reasons":{"A":"Market growth does not directly reveal competitors' prices. Prices must be researched separately; growth shows the direction of demand. For Poitiers Brushes, the facts point to To identify opportunities and threats in the market, so this option cannot be correct.","B":"Market growth reveals whether demand is expanding or shrinking, helping a firm spot opportunities and threats. Poitiers Brushes watches the brush market's growth to inform its plans.","C":"Tax depends on profits and rates, not on market growth. Growth information guides strategy rather than tax calculations. In Poitiers Brushes's case, the correct description is To identify opportunities and threats in the market, not this choice.","D":"Legal standards are set by regulators, not inferred from market growth. Growth data help with commercial planning. Poitiers Brushes's circumstances match To identify opportunities and threats in the market, so this option does not fit."}}},{"id":"P1_U3_MCQ_1873","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1873","question":"Limoges Porcelain, based in Limoges, France, replaces broken items quickly and helpfully, and many customers return to buy again. What does this after-sales service help the firm build?","options":{"A":"Higher production costs only","B":"Legal compliance","C":"Market segmentation","D":"Customer loyalty and repeat custom"},"correctOption":"D","correctAnswer":"Customer loyalty and repeat custom","questionType":"MCQ","explanation":{"correct_reason":"Good after-sales service encourages satisfaction and repeat buying, building customer loyalty. Limoges Porcelain's prompt replacements lead customers to return, so the service fosters loyalty.","distractor_reasons":{"A":"After-sales service may cost money, but its purpose is not simply to raise costs. It helps retain customers and encourage repeat purchases.","B":"Legal compliance is not the main point here. The scenario shows service creating willing repeat buyers, not meeting a legal rule.","C":"Market segmentation divides buyers into groups. The after-sales service is the same for all and builds loyalty rather than dividing customers.","D":"Good after-sales service encourages satisfaction and repeat buying, building customer loyalty. Limoges Porcelain's prompt replacements lead customers to return, so the service fosters loyalty."}}},{"id":"P1_U3_MCQ_1874","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1874","question":"Bourges Tools, based in Bourges, France, uses a questionnaire with closed answers such as yes, no and a rating from one to five. What is the main advantage of such closed questions?","options":{"A":"Easy to tally and compare numerically","B":"Gives rich descriptive detail","C":"Avoids all bias","D":"Removes need for a sample"},"correctOption":"A","correctAnswer":"Easy to tally and compare numerically","questionType":"MCQ","explanation":{"correct_reason":"Closed questions produce fixed responses that are easy to count and compare. Bourges Tools' yes/no and rating answers can be tallied quickly and analysed numerically.","distractor_reasons":{"A":"Closed questions produce fixed responses that are easy to count and compare. Bourges Tools' yes/no and rating answers can be tallied quickly and analysed numerically.","B":"Rich descriptive detail comes from open questions. Closed answers restrict respondents to set options, so they do not provide detailed explanations.","C":"Closed questions do not eliminate all bias; wording can still lead respondents. Their advantage is ease of analysis, not freedom from bias.","D":"A sample is still needed even with closed questions. The responses must come from a chosen group of respondents. For Bourges Tools, the facts point to Easy to tally and compare numerically, so this option cannot be correct."}}},{"id":"P1_U3_MCQ_1875","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1875","question":"Nevers Faience, based in Nevers, France, sells large consignments of pottery to wholesalers, which then split them into smaller lots for village shops. What is the role of the wholesaler in this channel?","options":{"A":"Manufacture the product","B":"Set retail prices by law","C":"Break bulk and distribute to retailers","D":"Advertise nationally"},"correctOption":"C","correctAnswer":"Break bulk and distribute to retailers","questionType":"MCQ","explanation":{"correct_reason":"Wholesalers buy in bulk and break it into smaller quantities for retailers. Nevers Faience sells large consignments and the wholesalers divide them for village shops, which is bulk-breaking.","distractor_reasons":{"A":"Wholesalers do not manufacture the goods; Nevers Faience makes the pottery. The wholesaler's role is distributing existing products. Nevers Faience's circumstances match Break bulk and distribute to retailers, so this option does not fit.","B":"Wholesalers do not set retail prices by law. They buy and resell in smaller quantities; pricing is a separate decision. The details given about Nevers Faience support Break bulk and distribute to retailers, so this answer is unsuitable.","C":"Wholesalers buy in bulk and break it into smaller quantities for retailers. Nevers Faience sells large consignments and the wholesalers divide them for village shops, which is bulk-breaking.","D":"National advertising is a promotion activity, not the wholesaler's function. The role here is breaking bulk and supplying shops. The scenario for Nevers Faience instead describes Break bulk and distribute to retailers, which rules this alternative out."}}},{"id":"P1_U3_MCQ_1876","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1876","question":"Auxerre Cider, based in Auxerre, France, decides to focus its marketing on young adults living in cities, having identified several possible customer groups. What is this choice called?","options":{"A":"Market segmentation","B":"Market targeting","C":"Market research","D":"Market positioning"},"correctOption":"B","correctAnswer":"Market targeting","questionType":"MCQ","explanation":{"correct_reason":"Market targeting is selecting which identified segments to serve. Auxerre Cider has identified groups and chooses young urban adults, so it is making a targeting decision.","distractor_reasons":{"A":"Market segmentation is dividing buyers into groups, which happened earlier. The decision described is choosing which group to serve, so it is targeting.","B":"Market targeting is selecting which identified segments to serve. Auxerre Cider has identified groups and chooses young urban adults, so it is making a targeting decision.","C":"Market research gathers information to find segments. The firm is selecting a segment, not collecting data, so research is not the answer.","D":"Market positioning shapes perception relative to rivals. Choosing young urban adults as the focus is targeting, not positioning. In Auxerre Cider's case, the correct description is Market targeting, not this choice."}}},{"id":"P1_U3_MCQ_1877","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1877","question":"Troyes Hosiery, based in Troyes, France, offers one basic range of socks and promotes it in the same way to all households across the country. Which market approach does this represent?","options":{"A":"Mass marketing","B":"Niche marketing","C":"Relationship marketing","D":"Differentiated marketing"},"correctOption":"A","correctAnswer":"Mass marketing","questionType":"MCQ","explanation":{"correct_reason":"Mass marketing uses a single offer aimed at the whole market. Troyes Hosiery sells one sock range with identical promotion to all households, so it is mass marketing.","distractor_reasons":{"A":"Mass marketing uses a single offer aimed at the whole market. Troyes Hosiery sells one sock range with identical promotion to all households, so it is mass marketing.","B":"Niche marketing focuses on a narrow specialist group. Offering one product to all households is the opposite of a niche strategy.","C":"Relationship marketing builds long-term individual ties. Standardised national promotion is not personal relationship building. In Troyes Hosiery's case, the correct description is Mass marketing, not this choice.","D":"Differentiated marketing tailors offers to several segments. Troyes Hosiery uses one undifferentiated offer, so it is not differentiated marketing. Troyes Hosiery's circumstances match Mass marketing, so this option does not fit."}}},{"id":"P1_U3_MCQ_1878","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1878","question":"Reims Sparkling Wine, based in Reims, France, organises its own tasting sessions and records participants' opinions for a new blend. What kind of data is the firm collecting?","options":{"A":"Secondary data","B":"Desk research","C":"Published statistics","D":"Primary data"},"correctOption":"D","correctAnswer":"Primary data","questionType":"MCQ","explanation":{"correct_reason":"Primary data are collected first-hand by the business for its own purpose. Reims Sparkling Wine gathers fresh opinions from its own tasting sessions, so the data are primary.","distractor_reasons":{"A":"Secondary data already exist from other sources. The tasting sessions create new information first-hand, so the data are not secondary. The scenario for Reims Sparkling Wine instead describes Primary data, which rules this alternative out.","B":"Desk research uses existing published material. Organising live tasting sessions is field research, so desk research is not correct. In Reims Sparkling Wine's case, the correct description is Primary data, not this choice.","C":"Published statistics are secondary sources. The firm's own sessions produce original data, so this option is wrong. Reims Sparkling Wine's circumstances match Primary data, so this option does not fit.","D":"Primary data are collected first-hand by the business for its own purpose. Reims Sparkling Wine gathers fresh opinions from its own tasting sessions, so the data are primary."}}},{"id":"P1_U3_MCQ_1879","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1879","question":"Metz Lace, based in Metz, France, has seen sales of its tablecloths level off at a high level, with many rivals and little room for further growth. Which stage of the product life cycle is this?","options":{"A":"Introduction","B":"Growth","C":"Maturity","D":"Decline"},"correctOption":"C","correctAnswer":"Maturity","questionType":"MCQ","explanation":{"correct_reason":"Maturity is reached when sales plateau after strong growth and competition is intense. Metz Lace's flat high sales and many rivals indicate the maturity stage.","distractor_reasons":{"A":"Introduction involves low sales and high promotion after launch. Sales are high and stable here, so the product is not new.","B":"Growth features rapidly rising sales. Metz Lace's sales have levelled off, so growth has ended. Metz Lace's circumstances match Maturity, so this option does not fit.","C":"Maturity is reached when sales plateau after strong growth and competition is intense. Metz Lace's flat high sales and many rivals indicate the maturity stage.","D":"Decline means falling sales. The sales are steady at a high level, so the product is not yet declining. For Metz Lace, the facts point to Maturity, so this option cannot be correct."}}},{"id":"P1_U3_MCQ_1880","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1880","question":"Nancy Marzipan, based in Nancy, France, uses a secret family recipe and elegant packaging that competitors cannot match, allowing a premium price. Which competitive strategy is the firm following?","options":{"A":"Differentiation","B":"Cost leadership","C":"Mass marketing","D":"Market development"},"correctOption":"A","correctAnswer":"Differentiation","questionType":"MCQ","explanation":{"correct_reason":"Differentiation means offering something distinctive that buyers value, allowing a premium price. Nancy Marzipan's unique recipe and packaging set it apart, so it is differentiating.","distractor_reasons":{"A":"Differentiation means offering something distinctive that buyers value, allowing a premium price. Nancy Marzipan's unique recipe and packaging set it apart, so it is differentiating.","B":"Cost leadership means being the lowest-cost producer. Nancy Marzipan uses premium ingredients and packaging, not low costs, so it is not a cost leader.","C":"Mass marketing targets the whole market with one offer. The scenario describes a distinctive product, not the breadth of the market.","D":"Market development means entering new markets with existing products. The firm is differentiating its product, not entering new markets. In Nancy Marzipan's case, the correct description is Differentiation, not this choice."}}},{"id":"P1_U3_MCQ_1881","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1881","question":"Strasbourg Pastries, based in Strasbourg, France, hears customers ask for a low-sugar croissant. The deeper need is an enjoyable breakfast without excess sugar. What is the specific request for a low-sugar product called?","options":{"A":"Basic need","B":"Necessity","C":"Market demand","D":"Want"},"correctOption":"D","correctAnswer":"Want","questionType":"MCQ","explanation":{"correct_reason":"A want is a specific form that a need takes. Customers need a pleasant, lighter breakfast, and asking for a low-sugar croissant expresses that need as a want.","distractor_reasons":{"A":"A basic need would be something like hunger or nourishment. The low-sugar croissant is a particular way of meeting that need, so it is a want.","B":"A necessity is essential. A low-sugar croissant is a preference rather than something essential, so it is not a necessity. The scenario for Strasbourg Pastries instead describes Want, which rules this alternative out.","C":"Market demand is the total quantity buyers are willing to purchase. A specific product request is a want, not the overall demand.","D":"A want is a specific form that a need takes. Customers need a pleasant, lighter breakfast, and asking for a low-sugar croissant expresses that need as a want."}}},{"id":"P1_U3_MCQ_1882","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1882","question":"Mulhouse Cotton, based in Mulhouse, France, surveyed 3,200 shoppers and found that 37.5 percent had bought clothing online in the past month. How many of those surveyed had made an online purchase?","options":{"A":"1,000","B":"1,200","C":"1,500","D":"1,600"},"correctOption":"B","correctAnswer":"1,200","questionType":"MCQ","explanation":{"correct_reason":"The count equals the sample size multiplied by the percentage. Mulhouse Cotton surveyed 3,200 shoppers and 37.5 percent bought online, and 3,200 multiplied by 0.375 equals 1,200.","distractor_reasons":{"A":"1,000 is about 31 percent of the sample. The stated 37.5 percent of 3,200 gives 1,200 shoppers. The scenario for Mulhouse Cotton instead describes 1,200, which rules this alternative out.","B":"The count equals the sample size multiplied by the percentage. Mulhouse Cotton surveyed 3,200 shoppers and 37.5 percent bought online, and 3,200 multiplied by 0.375 equals 1,200.","C":"1,500 is roughly 47 percent of 3,200. With 37.5 percent buying online, the correct figure is 1,200. Mulhouse Cotton's circumstances match 1,200, so this option does not fit.","D":"1,600 is 50 percent of the sample. Since only 37.5 percent purchased online, the answer is 1,200. The details given about Mulhouse Cotton support 1,200, so this answer is unsuitable."}}},{"id":"P1_U3_MCQ_1883","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1883","question":"Colmar Wines, based in Colmar, France, sold 5,000 bottles at $14 each. Each bottle cost the firm $8 to produce. What was the total profit from these bottle sales?","options":{"A":"$40,000","B":"$70,000","C":"$30,000","D":"$50,000"},"correctOption":"C","correctAnswer":"$30,000","questionType":"MCQ","explanation":{"correct_reason":"Profit is total revenue minus total cost. Colmar Wines earned 5,000 times $14, which is $70,000, and spent 5,000 times $8, which is $40,000, leaving $30,000 profit.","distractor_reasons":{"A":"$40,000 is the total production cost, not the profit. Subtracting cost from the $70,000 revenue leaves $30,000. In Colmar Wines's case, the correct description is $30,000, not this choice.","B":"$70,000 is the sales revenue, not the amount left after costs. Deducting $40,000 of costs gives $30,000 profit. Colmar Wines's circumstances match $30,000, so this option does not fit.","C":"Profit is total revenue minus total cost. Colmar Wines earned 5,000 times $14, which is $70,000, and spent 5,000 times $8, which is $40,000, leaving $30,000 profit.","D":"$50,000 does not follow from the figures. Revenue of $70,000 minus costs of $40,000 equals $30,000. For Colmar Wines, the facts point to $30,000, so this option cannot be correct."}}},{"id":"P1_U3_MCQ_1884","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1884","question":"Besancon Watches, based in Besancon, France, sold 24,000 watches last year. Total watch sales in its market were 160,000 units over the same period. What was its market share by volume?","options":{"A":"15%","B":"24%","C":"12%","D":"20%"},"correctOption":"A","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Market share by volume is the firm's unit sales divided by total units sold, multiplied by 100. Besancon Watches sold 24,000 of 160,000 watches, and 24,000 divided by 160,000 is 15 percent.","distractor_reasons":{"A":"Market share by volume is the firm's unit sales divided by total units sold, multiplied by 100. Besancon Watches sold 24,000 of 160,000 watches, and 24,000 divided by 160,000 is 15 percent.","B":"24 percent mistakes the 24,000 sales figure for a percentage. Dividing 24,000 by 160,000 gives 15 percent. The details given about Besancon Watches support 15%, so this answer is unsuitable.","C":"12 percent would mean only 19,200 watches sold. The firm actually sold 24,000, giving a 15 percent share. For Besancon Watches, the facts point to 15%, so this option cannot be correct.","D":"20 percent corresponds to 32,000 watches in a 160,000-unit market. With 24,000 sold, the share is 15 percent. The scenario for Besancon Watches instead describes 15%, which rules this alternative out."}}},{"id":"P1_U3_MCQ_1885","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1885","question":"Chalon Saddlery, based in Chalon, France, has 600 regular customers who generated $480,000 in revenue last year. The owner wants the average spend per customer. What was the average revenue per customer?","options":{"A":"$600","B":"$700","C":"$850","D":"$800"},"correctOption":"D","correctAnswer":"$800","questionType":"MCQ","explanation":{"correct_reason":"Average revenue per customer is total revenue divided by the number of customers. Chalon Saddlery earned $480,000 from 600 customers, and $480,000 divided by 600 equals $800.","distractor_reasons":{"A":"$600 mistakes the customer count for an average. Dividing $480,000 by 600 customers gives $800 per customer. The details given about Chalon Saddlery support $800, so this answer is unsuitable.","B":"$700 would produce only $420,000 from 600 customers. The actual revenue was $480,000, so the average is $800. For Chalon Saddlery, the facts point to $800, so this option cannot be correct.","C":"$850 would give $510,000 in total. With $480,000 earned from 600 customers, the correct average is $800. The scenario for Chalon Saddlery instead describes $800, which rules this alternative out.","D":"Average revenue per customer is total revenue divided by the number of customers. Chalon Saddlery earned $480,000 from 600 customers, and $480,000 divided by 600 equals $800."}}},{"id":"P1_U3_MCQ_1886","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1886","question":"Macon Vineyards, based in Macon, France, plans to use government figures on grape production but discovers they are two years old. What is the key disadvantage of secondary data illustrated here?","options":{"A":"It is always expensive","B":"It is collected first-hand","C":"It may be out of date for current decisions","D":"It cannot be used at all"},"correctOption":"C","correctAnswer":"It may be out of date for current decisions","questionType":"MCQ","explanation":{"correct_reason":"Secondary data were collected earlier for another purpose and can become outdated. Macon Vineyards' two-year-old figures may not reflect current conditions, showing this disadvantage.","distractor_reasons":{"A":"Secondary data are not always expensive; many are free. The problem here is age, not cost. For Macon Vineyards, the facts point to It may be out of date for current decisions, so this option cannot be correct.","B":"Data collected first-hand would be primary. Government figures are secondary, so being first-hand is not the issue. The scenario for Macon Vineyards instead describes It may be out of date for current decisions, which rules this alternative out.","C":"Secondary data were collected earlier for another purpose and can become outdated. Macon Vineyards' two-year-old figures may not reflect current conditions, showing this disadvantage.","D":"Secondary data can still be useful and are widely used. The issue is that old figures may be less relevant, not unusable."}}},{"id":"P1_U3_MCQ_1887","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1887","question":"Annecy Backpacks, based in Annecy, France, sells one popular rucksack below its cost to attract shoppers into the shop, hoping they will buy higher-margin accessories. Which pricing method is this?","options":{"A":"Price skimming","B":"Loss leader","C":"Penetration pricing","D":"Cost-plus pricing"},"correctOption":"B","correctAnswer":"Loss leader","questionType":"MCQ","explanation":{"correct_reason":"A loss leader is sold below cost to attract customers who then buy other profitable items. Annecy Backpacks' below-cost rucksack draws shoppers in, so it is a loss leader.","distractor_reasons":{"A":"Price skimming charges a high price initially. The rucksack is priced below cost, so it is not skimming. The scenario for Annecy Backpacks instead describes Loss leader, which rules this alternative out.","B":"A loss leader is sold below cost to attract customers who then buy other profitable items. Annecy Backpacks' below-cost rucksack draws shoppers in, so it is a loss leader.","C":"Penetration pricing sets a low price to gain share across a product range. Selling one item below cost to draw people in is a loss leader.","D":"Cost-plus pricing adds a mark-up to costs. A below-cost price cannot be cost-plus. The details given about Annecy Backpacks support Loss leader, so this answer is unsuitable."}}},{"id":"P1_U3_MCQ_1888","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1888","question":"Szczecin Ship Supplies, based in Szczecin, Poland, cut prices sharply to win market share, but its profit per sale fell and total profit declined. What does this illustrate?","options":{"A":"Market share always rises","B":"Discounts have no effect","C":"Costs automatically fall","D":"Pursuing share through heavy discounts can reduce profitability"},"correctOption":"D","correctAnswer":"Pursuing share through heavy discounts can reduce profitability","questionType":"MCQ","explanation":{"correct_reason":"Heavy discounting can raise share while cutting margins enough to reduce total profit. Szczecin Ship Supplies won volume but saw profit fall, illustrating the trade-off between share and profitability.","distractor_reasons":{"A":"Market share did not fail to rise; the problem is that profit fell. The scenario shows a cost of chasing share, not a failure to gain it.","B":"Discounts clearly affected both sales and profit, so saying they have no effect is wrong. Szczecin Ship's circumstances match Pursuing share through heavy discounts can reduce profitability, so this option does not fit.","C":"Costs do not automatically fall when prices are cut. Here lower prices reduced profit per sale, so costs were not the saving.","D":"Heavy discounting can raise share while cutting margins enough to reduce total profit. Szczecin Ship Supplies won volume but saw profit fall, illustrating the trade-off between share and profitability."}}},{"id":"P1_U3_MCQ_1889","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1889","question":"Poznan Scooters, based in Poznan, Poland, believes that heavy advertising and persuasive selling will shift whatever it produces, without first checking what buyers want. Which orientation does this reflect?","options":{"A":"Sales orientation","B":"Market orientation","C":"Product orientation","D":"Production orientation"},"correctOption":"A","correctAnswer":"Sales orientation","questionType":"MCQ","explanation":{"correct_reason":"A sales orientation assumes that aggressive selling will move products, rather than starting from customer needs. Poznan Scooters relies on persuasive selling, so it has a sales orientation.","distractor_reasons":{"A":"A sales orientation assumes that aggressive selling will move products, rather than starting from customer needs. Poznan Scooters relies on persuasive selling, so it has a sales orientation.","B":"A market orientation begins with customer needs. Poznan Scooters ignores those needs and relies on promotion, so it is not market-oriented.","C":"A product orientation focuses on making a superior product. The firm is focused on selling, not on product excellence. For Poznan Scooters, the facts point to Sales orientation, so this option cannot be correct.","D":"A production orientation emphasises efficient output. The scenario emphasises selling effort rather than production efficiency. The scenario for Poznan Scooters instead describes Sales orientation, which rules this alternative out."}}},{"id":"P1_U3_MCQ_1890","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1890","question":"Wroclaw Containers, based in Wroclaw, Poland, ensures its survey includes exactly 100 people from each of three age groups, filling set targets. Which sampling method is being used?","options":{"A":"Random sampling","B":"Observation","C":"Quota sampling","D":"Secondary research"},"correctOption":"C","correctAnswer":"Quota sampling","questionType":"MCQ","explanation":{"correct_reason":"Quota sampling sets fixed numbers for categories of people and fills those quotas. Wroclaw Containers requires exactly 100 from each age group, so it is using quota sampling.","distractor_reasons":{"A":"Random sampling gives every person an equal chance without set group targets. The fixed age-group targets here indicate quota sampling. For Wroclaw Containers, the facts point to Quota sampling, so this option cannot be correct.","B":"Observation watches behaviour without asking questions. The firm is conducting a survey with set quotas, so observation is not correct. The scenario for Wroclaw Containers instead describes Quota sampling, which rules this alternative out.","C":"Quota sampling sets fixed numbers for categories of people and fills those quotas. Wroclaw Containers requires exactly 100 from each age group, so it is using quota sampling.","D":"Secondary research uses existing data. Filling survey quotas generates new data first-hand, so it is not secondary. Wroclaw Containers's circumstances match Quota sampling, so this option does not fit."}}},{"id":"P1_U3_MCQ_1891","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1891","question":"Katowice Fasteners, based in Katowice, Poland, sends a sales representative to visit construction firms, demonstrate its bolts and answer questions face to face. Which element of promotion is this?","options":{"A":"Public relations","B":"Personal selling","C":"Sales promotion","D":"Direct marketing"},"correctOption":"B","correctAnswer":"Personal selling","questionType":"MCQ","explanation":{"correct_reason":"Personal selling involves direct face-to-face communication between a seller and a buyer. The representative's visits and demonstrations to construction firms make this personal selling.","distractor_reasons":{"A":"Public relations aims at goodwill with the wider public through unpaid communication. A sales visit to a specific buyer is personal selling.","B":"Personal selling involves direct face-to-face communication between a seller and a buyer. The representative's visits and demonstrations to construction firms make this personal selling.","C":"Sales promotion uses short-term incentives like discounts. A demonstration and discussion with a buyer is personal selling. Katowice Fasteners's circumstances match Personal selling, so this option does not fit.","D":"Direct marketing communicates with customers through post, phone or online without a face-to-face visit. The representative's visit is personal selling. The details given about Katowice Fasteners support Personal selling, so this answer is unsuitable."}}},{"id":"P1_U3_MCQ_1892","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1892","question":"Lublin Linen, based in Lublin, Poland, sets a target of raising its share of the national linen market from 6 percent to 10 percent within three years. What type of objective is this?","options":{"A":"Marketing objective","B":"Financial objective","C":"Production objective","D":"Legal objective"},"correctOption":"A","correctAnswer":"Marketing objective","questionType":"MCQ","explanation":{"correct_reason":"Objectives about market share are marketing objectives because they concern the firm's position in its market. Lublin Linen's share target is a marketing objective.","distractor_reasons":{"A":"Objectives about market share are marketing objectives because they concern the firm's position in its market. Lublin Linen's share target is a marketing objective.","B":"A financial objective would target profit, revenue or cash flow. Share of the market is a market-based goal, not a financial one.","C":"A production objective concerns output and efficiency. Increasing market share is about marketplace performance. The details given about Lublin Linen support Marketing objective, so this answer is unsuitable.","D":"A legal objective would relate to compliance. The share target is commercial, so it is a marketing objective. For Lublin Linen, the facts point to Marketing objective, so this option cannot be correct."}}},{"id":"P1_U3_MCQ_1893","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1893","question":"Bydgoszcz Tarpaulins, based in Bydgoszcz, Poland, notes that builders need covers that keep materials dry on site, and develops a heavier fabric to meet that requirement. What is the builders' requirement for dryness?","options":{"A":"A want","B":"A demand","C":"A basic need","D":"A preference"},"correctOption":"C","correctAnswer":"A basic need","questionType":"MCQ","explanation":{"correct_reason":"A basic need is a fundamental requirement such as protection from the weather. Builders needing to keep materials dry have a basic need, which the new fabric addresses.","distractor_reasons":{"A":"A want is a specific preferred way of meeting a need. Keeping materials dry is the underlying need itself, not a particular want.","B":"Demand is the quantity buyers are willing and able to purchase. The requirement for dryness is a need, not a quantity demanded.","C":"A basic need is a fundamental requirement such as protection from the weather. Builders needing to keep materials dry have a basic need, which the new fabric addresses.","D":"A preference is a like for one option over another. The need for dry materials is more fundamental than a preference."}}},{"id":"P1_U3_MCQ_1894","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1894","question":"Torun Gingerbread, based in Torun, Poland, compares the results of a customer survey with a separate set of interviews to see whether they agree. What is the firm trying to assess?","options":{"A":"The cost of the research","B":"The reliability of the findings","C":"The legal compliance","D":"The production efficiency"},"correctOption":"B","correctAnswer":"The reliability of the findings","questionType":"MCQ","explanation":{"correct_reason":"Comparing findings from different sources checks whether results are consistent and reliable. Torun Gingerbread cross-checks its survey against interviews to assess the reliability of the findings.","distractor_reasons":{"A":"Comparing results does not measure research cost. Torun Gingerbread is checking agreement between sources, not adding up expenditure. The details given about Torun Gingerbread support The reliability of the findings, so this answer is unsuitable.","B":"Comparing findings from different sources checks whether results are consistent and reliable. Torun Gingerbread cross-checks its survey against interviews to assess the reliability of the findings.","C":"Legal compliance concerns rules and regulations. The comparison of research findings is about reliability, not the law. The scenario for Torun Gingerbread instead describes The reliability of the findings, which rules this alternative out.","D":"Production efficiency is an operations matter. The firm is checking whether its research results are consistent. In Torun Gingerbread's case, the correct description is The reliability of the findings, not this choice."}}},{"id":"P1_U3_MCQ_1895","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1895","question":"Gdynia Nets, based in Gdynia, Poland, uses a stronger rope than competitors, so its fishing nets last longer and can be sold at a premium price. What is the firm doing?","options":{"A":"Cost leadership","B":"Market penetration","C":"Product differentiation","D":"Mass marketing"},"correctOption":"C","correctAnswer":"Product differentiation","questionType":"MCQ","explanation":{"correct_reason":"Product differentiation means making a product distinct in a way buyers value. Gdynia Nets' stronger, longer-lasting ropes set its nets apart, so it is differentiating its product.","distractor_reasons":{"A":"Cost leadership means being the cheapest producer. The stronger material likely raises costs, and the firm charges a premium, so it is not a cost leader.","B":"Market penetration means increasing share of existing markets, often via lower prices. The scenario highlights a superior product feature, not a share drive.","C":"Product differentiation means making a product distinct in a way buyers value. Gdynia Nets' stronger, longer-lasting ropes set its nets apart, so it is differentiating its product.","D":"Mass marketing targets the whole market with one offer. The nets are differentiated by quality, not aimed undifferentiated at everyone. Gdynia Nets's circumstances match Product differentiation, so this option does not fit."}}},{"id":"P1_U3_MCQ_1896","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1896","question":"Czestochowa Mills, based in Czestochowa, Poland, grew its own sales by 5 percent last year while the total market expanded by 15 percent. What happened to the firm's market share?","options":{"A":"Share fell","B":"Share rose","C":"Share unchanged","D":"Sales fell"},"correctOption":"A","correctAnswer":"Share fell","questionType":"MCQ","explanation":{"correct_reason":"Market share falls when a firm's sales grow more slowly than the overall market. Czestochowa Mills grew 5 percent against a 15 percent market, so its share declined.","distractor_reasons":{"A":"Market share falls when a firm's sales grow more slowly than the overall market. Czestochowa Mills grew 5 percent against a 15 percent market, so its share declined.","B":"A rising share requires sales to outpace the market. Growing 5 percent while the market grew 15 percent means the share fell.","C":"An unchanged share would require the firm to grow at the market's 15 percent. It grew only 5 percent, so the share changed.","D":"Sales did not fall; they rose by 5 percent. The issue is that this was slower than the market, reducing share."}}},{"id":"P1_U3_MCQ_1897","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1897","question":"Rzeszow Bearings, based in Rzeszow, Poland, increased its annual revenue from $50 million to $57.5 million. The finance team wants the growth rate. What was the percentage increase in revenue?","options":{"A":"7.5%","B":"10%","C":"15%","D":"20%"},"correctOption":"C","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Percentage increase is the change divided by the original value, multiplied by 100. Revenue rose by $7.5 million from $50 million, and 7.5 divided by 50 is 0.15, or 15 percent.","distractor_reasons":{"A":"7.5 percent mistakes the $7.5 million increase for a percentage. Dividing the increase by the original $50 million gives 15 percent.","B":"10 percent would be a $5 million rise. The actual rise was $7.5 million, giving a 15 percent increase. Rzeszow Bearings's circumstances match 15%, so this option does not fit.","C":"Percentage increase is the change divided by the original value, multiplied by 100. Revenue rose by $7.5 million from $50 million, and 7.5 divided by 50 is 0.15, or 15 percent.","D":"20 percent would mean a $10 million increase. With a $7.5 million rise on $50 million, the increase is 15 percent."}}},{"id":"P1_U3_MCQ_1898","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1898","question":"Olsztyn Poultry, based in Olsztyn, Poland, surveyed 2,000 customers and found that 62 percent were satisfied with its packaging. How many of those surveyed were satisfied?","options":{"A":"1,240","B":"1,200","C":"1,400","D":"620"},"correctOption":"A","correctAnswer":"1,240","questionType":"MCQ","explanation":{"correct_reason":"The satisfied count is the sample size multiplied by the percentage. Olsztyn Poultry surveyed 2,000 customers and 62 percent were satisfied, and 2,000 multiplied by 0.62 equals 1,240.","distractor_reasons":{"A":"The satisfied count is the sample size multiplied by the percentage. Olsztyn Poultry surveyed 2,000 customers and 62 percent were satisfied, and 2,000 multiplied by 0.62 equals 1,240.","B":"1,200 is 60 percent of 2,000, slightly below the reported 62 percent. The correct count is 1,240. The details given about Olsztyn Poultry support 1,240, so this answer is unsuitable.","C":"1,400 is 70 percent of the sample. With 62 percent satisfied, the correct figure is 1,240. For Olsztyn Poultry, the facts point to 1,240, so this option cannot be correct.","D":"620 is roughly 31 percent of the sample, half the correct count. Sixty-two percent of 2,000 is 1,240. The scenario for Olsztyn Poultry instead describes 1,240, which rules this alternative out."}}},{"id":"P1_U3_MCQ_1899","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1899","question":"Bialystok Ladders, based in Bialystok, Poland, pays to sponsor a national athletics team and displays its logo on their kits to raise brand awareness. Which promotional activity is this?","options":{"A":"Sales promotion","B":"Sponsorship","C":"Personal selling","D":"Direct marketing"},"correctOption":"B","correctAnswer":"Sponsorship","questionType":"MCQ","explanation":{"correct_reason":"Sponsorship involves funding an event, person or team in return for publicity. Bialystok Ladders funds an athletics team and gains logo exposure, so the activity is sponsorship.","distractor_reasons":{"A":"Sales promotion uses short-term incentives such as discounts to boost sales. Sponsoring a team is a longer-term image-building activity, not a sales incentive.","B":"Sponsorship involves funding an event, person or team in return for publicity. Bialystok Ladders funds an athletics team and gains logo exposure, so the activity is sponsorship.","C":"Personal selling is face-to-face selling to individual buyers. Sponsorship raises awareness broadly rather than selling to one buyer. The scenario for Bialystok Ladders instead describes Sponsorship, which rules this alternative out.","D":"Direct marketing sends targeted messages to named individuals. Team sponsorship exposes the brand to a general audience, not individuals directly. In Bialystok Ladders's case, the correct description is Sponsorship, not this choice."}}},{"id":"P1_U3_MCQ_1900","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1900","question":"Radom Blankets, based in Radom, Poland, earned $18 million in revenue last year from a national blanket market worth $120 million. What was the firm's market share by value?","options":{"A":"10%","B":"12%","C":"18%","D":"15%"},"correctOption":"D","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Market share by value is firm revenue divided by total market value, multiplied by 100. Radom Blankets earned $18 million in a $120 million market, and 18 divided by 120 is 15 percent.","distractor_reasons":{"A":"10 percent would mean $12 million of revenue. The firm earned $18 million, giving a 15 percent share. In Radom Blankets's case, the correct description is 15%, not this choice.","B":"12 percent corresponds to $14.4 million. With $18 million earned, the correct share is 15 percent. Radom Blankets's circumstances match 15%, so this option does not fit.","C":"18 percent mistakes the $18 million revenue for a share. Dividing by the $120 million market gives 15 percent. The details given about Radom Blankets support 15%, so this answer is unsuitable.","D":"Market share by value is firm revenue divided by total market value, multiplied by 100. Radom Blankets earned $18 million in a $120 million market, and 18 divided by 120 is 15 percent."}}},{"id":"P1_U3_MCQ_1901","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1901","question":"Harbourlight Kites operates in Cape Town, South Africa, where the total market for recreational kites is 50,000 units a year. Last year Harbourlight sold 7,500 kites. The marketing manager wants to know the firm's share of this market. What was Harbourlight's market share last year?","options":{"A":"7.5%","B":"150%","C":"20%","D":"15%"},"correctOption":"D","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Market share is the firm's sales divided by total market sales, multiplied by 100. Harbourlight sold 7,500 of the 50,000 kites bought in Cape Town, so 7,500 divided by 50,000 is 0.15, which equals 15 per cent.","distractor_reasons":{"A":"7.5 per cent would result from dividing 7,500 by 100,000, but the total Cape Town market is only 50,000 kites, so the true proportion of kites sold by Harbourlight is twice as large.","B":"150 per cent is impossible for a share of a market and comes from dividing 50,000 by 7,500 and then misplacing the decimal point; a firm cannot sell more than the entire market.","C":"20 per cent would require Harbourlight to have sold 10,000 of the 50,000 kites in the market. Actual sales were 7,500, so this option overstates the share by 2,500 kites.","D":"Market share is the firm's sales divided by total market sales, multiplied by 100. Harbourlight sold 7,500 of the 50,000 kites bought in Cape Town, so 7,500 divided by 50,000 is 0.15, which equals 15 per cent."}}},{"id":"P1_U3_MCQ_1902","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1902","question":"Fieldwork Forum, a consultancy in Dublin, Ireland, has been asked to find out what first-time home buyers think of a new mortgage product. It decides to collect brand-new opinions directly from potential customers rather than using any previously published figures. What kind of research is this?","options":{"A":"Internal research","B":"Secondary research","C":"Desk research","D":"Primary research"},"correctOption":"D","correctAnswer":"Primary research","questionType":"MCQ","explanation":{"correct_reason":"Primary research means gathering new, first-hand information directly from the people being studied. By asking potential home buyers for their own views, Fieldwork Forum is collecting original data rather than reusing existing published material, so this is primary research.","distractor_reasons":{"A":"Internal research would draw on records already held inside a business. Since the information comes from outside potential customers in Dublin, this label does not describe the first-hand collection taking place.","B":"Secondary research uses information that already exists, such as government statistics or earlier reports. Because the Dublin consultancy is collecting fresh opinions from buyers itself, it is not relying on second-hand sources.","C":"Desk research is carried out using existing documents and online sources without contacting respondents. Fieldwork Forum is speaking directly to mortgage customers, so its approach is not desk-based research.","D":"Primary research means gathering new, first-hand information directly from the people being studied. By asking potential home buyers for their own views, Fieldwork Forum is collecting original data rather than reusing existing published material, so this is primary research."}}},{"id":"P1_U3_MCQ_1903","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1903","question":"Peppercat Sauces in Bangkok, Thailand, is launching a new chilli sauce. The team is deciding on the size of the glass jar, the strength of the recipe and the wording on the label before any advertising is planned. Which element of the marketing mix are these decisions part of?","options":{"A":"Price","B":"Place","C":"Product","D":"Promotion"},"correctOption":"C","correctAnswer":"Product","questionType":"MCQ","explanation":{"correct_reason":"The product element covers the physical good itself, including its design, features, quality, packaging and branding. Choosing the jar size, recipe strength and label wording for the Bangkok sauce all shape the item being offered, so these are product decisions.","distractor_reasons":{"A":"Price decisions concern how much customers pay, such as discounts or payment terms. The jar size and recipe describe what the sauce actually is, not its price, so price is not the element being decided here.","B":"Place is about distribution and how customers obtain the product, such as which shops stock it. Deciding the jar and label in Bangkok does not address where the sauce will be sold, so place is incorrect.","C":"The product element covers the physical good itself, including its design, features, quality, packaging and branding. Choosing the jar size, recipe strength and label wording for the Bangkok sauce all shape the item being offered, so these are product decisions.","D":"Promotion covers advertising and sales messages. Although a label carries information, the team is specifying the sauce's size and recipe before any campaign, so the central element is the product itself rather than promotion."}}},{"id":"P1_U3_MCQ_1904","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1904","question":"Willowbay Buses runs city services in Leeds, United Kingdom. The total number of bus journeys in the city rose from 200,000 a month to 230,000 a month after a new ticket scheme. The manager wants the percentage growth in total demand. What was the percentage increase in bus journeys?","options":{"A":"13%","B":"30%","C":"23%","D":"15%"},"correctOption":"D","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Growth is the change in demand divided by the original amount, multiplied by 100. Journeys in Leeds increased by 30,000 from a base of 200,000, so 30,000 divided by 200,000 gives 0.15, which is a 15 per cent rise.","distractor_reasons":{"A":"13 per cent comes from dividing the 30,000 extra journeys by the new total of 230,000 rather than the original 200,000. Growth must always be measured against the starting figure, not the final one.","B":"30 per cent confuses the 30,000 extra journeys with a percentage. Since the original market was 200,000 journeys, an increase of 30,000 is only 15 per cent of that base.","C":"23 per cent would mean an increase of 46,000 journeys on a base of 200,000. The actual rise from 200,000 to 230,000 is only 30,000 journeys, so this overstates the change considerably.","D":"Growth is the change in demand divided by the original amount, multiplied by 100. Journeys in Leeds increased by 30,000 from a base of 200,000, so 30,000 divided by 200,000 gives 0.15, which is a 15 per cent rise."}}},{"id":"P1_U3_MCQ_1905","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1905","question":"Cedarpoint Coffee in Seattle, United States, begins each product launch by asking local residents what they want from a morning drink, then designs its menu around those answers. Which approach to marketing is the firm using?","options":{"A":"A sales orientation","B":"A product orientation","C":"A production orientation","D":"A market orientation"},"correctOption":"D","correctAnswer":"A market orientation","questionType":"MCQ","explanation":{"correct_reason":"A market orientation puts customer needs at the centre of decision making. Cedarpoint Coffee researches what Seattle residents want before creating its drinks, so the business is built around satisfying identified customer needs rather than pushing what it already makes.","distractor_reasons":{"A":"A sales orientation assumes customers will buy only if the firm promotes aggressively, focusing on selling existing output. Cedarpoint instead changes its menu to match what residents say they want, which is the opposite approach.","B":"A product orientation concentrates on improving the product itself, often without checking customer demand. Because Cedarpoint starts by asking residents about their needs, it is not simply perfecting a product in isolation.","C":"A production orientation emphasises efficient, high-volume output and low costs, assuming customers will buy cheap products. The Seattle firm is guided by customer preferences, not by maximising production efficiency.","D":"A market orientation puts customer needs at the centre of decision making. Cedarpoint Coffee researches what Seattle residents want before creating its drinks, so the business is built around satisfying identified customer needs rather than pushing what it already makes."}}},{"id":"P1_U3_MCQ_1906","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1906","question":"Nordhavn Sports in Copenhagen, Denmark, mailed 2,000 questionnaires to households about sports equipment buying habits and received 460 completed replies. The marketing intern needs the response rate for the survey. What percentage of questionnaires were returned?","options":{"A":"2.3%","B":"46%","C":"4.6%","D":"23%"},"correctOption":"D","correctAnswer":"23%","questionType":"MCQ","explanation":{"correct_reason":"Response rate equals the number of completed questionnaires divided by the number sent out, multiplied by 100. Nordhavn received 460 replies from 2,000 mailed forms in Copenhagen, so 460 divided by 2,000 is 0.23, giving a response rate of 23 per cent.","distractor_reasons":{"A":"2.3 per cent is a decimal place error; dividing 460 by 2,000 does not produce such a small share. Roughly a quarter of the questionnaires were returned, so the rate is 23 per cent.","B":"46 per cent would require 920 replies out of 2,000 questionnaires. Only 460 forms came back, so this figure is exactly twice the true response rate for the Copenhagen survey.","C":"4.6 per cent comes from dividing 460 by 10,000 rather than by the 2,000 forms actually mailed. The denominator must be the number of questionnaires sent, which gives 23 per cent.","D":"Response rate equals the number of completed questionnaires divided by the number sent out, multiplied by 100. Nordhavn received 460 replies from 2,000 mailed forms in Copenhagen, so 460 divided by 2,000 is 0.23, giving a response rate of 23 per cent."}}},{"id":"P1_U3_MCQ_1907","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1907","question":"Saffrona Textiles in Jaipur, India, is entering a new regional market and has set an intentionally low price for its printed cottons to attract buyers away from established brands. Which pricing method is the firm using?","options":{"A":"Skimming","B":"Competitive pricing","C":"Cost-plus pricing","D":"Penetration pricing"},"correctOption":"D","correctAnswer":"Penetration pricing","questionType":"MCQ","explanation":{"correct_reason":"Penetration pricing means setting a low initial price to win customers and gain market share quickly. By pricing its Jaipur cottons below established rivals, Saffrona is trying to pull buyers toward the new brand, which matches this method.","distractor_reasons":{"A":"Price skimming sets a high introductory price to earn maximum revenue from keen early buyers before lowering it. Saffrona has done the opposite in Jaipur by starting low, so skimming is not the method described.","B":"Competitive pricing sets a price close to rivals' prices rather than clearly below them. The Jaipur firm is deliberately undercutting established brands, so it is using penetration rather than matching competitors.","C":"Cost-plus pricing adds a fixed margin to the cost of production. The scenario says nothing about the firm's costs or a markup; it emphasises a deliberately low price to attract customers, which is penetration pricing.","D":"Penetration pricing means setting a low initial price to win customers and gain market share quickly. By pricing its Jaipur cottons below established rivals, Saffrona is trying to pull buyers toward the new brand, which matches this method."}}},{"id":"P1_U3_MCQ_1908","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1908","question":"Aurora Ski Gear in Innsbruck, Austria, groups its customers by age, income and lifestyle, then designs separate product ranges for families, students and professional skiers. What is this activity called?","options":{"A":"Product differentiation","B":"Market research","C":"Mass marketing","D":"Market segmentation"},"correctOption":"D","correctAnswer":"Market segmentation","questionType":"MCQ","explanation":{"correct_reason":"Market segmentation divides a broad market into distinct groups of buyers with shared characteristics. Aurora is splitting skiers in Innsbruck into families, students and professionals using age, income and lifestyle, so it is carrying out segmentation.","distractor_reasons":{"A":"Product differentiation makes an offer distinct from competitors' offers. The scenario focuses on dividing customers into groups, not on distinguishing Aurora's goods from rival ski brands, so segmentation is the better answer.","B":"Market research is the process of collecting information about customers. Although research may inform the split, the act of grouping buyers into families, students and professionals is segmentation itself, not data collection.","C":"Mass marketing treats the whole market as one group with a single offer. Aurora is doing the reverse by creating different ranges for different types of skier, so a mass approach does not fit.","D":"Market segmentation divides a broad market into distinct groups of buyers with shared characteristics. Aurora is splitting skiers in Innsbruck into families, students and professionals using age, income and lifestyle, so it is carrying out segmentation."}}},{"id":"P1_U3_MCQ_1909","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1909","question":"Lagoon View Hotels owns a 120-room resort in Phuket, Thailand. Every room was occupied for 30 nights at a nightly rate of $90. The manager wants the total room revenue for the month. What was the resort's total room revenue?","options":{"A":"$32,400","B":"$108,000","C":"$324,000","D":"$360,000"},"correctOption":"C","correctAnswer":"$324,000","questionType":"MCQ","explanation":{"correct_reason":"Total room revenue is rooms multiplied by nightly rate multiplied by nights occupied. In Phuket, 120 rooms at $90 per night for 30 nights gives 120 multiplied by 90, which is $10,800 per night, then multiplied by 30 to reach $324,000.","distractor_reasons":{"A":"$32,400 results from multiplying 120 rooms by $90 and then by 3 nights instead of 30. The resort was fully occupied for 30 nights, so the monthly figure is ten times larger.","B":"$108,000 is 120 rooms multiplied by $90 per night for 10 nights. Because the rooms were sold for 30 nights in Phuket, this understates revenue by two thirds.","C":"Total room revenue is rooms multiplied by nightly rate multiplied by nights occupied. In Phuket, 120 rooms at $90 per night for 30 nights gives 120 multiplied by 90, which is $10,800 per night, then multiplied by 30 to reach $324,000.","D":"$360,000 would require a nightly rate of $100 instead of $90. With 120 rooms occupied over 30 nights at the actual $90 rate, total revenue is $324,000."}}},{"id":"P1_U3_MCQ_1910","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1910","question":"Brightpath Analytics, a firm in Melbourne, Australia, is researching household spending on pet food. It begins by studying census tables and industry reports published by the government and trade bodies, without contacting any households. What type of data is it using?","options":{"A":"Primary data","B":"Field data","C":"Qualitative data","D":"Secondary data"},"correctOption":"D","correctAnswer":"Secondary data","questionType":"MCQ","explanation":{"correct_reason":"Secondary data is information that was collected by someone else and already exists in published form. By reading government census tables and trade reports, Brightpath is reusing second-hand statistics rather than gathering new information from Melbourne households itself.","distractor_reasons":{"A":"Primary data would involve collecting fresh information directly from respondents, such as surveys or interviews. The Melbourne firm is only reading existing reports, so it is not generating primary data.","B":"Field data is gathered first-hand in the location being studied. Because Brightpath stays in its office with published documents, its approach is not field research.","C":"Qualitative data consists of words, opinions and descriptions rather than numerical tables. Census tables and spending statistics are numerical, so this label does not describe the published figures being examined.","D":"Secondary data is information that was collected by someone else and already exists in published form. By reading government census tables and trade reports, Brightpath is reusing second-hand statistics rather than gathering new information from Melbourne households itself."}}},{"id":"P1_U3_MCQ_1911","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1911","question":"Basant Bakery in Kathmandu, Nepal, sells cakes through its own shops and now offers home delivery through a motorcycle fleet. Which element of the marketing mix does this delivery decision mainly concern?","options":{"A":"Product","B":"Price","C":"Place","D":"Promotion"},"correctOption":"C","correctAnswer":"Place","questionType":"MCQ","explanation":{"correct_reason":"The place element covers how a product reaches customers, including distribution channels and delivery. By adding motorcycle home delivery in Kathmandu, Basant is changing how buyers obtain its cakes, which is a distribution or place decision.","distractor_reasons":{"A":"Product decisions concern the cake's recipe, size and packaging. The delivery fleet does not change the cake itself, so it is not a product decision even though customers may value the service.","B":"Price decisions set what customers pay. The scenario says nothing about changing cake prices or delivery charges, so the addition of a motorcycle fleet is not primarily about price.","C":"The place element covers how a product reaches customers, including distribution channels and delivery. By adding motorcycle home delivery in Kathmandu, Basant is changing how buyers obtain its cakes, which is a distribution or place decision.","D":"Promotion communicates with customers through advertising or offers. Although delivery could later be advertised, the decision described is about getting the cakes to buyers, which belongs to place."}}},{"id":"P1_U3_MCQ_1912","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1912","question":"Riverbend Phones sells 96,000 handsets a year in Manila, Philippines. Industry figures show the total mobile handset market in the city is 800,000 units a year. What share of the Manila market does Riverbend hold?","options":{"A":"8.6%","B":"83%","C":"16%","D":"12%"},"correctOption":"D","correctAnswer":"12%","questionType":"MCQ","explanation":{"correct_reason":"Market share is the business's sales divided by total market sales, multiplied by 100. Riverbend sells 96,000 of the 800,000 handsets bought in Manila, so 96,000 divided by 800,000 equals 0.12, which is a 12 per cent share.","distractor_reasons":{"A":"8.6 per cent would come from dividing 96,000 by about 1.1 million, not by the 800,000 handsets in the Manila market. The correct calculation uses total city sales of 800,000.","B":"83 per cent is close to dividing 800,000 by 96,000 rather than the other way around. Market share is a small part of the whole, not the whole divided by the firm's sales.","C":"16 per cent would require Riverbend to sell 128,000 handsets out of 800,000. Its real sales are 96,000, so this option overstates its position by 32,000 units.","D":"Market share is the business's sales divided by total market sales, multiplied by 100. Riverbend sells 96,000 of the 800,000 handsets bought in Manila, so 96,000 divided by 800,000 equals 0.12, which is a 12 per cent share."}}},{"id":"P1_U3_MCQ_1913","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1913","question":"Tasman Trailers in Auckland, New Zealand, sells flat-bed trailers to building companies that use them on construction sites rather than to individual households. Which type of market is Tasman selling into?","options":{"A":"The consumer market","B":"The organisational market","C":"The fractional market","D":"The overseas market"},"correctOption":"B","correctAnswer":"The organisational market","questionType":"MCQ","explanation":{"correct_reason":"The organisational market consists of businesses and other institutions that buy goods for use in their operations. Because Tasman Trailers sells to Auckland building companies rather than to households, it is operating in a business-to-business or organisational market.","distractor_reasons":{"A":"The consumer market involves individuals buying goods for personal or household use. The purchasers here are construction firms using trailers for work, so this is not a sale to final consumers.","B":"The organisational market consists of businesses and other institutions that buy goods for use in their operations. Because Tasman Trailers sells to Auckland building companies rather than to households, it is operating in a business-to-business or organisational market.","C":"There is no recognised 'fractional market' in this context; the phrase is invented. The clear classification for sales to building companies is the organisational market, so this option should be rejected.","D":"The overseas market would involve customers in other countries. Tasman's buyers are building firms in Auckland, so the transaction is domestic and this option does not describe the situation."}}},{"id":"P1_U3_MCQ_1914","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1914","question":"Keystone Research Group in Toronto, Canada, interviewed 1,250 shoppers and found that 375 of them preferred a locally made brand of olive oil. What percentage of the shoppers preferred the local brand?","options":{"A":"25%","B":"30%","C":"37.5%","D":"3%"},"correctOption":"B","correctAnswer":"30%","questionType":"MCQ","explanation":{"correct_reason":"The percentage preferring the brand is the number who chose it divided by the total surveyed, multiplied by 100. In Toronto, 375 out of 1,250 shoppers preferred the local oil, so 375 divided by 1,250 equals 0.3, giving 30 per cent.","distractor_reasons":{"A":"25 per cent would mean 312 or 313 shoppers out of 1,250. The survey found 375 supporters, so this understates the proportion who chose the locally made olive oil.","B":"The percentage preferring the brand is the number who chose it divided by the total surveyed, multiplied by 100. In Toronto, 375 out of 1,250 shoppers preferred the local oil, so 375 divided by 1,250 equals 0.3, giving 30 per cent.","C":"37.5 per cent comes from dividing 375 by 1,000 rather than by the 1,250 people actually interviewed. Using the correct denominator of 1,250 gives 30 per cent.","D":"3 per cent is a decimal place error; 375 out of 1,250 is roughly one third of the sample, not three in a hundred. The true share of Toronto shoppers preferring the brand is 30 per cent."}}},{"id":"P1_U3_MCQ_1915","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1915","question":"Solstice Sunscreen in Brisbane, Australia, is running television adverts and paid social media posts to tell swimmers about its new SPF50 lotion. Which element of the marketing mix does this activity represent?","options":{"A":"Product","B":"Price","C":"Place","D":"Promotion"},"correctOption":"D","correctAnswer":"Promotion","questionType":"MCQ","explanation":{"correct_reason":"Promotion includes all the ways a business communicates with customers, such as advertising and social media campaigns. By using television and paid posts to inform Brisbane swimmers about its lotion, Solstice is carrying out promotion.","distractor_reasons":{"A":"Product decisions relate to the lotion's formula, bottle and protection level. The adverts describe an existing SPF50 product rather than changing it, so the main activity is not product development.","B":"Price concerns what customers pay and any discounts offered. Nothing in the Brisbane campaign mentions a special price, so the activity being described is communication rather than pricing.","C":"Place is about distribution and where the sunscreen is sold. Although the campaign may drive buyers to shops, the adverts themselves are a communication tool, which belongs to promotion.","D":"Promotion includes all the ways a business communicates with customers, such as advertising and social media campaigns. By using television and paid posts to inform Brisbane swimmers about its lotion, Solstice is carrying out promotion."}}},{"id":"P1_U3_MCQ_1916","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1916","question":"Maple Ridge Furniture in Ottawa, Canada, has chosen to serve only wealthy urban professionals who want handcrafted oak desks, ignoring other customer groups entirely. Which targeting approach is the firm using?","options":{"A":"Mass marketing","B":"Concentrated targeting","C":"Undifferentiated marketing","D":"Mass customisation"},"correctOption":"B","correctAnswer":"Concentrated targeting","questionType":"MCQ","explanation":{"correct_reason":"Concentrated targeting means focusing the whole marketing effort on one clearly defined customer segment. By serving only wealthy urban professionals in Ottawa and ignoring everyone else, Maple Ridge is directing its offer at a single narrow group.","distractor_reasons":{"A":"Mass marketing aims at the whole market with one broad offer. Maple Ridge is deliberately excluding most buyers in Ottawa, so it is the opposite of a mass approach.","B":"Concentrated targeting means focusing the whole marketing effort on one clearly defined customer segment. By serving only wealthy urban professionals in Ottawa and ignoring everyone else, Maple Ridge is directing its offer at a single narrow group.","C":"Undifferentiated marketing treats all customers alike with a single product and message. This firm tailors handcrafted desks to one professional segment, so it is differentiated and concentrated rather than undifferentiated.","D":"Mass customisation uses flexible production to give many customers individualised products. The scenario describes a targeting choice about whom to serve, not a production method for making bespoke desks."}}},{"id":"P1_U3_MCQ_1917","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1917","question":"Alpine Yoghurt in Zurich, Switzerland, buys raw milk and cultures for $2.00 per tub and sells the finished yoghurt for $6.00 per tub. What is the value added by the firm per tub?","options":{"A":"$2.00","B":"$3.00","C":"$4.00","D":"$8.00"},"correctOption":"C","correctAnswer":"$4.00","questionType":"MCQ","explanation":{"correct_reason":"Value added per unit is the selling price minus the cost of bought-in materials. Alpine Yoghurt sells each tub in Zurich for $6.00 after spending $2.00 on milk and cultures, so $6.00 minus $2.00 gives $4.00 of added value per tub.","distractor_reasons":{"A":"$2.00 is the cost of the raw materials, not the value added. Added value measures what the business adds through its own work, which is the gap between the $6.00 price and the $2.00 material cost.","B":"$3.00 would be the result if raw materials cost $3.00 per tub. The stated cost in Zurich is $2.00, so the difference between price and cost is actually $4.00.","C":"Value added per unit is the selling price minus the cost of bought-in materials. Alpine Yoghurt sells each tub in Zurich for $6.00 after spending $2.00 on milk and cultures, so $6.00 minus $2.00 gives $4.00 of added value per tub.","D":"$8.00 comes from adding the $6.00 price to the $2.00 cost instead of subtracting. Value added is a margin between price and input cost, never their sum."}}},{"id":"P1_U3_MCQ_1918","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1918","question":"Cobalt Cycles in Antwerp, Belgium, brings together eight experienced riders and asks a trained moderator to guide a discussion about what they want from a new commuting bike. Which research method is being used?","options":{"A":"A questionnaire","B":"A focus group","C":"An observation study","D":"A sales forecast"},"correctOption":"B","correctAnswer":"A focus group","questionType":"MCQ","explanation":{"correct_reason":"A focus group is a small, purposely selected group of people led by a moderator in a guided discussion to explore views in depth. Cobalt is using eight Antwerp riders and a moderator, which matches this qualitative research method exactly.","distractor_reasons":{"A":"A questionnaire uses a set of written questions completed by many respondents, usually individually. The Antwerp firm is running a moderated group discussion rather than collecting separate written answers.","B":"A focus group is a small, purposely selected group of people led by a moderator in a guided discussion to explore views in depth. Cobalt is using eight Antwerp riders and a moderator, which matches this qualitative research method exactly.","C":"Observation records customers' behaviour without asking them questions, such as watching how people choose bikes in a shop. Here the riders are actively discussing their preferences, so the method is not observation.","D":"A sales forecast predicts future sales using past data or market trends. The Cobalt exercise is gathering opinions from riders, not estimating how many bikes will be sold next year."}}},{"id":"P1_U3_MCQ_1919","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1919","question":"Lumen Lamps in Stockholm, Sweden, offers trade buyers a 20 per cent reduction on every order of more than 50 floor lamps. Which element of the marketing mix is this decision about?","options":{"A":"Product","B":"Price","C":"Promotion","D":"Place"},"correctOption":"B","correctAnswer":"Price","questionType":"MCQ","explanation":{"correct_reason":"Price decisions include discounts, allowances and the amount customers actually pay. By cutting the charge by 20 per cent for large orders, Lumen is changing the price paid by Stockholm trade buyers, so this is a pricing decision.","distractor_reasons":{"A":"Product decisions concern the lamp's design, quality and packaging. The 20 per cent reduction does not alter the lamp itself, so it cannot be described as a product change.","B":"Price decisions include discounts, allowances and the amount customers actually pay. By cutting the charge by 20 per cent for large orders, Lumen is changing the price paid by Stockholm trade buyers, so this is a pricing decision.","C":"Promotion covers advertising and communication, such as a campaign announcing a sale. Although a discount can be advertised, the decision described is the reduction in the amount charged, which is price.","D":"Place is about distribution and how lamps reach buyers. Offering a bulk discount in Stockholm says nothing about delivery or stocking, so place is not the element being altered."}}},{"id":"P1_U3_MCQ_1920","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1920","question":"Zenith Activewear in Seoul, South Korea, works to create a distinct image of durability and style in customers' minds so that buyers see it as different from rival sports brands. What is this activity called?","options":{"A":"Channel selection","B":"Market capacity","C":"Sales forecasting","D":"Market positioning"},"correctOption":"D","correctAnswer":"Market positioning","questionType":"MCQ","explanation":{"correct_reason":"Positioning is the process of creating a clear, distinctive place for a brand in the customer's mind relative to competitors. By building an image of durability and style against Seoul rivals, Zenith is positioning its activewear.","distractor_reasons":{"A":"Channel selection decides where a product is sold, such as online or in shops. The Seoul firm is working on brand image, not choosing retail outlets, so this option is not relevant.","B":"Market capacity refers to the total volume a market can absorb. The scenario describes shaping customer perceptions of a brand, not measuring how many garments the market could purchase.","C":"Sales forecasting estimates future sales from data and trends. Zenith is concerned with how buyers perceive its products compared with rivals, which is a positioning issue rather than a numerical prediction.","D":"Positioning is the process of creating a clear, distinctive place for a brand in the customer's mind relative to competitors. By building an image of durability and style against Seoul rivals, Zenith is positioning its activewear."}}},{"id":"P1_U3_MCQ_1921","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1921","question":"Solara Batteries in Nairobi, Kenya, estimates the total market for rechargeable power packs grew from 40,000 units to 52,000 units in one year. The marketing director wants the annual growth rate of the market. What was the percentage growth in demand?","options":{"A":"12%","B":"20%","C":"30%","D":"52%"},"correctOption":"C","correctAnswer":"30%","questionType":"MCQ","explanation":{"correct_reason":"Market growth is the increase in total demand divided by the original market size, multiplied by 100. The Nairobi market rose from 40,000 to 52,000 units, an increase of 12,000, so 12,000 divided by 40,000 is 0.3, meaning growth of 30 per cent.","distractor_reasons":{"A":"12 per cent mistakes the 12,000 extra units for a percentage. Because the starting market in Nairobi was 40,000 units, an increase of 12,000 represents 30 per cent of that base.","B":"20 per cent would be the figure if the market had grown from 40,000 to 48,000 units. The actual rise to 52,000 adds 12,000 units, which is a 30 per cent increase.","C":"Market growth is the increase in total demand divided by the original market size, multiplied by 100. The Nairobi market rose from 40,000 to 52,000 units, an increase of 12,000, so 12,000 divided by 40,000 is 0.3, meaning growth of 30 per cent.","D":"52 per cent confuses the final market size of 52,000 with a growth rate. Growth measures the change from the original 40,000 units, which is only 30 per cent."}}},{"id":"P1_U3_MCQ_1922","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1922","question":"Cirrus Research in Helsinki, Finland, is planning a large telephone survey of commuters. Before committing to the full study, the team tests the questions on ten colleagues to check that the wording is clear and the answers can be recorded. What is this preliminary step called?","options":{"A":"A focus group","B":"A census","C":"A pilot study","D":"Secondary analysis"},"correctOption":"C","correctAnswer":"A pilot study","questionType":"MCQ","explanation":{"correct_reason":"A pilot study is a small trial run of a research instrument before the main investigation, used to test wording and recording methods. By trying its questions on ten colleagues in Helsinki, Cirrus is conducting a pilot to refine the survey.","distractor_reasons":{"A":"A focus group is a moderated discussion among selected participants to explore attitudes. Colleagues here are checking question clarity rather than discussing commuting views in depth, so this is not a focus group.","B":"A census attempts to collect data from every member of a population. Testing questions on ten colleagues is a tiny trial, so it is not a census of Helsinki commuters.","C":"A pilot study is a small trial run of a research instrument before the main investigation, used to test wording and recording methods. By trying its questions on ten colleagues in Helsinki, Cirrus is conducting a pilot to refine the survey.","D":"Secondary analysis reuses data collected by other researchers. The Helsinki team is testing its own new questionnaire, so it is not working with existing secondary data."}}},{"id":"P1_U3_MCQ_1923","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1923","question":"Petal & Pod, a gift shop in Chiang Mai, Thailand, now lets customers pay for hampers in three monthly instalments instead of one lump sum. Which element of the marketing mix does this change mainly affect?","options":{"A":"Product","B":"Promotion","C":"Place","D":"Price"},"correctOption":"D","correctAnswer":"Price","questionType":"MCQ","explanation":{"correct_reason":"Price includes not only the amount charged but also payment terms and credit. By allowing Chiang Mai customers to spread payments for hampers over three months, Petal & Pod is altering the terms on which the price is paid, which is a price decision.","distractor_reasons":{"A":"Product covers the hamper's contents and packaging. Offering instalments does not change the physical hamper, so the adjustment is about how payment is made rather than the product itself.","B":"Promotion communicates messages to customers, such as advertising. Although instalments might be advertised, the substance of the change is the payment arrangement, which belongs to price.","C":"Place concerns distribution and how goods reach buyers. Letting shoppers pay in instalments in Chiang Mai says nothing about delivery or store location, so place is not involved here.","D":"Price includes not only the amount charged but also payment terms and credit. By allowing Chiang Mai customers to spread payments for hampers over three months, Petal & Pod is altering the terms on which the price is paid, which is a price decision."}}},{"id":"P1_U3_MCQ_1924","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1924","question":"Vertex Running Shoes in Boulder, United States, produces separate adverts and product lines for marathon runners, casual joggers and school athletics clubs, with a distinct offer for each group. Which targeting strategy is the firm following?","options":{"A":"Undifferentiated marketing","B":"Differentiated marketing","C":"Concentrated marketing","D":"Mass marketing"},"correctOption":"B","correctAnswer":"Differentiated marketing","questionType":"MCQ","explanation":{"correct_reason":"Differentiated targeting means designing separate marketing mixes for several distinct customer segments. Vertex is creating different shoes and messages for marathon runners, joggers and school clubs in Boulder, so it is pursuing a differentiated strategy.","distractor_reasons":{"A":"Undifferentiated marketing offers one standard product to the whole market. Vertex is tailoring separate ranges and adverts to three groups, which is the opposite of treating all customers the same.","B":"Differentiated targeting means designing separate marketing mixes for several distinct customer segments. Vertex is creating different shoes and messages for marathon runners, joggers and school clubs in Boulder, so it is pursuing a differentiated strategy.","C":"Concentrated targeting focuses on a single segment. Because the Boulder firm serves three different groups with distinct offers, it is not concentrating on just one.","D":"Mass marketing uses a single broad message for everyone. The separate product lines and campaigns for runners, joggers and clubs show that Vertex is segmenting rather than mass marketing."}}},{"id":"P1_U3_MCQ_1925","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1925","question":"A shopper in Athens, Greece, tells Olive Grove Foods that she needs a cooking oil that stays fresh, but says she would like one in a decorative bottle for dinner parties. Which statement correctly identifies her need and her want?","options":{"A":"Freshness is the want and the decorative bottle is the need","B":"Freshness is the need and the decorative bottle is the want","C":"Both are needs because she asked for them","D":"Neither is a need because oil is a luxury"},"correctOption":"B","correctAnswer":"Freshness is the need and the decorative bottle is the want","questionType":"MCQ","explanation":{"correct_reason":"A need is a basic requirement, such as oil that stays fresh, while a want is a specific way of satisfying it, such as a decorative bottle. The Athens shopper's freshness requirement is the need and the pretty bottle is the want, so option B is right.","distractor_reasons":{"A":"This reverses the two ideas. Keeping oil fresh is a fundamental requirement, whereas a decorative bottle is a particular preference for how that requirement is met, so the labels should be the other way around.","B":"A need is a basic requirement, such as oil that stays fresh, while a want is a specific way of satisfying it, such as a decorative bottle. The Athens shopper's freshness requirement is the need and the pretty bottle is the want, so option B is right.","C":"Simply asking for something does not make it a need. The decorative bottle is a desirable extra rather than a basic requirement, so treating both requests as needs is inaccurate.","D":"Cooking oil is a routine household purchase, and the shopper clearly expressed a genuine need for freshness. Dismissing both requests as luxuries ignores the distinction the scenario asks about."}}},{"id":"P1_U3_MCQ_1926","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1926","question":"Pinecrest Polling in Vancouver, Canada, completed 800 interviews about public transport and found that 288 respondents would use a new tram line. What percentage of those interviewed supported the tram?","options":{"A":"28.8%","B":"30%","C":"36%","D":"42%"},"correctOption":"C","correctAnswer":"36%","questionType":"MCQ","explanation":{"correct_reason":"The percentage supporting the tram is the number in favour divided by everyone interviewed, multiplied by 100. In Vancouver, 288 of 800 respondents supported it, so 288 divided by 800 equals 0.36, giving 36 per cent support.","distractor_reasons":{"A":"28.8 per cent comes from dividing 288 by 1,000 rather than by the 800 people actually interviewed. The correct denominator is 800, which yields 36 per cent.","B":"30 per cent would require 240 supporters out of 800 respondents. The Vancouver poll found 288 in favour, so this option understates support by 48 people.","C":"The percentage supporting the tram is the number in favour divided by everyone interviewed, multiplied by 100. In Vancouver, 288 of 800 respondents supported it, so 288 divided by 800 equals 0.36, giving 36 per cent support.","D":"42 per cent would mean 336 of the 800 respondents backed the tram. Since only 288 said they would use it, this figure is too high by 48 people."}}},{"id":"P1_U3_MCQ_1927","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1927","question":"Meridian Coffee Capsules in Rotterdam, Netherlands, places 'buy one, get one free' cards on supermarket shelves to encourage immediate purchases. Which element of the marketing mix does this activity belong to?","options":{"A":"Product","B":"Place","C":"Promotion","D":"Price"},"correctOption":"C","correctAnswer":"Promotion","questionType":"MCQ","explanation":{"correct_reason":"Promotion includes short-term incentives such as 'buy one, get one free' offers designed to stimulate quick sales. By putting these cards on supermarket shelves in Rotterdam, Meridian is using a sales promotion technique to attract shoppers.","distractor_reasons":{"A":"Product concerns the capsules' design, flavour and packaging. The free-offer cards do not change the coffee itself, so this activity is a selling incentive rather than a product decision.","B":"Place is about where and how the capsules are distributed. Although the cards sit in supermarkets, the 'buy one, get one free' message is a promotional tool, not a change to distribution.","C":"Promotion includes short-term incentives such as 'buy one, get one free' offers designed to stimulate quick sales. By putting these cards on supermarket shelves in Rotterdam, Meridian is using a sales promotion technique to attract shoppers.","D":"Price involves the amount charged for goods. While the offer affects value, a 'buy one, get one free' card is classified as a sales promotion activity within the promotion element."}}},{"id":"P1_U3_MCQ_1928","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1928","question":"Crimson Taxis operates 240,000 paid journeys a year in Mumbai, India. The city's total taxi market is estimated at 2,000,000 journeys a year. What is Crimson's market share in Mumbai?","options":{"A":"8.3%","B":"12%","C":"16.7%","D":"24%"},"correctOption":"B","correctAnswer":"12%","questionType":"MCQ","explanation":{"correct_reason":"Market share is the firm's sales divided by total market sales, multiplied by 100. Crimson provides 240,000 of Mumbai's 2,000,000 taxi journeys, so 240,000 divided by 2,000,000 equals 0.12, which is a 12 per cent share.","distractor_reasons":{"A":"8.3 per cent would come from dividing 240,000 by nearly 2.9 million journeys, not by the 2,000,000 rides in Mumbai. The stated market size must be used as the denominator.","B":"Market share is the firm's sales divided by total market sales, multiplied by 100. Crimson provides 240,000 of Mumbai's 2,000,000 taxi journeys, so 240,000 divided by 2,000,000 equals 0.12, which is a 12 per cent share.","C":"16.7 per cent would require about 334,000 journeys out of 2,000,000. Crimson's actual 240,000 journeys amount to only 12 per cent of the Mumbai market.","D":"24 per cent is double the correct share and would mean 480,000 journeys. The firm completes 240,000, so 12 per cent is the accurate figure."}}},{"id":"P1_U3_MCQ_1929","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1929","question":"Bluepeak Bottled Water in Gdansk, Poland, is studying its buyers and finds they are mostly teenagers who choose drinks mainly on price. In analysing this group, which question best identifies a customer need rather than a want?","options":{"A":"Which flavour do they like best?","B":"Do they require a drink that quenches thirst affordably?","C":"Which celebrity do they admire?","D":"What colour is their favourite bottle?"},"correctOption":"B","correctAnswer":"Do they require a drink that quenches thirst affordably?","questionType":"MCQ","explanation":{"correct_reason":"A need is a basic requirement, such as an affordable drink that quenches thirst. The other options describe specific preferences for flavour, celebrities or bottle colour, which are wants, so only the affordability and thirst question captures a genuine need.","distractor_reasons":{"A":"A preferred flavour is a particular way of satisfying thirst, so it is a want rather than a fundamental need. Teenagers may change flavours, but they still require a drink that refreshes them.","B":"A need is a basic requirement, such as an affordable drink that quenches thirst. The other options describe specific preferences for flavour, celebrities or bottle colour, which are wants, so only the affordability and thirst question captures a genuine need.","C":"Admiring a celebrity is a social preference unrelated to the basic purpose of bottled water. It cannot be a need for a drink and does not help Bluepeak identify what buyers fundamentally require.","D":"Bottle colour is a cosmetic preference and therefore a want. While it may influence choice, it does not address the underlying requirement for an affordable, thirst-quenching drink."}}},{"id":"P1_U3_MCQ_1930","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1930","question":"Lakeside Research is watching shoppers move through a supermarket in Kampala, Uganda, noting which shelves they stop at and which products they pick up, without asking any questions. Which data collection method is being used?","options":{"A":"A pilot study","B":"A questionnaire","C":"A focus group","D":"Observation"},"correctOption":"D","correctAnswer":"Observation","questionType":"MCQ","explanation":{"correct_reason":"Observation involves recording customers' behaviour as it happens without intervening or asking questions. By quietly watching which shelves shoppers visit in Kampala, Lakeside is gathering behavioural data through observation.","distractor_reasons":{"A":"A pilot study is a small trial of a research instrument before the main survey. The Kampala activity records actual shopping behaviour, so it is observation rather than a preliminary test.","B":"A questionnaire asks respondents a set of questions, either written or verbal. The researchers in the Kampala store ask nothing, so they are not collecting data through a questionnaire.","C":"A focus group brings participants together for a moderated discussion. No group discussion takes place here; the shoppers are simply being watched as they move around the store.","D":"Observation involves recording customers' behaviour as it happens without intervening or asking questions. By quietly watching which shelves shoppers visit in Kampala, Lakeside is gathering behavioural data through observation."}}},{"id":"P1_U3_MCQ_1931","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1931","question":"Thistle Chocolates in Edinburgh, United Kingdom, is launching a luxury box and has set a high introductory price, expecting keen buyers to pay more before the price is later reduced. Which pricing approach is being used?","options":{"A":"Penetration pricing","B":"Cost-plus pricing","C":"Loss leader pricing","D":"Price skimming"},"correctOption":"D","correctAnswer":"Price skimming","questionType":"MCQ","explanation":{"correct_reason":"Price skimming involves charging a high initial price to earn revenue from enthusiastic early buyers before lowering it later. Thistle is starting high for its Edinburgh luxury box and planning a later reduction, which matches skimming exactly.","distractor_reasons":{"A":"Penetration pricing sets a low price to win market share quickly. Thistle has done the opposite in Edinburgh by starting with a high price aimed at keen buyers, so this is not penetration.","B":"Cost-plus pricing adds a set margin to production costs. Nothing about Thistle's costs or a markup is mentioned; the emphasis is on a high introductory price for eager buyers.","C":"Loss leader pricing sells a product below cost to attract customers who will buy other items. The scenario describes a premium price for a luxury box, not a deliberate loss on one product.","D":"Price skimming involves charging a high initial price to earn revenue from enthusiastic early buyers before lowering it later. Thistle is starting high for its Edinburgh luxury box and planning a later reduction, which matches skimming exactly."}}},{"id":"P1_U3_MCQ_1932","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1932","question":"Nimbus Cloud Software in Bengaluru, India, offers one standard accounting package at the same low price to every customer, from small shops to large factories, with a single advert campaign. Which strategy is this?","options":{"A":"Niche marketing","B":"Concentrated marketing","C":"Differentiated marketing","D":"Mass marketing"},"correctOption":"D","correctAnswer":"Mass marketing","questionType":"MCQ","explanation":{"correct_reason":"Mass marketing, also called undifferentiated marketing, offers one product to the whole market with a single message. Nimbus sells the same Bengaluru package at one price with one campaign to all customer types, so it is using a mass approach.","distractor_reasons":{"A":"Niche marketing targets a small, specialised group. Selling a standard product to all comers is the reverse of a niche focus, so this option does not match the scenario.","B":"Concentrated marketing focuses on one specific segment. Nimbus is deliberately serving a wide range of customers rather than targeting small shops or factories alone, so concentration is not shown.","C":"Differentiated marketing creates separate offers for different segments. Since the Bengaluru firm uses one package and one campaign for everyone, it is not differentiating between customer groups.","D":"Mass marketing, also called undifferentiated marketing, offers one product to the whole market with a single message. Nimbus sells the same Bengaluru package at one price with one campaign to all customer types, so it is using a mass approach."}}},{"id":"P1_U3_MCQ_1933","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1933","question":"Marigold Spices in Colombo, Sri Lanka, sells 5,000 packets of cinnamon a month at $3.50 per packet. The owner wants the total monthly sales revenue from cinnamon. What is the monthly revenue?","options":{"A":"$1,750","B":"$3,500","C":"$17,500","D":"$35,000"},"correctOption":"C","correctAnswer":"$17,500","questionType":"MCQ","explanation":{"correct_reason":"Revenue equals the number of units sold multiplied by the price per unit. Marigold sells 5,000 packets in Colombo at $3.50 each, so 5,000 multiplied by $3.50 gives $17,500 of sales revenue each month.","distractor_reasons":{"A":"$1,750 is a tenth of the correct amount and would result from selling only 500 packets. The Colombo firm actually sells 5,000 packets a month.","B":"$3,500 is the price of 1,000 packets, not 5,000. Multiplying the full 5,000 packets by $3.50 gives $17,500 in monthly revenue.","C":"Revenue equals the number of units sold multiplied by the price per unit. Marigold sells 5,000 packets in Colombo at $3.50 each, so 5,000 multiplied by $3.50 gives $17,500 of sales revenue each month.","D":"$35,000 would require selling 10,000 packets at $3.50. With only 5,000 packets sold in Colombo, this overstates revenue by half. The scenario for Marigold Spices instead describes $17,500, which rules this alternative out."}}},{"id":"P1_U3_MCQ_1934","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1934","question":"Harborview Research in Valparaiso, Chile, sent 1,600 invitations to a taste test and 360 people attended. The manager wants the attendance rate for the invitations. What percentage of invitees attended?","options":{"A":"18%","B":"22.5%","C":"25%","D":"36%"},"correctOption":"B","correctAnswer":"22.5%","questionType":"MCQ","explanation":{"correct_reason":"Attendance rate is the number who attended divided by the number invited, multiplied by 100. In Valparaiso, 360 of 1,600 invitees came, so 360 divided by 1,600 equals 0.225, which is an attendance rate of 22.5 per cent.","distractor_reasons":{"A":"18 per cent would require 288 attendees out of 1,600 invitations. The actual number in Valparaiso was 360, so this understates attendance by 72 people.","B":"Attendance rate is the number who attended divided by the number invited, multiplied by 100. In Valparaiso, 360 of 1,600 invitees came, so 360 divided by 1,600 equals 0.225, which is an attendance rate of 22.5 per cent.","C":"25 per cent would mean 400 people attended. Since only 360 of the 1,600 invitees turned up, the true rate is slightly lower at 22.5 per cent.","D":"36 per cent confuses 360 attendees with a percentage. Dividing 360 by the 1,600 invitations sent in Valparaiso gives 22.5 per cent, not 36 per cent."}}},{"id":"P1_U3_MCQ_1935","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1935","question":"Tandem Bicycles in Lyon, France, is paying a local cycling club to wear its branded jerseys in regional races, hoping to raise awareness among riders. Which element of the marketing mix does this sponsorship belong to?","options":{"A":"Product","B":"Price","C":"Promotion","D":"Place"},"correctOption":"C","correctAnswer":"Promotion","questionType":"MCQ","explanation":{"correct_reason":"Promotion covers all communication used to build awareness and encourage purchases, including sponsorship. By funding a Lyon cycling club to wear its jerseys at races, Tandem is promoting its brand to potential customers.","distractor_reasons":{"A":"Product decisions concern the bicycles' design and quality. Sponsoring a club does not change the bikes themselves, so it is a communication activity rather than a product change.","B":"Price is about what customers pay for the bikes. The sponsorship payment in Lyon is money spent on promotion, not a change to the price charged to buyers.","C":"Promotion covers all communication used to build awareness and encourage purchases, including sponsorship. By funding a Lyon cycling club to wear its jerseys at races, Tandem is promoting its brand to potential customers.","D":"Place concerns distribution and where bicycles are sold. Wearing branded jerseys at races is not a distribution decision, so it does not belong to the place element."}}},{"id":"P1_U3_MCQ_1936","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1936","question":"Solace Mattresses in Gothenburg, Sweden, has saturated its home market and has begun selling the same mattresses to customers in Norway and Finland through local distributors. Which strategy is the firm pursuing?","options":{"A":"International marketing","B":"Mass marketing","C":"Concentrated targeting","D":"Product differentiation"},"correctOption":"A","correctAnswer":"International marketing","questionType":"MCQ","explanation":{"correct_reason":"International marketing involves promoting and selling a firm's products to customers in other countries. By exporting the same mattresses from Gothenburg to Norway and Finland via local distributors, Solace is pursuing an international strategy.","distractor_reasons":{"A":"International marketing involves promoting and selling a firm's products to customers in other countries. By exporting the same mattresses from Gothenburg to Norway and Finland via local distributors, Solace is pursuing an international strategy.","B":"Mass marketing means using one broad offer for the whole market. The key feature here is crossing national borders into Norway and Finland, so international marketing describes the move more precisely.","C":"Concentrated targeting focuses on one narrow customer segment. Solace is expanding geographically to several countries rather than narrowing its customer base, so this label does not fit.","D":"Product differentiation would require changing the mattress to make it distinct from rivals. The Gothenburg firm sells the same product abroad, so differentiation is not the strategy being described."}}},{"id":"P1_U3_MCQ_1937","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1937","question":"Cobaltpeak Bottled Water in Durban, South Africa, is reviewing the prices and quality of other drinks brands before deciding how to position its own product. What is this activity an example of?","options":{"A":"Competitor analysis","B":"Sales forecasting","C":"Market segmentation","D":"Distribution planning"},"correctOption":"A","correctAnswer":"Competitor analysis","questionType":"MCQ","explanation":{"correct_reason":"Competitor analysis is the assessment of rival firms' prices, products and quality to inform a business's own decisions. By examining other Durban drinks brands before positioning its water, Cobaltpeak is carrying out competitor analysis.","distractor_reasons":{"A":"Competitor analysis is the assessment of rival firms' prices, products and quality to inform a business's own decisions. By examining other Durban drinks brands before positioning its water, Cobaltpeak is carrying out competitor analysis.","B":"Sales forecasting predicts future sales from historical data or market trends. Looking at what rivals in Durban charge is not a numerical prediction of Cobaltpeak's own future sales.","C":"Market segmentation divides buyers into groups with shared characteristics. The firm is studying competitors rather than dividing its customers, so segmentation is not the activity here.","D":"Distribution planning decides how a product reaches customers. Comparing rivals' prices and quality in Durban does not involve choosing channels or outlets, so this option is unsuitable."}}},{"id":"P1_U3_MCQ_1938","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1938","question":"Cardinal Research in Krakow, Poland, includes survey questions that ask respondents to choose from a fixed list of answers, such as age bands and Yes or No choices. What kind of data will these questions mainly produce?","options":{"A":"Quantitative data","B":"Qualitative data","C":"Observation data","D":"Secondary data"},"correctOption":"A","correctAnswer":"Quantitative data","questionType":"MCQ","explanation":{"correct_reason":"Quantitative data is numerical and can be counted or statistically analysed. Fixed-choice answers like age bands and Yes or No responses in the Krakow survey generate numbers and categories that can be tallied, so they mainly produce quantitative data.","distractor_reasons":{"A":"Quantitative data is numerical and can be counted or statistically analysed. Fixed-choice answers like age bands and Yes or No responses in the Krakow survey generate numbers and categories that can be tallied, so they mainly produce quantitative data.","B":"Qualitative data captures opinions, feelings and descriptions in respondents' own words. Closed questions with set options do not collect rich narrative, so the results are not mainly qualitative.","C":"Observation data is gathered by watching behaviour rather than asking questions. The Krakow study uses a questionnaire with fixed answers, so it is not an observation method.","D":"Secondary data already exists from other sources. The fixed-choice questions are being asked directly by Cardinal, so the information is newly collected rather than secondary."}}},{"id":"P1_U3_MCQ_1939","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1939","question":"Juniper Jams in Tbilisi, Georgia, sells its preserves only through selected farmers' markets and independent delicatessens, refusing to supply large supermarket chains. Which aspect of the marketing mix is this decision about?","options":{"A":"Product","B":"Place","C":"Price","D":"Promotion"},"correctOption":"B","correctAnswer":"Place","questionType":"MCQ","explanation":{"correct_reason":"The place element covers distribution channels and the outlets through which a product reaches customers. By choosing only farmers' markets and independent delicatessens in Tbilisi, Juniper is making a selective distribution decision, which belongs to place.","distractor_reasons":{"A":"Product concerns the jam's recipe, jar and label. The choice of where to sell does not alter the preserve itself, so it is not a product decision even though the outlets may suggest a premium image.","B":"The place element covers distribution channels and the outlets through which a product reaches customers. By choosing only farmers' markets and independent delicatessens in Tbilisi, Juniper is making a selective distribution decision, which belongs to place.","C":"Price is about the amount charged to customers. Nothing in the Tbilisi scenario mentions the price of the jam, so the decision about which shops stock it is not a pricing matter.","D":"Promotion involves advertising and communication with buyers. Refusing to supply supermarkets is a distribution choice, not a message sent to customers, so place is the correct element."}}},{"id":"P1_U3_MCQ_1940","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1940","question":"Silverline Aviation in Doha, Qatar, carried 500,000 passengers last year. This year the total airline market in the city grew from 2,000,000 to 2,300,000 passengers. What was the percentage growth of the Doha market?","options":{"A":"46%","B":"23%","C":"30%","D":"15%"},"correctOption":"D","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Market growth is the rise in total demand divided by the original market size, multiplied by 100. The Doha market increased by 300,000 passengers from a base of 2,000,000, so 300,000 divided by 2,000,000 is 0.15, giving growth of 15 per cent.","distractor_reasons":{"A":"46 per cent confuses the 300,000 increase with a share of the final market. Growth is always measured against the starting figure of 2,000,000 in Doha, which yields 15 per cent.","B":"23 per cent would require an increase of 460,000 passengers on a base of 2,000,000. The actual rise to 2,300,000 is only 300,000 passengers, so this figure is too high.","C":"30 per cent comes from dividing 300,000 extra passengers by 1,000,000 rather than by the original 2,000,000 market. Using the correct base gives 15 per cent growth.","D":"Market growth is the rise in total demand divided by the original market size, multiplied by 100. The Doha market increased by 300,000 passengers from a base of 2,000,000, so 300,000 divided by 2,000,000 is 0.15, giving growth of 15 per cent."}}},{"id":"P1_U3_MCQ_1941","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1941","question":"Swiftclean Laundry in Manchester, United Kingdom, offers free next-day collection that no rival in the city provides, and customers say this is why they stay. What does this illustrate about the firm's position in the market?","options":{"A":"It has a competitive advantage","B":"It has a cost disadvantage","C":"It operates in a monopoly","D":"It is using loss-leading prices"},"correctOption":"A","correctAnswer":"It has a competitive advantage","questionType":"MCQ","explanation":{"correct_reason":"A competitive advantage exists when a firm offers something rivals do not, such as free next-day collection in Manchester. Because customers choose Swiftclean for this distinctive service, the business has an advantage over local competitors.","distractor_reasons":{"A":"A competitive advantage exists when a firm offers something rivals do not, such as free next-day collection in Manchester. Because customers choose Swiftclean for this distinctive service, the business has an advantage over local competitors.","B":"A cost disadvantage would mean the firm's costs are higher than rivals' without justification. The scenario highlights a valued service that attracts buyers, not an unfavourable cost position in Manchester.","C":"A monopoly requires a single supplier with no close substitutes. Many rival laundry services exist in the city, so Swiftclean is clearly not the only provider and cannot be described as a monopoly.","D":"Loss-leading prices involve selling below cost to attract buyers. The advantage described is a free collection service, not a below-cost price on the laundry itself, so this option is inaccurate."}}},{"id":"P1_U3_MCQ_1942","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1942","question":"Mekong Rice Mills in Can Tho, Vietnam, wants to know customer opinions but has 5,000 regular buyers. It questions 200 of them and uses their answers to represent the whole group. What is the 200-buyer group called?","options":{"A":"The population","B":"The sample","C":"The census","D":"The market"},"correctOption":"B","correctAnswer":"The sample","questionType":"MCQ","explanation":{"correct_reason":"A sample is the smaller group selected from a larger population to represent it. Mekong questions 200 of its 5,000 buyers in Can Tho and uses their views to stand for all customers, so those 200 people form the sample.","distractor_reasons":{"A":"The population is the entire group being studied, which here is all 5,000 regular buyers. The 200 questioned are only a part of that population, so they cannot be the population itself.","B":"A sample is the smaller group selected from a larger population to represent it. Mekong questions 200 of its 5,000 buyers in Can Tho and uses their views to stand for all customers, so those 200 people form the sample.","C":"A census would require gathering information from every one of the 5,000 buyers. Questioning just 200 customers in Can Tho falls far short of a complete census.","D":"The market refers to all potential buyers of a product, not the specific people surveyed. The 200 respondents are a research group drawn from the customer base, so 'sample' is the precise term."}}},{"id":"P1_U3_MCQ_1943","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1943","question":"Kestrel Electronics in Penang, Malaysia, has checked the prices charged by nearby retailers and set its own headphones at the same level as those rivals rather than higher or lower. Which pricing approach is this?","options":{"A":"Cost-plus pricing","B":"Penetration pricing","C":"Competitive pricing","D":"Price skimming"},"correctOption":"C","correctAnswer":"Competitive pricing","questionType":"MCQ","explanation":{"correct_reason":"Competitive pricing sets a price in line with what rivals charge. By matching the headphone prices of other Penang retailers rather than undercutting or premium-pricing them, Kestrel is following a competitive pricing approach.","distractor_reasons":{"A":"Cost-plus pricing adds a fixed percentage to production costs. No cost figures or markup are mentioned in the Penang scenario; the decision is based on matching what competitors charge.","B":"Penetration pricing uses a deliberately low introductory price to win customers. Kestrel sets its headphones at the same level as local rivals, so it is not trying to undercut them.","C":"Competitive pricing sets a price in line with what rivals charge. By matching the headphone prices of other Penang retailers rather than undercutting or premium-pricing them, Kestrel is following a competitive pricing approach.","D":"Price skimming charges a high initial price before later reductions. Matching competitors' ordinary prices in Penang is not an example of skimming the market at a premium."}}},{"id":"P1_U3_MCQ_1944","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1944","question":"Aster Appliances in Tunis, Tunisia, sold 45,000 blenders last year. Market research estimates the total blender market in the country at 300,000 units. What share of the Tunis blender market did Aster achieve?","options":{"A":"6.7%","B":"45%","C":"20%","D":"15%"},"correctOption":"D","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Market share is the business's own sales divided by total market sales, multiplied by 100. Aster sold 45,000 of the 300,000 blenders bought in Tunisia, so 45,000 divided by 300,000 is 0.15, giving a 15 per cent share.","distractor_reasons":{"A":"6.7 per cent would come from dividing 45,000 by about 675,000 units, not by the 300,000 blenders in the Tunis market. The total market figure given must be the denominator.","B":"45 per cent confuses the 45,000 units sold with a percentage. Since the whole Tunis market is 300,000 blenders, 45,000 units represent only 15 per cent of it.","C":"20 per cent would require Aster to sell 60,000 blenders out of 300,000. Its actual sales were 45,000, so this option overstates the share by 15,000 units.","D":"Market share is the business's own sales divided by total market sales, multiplied by 100. Aster sold 45,000 of the 300,000 blenders bought in Tunisia, so 45,000 divided by 300,000 is 0.15, giving a 15 per cent share."}}},{"id":"P1_U3_MCQ_1945","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1945","question":"A marketing lecturer in Valencia, Spain, explains that a market consists of more than just shops or adverts. Which definition of a market is correct?","options":{"A":"All places where goods are displayed","B":"Customers with a need, ability and willingness to pay","C":"The total spending on advertising","D":"Only the people who already bought a product"},"correctOption":"B","correctAnswer":"Customers with a need, ability and willingness to pay","questionType":"MCQ","explanation":{"correct_reason":"A market is made up of potential customers who have a need or want, the ability to pay and the willingness to buy. This definition captures why people in Valencia with a need and spending power form a market, unlike a physical shop or advertising total.","distractor_reasons":{"A":"A market is not simply the places where goods are displayed. Shops and stalls are retail outlets; the market itself is the group of buyers with needs and purchasing power.","B":"A market is made up of potential customers who have a need or want, the ability to pay and the willingness to buy. This definition captures why people in Valencia with a need and spending power form a market, unlike a physical shop or advertising total.","C":"Total advertising spending is a measure of promotional activity, not a market. It says nothing about the customers who have needs and the ability to satisfy them.","D":"A market includes potential buyers as well as existing purchasers. Limiting it to people who have already bought a product ignores those who could be attracted in future."}}},{"id":"P1_U3_MCQ_1946","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1946","question":"Cedar Research in Lima, Peru, spent $2,400 conducting 300 completed face-to-face interviews. The project manager needs the average cost per completed interview. What was the cost per interview?","options":{"A":"$6","B":"$8","C":"$12","D":"$24"},"correctOption":"B","correctAnswer":"$8","questionType":"MCQ","explanation":{"correct_reason":"Average cost per interview is total spending divided by the number of completed interviews. Cedar spent $2,400 in Lima on 300 interviews, so $2,400 divided by 300 gives $8 for each completed interview.","distractor_reasons":{"A":"$6 would mean the Lima research had cost only $1,800 for 300 interviews. The actual spend was $2,400, which raises the average to $8 per interview.","B":"Average cost per interview is total spending divided by the number of completed interviews. Cedar spent $2,400 in Lima on 300 interviews, so $2,400 divided by 300 gives $8 for each completed interview.","C":"$12 comes from dividing $2,400 by 200 instead of by the 300 interviews actually completed. Using the correct count gives an average cost of $8.","D":"$24 would be the cost if only 100 interviews had been finished. Since 300 were completed in Lima, the average cost is three times smaller at $8."}}},{"id":"P1_U3_MCQ_1947","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1947","question":"Halcyon Herbal Teas in Wellington, New Zealand, sells its teas exclusively through its own website and delivery service, with no physical shops. Which element of the marketing mix does this choice mainly concern?","options":{"A":"Product","B":"Price","C":"Place","D":"Promotion"},"correctOption":"C","correctAnswer":"Place","questionType":"MCQ","explanation":{"correct_reason":"Place covers the channels through which a product reaches customers. By selling only through its website and delivery service in Wellington, Halcyon has chosen an online distribution channel, which is a place decision.","distractor_reasons":{"A":"Product concerns the tea's ingredients and packaging. Selling online does not change the herbal tea itself, so the decision about channels belongs to place rather than product.","B":"Price is about what customers pay. The Wellington firm's choice of a website rather than shops is not a pricing decision, even though online selling might affect costs.","C":"Place covers the channels through which a product reaches customers. By selling only through its website and delivery service in Wellington, Halcyon has chosen an online distribution channel, which is a place decision.","D":"Promotion involves advertising and communication. Although the website may promote the brand, the key point is where customers buy the tea, which is the place element."}}},{"id":"P1_U3_MCQ_1948","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1948","question":"Orchid Cleaners in Osaka, Japan, gives loyalty cards, sends personalised offers and assigns an account manager to its regular business clients to keep them coming back. Which strategy is the firm applying?","options":{"A":"Product differentiation","B":"Mass marketing","C":"Concentrated targeting","D":"Relationship marketing"},"correctOption":"D","correctAnswer":"Relationship marketing","questionType":"MCQ","explanation":{"correct_reason":"Relationship marketing focuses on building long-term links with existing customers through loyalty rewards and personal attention. By using cards, tailored offers and an account manager in Osaka, Orchid is trying to retain clients rather than chase one-off sales.","distractor_reasons":{"A":"Product differentiation changes the offer to make it distinct from rivals'. The loyalty cards and account manager are retention tools, not alterations to the cleaning service itself.","B":"Mass marketing uses one broad message for a large audience. The personalised offers and dedicated manager in Osaka show the opposite: individual attention to particular customers.","C":"Concentrated targeting chooses one customer segment to serve. Orchid already has regular clients and is working to keep them, so the emphasis is on relationships rather than choosing a new segment.","D":"Relationship marketing focuses on building long-term links with existing customers through loyalty rewards and personal attention. By using cards, tailored offers and an account manager in Osaka, Orchid is trying to retain clients rather than chase one-off sales."}}},{"id":"P1_U3_MCQ_1949","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1949","question":"Tulip Tanning in Amsterdam, Netherlands, had 8,000 regular customers last year. A loyalty campaign raised this to 9,200 this year. What was the percentage increase in customer numbers?","options":{"A":"8%","B":"12%","C":"15%","D":"20%"},"correctOption":"C","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Percentage increase is the change in customers divided by the original number, multiplied by 100. Tulip grew from 8,000 to 9,200 in Amsterdam, a rise of 1,200, so 1,200 divided by 8,000 is 0.15, giving 15 per cent growth.","distractor_reasons":{"A":"8 per cent would mean an increase of only 640 customers on a base of 8,000. The Amsterdam firm actually gained 1,200 customers, so this is too low.","B":"12 per cent would require 960 extra customers. Because Tulip added 1,200 customers to its 8,000 base, the true rise is 15 per cent.","C":"Percentage increase is the change in customers divided by the original number, multiplied by 100. Tulip grew from 8,000 to 9,200 in Amsterdam, a rise of 1,200, so 1,200 divided by 8,000 is 0.15, giving 15 per cent growth.","D":"20 per cent would mean gaining 1,600 customers. With a rise of 1,200 from 8,000, the correct percentage increase is 15 per cent."}}},{"id":"P1_U3_MCQ_1950","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1950","question":"Redwood Research in Calgary, Canada, draws 100 names at random from a loyalty list of 4,000 before phoning them. What is this selection process an example of?","options":{"A":"Random sampling","B":"A census","C":"Observation","D":"Secondary research"},"correctOption":"A","correctAnswer":"Random sampling","questionType":"MCQ","explanation":{"correct_reason":"Random sampling gives every member of a population an equal chance of selection. By picking 100 names without bias from its 4,000 loyalty members in Calgary, Redwood is using random sampling to choose respondents.","distractor_reasons":{"A":"Random sampling gives every member of a population an equal chance of selection. By picking 100 names without bias from its 4,000 loyalty members in Calgary, Redwood is using random sampling to choose respondents.","B":"A census surveys every member of the group. Selecting only 100 of the 4,000 loyalty members in Calgary is far from a complete survey, so this cannot be a census.","C":"Observation records behaviour without asking questions. The Calgary firm is choosing people to phone, so the process described is sampling rather than observing shoppers.","D":"Secondary research uses data collected by others. Drawing names from its own loyalty list to contact customers is primary research preparation, not secondary research."}}},{"id":"P1_U3_MCQ_1951","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1951","question":"Ironbridge Tools in Birmingham, United Kingdom, employs sales representatives who visit hardware stores and demonstrate its drills face to face, taking orders on the spot. Which element of the marketing mix does this activity belong to?","options":{"A":"Price","B":"Place","C":"Promotion","D":"Product"},"correctOption":"C","correctAnswer":"Promotion","questionType":"MCQ","explanation":{"correct_reason":"Promotion includes personal selling, where representatives communicate directly with buyers to persuade them and take orders. By sending reps to demonstrate drills in Birmingham hardware stores, Ironbridge is carrying out personal selling, part of promotion.","distractor_reasons":{"A":"Price concerns the amount charged for the drills. Face-to-face demonstrations may mention a price, but the activity described is a selling and communication method, so price is not the central element.","B":"Place is about how goods reach customers, such as which stores stock them. The representatives are persuading existing Birmingham stores to order, so their activity is promotional rather than a distribution decision.","C":"Promotion includes personal selling, where representatives communicate directly with buyers to persuade them and take orders. By sending reps to demonstrate drills in Birmingham hardware stores, Ironbridge is carrying out personal selling, part of promotion.","D":"Product covers the drills' features and quality. The demonstration shows the product, but the focus is the direct selling conversation with store buyers, which belongs to promotion."}}},{"id":"P1_U3_MCQ_1952","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1952","question":"Quillpoint Printers in Guadalajara, Mexico, wants to achieve 12 per cent of a 250,000-unit printer market next year. How many printers must it sell to reach that share?","options":{"A":"12,000","B":"20,833","C":"30,000","D":"37,500"},"correctOption":"C","correctAnswer":"30,000","questionType":"MCQ","explanation":{"correct_reason":"Required sales equal the target share divided by 100, multiplied by total market size. Quillpoint aims for 12 per cent of Guadalajara's 250,000 printers, so 0.12 multiplied by 250,000 gives 30,000 units that must be sold.","distractor_reasons":{"A":"12,000 printers would be only 4.8 per cent of the 250,000-unit market. The target is 12 per cent, which requires selling considerably more than 12,000 units.","B":"20,833 units is roughly the result of dividing 250,000 by 12, which is not how a percentage share is calculated. Multiplying the market by 0.12 gives 30,000 printers.","C":"Required sales equal the target share divided by 100, multiplied by total market size. Quillpoint aims for 12 per cent of Guadalajara's 250,000 printers, so 0.12 multiplied by 250,000 gives 30,000 units that must be sold.","D":"37,500 printers would represent 15 per cent of the Guadalajara market. Since Quillpoint's goal is 12 per cent, the correct volume is 30,000 units."}}},{"id":"P1_U3_MCQ_1953","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1953","question":"A market analyst in Bratislava, Slovakia, notes that several firms sell almost identical shampoo at similar prices and shoppers switch brands easily. Which statement best describes competition in this market?","options":{"A":"Competition is weak because products differ","B":"Competition is strong because buyers can switch easily","C":"There is no competition as prices are fixed","D":"Competition only comes from foreign firms"},"correctOption":"B","correctAnswer":"Competition is strong because buyers can switch easily","questionType":"MCQ","explanation":{"correct_reason":"When many firms sell similar products at comparable prices and customers can change brands without difficulty, rivalry is intense. The Bratislava shampoo market shows low switching costs, so competition is strong among the sellers.","distractor_reasons":{"A":"The products in the Bratislava market are described as almost identical, not different. Similar offerings make it harder for any one firm to stand out, which increases rather than weakens competition.","B":"When many firms sell similar products at comparable prices and customers can change brands without difficulty, rivalry is intense. The Bratislava shampoo market shows low switching costs, so competition is strong among the sellers.","C":"Similar prices do not remove competition; they often reflect it. Shoppers in Bratislava can still choose between several brands, so it is wrong to claim that no competition exists.","D":"Competition comes from all rival sellers, whether local or foreign. The scenario describes several firms in the market and gives no reason to limit competitive pressure to overseas businesses."}}},{"id":"P1_U3_MCQ_1954","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1954","question":"Summit Fieldwork in Geneva, Switzerland, mailed 1,200 questionnaires to shoppers about public transport and received 324 completed forms back. The manager wants to report the survey's response rate. What was the response rate?","options":{"A":"36%","B":"32.4%","C":"27%","D":"41%"},"correctOption":"C","correctAnswer":"27%","questionType":"MCQ","explanation":{"correct_reason":"Response rate is completed questionnaires divided by those distributed, multiplied by 100. Summit sent 1,200 forms in Geneva and got 324 returned, so 324 divided by 1,200 equals 0.27, giving a response rate of 27 per cent.","distractor_reasons":{"A":"36 per cent would require 432 replies out of 1,200. Only 324 forms came back in Geneva, so this option overstates the response rate.","B":"32.4 per cent comes from dividing 324 by 1,000 rather than by the 1,200 questionnaires actually sent. The correct denominator gives a 27 per cent response rate.","C":"Response rate is completed questionnaires divided by those distributed, multiplied by 100. Summit sent 1,200 forms in Geneva and got 324 returned, so 324 divided by 1,200 equals 0.27, giving a response rate of 27 per cent.","D":"41 per cent would mean 492 questionnaires were returned. Since just 324 of the 1,200 were completed, the true rate is 27 per cent."}}},{"id":"P1_U3_MCQ_1955","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1955","question":"Orion Cinemas in Lisbon, Portugal, charges $6 for adults and $4 for students at the same screening of a film. Which pricing technique is the cinema using?","options":{"A":"Loss leader pricing","B":"Price skimming","C":"Price discrimination","D":"Cost-plus pricing"},"correctOption":"C","correctAnswer":"Price discrimination","questionType":"MCQ","explanation":{"correct_reason":"Price discrimination means charging different prices to different customer groups for the same product. Orion charges adults and students different amounts for the same Lisbon screening, so it is segmenting buyers by their willingness or ability to pay.","distractor_reasons":{"A":"Loss leader pricing sells an item below cost to attract other purchases. The student ticket at Lisbon is a reduced price, but the scenario gives no indication it is below cost or designed to sell extras.","B":"Price skimming sets a high initial price that falls over time. Charging two groups different prices at the same screening is not a time-based high-to-low strategy.","C":"Price discrimination means charging different prices to different customer groups for the same product. Orion charges adults and students different amounts for the same Lisbon screening, so it is segmenting buyers by their willingness or ability to pay.","D":"Cost-plus pricing adds a margin to the cost of providing a service. No cost figures are given; the distinction is between customer groups, which is price discrimination."}}},{"id":"P1_U3_MCQ_1956","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1956","question":"Cedar Grove Dairy in Winnipeg, Canada, already known for cheese, is launching a range of flavoured milk using the same well-known brand name and logo. What is this strategy called?","options":{"A":"Brand extension","B":"Mass marketing","C":"Price skimming","D":"Concentrated targeting"},"correctOption":"A","correctAnswer":"Brand extension","questionType":"MCQ","explanation":{"correct_reason":"A brand extension uses an established, trusted brand name to launch a new product category. By putting its recognised Winnipeg cheese brand on flavoured milk, Cedar Grove is extending the brand into a different product line.","distractor_reasons":{"A":"A brand extension uses an established, trusted brand name to launch a new product category. By putting its recognised Winnipeg cheese brand on flavoured milk, Cedar Grove is extending the brand into a different product line.","B":"Mass marketing uses a single broad offer aimed at everyone. The key feature in Winnipeg is the reuse of an established brand for a new item, not an undifferentiated appeal to the whole market.","C":"Price skimming involves a high introductory price. Nothing in the scenario mentions how the flavoured milk is priced, so this option is unrelated to the branding decision.","D":"Concentrated targeting focuses on one narrow segment. Cedar Grove is leveraging its brand name across products rather than selecting a specific group of buyers, so this does not fit."}}},{"id":"P1_U3_MCQ_1957","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1957","question":"Brightwell Ceramics in Porto, Portugal, sells 2,500 hand-painted vases a month to hotels and gift shops at $48 each. The owner wants to calculate total monthly sales from vases. What is the monthly revenue from vase sales?","options":{"A":"$12,000","B":"$48,000","C":"$120,000","D":"$250,000"},"correctOption":"C","correctAnswer":"$120,000","questionType":"MCQ","explanation":{"correct_reason":"Revenue equals price per unit multiplied by units sold. Brightwell sells 2,500 vases in Porto at $48 each, so 2,500 multiplied by $48 gives $120,000 of monthly revenue from vases.","distractor_reasons":{"A":"$12,000 would come from multiplying 250 vases by $48. The Porto firm actually sells 2,500 vases, ten times as many, so this figure is far too low.","B":"$48,000 is the price of 1,000 vases. With 2,500 sold in Porto at $48 each, the true monthly revenue is $120,000.","C":"Revenue equals price per unit multiplied by units sold. Brightwell sells 2,500 vases in Porto at $48 each, so 2,500 multiplied by $48 gives $120,000 of monthly revenue from vases.","D":"$250,000 comes from multiplying 2,500 vases by $100 instead of $48. Using the stated price of $48 gives $120,000. In Brightwell Ceramics's case, the correct description is $120,000, not this choice."}}},{"id":"P1_U3_MCQ_1958","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1958","question":"A research team in Lusaka, Zambia, is deciding whether to question all 20,000 students at a university or just 500 of them. Which is the main advantage of using 500 students instead of the full population?","options":{"A":"It gives more accurate results","B":"It is quicker and cheaper","C":"It removes sampling error","D":"It guarantees every view is heard"},"correctOption":"B","correctAnswer":"It is quicker and cheaper","questionType":"MCQ","explanation":{"correct_reason":"A sample of 500 is smaller than surveying all 20,000 students, so it takes less time and costs less to collect and analyse. The main practical advantage of sampling in Lusaka is speed and lower cost, not perfect accuracy.","distractor_reasons":{"A":"A larger survey usually gives more accurate results, so a sample of 500 is not chosen for greater accuracy. It is a trade-off that saves time and money at the expense of some precision.","B":"A sample of 500 is smaller than surveying all 20,000 students, so it takes less time and costs less to collect and analyse. The main practical advantage of sampling in Lusaka is speed and lower cost, not perfect accuracy.","C":"Sampling cannot remove error; in fact, a sample introduces sampling error because not every student is asked. Claiming it removes error is incorrect.","D":"Questioning only 500 students means the views of the other 19,500 are not heard directly. A sample cannot guarantee that every individual view is captured."}}},{"id":"P1_U3_MCQ_1959","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1959","question":"Meadow Snacks in Cork, Ireland, is adding small single-serve bags alongside its family-sized packs of popcorn. Which element of the marketing mix is this change mainly about?","options":{"A":"Product","B":"Price","C":"Place","D":"Promotion"},"correctOption":"A","correctAnswer":"Product","questionType":"MCQ","explanation":{"correct_reason":"Product decisions include the range of sizes and forms a good is offered in. By introducing single-serve bags in Cork as well as family packs, Meadow is widening its product range, which is a product decision.","distractor_reasons":{"A":"Product decisions include the range of sizes and forms a good is offered in. By introducing single-serve bags in Cork as well as family packs, Meadow is widening its product range, which is a product decision.","B":"Price concerns what customers pay. Although the small bags may have a different price, the change described is the addition of a new pack size, which belongs to the product element.","C":"Place is about distribution and where snacks are sold. Adding a single-serve option in Cork does not change the outlets or channels used, so it is not a place decision.","D":"Promotion communicates with customers through adverts and offers. The new bag size is a change to what is sold rather than a message, so the correct element is product."}}},{"id":"P1_U3_MCQ_1960","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1960","question":"Ridgeway Cycling in Sheffield, United Kingdom, saw total city cycle sales rise from 60,000 to 75,000 units in a year. What was the percentage growth in the market?","options":{"A":"15%","B":"20%","C":"25%","D":"75%"},"correctOption":"C","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"Market growth is the increase in sales divided by the original market size, multiplied by 100. Sheffield sales rose by 15,000 from a base of 60,000 units, so 15,000 divided by 60,000 is 0.25, giving growth of 25 per cent.","distractor_reasons":{"A":"15 per cent would require an increase of 9,000 units on a base of 60,000. The actual rise in Sheffield was 15,000 cycles, so this figure is too low.","B":"20 per cent would mean the market grew to 72,000 units. Since sales reached 75,000, the increase is larger, at 25 per cent.","C":"Market growth is the increase in sales divided by the original market size, multiplied by 100. Sheffield sales rose by 15,000 from a base of 60,000 units, so 15,000 divided by 60,000 is 0.25, giving growth of 25 per cent.","D":"75 per cent confuses the final sales total of 75,000 with a growth rate. Growth is the change from 60,000, which is 15,000 units or 25 per cent."}}},{"id":"P1_U3_MCQ_1961","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1961","question":"Sunline Ski Wear in Bilbao, Spain, has decided to make lightweight jackets for families going on winter holidays, rather than for professional athletes. Which term describes the group of buyers the firm has chosen to serve?","options":{"A":"The internal market","B":"The mass market","C":"The wholesaler market","D":"The target market"},"correctOption":"D","correctAnswer":"The target market","questionType":"MCQ","explanation":{"correct_reason":"A target market is the specific group of customers a business chooses to aim its products at. By focusing on families taking winter holidays in Bilbao instead of professional athletes, Sunline has identified its target market.","distractor_reasons":{"A":"There is no such thing as an 'internal market' for outside customers. The families in Bilbao are external buyers, so this invented term cannot describe them.","B":"The mass market means aiming at all customers with one broad offer. Sunline has deliberately selected holidaying families rather than everyone who buys ski wear, so it is not a mass market approach.","C":"A wholesaler market would involve selling to intermediaries who resell goods. The scenario describes which end buyers the jackets are designed for, not the channel used to distribute them.","D":"A target market is the specific group of customers a business chooses to aim its products at. By focusing on families taking winter holidays in Bilbao instead of professional athletes, Sunline has identified its target market."}}},{"id":"P1_U3_MCQ_1962","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1962","question":"A research team in Ghent, Belgium, asks shoppers to describe in their own words why they stopped buying a brand, using questions with no fixed answer choices. What kind of information will this mainly generate?","options":{"A":"Qualitative data","B":"Quantitative data","C":"Secondary data","D":"Observation data"},"correctOption":"A","correctAnswer":"Qualitative data","questionType":"MCQ","explanation":{"correct_reason":"Qualitative data consists of words, opinions and explanations rather than numbers. By letting Ghent shoppers answer freely about why they stopped buying, the team collects detailed views and feelings, which is qualitative information.","distractor_reasons":{"A":"Qualitative data consists of words, opinions and explanations rather than numbers. By letting Ghent shoppers answer freely about why they stopped buying, the team collects detailed views and feelings, which is qualitative information.","B":"Quantitative data is numerical and counted. Open-ended answers in Ghent produce descriptions rather than tallyable figures, so the results are not mainly quantitative.","C":"Secondary data already exists from other sources. The researchers are gathering new views directly from shoppers, so the information is primary rather than secondary.","D":"Observation records behaviour without asking questions. Here shoppers are being asked to explain their reasons, so the method is not observation."}}},{"id":"P1_U3_MCQ_1963","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1963","question":"Willowbrook Foods in Norwich, United Kingdom, sells its baked beans through wholesalers and supermarkets rather than directly from its factory. Which element of the marketing mix does this arrangement mainly concern?","options":{"A":"Product","B":"Price","C":"Place","D":"Promotion"},"correctOption":"C","correctAnswer":"Place","questionType":"MCQ","explanation":{"correct_reason":"The place element covers distribution channels used to get goods to customers. By supplying wholesalers and supermarkets in Norwich rather than selling from the factory, Willowbrook is making a place or distribution decision.","distractor_reasons":{"A":"Product concerns the beans' recipe, can and label. Using wholesalers does not change the baked beans themselves, so the arrangement is not a product decision.","B":"Price is about the amount charged to buyers. The Norwich firm's use of intermediaries is not a pricing matter, even though it may affect final costs.","C":"The place element covers distribution channels used to get goods to customers. By supplying wholesalers and supermarkets in Norwich rather than selling from the factory, Willowbrook is making a place or distribution decision.","D":"Promotion involves advertising and sales messages. Choosing wholesalers and supermarkets is about how beans reach shoppers, which belongs to place rather than communication."}}},{"id":"P1_U3_MCQ_1964","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1964","question":"Kestrel Kettles in Prague, Czech Republic, sold 12,000 kettles last year in a total national market of 80,000 units. What was the firm's market share for that year?","options":{"A":"8%","B":"12%","C":"15%","D":"20%"},"correctOption":"C","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Market share is the firm's sales divided by total market sales, multiplied by 100. Kestrel sold 12,000 of the 80,000 kettles bought in the Czech market, so 12,000 divided by 80,000 is 0.15, giving a 15 per cent share.","distractor_reasons":{"A":"8 per cent would require Kestrel to sell only 6,400 kettles out of 80,000. Actual sales were 12,000, so this option understates the share considerably.","B":"12 per cent comes from confusing the 12,000 units sold with a percentage. Dividing 12,000 by the 80,000-unit market gives 15 per cent.","C":"Market share is the firm's sales divided by total market sales, multiplied by 100. Kestrel sold 12,000 of the 80,000 kettles bought in the Czech market, so 12,000 divided by 80,000 is 0.15, giving a 15 per cent share.","D":"20 per cent would mean selling 16,000 kettles. Kestrel's 12,000 sales represent 15 per cent of the Prague market, not a fifth of it."}}},{"id":"P1_U3_MCQ_1965","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1965","question":"A hotel chain in Nice, France, is reviewing how it approaches its customers. Which statement best describes the central idea of marketing in a business such as this hotel chain?","options":{"A":"Selling as much output as the hotel can produce","B":"Identifying customer needs and satisfying them profitably","C":"Reducing the cost of every hotel service","D":"Opening as many hotels as possible"},"correctOption":"B","correctAnswer":"Identifying customer needs and satisfying them profitably","questionType":"MCQ","explanation":{"correct_reason":"Marketing is about finding out what customers want and then providing it in a way that earns a profit. For a hotel chain in Nice, this means understanding guests' needs and meeting them profitably, rather than simply maximising output or size.","distractor_reasons":{"A":"Selling all available output describes a sales or production focus, not marketing. A hotel chain in Nice that ignores guest needs may fill rooms briefly but will not build lasting demand.","B":"Marketing is about finding out what customers want and then providing it in a way that earns a profit. For a hotel chain in Nice, this means understanding guests' needs and meeting them profitably, rather than simply maximising output or size.","C":"Cutting costs is an operations or finance concern. Lower costs alone do not identify what customers want, so cost reduction is not the central idea of marketing.","D":"Opening many hotels is a growth decision, not the essence of marketing. Expansion without understanding customer needs in Nice would not guarantee that the new hotels attract guests."}}},{"id":"P1_U3_MCQ_1966","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1966","question":"A survey in Antananarivo, Madagascar, asked 1,000 households which brand of rice they buy. If 250 named the same local brand, what percentage of households chose it?","options":{"A":"20%","B":"25%","C":"30%","D":"40%"},"correctOption":"B","correctAnswer":"25%","questionType":"MCQ","explanation":{"correct_reason":"The percentage choosing the brand is the number of households that named it divided by the total surveyed, multiplied by 100. In Antananarivo, 250 of 1,000 households chose the local rice, so 250 divided by 1,000 is 0.25, or 25 per cent.","distractor_reasons":{"A":"20 per cent would mean only 200 of the 1,000 households picked the brand. The survey recorded 250 choices, so the correct share is 25 per cent.","B":"The percentage choosing the brand is the number of households that named it divided by the total surveyed, multiplied by 100. In Antananarivo, 250 of 1,000 households chose the local rice, so 250 divided by 1,000 is 0.25, or 25 per cent.","C":"30 per cent would require 300 households to name the local rice. Since 250 did so in Antananarivo, this figure overstates the brand's share.","D":"40 per cent would mean 400 households chose the brand. With only 250 out of 1,000 doing so, the true figure is 25 per cent."}}},{"id":"P1_U3_MCQ_1967","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1967","question":"Larkspur Fragrances in Grasse, France, is paying a well-known actress to appear in its perfume campaign, hoping buyers will associate the product with her style. Which element of the marketing mix is this?","options":{"A":"Product","B":"Price","C":"Place","D":"Promotion"},"correctOption":"D","correctAnswer":"Promotion","questionType":"MCQ","explanation":{"correct_reason":"Celebrity endorsement is a promotional tool used to build brand image and attract attention. By paying an actress to front its perfume campaign in Grasse, Larkspur is communicating with customers, which belongs to the promotion element.","distractor_reasons":{"A":"Product decisions concern the perfume's scent and bottle. The actress does not change the fragrance itself, so the campaign is a communication activity rather than a product change.","B":"Price is about what customers pay for the perfume. No pricing change is described in Grasse; the spend on an actress is money used to promote the brand.","C":"Place concerns where the perfume is sold. An endorsement campaign is not a distribution decision, so it does not belong to the place element.","D":"Celebrity endorsement is a promotional tool used to build brand image and attract attention. By paying an actress to front its perfume campaign in Grasse, Larkspur is communicating with customers, which belongs to the promotion element."}}},{"id":"P1_U3_MCQ_1968","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1968","question":"Fable Guitars in Cremona, Italy, makes specialist instruments only for left-handed classical guitarists, a small group ignored by most large manufacturers. Which strategy is the firm following?","options":{"A":"Niche marketing","B":"Mass marketing","C":"Differentiated marketing","D":"International marketing"},"correctOption":"A","correctAnswer":"Niche marketing","questionType":"MCQ","explanation":{"correct_reason":"Niche marketing concentrates on a small, specialised group of customers with particular needs. By serving only left-handed classical guitarists in Cremona, Fable is focusing on a narrow segment that bigger firms overlook.","distractor_reasons":{"A":"Niche marketing concentrates on a small, specialised group of customers with particular needs. By serving only left-handed classical guitarists in Cremona, Fable is focusing on a narrow segment that bigger firms overlook.","B":"Mass marketing targets the whole market with one offer. Fable is deliberately serving a tiny specialist group, so a mass approach does not describe its strategy.","C":"Differentiated marketing offers separate mixes to several segments. The Cremona firm focuses on one narrow group of guitarists, so it is not pursuing several segments at once.","D":"International marketing involves selling across national borders. The scenario describes a specialist customer group, not expansion into other countries, so this label is not appropriate."}}},{"id":"P1_U3_MCQ_1969","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1969","question":"Okavango Crafts in Windhoek, Namibia, sells 800 handwoven baskets a month to tourists at $25 each. The manager wants the total monthly sales figure. What is the total monthly revenue from basket sales?","options":{"A":"$2,000","B":"$20,000","C":"$25,000","D":"$200,000"},"correctOption":"B","correctAnswer":"$20,000","questionType":"MCQ","explanation":{"correct_reason":"Revenue equals the number of units sold multiplied by the price per unit. Okavango sells 800 baskets in Windhoek at $25 each, so 800 multiplied by $25 gives $20,000 of monthly revenue from baskets.","distractor_reasons":{"A":"$2,000 would result from selling only 80 baskets. The Windhoek firm actually sells 800, ten times as many, so the revenue is much higher.","B":"Revenue equals the number of units sold multiplied by the price per unit. Okavango sells 800 baskets in Windhoek at $25 each, so 800 multiplied by $25 gives $20,000 of monthly revenue from baskets.","C":"$25,000 comes from multiplying 1,000 baskets by $25. Since only 800 were sold, the correct monthly revenue is $20,000. The details given about Okavango Crafts support $20,000, so this answer is unsuitable.","D":"$200,000 is ten times the true amount and would require selling 8,000 baskets. With 800 sold at $25, revenue is $20,000."}}},{"id":"P1_U3_MCQ_1970","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1970","question":"Vantage Motors in Stuttgart, Germany, is assessing demand by looking at the company's own records of past sales and customer complaints, collected over five years. What type of data is being used?","options":{"A":"Qualitative interview data","B":"External primary data","C":"Observation data","D":"Internal secondary data"},"correctOption":"D","correctAnswer":"Internal secondary data","questionType":"MCQ","explanation":{"correct_reason":"Internal secondary data is information already collected within the business for another purpose. By reviewing its own past sales and complaint records in Stuttgart, Vantage is reusing existing internal data rather than gathering fresh information.","distractor_reasons":{"A":"Qualitative interview data comes from spoken conversations. Sales totals and complaint records are existing documents, not interview transcripts, so this category does not fit.","B":"External primary data would be new information collected from outside the firm. The records in Stuttgart are held inside Vantage and were collected earlier, so they are not external primary data.","C":"Observation involves watching behaviour as it occurs. Looking through old sales files is not observing customers, so this option is not relevant.","D":"Internal secondary data is information already collected within the business for another purpose. By reviewing its own past sales and complaint records in Stuttgart, Vantage is reusing existing internal data rather than gathering fresh information."}}},{"id":"P1_U3_MCQ_1971","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1971","question":"Aurelia Watches in Geneva, Switzerland, prices its gold watches far above similar rivals because it believes buyers associate a high price with high quality and status. Which pricing approach is this?","options":{"A":"Premium pricing","B":"Penetration pricing","C":"Loss leader pricing","D":"Competitive pricing"},"correctOption":"A","correctAnswer":"Premium pricing","questionType":"MCQ","explanation":{"correct_reason":"Premium pricing sets a deliberately high price to signal quality and exclusivity. Aurelia is pricing its Geneva watches above comparable rivals because customers link a high price with status, which is exactly a premium pricing approach.","distractor_reasons":{"A":"Premium pricing sets a deliberately high price to signal quality and exclusivity. Aurelia is pricing its Geneva watches above comparable rivals because customers link a high price with status, which is exactly a premium pricing approach.","B":"Penetration pricing uses a low introductory price to win market share. Setting a high price in Geneva to convey prestige is the opposite of undercutting rivals.","C":"Loss leader pricing sells below cost to attract other purchases. The watches are priced far above rivals, not below cost, so this technique does not apply.","D":"Competitive pricing matches what other firms charge. Aurelia is deliberately setting a higher price than similar watches in Geneva, so it is not matching competitors."}}},{"id":"P1_U3_MCQ_1972","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1972","question":"Andes Textiles in Bogota, Colombia, saw the total market for woven fabrics grow from 120,000 to 138,000 metres in a year. What was the percentage growth of the market?","options":{"A":"13.8%","B":"15%","C":"18%","D":"20%"},"correctOption":"B","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Market growth is the increase in demand divided by the original market size, multiplied by 100. The Bogota fabric market rose by 18,000 metres from a base of 120,000, so 18,000 divided by 120,000 is 0.15, giving 15 per cent growth.","distractor_reasons":{"A":"13.8 per cent comes from dividing the 18,000 extra metres by the final total of 138,000 rather than by the original 120,000. Growth must be measured against the starting figure.","B":"Market growth is the increase in demand divided by the original market size, multiplied by 100. The Bogota fabric market rose by 18,000 metres from a base of 120,000, so 18,000 divided by 120,000 is 0.15, giving 15 per cent growth.","C":"18 per cent confuses the 18,000-metre increase with a percentage. Since the original Bogota market was 120,000 metres, that rise equals 15 per cent.","D":"20 per cent would require an increase of 24,000 metres. The actual rise in Bogota was 18,000, so the growth rate is 15 per cent."}}},{"id":"P1_U3_MCQ_1973","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1973","question":"Silk Road Linens in Samarkand, Uzbekistan, competes by offering higher-quality stitching and a wider choice of colours rather than by charging less than rivals. What form of competition is the firm using?","options":{"A":"Price competition","B":"Non-price competition","C":"Monopoly competition","D":"Cost competition"},"correctOption":"B","correctAnswer":"Non-price competition","questionType":"MCQ","explanation":{"correct_reason":"Non-price competition means attracting customers through features other than price, such as quality and range. By stressing superior stitching and more colours in Samarkand, Silk Road Linens is competing on factors other than being cheapest.","distractor_reasons":{"A":"Price competition involves trying to undercut rivals' prices. The Samarkand firm is not cutting prices; it is emphasising stitching quality and colour choice, so this is not price competition.","B":"Non-price competition means attracting customers through features other than price, such as quality and range. By stressing superior stitching and more colours in Samarkand, Silk Road Linens is competing on factors other than being cheapest.","C":"Monopoly competition is not a meaningful term because a monopoly has no rivals to compete with. The scenario describes several firms competing, so it cannot be a monopoly.","D":"Cost competition means trying to produce more cheaply than rivals in order to offer low prices. The emphasis in Samarkand is on higher quality, not on reducing costs."}}},{"id":"P1_U3_MCQ_1974","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1974","question":"Baobab Polls in Dakar, Senegal, sent 2,500 survey forms to households about shopping habits and received 550 completed returns. The analyst needs to report the response rate. What was the response rate for this survey?","options":{"A":"18%","B":"22%","C":"25%","D":"55%"},"correctOption":"B","correctAnswer":"22%","questionType":"MCQ","explanation":{"correct_reason":"Response rate is the number of completed forms divided by the number sent out, multiplied by 100. Baobab received 550 returns from 2,500 forms in Dakar, so 550 divided by 2,500 equals 0.22, giving a response rate of 22 per cent.","distractor_reasons":{"A":"18 per cent would require 450 completed forms out of 2,500. The Dakar survey returned 550, so this figure understates the response rate.","B":"Response rate is the number of completed forms divided by the number sent out, multiplied by 100. Baobab received 550 returns from 2,500 forms in Dakar, so 550 divided by 2,500 equals 0.22, giving a response rate of 22 per cent.","C":"25 per cent would mean 625 of the 2,500 forms were completed. Since only 550 came back, the correct rate is 22 per cent.","D":"55 per cent confuses the 550 returns with a percentage. Dividing 550 by the 2,500 forms sent in Dakar gives 22 per cent, not 55 per cent."}}},{"id":"P1_U3_MCQ_1975","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1975","question":"Crest Bakery in Belfast, United Kingdom, allows independent shopkeepers to trade under its name and sell its bread in return for a fee and a share of sales. Which element of the marketing mix does this arrangement mainly concern?","options":{"A":"Product","B":"Place","C":"Price","D":"Promotion"},"correctOption":"B","correctAnswer":"Place","questionType":"MCQ","explanation":{"correct_reason":"The place element includes distribution channels and methods of reaching customers, such as franchising independent outlets. By letting shopkeepers in Belfast sell its bread under its name, Crest is choosing how the product reaches buyers, which is a place decision.","distractor_reasons":{"A":"Product concerns the bread's recipe and packaging. The franchise arrangement does not change the loaf itself, so the decision is about distribution rather than the product.","B":"The place element includes distribution channels and methods of reaching customers, such as franchising independent outlets. By letting shopkeepers in Belfast sell its bread under its name, Crest is choosing how the product reaches buyers, which is a place decision.","C":"Price is about what customers pay for the bread. Although a fee is paid by shopkeepers, the main point is the channel used to sell, which belongs to place.","D":"Promotion involves advertising and communication. Trading under Crest's name may build awareness, but the core arrangement is about where and how the bread is sold."}}},{"id":"P1_U3_MCQ_1976","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1976","question":"Titan Cleaning in Montreal, Canada, already has the largest share of the office-cleaning market and is spending heavily on advertising to keep its leading position. Which role is the firm playing in the market?","options":{"A":"Market leader","B":"Market follower","C":"Niche operator","D":"New entrant"},"correctOption":"A","correctAnswer":"Market leader","questionType":"MCQ","explanation":{"correct_reason":"A market leader is the firm with the largest share that defends its position through heavy promotion and investment. Titan already holds the biggest office-cleaning share in Montreal and is advertising strongly to keep it, so it is acting as the market leader.","distractor_reasons":{"A":"A market leader is the firm with the largest share that defends its position through heavy promotion and investment. Titan already holds the biggest office-cleaning share in Montreal and is advertising strongly to keep it, so it is acting as the market leader.","B":"A market follower copies the leader rather than defending a dominant share. Titan has the largest share in Montreal and is investing to maintain it, so it is not following another firm.","C":"A niche operator serves a narrow segment. The scenario describes the widest share of the whole Montreal office-cleaning market, not a restricted niche.","D":"A new entrant has just joined the market. Titan is already established with the leading share, so it cannot be described as a newcomer."}}},{"id":"P1_U3_MCQ_1977","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1977","question":"Linden Furniture in Ljubljana, Slovenia, buys wood and fabric costing $6 for each chair and sells the finished chair for $15. What is the value added per chair?","options":{"A":"$6","B":"$9","C":"$15","D":"$21"},"correctOption":"B","correctAnswer":"$9","questionType":"MCQ","explanation":{"correct_reason":"Value added per unit is the selling price minus the cost of bought-in materials. Linden sells each chair in Ljubljana for $15 after spending $6 on wood and fabric, so $15 minus $6 gives $9 of value added per chair.","distractor_reasons":{"A":"$6 is the material cost, not the value added. Added value is what the business contributes through its own work, which is the gap between the $15 price and the $6 cost.","B":"Value added per unit is the selling price minus the cost of bought-in materials. Linden sells each chair in Ljubljana for $15 after spending $6 on wood and fabric, so $15 minus $6 gives $9 of value added per chair.","C":"$15 is the full selling price, not the added value. The $6 spent on wood and fabric must be subtracted to find what Linden itself adds.","D":"$21 comes from adding the $15 price to the $6 cost. Value added is a difference between price and input cost, never their sum."}}},{"id":"P1_U3_MCQ_1978","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1978","question":"A researcher in Tallinn, Estonia, sits down with one shopper at a time and asks detailed follow-up questions about their buying habits, letting the conversation develop naturally. Which research method is being used?","options":{"A":"An in-depth interview","B":"A questionnaire","C":"An experiment","D":"A census"},"correctOption":"A","correctAnswer":"An in-depth interview","questionType":"MCQ","explanation":{"correct_reason":"An in-depth interview is a one-to-one conversation where a researcher explores a respondent's views with flexible follow-up questions. The Tallinn researcher is doing exactly this with individual shoppers, so the method is an in-depth interview.","distractor_reasons":{"A":"An in-depth interview is a one-to-one conversation where a researcher explores a respondent's views with flexible follow-up questions. The Tallinn researcher is doing exactly this with individual shoppers, so the method is an in-depth interview.","B":"A questionnaire uses a fixed set of questions, often written and self-completed. The Tallinn conversations are flexible and spoken, so they are not a standard questionnaire.","C":"An experiment changes one factor to measure its effect on another. The researcher is simply asking questions about habits, not manipulating any variable.","D":"A census would survey every member of a population. Interviewing shoppers one at a time in Tallinn is not an attempt to reach the entire population."}}},{"id":"P1_U3_MCQ_1979","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1979","question":"Beacon Foods in Galway, Ireland, issues press releases and holds open days to build goodwill and a positive public image rather than paying for adverts. Which element of the marketing mix does this activity mainly belong to?","options":{"A":"Product","B":"Price","C":"Place","D":"Promotion"},"correctOption":"D","correctAnswer":"Promotion","questionType":"MCQ","explanation":{"correct_reason":"Promotion includes public relations activities such as press releases and open days that build a favourable image. By using these methods in Galway instead of paid adverts, Beacon is communicating with the public, which is part of promotion.","distractor_reasons":{"A":"Product concerns the food's ingredients and packaging. Press releases and open days do not change the product itself, so this is a communication activity.","B":"Price is about what customers pay. The Galway firm's public relations work does not set or change prices, so it is not a pricing decision.","C":"Place concerns distribution and where food is sold. Building goodwill through open days is not about channels or outlets, so the place element is not involved.","D":"Promotion includes public relations activities such as press releases and open days that build a favourable image. By using these methods in Galway instead of paid adverts, Beacon is communicating with the public, which is part of promotion."}}},{"id":"P1_U3_MCQ_1980","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1980","question":"Sava Appliances in Belgrade, Serbia, sold 36,000 refrigerators last year in a national market totalling 240,000 units. The marketing team wants its share of the market. What share of the market did it achieve?","options":{"A":"12%","B":"15%","C":"24%","D":"36%"},"correctOption":"B","correctAnswer":"15%","questionType":"MCQ","explanation":{"correct_reason":"Market share is the business's sales divided by total market sales, multiplied by 100. Sava sold 36,000 of the 240,000 refrigerators bought in Serbia, so 36,000 divided by 240,000 is 0.15, giving a 15 per cent share.","distractor_reasons":{"A":"12 per cent would require Sava to sell only 28,800 refrigerators out of 240,000. Its actual sales were 36,000, so this option understates the share.","B":"Market share is the business's sales divided by total market sales, multiplied by 100. Sava sold 36,000 of the 240,000 refrigerators bought in Serbia, so 36,000 divided by 240,000 is 0.15, giving a 15 per cent share.","C":"24 per cent comes from confusing the 240,000-unit market size with a percentage. Dividing 36,000 by 240,000 gives 15 per cent.","D":"36 per cent mistakes the 36,000 units sold for a share. Since the whole Serbian market is 240,000 refrigerators, Sava's share is 15 per cent."}}},{"id":"P1_U3_MCQ_1981","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1981","question":"A marketing consultant in Valletta, Malta, tells a client that every marketing decision should start with the same activity. What is the correct starting point for the marketing process?","options":{"A":"Setting the advertising budget","B":"Understanding customer needs","C":"Choosing a factory location","D":"Hiring sales staff"},"correctOption":"B","correctAnswer":"Understanding customer needs","questionType":"MCQ","explanation":{"correct_reason":"Marketing begins by identifying what customers need and want, because all later decisions about products and promotion depend on that understanding. The consultant in Valletta is therefore right to put customer needs before budgets, locations or staffing.","distractor_reasons":{"A":"Setting an advertising budget comes after the firm knows what customers want and what message to send. In Valletta, choosing a budget first would risk spending money on a message that does not address customer needs.","B":"Marketing begins by identifying what customers need and want, because all later decisions about products and promotion depend on that understanding. The consultant in Valletta is therefore right to put customer needs before budgets, locations or staffing.","C":"Factory location is an operations decision, not the starting point of marketing. A firm in Malta might have a convenient plant but still fail if it has not identified what buyers actually require.","D":"Hiring sales staff happens once the firm knows which customers it serves and what to offer. Recruiting before understanding needs in Valletta would leave representatives without a clear product or message."}}},{"id":"P1_U3_MCQ_1982","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1982","question":"Sunrise Motors in Adelaide, Australia, wants to know why people did not buy its new car model, but it questions only customers who already own one. What is the main problem with this research?","options":{"A":"The sample is biased towards existing buyers","B":"The survey will be too expensive","C":"The questions are qualitative","D":"It uses secondary data"},"correctOption":"A","correctAnswer":"The sample is biased towards existing buyers","questionType":"MCQ","explanation":{"correct_reason":"A sample is biased when it excludes the group whose views matter. By asking only owners in Adelaide why non-owners rejected the car, Sunrise misses the very people it needs to hear from, so the findings will be one-sided.","distractor_reasons":{"A":"A sample is biased when it excludes the group whose views matter. By asking only owners in Adelaide why non-owners rejected the car, Sunrise misses the very people it needs to hear from, so the findings will be one-sided.","B":"Cost is not the central weakness described. Questioning owners in Adelaide may be cheap, but the real issue is that it leaves out non-buyers, whose reasons are the focus of the study.","C":"Whether answers are qualitative is a question of data type, not a flaw in the situation. The problem in Adelaide is the choice of respondents, not the style of the questions asked.","D":"The firm is collecting new opinions from customers, which makes this primary research, not secondary data. The bias comes from who was selected, not from reusing old information."}}},{"id":"P1_U3_MCQ_1983","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1983","question":"A confectionery firm in Harare, Zimbabwe, registers a distinctive name, colour scheme and logo for its new chocolate bar so shoppers can recognise it instantly. Which product decision is this?","options":{"A":"Advertising","B":"Distribution","C":"Pricing","D":"Branding"},"correctOption":"D","correctAnswer":"Branding","questionType":"MCQ","explanation":{"correct_reason":"Branding involves creating a name, symbol, colour or design that identifies a product and distinguishes it from rivals. By registering a name, colour scheme and logo in Harare, the firm is making a branding decision within the product element.","distractor_reasons":{"A":"Advertising communicates a message to buyers. Although the brand may later be advertised, choosing the name and logo itself is a branding activity within the product element.","B":"Distribution concerns how the chocolate bar reaches shops and customers. Registering a name and logo in Harare does not change the channels used, so it is not a distribution decision.","C":"Pricing sets the amount customers pay. No price is mentioned in the Harare scenario; the focus is on creating a recognisable identity for the bar.","D":"Branding involves creating a name, symbol, colour or design that identifies a product and distinguishes it from rivals. By registering a name, colour scheme and logo in Harare, the firm is making a branding decision within the product element."}}},{"id":"P1_U3_MCQ_1984","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1984","question":"A mobile network in Bruges, Belgium, currently holds 9 per cent of the city's subscribers and has set a target of 14 per cent within two years. Which type of objective is this?","options":{"A":"A market share objective","B":"A cost reduction objective","C":"A production efficiency objective","D":"A recruitment objective"},"correctOption":"A","correctAnswer":"A market share objective","questionType":"MCQ","explanation":{"correct_reason":"A market share objective states the proportion of total sales a firm aims to capture. The Bruges network wants to move from 9 to 14 per cent of subscribers, so it has set a clear market share target for the next two years.","distractor_reasons":{"A":"A market share objective states the proportion of total sales a firm aims to capture. The Bruges network wants to move from 9 to 14 per cent of subscribers, so it has set a clear market share target for the next two years.","B":"A cost reduction objective would aim to lower expenses per customer. The Bruges target is about the share of subscribers, not about cutting the cost of running the network.","C":"Production efficiency refers to output per worker or machine. Increasing the proportion of subscribers in Bruges is a marketing goal, not a measure of production efficiency.","D":"A recruitment objective concerns hiring staff. The network's target relates to customers and market share, so it is not about recruiting employees."}}},{"id":"P1_U3_MCQ_1985","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1985","question":"In Salalah, Oman, a furniture buyer says she must have a bed to sleep on, but would like one carved from imported rosewood. Which statement correctly classifies these two requests?","options":{"A":"The bed is a need and the rosewood is a want","B":"The bed is a want and the rosewood is a need","C":"Both statements describe wants","D":"Both statements describe needs"},"correctOption":"A","correctAnswer":"The bed is a need and the rosewood is a want","questionType":"MCQ","explanation":{"correct_reason":"A need is a basic requirement, such as somewhere to sleep, while a want is a particular way of meeting it, such as carved rosewood. The buyer in Salalah needs a bed but wants the specific imported material, so the first part is the need.","distractor_reasons":{"A":"A need is a basic requirement, such as somewhere to sleep, while a want is a particular way of meeting it, such as carved rosewood. The buyer in Salalah needs a bed but wants the specific imported material, so the first part is the need.","B":"This reverses the correct classification. A bed satisfies the fundamental requirement for sleep, whereas rosewood is a specific preference, so the labels should be the other way around.","C":"The request for a bed is not merely a want; it addresses the basic need for rest. Only the rosewood carving is a want in the Salalah example.","D":"Treating both as needs ignores that rosewood is one particular choice among many ways to satisfy the need for a bed. Wants can change while the underlying need remains."}}},{"id":"P1_U3_MCQ_1986","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1986","question":"A research team in Nicosia, Cyprus, is choosing between interviewing 50 shoppers and interviewing 500 about a new product. Which statement about the larger sample of 500 is generally correct?","options":{"A":"It will always be perfectly accurate","B":"It is likely to be more reliable","C":"It removes all research costs","D":"It guarantees no questions are asked"},"correctOption":"B","correctAnswer":"It is likely to be more reliable","questionType":"MCQ","explanation":{"correct_reason":"A larger sample usually reduces the effect of unusual individual answers, so results are more reliable. Interviewing 500 shoppers in Nicosia rather than 50 makes the findings more representative, though it does not make them perfectly accurate.","distractor_reasons":{"A":"No sample is perfectly accurate because some respondents will always differ from the average. Even 500 interviews in Nicosia leave a margin of error, so claiming perfection is wrong.","B":"A larger sample usually reduces the effect of unusual individual answers, so results are more reliable. Interviewing 500 shoppers in Nicosia rather than 50 makes the findings more representative, though it does not make them perfectly accurate.","C":"Larger samples cost more, not less, because more people must be contacted and analysed. The Nicosia team would increase spending by choosing 500 interviews.","D":"A larger sample plainly involves asking more questions, not fewer. This statement is the opposite of what happens when a survey is expanded in Nicosia."}}},{"id":"P1_U3_MCQ_1987","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1987","question":"A bakery in Montevideo, Uruguay, calculates that a loaf costs $1.20 to make and then adds a fixed 25 per cent to cover profit. Which pricing method is this?","options":{"A":"Cost-plus pricing","B":"Price skimming","C":"Penetration pricing","D":"Premium pricing"},"correctOption":"A","correctAnswer":"Cost-plus pricing","questionType":"MCQ","explanation":{"correct_reason":"Cost-plus pricing sets a selling price by adding a chosen percentage margin to the cost of production. The Montevideo bakery starts from a $1.20 cost and adds 25 per cent, so it is using a cost-plus method to set the loaf's price.","distractor_reasons":{"A":"Cost-plus pricing sets a selling price by adding a chosen percentage margin to the cost of production. The Montevideo bakery starts from a $1.20 cost and adds 25 per cent, so it is using a cost-plus method to set the loaf's price.","B":"Price skimming starts with a high price for keen early buyers and lowers it later. The Montevideo bakery is applying a fixed markup to cost, not charging a premium that falls over time.","C":"Penetration pricing sets a low initial price to win customers. Adding a set percentage to costs in Montevideo does not by itself create a deliberately low introductory price.","D":"Premium pricing sets a high price to signal status or quality. The bakery's method is based on cost and a fixed margin, not on creating a luxury image in Uruguay."}}},{"id":"P1_U3_MCQ_1988","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1988","question":"A drinks company in Havana, Cuba, has bought a rival business in order to gain control of a larger share of the market quickly. Which growth strategy is this?","options":{"A":"Acquisition","B":"Internal growth","C":"Franchising","D":"Exporting"},"correctOption":"A","correctAnswer":"Acquisition","questionType":"MCQ","explanation":{"correct_reason":"An acquisition involves one business buying another to expand rapidly. By purchasing a rival in Havana, the drinks company gains the rival's customers and distribution at once, which is growth by acquisition rather than by building slowly from within.","distractor_reasons":{"A":"An acquisition involves one business buying another to expand rapidly. By purchasing a rival in Havana, the drinks company gains the rival's customers and distribution at once, which is growth by acquisition rather than by building slowly from within.","B":"Internal growth means expanding through the firm's own resources, such as launching new products or opening new plants. Buying an existing Havana rival is external growth, not internal development.","C":"Franchising allows independent operators to trade under a firm's name. The Havana company is buying a competitor outright, not granting franchise rights to others.","D":"Exporting means selling goods to customers in other countries. The transaction described takes place in Cuba, so it is not an overseas selling strategy."}}},{"id":"P1_U3_MCQ_1989","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1989","question":"A utility company in Trondheim, Norway, is the only supplier of electricity to homes in the region and faces no close competitors. What market structure does this describe?","options":{"A":"A monopoly","B":"Perfect competition","C":"Monopsony","D":"Oligopoly"},"correctOption":"A","correctAnswer":"A monopoly","questionType":"MCQ","explanation":{"correct_reason":"A monopoly exists when a single seller supplies a market with no close substitutes. The Trondheim utility is the only electricity provider for homes in its region, so households have no alternative supplier and the firm is a monopoly.","distractor_reasons":{"A":"A monopoly exists when a single seller supplies a market with no close substitutes. The Trondheim utility is the only electricity provider for homes in its region, so households have no alternative supplier and the firm is a monopoly.","B":"Perfect competition requires many small firms selling identical products. The Trondheim market has just one supplier, so it is the opposite of a highly competitive market.","C":"A monopsony describes a single buyer facing many sellers. Here there is one seller serving many households, so the correct term is monopoly rather than monopsony.","D":"An oligopoly has a few large sellers. The scenario says there is only one supplier of electricity in the region, so it does not fit an oligopoly structure."}}},{"id":"P1_U3_MCQ_1990","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1990","question":"A cosmetics firm in Graz, Austria, tries a new bottle design in two cities for three months before deciding whether to launch it nationwide. What is this research activity called?","options":{"A":"Secondary analysis","B":"Desk research","C":"A census","D":"Test marketing"},"correctOption":"D","correctAnswer":"Test marketing","questionType":"MCQ","explanation":{"correct_reason":"Test marketing involves trying a product or campaign in a limited area before a wider launch. By using two Austrian cities for three months to assess the new bottle, the cosmetics firm is test marketing the design.","distractor_reasons":{"A":"Secondary analysis reuses data gathered by others. The firm is generating its own results from a controlled trial in Graz, so this is primary test marketing.","B":"Desk research uses existing documents without contacting customers. The Graz firm is placing the bottle in real cities and observing sales, which is field-based test marketing.","C":"A census collects information from every member of a population. Testing in just two cities is a limited exercise, not a survey of all Austrian shoppers.","D":"Test marketing involves trying a product or campaign in a limited area before a wider launch. By using two Austrian cities for three months to assess the new bottle, the cosmetics firm is test marketing the design."}}},{"id":"P1_U3_MCQ_1991","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1991","question":"A soft drinks maker in Plovdiv, Bulgaria, wants its product stocked in as many shops, kiosks and vending machines as possible. Which distribution approach is this?","options":{"A":"Intensive distribution","B":"Exclusive distribution","C":"Direct selling","D":"Selective distribution"},"correctOption":"A","correctAnswer":"Intensive distribution","questionType":"MCQ","explanation":{"correct_reason":"Intensive distribution aims to place a product in as many outlets as possible so customers can buy it easily. By targeting shops, kiosks and vending machines throughout Plovdiv, the soft drinks maker is pursuing intensive distribution.","distractor_reasons":{"A":"Intensive distribution aims to place a product in as many outlets as possible so customers can buy it easily. By targeting shops, kiosks and vending machines throughout Plovdiv, the soft drinks maker is pursuing intensive distribution.","B":"Exclusive distribution restricts sales to one or very few outlets in an area. The Plovdiv firm wants maximum coverage, which is the opposite of an exclusive arrangement.","C":"Direct selling means selling straight to consumers without intermediaries. Supplying shops, kiosks and machines uses intermediaries, so it is not direct selling.","D":"Selective distribution uses a limited number of chosen outlets. The soft drinks maker seeks as many outlets as possible in Plovdiv, so its approach is intensive rather than selective."}}},{"id":"P1_U3_MCQ_1992","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1992","question":"A supermarket chain in Kuching, Malaysia, notes that total grocery sales in the city are growing by 3 per cent a year while its own sales are growing by 7 per cent. What is happening to the chain's market share?","options":{"A":"It is increasing","B":"It is decreasing","C":"It is unchanged","D":"It cannot be determined"},"correctOption":"A","correctAnswer":"It is increasing","questionType":"MCQ","explanation":{"correct_reason":"Market share rises when a firm's sales grow faster than the whole market. With the Kuching market expanding by 3 per cent but the chain growing by 7 per cent, the chain is taking a larger proportion of total grocery sales.","distractor_reasons":{"A":"Market share rises when a firm's sales grow faster than the whole market. With the Kuching market expanding by 3 per cent but the chain growing by 7 per cent, the chain is taking a larger proportion of total grocery sales.","B":"A firm loses share only when its sales grow more slowly than the market. In Kuching the chain grows faster than the 3 per cent market rate, so its share is rising, not falling.","C":"Share would be unchanged if the chain grew at exactly the market rate of 3 per cent. Its 7 per cent growth in Kuching means the proportion is changing upwards.","D":"The information given is sufficient: comparing the chain's growth with the market growth determines the direction of share. Since 7 per cent exceeds 3 per cent, share is increasing."}}},{"id":"P1_U3_MCQ_1993","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1993","question":"A gym in Santa Cruz, Bolivia, finds that members compare the monthly fee with the quality of equipment and classes before joining. What is this comparison an example of?","options":{"A":"Customer value","B":"Market capacity","C":"Production cost","D":"Distribution intensity"},"correctOption":"A","correctAnswer":"Customer value","questionType":"MCQ","explanation":{"correct_reason":"Customer value is the balance between the benefits received and the price paid. By weighing the gym's equipment and classes against the monthly fee, members in Santa Cruz are judging the value the offer provides.","distractor_reasons":{"A":"Customer value is the balance between the benefits received and the price paid. By weighing the gym's equipment and classes against the monthly fee, members in Santa Cruz are judging the value the offer provides.","B":"Market capacity is the total volume a market could absorb. Individual members comparing fees with facilities are assessing value, not measuring the size of the Bolivian market.","C":"Production cost is what the gym spends on providing services. The comparison described is made by customers between benefits and price, not by the firm calculating its costs.","D":"Distribution intensity concerns how widely a product is available. Nothing in the Santa Cruz scenario relates to where the gym is located or how many outlets it has."}}},{"id":"P1_U3_MCQ_1994","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1994","question":"A survey in Surabaya, Indonesia, includes the question: 'Surely you agree our new snack is delicious, don't you?' What is the main problem with this question?","options":{"A":"It is leading and biases respondents","B":"It is too short","C":"It asks about price","D":"It uses a sample"},"correctOption":"A","correctAnswer":"It is leading and biases respondents","questionType":"MCQ","explanation":{"correct_reason":"A leading question suggests the answer the researcher wants, pressuring respondents to agree. The Surabaya wording 'Surely you agree' pushes people toward a positive reply, so the answers would be biased and unreliable.","distractor_reasons":{"A":"A leading question suggests the answer the researcher wants, pressuring respondents to agree. The Surabaya wording 'Surely you agree' pushes people toward a positive reply, so the answers would be biased and unreliable.","B":"Length is not the difficulty here. The Surabaya question is brief but problematic because its wording nudges respondents toward a particular answer rather than length.","C":"The question concerns taste, not price. Even if it were about price, the flaw would remain that it leads respondents to a preferred response.","D":"Using a sample is normal survey practice and not a problem in itself. The weakness in Surabaya is the biased wording of the question, not the fact that a group of people is surveyed."}}},{"id":"P1_U3_MCQ_1995","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1995","question":"A cereal company in Kirkuk, Iraq, prints money-off vouchers on its boxes to encourage repeat purchases in the short term. Which element of the marketing mix does this mainly belong to?","options":{"A":"Product","B":"Price","C":"Promotion","D":"Place"},"correctOption":"C","correctAnswer":"Promotion","questionType":"MCQ","explanation":{"correct_reason":"Sales promotion uses short-term incentives such as coupons and vouchers to stimulate purchases. By printing money-off vouchers on cereal boxes in Kirkuk, the company is running a promotion to encourage customers to buy again.","distractor_reasons":{"A":"Product concerns the cereal's recipe and packaging. Although the voucher appears on the box, it is an incentive message rather than a change to the cereal itself.","B":"Price is about the amount charged. The vouchers reduce what buyers pay, but a money-off coupon is classified as a sales promotion technique within the promotion element.","C":"Sales promotion uses short-term incentives such as coupons and vouchers to stimulate purchases. By printing money-off vouchers on cereal boxes in Kirkuk, the company is running a promotion to encourage customers to buy again.","D":"Place concerns how the cereal reaches customers. Printing vouchers in Kirkuk does not change distribution channels, so it is not a place decision."}}},{"id":"P1_U3_MCQ_1996","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_1996","question":"A cleaning products firm in Maputo, Mozambique, offers a unique eco-friendly formula that rivals cannot match, and builds its whole strategy around this difference. Which competitive strategy is it following?","options":{"A":"Differentiation","B":"Cost leadership","C":"Mass marketing","D":"Concentrated targeting"},"correctOption":"A","correctAnswer":"Differentiation","questionType":"MCQ","explanation":{"correct_reason":"Differentiation means competing on distinctive features that customers value and rivals lack. By building its Maputo strategy around a unique eco-friendly formula, the firm is differentiating its products from competitors.","distractor_reasons":{"A":"Differentiation means competing on distinctive features that customers value and rivals lack. By building its Maputo strategy around a unique eco-friendly formula, the firm is differentiating its products from competitors.","B":"Cost leadership means being the lowest-cost producer in the market. The Maputo firm is emphasising a unique formula rather than low prices or low costs, so cost leadership does not apply.","C":"Mass marketing aims one offer at the whole market. The key feature here is the unique formula that sets the firm apart, which is differentiation rather than an undifferentiated appeal.","D":"Concentrated targeting focuses on one narrow customer segment. The scenario describes competing through a distinctive product, not selecting a specific group of buyers in Maputo."}}},{"id":"P1_U3_MCQ_1997","section":"3","unit":"Unit 3: Marketing","chapter":"3.1 Marketing, competition and the customer","questionNumber":"P1_U3_MCQ_1997","question":"A mobile phone shop in Alexandria, Egypt, focuses on keeping its current customers satisfied through quick repairs and loyalty points, believing this is cheaper than constantly finding new buyers. What is this approach called?","options":{"A":"Customer retention","B":"Market development","C":"Mass marketing","D":"Price skimming"},"correctOption":"A","correctAnswer":"Customer retention","questionType":"MCQ","explanation":{"correct_reason":"Customer retention means keeping existing buyers through service and rewards. The Alexandria shop uses quick repairs and loyalty points to hold on to its customers because retaining them costs less than attracting new ones.","distractor_reasons":{"A":"Customer retention means keeping existing buyers through service and rewards. The Alexandria shop uses quick repairs and loyalty points to hold on to its customers because retaining them costs less than attracting new ones.","B":"Market development involves taking existing products to new markets. The shop in Alexandria is working with customers it already has, not seeking new markets.","C":"Mass marketing targets all buyers with one broad offer. The shop's attention to current customers and loyalty points is a retention focus, not an undifferentiated mass appeal.","D":"Price skimming sets a high price that falls later. Nothing in the Alexandria scenario mentions prices; the effort is on service and rewards to keep buyers."}}},{"id":"P1_U3_MCQ_1998","section":"3","unit":"Unit 3: Marketing","chapter":"3.2 Market research","questionNumber":"P1_U3_MCQ_1998","question":"A travel agency in Coventry, United Kingdom, monitors customers' posts and reviews on social media to understand what they think of its holidays. What kind of research is this?","options":{"A":"Online social media monitoring","B":"A census","C":"An experiment","D":"Secondary desk research only"},"correctOption":"A","correctAnswer":"Online social media monitoring","questionType":"MCQ","explanation":{"correct_reason":"Social media monitoring collects customers' comments and reviews from online platforms to gauge opinions. By reading posts about its holidays in Coventry, the agency is conducting online research into what buyers think.","distractor_reasons":{"A":"Social media monitoring collects customers' comments and reviews from online platforms to gauge opinions. By reading posts about its holidays in Coventry, the agency is conducting online research into what buyers think.","B":"A census would require information from every customer. Reading social media posts in Coventry captures only those who choose to comment, so it is not a complete census.","C":"An experiment changes a factor to measure its effect. The agency is passively observing online comments, not manipulating prices or products to test a hypothesis.","D":"While the posts already exist online, calling this only secondary desk research misses the active monitoring of customer opinions. The defining feature here is online social media monitoring."}}},{"id":"P1_U3_MCQ_1999","section":"3","unit":"Unit 3: Marketing","chapter":"3.3 Marketing mix","questionNumber":"P1_U3_MCQ_1999","question":"A dairy in Hamilton, New Zealand, already sells plain yoghurt and is adding a strawberry flavour to the same product line. Which product decision is this?","options":{"A":"Promotion campaign","B":"Price reduction","C":"Place expansion","D":"Product line extension"},"correctOption":"D","correctAnswer":"Product line extension","questionType":"MCQ","explanation":{"correct_reason":"A product line extension adds a new variety to an existing range of related products. By offering strawberry yoghurt alongside plain in Hamilton, the dairy is extending its product line rather than changing price or distribution.","distractor_reasons":{"A":"A promotion campaign communicates with customers. Although the new flavour may be advertised, the decision described is adding a product, which is a line extension.","B":"A price reduction lowers the amount charged. The Hamilton dairy is adding a flavour, not cutting the price of its existing yoghurt.","C":"Place expansion would mean selling through more outlets. The new strawberry variety is a change to the product range in Hamilton, not to where yoghurt is sold.","D":"A product line extension adds a new variety to an existing range of related products. By offering strawberry yoghurt alongside plain in Hamilton, the dairy is extending its product line rather than changing price or distribution."}}},{"id":"P1_U3_MCQ_2000","section":"3","unit":"Unit 3: Marketing","chapter":"3.4 Marketing strategy","questionNumber":"P1_U3_MCQ_2000","question":"A textile firm in Fes, Morocco, sets marketing objectives each year, selects the strategies to reach them and then measures results against those goals. What is this whole process called?","options":{"A":"Marketing planning","B":"Market research","C":"Sales promotion","D":"Product differentiation"},"correctOption":"A","correctAnswer":"Marketing planning","questionType":"MCQ","explanation":{"correct_reason":"Marketing planning is the process of setting objectives, choosing strategies to achieve them and controlling the results. The Fes firm's annual cycle of goals, chosen methods and measurement matches this planning process.","distractor_reasons":{"A":"Marketing planning is the process of setting objectives, choosing strategies to achieve them and controlling the results. The Fes firm's annual cycle of goals, chosen methods and measurement matches this planning process.","B":"Market research gathers information about customers and competitors. While research may inform the plan, the Fes firm's activity of setting goals and checking outcomes is marketing planning.","C":"Sales promotion uses short-term incentives to boost sales. The Moroccan firm is describing a management process, not a coupon or discount campaign.","D":"Product differentiation makes an offer distinct from rivals'. The scenario is about planning and control in Fes, not about changing the textile product itself."}}}];
